INSERT OR REPLACE INTO collections (id, title_ru, title_en, title_me, slug, description_ru, description_en, description_me, created_at) VALUES ('important_topics', 'На важные темы', 'Important Topics & Human Rights', 'O važnim temama i pravima', 'important-topics', 'Истории о смелости, свободе, правах человека и преодолении трудностей', 'Stories about courage, freedom, human rights, and overcoming adversity', 'Priče o hrabrosti, slobodi, ljudskim pravima i prevazilaženju teškoća', 1792836322693);
