INSERT OR REPLACE INTO collections (id, title_ru, title_en, title_me, slug, description_ru, description_en, description_me, created_at) VALUES ('winter_and_new_year', 'Зимние и новогодние истории', 'Winter & Holiday Tales', 'Zimske i novogodišnje priče', 'winter-tales', 'Снежные приключения, ёлка, уют и новогодние чудеса', 'Snowy adventures, Christmas trees, warmth, and holiday miracles', 'Snježne avanture, jelka, udobnost i praznična čuda', 1792836322693);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('якоб-говорит-нет--1', 'DP-0001', 'Якоб говорит "нет"', 'Jacob Says "No!"', 'Jakob kaže "ne!"', 'Сандра Гримм', 'Sandra Grimm', 'Sandra Grim', '', 'Альпина.Дети', 2024, '978-5-9614-9702-1', 0, 6, 'little', 'Петер Фридл', 'Little Jacob has discovered his new favorite word: "No!" A gentle, comforting, and relatable story about toddler independence, daily routines, and learning healthy boundaries.', 'Mali Jakob je otkrio svoju novu omiljenu riječ: „Ne!” Nježna, utješna i prepoznatljiva priča o dječijoj samostalnosti, svakodnevnim navikama i postavljanju granica.', 'Настоящее спасение для родителей малышей, чей главный и самый громкий ответ на всё на свете сейчас — решительное «нет!».', 'A true lifesaver for parents of toddlers whose favorite and loudest response to everything right now is an emphatic "no!".', 'Pravi spas za roditelje mališana čiji je najglasniji odgovor na apsolutno sve trenutno jedno odlučno „ne!”.', '/covers/DP-0001.webp', '#e76f51', '0+', 'ru', 'available', '', '["real","funny"]', '["toddlers","growing up","family","emotions","boundaries"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('клуб-друзей-2', 'DP-0002', 'Клуб друзей', 'The Friends Club', 'Klub prijatelja', 'Софи Геррив', 'Sophie Guerrive', 'Sofi Geriv', '', 'Самокат', NULL, NULL, 0, 6, 'little', 'Комикс для самых маленьких! Удивительно, но да, его можно и нужно читать со своим взрослым уже начиная лет с трёх. Это аккуратный, полный нежности и юмора рассказ о том, как важно с молодых лет искать и находить друзей, вылезая из-под родительского крыла. Змея Крокус со страхом покидает родное болото и отправляется искать друзей. Почти сразу он знакомится с задумчивым медведем Тюльпаном, а затем у них появляется третий друг – птичка Фиалка. Вместе они справляются со страхами, учатся дружить и взрослеть. Клуб друзей выиграл главный комиксовый приз в Ангулеме в 2021 году.', 'A charming first comic book for little readers and their grown-ups! Gentle, witty, and deeply touching, it tells the story of venturing out of one''s comfort zone to find friendship. Crocus the snake bravely leaves his familiar swamp and soon befriends Tulip the thoughtful bear, followed by Violet the bird. Together, the trio navigate childhood fears, learn empathy, and grow up side by side. Winner of the prestigious Youth Prize at the Angoulême International Comics Festival in 2021.', 'Prvi strip za najmlađe koji se čita zajedno sa roditeljima već od treće godine! Nježna i duhovita priča o hrabrosti da se napusti rodno gnijezdo i pronađu pravi prijatelji. Zmijica Krokus plašljivo napušta svoju močvaru i kreće u potragu za društvom, gdje ubrzo upoznaje zamišljenog medvjeda Ljiljana i ptičicu Ljubičicu. Zajedno prevazilaze strahove, uče šta znači pravo prijateljstvo i odrastaju. Knjiga je osvojila prestižnu nagradu za strip u Angulemu 2021. godine.', 'Нежный и уморительный комикс о том, что шагнуть в большой мир совсем не страшно, если рядом есть задумчивый медведь и верная птичка.', 'A tender, whimsical comic proving that stepping into the big world isn''t scary at all when you have a thoughtful bear and a loyal little bird by your side.', 'Nježan i duhovit strip koji dokazuje da izlazak u veliki svijet uopšte nije strašan kada uz sebe imate zamišljenog medvjeda i vjernu ptičicu.', '/covers/DP-0002.webp', '#6d9a5b', '0+', 'ru', 'available', '', '["friends","animals","funny"]', '["graphic novel","friendship","animals","toddlers","award winner"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('фредрик-3', 'DP-0003', 'Фредрик', 'Frederick', 'Frederik', 'Лео Лионни', 'Leo Lionni', 'Leo Lionni', '', 'Самокат', NULL, NULL, 0, 6, 'little', 'Мыши готовятся к зиме, тащат в норку съестные припасы. Только Фредерик сидит без дела, но отговаривается тем, что копит солнечный свет, краски природы и важные слова. И вот еда кончается, и оказывается, что запасы Фредерика могут согреть даже в зимнюю стужу. Лео Лионни, всемирно известный дизайнер, график и книжный иллюстратор, родился в Голландии, учился в Италии, а в 1939 году переехал в США. Художник умер в 1999 году в возрасте 89 лет, оставив маленьким читателям множество книжек-картинок. Четыре книжки Лионни были удостоены престижной премии Калдекотта.', 'While the other field mice work hard gathering nuts and wheat for the approaching winter, Frederick seems to daydream, collecting sunbeams, vibrant colors, and words instead. But when snow blankets the meadow and the food supplies dwindle, Frederick''s poetic warmth proves to be the most vital treasure of all. A beloved Caldecott Honor-winning fable about the irreplaceable gift of art, poetry, and imagination.', 'Dok drugi poljski miševi neumorno rade i skupljaju hranu za zimu, Frederik samo sanjari, govoreći da prikuplja sunčeve zrake, boje prirode i tople riječi. Kada padne snijeg i zalihe se istroše, Frederikovi poetski darovi ugrijaće srce svakog mišića. Prelijepa, bezvremenska basna o snazi mašte, umjetnosti i zajedništva.', 'Поэтичная и невероятно уютная притча, которая напоминает: сказки, краски и добрые слова греют зимой ничуть не хуже сытных запасов.', 'A poetic and deeply comforting classic proving that warm words, sunshine, and colors are just as essential for winter survival as berries and nuts.', 'Topla i poetična priča koja nas podsjeća da su lijepa riječ, mašta i sunčevi zraci podjednako važni za zimu kao i puni ambari.', '/covers/DP-0003.webp', '#9a8b79', '0+', 'ru', 'available', '', '["animals","friends"]', '["mice","winter","poetry","art","classic"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('из-гнезда-4', 'DP-0004', 'Из гнезда', 'Out of the Nest', 'Iz gnijezda', '', 'Unknown', 'Nepoznati autor', '', 'Самокат', NULL, NULL, 0, 6, 'little', 'Для взрослого дрозда это был бы самый обычный день, но Кира — слёток. Она только что выпала из гнезда и сегодня её ждёт первое большое приключение! Наблюдая за историей Киры, её новыми знакомствами и открытиями, мы узнаём, как устроен этот удивительный мир — мир леса. Здесь каждый кому-то обед, но дружба выгоднее вражды. Домом может стать любое укромное место, но иногда даже дом — опасность. И есть настоящее спа! Изучай лес вместе с Кирой, ищи редких животных и растения, читай интересные факты из жизни леса, и тогда — вслед за героями книги — ты можешь сказать: «Теперь это и мой лес тоже!»', 'For an adult thrush, this would be an ordinary day, but Kira is just a fledgling. She has just tumbled out of her nest, embarking on her very first big adventure! Following Kira''s new encounters and discoveries, young readers learn how the forest ecosystem works: where friendship is often safer than conflict, cozy hideaways can conceal danger, and nature has its own wonders. Explore the woods with Kira, spot rare plants and animals, and make the forest feel like home!', 'Za odraslog kosa ovo bi bio sasvim običan dan, ali Kira je još poletarac. Upravo je ispala iz gnijezda i pred njom je prva velika šumska avantura! Prateći Kirina nova poznanstva i otkrića, mališani uče kako funkcioniše čarobni svijet šume — gdje je prijateljstvo dragocjeno, a svako skrovište krije nova saznanja. Istražite šumu zajedno s Kirom, pronađite skrivene životinje i biljke i osjetite prirodu kao svoj pravi dom!', 'Трогательное и познавательное путешествие крохотного птенца, которое научит бережно любить и понимать живой лес!', 'A heartwarming and curious journey of a tiny fledgling that will inspire your little explorer to fall in love with the forest!', 'Dirljivo i poučno putovanje malenog ptića koje će podstaći svakog malog istraživača da zavoli šumski svijet!', '/covers/DP-0004.webp', '#4a7c59', '0+', 'ru', 'available', '', '["adventure","animals","real"]', '["birds","forest","nature","ecosystem","fledgling"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('из-ниотуда-5', 'DP-0005', 'Из ниотуда', 'Out of Nowhere', 'Niotkuda', '', 'Chris Naylor-Ballesteros', 'Kris Nejlor-Balesteros', '', 'Поляндрия', NULL, NULL, 0, 6, 'little', 'Настоящая дружба найдёт тебя, где бы ты ни был Каждый день две подруги устраивают пикник на высоком утёсе и каждый вечер вместе смотрят, как восходит луна. Но что произойдёт, если одна из подруг исчезнет? Что, если она не вернётся? Или вернётся, но совершенно другой? История о том, как настоящая дружба может возникнуть из ниоткуда, удивит и тронет каждого читателя.', 'True friendship will find you wherever you are. Every day, two best friends have a picnic on a high cliff and watch the moon rise together every evening. But what happens if one friend vanishes into thin air? What if she doesn''t come back—or returns completely transformed? A moving story about trust, change, and bonds that withstand any metamorphosis.', 'Pravo prijateljstvo naći će te ma gdje bio. Svakog dana dvije nerazdvojne prijateljice prave piknik na visokoj litici i svake večeri zajedno posmatraju izlazak mjeseca. Ali šta se dešava ako jedna od njih iznenada nestane? Šta ako se ne vrati—ili se vrati sasvim promijenjena? Dirljiva priča o povjerenju, promjenama i prijateljstvu koje nastaje niotkuda.', 'Трогательная до слез притча о переменах и дружбе, которая выдержит даже превращение гусеницы в бабочку.', 'A deeply touching tale about growing up, changes, and a friendship strong enough to withstand even a butterfly''s metamorphosis.', 'Dirljiva i nježna priča o odrastanju i prijateljstvu koje ostaje neraskidivo čak i kada se neko sasvim promijeni.', '/covers/DP-0005.webp', '#5b8296', '0+', 'ru', 'available', '', '["friends","animals"]', '["дружба","насекомые","перемены","природа","метаморфоза"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('где-живет-птичка-6', 'DP-0006', 'Где живет птичка', 'Where Does the Little Bird Live?', 'Gdje živi ptičica?', 'Елена Цветавева', 'Elena Tsvetaeva', 'Jelena Cvetajeva', '', 'Клевер', NULL, NULL, 0, 6, 'little', 'Где живёт маленькая птичка? Загляните под каждый листочек-клапан и найдите ответ! Эта книга с плотными страницами из картона поможет вашему малышу развивать мелкую моторику и фантазию, а яркие иллюстрации молодой художницы Елены Цветаевой сделают чтение увлекательным и запоминающимся.', 'Where does the little bird live? Peek under every lift-the-flap leaf to find out! Made with sturdy cardboard pages, this interactive board book helps toddlers develop fine motor skills and imagination, while vibrant illustrations by Elena Tsvetaeva turn reading into a delightful hide-and-seek adventure.', 'Gdje živi mala ptičica? Zavirite ispod svakog prozorčića i pronađite odgovor! Ova knjiga sa čvrstim kartonskim stranicama pomaže mališanima da razviju finu motoriku i maštu, dok živopisne ilustracije Jelene Cvetajeve čitanje pretvaraju u uzbudljivu igru skrivalica.', 'Идеальная книжка-прятка для самых маленьких пальчиков, которые обожают заглядывать под каждый листочек!', 'The perfect peek-a-boo board book for curious little fingers that just have to lift every single flap!', 'Savršena knjiga-skrivalica za radoznale prstiće koji jednostavno moraju da zavire iza svakog prozorčića!', '/covers/DP-0006.webp', '#489f66', '0+', 'ru', 'available', '', '["animals","adventure"]', '["birds","flap book","toddlers","interactive","nature"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('асфальт-7', 'DP-0007', 'Асфальт', 'Asphalt', 'Asfalt', 'Салла Саволайнен', 'Salla Savolainen', 'Salla Savolainen', '', 'Белая ворона', NULL, NULL, 0, 6, 'little', 'Ранним утром Койстинен и его пес Рики отправляются на работу. Сегодня они будут ремонтировать автомобильную дорогу. Дорожные работы в самом разгаре: бригаде предстоит снять старый асфальт, приготовить новый и правильно его уложить. И, конечно же, не забывать про технику безопасности! В компании Койстинена, Рики и целой бригады специалистов по ремонту дорог ты узнаешь все-все об этом сложном процессе. Как устроены асфальтобетонный завод и дорожная фреза? Можно ли отмыть битум с лопаты? И, в конце концов, куда все время пропадает Рики?', 'Early in the morning, Koistinen and his faithful dog Riki head to work on a big road repair project. The crew has a lot to do: scrape away the old asphalt, mix a fresh batch, and lay it down smoothly—all while following strict safety rules! Alongside Koistinen and his hardworking team, young readers will explore how an asphalt plant and a cold planer work, find out how to clean bitumen off a shovel, and solve the mystery of where Riki keeps sneaking off to.', 'Rano ujutru, Koistinen i njegov pas Riki kreću na posao – danas popravljaju put! Radovi su u punom jeku: ekipa mora da ukloni stari asfalt, pripremi novu smjesu i pažljivo je položi, pazeći na sve mjere bezbjednosti. Uz Koistinena, Rikija i tim putara saznaćete sve o radu asfaltne baze i velikih glodalica, ali i otkriti gdje to Riki stalno nestaje!', 'Абсолютный хит для всех маленьких фанатов катков, самосвалов и настоящей дорожной стройки!', 'The ultimate treat for every little fan of steamrollers, dump trucks, and heavy-duty machinery!', 'Pravi hit za sve male obožavaoce valjaka, kamiona i velikih građevinskih mašina!', '/covers/DP-0007.webp', '#e87a1e', '0+', 'ru', 'available', '', '["real","friends"]', '["construction","machinery","dogs","professions","vehicles"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мышонок-и-крот-наш-кусочек-неб-8', 'DP-0008', 'Мышонок и Крот. Наш кусочек неба', 'Mouse and Mole: Our Piece of Sky', 'Mišić i Krtica: Naše parče neba', 'Анри Мёнье, Бенжамен Шо', 'Henri Meunier, Benjamin Chaud', 'Henri Meunier, Benjamin Chaud', '', 'МИФ', NULL, NULL, 0, 6, 'little', 'Крот и Мышонок дружат, несмотря на все различия. Они помогают друг другу и каждый день проводят вместе — гуляют, делают фотографии, устраивают генеральную уборку и придумывают множество других увлекательных занятий. У Крота плохое зрение, зато столько воображения и умения фантазировать, что хватит на двоих! Он постоянно попадает в забавные ситуации, а Мышонок с удовольствием поддерживает Крота и подыгрывает ему, проявляя чудеса изобретательности, чтобы ничем не обидеть лучшего друга.', 'Mole and Mouse are inseparable companions despite their differences. Mole has terribly poor eyesight, but an imagination vast enough for two! Whenever Mole stumbles into amusing mix-ups, Mouse thoughtfully plays along with endless tact and creativity. Together, they go on walks, take photos, tidy up, and celebrate everyday wonders under their shared patch of sky.', 'Krtica i Mišić su najbolji prijatelji uprkos svim razlikama. Krtica slabo vidi, ali ima maštu dovoljnu za obojicu! Kada Krtica upadne u neobične i smiješne situacije, Mišić mu s puno takta i nježnosti priskače u pomoć kako ga ne bi povrijedio. Zajedno šetaju, fotografišu, spremaju i uživaju u toplim svakodnevnim avanturama.', 'Трогательные и невероятно смешные истории о дружбе, где плохое зрение с лихвой окупается безграничной фантазией и чуткостью верного друга.', 'A tender and hilarious celebration of friendship where poor eyesight is delightfully outmatched by wild imagination and a caring buddy.', 'Dirljive i vesele priče o pravom prijateljstvu u kojem se slab vid lako nadoknađuje bujnom maštom i bezgraničnom pažnjom.', '/covers/DP-0008.webp', '#6ea3c1', '0+', 'ru', 'available', 'новое в библиотеке | 4-8 лет', '["funny","friends","animals"]', '["friendship","kindness","humor","animals","empathy"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('очень-голодная-гусеница-9', 'DP-0009', 'Очень голодная гусеница', 'The Very Hungry Caterpillar', 'Veoma gladna gusjenica', 'Эрик Карл', 'Eric Carle', 'Erik Karl', '', 'Розовый жираф', NULL, NULL, 0, 6, 'little', 'У Эрика Карла, знаменитого американского детского художника и писателя, много прекрасных книг, но самая известная из всех — «Очень голодная гусеница». В этой удивительной книжке около 20 страниц и не больше 200 слов. 200 слов, которые родители читают вслух своим малышам на двадцати четырех языках уже в течение сорока лет. По данным британской благотворительной организации «Буктраст» «Очень голодная гусеница» заняла второе место в списке «Самых лучших книг для детей», уверенно обойдя даже «Гарри Поттера». В чем секрет успеха этой книги? В ярких, но очень простых иллюстрациях автора, которые может понять любой двухлетний ребенок? В чудесном превращении гусеницы в прекрасную бабочку? В волшебной игре ребенка в дни недели? Мы не знаем ответа. Мы только знаем, что наши дети с двух лет и иногда по сей день с удовольствием окунаются в волшебный мир, созданный для них Эриком Карлом. Мы очень надеемся, что и ваши дети полюбят эту книгу.', 'Eric Carle’s worldwide bestseller tells the story of a tiny, famished caterpillar who eats his way through apples, plums, chocolate cake, and pickles over the course of a week before pupating and emerging as a splendid butterfly. With vibrant collage artwork and clever die-cut holes for tiny fingers, this timeless classic gently teaches days of the week, counting, and the wonders of nature.', 'Svjetski bestseler Erika Karla priča priču o sićušnoj, vječno gladnoj gusjenici koja se tokom sedmice gosti jabukama, šljivama, čokoladnom tortom i krastavčićima, sve dok se ne učaura i pretvori u prelijepog leptira. Uz živopisne kolaže i prepoznatljive rupice za radoznale prstiće, ova vanvremenska slikovnica nježno uči djecu danima u sedmici, brojanju i čudima prirode.', 'Идеальная первая книжка: учим дни недели, считаем вкусности, суем пальчики в дырочки и замираем от восторга при виде красавицы-бабочки!', 'The ultimate toddler classic: poke curious fingers through the holes, count yummy treats, and watch a tiny tummy ache turn into a glorious butterfly!', 'Savršena prva slikovnica: guramo prstiće kroz rupice, brojimo poslastice i sa oduševljenjem čekamo rođenje prelijepog leptira!', '/covers/DP-0009.webp', '#5e9c3f', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["animals","magic"]', '["caterpillar","counting","days of the week","nature","interactive"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('морской-конек-10', 'DP-0010', 'Морской конек', 'Mister Seahorse', 'Morski konjić', 'Эрик Карл', 'Eric Carle', 'Erik Karl', '', 'Розовый жираф', NULL, NULL, 0, 6, 'little', 'Издательство “Розовый жираф” переиздало бестселлер Эрика Карла “Морской конек”. На этот раз – в картонном варианте! А знаете ли вы, как появляются на свет маленькие рыбки? Мама-рыбка откладывает икринки, папа-рыбка их оплодотворяет – и всё, больше о будущих малышах никто не заботится. Так обстоит дело у большинства рыб. Но есть и удивительные исключения: морской конёк, тиляпия, куртус, флейторыл, сомик-кошка и некоторые другие. Эти рыбы заботятся о своих икринках и бережно вынашивают их, причем делают это — вы не поверите! — не мамы, а папы! Про таких пап писатель Эрик Карл и написал свою сказку. Её главный герой — морской конёк плывёт по морю, бережно неся в сумке на брюшке икру, которую отложила туда его супруга. По дороге он встречает друзей и соседей — других рыб-пап. Они приветствуют друг друга, делятся впечатлениями и опытом: ведь каждый выводит своих мальков по-своему. Конечно, кроме друзей и соседей, в море водятся и другие — страшные, хищные рыбы… Но не бойтесь! Всё кончается хорошо, как и должно быть в сказке. И всё-таки, это не просто сказка. Ваш малыш узнает из неё много интересного о подводных жителях: новые названия рыб, как выводят мальков разные рыбки, как они прячутся от хищников. Поэтому именно этой книжкой мы открываем серию научно-популярных сказок для самых маленьких. Иллюстрации к «Морскому коньку» нарисовал сам автор. Здесь, как и в других своих книжках, Эрик Карл использовал уникальную технику коллажа: вырезал фигурки, волны и водоросли из папиросной бумаги, а затем раскрасил их. Поэтому они получились такими воздушными и лёгкими — как лазурное море, в котором живут наши герои. Эта книга Эрика Карла заняла 6-е место в рейтинге лучших детских книг 2009 года, который составили читатели Центральной Городской Детской Библиотеки им. А.П. Гайдара', 'Eric Carle dives deep into the ocean to celebrate the most devoted underwater fathers! When Mrs. Seahorse lays her eggs into Mr. Seahorse''s belly pouch, he embarks on a gentle voyage across the sea, greeting fellow fish dads who nurture and protect their little ones in wonderful, surprising ways. Illustrated with Carle''s iconic vibrant tissue-paper collage, this heartwarming board book weaves fascinating marine biology with tender paternal love.', 'Erik Karl vodi najmlađe čitaoce na divno morsko putovanje posvećeno najbrižnijim očevima okeana! Kada gospođa Konjić povjeri svoja jajašca gospodinu Konjiću, on ponosno pliva morskim dubinama i susreće druge tate-ribe koje na čudesne načine čuvaju svoje mladunce. Oslikana prepoznatljivim šarenim kolažima, ova topla kartonka spaja prva naučna saznanja o prirodi sa nježnom pričom o očinskoj ljubavi.', 'Трогательная ода заботливым папам и подводным чудесам, написанная и наклеенная из ярких кусочков бумаги великим Эриком Карлом.', 'A tender, sunlit salute to the ocean''s most dedicated stay-at-home dads, told with Eric Carle''s signature collage magic.', 'Nježna i šarena priča o najbrižnijim podvodnim tatama, ispričana kroz prepoznatljivu magiju kolaža Erika Karla.', '/covers/DP-0010.webp', '#2ea5a8', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["animals","real","friends"]', '["ocean","fathers","sea creatures","eric carle","nature"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('10-резиновых-утят-11', 'DP-0011', '10 резиновых утят', '10 Little Rubber Ducks', '10 gumenih patkica', 'Эрик Карл', 'Eric Carle', 'Erik Karl', '', 'Розовый жираф', NULL, NULL, 0, 6, 'little', 'В 1992 году из Китая в Америку плыл грузовой корабль. Где-то в Тихом океане на него налетел шторм, и огромной волной за борт смыло контейнер с двадцатью девятью тысячами резиновых игрушек. Желтые утята, красные бобры, зеленые лягушки и синие черепахи отправились в самостоятельное плавание по Мировому океану. Какая только судьба не ожидала резиновых утят! Они присоединялись к тоннам океанского мусора, застревали во льдах Арктики, доплывали до Аляски, Южной Америки и Японии, а некоторые из них достигли берегов Европы. За шесть лет путешествия (а некоторые игрушки плавали больше 15 лет!) утята и бобры выцвели под солнцем, но люди в разных точках планеты их все равно узнавали, бережно собирали и сообщали о находках в местные газеты. Знаменитый океанограф Кертис Эббесмейер использовал случай с резиновыми утятами, чтобы исследовать океанические течения и построить описывающую их научную модель. А знаменитый автор детских книг Эрик Карл создал книжку “Десять резиновых утят”, рассказывающую о приключениях игрушек. В этой книжке есть все, что может поразить воображение 3-х летнего ребенка: интересная история, потрясающе яркие, выполненные в стиле коллажа иллюстрации, много новой информации. Слушая и рассматривая “Десять резиновых утят”, малыш узнает, как игрушки появляются на свет и как попадают в магазины; познакомится с морскими животными и научится считать до 10; а еще он сможет развить базовые навыки ориентации в пространстве — во время чтения можно обсудить понятия “прямо”, “наискосок”, “вправо”, “влево”, назвать стороны света. И еще одна важная тема для разговора с читателями — это семья, то место, где мы чувствуем себя защищенными и окруженными заботой, словом, в полной безопасности.', 'Inspired by the true story of a cargo ship accident in 1992 that set 29,000 bath toys adrift across the globe, this vibrant picture book by Eric Carle follows ten little yellow rubber ducks on their ocean odyssey. Swept in different directions, each duck encounters a different sea creature—from dolphins and seals to polar bears and octopuses—while introducing young readers to ordinal counting, cardinal directions, and spatial awareness. Full of Eric Carle''s signature painted paper collages, this heartwarming journey culminates in a sweet lesson about family and belonging.', 'Inspirisana istinitom pričom iz 1992. godine kada je teretni brod izgubio 29.000 gumenih igračaka u Tihom okeanu, ova živopisna slikovnica Erika Karla prati deset žutih patkica na njihovoj velikoj morskoj avanturi. Nošena talasima na sve strane svijeta, svaka patkica susreće drugačiju morsku životinju — od delfina i foka do polarnih medvjeda i hobotnica — dok mališani kroz igru uče brojanje do deset, strane svijeta i prostornu orijentaciju. Uz prepoznatljive Karl-ove kolaže jarkih boja, ova topla priča donosi predivnu poruku o pronalasku doma i porodice.', 'Удивительная одиссея резиновых утят, которая не только научит малыша считать до десяти и различать стороны света, но и докажет: даже посреди бескрайнего океана можно найти свой тёплый дом!', 'A delightful ocean odyssey that turns a real-life sea mishap into a sunny counting adventure full of marine friends and cozy endings.', 'Nevjerovatna okeanska avantura koja će mališane naučiti brojanju i stranama svijeta, ali i ugrijati im srce pričom o pronalasku pravog doma!', '/covers/DP-0011.webp', '#2a7f9e', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["adventure","animals","real"]', '["counting","ocean","eric carle","animals","real story"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('спокойной-ночи-карлхен--12', 'DP-0012', 'Спокойной ночи, Карлхен!', 'Good Night, Karlchen!', 'Laku noć, Karlhen!', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', '', 'Мелик-Пашаев', NULL, NULL, 0, 6, 'little', 'Каждый вечер одно и то же: Карлхен не хочет ложиться спать. Поэтому папа отправляется с ним в Большое путешествие на скоростном тапочковом поезде. Первая остановка – Морковьбург, потом их ждет город Мойбург. Наконец, после многих приключений они приезжают на конечную станцию Спибург в детской комнате. Спокойной ночи, Карлхен! Детские книги немецкой художницы Ротраут Сюзанне Бернер стали бестселлерами в нашей стране. Ее иллюстрации отличаются яркостью красок, точностью и вниманием к мельчайшим деталям. Именно такой должна быть любимая книжка, которую можно рассматривать, читать, класть под подушку, брать с собой в поездку и потом, будучи взрослым, вспоминать как любимую книжку детства.', 'Every evening brings the same struggle: little Karlchen doesn''t want to go to bed. So Papa Rabbit invents a clever game, embarking on a grand journey aboard the Slippers Express! First stop: Carrotville, then Washville, and finally, after gentle bedtime adventures, the terminal station at Sleepville. A soothing, beloved ritual for little ones who resist bedtime.', 'Svake večeri ista priča: mali Karlhen ne želi da ide na spavanje. Zato tata zeko smišlja igru i kreće s njim na veliko putovanje brzim „papučastim vozom”. Prva stanica je Šargarepograd, pa Kupanjac, dok konačno ne stignu na krajnju stanicu — Sanjograd u dječijoj sobi. Neodoljiva i topla priča za laku noć.', 'Лучший родительский лайфхак: превратить утомительное укладывание в весёлое путешествие на папиных тапках прямиком в Спибург!', 'The ultimate bedtime hack: turn evening stalling into a playful ride on Papa''s slipper train straight to Sleepville!', 'Genijalan roditeljski trik: pretvorite večernje odugovlačenje u veselu vožnju na tatinim papučama pravo u Sanjograd!', '/covers/DP-0012.webp', '#2b4c7e', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["animals","funny","adventure"]', '["bedtime","bunnies","toddlers","fatherhood","family"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зимняя-книга-13', 'DP-0013', 'Зимняя книга', 'Winter', 'Zimska knjiga', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', '', 'Самокат', NULL, NULL, 0, 6, 'little', '«Зимняя книга» знакомит начинающих читателей со всеми обитателями Городка - людьми и животными. Эти книги расскажут множество интересных историй, которые произошли на улицах Городка однажды зимой. Книжки-картинки Ротраут Сузанны Бернер стали бестселлерами во многих странах мира от Японии до Фарерских островов. И нет никаких сомнений, что добрые, отзывчивые и любознательные герои этих оригинальных книжек будут любимы и в России. ВНИМАНИЮ РОДИТЕЛЕЙ И ПЕДАГОГОВ! Книжки-картинки Ротраут Сузанны Бернер это еще и прекрасные пособия для обучения детей пересказу, рассказу по картинке, запоминанию, а также для логопедических занятий с детьми и взрослыми.', 'The Winter Book welcomes young explorers into a bustling, snow-dusted town filled with charming residents and animal friends. Through detailed, text-free panoramic spreads, Rotraut Susanne Berner weaves countless visual storylines—from a runaway parrot and a lost wallet to joyful neighborhood chores and winter games. A world-renowned classic that sparks vocabulary development, close observation, and endless family storytelling.', '„Zimska knjiga“ vodi najmlađe čitaoce u snježnu šetnju gradićem prepunim simpatičnih stanovnika i njihovih ljubimaca. Na bogato ilustrovanim stranicama ovog čuvenog vimlbuha kriju se bezbrojne svakodnevne avanture: potraga za odbjeglim papagajem, zimske radosti i tople komšijske zgode. Izvanredna knjiga-skrivalica koja podstiče razvoj govora, zapažanje detalja i zajedničko maštanje.', 'Отыщите сбежавшего попугая, проследите за каждым прохожим и сочините десятки собственных историй о заснеженном Городке!', 'Track down the runaway parrot, follow the bustling neighbors, and invent your very own winter tales on every page!', 'Pronađite odbjeglog papagaja, pratite vesele prolaznike i smislite sopstvene priče o ovom sniježnom gradiću!', '/covers/DP-0013.webp', '#759bb5', '0+', 'ru', 'available', 'большого формата', '["friends","animals","real"]', '["виммельбух","зима","находилка","развитие речи","город"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ночная-книга-14', 'DP-0014', 'Ночная книга', 'The Night Book', 'Noćna knjiga', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', '', 'Самокат', NULL, NULL, 0, 6, 'little', 'Долгожданная книга немецкой художницы Ротраут Сузанны Бернер из популярной серии про Городок наконец-то выходит в России! В Городке наступила ночь. Люди и звери мирно спят, во всяком случае, некоторые. Остальные отправились гулять и стали участниками самых удивительных событий: кто провел ночь в библиотеке, кто ловил вора, а кто побывал на празднике в парке. В «Ночной книге» Ротраут Сузанна Бернер рассказывает о порхающих летучих мышах, о прогулках при луне и об уютных кроватях — обо всем, что происходит в Городке теплой летней ночью.', 'Night has fallen over the little town, but not everyone is fast asleep! While some residents snooze peacefully in their cozy beds, others are out wandering under the moonlit sky, solving mysteries, catching a thief, or partying in the park. Filled with flitting bats, warm summer breezes, and countless hidden details, this beloved wimmelbook is a bedtime treasure for curious little eyes.', 'Noć se spustila na gradić, ali ne spavaju svi! Dok neki mirno sanjaju u toplim krevetima, drugi šetaju pod mjesečinom, hvataju lopova ili uživaju u noćnoj zabavi u parku. Prepuna šišmiša, ljetnjeg povjetarca i bezbroj skrivenih detalja koje treba pronaći, ova omiljena slikovnica-tražilica savršena je za čitanje i maštanje pred spavanje.', 'Загляните в сонный Городок под звёздным небом, где жизнь ночью только начинается — идеальный виммельбух для тихих открытий перед сном!', 'Peek into the sleepy little town under the starry sky, where gentle nocturnal adventures are just getting started!', 'Zavirite u usnuli gradić pod zvjezdanim nebom, gdje tihe noćne avanture i istraživanja tek počinju!', '/covers/DP-0014.webp', '#1b294b', '0+', 'ru', 'available', 'большого формата, повреждена обложка', '["adventure","real","animals"]', '["wimmelbuch","bedtime","nighttime","search and find","town life"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('осенняя-книга-15', 'DP-0015', 'Осенняя книга', 'All Around Bustletown: Autumn', 'Jesenja knjiga', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', '', 'Самокат', NULL, NULL, 0, 6, 'little', '«Осенняя книга» знакомит начинающих читателей со всеми обитателями Городка — людьми и животными. Эти книги расскажут множество интересных историй, которые произошли на улицах Городка однажды осенью. Книжки-картинки Ротраут Сузанны Бернер стали бестселлерами во многих странах мира от Японии до Фарерских островов. И нет никаких сомнений, что добрые, отзывчивые и любознательные герои этих оригинальных книжек будут любимы и в России. Книжки-картинки Ротраут Сузанны Бернер это еще и прекрасные пособия для обучения детей пересказу, рассказу по картинке, запоминанию, а также для логопедических занятий с детьми и взрослыми.', 'The Autumn Book introduces young readers to the charming inhabitants of Bustletown, both human and animal. Bursting with intricate, wordless illustrations, it weaves countless little stories unfolding across town on a crisp autumn day. A globally beloved wimmelbook, it is an ideal companion for sparking observation skills, speech development, and family storytelling.', '„Jesenja knjiga“ upoznaje najmlađe čitaoce sa svim stanovnicima Gradića — i ljudima i životinjama. Kroz predivne i detaljne ilustracije bez riječi kriju se bezbrojne priče koje se odvijaju u jednom prijatnom jesenjem danu. Ovaj svjetski bestseler savršen je za razvoj govora, zapažanja i zajedničko maštanje.', 'Устройтесь поуютнее с тёплым пледом и попробуйте отыскать сбежавшего попугая и огромную тыкву на шумных улочках Городка!', 'Grab a cozy blanket and follow the delightfully busy townspeople through leaf piles, lantern parades, and runaway pets!', 'Ušuškajte se i krenite u zabavnu potragu za bundevama, lampionima i izgubljenim papagajem kroz tople ulice Gradića!', '/covers/DP-0015.webp', '#d97724', '0+', 'ru', 'available', 'карманного формата', '["real","friends","animals"]', '["wimmelbuch","autumn","seasons","search-and-find","everyday-life"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('природа-над-землей-и-под-земле-16', 'DP-0016', 'Природа над землей и под землей', 'Nature Above and Below', 'Priroda iznad i ispod zemlje', 'Анн-Софи Боман', 'Anne-Sophie Baumann', 'En-Sofi Boman', '', 'Эта необычная книга покажет вашему ребенку, что скрывает природа от наших глаз: на дне реки и в морских водах, в лесу среди густых зарослей и в опавшей листве, на вершине горы и в подземной пещере. Вы узнаете, как животные строят свои норы и как под землей выглядит наш огород, чем питаются деревья и откуда под землей берется вода...', NULL, NULL, 0, 6, 'little', 'Клотильда Перрен', 'This fascinating lift-the-flap journey reveals the secret wonders hidden from our view: from riverbeds and ocean depths to forest floors and mountain caves, showing how animals build subterranean homes and where underground water comes from.', 'Ova čudesna knjiga sa prozorčićima otkriva tajne koje priroda krije od naših očiju: na dnu rijeka i u morskim dubinama, u šumi među lišćem, na planinskim vrhovima i u podzemnim pećinama, pokazujući kako životinje grade svoja skrovišta.', 'Загляните под каждый листик и корягу — там кипит удивительная тайная жизнь, о которой взрослые даже не догадываются!', 'Peek beneath every leaf and burrow to uncover the bustling secret world thriving right under our feet!', 'Zavirite ispod svakog lista i skrivenog kutka da otkrijete tajni život prirode koji se odvija tik pod našim nogama!', '/covers/DP-0016.webp', '#3f7a4d', '0+', 'ru', 'available', 'МИФ', '["real","animals","adventure"]', '["nature","animals","encyclopedia","underground","flaps"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кротик-и-его-друзья-17', 'DP-0017', 'кротик и его друзья', 'Little Mole and His Friends', 'Krtić i njegovi prijatelji', 'Зденек Миллер', 'Zdeněk Miler', 'Zdenjek Miler', '', 'Книжки-картинки с яркими иллюстрациями непременно понравятся детям. Ведь в них много неожиданных и интересных деталей, которые можно разглядывать бесконечно долго и каждый раз находить что-то новое! В этой книге столько зверей! И все они — друзья знаменитого Кротика, которого придумал художник Зденек Милер. Смотрите-ка: Сова играет на дудочке, а зверята танцуют. Вот Заяц несёт кому-то букет цветов, Белочка нашла яблоко, Мишка играет в мячик… А чем ещё занимаются звери в Сказочному лесу, ваш ребёнок узнает, рассматривая красочные и весёлые картинки.', NULL, NULL, 0, 6, 'little', '', 'Meet the beloved Little Mole and all his woodland companions! Full of vibrant, detailed illustrations, this charming board book invites young toddlers to spot the owl playing a flute, a dancing bunny, and a bear rolling a ball, making every page turn a delightful game of forest hide-and-seek.', 'Upoznajte voljenog Krtića i sve njegove šumske drugare! Puna vedrih i detaljnih ilustracija, ova divna slikovnica poziva najmlađe da pronađu sovu koja svira frulu, zeku koji pleše i meda s loptom, pretvarajući svako listanje u pravu malu šumsku pustolovinu.', 'Самый добрый чешский Кротик снова собирает лесную полянку друзей — идеальная книга-картинка для первых уютных разглядываний с малышом!', 'The world''s sweetest Little Mole brings his woodland pals together for an irresistible picture book perfect for early discovery and cozy cuddles!', 'Najomiljeniji Krtić na svijetu okuplja šumsku družinu u predivnoj slikovnici stvorenoj za prvo toplo istraživanje sa vašim mališanom!', '/covers/DP-0017.webp', '#3f7a4d', '0+', 'ru', 'available', 'Росмэн | поврежден корешок книги', '["animals","friends"]', '["board book","forest animals","toddlers","classic illustration","picture book"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кротик-и-путешествие-18', 'DP-0018', 'Кротик и путешествие', 'Little Mole''s Big Journey', 'Krtić i veliko putovanje', 'Зденек Миллер', 'Zdeněk Miler', 'Zdenjek Miler', '', 'Книжки-картинки с яркими иллюстрациями непременно понравятся детям. Ведь в них много неожиданных и интересных деталей, которые можно разглядывать бесконечно долго и каждый раз находить что-то новое! В этой книге храбрый Кротик отправился в большое путешествие. Он летает на воздушном шаре над лесами и городами, плавает на корабле в бескрайнем море, взбирается на горы и спускается в ущелья. Вот так Кротик! Если ваш ребёнок отправится в путешествие по ярким страничкам, он отыщет знаменитого персонажа Зденека Милера ещё во множестве самых разных уголков мира.', NULL, NULL, 0, 6, 'little', '', 'Join beloved Little Mole as he sets off on a grand adventure across the globe! Floating in a hot-air balloon above bustling cities, sailing across vast blue seas, and trekking through mountains, Krtek discovers the world in this wonderfully detailed, vibrant picture book that toddlers will love exploring again and again.', 'Pridružite se omiljenom Krtiću u njegovoj velikoj pustolovini širom svijeta! Leteći balonom iznad šuma i gradova, ploveći brodom po plavom moru i osvajajući planine, hrabri junak otkriva čuda planete na bogato ilustrovanim stranicama koje najmlađi mogu istraživati bez prestanka.', 'Запрыгивайте в воздушный шар вместе с неутомимым Кротиком — это идеальная книга для первых мечтаний о дальних странствиях!', 'Hop into a hot-air balloon with everyone''s favorite little mole — the ultimate feel-good picture book for little wanderers!', 'Uskočite u balon sa neumornim Krtićem — savršena slikovnica za prvo maštanje o dalekim putovanjima!', '/covers/DP-0018.webp', '#3a86c8', '0+', 'ru', 'available', 'Росмэн', '["adventure","animals"]', '["picture book","little mole","travel","toddlers","classic"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('найди-и-покажи-на-ферме-19', 'DP-0019', 'Найди и покажи на ферме', 'Seek and Find: On the Farm', 'Pronađi i pokaži na farmi', 'Тьерри Лаваль', 'Thierry Laval', 'Thierry Laval', '', 'Эта удивительная книжка-раскладушка — захватывающий путеводитель по ферме, который познакомит вас с различными домашними животными, заботами и обязанностями деревенских жителей. Что можно делать с этой книгой: > тренировать внимание, находя на панорамной картинке множество мелких деталей > развивать память > тренировать счёт > расширять словарный запас > придумывать истории. Здесь 5 раскладывающихся страниц-панорам: сад и огород, посевные работы, скотный двор, сбор урожая — все это есть здесь, на страницах книжки.', NULL, NULL, 0, 6, 'little', '', 'An exciting fold-out wimmelbuch that takes toddlers right into the heart of the countryside! Featuring five giant panoramic fold-outs—the garden, the sowing fields, the bustling barnyard, and the harvest—this interactive book lets little readers spot hidden animals, practice counting, expand their vocabulary, and invent their own farm stories.', 'Uzbudljiva slikovnica-harmonika koja vodi mališane u pravo seosko carstvo! Sa pet velikih panoramskih strana na rasklapanje — od povrtnjaka i sjetve do seoskog dvorišta i žetve — ova interaktivna knjiga omogućava djeci da traže skrivene detalje, vježbaju brojanje, šire rječnik i otkrivaju domaće životinje.', 'Разверните гигантские панорамы и проверьте свою зоркость: сколько гусей, тракторов и хитрых мышат отыщет ваш юный следопыт?', 'Unfold these giant panoramic pages and see if your little detective can spot every tractor, piglet, and carrot hidden across the busy farm!', 'Rasklopite ove čarobne panorame i provjerite koliko traktora, prasića i skrivenih detalja vaš mališan može da pronađe!', '/covers/DP-0019.webp', '#5b8c32', '0+', 'ru', 'available', 'clever', '["animals","real","adventure"]', '["wimmelbuch","farm animals","search and find","interactive","toddlers"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('найди-и-покажи-динозавры-20', 'DP-0020', 'Найди и покажи Динозавры', 'Seek and Find: Dinosaurs', 'Pronađi i pokaži: Dinosaurusi', 'Тьерри Лаваль', 'Thierry Laval', 'Thierry Laval', '', 'На каждом из 5 разворотов — живописная панорама, посвященная той или иной эпохе. Сначала внимательно изучите животных на клапанах, а потом найдите их на панорамах. Тренируйте внимательность, воображение, развивайте память, играйте в командные игры и находите все 196 предметов. Поразите друзей и родителей своими глубокими познаниями! Изюминки книжки: • Удобная форма книги позволит взять ее с собой в любое путешествие. • Стремительно набирающая популярность серия книг-находилок «Найди и покажи». • Книга «Найди и покажи. Динозавры» — это 5 раскладывающихся панорам и 196 предметов для поиска! • Роскошный подарок для малышей: яркая, увлекательная книга развивает внимание, память, воображение и мышление.', NULL, NULL, 0, 6, 'little', '', 'Travel millions of years back in time with five giant fold-out panoramas teeming with prehistoric life. Study the dinosaurs on the flaps, then search for all 196 hidden creatures across different prehistoric epochs in this captivating visual adventure.', 'Otputujte milionima godina u prošlost uz pet velikih rasklopivih panorama prepunih praistorijskih stvorenja. Proučite dinosauruse na preklopima, a zatim pronađite svih 196 skrivenih bića kroz različite epohe u ovoj uzbudljivoj vizuelnoj avanturi.', 'Пять гигантских панорам и 196 доисторических находок — гарантированный способ подарить маленькому палеонтологу часы азартных поисков и восторга!', 'Five giant fold-out panoramas and 196 prehistoric treasures to spot—the ultimate visual quest to keep your little paleontologist happily absorbed!', 'Pet džinovskih panorama i čak 196 praistorijskih bića za traženje — savršena knjiga-tražilica za sate uzbudljivog istraživanja malih paleontologa!', '/covers/DP-0020.webp', '#3d7e5a', '0+', 'ru', 'available', 'clever', '["adventure","animals"]', '["dinosaurs","seek-and-find","wimmelbuch","interactive"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('найди-и-покажи-5-континентов-21', 'DP-0021', 'Найди и покажи 5 континентов', 'Seek and Find: 5 Continents', 'Pronađi i pokaži: 5 kontinenata', 'Тьерри Лаваль', 'Thierry Laval', 'Tijeri Laval', '', 'Интеллектуальный и познавательный квест по всем континентам земного шара. Все для развития ребенка: тренировка памяти, внимательности Изучение животных, счета, и самое главное – игра прививает ЛЮБОЗНАТЕЛЬНОСТЬ! Оригинальный, привлекательный формат: страницы раскладываются, увеличивая площадь книги в два раза. Книга-игра: играть можно всей семьей, с друзьями. Выполнять задания на скорость, разбившись на команды.', NULL, NULL, 0, 6, 'little', '', 'Unfold gigantic panoramic pages and embark on a thrilling quest across the five continents! Packed with clever details, this playful search-and-find book lets little explorers discover wild animals, world cultures, and breathtaking landscapes while training their attention and memory.', 'Rasklopite ogromne panoramske stranice i krenite na uzbudljivo putovanje kroz pet kontinenata! Ova zabavna knjiga-skrivalica pomaže malim istraživačima da upoznaju divlje životinje, svjetske kulture i zadivljujuće pejzaže, vježbajući pažnju i pamćenje.', 'Раскладывайте огромные панорамы на ковре и считайте забавных зверят со всех уголков планеты всей семьёй!', 'Spread out these giant panoramic pages on the floor and embark on a globe-trotting animal treasure hunt with the whole family!', 'Raširite ove ogromne panorame po podu i sa cijelom porodicom krenite u veselu potragu za životinjama sa svih krajeva svijeta!', '/covers/DP-0021.webp', '#348aa7', '0+', 'ru', 'available', 'clever', '["adventure","animals","real"]', '["seek-and-find","animals","continents","geography","interactive"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мир-животных-22', 'DP-0022', 'Мир животных', 'Little Explorers: The Animal World', 'Svijet životinja', 'Рут Мартин', 'Ruth Martin', 'Rut Martin', '', '', NULL, NULL, 0, 6, 'little', 'Аллан Сандерс', 'A vibrant lift-the-flap guide illustrated by Allan Sanders, inviting little explorers to discover creatures big and small across habitats around the globe.', 'Živopisna interaktivna slikovnica s prozorčićima, koju je ilustrovao Alan Sanders, vodi male istraživače u uzbudljiv svijet životinja iz svih krajeva planete.', 'Загляните под каждый клапан и познакомьтесь с удивительными зверями со всех уголков нашей планеты!', 'Peek under every flap to meet fascinating creatures from the deepest oceans to the tallest treetops!', 'Zavirite ispod svakog prozorčića i otkrijte čudesna stvorenja iz svih krajeva naše planete!', '/covers/DP-0022.webp', '#3b7a57', '0+', 'ru', 'available', 'clever', '["animals","adventure","real"]', '["animals","nature","lift-the-flap","board book","early learning"]', 1792836322693, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лес-книга-с-окошками-23', 'DP-0023', 'Лес книга с окошками', 'The Forest: Lift-the-Flap Book', 'Šuma: Knjiga sa prozorčićima', 'Кристина Хенкель', 'Christina Henkel, Daniela Prusse', 'Christina Henkel, Daniela Prusse', '', 'Мини-энциклопедии с окошками ответят на все вопросы, которые задают любознательные малыши. Ваш ребёнок узнает всё о лиственных и хвойных деревьях, а также о ягодах, грибах, папоротниках и обо всём интересном, что только можно найти в Лесу! Для детей дошкольного возраста.', NULL, NULL, 0, 6, 'little', 'Даниэла Прусс', 'A charming mini lift-the-flap encyclopedia answering curious toddlers'' questions about deciduous and evergreen trees, woodland berries, mushrooms, ferns, and all the forest wildlife.', 'Mala enciklopedija sa prozorčićima koja odgovara na pitanja radoznalih mališana o drveću, šumskim bobicama, gljivama i skrivenim šumskim stanovnicima.', 'Загляните под каждое окошко, чтобы раскрыть пушистые и зелёные тайны самого настоящего леса!', 'Peek under each flap to discover the rustling secrets and tiny creatures hiding in the woods!', 'Zavirite iza svakog prozorčića i otkrijte male i velike tajne čudesnog šumskog svijeta!', '/covers/DP-0023.webp', '#2e6f40', '0+', 'ru', 'available', 'АСТ', '["animals","real","adventure"]', '["forest","nature","lift-the-flap","board-book","animals"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пластилиновая-азбука-абв-24', 'DP-0024', 'Пластилиновая азбука АБВ', 'The Clay Alphabet: ABV', 'Plastelinska azbuka ABV', 'Сергей Меринов', 'Sergey Merinov', 'Sergej Merinov', '', 'В небе - аисты и ангелы, на земле - богатыри и великаны. В руках одного из лучших пластилиновых аниматоров России Сергея Меринова, одного из авторов "Горы самоцветов" и "Мульти-России", буквы "Пластилиновой азбуки" начинают жить собственной жизнью: "А" улетает в небо, а "Б" страдает от обжорства. Это целая волшебная азбучная страна, русская алфавитная сказка. Для маленьких детей нет лучше способа начать постигать алфавит, чем погрузиться в него с головой: подружиться с персонажами, пропевать веселые стихи, а еще и лепить по­любившихся героев, которые, если следовать инструкции аниматоров, получатся совсем такими же, как в мультфильме.', NULL, NULL, 0, 6, 'little', '', 'Created by celebrated clay animator Sergey Merinov, this vibrant alphabet book brings Russian letters to life with warmth and humor. From flying storks to ravenous giants, each letter stars in its own playful mini-tale with catchy rhymes and step-by-step instructions for little fingers to sculpt the characters right out of modeling clay.', 'Stvorena od strane poznatog animatora plastelina Sergeja Merinova, ova živopisna azbuka oživljava slova uz humor i toplinu. Uz vesele stihove i korak-po-korak uputstva za vajanje likova od plastelina, učenje slova postaje prava kreativna i razigrana avantura za najmlađe.', 'Запасайтесь брусками яркого пластилина: с этой книгой буквы не просто учат, их лепят, оживляют и превращают в мультфильм прямо на ковре!', 'Stock up on colorful modeling clay: with this book, little hands don''t just learn letters—they sculpt them into life!', 'Pripremite šareni plastelin: uz ovu knjigu slova se ne samo uče, već se oživljavaju i vajaju pravo na vašem stolu!', '/covers/DP-0024.webp', '#e35d25', '0+', 'ru', 'available', 'Бурда', '["funny","magic"]', '["азбука","алфавит","лепка","стихи","творчество"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бе-и-ме-пикник-25', 'DP-0025', 'Бе и Ме. Пикник', 'Boo and Baa on a Picnic', 'Be i Me: Piknik', 'Улоф Ландстрем', 'Olof Landström', 'Olof Landström', '', 'Бе и Ме отправились на пикник. Они плыли на лодке и пели песню. Но вдруг лодка села на мель! Что делать? Для чтения взрослым детям.Книжки-картинки про Бе и Ме, появившиеся в Швеции в 90-е годы, стали современной классикой. Сегодня они известны во многих странах и переведены на восемь языков. Это серия смешных книг для самых маленьких ребят; истории можно перечитывать снова и снова: забавные картинки с очаровательными деталями, тонкий и в то же время простой юмор, узнаваемые ситуации – за это Бе и Ме любят и ценят дети и взрослые разных стран. Когда Бе и Ме берутся за дело, обязательно начинаются приключения, даже если это простая уборка или пикник на озере. Но барашки всегда находят выход из самых запутанных ситуаций, главное, чтобы было чем подкрепиться!', NULL, NULL, 0, 6, 'little', '', 'Boo and Baa head out across the lake in their little rowboat for a cozy picnic, singing merrily along the way. But when their boat unexpectedly runs aground, the two little sheep must figure out how to get unstuck. A beloved Swedish classic picture book full of quiet humor and gentle, relatable adventures for toddlers.', 'Be i Me su se uputili čamcem na piknik preko jezera, veselo pjevajući. Ali iznenada, čamac se nasukao! Kako će se dva simpatična jagnjeta izvući iz ove nevolje i stići do svoje užine? Omiljeni švedski klasik slikovnica, prožet toplim humorom i prepoznatljivim situacijama za najmlađe.', 'Очаровательная шведская классика о двух неунывающих барашках, для которых любая мель — лишь отличный повод подкрепиться!', 'A wonderfully gentle Swedish gem proving that no boating mishap can ruin a great picnic when you''re with your best friend.', 'Neodoljiva i topla priča o dva jagnjeta koja dokazuju da nikakva nezgoda na vodi ne može pokvariti piknik s najboljim prijateljem!', '/covers/DP-0025.webp', '#5b9279', '0+', 'ru', 'available', 'Белая ворона', '["funny","friends","animals"]', '["sheep","picnic","friendship","swedish literature","toddlers"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('меня-зовут-мильтон-26', 'DP-0026', 'Меня зовут Мильтон', 'My Name Is Milton', 'Zovem se Milton', 'Хайде', 'Haydé Ardalan', 'Haydé Ardalan', '', 'В этой книжке - истории про озорного черно-белого кота Мильтона. Как и все коты, он всячески старается подчеркнуть уверенность в себе и полную независимость. Черно-белая графика Хайде Ардалан стилизована под детский рисунок, но отличается большой выразительностью.', NULL, NULL, 0, 6, 'little', '', 'Meet Milton, a cheeky black-and-white cat who is utterly convinced of his own supreme importance and fierce independence. With expressive, minimalist line art styled like a child''s drawing, this delightful picture book captures the humorous daily routines, quirks, and charming pride of a beloved feline companion.', 'Upoznajte Miltona, nestašnog crno-bijelog mačka koji je potpuno ubijeđen u svoju nepokolebljivu samostalnost i važnost. Kroz izražajne, minimalističke crteže koji podsjećaju na dječije skice, ova slikovnica na duhovit način prikazuje svakodnevni život, hirove i ponos jednog pravog mačjeg filozofa.', 'Очаровательный черно-белый кот Мильтон научит малышей сохранять невозмутимость и гордое кошачье достоинство в любой непонятной ситуации!', 'Meet Milton, the black-and-white cat who will teach young readers how to maintain utter dignity no matter what mischief unfolds!', 'Upoznajte mačka Miltona, pravog majstora za čuvanje mačijeg dostojanstva čak i u najvećim mogućim nestašlucima!', '/covers/DP-0026.webp', '#2c2c2c', '0+', 'ru', 'available', 'Бумкнига', '["animals","funny"]', '["cats","humor","picture book","black and white","pets"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мильтон-и-вороны-27', 'DP-0027', 'Мильтон и вороны', 'Milton and the Crows', 'Milton i vrane', 'Хайде', 'Haydé', 'Haydé', '', 'В этой книжке - истории в комиксах про озорного черно-белого кота Мильтона. Как и все коты, он всячески старается подчеркнуть уверенность в себе и полную независимость. Черно-белая графика Хайде Ардалан стилизована под детский рисунок, но отличается большой выразительностью.', NULL, NULL, 0, 6, 'little', '', 'This charming graphic tale follows Milton, a cheeky black-and-white cat determined to assert his cool confidence and independence—even when a gang of clever crows tests his feline patience. Expressive, minimalist illustrations bring his funny everyday dramas to life.', 'Ovaj šarmantni strip prati Miltona, nestašnog crno-bijelog mačka koji nastoji da pokaže svoju samouvjerenost i nezavisnost, čak i kada ga grupa dosadnih vrana stavi na probu. Izražajni crno-bijeli crteži dočaravaju njegove neodoljive mačije drame.', 'Очаровательный черно-белый комикс о кошачьей гордости и пушистых проделках, который рассмешит даже самых маленьких читателей!', 'A delightful black-and-white comic about feline pride and cheekiness that will tickle little readers and cat lovers alike!', 'Šarmantan crno-bijeli strip o mačijem ponosu i nestašlucima koji će nasmijati i najmlađe čitaoce!', '/covers/DP-0027.webp', '#2c2d30', '0+', 'ru', 'available', 'Бумкнига', '["funny","animals"]', '["cats","comics","humor","crows","picture-book"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('живая-азбука-28', 'DP-0028', 'Живая азбука', 'Living Alphabet', 'Živa azbuka', '', 'Unknown', 'Nepoznat autor', '', 'Невероятной красоты иллюстрированная обучающая книга ЖИВАЯ АЗБУКА познакомит малыша не только с алфавитом, но и с великим разнообразием мира животных. А кроме того подарит эстетическое удовольствие как ребенку, так и его родителям. Богатейшая коллекция красочных изображений животных! Более 100 потрясающих иллюстраций! Увлекательное путешествие в мир знаний и красоты!', NULL, NULL, 0, 6, 'little', '', 'An exceptionally beautiful illustrated learning book that introduces toddlers not only to letters, but also to the magnificent diversity of the animal kingdom with over 100 stunning illustrations.', 'Nevjerovatno lijepo ilustrovana edukativna knjiga koja mališane upoznaje ne samo sa slovima, već i sa čudesnim svijetom životinja kroz više od 100 raskošnih ilustracija.', 'Учить буквы в компании сотни удивительных зверей — это не просто урок, а настоящее эстетическое сафари для малышей и родителей!', 'Learning the alphabet alongside a hundred magnificent creatures turns storytime into a breathtaking visual safari!', 'Učenje slova u društvu stotinu predivnih životinja pretvara se u pravi vizuelni safari za mališane i roditelje!', '/covers/DP-0028.webp', '#438945', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["animals","real"]', '["alphabet","animals","early learning","picture book"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('живой-английский-29', 'DP-0029', 'Живой английский', 'Living English', 'Živi engleski', '', 'Unknown', 'Nepoznati autor', '', 'Невероятной красоты иллюстрированная обучающая книга ЖИВОЙ АНГЛИЙСКИЙ познакомит малыша не только с противоположностями, но и с великим разнообразием мира животных. А кроме того, подарит эстетическое удовольствие как ребёнку, так и его родителям. Богатейшая коллекция красочных изображений животных! Более 100 потрясающих иллюстраций! Увлекательное путешествие в мир знаний и красоты.', NULL, NULL, 0, 6, 'little', '', 'An exquisitely illustrated educational book that introduces toddlers to opposites and the magnificent diversity of the animal kingdom. With more than 100 vibrant animal illustrations, it turns learning first English words into a joyful, visual adventure for children and parents alike.', 'Izuzetno ilustrovana edukativna slikovnica koja upoznaje mališane sa suprotnostima i veličanstvenim carstvom životinja. Sa više od 100 raskošnih ilustracija, učenje prvih engleskih riječi pretvara se u pravu vizuelnu i zabavnu avanturu za djecu i roditelje.', 'Учить первые английские слова ещё никогда не было так эстетично, познавательно и пушисто!', 'Learning your first English words has never looked so gorgeous, wild, and utterly delightful!', 'Učenje prvih engleskih riječi nikada nije bilo tako lijepo, poučno i puno divnih životinja!', '/covers/DP-0029.webp', '#3f8a6d', '0+', 'ru', 'available', 'повреждена обложка', '["animals","real"]', '["animals","english","first words","opposites","early learning"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('живые-цифры-30', 'DP-0030', 'Живые цифры', 'Living Numbers', 'Živi brojevi', '', 'Unknown', 'Nepoznati autor', '', 'Невероятной красоты иллюстрированная обучающая книга ЖИВЫЕ ЦИФРЫ познакомит малыша не только с цифрами и счетом, но и с великим разнообразием мира животных. А кроме того подарит эстетическое удовольствие как ребенку, так и его родителям. Богатейшая коллекция красочных изображений животных! Более 100 потрясающих иллюстраций! Увлекательное путешествие в мир знаний и красоты!', NULL, NULL, 0, 6, 'little', '', 'This beautifully illustrated educational book introduces toddlers not only to numbers and counting, but also to the wonderful diversity of the animal kingdom. Featuring over 100 stunning animal illustrations, it turns early learning into a visually captivating adventure for both children and parents.', 'Ova predivno ilustrovana edukativna knjiga upoznaje mališane ne samo sa brojevima i brojanjem, već i sa čarobnim carstvom životinja. Sa više od 100 prelijepih ilustracija, učenje brojeva pretvara se u pravo vizuelno uživanje za djecu i roditelje.', 'Считать слонят и бабочек куда веселее, чем сухие цифры — эта книга превратит первые уроки счёта в прогулку по яркому зоопарку!', 'Counting playful elephants and butterflies is so much fun—this book turns early math into a colorful safari adventure!', 'Brojanje slonova i leptirića mnogo je zabavnije od suvih cifara — ova knjiga pretvara prve korake u matematici u šareni safari!', '/covers/DP-0030.webp', '#e67e22', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["animals","real"]', '["counting","animals","numbers","early learning","board book"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волли-в-голливуде-31', 'DP-0031', 'Волли в Голливуде', 'Where''s Wally? In Hollywood', 'Gdje je Vali? U Holivudu', 'Мартин Хэнфорд', 'Martin Handford', 'Martin Handford', '', 'Вы уже нашли Волли? Вот это да! Волли попал в Голливуд! Попробуй отыскать его среди вспышек камер и декораций. Играя в прятки с Волли, не забудь найти и его товарищей - Венду, Белоборода и Гав-Гава! Помни и о том, что где-то прячется вор Беззаконник. Супергерои и потрясающие актёры, великолепные сцены и неразбериха на сьёмках. Внимание, сыщики! Это будет непросто, ведь про Волли даже сняли фильм - попробуй отличить настоящего! Скорее на поиски!', NULL, NULL, 0, 6, 'little', '', 'Wally heads straight to the bustling film sets of Hollywood! Amid thousands of actors, flashing cameras, superheroes, and epic movie scenes, sharp-eyed readers must track down the famous traveler in his red-and-white stripes, along with Wenda, Wizard Whitebeard, Woof, and the sneaky Odlaw.', 'Vali stiže pravo na užurbane filmske setove Holivuda! Među hiljadama glumaca, bljeskovima kamera, superherojima i filmskim haosom, mali detektivi imaju zadatak da pronađu čuvenog putnika u crveno-bijelom prugastom džemperu, kao i njegove vjerne prijatelje.', 'Вооружитесь терпением и острым взглядом: отыскать полосатого путешественника среди сотен голливудских кинодекораций — задачка для настоящих суперсыщиков!', 'Sharpen your eyes and get ready for a challenge: tracking down our striped traveler in Hollywood''s hilarious cinematic mayhem is sheer delight!', 'Izoštrite pogled i naoružajte se strpljenjem: pronaći prugastog junaka u holivudskom filmskom haosu pravi je izazov za male detektive!', '/covers/DP-0031.webp', '#d62828', '0+', 'ru', 'available', 'Речь', '["funny","adventure"]', '["виммельбух","поиск предметов","кино","внимательность","головоломка"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-чудес-32', 'DP-0032', 'Книга чудес', 'Where''s Wally? The Wonder Book', 'Gdje je Vili? Knjiga čuda', 'Мартин Хэнфорд', 'Martin Handford', 'Martin Handford', '', 'Волли путешествует среди самых невероятных чудес. Вас ждут город клоунов, кондитерская фабрика, игрушечный магазин, болото Беззаконника. Среди всего этого беспорядка Волли и его команда потерялась! Несколько миллионов наблюдательных читателей в двух десятках стран мира уже отыскали отважных путешественников на страницах этой книги. А ты сумеешь найти знаменитого Волли? Лучшая в мире игра на внимание для следопытов-любителей!', NULL, NULL, 0, 6, 'little', '', 'Wally and his trusty friends explore the most incredible wonders, from a dizzying clown town and a bustling candy factory to an outlaw swamp and a magical toy shop. Amidst all the colorful chaos and hidden jokes, can you spot the famous traveler in the red-and-white striped shirt? A world-renowned search-and-find classic that promises hours of absorbing fun for eagle-eyed explorers.', 'Vili i njegova vesela družina putuju kroz nevjerovatna čuda: grad klovnova, fabriku slatkiša, prodavnicu igračaka i močvaru odmetnika. U ovom šarenom metežu punom duhovitih detalja, možete li pronaći slavnog putnika u prugastoj majici? Legendarna potraga i vježba zapažanja koja garantuje sate zabave za oštrooke istraživače svih uzrasta.', 'Запаситесь терпением и лупой: отыскать Волли среди сотен клоунов и тортов — задачка не из легких, но оторваться просто невозможно!', 'Grab your magnifying glass: spotting Wally amidst a sea of clowns and cakes is tricky, brilliant, and utterly addictive!', 'Pripremite lupu i strpljenje: pronaći Vilija među stotinama klovnova i kolača pravi je izazov od kojeg se ne možete odvojiti!', '/covers/DP-0032.webp', '#d63031', '0+', 'ru', 'available', 'Речь', '["adventure","funny"]', '["виммельбух","поиск предметов","где волли","внимание","wimmelbuch"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мое-любимое-животное-33', 'DP-0033', 'Мое любимое животное', 'What''s Your Favorite Animal?', 'Moja omiljena životinja', 'Эрик Карл и др.', 'Eric Carle and Friends', 'Erik Karl i prijatelji', '', 'Эрик Карл и его друзья - самые известные детские иллюстраторы - придумали увлекательную книжку, в которой каждый из них рассказал о своем любимом животном. Рассказал, почему именно это животное нравится художнику больше всего. И нарисовал его. Получился книжный шедевр. Энциклопедия для малышей про животных? Или художественный альбом, рассматривая который малыш видит разные художественные стили, разные техники, разные подходы: как рисовать животных. Пожалуйста, нарисуй и свое любимое животное! Для детей от 4 до 8 лет.', NULL, NULL, 0, 6, 'little', '', 'Fourteen celebrated children''s book illustrators, led by Eric Carle, reveal their favorite animals through distinct artistic styles, playful stories, and vibrant collage techniques that inspire young readers to grab crayons and draw their own.', 'Četrnaest vrhunskih ilustratora za djecu, predvođenih Erikom Karlom, predstavlja svoje omiljene životinje kroz jedinstvene stilove, tople priče i raznovrsne likovne tehnike koje podstiču mališane da i sami stvore svoja remek-djela.', 'Четырнадцать гениальных художников показывают своих любимцев и так заражают вдохновением, что вам немедленно захочется нарисовать кота, слона или пингвина!', 'Fourteen world-famous illustrators show off their favorite creatures, and it''s impossible to finish without immediately grabbing your crayons!', 'Četrnaest slavnih ilustratora predstavlja svoja omiljena stvorenja — nemoguće je zatvoriti knjigu a da odmah ne poželite da uzmete bojice u ruke!', '/covers/DP-0033.webp', '#2f80ed', '0+', 'ru', 'available', 'Карьера пресс', '["animals","friends","funny"]', '["animals","art","illustration","creativity","picture book"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказка-про-вилли-и-донни-34', 'DP-0034', 'Сказка про Вилли и Донни', 'The Tale of Willy and Donny', 'Bajka o Viliju i Doniju', 'Александр Смакотин', 'Aleksandr Smakotin', 'Aleksandar Smakotin', '', 'Это сказка о том, кто мы есть на самом деле и о том, как важно принимать себя такими, какими нас создал этот мир - ведь именно в этом и заключено счастье!', NULL, NULL, 0, 6, 'little', 'Алена Зайцева', 'A warm and tender bedtime tale about discovering who we truly are and the beauty of accepting ourselves just as we were made — because that is where real happiness begins.', 'Topla i nježna priča o tome ko smo zaista i koliko je važno prihvatiti sebe onakvima kakvi jesmo — jer u tome leži prava sreća.', 'Добрая и мудрая сказка для малышей, которая бережно учит ценить себя и радоваться своей неповторимости.', 'A gentle, heartwarming tale that teaches little ones the superpower and joy of simply being themselves.', 'Nježna i topla priča koja najmlađe uči koliko je divno voljeti sebe baš onakvim kakav jesi.', '/covers/DP-0034.webp', '#e29b52', '0+', 'ru', 'available', 'Пиком', '["friends","animals"]', '["self-acceptance","friendship","kindness","bedtime story","toddlers"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('где-волли-книга-чудес-35', 'DP-0035', 'Где Волли? книга чудес', 'Where''s Wally? The Wonder Book', 'Gdje je Voli? Knjiga čuda', 'Мартин Хэнфорд', 'Martin Handford', 'Martin Handford', '', 'Волли путешествует среди самых невероятных чудес. Вас ждут город клоунов, кондитерская фабрика, игрушечный магазин, болото Беззаконника. Среди всего этого беспорядка Волли и его команда потерялась! Несколько миллионов наблюдательных читателей в двух десятках стран мира уже отыскали отважных путешественников на страницах этой книги. А ты сумеешь найти знаменитого Волли? Лучшая в мире игра на внимание для следопытов-любителей!', NULL, NULL, 0, 6, 'little', '', 'Wally embarks on a dizzying journey through incredible wonderlands, from a chaotic clown town and a bustling candy factory to an enchanted toy shop. Millions of sharp-eyed readers around the world have already tried to spot Wally and his quirky crew—can you find the striped adventurer hidden among hundreds of hilarious details?', 'Voli putuje kroz najnevjerovatnija čuda svijeta: grad klovnova, fabriku slatkiša, prodavnicu igračaka i začarane močvare. Milioni pažljivih čitalaca širom svijeta već su tražili ovog hrabrog putnika — možeš li ti pronaći slavnog prugastog junaka i njegovu družinu u ovom čudesnom, šarenom neredu?', 'Вооружитесь лупой и терпением: отыскать полосатого путешественника в этом искрометном вихре деталей — настоящий спортивный азарт для всей семьи!', 'Grab a magnifying glass and get ready to test your eagle eyes—hunting for the striped wanderer in this delightful whirlwind of chaos is pure addictive fun!', 'Naoružajte se strpljenjem i oštrim vidom: traženje prugastog putnika u ovom šarenom vrtlogu detalja pretvoriće se u pravu zabavu za cijelu porodicu!', '/covers/DP-0035.webp', '#d62828', '0+', 'ru', 'available', 'Рипол Кит', '["adventure","funny"]', '["wimmelbuch","seek-and-find","puzzles","attention","humor"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мир-вокруг-36', 'DP-0036', 'Мир вокруг', 'Make a World', 'Svijet oko nas', 'Эд Эмберли', 'Ed Emberley', 'Ed Emberli', '', 'С этой веселой книгой известного иллюстратора Эда Эмберли ваш ребенок сможет нарисовать целый мир! В ней собраны здания, постройки, автомобили, суда, поезда, люди и животные. Как всегда, Эд Эмбрели раскладывает изображение на линии и простые элементы, а потом собирает их в одну картинку. Повторить эти инструкции сможет любой ребенок!', NULL, NULL, 0, 6, 'little', '', 'With this delightful drawing guide by beloved illustrator Ed Emberley, young artists can create an entire world using simple lines and basic shapes—from ships and trains to bustling cities and friendly animals.', 'Uz ovaj veseli vodič za crtanje proslavljenog ilustratora Eda Emberlija, mali umjetnici mogu nacrtati čitav svijet pomoću jednostavnih linija i oblika — od brodova i vozova do zgrada i životinja.', 'Оказывается, чтобы нарисовать целый город с кораблями и жирафами, нужны всего лишь простые палочки, кружочки и капелька фантазии!', 'Turns out, drawing an entire bustling universe of trains, castles, and critters only takes a few basic shapes and a splash of imagination!', 'Ispostavlja se da vam za crtanje čitavog svijeta sa brodovima i žirafama trebaju samo jednostavne linije, krugovi i malo mašte!', '/covers/DP-0036.webp', '#e67e22', '0+', 'ru', 'available', 'МИФ', '["real","animals"]', '["drawing","creativity","step-by-step","vehicles","art"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('медвежонок-помпон-в-цирке-37', 'DP-0037', 'Медвежонок Помпон в цирке', 'The Bear''s Big Circus Show', 'Medvjedić Pompon u cirkusu', 'Бенджамин Шо', 'Benjamin Chaud', 'Benjamin Chaud', '', 'КомпасГид', 2019, '978-5-907124-04-2', 0, 6, 'little', '', 'Curious Little Bear Pompon wanders off following the sound of lively music and ends up right under the big top of a bustling circus. Papa Bear rushes to the rescue, searching for his cub among acrobats, clowns, and roaring crowds in this delightful, oversized visual hide-and-seek adventure.', 'Radoznali medvjedić Pompon kreće za veselom muzikom i završava pravo pod šatrom bučnog cirkusa. Tata medvjed juri da ga pronađe među akrobatama, klovnovima i razdraganom publikom u ovoj prelijepo ilustrovanoj knjizi-potrazi punoj neodoljivih detalja.', 'Приготовьтесь разглядывать крошечные цирковые шалости на гигантских разворотах и болеть за самого заботливого папу-медведя!', 'Get ready to spot tiny circus antics across gorgeous spreads while cheering on the world''s most determined Papa Bear!', 'Pripremite se za traženje vragolastih cirkuskih detalja na raskošnim stranicama dok navijate za najbrižnijeg medvjeđeg tatu!', '/covers/DP-0037.webp', '#d6453d', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["adventure","funny","animals"]', '["circus","bears","search and find","wimmelbuch","family"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('каб-пора-на-горшок-38', 'DP-0038', 'Каб пора на горшок', 'Caillou: Potty Time', 'Kaju ide na nošu', 'Жоселин Саншагрен', 'Joceline Sanschagrin', 'Žoslen Sanšagren', '', 'Мир и Образование', 2018, '978-5-94666-811-8', 0, 6, 'little', '', 'A gentle and encouraging story that helps toddlers take their first steps toward ditching diapers and embracing potty training with confidence.', 'Nježna i ohrabrujuća priča koja pomaže mališanima da sa osmijehom i bez straha savladaju odvikavanje od pelena i navikavanje na nošu.', 'Добрый и терпеливый помощник для малышей и родителей на пути к уверенному прощанию с подгузниками!', 'A sweet and reassuring little guide that turns potty training into a natural, tear-free adventure!', 'Nježan i vedar saveznik za mališane i roditelje na putu ka sigurnom opraštanju od pelena!', '/covers/DP-0038.webp', '#f4c430', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["real"]', '["potty training","toddlers","growing up","daily life"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чудо-песенки-для-самых-маленьк-39', 'DP-0039', 'Чудо песенки для самых маленьких', 'Wonder Songs for the Little Ones', 'Čudesne pjesmice za najmlađe', '', 'Various Authors', 'Razni autori', '', 'Самовар', 2022, '978-5-9781-1137-8', 0, 6, 'little', '', 'A cheerful collection of classic nursery rhymes, playful verses, and gentle lullabies designed to engage babies and toddlers from their very first words.', 'Vesela zbirka klasičnih dječjih pjesmica, ritmičnih stihova i nježnih uspavanki stvorena da nasmije i umiri najmlađe od njihovih prvih riječi.', 'Лучший способ развеселить капризулю или сладко убаюкать малыша под любимые добрые песенки!', 'The ultimate soundtrack for giggle sessions and sweet bedtimes with your tiny human!', 'Najbolji način da nasmijete mališana ili ga nježno uspavate uz tople, pjevne stihove!', '/covers/DP-0039.webp', '#ffb703', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["funny","animals"]', '["nursery rhymes","songs","toddlers","bedtime","board book"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сонные-сказочки-для-малышей-40', 'DP-0040', 'Сонные сказочки для малышей', 'Bedtime Tales for Toddlers', 'Pospane bajke za najmlađe', 'Елена Ульева', 'Elena Ulyeva', 'Jelena Uljeva', '', 'Феникс-Премьер', 2020, '978-5-222-33247-4', 0, 6, 'little', '', 'A tender collection of soothing bedtime fairy tales designed to help toddlers wind down after an active day, relax, and drift off into sweet dreams.', 'Nježna zbirka umirujućih bajki za laku noć, stvorena da pomogne mališanima da se opuste nakon aktivnog dana i lagano utonu u san.', 'Уютные убаюкивающие истории, которые мягко помогут даже самым неугомонным непоседам сладко уснуть.', 'Cozy, gentle lullaby stories that will gently soothe even the most energetic little dreamers right to sleep.', 'Tople i umirujuće priče koje će i najnemirnije mališane nježno uljuljkati u carstvo snova.', '/covers/DP-0040.webp', '#3f6385', '0+', 'ru', 'available', 'Категория: книжки-картонки', '["magic","animals"]', '["bedtime","toddlers","fairytales","animals","sleep"]', 1792836322694, 1792845651022);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('почему-я-обиделся--41', 'DP-0041', 'Почему я обиделся?', 'Why Am I Feeling Hurt?', 'Zašto sam se uvrijedio?', 'Елена Ульева', 'Elena Ulyeva', 'Elena Ulijeva', '', 'Clever', 2019, '978-5-00115-863-9', 0, 6, 'little', '', 'A tender and accessible guide to emotional intelligence for little ones, helping toddlers understand what being hurt or offended feels like. Through gentle situations, children discover why we pout and how kind words, sharing, and warm hugs can easily melt resentment away.', 'Nježan i pristupačan vodič kroz osjećanja za najmlađe, koji pomaže mališanima da prepoznaju i razumiju zašto se ponekad osjećaju uvrijeđeno. Kroz tople primjere djeca uče kako lijepa riječ, razgovor i zagrljaj mogu otopiti svaku ljutnju.', 'Тёплая сказка-помощница, которая научит малыша не прятать обиды в кармашках, а отпускать их легко и с улыбкой!', 'A gentle helper of a book that teaches little ones how to let go of hurt feelings and make room for big, happy smiles!', 'Topla priča-vodič koja uči mališane kako da otpuste uvrede i zamijene durenje iskrenim osmijehom!', '/covers/DP-0041.webp', '#5b9aa0', '0+', 'ru', 'available', 'Категория: Якоб говорит"нет"', '["real","friends"]', '["emotions","feelings","toddlers","growing up","forgiveness"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('почему-я-злюсь--42', 'DP-0042', 'Почему я злюсь?', 'Why Am I Angry?', 'Zašto se ljutim?', 'Елена Ульева', 'Elena Ulyeva', 'Elena Uljeva', '', 'Clever', 2021, '978-5-00115-876-9', 0, 6, 'little', '', 'A gentle and comforting guide by Elena Ulyeva that helps young children understand anger, recognize where big feelings come from, and discover simple, playful ways to calm their inner storms.', 'Nježna i poučna slikovnica Elene Uljeve koja pomaže mališanima da razumiju svoj bijes, prepoznaju odakle dolaze snažna osjećanja i nauče jednostavne načine kako da se smire.', 'Идеальная терапевтическая сказка для маленьких бунтарей, помогающая превратить сердитую грозовую тучку в тёплое солнышко.', 'The perfect therapeutic tale for little firecrackers, showing how to gently turn angry thunderclouds back into sunshine.', 'Savršena terapeutska priča za male tvrdoglavce koja uči kako da ljutiti olujni oblak pretvore u toplo sunce.', '/covers/DP-0042.webp', '#e05338', '0+', 'ru', 'available', 'Категория: Якоб говорит"нет"', '["real"]', '["emotions","anger","emotional intelligence","toddlers","self-regulation"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('da-grosse-augsburger-wimmelbuc-43', 'DP-0043', 'Daš grosse augsburger wimmelbuch', 'The Big Augsburg Search-and-Find Book', 'Velika augsburška slikovnica tražilica', 'Daniella Grabner', 'Daniela Grabner', 'Daniela Grabner', '', 'Volk Verlag', 2017, '978-3-86222-257-5', 0, 6, 'little', '', 'A vibrant search-and-find journey through the historic city of Augsburg! Little explorers can wander across the bustling town hall square, visit the famous zoo, stroll through the fairytale-like Fuggerei, and discover hundreds of playful details and cheerful everyday stories on every page.', 'Živopisna slikovnica-tražilica vodi male istraživače kroz istorijski grad Augzburg! Šetajte gradskim trgom, posjetite zoološki vrt, zavirite u slavni Fugeraj i otkrijte stotine veselih detalja i razigranih minijaturnih priča na svakoj stranici.', 'Идеальный виммельбух для юных сыщиков: здесь можно часами разглядывать уютные улочки, зоопарк и забавные городские приключения!', 'The ultimate seek-and-find delight: dive into bustling historic streets packed with charming characters and hilarious miniature adventures!', 'Prava poslastica za male istraživače: zaronite u živopisne gradske ulice prepune simpatičnih likova i skrivenih avantura!', '/covers/DP-0043.webp', '#d95f38', '0+', 'ru', 'available', 'Категория: Sonne, mond und sterne', '["adventure","funny","real"]', '["wimmelbuch","seek-and-find","city-life","exploration","board-book"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('da-grosse-bayerische-wimmelbuc-44', 'DP-0044', 'Daš grosse bayerische wimmelbuch', 'The Big Bavarian Wimmelbook', 'Velika bavarska knjiga-skrivalica', 'Daniella Grabner', 'Daniela Grabner', 'Daniela Grabner', '', 'Volk Verlag', 2018, '978-3-86222-273-5', 0, 6, 'little', '', 'Pack your backpack for an entertaining visual journey across Bavaria! From the snowy peaks of the Alps and fairytalesque Neuschwanstein Castle to lively folk festivals, beer gardens, and tranquil crystal-clear lakes, every page is brimming with charming details, quirky characters, and playful mini-stories waiting to be discovered by curious little detectives.', 'Spakujte ruksak za zabavno vizuelno putovanje kroz Bavarsku! Od sniježnih vrhova Alpa i dvorca Nojšvanštajn kao iz bajke, do veselih festivala i kristalnih jezera, svaka stranica vrvi od šarmantnih detalja i skrivenih pričica koje čekaju radoznale male detektive.', 'Настоящий визуальный праздник: разглядывайте Альпы, замки и весёлые праздники, находя сотни забавных историй на каждой странице!', 'A visual treasure hunt through the Alps and fairy-tale castles, packed with hundreds of hilarious little stories to spot!', 'Prava vizuelna avantura kroz Alpe i dvorce iz bajki, prepuna stotina duhovitih detalja za neumorno istraživanje!', '/covers/DP-0044.webp', '#2b70b8', '0+', 'ru', 'available', 'Категория: Sonne, mond und sterne', '["adventure","funny","real"]', '["wimmelbook","seek-and-find","bavaria","mountains","travel","castles"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мэтти-и-неожиданный-гость-45', 'DP-0045', 'Мэтти и неожиданный гость', 'Matti and the Unexpected Guest', 'Mati i neočekivani gost', 'Мадлен Оттеншлеггер, Стефания Райх', 'Madeleine Ottenschläger, Stefanie Reich', 'Madlen Otenšleger, Stefanija Rajh', '', 'Клевер-Медиа-Групп', 2024, '978-5-00211-305-7', 0, 6, 'little', '', 'Matti loves quiet and cozy days, but everything turns upside down when a lively surprise visitor knocks on his door. A gentle and humorous tale about unexpected encounters, stepping outside one''s comfort zone, and discovering that the best friendships often arrive unannounced.', 'Mati obožava mir i tišinu, ali sve se okreće naglavačke kada mu na vrata zakuca neočekivani i razigrani gost. Nježna i duhovita priča o izlascima iz zone komfora, gostoprimstvu i prijateljstvima koja se rode sasvim iznenada.', 'Трогательная и забавная история о том, как незваный гость может превратить обычный тихий день в начало чудесной дружбы!', 'A charming and cozy reminder that sometimes the best adventures start when a surprise visitor knocks at your door!', 'Šarmantna i topla priča koja pokazuje kako nenajavljeni gosti često donose najljepša prijateljstva!', '/covers/DP-0045.webp', '#e2944b', '0+', 'ru', 'available', 'Категория: Книжка для малышей. Профессии', '["friends","animals","funny"]', '["friendship","hospitality","animals","cozy reading","bedtime story"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лора-инглз-уайлдер-46', 'DP-0046', 'Лора инглз уайлдер', 'Laura Ingalls Wilder', 'Lora Ingals Vajlder', 'Мелик-Пашаев', 'Melik-Pashaev', 'Melik-Pašajev', '', 'Мелик-Пашаев', 2021, '978-5-00041-420-0', 7, 10, 'middle', '', 'A warm and nostalgic glimpse into pioneer life on the American frontier, inspired by the beloved autobiographical tales of Laura Ingalls Wilder. Filled with cozy family moments, wilderness challenges, and timeless lessons of courage.', 'Topao i nostalgičan pogled na pionirski život u američkoj divljini, inspirisan voljenim autobiografskim pričama Lore Ingals Vajlder. Knjiga puna porodične topline, prirodnih izazova i bezvremenskih lekcija o hrabrosti.', 'Загляните в бревенчатый домик на краю дикого леса, где морозные вечера согреты звуками скрипки и семейным уютом!', 'Step into a cozy log cabin on the edge of the big woods, where chilly frontier evenings are warmed by fiddle tunes and family love!', 'Zavirite u brvnaru na ivici velike šume, gdje hladne pionirske večeri griju zvuci violine i porodična ljubav!', '/covers/DP-0046.webp', '#8b5a2b', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["real","adventure","friends"]', '["frontier","family","nature","history","pioneers"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('анастасия-строкина-47', 'DP-0047', 'Анастасия Строкина', 'Anastasia Strokina', 'Anastasija Strokina', 'КомпасГид', 'KompasGid', 'KompasGid', '', 'КомпасГид', 2015, '978-5-00083-141-0', 7, 10, 'middle', '', 'A poetic and atmospheric northern journey blending gentle philosophy, mythical folklore, and wondrous creatures. Filled with evocative storytelling, it invites young readers on an unforgettable expedition across snowy landscapes and endless ocean waves in search of their true calling.', 'Poetično i atmosferično putovanje kroz sjeverne predjele koje spaja tihu mudrost, drevne legende i čarobna bića. Ova topla priča vodi mlade čitaoce kroz sniježne predjele i beskrajna mora u potrazi za sopstvenim mjestom pod zvijezdama.', 'Поэтичная и мудрая сказка с северным ветром в парусах, которая согреет сердце каждого мечтателя!', 'A poetic, windswept northern tale that will instantly warm the heart of every little dreamer!', 'Poetična i topla priča nošena sjevernim vjetrom koja će ugrijati srce svakog malog sanjara!', '/covers/DP-0047.webp', '#2c5d73', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["magic","adventure","animals"]', '["northern tales","journey","folklore","magic","friendship"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гипс-48', 'DP-0048', 'Гипс', 'Plaster', 'Gips', 'Анна Вольтц', 'Anna Woltz', 'Ana Volc', '', '', NULL, NULL, 7, 10, 'middle', 'Один день, горы снега и немного крови. Родители Фитц только что развелись, и больше всего она хочет исчезнуть. С младшей сестрёнкой происходит несчастный случай, а Фитц удаётся украсть в больнице гипс, повстречать загадочного Адама и подружиться с Примулой. Пока Фитц придумывает, как помочь одной влюблённой медсестре… она сама случайно влюбляется. Потому что если кто-то и готов всю жизнь прождать в приёмной, то Фитц точно предпочитает взять всё в свои руки, пусть и загипсованные. Сегодня книги Анны Вольтц переведены на 16 языков. Роман «Гипс» получил в Голландии сразу две престижные премии: Золотой и Серебряный грифель. В 2018 году по книге снят мини-сериал. «Гипс» — это настоящий гипс, который Фитц крадет, чтобы притвориться, что она сломала руку, и в которой она зарывает обручальные кольца своих родителей. Фитц говорит, что вся её семья должна быть в гипсе, потому что все они сломлены от развода ее родителей. Гипс — это история о том, как восстанавливать сломанное, и что некоторые вещи восстановить нельзя.', 'One snowy day, a little blood, and completely shattered family plans. Fitz''s parents have just divorced, and all she wants is to vanish. But when her younger sister has an accident and ends up in the hospital, Fitz''s wild day begins: stealing real plaster to fake a broken arm, burying her parents'' wedding rings inside it, befriending the intriguing Adam and brave Primula, and even meddling in a nurse''s love life. Deeply touching and laugh-out-loud funny, this award-winning Dutch novel reveals how healing a broken heart is a lot like setting a bone.', 'Jedan snježni dan, malo krvi i potpuno polomljeni porodični planovi. Ficine roditelje je zadesio razvod, i ona najviše želi da nestane. Ali kada njena mlađa sestra završi u bolnici nakon nezgode, Fica započinje sopstvenu avanturu: krade pravi gips kako bi se pretvarala da ima prelom, u njega zakopava vjenčano prstenje svojih roditelja, upoznaje tajanstvenog Adama i hrabru Primulu. Ova dirljiva i duhovita priča pokazuje kako se liječe slomljena srca i šta zaista znači popraviti ono što je slomljeno.', 'Трогательная и удивительно живая история о том, что разбитые сердца иногда тоже нуждаются в надёжном гипсе — и верных друзьях рядом.', 'A fiercely funny, honest, and tender hospital escapade proving that broken hearts, just like broken bones, can heal in the most unexpected ways.', 'Nevjerovatno topla i iskrena bolnička avantura koja podsjeća da i slomljenim srcima ponekad treba gips — i pravi prijatelji.', '/covers/DP-0048.webp', '#4a8b99', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["real","friends","funny"]', '["divorce","family","hospital","friendship","growing up"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ламп-шка-49', 'DP-0049', 'Лампёшка', 'Lampie', 'Lampica', 'Аннет Схап', 'Annet Schaap', 'Anet Shap', '', '', NULL, NULL, 7, 10, 'middle', 'Эта история — о море. О таинственных морских созданиях и свирепых пиратах. О Чёрном доме, в котором, по слухам, живёт чудовище. О маяке — высокой серой башне, что стоит на маленьком полуострове. О мечтательнице Эмилии, по прозвищу Лампёшка, дочери смотрителя маяка, которая каждый день взбирается по крутой винтовой лестнице, чтобы зажечь огонь. Об одном злополучном вечере, с которого всё и начинается, когда на море бушует шторм, а у Лампёшки, как назло, закончились спички… Романтичная, сказочная, порой страшная, но очень добрая история стала писательским дебютом известной голландской художницы Аннет Схап. Она покорила сердца читателей и критиков и в 2018 году была удостоена высшей награды Нидерландов в области детской литературы — премии «Золотой грифель». Книга в Нидерландах стала очень востребованной — уже вышла её аудиоверсия, осенью 2019 года ожидается спектакль в Роттердаме, заявлены и съемки подросткового сериала. Права на издание проданы в несколько европейских стран.', 'A captivating maritime fairy tale about the sea, fierce pirates, and the ominous Black House where a monster is rumored to live. Lampie, the lighthouse keeper''s brave daughter, must climb the spiraling stairs every evening to light the lantern. But on one fateful, stormy night, the matches run out, setting off a breathtaking adventure full of dark secrets, unlikely friendships, and ocean magic.', 'Uzbudljiva i dirljiva bajka o moru, gusarima i zlokobnoj Crnoj kući u kojoj navodno živi čudovište. Lampica, kćerka svetioničara, svake večeri se penje uz uske stepenice da upali svjetlo. Ali jedne olujne noći šibice nestaju, pokrećući nezaboravnu pustolovinu o hrabrosti, tajnama morskih dubina i snazi pravog prijateljstva.', 'Приготовьтесь к солёным брызгам, штормовому ветру и тайне Чёрного дома — эта невероятно атмосферная сказка согреет сердце в любой ненастный день!', 'Grab your raincoat and get ready for salty sea winds, mysterious monsters, and a fearless girl who proves love is brighter than any lighthouse.', 'Spremite se za miris morske oluje i tajnu Crne kuće — ova topla i čarobna priča ugrijaće vas i u najhladnijim večerima!', '/covers/DP-0049.webp', '#1a4b5c', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["adventure","magic","spooky"]', '["lighthouse","sea","mermaids","friendship","bravery"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лучший-подарок-50', 'DP-0050', 'Лучший подарок', 'Dani''s Best Present', 'Najbolji poklon', 'Русе Лагеркранц', 'Rose Lagercrantz', 'Rose Lagercrantz', '', 'Компасгид', NULL, NULL, 7, 10, 'middle', 'Дюнне и не заметила, как пролетели полгода её второго класса: в школе так интересно, особенно на уроках рисования и чтения! Да ещё и мальчик Кюдде мечтает сидеть с Дюнне за одной партой - но нет, это место должно быть пустым: вдруг Элла-Фрида вернётся в Стокгольм. Разлука с лучшей подругой - единственное, что делает маленькую счастливую девочку немного грустной. Но зимние каникулы запомнятся героине надолго: она наберётся смелости - и сама, без взрослых, поедет к Элле-Фриде на день рождения! Русе Лагеркранц (родилась в 1947 году) - наиболее признанная и известная детская писательница современной Швеции, лауреат премий им. Августа Стриндберга и им. Астрид Линдгрен. Серия "Дюнне и счастье" переведена на десятки языков, включена в список лучших детских книг The New York Times, номинирована на премию Сорсьер (Франция) и Немецкую детскую литературную премию. Не будет преувеличением сказать, что уже миллионы читателей от 6 до 8 лет всей душой полюбили очаровательную и немного наивную героиню - а вместе с ней полюбили и литературу. Книги Русе Лагеркранц отлично подходят для первого самостоятельного чтения: шрифт крупный, главки краткие, иллюстрации Эвы Эриксон поднимают настроение. "Лучший подарок" - шестая часть увлекательной истории. Для младшего школьного возраста. 3-е издание, стереотипное.', 'Second grade is flying by, and Dani loves school, but an empty seat beside her is a constant reminder of how much she misses her best friend, Ella-Frida. When winter break arrives, Dani makes a daring decision: she will gather all her courage and take the train all by herself to surprise Ella-Frida for her birthday. A tender, heartwarming chapter book about friendship, independence, and growing up.', 'Prvo polugodište drugog razreda prošlo je za tren, ali jedno prazno mjesto u klupi stalno podsjeća Djunje na njenu najbolju drugaricu Elu-Fridu. Kad stignu zimski praznici, Djunje skuplja hrabrost i odlučuje se na pravi podvig: sama će sjesti na voz i otputovati kod Ele-Fride na rođendan! Nježna i topla priča o pravom prijateljstvu i prvim samostalnim koracima.', 'Трогательная и смелая история о том, на какие удивительные путешествия готова второклассница ради объятий лучшей подруги.', 'A warm and brave story about just how far a determined second-grader will travel for a hug from her best friend.', 'Dirljiva i hrabra priča o tome na kakve je sve avanture spremna jedna djevojčica da bi zagrlila najbolju drugaricu.', '/covers/DP-0050.webp', '#5b92a5', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["friends","real","adventure"]', '["friendship","school","journey","independence","feelings"]', 1792836322694, 1792845651023);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('элла-в-лапландии-51', 'DP-0051', 'Элла в Лапландии', 'Ella in Lapland', 'Ela u Laponiji', 'Тимо Парвела', 'Timo Parvela', 'Timo Parvela', '', 'Розовый жираф', NULL, NULL, 7, 10, 'middle', 'В третьей книжке Элла и весь её второй класс отправляются вместе с учителем на каникулы к морю. Только вот учитель снова что-то перепутал, и вместо тёплых стран вся компания оказывается в Лапландии! А там, если вы не знали, живут финский Дед Мороз - точнее, Рождественский Козёл - и гномы, которые помогают ему мастерить подарки. Элла и её одноклассники убеждены, что теперь им предстоит стать рождественскими гномами, а учителю - Козломорозом! Для младшего школьного возраста.', 'In this delightful third adventure, Ella and her second-grade classmates set off for a sunny seaside holiday with their teacher. But as usual, teacher mixes up the tickets, and the whole crew lands in freezing Lapland! Surrounded by snowdrifts, Ella and the kids become thoroughly convinced that their teacher is actually Santa Claus and that they''ve been drafted as his hardworking elves.', 'U trećoj knjizi serijala, Ela i njen drugi razred kreću sa učiteljem na ljetovanje na more. Međutim, učitelj je ponovo nešto pobrkao, pa umjesto na plažu, čitavo društvo stiže u zavejanu Laponiju! Djeca su čvrsto ubijeđena da im je suđeno da postanu božićni vilenjaci, a da je njihov zbunjeni učitelj zapravo sam finski Deda Mraz.', 'Думали, едете купаться на море, а очутились в сугробах у финского Деда Мороза? С классом неугомонной Эллы любые каникулы гарантированно доведут до хохота!', 'Packed your swimsuits for the beach only to land in arctic snowdrifts? With Ella''s class, any holiday turns into a whirlwind of pure comic chaos!', 'Spakovali ste kupaće za more, a završili u snijegu kod Deda Mraza? Sa Elinim razredom svaki raspust donosi lavinu smijeha!', '/covers/DP-0051.webp', '#387896', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["funny","adventure","friends"]', '["school","winter","holidays","humor","travel"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('элла-и-рок-звезда-52', 'DP-0052', 'Элла и рок-звезда', 'Ella and the Rock Star', 'Ela i rok zvijezda', 'Тимо Парвела', 'Timo Parvela', 'Timo Parvela', '', 'Розовый жираф', NULL, NULL, 7, 10, 'middle', 'Долгожданное продолжение приключений Эллы, ее школьных друзей и их прекрасного учителя! Элла, Пат, Тукка, Сампа и все-все-все совсем скоро должны перейти в третий класс. Вот только Пат не знает таблицу умножения и не собирается ее учить. И действительно, зачем ее учить, ведь Пат - рок-звезда, а рок-звездам совершенно не обязательно знать таблицу умножения. Но без знания таблицы умножения Пат не попадет в третий класс, а рок-звезда, которая на многие годы застряла во втором классе, - не очень-то завидное будущее. На помощь Пату приходит весь его дружный класс, который теперь превратился в настоящую рок-группу. На пути к спасению Пата друзьям предстоит получить алюминиевый, железный и комбинированный диски (вместо платинового), приобрести яхту для учителя (немного старую), сыграть настоящий концерт и разгадать, что случилось с исчезнувшей певицей Эльвирой, главным кумиром Пата. Рок-звездам, не зависимо от возраста, к прочтению обязательно! Для младшего школьного возраста.', 'Third grade is just around the corner, but Pate refuses to learn his multiplication tables—after all, why would a future rock star need math? To keep him from being held back, Ella and their whole class form a rock band. Ahead lies a wild journey filled with funny awards, an old yacht for their teacher, an unforgettable concert, and solving the mystery of missing pop idol Elvira.', 'Treći razred je na pragu, ali Pate odbija da uči tablicu množenja — jer zašto bi buduća rok zvijezda morala da zna matematiku? Da ne bi ponavljao razred, Ela i cijelo odjeljenje pretvaraju se u pravi rok bend. Čekaju ih neobične muzičke nagrade, stara jahta za učitelja, nezaboravan koncert i rješavanje misterije nestanka slavne pjevačice Elvire.', 'Кто сказал, что рок-звёздам не нужна математика — особенно когда на кону переход в третий класс и спасение лучшего друга?', 'Who says rock stars don''t need math—especially when passing to the third grade requires a full classroom rock band to pull it off?', 'Ko kaže da rok zvijezdama ne treba matematika — posebno kad cijelo odjeljenje mora da zasvira da bi spasilo druga od ponavljanja razreda?', '/covers/DP-0052.webp', '#c8385a', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["funny","friends","adventure"]', '["school","rock music","humor","friendship","teamwork"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('манюня-юбилей-ба-53', 'DP-0053', 'Манюня, юбилей Ба', 'Manyunya: Ba''s Jubilee', 'Manjunja: Bain jubilej', 'Наринэ Абгарян', 'Narine Abgaryan', 'Narine Abgarjan', '', 'АСТ', NULL, NULL, 7, 10, 'middle', 'Вы держите в руках новую (и, по словам автора, точно последнюю) книгу о приключениях Манюни, Нарки и прочих замечательных жителей маленького городка Берд. Спешите видеть! И читать. "Любая история имеет свое начало и свой конец. Перед вами - третья, заключительная книга о девочке Манюне и прочих ее друзьях-родственниках. Это большое счастье, когда история одной семьи находит отклик в сердцах стольких людей. Мы хотим поблагодарить вас за то, что вы были с нами. Спасибо за ваши улыбки и распахнутые сердца. Мы этого не забудем никогда". Герои "Манюни". Для среднего школьного возраста.', 'The grand finale to the beloved adventures of Manyunya, Narka, and the lively town of Berd! Between epic preparations for formidable Ba’s milestone celebration, mischievous schemes, and mountain-sized laughs, this warm family chronicle bids a joyful, heartfelt farewell to childhood.', 'Veliko finale omiljenih avantura Manjunje, Narke i stanovnika živopisnog gradića Berda! Dok teku urnebesne pripreme za veliku proslavu stroge, ali voljene Ba, djevojčice upadaju u nove komične nezgode. Topla, bučna i nezaboravna priča o djetinjstvu koja grije srce.', 'Запасайтесь платочками — вы будете безудержно хохотать от проделок неугомонных девчонок и растроганно улыбаться на грандиозном празднике Ба!', 'Get ready to laugh until your cheeks hurt at the girls'' unstoppable antics and celebrate the grandest grandmother in the world!', 'Spremite se za gromoglasan smijeh uz najnovije nestašluke neumornih djevojčica i najtopliju porodičnu feštu!', '/covers/DP-0053.webp', '#e26a2c', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["funny","friends","real"]', '["family","humor","friendship","childhood","mischief"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-исто-54', 'DP-0054', 'Большая маленькая девочка. История первая. Как приручить город', 'The Big Little Girl. Story One: How to Tame a City', 'Velika mala djevojčica. Prva priča: Kako pripitomiti grad', 'Мария Бершадская', 'Maria Bershadskaya', 'Marija Beršadska', 'Саша Ивойлова', 'Компасгид', NULL, NULL, 7, 10, 'middle', 'Женя - большая маленькая девочка. С одной стороны, она младше всех, даже своей любимой таксы Ветки, а с другой - чтобы заплести ей косички, маме каждое утро приходится вставать на табуретку. Вообще Женя точно такая же, как все другие семилетние девочки. Она терпеть не может, когда её разглядывают или считают какой-то особенной. Она умеет чистить картошку так, чтобы шкурка превращалась в тонкие длинные ленточки. Умеет пришивать пуговицы - почти так же красиво, как папа. А ещё у неё отлично получается рассказывать разные истории - потому что с ней всё время случается что-нибудь интересное… Недавно, например, вся семья переехала в другой город. Среди незнакомых улиц и лиц легко потеряться даже такой большой маленькой девочке. Кто-нибудь знает, как приручаются города? Может быть, для этого нужно соорудить находчивое дерево, выбраться на улицу в самый унылый и дождливый день и встретить Мишку-горошка?.. Кроме необычной героини, всё в серии книжек Марии Бершадской о большой маленькой девочке совершенно обыкновенное. Здесь не бродят драконы, рыцари и принцессы. Зато есть двор, школа за углом, магазинчики, старый парк с колесом обозрения. Но ведь и самые привычные, самые обыденные вещи могут оказаться поэтичными, смешными, абсурдными и непохожими на что-то ещё, правда?', 'Zhenya is a big little girl. She is the youngest in her family—even younger than her beloved dachshund Vetka—yet her mom has to stand on a stool every morning just to braid her hair. In every other way, Zhenya is an ordinary seven-year-old who hates being stared at and loves peeling potatoes into ribbon-thin spirals. When her family moves to a brand-new town, Zhenya faces a real challenge: how do you tame an unfamiliar city and make it feel like home?', 'Ženja je velika mala djevojčica. Ona je najmlađa u porodici — mlađa čak i od svoje jazavičarke Vetke — ali mama svako jutro mora da se popne na stolicu kako bi joj splela pletenice. U svemu drugom Ženja je obična sedmogodišnjakinja koja ne podnosi kad u nju zure i odlično prišiva dugmad. Nakon preseljenja u novi grad, Ženja se suočava sa pravim izazovom: kako pripitomiti nepoznate ulice i pronaći nove prijatelje?', 'Трогательная и очень жизненная история о том, каково это — расти быстрее всех, и как научиться любить новый город.', 'A tender, heartwarming tale about standing tall, growing up, and the gentle art of making a strange new city feel like home.', 'Dirljiva i topla priča o odrastanju, prihvatanju sopstvene posebnosti i pronalaženju pravih prijatelja u novom gradu.', '/covers/DP-0054.webp', '#e89234', '7-9', 'ru', 'available', 'младший школьный', '["real","friends","funny"]', '["moving","friendship","growing up","city life","family"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-ист--55', 'DP-0055', 'Большая маленькая девочка. Ист 2. Рецепт волшебного дня', 'The Big Little Girl: The Recipe for a Magical Day', 'Velika mala djevojčica: Recept za čaroban dan', 'Бершадская Мария |', 'Maria Bershadskaya', 'Marija Beršadska', '', 'Компасгид', NULL, NULL, 7, 10, 'middle', 'Женя - большая маленькая девочка. С одной стороны, в семье она младше всех, даже своей любимой таксы Ветки, а с другой - чтобы заплести ей косички, маме каждое утро приходится вставать на табуретку. Вообще Женя точно такая же, как все другие семилетние девочки. Она терпеть не может, когда её разглядывают или считают какой-то особенной. Она умеет чистить картошку так, чтобы шкурка превращалась в тонкие длинные ленточки. Умеет пришивать пуговицы - почти так же красиво, как папа. А ещё у неё отлично получается рассказывать разные истории - потому что с ней всё время случается что-нибудь интересное… Вот, например, недавно Женя решила сделать папе подарок на день рождения. Но ей очень хотелось подарить что-нибудь настоящее. А пирог с яблоками - замечательный подарок. Гораздо лучше пластилинового ежа. И если друзья говорят, что испечь пирог проще простого - значит, так оно и есть. Надо только знать рецепт: яблоки, мука, четыре яйца, сахар и... Но об этом вы узнаете, когда прочитаете "Рецепт волшебного дня" - вторую книгу серии о БОЛЬШОЙ МАЛЕНЬКОЙ ДЕВОЧКЕ.', 'Zhenya is a big little girl. She is the youngest in her family, yet her mom has to stand on a stool just to braid her hair! Otherwise, Zhenya is just like any seven-year-old: she can peel potatoes in long ribbons, sew on buttons, and tell great stories. For her dad''s birthday, she decides to bake a real apple pie instead of making another clay hedgehog. Baking should be a piece of cake when friends help out, right? All you need are apples, flour, eggs, sugar... and a pinch of everyday magic.', 'Ženja je velika mala djevojčica. Najmlađa je u svojoj porodici, a ipak mama mora da se popne na stolicu da bi joj splela pletenice! Inače, Ženja je sasvim obična sedmogodišnjakinja: ljušti krompir u dugim trakama, prišiva dugmad i priča sjajne priče. Za tatin rođendan odlučila je da ispeče pravu pitu s jabukama — mnogo bolji poklon od ježa od plastelina. A kad prijatelji pomognu, pečenje pite je prava sitnica... ili možda ipak prava avantura?', 'Уютная и смешная история о том, как испечь папе лучший в мире пирог и понять, что настоящая магия скрывается в простых вещах и верных друзьях.', 'A cozy and humorous tale about baking the ultimate birthday pie and discovering that true magic comes from good friends and a warm heart.', 'Topla i duhovita priča o tome kako ispeći najbolju pitu za tatin rođendan i otkriti da se prava čarolija krije u prijateljstvu i zajedništvu.', '/covers/DP-0055.webp', '#76a347', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["real","friends","funny"]', '["growing up","baking","family","birthday","friendship"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-исто-56', 'DP-0056', 'Большая маленькая девочка. История третья. Вышел зайчик погулять…', 'Big Little Girl. Story Three: A Bunny Went for a Walk…', 'Velika mala djevojčica. Treća priča: Izašao zeko u šetnju…', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'однажды Женя увидела объявление: чтобы выиграть "потрясающий приз-сюрприз", надо сделать костюм для своего питомца. Но кто сказал, что сшить костюм зайца и засунуть в него таксу просто?! А если на пути к призу вас ждет еще и настоящий бег с препятствиями: нервные старушки, перепуганная невеста, летний снег и даже злодей с пистолетом?! Тут помогут только "морковка с секретом" и быстрые ноги!', 'One day, Zhenya spots a contest: make a costume for your pet to win an incredible surprise prize! But whoever said that stitching a bunny costume and coaxing a stubborn dachshund into it was simple? Especially when the road to victory turns into a wild obstacle course complete with startled grannies, a panicked bride, summer snow, and a villain with a gun. Only quick feet and a very clever secret carrot can save the day!', 'Jednog dana Ženja je vidjela oglas: da biste osvojili nevjerovatnu nagradu iznenađenja, morate napraviti kostim za svog ljubimca. Ali ko kaže da je lako sašiti odijelo zeca i u njega ugurati tvrdoglavog jazavičara?! Pogotovo kad se put do nagrade pretvori u pravu trku s preponama: nervozne bake, prestravljena mlada, ljetnji snijeg, pa čak i zlikovac s pištoljem! Spasiti stvar mogu samo brze noge i šargarepa s tajnom.', 'Попробуйте нарядить таксу в зайца, не потеряв чувство юмора, — Женя докажет, что смекалка творит чудеса!', 'Try dressing up a dachshund as a bunny without losing your cool — Zhenya proves that wild adventures take true grit!', 'Probajte da obučete jazavičara u kostim zeke a da ne puknete od smijeha — Ženja dokazuje da snalažljivost pobjeđuje sve!', '/covers/DP-0056.webp', '#e26a2c', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["funny","adventure","animals"]', '["dachshund","dogs","costumes","humor","friendship"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-ист--57', 'DP-0057', 'Большая маленькая девочка. Ист 4. Семь с половиной крокодильских улыбок', 'Big Little Girl. Story 4: Seven and a Half Crocodile Smiles', 'Velika mala djevojčica. Priča 4: Sedam i po krokodilskih osmijeha', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В четвёртой книге "Семь с половиной крокодильских улыбок" Женя наконец идёт в первый класс. Она давно мечтала о том, как наденет большой красивый бант, познакомится с весёлой учительницей и быстро подружится с соседкой по парте… Только вот почему-то всё сразу не заладилось. Накануне Женю отвели к стоматологу, и она лишилась всех своих крокодильских улыбок. А первого сентября обнаружила, что ей не только парта, но и вся школа МАЛА. Как же теперь быть? Может, лучший друг Мишка, как всегда, что-нибудь придумает?..', 'In the fourth book, Zhenya finally heads off to first grade. She had dreamed of wearing a lovely big bow, meeting a cheerful teacher, and making friends with her deskmate. But things get off to a bumpy start: a visit to the dentist robs her of her broad crocodile grin, and on the first day of school, she discovers that not just her desk, but the entire building is far too small for her! Luckily, her best friend Mishka is always ready with a clever idea.', 'U četvrtoj knjizi Ženja konačno kreće u prvi razred. Dugo je maštala o tome kako će staviti veliku mašnu, upoznati veselu učiteljicu i brzo pronaći drugaricu iz klupe... Ali ništa ne ide po planu: poslije zubara ostala je bez svojih krokodilskih osmijeha, a prvog septembra shvata da su joj i klupa i cijela škola premale. Kako se snaći? Možda će njen najbolji drug Miška ponovo smisliti spas!', 'Трогательная и уморительная история о том, как пережить первый класс, даже если ты выше всех на две головы и только что от зубного!', 'A witty and heartwarming tale about surviving the first day of school when you are taller than everyone else and fresh from the dentist!', 'Duhovita i topla priča o polasku u prvi razred kad si za dvije glave viši od svih i još se oporavljaš od zubara!', '/covers/DP-0057.webp', '#489f85', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["funny","friends","real"]', '["school","friendship","growing up","first grade","humor"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-ист--58', 'DP-0058', 'Большая маленькая девочка. Ист 5. Сто один способ заблудиться в лесу', 'Big Little Girl. Story 5: 101 Ways to Get Lost in the Woods', 'Velika mala djevojčica. Priča 5: Sto jedan način da se izgubite u šumi', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В пятой книге СТО ОДИН СПОСОБ ЗАБЛУДИТЬСЯ В ЛЕСУ Женя гостит в настоящей деревне - это Мишка позвал ее к себе, там живет его дедушка. Друзья сразу находят себе занятие: они пойдут за грибами! Одна беда - в лесу очень легко потеряться! Что же делать, если кругом ни души? И даже Ветка не знает, куда бежать? На всякий пожарный Мишка взял с собой книгу "101 способ выжить в лесу", шерстяные носки и целых два бутерброда, так что они, конечно, не пропадут… Но дорогу-то все равно искать надо! Вся надежда на Спасательный мотоцикл и Путеводную козу…', 'In the fifth book of the series, Zhenya visits a real village where Mishka''s grandfather lives. The friends embark on a mushroom-hunting adventure, but getting lost in the forest turns out to be surprisingly easy! Luckily, Mishka packed a survival manual, warm socks, and two sandwiches. Still, finding the way back will require the help of a very special rescue motorcycle and a guiding goat!', 'U petoj knjizi, Ženja odlazi u pravo selo kod Miškinog dede. Prijatelji odmah kreću u berbu pečuraka, ali u šumi se tako lako izgubiti! Srećom, Miška je poneo priručnik za preživljavanje, vunene čarape i dva sendviča. Ipak, put do kuće moraće da pronađu uz pomoć spasilačkog motocikla i jedne neobične koze vodiča!', 'Запасайтесь бутербродами и хорошим настроением — с Женей и Мишкой даже заблудиться в лесу превращается в самое весёлое приключение!', 'Pack some sandwiches and good humor — with Zhenya and Mishka, getting lost in the woods turns into the coziest, funniest adventure!', 'Ponesite sendviče i osmijeh — sa Ženjom i Miškom čak i gubljenje u šumi postaje najveselija seoska avantura!', '/covers/DP-0058.webp', '#4a7c59', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["adventure","friends","funny"]', '["forest","friendship","village","adventures","humor"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-исто-59', 'DP-0059', 'Большая маленькая девочка. История шестая. Тыквандо', 'Big Little Girl. Story Six: Pumpkwondo', 'Velika mala djevojčica. Šesta priča: Bundevando', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В шестой книге "Тыквандо" Женю и её друзей поджидает… весёлый Хэллоуин. А точнее, целых два конкурса - "Тыква года", а ещё "Самый Ужасный Костюм". Теперь надо срочно раздобыть тыкву! И Мишка знает где - дома у своей тёти. Только есть проблема: эту неподъёмную тыкву надо доставить в школу целой и невредимой! Конечно, тут поможет Тыквоперевозочное средство, но всё не так просто, как кажется… А ещё Женя не хочет придумывать себе костюм. Точнее, она уже всё придумала. Жене хочется побыть самой обычной, неудивительной девочкой. Как думаете, у неё получится?', 'In the sixth book, "Pumpkwondo", Zhenya and her friends are gearing up for Halloween—featuring two big school contests: "Pumpkin of the Year" and "The Most Horrible Costume". Mishka tracks down an enormous pumpkin at his aunt''s place, but transporting this giant veggie intact to school takes real ingenuity. Meanwhile, unusually tall Zhenya decides not to wear an extravagant outfit: she simply wants to dress up as an ordinary, unremarkable girl. Will she pull it off?', 'U šestoj knjizi, „Bundevando“, Ženju i njene prijatelje čeka vesela Noć vještica i dva školska takmičenja: „Bundeva godine“ i „Najstrašniji kostim“. Hitno im treba džinovska bundeva, a Miška zna gdje je može naći — kod svoje tetke. Jedini je problem kako tu tešku grdosiju dopremiti do škole čitavu i bezbjednu! Uz to, Ženja ne želi strašan kostim, već mašta o tome da makar jednom bude sasvim obična djevojčica.', 'Захватывающая тыквенная экспедиция и трогательная история о том, как непросто порой быть «самой обычной» девочкой!', 'A hilarious giant-pumpkin rescue mission and a heartwarming story about why sometimes the hardest thing is just being ordinary.', 'Urnebesna misija prevoza džinovske bundeve i topla priča o tome kako je ponekad najteže biti sasvim običan!', '/covers/DP-0059.webp', '#e06323', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["funny","friends","real"]', '["halloween","pumpkin","school","friendship","growing up"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-исто-60', 'DP-0060', 'Большая маленькая девочка. История 7. Грустный радостный праздник', 'Big Little Girl. Story 7: A Sad Happy Holiday', 'Velika mala djevojčica. Priča 7: Tužan radosni praznik', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В седьмой книге "Грустный радостный праздник" Жене и её другу Мишке предстоит ещё немного повзрослеть. На носу Новый год, а снега всё нет и нет, да ещё и Мишкин дедушка заболел... Лежит, грустит и никуда не выходит. Значит, Новый год отменяется? Но ведь это несправедливо, если дедушка останется без праздника. Женя и Мишка решают: они обязательно должны что-нибудь придумать и дедушку развеселить. Как насчёт Ёлочного абажура? А Десяти Мешочков для Радости и Удовольствия? Как думаете, у них получится?..', 'In the seventh book, "A Sad Happy Holiday," Zhenya and her friend Mishka have to grow up just a little bit more. New Year''s Eve is just around the corner, but there''s still no snow, and worse, Mishka''s grandfather has fallen ill... He lies in bed, feeling sad and unable to go out. Does this mean the holiday is canceled? Zhenya and Mishka decide that leaving Grandpa without a celebration is simply unfair. Together, they set out to invent ways to bring him cheer—like a pine-branch lampshade and Ten Pouches of Joy and Delight!', 'U sedmoj knjizi, „Tužan radosni praznik“, Ženja i njen drug Miška moraće još malo da odrastu. Nova godina samo što nije, a snijega još nema, pa nema, a povrh svega se Miškin djed razbolio... Leži, tuguje i nigdje ne izlazi. Znači li to da se Nova godina otkazuje? Ali nije pošteno da djed ostane bez slavlja! Ženja i Miška odlučuju da pod svaku cijenu vrate osmijeh na djedovo lice uz pomoć novogodišnjeg abažura i Deset vrećica radosti.', 'Тёплая и душевная зимняя история о том, как детская забота способна подарить настоящее новогоднее чудо даже без снега за окном!', 'A warm, heartwarming winter tale proving that a little empathy and imagination can create true holiday magic even without snow!', 'Topla i dirljiva zimska priča o tome kako dječja pažnja i mašta mogu stvoriti pravo praznično čudo čak i bez snijega!', '/covers/DP-0060.webp', '#3b6e68', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["friends","real"]', '["holidays","winter","kindness","family","growing up"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-ист--61', 'DP-0061', 'Большая маленькая девочка. Ист 8. Дело о клетчатой сумке', 'Big Little Girl. Story 8: The Mystery of the Plaid Bag', 'Velika mala djevojčica. Priča 8: Slučaj karirane torbe', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В восьмой книге «Дело о клетчатой сумке» Женин лучший друг Мишка находит на улице собаку. Но не простую, а очень-очень грустную и одинокую. Она лежит на снегу с клетчатой сумкой и никого к себе не подпускает. Откуда она взялась? И кого так долго ждёт? Женя, Мишка и другие ребята решают стать настоящими детективами и выяснить, кому же принадлежит клетчатая сумка и что вообще тут стряслось. Им предстоит освоить метод дедукции, провести операцию «Кошмарный День», а ещё — узнать, что порой, даже если вроде всё делаешь правильно, потом почему-то бывает очень неловко…', 'In the eighth story, Zhenya''s best friend Mishka finds a stray dog sitting in the snow beside a plaid bag, refusing to let anyone near. Who is this dog waiting for, and where did the bag come from? The kids turn into real detectives to solve the mystery, trying out deduction, launching Operation ''Nightmare Day,'' and discovering that sometimes doing the right thing can still feel wonderfully awkward.', 'U osmoj priči, Ženjin najbolji drug Miška pronalazi psa na snijegu pored karirane torbe, koji nikome ne da da mu priđe. Koga ovaj pas čeka i odakle se stvorio? Djeca postaju pravi detektivi kako bi riješila misteriju, isprobavajući dedukciju, pokrećući operaciju „Košmaran dan“ i učeći da ponekad, čak i kad radite pravu stvar, može biti pomalo neprijatno.', 'Трогательный зимний детектив о дружбе, верном псе и дедукции, от которого на душе становится по-настоящему тепло!', 'A touching winter detective tale about loyalty, a mysterious dog, and the sweet warmth of true friendship!', 'Dirljiva zimska detektivska priča o prijateljstvu, vjernom psu i toplini koja grije i po najvećem snijegu!', '/covers/DP-0061.webp', '#3b6e8c', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["adventure","friends","animals"]', '["detective","dogs","friendship","winter","mystery"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-исто-62', 'DP-0062', 'Большая маленькая девочка. История 9. Про любовь', 'Big Little Girl. Story 9: About Love', 'Velika mala djevojčica. Priča 9: O ljubavi', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В девятой книге "Про любовь" Жене предстоит много всего узнать и почувствовать. На носу День святого Валентина, и Женя, хотя и считает всю эту возню с валентинками сущей глупостью, почему-то всё равно боится: а вдруг ей никто валентинку не напишет? А ещё она очень боится за свою сестру Аньку. Анька встречается с Германом, но они вдруг поссорились, и вообще непонятно, как их теперь помирить. Впрочем, Соня, кажется, знает, как всё уладить. Но, оказывается, это не так-то просто… И это ещё не всё! Ведь у родителей Жени и Аньки есть для них очень важная и совершенно неожиданная новость…', 'In the ninth book, ''About Love'', Zhenya experiences a whole swirl of brand-new emotions. Valentine''s Day is just around the corner, and even though Zhenya claims the whole holiday is utter nonsense, she secretly worries: what if nobody sends her a valentine? To make matters more complicated, her older sister Anka has had a big fight with her boyfriend, and their parents have a sudden, game-changing surprise in store for the whole family.', 'U devetoj knjizi ''O ljubavi'', Ženja doživljava vrtlog potpuno novih osjećanja. Dan zaljubljenih je pred vratima, i iako Ženja tvrdi da su sve te čestitke potpuna besmislica, potajno brine: šta ako niko njoj ne pošalje valentinovo? Uz to, njena starija sestra Anka se posvađala sa momkom, a roditelji pripremaju veliku i neočekivanu vijest za cijelu porodicu.', 'Трогательная и очень искренняя история о первых сердечных тайнах, переживаниях за близких и о том, что любовь бывает совершенно разной.', 'A tender and wonderfully honest story about first fluttery crushes, family worries, and discovering how many different shapes love can take.', 'Dirljiva i iskrena priča o prvim simpatijama, brizi za stariju sestru i tome kako ljubav dolazi u najrazličitijim oblicima.', '/covers/DP-0062.webp', '#d65a6f', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["friends","real"]', '["growing up","first love","family","feelings","sisters"]', 1792836322694, 1792845656350);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-исто-63', 'DP-0063', 'Большая маленькая девочка. История 10. Пушкин и компания.', 'The Big Little Girl. Story 10: Pushkin and Company', 'Velika mala djevojčica. Priča 10: Puškin i društvo', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В десятой книге "Пушкин и компания" Женя и её друзья узнают много нового о… Пушкине! Да-да, о том самом, об Александре Сергеевиче. "Сколько можно про Пушкина, про него ведь всё давно известно!" — скажете вы. А вот и нет! И Соня, правнучка пушкиниста, знает о нём то, что неизвестно практически никому. Вот вы, например, знали, что во времена Пушкина были не лайки, как в "Фейсбуке", а лайковые перчатки? А что Пушкин, когда у него пропадало вдохновение, шёл на кухню и готовил майонез? А что он грязное окно носком протирал, чтобы разглядеть природу? Вот именно, не знали! А Соня знает про Пушкина ВСЁ. Как-то раз она даже решила в "Узника" поиграть. Взяла старый велосипедный замок, пристегнула себя к окну, набрала шифр… А потом его забыла! И как теперь быть? Ведь Соне срочно нужно сделать семь добрых дел для мамы и написать об этом целое сочинение. Как же открыть замок? Хорошо, что у Сони есть друзья! Жене и Мишке предстоит разгадать шифр, который, конечно, тоже про Пушкина — заветные три цифры из его жизни…', 'In the tenth book, Zhenya and her friends discover mind-boggling facts about Alexander Pushkin! Sonya, the great-granddaughter of a Pushkin scholar, knows quirky trivia that hardly anyone else does—like how Pushkin supposedly whipped up mayonnaise when his muse ran dry or wiped windows with a sock. But when Sonya locks herself to a window frame with a bicycle lock while playing ''The Prisoner'' and forgets the code, Zhenya and Mishka have to crack a Pushkin-themed secret cipher to set her free before dinner!', 'U desetoj knjizi, Ženja i njeni prijatelji saznaju nevjerovatne stvari o čuvenom pjesniku Puškinu! Sonja, praunuka uglednog puškiniste, zna tajne koje malo ko poznaje. Međutim, igrajući se ''Zatvorenika'', Sonja se starom biciklističkom bravom veže za prozor i — zaboravi šifru! Kako bi je oslobodili na vrijeme da završi domaći zadatak, Ženja i Miška moraju da odgonetnu tajni kod povezan s neobičnim detaljima iz Puškinovog života.', 'Кто бы мог подумать, что Пушкин поможет взломать велосипедный замок и спасёт отчаянную компанию от курьёзного плена!', 'Who knew that historical trivia about a classic poet could crack a bicycle lock and rescue a best friend?', 'Ko bi rekao da poznavanje Puškinovih tajni može pomoći da se otključa zarđali katanac i spasi najbolja drugarica!', '/covers/DP-0063.webp', '#d96543', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["funny","friends","real"]', '["growing up","friendship","school life","humor","riddles"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-маленькая-девочка-исто-64', 'DP-0064', 'Большая маленькая девочка. История 11. Джинсы в горошек', 'Big Little Girl. Story 11: Polka-Dot Jeans', 'Velika mala djevojčica. Priča 11: Farmerke na tufne', '', 'Maria Bershadskaya', 'Marija Beršadska', '', '', NULL, NULL, 7, 10, 'middle', 'В одиннадцатой книге "Джинсы в горошек" Женя и Мишка собрались прокатиться на новых аттракционах, которые открылись в другом городе. Женин папа всё равно едет туда на конференцию, так что возьмёт их с собой - Мишка его очень об этом просил. Только, кажется, Мишка что-то скрывает, и никакое колесо обозрения ему не нужно… А нужно увидеть… папу! И поздравить его с днём рождения. Отличная идея, но почему Мишка не сразу обо всём рассказал? И зачем его папе в день рождения банки с зелёным горошком? И откуда их взять, если денег не хватает? Мишка, конечно, всегда что-нибудь придумает, а у Жени есть секрет, который приносит удачу, вот только в незнакомом городе с ними запросто может случиться что-нибудь неожиданное…', 'In the eleventh story, Zhenya and Mishka set off to a neighboring city ostensibly to try out the brand-new amusement rides while Zhenya''s dad attends a conference. But Mishka has a secret mission: he doesn''t really care about the Ferris wheel; he wants to surprise his dad for his birthday! Mishka has a quirky plan involving cans of green peas and luck-bringing polka-dot jeans, but navigating an unfamiliar city always comes with unexpected surprises.', 'U jedanaestoj priči, Ženja i Miška odlaze u drugi grad navodno da isprobaju novi zabavni park dok je Ženjin tata na konferenciji. Ipak, Miška krije tajnu: uopšte ga ne zanima panoramski točak, već želi da iznenadi svog oca za rođendan! Njegov neobičan plan uključuje konzerve graška i srećne farmerke na tufne, ali u nepoznatom gradu avanture rijetko teku po planu.', 'Трогательная и добрая городская история о том, как ради папиной улыбки можно преодолеть любые расстояния (и даже раздобыть консервированный горошек)!', 'A heartwarming urban adventure proving that with a loyal friend and a lucky pair of jeans, no birthday surprise is impossible!', 'Dirljiva i topla priča koja pokazuje da su uz pravog prijatelja i srećne farmerke i najveća rođendanska iznenađenja moguća!', '/covers/DP-0064.webp', '#42678d', '7-9', 'ru', 'available', 'Категория: Большая Маленькая девочка', '["friends","adventure","real"]', '["friendship","family","fathers","travel","growing up"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рассказы-про-франца-65', 'DP-0065', 'Рассказы про Франца', 'Franz Stories', 'Priče o Francu', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', '"Рассказы про Франца" классика австрийской детской литературы Кристине Нёстлингер - дверь в мир шестилетнего ребенка. Взрослые давно забыли, как много тайн за ней скрыто. Этот мир полон своих переживаний, неуверенностей, настоящих побед и истинной преданности. Франц - прекрасный белокурый малыш, очень переживающий, что нестерпимо похож на девчонку. Его не успокаивает ничто: ни детские фотографии папы, ни тихие разговоры мамы. Ведь, как только он переступает порог собственной квартиры, другие мальчишки не упускают возможности, чтобы над ним подтрунить. У Франца есть старший брат Йозеф, ему двенадцать и, кажется, ему совершенно нет дела до проблем этого "клопа и балбеса". Так ли это на самом деле? Конечно же нет, за маской детского безразличия скрыта настоящая безграничная любовь. И теперь-то Франц это знает наверняка. Не верите? Вперёд к открытой книге. Рассказы про Франца - это идеальное чтение для тех, кто только начинает читать.', 'Christine Nöstlinger’s classic ''Franz Stories'' opens the door to the rich inner world of a six-year-old boy. Franz is a lovely blond kid who worries constantly about looking too much like a girl, especially when neighborhood boys tease him. His twelve-year-old brother Josef acts completely indifferent, yet underneath lies genuine sibling loyalty. Full of relatable everyday dilemmas, warm humor, and heart, this book is an ideal choice for children taking their first independent reading steps.', 'Klasik austrijske dječije književnosti Kristine Nestlinger, ''Priče o Francu'', otvara vrata u dirljivi svijet šestogodišnjaka. Franc je plavokosi dječak koji se silno brine jer isuviše liči na djevojčicu, zbog čega ga vršnjaci često zadirkuju. Njegov dvanaestogodišnji brat Jozef pretvara se da ga brige mlađeg brata uopšte ne zanimaju, ali iza te maske krije se prava bratska ljubav. Tople, duhovite i mudre, ove priče savršeno su štivo za djecu koja tek počinju samostalno da čitaju.', 'Идеальное лекарство от детских тревог: остроумные и невероятно душевные истории о кудрявом мальчике, который учится быть собой.', 'The perfect antidote to childhood worries: witty, heartwarming stories about a curly-haired boy learning to be proud of who he is.', 'Savršen lijek za dječije brige: tople i duhovite priče o plavokosom dječaku koji uči da prihvati sebe i izbori se za svoje mjesto u svijetu.', '/covers/DP-0065.webp', '#e59b32', '7-9', 'ru', 'available', 'Для младшего школьного возраста.', '["real","funny","friends"]', '["growing up","brothers","humor","early reader","family"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('новые-рассказы-про-франца-66', 'DP-0066', 'Новые рассказы про Франца', 'New Stories About Franz', 'Nove priče o Francu', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristin Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Казалось бы, что может происходить в жизни обычного мальчишки-дошкольника? Но оказывается, в ней полно событий! Вы, например, помните, как хотели научиться читать? Было трудно? А вот Франц освоил чтение очень быстро - только осталась одна ма-а-аленькая проблема… О ней вы узнаете, когда сами прочтёте историю. А ещё Франц впервые самостоятельно отправился в гости. Да не куда-нибудь, а к бабушке, которая живёт в доме престарелых. Конечно, уходить из дома без спроса нельзя, но ведь мама велела Францу больше не попадаться ей на глаза! Вот только что может получиться, когда приходишь в гости без предупреждения? Правильно, тебя никто не ждёт. Ну и ну! Что же Франц сделает?', 'You might think ordinary life is quiet, but for little Franz it''s packed with big adventures! Franz masters reading in no time—except for one tiiiny, hilarious problem. And when his mom tells him to get out of her sight, he takes it quite literally and sets off all by himself across town to visit his grandma in her retirement home. What could possibly go wrong when you show up completely unannounced?', 'Možda mislite da je svakodnevni život običnog dječaka miran, ali Francov je prepun uzbuđenja! Franc je naučio da čita nevjerovatno brzo — uz samo jedan ma-a-jušni problem. A kada mu mama ljutito kaže da joj se skloni s očiju, Franc to shvata doslovno i sam kreće u posjetu baki u starački dom. Šta sve može poći naopako kada banete u posjetu bez najave?', 'Добрый и уморительный Франц доказывает: даже самые крошечные неурядицы детства превращаются в грандиозные приключения!', 'Charming, pint-sized Franz is back to prove that even the smallest childhood dilemmas can spark the greatest everyday adventures!', 'Simpatični i iskreni Franc dokazuje da se i najmanje dječje muke mogu pretvoriti u nezaboravne avanture!', '/covers/DP-0066.webp', '#e76f51', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","real","friends"]', '["childhood","grandparents","humor","growing up","reading"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-каникулы-5-67', 'DP-0067', 'про Франца и каникулы 5', 'Franz on Holiday', 'Priče o Francu i raspustu', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'В этой книге классика детской австрийской литературы Кристине Нёстлингер вас ждёт новая порция рассказов про Франца, которому уже целых восемь лет. Как и все дети, Франц просто обожает каникулы, ведь на них можно делать всё что захочешь. Франц даже не знает, какие каникулы ему нравятся больше всего: зимние, летние, пасхальные или карнавальные (да, в Австрии есть даже такие). Летние каникулы самые длинные. Франц почти целый месяц проводит с родителями, а в остальное время за ним кто-нибудь приглядывает: то тётя Бетти, то бабушка, то няня Лилли… Но вдруг выяснилось, что в этот раз у всех неотложные дела и за Францем совсем некому присмотреть. Тогда мама предложила Францу поехать в детский лагерь. Почему бы и нет? Франц сначала согласился, а потом испугался: он ведь ещё ни разу не оставался совсем один, без мамы, папы и бабушки. Что ждёт Франца в лагере? Найдёт ли он себе новых друзей? А что будет, если устроить там забастовку? А если нарядиться привидением, чтобы кое-кому отомстить? "Рассказы про Франца и школу" - это идеальное чтение для тех, кто только начинает читать.', 'Eight-year-old Franz loves holidays, but this summer nobody is free to look after him, so his parents sign him up for summer camp. Franz is nervous—he has never been away from his family before! Will he find friends, how will a camp-wide strike unfold, and what happens when he dresses up as a ghost for revenge? A delightful, heartwarming story for beginner readers about courage and growing up.', 'Osmogodišnji Franc obožava raspust, ali ovog ljeta niko od odraslih nema vremena da ga čuva, pa mu mama predlaže odlazak u dječiji kamp. Franca hvata trema jer nikada ranije nije bio bez mame, tate i bake. Ipak, kamp donosi neočekivane avanture: sticanje novih prijatelja, štrajk u trpezariji i osvetu pod maskom duha! Divna i duhovita priča savršena za djecu koja tek počinju samostalno da čitaju.', 'Франц докажет: даже первая поездка в лагерь без мамы может превратиться в уморительное приключение с привидениями и забастовками!', 'Franz proves that your very first trip to summer camp can turn into a hilarious adventure packed with ghost pranks and newfound bravery!', 'Franc nam dokazuje da prvi odlazak u ljetnji kamp bez roditelja može postati urnebesna avantura puna smicalica i novih prijateljstava!', '/covers/DP-0067.webp', '#f39c12', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","friends","real"]', '["summer camp","holidays","friendship","growing up","humor"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-любовь-7-68', 'DP-0068', 'про Франца и любовь 7', 'Franz and Love', 'O Francu i ljubavi', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Францу восемь с половиной лет, и пока ему знакома только взаимная любовь: Франц любит папу, маму, бабушку и брата Йозефа, а те, конечно же, любят его. Но вот Йозеф безответно влюбляется в девочку, с которой едва знаком. Франц за Йозефа очень переживает и решает помочь брату завоевать её сердце. Но стоит ли вмешиваться в чужие отношения? Особенно когда толком не понимаешь, что творится в голове у мальчиков и девочек тринадцати лет. Да и к чему вмешиваться, если у самого дружба расклеилась? Габи, лучшая подружка Франца, теперь души не чает в Сандре, а его почти не замечает. Но если бы только это… Франц ведь и сам влюбился, да ещё в самую большую хулиганку. Как же со всем этим быть?', 'Franz is eight and a half, and until now, love only meant loving his family. But when his older brother Josef falls hopelessly in unrequited love, Franz decides to play Cupid—which proves tricky when you''re eight and have no idea how teenagers think. To make things more chaotic, his best friend Gabi is ignoring him, and Franz himself suddenly catches feelings for the school''s biggest troublemaker!', 'Franc ima osam i po godina i do sada je poznavao samo porodičnu ljubav: prema roditeljima, baki i bratu Jozefu. Ali kada se Jozef nesrećno zaljubi u djevojčicu koju jedva poznaje, Franc odlučuje da mu pomogne da osvoji njeno srce. Međutim, miješati se u tajne tinejdžera nije nimalo lako, posebno kad se i Francovo prijateljstvo sa Gabi klima, a on sam se zaljubljuje u najveću mangupicu u školi.', 'Остроумная и удивительно чуткая история о первых бабочках в животе, сердечных тайнах старших братьев и непростых испытаниях дружбы.', 'A genuinely warm and humorous look at first crushes, teenage heartaches seen through younger eyes, and the messy art of friendship.', 'Duhovita i topla priča o prvim leptirićima u stomaku, tinejdžerskim ljubavnim jadima i izazovima pravog prijateljstva.', '/covers/DP-0068.webp', '#d65b70', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","friends","real"]', '["first love","friendship","brothers","school life","humor"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-школу-3-69', 'DP-0069', 'про Франца и школу 3', 'Franz and School', 'Franc i škola', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Франц наконец-то идет в школу. Вот только учитель Францу не нравится: он разговаривает так, будто у него не дети в классе, а солдатики. Франц ему даже прозвище дал - Ать-два. Однажды, когда Франц сидит с бабушкой в кафе и жалуется ей на учителя, тот появляется рядом. А бабушку, раз уж она что решила, не остановишь. "Вы знаете, герр Ать-два…" - обращается она к учителю… И хотя Францу удается во время разговора отсидеться в кустах, в школу в понедельник ему все-таки придется пойти! Даже если от страха заболит живот. А ещё у Франца в классе есть враг. Эберхард Мост очень высокий и сильный и запросто может отобрать завтрак или придумать еще какую-нибудь гадость. А Франц самый маленький в классе и никак не может справиться с обидчиком. Но ведь у Франца есть Лилли, она присматривает за ним, пока мама на работе. Она уж точно придумает, как ему помочь.', 'Franz is finally going to school, but his teacher barks orders like a drill sergeant, earning the nickname ''Hup-Two''! When Franz''s unstoppable grandma unexpectedly confronts the teacher in a café, facing Monday morning becomes terrifying. To make matters worse, a tall class bully is stealing lunches. Luckily, Franz has his clever babysitter and friend Lilly, who always knows how to outsmart trouble.', 'Franc napokon kreće u školu, ali njegov strogi učitelj naređuje kao general, pa odmah dobija nadimak „Jedan-dva“! Kada Francova neustrašiva baka sasvim neočekivano priđe učitelju u kafiću, odlazak u školu u ponedjeljak pretvara se u pravu brigu. Uz to, visoki školski nasilnik krade užinu, ali Franc ima dovitljivu prijateljicu i dadilju Lili, koja uvijek zna kako da mu pomogne.', 'Жизненная, уморительно честная школьная история о том, как пережить строгого учителя, дать отпор задире и довериться лучшим друзьям.', 'A laugh-out-loud, delightfully honest school tale about dealing with drill-sergeant teachers, outsmarting playground bullies, and trusting true friends.', 'Duhovita i topla priča o školi koja pokazuje kako se nositi sa strogim učiteljem, nadmudriti školskog nasilnika i osloniti se na prave prijatelje.', '/covers/DP-0069.webp', '#e06d43', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","friends","real"]', '["школа","дружба","первоклассники","юмор","учителя"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('новые-рассказы-про-школу-4-70', 'DP-0070', 'новые рассказы про школу 4', 'New School Stories About Franz', 'Nove školske priče o Francu', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Франц ходит в школу, и у него в связи с этим есть "парочка проблем". Во-первых, он самый маленький в классе и не знает, что с этим делать. Во-вторых, когда Франц волнуется, голос у него становится тонким и писклявым, как у мышки, и Франца это очень раздражает. Как-то раз Франц сидел над домашним заданием. Он наделал ошибок, а когда захотел всё исправить, случайно намочил тетрадку, так что нести её в школу было стыдно. Теперь придётся всё объяснять учителю Ать-два. Но как же быть? Ведь когда Франц волнуется, он начинает пищать! Все хотят помочь Францу, но не знают как. И только один человек даёт ему суперсовет… А ещё Франц опаздывает на урок и думает: врать или не врать учителю о том, почему он так задержался? Как же поступит Франц?', 'Franz is back at school with a couple of tricky dilemmas: he is the shortest boy in his class, and whenever he gets nervous, his voice squeaks like a mouse! When a ruined homework notebook threatens to bring the wrath of his strict teacher upon him, Franz must find a way to explain himself without squeaking. Plus, when he''s running late, he has to choose between an easy lie and the awkward truth.', 'Franc ide u školu i muči ga nekoliko nezgodnih problema: najniži je u razredu, a kad god se unervozi, glas mu zacvili poput miša! Kada mu se domaći zadatak uništi neposredno pred čas, mora stati pred strogog učitelja Jedan-Dva. Da stvar bude gora, Franc kasni na čas i suočava se s vječnom dilemom: slagati ili reći istinu?', 'Франц покажет, как справиться с любыми школьными конфузами и строгими учителями без лишней паники и писка!', 'Endearing and wonderfully relatable, Franz teaches kids how to navigate school mishaps and strict teachers with courage and humor!', 'Duhovita i topla priča koja će svakog školarca naučiti kako da prevaziđe nezgode u učionici bez straha!', '/covers/DP-0070.webp', '#e58e26', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","real"]', '["school","growing up","humor","franz","everyday life"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-болезни-6-71', 'DP-0071', 'Про Франца и болезни 6', 'Franz and Illnesses', 'O Francu i bolestima 6', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'В этой книге классика детской австрийской литературы Кристине Нёстлингер вас ждёт новая порция рассказов про Франца, которому уже восемь с половиной лет. Франц по-прежнему ниже всех в классе, но всё же не такой маленький, как раньше: за последние полгода он вымахал на целую ладонь. А ещё у Франца вырос нос, и теперь его редко принимают за девочку. Всё бы ничего, но на смену этим проблемам пришли две новые… Первая - это фрау Ляйденфрост, или Домдраконица, как называет её Йозеф. Она приходит домой к Францу, чтобы убраться и приготовить обед. Фрау Ляйденфрост вечно на всех рычит, поэтому Франц её недолюбливает. Вторая проблема - это болезни. Франц изо всех сил пытается чем-нибудь заболеть, чтобы не ходить в школу, но у него никак не получается. Он считает, что это ужасно несправедливо. Только вот Франц ещё не знает, каково это - болеть по-настоящему… Почему нельзя есть слишком много клубники? Что делать, если сломал ногу, а мамы нет рядом? Как превратить болезнь в конфетный пир? Об этом и о многом другом - в новой книге рассказов про Франца.', 'Franz is eight and a half now: he grew taller, his nose got bigger, and people finally stopped mistaking him for a girl! But life brings brand-new challenges: Frau Leidenfrost, a grumpy housekeeper nicknamed the ''House Dragon'', and Franz''s stubborn attempts to fall ill just to skip school. When real trouble strikes—from a broken leg to eating far too many strawberries—Franz learns that being sick isn''t quite the holiday he imagined, though a bit of ingenuity can turn any recovery into a delightful candy feast.', 'Franc sada ima osam i po godina: porastao je za čitav dlan, nos mu se izdužio i više ga ne miješaju sa djevojčicom. Ipak, stižu nove muke: gospođa Lajdenfrost, mrzovoljna pomoćnica koju zovu „Zmajica“, i Francova velika želja da se razboli samo da ne bi išao u školu. Ali kad ga nevolje zaista stignu — uz slomljenu nogu i previše jagoda — Franc shvata da bolest uopšte nije zabavna, mada se uz malo mašte i oporavak u krevetu može pretvoriti u pravu gozbu sa slatkišima.', 'Оказывается, заболеть нарочно куда сложнее, чем кажется, зато любую хворь можно вылечить доброй шуткой и запасом леденцов!', 'Franz discovers that catching a cold on purpose is surprisingly hard work, but any real recovery is much sweeter with a secret stash of candy!', 'Franc otkriva da se uopšte nije lako razboljeti po želji, ali da se svaka prava prehlada lakše podnosi uz šaku bombona i dobar humor!', '/covers/DP-0071.webp', '#4ba397', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","real"]', '["growing up","franz","humor","school life","childhood"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-младенца-11-72', 'DP-0072', 'про Франца и младенца 11', 'Franz and the Baby', 'Franc i beba', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'У Франца большая проблема: с Габи, его лучшей подружкой, стало невозможно общаться! С некоторых пор она может говорить только об одном - о "младенчике", которого ждёт её мама. Ребёнок ещё не родился, а Франц уже страшно ревнует. Вдруг Габи будет всё время проводить с младенцем, а о нём забудет? Но Габи, оказывается, тоже очень волнуется: что, если родители перестанут обращать на неё внимание, когда в семье появится ещё один ребёнок? Как тогда быть? И вот наступает заветный день: мама с папой едут в больницу, младенец вот-вот родится, Габи и Франц не спят всю ночь, и никто не знает, что же будет потом…', 'Franz has a major dilemma: talking to his best friend Gabi has become impossible ever since she found out her mom is expecting! Gabi talks about nothing but the upcoming baby, and Franz is already wrestling with jealousy. What if she forgets all about him? But Gabi has her own secret fears about being cast aside once the newborn arrives. When the big night finally comes and her parents dash to the hospital, Franz and Gabi stay up together, wondering what on earth life will look like next.', 'Franc ima veliki problem: njegova najbolja drugarica Gabi priča samo o jednoj temi – bebi koju čeka njena mama! Franc se već plaši da će ga ona potpuno zaboraviti, dok i samu Gabi muči strah da će roditelji prestati da obraćaju pažnju na nju. Kada dođe dan porođaja i roditelji odjure u bolnicu, dvoje prijatelja provode neprospavanu noć punu strepnje i nagađanja šta im sve donosi novi član porodice.', 'Трогательная и жизненная история о том, как ревность уступает место настоящей поддержке, когда на горизонте маячит младший братик или сестричка.', 'A tender, funny look at childhood jealousy and friendship when a brand-new baby arrives to turn everything upside down.', 'Nježna i duhovita priča o ljubomori i pravom drugarstvu kada u život ušeta jedna sasvim nova beba.', '/covers/DP-0072.webp', '#e78b43', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["friends","real","funny"]', '["friendship","family","baby","growing up","feelings"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-дедушку-12-73', 'DP-0073', 'про Франца и дедушку 12', 'Stories of Franz and Grandpa', 'O Francu i djedu', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Франц учится во втором классе, и всё у него замечательно, кроме одного: мальчик по имени Йошка всё время Франца обижает. Йошка - ужасный хвастун. Он дразнит Франца, что у того нет четырёхцветной ручки, конструктора, фотоаппарата или ещё чего-нибудь, что есть у него самого. Как-то раз Йошка вообще поступил очень некрасиво: зная, что у Франца нет дедушки, взял и похвастался своим. Франц не выдержал и ответил, что у него тоже дедушка есть. Но Йошка ему не поверил. Ребята бросились Франца защищать и даже поспорили, что он не соврал и скоро покажет всем дедушку. Ну и что теперь Францу делать? Где ему найти настоящего деда? Похоже, Франца может спасти только один человек - его любимая бабушка…', 'Franz is in second grade and life would be wonderful if it weren''t for Joschka, the class show-off who loves teasing him. Knowing Franz has no grandfather, Joschka can''t resist boasting about his own. Cornered, Franz blurts out that he has a grandpa too! His loyal classmates back him up and bet that Franz will introduce him soon. Now Franz faces an impossible mission: where can he find a real grandfather? Fortunately, his wonderful grandma might have the ultimate rescue plan...', 'Franc ide u drugi razred i sve bi bilo savršeno da nema Joške, nepodnošljivog hvalisavca koji ga stalno zadirkuje. Kada se Joška pohvalio svojim djedom — znajući da ga Franc nema — Franc nije izdržao i izbrbljao se da i on ima djeda! Drugari iz razreda su stali u Francovu odbranu i opkladili se da će ga uskoro svi upoznati. Gdje sad pod hitno naći pravog djeda? Izgleda da Franca može spasiti samo njegova domišljata baka...', 'Что делать, если назло школьному хвастуну ты случайно придумал себе дедушку? Срочно звать на помощь бабушку!', 'What do you do when you accidentally invent a grandpa just to silence a bully? Call grandma to the rescue!', 'Šta uraditi kad u inat školskom hvalisavcu izmisliš djeda? Hitno zvati baku u pomoć!', '/covers/DP-0073.webp', '#4b86b4', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","friends","real"]', '["school","family","grandparents","humor","growing up"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-рождество-8-74', 'DP-0074', 'про Франца и Рождество 8', 'Franz and Christmas', 'O Francu i Božiću', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Совсем скоро Рождество, Франц уже придумал, что кому подарить, и, конечно, тоже с нетерпением ждёт подарков - особенно от своей лучшей подруги Габи и от Деда Мороза, которым у них в семье служит мама. Но с Габи каждый раз одно и то же: она дарит Францу то, что ни ему, ни ей самой совсем не нужно. А маме рассказывать о своих пожеланиях почти бесполезно. Она любит сюрпризы, поэтому никогда не знаешь, прислушается она к Францу или нет. К тому же ни ножей, ни пистолетов мама ему точно покупать не станет. В общем, Франц решил, что на этот раз он возьмёт всё в свои руки: Габи наконец-то подарит ему что-нибудь полезное, а мама - именно то, о чём он так давно мечтает. И никто даже не заподозрит, что Франц всё подстроил. Как же у него это получится? А вдруг что-то пойдёт не так? Вы узнаете обо всём, прочитав эту весёлую рождественскую историю.', 'Christmas is right around the corner, and Franz has decided to take holiday gifts into his own hands. Tired of receiving useless knick-knacks from his best friend Gabi and unpredictable surprises from his mom, he devises a clever secret plan so everyone gets him exactly what he actually wants. A heartwarming, witty holiday story about childhood schemes and true holiday cheer.', 'Božić samo što nije stigao, a Franc je riješio da stvari uzme u svoje ruke! Umoran od beskorisnih poklona najbolje drugarice Gabi i maminih nepredvidivih iznenađenja, on smišlja genijalan tajni plan kako bi ovog puta dobio baš ono o čemu sanja. Duhovita praznična priča puna topline i dječije snalažljivosti.', 'Хотите узнать, как хитро перехитрить праздничную суматоху и получить идеальный подарок? Франц научит!', 'Franz has masterminded the ultimate holiday gift hack, but will his secret plan actually survive Christmas?', 'Franc ima savršen tajni plan za božićne poklone, ali hoće li sve proći bez urnebesnih nezgoda?', '/covers/DP-0074.webp', '#c73832', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","friends","real"]', '["christmas","holidays","presents","friendship","family"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-франца-и-лошадей-14-75', 'DP-0075', 'про Франца и лошадей 14', 'Franz and the Horses', 'Franc i konji', 'Кристине Нестлингер', 'Christine Nöstlinger', 'Kristine Nestlinger', 'Катя Толстая', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Франца. Ему восемь лет, и у него появляется неожиданное увлечение: лошади. Правда, на самом деле Франц их ужасно боится, а единственная в его жизни поездка верхом продлилась секунд пять - папа едва успел сделать фото. Но что ещё оставалось, как не изображать из себя знатока лошадей, когда Габи, его лучшая подруга, начала грезить конными прогулками? Как можно было - ради продолжения дружбы - не изучить все "лошадиные" энциклопедии и не расспросить маму о верховой езде? Вот девочка и поверила, будто Франц разбирается в теме в сто раз лучше, чем подружка Сандра и сама Габи. Кто же мог представить, что уже через пару недель Габи позовёт Франца на "Пони-ранчо" - чтобы тот ехал с ней бок о бок и помогал экспертным советом! Теперь он боится не только лошадей, но и того, что девочка уличит его во лжи, посмеётся, обидится, перестанет дружить. И ещё зачем-то подарил ей ту самую фотографию, где он в седле с гордой осанкой! Выпутаться из безнадёжной ситуации может помочь только бабушка: на неё всегда можно положиться. Как Францу перестать бояться лошадей и снова спасти дружбу?', 'Eight-year-old Franz has an unexpected new passion: horses! Well, not really—truth be told, he is utterly terrified of them, and his only riding experience lasted five seconds. But his best friend Gabi is suddenly obsessed with horseback riding, so what else could Franz do to save their friendship besides memorizing horse encyclopedias and posing as a master equestrian? When Gabi enthusiastically invites him to the Pony Ranch for a ride together, Franz faces ultimate doom: exposure, mockery, and losing his best friend. Luckily, his clever grandmother might have just the plan to turn this wild bluff into a gentle triumph.', 'Osmogodišnji Franc ima novu strast: konje! Doduše, zapravo ih se užasno boji, a njegovo jedino jahanje u životu trajalo je jedva pet sekundi. Ali pošto njegova najbolja drugarica Gabi mašta o jahanju, Franc odlučuje da pročita sve enciklopedije i pretvara se da je pravi konjički stručnjak kako bi sačuvao prijateljstvo. Problem nastaje kada ga Gabi pozove na ranč ponija da jašu zajedno! Prestravljen od konja i mogućnosti da bude razotkriven kao lažov, Franc ima samo jednog saveznika na kog se uvijek može osloniti — svoju mudru baku.', 'Остроумная и жизненная история о том, на какую грандиозную ложь мы способны ради дружбы и как бабушкина мудрость помогает слезть с коня без позора.', 'A delightfully relatable tale showing the unbelievable heights of exaggeration we reach for our best friends—and how a wise grandma can save the day.', 'Duhovita i topla priča o tome u kakve se sve nevolje uvalimo zbog prijateljstva i kako nas mudra baka može spasiti od najvećeg blama.', '/covers/DP-0075.webp', '#8d5b36', '7-9', 'ru', 'available', 'Категория: Рассказы про Франца (серия для первого самостоятельного чтения)', '["funny","friends","real"]', '["horses","friendship","humor","overcoming fear","family"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цацики-идет-в-школу-76', 'DP-0076', 'Цацики идет в школу', 'Tsatsiki Goes to School', 'Caciki ide u školu', 'Мони Нильсон', 'Moni Nilsson', 'Moni Nilson', '', '', NULL, NULL, 7, 10, 'middle', 'Это книга о семье, где царят взаимопонимание и поддержка, свобода самовыражения и терпимость... И которой все-таки немного не хватает папы. Книги о Цацики - одни из самых известных в Европе книг для семейного чтения - уже переведены на 13 языков, экранизированы и известны школьникам всей Европы и их родителям. "Чтение должно быть приключением", - заявила в одном из интервью автор "Цацики" Мони Нильсон-Брэнстрем. И книга о Цацики - самое настоящее приключение, которое хочется пережить еще раз вместе с главными героями. Увлекательная и поучительная история про мальчика Цацики, который пошел в школу, где встретил и первого друга, и первую любовь, и первого врага. Приключения в школе получают неожиданное продолжение у Цацики дома, ведь у него самая невероятная в мире мама, которая умеет ходить на руках, шевеля при этом пальцами ног, и может ворваться в кабинет директора школы, если ее очень разозлить. Это детская и в то же время недетская книга о сочувствии, терпимости и взрослении детей и их родителей.', 'Tsatsiki is starting first grade, stepping into a whole new world full of first friends, secret crushes, and playground bullies. Luckily, he has the coolest, most unconventional mother on the planet—a rock bassist who can walk on her hands and will fiercely stand up for her son no matter what. A heartwarming, delightfully honest, and funny Scandinavian classic about unconditional love, growing up, and the everyday adventures of school life.', 'Caciki polazi u prvi razred, gdje ga čekaju prvi pravi prijatelj, prva simpatija i prve školske nevolje. Na sreću, kod kuće ima najneobičniju mamu na svijetu – basistkinju u rok bendu koja hoda na rukama i bez oklijevanja brani svog sina. Topla, iskrena i izuzetno duhovita skandinavska priča o bezuslovnoj ljubavi, odrastanju i svakodnevnim školskim pustolovinama.', 'Если вы думаете, что школа — это скучно, познакомьтесь с Цацики и его супермамой, которая ходит на руках и точно знает, как победить любые школьные невзгоды!', 'If you think school is boring, meet Tsatsiki and his hand-walking rockstar mom, who prove that family love and a bit of courage can conquer any playground challenge!', 'Ako mislite da je škola dosadna, upoznajte Cacikija i njegovu mamu rokerku koja hoda na rukama i zna kako riješiti svaku školsku nevolju!', '/covers/DP-0076.webp', '#e76f51', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","friends","real"]', '["school","family","friendship","growing up","humor"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цацики-и-его-семья-77', 'DP-0077', 'Цацики и его семья', 'Tsatsiki and His Family', 'Caciki i njegova porodica', 'Мони Нильсон', 'Moni Nilsson', 'Moni Nilson', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Продолжение истории про мальчика Цацики и его необыкновенную маму. В этой книге Цацики предстоит отправиться в Грецию и познакомиться с папой - Ловцом Каракатиц. Как сложатся их отношения? Какими окажутся новые родственники? И какие перемены ожидают Цацики после этого удивительного лета? Это детская и в то же время недетская книга о сочувствии, терпимости, взрослении детей и их родителей и, конечно же, семье.', 'The adventures of Tsatsiki and his unconventional mom continue! This time, Tsatsiki travels to Greece to finally meet his father, the legendary Cuttlefish Catcher. How will their relationship unfold, what surprises await him with his new relatives, and how will this unforgettable summer change everything? A wonderfully tender and funny story about growing up, empathy, and what truly makes a family.', 'Nastavak priče o dječaku Cacikiju i njegovoj neobičnoj mami. Ovog puta Caciki putuje u Grčku kako bi konačno upoznao svog oca — slavnog Lovca na sipe. Kako će izgledati njihov susret, ko su novi rođaci i kakve promjene nosi ovo čarobno ljeto? Tople i duhovite stranice o empatiji, odrastanju i pravoj porodičnoj ljubavi.', 'Поездка в Грецию, долгожданная встреча с папой — Ловцом Каракатиц — и целое море нежности, смеха и житейской мудрости.', 'A sunny voyage to Greece to meet the legendary Cuttlefish Catcher proves that family can be messy, surprising, and utterly wonderful.', 'Sunčano putovanje u Grčku i susret sa pravim Lovcem na sipe otkrivaju koliko porodica može biti topla, smiješna i nepredvidiva.', '/covers/DP-0077.webp', '#2b82a2', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","real","adventure"]', '["family","greece","growing up","humor","summer"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цацики-и-вселенная-78', 'DP-0078', 'Цацики и вселенная', 'Tsatsiki and the Universe', 'Caciki i svemir', 'Мони Нильсон', 'Moni Nilsson', 'Moni Nilson', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Новая - третья - книга о Цацики, его маме, папе и одноклассниках. Цацики и Пер Хаммар снова будут играть в футбол и шпионить, как раньше. Но уже и не как раньше. Они становятся самостоятельными. Цацики ждут новые увлечения и новая любовь, и перед ним - целая жизнь, целая вселенная. Для среднего школьного возраста', 'The third heartwarming book about Tsatsiki, his rock-and-roll mom, and his friends. Tsatsiki and Per Hammar are still playing football and playing detective, but growing up is changing the game. With brand-new crushes and newfound independence, Tsatsiki discovers that the world before him is as vast and exciting as the entire universe.', 'Treća topla priča o Cacikiju, njegovoj neobičnoj mami i školskim drugarima. Caciki i Per Hamar ponovo igraju fudbal i tajno špijuniraju, ali odrastanje donosi promjene. Pred Cacikijem su nove simpatije, velika pitanja i čitav jedan uzbudljiv svemir koji tek treba otkriti.', 'Взрослеть — это целое космическое приключение, особенно когда у тебя самая классная мама на свете и верный друг рядом!', 'Growing up is a cosmic adventure, especially when you have the coolest mom in the world and a loyal best friend by your side!', 'Odrastanje je prava kosmička avantura, posebno kada imaš najkul mamu na svijetu i najboljeg druga uz sebe!', '/covers/DP-0078.webp', '#2d5584', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["friends","funny","real"]', '["growing up","friendship","family","first crush","school life"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цацики-любовь-79', 'DP-0079', 'Цацики любовь', 'Tsatsiki and Love', 'Caciki i ljubav', 'Мони Нильсон', 'Moni Nilsson', 'Moni Nilson', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'В четвертой книге главному герою Цацики исполняется десять лет и он снова летит в Грецию. Для этого есть серьезная причина: умирает его дедушка. Цацики очень переживает, но ему помогает Элена, его двоюродная сестра. Они так здорово проводят время, что к концу лета Цацики даже не хочется возвращаться. Но дома, в Стокгольме, его ждет семья и новые жизненные задачи. Цацики продолжает ходить в школу и дружить с Пером Хаммаром, учится строить отношения с девочками и становится старшим братом! Для среднего школьного возраста', 'In the fourth book, Tsatsiki turns ten and travels back to Greece under poignant circumstances: his beloved grandfather is passing away. With the warmth and comfort of his cousin Elena, Tsatsiki navigates sadness and finds joy under the Mediterranean sun. But back in Stockholm, exciting new chapters unfold as Tsatsiki balances school, friendship with Per Hammar, first romantic butterflies, and welcoming a newborn sister into the family.', 'U četvrtoj knjizi Caciki puni deset godina i ponovo putuje u Grčku pod tužnim okolnostima: njegov voljeni djed je na samrti. Uz podršku rođake Elene, Caciki prevazilazi tugu i provodi divno ljeto. Po povratku u Stokholm čekaju ga novi životni izazovi: škola, prijateljstvo s Perom Hamarom, prve simpatije prema djevojčicama i preuzimanje ponosne uloge starijeg brata.', 'Пронзительная и светлая повесть о взрослении, искренней дружбе, первой влюблённости и радости стать старшим братом.', 'A tender, touching chapter in Tsatsiki''s life about saying goodbye, navigating first crushes, and stepping up as a big brother.', 'Dirljiva i topla priča o odrastanju, prvim ljubavnim leptirićima i ponosu što postaješ stariji brat.', '/covers/DP-0079.webp', '#2c7a9e', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["real","friends","funny"]', '["growing up","family","friendship","greece","first love"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цацики-и-рецина-80', 'DP-0080', 'Цацики и Рецина', 'Tsatsiki and Retzina', 'Caciki i Recina', 'Мони Нильсон', 'Moni Nilsson', 'Moni Nilson', '', 'Самокат', NULL, NULL, 7, 10, 'middle', '"Цацики и Рецина" - долгожданная пятая история в серии книг о Цацики известной шведской писательницы Мони Нильсон, которые уже давно полюбились русским читателям. Написанные с большим пониманием проблем и забот современных детей, книги про Цацики и его удивительную Мамашу проникнуты безусловной любовью героев друг к другу и к жизни, а автора - к читателю. Цацики, которому "десять, почти одиннадцать", в пятой книге учится заботиться о маленькой сестренке Рецине, ссорится с лучшим другом, попадает в "плохую компанию", помогает Мортену обрести новую семью. Справиться со всем этим ему помогают родительская любовь, понимание и умение разумно и с чувством юмора подходить к проблемам. Для среднего школьного возраста.', 'In the fifth book of Moni Nilsson''s beloved Swedish series, Tsatsiki is ten, almost eleven, and life is suddenly getting complicated. Between learning how to be a big brother to baby sister Retzina, falling out with his best friend, and getting mixed up with the wrong crowd, he discovers that growing up takes courage. Luckily, his unconventional mom, warm family love, and a great sense of humor make every obstacle manageable.', 'U petoj knjizi omiljenog švedskog serijala Moni Nilson, Caciki ima deset, skoro jedanaest godina, a odrastanje donosi nove izazove. Dok uči da bude pažljiv stariji brat maloj sestri Recini, Caciki se suočava sa svađom s najboljim drugom, upadanjem u loše društvo i pomaganjem Mortenu da nađe novi dom. Kroz sve životne prepreke vode ga bezuslovna porodična ljubav, razumijevanje i vedar duh.', 'Взрослеть — дело непростое, но когда рядом безусловно любящая Мамаша и забавная сестрёнка, любые школьные драмы преодолимы с улыбкой!', 'Growing up is no easy feat, but with an unconventional, loving mom and a brand-new baby sister, every bumpy lesson comes with plenty of heart and laughter!', 'Odrastanje nije nimalo jednostavno, ali uz veliku ljubav neobične Mame i novu malu sestru, sve nevolje lakše se prebrode uz osmijeh!', '/covers/DP-0080.webp', '#e67e22', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["real","friends","funny"]', '["growing up","family","friendship","siblings","humor"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('самсон-и-роберто-неожиданное-н-81', 'DP-0081', 'Самсон и Роберто Неожиданное наследство', 'Samson and Roberto: The Unexpected Inheritance', 'Samson i Roberto: Neočekivano nasljedstvo', 'Ингвар Амбьернсен', 'Ingvar Ambjørnsen', 'Ingvar Ambjernsen', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Хитрый кот Роберто и простодушный пёс Самсон неожиданно получили наследство - целый пансионат на берегу фьорда! Но у здания имеется один недостаток: в нём водится привидение. Для настоящих друзей это не помеха. Они раскроют тайну и превратят пансионат в самое популярное место в округе.', 'When clever cat Roberto and good-hearted dog Samson unexpectedly inherit a whole guesthouse by a scenic fjord, there is just one tiny catch: it comes with a ghost! But no spooky mystery can stand in the way of true friendship as these two set out to turn their quirky inn into the coziest hotspot around.', 'Lukavi mačak Roberto i dobroćudni pas Samson iznenada dobijaju nasljedstvo — čitav pansion na obali fjorda! Ipak, postoji mala začkoljica: u pansionu živi duh. Za prave prijatelje to nije prepreka; oni će razotkriti tajnu i pretvoriti staro zdanje u najomiljenije mjesto u okolini.', 'Очаровательная детективная история о том, как дружба кота и пса побеждает любых призраков и открывает двери самого уютного пансионата на фьорде!', 'A charming and cozy mystery proving that a clever cat and a loyal dog can tame any ghost and run the friendliest inn on the fjord!', 'Šarmantna i topla priča o tome kako mačje lukavstvo i pseća odanost mogu riješiti svaku tajnu sa duhovima i stvoriti najudobniji pansion na fjordu!', '/covers/DP-0081.webp', '#2b6d87', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","friends","animals"]', '["cat and dog","fjord","guesthouse","ghost","detective"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('самсон-и-роберто-крутые-ребята-82', 'DP-0082', 'Самсон и Роберто Крутые ребята', 'Samson and Roberto: The Tough Guys', 'Samson i Roberto: Opaki momci', 'Ингвар Амбьернсен', 'Ingvar Ambjørnsen', 'Ingvar Ambjernsen', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Пёс Самсон и кот Роберто живут припеваючи. Не так давно они получили в наследство замечательный пансионат, и с тех пор у них появилось много хлопот. Слава о пансионате долетела даже до обитателей фьорда, и вот уже там хочет остановиться огромный налим Хельге. Что делать? Приходится оборудовать для нового постояльца комнату с гигантской ванной и насосом, ведущим прямо в море. На этом проблемы не кончаются, потому что в пансионат собираются нагрянуть вороны из скандально известной рок-группы "Крутые ребята"!', 'Dog Samson and cat Roberto are living the sweet life managing their inherited fjord boarding house, but trouble is never far behind! First, an enormous burbot named Helge wants a room equipped with a giant saltwater tub, and then a notorious rock band of rowdy crows called ''The Tough Guys'' books a stay. Running a seaside hotel has never been this wild!', 'Pas Samson i mačak Roberto uživaju vodeći naslijeđeni pansion pored fjorda, ali brige nikada ne prestaju. Prvo džinovski manić Helge traži sobu s ogromnom kadom i pumpom koja vuče morsku vodu, a zatim najavljuju dolazak vrane iz skandalozne rok grupe „Opaki momci“! Vođenje hotela na obali mora nikada nije bilo ovako urnebesno.', 'Что делать, если в ваш тихий отель заселяется рок-банда ворон и гигантская рыба? Наливать чай и готовиться к безудержному веселью!', 'What do you do when a rock band of rowdy crows and a giant sea fish check into your quiet hotel? Brew some tea and brace for pure chaos!', 'Šta raditi kada se u vaš mirni pansion usele rok bend vrana i džinovska riba? Skuvajte čaj i spremite se za nezaboravnu zabavu!', '/covers/DP-0082.webp', '#2c6c8c', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","animals","friends"]', '["hotel","rock band","cat and dog","humor","scandinavian literature"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('голландский-без-проблем-83', 'DP-0083', 'Голландский без проблем', 'Dutch Without Trouble', 'Holandski bez muke', 'Мари-од Мюрай', 'Marie-Aude Murail', 'Mari-Od Miraj', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Жан Шарль мечтает погрузиться в теплое море, но его отец считает, что будет куда лучше, если он погрузится в "языковую среду" и выучит иностранный язык. Марианна ждет восемь подарков на Рождество, но получает дешевую куклу, совсем не похожую на настоящего младенца. Кентен предвкушает наступление воскресенья, чтобы пойти на выставку динозавров, но проводит целый выходной день с отцом, который готов на все, лишь бы остаться дома с газетой и кофе. Что же спасает этих детей, героев книги Мари-Од Мюрай "Голландский без проблем", от разочарования и скуки? Конечно же, богатое воображение!!! В сборник входит три рассказа: "Мой малыш за 210 франков", "Воскресенье с динозаврами" и, конечно, "Голландский без проблем", ставший названием книги. Кроме увлекательных рассказов, в этой книге маленьких читателей ждут небольшие задания на развитие фантазии.', 'Jean-Charles dreams of swimming in the warm sea, but his father thinks it’s far better to plunge into a "language environment" and pick up a foreign language. Marianne expects eight presents for Christmas but gets a cheap doll that looks nothing like a real baby. Quentin eagerly awaits Sunday to visit a dinosaur exhibit, yet spends the entire day with a father willing to do anything to stay home with his newspaper and coffee. What saves these children from boredom and heartbreak? Boundless imagination, of course! This collection features three humorous stories about growing up, plus playful creative prompts for young readers.', 'Žan Šarl sanja o kupanju u toplom moru, ali njegov otac smatra da je mnogo korisnije uroniti u „jezičko okruženje“ i naučiti strani jezik. Marijana za Božić očekuje osam poklona, ali dobija jeftinu lutku koja nimalo ne liči na pravu bebu. Kanten jedva čeka nedjelju da posjeti izložbu dinosaurusa, ali cijeli dan provodi s tatom koji bi dao sve samo da ostane kod kuće uz novine i kafu. Šta spasava ove male junake od dosade i razočaranja? Naravno, neiscrpna mašta! Ova zbirka donosi tri tople, duhovite priče i zabavne zadatke za razvoj kreativnosti.', 'Три невероятно смешных и жизненных рассказа о том, как детская фантазия легко побеждает любые взрослые занудства!', 'Three hilarious and relatable stories showing how boundless childhood imagination easily outsmarts boring grown-up plans!', 'Tri urnebesno duhovite priče koje pokazuju kako dječja mašta bez po muke pobjeđuje svaku dosadu odraslih!', '/covers/DP-0083.webp', '#e87a32', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","real"]', '["imagination","family","humor","growing up","short stories"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('oh-boy--84', 'DP-0084', 'Oh, boy!', 'Oh, Boy!', 'Oh, boy!', 'Мари-од Мюрай', 'Marie-Aude Murail', 'Marie-Aude Murail', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Мари-Од Мюрай - одна из наиболее замечательных французских авторов литературы для юношества. Ни саму писательницу, ни ее произведения - серьезные, беспокоящие и одновременно человечные и смешные до слез, - никак нельзя назвать политкорректными. В романе для подростков "Oh, boy!" через историю трех детей, оставшихся сиротами, Мари-Од Мюрай талантливо и с юмором касается сразу нескольких тем, о которых не очень принято говорить - сиротства, тяжелой болезни близкого человека, гомосексуализма, взаимосвязи между ответственностью и взрослением. В 2010 году Наталья Шаховская была удостоена премии "Мастер" Гильдии "Мастера литературного перевода" за перевод "Oh, boy!".', 'A deeply touching, razor-sharp, and delightfully unconventional story of three orphaned siblings fighting to stay together who land in the life of their chaotic half-brother Barthelemy. Marie-Aude Murail brilliantly balances tender humor with weighty life topics—illness, responsibility, and non-traditional family bonds—showing that true care can blossom in the most unexpected places.', 'Dirljiva, duhovita i krajnje neobična priča o troje djece bez roditelja koja se bore da ostanu zajedno i neočekivano ulaze u život svog polubrata Bartolomija. Mari-Od Miraj na maestralan način prepliće topao humor i ozbiljne životne teme, pokazujući da se prava porodica ne mjeri krvlju, već bezuslovnom podrškom i ljubavlju.', 'Приготовьтесь смеяться сквозь слёзы и бесконечно влюбляться в эту сумасбродную, но самую искреннюю семью на свете!', 'Get ready to laugh through your tears and fall head over heels for the messiest, most genuinely loving family you''ll ever meet!', 'Spremite se za smijeh kroz suze i bezuslovnu ljubav prema najneobičnijoj, ali najtoplijoj porodici koju ćete ikada sresti!', '/covers/DP-0084.webp', '#e86b32', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","real","friends"]', '["family","growing up","siblings","humor","empathy"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вафельное-сердце-85', 'DP-0085', 'Вафельное сердце', 'Waffle Hearts', 'Srce od vafla', 'Мария Парр', 'Maria Parr', 'Marija Par', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Год из жизни двух жителей бухты Щепки-Матильды, где всего-то три дома, - девятилетнего Трилле, который и рассказывает нам эту историю, и его соседки и одноклассницы Лены - вмещает немыслимо много событий и приключений: забавных, трогательных, опасных... Идиллическое житье-бытье на норвежском хуторе нарушается - но не разрушается - драматическими событиями. Но дружба, конечно же, оказывается сильнее! "Вафельное сердце" (2005) - дебютная книга Марии Парр, которая была переведена более чем на двадцать языков и удостоена множества премий на родине в Норвегии и за рубежом. Только в России продано уже более 120 тысяч экземпляров, а общий тираж по всему миру давно перевалил за миллион. В 2018 году вышло долгожданное продолжение - "Вратарь и море". 8-е издание.', 'A year in the life of two young residents of Mathildewick Cove, a tiny Norwegian bay with only three houses. Nine-year-old Trille and his fearless, inventive neighbor Lena share countless adventures—some hilarious, some dangerous, and some deeply touching. Even when dramatic events shake their quiet rural life, the power of friendship and Grandma''s warm waffles hold everything together.', 'Godina u životu dvoje stanovnika uvale Šćepke-Matilde, gdje se nalaze samo tri kuće — devetogodišnjeg Trila i njegove neustrašive komšinice i drugarice Lene — ispunjena je nevjerovatnim avanturama: zabavnim, dirljivim i ponekad opasnim. Idilični seoski život u Norveškoj suočiće se sa izazovima, ali pravo prijateljstvo i topli vafli baka-tetke pokazaće se jačim od svega.', 'Запасайтесь тёплыми вафлями и носовыми платками: неугомонная Лена и верный Трилле заставят вас смеяться в голос и верить в настоящую дружбу!', 'Grab a plate of warm waffles and keep tissues handy: fearless Lena and loyal Trille will make you laugh out loud and believe in true friendship!', 'Pripremite tople vafle i maramice: nestašna Lena i vjerni Trile nasmijaće vas do suza i podsjetiti na snagu pravog prijateljstva!', '/covers/DP-0085.webp', '#d97736', '7-9', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["friends","funny","adventure"]', '["norway","friendship","childhood","family","humor"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вратарь-и-море-86', 'DP-0086', 'Вратарь и море', 'The Goalie and the Sea', 'Golman i more', 'Мария Парр', 'Maria Parr', 'Marija Par', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Долгожданное продолжение Вафельного сердца" норвежской писательницы Марии Парр, прозванной новой Астрид Линдгрен! Герои "Вафельного сердца" Лена и Трилле из бухты Щепки-Матильды подросли - им уже по двенадцать лет, а в этом возрасте все непросто. Дед Трилле стареет, неподалеку поселяется девочка-иностранка, а новый тренер футбольной команды изводит Лену придирками и держит на скамейке запасных. Друзья по-прежнему пускаются в невероятные авантюры, ссорятся и мирятся, ведут разговоры о пустяках и о важном. Год им предстоит нелегкий, он принесет любовь и ревность, страх смерти и отчаяние, мужество в трудную минуту и стойкость на пути к цели. Остроумная и трогательная повесть, как и предыдущие книжки Марии Парр, читается на одном дыхании: вместе с героями мы смеемся и плачем - и верим каждому слову. С 2005 года, когда история Лены и Трилле впервые вышла в Норвегии, "Вафельное сердце" читают на тридцати языках, а в России его общий тираж превысил 100 тысяч экземпляров.', 'The eagerly awaited sequel to *Waffle Hearts*! Trille and Lena have turned twelve, and growing up isn''t as simple as it used to be. Trille''s grandad is growing older, a new foreign girl moves into the cove, and a demanding soccer coach keeps Lena benched. Amid stormy seas, first crushes, and growing pains, the inseparable duo proves that true friendship and daring spirit can weather any tide.', 'Dugo očekivani nastavak romana „Vafelsko srce“! Trile i Lena su napunili dvanaest godina i otkrivaju da odrastanje donosi nove izazove. Trilov đed stari, u uvali se pojavljuje nova djevojčica, a strogi fudbalski trener drži borbenu Lenu na klupi za rezerve. Kroz morske oluje, prve simpatije i nestašluke, nerazdvojni prijatelji uče o hrabrosti, gubicima i nepokolebljivoj odanosti.', 'Возвращаемся в любимую норвежскую бухту: Лене и Трилле уже по двенадцать, штормы стали взрослее, но дружба по-прежнему крепче скал!', 'Return to the windswept Norwegian cove where Lena and Trille face bigger storms, fierce football trials, and the invincible power of growing up together.', 'Povratak u omiljeni norveški zaliv: Lena i Trile imaju dvanaest godina, bure su ozbiljnije, ali njihovo prijateljstvo ostaje čvršće od svake stijene!', '/covers/DP-0086.webp', '#246587', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["friends","adventure","real"]', '["norway","friendship","growing up","sea","football"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лакрица-и-привезение-87', 'DP-0087', 'Лакрица и привезение', 'Licorice and the Spook', 'Lakris i neobični duh', 'Мони Нильсон', 'Moni Nilsson', 'Moni Nilson', '', 'Самокат', NULL, NULL, 7, 10, 'middle', '"Если бы Лакрица мог сам выбирать, его бы звали Иисус, Фантомас, или, скажем, Клас-Бертил. Клас-Бертил вполне годился, Иисуса все любили, а Фантомас никого не боялся". Но его зовут Лакрица, ему скоро в школу, и ему страшно хочется иметь друга: в маленькой шведской горнолыжной деревушке Норрнэс даже поиграть не с кем. И тут - из Нитам-Нисяма появляется... Привезение! Оно умеет быть невидимым, перемещается между мирами и обожает шалить! Книга вышла на нескольких европейских языках.', '"If Licorice could choose, he''d be named Jesus, Fantômas, or say, Klas-Bertil. Klas-Bertil was quite decent, everyone loved Jesus, and Fantômas feared no one." But his name is Licorice, he’s starting school soon, and he desperately wants a friend: in a tiny Swedish ski village of Norrnäs, there is nobody to play with. And then—straight out of Nowhere-in-Particular—appears a mischievous Ghost! It can turn invisible, travel across worlds, and loves stirring up trouble!', '„Da je Lakris mogao sam da bira, zvao bi se Isus, Fantomas ili, recimo, Klas-Bertil. Klas-Bertil bi sasvim odgovarao, Isusa su svi voljeli, a Fantomas se nikoga nije bojao.” Ali njegovo ime je Lakris, uskoro kreće u školu i očajnički mu je potreban prijatelj: u malom švedskom skijaškom selu Nornes nema s kim ni da se poigra. A onda se, pravo niotkuda, pojavljuje... neobično Priviđenje! Ono umije da bude nevidljivo, putuje između svjetova i obožava nestašluke!', 'Трогательная и озорная шведская повесть о том, как тоскливо ждать первого звонка в одиночестве и какое счастье обрести тайного сообщника для проказов!', 'A warm, mischievous Swedish tale about the longing for a best friend before starting school—and the sheer joy of finding an invisible partner in crime!', 'Topla i nestašna švedska priča o tome kako je teško čekati polazak u školu bez drugara i kakva je radost pronaći nevidljivog saveznika za sve smicalice!', '/covers/DP-0087.webp', '#3c6382', '7-9', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","magic","friends"]', '["friendship","ghosts","sweden","mischief","starting school"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('само-собой-и-вообще-88', 'DP-0088', 'Само собой и вообще', 'Anyway and All That', 'Samo po sebi i uopšte', 'Кристине Нестлинер', 'Christine Nöstlinger', 'Kristin Nestlinger', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Само собой, ни Карли, ни Ани, ни тем более Шустрику вовсе не хочется "разводиться" с папой! Только этих троих ни о чем не спросили. Детей вообще редко спрашивают. А зря! Влюбчивая пятнадцатилетняя Карли, тринадцатилетний книгочей Ани и даже малыш Шустрик понимают гораздо больше, чем может показаться взрослым, по-своему оценивают воцарившийся в их жизни хаос и пытаются разобраться с родительскими и собственными проблемами. Кристине Нёстлингер - австрийская писательница, автор более 100 книг для детей и подростков, лауреат премий им. А. Линдгрен (2003) и Х.К. Андресена (1984), позволила детям высказаться. И из истории развода получилась очень смешная и жизнерадостная книжка.', 'Naturally, neither Karli, Ani, nor little Shustrik want to ''divorce'' their dad! But no one bothered to ask the kids. Fifteen-year-old romantic Karli, thirteen-year-old bookworm Ani, and even the youngest sibling understand far more than adults realize. As chaos descends upon their family, the kids navigate both their parents'' turmoil and their own growing pains with humor, wit, and resilience. Austrian master storyteller Christine Nöstlinger gives children a voice, turning a bittersweet family separation into a heartwarming, surprisingly hilarious, and deeply honest story.', 'Naravno, ni Karli, ni Ani, a kamoli mali Šustrik, uopšte ne žele da se ''razvedu'' od tate! Ali njih troje niko ništa nije pitao. Petnaestogodišnja romantična Karli, trinaestogodišnji knjiški moljac Ani i mališan Šustrik razumiju mnogo više nego što odrasli misle. Dok se u njihovom domu stvara haos, djeca pokušavaju da shvate roditeljske probleme, ali i svoje sopstvene. Čuvena austrijska autorka Kristin Nestlinger daje glas djeci i stvara nevjerovatno duhovitu, optimističnu i toplu priču o izazovima odrastanja i porodičnim promjenama.', 'Когда взрослые чудят и разводятся, дети берут дело в свои руки — искренне, без прикрас и с обезоруживающим юмором!', 'When grown-ups turn life upside down with a divorce, the kids take charge with honest wit and unforgettable humor!', 'Kad odrasli zakomplikuju život razvodom, djeca preuzimaju stvar u svoje ruke — uz mnogo mudrosti i neodoljivog humora!', '/covers/DP-0088.webp', '#e07a5f', '7-9', 'ru', 'available', 'Для среднего и старшего школьного возраста.', '["funny","real"]', '["family","divorce","siblings","growing up","humor"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лети-майский-жук--89', 'DP-0089', 'Лети, майский жук!', 'Fly Away Home', 'Leti, gundelju!', 'Кристине Нестлинер', 'Christine Nöstlinger', 'Kristin Nestlinger', '', 'КонтрКультура', NULL, NULL, 7, 10, 'middle', 'Автобиографическая книга воспоминаний лауреата Международной премии имени Астрид Линдгрен - австрийской писательницы Кристине Нестлингер "Лети, майский жук!" вошла в ряд выдающихся произведений детской литературы конца XX века. Она повествует о последних неделях великой войны через призму впечатлений маленькой героини, в роли которой выступает автор. Литературное творчество К.Нестлингер, удостоенной более 30 литературных премий, в том числе - Золотой медали Ханса Кристиана Андерсена, несмотря на общемировое признание автора, практически неизвестно российскому читателю. Представляя перевод Эльвиры Ивановой, издательство впервые дает возможность прикоснуться к богатому образному миру этого удивительного человека. В качестве иллюстратора и оформителя повести дебютирует художница Ксения Макарова, которая не только знакомит с героями книги - родными и соседями, жителями военной Вены и советскими солдатами, но и переносит нас в атмосферу незабываемых дней весны 1945 года, наполненных человеческими трагедиями и удивительными встречами.', 'An autobiographical masterpiece by acclaimed Austrian author Christine Nöstlinger, Fly Away Home captures the final tumultuous weeks of World War II through the fearless, curious eyes of a young girl living in the outskirts of Vienna. As soldiers arrive and everyday life is turned upside down, she finds warmth, unexpected friendships, and poignant moments of hope amid the ruins. A powerful, deeply honest, and touching coming-of-age classic about finding humanity in the darkest of times.', 'Autobiografsko remek-djelo cijenjene austrijske spisateljice Kristin Nestlinger, roman „Leti, gundelju!“, prikazuje posljednje burne sedmice Drugog svjetskog rata kroz radoznale i hrabre oči djevojčice u predgrađu Beča. Dok se svijet odraslih ruši, a vojnici preplavljuju grad, ona otkriva toplinu, neočekivana prijateljstva i iskrice nade u ruševinama. Ovo je dirljiva i iskrena priča o odrastanju i humanosti koja sija čak i u najtežim vremenima.', 'Пронзительная и искренняя повесть о весне 1945 года глазами девятилетней девочки, где сквозь грохот войны пробиваются дружба, надежда и простое человеческое тепло.', 'A deeply moving and honest story of the spring of 1945 through the eyes of a nine-year-old girl, where friendship, resilience, and humanity bloom right through the cracks of war.', 'Dirljiva i iskrena priča o proljeću 1945. kroz oči devetogodišnje djevojčice, u kojoj usred ratnog vihora cvjetaju prijateljstvo, nada i ljudska toplina.', '/covers/DP-0089.webp', '#7e6244', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["real","friends"]', '["world war ii","vienna","childhood","history","growing up"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('джаггер-джаггер-90', 'DP-0090', 'Джаггер, Джаггер', 'Jagger, Jagger', 'Džager, Džager', 'Фрида Нильсон', 'Frida Nilsson', 'Frida Nilson', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'С Джаггером всегда интересно: он умный и очень классный. Этот полупес-получеловек понимает Бенгта лучше, чем родители, которые мило улыбаются и делают вид, что все в порядке - даже когда соседские дети запирают его в сарайчике с мусорными баками. С лучшим другом меняется все вокруг, причем в лучшую сторону! Для младшего школьного возраста.', 'Life with Jagger is never dull: he is clever, bold, and unapologetically cool. This half-dog, half-human understands Bengt far better than his parents do—parents who smile politely and pretend everything is fine even when the neighborhood bullies lock Bengt in the dumpster shed. Having a true friend changes everything, and definitely for the better! A touching and funny story for early school readers.', 'Sa Džagerom je uvijek uzbudljivo: on je pametan, hrabar i nevjerovatno kul. Ovaj neobični pas-čovjek razumije Bengta mnogo bolje od njegovih roditelja, koji se samo ljubazno smiješe i prave da je sve u redu — čak i kad ga djeca iz komšiluka zaključaju u ostavu za smeće. Uz pravog prijatelja sve se mijenja, i to nabolje! Dirljiva priča za mlađi školski uzrast.', 'Пронзительная и честная история о том, как один лохматый и дерзкий друг может вернуть веру в себя и научить давать отпор обидчикам!', 'A poignant and warm tale about how one scruffy, bold friend can give you the courage to stand tall against bullies.', 'Dirljiva i iskrena priča o tome kako jedan čupavi, hrabri prijatelj može vratiti samopouzdanje i naučiti te da se izboriš za sebe.', '/covers/DP-0090.webp', '#e8a838', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["friends","real"]', '["friendship","bullying","growing up","courage","dogs"]', 1792836322694, 1792845656351);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебные-кеды-моего-друга-пер-91', 'DP-0091', 'Волшебные кеды моего друга Перси', 'My Friend Percy''s Magical Gym Shoes', 'Čarobne patike mog prijatelja Persija', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', '', '', NULL, NULL, 7, 10, 'middle', 'Когда у осторожного и неуклюжего Ульфа появляется новый друг, жизнь переворачивается с ног на голову. Перси — полная противоположность Ульфа: он любит подраться, топчет чужие фуражки, и на переменах все обходят его стороной. Ульф страшно хочет быть похожим на Перси, он мечтает завладеть его волшебными кедами, которые, по словам Перси, наделяют своего обладателя силой и храбростью. И ему это удается! Но увы, все не так просто... Это юмористическая история о том, как «хороший мальчик» попадает в дурную компанию и становится отпетым хулиганом, она построена на реальных воспоминаниях знаменитого шведского писателя Ульфа Старка, автора множества книг и спектаклей для детей.', 'When cautious and clumsy Ulf makes a new friend, his quiet life turns completely upside down. Percy is Ulf''s exact opposite: tough, fearless, and feared by everyone at school. Desperate to become just as cool and brave, Ulf dreams of getting his hands on Percy''s magical sneakers, which allegedly grant their owner superhuman courage. A delightfully funny coming-of-age story based on the childhood memories of celebrated Swedish author Ulf Stark.', 'Kada oprezni i nespretni Ulf dobije novog druga, njegov mirni svijet okreće se naglavačke. Persi je njegova sušta suprotnost: neustrašiv je, spreman na kavgu i svi ga zaobilaze na velikom odmoru. Želeći da postane hrabar, Ulf žudi za Persijevim čarobnim patikama koje navodno donose snagu i odvažnost. Duhovita priča o odrastanju zasnovana na stvarnim uspomenama iz djetinjstva slavnog švedskog pisca Ulfa Starka.', 'Осторожно: эти кеды гарантируют внезапный прилив храбрости и целую кучу уморительных школьных неприятностей!', 'Slip on these sneakers at your own risk—they guarantee instant bravado and an awful lot of hilarious schoolyard trouble!', 'Obujte ove patike na sopstvenu odgovornost — garantuju instant hrabrost i gomilu urnebesnih školskih nevolja!', '/covers/DP-0091.webp', '#d8432a', '7-9', 'ru', 'available', 'новое в библиотеке', '["funny","friends","real"]', '["friendship","school life","growing up","childhood memories","humor"]', 1792836322694, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мой-друг-перси-буффало-билл-и--92', 'DP-0092', 'Мой друг Перси, буффало Билл и я', 'My Friend Percy, Buffalo Bill and Me', 'Moj prijatelj Persi, Bafalo Bil i ja', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Что может быть лучше летних каникул, проведенных вместе с другом? Десятилетние Ульф и Перси строят хижину, купаются в море, играют в индейцев, помогают приятелю собирать жуков и читают книгу про Буффало Билла, знаменитого охотника на бизонов с Дикого Запада. Перси неожиданным образом удается расположить к себе всю семью, даже сердитого дедушку Ульфа. И всех приятелей друга. Даже девочку Пию, в которую Ульф безнадежно влюблен! Выдержит ли дружба мальчиков такие испытания? Ульф Старк - классик шведской детской литературы, лауреат Немецкой международной детской литературной премии 1994 г., Шведской национальной Августовской премии 1996 г., автор повестей "Чудаки и зануды", "Пусть танцуют белые медведи", "Умеешь ли ты свистеть, Йоханна?". "Мой друг Перси, Буффало Билл и я" - одна из самых известных его книг (в 2005 году была экранизирована) - впервые выходит на русском языке!', 'What could be better than summer holidays spent with a best friend? Ten-year-old Ulf and Percy build a secret hideout, swim in the sea, play cowboys and Indians, and read thrilling tales of Buffalo Bill. But Percy effortlessly charms everyone—including Ulf’s notoriously grumpy grandfather, the neighborhood kids, and Pia, the girl Ulf secretly loves. Will their friendship withstand the test of rivalry and summer romance? A classic Swedish masterpiece about childhood, laughter, and growing up.', 'Šta može biti bolje od ljetnjeg raspusta provedenog sa najboljim drugom? Desetogodišnji Ulf i Persi grade tajno sklonište, kupaju se u moru, igraju se Indijanaca i čitaju uzbudljive priče o Bafalu Bilu. Međutim, Persi bez truda osvaja srca svih—čak i mrzovoljnog Ulfovog đeda, ali i Pije, djevojčice u koju je Ulf potajno zaljubljen! Može li njihovo prijateljstvo preživjeti ovakvo iskušenje? Topla i duhovita priča švedskog majstora Ulfa Starka.', 'Идеальная повесть о лете, первой влюблённости и дружбе, способной выдержать даже самого обаятельного соперника и ворчливого дедушку!', 'The quintessential summer read packed with salty sea air, first crushes, and a friendship tested by a wonderfully charming best mate.', 'Savršena priča o ljetnjem raspustu, prvim simpatijama i pravom drugarstvu koje može da preživi i ljubomoru i najmrzovoljnijeg đeda!', '/covers/DP-0092.webp', '#e28b3a', '7-9', 'ru', 'available', 'Для среднего и старшего школьного возраста.', '["friends","funny","real"]', '["summer","friendship","humor","growing up","first love"]', 1792836322694, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленькая-повесть-о-любви-93', 'DP-0093', 'Маленькая повесть о любви', 'The Little Book of Love', 'Mala priča o ljubavi', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Ида Бьорс', '', NULL, NULL, 7, 10, 'middle', 'Настроение у Фреда совсем не рождественское. Девочка Эльза, от которой его бросает в жар, сердится на него - и за дело. Мама все время усталая и сердитая, еду выдают по талонам, а самое грустное - папа где-то далеко и вряд ли приедет домой на праздник. А все из-за одного дурака с черными усиками, которому вздумалось повоевать. Но Рождество на то и Рождество, чтобы случались разные чудеса... Для среднего школьного возраста.', 'Fred is definitely not in a festive mood. Gerda, the girl who makes his heart race, is furious with him—and with good reason. Mother is exhausted from rationing coupons, and worst of all, Dad is far away at the border because of a certain mustache-twirling dictator who decided to start a war. But Christmas is a time for real magic, even when hope seems tiny. A tender and funny holiday story full of courage, first crush butterflies, and fatherly love.', 'Fred uopšte nije u prazničnom raspoloženju. Elsa, djevojčica zbog koje mu klecaju koljena, ljuta je na njega — i to sa razlogom. Mama je stalno umorna, hrana je na tačkice, a tata je daleko na frontu zbog nekog ludaka s brčićima koji je riješio da ratuje. Ali Božić ne bi bio Božić kada se ne bi dešavala čuda... Dirljiva i duhovita priča o prvoj ljubavi i nadi u teškim vremenima.', 'Трогательная до слёз и очень светлая рождественская история о первой любви, говорящем вентиляторе и настоящих чудесах посреди суровой зимы.', 'A deeply touching, gently hilarious holiday tale about first love, a secret vent conversation, and small miracles that keep hope glowing.', 'Nevjerovatno topla i duhovita praznična priča o prvoj ljubavi, tatinom odijelu i malim čudima koja griju i u najhladnijoj zimi.', '/covers/DP-0093.webp', '#a83c32', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["real","friends","funny"]', '["christmas","first love","family","growing up","winter"]', 1792836322694, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-старк-94', 'DP-0094', 'Маленький Старк', 'Little Stark', 'Mali Stark', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Улоф Ландстрем', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Эта смешная и грустная книга построена на реальных воспоминаниях знаменитого шведского писателя Ульфа Старка, автора множества книг и спектаклей для детей. Главный герой живет в самой обычной семье, его папа работает зубным врачом, мама занимается хозяйством. Он частенько попадает в разнообразные переделки, разыгрывает своего дедушку, подбивает маму играть в индейцев или просто отправляет в плавание на самодельном кораблике светлячка. Ульф Старк потрясающе тонко и тепло описывает отношения между братьями, сочетая взрослый и детский взгляд на жизнь.', 'This bittersweet and heartwarming collection is rooted in the real childhood memories of renowned Swedish author Ulf Stark. Growing up with a dentist father, young Ulf is always stumbling into mischievous scrapes—pranking his grandfather, roping his mom into playing Indians, or launching a firefly on a homemade bark boat. Stark portrays brotherhood and the wonders of growing up with poignant humor and tender honesty.', 'Ova duhovita i dirljiva knjiga zasnovana je na istinitim uspomenama proslavljenog švedskog pisca Ulfa Starka. Glavni junak odrasta u sasvim običnoj porodici sa ocem stomatologom, ali njegov svakodnevni život pun je nestašluka — od smicalica dedi do plovidbe svica na malenom brodiću. Stark s nevjerovatnom toplinom i iskrenošću dočarava bratske odnose i djetinjstvo koje se pamti zauvijek.', 'Трогательные, хулиганские и невероятно живые истории о детстве, где даже обычный вечер превращается в незабываемое приключение.', 'Mischievous, tender, and deeply relatable stories of childhood that will make you laugh out loud and cherish everyday family moments.', 'Nestašne, tople i nevjerovatno iskrene priče o odrastanju koje će vas nasmijati i podsjetiti na pravu magiju djetinjstva.', '/covers/DP-0094.webp', '#e07a5f', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","real","adventure"]', '["childhood","family","humor","brothers","growing up"]', 1792836322694, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('георгий-и-дракон-95', 'DP-0095', 'Георгий и Дракон', 'George and the Dragon', 'Georgije i zmaj', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Анна Хеглунд', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Давным-давно, когда Георгий еще не был святым, он жил с отцом и старшими братьями в Каппадокии. Они бегали наперегонки по полю, боролись и устраивали во дворе поединки на деревянных мечах. Но вот настала пора побродить по свету, набраться опыта. Впереди Георгия ждут нелегкие испытания. Но что бы ни случилось, он всегда слушает свое сердце. Всемирно известный детский писатель Ульф Старк переосмысляет старинное сказание о Георгии и змие.', 'Long ago, before George became a saint, he lived with his father and elder brothers in Cappadocia, running races and sparring with wooden swords. But the time comes to set out into the world and seek his own path. Hard trials lie ahead, yet George always listens to his heart. World-renowned storyteller Ulf Stark offers a tender and thoughtful reimagining of the ancient legend of George and the dragon.', 'Davno, prije nego što je postao svetac, Georgije je živio s ocem i starijom braćom u Kapadokiji, trčeći po poljima i boreći se drvenim mačevima. No kucnuo je čas da pođe u svijet i stekne životno iskustvo. Pred njim su teška iskušenja, ali Georgije uvijek sluša svoje srce. Poznati pisac Ulf Stark donosi toplo i mudro viđenje drevne legende o Georgiju i zmaju.', 'Мудрая и трогательная легенда от Ульфа Старка о том, что истинное мужество живёт не на острие меча, а в чутком сердце.', 'A tender, wise retelling by Ulf Stark showing that true bravery isn''t found in a sharp sword, but in a listening heart.', 'Topla i mudra priča Ulfa Starka koja nas uči da prava hrabrost ne leži u oštrici mača, već u plemenitom srcu.', '/covers/DP-0095.webp', '#b85b35', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["adventure","magic"]', '["dragons","legends","courage","ulf stark","growing up"]', 1792836322694, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('беглецы-96', 'DP-0096', 'Беглецы', 'The Runaways', 'Bjegunci', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Китти Краутер', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Любимый дедушка Готфрида оказался в больнице. Он постоянно ворчит, ругается и размышляет о том, попадет ли на небеса. Готфрид старается как можно чаще его навещать, иногда даже втайне от родителей. У дедушки есть мечта - в последний раз навестить летний домик, где они с бабушкой когда-то были очень счастливы. Внук помогает осуществить побег - тут-то и начинаются настоящие приключения! Последняя книга всемирно известного писателя Ульфа Старка. Иллюстрации нарисовала бельгийская художница Китти Краутер, лауреат мемориальной премии Астрид Линдгрен.', 'Gottfried''s grandfather is stuck in the hospital, grumbling and wondering whether he''ll make it to heaven. He has one last wish: to see the beloved summer cottage where he spent his happiest days with his late wife. Loyal Gottfried decides to help his grumpy grandpa break out for one final journey. Ulf Stark''s touching and funny farewell masterpiece, illustrated by Astrid Lindgren Memorial Award winner Kitty Crowther.', 'Gotfridov djed završio je u bolnici, stalno gunđa i razmišlja o tome hoće li dospjeti u raj. Njegova najveća želja jeste da još jednom posjeti ljetnjikovac u kom je nekada bio beskrajno srećan sa svojom suprugom. Unuk mu pomaže da pobjegne iz bolnice — i tako počinje njihova nezaboravna avantura. Posljednja knjiga slavnog švedskog pisca Ulfa Starka, sa divnim ilustracijama Kiti Krauter.', 'Трогательная до слёз и одновременно очень смешная история о дедушке, внуке, побеге из больницы и силе настоящей любви.', 'A laugh-out-loud funny and deeply moving story about a daring hospital breakout and the tender bond between a boy and his grandfather.', 'Nevjerovatno topla i duhovita priča o bjekstvu iz bolnice i neraskidivoj ljubavi između dječaka i njegovog djeda.', '/covers/DP-0096.webp', '#d97736', '7-9', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["adventure","real","funny"]', '["grandparents","family","adventure","friendship","growing-up"]', 1792836322695, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('умеешь-ли-ты-свистеть-йоханна--97', 'DP-0097', 'Умеешь ли ты свистеть, Йоханна?', 'Can You Whistle, Johanna?', 'Umiješ li da zviždiš, Johana?', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'У семилетнего Ульфа есть дедушка. А вот у его друга Берры дедушки нет. Когда тебе семь лет и у тебя нет дедушки, грустно: никто не пригласит тебя в гости, не угостит кофе, не возьмёт порыбачить на озеро, не научит запускать воздушного змея и красиво свистеть… Но это поправимо, если есть друг Ульф, который может показать место, где дедушек видимо-невидимо. И вот однажды оба мальчугана отправляются в дом престарелых и находят себе самого настоящего дедушку, пусть ненадолго…', 'Seven-year-old Ulf has a grandfather, but his best friend Berra doesn''t. And that is simply unfair, because who else will invite you over, take you fishing, or teach you how to whistle a proper tune? Luckily, Ulf knows a nursing home packed with potential grandpas. There, Berra adopts lonely Nils, sparking a short, touching, and truly unforgettable friendship.', 'Sedmogodišnji Ulf ima đeda, ali njegov najbolji drug Bera nema. A to je baš bezveze: ko će te onda častiti kafom, povesti na pecanje ili naučiti da zviždiš? Srećom, Ulf zna starački dom pun đedova. Tamo Bera bira usamljenog Nilsa, započinjući dirljivu i nezaboravnu priču o prijateljstvu koje ne mari za godine.', 'Пронзительная, добрая и светлая история о том, что самого лучшего дедушку можно не только унаследовать, но и выбрать сердцем.', 'A tender, bittersweet Swedish classic proving that you don''t need to be related by blood to choose the world''s best grandfather.', 'Dirljiva i topla priča koja dokazuje da se najbolji đed na svijetu ne mora naslijediti, već se može izabrati srcem.', '/covers/DP-0097.webp', '#3b7a9e', '7-9', 'ru', 'available', 'Для младшего школьного возраста.', '["friends","real"]', '["grandparents","friendship","growing up","generations","swedish literature"]', 1792836322695, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пусть-танцуют-белые-медведи-98', 'DP-0098', 'Пусть танцуют белые медведи', 'Let the Polar Bears Dance', 'Neka bijeli medvjedi plešu', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Повесть "Пусть танцуют белые медведи" шведского писателя Ульфа Старка ("Умеешь ли ты свистеть, Йоханна?", "Чудаки и зануды", "Рождество в лесу" и другие) издается на русском языке уже 10 лет и стала классикой подросткового чтения. Герой повести Лассе не блещет в учебе, ходит в потертых брюках, слушает Элвиса Пресли и хулиганит на улицах. Но однажды его жизнь круто меняется. Он вдруг обнаруживает, что вынужден делать выбор между новым образом примерного мальчика с блестящими перспективами и прежним Лассе, похожим на своего "непутевого" и угрюмого, как медведь, отца. Он пытается примирить два противоречивых мира, найти свое место в жизни и, главное, доказать самому себе, что может сделать невозможное...', 'A poignant and funny coming-of-age story by beloved Swedish author Ulf Stark. Lasse doesn''t shine in school; he wears scuffed trousers, loves Elvis Presley, and causes mischief in the streets. But when his parents separate and his mother remarries into a wealthy, respectable household, Lasse finds himself pressured into becoming a prim model student. Torn between this new polished life and his loyalties to his gruff, bear-like working-class father, Lasse embarks on a quest to reconcile both worlds without losing his true self.', 'Dirljiva i duhovita priča o odrastanju čuvenog švedskog pisca Ulfa Starka. Laseu ne ide baš najbolje u školi; nosi izlizane pantalone, obožava Elvisa Prislija i pravi nestašluke po ulici. Ali kada mu se roditelji razvedu, a majka ponovo uda u uglednu i strogu porodicu, Lase se nađe pred teškim izborom između uloge uzornog dječaka i svog starog života uz mrzovoljnog, medveđeg oca. Nastojeći da pomiri dva sasvim različita svijeta, Lase pokušava da pronađe sopstveni put i dokaže da može učiniti nemoguće a ostati svoj.', 'Искренняя, щемящая и очень живая повесть о том, как непросто и важно остаться собой, даже если весь мир ждёт от тебя идеальности.', 'A tender and razor-sharp story about the guts it takes to dance to your own rock-and-roll tune when everyone is expecting perfection.', 'Nježna i topla priča o hrabrosti da plešeš u sopstvenom ritmu, čak i kada čitav svijet od tebe traži da budeš savršen.', '/covers/DP-0098.webp', '#3e6f8d', '7-9', 'ru', 'available', 'Для среднего и старшего школьного возраста. 5-е издание.', '["real","friends"]', '["growing up","family","identity","father and son","scandinavian literature"]', 1792836322695, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тумас-и-трассель-99', 'DP-0099', 'Тумас и Трассель', 'Tomas and Trassel', 'Tomas i Trasel', 'Йоста Кнутсон', 'Gösta Knutsson', 'Gesta Knutson', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Тумасу шесть, он сидит на веранде и ждет своего лучшего друга - лохматого смешного пса по имени Трассель. Обычно Трассель прибегает к Тумасу утром и они играют весь день напролет. Но сегодня Трасселя все нет и нет. Что, если с ним что-то случилось? Тумасу строго-настрого запрещено выходить из дома одному, но он все равно отправляется на поиски друга. Для дошкольного возраста.', 'Tomas is six years old, sitting on the porch and waiting for his best friend—a shaggy, funny dog named Trassel. Usually, Trassel dashes over in the morning, and they play together all day long. But today there is no sign of Trassel. Could something have happened to him? Tomas is strictly forbidden to leave home alone, but nothing will stop him from setting out on a brave rescue mission for his beloved friend.', 'Tomas ima šest godina, sjedi na verandi i čeka svog najboljeg prijatelja — čupavog, smiješnog psa po imenu Trasel. Obično Trasel dotrči ujutru i njih dvojica se igraju po cio dan. Ali danas Trasela nema pa nema. Da mu se nije nešto dogodilo? Tomasu je strogo zabranjeno da izlazi sam iz kuće, ali on ipak kreće u veliku potragu za svojim drugarom.', 'Трогательная и смелая история о том, что преданная дружба с лохматым псом способна победить любые строгие запреты и страхи.', 'A tender and brave story showing that true friendship with a shaggy pup is stronger than any house rules or fear.', 'Dirljiva i hrabra priča o tome kako pravo prijateljstvo sa čupavim psom može da pobijedi sve zabrane i strahove.', '/covers/DP-0099.webp', '#537c56', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["friends","animals","adventure"]', '["dogs","friendship","bravery","swedish literature"]', 1792836322695, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('урпо-и-турпо-два-веселых-медве-100', 'DP-0100', 'Урпо и Турпо два веселых медвежонка', 'Urpo and Turpo: Two Cheerful Little Bears', 'Urpo i Turpo: Dva vesela medvjedića', 'Ханелле Хуови, Юкка Лемметю', 'Hannele Huovi, Jukka Lemmetty', 'Hannele Huovi, Jukka Lemmetty', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Эта книга состоит из невероятно смешных, остроумных и добрых рассказов про двух милых плюшевых медвежат - Урпо и Турпо. Они живут в детской среди других игрушек, которые принадлежат девочке, мальчику и малышу. Медвежата очень любознательные и находчивые: они читают книги, играют в шахматы, строят рыцарские замки, то и дело попадая в комичные ситуации. Замечательно иллюстрированные истории про Урпо и Турпо взрослые полюбят не меньше чем дети! Для чтения взрослыми детям.', 'This charming book is packed with hilarious, witty, and heartwarming tales about two lovable teddy bears, Urpo and Turpo. Living in a nursery among other toys, these curious and inventive friends read books, play chess, construct knightly castles, and stumble into one comical predicament after another.', 'Ova šarmantna knjiga donosi nevjerovatno smiješne, duhovite i tople priče o dva neodoljiva plišana medvjedića – Urpu i Turpu. Živeći u dječijoj sobi među ostalim igračkama, ovi radoznali i snalažljivi drugari čitaju knjige, igraju šah, grade viteške dvorce i neprestano upadaju u komične nezgode.', 'Пока дети не видят, эти плюшевые непоседы читают книги, играют в шахматы и устраивают первоклассный кавардак — смеяться будете всей семьёй!', 'When the kids are away, these two clever teddy bears play chess and conquer castles, proving that life in the nursery is never boring!', 'Dok djeca ne gledaju, ova dva plišana drugara čitaju knjige, igraju šah i prave pravi veseli haos u dječijoj sobi!', '/covers/DP-0100.webp', '#e69a28', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","friends","adventure"]', '["teddy bears","toys","humor","friendship","read-aloud"]', 1792836322695, 1792845656352);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('стелла-и-седьмая-звезда-101', 'DP-0101', 'Стелла и седьмая звезда', 'Stella and the Seventh Star', 'Stela i sedma zvijezda', 'Унни Линделл, Фредрик Скавлан', 'Unni Lindell, Fredrik Skavlan', 'Unni Lindell, Fredrik Skavlan', '', 'Мар детства', NULL, NULL, 7, 10, 'middle', 'Нелегко быть маленьким привидением, особенно если на твою долю то и дело выпадают опасные приключения. Страшилка Стелла еще очень мала, но уже обладает несгибаемой волей и твердой верой в чудо, а также выполняет сложнейшие пируэты в воздухе. На этот раз ей предстоит головокружительный полёт на Седьмую звезду - надо спасать Тараторку Тилию. Затем Стелла окажется в самом сердце туманного Лондона. Вместе со своим лучшим другом Пиннеусом они прогуляются вдоль берега Темзы, побывают на экскурсии в Тауэре и увидят Большого Бена. Спастись от Гобеленовых призраков и найти Тилию Стелле помогут поэт Уильям Шекспир, сестра милосердия Флоренс Найтингейл и поэтесса Сильвия Плат. Унни Линделл не только знакомит читателей со взглядами и повадками привидений, но также рассказывает о литературе и философии, музыке и танце, любви и смерти.', 'Being a little ghost isn''t easy, especially when perilous adventures keep finding you! Young Stella may be tiny, but she possesses an unshakeable spirit, performs dazzling aerial pirouettes, and firmly believes in miracles. This time, she takes a dizzying flight to the Seventh Star to rescue Chatterbox Tilia, only to find herself in the misty heart of London. Exploring the Thames and the Tower of London alongside her best friend Pinneus, Stella outwits sinister tapestry phantoms with the unexpected help of William Shakespeare, Florence Nightingale, and Sylvia Plath.', 'Nije lako biti mali duh, posebno kada te na svakom koraku čekaju opasne avanture! Mala strašljivica Stela možda jeste sitna, ali posjeduje nesalomivu volju, izvodi nevjerovatne vazdušne piruete i čvrsto vjeruje u čuda. Ovoga puta kreće na vrtoglavi let do Sedme zvijezde kako bi spasila brbljivu Tiliju, a put je vodi pravo u maglovito srce Londona. Uz pomoć svog najboljeg prijatelja Pineusa, ali i duhova Vilijama Šekspira, Florens Najtingejl i Silvije Plat, Stela otkriva tajne Londonske kule i pravu snagu prijateljstva.', 'Обаятельное норвежское привидение покажет вам туманный Лондон и познакомит с призраками великих писателей!', 'Follow a brave little ghost on an acrobatic flight across foggy London to meet famous phantoms and rescue a dear friend!', 'Pridružite se hrabrom malom duhu u akrobatskom letu kroz magloviti London u potrazi za nestalom prijateljicom!', '/covers/DP-0101.webp', '#3b4371', '7-9', 'ru', 'available', 'Для детей от 7 до 14 лет', '["spooky","adventure","magic"]', '["ghosts","london","friendship","adventures","scandinavian literature"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('письма-с-моей-фермы-102', 'DP-0102', 'Письма с моей фермы', 'Letters from My Farm', 'Pisma sa moje farme', 'Маша Слоним', 'Masha Slonim', 'Maša Slonim', 'Таня Кормер', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Рассказы журналистки Маши Слоним о многочисленных животных, населяющих ее подмосковную ферму, - об их характерах, повадках и приключениях. Как конь Пушкин отомстил гнедому мерину за давнюю обиду, как попугай Жека подружился с мышами, как сбежал павлин Кузя и как провалился в печную трубу кот Вася, куда пропадала каждое лето кошка Пусси, как праздновал день рождения пес Арчи и многое другое. Впервые эти истории прозвучали на радио - в передаче Маши Слоним "Письма с фермы" на "Эхе Москвы", затем прошлой осенью вышла аудиокнига, ну а теперь - книга бумажная.', 'Journalist Masha Slonim shares delightful, true-life stories about the eccentric four-legged and feathered inhabitants of her countryside farm. Meet Pushkin the vindictive horse, Zheka the parrot who befriended mice, Kuzya the runaway peacock, and Vasya the cat who took an unexpected plunge down the chimney flue! Born as a beloved radio series, these warmhearted chronicles capture all the comedy, tenderness, and everyday chaos of country life with animals.', 'Novinarka Maša Slonim donosi tople i istinite priče o neobičnim životinjama koje dijele život na njenoj seoskoj farmi. Saznajte kako je konj Puškin poravnao stare račune, kako se papagaj Žeka sprijateljio sa miševima, kuda je bježao paun Kuzja i kako je mačak Vasja upao pravo u odžak! Nastale iz popularne radio-emisije, ove vesele i dirljive seoske crtice otkrivaju sav šarm i komične nezgode suživota sa mnogobrojnim ljubimcima.', 'Остроумные и душевные деревенские хроники о том, как упрямый конь, беглый павлин и кот-трубочист превращают обычную ферму в самое весёлое место на земле!', 'Heartwarming, witty rural dispatches proving that a mischievous horse, an escapee peacock, and a chimney-diving cat can turn any farm into the happiest comedy on earth!', 'Duhovite i tople seoske hronike koje dokazuju da svojeglavi konj, odbjegli paun i mačak u odžaku mogu svaku farmu pretvoriti u najsmješniju avanturu na svijetu!', '/covers/DP-0102.webp', '#628b48', '7-9', 'ru', 'available', 'Для среднего школьного возраста.', '["animals","funny","real"]', '["ферма","животные","юмор","деревня","рассказы"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тося-и-тайна-геодезиста-103', 'DP-0103', 'Тося и тайна геодезиста', 'Tosia and the Mystery of the Surveyor', 'Tosja i tajna geodete', 'Магдалена Мечницка', 'Magdalena Miecznicka', 'Magdalena Mječnjicka', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Если ты ребенок, никто не воспринимает тебя всерьез. И уж конечно не видит в тебе настоящего детектива. Даже когда вокруг все очень подозрительно: геодезист смотрит в бинокль, незнакомец прячет шрам под шарфом, а Йоланта готовится танцевать балет. Опустить руки? Как бы не так! Маленькая Тося упрямо ведет расследование. И пусть взрослые твердят, что у нее чересчур буйное воображение. Они вообще любят находить скучные объяснения даже самым необычным вещам. А ведь мир куда удивительней, чем кажется взрослым!', 'When you''re a kid, no one takes you seriously, and certainly nobody sees a true detective in you. Even when everything around seems suspicious: a surveyor peers through binoculars, a stranger conceals a scar beneath his scarf, and Jolanta is rehearsing ballet. Give up? Not a chance! Determined little Tosia launches her own investigation, unbothered by adults who dismiss it all as an overactive imagination.', 'Kad si dijete, niko te ne shvata ozbiljno, a ponajmanje kao pravog detektiva. Čak i kada je sve oko tebe krajnje sumnjivo: geodeta gleda kroz dvogled, nepoznati čovek krije ožiljak ispod šala, a Jolanta se sprema za balet. Odustati? Nema šanse! Mala Tosja tvrdoglavo vodi sopstvenu istragu, ne mareći što odrasli sve pripisuju njenoj bujnoj mašti.', 'Если взрослые твердят, что у вас слишком буйная фантазия, значит, вы напали на след самого настоящего заговора!', 'If grown-ups tell you that you''ve got an overactive imagination, it only means you''re hot on the trail of a real mystery!', 'Ako vam odrasli kažu da imate previše bujnu maštu, to samo znači da ste na tragu prave misterije!', '/covers/DP-0103.webp', '#e58e37', '7-9', 'ru', 'available', '"МА-МА МЫ-ЛА РА-МУ" - серия книг для первого чтения. Это первые книги для тех, кто уже научился читать. Для младшего школьного возраста.', '["funny","adventure"]', '["detective","mystery","investigation","childhood","imagination"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('почему-бы-и-нет--104', 'DP-0104', 'Почему бы и нет?', 'Why Not?', 'Zašto da ne?', 'Як Ривэ', 'Yak Rivais', 'Jak Rive', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Кто такие школдунчики? Это на первый взгляд обычные парижские школьники, которые вдруг обнаруживают в себе неожиданные способности. То Фабрис начинает получать знания из книг, поедая их. То Аврора отправляется в Страну чудес и превращает папину машину в карету. То Брюно начинает делать все шиворот-навыворот, а Орели взламывает банковский сейф одним пальцем... Этот мир, где смешиваются реальность и фантастика, юмор и любовь, придумал и проиллюстрировал классик французской детской литературы, лауреат более тридцати литературных премий Як Ривэ.', 'Meet the little wizard-pupils of Paris! At first glance, they are ordinary schoolchildren, but suddenly they develop utterly astonishing superpowers. Fabrice starts absorbing knowledge by eating book pages, Aurore wanders into Wonderland and turns her dad''s car into a pumpkin carriage, Bruno does everything upside down, and Aurélie cracks bank safes with a single touch. French children''s classic Yak Rivais blends whimsical magic, sharp humor, and real school life into irresistible stories.', 'Upoznajte pariske školarce-čarobnjake! Na prvi pogled to su sasvim obična djeca, sve dok ne otkriju nevjerovatne supermoći. Fabris počinje da uči tako što doslovno jede stranice knjiga, Avrora pretvara tatin automobil u kočiju, Bruno sve radi naopako, a Oreli otvara bankarske sefove samo jednim prstom. Klasični pisac francuske književnosti za djecu, Jak Rive, stvara svijet prepun mašte, humora i vragolija.', 'Осторожно: после этих историй вам наверняка захочется съесть учебник для пятерки или превратить семейный автомобиль в карету!', 'Beware: after reading these tales, you might feel an irresistible urge to devour an encyclopedia for top grades or turn the family car into a carriage!', 'Pazite se: nakon ovih priča sigurno ćete poželjeti da pojedete udžbenik radi petice ili pretvorite porodični auto u kočiju!', '/covers/DP-0104.webp', '#d95c2b', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","magic","friends"]', '["school","magic","humor","short stories","french literature"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('привет-маттиас--105', 'DP-0105', 'Привет, Маттиас!', 'Hello, Mattias!', 'Zdravo, Matijas!', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Летом спешить некуда, можно просто радоваться жизни. Надоело искать сокровища - пора строить городок для улиток. Тут будут домики, больница, даже церковь. Еще каникулы - лучшее время, чтобы собрать коллекцию билетиков, банок или зубов. Или искать страшного тролля. Но настоящий праздник наступит, когда приедет толстый дядя Клупме-Думп. Он любит прыгать с дерева в кучу сухой листвы и кидаться подушками. Это вторая книга из трилогии о Маттиасе и его друзьях. Ее автор - Барбру Линдгрен. Талант писательницы открыла Астрид Линдгрен, ее однофамилица. Серия о Маттиасе стала дебютом Барбру, истории о нем публиковали в издательстве "Raben & Sjogren", где редактором работала Астрид. С тех пор книги были переведены на тридцать языков, издавались в СССР и России. Сама Барбру стала лауреатом престижных премий Ханса Кристиана Андерсена и... своей однофамилицы Астрид.', 'There is no rush in the summer—just pure joy. When treasure hunting gets old, it is time to build a miniature city for snails, complete with cozy houses, a hospital, and even a church. Summer break is also the best time to collect bus tickets, tin cans, or lost teeth, and perhaps track down a mysterious troll. But the real celebration begins when cheerful Uncle Klumpe-Dumpe arrives, ready to leap into leaf piles and spark epic pillow fights! A heartwarming Scandinavian classic about innocent adventures and the sweet freedom of childhood.', 'Ljeti nema žurbe, samo čista radost života. Kad dosadi traženje blaga, pravo je vrijeme da se napravi gradić za puževe sa kućicama, bolnicom, pa čak i crkvom. Raspust je savršen za sakupljanje voznih karata, konzervi ili ispalih zubića, ali i za potragu za strašnim trolom. Ipak, pravo slavlje počinje kad u posjetu stigne veseli ujak Klumpe-Dumpe, spreman za skakanje u suvo lišće i legendarne borbe jastucima! Topla i bezbrižna skandinavska priča o pravom djetinjstvu.', 'Самая уютная и озорная книга о лете, в котором есть время и для больницы улиток, и для битвы подушками с любимым дядей!', 'The coziest, sunniest tale of childhood summer, where building snail hospitals and pillow-fighting with goofy uncles take center stage!', 'Najtoplija i najvedrija priča o ljetnjem raspustu, u kom ima mjesta i za bolnicu za puževe i za urnebesne borbe jastucima!', '/covers/DP-0105.webp', '#e2a03f', '7-9', 'ru', 'available', 'Для дошкольного и младшего школьного возраста.', '["funny","friends","real"]', '["summer","childhood","friendship","family","scandinavian literature"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лето-маттиаса-106', 'DP-0106', 'Лето Маттиаса', 'Mattias''s Summer', 'Matijasovo ljeto', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Маттиас, Пелле Маленький и Пончик, как и все дети, знают толк в радостях жизни. Они сумеют надежно спрятать клад, спасут выпавшего из гнезда птенчика и выручат друга, угодившего в открытый люк. Мир вокруг них добрый и надежный, в нем всегда помогут. Пекарь заступится за Маттиаса, прохожий подарит блестящую крону, а полицейские угостят булочками и малиновым соком. Эта книга - первая из трилогии о Маттиасе и его друзьях. Ее автор - Барбру Линдгрен. Талант писательницы открыла Астрид Линдгрен, ее однофамилица. Серия о Маттиасе стала дебютом Барбру, истории о нем публиковали в издательстве "Raben & Sjogren", где редактором работала Астрид. С тех пор книги были переведены на тридцать языков, издавались в СССР и России. Сама Барбру стала лауреатом престижных премий Ханса Кристиана Андерсена и... своей однофамилицы Астрид.', 'Mattias, Little Pelle, and Ponchik know how to relish life''s greatest pleasures. They can hide a treasure in the safest spot, rescue a chick that fell from its nest, and save a pal stuck in an open manhole. The world around them is warm, safe, and kind—a baker sticks up for Mattias, a friendly passerby gifts a shiny coin, and policemen treat the kids to sweet buns and raspberry juice. This beloved classic by Astrid Lindgren Memorial Award winner Barbro Lindgren captures the sunny, unforgettable magic of childhood summers.', 'Matijas, Mali Pele i Pončik tačno znaju kako se uživa u djetinjstvu: znaju gdje sakriti pravo blago, kako spasiti ptića ispala iz gnijezda i kako izvući druga koji je upao u otvoren šaht. Svijet oko njih je topao i siguran — pekar staje u Matijasovu odbranu, prolaznik daruje sjajni novčić, a policajci časte mekanim pecivom i sokom od maline. Ova topla priča čuvene švedske spisateljice Barbro Lindgren podsjeća na sunčane, bezbrižne dane u kojima je svaka ulica bila puna avantura.', 'Тёплая и светлая скандинавская классика о том самом золотом лете из детства, когда каждый день полон открытий, а все взрослые вокруг на твоей стороне.', 'A warm, sun-drenched Scandinavian classic that captures the pure wonder of childhood summers when every corner hides an adventure and kind neighbors always lend a hand.', 'Topla skandinavska priča o onom zlatnom djetinjstvu kada je svaki ljetnji dan bio nova avantura, a komšiluk pun dobrih prijatelja.', '/covers/DP-0106.webp', '#e2943b', '7-9', 'ru', 'available', 'Для дошкольного и младшего школьного возраста.', '["friends","real","adventure"]', '["summer","friendship","childhood","scandinavia","growing up"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('славный-пес-мактавиш-107', 'DP-0107', 'Славный пес Мактавиш', 'Good Dog McTavish', 'Dobar pas Maktaviš', 'Мег Розофф', 'Meg Rosoff', 'Meg Rozof', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Первая книга из серии про пса Мактавиша, в которой рассказывается о том, как он нашел свой дом и перевоспитал семью Перси. Мег Розофф - всемирно известная британская писательница, прославившаяся своими книгами для подростков. "Милая семейная книжка про замечательного пса, пронизанная причудливым юмором". The Bookseller', 'The first book in the heartwarming McTavish series reveals how an observant rescue dog finds a new home and gently re-educates the chaotic Peachey family. Award-winning author Meg Rosoff serves up a delightful, witty tale of domestic anarchy solved by four clever paws.', 'Prva knjiga iz serijala o psu Maktavišu govori o tome kako je jedan mudri pas iz azila pronašao dom i strpljivo prevaspitao haotičnu porodicu Piči. Nagrađivana autorka Meg Rozof donosi divnu, duhovitu priču o spasavanju jedne porodice na pseći način.', 'Если в вашем доме царит хаос и никто не хочет готовить ужин, срочно заведите пса Мактавиша — он наведёт образцовый порядок!', 'If household chaos is spiraling out of control, you need McTavish the rescue dog to gently whip your family into shape!', 'Ako u vašoj kući vlada rasulo, potreban vam je pas Maktaviš da diskretno dovede porodicu u savršen red!', '/covers/DP-0107.webp', '#e69c3a', '7-9', 'ru', 'available', '"МА-МА МЫ-ЛА РА-МУ" - серия книг для первого чтения. Это первые книги для тех, кто уже научился читать. Для дошкольного и младшего школьного возраста.', '["funny","animals","friends"]', '["dogs","family","humor","pets","rescue dog"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мактавиш-и-пряники-108', 'DP-0108', 'Мактавиш и пряники', 'McTavish Takes the Biscuit', 'Maktaviš i medenjaci', 'Мег Розофф', 'Meg Rosoff', 'Meg Rozof', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Третья книга из серии про пса Мактавиша, в которой рассказывается о том, как он помогал папе Перси испечь Версальский дворец. Мег Розофф - всемирно известная британская писательница, прославившаяся своими книгами для подростков. "Милая семейная книжка про замечательного пса, пронизанная причудливым юмором".', 'The third adventure in the beloved McTavish series finds the wonderfully perceptive dog gently rescuing Dad Percy from culinary chaos as he attempts to bake an ambitious gingerbread Palace of Versailles. A delightfully witty and cozy family tale by award-winning author Meg Rosoff.', 'Treća knjiga u serijalu o mudrom psu Maktavišu prati njegovu misiju spašavanja tate Persija od kulinarske katastrofe dok pokušava da napravi dvorac Versaj od medenjaka. Šarmantna i topla porodična priča britanske autorke Meg Rozof, prepuna suptilnog humora.', 'Когда папа решает испечь съедобный Версаль, только мудрый пёс Мактавиш способен спасти кухню от катастрофы!', 'When Dad sets out to bake an edible Palace of Versailles, only the clever dog McTavish can steer the kitchen clear of catastrophe!', 'Kad tata odluči da ispeče jestivi Versaj, samo mudri pas Maktaviš može spasiti kuhinju od potpunog haosa!', '/covers/DP-0108.webp', '#d27d3c', '7-9', 'ru', 'available', '"МА-МА МЫ-ЛА РА-МУ" - серия книг для первого чтения. Это первые книги для тех, кто уже научился читать. Для дошкольного и младшего школьного возраста.', '["funny","animals","friends"]', '["dogs","family","baking","humor","clever pets"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мактавиш-вырывается-на-волю-109', 'DP-0109', 'Мактавиш вырывается на волю', 'McTavish Goes Wild', 'Mektaviš ide u divljinu', 'Мег Розофф', 'Meg Rosoff', 'Meg Rozof', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Вторая книга из серии про пса Мактавиша, в которой рассказывается о том, как он ходил в поход вместе с семьей Перси. Мег Розофф - всемирно известная британская писательница, прославившаяся своими книгами для подростков. "Милая семейная книжка про замечательного пса, пронизанная причудливым юмором".', 'The Peachey family decides to go camping, but they are utterly unprepared for the great outdoors! Luckily, their wise and unflappable dog, McTavish, is on hand to keep disaster at bay and teach his humans what real wild adventure is all about.', 'Porodica Piči odlučuje da ode na kampovanje, ali su potpuno nespremni za život u prirodi! Srećom, njihov mudri i smireni pas Mektaviš je tu da spriječi katastrofu i nauči svoje ljude šta je prava avantura.', 'Если вы думаете, что поход с семьёй — это просто, приготовьтесь к уморительному спасению ситуации самым разумным псом на свете!', 'If you think family camping is easy, let the wisest rescue dog in the world show you how to survive tents, rain, and chaotic humans!', 'Ako mislite da je kampovanje sa porodicom mačji kašalj, dopustite najpametnijem psu na svijetu da vas provede kroz ovu urnebesnu avanturu!', '/covers/DP-0109.webp', '#3e8e58', '7-9', 'ru', 'available', '"МА-МА МЫ-ЛА РА-МУ" - серия книг для первого чтения. Это первые книги для тех, кто уже научился читать. Для дошкольного и младшего школьного возраста.', '["funny","adventure","animals"]', '["dogs","camping","family","humor","outdoor adventure"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рождество-в-лесу-110', 'DP-0110', 'Рождество в лесу', 'Christmas in the Forest', 'Božić u šumi', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Эва Эриксон', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Ворчливый одинокий гном Бука развесил сушиться варежки. Но вот незадача — ветер унес их. А когда Бука погрозил ветру кулаком, озорник сорвал с его головы и красный колпак. Разве их теперь поймаешь! В лесу под старым дубом живет большая семья кроликов: мама, папа, тетя и дядя, дедушка и детей — не сосчитать, ведь они все время носятся, кричат, скачут. Два крольчонка, Нина и Ника, находят среди листьев и мха красный колпак, унесенный ветром у гнома, который всегда приходит в лес на Рождество. Но что такое Рождество? Белки и вороны рассказали, что Рождество — это самый радостный праздник. Как его встречать, никто не знает, но все ждут его с нетерпением и готовятся к приходу гнома: сочиняют радостную гномичью песню, пекут вкусности, прибираются в доме, готовят подарки и наряжают из всякой всячины дерево в лесу. Но гнома все нет и нет. Тогда крольчата отправляются на его поиски!', 'Grumpy solitary gnome Vrese loses his red hat and mittens to a gust of wind, while deep in the woods a lively rabbit family finds them and eagerly prepares for the arrival of the mysterious Christmas Tomte. But how do you celebrate Christmas if you''ve never seen it before? Filled with festive songs, treats, and boundless anticipation, the forest creatures set out to discover true holiday magic in this heartwarming winter tale.', 'Mrzovoljni i usamljeni patuljak Vrese gubi svoju crvenu kapu na vjetru, a pod starim hrastom velika porodica zečeva pronalazi kapu i saznaje za dolazak čudesnog Božića. Šumski stanovnici ne znaju tačno kako se Božić slavi, ali pripremaju poslastice, ukrašavaju jelku i s nestrpljenjem čekaju gosta — a kad on zakasni, mali zečevi kreću u potragu za pravim prazničnim čudom.', 'Невероятно уютная и трогательная скандинавская сказка, доказывающая: даже самое сердитое сердце обязательно растает от тепла и заботы.', 'An utterly charming Scandinavian tale proving that even the grumpiest heart can be melted by a little forest kindness.', 'Nevjerovatno topla skandinavska bajka koja dokazuje da se i najmrzovoljnije srce može otopiti uz malo zečije dobrote.', '/covers/DP-0110.webp', '#a83232', '7-9', 'ru', 'available', 'дошкольный и младший школьный', '["magic","friends","animals"]', '["christmas","winter","rabbits","kindness","forest"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лето-в-лесу-111', 'DP-0111', 'Лето в лесу', 'Summer in the Forest', 'Ljeto u šumi', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Жители леса готовятся к Иванову дню, празднику любви и колдовских чар, и вспоминают ворчливого гнома Буку, с которым зимой они встречали Рождество. Но накануне Иванова дня в лесу разыгралась буря. Звери и птицы остались без крова, им срочно нужна помощь! Где же Бука, где добрый сердитый гном?.. Ульф Старк и Эва Эриксон рассказывают свою сказку, словно плетут венок на Иванов день — из красочных образов, смеха и любви. Это вторая повесть о жителях леса, знакомых читателю по книге «Рождество в лесу».', 'The forest creatures are eagerly preparing for Midsummer Eve, recalling their winter adventure with Grump the grumpy gnome. But just before the celebration, a fierce storm ravages the woods, leaving birds and beasts without shelter. Where is Grump when they need him most? Ulf Stark weaves a tender, luminous summer tale woven with laughter, community, and the quiet magic of helping one another.', 'Šumski stanovnici se pripremaju za Ivanjdan, praznik ljubavi i čarolije, sjećajući se mrzovoljnog patuljka Buke s kojim su zimus dočekali Božić. Ali uoči praznika, šumu pogađa snažna oluja i životinje ostaju bez doma. Gdje je sada Buka, taj dobrodušni gunđalo? Ulf Stark donosi toplu i dirljivu priču punu humora, nježnosti i zajedništva.', 'Ворчливые гномы тоже умеют спасать праздники — особенно когда над лесом гремит гроза, а друзьям так нужно тепло!', 'Even the grumpiest gnome has a heart of gold when a wild summer storm threatens his woodland friends!', 'Čak i najmrzovoljniji patuljak ima zlatno srce kada ljetnja oluja zaprijeti njegovim šumskim prijateljima!', '/covers/DP-0111.webp', '#4a7c59', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["magic","friends","animals"]', '["forest","animals","gnomes","summer","kindness"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('взгляд-кролика-112', 'DP-0112', 'Взгляд кролика', 'A Rabbit''s Eyes', 'Pogled zeca', 'Хайтани Кэндзиро', 'Kenjiro Haitani', 'Kendžiro Haitani', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Молодая учительница Фуми Котани приходит работать в начальную школу, расположенную в промышленном районе города Осака. В классе у Фуми учится сирота Тэцудзо - молчаливый и недружелюбный мальчик, которого, кажется, интересуют только мухи. Терпение Котани, ее готовность понять и услышать ребенка помогают ей найти с Тэцудзо общий язык. И оказывается, что иногда достаточно способности одного человека непредвзято взглянуть на мир, чтобы жизнь многих людей изменилась - к лучшему. Роман известного японского писателя Кэндзиро Хайтани "Взгляд кролика" (1974) выдержал множество переизданий (общим тиражом более двух миллионов экземпляров), был переведен на английский, широко известен в Великобритании, США и Канаде и был номинирован на медаль Ганса Христиана Андерсена.', 'When young teacher Fumi Kotani arrives at an elementary school in an industrial district of Osaka, she meets Tetsuzo—a silent, brooding boy obsessed solely with flies. Through patience, empathy, and genuine listening, Kotani-sensei discovers Tetsuzo''s hidden brilliance. Kenjiro Haitani''s internationally acclaimed Japanese classic is a deeply moving story about seeing the world without prejudice and finding the quiet wonders within every child.', 'Mlada učiteljica Fumi Kotani započinje rad u osnovnoj školi u industrijskom dijelu Osake. U njenom razredu je Tetsuzo — ćutljivi, povučeni dječak koga naizgled zanimaju samo muve. Strpljenje i spremnost učiteljice da istinski čuje dijete pomažu joj da pronađe put do njegovog srca. Ovaj dirljivi japanski klasik podsjeća nas koliko prihvatanje i pogled bez predrasuda mogu promijeniti nečiji život nabolje.', 'Трогательная и светлая история о том, как искреннее учительское сердце способно разглядеть чудо даже в молчаливом любителе мух.', 'A deeply moving Japanese classic proving that true empathy and patience can uncover brilliance in the most misunderstood child.', 'Dirljiva i topla priča o tome kako otvoreno srce jedne učiteljice može promijeniti život dječaka kojeg su svi otpisali.', '/covers/DP-0112.webp', '#5b7a58', '7-9', 'ru', 'available', 'Для среднего и старшего школьного возраста. 5-е издание.', '["real","friends"]', '["school","japan","empathy","teachers","growing up"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('глаз-волка-113', 'DP-0113', 'Глаз волка', 'Eye of the Wolf', 'Oko vuka', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'В Парижском зоопарке происходят невероятные события: одноглазый полярный Волк и маленький африканский мальчик молча рассказывают друг другу истории, одна удивительнее другой. В двух зрачках - мальчишечьем и волчьем - мелькают, сменяя друг друга, заснеженная Тундра, желтая, серая и зеленая Африки. Где-то там, в прошлом, звучат выстрелы, раздаются крики, шум пропеллеров и вой шакалов, вспыхивают золотые блестки и дождь обволакивает джунгли. Волк и мальчик пристально смотрят друг на друга. И чем больше узнают друг друга, тем яснее понимают, что будь ты волком или мальчиком, верблюдом или гепардом - если тебе хватило терпения и мудрости услышать историю чужого сердца и откликнуться на нее, ты больше не одинок. Оставаясь по разные стороны решетки зоопарка, Волк и мальчик по имени Африка сломают клетку недоверия и подозрительности - клетку, в которой может очутиться каждый и из которой не выбраться поодиночке.', 'In a Paris zoo, a silent encounter sparks a profound journey: a one-eyed polar wolf and a boy named Africa gaze into each other''s eyes. Through their pupils, breathtaking memories unfurl—from the frozen Alaskan tundra to the yellow, gray, and green expanses of Africa. Separated by cold iron bars, they slowly unlock each other''s past, breaking down the invisible cages of fear, loss, and distrust to discover the healing power of shared stories.', 'U pariskom zoološkom vrtu dešava se tiho čudo: jednooki polarni vuk i dječak po imenu Afrika bez riječi dijele svoje nevjerovatne priče. Gledajući se pravo u oči, oni oživljavaju zaboravljene pejzaže — od sniježne tundre do dalekih savana i džungli. Stojeći sa suprotnih strana rešetki, vuk i dječak srušiće nevidljivi kavez nepovjerenja, dokazujući da se uz malo strpljenja i empatije nijedno srce više ne mora osjećati usamljeno.', 'Пронзительная притча о том, как один долгий взгляд способен растопить лёд недоверия между диким зверем и человеком.', 'A deeply moving fable proving that an open heart and a single shared look can melt away any cage of loneliness.', 'Dirljiva priča o tome kako jedan jedini iskren pogled može srušiti rešetke i istopiti led nepovjerenja.', '/covers/DP-0113.webp', '#c27d38', '7-9', 'ru', 'available', 'Для среднего школьного возраста.', '["animals","friends","adventure"]', '["wolf","friendship","africa","empathy","zoo"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-одежде-человека-сфинкс-или-р-114', 'DP-0114', 'В одежде человека; Сфинкс или робот', 'In Human Clothing; Sphinx or Robot', 'U ljudskoj odjeći; Sfinga ili robot', 'Леена Крун', 'Leena Krohn', 'Leena Krohn', '', 'Самокат', NULL, NULL, 7, 10, 'middle', '"В одежде человека" - история о пеликане, который мечтал стать человеком. Мальчик Эмиль открывает ему странный мир человеческих существ, живущих в большом городе. В сборник также вошла повесть "Сфинкс или робот" - книга, главы которой могут быть прочитаны в любом порядке. И все же это вполне связная история девочки Лидии, живущей в мире, где законы физики растягиваются и выворачиваются наизнанку, создавая параллельную реальность. Там происходят странные вещи, но Лидия относится к ним с детской непосредственностью и открытостью - и читатель вместе с ней открывает мир и ищет ответы на вопросы.', '"In Human Clothing" is a thoughtful and witty story about a pelican who dreams of living as a human, guided through the peculiar urban world by a boy named Emil. The collection also includes "Sphinx or Robot", an innovative novella whose chapters can be read in any order. It follows Lydia through a reality where the laws of physics bend and turn inside out, inviting curious young thinkers to look at everyday life with wonder and ask big questions.', '„U ljudskoj odjeći“ je neobična i topla priča o pelikanu koji želi da postane čovjek, a dječak Emil mu otkriva čudnovati svijet velikog grada. U knjizi se nalazi i novela „Sfinga ili robot“, čija se poglavlja mogu čitati bilo kojim redosljedom. Kroz radoznale oči đevojčice Lidije, u svijetu đe se zakoni fizike izvrću naopačke, čitaoci otkrivaju paralelnu stvarnost i traže odgovore na duboka životna pitanja.', 'Готовы взглянуть на мир людей удивлёнными глазами пеликана в пальто и разгадать законы параллельной реальности?', 'Ready to see our human world through the bewildered eyes of a stylish pelican and explore mind-bending parallel realities?', 'Jeste li spremni da pogledate svijet ljudi očima otmjenog pelikana i riješite zagonetke paralelne stvarnosti?', '/covers/DP-0114.webp', '#3f7685', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["magic","animals","friends"]', '["scandinavian literature","philosophical tales","city life","friendship","imagination"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('манолито-очкарик-115', 'DP-0115', 'Манолито Очкарик', 'Manolito Four-Eyes', 'Manolito Naočarko', 'Эльвира Линдо', 'Elvira Lindo', 'Elvira Lindo', '', 'Самокат', NULL, NULL, 7, 10, 'middle', '"Манолито Очкарик" - прежде всего честное и ироничное повествование о повседневности, увиденной и осмысленной современным ребенком, в чьем сознании телевизионные клише переплетаются с наблюдениями за реальными миром, плодами домашнего и школьного воспитания и собственной жизненной философией. Символ современной испанской литературы для детей, Манолито олицетворяет собой ребенка нашего времени, узнаваемого и сверстниками, и их родителями - независимо от того, в какой стране они живут..', 'Manolito Four-Eyes is an honest, witty chronicle of everyday life through the eyes of an outspoken boy from Madrid, whose world is a hilarious blend of television cliches, schoolyard drama, and homegrown philosophy. A modern classic of Spanish children''s literature, Manolito is instantly recognizable and utterly endearing to kids and parents around the globe.', '„Manolito Naočarko” je iskrena i neodoljivo duhovita priča o svakodnevici viđenoj očima dječaka iz radničkog predgrađa Madrida, u čijim se mislima miješaju televizijske fraze, školske zavrzlame i lična životna mudrost. Pravi klasik savremene španske književnosti, Manolito je junak u kome se lako prepoznaju i djeca i njihovi roditelji.', 'Приготовьтесь хохотать до слёз над буднями самого болтливого и обаятельного очкарика из спального района Мадрида!', 'Get ready to laugh out loud at the everyday adventures of Madrid''s most talkative and charming four-eyed kid!', 'Spremite se za glasan smijeh uz svakodnevne avanture najbrbljivijeg i najšarmantnijeg naočarka iz Madrida!', '/covers/DP-0115.webp', '#e67e22', '7-9', 'ru', 'available', 'Для детей младшего и среднего школьного возраста.', '["funny","real","friends"]', '["humor","school","family","growing up","neighborhood"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('собака-пес-116', 'DP-0116', 'Собака Пес', 'Dog', 'Pas zvani Pas', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', 'Татьяна Кормер', 'Самокат', NULL, NULL, 7, 10, 'middle', 'В этом мире, где несчастных собак постоянно подстерегают опасности: падающие холодильники, ревущие автомобили, ловцы бродячих животных и просто злые люди, выжить — уже большое дело. Но просто выжить — мало. У каждой настоящей собаки есть в жизни главная цель. Маленький пес, герой этой книги, пройдет долгий путь от свалки под Ниццей до парижской квартиры, прежде чем достигнет этой цели — воспитает себе настоящего друга. Об этом — фантастическая и одновременно правдивая история, рассказанная французским писателем и педагогом Даниэлем Пеннаком.', 'Surviving in a world of roaring cars, dogcatchers, and abandoned landfills near Nice is tough, but this scruffy little dog has an even bigger mission in mind: to find and patiently train a human friend of his own. A touching, adventurous, and delightfully wise story of loyalty, growing up, and mutual love by beloved French author Daniel Pennac.', 'Preživjeti u svijetu punom jurećih automobila, šintera i opasnosti na smetlištu kraj Nice nije lako, ali ovaj neugledni pas ima mnogo veći cilj — da pronađe i strpljivo vaspita svog čovjeka. Dirljiva, mudra i avanturistička priča slavnog francuskog pisca Danijela Penaka o tome kako izgleda pravo i ravnopravno prijateljstvo.', 'Трогательная и остроумная история о том, что не только люди приручают собак, но и мудрые псы терпеливо воспитывают своих капризных хозяев.', 'A touching and witty reminder that sometimes it''s not humans who adopt dogs, but wise dogs who patiently train their humans!', 'Dirljiva i duhovita priča koja nas podsjeća da ponekad ne biraju ljudi pse, već mudri psi strpljivo vaspitavaju svoje vlasnike!', '/covers/DP-0116.webp', '#d4883b', '7-9', 'ru', 'available', 'Для детей младшего и среднего школьного возраста.', '["animals","friends","adventure"]', '["dogs","friendship","loyalty","paris","pets"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маяк-на-омаровых-рифах-117', 'DP-0117', 'Маяк на Омаровых рифах', 'The Lighthouse on the Lobster Cliffs', 'Svjetionik na Jastogovim grebenima', 'Джеймс Крюс', 'James Krüss', 'Džejms Kris', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Джеймс Крюс (1926-1997) - известный немецкий детский писатель, лауреат Международной премии имени Г.-Х. Андерсена. Русские читатели помнят его по книгам "Тим Талер, или Проданный смех" и "Мой прадедушка, герои и я". А немецкие дети знают, что Крюс - еще и замечательный поэт! Впервые изданная по-русски книга "Маяк на Омаровых рифах" - это собрание разнообразных историй и сказок в стихах и прозе. Действие книжки разворачивается вблизи острова Гельголанд - родины писателя, - где смотритель маяка старик Иоганн, чайка Александра и другие герои рассказывают друг другу истории - хорошие и складные, и с намеком: про рыбий карнавал, про маленький желтый трамвайчик, про маэстро Погодника или про ловца звезд... И всякий раз читатель оказывается в самых разных уголках мира - стоит только захотеть! И открыть книжку Джеймса Крюса...', 'Perched on the rugged cliffs near the island of Heligoland, old lighthouse keeper Johann, Alexandra the seagull, and their friends gather to spin enchanting tales in poetry and prose. From a dazzling underwater fish carnival to the legend of a star catcher and a runaway yellow tram, this whimsical collection by Hans Christian Andersen Medalist James Krüss carries readers to the farthest corners of imagination right from the cozy glow of the lighthouse lantern.', 'Na stjenovitim liticama ostrva Helgoland, stari svjetioničar Johan, galeb Aleksandra i njihovi neobični prijatelji okupljaju se da pripovijedaju čudesne priče u stihu i prozi. Od podvodnog karnevala riba do legende o lovcu na zvijezde i malom žutom tramvaju, ova topla i maštovita zbirka bajki Džejmsa Krisa vodi male čitaoce na čarobna putovanja širom svijeta — pravo iz udobne svjetioničarske kule.', 'Заварите чай, завернитесь в плед и поднимитесь на маяк, где чайка и старый смотритель раскроют перед вами самые диковинные сказки со всего света.', 'Brew some tea, wrap yourself in a blanket, and climb the lighthouse stairs, where a kind keeper and a wise seagull are waiting to spin the coziest seaside tales.', 'Skuvajte čaj, ušuškajte se pod ćebe i popnite se na svjetionik, gdje vas stari svjetioničar i mudri galeb čekaju sa najljepšim morskim pričama.', '/covers/DP-0117.webp', '#1f5975', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["magic","adventure","friends"]', '["lighthouse","sea tales","storytelling","poetry","islands"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лошадь-без-головы-118', 'DP-0118', 'Лошадь без головы', 'The Horse Without a Head', 'Konj bez glave', 'Поль Берна', 'Paul Berna', 'Pol Berna', '', 'Теревинф', NULL, NULL, 7, 10, 'middle', 'Франция, начало 1950-х годов... Вся страна взбудоражена громким преступлением: из поезда Винтимилья-Париж похищены 100000000 франков! Об этом трубят газетные заголовки, на поиски преступников брошены лучшие сыщики страны. В это же время в маленьком городке Лювиньи совершена еще одна кража. Но она не интересует журналистов, и даже местный полицейский спокоен: невелика беда - у детей с улицы Маленьких Бедняков стащили их игрушечную трехколесную лошадь. Кому она могла понадобиться - старая, облезлая, к тому же давно лишившаяся головы!?', 'France, the early 1950s... The whole country is shaken by a sensational crime: a hundred million francs have been stolen from the Ventimiglia–Paris express! While the nation''s best detectives hunt for the thieves, another theft takes place in the small town of Louvigny. No journalists care, and the local policeman shrugs it off: a gang of kids from the poor quarter had their battered, headless three-wheeled toy horse stolen. Who could possibly want an old, ragged toy—and could it be tied to the heist of the century?', 'Francuska, početak 1950-ih... Čitava zemlja bruji o velikoj pljački: iz voza Ventimilja–Pariz ukradeno je sto miliona franaka! Novine vrište sa naslovnica, a najbolji detektivi tragaju za krivcima. U isto vrijeme, u gradiću Luvinji, dogodila se još jedna krađa. Novinari ne mare, a lokalni policajac samo odmahuje rukom: djeci iz siromašnog kvarta ukraden je njihov stari trotočkaš — drveni konj bez glave. Kome bi uopšte trebala ova otrcana igračka i kakvu to tajnu krije?', 'Кто сказал, что для раскрытия преступления века нужны взрослые сыщики, если есть банда верных друзей и деревянный конь на колёсиках?', 'Who needs top-tier detectives to crack the crime of the century when you have a brave gang of kids and a headless toy horse on wheels?', 'Kome trebaju odrasli detektivi za pljačku vijeka kad družina klinaca ima drvenog konja na točkićima i nos za misterije?', '/covers/DP-0118.webp', '#7b4832', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["adventure","friends"]', '["detective","mystery","gang of friends","france","childhood"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('собачья-жизнь-и-другие-рассказ-119', 'DP-0119', 'Собачья жизнь и другие рассказы', 'A Dog''s Life and Other Stories', 'Pseći život i druge priče', 'Людвик Ашкенази', 'Ludvík Aškenazy', 'Ludvik Aškenazi', '', 'Теревинф', NULL, NULL, 7, 10, 'middle', 'Чешский писатель и поэт Людвик Ашкенази по-русски был издан единожды - в 1967 году. В мире он более всего известен как детский автор (даже премирован Государственной премией ФРГ за лучшую детскую книгу). В наше издание вошли повести и рассказы без "возрастного ценза" - они адресованы всем, достаточно взрослым, чтобы читать про любовь и войну, но еще недостаточно старым, чтобы сказать: "Я все это и без того знаю".', 'Czech author and poet Ludvík Aškenazy was celebrated worldwide for his delicate, poignant tales, winning the prestigious German Youth Literature Prize. This collection brings together touching stories with no real age barrier—written for anyone mature enough to read about love, resilience, and compassion, yet still young at heart enough to marvel at the world.', 'Češki pisac i pjesnik Ludvik Aškenazi širom svijeta je proslavljen po svojim nježnim i poetičnim pričama za djecu, za koje je nagrađen i prestižnom njemačkom nagradom za dječiju književnost. Ova zbirka okuplja tople pripovijetke bez starosnih granica — namijenjene svima koji su dovoljno zreli da čitaju o ljubavi i životu, a još uvijek radoznali prema svijetu oko sebe.', 'Трогательные, мудрые и пронзительно добрые истории чешского классика о собаках, людях и самых главных вещах на свете.', 'Tender, witty, and deeply philosophical tales about dogs, humans, and life''s gentle truths that resonate with children and grown-ups alike.', 'Nježne, mudre i tople priče o psima, ljudima i velikim istinama koje podjednako dotiču i djecu i odrasle.', '/covers/DP-0119.webp', '#b97a47', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["animals","friends","real"]', '["dogs","short stories","kindness","philosophy","czech literature"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('детские-этюды-120', 'DP-0120', 'Детские этюды', 'Children''s Etudes', 'Dječje etide', 'Людвик Ашкенази', 'Ludvik Askenazy', 'Ludvik Aškenazi', '', 'Теревинф', NULL, NULL, 7, 10, 'middle', '"Детские этюды" - не просто отцовский дневник, запись наблюдений о подрастающем сыне, свод его трогательных высказываний и забавных поступков. Книга фиксирует процесс превращения реальных событий в факт искусства, в литературу.', '"Children''s Etudes" is far more than just a father''s diary observing his growing son, full of touching quotes and humorous antics. This poetic book captures the delicate process of everyday life turning into pure literary art.', '„Dječje etide“ nijesu samo očev dnevnik i bilješke o sinu koji raste, niti prosti zbir njegovih dirljivih riječi i nestašluka. Ova knjiga majstorski bilježi kako se obični porodični trenuci pretvaraju u pravu umjetnost i književnost.', 'Трогательные и остроумные зарисовки о детстве глазами любящего папы, которые согреют всю семью тихим уютом.', 'Tender and witty snapshots of childhood through a loving father''s eyes that will wrap your whole family in quiet warmth.', 'Nježne i duhovite sličice djetinjstva viđene očima oca punog ljubavi koje će unijeti toplinu i osmijeh u svaki dom.', '/covers/DP-0120.webp', '#d97d54', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["real","funny"]', '["family","childhood","fatherhood","humor","growing up"]', 1792836322695, 1792845662000);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пусть-он-останется-с-нами-121', 'DP-0121', 'Пусть он останется с нами', 'Let Him Stay with Us', 'Neka ostane s nama', 'Максуд Ибрагимбеков', 'Maksud Ibragimbekov', 'Maksud Ibragimbekov', '', 'Теревинф', NULL, NULL, 7, 10, 'middle', 'Самокат', 'Two brothers secretly bring an enormous, gentle dog into their apartment, dreaming that their parents will let them keep him. A warm, hilarious, and timeless classic about childhood loyalty, brotherly schemes, and unconditional love for a big furry friend.', 'Dva brata krišom dovode u stan ogromnog, dobroćudnog psa, nadajući se da će nekako ubijediti roditelje da ga zadrže. Topla, duhovita i bezvremena priča o djetinjstvu, bratskoj slozi i bezuslovnoj ljubavi prema krznenom džinu.', 'Трогательная и очень смешная история о том, как спрятать в городской квартире собаку размером с телёнка и растопить родительские сердца.', 'A tender and laugh-out-loud tale about sneaking a calf-sized dog into a city apartment and successfully melting your parents'' hearts.', 'Dirljiva i beskrajno smiješna priča o tome kako u gradskom stanu sakriti psa veličine teleta i omekšati srca roditelja.', '/covers/DP-0121.webp', '#d06a3b', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["animals","friends","funny"]', '["dogs","family","brothers","childhood","pets"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('счастливый-неудачник-122', 'DP-0122', 'Счастливый неудачник', 'The Happy Loser', 'Srećni gubitnik', 'Вадим Шефнер', 'Vadim Shefner', 'Vadim Šefner', '', 'Теревинф', NULL, NULL, 7, 10, 'middle', '"Уважаемые читатели! Я Виктор Шумейкин. Вам, конечно, знакомо это имя - ведь вы читаете мои стихи. Но сегодня я решил поведать вам в прозе о том, как я вступил на путь поэзии. Почему я захотел об этом рассказать? - спросите вы. А вот почему. Есть люди, которые жалуются, что им не везет в жизни. Каждую мелкую неудачу они воспринимают как жестокий приговор судьбы, который не подлежит обжалованию. Они начинают считать себя неудачниками, падают духом. Вот я и хочу придать им бодрости и по мере сил доказать, что неудачи часто ведут к удачам, ибо прав арабский мудрец, который сказал: "Из зерен печали вырастают колосья радости".', 'Meet Viktor Shumeikin, an aspiring poet who firmly believes that even the most comical misfortunes can pave the way to real triumph. Looking back at his lively Leningrad childhood in the 1920s, he shares hilarious misadventures and quirky mishaps with unshakeable optimism, proving that seeds of sorrow can blossom into ears of joy.', 'Upoznajte Viktora Šumejkina, mladog pjesnika koji vjeruje da čak i najsmješniji pehovi vode do pravih uspjeha. Prisjećajući se svog djetinjstva u živopisnom Lenjingradu dvadesetih godina prošlog vijeka, on sa vedrinom i humorom priča o nezgodama koje se pretvaraju u neočekivanu sreću.', 'Невероятно остроумная и добрая повесть о том, как превратить любую нелепую неудачу в крылатое вдохновение и повод посмеяться от души!', 'A wonderfully witty and heartwarming tale about turning life''s clumsiest mishaps into soaring inspiration and contagious laughter!', 'Izuzetno duhovita i topla priča o tome kako svaki nespretni peh pretvoriti u nadahnuće i razlog za iskren smijeh!', '/covers/DP-0122.webp', '#d97736', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","real","friends"]', '["childhood","humor","optimism","poetry","school days"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебные-перья-арарахиса-123', 'DP-0123', 'Волшебные перья Арарахиса', 'The Magic Feathers of Ararakhis', 'Čarobna pera Ararahisa', 'Александр Якубенко', 'Aleksandr Yakubenko', 'Aleksandar Jakubenko', '', '', NULL, NULL, 7, 10, 'middle', 'В этой книге пять героев (нарисованный человечек Михрютка, отважный пес Угадай, ученая морская свинка Фунтик, талантливый химик-изобретатель кот Хандрила и веселая канарейка Пип) и очень много приключений, порой весьма опасных. Но не волнуйтесь: все закончится так, как положено, то есть хорошо. Не зря же Корней Иванович Чуковский написал автору "Волшебных перьев Арарахиса": "...повесть написана в лучших традициях приключенческого жанра для дошкольников. И герои, и их приключения выбраны Вами безошибочно - с учетом психики малых детей. Если снабдить эту книгу хорошими иллюстрациями, она станет одной из любимейших детских книг. В этом я не сомневаюсь".', 'This book follows five extraordinary companions—a drawn little man named Mikhryutka, the brave dog Guess, the learned guinea pig Funtik, the brilliant chemist-cat Khandrila, and a cheerful canary named Peep—through an avalanche of exciting and sometimes perilous adventures. But fear not: justice and friendship always prevail! Legendary storyteller Korney Chukovsky praised the tale as a masterclass in adventure literature for young readers, perfectly tuned to childhood wonder and daring imagination.', 'Ova knjiga prati petoricu neobičnih junaka — nacrtanog čovječuljka Mihrjutku, hrabrog psa Pogađaja, učenog morskog prasića Funtika, mačka-hemičara i pronalazača Handrilu i veselog kanarinca Pipa — kroz mnoštvo uzbudljivih i povremeno opasnih avantura. Ali ne brinite: sve će se završiti baš onako kako treba — srećno! Nije slučajno slavni Kornej Čukovski pohvalio ovu priču kao izvanredan primjer prave avanturističke književnosti prilagođene dječijoj mašti.', 'Замечательная, полная доброго озорства сказка, где кот-химик и нарисованный человечек докажут: настоящая дружба творит чудеса почище любых волшебных перьев!', 'A delightful classic romp where an inventive chemist-cat and a drawn doodle-boy prove that true friendship is the greatest magic of all!', 'Predivna, topla i uzbudljiva priča u kojoj mačak-pronalazač i nacrtani čovječuljak dokazuju da je pravo prijateljstvo jače od svake čarolije!', '/covers/DP-0123.webp', '#d9822b', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["adventure","magic","animals"]', '["talking animals","friendship","magic feathers","inventions","journey"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-среди-бела-дня-124', 'DP-0124', 'Сказки среди бела дня', 'Fairytales in Broad Daylight', 'Bajke usred bijela dana', 'Виктор Виткович, Григорий Ягфельд', 'Viktor Vitkovich, Grigory Yagdfeld', 'Viktor Vitkovič, Grigorij Jagdfeld', '', 'Теревинф', NULL, NULL, 7, 10, 'middle', 'Из первой сказки ("Кукольная комедия") вы узнаете, что все куклы - это на самом деле люди, жившие ранее так, как человеку не подобает: жулики, хамы и прочие обладатели "кукольных" сердец. К счастью, вернуть себе человеческий облик можно. Но как это сделать?! Во второй сказочной повести, давшей название всей книге, всё наоборот: здесь оживают, обретают душу... снежные бабы. И души эти оказываются разные, как и желания, и поступки бывших снеговиков. В общем, сейчас оба произведения отнесли бы к жанру "детских триллеров"; вот только написаны они были во времена, когда писатели ещё не позабыли, что сказки должны быть добрыми и заканчиваться счастливо.', 'In the first story, bad-tempered and dishonest people are turned into dolls who must figure out how to reclaim their human hearts. In the title story, snowmen magically come to life in broad daylight, each with a distinct soul and surprising motives! These two classic Soviet tales balance thrilling mystery with undeniable warmth, humor, and a guaranteed happy ending.', 'Iz prve priče saznaćete da su lutke zapravo nekada bili ljudi hladnog srca koji sada traže način da povrate ljudski lik. U drugoj bajci, snježne figure oživljavaju usred bijela dana, svaka sa sasvim drugačijom dušom i namjerama. Uzbudljive i pomalo napete, ove klasične priče podsjećaju nas na vrijeme kada su bajke uvijek donosile pobjedu dobrote.', 'Уютный и захватывающий «детский триллер» из нашего детства, где ожившие снеговики и заколдованные куклы учат искренности и доброте!', 'A wonderfully cozy vintage thriller where living snowmen and enchanted dolls prove that a genuine, warm heart always wins!', 'Neodoljivo uzbudljiv retro klasik u kojem oživjeli snješkići i začarane lutke podsjećaju na pravu vrijednost toplog ljudskog srca!', '/covers/DP-0124.webp', '#3b7a9e', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["magic","adventure","spooky"]', '["classic tales","living dolls","snowmen","mystery","magic"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневник-кости-рябцева-125', 'DP-0125', 'Дневник Кости Рябцева', 'The Diary of Kostya Ryabtsev', 'Dnevnik Kostje Rjabceva', 'Н. Огнёв', 'Nikolai Ognev', 'Nikolaj Ognjov', '', 'Теревинф', NULL, NULL, 7, 10, 'middle', 'Косте Рябцеву пятнадцать лет, и его "Дневник" рассказывает о школьной жизни, учёбе, друзьях, то есть о том, что должно быть хорошо знакомо читателю (во всяком случае, Костяному ровеснику или тем, кто старше). Однако с первых страниц книга погружает нас в неведомое: оказывается, тогда, в начале-середине 1920-х годов, всё было удивительно непохоже на привычную нам обстановку "повести для подростков". Другому учили, совсем иными были методы преподавания и отношения между учениками и учителями. Всё было другим - на первый взгляд; но эта несхожесть лишь подчеркивает неизменную важность таланта учителя, взаимо- и самоуважения, благородства помыслов и поступков, дружбы и верности. Лев Кассиль писал о "Дневнике Кости Рябцева": "Эту книгу, по праву признанную современниками знаменитой (её читали и в школе, и в вузе, и в семье; отдельные словечки, забавные выражения Кости Рябцева и его товарищей стали надолго нарицательными), уже давно не переиздавали... Некоторые склонны были считать её антипедагогической, устаревшей, уже якобы несозвучной нашему времени... Между тем книга написана писателем, который был наделён не только литературным даром, но и большим педагогическим талантом".', 'Fifteen-year-old Kostya Ryabtsev records his everyday school life in the turbulent 1920s, a time of radical educational experiments, lively student debates, and bold social changes. Beneath the unusual historical backdrop lie timeless questions of youth: figuring out who you are, navigating clashes between students and teachers, and learning what true friendship and integrity really mean.', 'Petnaestogodišnji Kostja Rjabcev u svom dnevniku bilježi đački život u burnim dvadesetim godinama prošlog vijeka — vremenu smjelih obrazovnih eksperimenata i neobičnih pravila. Ipak, iza svih tih istorijskih posebnosti krije se vanvremenska i topla priča o odrastanju, prijateljstvu, časti i važnosti pravog uzajamnog poštovanja između đaka i nastavnika.', 'Остроумный, честный и невероятно живой школьный дневник из 1920-х покажет, что подростки во все времена одинаково ищут себя, бунтуют и учатся настоящей дружбе.', 'A witty, brutally honest, and vibrant school diary from the 1920s showing that teenagers in any era question everything, make mistakes, and cherish true friendship.', 'Duhovit, iskren i nevjerovatno živopisan đački dnevnik iz 1920-ih koji dokazuje da tinejdžeri u svakom vremenu tragaju za sobom, preispituju pravila i cijene pravo prijateljstvo.', '/covers/DP-0125.webp', '#a34836', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["real","friends","funny"]', '["школа","дневник","подростки","история","дружба"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('болтушка-126', 'DP-0126', 'Болтушка', 'Blabber Mouth', 'Brbljivica', 'Морис Глейцман', 'Morris Gleitzman', 'Moris Glajcman', '', 'Дети ОГИ', NULL, NULL, 7, 10, 'middle', 'Девочке Ро 11 лет, и она считает себя ужасной болтушкой. Она и в самом деле болтает без умолку, но только… про себя. С самого рождения ее горло устроено немного по-другому, и из-за этого девочка не может разговаривать вслух. А еще у Ро необычный и замечательный папа, который не похож на других пап - он не носит строгих костюмов и любит петь ковбойские песни. Австралийский писатель Моррис Глейцман написал прекрасную историю о том, как важно понимать и уважать того, кто не похож на тебя.', 'Eleven-year-old Rowena considers herself a terrible chatterbox, talking non-stop—only completely inside her head. Born unable to speak out loud, Rowena navigates a new school, friendships, and a wonderfully eccentric dad who loves loud Hawaiian shirts and singing cowboy songs. Australian author Morris Gleitzman delivers an uplifting and deeply empathetic story about finding your voice, accepting quirks, and celebrating individuality.', 'Jedanaestogodišnja Rovena smatra sebe pravom brbljivicom, jer neprestano priča — ali samo u svojoj glavi. Budući da od rođenja ne može da govori naglas, Rovena se suočava sa novom školom, sklapanjem prijateljstava i svojim urnebesnim, neobičnim tatom koji obožava kaubojske pjesme. Australijski pisac Moris Glajcman stvara toplu i dirljivu priču o pronalaženju sopstvenog glasa i prihvatanju onih koji su drugačiji.', 'Трогательная и ужасно смешная история о том, что самый громкий голос звучит не в горле, а в любящем сердце!', 'A heartwarming and laugh-out-loud tale proving that the loudest voice doesn''t come from your vocal cords, but straight from the heart!', 'Dirljiva i beskrajno duhovita priča koja dokazuje da najglasnije govorimo onda kada pričamo srcem!', '/covers/DP-0126.webp', '#e76f51', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["real","funny","friends"]', '["school","family","acceptance","empathy","humor"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-всего-лишь-ребенок-127', 'DP-0127', 'Я всего лишь ребенок', 'I''m Just a Kid Here', 'Samo sam dijete', 'Ютта Рихтер', 'Jutta Richter', 'Juta Rihter', '', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Мир взрослых так непонятен и непредсказуем! В этом Ханна убеждается каждый день. Сегодня, например, она разозлилась и вылила своей однокласснице на голову какао. А мама, вместо того чтобы отругать, хохотала до упаду и даже хвалила: "Просто великолепно!" Ну как такое возможно?! А на днях бабушка пообещала подарить Ханне котёнка - несмотря на то что мама категорически против. Как они будут между собой разбираться?! Лучше даже не представлять, а тихо радоваться про себя обещанному подарку. Вообще жизнь Ханны не проста. То надо объяснить папе, почему котёнок Лапочка расцарапал кожаное сиденье мотоцикла. То пережить месть одноклассника Леонарда, который якобы из-за неё опоздал на урок. В этот трудный момент у девочки появляется лучшая подруга Зоя. Она обязательно подскажет, как действовать!', 'The world of grown-ups is utterly bewildering, as Hanna discovers every single day. She dumps cocoa over a classmate''s head in anger, and Mom bursts out laughing instead of scolding! Then Grandma promises a forbidden kitten behind Mom''s back, Dad needs explanations about scratched motorcycle leather, and school drama is brewing. Thankfully, Hanna''s loyal new best friend Zoe is right there to help her navigate the chaotic rules of adult logic.', 'Svijet odraslih je potpuno neshvatljiv, a Hana se u to uvjerava svakoga dana. Kada u bijesu prospe kakao drugarici na glavu, mama se umjesto grdnje samo nasmije do suza! Dok baka krišom obećava mače protiv maminih pravila, tata traži krivca za izgrebano sjedište motora, a u školi vrebaju sitne osvete, Hanin život postaje pravi izazov. Na sreću, tu je nova najbolja drugarica Zoja, koja uvijek ima dobar plan.', 'Остроумный и трогательный взгляд на странный мир взрослых глазами девочки, которая просто пытается в нём выжить и завести котёнка!', 'A witty, relatable peek into the baffling world of grown-ups through the eyes of a girl just trying to survive school and keep her secret kitten!', 'Duhovit i topao uvid u zbunjujući svijet odraslih očima djevojčice koja samo želi da preživi školu i zadrži svoje mače!', '/covers/DP-0127.webp', '#e07a5f', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","real","friends"]', '["family life","friendship","growing up","school","kittens"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пингвины-мистера-поппера-128', 'DP-0128', 'Пингвины мистера Поппера', 'Mr. Popper''s Penguins', 'Pingvini gospodina Popera', 'Ричард и Флоренс Этуотер', 'Richard and Florence Atwater', 'Ričard i Florens Etvoter', '', 'Белая ворона', NULL, NULL, 7, 10, 'middle', 'Маляр мистер Поппер живет в маленьком американском городке и мечтает о далеких полярных экспедициях. Но мечты остаются мечтами, жизнь идет своим чередом, а семья едва сводит концы с концами. И вдруг почтальон приносит мистеру Попперу посылку с Южного полюса. Вскоре по дому маршируют антарктические пингвины, а миссис Поппер аккомпанирует им на фортепьяно. И это только начало! Эту невероятную и смешную историю сочинили в конце 1930-х годов Ричард Этуотер, журналист и преподаватель древнегреческого языка из Чикаго, и его жена Флоренс. Книга стала классикой, авторы получили за нее Медаль Джона Ньюбери, которая вручается за выдающийся вклад в литературу. По мотивам этой истории снят фильм с Джимом Керри в главной роли.', 'Mr. Popper, a modest house painter living in a quiet American town, spends his days dreaming of polar expeditions. Life is ordinary and money is tight—until a surprise parcel arrives straight from the South Pole! Before long, real Antarctic penguins are marching proudly through the living room, Mrs. Popper is playing them waltzes on the piano, and the family''s world turns joyfully upside down. Written in the late 1930s by Richard and Florence Atwater, this beloved Newbery Honor classic remains one of the funniest family stories ever told.', 'Gospodin Poper, skromni moler iz mirnog američkog gradića, dane provodi maštajući o polarnim ekspedicijama. Život teče uobičajeno i novca je malo — sve dok poštar ne donese neočekivani paket pravo sa Južnog pola! Uskoro se po kući šepure pravi antarktički pingvini, gospođa Poper im svira klavir, a život porodice se pretvara u urnebesni haos. Ovaj nagrađivani dječji klasik Ričarda i Florens Etvoter iz 1930-ih decenijama nasmijava generacije malih i velikih čitalaca.', 'Что делать, если в посылке с Южного полюса оказался пингвин? Конечно же, превратить подвал в ледовый каток и научить птиц танцевать!', 'What do you do when a real penguin arrives in the mail? Turn your basement into an ice rink and teach them to dance, of course!', 'Šta uraditi kada vam poštom stigne pravi pingvin sa Južnog pola? Pretvoriti podrum u klizalište i naučiti ih da plešu!', '/covers/DP-0128.webp', '#2c5282', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","adventure","animals"]', '["пингвины","юмор","классика","необычные питомцы","семья"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хранитель-острова-паффин-129', 'DP-0129', 'Хранитель острова Паффин', 'The Puffin Keeper', 'Čuvar ostrva Pafin', 'Майкл Морпурго', 'Michael Morpurgo', 'Majkl Morpurgo', 'Бэнджи Дэвис', 'Махаон', NULL, NULL, 7, 10, 'middle', '«Всю свою долгую жизнь на острове Паффин Бенджамин Послвет неусыпно следил за тем, чтобы на маяке ярко сиял огонь. День и ночь с высокой башни раздавался уныло протяжный звон колокола, а свет маяка помогал проходящим мимо острова торговым пароходам и рыбацким шхунам благополучно держаться верного курса…» Бенджамин Послвет — смотритель маяка на острове Паффин, посвятивший себя беззаветному служению людям, не требуя ничего взамен — ни наград, ни почестей, ни признания. Это история о человеке — самоотверженном, честном и бескорыстном. А ещё эта трогательная, необыкновенно светлая и захватывающая история о дружбе и преданности, о вере и надежде, о героизме и чувстве долга.', 'Benjamin Postlethwaite has spent his whole life tending the light on Puffin Island, guiding merchant steamers and fishing boats safely through perilous seas. A chance shipwreck rescue sparks an extraordinary friendship between the quiet lighthouse keeper, a young boy, and an injured puffin. A luminous, tender story about devotion, hope, and everyday heroism.', 'Bendžamin Postlvejt je cijeli svoj život posvetio ostrvu Pafin, neumorno pazeći da svjetionik sija i vodi brodove kroz nemirno more. Kada iz brodoloma spasi dječaka, a zatim i povrijeđenu morsku pticu, rađa se neraskidivo prijateljstvo. Dirljiva i topla priča o tihom herojstvu, odanosti, nadi i osjećaju dužnosti.', 'Уютная и благородная морская история от Майкла Морпурго о верном смотрителе маяка, спасённом тупике и свете, который никогда не гаснет.', 'A cozy, sweeping maritime tale from Michael Morpurgo about a steadfast lighthouse keeper, a brave little puffin, and the light that guides us home.', 'Topla i plemenita morska priča Majkla Morpurga o odanom svjetioničaru, malom pafinu i svjetlosti koja nikada ne gasne.', '/covers/DP-0129.webp', '#2b5f7d', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["adventure","animals","friends"]', '["lighthouse","sea","puffins","friendship","heroism"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-капитана-врунгеля-130', 'DP-0130', 'Приключения капитана Врунгеля', 'The Adventures of Captain Vrungel', 'Pustolovine kapetana Vrungela', 'Андрей Некрасов', 'Andrei Nekrasov', 'Andrej Nekrasov', '', 'Махаон', NULL, NULL, 7, 10, 'middle', 'Классическое литературное произведение о приключениях любимых героев - капитана Врунгеля, его помощников Лома и Фукса. Книга отвечает всем требованиям современного юного читателя. Хорошая бумага - офсет, иллюстрации - красочные и яркие. Все герои на них - добрые и озорные. Они приглашают совершить увлекательное путешествие по страницам книги.', 'A legendary maritime adventure filled with tall tales and side-splitting humor! Follow the unflappable Captain Vrungel and his quirky crew, Lom and Fuchs, aboard the yacht ''Trouble'' as they embark on an unforgettable, topsy-turvy round-the-world regatta.', 'Legendarna pomorska pustolovina puna humora i nevjerovatnih morskih priča! Pridružite se domišljatom kapetanu Vrungelu i njegovoj neobičnoj posadi, Lomu i Fuksu, na jahti „Nevolja” dok plove oko svijeta kroz najsmješnije zgode.', 'В портовом городе Баре каждый юный моряк просто обязан выйти в плавание с легендарным Врунгелем на непотопляемой яхте «Беда»!', 'Living right here by the sea in Bar, every young explorer simply must set sail on this hilarious, topsy-turvy voyage aboard the yacht ''Trouble''!', 'Ovdje, uz more u Baru, svaki mladi moreplovac jednostavno mora zaploviti u ovu urnebesnu avanturu sa kapetanom Vrungelom!', '/covers/DP-0130.webp', '#23689b', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","adventure","friends"]', '["sea","sailing","humor","regatta","travel"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('омлет-с-сахаром-приключения-се-131', 'DP-0131', 'Омлет с сахаром : Приключения семейки из Шербура', 'Sugar Omelette: The Adventures of the Cherbourg Family', 'Omlet sa šećerom: Avanture porodice iz Šerbura', 'Арру-Виньо Жан-Филипп', 'Jean-Philippe Arrou-Vignod', 'Žan-Filip Aru-Vinjo', '', '', NULL, NULL, 7, 10, 'middle', 'Автор книги, которую вы держите в руках, француз Жан-Филипп Арру-Виньо — один из тех самых шести братьев Жанов, о которых пойдет речь. А еще точнее — Жан Б., второй по старшинству. С самого детства Арру-Виньо обожал читать. В 1984 году он опубликовал свой первый «взрослый» роман, за который получил премию «Лучший дебют», а через несколько лет выпустил вторую книгу — детскую. Сегодня Арру-Виньо, автор около тридцати книг, заведует отделом детской литературы в крупнейшем независимом французском издательстве «Галлимар». Свою серию «Приключения семейки из Шербура», столь любимую детьми и родителями во Франции, он создал совместно с известным иллюстратором Доминик Корбасон, чьи работы можно увидеть на страницах таких журналов, как Cosmopolitan, Madame Figaro и Vanity Fair. По духу «Приключения семейки из Шербура» напоминают знаменитого «Малыша Николя» Рене Госинни и Жан-Жака Сампэ: герои «Семейки» — те же веселые, неугомонные мальчишки, которые так и норовят что-нибудь натворить. Серию открывает книга «Омлет с сахаром» (1999). Вы когда-нибудь ели омлет c сахаром? Его очень легко приготовить! Рецепт: возьмите семью с пятью сыновьями, добавьте еще одного младенца, черепаху, морскую свинку и горстку белых мышей. Хорошенько перемешайте. Не забудьте еще о строгой маме и папе, который на все руки мастер, ну и, конечно, о школьных друзьях с богатым воображением. Щепотка вредности — и готово, можно подавать на стол!', 'Meet the Jean brothers: Jean A., Jean B., Jean C., Jean D., and Jean E., with a brand-new baby brother on the way! Between mischievous school antics, guinea pigs, pet turtles, and an energetic father who loves DIY, daily life in this French household is pure hilarious chaos. Written by Jean B. himself, this lively story reminiscent of ''Little Nicholas'' is a deliciously funny recipe for true family fun.', 'Upoznajte braću Žan: Žana A., Žana B., Žana C., Žana D., Žana E., a na putu je i nova beba! Između nestašluka u školi, zamorčića, kornjača i snalažljivog tate, svakodnevica ove francuske porodice pretvara se u urnebesan haos. Napisana iz pera drugog po starini brata Žana B., ova knjiga u duhu ''Malog Nikole'' donosi neodoljiv i zabavan recept za porodičnu avanturu.', 'Если в семье растут шесть братьев с одним именем на всех, скучать не придётся никому — запасайтесь смехом и хорошим настроением!', 'When a household is run by six brothers who all share the exact same first name, you know every single day is pure comic mayhem!', 'Kad pod jednim krovom živi šestoro braće sa istim imenom, urnebesni nestašluci i smijeh do suza su zagarantovani!', '/covers/DP-0131.webp', '#e89736', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","real","friends"]', '["brothers","family","humor","school life","french literature"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('летающий-сыр-132', 'DP-0132', 'Летающий сыр', 'The Flying Cheese', 'Leteći sir', 'Жан-Филипп Арру-Виньо', 'Jean-Philippe Arrou-Vignod', 'Žan-Filip Aro-Vinjo', '', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Наступило лето, а значит, наших хороших знакомых - братьев Жанов и их родителей - ждут новые приключения. Летнее меню: переезд из родного Шербура, каникулы в деревне у бабушки и дедушки, рыбка по имени Суппозиторий, орава лопоухих кузенов Фугас, ну и, конечно, загадочный объект под названием "Летающий сыр". Тем, кто уже попробовал "Омлет с сахаром" и хочет еще чего-нибудь необычного, предлагаем насладиться "Летающим сыром" под соусом из тонкого юмора Арру-Виньо. Жан-Филипп Арру-Виньо - один из тех самых шести братьев Жанов, о которых пойдет речь. А еще точнее - Жан Б., второй по старшинству. С самого детства он обожал читать. В 1984 году опубликовал свой первый "взрослый" роман, за который получил премию "Лучший дебют", а через несколько лет выпустил вторую книгу - детскую. Сегодня Арру-Виньо, автор около тридцати книг, заведует отделом детской литературы в крупнейшем независимом французском издательстве "Галлимар". По духу "Приключения семейки из Шербура" напоминают знаменитого "Малыша Николя" Рене Госинни и Жан-Жака Сампэ: герои "Семейки" - те же веселые, неугомонные мальчишки, которые так и норовят что-нибудь натворить', 'Summer has arrived, bringing a whirlwind of hilarious new escapades for the Jean brothers and their long-suffering parents! This summer''s menu includes moving away from their beloved Cherbourg, holidays in the countryside with grandparents, a pet goldfish oddly named Suppository, a noisy mob of big-eared cousins, and of course, a mysterious airborne entity known as the ''Flying Cheese''. Continuing in the spirited tradition of ''Sugar Omelet'' and reminiscent of ''Little Nicholas'', Arrou-Vignod serves up a delightfully chaotic retro family comedy packed with warmth and mischief.', 'Ljeto je stiglo, a to znači nove avanture za čuvenu braću Žan i njihove roditelje! Ljetni meni donosi: selidbu iz rodnog Šerbura, raspust na selu kod babe i djeda, zlatnu ribicu neobičnog imena Čepić, hordu nestašnih rođaka i, naravno, misteriozni leteći objekat zvan ''Leteći sir''. U duhu slavnog ''Malog Nikole'', ova topla francuska priča nudi pregršt bezazlenih nepodopština i iskrenog humora uz koje se naglas smije cijela porodica.', 'Шесть братьев-сорванцов, каникулы в деревне и летающий сыр — идеальный рецепт заразительного смеха для всей семьи!', 'Six mischievous brothers, a summer at the grandparents'' house, and airborne dairy: pure, laugh-out-loud family chaos!', 'Šestorica nestašne braće, ljetnji raspust na selu i sir u vazduhu — savršen recept za grohotan smijeh cijele porodice!', '/covers/DP-0132.webp', '#e8a427', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","adventure","real"]', '["brothers","family","summer vacation","humor","mischief"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('суп-из-золотых-рыбок-133', 'DP-0133', 'Суп из золотых рыбок', 'Goldfish Soup', 'Supa od zlatnih ribica', 'Жан-Филипп Арру-Виньо', 'Jean-Philippe Arrou-Vignod', 'Žan-Filip Aru-Vinjo', '', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Уже знакомые нам по предыдущим книгам серии "Приключения семейки из Шербура" - "Омлету с сахаром" и "Летающему сыру" - братья Жаны и их родители переехали в Тулон. Папа, конечно, мастер на все руки, а у мамы всегда всё под контролем, но похоже, что год предстоит непростой. Еще бы, ведь Жан А. вместо подготовки к контрольной тайком собрался на вечеринку, Жан Б. вообще боится идти в новую школу, а вместе с Жаном В. они объявляют войну загадочным Касторам…', 'The beloved Jean brothers are packing their bags and moving to sunny Toulon! Dad may be handy and Mom keeps everything under control, but this year will be anything but calm: sneaky party plans instead of studying, the dread of a brand-new school, and an epic declared war against the mysterious Beavers.', 'Omiljena braća Žanovi i njihovi roditelji sele se u sunčani Tulon! Tata je majstor za sve, a mama drži sve konce u rukama, ali ova godina neće biti nimalo laka: tajne žurke umjesto učenja za kontrolni, strah od nove škole i pravi rat protiv tajanstvenih Dabrova.', 'Шесть неугомонных братьев по имени Жан переезжают на юг — приготовьтесь к грандиозному семейному переполоху, где ни минуты не бывает скучно!', 'Six brothers, all named Jean, move to the south of France — get ready for a hilariously chaotic family adventure where boredom is simply not an option!', 'Šestoro neumorne braće po imenu Žan sele se na jug — pripremite se za urnebesnu porodičnu zbrku u kojoj dosada ne postoji!', '/covers/DP-0133.webp', '#e56738', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","adventure","real"]', '["brothers","family life","humor","new school","moving"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шоколадные-каникулы-134', 'DP-0134', 'Шоколадные каникулы', 'Chocolate Holidays', 'Čokoladni raspust', 'Жан-Филипп Арру-Виньо', 'Jean-Philippe Arrou-Vignod', 'Žan-Filip Aro-Vinjo', '', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Этим летом уже знакомые нам по другим книгам серии "Приключения семейки из Шербура" братья Жаны отправляются на каникулы к морю, в отель "Алые скалы". В программе: секретная экспедиция по гостинице во время тихого часа, уникальное представление цирка "Пиполо", ну и, конечно, знаменитая велогонка "Тур де Франс", которую братья Жаны наконец-то увидят своими глазами. Опасные приключения, дикий смех и подушечные бои - каникулы обещают быть незабываемыми, особенно для родителей...', 'This summer, the Jean brothers from the beloved French series head to the seaside for a holiday at the Scarlet Rocks hotel. Their busy schedule includes sneaking through the hotel during naptime, visiting the unique Pipolo Circus, and finally watching the legendary Tour de France with their own eyes. Wild pillow fights, seaside mischief, and endless laughter make this a truly unforgettable vacation—especially for their parents!', 'Ovog ljeta, nerazdvojna braća Žan odlaze na ljetovanje na more, u hotel „Grimizne stijene”. Na njihovom rasporedu su: tajna ekspedicija kroz hotel tokom popodnevnog odmora, jedinstvena predstava cirkusa „Pipolo” i, naravno, čuvena biciklistička trka Tur de Frans koju će konačno vidjeti uživo. Opasne avanture, urnebesni smijeh i borbe jastucima garantuju nezaboravan odmor — naročito za njihove roditelje...', 'Шестеро неугомонных братьев на море — это рецепт чистейшего детского счастья, грандиозных шалостей и полнейшей капитуляции родительских нервов!', 'Six unstoppable brothers on a seaside holiday guarantee wild laughter, pillow fights, and zero peace and quiet for their brave parents!', 'Šestorica neumorne braće na moru garantuju urnebesnu zabavu, borbe jastucima i potpunu kapitulaciju roditeljskih živaca!', '/covers/DP-0134.webp', '#d9742b', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","adventure","real"]', '["brothers","summer vacation","humor","family","seaside"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вс-о-малыше-николя-135', 'DP-0135', 'Всё о малыше Николя', 'All About Little Nicholas', 'Sve o malom Nikoli', 'Рене Госсини', 'René Goscinny', 'Rene Gosini', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Эта история началась в далёкие пятидесятые годы прошлого века с небольших юмористических рисунков, автором которых был художник Жан-Жак Сампе. Его друг писатель Рене Госинни решил к этим рисункам написать тексты. Таким образом получились забавные рассказы-комиксы, героем которых стал малыш Николя. Этого симпатичного мальчишку юные читатели очень полюбили и с нетерпением ждали публикации очередного рассказа. Авторы сочиняли и рисовали всё новые и новые истории, и издатели решили объединить их в книжки. С тех пор прошло немало лет, но малыш Николя по-прежнему необычайно популярен и любим детьми многих стран мира. Весёлые истории об этом добром, обаятельном сорванце, о его приятелях и школе близки и понятны детям. И не важно, на каком языке они разговаривают.', 'Created in the 1950s by writer René Goscinny and cartoonist Jean-Jacques Sempé, the adventures of Little Nicholas have delighted generations of readers around the globe. This collection brings together the hilarious, heartwarming stories of Nicholas, his spirited schoolmates, and their endless everyday mischief. Timeless, relatable, and bursting with childhood charm, it will make readers of all ages laugh out loud.', 'Nastale pedesetih godina prošlog vijeka iz pera pisca Renea Gosinija i crtača Žan-Žaka Sempea, priče o malom Nikoli osvojile su srca djece širom svijeta. Ova zbirka donosi nezaboravne i urnebesne zgode simpatičnog dječaka, njegovih školskih drugara i porodice. Topli, duhoviti i bezvremeni nestašuci bliski su i razumljivi svakom djetetu, ma kojim jezikom govorilo.', 'Приготовьтесь хохотать до слёз над проделками Николя и его банды — идеальная книга, чтобы влюбиться в чтение всей семьёй!', 'Get ready to laugh until your stomach hurts at the antics of Nicholas and his gang—a timeless masterpiece that turns anyone into a reader!', 'Spremite se za smijeh do suza uz vragolije malog Nikole i njegove družine — savršena knjiga uz koju se zavoli čitanje!', '/covers/DP-0135.webp', '#d93829', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","friends","real"]', '["humor","school life","friendship","french classic","family reading"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('каникулы-малыша-николя-136', 'DP-0136', 'Каникулы Малыша Николя', 'Nicholas on Holiday', 'Nikolini raspusti', 'Рене Госсини', 'René Goscinny', 'Rene Gosini', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Рене Госинни, один из создателей популярнейших героев Астерикса и Обеликса, является автором и забавных рассказов о малыше Николя. Весёлые истории о добром, озорном сорванце, о его приятелях и школе очень полюбили дети многих стран мира. Пришло время познакомиться с этим очаровательным проказником и нашим читателям. Рассказы переведены на 37 языков и изданы миллионными тиражами. А совсем недавно в прокат вышел художественный фильм "Маленький Николя".', 'René Goscinny, co-creator of Asterix and Obelix, brings us the laugh-out-loud tales of Little Nicholas. Nicholas is heading off on summer vacation, first to the seaside and then to summer camp! Packed with sun, sea, swimming, and an unstoppable barrage of hilarious mishaps with his new friends, this classic French favorite brings sunny chaos wherever Nicholas goes.', 'Rene Gosini, jedan od tvoraca čuvenih junaka Asteriksa i Obeliksa, donosi nam urnebesne priče o dječaku Nikoli. Stigli su ljetnji raspusti, a to znači odlazak na more i u dječji kamp! Uz sunce, kupanje i nove prijatelje, Nikola uspijeva da svaku bezazlenu situaciju pretvori u nezaboravnu i smiješnu avanturu.', 'Запасайтесь плавательными кругами и готовьте щёки для смеха — каникулы с Николя обещают быть незабываемо шумными и весёлыми!', 'Grab your swim ring and get ready to laugh until your cheeks hurt — summer vacation with Nicholas is delightfully chaotic!', 'Uzmite šlauf za plivanje i pripremite se za smijeh do suza — ljetnji raspust sa Nikolom biće nevjerovatno zabavan!', '/covers/DP-0136.webp', '#2a75d3', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["funny","adventure","friends"]', '["summer vacation","childhood","humor","mischief","classic"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('крылатые-кошки-137', 'DP-0137', 'Крылатые кошки', 'Catwings', 'Krilate mačke', 'Урсула ле Гуин', 'Ursula K. Le Guin', 'Ursula K. Le Gvin', '', 'Карьера пресс', NULL, NULL, 7, 10, 'middle', 'Урсула Ле Гуин не нуждается в представлении читателю. Она - классик мировой литературы. Но вот детские повести и рассказы, которые популярны в мире не меньше "Мага Земноморья", в России еще не издавались. Эта книга - первая в серии историй о семействе крылатых кошек. Для младшего школьного возраста.', 'Ursula K. Le Guin is celebrated worldwide for her fantasy masterworks, but her delightful children''s stories are just as magical. This is the first book in the beloved series about four extraordinary kittens born with wings, who fly away from the dangerous city to find a safe and quiet home in the countryside.', 'Ursula K. Le Gvin je svjetski poznata po fantastičnim remek-djelima, ali njene tople priče za djecu jednako plijene pažnju. Ovo je prva knjiga o neobičnoj porodici mačića rođenih sa krilima, koji lete daleko od opasnog grada u potrazi za mirnim i bezbjednim domom.', 'Что делать котятам с крыльями в опасном шумном городе? Расправить перышки и полететь навстречу свободе и верным друзьям!', 'What should four kittens with wings do in a dangerous alley? Spread their feathers and fly off toward freedom and true friendship!', 'Šta mačići sa krilima mogu uraditi u bučnom gradu? Raširiti perca i poletjeti u susret slobodi i pravim prijateljima!', '/covers/DP-0137.webp', '#497b9e', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["animals","adventure","magic"]', '["cats","wings","flight","friendship","classics"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('однажды-в-новом-мире-138', 'DP-0138', 'Однажды в новом мире', 'Once in the New World', 'Jednom u novom svijetu', 'Марина Аромштам', 'Marina Aromshtam', 'Marina Aromštam', 'Игорь Слаук', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Детей часто волнует вопрос "откуда что взялось?". Сказки-притчи "Однажды в Новом Мире" переносят юного читателя к "началу начал", делая его свидетелем первых событий и первых конфликтов только что родившегося мира. Автор этих сказок - Марина Аромштам - писатель, журналист, специалист по детскому чтению. Книги Марины Аромштам удостоены многих премий и отмечены критиками, в том числе за рубежом. Особую уникальность книге "Однажды в Новом Мире" придают редкие по нынешним временам иллюстрации в технике офорта, выполненные заслуженным художником Республики Беларусь Валерием Слауком. Книга пополнит собой библиотеку семейного чтения.', 'Children often wonder: ''Where did everything come from?'' The parable-like tales of ''Once in the New World'' transport young readers to the very beginning of time, making them witnesses to the very first events and conflicts of a newly born earth. Written by acclaimed author and literacy expert Marina Aromshtam, this evocative collection is brought to life with rare and intricate etchings by honored artist Valery Slauk, making it a true treasure for family reading.', 'Djeca se često pitaju: „Odakle je sve nastalo?“ Bajkovite priče u knjizi „Jednom u novom svijetu“ vode mlade čitaoce na sam početak vremena, čineći ih svjedocima prvih događaja i sukoba tek rođenog svijeta. Autorka Marina Aromštam, nagrađivana spisateljica i pedagog, stvara djelo obogaćeno rijetkim i prefinjenim grafikama Valerija Slauka, pretvarajući ga u pravo blago za porodično čitanje.', 'Мудрые и завораживающие притчи о рождении всего сущего, украшенные редкими по красоте офортами!', 'Wise and captivating parables about the dawn of creation, illustrated with stunning, timeless etchings!', 'Mudre i očaravajuće priče o postanku svijeta, obogaćene zadivljujućim i rijetkim grafikama!', '/covers/DP-0138.webp', '#5b5247', '7-9', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["magic","adventure"]', '["parables","origins","family reading","etchings","tales"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-отдыхают-ангелы-139', 'DP-0139', 'Когда отдыхают ангелы', 'When Angels Rest', 'Kad anđeli odmaraju', 'Марина Аромштам', 'Marina Aromshtam', 'Marina Aromštam', '', 'КомпасГид', NULL, NULL, 7, 10, 'middle', 'Роман Марии Аромштам "Когда отдыхают ангелы" получил Национальную детскую литературную премию "Заветная мечта", Приз детской признательности за открытие и приобщение к миру чтения "Размышление о Маленьком Принце", был отмечен премиями им. А. Толстого и Л. Толстого, вошел в список "Нравится детям Ленинградской области" и список выдающихся книг мира "Белые вороны", составляемый Мюнхенской международной детской библиотекой. Для старшего школьного возраста. 7-е издание', 'Marina Aromshtam’s award-winning novel is a wise and tender story of childhood, growing up, and the bond between schoolkids and their inspiring teacher, who shares a gentle secret: guardian angels get to rest whenever humans do good deeds.', 'Nagrađivani roman Marine Aromštam dirljiva je i mudra priča o djetinjstvu, odrastanju i vezi između đaka i njihove neobične učiteljice, koja dijeli tihu tajnu: anđeli čuvari mogu da predahnu samo onda kada ljudi čine dobra djela.', 'Искренняя и невероятно мудрая повесть о любимой учительнице, взрослении и добрых поступках, которые берегут наших ангелов.', 'A deeply touching, heartfelt story about an unforgettable teacher, growing up, and the everyday kindness that lets our guardian angels rest.', 'Duboko dirljiva i mudra priča o nezaboravnoj učiteljici, odrastanju i svakodnevnoj dobroti koja omogućava našim anđelima da predahnu.', '/covers/DP-0139.webp', '#2e4a62', '7-9', 'ru', 'available', 'Категория: Средний школьный возраст', '["friends","real"]', '["school life","teachers","growing up","empathy","kindness"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мой-внутренний-элвис-140', 'DP-0140', 'Мой внутренний Элвис', 'My Inner Elvis', 'Moj unutrašnji Elvis', 'Яна Шерер', 'Jana Scheerer', 'Jana Šerer', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Элвис жив! Юная Антье, как и тысячи других поклонников короля рок-н-ролла, нисколько не сомневается в этом. И, конечно же, она хочет отпраздновать свой шестнадцатый день рождения не где-нибудь, а в Грейсленде, на родине Элвиса. И вот удача: семья девушки собирается провести лето в Америке! Удастся ли Антье осуществить свою мечту и встретиться со своим кумиром? "Мой внутренний Элвис" - роман молодой немецкой писательницы Яны Шерер, которой с необыкновенной точностью удалось описать период взросления: мечты, противоречивые чувства, свойственные подростковому возрасту, поиск своего места в жизни. А необычный стиль повествования, без сомнения, придется по душе не только юным читателям, но и их родителям: каждый наверняка узнает в главной героине себя.', 'Elvis is alive! Young Antje, like thousands of devoted fans of the King of Rock ''n'' Roll, has no doubt about it. Naturally, she dreams of celebrating her sixteenth birthday nowhere else but Graceland. And what luck: her family is setting off for a summer road trip across America! Will Antje make her dream come true and track down her idol? Jana Scheerer''s debut novel is a humorous and touching coming-of-age journey full of teenage soul-searching and quirky family adventures.', 'Elvis je živ! Mlada Antje, poput hiljada drugih vjernih obožavalaca kralja rokenrola, uopšte ne sumnja u to. Naravno, svoj šesnaesti rođendan želi da proslavi nigdje drugdje do u Grejslendu. I kakva sreća: njena porodica odlazi na ljetnje putovanje kroz Ameriku! Hoće li Antje ostvariti svoj san i pronaći svog idola? Roman Jane Šerer je duhovita i dirljiva priča o odrastanju, tinejdžerskim dilemama i neobičnim porodičnim avanturama.', 'Врубайте рок-н-ролл на полную: вас ждёт уморительное семейное автопутешествие по Америке в поисках короля рок-н-ролла и самой себя!', 'Crank up the rock ''n'' roll: get ready for a hilarious family road trip across America in search of the King and oneself!', 'Pojačajte rokenrol do daske: čeka vas urnebesno porodično putovanje po Americi u potrazi za kraljem i sopstvenim glasom!', '/covers/DP-0140.webp', '#d85040', '7-9', 'ru', 'available', 'Для старшего школьного возраста.', '["funny","adventure","real"]', '["rock''n''roll","road trip","growing up","family","humor"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мы-разбойниковы-141', 'DP-0141', 'Мы - разбойниковы', 'Me and the Robbersons', 'Mi, Razbojnici', 'Сири Колу', 'Siri Kolu', 'Siri Kolu', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Каникулы у бабушки - самый неудачный из всех возможных планов на лето. Но для Вильи он так и остался планом: ее похитили прямо на дороге. Самые настоящие разбойники. Правда, очень странные. Потому что деньги и прочие традиционные ценности их мало волнуют. Им бы побольше сладостей, еды, одежды, игр и всяких полезных мелочей - вот это правильная добыча. А Вилья зачем? "Пригодится. Слово атамана". И, похоже, Вилье такие каникулы пришлись по душе: погони, приключения, свежий воздух, море и свобода - отличный рецепт незабываемого лета. Одна из самых любимых историй финских детей была удостоена престижной премии Книжного фонда Финляндии, экранизирована и переведена на 17 языков.', 'Spending the summer at grandma''s sounded painfully dull, but Vilja''s plans change abruptly when she is kidnapped right off the highway by bandits! Luckily, these aren''t dangerous criminals—they care little for gold and instead loot candy, tasty snacks, and fun knick-knacks. Swept along in their chaotic van, Vilja discovers that wild road chases, endless freedom, and a family of lovable rogues make for the best summer vacation imaginable.', 'Dosadno ljetovanje kod babe bila je jedina opcija za Vilju, sve dok je s puta nijesu oteli pravi pravcati drumski razbojnici! Ipak, ovu neobičnu družinu ne zanimaju zlato i novac – njihov omiljeni plijen su slatkiši, grickalice, igračke i korisne sitnice. Vilja ubrzo shvata da joj život na točkovima, pun ludih jurnjava i ljetnje slobode, donosi najzabavniji raspust u životu.', 'Если обычные каникулы кажутся смертной скукой, смело запрыгивайте в фургон к этим обаятельным охотникам за сладостями!', 'If your summer plans look boring, hop into the van with the world''s most charming candy-hunting bandits!', 'Ako vam raspust zvuči dosadno, uskočite u kombi najslađe razbojničke bande i krenite u ludu ljetnju avanturu!', '/covers/DP-0141.webp', '#e25c27', '7-9', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["funny","adventure"]', '["bandits","road trip","summer vacation","humor","finland"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мы-разбойниковы-и-разбойничья--142', 'DP-0142', 'Мы - разбойниковы и разбойничья песнь', 'Me and the Robbersons and the Bandit Song', 'Mi Razbojnici i razbojnička pjesma', 'Сири Колу', 'Siri Kolu', 'Siri Kolu', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'В этом году Разбойниковых ждут новые испытания на ежегодном разбойничьем фестивале. Грядут выборы глав-атамана всех кланов, и Карло Разбойников со своей командой вступает в нешуточную борьбу, и Вилье снова придется проявить свои выдающиеся аналитические способности... Это вторая книга о Вилье и ее лучших друзьях Разбойниковых - самых обаятельных и благородных бандитах финских автодорог. Первая история "Мы - Разбойниковы" принесла автору, писательнице Сири Колу, крупнейшую премию Финляндии в области детской литературы Suomen Kirjasaatio и любовь читателей по всему миру.', 'The Robbersons are revving their engines for the grand annual bandit jamboree! With elections looming for the supreme highway chieftain, Karlo Robberson and his unruly crew dive headfirst into a fierce competition. Once again, young Vilja will need all her clever wits and sharp planning to guide Finland''s warmest, wildest band of highway outlaws to victory.', 'Razbojnike čekaju novi izazovi na velikom godišnjem razbojničkom festivalu! Bliže se izbori za vrhovnog poglavicu svih klanova, a Karlo Razbojnik i njegova vesela ekipa ulijeću u pravu borbu. Djevojčica Vilja ponovo mora upotrijebiti svoju snalažljivost i oštroumnost kako bi pomogla najšarmantnijim drumskim banditima Finske da odnesu pobjedu.', 'Пристегните ремни: вас ждут безумные дорожные гонки, хоровое пение у костра и самые добродушные бандиты на свете!', 'Fasten your seatbelts for wild highway rallies, spirited campfire karaoke, and the kindest band of outlaws you''ll ever meet!', 'Vežite pojaseve za lude drumske trke, razbojničke pjesme uz logorsku vatru i najsimpatičnije bandite na svijetu!', '/covers/DP-0142.webp', '#d35400', '7-9', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["funny","adventure","friends"]', '["bandits","road trip","friendship","humor","festival"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ахап-ереч-143', 'DP-0143', 'Ахап Ереч', 'Esio Trot', 'Esio Trot', '', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'Мистер Хоппи влюблён в свою соседку, но увы, она любит другого, и этот другой — Элфи, маленькая черепашка. Миссис Силвер только об Элфи и думает, а до мистера Хоппи ей нет никакого дела. Сам же мистер Хоппи — человек застенчивый, он даже не решается пригласить соседку на чашечку чая. Но однажды его осеняет блестящая идея. Теперь он знает, как привлечь внимание миссис Силвер! Если план сработает, она непременно влюбится в мистера Хоппи. В конце концов, всем известно, что путь к сердцу женщины лежит через её черепашку.', 'Mr. Hoppy is secretly in love with his neighbor, Mrs. Silver, but she only has eyes for her pet tortoise, Alfie. Too shy to confess his feelings, Mr. Hoppy comes up with a brilliantly audacious plan involving secret tortoise spells and a whole lot of shelled stand-ins to finally win her heart.', 'Gospodin Hopi je potajno zaljubljen u svoju komšinicu, gospođu Silver, ali ona ima oči samo za svoju ljubimicu kornjaču Alfija. Previše stidljiv da prizna svoja osjećanja, gospodin Hopi smišlja genijalan i luckast plan sa tajnim kornjačjim čarolijama kako bi osvojio njeno srce.', 'Трогательная и ужасно смешная история Роальда Даля о том, что ради любви можно заговорить на черепашьем языке и провернуть грандиозную аферу!', 'A warm and wonderfully cheeky Roald Dahl tale proving that the true way to someone''s heart might just be speaking fluent tortoise!', 'Topla i duhovita priča Roalda Dala koja dokazuje da se zbog ljubavi može progovoriti i kornjačjim jezikom!', '/covers/DP-0143.webp', '#5b8a54', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["funny","animals","friends"]', '["tortoises","neighbors","humor","love story","clever trick"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('свинтусы-144', 'DP-0144', 'Свинтусы', 'The Twits', 'Grozni Tviti', '', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'Мистер и миссис Свин — самые вонючие, противные и уродливые люди в мире. А их любимое развлечение — шутить друг над другом немилосердно и безобразно. А дом у них без окон, чтобы никто не мог заглянуть внутрь. И в саду растут чертополох и крапива, чтоб ни один ребенок не бегал бы там. А еще они ловят невинных птиц, чтобы положить их в Птичий пирог, и мучают дрессированных обезьянок, заставляя их стоять на голове целый день. В общем, вы уже поняли, какая это отвратительная парочка. Но у обезьянок больше нет сил и терпения — они хотят отомстить. «Свинтусы» — первый перевод повести Роальда Даля The Twits, которая вышла в 1980 году с иллюстрациями Квентина Блейка.', 'Mr. and Mrs. Twit are the smelliest, nastiest, ugliest couple in the world. Their favorite pastime is playing foul practical jokes on each other, while keeping innocent monkeys upside down all day and baking poor birds into pies. But the clever Muggle-Wump monkeys have finally had enough and devise an ingenious, hilarious revenge.', 'Gospodin i gospođa Tvit su najodvratniji, najsmrdljiviji i najzlobniji par na svijetu. Najviše vole da jedno drugom podmeću neslane šale, love ptice za pitu i tjeraju majmune da stoje na glavama po cijeli dan. Ipak, majmunčići gube strpljenje i pripremaju im veličanstvenu, urnebesnu osvetu.', 'Неподражаемый Роальд Даль во всей своей хулиганской красе: приготовьтесь хохотать над самыми мерзкими проделками и болеть за смышлёных обезьянок!', 'Vintage Roald Dahl mischief at its absolute best — prepare for nasty pranks, belly laughs, and a glorious triumph of clever monkeys!', 'Nenadmašni Roald Dal u svom najvragolastijem izdanju: pripremite se za grozne smicalice, glasan smijeh i pobjedu pametnih majmuna!', '/covers/DP-0144.webp', '#d9822b', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["funny","animals"]', '["pranks","humor","monkeys","justice","classic","roald dahl"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('матильда-145', 'DP-0145', 'Матильда', 'Matilda', 'Matilda', 'Роальд Даль', 'Roald Dahl', 'Ruald Dal', 'Квентин Блейк', '', NULL, NULL, 7, 10, 'middle', 'Матильда маленькая и очень умненькая девочка. Очень-очень умненькая. Она сама научилась читать в три года и больше всего на свете любит книги. И не какие-нибудь там детские сказочки, а Диккенса, Хэмингуэя, Стейнбека и Киплинга. Но, к несчастью, это совсем не по вкусу ее родителям, двум довольно неприятным личностям, которые бы предпочли, чтобы она смотрела, как и они, дурацкие передачи по телевизору. И в школе маленькую Матильду ждут неприятности, потому что директриса заведения ненавидит детей и жестоко мучит их. Но к счастью, учительница Матильды невероятно добра к ней и внимательна. К тому же Матильда внезапно открывает в себе сверхъестественные способности... Как и в других историях знаменитого Роальда Даля, в «Матильде» он высмеивает глупость и ограниченность и позволяет уму и справедливости восторжествовать над ними. И заставляет смеяться и детей, и взрослых. Умных, конечно же, взрослых.', 'Matilda is an extraordinarily brilliant little girl who taught herself to read at age three and devours classics by Dickens and Hemingway. Unfortunately, her loud, obnoxious parents despise reading, and her tyrannical headmistress, Miss Trunchbull, despises children. But with the help of the wonderful Miss Honey and a sudden burst of telekinetic powers, Matilda decides it''s time to teach the grown-ups a lesson they will never forget. A timeless, laugh-out-loud masterpiece celebrating wit, resilience, and the pure joy of books.', 'Matilda je nevjerovatno pametna djevojčica koja je sama naučila da čita sa samo tri godine i više od svega na svijetu voli knjige — i to ne bajke, već Dikensa i Hemingveja. Nažalost, njeni roditelji više vole gledanje televizije, a u školi vlada zloglasna i okrutna direktorka Trančbul. Ipak, uz nježnu podršku učiteljice gđice Hani i čudesnu telekinetičku moć koju iznenada otkriva, Matilda uzima pravdu u svoje ruke. Urnebesna priča o pobjedi mudrosti i dobrote nad glupošću.', 'Вдохновляющая и невероятно смешная ода юным книголюбам, способным силой ума и капелькой магии поставить на место любых самодуров!', 'A hilarious and empowering tribute to little bookworms, proving that brainpower and a dash of magic can topple any bully!', 'Urnebesna i inspirativna priča o maloj ljubiteljki knjiga koja dokazuje da pamet i mrvica magije mogu pobijediti svaku nepravdu!', '/covers/DP-0145.webp', '#f2a900', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["funny","magic","friends"]', '["школа","книги","телекинез","юмор","классика"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('джеймс-и-чудо-персик-146', 'DP-0146', 'Джеймс и чудо-персик', 'James and the Giant Peach', 'Džejms i džinovska breskva', 'Роальд Даль', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'У Джеймса Генри Круизо погибают родители, и с этого момента его жизнь круто меняется. Он переезжает к своим тетям — Пике и Плюхе, которые заставляют его работать круглыми сутками, не кормят и всячески унижают. Мальчик несчастен. Но однажды с ним приключается немыслимо странная вещь, в результате чего на персиковом дереве во дворе вырастает гигантский Чудо-Персик. И тут начинаются приключения! И Джеймса ждут настоящие друзья, которые помогут ему осуществить заветные мечты. В 1996 году киностудия Disney сняла мультфильм по мотивам книги (хотя сам Роальд Даль при жизни отказал в предоставлении прав). В 2011 году во всем мире отмечалось 50-летие «Джеймса и Чудо-Персика», одной из самых известных и популярных книг Роальда Даля.', 'When poor James Henry Trotter is sent to live with his cruel aunts, Spiker and Sponge, life feels thoroughly miserable. But a bag of glowing crocodile tongues sparks a miracle: a colossal peach begins growing on the barren garden tree. Climbing inside its juicy core, James discovers a charming crew of oversized talking insects and embarks on a wild, airborne transatlantic voyage.', 'Nakon što izgubi roditelje, dječak Džejms dospijeva u kandže okrutnih tetki Spajker i Spong. Život mu postaje nepodnošljiv sve dok uz pomoć čarobnih zrnaca u dvorištu ne izraste džinovska breskva. Ušunjavši se unutra, Džejms upoznaje neobičnu družinu uvećanih baštenskih insekata i zajedno sa njima kreće na nevjerovatno prekookeansko putovanje.', 'Если жизнь кажется кислой, залезай в гигантский персик и лети через океан в компании обаятельных насекомых-великанов!', 'When life turns sour, just climb inside a giant magical peach and take flight with the most charming crew of oversized bugs!', 'Kada život postane težak, samo uskoči u džinovsku breskvu i zaplovi nebom sa najveselijom družinom insekata!', '/covers/DP-0146.webp', '#e7733c', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","magic","friends"]', '["роальд даль","приключения","дружба","насекомые","магия"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большой-добрый-великан-147', 'DP-0147', 'Большой добрый великан', 'The BFG', 'VDD: Veliki dobroćudni džin', 'Роальд Даль', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'В час темных сил, когда мир спит, злобные гадкие великаны пожирают людишек-плутишек. И никто, никто не может их остановить, кроме Большого и Доброго Великана. Усадив в карман своего жилета маленькую Софи, он пускается в путь, чтобы навсегда избавить мир от Кровушкипопьем, Девочкойзакусим и их ужасных дружков...', 'During the witching hour, when the world sleeps and wicked giants roam about gobbling up human beans, only one giant stands in their way: the Big Friendly Giant. Tucking little Sophie into his waistcoat pocket, the BFG embarks on a whimsical and daring quest to rid the world of the Bloodbottler, the Fleshlumpeater, and their foul friends forever.', 'U gluvo doba noći, dok cijeli svijet spava, zli divovi proždiru ljude. Niko ih ne može zaustaviti osim Velikog dobroćudnog džina. Sa malom Sofi u džepu svog prsluka, VDD kreće u nevjerovatnu avanturu da zauvijek spasi svijet od strašnih ljudoždera.', 'Приготовьтесь пить бурбл и ловить чудесные сны вместе с самым чутким ушастым великаном на свете!', 'Get ready to sip frobscottle and catch magical dreams with the kindest, biggest-eared giant in literature!', 'Pripremite se za hvatanje snova i neobične riječi uz najnježnijeg džina velikih ušiju na svijetu!', '/covers/DP-0147.webp', '#2c4c64', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["magic","adventure","funny"]', '["giants","dreams","friendship","humor","classics"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чарли-и-шоколадная-фабрика-148', 'DP-0148', 'Чарли и шоколадная фабрика', 'Charlie and the Chocolate Factory', 'Čarli i fabrika čokolade', 'Роальд Даль', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'Загадочный владелец шоколадной фабрики мистер Вонка наконец-то открывает ее двери! Но только перед пятью счастливчиками, которые нашли золотой билет в шоколадках Вонка, и в конце их ждет большой сюрприз. Кто же они? Толстый обжора Август Глуп, избалованная грубиянка Верука Солт, амбициозная потребительница жвачки Виолетта Бьюргард, зомбированный телевидением Майк Тиви и Чарли Бакет. Скромный, умный, честный, благородный, смелый и... в общем, каким и должен быть настоящий герой. «Чарли и Шоколадная фабрика» — одна из самых известных и популярных детских книг в мире. Полная фантазии и иронии повесть была переведена на множество языков и дважды экранизирована.', 'The eccentric chocolatier Willy Wonka is finally opening the gates of his wondrous factory, but only to five lucky golden ticket holders! Among greedy gluttons, spoiled brats, and screen addicts stands young, humble Charlie Bucket. A world of pure imagination, mouth-watering candy, and unforgettable surprises awaits behind those mysterious gates.', 'Misteriozni vlasnik fabrike čokolade, gospodin Vili Vonka, konačno otvara svoja vrata za samo pet srećnih dobitnika Zlatne ulaznice. Među razmaženom i pohlepnom djecom nalazi se i skromni, plemeniti dječak Čarli Baket. Čeka ih nevjerovatno putovanje kroz slatka čuda, neobične izume i velika iznenađenja.', 'Держите золотой билет крепче — внутри вас ждут шоколадные водопады, озорные умпа-лумпы и море сладкого волшебства!', 'Hold onto your Golden Ticket tightly—chocolate waterfalls, mischievous Oompa-Loompas, and pure sweet magic await inside!', 'Čvrsto držite svoju Zlatnu ulaznicu — unutra vas čekaju čokoladni vodopadi, nestašni Umpa-Lumpe i čista magija slatkiša!', '/covers/DP-0148.webp', '#6d3b1e', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["magic","adventure","funny"]', '["chocolate","classic","willy wonka","golden ticket","sweets"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чарли-и-большой-стеклянный-лиф-149', 'DP-0149', 'Чарли и большой стеклянный лифт', 'Charlie and the Great Glass Elevator', 'Čarli i veliki stakleni lift', 'Роальд Даль', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'Помните, как Чарли Бакет в конце книги «Чарли и шоколадная фабрика» взлетел в небо в большом стеклянном лифте? Что ж, вперед, к новым захватывающим приключениям! Лифт набирает скорость, и Чарли, Вилли Вонка и вся компания несутся сквозь время и пространство. Посещение первого в мире Космического отеля, битва со злобными вермизлюками, спасение мира — лишь несколько эпизодов их незабываемого космического путешествия. «Чарли и Шоколадная фабрика» ― одна из самых известных и популярных детских книг в мире. Полная фантазии и иронии повесть была переведена на множество языков и дважды экранизирована.', 'Charlie Bucket has won the chocolate factory, but the adventure is far from over! Blasting into orbit aboard Mr. Willy Wonka’s extraordinary Great Glass Elevator, Charlie and his family encounter the world''s first Space Hotel, battle ferocious Vermicious Knids, and embark on a cosmic escapade packed with classic Dahlian wit, danger, and boundless imagination.', 'Čarli Baket je osvojio fabriku čokolade, ali avantura tek počinje! Lansirajući se pravo u orbitu u čudesnom staklenom liftu gospodina Vilija Vonke, Čarli i njegova porodica posjećuju prvi Svemirski hotel na svijetu, bore se protiv opasnih svemirskih nemani i doživljavaju nezaboravnu odiseju punu humora i mašte.', 'Пристегните ремни: стеклянный лифт мистера Вонки вылетает прямо на орбиту — навстречу инопланетянам и уморительному космическому хаосу!', 'Fasten your seatbelts: Mr. Wonka’s elevator is shooting straight into orbit for an unforgettable romp with aliens and sheer cosmic mischief!', 'Vežite pojaseve: stakleni lift gospodina Vonke lansira se pravo u orbitu u urnebesnu svemirsku avanturu punu vanzemaljaca!', '/covers/DP-0149.webp', '#2d4059', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","funny","magic"]', '["space","aliens","roald dahl","willy wonka","humor"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебный-палец-150', 'DP-0150', 'Волшебный палец', 'The Magic Finger', 'Čarobni prst', 'Роальд Даль', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'Как еще объяснить кровожадным охотникам, что стрелять в беззащитных животных ради развлечения — это ужасно! Все вокруг говорят об этом, но никакие увещевания на людей не действуют. Зато восьмилетняя девочка смогла отучить своих соседей от бессмысленной жестокости с помощью волшебного пальца. Утки и охотники поменялись на время местами, но птицы оказались милосерднее, и люди запомнили их урок на всю жизнь.', 'How else can you teach hunters that shooting defenseless animals for fun is cruel? When all reasoning fails, an eight-year-old girl uses her extraordinary magic finger to give her neighbors a taste of their own medicine. The ducks and the hunters suddenly swap places, teaching the Gregg family an unforgettable lesson about empathy and kindness.', 'Kako objasniti lovcima da je ubijanje nedužnih životinja iz zabave strašno? Niko ih nije mogao ubijediti dok jedna osmogodišnja djevojčica nije upotrijebila svoj čarobni prst! Patke i lovci odjednom mijenjaju uloge, a porodica Greg dobija nezaboravnu lekciju o saosjećanju i dobroti.', 'Будьте осторожны, когда сердите восьмилетнюю девочку с волшебным пальцем, иначе проснётесь с перьями и крыльями вместо рук!', 'Think twice before upsetting an eight-year-old girl with a magic finger, or you might just wake up with duck wings instead of arms!', 'Pazite da ne naljutite osmogodišnju djevojčicu sa čarobnim prstom, jer biste se mogli probuditi s perjem i krilima umjesto ruku!', '/covers/DP-0150.webp', '#6a3d82', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["magic","funny","animals"]', '["ducks","magic powers","transformation","empathy","classic"]', 1792836322695, 1792845662001);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ведьмы-151', 'DP-0151', 'Ведьмы', 'The Witches', 'Vještice', 'Роальд Даль', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'Это правдивая история про самых настоящих ведьм, которые, оказывается, живут среди нас и ненавидят детей. Уничтожить ребенка для Ведьмы — это высшее наслаждение. Поэтому очень важно научиться распознавать её среди обычных женщин. В этой истории у главного героя есть умная и наблюдательная бабушка, которая знает все про ведьминские повадки и рассказывает внуку, как избежать нежелательной встречи. Но все это оказывается напрасным, когда однажды он сталкивается лицом к лицу с Величайшей Самой Главной Ведьмой Всех Времен…', 'This is a true story about real witches who live right among us and utterly despise children. To get rid of a child is the ultimate delight for a witch, which makes it crucial to learn how to spot one hiding beneath an ordinary disguise. Luckily, the young hero has a wise, observant grandmother who knows every witchy habit and teaches him how to stay safe. But all the warnings are put to the ultimate test when he comes face-to-face with the terrifying Grand High Witch of All the World...', 'Ovo je istinita priča o pravim vješticama koje žive među nama i iz dna duše mrze djecu. Uništiti dijete za vješticu predstavlja najveće zadovoljstvo, pa je izuzetno važno naučiti kako ih prepoznati među običnim ženama. Glavni junak ima mudru i oštroumnu baku koja zna sve o njihovim navikama i uči unuka kako da ih izbjegne. Međutim, sve to pada u vodu kada se dječak nađe licem u lice sa Velikom Vrhovnom Vješticom Svih Vremena...', 'Жутковатая, уморительная и захватывающая классика, после которой вы непременно станете с подозрением приглядываться к дамам в перчатках!', 'A deliciously spooky, hilarious classic that will have you forever eyeing women in gloves with deep suspicion!', 'Pomalo jeziv, urnebesan i uzbudljiv klasik nakon kojeg ćete zauvijek sumnjičavo posmatrati dame u rukavicama!', '/covers/DP-0151.webp', '#4a2a6b', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["spooky","adventure","magic"]', '["witches","magic","roald dahl","bravery","humor"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('полеты-в-одиночку-152', 'DP-0152', 'Полеты в одиночку', 'Going Solo', 'Solo letenje', 'Роальд Даль', 'Roald Dahl', 'Roald Dal', '', '', NULL, NULL, 7, 10, 'middle', 'Вторая мировая война застала Роальда Даля в Восточной Африке, куда он, вчерашний школьник, отправился за романтикой и приключениями — и получил их сполна. Он записался добровольцем в авиацию и стал лётчиком-истребителем, участвовал в воздушных сражениях и выполнял секретные задания... Об этом, а ещё о змеях и львах, о великих африканских воинах, о «харрикейнах» и «мессершмиттах» — захватывающая повесть «Полёты в одиночку». И, кстати, написана она с неподражаемым юмором, как и все остальные всемирно известные книги Сказочника № 1 в мире.', 'World War II caught young Roald Dahl in East Africa, where he had gone seeking romance and adventure—and found more than he bargained for. Enlisting in the Royal Air Force, he became a fighter pilot in dogfights across the Mediterranean. Filled with encounters with black mambas, lions, and Messerschmitts, this thrilling autobiographical tale is written with the inimitable humor and heart of the world''s master storyteller.', 'Drugi svjetski rat zatekao je mladog Roalda Dala u istočnoj Africi, gdje je otišao u potragu za romantikom i avanturom. Prijavio se u Kraljevsko ratno vazduhoplovstvo, postao pilot-lovac i preživio nevjerovatne vazdušne bitke. Ispunjena susretima sa mambama, lavovima i ratnim avionima, ova uzbudljiva autobiografska priča napisana je sa neponovljivim humorom omiljenog pripovjedača.', 'Настоящие подвиги, чёрные мамбы и воздушные бои: Роальд Даль доказывает, что его собственная жизнь была круче любой сказки!', 'Real-life dogfights, deadly mambas, and survival against all odds: Roald Dahl proves his own youth was as wild as any of his stories!', 'Pravi vazdušni dueli, smrtonosne mambe i nevjerovatna hrabrost: Roald Dal dokazuje da je njegov stvarni život bio uzbudljiviji od bilo koje bajke!', '/covers/DP-0152.webp', '#3b6e8c', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","real","funny"]', '["autobiography","aviation","africa","world war ii","pilots"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебник-изумрудного-города-153', 'DP-0153', 'Волшебник изумрудного города', 'The Wizard of the Emerald City', 'Čarobnjak iz Smaragdnog grada', 'Волков', 'Alexander Volkov', 'Aleksandar Volkov', '', '', NULL, NULL, 7, 10, 'middle', 'Книгами Александра Мелентьевича Волкова, написанными в середине прошлого века, зачитывались дети нескольких поколений. Но и в наше время истории о смелой девочке Элли и ее друзьях, которые отправились к великому волшебнику Гудвину, чтобы он исполнил их самые заветные желания, читаются на одном дыхании. Волков не просто талантливо переложил для русских детей сюжет американского писателя Фрэнка Баума, но подарил своим маленьким читателям множество новых приключений любимых героев – Элли и Тотошки, Страшилы, Железного Дровосека и Льва.', 'Generations of children have grown up cherishing Alexander Volkov''s beloved mid-century tales. Today, the story of brave Ellie and her companions journeying to the Great Wizard Goodwin to fulfill their deepest wishes remains as captivating as ever. Volkov didn''t simply adapt L. Frank Baum''s American classic—he gifted young readers a vibrant universe filled with thrilling adventures alongside Ellie, Toto, Scarecrow, the Tin Woodman, and the Cowardly Lion.', 'Knjige Aleksandra Volkova očaravale su generacije djece, a i danas se priča o hrabroj djevojčici Eli i njenim prijateljima koji kreću kod velikog čarobnjaka Gudvina čita u jednom dahu. Volkov nije samo vješto prilagodio radnju američkog pisca Frenka Bauma, već je stvorio čitav čarobni svijet pun novih avantura sa Eli, psićem Totoškom, Strašilom, Gvozdenim Drvosječom i Plašljivim Lavom.', 'Надевайте серебряные башмачки: дорога из жёлтого кирпича проверит на прочность дружбу, ум, сердце и смелость!', 'Slip into the silver shoes: the yellow brick road is ready to test friendship, brains, heart, and courage!', 'Obujte srebrne cipelice: put od žute cigle staviće na probu pravo prijateljstvo, mudrost, srce i hrabrost!', '/covers/DP-0153.webp', '#1b7a43', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","magic","friends"]', '["fairy tale","friendship","emerald city","classic","journey"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('урфин-джюс-и-его-деревянные-со-154', 'DP-0154', 'Урфин Джюс и его деревянные солдаты', 'Urfin Jus and His Wooden Soldiers', 'Urfin Džus i njegovi drveni vojnici', '', 'Aleksandr Volkov', 'Aleksandar Volkov', '', '', NULL, NULL, 7, 10, 'middle', 'Продолжение истории «Волшебника Изумрудного Города». Урфин Джюс, помощник погибшей злой колдуньи Гингемы, занимает место правителя. Ему удается раздобыть волшебный порошок, с помощью которого можно оживить любой предмет, и теперь честолюбивый Урфин строит планы по завоеванию Изумрудного города. Страшиле, Железному Дровосеку и остальным жителям города вновь требуется помощь Элли, чтобы защитить город и жителей. Только в этот раз к Элли приходит не одна, а со своим дядей Чарли – отважным и смелым моряком.', 'In this thrilling sequel to ''The Wizard of the Emerald City'', the ambitious Urfin Jus discovers a magical powder that brings any inanimate object to life. Carving an army of ruthless wooden soldiers, he marches to conquer the Emerald City. Scarecrow and the Tin Woodman desperately need Ellie''s help once again—and this time she brings her brave uncle, Sailor Charlie!', 'U uzbudljivom nastavku priče o Čarobnjaku iz Smaragdnog grada, ambiciozni Urfin Džus dolazi do čarobnog praha koji može oživjeti svaki predmet. Nakon što stvori čitavu armiju drvenih vojnika, kreće u osvajanje Smaragdnog grada. Strašilu i Gvozdenom Drvosječi ponovo je potrebna Elina pomoć, a ovoga puta u pomoć stiže i njen hrabri ujak, mornar Čarli.', 'Осторожно: ожившие деревянные дуболомы маршируют прямо на Изумрудный город, и спасти всех может только верная дружба и смекалка!', 'Watch out: an army of wooden soldiers is marching on the Emerald City, and only true friendship and clever wit can save the day!', 'Pazite se: armija oživjelih drvenih vojnika maršira ka Smaragdnom gradu, a samo pravo prijateljstvo i snalažljivost mogu spasiti stvar!', '/covers/DP-0154.webp', '#3a7d44', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","magic","friends"]', '["emerald city","fairy tale","magic powder","wooden soldiers","classic"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('семь-подземных-королей-155', 'DP-0155', 'Семь подземных королей', 'The Seven Underground Kings', 'Sedam podzemnih kraljeva', '', 'Alexander Volkov', 'Aleksandar Volkov', '', '', NULL, NULL, 7, 10, 'middle', 'В третий раз Элли попадает в Волшебную страну, теперь в Царство семи подземных королей, расположенное под землей. Жители и правители этого царства принимают ее за фею и требуют от нее починить источник «усыпительной воды». Теперь самой Элли требуется помощь Страшилы, Железного Дровосека и Льва, которые сразу спешат на помощь.', 'For the third time, Ellie finds herself in the Magic Land, this time trapped in the subterranean realm of seven squabbling kings. Believing she is a mighty fairy, the rulers demand she restore their dried-up spring of ''sleeping water.'' Now Ellie must rely on her trusty companions—the Scarecrow, the Tin Woodman, and the Cowardly Lion—to launch a daring rescue mission.', 'Po treći put Eli dospijeva u Čarobnu zemlju, ovog puta duboko ispod zemlje u carstvo sedam posvađanih kraljeva. Smatrajući je moćnom vilom, vladari traže da im popravi presušeni izvor „uspavljujuće vode“. Kako bi se spasila, Eli računa na vjerne prijatelje — Strašila, Gvozdenog Drvosječu i Lava — koji hitaju u podzemlje u smjelu akciju spasavanja.', 'Интриги под землёй, пещерные драконы, усыпительная вода и старые добрые друзья, готовые спуститься в самые тёмные глубины ради спасения Элли!', 'Underground court intrigue, cave dragons, sleeping water, and loyal old friends ready to tunnel into the deepest caves to save Ellie!', 'Podzemne spletke, pećinski zmajevi, uspavljujuća voda i odani prijatelji koji hrabro silaze u najmračnije dubine da spasu Eli!', '/covers/DP-0155.webp', '#4b3f72', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","magic","friends"]', '["magic land","underground world","friendship","fairytale","rescue mission"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ж-лтый-туман-156', 'DP-0156', 'Жёлтый туман', 'The Yellow Fog', 'Žuta magla', '', 'Alexander Volkov', 'Aleksandar Volkov', '', '', NULL, NULL, 7, 10, 'middle', 'Проснувшись после пяти тысяч лет сна, злая великанша и колдунья Арахна обнаруживает вокруг себя Волшебную страну, полную добрых и беззащитных жителей. Она решает завоевать их, используя Жёлтый Туман, который погружает мир во мрак и вызывает зиму. Однако Элли, Тим и Чарли Блек готовы прийти на помощь своим друзьям, а им поможет и Железный рыцарь Тилли-Вилли.', 'Waking up from a five-thousand-year slumber, the wicked giant sorceress Arachna discovers the Magic Land inhabited by kind and defenseless folk. She decides to conquer them by unleashing the toxic Yellow Fog, which plunges the world into freezing gloom. Luckily, Ellie, Tim, Uncle Charlie, and the giant iron knight Tilly-Willy set out on an epic rescue mission!', 'Nakon što se probudila iz pet hiljada godina dugog sna, zla džinovska čarobnica Arahna otkriva Čarobnu zemlju punu dobrih stanovnika. Odlučuje da ih pokori pomoću Žute magle koja donosi zimu i tamu. Ipak, Eli, Tim i mornar Čarli Blek, uz pomoć džinovskog gvozdenog viteza Tili-Vilija, kreću u odvažnu spasilačku misiju!', 'Приготовьте противогазы и верных друзей: в Волшебной стране туманно, но железный рыцарь Тилли-Вилли уже спешит на выручку!', 'Grab your goggles and rally your friends: a noxious mist has blanketed the Magic Land, but the giant iron knight Tilly-Willy is ready to smash through it!', 'Spremite se za akciju i okupite prijatelje: Čarobna zemlja je u gustoj magli, ali gvozdeni vitez Tili-Vili stiže u pomoć!', '/covers/DP-0156.webp', '#d9a732', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","magic","friends"]', '["magic land","fairy tale","giant","teamwork","friendship"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('огненный-бог-марранов-157', 'DP-0157', 'Огненный бог Марранов', 'The Fiery God of the Marrans', 'Ognjeni bog Marana', '', 'Alexander Volkov', 'Aleksandar Volkov', '', '', NULL, NULL, 7, 10, 'middle', 'Повесть-сказка «Огненный бог Марранов» продолжает рассказ о событиях, происходящих в Волшебной стране. Хитроумный Урфин Джюс, назвав себя «огненным богом», решил стать правителем страны. Страшила, Железный Дровосек и гости из-за гор снова приходят на помощь её жителям.', 'The fairy tale continues the chronicle of the Magic Land. The cunning Urfin Jus proclaims himself the ''fiery god'' in a bid to conquer the realm once more. The Scarecrow, the Tin Woodman, and faithful friends from beyond the mountains must unite again to save their home.', 'Bajkovita pripovijest nastavlja hroniku Čarobne zemlje. Lukavi Urfin Džus proglasi sebe ''ognjenim bogom'' u novom pokušaju da zagospodari zemljom. Strašilo, Limeni Drvosječa i prijatelji preko planina ponovo pristižu u pomoć.', 'Урфин Джюс снова взялся за старое, но против верной дружбы и изобретательности бессильны даже мнимые боги!', 'Urfin Jus is up to his old tricks again, but even phony gods can''t stand against genuine friendship and wits!', 'Urfin Džus se opet vratio starim smicalicama, ali čak ni lažni bogovi ne mogu pobijediti pravo prijateljstvo!', '/covers/DP-0157.webp', '#d35400', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","magic","friends"]', '["volkov","magic land","fairy tale","friendship","bravery"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-заброшенного-замка-158', 'DP-0158', 'тайна заброшенного замка', 'The Mystery of the Abandoned Castle', 'Tajna napuštenog dvorca', '', 'Alexander Volkov', 'Aleksandar Volkov', '', '', NULL, NULL, 7, 10, 'middle', 'В этой повести на территории Волшебной страны высаживается космический корабль «Диавона» с планеты Рамерия. Население планеты делится на арзаков и менвитов, верховным правителем которых является Гван-Ло. Арзаки — талантливый и трудолюбивый народ, но менвиты смогли подчинить их, используя гипноз. Инопланетяне, вооружённые лучевыми пистолетами, основали недалеко от старинного замка Гуррикапа свой лагерь Ранавир и попытались захватить власть во всей Волшебной стране. Но на помощь её жителям вновь прибыли Энни Смит и Тим О’Келли. На этот раз их сопровождал Альфред Каннинг. Жителям Волшебной страны удалось дать отпор пришельцам. В конце концов арзаки усыпили с помощью усыпительной воды всех менвитов, кроме Кау-Рука, перешедшего на сторону арзаков. Кау-Рук сообщил на Рамерию, что Земля непригодна для жизни и надо отказаться от попыток её захвата, после чего звездолёт рамерийцев отправился на родину.', 'In this final adventure, a starship from the planet Rameria lands in the Magic Land. The hypnotic Menvits set up camp near Gurrikap''s ancient castle and plot conquest, but Annie, Tim, and their loyal fairytale companions join forces with the oppressed Arzaks to outwit the high-tech invaders with courage, camaraderie, and enchanted sleeping water.', 'U ovoj uzbudljivoj avanturi, svemirski brod sa planete Ramerije slijeće pravo u Čarobnu zemlju. Osvajači Menviti dižu bazu blizu Gurikapovog drevnog dvorca s ciljem pokoravanja cijelog vilinskog svijeta, ali Eni, Tim i njihovi vjerni prijatelji udružuju se sa potlačenim Arzacima kako bi lukavstvom i magijom nadmudrili vanzemaljce.', 'Звездолёты, гипноз и лазеры против магии и дружбы — грандиозная битва за Волшебную страну в любимом цикле!', 'Alien ray-guns clash with fairytale sorcery in this thrilling sci-fi finale to the beloved Magic Land saga!', 'Svemirski brodovi protiv vilinske magije — spektakularni završni okršaj za spas Čarobne zemlje!', '/covers/DP-0158.webp', '#394a6d', '7-9', 'ru', 'available', 'Категория: Роальд Даль', '["adventure","magic","friends"]', '["magic land","aliens","castle","friendship","fairytale"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гарри-поттер-и-философский-кам-159', 'DP-0159', 'Гарри Поттер и философский камень. книга 1', 'Harry Potter and the Philosopher''s Stone', 'Hari Poter i Kamen mudrosti', 'Джоан Роулинг', 'J.K. Rowling', 'Dž. K. Rouling', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Книга, покорившая мир, эталон литературы для читателей всех возрастов, синоним успеха. Книга, сделавшая Джоан Роулинг самым читаемым писателем современности. Книга, ставшая культовой уже для нескольких поколений. «Гарри Поттер и Философский камень» - история начинается.', 'The legendary tale that captivated readers across the globe. Follow eleven-year-old orphan Harry Potter as he discovers he is a wizard, leaves the dreary human world behind, and steps through the gates of Hogwarts School of Witchcraft and Wizardry.', 'Legendarno remek-djelo koje je osvojilo čitaoce širom svijeta. Pratite jedanaestogodišnjeg siročeta Harija Potera dok otkriva da je čarobnjak, napušta sivi svijet običnih ljudi i ulazi u čarobni Hogvorts.', 'Осторожно: как только вы откроете это письмо из Хогвартса, ваш привычный мир навсегда наполнится магией!', 'Careful: the moment you open this letter from Hogwarts, your everyday world will never be the same!', 'Pazite: čim otvorite ovo pismo iz Hogvortsa, vaš obični svijet zauvijek će postati magičan!', '/covers/DP-0159.webp', '#8b1525', '7-9', 'ru', 'available', 'перевод Марии Спивак', '["magic","adventure","friends"]', '["hogwarts","wizards","magic school","friendship","fantasy"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дары-сметри-книга-7-160', 'DP-0160', 'Дары сметри. книга 7', 'Harry Potter and the Deathly Hallows (Book 7)', 'Hari Poter i relikvije Smrti (Knjiga 7)', 'Джоан Роулинг', 'J.K. Rowling', 'Dž. K. Rouling', '', 'Росмэн', NULL, NULL, 7, 10, 'middle', 'Книга "Гарри Поттер и дары смерти" рассказывает о седьмом годе обучения Гарри и его друзей в школе магии и волшебства Хогвартс. Пожалуй, это — самая захватывающая, интригующая и занимательная из всех книг про Гарри Поттера, ведь она завершает цикл про знаменитого волшебника в очках. Чем же завершится приключения Гарри? Будет ли повержен Волан-де-Морт? Что станет с Роном и Гермионой? На все эти и многие другие вопросы вы сможете найти ответы, лишь купив книгу «Гарри Поттер и дары смерти», в которой завершается история о «мальчике, который выжил».', 'The epic finale to the saga of the Boy Who Lived! Harry, Ron, and Hermione leave Hogwarts behind on an urgent, dangerous quest to find and destroy the remaining Horcruxes. Loyalty, courage, and true friendship face their greatest test in the ultimate battle to defeat Voldemort and save the wizarding world.', 'Epski završetak sage o dječaku koji je preživio! Hari, Ron i Hermiona napuštaju Hogvorts i kreću u opasnu potragu za preostalim Horkruksima lorda Voldemora. Prijateljstvo, hrabrost i najveća iskušenja naći će se na ispitu u konačnoj bici za spas čarobnjačkog svijeta.', 'Приготовьте платочки и держите палочки наготове — грандиозная финальная битва за Хогвартс начинается прямо сейчас!', 'Grab some tissues and keep your wands at the ready — the epic final battle for Hogwarts begins right now!', 'Pripremite maramice i držite štapiće spremne — epska konačna bitka za Hogvorts počinje upravo sada!', '/covers/DP-0160.webp', '#2b4657', '7-9', 'ru', 'available', 'Категория: Гарри Поттер и тайная комната. книга 2', '["magic","adventure","friends"]', '["harry potter","wizards","hogwarts","friendship","epic battle"]', 1792836322695, 1792845613251);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('фантастические-твари-и-где-они-161', 'DP-0161', 'Фантастические твари и где они обитают', 'Fantastic Beasts and Where to Find Them', 'Fantastične zvijeri i gdje ih naći', 'Джоан Роулинг', 'J.K. Rowling', 'J. K. Rowling', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Книга «Фантастические твари и где они обитают» есть практически во всех колдовских домах. Кроме того, она – обязательный учебник в школе колдовства и ведьминских искусств «Хогварц».', 'An indispensable guide found in almost every wizarding home and a required textbook at Hogwarts School of Witchcraft and Wizardry, detailing the extraordinary habits of magical creatures across the globe.', 'Obavezni udžbenik u školi čarobnjaštva Hogvorts i nezaobilazna knjiga u gotovo svakom magičnom domu, koja detaljno opisuje neobične navike čarobnih stvorenja širom svijeta.', 'Загляните в настоящий учебник Гарри Поттера — только берегите блестящие вещи, а то нюхлер мигом утащит их в свою нору!', 'Peek into Harry Potter''s own textbook—just hold onto your shiny library card before a mischievous Niffler spots it!', 'Zavirite u pravi udžbenik Harija Potera — samo pripazite na sjajne stvari, da ih nestašni šnjofavac ne odvuče u svoju jazbinu!', '/covers/DP-0161.webp', '#7a2e22', '7-9', 'ru', 'available', 'перевод Марии Спивак', '["magic","animals","adventure"]', '["harry potter","magical creatures","hogwarts","guide","wizards"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('часодеи-часовой-ключ-162', 'DP-0162', 'Часодеи часовой ключ', 'Chasodei: The Time Key', 'Časodeji: Časovni ključ', 'Наталья Щерба', 'Natalia Shcherba', 'Natalija Ščerba', '', 'Росмэн', NULL, NULL, 7, 10, 'middle', 'Василиса - обычная земная девочка, живущая с бабушкой, - неожиданно узнает, что ее отец - влиятельный маг Эфлары, мира, построенного на особой часовой магии. Попав в страну часодеев, фей и лютов, Василиса оказывается в центре опасной игры. Даже друзья не могут понять, кто же она сама? Неумеха, ничего не знающая о своем происхождении? Шпионка, засланная отцом, чтобы заполучить трон? Или могущественная часовщица, которая умеет управлять временем и может спасти Землю и Эфлару от грядущего столкновения? Кроме России и Украины, произведение было издано в Польше, Чехии, Словакии и Венгрии.', 'Vasilisa is an ordinary girl living with her grandmother until she discovers her estranged father is an influential mage from Ephlara, a realm governed by clock magic. Thrust into a hidden world of time-crafters, fairies, and fierce spirits, Vasilisa finds herself in the center of a dangerous contest. Can she master the secrets of time before two colliding worlds unravel?', 'Vasilisa je obična djevojčica koja živi s bakom, sve dok iznenada ne sazna da je njen otac moćan mag iz Eflare — tajnog svijeta zasnovanog na magiji vremena. Našavši se u zemlji časodeja, vila i duhova, Vasilisa upada u centar opasne igre moći. Može li savladati tajne vremena prije nego što se dva svijeta nepovratno sudare?', 'Приготовьтесь завести воображение на полную мощность — время здесь течет совсем не так, как на уроках математики!', 'Wind up your imagination, because time in this magical realm ticks to an exhilarating rhythm you won''t want to stop!', 'Pripremite se da navijete maštu — vrijeme u ovoj čarobnoj priči teče potpuno drugačije nego na časovima matematike!', '/covers/DP-0162.webp', '#8c5a2b', '7-9', 'ru', 'available', 'Категория: Гарри Поттер и тайная комната. книга 2', '["magic","adventure"]', '["fantasy","time magic","parallel worlds","clocks","mystery"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('фабр-восстание-жуков-163', 'DP-0163', 'Фабр восстание жуков', 'Beetle Boy', 'Dječak buba', 'Майя Леонард', 'M.G. Leonard', 'M. G. Leonard', '', 'Робинс', NULL, NULL, 7, 10, 'middle', 'Отец Даркуса, Бартоломью Катл, таинственным образом исчезает из закрытого кабинета Музея естествознания в Лондоне. Полиция сбита с толку - как и куда мог пропасть заслуженный учёный? Жизнь мальчика меняется: он попадает в дом к своему дяде Максу, в новую школу, где заводит друзей, но самое главное - у него появляется Бакстер, огромный чёрный жук-носорог, который - о чудо! - понимает его с полуслова. Даркус намерен найти своего пропавшего отца во что бы то ни стало. Но его планам может помешать сумасшедшая учёная-генетик Лукреция Каттэр, которая задумала ужасный план уничтожения мира. Стремительный вихрь таинственных событий, детективного расследования, потрясающих открытий и захватывающих приключений - всё это увлекает юного читателя в удивительный фэнтезийно-приключенческий мир!', 'When Darkus Cuttle''s father mysteriously vanishes from a locked room in London''s Natural History Museum, Darkus is determined to track him down. Moving in with his eccentric uncle, he meets new friends and discovers an extraordinary ally: Baxter, a giant rhinoceros beetle who understands him completely. Together with an army of beetles, Darkus must unravel clues and stop the villainous geneticist Lucretia Cutter in this thrilling, beetle-powered mystery adventure.', 'Kada otac dječaka Darkusa zagonetno nestane iz zaključanog kabineta Muzeja prirodne istorije u Londonu, policija ostaje bez odgovora. Darkus odlučuje da ga pronađe po svaku cijenu, a u tome mu pomaže nevjerovatan saveznik – divovska buba nosorog po imenu Bakster, koja ga savršeno razumije. Zajedno sa prijateljima i vojskom buba, Darkus kreće u uzbudljivu i opasnu detektivsku avanturu protiv zle naučnice Lukrecije Kater.', 'Приготовьтесь полюбить жуков всем сердцем, ведь это захватывающий детектив о верной дружбе и шестиногих супергероях!', 'Get ready to fall in love with insects in this gripping, heartwarming mystery powered by courage, friendship, and six-legged superheroes!', 'Spremite se da zavolite insekte uz ovu napetu i toplu detektivsku priču o prijateljstvu, hrabrosti i šestonožnim superherojima!', '/covers/DP-0163.webp', '#236852', '7-9', 'ru', 'available', 'Категория: Гарри Поттер и тайная комната. книга 2', '["adventure","animals","friends"]', '["beetles","detective","friendship","insects","mystery"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-не-верю-в-моснстров-164', 'DP-0164', 'Я не верю в моснстров', 'There''s a Boy in the Girls'' Bathroom', 'Ne vjerujem u čudovišta', 'Луис Сашар', 'Louis Sachar', 'Luis Sašar', '', 'Розовый жираф', NULL, NULL, 7, 10, 'middle', 'Почти в каждом классе есть такой человек. Как говорится, отпетый. Он сидит на последней парте. Уроков никогда не делает. По всем предметам у него двойки, а когда его стыдят, он только ухмыляется. Учителя давно махнули на него рукой, одноклассники от него шарахаются. Он врет по делу и без дела, частенько противореча сам себе. То он лезет в драку, то вымогает у кого-то деньги, то угрожает девочкам, то толкает малышей. Понятно, что все его ненавидят. Но знает ли кто-нибудь, что чувствует он сам? Оказывается, есть способ выяснить это наверняка. Какой? Подружиться с ним. Неужели найдется человек, готовый дружить с таким монстром?', 'Almost every classroom has a kid like Bradley Chalkers: he sits in the back, never does his homework, tells bizarre lies, and picks fights with everyone. The teachers have given up on him, and his classmates avoid him like the plague. But Carla, the warm-hearted new school counselor, sees right through his prickly defenses. She believes Bradley isn''t a monster at all—he''s just a boy who has never had a real friend.', 'U skoro svakom odjeljenju postoji dijete poput Bredlija: sjedi u zadnjoj klupi, nikad ne piše domaći, stalno izmišlja priče i pravi probleme. Učitelji su digli ruke od njega, a vršnjaci ga izbjegavaju. Ali nova školska psihološkinja Karla odbija da povjeruje da je on beznadežan slučaj. Ona dobro zna da se iza maske „čudovišta” krije dječak kome je samo očajnički potreban prijatelj.', 'Трогательная и удивительно смешная школьная классика о том, что даже самому колючему хулигану больше всего на свете нужны понимание и верный друг.', 'A tender, laugh-out-loud funny school classic proving that even the classroom''s prickliest troublemaker is just waiting for someone to believe in him.', 'Dirljiva i duhovita priča koja nas podsjeća da se iza najbodljikavijeg ponašanja često krije neko ko samo čezne za razumijevanjem i pravim prijateljem.', '/covers/DP-0164.webp', '#3e7864', '7-9', 'ru', 'available', 'Категория: Гарри Поттер и тайная комната. книга 2', '["real","friends","funny"]', '["school life","empathy","friendship","growing up","counseling"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-камо-165', 'DP-0165', 'Приключения Камо', 'The Adventures of Kamo', 'Kamoove avanture', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Самокат', NULL, NULL, 7, 10, 'middle', 'Это приключения двух французских школьников — Камо и его лучшего друга, которые попадают в невероятные, порой фантастические ситуации. Это истории о любви и разочаровании, о доме и школе, о родителях и учителях, о настоящей дружбе и взаимопонимании и обо всем том, что бывает, когда тебе десять лет, когда впереди такая долгая и прекрасная жизнь.', 'Follow the unforgettable adventures of two French schoolboys, Kamo and his loyal best friend, as they tumble into extraordinary, hilarious, and almost fantastical dilemmas. Packed with wit, warmth, and mischief, these stories explore home life, school rivalries, quirky parents, eccentric teachers, and the magic of true friendship when you are ten years old and life is just getting started.', 'Pratite nezaboravne avanture dvojice francuskih đaka — Kamoa i njegovog najboljeg druga — koji upadaju u nevjerovatne, urnebesne i pomalo fantastične zavrzlame. Puna topline i vrcavog humora, ova knjiga donosi priče o školi, roditeljima, neobičnim nastavnicima i neraskidivom prijateljstvu kada imaš deset godina i čitav svijet pred sobom.', 'Искромётные и трогательные парижские школьные хроники, в которых каждый неугомонный третьеклассник узнает себя и своего лучшего друга!', 'Sparkling, witty, and heartwarming Parisian school chronicles where every energetic ten-year-old will spot themselves and their best friend!', 'Vrcave, duhovite i tople pariske školske hronike u kojima će svaki nestašni desetogodišnjak prepoznati sebe i svog najboljeg druga!', '/covers/DP-0165.webp', '#2c6b9e', '7-9', 'ru', 'available', 'Категория: Гарри Поттер и тайная комната. книга 2', '["funny","friends","adventure"]', '["school life","friendship","humor","french literature","growing up"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('загадка-исчезнувшего-друга-166', 'DP-0166', 'загадка исчезнувшего друга', 'The Mystery of the Missing Friend', 'Zagonetka nestalog prijatelja', 'Антон Иванов', 'Anton Ivanov', 'Anton Ivanov', 'черный котенок', '', NULL, NULL, 7, 10, 'middle', 'Папа Олега в панике! Его лучший друг Александр Волков бесследно исчез по дороге домой. Все попытки семьи и друзей отыскать пропавшего или хотя бы выяснить, что с ним случилось, не приносят результатов. Александр Евгеньевич не попал в аварию, тело его тоже нигде не обнаружено, и никто не требует за него выкуп. За дело тут же берется Компания с Большой Спасской. Вскоре ребята находят в ангаре автосервиса машину, очень похожую на ту, вместе с которой пропал Волков, и...', 'Oleg''s father is panicked: his best friend, Alexander Volkov, vanished without a trace on his way home. There was no accident, no ransom demand, and police clues lead nowhere. Luckily, the young detectives from Bolshaya Spasskaya step in. Soon they track down a suspicious car in an auto repair hangar that looks just like Volkov''s, and the real investigation begins!', 'Olegov tata je u panici: njegov najbolji prijatelj Aleksandar Volkov netragom je nestao na putu kući. Nije bilo nesreće, nema otkupnine, a potraga ne daje nikakve rezultate. Družina sa Boljšaje Spaske odmah preuzima slučaj! Ubrzo u auto-servisu pronalaze automobil nevjerovatno sličan onom u kojem je Volkov nestao, i prava istraga počinje...', 'Захватывающий дворовый детектив с таинственными автосервисами, запутанными уликами и непобедимой силой дружбы!', 'A classic kid-sleuth mystery packed with suspicious garages, puzzling clues, and the unstoppable power of teamwork!', 'Uzbudljiva dječja detektivska priča puna sumnjivih tragova, auto-servisa i nepobjedivog prijateljstva!', '/covers/DP-0166.webp', '#2b4c6f', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends"]', '["detective","mystery","investigation","teamwork","kid sleuths"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-ограбления-в-театре-167', 'DP-0167', 'Тайна ограбления в театре', 'The Mystery of the Pantomime Cat', 'Tajna pljačke u pozorištu', 'Энид Блайтон', 'Enid Blyton', 'Enid Blajton', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'До конца каникул остаётся всего ничего, а юные сыщики ещё не разгадали ни одной, даже самой маленькой, тайны. Ребята так просто не сдаются – если преступления нет, то они его придумают! Тем более что нашёлся подходящий объект для розыгрыша – молодой констебль Пиппин. Но сыщики и предположить не могли, что их шалость обернётся настоящим преступлением – кто-то ограбил директора местного театра. Все улики указывают на… кота!', 'With school holidays coming to an end, the young detectives haven''t solved a single case. To stir things up, they invent a fake mystery to tease the gullible young PC Pippin. But their prank takes an unexpected turn when a real crime occurs at the local theatre, and every piece of evidence points suspiciously towards the pantomime cat!', 'Raspust se bliži kraju, a mladi detektivi još uvijek nisu riješili nijednu zagonetku. Da bi se zabavili, smišljaju lažni trag za mladog policajca Pipina. Međutim, njihova bezazlena šala pretvara se u pravi zločin kada neko opljačka direktora lokalnog pozorišta, a svi tragovi vode pravo do... pozorišne mačke!', 'Что делать, если каникулы на исходе, а тайн всё нет? Придумать розыгрыш, который случайно приведёт к поимке настоящего театрального вора!', 'When an innocent holiday prank on the constable accidentally uncovers a real theatre robbery, these clever young sleuths must track down the true cat burglar!', 'Kada bezazlena šala sa lokalnim policajcem slučajno otkrije pravu pozorišnu pljačku, mladi detektivi moraju otkriti ko je stvarni kradljivac!', '/covers/DP-0167.webp', '#8b263e', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends","funny"]', '["detective","mystery","theatre","friendship","investigation"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-вора-невидимки-168', 'DP-0168', 'Тайна вора-невидимки', 'The Mystery of the Invisible Thief', 'Tajna nevidljivog kradljivca', 'Энид Блайтон', 'Enid Blyton', 'Enid Blajton', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Пошла четвёртая неделя лета, а юные сыщики только и делают, что прячутся от жары в тени деревьев и маются от скуки. В Петерсвуде ни единого намёка на тайну! Чтобы хоть как-то развеяться, ребята отправляются на спортивный праздник и встречают там инспектора Дженкса, но и ему нечем порадовать команду сыщиков. К счастью, удача улыбается ребятам: в Петерсвуде объявляется вор да не простой, а невидимка. Юных сыщиков и пса-детектива таким не испугать – они уверены, что разоблачат загадочного преступника до конца летних каникул!', 'It''s the fourth week of summer, and the Five Find-Outers are hiding from the heat and dying of boredom. Peterswood has no mysteries in sight! But just when hope seems lost, a baffling burglar appears—an invisible thief leaving no obvious trace behind. The young detectives and Buster the dog are on the case, determined to catch the phantom culprit before their summer holidays come to an end.', 'Prošla je četvrta nedjelja ljeta, a mladi detektivi se samo kriju od vrućine u hladu i umiru od dosade. U Pitersvudu nema ni traga od misterije! Ali sreća im se osmjehnula: u selu se pojavljuje lopov, i to ne običan, već nevidljiv. Mlade detektive i psa Bastera to ne plaši – riješeni su da razotkriju zagonetnog kradljivca prije kraja raspusta.', 'Идеальный летний детектив: дерзкие ограбления, забавные маскировки и верный пёс, готовый взять след даже невидимого воришки!', 'The ultimate summer mystery full of clever disguises, perplexing clues, and a loyal dog ready to track down an invisible thief!', 'Savršen ljetnji detektivski roman sa genijalnim prerušavanjima i vjernim psom spremnim da pronađe čak i nevidljivog lopova!', '/covers/DP-0168.webp', '#2b6e82', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends","funny"]', '["детектив","расследование","летние каникулы","друзья","собака"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-жемчужного-ожерелья-169', 'DP-0169', 'Тайна жемчужного ожерелья', 'The Mystery of the Missing Necklace', 'Tajna biserne ogrlice', '', 'Enid Blyton', 'Enid Blajton', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Вот и летние каникулы. Пятеро юных сыщиков изнемогают от безделья в родном городке Петерсвуд, пока однажды не узнают об украденном ожерелье. Ребята с радостью берутся за расследование, им не терпится перехитрить своего давнишнего соперника – констебля Теофиля Гуна. А для этого друзьям придётся прибегнуть к чудесам маскировки, пережить странное происшествие в Музее восковых фигур и узнать, какое отношение имеет детская игра в напёрсток к раскрытию новой тайны…', 'Summer holidays have arrived, and the Five Find-Outers are bored in Peterswood until news of a stolen pearl necklace breaks out. Thrilled to launch an investigation, they are eager to outsmart their old rival, Constable Goon. To solve the case, the young sleuths must master disguises, survive an eerie encounter in a wax museum, and discover how a simple thimble game holds the key to the mystery.', 'Stigao je ljetnji raspust, a petoro mladih detektiva se dosađuju u Petersvudu sve dok ne saznaju za ukradenu bisernu ogrlicu. S radošću započinju istragu, željni da nadmudre svog starog rivala, policajca Guna. Da bi riješili misteriju, moraće da upotrijebe umijeće prerušavanja, prežive čudnu nezgodu u muzeju voštanih figura i otkriju kakve veze dječja igra naprstka ima sa ovim slučajem.', 'Мастерские маскировки, музей восковых фигур и усатый констебль Гун снова с носом — классический летний детектив, от которого невозможно оторваться!', 'Clever disguises, a spooky wax museum, and outsmarting the grumpy village constable make this classic summer mystery pure joy to read!', 'Vješto prerušavanje, jezivi muzej voštanih figura i nadmudrivanje mrzovoljnog policajca Guna čine ovaj ljetnji detektivski klasik neodoljivim!', '/covers/DP-0169.webp', '#2d547d', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends"]', '["detective","mystery","summer","disguises","investigation"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-похищенной-картины-170', 'DP-0170', 'Тайна похищенной картины', 'The Mystery of the Stolen Painting', 'Tajna ukradene slike', '', 'Enid Blyton', 'Enid Blajton', '', 'Азбука', NULL, NULL, 7, 10, 'middle', 'Юные сыщики только собрались вместе на рождественских каникулах, как на горизонте появилась новая тайна. Грабители украли из галереи старинную картину и скрылись в неизвестном направлении. Сыщики уже готовы взяться за дело, но суперинтендант Дженкс запрещает им вмешиваться в расследование. Ребята не сдаются и находят способ подключиться к поискам похищенной картины.', 'The young detectives have just gathered together for their Christmas holidays when a brand-new mystery strikes. Burglars have stolen an antique painting from the gallery and vanished into thin air. The children are eager to jump on the case, but Superintendent Jenks strictly forbids them from meddling in the investigation. Unwilling to back down, the clever sleuths find their own way to track down the stolen masterpiece.', 'Mladi detektivi tek što su se okupili za božićne praznike, a na horizontu se već pojavila nova zagonetka. Provalnici su iz galerije ukrali vrijednu starinsku sliku i pobjegli u nepoznatom pravcu. Družina je spremna da odmah krene u akciju, ali im inspektor Dženks strogo zabranjuje miješanje u policijsku istragu. Međutim, djeca ne odustaju i pronalaze domišljat način da riješe slučaj.', 'Взрослые велели не совать нос не в своё дело, но разве настоящих сыщиков на каникулах это когда-нибудь останавливало?', 'The adults told them to stay out of it, but when has that ever stopped clever young detectives on school break?', 'Odrasli su im rekli da se ne miješaju, ali zar je to ikada spriječilo prave mlade detektive na raspustu?', '/covers/DP-0170.webp', '#1f4e5b', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends"]', '["detective","mystery","investigation","art heist","winter holidays"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-секретной-комнаты-171', 'DP-0171', 'Тайна секретной комнаты', 'The Mystery of the Secret Room', 'Tajna skrivene sobe', 'Энид Блайтон', 'Enid Blyton', 'Enid Blajton', '', '', NULL, NULL, 7, 10, 'middle', 'На окраине Петерсвуда стоит старый, давным-давно заброшенный особняк. Но оказывается, комната под крышей этого дома полностью обставлена мебелью! Неужели там всё ещё кто-то живёт? И почему на самом верху? Может быть, кто-то втайне посещает заброшенный дом? За расследование этой загадки берутся пятеро юных сыщиков и пёс-детектив.', 'On the outskirts of Peterswood stands an old, abandoned mansion. Curiously, one room under the roof is fully furnished and impeccably kept! Could someone secretly be living there, or is the house being used for shady meetings? The Five Find-Outers and Buster the dog take on the case to uncover the truth.', 'Na rubu Pitersvuda nalazi se stara, odavno napuštena vila. Ipak, ispostavlja se da je jedna soba pod krovom potpuno namještena! Da li tamo još neko tajno boravi i zašto baš na samom vrhu? Petoro mladih detektiva i njihov vjerni pas kreću u rješavanje ove uzbudljive zagonetke.', 'Заброшенный особняк, подозрительная комната на чердаке и верный пёс-сыщик — классический детектив, от которого невозможно оторваться!', 'An abandoned mansion, a curiously furnished attic, and a clever detective dog—classic sleuthing fun you simply can''t put down!', 'Napuštena vila, misteriozna soba na tavanu i pametni pas detektiv — klasična avantura koja se čita u jednom dahu!', '/covers/DP-0171.webp', '#2e4a62', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends","animals"]', '["detective","mystery","abandoned house","dogs","friendship"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-сгоревшего-коттеджа-172', 'DP-0172', 'Тайна сгоревшего коттеджа', 'The Mystery of the Burnt Cottage', 'Tajna izgorjele kolibe', 'Энид Блайтон', 'Enid Blyton', 'Enid Blajton', '', '', NULL, NULL, 7, 10, 'middle', 'В деревушке Петерсвуд произошло самое что ни на есть настоящее преступление! Кто-то поджёг коттедж в саду мистера Хика. Пятеро детей, живущих по соседству, не собираются ждать, когда дело раскроет местный полицейский по прозвищу А-ну-ка-разойдись, и организуют клуб сыщиков. Вместе со своим псом ребята идут по следу преступника, но подозреваемых оказывается слишком много.', 'A real crime has shaken the quiet village of Peterswood: someone set fire to the cottage workshop in Mr. Hick''s garden! Five clever neighborhood children aren''t about to wait around for the grumpy local policeman to crack the case, so they form their very own detective club. Alongside their spirited little dog, they follow the clues, only to discover that almost everyone has a motive.', 'U mirnom selu Pitersvud dogodio se pravi zločin: neko je zapalio kolibu u vrtu gospodina Hika! Petoro djece iz komšiluka ne žele da čekaju nespretnog lokalnog policajca, pa osnivaju sopstveni detektivski klub. Zajedno sa svojim psom kreću u potragu za tragovima, ali osumnjičenih je iznenada previše.', 'Идеальный классический детектив для тех, кто мечтает разгадывать запутанные тайны быстрее взрослых и обожает четвероногих напарников!', 'A delightfully witty classic mystery for young sleuths who dream of outsmarting the grown-ups and solving crimes before teatime!', 'Savršen klasični detektivski roman za mlade istražitelje koji žele nadmudriti odrasle i riješiti misteriju prije policije!', '/covers/DP-0172.webp', '#c2542a', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends","funny"]', '["detective","mystery","classic","friendship","investigation"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-анонимных-писем-173', 'DP-0173', 'Тайна анонимных писем', 'The Mystery of the Spiteful Letters', 'Tajna anonimnih pisama', 'Энид Блайтон', 'Enid Blyton', 'Enid Blajton', '', '', NULL, NULL, 7, 10, 'middle', 'Юные сыщики и пёс-детектив снова вместе и готовы расследовать самые таинственные дела. Но увы, в Петерсвуде всё спокойно и ничего необычного не происходит, кроме неожиданного отъезда Глэдис – горничной Пипа и Бетси. Ребята уверены, что всё не так просто, как заявляют взрослые, и оказываются правы. Жители Петерсвуда один за другим стали получать неприятные анонимные послания. Кто же автор этих загадочных писем? Эту тайну раскроют пятеро юных сыщиков и пёс-детектив!', 'The Five Find-Outers and Dog are back together, eager to crack a new case! Peterswood seems quiet until Gladys, Pip and Bets'' parlor-maid, suddenly leaves in distress. Soon enough, venomous anonymous letters start landing on the doorsteps of respectable villagers. Who is writing these spiteful notes, and why? It is up to Fatty, Larry, Daisy, Pip, Bets, and Buster the dog to unmask the culprit!', 'Petoro mladih detektiva i njihov vjerni pas ponovo su na zadatku! U Petersvudu naizgled vlada mir, sve dok služavka Gledis iznenada ne napusti kuću u suzama. Ubrzo mještani počinju da dobijaju zlonamjerna anonimna pisma. Ko stoji iza ovih podmuklih poruka? Vrijeme je da družina pronađe tragove i riješi novu misteriju prije policajca Guna!', 'Доставайте лупы и блокноты: юные сыщики берутся за дело о коварных посланиях, пока местный констебль в растерянности чешет в затылке!', 'Grab your magnifying glasses: the Five Find-Outers are on the trail of a poison-pen mystery before Constable Goon even gets a clue!', 'Pripremite lupe i bilježnice: petoro mladih detektiva je na tragu tajanstvenom piscu dok lokalni policajac još tapka u mraku!', '/covers/DP-0173.webp', '#2c4c5e', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends","animals"]', '["detective","mystery","investigation","friendship","dog"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('нэнси-дрю-и-фальшивая-нота-174', 'DP-0174', 'Нэнси Дрю и фальшивая нота', 'Nancy Drew: False Notes', 'Nensi Dru: Lažna nota', 'Кэролайн Кин', 'Carolyn Keene', 'Kerolin Kin', '', 'АСТ', NULL, NULL, 7, 10, 'middle', 'Друзья называют меня Нэнси Дрю. Враги – по-разному, например: «Девушка, которая испортила мне все дело». Впрочем, чего еще ожидать от преступников? Видите ли, я – детектив. Ну не совсем. Значка и пистолета у меня нет. Зато я всегда обращаю внимание на несправедливость, обман и подлые поступки и знаю, как остановить негодяев. Я люблю искать ответы на самые сложные загадки, но, когда дело касается папиного дня рождения, я просто теряюсь и не могу найти подходящий подарок! Вдобавок к этому я выяснила совершенно ужасную вещь: кандидат в мэры Ривер-Хайтс скрывает кое-какую страшную тайну о своей дочери. Мне просто необходимо выяснить, что происходит. И желательно до того, как наступит папин день рождения…', 'Friends call me Nancy Drew. Enemies call me plenty of things, like ''the girl who ruined everything.'' What else could you expect from criminals? You see, I''m a detective—well, almost, without a badge or a gun. But I always spot injustice and deceit, and I know how to stop troublemakers. I love cracking tough mysteries, yet finding Dad the perfect birthday present leaves me totally stumped! On top of that, I''ve uncovered a dark secret involving the River Heights mayoral candidate''s daughter. I must get to the bottom of this before Dad''s big day arrives...', 'Prijatelji me zovu Nensi Dru. Neprijatelji svakojako, recimo: „Djevojka koja mi je uništila sve planove”. Šta drugo i očekivati od zlikovaca? Vidite, ja sam detektivka—doduše, bez značke i pištolja. Ali uvijek primijetim nepravdu i laž i znam kako da zaustavim krivce. Obožavam rješavanje zagonetki, ali kad treba naći savršen poklon za tatin rođendan, potpuno sam bespomoćna! Povrh svega, saznala sam da kandidat za gradonačelnika krije mračnu tajnu o svojoj ćerki. Moram riješiti ovaj slučaj prije rođendanske proslave...', 'Захватывающее расследование, где найти подарок папе оказывается почти так же сложно, как разоблачить коварный заговор!', 'A thrilling detective caper where finding the perfect birthday gift for Dad is almost as tricky as cracking a local scandal!', 'Uzbudljiva detektivska avantura u kojoj je naći tati rođendanski poklon jednako teško kao i razotkriti veliku tajnu!', '/covers/DP-0174.webp', '#2c6b99', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","friends","real"]', '["detective","mystery","nancy drew","investigation","secrets"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('новые-друзья-близнецов-в-школе-175', 'DP-0175', 'Новые друзья близнецов в школе Сент-Клэр', 'New Friends for the Twins at St Clare''s', 'Nove prijateljice bliznakinja u Sent Kleru', '', 'Enid Blyton', 'Enid Blajton', '', '', NULL, NULL, 7, 10, 'middle', 'Изабель и Патриция О’Салливан не успели оглянуться, как закончились очередные каникулы и пришла пора собираться в Сент-Клэр. Близняшки предвкушают встречу со школьными подругами, но с особенным нетерпением они ждут знакомства с новенькими, которые наверняка станут их друзьями. Иначе и быть не может! И пусть строгие учителя глаз не спускают с озорных учениц, нагружают их скучными домашними заданиями, дружная компания всегда находит время развлечься, придумать какую-нибудь шалость и даже устроить ночной пир в честь дня рождения одной из девчонок.', 'Before they know it, the holidays are over and Pat and Isabel O''Sullivan are packing their bags for another term at St Clare''s! The twins are eager to catch up with old friends, but most of all, they can''t wait to meet the new girls. Despite strict teachers and piles of homework, the girls always find time for laughter, clever escapades, and a secret midnight feast to celebrate a special birthday.', 'Dok su trepnule, raspust je proletio i došlo je vrijeme da se Pet i Izabel O''Saliven spakuju za povratak u internat Sent Kler! Bliznakinje jedva čekaju susret sa starim prijateljicama, ali i upoznavanje sa novim učenicama. I mada su strogi nastavnici uvijek na oprezu, veselo društvo uvijek pronađe način za smicalice, zabavu i tajnu ponoćnu gozbu u čast rođendana.', 'Классика школьных историй: секретные ночные пиры, забавные проделки и дружба, которая побеждает любые строгие правила пансиона!', 'Boarding school classic at its best: midnight feasts, mischievous pranks, and friendships that make homework almost bearable!', 'Pravi klasik školskih priča: tajne ponoćne gozbe, nestašluci i prijateljstvo koje pobjeđuje sva stroga pravila internata!', '/covers/DP-0175.webp', '#8b263e', '7-9', 'ru', 'available', 'Категория: детские детективы', '["friends","funny","adventure"]', '["boarding school","twins","friendship","pranks","school stories"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('новенькая-в-школе-сент-клэр-176', 'DP-0176', 'Новенькая в школе Сент-Клэр', 'Claudine at St Clare''s', 'Nova učenica u školi Sent Kler', '', 'Enid Blyton', 'Enid Blajton', '', '', NULL, NULL, 7, 10, 'middle', 'Школьная жизнь близняшек О’Салливан шла своим чередом: уроки, переменки, домашние задания, вечеринки и прочие развлечения… Казалось, чего ещё ожидать? Но однажды в их классе появилась новая ученица Клодин – большая выдумщица и фантазёрка, непосредственная, способная на самые дерзкие шалости. С приходом этой озорной девчонки и без того нескучная жизнь в школе забурлила с новой силой…', 'Life at St Clare''s boarding school for the O''Sullivan twins was buzzing along as usual with lessons, games, midnight feasts, and sports. But everything turns upside down when Claudine arrives! Outspoken, utterly unpredictable, and full of bold, cheeky pranks, this new French girl ensures that boarding school life becomes livelier and more chaotic than ever before.', 'Život bliznakinja O''Salivan u internatu Sent Kler tekao je uobičajenim tokom: časovi, odmori, domaći zadaci i vesele zabave. Međutim, dolazak nove učenice Klodin sve okreće naglavačke! Ova neposredna, maštovita i nestašna djevojčica spremna je na najsmjelije smicalice, unoseći pravi kovitlac uzbuđenja u već ionako živahan školski život.', 'Если вы думали, что в закрытой английской школе всё чинно и благородно, приготовьтесь к урагану по имени Клодин!', 'If you thought an English boarding school was all about quiet manners and decorum, prepare yourself for the whirlwind that is Claudine!', 'Ako ste mislili da je u engleskom internatu sve mirno i po strogim pravilima, pripremite se za pravi vihor zvan Klodin!', '/covers/DP-0176.webp', '#8b263e', '7-9', 'ru', 'available', 'Категория: детские детективы', '["friends","funny","real"]', '["boarding school","school stories","twins","pranks","friendship"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('привидения-в-школе-сент-клэр-177', 'DP-0177', 'Привидения в школе Сент-Клэр', 'Ghosts at St Clare''s', 'Duhovi u školi Sent Kler', '', 'Enid Blyton', 'Enid Blajton', '', '', NULL, NULL, 7, 10, 'middle', 'Сёстры-близняшки Патриция и Изабель О’Салливан продолжают учиться в школе Сент-Клэр, успешно переходя из класса в класс. Они усердно занимаются на уроках и не менее усердно выполняют домашние задания. Но не только учёбой ограничивается их школьная жизнь. Конечно же Изабель и Пат с подружками развлекаются и веселятся, участвуют в спортивных соревнованиях, знакомятся с новенькими, ссорятся и мирятся, да много всего интересного происходит в Сент-Клэре. Чего только стоят таинственные ночные происшествия…', 'Twin sisters Pat and Isabel O''Sullivan continue their adventures at St Clare''s boarding school. Between diligent classes, sports matches, and making friends, school life is bustling with excitement. But when strange things begin to go bump in the night, the girls must band together to solve a spooky schoolyard mystery!', 'Sestre bliznakinje Pat i Izabel O''Salivan nastavljaju školovanje u internatu Sent Kler. Između vrijednog učenja, sportskih takmičenja i novih prijateljstava, život u školi je pun uzbuđenja. Ipak, kad se noću pojave neobjašnjive tajne i prikaze, djevojčice moraju da udruže snage i otkriju ko to plaši učenice!', 'Уютная классика закрытого пансиона: верные подруги, полуночные пиры и загадочные шорохи в коридорах!', 'Cozy boarding-school classics at their best: loyal friends, midnight feasts, and mysterious bumps in the dark!', 'Udobna priča o školskom internatu: vjerne drugarice, ponoćne gozbe i misteriozni šušnji u hodnicima!', '/covers/DP-0177.webp', '#3b5998', '7-9', 'ru', 'available', 'Категория: детские детективы', '["friends","spooky","adventure"]', '["boarding school","twins","mystery","friendship","school life"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тихие-гости-178', 'DP-0178', 'Тихие гости', 'The Quiet Guests', 'Tihi gosti', 'Татьяна Мастрюкова', 'Tatiana Mastryukova', 'Tatjana Mastrjukova', '', 'Росмэн', NULL, NULL, 7, 10, 'middle', 'Захватывающий мистический триллер призера IX конкурса «Новая детская книга» в номинации «Мистика. Триллер. Фэнтези» Татьяны Мастрюковой, автора романов «Болотница» и «Приоткрытая дверь». Аня, Соня и Лера решили провести зимние каникулы на природе. Но в погребенной под снегом далекой деревне – ни души, не считая странной старухи-соседки да неизвестно откуда взявшегося безмолвного пса. Тишина такая, что звенит в ушах. Отчего же кажется, что кто-то следит за тобой недобрым взглядом, дышит холодом в спину? Беги скорее в дом, прижмись к теплой печке и слушай страшные истории подруг. Не смотри в окно! Запри дверь! Захлопни калитку, пока не ступили неслышно на двор незваные гости…', 'An atmospheric, spine-chilling winter mystery. Anya, Sonya, and Lera decide to spend their school break in a remote village buried under thick snow. There is not a soul around, except for an eerie elderly neighbor and a silent stray dog. As darkness falls and the chilling silence grows louder, someone seems to be watching their every move. Hurry inside, huddle near the warm stove, lock the door, and whatever you do—don''t look out the window when the uninvited guests arrive.', 'Uzbudljiv mistični zimski triler. Anja, Sonja i Lera odlučuju da provedu raspust u zabačenom selu zatrpanom snijegom. Tamo nema žive duše, osim čudnovate starice iz komšiluka i nijemog psa lutalice. U jezivoj tišini djevojčice osjećaju hladan pogled na svojim leđima. Zaključajte vrata, privijte se uz toplu peć i nipošto ne gledajte kroz prozor dok u dvorište nečujno stupaju nepozvani gosti...', 'Запасайтесь тёплым пледом и заприте двери покрепче — эта леденящая фолк-страшилка заставит сердечко биться чаще!', 'Grab your warmest blanket and lock the front door tight—this eerie winter folk-mystery will send delightful shivers down your spine!', 'Ušuškajte se pod toplo ćebe i dobro zaključajte vrata — ova zimska priča pružiće vam savršeno uzbudljive žmarce!', '/covers/DP-0178.webp', '#1e2d3b', '7-9', 'ru', 'available', 'Категория: детские детективы', '["spooky","friends","magic"]', '["ghost stories","winter","mystery","folklore","thriller"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('агент-на-мягких-лапах-1--179', 'DP-0179', 'Агент на мягких лапах (1)', 'Secret Agent Winston: A Cat on a Secret Mission', 'Agent na mekim šapama', 'Фрауке Шойнеманн', 'Frauke Scheunemann', 'Frauke Šojneman', '', 'Эксмо', NULL, NULL, 7, 10, 'middle', 'Уинстон Черчилль — истинный аристократ, короткошёрстный британец, грациозный, умный и самую малость ленивый кот, который живёт в доме профессора физики в Гамбурге. Его жизнь была спокойной и размеренной, пока он не познакомился с двенадцатилетней Кирой. Обычная прогулка обернулась для новых друзей неожиданным приключением — во время грозы они поменялись телами! Это оказалось настоящей катастрофой: ведь теперь Уинстон должен не только попасть в компанию самых крутых девчонок в Кириной школе, но и разоблачить банду контрабандистов, чтобы спасти маму девочки от несправедливых обвинений!', 'Winston Churchill is an aristocratic British Shorthair who enjoys a peaceful, luxurious life with a physics professor in Hamburg. But when a freak lightning storm strikes during a walk with twelve-year-old Kira, cat and girl mysteriously swap bodies! Now Winston must survive sixth-grade girl drama and unmask a gang of smugglers to clear Kira''s mother''s name.', 'Vinston Čerčil je pravi mačiji aristokrata koji uživa u lagodnom životu kod profesora fizike u Hamburgu. Sve se mijenja kada upozna dvanaestogodišnju Kiru: tokom iznenadne grmljavine njih dvoje misteriozno zamijene tijela! Sada Vinston mora da se snađe u školskim đačkim spletkama i istovremeno raskrinka bandu krijumčara kako bi spasio Kirinu mamu.', 'Что бывает, когда ленивый пушистый аристократ и школьница меняются телами? Уморительный детектив с усами и когтями!', 'What happens when a pampered pedigree cat and a schoolgirl swap bodies? A hilarious, whiskered detective adventure!', 'Šta se desi kada se razmaženi mačak aristokrata i jedna školarica nađu u zamijenjenim tijelima? Urnebesna detektivska avantura sa brkovima i kandžama!', '/covers/DP-0179.webp', '#d66a2e', '7-9', 'ru', 'available', 'Категория: детские детективы', '["funny","adventure","animals"]', '["cats","body swap","detective","mystery","school","friendship"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('загадка-сбежавшего-сейфа-180', 'DP-0180', 'Загадка сбежавшего сейфа', 'The Mystery of the Runaway Safe', 'Zagonetka odbjeglog sefa', 'Фрауке Шойнеманн', 'Frauke Scheunemann', 'Frauke Šojneman', '', '', NULL, NULL, 7, 10, 'middle', 'Целая серия краж потрясла город! Неизвестные таинственным образом проникли в несколько школ и украли оттуда сейфы! Полиция недоумевает, как злоумышленникам удалось пройти сквозь запертые двери. Но когда они добрались до гимназии «Вильгельмина», в которой учатся друзья Уинстона, коту-детективу не осталось ничего, кроме как начать расследование. Конечно, это невероятно опасно, ведь здесь орудует целая банда! Но у Уинстона есть суперсмелые друзья! Кира, Том, Паули и четыре мяушкетера уже готовы выйти на след похитителей сейфов!', 'A wave of mysterious break-ins has struck the city! Heavy school safes are vanishing into thin air without a single forced door, leaving the police completely baffled. But when the burglars hit the Wilhelmina Gymnasium where his best human pals study, the aristocratic feline detective Winston takes matters into his own paws. Tracking down a whole gang is perilous, but with Kira, Tom, Pauli, and four fearless meow-sketeers on the trail, no mystery can stay unsolved!', 'Talas misterioznih provala uzdrmao je grad! Nepoznati lopovi neobjašnjivo ulaze u škole i odnose teške sefove, a policija je u čudu jer su sve brave ostale netaknute. Kada na red dođe gimnazija „Vilhelmina“ u koju idu njegovi drugari, mačak-detektiv Vinston odmah kreće u akciju. Suočavanje s bandom kradljivaca nosi mnoge opasnosti, ali uz Kiru, Toma, Paulija i hrabre mačketepe, pravda je sigurno na putu!', 'Кот-аристократ Уинстон снова расследует дело: берегитесь, похитители школьных сейфов, кошачий спецназ уже на тропе войны!', 'Aristocratic feline Winston puts on his sleuthing cap once again—safe-crackers beware, the whiskers of justice are on your trail!', 'Otmeni mačak Vinston ponovo preuzima slučaj — lopovi, pazite se, mačji detektivski odred nikad ne ostavlja trag neistraženim!', '/covers/DP-0180.webp', '#24527a', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","animals","friends"]', '["cat detective","mystery","school","investigation","heist"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секрет-еловых-писем-2--181', 'DP-0181', 'Секрет еловых писем (2)', 'Winston: The Secret of the Fir Letters', 'Vinston: Tajna jelovih pisama', 'Фрауке Шойнеманн', 'Frauke Scheunemann', 'Frauke Šojneman', '', '', NULL, NULL, 7, 10, 'middle', 'Жизнь кота-детектива не так-то легка. Вместо того чтобы наслаждаться безмятежным сном и отменными деликатесами, Уинстону приходится расследовать новое запутанное преступление. В этот раз случилось невероятное: одноклассницу его подруги Киры Эмилию похитили — и это в самый разгар репетиций школьного спектакля, в котором девочка играла главную роль! Теперь преступник требует выкуп! Детям и дворовым кошкам придётся объединиться, чтобы вывести злоумышленника на чистую воду.', 'The life of a detective cat isn''t all naps and gourmet treats! Winston is back on the case, and this time, Kira''s classmate Emilia has been kidnapped right in the middle of rehearsals for the school play. With ransom notes appearing and the premiere at stake, the clever kids and street-smart neighborhood cats must join forces to crack the case and catch the culprit.', 'Život mačka detektiva nije lak: umjesto izležavanja i poslastica, Vinston mora da riješi novu zagonetku. Kirina drugarica Emilija je oteta usred proba za školsku predstavu u kojoj igra glavnu ulogu! Otmičar traži otkup, pa se djeca i ulične mačke udružuju u uzbudljivoj istrazi kako bi razotkrili krivca i spasili stvar.', 'Элегантный британский кот Уинстон и банда дворовых кошек снова берутся за дело — держитесь, похитители!', 'Aristocratic cat Winston and his alley-cat squad prove that four paws are always better than two when solving a mystery!', 'Aritokratski mačak Vinston i družina uličnih mačaka dokazuju da su četiri šape nenadmašne u rešavanju misterija!', '/covers/DP-0181.webp', '#2c6b4f', '7-9', 'ru', 'available', 'Категория: детские детективы', '["animals","adventure","friends"]', '["detective","cats","mystery","friendship","school"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('уинстон-берегись-4--182', 'DP-0182', 'Уинстон, берегись! (4)', 'Winston, Watch Out!', 'Vinstone, čuvaj se!', 'Фрауке Шойнеманн', 'Frauke Scheunemann', 'Frauke Šojneman', '', '', NULL, NULL, 7, 10, 'middle', 'И все-таки этот семейный ужин Уинстон представлял себе по-другому. Противные племянники профессора Вернера, то и дело готовые схватить его за хвост, — что может быть хуже?! Но оказалось, что издевательства маленьких мучителей не самое страшное на свете. Ведь после ужина Уинстон чуть не умер от боли в животе. Ужасный скандал: ветеринар уверен, что усатого детектива хотели отравить!', 'Winston had imagined this family dinner very differently. Professor Werner''s mischievous nephews constantly trying to yank his tail was bad enough, but what followed was far worse: Winston ended up with terrible stomach cramps. A scandalous diagnosis from the vet reveals someone actually tried to poison the feline detective!', 'Vinston je ovu porodičnu večeru zamislio sasvim drugačije. Dosadni nećaci profesora Vernera, koji vrebaju priliku da ga povuku za rep, bili su prava muka, ali ono što je uslijedilo bilo je još strašnije: Vinston je umalo stradao od bolova u stomaku. Veterinar donosi šokantnu vijest — neko je pokušao da otruje brkatog detektiva!', 'Держите ушки на макушке: пушистый аристократ берётся за самое личное расследование — покушение на собственную миску!', 'Keep your whiskers twitching: the finest feline detective is investigating a dastardly plot against his very own dinner bowl!', 'Naćulite uši: otmjeni brkati detektiv vodi najličniju istragu do sada — ko je pokušao da mu otruje večeru!', '/covers/DP-0182.webp', '#d9652b', '7-9', 'ru', 'available', 'Категория: детские детективы', '["animals","adventure","funny"]', '["cats","detective","mystery","pets","humor"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сыщик-на-арене-5--183', 'DP-0183', 'Сыщик на арене (5)', 'Winston: Detective in the Circus Arena', 'Vinston: Detektiv u areni', 'Фрауке Шойнеманн', 'Frauke Scheunemann', 'Frauke Šojneman', '', '', NULL, NULL, 7, 10, 'middle', 'Уинстон вместе с Кирой и друзьями отправляется в парк развлечений, в котором есть всё! Американские горки, Пещера ужасов, сахарная вата и настоящий цирк! Агент на мягких лапах примеряет на себя новую роль — циркового артиста! Вместе с другими зверями Уинстон выступает на арене, поражая публику своими талантами. Но во время одного из выступлений в зрительном зале происходит целая серия краж! Кто-то ворует вещи у публики. Не поверите: главный подозреваемый — клоун! Однако Уинстон уверен, что настоящий преступник прячется под другой маской. Кто же он?', 'Winston, Kira, and their crew head to a thrilling amusement park with roller coasters, a spooky ghost train, cotton candy, and a real circus! The feline secret agent takes on a bold new role as a circus performer, wowing spectators alongside other talented animals. But during the show, a string of pickpocketing thefts sweeps through the audience! The prime suspect is the clown, but Winston is convinced the true culprit hides behind a very different disguise. Can the whiskered detective crack the case?', 'Vinston sa Kirom i prijateljima odlazi u zabavni park koji nudi sve: rolerkostere, pećinu straha, šećernu vunu i pravi pravcati cirkus! Tajni agent na mekim šapama isprobava novu ulogu cirkuskog izvođača i oduševljava publiku svojim talentom. Međutim, tokom predstave među gledaocima dolazi do serije krađa! Glavni osumnjičeni je klovn, ali Vinston je uvjeren da se pravi krivac krije iza sasvim druge maske.', 'Пушистый детектив выходит на манеж, ведь под куполом цирка запахло сладкой ватой и дерзким преступлением!', 'Our favorite feline detective steps into the circus ring, where sweet cotton candy mixes with a delightfully sneaky mystery!', 'Naš omiljeni mačji detektiv ulazi u cirkusku arenu, gdje uz miris šećerne vune vreba nova uzbudljiva zagonetka!', '/covers/DP-0183.webp', '#d94336', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","animals","funny"]', '["cats","detective","circus","mystery","friendship"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('спасти-одетту-6--184', 'DP-0184', 'Спасти Одетту (6)', 'Winston: Saving Odette', 'Vinston: Spasiti Odetu', 'Фрауке Шойнеманн', 'Frauke Scheunemann', 'Frauke Šojneman', '', '', NULL, NULL, 7, 10, 'middle', 'А ведь я предупреждал, что это глупая затея! Отправиться в деревню, в глушь – да что тут может быть хорошего?! Вот и случилось просто непоправимое! Одетту, мою возлюбленную, самую прекрасную кошку в мире, похитили! А теперь приготовьтесь к еще более шокирующей новости: местные жители утверждают, что это дело лап… мышей!!! Святые сардины в масле, как такое могло произойти? Но главный вопрос – как теперь вызволить Одетту из мышиного плена? Поговаривают, что деревенские мыши ужасно опасные…', 'I warned them that heading out to the countryside was a dreadful idea! Now the unthinkable has happened: Odette, my beloved and the most gorgeous cat in the world, has been catnapped! Even more shocking, local rumors claim it''s the work of... mice! Holy sardines in oil, how can that even be? More importantly, how am I going to bust Odette out of the clutches of these ferocious country mice?', 'Upozoravao sam da je odlazak na selo užasna ideja! I evo, dogodilo se nezamislivo: Odeta, moja voljena i najljepša mačka na svijetu, oteta je! Što je još luđe, mještani tvrde da su to izveli... miševi! Svetih mi sardina u ulju, kako je to uopšte moguće? A najvažnije pitanje je: kako sada spasiti Odetu iz kandži neustrašivih seoskih glodara?', 'Детектив Уинстон снова в деле: на кону честь, любовь всей жизни и противостояние с дерзкими деревенскими мышами!', 'Detective Winston faces his wildest case yet: saving his feline true love from a mischievous mob of country mice!', 'Mačji detektiv Vinston je pred najluđom istragom do sada: spasiti ljubav svog života iz kandži opake seoske mišje bande!', '/covers/DP-0184.webp', '#4a8a56', '7-9', 'ru', 'available', 'Категория: детские детективы', '["funny","adventure","animals"]', '["detective","cats","humor","mystery","rescue"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секрет-говорящего-какаду-185', 'DP-0185', 'Секрет говорящего какаду', 'Violet: The Secret of the Talking Cockatoo', 'Vajolet: Tajna brbljivog kakadua', 'Гарриет Уайтхорн', 'Harriet Whitehorn', 'Harijet Vajthorn', '', 'Эксмо', NULL, NULL, 7, 10, 'middle', 'Совсем недавно Вайолет вернулась из удивительнейшего путешествия в её жизни. Она побывала в Индии! Там девочка познакомилась с махараджей, очень старым и очень богатым индийским князем, и его любимым говорящим какаду. Но как же удивилась Вайолет, когда обнаружила на пороге своего дома в Лондоне слугу махараджи. Он попросил её приютить какаду, потому что ценную птицу хотят украсть! А всё потому, что махараджа завещал попугаю всё своё наследство! Но кто именно охотится за пернатым сокровищем? Вайолет ждёт новое захватывающее дело! Вторая книга в серии. Для среднего школьного возраста.', 'Violet has just returned from an unforgettable trip to India, where she befriended an elderly, fabulously wealthy maharajah and his beloved talking cockatoo. Imagine her surprise when the maharajah''s servant suddenly arrives on her London doorstep with the bird! It turns out the maharajah has willed his entire fortune to the cockatoo, and now thieves are desperately scheming to birdnap the feathered heir. A thrilling, stylish new investigation awaits our young detective!', 'Vajolet se tek vratila s nevjerovatnog putovanja u Indiju, gdje je upoznala basnoslovno bogatog maharadžu i njegovog omiljenog brbljivog kakadua. Njeno iznenađenje je ogromno kada se maharadžin sluga iznenada pojavi na njenom pragu u Londonu! Ispostavlja se da je maharadža prepisao čitavo bogatstvo ptici, a lopovi već kuju plan da kidnapuju pernatog naslednika. Pred mladom detektivkom je nov uzbudljiv i otmjen slučaj!', 'Остроумный детектив в ретро-стиле, где спасти пернатого миллионера под силу только самой сообразительной девочке на Бейкер-стрит!', 'A delightfully stylish detective adventure where only one quick-witted girl can protect a feathered heir from greedy birdnappers!', 'Šarmantna i duhovita detektivska priča u kojoj samo oštroumna djevojčica može sačuvati pernatog milionera od pohlepnih lopova!', '/covers/DP-0185.webp', '#e09f3e', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","funny","animals"]', '["detective","cockatoo","investigation","london","mystery"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('история-голубой-планеты-186', 'DP-0186', 'История голубой планеты', 'The Story of the Blue Planet', 'Priča o plavoj planeti', 'Андри Снайр Магнассон', 'Andri Snær Magnason', 'Andri Snær Magnason', '', 'Городец', NULL, NULL, 7, 10, 'middle', 'На Голубой планете нет взрослых, она населена детьми, которые делают всё, что им заблагорассудится, и никто не указывает им, как надо жить. Однажды на планету детей приземляется загадочный человек, и начинают происходить чудеса. Прогремевшая на весь мир повесть исландского писателя Андри Снайра Магнасона начинается как невинная сказка и перерастает в философскую притчу о современном мире. Почему нельзя всегда быть счастливым? Хорошо ли, если все желания начнут исполняться? Что такое война? Почему одним всё, а другим ничего? Книга получила рекордное количество наград в Исландии и за рубежом, в том числе Британскую национальную книжную премию, Международную премию им. Януша Корчака, Американскую международную премию «Зеленая планета», а недавно была выбрана лучшей детской книгой в Китае. «История Голубой планеты» издана более чем в 35 странах мира, а также поставлена на сцене в нескольких детских театрах разных стран.', 'On the Blue Planet, there are no adults—it is inhabited entirely by children who live in wild harmony with nature. But when a mysterious grown-up crash-lands from space promising limitless thrills, their paradise faces unforeseen consequences. Andri Snær Magnason''s award-winning Icelandic masterpiece begins as a whimsical adventure and unfolds into a powerful, poetic allegory about ecology, consumerism, and the true cost of endless fun.', 'Na Plavoj planeti nema odraslih — naseljena je isključivo djecom koja žive u potpunoj slobodi i skladu s prirodom. Ipak, kada se misteriozni svemirski putnik spusti među njih s obećanjem beskrajne zabave, njihov raj se nađe u opasnosti. Višestruko nagrađivana islandska pripovijest Andrija Snajra Magnasona počinje kao vedra bajka, a prerasta u duboku i dirljivu priču o ekologiji, prijateljstvu i posljedicama naših želja.', 'Что произойдёт, если доверить управление целой планетой детям и одному подозрительно щедрому космическому фокуснику?', 'Find out what happens when kids run an entire planet all by themselves—until a tricky space salesman offers them endless sunshine!', 'Saznajte šta se događa kada djeca sama upravljaju čitavom planetom — sve dok ne stigne lukavi svemirski trgovac koji nudi vječno sunce!', '/covers/DP-0186.webp', '#20689b', '7-9', 'ru', 'available', 'Категория: детские детективы', '["adventure","magic","friends"]', '["ecology","fairytale","friendship","planet","morality"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ведьмочки-гламбурга-187', 'DP-0187', 'ведьмочки гламбурга', 'Witch Wars', 'Vještice Glamburga', 'Шибел Паундер', 'Sibéal Pounder', 'Šibel Paunder', '', 'Росмэн', NULL, NULL, 7, 10, 'middle', 'Многие думают, что ведьмы - страшные старухи в остроконечных шляпах. Они варят зелья в котлах и делают всем гадости. На самом деле это не так. Не совсем так. Настоящие ведьмы живут в Водостоке - своем мире, попасть в который можно только по канализационным трубам. Они большие модницы, обожают туфли, шляпки и кружева. Именно в Водосток, а точнее, в его столицу - город Гламбург - и попала Вега Дьямема - обычная девочка, которая и не подозревала, что она ведьма. Но стоило ей туда угодить, как оказалось, что надо участвовать в соревновании - "Битве ведьм". Но Вега не знает ни одного заклинания. Сможет ли она победить и остаться в Водостоке или придется возвращаться назад, к противной опекунше мисс Хекс? Приключенческая повесть, полная юмора и неожиданных поворотов, написанная английской писательницей Шибел Паундер.', 'Forget boring old crones stirring cauldrons—real witches are glamorous fashionistas living in a secret world hidden right down the sewer pipes! Nine-year-old Tiga didn''t even know she was a witch until she tumble-landed straight into Ritzy City and found herself entered into the fabulous, high-stakes Witch Wars competition. With zero spells up her sleeve and only stylish fairy Fran to help, can Tiga win the contest, or will she be banished back to her dreadful guardian Miss Greystones?', 'Zaboravite dosadne starice nad kotlovima – prave vještice su prave modne ikone i žive u tajnom svijetu do kojeg se stiže pravo kroz kanalizacione cijevi! Devetogodišnja Vega nije imala pojma da je vještica sve dok se nije obrela u Glamburgu i saznala da mora učestvovati u uzbudljivom takmičenju „Bitka vještica”. Pošto ne zna nijednu čaroliju, hoće li uspjeti da pobijedi i ostane u magičnom svijetu, ili će morati da se vrati svojoj groznoj starateljki?', 'Остроумная, полная модного блеска и магии история о том, что даже сбежав через канализацию, можно оказаться на самом стильном ведьмовском турнире!', 'A sparkling, giggle-out-loud adventure proving that secret witchy worlds and fabulous shoe-obsession can turn an ordinary girl''s life totally upside down!', 'Duhovita, blistava i magična priča koja dokazuje da čak i bijeg kroz kanalizaciju može voditi pravo na najglamurozniji vještičji turnir!', '/covers/DP-0187.webp', '#df3985', '7-9', 'ru', 'available', 'Категория: детские детективы', '["funny","magic","adventure"]', '["witches","magic","fashion","competition","humor"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хранитель-пенхэллоу-тайная-лес-188', 'DP-0188', 'Хранитель Пенхэллоу Тайная лестница', 'Penhallow Halls: The Secret Staircase', 'Čuvar Penhaloua: Tajno stepenište', 'Холли Вебб', 'Holly Webb', 'Holi Veb', '', 'Эксмо', NULL, NULL, 7, 10, 'middle', 'Полли и её друг Рекс — непростые девочка и собака. Точнее, Полли совершенно обычная девочка, а Рекс — дух-хранитель старинного особняка Пенхэллоу. И весь этот огромный особняк полон собак: они высовывают мордочки из барельефов и балясин, смотрят с картин, сидят статуями и статуэтками. Все они когда-то жили тут, в Пенхэллоу, и навсегда остались его хранителями. И вот одному такому волшебному пёсику настолько грустно, что даже Полли это почувствовала. Давным-давно маленькая девочка забыла игрушку в комнате, но пёсик не забыл свою хозяйку. Полли и Рекс не знают, что делать, как вывести пёсика из его печали. Вот разве что найти девочку, которой так же грустно и которой пёсик мог бы помочь? Книга издана на белой бумаге, внутри достаточно крупный шрифт и иллюстрации, которые позволят детям переключать внимание, не перенагружая глаза. Идеально для родителей, которые хотят, чтобы дети втянулись в чтение, или для тех, чьи дети уже стали заядлыми читателями. Для среднего школьного возраста.', 'Polly is an ordinary girl, but her companion Rex is the spirit dog guarding historic Penhallow Hall. The grand mansion is teeming with canine guardians resting within carvings, paintings, and stone statues. When a tiny magical dog is overcome with sorrow over a long-forgotten mistress, Polly and Rex set out to heal its lonely heart by finding someone who needs that devotion just as much.', 'Poli je sasvim obična djevojčica, ali njen pratilac Reks je pas-duh koji čuva drevno imanje Penhalou. Cijeli dvorac je pun pasa zaštitnika koji vrebaju iz reljefa, portreta i skulptura. Kada jednog malog čarobnog psića obuzme tuga za davno izgubljenom vlasnicom, Poli i Reks kreću u potragu za nekim kome je pseća ljubav i vjernost najpotrebnija.', 'Уютная таинственная история о призрачных собаках, старинных особняках и преданности, которая согревает сквозь века.', 'A heartwarming mystery filled with secret staircases and ghost dogs who prove that loyalty never fades.', 'Topla i misteriozna priča o tajnim stepenicama i psima-duhovima koji dokazuju da prava odanost traje vječno.', '/covers/DP-0188.webp', '#2c3e6b', '7-9', 'ru', 'available', 'Категория: детские детективы', '["magic","animals","friends"]', '["dogs","mystery","ghosts","old mansion","friendship"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('необычайные-похождения-севы-ко-189', 'DP-0189', 'Необычайные похождения Севы Котлова', 'The Extraordinary Adventures of Seva Kotlov', 'Neobični doživljaji Seve Kotlova', 'А. Алексин', 'Anatoly Aleksin', 'Anatolij Aleksin', '', 'Эксмо', NULL, NULL, 7, 10, 'middle', 'В книгу вошли три жизнерадостные и трогательные повести известного русского писателя Анатолия Алексина о веселых приключениях школьника Севы Котлова: «Под чужим именем», «Тайный сигнал барабанщика, или Как я вел дневник» и «Сева Котлов за Полярным кругом». Эти произведения были переведены более чем на 20 языков и изданы миллионными тиражами по всему миру.', 'This book brings together three cheerful and touching stories by Anatoly Aleksin about the funny adventures of schoolboy Seva Kotlov: ''Under an Assumed Name'', ''The Secret Signal of the Drummer'', and ''Seva Kotlov Beyond the Polar Circle''. Beloved worldwide, these classic tales explore friendship, school life, and growing up with genuine warmth and gentle humor.', 'Ova knjiga objedinjuje tri vesele i dirljive pripovijetke Anatolija Aleksina o komičnim avanturama školarca Seve Kotlova: ''Pod tuđim imenom'', ''Tajni signal dobošara'' i ''Seva Kotlov iza Polarnog kruga''. Ove klasične priče, prevedene na više od dvadeset jezika, donose toplinu, nestašluke i pravo školsko drugarstvo.', 'Приготовьтесь смеяться от души над остроумными школьными проделками неунывающего Севы Котлова — классика доброго детского юмора!', 'Get ready to laugh out loud at Seva Kotlov''s witty school antics — a heartwarming, timeless classic of pure childhood fun!', 'Spremite se za glasan smijeh uz školske doživljaje Seve Kotlova — vanvremensku klasiku o djetinjstvu i pravom drugarstvu!', '/covers/DP-0189.webp', '#d97706', '7-9', 'ru', 'available', 'Категория: детские детективы', '["funny","adventure","friends"]', '["school stories","humor","friendship","growing up","classics"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мальчишки-в-сорок-первом-190', 'DP-0190', 'Мальчишки в сорок первом', 'Boys of Forty-One', 'Dječaci četrdeset prve', 'Виктор Дубровин', 'Viktor Dubrovin', 'Viktor Dubrovin', '', 'Речь', NULL, NULL, 7, 10, 'middle', 'Какой мальчишка не мечтает побывать на поле боя? Тем более если вчера началась самая настоящая война! Вот и Вовка с Женькой совершенно серьезно решили отправиться в армию. Кто бы мог подумать, что до настоящих бойцов им еще расти и расти! И, конечно, друзья и представить себе не могли, что в Ленинграде, окруженном кольцом блокады, будет ничуть не легче, чем на передовой. Теперь на счету каждый грамм хлеба, а совсем рядом, за озером, куда раньше по выходным ребята ходили купаться и загорать, - линия фронта. Так для мальчишек наступает время попрощаться с беззаботным детством, пережить совсем недетские трудности и - повзрослеть.', 'What boy doesn''t dream of heroics on the battlefield, especially when a real war has just begun? Vovka and Zhenka are determined to run off and join the army. Little do they know, growing into true soldiers takes time, and life in besieged Leningrad will prove just as harsh as the front lines. With every crumb of bread strictly rationed and the enemy right across their favorite swimming lake, the boys must leave their carefree childhood behind, face unimaginable hardships, and grow up fast.', 'Koji dječak ne sanja o borbi, posebno kada je tek počeo pravi rat? Vovka i Ženjka su sasvim ozbiljno odlučili da pobjegnu u vojsku. Međutim, pravi podvizi zahtijevaju zrelost, a život u opkoljenom Lenjingradu biće jednako težak kao i na samom frontu. Dok se svaki gram hljeba broji, a linija fronta stoji tik uz njihovo omiljeno jezero, dječaci moraju da se oproste od bezbrižnog djetinjstva i nauče šta znači stvarna hrabrost.', 'Трогательная и честная повесть о том, как ленинградские мальчишки меняют наивные мечты о подвигах на настоящую стойкость и верную дружбу.', 'A touching, honest story about how boys in besieged Leningrad trade naive dreams of battlefield glory for genuine resilience and loyal friendship.', 'Dirljiva i iskrena priča o tome kako dječaci iz opkoljenog Lenjingrada naivne snove o podvizima zamjenjuju istinskom izdržljivošću i odanim prijateljstvom.', '/covers/DP-0190.webp', '#5a604f', '7-9', 'ru', 'available', 'Категория: детские детективы', '["real","friends"]', '["world war ii","siege of leningrad","friendship","growing up","historical fiction"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ирка-рисует-в-скетчбуке-тимофе-191', 'DP-0191', 'Ирка, рисует в скетчбуке/ Тимофей пишет в блокнот', 'Irka Sketches in a Sketchbook / Timofey Writes in a Notebook', 'Irka crta u skicen-bloku / Timofej piše u bilježnicu', 'Нина Дашевская', 'Nina Dashevskaya', 'Nina Daševska', '', 'Самокат', 2020, '978-5-91759-965-6', 11, 15, 'big', '', 'This flip-book offers two interconnected perspectives on the fragile world of adolescence. Irka captures reality through vibrant drawings, while Timofey records his thoughts and observations in prose. As their creative paths cross, they learn how deeply art can connect two lonely souls and help make sense of growing up.', 'Ova dvostrana knjiga nudi dvije povezane priče o krhkom svijetu odrastanja. Irka hvata stvarnost kroz crteže u svom skicen-bloku, dok Timofej bilježi misli i zapažanja riječima. Kada im se putevi ukrste, oboje otkrivaju koliko umjetnost može povezati dvoje tinejdžera i pomoći im da razumiju sebe.', 'Две стороны одной истории о том, как научиться видеть красоту вокруг и слышать того, кто рядом.', 'Two sides of one heartfelt story about learning to see the world around you and truly hear someone else.', 'Dvije strane jedne tople priče o tome kako vidjeti ljepotu u sitnicama i zaista čuti osobu pored sebe.', '/covers/DP-0191.webp', '#e07a5f', 'teens', 'ru', 'available', '', '["friends","real"]', '["teenagers","art","creativity","growing up","friendship"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гриша-не-свидетель-192', 'DP-0192', 'Гриша не свидетель', 'Grisha Is Not a Bystander', 'Griša nije svjedok', 'Настя Рябцева', 'Nastya Ryabtseva', 'Nastja Rjabceva', '', 'Самокат', 2023, '978-5-00167-510-5', 11, 15, 'big', '', 'Grisha always preferred to stay in the shadows and keep his head down: observe everything, get involved in nothing, and never stand out. But school life and unexpected dilemmas quickly challenge his passive stance. When injustice happens right before your eyes, is it truly possible to remain just an outsider? A perceptive and honest coming-of-age story about empathy, courage, and finding the strength to speak up.', 'Griša je oduvijek birao da ostane po strani: da posmatra sve, ne miješa se ni u šta i ne privlači pažnju. Međutim, školski život i neočekivani sukobi brzo stavljaju njegovu neutralnost na test. Kada se nepravda dešava pred tvojim očima, da li je zaista moguće ostati samo nijemi posmatrač? Iskrena i dirljiva priča o odrastanju, empatiji i hrabrosti da se pronađe sopstveni glas.', 'Честная и пронзительная подростковая повесть о том, почему иногда так сложно не пройти мимо и как научиться слышать собственный голос.', 'An honest, sharp teen story about why it''s so hard not to look away and how to finally find your own voice.', 'Iskrena i dirljiva tinejdžerska priča o tome zašto je ponekad najteže ne okrenuti glavu i kako pronaći sopstveni glas.', '/covers/DP-0192.webp', '#335c67', 'teens', 'ru', 'available', '', '["real","friends"]', '["teen life","school","moral choices","growing up","empathy"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('поиск-звука-творогов-193', 'DP-0193', 'Поиск звука. Творогов', 'In Search of Sound: Tvorogov', 'U potrazi za zvukom: Tvorogov', 'Нина Дашевская', 'Nina Dashevskaya', 'Nina Daševska', '', 'Самокат', 2021, '978-5-00167-277-7', 11, 15, 'big', '', 'Ivan Tvorogov doesn''t consider himself anything special, yet he tunes into the world with rare precision. In his notebook, he captures snippets of conversations, city noises, awkward crushes, and shifting friendships. A sensitive, luminous coming-of-age story about discovering your own voice amidst the everyday chaos of teenage life.', 'Ivan Tvorogov ne misli da je po bilo čemu poseban, ali svijet osluškuje sa nevjerovatnom pažnjom. U svoju svesku bilježi odlomke razgovora, ulične zvuke, zbunjenost i prijateljstva koja se mijenjaju. Tople i iskrene stranice o odrastanju i pronalaženju sopstvenog glasa u buci svakodnevice.', 'Чуткая и удивительно музыкальная повесть о том, как научиться слышать себя и других посреди шумного взросления.', 'A deeply resonant, musical coming-of-age story about tuning into your own voice amidst the chaotic noise of growing up.', 'Topla i muzikalna priča o tome kako pronaći sopstveni ton i oslušnuti druge usred haosa odrastanja.', '/covers/DP-0193.webp', '#3c7a89', 'teens', 'ru', 'available', '', '["friends","real"]', '["teen life","growing up","music","friendship","school"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('удивительные-приключения-маули-194', 'DP-0194', 'Удивительные приключения Маулины Шмитт. Часть 1. Моё разрушенное королевство', 'The Amazing Adventures of Maulina Schmitt. Part 1: My Broken Kingdom', 'Čudesne avanture Mauline Šmit. Dio 1: Moje uništeno kraljevstvo', '', 'Finn-Ole Heinrich', 'Fin-Ole Hajnrih', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Мауляндия — настоящий рай. Солнышко светит, жуки жужжат, бутоны и почки разворачиваются, трава тянется вверх, кошки лениво потягиваются, мурчат и ловят жуков на лету... Всё осталось там. Теперь Маулина и её мама живут в дурацком Пластикбурге, где только сонные мухи, жабы и старые бабуськи, всё остальное — пластиковое. Почему мама и Тот человек расстались? Мама говорит: это потому, что они перестали друг друга понимать. Ну раз они оба чокнулись, придется взять дело в свои руки. Тот человек поступает несправедливо. Надо придумать план! План по возвращению Мауляндии!', 'Mauland was pure paradise: sunshine, buzzing bugs, blooming flowers, and purring cats. Now, Maulina and her sick mom have been forced to relocate to dreary Plasticburg, where everything is fake and boring. Why did Mom and That Man split up? If the grown-ups have lost their minds, Maulina will just have to take matters into her own hands and engineer a grand plan to reclaim her kingdom!', 'Maulendija je bila pravi raj: sunce sija, bube zuje, a mačke lenjo predu. Sve je to ostalo iza nje kada su se Maulina i njena mama preselile u dosadni Plastikburg. Zašto su se mama i Onaj Čovjek rastali? Ako su odrasli potpuno skrenuli s uma, Maulina mora uzeti stvari u svoje ruke i smisliti genijalan plan kako da povrati svoje kraljevstvo!', 'Громкая, смелая и очень трогательная история о том, как пережить крах привычного мира, вооружившись фантазией и невероятной стойкостью.', 'A fierce, funny, and deeply touching story about putting your shattered world back together when grown-ups make a mess of things.', 'Buntovna, duhovita i duboko dirljiva priča o tome kako preživjeti raspad starog svijeta i stvoriti novi, po sopstvenim pravilima.', '/covers/DP-0194.webp', '#e05a47', 'teens', 'ru', 'available', '10+', '["real","funny","friends"]', '["divorce","family","growing up","resilience","humor"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('добриллион-195', 'DP-0195', 'Добриллион', 'A Kindrillion', 'Dobrilion', '', 'Unknown', 'Nepoznati autor', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Франк и его мама живут в небольшом норвежском поселке. Франк учится в школе, его мама работает уборщицей. Но однажды они выигрывают 24 миллиона крон в лото. Все вот-вот должно измениться! Конечно, если удастся уговорить маму вообще начать тратить деньги. Пока окружающие без особой деликатности пытаются объяснить маме и Франку, на что им пустить свое состояние, мама придумывает неожиданный ход: она отдаст миллион тому из жителей поселка, кто совершит самый добрый поступок. Но можно ли делать добрые дела за деньги?', 'Frank and his mother live in a quiet Norwegian village, where she works as a cleaner. Overnight, their world turns upside down when they hit a 24-million-kroner lottery jackpot! While the nosy neighbors eagerly offer unsolicited financial advice, Frank''s mom comes up with an extraordinary challenge: she will award a million kroner to whoever performs the kindest deed in town. But can genuine kindness ever carry a price tag?', 'Frank i njegova majka žive u malom norveškom selu, gdje ona radi kao čistačica. Sve se neočekivano mijenja kada na lutriji osvoje 24 miliona kruna! Dok nestrpljive komšije navaljuju sa savjetima kako da potroše bogatstvo, Frankova mama donosi nevjerovatnu odluku: pokloniće milion kruna mještaninu koji učini najplemenitije djelo. Ali, može li se dobrota mjeriti novcem?', 'Остроумная и глубокая норвежская повесть о том, что происходит, когда на тебя сваливаются миллионы — и можно ли купить искреннюю доброту.', 'A witty and heartfelt Norwegian story exploring what happens when instant wealth strikes and whether you can really put a price on human kindness.', 'Duhovita i topla norveška priča o tome šta se desi kada osvojiš milione — i da li se iskrena dobrota uopšte može kupiti novcem.', '/covers/DP-0195.webp', '#e09f3e', 'teens', 'ru', 'available', '', '["funny","real","friends"]', '["lottery","kindness","money","family","norway","growing up"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('здесь-в-реальном-мире-196', 'DP-0196', 'Здесь, в реальном мире', 'Here in the Real World', 'Ovdje, u stvarnom svijetu', '', 'Sara Pennypacker', 'Sara Penipaker', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Одиннадцатилетний Вар мечтает провести лето в одиночестве, в мире средневековых рыцарей и замков. Но родители записывают его в городской лагерь «Рекреация», где придется проводить время«в осмысленном социальном взаимодействии с другими детьми». Хуже не придумаешь! В первый же день Вар находит по соседству с «Рекреацией» руины заброшенной церкви, где можно построить отличный замок. И знакомится с загадочной и упрямой Джолин, которая намерена здесь же, на пустыре, устроить плантацию папай. Вар и Джолин очень разные, однако у них есть кое-что общее: им обоим отчаянно нужно убежище. И когда оно оказывается под угрозой, Вар заглядывает в Рыцарский кодекс: Всякий раз, оказавшись перед лицом несправедливости, вступай с нею в бой. Но что значит быть рыцарем в реальной жизни? И что могут сделать двое детей?', 'Eleven-year-old Ware wants nothing more than to spend his summer lost in his inner world of medieval castles and knights. Instead, his parents ship him off to a dreaded day camp devoted to ''meaningful social interaction.'' Desperate to escape, Ware discovers an abandoned church lot next door—the perfect spot to construct a secret sanctuary. There he meets Jolene, a fiercely independent girl determined to grow a secret papaya plantation on the same ground. When their shared haven is threatened, Ware turns to the code of chivalry to figure out what it truly means to defend the vulnerable in the real world.', 'Jedanaestogodišnji Ver želi samo da provede ljeto u svom svijetu srednjovjekovnih vitezova i zamkova, ali ga roditelji šalju u ljetnji kamp pun ''društvenih aktivnosti''. Bježeći od buke, Ver u napuštenom dvorištu stare crkve pronalazi savršeno sklonište i upoznaje Džolin, svojeglavu djevojčicu koja na istoj ruševini sadi papaje. Kada njihovo utočište dođe u opasnost, Ver će morati da shvati šta viteški kodeks zapravo znači u stvarnom svijetu.', 'Пронзительная и вдохновляющая история о том, как интроверту найти своё безопасное место и стать настоящим рыцарем в реальном мире.', 'A tender and empowering story about finding your sanctuary, standing up for what matters, and learning to be a knight in everyday life.', 'Dirljiva i ohrabrujuća priča o tome kako pronaći sopstveno utočište i postati pravi vitez u stvarnom svijetu.', '/covers/DP-0196.webp', '#3b6b55', 'teens', 'ru', 'available', '', '["real","friends","adventure"]', '["friendship","growing up","introverts","imagination","sanctuary"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зимняя-битва-197', 'DP-0197', 'Зимняя битва', 'The Winter''s End', 'Zimska bitka', 'Жан-Клод Мурлева', 'Jean-Claude Mourlevat', 'Žan-Klod Murleva', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Когда за пятнадцать лет жизни не знаешь ничего кроме страха, не имеешь понятия о том, кто ты и откуда взялся, то где взять силы взглянуть правде в глаза? Где найти мужество, чтобы бросить вызов привычному миру и начать битву? Битву за свою свободу, за право жить, говорить и чувствовать самому — как велят сердце и память. Память, которую у тебя тоже хотели отнять? Главные герои романа сбегают из госинтернатов, чтобы продолжить битву своих родителей. Битву, которая, кажется, заранее проиграна. На пути к свободе им придется принимать страшные, слишком «взрослые» решения: убить или быть убитым, выйти в одиночку против армии или затеряться в толпе, всю жизнь молчать или наконец запеть во весь голос.', 'When your first fifteen years have known nothing but fear and enforced amnesia, where do you find the courage to defy a brutal regime? Four teenagers escape oppressive boarding schools to take up the torch of their parents'' rebellion—a battle that seems doomed from the start. On their harrowing path toward freedom, they must confront life-and-death choices, stand against impossible odds, and decide whether to remain silent forever or let their voices ring out in defiant song.', 'Kada tokom prvih petnaest godina života ne znaš za ništa osim straha i nemaš pojma ko si i odakle potičeš, gdje pronaći snagu da pogledaš istini u oči? Četvoro tinejdžera bježi iz surovih internata kako bi nastavili borbu svojih roditelja protiv tiranije. Na putu ka slobodi moraće da donose teške odluke odraslih: ubiti ili biti ubijen, suprotstaviti se armiji ili se izgubiti u masi, ćutati zauvijek ili napokon zapjevati iz sveg glasa.', 'Мощная и пронзительная антиутопия о дружбе, достоинстве и голосе свободы, который не заглушить даже в самые лютые морозы.', 'A gripping, lyrical dystopia about courage, enduring friendship, and the unstoppable power of song in the face of tyranny.', 'Snažna i dirljiva distopija o hrabrosti, prijateljstvu i glasu slobode koji ni najhladnija zima ne može da utiša.', '/covers/DP-0197.webp', '#2c4c64', 'teens', 'ru', 'available', '', '["adventure","friends"]', '["dystopia","rebellion","courage","friendship","resistance"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-поисках-синего-лоис-лоури-198', 'DP-0198', 'В поисках синего. Лоис Лоури', 'Gathering Blue', 'U potrazi za plavom', 'Лоис Лоури', 'Lois Lowry', 'Lois Lauri', '', 'Розовый жираф', NULL, NULL, 11, 15, 'big', 'Вторая часть тетралогии Лоис Лоури, как и "Дающий", описывает замкнутое сообщество со своими жесткими законами. После глобальной катастрофы на Земле, похоже, не осталось ни городов, ни машин, ни железных дорог. Девочка Кира живет в поселке, где помощь ближнему – редкость, добыть еду – удача, а смерть подстерегает любого – от болезни или от лап хищных тварей. У хромой сироты Киры мало шансов, тем более что соседи считают ее обузой и хотят убить. Но сделать это без разрешения Хранителей нельзя. Выдержать ненависть соседей и суд Старейшин Кире позволяет ее удивительный дар – она и сама не догадывалась, на что способна. С «Дающим», первой частью тетралогии, «В поисках синего» связывает лишь тонкая ниточка (хотя внимательный читатель найдет в ней ответ на главный вопрос – о судьбе Джонаса). И тем не менее эти книги очень похожи: в обеих описывается мир, который населяющие его люди воспринимают как правильный и единственно возможный, и только главные герои осознают, что он пронизан ложью и должен стать другим.', 'The second installment in Lois Lowry’s acclaimed Giver Quartet takes us to a ruthless post-apocalyptic society where the weak and injured are cast out to die. Born with a twisted leg, the orphaned Kira seems doomed until her extraordinary gift for weaving thread captures the attention of the Council of Elders. As Kira is assigned the monumental task of restoring the sacred Singer''s Robe, she discovers dark secrets buried beneath the village’s brutal traditions. This gripping dystopian tale celebrates the resilience of art, courage, and truth in a world stripped of empathy.', 'Drugi dio proslavljenog kvarteta Lois Lauri vodi nas u nemilosrdno postapokaliptično društvo gdje se slabi i bolesni odbacuju bez milosti. Siromašna i hroma siročica Kira naizgled nema šanse da preživi u selu u kom vladaju surovost i sebičnost, ali njen čudesni dar za vez spašava joj život privukavši pažnju Vijeća čuvara. Dok obnavlja drevnu svečanu odoru koja čuva istoriju njihovog svijeta, Kira otkriva mračne tajne skrivene iza lažnog poretka. Ova dirljiva i napeta distopijska priča govori o snazi umjetnosti, istini i hrabrosti u surovom svijetu.', 'Завораживающая антиутопия о силе искусства и хрупкой девочке, чья нить способна распутать ложь целого мира.', 'A gripping dystopian tale about the transformative power of art and a brave girl whose embroidery threads unravel a world built on lies.', 'Očaravajuća distopijska priča o snazi umjetnosti i hrabroj djevojčici čija nit istine može razmrsiti laži čitavog društva.', '/covers/DP-0198.webp', '#2c4d6f', 'teens', 'ru', 'available', '', '["adventure","real"]', '["dystopia","courage","art","survival","mystery"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('глава-джулиана-199', 'DP-0199', 'Глава Джулиана', 'The Julian Chapter: A Wonder Story', 'Džulijanovo poglavlje', 'Паласио', 'R. J. Palacio', 'R. Dž. Palasio', '', 'Розовый жираф', NULL, NULL, 11, 15, 'big', 'Как люди становятся задирами? Зачем они унижают и травят других? И есть ли у задиры шанс измениться? Помните, как в книге «Чудо» задира Джулиан травил Августа из-за его необычной внешности? Из всех героев книги только его история не была рассказана, а ведь и у Джулиана есть своя точка зрения. Например, он вовсе не считает, что травил кого-то. Джулиан совершенно не понимает, почему теперь все считают его чудовищем, ведь Август виноват в их ссоре не меньше него. Сможет ли он поменять свой взгляд на ситуацию? Р.Дж. Паласио снова мастерски описывает тонкое устройство человеческой души. И, если «Чудо» научило нас тому, как можно жить в мире друг с другом, несмотря на все различия, то «Глава Джулиана» рассказывает о том, что порой самые отвратительные поступки люди совершают не от внутренней злобы, а от затаенного страха и обиды.', 'How do kids become bullies? Why do they pick on others, and can a bully ever truly change? In the bestselling novel Wonder, Julian was the boy who made August Pullman''s life miserable. He was the only character whose voice went unheard—until now. Julian doesn''t see himself as a monster; from his perspective, August is just as much to blame, and fear drove his every move. R. J. Palacio masterfully explores the intricate human heart, showing that cruelty often stems not from pure malice, but from unaddressed fear and hurt, offering a powerful path toward empathy and redemption.', 'Kako djeca postaju nasilnici? Zašto ponižavaju druge i ima li nasilnik priliku da se promijeni? U romanu „Čudo“, Džulijan je nemilosrdno zadirkivao Avgusta zbog njegovog izgleda. Od svih likova, jedino njegova priča nije bila ispričana — a i Džulijan ima svoju stranu. On sebe ne doživljava kao čudovište i ne shvata zašto su se svi okrenuli protiv njega. R. Dž. Palasio ponovo majstorski oslikava ljudsku dušu, podsjećajući nas da se najružniji postupci često rađaju iz dubokog straha i nesigurnosti, otvarajući vrata oproštaju.', 'Взгляните на события «Чуда» глазами главного школьного задиры, чтобы понять: даже за самой колючей броней прячется чей-то страх.', 'Step into the shoes of Wonder''s main bully to discover that behind the meanest armor often hides deep fear and a chance for redemption.', 'Zavirite u priču iz ugla školskog nasilnika iz romana „Čudo“ i otkrijte šta se krije iza oklopa i ima li nade za iskupljenje.', '/covers/DP-0199.webp', '#d97438', 'teens', 'ru', 'available', '', '["real","friends"]', '["bullying","school life","empathy","growing up","wonder"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('глава-шарлотты-200', 'DP-0200', 'Глава Шарлотты', 'Shingaling: A Wonder Story', 'Šarlotina priča', 'Паласио', 'R. J. Palacio', 'R. Dž. Palasio', '', 'Розовый жираф', NULL, NULL, 11, 15, 'big', 'Когда любимая подружка уходит в компанию главных красоток класса, а мальчишки затевают настоящую войну, благоразумнее всего держать нейтралитет, считает Шарлотта. В средней школе все немного противные, разве нет? А если ни с кем не ссориться и быть милой, тогда, может быть, и тебя пригласят за стол к популярным девочкам. Хорошо бы еще пройти танцевальный отбор и выступить на школьном благотворительном концерте в Карнеги-холле… Но как только Шарлотта перестанет слишком беспокоиться о мнении окружающих, окажется, что настоящие друзья у нее уже есть, а подготовка к выступлению — нечто куда большее, чем билет в крутую компанию.', 'When her best friend drifts away to sit with the popular crowd and the boys wage a full-blown war, Charlotte figures that staying neutral is the smartest move. Middle school is tricky, so if you stay sweet and avoid conflict, maybe you''ll even get invited to the cool girls'' table. Plus, there is an audition for a major dance showcase at Carnegie Hall! But as Charlotte stops worrying so much about what others think, she realizes true friendship was right in front of her all along—and dancing isn''t just a ticket to popularity.', 'Kada najbolja drugarica pređe u društvo najpopularnijih djevojčica, a dječaci započnu pravi školski rat, Šarlota smatra da je najpametnije ostati neutralna. U višim razredima svi su pomalo naporni, zar ne? Možda će i nju pozvati za sto popularnih ako bude fina i ne zamjeri se nikome. Uz to, tu je i audicija za plesni nastup u Karnegi holu... Ali čim prestane da brine o tuđem mišljenju, Šarlota shvata da već ima prave prijatelje i da je ples mnogo više od karte za ulazak u ''kul'' ekipu.', 'Честный и вдохновляющий взгляд на школьные интриги, дружбу и смелость оставаться собой от звезды вселенной «Чуда».', 'An honest and heartwarming look at middle school drama, girlhood, and finding the courage to be your true self from the world of Wonder.', 'Iskren i dirljiv pogled na školske drame, prijateljstvo i hrabrost da budeš svoja, pravo iz svijeta romana „Čudo“.', '/covers/DP-0200.webp', '#3ea59d', 'teens', 'ru', 'available', '', '["friends","real"]', '["school","friendship","growing up","middle school","empathy"]', 1792836322695, 1792845613252);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('плутон-201', 'DP-0201', 'Плутон', 'Pluto: A Wonder Story', 'Pluton', 'Паласио', 'R. J. Palacio', 'R. Dž. Palasio', '', 'Розовый жираф', NULL, NULL, 11, 15, 'big', 'Бывают же такие ужасные дни! Крис забыл дома доклад, и рассерженная учительница снижает ему оценку в полугодии, первая тромбонистка школьного оркестра Кейти Мак-Энн вот-вот его убьет, а в рок-группе, где он играет, происходит настоящий раскол. Но это все ерунда по сравнению с тем, что Крис узнает после занятий: его мама попала в аварию и сейчас в больнице. Под конец этого долгого дня, когда Крису так нужна будет помощь, он вдруг получит ее оттуда, где и не думал искать.', 'Some days are completely disastrous: Chris forgot his project, his teacher docks his grade, the lead trombonist wants him dead, and his rock band is splitting up. But everything pales in comparison to the news that his mom has been injured in a car crash. In the midst of this overwhelming day, Chris discovers that true friendship endures, even across long distances.', 'Neki dani su jednostavno katastrofalni: Kris je zaboravio referat, profesorka mu obara ocjenu, koleginica iz orkestra je bijesna na njega, a rok bend mu se raspada. Ipak, sve to postaje nevažno kada sazna da mu je majka u bolnici nakon saobraćajne nesreće. U ovom teškom trenutku, neočekivana podrška podsjetiće ga na snagu pravog prijateljstva.', 'Трогательная история из вселенной «Чуда» о том, что даже когда весь мир рушится, старый друг всегда готов подставить плечо.', 'A tender companion to ''Wonder'' reminding us that even on the worst day imaginable, lifelong friendships are our strongest lifeline.', 'Dirljiva priča iz svijeta ''Čuda'' koja nas podsjeća da su stari prijatelji naša najveća snaga kad god se dan pretvori u haos.', '/covers/DP-0201.webp', '#3f678a', 'teens', 'ru', 'available', '', '["friends","real"]', '["friendship","family","school life","growing up","wonder"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('азбука-любви-202', 'DP-0202', 'Азбука любви', 'The Alphabet of Love', 'Abeceda ljubavi', 'Юлия Яковлева', 'Yulia Yakovleva', 'Julija Jakovljeva', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Давайте начистоту. Никому из нас не хочется снова стать пятнадцатилетним. Никто из нас не хочет снова влюбляться первый раз. Снова страдать. Снова умирать от любви. Снова перечитывать школьную программу по литературе тоже никто не хочет. А зря: у великих писателей для влюбленных есть много советов. Не повторяйте ошибок Онегина и Татьяны, Ромео и Джульетты, Хосе и Кармен, Анны Карениной и Вронского. Не переходите дорогу в неположенном месте. Отвечайте на письма сразу, в день получения. Готовьте паэлью и не ссорьтесь из-за ерунды. Любите как Афанасий Иванович и Пульхерия Ивановна из "Старосветских помещиков" - ведь это единственная история счастливой любви в мировой литературе.', 'Let''s be honest: nobody truly wants to be fifteen again, suffering through the agonies of first love—or re-reading the school literature curriculum. But that''s a mistake: classic writers have plenty of practical advice for lovers! Learn from the fatal mistakes of Romeo and Juliet, Onegin and Tatiana, Carmen, and Anna Karenina. Don''t cross train tracks recklessly, reply to messages on the day you receive them, and love without dramatic heartbreak.', 'Budimo iskreni: niko ne želi ponovo da prolazi kroz muke prve ljubavi sa petnaest godina, a rijetko ko želi i ponovo da lista lektiru. A trebalo bi: slavni pisci imaju pregršt korisnih savjeta za zaljubljene! Nemojte ponavljati fatalne greške Romea i Julije, Onjegina i Tatjane, Karmen ili Ane Karenjine. Odgovarajte na pisma istog dana, ne pravite drame oko sitnica i naučite kako da volite zrelo i srećno.', 'Ироничный гид по первой любви, который наконец-то объяснит, почему классику из школьной программы полезно читать ради спасения собственного сердца.', 'A witty survival guide to first love that proves classic literature holds the ultimate secrets to surviving teenage heartbreak.', 'Duhovit vodič kroz prve simpatije koji dokazuje da školska lektira krije najbolje recepte za spas slomljenog srca.', '/covers/DP-0202.webp', '#d15b68', 'teens', 'ru', 'available', '', '["real","funny"]', '["first love","literature","teens","relationships","humor"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('звезды-светят-на-потолке-203', 'DP-0203', 'Звезды светят на потолке', 'In the Ceiling the Stars Are Shining', 'Zvijezde sijaju na plafonu', 'Юханна Тидель', 'Johanna Thydell', 'Johana Tidel', '', 'Мир детства', NULL, NULL, 11, 15, 'big', 'Каково это: порвать с прошлой жизнью, бросить лучшую подругу и начать тусоваться с самой отвязной девчонкой в классе? Йенна не думала, что все так обернется.Но когда твоя мама смертельно больна, жизнь стремительно меняется. И ты понимаешь, что можно быть сильной и слабой одновременно. Этот дебютный роман 23-летней Юханны Тидель был удостоен самой престижной литературной премии Швеции - премии Августа Стриндберга, а также многих других литературных наград. Книга переведена на четырнадцать языков, по ней снят фильм.', 'Jenna never expected her world to crumble, but when your mother is terminally ill, life changes overnight. Finding solace away from home, she drifts away from her best friend and ends up hanging out with the wildest girl in school. A tender, brutally honest Swedish coming-of-age story about sorrow, rebellion, and learning that you can be strong and fragile at the very same time.', 'Kako je to udaljiti se od najbolje drugarice i početi druženje sa najotkačenijom djevojkom u razredu? Džena to nije planirala, ali kada ti je majka teško bolesna, život se okreće naglavačke. Tada shvataš da možeš biti i snažna i slomljena u isto vrijeme. Ovaj nagrađivani švedski roman donosi dirljivu i iskrenu priču o odrastanju, tugovanju i pronalaženju nade u najtežim trenucima.', 'Пронзительная и предельно честная история взросления, которая учит держаться на плаву и замечать свет даже в самые темные дни.', 'A fiercely honest, tender coming-of-age novel that will make you cry, heal, and search for glow-in-the-dark stars in your own room.', 'Nevjerovatno iskrena i topla priča o odrastanju koja pokazuje kako pronaći sopstvenu svjetlost kada se sve oko vas ruši.', '/covers/DP-0203.webp', '#233352', 'teens', 'ru', 'available', '', '["real","friends"]', '["coming of age","grief","friendship","teens","family"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('правила-не-снимай-штаны-в-аква-204', 'DP-0204', 'Правила не снимай штаны в аквариуме', 'Rules', 'Pravila', 'Синтия Лорд', 'Cynthia Lord', 'Sintija Lord', '', 'Мир детства', NULL, NULL, 11, 15, 'big', 'Как быть, если твой младший брат - аутист? Если в самый неподходящий момент он позорит тебя перед друзьями и из-за него тебя не зовут в гости? Дэвид просто достал Кэтрин. Но ведь она так любит брата и так хочет помочь ему научиться хотя бы немного жить по законам этого мира. Поэтому Кэтрин сочиняет игру в правила, которые Дэвид может усвоить - в отличие от криков и замечаний. Это история двенадцатилетней девчонки - о ее мечтах и печалях, о том, как добиться внимания собственного отца, о том, каково это, влюбиться в мальчика в инвалидном кресле.Синтия Лорд – американская детская писательница. "Правила, не снимай штаны в аквариуме" – дебютный роман автора, написанный в 2006 году. Частично книга основывается на реальных событиях: у Синтии трое детей, и у одного из них аутизм. Это произведение о принятии себя и окружающих, о торжестве дружбы и любви.', 'Twelve-year-old Catherine just wants a normal life, which seems impossible when your younger brother David has autism and embarrasses you at every turn. To help him navigate the confusing social world, Catherine invents a set of funny and practical rules—like ''no taking off your pants in the aquarium.'' But when she befriends Jason, a nonverbal boy who uses a wheelchair, Catherine begins to realize that ''normal'' might not exist at all, and that true love and acceptance mean breaking a few rules of your own.', 'Dvanaestogodišnja Ketrin samo želi normalan život, što izgleda nemoguće kada tvoj mlađi brat Dejvid ima autizam i stalno te dovodi u neprijatne situacije. Da bi mu pomogla da se snađe u svijetu, ona smišlja neobična pravila — poput onog da se pantalone ne skidaju u akvarijumu. Ipak, kada upozna Džejsona, dječaka u invalidskim kolicima koji komunicira pomoću slika, Ketrin počinje da shvata da ''normalno'' možda i ne postoji, i da pravo prihvatanje ponekad traži kršenje sopstvenih pravila.', 'Трогательная, честная и на удивление светлая история о том, как трудно и важно любить тех, кто не похож на остальных (даже если они заставляют тебя краснеть каждый день!).', 'A deeply touching and honest story about discovering that nobody is truly ''normal''—and that real love means welcoming the chaos with an open heart.', 'Dirljiva i iskrena priča o tome kako prihvatiti one koji su drugačiji i shvatiti da savršeno ''normalno'' zapravo uopšte ne postoji.', '/covers/DP-0204.webp', '#35799c', 'teens', 'ru', 'available', '', '["real","friends"]', '["autism","family","friendship","growing up","empathy"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('солнечная-аллея-205', 'DP-0205', 'Солнечная аллея', 'The Short End of Sonnenallee', 'Sunčana aleja', 'Томас Бруссиг', 'Thomas Brussig', 'Thomas Brussig', '', 'Слово', NULL, NULL, 11, 15, 'big', 'Герои повести, четверо непутевых друзей и обворожительная девушка, в которую они все влюблены, томятся за Берлинской стеной, изредка заглядывая за нее в большой свободный мир. Они тайком слушают запретные песни своих кумиров "Rolling Stones", мечтают о настоящих джинсах и осваивают азы модной философии экзистенциализма.', 'Living in the shadow of the Berlin Wall, four goofy friends and the irresistible girl they all adore catch glimpses of the dazzling free world just across the border. Together, they secretly blast forbidden Rolling Stones vinyl, dream of genuine western denim, and ponder the mysteries of existentialist philosophy with endless teenage charm.', 'Živeći u sjenci Berlinskog zida, četiri luckasta prijatelja i neodoljiva djevojka u koju su svi zaljubljeni povremeno vire u veliki, slobodni svijet. Oni krišom slušaju zabranjene ploče Rolingstonsa, maštaju o pravim zapadnjačkim farmerkama i otkrivaju čari egzistencijalističke filozofije uz pregršt humora.', 'Трогательная и ироничная история о взрослении по ту сторону Берлинской стены, где запретный рок-н-ролл звучит слаще всего!', 'A witty, bittersweet coming-of-age tale behind the Berlin Wall, proving that teenage rebellion, first love, and rock ''n'' roll can breach any border!', 'Duhovita i topla priča o odrastanju iza Berlinskog zida, koja dokazuje da mladalački bunt, prva ljubav i rokenrol ne poznaju granice!', '/covers/DP-0205.webp', '#d97724', 'teens', 'ru', 'available', '', '["funny","friends","real"]', '["berlin wall","coming of age","friendship","rock music","first love"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сделай-погромче--206', 'DP-0206', 'Сделай погромче!', 'Hairstyles of the Damned', 'Pojačaj do daske!', 'Джо Мено', 'Joe Meno', 'Džo Meno', '', 'Лимбус тин', NULL, NULL, 11, 15, 'big', 'Мир плох. У Брайана Освальда полно проблем. Он старшеклассник, он тайно влюблен в толстуху Гретхен, он учится в католической школе для мальчиков, и у него все время стоит. Он слушает хэви-металл и панк-рок и любит петь в церкви. Перед ним неразрешимые вопросы: как понравиться девчонке, как покрасить волосы в розовый цвет, с кем пойти на выпускной, но главное - как стать самим собой. Со страниц книги звучит подлинный, узнаваемый голос подростка - пожалуй, впервые со времен "Над пропастью во ржи". Если вы все еще думаете, что детство и отрочество - прекрасная пора, - знакомьтесь с Брайаном.', 'High school junior Brian Oswald is navigating awkward crushes, punk rock, Catholic school absurdities, and the chaotic quest to find himself in 1990s Chicago. An honest, raw, and fiercely authentic coming-of-age story that captures the real beat of teenage life.', 'Brajan Osvald ima gomilu tinejdžerskih problema: ide u katoličku školu, sluša pank i hevi-metal, potajno je zaljubljen i pokušava da shvati ko je zapravo. Duhovita, sirova i iskrena priča o odrastanju koja pogađa pravo u centar tinejdžerskog haosa.', 'Честная, шумная и очень живая хроника взросления под аккорды панк-рока — для каждого, кто хоть раз чувствовал себя белой вороной.', 'A loud, honest, and painfully funny punk-rock soundtrack to growing up, perfect for anyone who has ever felt like an outsider.', 'Bučna, iskrena i duhovita pank-rok priča o odrastanju za sve koji su se ikada osjećali kao potpuni autsajderi.', '/covers/DP-0206.webp', '#d6336c', 'teens', 'ru', 'available', '', '["real","funny"]', '["growing up","punk rock","high school","first love"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ночные-птицы-207', 'DP-0207', 'Ночные птицы', 'The Night Birds', 'Noćne ptice', 'Турмуд Хауген', 'Tormod Haugen', 'Tormod Haugen', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Книги Турмуда Хаугена всегда балансируют между двумя мирами - фантазии и действительности - и стирают границу между фантастической и реалистической, между детской и взрослой литературой. "Ночные птицы" - роман, рассказывающий о реальных и воображаемых детских и взрослых страхах, - получил литературные премии в Норвегии и Германии, рекомендован ассоциациями психологов, переведен на 20 языков и стал самым известным в мире романом Турмуда Хаугена.', 'Tormod Haugen''s books balance delicately between fantasy and reality, blurring the lines between childhood fears and adult struggles. ''The Night Birds'' is a tender, atmospheric story about childhood anxiety and the shadowy monsters that hide in our closets and minds. Honored with prestigious awards in Norway and Germany and translated into twenty languages, it remains Haugen''s most celebrated masterpiece on finding courage in the dark.', 'Knjige Tormoda Haugena vješto balansiraju između mašte i stvarnosti, brišući granice između dječijih i odraslih strahova. „Noćne ptice“ je dirljiv i iskren roman o stvarnim i umišljenim tjeskobama, noćnim sjenkama i hrabrosti da se suočimo sa onim što nas plaši. Preveden na više od dvadeset jezika, ovo je Haugenovo najpoznatije remek-djelo ovjenčano prestižnim svjetskim priznanjima.', 'Глубокая и поэтичная скандинавская повесть, которая учит приручать ночные тени и не бояться собственных страхов.', 'A deeply poetic Scandinavian novel that gently teaches us how to tame the night shadows and face our quietest fears.', 'Duboka i poetična skandinavska priča koja nas nježno uči kako da pripitomimo noćne sjenke i suočimo se sa sopstvenim strahovima.', '/covers/DP-0207.webp', '#223347', 'teens', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["real","spooky"]', '["fears","growing up","scandinavian literature","psychology","family"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('а-теперь-любите-меня-208', 'DP-0208', 'А теперь любите меня', 'And Now Love Me', 'A sad me volite', 'Аксель Сандр', 'Axel Sandre', 'Axel Sandre', '', 'КомпасГид', NULL, NULL, 11, 15, 'big', 'Быть любимым. Это все, к чему стремится герой романа молодого французского писателя Акселя Сандра. Не зная, кто его родители, он с детства привык оказываться в разных приемных семьях, где он чувствовал большее и меньшее участие. Но не более того. И как только он узнаёт, что обладает выдающимся интеллектом и впервые чувствует интерес к своей персоне, он начинает думать, что добившись успехов в учебе, сможет снискать внимание и любовь окружающих. И поэтому упорно трудится: в интернате, в школе, в институте. Раскладывая свои мысли и чувства по папочкам, герой Акселя Сандра поступает на медицинский факультет, оканчивает учебный год с отличием, получает возможность пройти оплачиваемую стажировку, вливается в компании сокурсников. "А теперь любите меня!" - замирает в восторженном ожидании он. Но в один прекрасный день он понимает, что ошибался. Что настоящая любовь не завоевывается путем простого преуспевания. Что человеческие чувства не так просты и зачастую обманчивы. Система рушится, и он вместе с ней. В замешательстве безымянный герой романа входит в первое попавшееся кафе и находит там таких же, как он. Отчаявшихся…', 'To be loved—that is all the nameless protagonist of this novel desires. Having grown up in foster homes without ever knowing his parents, he discovers he has a brilliant mind and decides that sheer academic success is the golden ticket to affection. He works tirelessly, organizing his emotions into neat mental folders, breezes through med school, and waits for the promised reward: ''And now, love me!'' But when he realizes that love cannot be bought with straight A''s and achievements, his meticulously ordered world collapses, sending him on an honest search for real connection among fellow outsiders.', 'Biti voljen – to je sve čemu teži bezimeni junak ovog romana. Odrastao po hraniteljskim porodicama, bez saznanja o tome ko su mu roditelji, on otkriva da posjeduje izuzetan intelekt i zaključuje da je akademski uspjeh siguran put do pažnje i ljubavi. Marljivo uči, slaže emocije u uredne mentalne fascikle, upisuje medicinu i niže uspjehe, uvjeren da je došlo vrijeme za nagradu: „A sad me volite!“ Međutim, kada shvati da se prava ljubav ne osvaja diplomama i priznanjima, njegov savršeno izgrađeni sistem se ruši, vodeći ga ka neočekivanom susretu sa onima koji se osjećaju jednako izgubljeno.', 'Тонкая и пронзительная подростковая драма о том, что отличные оценки не заменят объятий, а любовь нельзя заслужить по инструкции.', 'A poignant and sharp coming-of-age drama proving that straight A''s cannot replace a genuine hug and that love can never be earned like a medal.', 'Dirljiva i iskrena priča o odrastanju koja nas podsjeća da se ljubav ne može zaslužiti peticama i diplomama, već otvorenim srcem.', '/covers/DP-0208.webp', '#4a6984', 'teens', 'ru', 'available', 'Для старшего школьного возраста.', '["real","friends"]', '["teens","coming-of-age","loneliness","growing-up","mental-health"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('совсем-не-аполлон-209', 'DP-0209', 'Совсем не Аполлон', 'Not Exactly Apollo', 'Nije baš Apolon', 'Катарина Киери', 'Katarina Kieri', 'Katarina Kieri', '', 'КомпасГид', NULL, NULL, 11, 15, 'big', 'Лауре пятнадцать. Она учится в школе, болтает обо всем на свете с лучшей подругой, из чувства протеста продолжает по детской традиции покупать конфеты по субботам и совсем не хочет казаться взрослой, как многие ее одноклассницы. Но однажды случается непредвиденное: на школьном собрании она знакомится с Андерсом Страндбергом. Он Совсем не Аполлон, не идеал красоты, но почему-то Лаура не может перестать думать о нем, мечтать о встрече, разговоре, совместной прогулке. Но есть неразрешимая проблема: Андерсу Страндбергу намного больше лет, чем Лауре, и он новый учитель математики в их школе. Лаура изо всех сил борется с охватившим ее чувством: ведь ни строгая подруга Лена, ни родители, ни сам Андерс не смогут ее понять и уж тем более одобрить... В 2002 за повесть для подростков "Совсем не Аполлон" Катарина Киери была номинирована на самую престижную в Швеции премию имени Августа Стриндберга.', 'Laura is fifteen. She goes to school, talks about everything under the sun with her best friend, clings to her childhood habit of buying Saturday sweets, and refuses to rush into adulthood. But then the unexpected happens: she meets Anders Strandberg. He is definitely not Apollo, far from an ideal of beauty, yet Laura cannot get him out of her head. There is only one impossible problem: Anders is much older than her, and he is the new math teacher at school. Laura wrestles with an overwhelming secret crush that she knows no one would understand. A deeply moving YA novel nominated for Sweden''s prestigious August Prize.', 'Laura ima petnaest godina. Ide u školu, ćaska o svemu sa najboljom drugaricom, subotom tvrdoglavo kupuje bombone i nimalo ne žuri da odraste poput svojih vršnjakinja. A onda se događa neočekivano: upoznaje Andersa Strandberga. On nipošto nije Apolon, ali Laura nikako ne može da prestane da misli na njega. Postoji samo jedan nerješiv problem: Anders je mnogo stariji od nje i novi je nastavnik matematike u njenoj školi. Laura pokušava da obuzda svoja osjećanja, znajući da je niko ne bi razumio... Roman nominovan za prestižnu švedsku nagradu „August”.', 'Искренний, щемящий и невероятно честный роман о первой запретной влюбленности и мучительных шагах к взрослению.', 'A deeply honest, tender novel about an impossible first crush and the confusing, bittersweet steps of growing up.', 'Duboko iskren i dirljiv roman o prvoj nemogućoj zaljubljenosti i gorko-slatkom putu odrastanja.', '/covers/DP-0209.webp', '#945864', 'teens', 'ru', 'available', '', '["real","friends"]', '["first love","growing up","school life","swedish literature","teen drama"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('скажи-красная-шапочка-210', 'DP-0210', 'Скажи, Красная Шапочка', 'Red Riding Hood Must Cry', 'Reci, Crvenkapice', 'Беате Тереза Ханика', 'Beate Teresa Hanika', 'Beate Tereza Hanika', '', 'КомпасГид', NULL, NULL, 11, 15, 'big', 'Мальвине - тринадцать лет, и она, как все ее сверстницы, ходит в школу, любит болтать с лучшей подружкой Лиззи, занимается музыкой, воюет с мальчишками на вилле, катается на велосипеде, влюбляется, ссорится со старшей сестрой, навещает дедушку, словно Красная Шапочка... Но что-то не так. У Мальвины есть темная тайна - то, в чем стыдно признаться, но очень тяжело держать в себе. Однажды она пытается рассказать правду родным, но ее не хотят услышать и понять. Даже брат, который раньше всегда ее поддерживал... Пронзительный, светлый, остроумный, поэтичный роман немецкой писательницы Беате Терезы Ханики - ее первая книга для подростков, но именно за него Беате получила несколько премий, и в том числе была номинирована на Немецкую детскую литературную премию.', 'Thirteen-year-old Malvina leads an ordinary teen life: hanging out with her best friend Lizzie, practicing music, bickering with her sister, and visiting her grandfather like Little Red Riding Hood. But Malvina carries a dark, painful secret that becomes impossible to keep inside. When she finally attempts to tell her family, she is met with deafening denial and silence. A poignant, sensitive, and brave novel about the power of finding one''s voice.', 'Trinaestogodišnja Malvina živi tipičnim tinejdžerskim životom: druži se s najboljom drugaricom Lizi, svira, vozi bicikl, svađa se sa starijom sestrom i redovno posjećuje djeda, baš poput Crvenkapice. Ali Malvina nosi mračnu i tešku tajnu koju više ne može držati u sebi. Kada pokuša da kaže istinu, porodica odbija da je sasluša. Dirljiva, hrabra i poetska priča o snazi da se prekine tišina.', 'Важная, смелая и невероятно честная повесть о том, как трудно, но жизненно необходимо найти свой голос и разрушить стену молчания.', 'A brave, deeply moving novel reminding every young reader that finding your voice is hard, but breaking the silence is essential.', 'Hrabra i duboko potresna priča koja podsjeća mlade da njihov glas ima težinu i da se zidovi ćutanja mogu i moraju srušiti.', '/covers/DP-0210.webp', '#b83338', 'teens', 'ru', 'available', 'Для старшего школьного возраста.', '["real","friends"]', '["growing up","courage","family secrets","breaking silence","teen drama"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('через-границу-211', 'DP-0211', 'Через границу', 'The Crossing', 'Preko granice', 'Майя Лунде', 'Maja Lunde', 'Maja Lunde', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Герде десять лет, Отто - двенадцать. Они брат и сестра. Герда любит приключения, воображает себя мушкетером. Отто увлекается географией, целыми днями сидит с книжкой. Как и все дети, они ссорятся, мирятся, играют в прятки. Разве что обедают очень скромно - ведь сейчас война. Однажды они встречают других детей, тоже брата и сестру. Только этим детям грозит опасность, даже гибель. Больше того - теперь и родители Герды и Отто в опасности. Герда понимает - спасти нужно всех. "Верхняя полка" - серия книг для тех, кто уже вырос из сказок и историй с картинками и интересуется реальным миром. Для тех, кто задает вопросы и ищет ответы.', 'Gerda is ten, and Otto is twelve. They quarrel, make peace, and play hide-and-seek—except it is wartime Norway in 1942. When their parents are arrested and two Jewish children are found hiding in their basement, Gerda and Otto realize they must risk everything on a perilous winter journey across the border to neutral Sweden.', 'Gerda ima deset godina, a Oto dvanaest. Kao i svi brat i sestra, oni se svađaju i igraju žmurke, ali ratno je doba u okupiranoj Norveškoj 1942. godine. Kada njihovi roditelji budu uhapšeni, a u podrumu pronađu dvoje skrivene jevrejske djece, Gerda i Oto kreću na opasno putovanje kroz snijeg kako bi ih spasili i preveli preko granice u Švedsku.', 'Пронзительная и захватывающая повесть о том, как обычные дети находят в себе мужество стать настоящими героями в самый темный час истории.', 'A gripping and heart-wrenching wartime journey proving that courage and compassion can outshine the darkest shadows.', 'Dirljiva i napeta ratna priča koja dokazuje da dječja hrabrost i dobrota mogu pobijediti i najmračnija vremena.', '/covers/DP-0211.webp', '#3b556e', 'teens', 'ru', 'available', 'Для среднего школьного возраста.', '["adventure","real","friends"]', '["wwii","courage","siblings","historical fiction","escape"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('папа-пелерин-212', 'DP-0212', 'Папа Пелерин', 'Pappa Pellerin''s Daughter', 'Tata Pelerin', 'Мария Грипе', 'Maria Gripe', 'Marija Gripe', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Луэлла живет в лесу с двумя братьями-малышами - вдали от других людей. Она очень ждет маму, а папу совсем не помнит. Мама иногда присылает письма, вместо папы Луэлла соорудила пугало. Странно? Да, Луэлла - странная девочка. Она может даже напугать, особенно когда произносит слова, похожие на заклинание: "Змеюшкины слезы, луноцвет, волчья капуста…" Луэлла не подозревает, что скоро все переменится, с братьями ее разлучат, а жить придется в городе. Здесь горит электричество, улицы заполнены толпами, и все без умолку говорят. Будет очень трудно. Справится ли она? И дождется ли ее пугало - Папа Пелерин?', 'Loella lives deep in the forest caring for her two toddler brothers, far from civilization, patiently awaiting letters from their mother. In place of the father she never knew, she builds a scarecrow named Papa Pellerin. Wild and fiercely independent, Loella knows forest lore and secret chants—until authorities intervene, separating the siblings and sending Loella to a noisy city foster home. Will this resilient forest girl survive the bustling urban world, and will Papa Pellerin still be waiting for her?', 'Luella živi duboko u šumi brinući o dvojici male braće, daleko od svijeta, strpljivo čekajući pisma od majke. Umjesto oca koga nikada nije upoznala, napravila je strašilo po imenu Tata Pelerin. Divlja, neobična i samostalna, Luella šapuće bajalice biljkama — sve dok je jednog dana ne odvoje od braće i presele u bučan, nepoznat grad. Može li se šumska djevojčica snaći među ljudima i hoće li je njen Tata Pelerin dočekati?', 'Пронзительная скандинавская классика о дикой лесной девочке, вынужденной приручать чужой и шумный взрослый мир.', 'A poignant Nordic classic about a fiercely independent forest girl forced to navigate the bustling, bewildering world of adults.', 'Dirljiv nordijski klasik o divljoj, samosvojnoj šumskoj djevojčici koja mora da pronađe svoje mjesto u bučnom svijetu odraslih.', '/covers/DP-0212.webp', '#3b5e48', 'teens', 'ru', 'available', 'Для среднего школьного возраста.', '["real","adventure"]', '["growing up","forest life","scarecrow","family secrets","scandinavian classic"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('элвис-карлсон-213', 'DP-0213', 'Элвис Карлсон', 'Elvis Karlsson', 'Elvis Karlson', 'Мария Грипе', 'Maria Gripe', 'Marija Gripe', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'По мнению маминых подруг, Элвис очень непослушный ребенок. Но если бы они только знали, сколько у него важных дел! Именно поэтому он целыми днями пропадает на улице. Элвис ухаживает за цветами, растущими в парках, оберегает от хулиганов старый дом Юлии и, самое главное, - хранит свою Тайну. Правда, он пока не знает, что это за Тайна, но обязательно это выяснит! Мария Грипе - одно из важнейших имен в истории мировой литературы для детей. Многие ее романы были экранизированы и стали театральными постановками. Книги Марии Грипе удостоены множества литературных наград и переведены на 29 языков. Гравюры к роману "Элвис Карлссон" были созданы мужем писательницы Харальдом Грипе, который проиллюстрировал в этой технике почти все ее книги.', 'To his mother’s friends, Elvis is an unruly and difficult child. If only they knew how many urgent matters demand his attention! He spends his days outdoors taking care of park flowers, protecting old Julia’s house from neighborhood bullies, and most importantly, guarding his great Secret—even if he hasn''t figured out what it is yet. A masterwork of Swedish children''s literature, Maria Gripe’s tender and perceptive novel delves into the solitary, rich inner life of a misunderstood boy.', 'Za prijateljice svoje majke, Elvis je samo neposlušan dječak. Ali kad bi samo znale koliko važnih poslova on zapravo ima! Zato dane provodi napolju: njeguje cvijeće u gradskom parku, čuva staru kuću Julije od huligana i, što je najvažnije, čuva svoju Tajnu — iako još uvijek ne zna tačno šta je to. Dirljiv klasik čuvene švedske autorke Marije Gripe o dječijem unutrašnjem svijetu i odrastanju.', 'Пронзительная и тонкая скандинавская классика о мальчике, чей богатый внутренний мир взрослые упорно путают с непослушанием.', 'A poignant, wonderfully observant Scandinavian classic about an introspective boy whose rich inner world is constantly misunderstood by adults.', 'Dirljiva i nježna skandinavska priča o dječaku čiji bogati unutrašnji svijet odrasli uporno miješaju sa nestašlukom.', '/covers/DP-0213.webp', '#3b6e5e', 'teens', 'ru', 'available', 'Для детей младшего и среднего школьного возраста.', '["real","friends"]', '["growing up","inner world","scandinavian classic","secrets"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тень-на-каменной-скамейке-214', 'DP-0214', 'Тень на каменной скамейке', 'The Shadow on the Stone Bench', 'Sjenka na kamenoj klupi', 'Мария Грипе', 'Maria Gripe', 'Marija Gripe', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', '1911 год. Каролина поступает горничной в самую обычную семью, и привычный ход жизни тотчас меняется. Вскоре веселая и умная Каролина становится любимицей всей семьи. Вместе с тем становится очевидно, что она хранит какую-то тайну. Кажется, Каролина не совсем та, за кого они ее принимают. Где она пропадает по ночам? И почему так интересуется старым фамильным фотоальбомом? Первая книга знаменитой тетралогии о тенях - остросюжетная психологическая проза с элементами мистики, которую так любят поклонники Марии Грипе во всем мире.', 'Set in 1911, the story begins when Carolin arrives as a maid in a typical family, turning their peaceful routine upside down. Smart and spirited, she quickly charms everyone, yet an aura of mystery surrounds her. Where does she slip away to at night, and why is she so fascinated by an old family photo album? The first book in Maria Gripe''s acclaimed Shadow quartet weaves gripping psychological drama with subtle gothic suspense.', 'Godina je 1911. Kerolin se zapošljava kao sobarica u sasvim običnoj porodici i njihov miran život odmah se mijenja. Pametna i vedra, ubrzo osvaja svačije srce, ali postaje očigledno da krije neku tajnu. Gdje nestaje noću i zašto je toliko zanima stari porodični album? Prva knjiga čuvene tetralogije o sjenkama donosi napetu psihološku priču prožetu suptilnom nordijskom mistikom.', 'Загадочная и тонкая северная готика для тех, кто любит семейные тайны, шорох старых платьев и неразгаданные загадки.', 'A masterclass in atmospheric Nordic mystery full of shadowy corners, whispered secrets, and hidden identities.', 'Izuzetna nordijska misterija puna sjenovitih hodnika, porodičnih tajni i skrivenih identiteta.', '/covers/DP-0214.webp', '#3b4d61', 'teens', 'ru', 'available', 'Издание адресовано детям среднего и старшего школьного возраста.', '["spooky","real"]', '["swedish literature","mystery","family secrets","historical fiction","gothic"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-гитлер-украл-розового-крол-215', 'DP-0215', 'Как Гитлер украл розового кролика', 'When Hitler Stole Pink Rabbit', 'Kad je Hitler ukrao ružičastog zeca', 'Джудит Керр', 'Judith Kerr', 'Džudit Ker', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', '1933 год. Девятилетняя Анна живет обычной жизнью берлинской школьницы, сочиняет стихи, играет с друзьями - как вдруг все резко меняется. Опасаясь преследований со стороны нацистов, ее семья спешно уезжает из Берлина. Швейцария, Франция и, наконец, Англия - путешествие затянется на два с лишним года, за которые девочка познакомится с культурой других стран, выучит французский и поймет, что значит - быть беженцем. И все это время ее не будет покидать воспоминание о плюшевом розовом кролике, оставленном в берлинском доме. Эта книга написана по следам реальных событий: семья Джудит Керр тоже бежала из Германии, когда к власти пришел Гитлер.', 'In 1933, nine-year-old Anna leads a carefree life in Berlin, writing poetry and playing with friends, until everything changes overnight. To escape Nazi persecution, her family flees Germany, embarking on a long journey through Switzerland and France to England. Along the way, Anna learns new languages, adapts to strange cultures, and discovers what it truly means to be a refugee—all while longing for the beloved pink plush rabbit she left behind. Based on the author''s own childhood, this tender and poignant classic shows that home is wherever your loved ones are.', 'Godine 1933. devetogodišnja Ana živi bezbrižnim životom berlinske učenice, piše pjesme i igra se s prijateljima, sve dok se preko noći sve ne promijeni. Bježeći od nacističkog progona, njena porodica napušta Njemačku i započinje putovanje preko Švajcarske i Francuske do Engleske. Kroz više od dvije godine izbjeglištva, Ana uči nove jezike, prilagođava se stranim kulturama i shvata šta znači biti izbjeglica — neprestano misleći na svog plišanog ružičastog zeca ostavljenog u Berlinu. Zasnovan na ličnim sjećanjima autorke, ovaj dirljivi roman dokazuje da je dom tamo gdje je porodica.', 'Пронзительная и удивительно светлая автобиографическая повесть о том, что даже когда мир рушится, самое главное богатство — семья, держащаяся за руки.', 'A tender, deeply touching classic showing that even when your world turns upside down, home stays intact as long as you have your family by your side.', 'Dirljiva i nevjerovatno topla autobiografska priča koja nas podsjeća da, čak i kad se čitav svijet ruši, pravi dom ostaje tamo gdje su naši najdraži.', '/covers/DP-0215.webp', '#d5727e', 'teens', 'ru', 'available', 'Для детей среднего и старшего школьного возраста.', '["real","adventure","friends"]', '["история","семья","эмиграция","взросление","автобиография"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-бог-съел-что-то-не-то-216', 'DP-0216', 'Как Бог съел что-то не то', 'The Other Way Round', 'Kako je Bog pojeo nešto pogrešno', 'Джудит Керр', 'Judith Kerr', 'Džudit Ker', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Продолжение романа Джудит Керр "Как Гитлер украл розового кролика". 1940 год, Великобритания. Анна - пятнадцатилетняя девушка, в которой никто не узнал бы немецкую беженку, а ее брат Макс - один из лучших студентов Кембриджа. Семья Анны избежала смертельной опасности во Франции, но война настигает их и в Лондоне. Бомбежки, страх, ночные кошмары, а вдобавок - эмигрантская бедность, неустроенность и неожиданное притеснение со стороны английских властей. Все, что Анна может противопоставить выпавшим на ее долю трудностям, - это молодость, талант и жажда счастья. Но достаточно ли этого?', 'The sequel to Judith Kerr''s ''When Hitler Stole Pink Rabbit''. It is 1940 in London, and fifteen-year-old Anna is navigating life as a teenage refugee in the midst of the Blitz. Bombs fall every night, poverty and uncertainty loom large, and her family faces unexpected scrutiny from British authorities. Yet, Anna confronts the wartime chaos with creative passion, adolescent spirit, and an enduring hope for happiness.', 'Nastavak voljenog romana Džudit Ker „Kad je Hitler ukrao ružičastog zeca“. Godina je 1940, London pod bombama. Petnaestogodišnja Ana odrasta u gradu zahvaćenom ratom, balansirajući između siromaštva, izbjegličke neizvjesnosti i pritiska vlasti, ali se protiv svih nedaća bori umjetničkim talentom, mladošću i neugasivom željom za srećom.', 'Пронзительное и светлое продолжение истории взросления под свист лондонских бомб, где искусство и вера в будущее побеждают тьму.', 'A poignant and luminous coming-of-age story amidst the London Blitz, proving that art and youthful resilience can outshine the darkest nights.', 'Dirljiva i iskrena priča o odrastanju pod londonskim bombama, gdje umjetnost i mladalački duh pobjeđuju i najteže dane.', '/covers/DP-0216.webp', '#4a6274', 'teens', 'ru', 'available', '', '["real"]', '["coming-of-age","world-war-ii","refugees","london","family"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('а-мама-дома--217', 'DP-0217', 'А мама дома?', 'A Small Person Far Away', 'Je li mama kod kuće?', 'Джудит Керр', 'Judith Kerr', 'Džudit Ker', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Третья, заключительная, часть автобиографической трилогии Джудит Керр рассказывает о послевоенной жизни Анны, вместе с семьей бежавшей из Германии в 1933 году. Война уже 11 лет как закончилась, Анна живет с мужем в Лондоне, у них все благополучно. Но тут приходит телеграмма из Берлина: мама Анны находится в коме. Анна тут же вылетает в Берлин. В Берлин прилетает и брат Анны, Макс. В течение нескольких дней мама Анны приходит в себя. Это сильная, энергичная и полная жизни женщина, но тяжелый опыт эмиграции сказывается и на ней. Макс и Анна остаются в Берлине на какое-то время, чтобы встретиться со своим прошлым, со своими страхами, и понять, какую глубокую незаживающую рану оставила война в душах людей. Но жизнь продолжается: вернувшись в Лондон, Анна понимает, что ждет ребенка.', 'The concluding chapter of Judith Kerr’s autobiographical trilogy follows Anna as an adult living happily in London eleven years after the end of the war. Suddenly, a telegram arrives from Berlin: her mother is in a coma. Anna rushes to Germany, joined by her brother Max. As their mother slowly recovers, brother and sister confront their past, their lingering traumas, and the deep emotional scars the war left behind. Yet life moves forward, bringing renewal and the dawn of a new generation.', 'Završni dio autobiografske trilogije Džudit Ker prati Anu kao odraslu ženu koja jedanaest godina nakon rata mirno živi u Londonu. Iznenada stiže telegram iz Berlina: njena majka je u komi. Ana smjesta kreće na put, gdje joj se pridružuje i brat Maks. Dok im se majka oporavlja, njih dvoje se suočavaju sa sopstvenom prošlošću, potisnutim strahovima i nevidljivim ranama koje je rat ostavio — shvatajući da se život ipak nastavlja i donosi novu nadu.', 'Пронзительная история взросления и примирения с прошлым, напоминающая, что любовь и жизнь всегда сильнее любых пережитых бурь.', 'A deeply moving story about confronting old ghosts, healing family wounds, and discovering that hope always outlives hardship.', 'Dirljiva priča o suočavanju sa prošlošću, porodičnoj snazi i nadi koja pobjeđuje i najteže ožiljke.', '/covers/DP-0217.webp', '#5c768d', 'teens', 'ru', 'available', '', '["real"]', '["family","postwar","memory","growing up","berlin"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('солнце-крутой-бог-218', 'DP-0218', 'Солнце - крутой бог', 'The Sun Is a Mighty God', 'Sunce je moćan bog', 'Юн Эво', 'Jon Ewo', 'Jon Evo', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Солнце крутой бог роман известного норвежского писателя Юна Эво, который с иронией и уважением пишет о старых как мир и вечно новых проблемах взрослеющего человека. Перед нами дневник подростка, шестнадцатилетнего Адама, который каждое утро забирается на крышу элеватора, чтобы приветствовать Солнце, заключившее с ним договор. В обмен на ежедневное приветствие Солнце обещает помочь исполнить самую заветную мечту Адама перестать быть ребенком.', 'A witty and deeply touching novel by celebrated Norwegian author Jon Ewo explores the timeless rollercoaster of growing up. Written as the intimate diary of sixteen-year-old Adam, who climbs onto a grain elevator roof every morning to greet the Sun. In exchange for this daily ritual, the Sun has agreed to help grant Adam''s greatest, most daunting wish: to finally stop being a child.', 'Duhovit i dirljiv roman poznatog norveškog pisca Jona Eva bavi se vječitim izazovima odrastanja. Pred nama je intimni dnevnik šesnaestogodišnjeg Adama, koji se svakog jutra penje na krov silosa kako bi pozdravio Sunce. U zamjenu za ovaj svakodnevni ritual, Sunce obećava da će mu ispuniti najveću želju — da konačno prestane biti dijete.', 'Ироничный и пронзительно честный дневник о том, как непросто взрослеть — даже если твоим тайным союзником выступает само Солнце!', 'A sharp, honest, and wonderfully funny teen diary about how tough growing up really is — even when the Sun itself is in your corner!', 'Iskren, duhovit i dirljiv tinejdžerski dnevnik o tome koliko je teško odrasti — čak i kada ti leđa čuva samo Sunce!', '/covers/DP-0218.webp', '#e67e22', 'teens', 'ru', 'available', '', '["real","funny"]', '["coming of age","diary","teenagers","norwegian literature","growing up"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кубик-рубика-и-пятый-битл-219', 'DP-0219', 'Кубик Рубика и пятый битл', 'The Rubik''s Cube and the Fifth Beatle', 'Rubikova kocka i peti Bitls', 'Ханс Улав Хамран', 'Hans Olav Hamran', 'Hans Olav Hamran', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', '8 декабря 1980 года. В Нью-Йорке убит Джон Леннон. Для пятнадцатилетнего Андерса это трагедия, ведь он единственный в своей школе фанат "Битлз". Сверстники пытаются травить Андерса, но есть у него и друзья - Фруде и Бригт. А учитель математики по прозвищу Сосиска - тоже фанат битлов. Это книга о дружбе и музыке, о первой влюбленности и безумных поступках, о потери и горе. В общем, о том, каково это - быть подростком. Ханс Улав Хамран - норвежский писатель и IT-специалист. "Кубик Рубика и пятый Битл" - первая художественная книга Хамрана.', 'December 8, 1980. John Lennon is murdered in New York, devastating fifteen-year-old Anders, the sole Beatles fanatic in his school. While some classmates pick on him, Anders leans on his best friends Frode and Brigt, and an eccentric math teacher nicknamed Sausage, who also shares a passion for rock music. A warm, poignant coming-of-age story about 1980s youth, first crushes, heavy grief, and the timeless power of great music.', '8. decembar 1980. Džon Lenon je ubijen u Njujorku, što duboko pogađa petnaestogodišnjeg Andersa, jedinog pravog obožavaoca Bitlsa u školi. Dok ga pojedini vršnjaci zadirkuju, Anders pronalazi utočište u vjernim prijateljima Frodu i Brigtu, kao i nastavniku matematike zvanom Kobasica, koji takođe obožava rokenrol. Topla i iskrena priča o odrastanju u osamdesetim godinama, prvoj ljubavi, gubitku i snazi prijateljstva.', 'Пронзительная и тёплая хроника взросления в 1980-х, где музыка «Битлз» и верные друзья спасают от любых школьных невзгод.', 'A poignant, retro coming-of-age story where Beatles vinyl and loyal friends help survive the bittersweet storms of growing up.', 'Dirljiva i nostalgična priča o odrastanju uz ploče Bitlsa, Rubikovu kocku i prijatelje koji liječe svako slomljeno srce.', '/covers/DP-0219.webp', '#c84b31', 'teens', 'ru', 'available', 'Для старшего школьного возраста.', '["friends","real"]', '["1980s","the beatles","coming of age","friendship","music"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зимняя-бухта-220', 'DP-0220', 'Зимняя бухта', 'Winter Bay', 'Zimska uvala', 'Матс Валь', 'Mats Wahl', 'Mats Wahl', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Если тебе шестнадцать, жизнь полна проблем. И в школе, и дома только они. Сбежишь на улицу, найдешь там новые, ведь твой приятель - отпетый хулиган. Очень хочется любви, но это тоже проблема, и огромная. Любовь не всегда валится прямо в руки. Наконец, что-то в жизни Йон-Йона начинает меняться. Почти случайно он спас маленькую девочку, потом познакомился с ее сестрой... Но похоже, без проблем Йон-Йон жить уже не умеет, а они - без него. "Все сложно" говорят иногда, если речь заходит о самом важном: любви, поисках себя, попытках понять жизнь. Мы назвали так серию книг о тех, кого считают уже взрослыми, способными во многом разобраться, и кто от этого лишь острее чувствует свою незащищенность. Все, абсолютно все очень сложно, временами - ложно. Такое случается в любом возрасте, но чаще всего - в юности.', 'At sixteen, life is a minefield of complications: trouble at home, friction at school, and street life alongside a reckless best friend. Longing for real connection feels impossible until John-John unexpectedly rescues a young girl and meets her sister from across the bay. But stepping outside your own neighborhood comes with a heavy price, and navigating first love while figuring out who you are proves to be the hardest challenge of all.', 'Kad imaš šesnaest godina, život je prepun problema – i u školi, i kod kuće, a na ulici te čekaju nove nevolje uz problematičnog najboljeg druga. Ljubav izgleda nedostižno sve dok Jon-Jon slučajno ne spasi jednu djevojčicu i ne upozna njenu stariju sestru iz bogatog kraja. Međutim, svijet nije jednostavan, a pronaći svoje mjesto u njemu i sačuvati prvu ljubav biće njegov najveći izazov.', 'Пронзительная шведская классика о первой любви и взрослении, где искренность побеждает даже самые суровые обстоятельства.', 'A gritty yet tender Swedish classic about the dizzying courage it takes to fall in love across divided worlds.', 'Iskrena i dirljiva švedska priča o hrabrosti da se zaljubiš i pronađeš sebe u svijetu punom prepreka.', '/covers/DP-0220.webp', '#2c4a6f', 'teens', 'ru', 'available', 'Для среднего и старшего школьного возраста.', '["real","friends"]', '["coming-of-age","first-love","teens","social-drama","swedish-literature"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-прыжке-221', 'DP-0221', 'В прыжке', 'In Mid-Air', 'U skoku', 'Арне Свинген', 'Arne Svingen', 'Arne Svingen', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Отныне Дидрик может заниматься на уроках полной ерундой, даже вовсе не ходить в школу. Отныне с ним ведет беседы психотерапевт. Мило, но лучше бы злополучной ночи, после которой все это началось, никогда не было. Дидрик не желает ни о чем вспоминать, он хочет думать о черепахах. Но вспомнить придется. Почему так случилось? Что же было на самом деле? Герой знает не слишком много, он с читателем на равных - словно ведет расследование вместе с ним. Очень интересно и очень страшно, ведь расследование касается отца Дидрика. Жизнь как будто скакнула в сторону. И нет гарантий, что не прыгнет еще дальше, когда все станет ясно.', 'From now on, Didrik can slack off in class, skip school, and have regular sessions with a therapist. It might sound like freedom, but he would give anything to erase the tragic night that started it all. Didrik tries to distract himself with thoughts about turtles, but remembering is unavoidable. What really happened with his father? Unfolding like an intimate detective investigation alongside the reader, Didrik''s journey tackles trauma, truth, and a life that has suddenly leaped off track.', 'Od sada Didrik može da zabušava na časovima, pa čak i da uopšte ne ide u školu, dok ga redovno posjećuje psihoterapeut. Zvuči primamljivo, ali dao bi sve da se ta kobna noć nikada nije dogodila. Didrik bi radije mislio o kornjačama, ali zaborav nije moguć. Šta se zapravo dogodilo s njegovim ocem? Poput iskrene i napete istrage, dječak zajedno sa čitaocem traga za bolnom istinom dok mu život izmiče tlu pod nogama.', 'Захватывающая и пронзительная психологическая драма для подростков, где семейная тайна раскрывается шаг за шагом, словно в настоящем детективе.', 'A gripping and poignant psychological mystery where a boy pieces together the hard truth about his father, step by uncertain step.', 'Napeta i dirljiva psihološka priča u kojoj dječak, korak po korak, poput pravog detektiva sklapa istinu o svom ocu.', '/covers/DP-0221.webp', '#2c4a63', 'teens', 'ru', 'available', 'Для среднего и старшего школьного возраста.', '["real"]', '["family secrets","teen drama","psychology","mystery","father and son"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('непростые-числа-222', 'DP-0222', 'Непростые числа', 'All That Counts', 'Sve što se računa', 'Ингрид Оведи Волден', 'Ingrid Ovedie Volden', 'Ingrid Ovedie Volden', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Петре двенадцать. Она считает, что все вокруг должно быть в абсолютном порядке. Если бутерброды — то по одному в руку, если голы — только четное количество, если ботинки в коридоре — то выстроенные в ряд. Но однажды в эту упорядоченную жизнь врывается... число пи! Бесконечное, неподвластное контролю и потому невыносимое, считает Петра. Она еще не знает, что столкновение с «несовершенством» мира — лишь первое из лавины счастливых, трагичных и захватывающих событий.', 'Twelve-year-old Petra needs the world to make complete sense: sandwiches eaten symmetrically in both hands, goals scored only in even numbers, and shoes neatly lined up in the hallway. But one day, the number Pi sneaks into her strictly ordered life—infinite, impossible to control, and thoroughly unbearable. Petra has yet to realize that facing the world''s messy imperfection is just the beginning of a roller-coaster of poignant, funny, and life-changing events.', 'Dvanaestogodišnjoj Petri je neophodno da sve oko nje bude u savršenom redu: sendviči po jedan u svakoj ruci, golovi samo u parnim brojevima, a cipele uredno poređane u hodniku. Međutim, jednog dana u njen posloženi život upada... broj pi! Beskonačan, nemoguć za kontrolu i zato potpuno nepodnošljiv. Petra još ne sluti da je sudar sa nesavršenošću svijeta samo početak lavine emotivnih, uzbudljivih i nezaboravnih događaja.', 'Трогательная и удивительно точная история о том, как научиться жить в неидеальном мире, даже если твой внутренний компас требует абсолютной симметрии.', 'A tender and wonderfully relatable story about learning to embrace life''s chaos, even when your inner compass desperately demands perfect symmetry.', 'Dirljiva i izuzetno topla priča o tome kako prihvatiti nesavršeni svijet, čak i kada tvoj unutrašnji kompas zahtijeva apsolutnu simetriju.', '/covers/DP-0222.webp', '#e5a93b', 'teens', 'ru', 'available', 'Для среднего школьного возраста.', '["real","friends"]', '["growing up","anxiety","math","friendship","first love"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('представь-что-меня-нет-223', 'DP-0223', 'Представь, что меня нет', 'Picture Me Gone', 'Zamisli da me nema', 'Мег Розофф', 'Meg Rosoff', 'Meg Rosof', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Двенадцатилетняя Мила уверена: из нее получился бы отличный терьер. Она не менее чуткая, быстрая и верная. Еще она прекрасно распутывает тайны, не хуже самого Пуаро. Сейчас перед ней стоит самая сложная загадка: куда пропал лучший друг ее отца за день до того, как они прилетели к нему в гости? Герои пускаются в роад-трип по штату Нью-Йорк и, как в любом истинном путешествии, не просто перемещаются в пространстве, но и сами постепенно становятся другими - мудрее, взрослее, сложнее и, может быть, чуть печальней.', 'Twelve-year-old Mila is convinced she would make an excellent terrier: she is sharp, observant, loyal, and has an uncanny knack for reading people. When her father''s best friend mysteriously disappears on the eve of their visit, father and daughter set out on a road trip across upstate New York to find him. As they follow the trail, Mila begins to see through the cracks in the adult world, uncovering quiet secrets and taking bittersweet steps toward growing up.', 'Dvanaestogodišnja Mila je uvjerena da bi bila sjajan terijer: pronicljiva je, brza, odana i posjeduje rijedak dar za rješavanje misterija. Sada je pred njom najveća zagonetka: gdje je nestao najbolji prijatelj njenog oca tik pred njihov dolazak? Krenuvši na putovanje kroz državu Njujork, Mila i njen otac ne samo da tragaju za nestalim čovjekom, već se suočavaju sa tajnama odraslih i neizbježnim, dirljivim odrastanjem.', 'Тонкая детективная история и трогательное дорожное путешествие о том, как научиться видеть правду о людях, даже когда она ранит.', 'A tender, deeply perceptive mystery and road-trip novel about learning to read between the lines of the adult world.', 'Suptilna detektivska priča i dirljivo putovanje o tome kako naučiti čitati između redova u svijetu odraslih.', '/covers/DP-0223.webp', '#3b5a6c', 'teens', 'ru', 'available', '', '["real","adventure","friends"]', '["road trip","coming of age","mystery","father daughter","detective"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('comedy-queen-224', 'DP-0224', 'Comedy queen', 'Comedy Queen', 'Kraljica komedije', 'Йенни Йегерфельд', 'Jenny Jägerfeld', 'Jenny Jägerfeld', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Саше вот-вот исполнится двенадцать. Она убеждена - спасение в юморе. Надо стать комиком и веселить людей со сцены. Надо учиться шутить, развивать свою "юмористическую жилку". Решено! Теперь Саша будет записывать удачные остроты, репетировать, узнает все про "сетап" и "панчлайн". Но откуда уверенность, что именно это спасет ее? И от чего, кстати? Может быть, причина всех шуток и странностей - глубокая печаль? Йенни Йегерфельд - шведский психолог и писательница. Первый роман Йенни для подростков - "Лежу на полу, вся в крови" - вышел в 2010 году и сразу же получил премию Августа Стриндберга. В 2017 году Йегерфельд выиграла премию Астрид Линдгрен. Роман Comedy Queen попал в шорт-лист премии Августа Стриндберга в 2018 году.', 'Sasha is about to turn twelve, and she has made a firm decision: she is going to become a stand-up comedian. She believes laughter is the ultimate shield, determined never to cry the way her mother did. Armed with a notebook for sharp setups and punchlines, Sasha sets out to conquer the stage. But behind the laughter lies a quiet heartache waiting to be understood. A deeply touching, award-winning Swedish novel about grief, resilience, and the healing power of humor.', 'Saša uskoro puni dvanaest godina i ima jasan cilj: postaće stendap komičarka. Čvrsto vjeruje da je humor jedini spas i da, ako uspije da nasmije ljude, nikada neće plakati onako kako je plakala njena majka. Sa sveskom punom doskočica i pančlajna, Saša kreće u osvajanje scene. Ipak, iza svih tih fora krije se duboka tuga koja traži iscjeljenje. Dirljiva, topla i nevjerovatno iskrena priča o odrastanju, tugovanju i snazi smijeha.', 'Пронзительная и невероятно смешная история о том, как стендап и детская отвага помогают справиться с самыми тёмными временами.', 'A deeply moving and laugh-out-loud tale about how stand-up comedy and fierce courage can heal a broken heart.', 'Dirljiva i nevjerovatno duhovita priča o tome kako stendap i dječja hrabrost mogu da zacijele i najteže rane.', '/covers/DP-0224.webp', '#f4a261', 'teens', 'ru', 'available', 'Для среднего и старшего школьного возраста.', '["funny","real","friends"]', '["stand-up","grief","growing up","family","sweden"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('моя-ослепительная-жизнь-225', 'DP-0225', 'Моя ослепительная жизнь', 'My Spectacular Life', 'Moj blistavi život', 'Йенни Йегерфельд', 'Jenny Jägerfeld', 'Dženi Jegerfeld', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Сигге двенадцать лет, у него есть мама, две сестры, морские свинки, черепаха и огромный пес по кличке Эйнштейн. Он только что перешел в новую школу и решил начать новую жизнь: стать популярным и завести много друзей. Но как это сделать? И возможно ли изменить свою жизнь за такое короткое время? Это первый роман в трилогии популярной шведской писательницы, психолога и журналистки Йенни Йегерфельд, чьи книги переведены на 18 языков и удостоены множества престижных премий.', 'Twelve-year-old Sigge has just moved to a new town with his mom, two sisters, guinea pigs, a turtle, and an enormous dog named Einstein. Starting at a new school, he makes a bold sixty-day plan to reinvent himself and become the coolest, most popular kid around. But can you really change who you are overnight? A hilarious, heartwarming, and poignant Swedish coming-of-age story about identity, family chaos, and genuine friendship.', 'Dvanaestogodišnji Sige seli se u novi grad sa mamom, dvije sestre, zamorcima, kornjačom i ogromnim psom po imenu Ajnštajn. Polazak u novu školu savršena je prilika za novi početak: Sige ima šezdeset dana da postane popularan i stekne gomilu prijatelja. Ali kako se to radi i da li se uopšte može promijeniti preko noći? Prva knjiga iz nagrađivane švedske trilogije puna je humora, topline i pravih tinejdžerskih izazova.', 'Уморительно смешная, искренняя и невероятно точная история о том, как трудно и важно быть собой, даже когда отчаянно хочется стать суперзвездой школы.', 'A hilarious and deeply relatable tale about the messy quest for popularity and the quiet magic of discovering who you truly are.', 'Urnebesno duhovita i iskrena priča o teškom putu do popularnosti i otkriću da je najljepše biti jednostavno svoj.', '/covers/DP-0225.webp', '#f4b728', 'teens', 'ru', 'available', '', '["funny","friends","real"]', '["school life","growing up","friendship","humor","family","scandinavian literature"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волна-любви-на-озере-дружбы-226', 'DP-0226', 'Волна любви на озере дружбы', 'A Wave of Love on a Lake of Friendship', 'Talas ljubavi na jezeru prijateljstva', 'Мари Деплешен', 'Marie Desplechin', 'Mari Deplešen', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Сюзанне одиннадцать, и ей не хватает любви. «Ты меня любишь?» — спрашивает она маму, но ее ответ кажется Сюзанне недостаточно убедительным. А папу она видит редко, потому что он либо работает, либо прыгает с парашютом. И тут в семье появляется девятнадцатилетний Тим, репетитор по английскому языку, который станет ее единственным другом и который поможет ей чуть лучше понять, что же это за чувство — любовь.', 'Suzanne is eleven, and she desperately needs affection and reassurance. When she asks her mother, ''Do you love me?'', the answer never feels convincing enough, and her father is rarely around, busy either working or skydiving. Everything changes when nineteen-year-old Tim arrives as her English tutor, quickly becoming her closest confidant and helping her unpack what love really means.', 'Suzan ima jedanaest godina i silno joj nedostaje pažnje i ljubavi. Kad upita mamu da li je voli, odgovor joj ne zvuči dovoljno iskreno, a oca rijetko viđa jer stalno radi ili skače padobranom. Sve se mijenja kada u njen život uđe devetnaestogodišnji Tim, nastavnik engleskog, koji joj postaje jedini pravi prijatelj i pomaže joj da shvati šta je zapravo ljubav.', 'Тонкая, ироничная и очень бережная повесть о взрослении, поисках близости и том самом первом понимании любви.', 'A delicate, witty, and heartfelt coming-of-age tale about craving connection and discovering what affection truly means.', 'Tanka, duhovita i topla priča o odrastanju, potrazi za bliskošću i otkrivanju šta ljubav zapravo znači.', '/covers/DP-0226.webp', '#4a7c8f', 'teens', 'ru', 'available', 'Для детей среднего школьного возраста.', '["real","friends"]', '["growing-up","friendship","family","emotions","teenagers"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('любовь-будет-всегда-227', 'DP-0227', 'Любовь будет всегда', 'Love Lasts Forever', 'Ljubav ostaje zauvijek', 'Мони Нильсон', 'Moni Nilsson', 'Moni Nilson', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Леа - самая обычная девочка, она любит дельфинов и отлично играет в футбол. Ей бы очень хотелось иметь самую обычную маму, которая ходит на работу и строит планы на будущее. Но это невозможно: мама Леи больна раком. Если твоя мама должна умереть, ты продолжаешь жить: влюбляешься, смотришь смешное кино, ссоришься с одноклассниками. Это книга о жизни и дружбе, о том, что любовь, которую ты получаешь от человека, не исчезает после его смерти, а остается с тобой навсегда.', 'Lea is a typical teenager who loves dolphins and plays football like a champ. What she wants most is an ordinary mom who goes to work and makes plans for tomorrow. But Lea''s mom is terminally ill with cancer. Even when facing the unthinkable, life keeps rolling: Lea falls in love, laughs at goofy movies, and bickers with classmates. A deeply moving, luminous story proving that the love we receive never fades—it stays inside us forever.', 'Lea je sasvim obična djevojčica: voli delfine i odlično igra fudbal. Najviše na svijetu voljela bi da ima sasvim običnu mamu koja ide na posao i pravi planove za budućnost. Međutim, njena mama boluje od raka. Čak i kada se suočavaš sa gubitkom, život teče dalje: zaljubljuješ se, gledaš komedije i svađaš se sa drugarima. Ovo je dirljiva priča o prijateljstvu i spoznaji da ljubav koju primamo nikada ne nestaje.', 'Пронзительная, честная и светлая повесть о том, что даже перед лицом страшной потери жизнь продолжается, а настоящая любовь никуда не исчезает.', 'A tender, heartbreaking, yet fiercely life-affirming novel reminding teens that even in grief, love is something nobody can ever take away.', 'Dirljiva, iskrena i topla priča koja podsjeća tinejdžere da život ide dalje i da ljubav koju nosimo u sebi nikada ne umire.', '/covers/DP-0227.webp', '#c25975', 'teens', 'ru', 'available', 'Для среднего школьного возраста.', '["real","friends"]', '["grief","growing up","family","first love","illness"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('с-кем-бы-побегать-228', 'DP-0228', 'с кем бы побегать', 'Someone to Run With', 'Neko s kim trčati', 'Давид Гроссман', 'David Grossman', 'David Grosman', '', 'Розовый жираф', NULL, NULL, 11, 15, 'big', 'Никогда еще Асаф так не бегал, никогда еще не нарушал стольких правил одновременно. Чтобы найти владельцев потерявшейся собаки, шестнадцатилетний мальчик бежит по Иерусалиму, и за каждым поворотом его ждут удивительные встречи: с добрейшим продавцом пиццы, с греческой монашкой, пятьдесят лет не выходившей из дома, с мальчиком-астрономом, с хозяйкой кафе, лицо которой покрыто шрамами… Все они рассказывают ему о необыкновенной Тамар, хозяйке собаки. Однако чем дальше, тем опаснее становятся поиски. Каждый день на тех же иерусалимских улицах выступают молодые уличные артисты - музыканты, актеры, гимнасты, и среди них - Тамар, которая поет так, что толпа замирает. Она тоже ищет одного человека. Ищет, чтобы спасти. И сама оказывается в ужасной ловушке.', 'Sixteen-year-old Asaf is tasked with an unusual summer job: finding the owner of an abandoned golden retriever by letting the dog lead him through the streets of Jerusalem. As the dog drags him from pizza shops to secluded monasteries, Asaf pieces together the puzzle of Tamar, a fiercely independent girl who has shaved her head and plunged into a dangerous criminal underworld of street performers to rescue someone she loves.', 'Šesnaestogodišnji Asaf dobija neobičan zadatak: da pronađe vlasnika izgubljenog psa prateći ga kroz ulice Jerusalima. Prateći trag neumornog psa, Asaf postepeno sklapa priču o Tamar — neustrašivoj djevojci koja je obrijala glavu i zakoračila u opasno podzemlje uličnih umjetnika kako bi spasila nekoga koga voli.', 'Захватывающий бег по переулкам Иерусалима на поводке отважной собаки, где каждая улика ведет к опасной тайне и настоящей любви.', 'A breathless, heart-pounding race through Jerusalem''s alleyways behind an unstoppable dog, leading straight into a daring rescue and first love.', 'Uzbudljiva jurnjava kroz jerusalimske uličice na drugom kraju psećeg povoca koja prerasta u nezaboravnu priču o hrabrosti, muzici i spasavanju.', '/covers/DP-0228.webp', '#c86432', 'teens', 'ru', 'available', '', '["adventure","animals","friends"]', '["jerusalem","coming-of-age","dogs","mystery","music"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('будь-жегорт-229', 'DP-0229', 'Будь Жегорт', 'Proud Budžes', 'Budi Žehort', 'Ирена Доускова', 'Irena Dousková', 'Irena Douskova', '', 'Розовый жираф', NULL, NULL, 11, 15, 'big', '70-е годы, Чехословакия, провинциальный город. После ввода войск СССР в Чехословакию надежды на свободную жизнь раздавлены. В том числе и надежды родителей восьмилетней Хелены Соучковой. Хотя у самой Хелены никаких особенных надежд нет: она толстая, задумчивая и над ней постоянно смеются в классе, потому что у нее фамилия не такая как у мамы, и не такая как у папы. Правда, у нее есть любимый младший брат, красивая мама-актриса, а еще она прекрасно лепит из глины, так что Хелена не унывает. Хелене приходится взрослеть на фоне печальных событий в стране. Эта история полна горькой иронии, и все же в ней светится надежда, ведь сама Хелена скоро поймет силу личной свободы каждого человека.', 'Czechoslovakia in the 1970s, a provincial town. After the Soviet invasion, hopes for a free life have been crushed—including those of eight-year-old Helenka Součková’s parents. Helenka herself doesn''t have grand expectations: she is chubby, daydreamy, and classmates tease her because her last name matches neither her mother''s nor her stepfather''s. Still, with a beloved little brother, a glamorous actress mom, and a real talent for sculpting clay, Helenka doesn''t despair. Full of gentle irony and quiet resilience, this bittersweet coming-of-age story captures the indomitable power of inner freedom.', 'Čehoslovačka 70-ih godina, provincijski gradić. Nakon ulaska sovjetskih trupa, nade u slobodan život su uništene, pa tako i snovi roditelja osmogodišnje Helenke Součkove. Sama Helenka nema prevelika očekivanja: punačka je, zamišljena i djeca u školi joj se rugaju jer joj prezime nije isto kao mami ili tati. Ipak, uz voljenog mlađeg brata, lijepu majku glumicu i talenat za vajanje, Helenka ne gubi duh. Ova priča prožeta gorkom ironijom i toplinom podsjeća na snagu unutrašnje slobode u teškim vremenima.', 'Трогательный, грустный и невероятно смешной взгляд восьмилетней девочки на непростую взрослую жизнь в социалистической Чехословакии.', 'A poignant, bittersweet, and hilariously sharp look at life in 1970s socialist Czechoslovakia through the candid eyes of an eight-year-old girl.', 'Dirljiv, gorko-sladak i nevjerovatno duhovit pogled osmogodišnje djevojčice na odrastanje u socijalističkoj Čehoslovačkoj.', '/covers/DP-0229.webp', '#b8543f', 'teens', 'ru', 'available', '', '["real","funny"]', '["growing up","historical fiction","school life","czechoslovakia","coming of age"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дом-в-котором-230', 'DP-0230', 'Дом, в котором', 'The Gray House', 'Kuća u kojoj...', 'Мариам Петросян', 'Mariam Petrosyan', 'Marijam Petrosjan', '', 'livebook', NULL, NULL, 11, 15, 'big', 'На окраине города, среди стандартных новостроек, стоит Серый Дом, в котором живут Сфинкс, Слепой, Лорд, Табаки, Македонский, Черный и многие другие. Неизвестно, действительно ли Лорд происходит из благородного рода драконов, но вот Слепой - действительно незряч, а Сфинкс - мудр и загадочен. Табаки, конечно, не шакал, хотя и любит поживиться чужим добром. Для каждого в Доме есть своя кличка и каждый проживал в нем за один день столько, сколько в Наружности мы иногда не проживаем и за целую жизнь. Каждого Дом принимал или отвергал. Дом хранил уйму тайн, и банальные "скелеты в шкафах" - лишь самый понятный угол незримого мира, куда нет хода из Наружности, где перестают действовать привычные законы пространства-времени. Дом - это нечто гораздо большее, чем просто интернат для детей, от которых отказались родители. Дом - это их отдельная вселенная.', 'On the outskirts of town stands the Gray House, home to Sphinx, Blind, Lord, Tabaqui, and many others. Here, nicknames replace real names, ordinary rules of time and space break down, and the outside world seems infinitely distant. More than just a boarding school for discarded children, the House is a living, breathing universe filled with myths, secret rituals, and uncanny wonders that accept some and exile others forever.', 'Na periferiji grada, među bezličnim novogradnjama, stoji Siva kuća u kojoj žive Sfinga, Slijepi, Lord, Tabaki i mnogi drugi. Za svakoga u Kući postoji nadimak, a u jednom danu proživi se više nego u Spoljašnjosti za čitav život. Ovo nije samo internat za djecu sa smetnjama u razvoju koju su porodice napustile — Kuća je živ, misteriozan i zatvoren univerzum sa sopstvenim zakonima, magijom i tajnama.', 'Осторожно: стоит лишь переступить порог этого загадочного Дома, и Наружность покажется вам блёклой и скучной на очень долгое время!', 'Step inside this uncanny House at your own risk: once you become part of its strange magic, the Outside world will never look the same again.', 'Zakoračite u ovu magičnu Kuću na sopstvenu odgovornost: jednom kada upoznate njen svijet, Spoljašnjost više nikada neće biti ista.', '/covers/DP-0230.webp', '#3f4a4c', 'teens', 'ru', 'available', '', '["magic","spooky","friends"]', '["magical realism","boarding school","coming of age","secrets","cult classic"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('три-четверти-231', 'DP-0231', 'Три четверти', 'Three Quarters', 'Tri četvrtine', 'Анна Красильщик', 'Anna Krasilshchik', 'Ana Krasiljščik', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Когда тебе 12 лет, мир становится с ног на голову, всё кругом трещит и рушится. А тут ты ещё попадаешь в новую школу. К тому же на дворе девяностые годы со всеми их непростыми событиями. Три школьные четверти - путь от себя, маленькой, домашней, к себе школьной, озлобленной, не понимающей, как быть не такой, как все. "Аня Красильщик росла в особенное, ни на что не похожее время. Она училась в школе не похожей на другие, а её друзья откликались на странные, ни на что не похожие прозвища. Так почему же от этой книжки, от этой истории взросления то и дело сжимается сердце, а щёки начинают ощутимо гореть - так, как будто всё это написано про тебя?" Анна Наринская, литературный критик, специальный корреспондент ИД "Коммерсант"', 'When you are twelve, the world turns upside down, and everything familiar begins to crack and crumble. To make matters worse, you find yourself in a brand-new school against the backdrop of the turbulent 1990s. Three school terms mark the painful yet necessary journey from a cozy, sheltered child to an awkward, defensive teenager trying to find her place without losing herself.', 'Kad imaš dvanaest godina, svijet se okreće naglavačke, a sve oko tebe počinje da puca. Povrh svega, prelaziš u novu školu, i to usred burnih i neizvjesnih devedesetih. Tri školska tromjesečja prate put od zaštićene, tihe djevojčice do nesigurne tinejdžerke koja očajnički pokušava da shvati kako da bude svoja i prihvaćena.', 'Искренняя и щемящая повесть о взрослении в девяностые, в которой каждый взрослый и подросток безошибочно узнает свои собственные двенадцать лет.', 'A deeply honest and poignant coming-of-age story from the nineties that will make anyone''s heart ache with recognition of their own twelve-year-old self.', 'Iskrena i dirljiva priča o odrastanju u devedesetim u kojoj će svako nepogrešivo prepoznati svojih sopstvenih dvanaest godina.', '/covers/DP-0231.webp', '#3b6e82', 'teens', 'ru', 'available', '', '["real","friends"]', '["coming of age","school life","1990s","friendship","growing up"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('анна-дарк-232', 'DP-0232', 'Анна Дарк', 'Anna d''Ark', 'Ana d''Ark', 'Мортен Санден', 'Mårten Sandén', 'Morten Sanden', '', 'ОГИ', NULL, NULL, 11, 15, 'big', 'Мортен Санден родился в 1962 году и живет в Лунде (Швеция). Он специалист в области социальной психологии. Его книги невероятно популярны на родине. Писатель умеет делать своих персонажей живыми. Это люди, с которыми вам захочется встретиться в реальности. "Анна д&#39;Арк" Толстый. В очках. Изгой. Старающийся не привлекать к себе внимания, боясь побоев и унижений. Не имеющий друзей. "Пустое место" для всех и каждого. Безнадежно влюбленный в самую бесшабашную девочку в школе. Но однажды все меняется. Оскар становится знаменитостью в своем городке.', 'Oskar is overweight, wears glasses, and tries his best to stay invisible to avoid bullies and humiliation. An outcast with zero friends, he is secretly and hopelessly in love with the wildest, most reckless girl in school: Anna d''Ark. But one day everything changes, and Oskar unexpectedly turns into an overnight local celebrity.', 'Oskar je bucmast, nosi naočare i trudi se da bude neprimijetan kako bi izbjegao nasilnike i poniženja. Autsajder bez ijednog prijatelja, beznadežno je zaljubljen u najotkačeniju i najbuntovniju djevojku u školi: Anu d''Ark. Ali jednog dana sve se mijenja i Oskar preko noći postaje lokalna zvijezda.', 'Пронзительная и честная шведская повесть о том, каково это — быть невидимкой, и что на самом деле происходит, когда тебя наконец замечают.', 'A piercingly honest Scandinavian coming-of-age story about being invisible—and what truly happens when the spotlight suddenly turns on you.', 'Dirljiva i iskrena skandinavska priča o tome kako je to biti nevidljiv i šta se zaista dešava kada te reflektori odjednom pronađu.', '/covers/DP-0232.webp', '#3b5a75', 'teens', 'ru', 'available', '', '["real","friends"]', '["growing up","first love","school","teen drama","sweden"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('принцесса-ангина-233', 'DP-0233', 'Принцесса Ангина', 'Princess Angina', 'Princeza Angina', 'Ролан Топор', 'Roland Topor', 'Rolan Topor', '', 'Самокат', NULL, NULL, 11, 15, 'big', '"Принцесса Ангина" заставляет по-другому взглянуть на мир, в котором мы живем. "Если маленькая девочка болтает вовсе не так, как пристало разговаривать маленькой девочке, то, скорее всего, она на самом деле и не девочка. И вполне может оказаться всем, чем угодно, даже хворью, а хворать никому не по душе. Хотя, если болезнь доброкачественная, можно с ней свыкнуться и перевести в разряд хронических. Разумеется, правильнее было бы без промедления обратиться к специалисту, но когда мы, наконец, собираемся к нему пойти, часто выясняется, что мы уже опоздали…"', '"Princess Angina" invites readers to look at the world from an upside-down perspective. If a little girl speaks unlike any ordinary little girl should, chances are she isn''t really a girl at all—she might just be an ailment in disguise. And while falling ill suits nobody, benign afflictions can turn into familiar, chronic companions. A brilliantly absurd, darkly whimsical masterpiece of 20th-century French surrealism.', '„Princeza Angina” poziva čitaoce da pogledaju svijet naglavačke. Ako jedna djevojčica uopšte ne priča onako kako bi priličilo maloj djevojčici, vrlo je vjerovatno da ona uopšte i nije prava djevojčica — možda je čak i sama bolest. Majstorska, apsurdna i nadrealna priča Rolana Topora puna uvrnutog humora i poetske slobode.', 'Озорная, сюрреалистичная и невероятно остроумная сказка-головоломка от классика французского авангарда для тех подростков, кто обожает абсурд и игру со смыслами.', 'A brilliantly eccentric, darkly funny surrealist tale for teens who love quirky wordplay, absurd quests, and books that break all the rules.', 'Neobična, nadrealna i vrcava bajka za tinejdžere koji vole apsurdni humor, jezičke igre i priče koje ruše sva uobičajena pravila.', '/covers/DP-0233.webp', '#8b1e28', 'teens', 'ru', 'available', '', '["funny","magic","spooky"]', '["absurdism","surrealism","dark fairytale","french literature","wordplay"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('остров-в-море-том-1-234', 'DP-0234', 'Остров в море. Том 1', 'A Faraway Island: Volume 1', 'Ostrvo u moru: Tom 1', '.Анника Тор.', 'Annika Thor', 'Anika Tor', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Сестрам Штеффи и Нелли приходится бежать в Швецию, спасаясь от преследования евреев в родной Австрии. Это значит, что девочкам предстоит жить здесь — на краю земли, в разных семьях, а потом — и городах. За сотни миль от родителей. Неизвестно, сколько это продлится. Кажется, что здесь — только море и камни. Здесь нет войны, нет гонений на евреев, но есть люди, которые поддерживают фашизм… А сами Штеффи и Нелли — остаются обычными девочками, хоть и в чужой стране. Тетралогия Анники Тор переиздаётся в России в двух томах, по две книги в каждом томе. В первый том вошли книги «Остров в море» и «Пруд белых лилий».', 'Sisters Steffi and Nelli are sent from Nazi-occupied Vienna to a remote Swedish island, far from their parents and everything they have ever known. Separated into different foster families amidst bare rocks and cold sea winds, they face a new language, isolation, and quiet prejudice, while holding on to hope for reunion. This volume includes the first two novels of the celebrated tetralogy: ''A Faraway Island'' and ''The Lily Pond''.', 'Sestre Štefi i Neli bježe iz Beča u Švedsku kako bi se spasile od progona, ostavljajući roditelje stotinama milja daleko. Na zabačenom, kamenitom ostrvu usred mora, razdvojene u dvije različite porodice, moraju da nauče novi jezik i suoče se sa predrasudama, ne gubeći nadu u ponovni susret. Prvi tom obuhvata prva dva dijela nagrađivane tetralogije: „Ostrvo u moru“ i „Ribnjak bijelih ljiljana“.', 'Пронзительная и светлая история о том, как остаться собой и сберечь надежду, даже когда привычный мир разбился, а вокруг — только скалы, холодное море и чужой язык.', 'A deeply moving and hopeful coming-of-age story about two refugee sisters finding courage and compassion on a windswept Swedish island.', 'Dirljiva i topla priča o odrastanju dvije sestre izbjeglice na vjetrovitom ostrvu, gdje dobrota i nada sijaju i u najhladnijim danima.', '/covers/DP-0234.webp', '#3b5a73', 'teens', 'ru', 'available', '', '["real","friends"]', '["historical fiction","wwii","sisters","refugees","growing up"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пруд-белых-лилий-том-2-235', 'DP-0235', 'Пруд белых лилий. Том 2', 'The Lily Pond (Book 2)', 'Ribnjak bijelih ljiljana (2. dio)', 'Анника Тор', 'Annika Thor', 'Anika Tor', '', '', NULL, NULL, 11, 15, 'big', '«Пруд Белых Лилий» – продолжение полюбившегося русским читателям романа «Остров в море» – истории о двенадцатилетней Штеффи, оказавшейся на острове в Швеции в начале Второй мировой войны. Повзрослевшая Штеффи получает стипендию и отправляется учиться в Гётеборг, где она будет жить на пансионе в семье Сёдербергов. Главное – она теперь будет находиться совсем рядом со Свеном, с которым познакомилась летом! Но что-то не складывается в новой жизни Штеффи, на вид вполне благополучной… «Что происходит с родителями? Что такое настоящая дружба? А настоящая любовь? Что лучше – правда или ложь?» – все эти вопросы переполняют ее. И берег пруда Белых Лилий становится для Штеффи местом, где она может побыть одна и попытаться разобраться в себе…', 'In this compelling sequel to ''A Faraway Island'', Steffi earns a scholarship to attend high school in Gothenburg. Boarding with an upper-class family and closer to Sven, the boy she met over the summer, Steffi expects her new life to be full of promise. But amidst the creeping shadows of World War II, agonizing worry for her parents trapped in Vienna, and the bewildering pangs of first love and social outsiderhood, Steffi finds solace beside the tranquil waters of the Lily Pond.', 'U dirljivom nastavku romana „Ostrvo u moru“, Štefi dobija stipendiju za školovanje u Geteborgu. Živi kod ugledne porodice i blizu je Svena, dječaka kog je upoznala tokom ljeta. Ipak, nova svakodnevica donosi teška iskušenja: brigu za roditelje zarobljene u ratom zahvaćenom Beču, prve ljubavne nesporazume i osjećaj nepripadanja. Mir i odgovore na burna pitanja odrastanja Štefi će potražiti na obali jezera bijelih ljiljana.', 'Пронзительная история взросления, где за витринами большого города прячутся первые взрослые тревоги, поиски себя и тихое зеркало пруда с кувшинками.', 'A poignant coming-of-age journey through the turbulence of wartime adolescence, first heartbreak, and the quiet refuge of finding one''s true voice.', 'Dirljiva i iskrena priča o odrastanju u ratno doba, prvoj ljubavi i potrazi za sopstvenim mjestom u svijetu.', '/covers/DP-0235.webp', '#2d5a57', 'teens', 'ru', 'available', '', '["real","friends"]', '["historical fiction","coming of age","world war ii","first love","refugees"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('глубина-моря-том-3-236', 'DP-0236', 'Глубина моря. Том 3', 'The Deep Sea. Book 3', 'Dubina mora. Tom 3', 'Анника Тор', 'Annika Thor', 'Anika Tor', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Что страшнее, неизвестность или страшная весть, пришедшая далеко из-за моря? Штеффи — уже далеко не ребёнок, она стремится к исполнению мечты и обретению профессии, сталкивается с несправедливостью и предательством, но не теряет надежду, даже когда Нелли отдаляется… Вестей от родителей уже нет давным-давно. И когда война кончится, вернется ли прежняя жизнь, спустя долгие шесть лет?', 'What is more terrifying: agonizing uncertainty, or devastating news arriving from across the sea? Steffi is no longer a child; she strives to fulfill her dreams and gain an education, facing injustice and betrayal along the way. Yet she refuses to lose hope, even as her sister Nellie drifts further away and silence from their parents stretches on endlessly. When the war finally ends after six long years, can their old life ever truly return?', 'Šta je strašnije: neizvjesnost ili teške vijesti koje stižu preko mora? Štefi više nije dijete; bori se za svoje snove i obrazovanje, suočava se sa nepravdom i izdajom, ali ne gubi nadu čak ni kada se Neli udaljava. O roditeljima već predugo nema glasa. A kada se rat napokon završi, hoće li se stari život ikada vratiti poslije šest dugih godina?', 'Пронзительная история взросления в тени большой войны, где надежда держится на плаву даже в самых глубоких водах.', 'A poignant, gripping coming-of-age story where hope stays afloat even in the deepest and stormiest seas.', 'Dirljiva i snažna priča o odrastanju u sjenci rata, u kojoj nada pluta čak i kroz najdublje talase.', '/covers/DP-0236.webp', '#23415c', 'teens', 'ru', 'available', '', '["real","friends"]', '["historical fiction","wwii","coming of age","sisters","refugees"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('открытое-море-том-4-237', 'DP-0237', 'Открытое море. Том 4', 'The Open Sea', 'Otvoreno more', 'Анника Тор', 'Annika Thor', 'Anika Tor', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Что скрывается на "Глубине моря"? Что страшнее, неизвестность или страшная весть, пришедшая далеко из-за моря? Штеффи - уже далеко не ребёнок, она стремится к исполнению мечты и обретению профессии, сталкивается с несправедливостью и сложной ситуацией в жизни подруги, а Нелли - всё больше отдаляется. Война закончилась, и вот - спустя шесть долгих лет, есть надежда, чтобы вся семья, наконец, воссоединилась.', 'What lies beneath the deep sea? What is more terrifying: the unknown or grim news arriving from far across the ocean? Steffi is no longer a child; she strives to fulfill her dreams and gain an education, confronts injustice, and supports a friend in distress, while Nelli drifts further away. The war has ended, and after six long years, a fragile hope emerges that the family might finally reunite.', 'Šta se krije u dubinama mora? Šta je strašnije – neizvjesnost ili strašne vijesti koje stižu iz daleka preko okeana? Štefi više nije dijete: teži ostvarenju snova i sticanju profesije, suočava se sa nepravdom, dok se Neli sve više udaljava. Rat je završen i nakon šest dugih godina javlja se nada da će se porodica konačno ponovo okupiti.', 'Трогательный и пронзительный финал тетралогии Анники Тор, где взросление и надежда оказываются сильнее любых жизненных бурь.', 'A poignant and deeply moving conclusion to Annika Thor''s tetralogy, reminding us that growing up and clinging to hope can weather any storm.', 'Dirljiv i snažan završetak tetralogije Anike Tor koji pokazuje da su odrastanje i nada jači od svake životne oluje.', '/covers/DP-0237.webp', '#23496d', 'teens', 'ru', 'available', '', '["real","friends"]', '["growing up","historical fiction","sisterhood","post-war","hope"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('соня-из-7-буээ--238', 'DP-0238', 'Соня из 7„Буээ“', 'Sonya from 7 "Bleh"', 'Sonja iz 7. „Bljak“', 'Алексей Олейников, Тим Яржомбек', 'Alexey Oleynikov, Tim Yarzhombek', 'Aleksej Olejnikov, Tim Jaržombek', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Это история о девочке Соне. Здесь драма и комедия в одном флаконе. Здесь есть слезы и есть смех. Эта история касается всех. Это история о травле? Об абсурде школы? О жестокости детей или о красоте жизни? О давлении коллектива или о том, как в сопротивлении ему рождается свобода? Обо всем этом и еще о многом другом. Это история о Соне.', 'This is the story of a girl named Sonya. Drama and comedy rolled into one, filled with tears and laughter alike. A story that resonates with everyone. Is it about bullying? The absurdity of middle school? The cruelty of teenagers or the unexpected beauty of life? The pressure of fitting in or discovering your own freedom by standing out? All of this and so much more. This is Sonya''s story.', 'Ovo je priča o djevojčici Sonji. Drama i komedija u jednom, puna i suza i smijeha. Priča koja se tiče svakoga od nas. Da li je ovo priča o vršnjačkom nasilju? O apsurdu škole? O okrutnosti tinejdžera ili o ljepoti života? O pritisku okoline ili o tome kako se kroz otpor rađa sloboda? O svemu tome i o još mnogo čemu. Ovo je Sonjina priča.', 'Искренний, пронзительный и остроумный рэп-комикс о выживании в седьмом классе, который поможет каждому подростку почувствовать себя не одиноким.', 'A witty, piercing, verse-powered graphic novel about surviving middle school that reminds every teen they are not alone.', 'Iskren, dirljiv i duhovit strip u stihovima o preživljavanju u sedmom razredu koji podsjeća svakog tinejdžera da nije sam.', '/covers/DP-0238.webp', '#e5a922', 'teens', 'ru', 'available', '', '["real","friends"]', '["graphic novel","school life","bullying","growing up","verse novel"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('соня-9-239', 'DP-0239', 'Соня-9', 'Sonya-9', 'Sonja-9', 'Алексей Олейников, Тим Яржомбек', 'Alexei Oleynikov, Tim Yarzhombek', 'Aleksej Olejnikov, Tim Jaržombek', '', 'Белая ворона', NULL, NULL, 11, 15, 'big', 'Это вторая книга поэта Алексея Олейникова и художника Тимофея Яржомбека про самую обычную девочку Соню и ее внутренний мир. В первой книге Соня ходит в 7 класс, сейчас же Соня повзрослела и перешла в 9 класс, а вместе с ней «повзрослели» и проблемы, которые ее волнуют.', 'This is the second graphic-poetry book by Alexei Oleynikov and artist Tim Yarzhombek about an ordinary girl named Sonya and her turbulent inner world. Sonya has grown up, moved up to 9th grade, and her worries, heartaches, and questions have grown right along with her.', 'Ovo je druga grafička zbirka stihova Alekseja Olejnikova i ilustratora Tima Jaržombeka o sasvim običnoj devojčici Sonji i njenom unutrašnjem svetu. Sonja je odrasla i krenula u 9. razred, a zajedno s njom odrasli su i problemi koji je muče.', 'Честный, пронзительный и остроумный комикс в стихах о том, каково это — быть девятиклассницей, когда весь мир вокруг штормит.', 'A raw, funny, and beautifully illustrated verse novel capturing the emotional rollercoaster of being a ninth-grader trying to find your place in the world.', 'Iskren, duhovit i dirljiv strip u stihovima o tome kako je zaista biti tinejdžerka u devetom razredu dok se ceo svet oko tebe menja.', '/covers/DP-0239.webp', '#e5b824', 'teens', 'ru', 'available', '', '["real","friends"]', '["graphic novel","verse novel","school life","growing up","teen angst"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('примитивные-сумчатые-240', 'DP-0240', 'Примитивные сумчатые', 'Primitive Marsupials', 'Primitivni torbari', 'Арне Свинген', 'Arne Svingen', 'Arne Svingen', '', 'Поляндрия', NULL, NULL, 11, 15, 'big', 'Взрослые уверены: подростки — сущий кошмар. Дик намерен довести это убеждение до абсурда и стать самым негативным человеком в мире! Осталось разобраться с родителями, вредными сёстрами, ненавистной школой, другом, которого угораздило влюбиться в учительницу, и... прекрасной Вильдой. А кто сказал, что негативным быть легко?', 'Adults are convinced that teenagers are an absolute nightmare. Dick decides to embrace the stereotype, push it to absurd extremes, and become the most negative human being on Earth! All that''s left is dealing with his parents, annoying sisters, dreaded school, a best friend hopelessly smitten with a teacher, and... the irresistible Vilde. Turns out, relentless negativity isn''t nearly as easy as it looks.', 'Odrasli su ubijeđeni da su tinejdžeri prava noćna mora. Dik je riješio da to uvjerenje dovede do apsurda i postane najnegativnija osoba na cijelom svijetu! Preostaje mu samo da izađe na kraj s roditeljima, dosadnim sestrama, omraženom školom, drugom koji se ludo zaljubio u nastavnicu i... predivnom Vildom. Jer ko je uopšte rekao da je lako biti negativac?', 'Остроумная хроника подросткового бунта, которая докажет: быть стопроцентным циником — адски сложная работа, особенно когда на горизонте маячит первая любовь.', 'A delightfully sarcastic take on teenage rebellion that proves being the world''s most negative person is exhausting work—especially when life and romance get in the way!', 'Urnebesan i iskren pogled na tinejdžerski bunt koji dokazuje da je biti apsolutni cinik đavolski težak posao, naročito kad se umiješa prva ljubav!', '/covers/DP-0240.webp', '#e2583e', 'teens', 'ru', 'available', '', '["funny","real","friends"]', '["teens","growing up","humor","school","first love"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сага-о-юном-с-льви-241', 'DP-0241', 'Сага о юном Сёльви', 'The Saga of Young Sölvi', 'Saga o mladom Selviju', '', 'Arnar Már Arngrímsson', 'Arnar Már Arngrímsson', '', 'Самокат', NULL, NULL, 11, 15, 'big', 'Сёльви пятнадцать, и он ненавидит всех: родителей, школу, одноклассников, учителей, самого себя. Но больше всего он ненавидит «стандарты», по которым живут люди вокруг: «лайки» — символ успеха/неуспеха, заученные из учебника ответы — гарантию учительской благосклонности, дом в модном районе Рейкьявика, обставленный по журналу дизайна, — штамп «жизнь удалась». И притворство. А любит — слова. И рэп. У него и тетрадка есть, в которой он рифмует, только о ней никто не знает. Чтобы перевоспитать отбившегося от рук сына, родители на лето отправляют его в деревню к «старой ведьме» — бабушке, лишив компьютера и телефона. Придется слушать отстойный отцовский винил, есть овсянку с кровяной колбасой, разгребать старый хлам, годами копившийся на хуторе, и гонять по горам баранов. И встретиться с новыми, непохожими ни на кого из знакомых людьми.Книга о штормах и бурях, бушующих в душе подростка, которому так не хватает рядом мудрого наставника, но от которого требуют «быть нормальным», «повзрослеть», «научиться быть ответственным»; который добивается признания, но боится быть отвергнутым. Роман, написанный с юмором и большим сочувствием ко всем подросткам,которые идут по полной трудностей дороге на встречу с самими собой.', 'Fifteen-year-old Sölvi hates everything: school, phony social media standards, and pretension. His only true passions are words and scribbling rap verses in a secret notebook. To teach him a lesson, his parents exile him for the summer to the Icelandic countryside to stay with his eccentric grandmother—stripped of his phone and internet. Surrounded by stubborn sheep, vintage vinyl records, and peculiar locals, Sölvi must navigate the turbulent waters of teen angst and finally find his authentic voice in this heartfelt, humorous coming-of-age novel.', 'Petnaestogodišnji Selvi prezire sve: školu, lažna mjerila uspjeha na mrežama i pretvaranje odraslih. Voli samo riječi i rep stihove koje krišom zapisuje u svoju svesku. Kako bi ga prevaspitali, roditelji ga preko ljeta šalju u zabačeno islandsko selo kod neobične bake — bez telefona i interneta. Okružen tvrdoglavim ovcama, očevim starim pločama i neobičnim mještanima, Selvi prolazi kroz buru tinejdžerskog buntoštva i otkriva ko je zapravo.', 'Честный, остроумный манифест взросления о том, как пережить тотальный цифровой детокс в исландской глуши и наконец услышать самого себя.', 'A sharp, witty coming-of-age story showing how a forced digital detox in the rugged Icelandic countryside can help you discover your own voice.', 'Iskrena i duhovita priča o odrastanju koja dokazuje da prisilni digitalni detoks na selu može pomoći da pronađete sopstveni glas.', '/covers/DP-0241.webp', '#3f5f6d', 'teens', 'ru', 'available', '16+', '["real","funny"]', '["teen rebellion","coming of age","rap","iceland","digital detox"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('синева-242', 'DP-0242', 'Синева', 'The End of the Ocean', 'Plavetnilo', 'Майя Лунде', 'Maja Lunde', 'Maja Lunde', '', '', NULL, NULL, 11, 15, 'big', 'Что будет, если из мира исчезнет всего одна вещь, настолько привычная, что мы не обращаем на нее внимания? В первом романе Майи Лунде «История пчел» пропали насекомые, а в «Синеве» апокалиптический мир будущего страдает без пресной воды. Вода исчезла не в одночасье: предыдущие поколения шаг за шагом приближали катастрофу, но бежать от засухи и пожаров приходится тем, кто только начинает жить. Есть ли у них шанс на спасение?', 'What happens when the world loses something so essential we barely notice it—fresh water? In this powerful climate-fiction story, a parched future forces a new generation to flee droughts and wildfires caused by those who came before them. As they search for safety, is hope still within reach?', 'Šta se dešava kada svijet ostane bez nečega što uzimamo zdravo za gotovo — pitke vode? U ovoj snažnoj ekološkoj distopiji, nova generacija mora da bježi od suša i požara koje su za sobom ostavili njihovi preci, boreći se za opstanak i tračak nade.', 'Захватывающая и тревожная антиутопия, после которой вы начнёте ценить каждую каплю воды из-под крана.', 'A gripping and thought-provoking cli-fi novel that will make you treasure every single drop of water.', 'Uzbudljiv i opominjući roman zbog kojeg ćete početi da cijenite svaku kap vode.', '/covers/DP-0242.webp', '#1b4965', 'teens', 'ru', 'available', '', '["adventure","real"]', '["climate fiction","dystopia","ecology","survival","nature"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебные-кроссовки-моего-друг-243', 'DP-0243', 'Волшебные кроссовки моего друга Перси', 'My Friend Percy''s Magical Gym Shoes', 'Magične patike mog druga Persija', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', '', 'Когда у осторожного и неуклюжего Ульфа появляется новый друг, жизнь переворачивается с ног на голову. Перси — полная противоположность Ульфа: он любит подраться, топчет чужие фуражки, и на переменах все обходят его стороной. Ульф страшно хочет быть похожим на Перси, он мечтает завладеть его волшебными кедами, которые, по словам Перси, наделяют своего обладателя силой и храбростью. И ему это удается! Но увы, все не так просто... Это юмористическая история о том, как «хороший мальчик» попадает в дурную компанию и становится отпетым хулиганом, она построена на реальных воспоминаниях знаменитого шведского писателя Ульфа Старка, автора множества книг и спектаклей для детей.', NULL, NULL, 11, 15, 'big', '', 'When cautious, clumsy young Ulf meets tough-talking troublemaker Percy, his world flips upside down. Desperate to be brave and cool, Ulf makes a deal to get Percy''s supposedly magical sneakers—shoes that promise ultimate courage and strength. But stepping into another boy''s shoes brings hilarious chaos and unexpected hard truths. A witty, heartfelt coming-of-age story inspired by the author''s own childhood.', 'Kada oprezni i nespretni Ulf upozna Persija, mangupa koga svi zaobilaze u širokom luku, njegov svijet se okreće naglavačke. Ulf žarko želi da bude hrabar poput svog novog druga, pa mijenja sve što ima za Persijeve navodno čudotvorne patike. Ali nositi tuđe patike i glumiti mangupa donosi više nevolja nego što je iko očekivao. Topla i urnebesno duhovita priča o odrastanju i pravom prijateljstvu.', 'Искрометная и трогательная повесть о том, что настоящая смелость прячется вовсе не в подошвах старых кед, а внутри нас самих!', 'A laugh-out-loud, tender Swedish classic proving that true bravery comes from the heart, not from a pair of worn-out sneakers!', 'Duhovita i dirljiva priča koja pokazuje da prava hrabrost ne leži u starim patikama, već u sopstvenom srcu!', '/covers/DP-0243.webp', '#c84b31', 'teens', 'ru', 'available', '550', '["funny","friends","real"]', '["friendship","school life","growing up","humor","swedish literature"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-месье-каротта-244', 'DP-0244', 'Тайна месье Каротта', 'The Mystery of Monsieur Carotte', 'Tajna gospodina Karota', 'Анна Красильщик', 'Anna Krasilshchik', 'Ana Krasiljščik', '', 'Это история второго расследования Марка, знакомого читателям по книге «Давай поедем в Уналашку». Почему взрослые из всех поездок привозят футболки и магниты? В чем пойти на папину свадьбу: в мантии Гриффиндора или в костюме C-3PO из «Звездных войн»? Чем пахнет физкультура? Марк Марковкин ищет ответы на эти и другие вопросы, а также помогает разгадать головоломку своему другу по переписке — французскому фотографу Жан-Пьеру Гарсиа, который поделился с Марком невероятной новостью. Один из его предков, Антуан Луи Каротт приехал в Россию в 1812 году вместе с наполеоновской армией и решил не возвращаться во Францию. В ходе расследования Марк узнает, что в этой истории переплелись предательство, печальная история любви и трагедия жизни человека, сломанного войной.', NULL, NULL, 11, 15, 'big', '', 'Mark Markovkin is back with a fresh investigation and plenty of teenage dilemmas—like whether to wear a Gryffindor robe or a C-3PO suit to his dad''s wedding. But a lighthearted quest turns profound when Mark''s French pen-pal reveals a family secret: an ancestor who marched into Russia with Napoleon''s army in 1812 and never returned. Diving into dusty archives and family lore, Mark unravels a poignant story of love, betrayal, and war.', 'Mark Markovkin se vraća sa novom istragom i gomilom tinejdžerskih dilema — poput one da li na očevo vjenčanje obući Grifindorsku odoru ili kostim C-3PO-a. Ipak, duhovita potraga postaje ozbiljna kada mu prijatelj iz Francuske povjeri tajnu o svom pretku, napoleonskom vojniku koji je 1812. ostao u Rusiji. Istražujući prošlost, Mark otkriva dirljivu priču o ljubavi, izdaji i ljudskoj sudbini koju je prelomio rat.', 'Остроумный детектив о взрослении, семейных тайнах и загадке наполеоновского солдата, которая перевернула всё с ног на голову!', 'A witty mystery about growing up, tricky family dilemmas, and a forgotten 1812 soldier whose secret turns history upside down!', 'Duhovita detektivska priča o odrastanju, porodičnim zavrzlamama i zagonetki napoleonskog vojnika koja mijenja sve!', '/covers/DP-0244.webp', '#3b6978', 'teens', 'ru', 'available', '750', '["funny","adventure","real"]', '["detective","history","growing up","family secrets","friendship"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('политика-о-чем-взрослые-тебе-н-245', 'DP-0245', 'Политика. О чем взрослые тебе не говорят', 'Politics: What Grown-Ups Never Tell You', 'Politika: O čemu ti odrasli ne govore', '', 'Boguś Janiszewski', 'Boguś Janiszewski', '', 'Сложно представить себе современного ребенка, который бы хоть раз не поинтересовался: кто такой президент? Что такое налоги? Почему в стране постоянно кого-то выбирают? И вообще зачем вся эта политика? Родителям порой трудно ответить на подобные вопросы кратко и емко. Политика – это одна из тех тем, про которые родители не разговаривают с детьми, потому что – как справедливо отмечает автор – часто и сами в ней не разбираются. Автор книги Богусь Янишевский – известный польский популяризатор науки – умеет простыми словами рассказывать детям про такие важные и непростые вещи. Его дуэт с иллюстратором Максом Скорвидером – великолепный образец современного подхода к обучению, в котором нет места сухим формулировкам, зато полно живых примеров и классного визуального материала. Книга отлично подойдет для семейного чтения, потому что может дать начало беседам на серьезные темы: о различных политических системах, о манипуляции, о функциях государства. Гражданское сознание формируется с детства, поэтому важно помнить, что дети однажды вырастут и получат возможность влиять на будущее нашей страны.', NULL, NULL, 11, 15, 'big', '', 'It’s hard to imagine a kid who hasn’t wondered at least once: what does a president actually do, what are taxes, and why do adults argue so much about elections? Polish science popularizer Boguś Janiszewski and illustrator Max Skorwider break down state systems, propaganda, voting, and civic responsibility with sharp humor, comics, and infographics. A remarkably engaging guide that turns intimidating adult topics into an empowering read for future changemakers.', 'Teško je zamisliti mladu osobu koja se bar jednom nije zapitala: ko je zapravo predsjednik, čemu služe porezi i zašto se odrasli stalno prepiru oko izbora? Poznati poljski autor Boguš Janiševski i ilustrator Maks Skorvider na duhovit, jasan i vizuelno privlačan način razlažu političke sisteme, medijske manipulacije i ulogu građana. Ova knjiga pretvara naizgled suve teme u uzbudljivu priču o tome kako društvo zaista funkcioniše.', 'Наконец-то внятный и очень остроумный гид по взрослому миру, после которого спорить о новостях за ужином станет в разы интереснее!', 'Finally, a sharp and wonderfully funny guide to power, taxes, and elections that makes politics fascinating rather than boring!', 'Konačno duhovit i kristalno jasan vodič kroz svijet politike koji će razjasniti sve ono o čemu odrasli često ćute!', '/covers/DP-0245.webp', '#1d5d9b', 'teens', 'ru', 'available', '1000', '["real","funny"]', '["non-fiction","politics","society","infographics","citizenship","teen-guide"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('правда-о-салли-джонс-246', 'DP-0246', 'Правда о Салли Джонс', 'The Murderer''s Ape', 'Istina o Sali Džons', 'Якоб Вегелиус', 'Jakob Wegelius', 'Jakob Vegelijus', '?', 'Капитан Старшой и горилла Салли Джонс путешествуют на борту корабля «Хадсон Квин» и зарабатывают перевозкой грузов. Салли Джонс работает механиком, отлично разбираясь в устройстве корабля. Она понимает человеческую речь и даже овладела навыком письма, но говорить не умеет. Контрабандисты обвиняют Старшого в убийстве, и тот попадает в тюрьму. Салли Джонс верит в невиновность капитана и должна доказать это. Так начинается долгий и тернистый, временами мучительный, а порой и забавный путь, цель которого — спасти Старшого. Эта приключенческая история о верной дружбе, надежде, предательстве и прощении получила множество литературных наград, в том числе Августовскую премию и самую престижную немецкую Jugendliteraturpreis. Об авторе: Якоб Вегелиус — шведский писатель и художник. Его необычная художественная манера привлекает как детей, так и взрослых. Лауреат премии Августа Стриндберга и почетного знака Нильса Хольгерссона.', NULL, NULL, 11, 15, 'big', '', 'Sally Jones is not just any gorilla: she is a master ship mechanic who can read and write, though she cannot speak. When her loyal friend, Chief Koskela, is framed for murder and thrown into prison, Sally sets off on a sprawling globe-trotting odyssey—from the foggy docks of Lisbon to the majestic palaces of India—determined to uncover the truth and clear his name.', 'Sali Džons nije obična gorila: ona je vrhunski brodski mehaničar, razumije ljudski govor i piše na pisaćoj mašini. Kada njenog najboljeg prijatelja, kapetana Šefa, nepravedno optuže za ubistvo i bace u tamnicu, Sali kreće na opasno i dirljivo putovanje oko svijeta kako bi otkrila istinu i spasila čovjeka koga voli kao oca.', 'Захватывающий винтажный детектив о горилле-механике, чья преданность и благородство способны переплыть все океаны и спасти невиновного друга.', 'A breathtaking maritime mystery starring an unforgettable gorilla engineer on an epic quest across the globe to clear her captain''s name.', 'Uzbudljivi pomorski roman o gorili-mehaničarki čija nepokolebljiva odanost može preploviti sve okeane svijeta da spasi nevinog prijatelja.', '/covers/DP-0246.webp', '#1b3a4b', 'teens', 'ru', 'available', '', '["adventure","friends","animals"]', '["gorilla","sea voyage","detective","friendship","historical fiction"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('новые-странствия-салли-джонс-247', 'DP-0247', 'Новые странствия Салли Джонс', 'The False Rose', 'Nova putovanja Sali Džons', 'Якоб Вегелиус', 'Jakob Wegelius', 'Jakob Vegelijus', '', 'Что скрывает старый моряк, владелец плешивого и слепого петуха? Он что-то знает о Салли Джонс? Или ему что-то от нее нужно? Раскрыв тайну, можно оказаться на пороге куда большей и сложной, а еще — в начале нового путешествия. Книги Якоба Вегелиуса — истории странствий, напастей и счастливых избавлений. Несмотря на эффектное смешение жанров, главная находка здесь — героиня. Горилла, мыслящая н хуже человека, умеющая писать, но не способная говорить, ее жизнь — огромное, почти бесконечное приключение, переходящее из книги в книгу.', NULL, NULL, 11, 15, 'big', '', 'When Sally Jones and the Chief discover a curious necklace hidden aboard their beloved boat, the Hudson Queen, it pulls them straight into a dangerous web of secrets. To unravel the mystery of the ''False Rose'', the extraordinary gorilla engineer must brave the fog-drenched underworld of 1920s Glasgow, ruthless smuggling gangs, and echoes from her own shadowy past.', 'Kada Sali Džons i Šef pronađu zagonetnu ogrlicu skrivenu na svom parobrodu, započinje nova, opasna pomorska avantura. Kako bi razotkrila tajnu „Lažne ruže“, ova nevjerovatna gorila i brodski mehaničar moraće da se suoči sa nemilosrdnim krijumčarima, mračnim podzemljem Glazgova i tajnama iz sopstvene prošlosti.', 'Невероятная горилла-механик снова в деле: приготовьтесь к туманным докам Глазго, старинным тайнам и дружбе, способной выдержать любые шторма!', 'The world’s most capable gorilla engineer is back for another globe-trotting adventure full of maritime mysteries, gritty underworlds, and steadfast friendship.', 'Najpametnija gorila na svijetu ponovo plovi: pripremite se za mračne dokove Glazgova, stare tajne i prijateljstvo jače od svakog nevremena!', '/covers/DP-0247.webp', '#35526b', 'teens', 'ru', 'available', '750', '["adventure","animals","friends"]', '["gorilla","sea voyage","mystery","detective","ship"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-всех-вещей-248', 'DP-0248', 'Книга всех вещей', 'The Book of Everything', 'Knjiga svih stvari', 'Гюс Кёйер', 'Guus Kuijer', 'Gis Kojer', '', 'Девятилетний Томас часто видит то, чего не видят другие: тропических рыбок в городских каналах; необыкновенную красоту Элизы, девушки с кожаной ногой; доброту старушки соседки, которую все считают ведьмой. И Иисуса, который частенько приходит к Томасу поболтать. Но кроме этого, он видит, как отец бьет мать, и даже Иисус здесь бессилен. И только благодаря друзьям Томас однажды понимает: чтобы стать счастливым, нужно просто перестать бояться. В 2012 году Гюс Кёйер получил одну из главных наград в детской литературе ― премию имени Астрид Линдгрен за пронзительный реализм, лукавый юмор и провидческую фантазию. Всё это соединилось в самой известной работе автора ― «Книге всех вещей», в которой Кёйер умело вписывает магию в повседневность, говорит просто и честно о несчастливом детстве и жестокости в семье. При этом не забывая о самом главном: любви, поддержке близких людей и вере в себя. Все это дает героям силы бороться, даже когда Бог молчит на всех языках. В «Самокате» эта повесть впервые вышла в 2013 году. Тогда о домашнем насилии в России говорили ещё очень мало, и книга на эту тему произвела на читателей сильнейшее впечатление. А цитата из «Книги всех вещей» ― «Чтобы стать счастливым, надо просто перестать бояться» ― навсегда стала одним из девизов издательства.', NULL, NULL, 11, 15, 'big', '', 'Nine-year-old Thomas sees things no one else does: tropical fish swimming in Amsterdam''s canals, beauty in a girl with a leather leg, and even Jesus dropping by for friendly chats. But Thomas also witnesses his father''s violent anger at home, something even his visions cannot heal. Guided by an eccentric neighbor whom everyone mistakes for a witch, Thomas begins writing his own book of life, discovering that overcoming fear is the very first step toward happiness. A luminous, tender, and courageous masterpiece.', 'Devetogodišnji Tomas vidi ono što drugi ne primjećuju: tropske ribice u kanalima Amsterdama, ljepotu djevojke sa kožnom protezom i Isusa koji navraća na čašicu razgovora. Ipak, on vidi i surovu stvarnost očevog nasilja u porodici. Uz podršku neobične komšinice koju svi smatraju vješticom i svojih prijatelja, Tomas shvata da put ka sreći počinje onog trenutka kada pobijedimo sopstveni strah. Izuzetno dirljiva, topla i duboko humana priča o odrastanju.', 'Пронзительная, честная и светлая повесть о том, что настоящее счастье начинается там, где заканчивается страх.', 'A brave, luminous, and deeply moving story reminding us that true happiness begins the moment we dare to stop being afraid.', 'Hrabra, topla i dirljiva priča koja nas podsjeća da prava sreća počinje onog trenutka kada prestanemo da se plašimo.', '/covers/DP-0248.webp', '#c85a32', 'teens', 'ru', 'available', '850', '["real","magic","friends"]', '["courage","growing up","family","imagination","classic"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('убежище-249', 'DP-0249', 'Убежище', 'The Diary of a Young Girl: The Secret Annex', 'Dnevnik Ane Frank', 'Анна Франк', 'Anne Frank', 'Ana Frank', '', '', NULL, NULL, 11, 15, 'big', '', 'Hiding from Nazi persecution in a secret annex in Amsterdam, thirteen-year-old Anne Frank confided her deepest thoughts, teenage dreams, and daily life to her diary, Kitty. Her luminous, poignant words remain one of the most powerful and enduring testimonies of youth, courage, and humanity.', 'Skrivajući se od nacističkog progona u tajnom skrovištu u Amsterdamu, trinaestogodišnja Ana Frank povjerava svoje snove, strahove i svakodnevicu svom dnevniku Kiti. Njene tople i iskrene riječi ostaju jedno od najsnažnijih svjedočanstava o odrastanju, nadi i nepokolebljivoj ljudskosti.', 'Пронзительный, честный и удивительно светлый голос девочки, которая даже в самые тёмные времена продолжала верить в доброту людей.', 'A poignant, deeply honest, and luminous voice of a young girl who, even in the darkest times, never stopped believing that people are truly good at heart.', 'Dirljiv, iskren i nevjerovatno topao glas djevojčice koja je čak i u najmračnijim vremenima vjerovala u dobrotu ljudi.', NULL, '#7a3b37', 'teens', 'ru', 'available', '', '["real"]', '["diary","history","world war ii","growing up","classic"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('доктор-сон-250', 'DP-0250', 'Доктор Сон', 'Doctor Sleep', 'Doktor San', 'Стивен Кинг', 'Stephen King', 'Stiven King', '', 'АСТ', 2021, '978-5-17-134431-3', 11, 15, 'big', '', 'Years after surviving the horrors of the Overlook Hotel, adult Dan Torrance discovers a psychic kinship with Abra Stone, a brave teenager with the brightest ''shine'' he has ever encountered. When a predatory cult targeting gifted youth tracks Abra down, Dan must confront the ghosts of his past to help her fight back.', 'Godinama nakon strašnih događaja u hotelu Vidikovac, odrasli Den Torans upoznaje Abru Stoun, hrabru djevojčicu s nevjerovatnim darom ''isijavanja''. Kada mračni kult krene u lov na djecu s natprirodnim moćima, Den mora prevazići sopstvene traume iz prošlosti kako bi spasio Abru.', 'Запаситесь пледом и не выключайте ночник: Дэнни Торранс вырос, но монстры никуда не делись, и только сила духа способна победить вековую тьму!', 'Keep the bedside lamp on: Danny Torrance is all grown up, but the shadows are hungrier than ever in this thrilling battle between darkness and extraordinary light!', 'Ušuškajte se i upalite lampu: Deni Torans je odrastao, ali čudovišta i dalje vrebaju, a ova natprirodna bitka držaće vas budnima do kasno u noć!', '/covers/DP-0250.webp', '#2c1b3d', 'teens', 'ru', 'available', '', '["spooky","magic","adventure"]', '["supernatural","thriller","courage","telepathy","sequel"]', 1792836322695, 1792845618036);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('замок-на-третьей-горе-король-у-251', 'DP-0251', 'Замок на третьей горе. Король, у которого было сердце', 'The Castle on the Third Mountain: The King Who Had a Heart', 'Zamak na trećoj planini: Kralj koji je imao srce', 'Мэри Соммер', 'Mary Sommer', 'Meri Somer', '', 'АСТ (Mainstream)', 2023, '978-5-17-160300-7', 11, 15, 'big', '', 'In a kingdom veiled by cold secrets and ancient curses, legends speak of a castle atop the third mountain and a ruler bound by a mysterious fate. A mesmerizing dark fairy tale exploring sacrifice, loyalty, and the resilient warmth of love against chilling royal intrigue.', 'U kraljevstvu obavijenom hladnim tajnama i drevnim kletvama, legende govore o zamku na trećoj planini i vladaru zagonetne sudbine. Očaravajuća mračna bajka za mlade o hrabrosti, žrtvi i toplini iskrenih osjećanja nasuprot ledenim dvorskim spletkama.', 'Мрачная и завораживающая сказка для тех, кто ищет живое, бьющееся сердце среди ледяных замков и коварных тайн!', 'A spellbinding, gothic-tinged fairy tale for anyone looking for a beating heart amidst frozen walls and shadowy secrets!', 'Zanosna i zagonetna bajka za sve koji traže toplo srce skriveno među ledenim zidinama i dvorskim tajnama!', '/covers/DP-0251.webp', '#2c3e50', 'teens', 'ru', 'available', '', '["magic","adventure","spooky"]', '["dark fantasy","castles","royalty","curses","secrets"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('замок-на-третьей-горе-убийцы-и-252', 'DP-0252', 'Замок на третьей горе. Убийцы и те, кого так называют', 'The Castle on the Third Mountain: Assassins and Those Called So', 'Zamak na trećoj gori: Ubice i oni koje tako zovu', 'Мэри Соммер', 'Mary Sommer', 'Meri Somer', '', '', NULL, NULL, 11, 15, 'big', '', 'High in the mist-shrouded peaks sits a castle harboring dark secrets, dangerous skills, and people branded by rumors. When lines between hunter and prey blur, teenagers must unravel the truth behind chilling reputations and figure out who the real monster is.', 'Visoko u maglovitim planinama uzdiže se zamak koji krije opasne tajne, smrtonosne vještine i ljude obilježene zlim glasinama. Kada se granica između lovca i plijena izbriše, tinejdžeri moraju otkriti pravu istinu i saznati ko je ovdje stvarna prijetnja.', 'Захватывающее подростковое фэнтези о том, что самые пугающие слухи редко говорят чистую правду.', 'A gripping teen fantasy mystery proving that the scariest rumors rarely tell the whole story.', 'Uzbudljiva tinejdžerska misterija koja dokazuje da najstrašnije glasine rijetko govore cijelu istinu.', NULL, '#39324a', 'teens', 'ru', 'available', '', '["spooky","adventure","magic"]', '["teen fantasy","mysteries","castle","secrets","danger"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('замок-на-третьей-горе-последня-253', 'DP-0253', 'Замок на третьей горе. Последняя принцесса белых песков', 'Castle on the Third Mountain: The Last Princess of the White Sands', 'Zamak na trećoj gori: Posljednja princeza bijelog pijeska', 'Мэри Соммер', 'Mary Sommer', 'Meri Somer', '', 'АСТ (Mainstream)', 2024, '978-5-17-160304-5', 11, 15, 'big', '', 'Perched atop a treacherous peak, the castle on the third mountain holds the dark secrets of a divided realm. As ancient powers awaken across the endless white sands, a young princess must navigate palace intrigue, hidden magic, and dangerous alliances to reclaim her destiny. A sweeping and atmospheric fantasy tale of courage, mystery, and forbidden truths.', 'Smješten na vrhu opasne planine, zamak na trećoj gori krije mračne tajne podijeljenog kraljevstva. Dok se drevne sile bude preko beskrajnog bijelog pijeska, mlada princeza mora se suočiti s dvorskim intrigama, skrivenom magijom i opasnim savezima kako bi povratila svoju sudbinu. Raskošna omladinska fantazija puna hrabrosti, tajni i čarolije.', 'Захватывающее фэнтези о дворцовых тайнах, ветрах судьбы и принцессе, которая точно не станет сидеть сложа руки!', 'A gripping YA fantasy filled with royal secrets, desert winds, and a princess determined to forge her own destiny!', 'Uzbudljiva omladinska fantazija puna dvorskih tajni, pustinjskih vjetrova i princeze koja uzima sudbinu u svoje ruke!', '/covers/DP-0253.webp', '#c29547', 'teens', 'ru', 'available', '', '["magic","adventure"]', '["ya fantasy","castles","princesses","mystery","destiny"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сербский-за-30-дней-254', 'DP-0254', 'Сербский за 30 дней', 'Serbian in 30 Days', 'Srpski za 30 dana', 'М. Николич', 'M. Nikolić', 'M. Nikolić', '', '', NULL, NULL, 16, 99, 'adult', '"Сербский за 30 дней" - это отличный помощник для тех, кто хочет выучить сербский быстро и эффективно. Самоучитель состоит из трех частей: краткий курс грамматики, разговорник, сербско-русский и русско-сербский словари. Структура самоучителя построена таким образом, чтобы сначала освоить и научиться применять основные правила языка, а переходя ко второй части, закрепить изученный материал на практике. Словарь поможет с легкостью выполнять перевод при изучении материала, а также расширить словарный запас.\r Самоучитель будет полезен всем, кто интересуется сербским языком и начинает его изучать. Материал ориентирован на уровень А1, А2.', '"Serbian in 30 Days" is a practical self-study guide designed for anyone who wants to learn Serbian quickly and effectively. The book consists of three practical sections: a concise grammar overview, a phrasebook for daily situations, and a two-way vocabulary dictionary. Tailored specifically for beginner levels (A1–A2), it smoothly guides learners from core rules to immediate everyday practice.', '„Srpski za 30 dana“ je praktičan priručnik namijenjen svima koji žele brzo i efikasno savladati osnove jezika. Knjiga obuhvata sažet pregled gramatike, tematski priručnik za razgovor i rječnik. Koncipirana tako da vodi od osnovnih gramatičkih pravila do neposredne primjene u svakodnevnom životu, savršen je izbor za početnike na nivoima A1 i A2.', 'Идеальный экспресс-помощник для жизни в Черногории, чтобы уверенно заказать кафу и поболтать с соседями уже через месяц!', 'Your ultimate 30-day fast track to ordering coffee and chatting warmly with your neighbors in Montenegro!', 'Savršen priručnik za brzo savladavanje osnova i opušteno ćaskanje uz kafu u komšiluku već za mjesec dana!', '/covers/DP-0254.webp', '#b83227', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["serbian language","language learning","self-study","phrasebook","dictionary"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайм-код-255', 'DP-0255', 'Тайм-код', 'Time Code', 'Vremenski kod', 'Елена Макарова', 'Elena Makarova', 'Elena Makarova', '', 'Самокат', NULL, NULL, 16, 99, 'adult', 'Елена Макарова - прозаик, педагог и арт-терапевт - автор книг "Движение образует форму" и трилогии "Как вылепить отфыркивание", посвященных самовыражению детей и взрослых в творчестве. В новой книге она продолжает делиться размышлениями о том, что же нас вдохновляет и почему всем нам время от времени так нужно почувствовать себя творцами. А еще - о связи времен и взаимосвязанности событий, о разном их восприятии детьми и взрослыми. Случаи из жизни, исследования, письма, рисунки, встречи, прочитанные книги, разговоры - все становится инструментом познания и самопознания. Автор уверен: в каждом человеке есть творческое начало, надо лишь суметь его раскрыть. И в этом могут помочь книги и семинары Елены Макаровой.', 'Writer, teacher, and renowned art therapist Elena Makarova explores the roots of creative expression in both children and adults. In this deeply personal and reflective book, she dives into what truly inspires us, the intertwining threads of time and memory, and how differently events are perceived across generations. Through real-life episodes, sketches, letters, and dialogues, Makarova reminds us that everyone is an artist at heart—we just need a gentle push to let it bloom.', 'Književnica, pedagogica i art-terapeutkinja Elena Makarova istražuje izvore kreativnog izražavanja kod djece i odraslih. U ovoj duboko ličnoj i mudroj knjizi, ona promišlja o tome šta nas zapravo inspiriše, o preplitanju vremena i sjećanja, te o tome kako djeca i odrasli različito doživljavaju svijet. Kroz stvarne životne priče, crteže, pisma i susrete, autorka nas podsjeća da u svakom čovjeku leži stvaralačka iskra koju samo treba znati probuditi.', 'Мудрое и тёплое напоминание для уставших взрослых о том, что в каждом из нас до сих пор живёт озорной творец.', 'A deeply comforting and inspiring read for grown-ups longing to revive their creative spark and reconnect with their inner artist.', 'Mudra i topla knjiga koja podsjeća odrasle da u svakom od nas i dalje živi radoznali stvaralac.', '/covers/DP-0255.webp', '#c85a48', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["art therapy","creativity","psychology","self-discovery","inspiration"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайная-опора-256', 'DP-0256', 'Тайная опора', 'The Secret Support', 'Tajni oslonac', 'Людмила Петрановская', 'Lyudmila Petranovskaya', 'Ljudmila Petranovska', '', 'АСТ', NULL, NULL, 16, 99, 'adult', '"Все мы родом из детства", - писал один известный французский писатель и летчик. Однако прежде чем достичь самостоятельности, мы едва ли можем обойтись без взрослых. В своей новой книге Людмила Петрановская, основываясь на научной теории привязанности, легко и доступно рассказывает о роли родителей на пути к взрослению: "Как зависимость и беспомощность превращаются в зрелость, как наши любовь и забота год за годом формируют в ребенке тайную опору, на которой, как на стержне, держится его личность?" Прочитав эту книгу, вы не только сможете увидеть, что на самом деле стоит за детскими "капризами", "избалованностью", "агрессией", "вредным характером", но и понять, чем помочь своему ребенку, чтобы он рос и развивался не тратя силы на борьбу за вашу любовь.', 'Drawing on scientific attachment theory, renowned psychologist Lyudmila Petranovskaya gently illuminates the essential role parents play on a child''s journey to adulthood. Step by step, she explains how love, safety, and care form an invisible inner pillar within a growing child—turning helplessness into resilience and maturity. This book will help you look past tantrums, defiance, and whims to understand your child''s true needs and build a deep, lifelong bond.', 'Zasnovana na naučnoj teoriji privrženosti, ova knjiga poznate psihološkinje Ljudmile Petranovske na topao i pristupačan način otkriva ključnu ulogu roditelja u odrastanju djeteta. Korak po korak, ona objašnjava kako ljubav, sigurnost i prihvatanje stvaraju unutrašnji oslonac na kojem počiva stabilna ličnost. Knjiga pomaže roditeljima da razumiju prave uzroke dječijeg otpora i hirova, te stvore odnos pun povjerenja bez nepotrebnog stresa.', 'Тёплый и мудрый путеводитель по миру детских чувств, который снимает родительскую тревогу и возвращает в семью спокойствие.', 'A deeply reassuring, compassionate guide to attachment theory that frees parents from guilt and helps nurture genuine resilience in kids.', 'Topao i mudar vodič kroz dječiji svijet koji roditeljima donosi olakšanje i pomaže da izgrade neraskidivo povjerenje.', '/covers/DP-0256.webp', '#4a7c8b', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["parenting","psychology","attachment","family","growing up"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('если-с-ребенком-трудно-257', 'DP-0257', 'Если с ребенком трудно', 'When Parenting Gets Tough: If It''s Hard with Your Child', 'Kad je s djetetom teško', 'Людмила Петрановская', 'Lyudmila Petranovskaya', 'Ljudmila Petranovska', '', 'АСТ', NULL, NULL, 16, 99, 'adult', 'Дети не слушают своих родителей, сколько стоит этот мир. В попытках научить "нерадивое чадо", как "надо себя вести", ответственные родители вооружаются новейшими психологическими "приемчиками", разучивают современные техники сидения на гречке, а дети в ответ лишь становятся все более раздражительными и непослушными. Что же нам мешает в отношениях с ребенком, а ему мешает вести себя лучше? Новая книга Людмилы Петрановской будет полезна родителям, отчаявшимся найти общий язык с детьми. Вы сможете научиться ориентироваться в сложных ситуациях, решать конфликты и достойно выходить из них. Книга поможет сохранить терпение, восстановить понимание и мир в семье.', 'Children have tested their parents'' patience since the dawn of time. Desperate to instill good behavior, conscientious parents often resort to modern psychological ''tricks'' or rigid tactics, only to find children growing even more irritable and defiant. What is really getting in the way of our connection with our children, and what prevents them from behaving better? Renowned family psychologist Lyudmila Petranovskaya offers practical, empathetic guidance for parents struggling to find common ground. This essential guide helps navigate challenging situations, resolve conflicts gracefully, and restore warmth, patience, and peace at home.', 'Djeca ne slušaju roditelje otkako je svijeta i vijeka. U pokušajima da nauče dijete lijepom ponašanju, savjesni roditelji se naoružavaju najnovijim psihološkim ''trikovima'', dok djeca zauzvrat postaju samo razdražljivija i neposlušnija. Šta zapravo ometa naš odnos s djetetom i šta njega spriječava da sarađuje? Knjiga priznate psihološkinje Ljudmile Petranovske biće od neprocjenjive pomoći roditeljima koji žele da prevaziđu sukobe, sačuvaju strpljenje i ponovo izgrade međusobno razumijevanje i mir u porodici.', 'Скорая родительская помощь и тёплое напоминание о том, что за любым капризом и протестом стоит потребность в любви и безопасности.', 'An essential first-aid kit for exhausted parents, gently reminding us that behind every difficult tantrum lies a deep longing for love and safety.', 'Prava prva pomoć za iscrpljene roditelje i topao podsjetnik da se iza svakog dječjeg prkosa krije potreba za ljubavlju i sigurnošću.', '/covers/DP-0257.webp', '#e07a5f', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["parenting","psychology","family","relationships","empathy"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('правила-жизни-258', 'DP-0258', 'Правила жизни', 'Rules for Living', 'Pravila života', 'Януш Корчак', 'Janusz Korczak', 'Januš Korčak', '', 'Детство отрочество юность', NULL, NULL, 16, 99, 'adult', 'Публицистические размышления выдающегося польского педагога, врача и писателя Януша Корчака, вместе со своими воспитанниками погибшими в газовой камере в годы фашистской оккупации в Польше, о принципах, которыми дети и юношество должны руководствоваться в своих жизненных поступках.', 'Deeply compassionate reflections by the outstanding Polish educator, physician, and writer Janusz Korczak, who perished alongside his orphan pupils during the Nazi occupation, exploring the ethical principles and heartfelt choices that guide children and young people through life.', 'Dirljiva razmišljanja izuzetnog poljskog pedagoga, ljekara i pisca Januša Korčaka, koji je stradao zajedno sa svojim štićenicima tokom nacističke okupacije, o moralnim principima i životnim odlukama kojima se mladi i odrasli trebaju voditi.', 'Мудрая, пронзительная и невероятно человечная книга о том, как взрослым и детям научиться по-настоящему понимать и уважать друг друга.', 'A profoundly wise and tender guide to understanding childhood, ethics, and mutual respect from one of history''s greatest educators.', 'Duboka, topla i dirljiva knjiga o tome kako da djeca i odrasli nauče da se istinski razumiju i međusobno poštuju.', '/covers/DP-0258.webp', '#3b5368', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["parenting","ethics","education","philosophy","classic"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-тыжемать-белка-в-колесе-259', 'DP-0259', '#тыжемать белка в колесе', '#YoureAMother: A Hamster in a Wheel', '#TiSiMajka: Vjeverica u točku', 'Надя Папудогло', 'Nadya Papudoglo', 'Nadja Papudoglo', '', 'КоспасГид', NULL, NULL, 16, 99, 'adult', 'Автор рассказывает нам, как сама искала баланс между работой и материнством и как сопротивлялась давлению с разных сторон, как училась не сравнивать себя и своего ребенка с другими и как осознавала свои материнские права. Она обращается к другим матерям с этими и прочими вопросами, и благодаря такому журналистскому подходу сборник "#тыжемать. Белка в колесе" превращается не просто в коллекцию персональных наблюдений, а в попытку исследовать современное материнство. Так подборка ироничных рассказов оказывается по-настоящему полезной книгой - как в практическом смысле, так и в психологическом.', 'In this witty yet deeply reassuring book, journalist Nadya Papudoglo explores the turbulent quest to balance career and motherhood without losing one''s sanity or identity. Through candid personal essays and interviews with fellow mothers, she deconstructs social pressure, maternal guilt, and the myth of perfection, offering a warm, validating, and profoundly practical guide to surviving modern parenting.', 'U ovoj duhovitoj i ohrabrujućoj knjizi, novinarka Nadja Papudoglo istražuje potragu za ravnotežom između karijere i majčinstva bez gubitka razuma i sopstvenog identiteta. Kroz iskrene lične priče i razgovore s drugim majkama, ona demistifikuje pritiske okoline, osjećaj krivice i mit o savršenstvu, pružajući toplu, iscjeljujuću i praktičnu podršku svakom roditelju.', 'Спасительный глоток юмора и сочувствия для каждой мамы, которая устала бежать бесконечный марафон за званием «идеального родителя».', 'A refreshing, laugh-out-loud dose of solidarity for every parent trapped on the relentless hamster wheel of trying to be perfect.', 'Spasonosna doza humora i podrške za svaku mamu koja je umorna od beskonačne trke za titulom „savršenog roditelja“.', '/covers/DP-0259.webp', '#e06b53', 'adults', 'ru', 'available', 'Категория: родителям', '["funny","real"]', '["parenting","motherhood","humor","psychology","essays"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('педагогика-для-всех-260', 'DP-0260', 'Педагогика для всех', 'Pedagogy for Everyone', 'Pedagogija za sve', 'Симон Соловейчик', 'Simon Soloveychik', 'Simon Solovejčik', '', 'Первое сентября', 2000, '5-8246-0042-2', 16, 99, 'adult', '', 'A legendary, profoundly humanistic book on upbringing that challenges strict formulas and dogmas. Simon Soloveychik speaks directly to the parent''s heart, exploring how to nurture inner freedom, conscience, and genuine mutual understanding with a growing child.', 'Legendarno, duboko humano djelo o vaspitanju koje prevazilazi stroge pedagoške šablone i pravila. Simon Solovejčik se obraća srcu roditelja, istražujući kako u djetetu razviti unutrašnju slobodu, savjest i iskreno uzajamno poštovanje.', 'Мудрая и невероятно тёплая книга, которая напоминает: воспитывать ребёнка — значит прежде всего любить его, слышать и уважать как личность.', 'A gentle, wise, and timeless book that reminds us parenting isn''t about control, but about unconditional love, trust, and shared soul-searching.', 'Mudra i nevjerovatno topla knjiga koja nas podsjeća da vaspitati dijete znači voljeti ga, čuti ga i poštovati kao cjelovitu ličnost.', '/covers/DP-0260.webp', '#385170', 'adults', 'ru', 'available', 'Категория: родителям', '["real","friends"]', '["parenting","pedagogy","family","psychology","education"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('школьные-страдания-261', 'DP-0261', 'Школьные страдания', 'School Blues', 'Školske muke', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Амфора', NULL, NULL, 16, 99, 'adult', 'В основу книги современного французского прозаика легли его личные переживания двоякого рода – опыт отстающего ученика и наблюдения "продвинутого" учителя. Это легкое, изящное, остроумное сочинение в 2007 г. было удостоено престижной французской литературной награды – премии Ренодо.', 'Drawing on his personal experience as both a hopeless dunce and later an inspiring teacher, Daniel Pennac delivers a tender, witty, and brilliantly insightful look at education, adolescence, and the transformative power of literature.', 'Zasnovana na ličnom iskustvu pisca — nekada beznadežnog đaka ponavljača, a kasnije omiljenog profesora književnosti — ova topla, duhovita i pronicljiva knjiga slavi snagu pedagogije i pruža nadu svakom ko se borio sa školom.', 'Утешительный и остроумный манифест для каждого бывшего «двоечника» и каждого родителя, отчаявшегося над школьными тетрадями.', 'A deeply comforting and witty manifesto for every former struggling student and every parent despairing over homework.', 'Utješna i duhovita knjiga za svakog bivšeg lošeg đaka i svakog roditelja koji gubi živce nad domaćim zadacima.', '/covers/DP-0261.webp', '#2d546e', 'adults', 'ru', 'available', 'Категория: родителям', '["funny","real"]', '["school","education","memoir","parenting","humor"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-дневник-262', 'DP-0262', 'Как дневник', 'Like a Diary', 'Kao dnevnik', 'Марина Аромштам', 'Marina Aromshtam', 'Marina Aromštam', '', 'КомпасГид', NULL, NULL, 16, 99, 'adult', 'Имя Марины Аромштам на обложке - залог правильного воспитания взрослых. Каждая ее книга - это ниточка, соединяющая мир ребенка и мир взрослого. Как говорить, как учить, как объяснить, как исправить и еще целый миллион как… Здесь нет готовых рецептов, здесь есть просто жизнь одного человека, для которого педагогика - это не пустой звук и не сухие учебники. Ее дети - самые обычные, они живут в соседних квартирах, соседних домах. Кто-то из неполной семьи, у кого-то, наоборот, все хорошо (но даже за это бывает стыдно), кто-то хвастается без меры, кто-то перебивает и лезет вперед, кто-то ворует кошелек у учителя и божится, что этого не делал, а кто-то пытается его уличить. В общем, самые обычные дети, которые вытащили счастливый билет, и им достался чуткий и понимающий наставник.', 'Marina Aromshtam''s name on a cover is a promise of thoughtful parenting and wise teaching. Each of her books bridges the divide between child and adult worlds. How do we talk, teach, explain, and mend things? There are no cookie-cutter recipes here—just the living, breathing experience of an educator for whom pedagogy is anything but dry theory. Her pupils are everyday kids living right next door: boasting, interrupting, struggling with broken homes, or navigating childhood guilt and peer conflicts. They are ordinary children who won the lottery by finding a truly perceptive, empathetic mentor.', 'Ime Marine Aromštam na koricama garantuje mudro razumijevanje odrastanja i vaspitanja. Svaka njena knjiga je nit koja povezuje svijet djeteta i svijet odraslog. Kako razgovarati, kako učiti, kako objasniti i ispraviti greške? Ovdje nema gotovih recepata, već se otkriva živo iskustvo učiteljice za koju pedagogija nije prazno slovo na papiru. Njeni đaci su sasvim obična djeca iz komšiluka — sa svim svojim vrlinama, nestašlucima i nesigurnostima — koja su imala sreću da dobiju pažljivog i saosjećajnog mentora.', 'Честный, пронзительный и невероятно поддерживающий дневник учительницы, который напомнит каждому взрослому, каково это — быть ребенком.', 'An honest, moving, and profoundly comforting diary of a teacher that gently reminds every adult what it truly feels like to be a child.', 'Iskren, dirljiv i topao dnevnik jedne učiteljice koji svakog odraslog nježno podsjeća na to kako je zaista biti dijete.', '/covers/DP-0262.webp', '#4a6b82', 'adults', 'ru', 'available', 'Категория: родителям', '["real","friends"]', '["pedagogy","school life","parenting","empathy","memoir"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('воспоминания-о-школе-263', 'DP-0263', 'Воспоминания о школе', 'School Memories', 'Uspomene na školu', 'Джованни Моска', 'Giovanni Mosca', 'Đovani Moska', '', 'КомпасГид', NULL, NULL, 16, 99, 'adult', 'В 1983 году весь Советский Союз смеялся над молодым итальянским учителем, которому достался класс настоящих дьяволят - в великолепном "Крокодиле" был напечатан рассказ Джованни Моска под названием "Сорок чертей и одна зеленая муха". В 1984 г. в "Ералаше" в эту самую муху стрелял молодой Геннадий Хазанов, а Евгений Моргунов, директор, распихивая по карманам револьверы, напутствовал молодого преподавателя словами: "В конце концов все мы смертны". И вот почти через 20 лет в России наконец выходит книга, из которой эта история выдернута. Книга-воспоминание, книга-исповедь.', 'A legendary autobiographical novel by Italian writer Giovanni Mosca about a greenhorn teacher confronted with a classroom of forty little devils. Full of irony, tender humanity, and brilliant situational comedy, this classic memoir reminds us of the true art of teaching and the wild, unforgettable spark of childhood.', 'Kultni autobiografski roman italijanskog pisca Đovanija Moske o mladom učitelju koji se suočava sa razredom od četrdeset malih đavolaka. Ispunjena toplim humorom, iskrenošću i dubokim razumijevanjem dječje duše, ova knjiga je dirljiva i beskrajno duhovita oda školskim danima i pedagoškom strpljenju.', 'Ироничный, трогательный и до слёз смешной гимн учительскому терпению, способный растопить сердце любого, кто хоть раз сидел за партой.', 'A warm, laugh-out-loud memoir proving that surviving a classroom of unruly rascals requires equal parts patience, humor, and sheer courage.', 'Topao i beskrajno duhovit podsjetnik da je za preživljavanje u razredu punom nestašnih đaka potrebno puno ljubavi, humora i prstohvat hrabrosti.', '/covers/DP-0263.webp', '#3d6352', 'adults', 'ru', 'available', 'Категория: родителям', '["funny","real"]', '["school","teachers","humor","memoir","nostalgia"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кузя-мишка-верочка-и-другие-ни-264', 'DP-0264', 'Кузя, Мишка, Верочка и другие ничейные дети', 'Kuzya, Mishka, Verochka, and Other Nobody''s Children', 'Kuzja, Miška, Veročka i druga ničija djeca', 'Татьяна Губина', 'Tatiana Gubina', 'Tatjana Gubina', '', 'КомпасГид', NULL, NULL, 16, 99, 'adult', 'У каждого человека, который, затаив дыхание, звонит в детский дом, своя история: кто-то, однажды проснувшись, понимает, что нестерпимо хочет помочь, что эти дети ни в чем не виноваты и имеют право на счастье, кто-то зреет годами и в день "икс" дрожащей рукой снимает телефонную трубку. Жизнь каждого из этих людей, будущих мам и пап, от этого первого звонка меняется моментально. Конечно сложно, конечно страшно, конечно не каждому этот экзамен удастся сдать. Книга Татьяны Губиной - откровение, исповедь сотрудника детского дома. Того, кто - по ту сторону реки - решает чужие судьбы, взвешивая все "против" и "за".', 'Everyone who calls an orphanage with bated breath carries their own story: some suddenly realize they can no longer stand aside, while others gather courage for years before picking up the phone with trembling hands. Tatiana Gubina''s book is an honest, heart-wrenching confession of an orphanage worker who stands on the other side of the desk, weighing every ''pro'' and ''con'' as life-altering decisions unfold.', 'Svako ko sa zebnjom pozove dom za nezbrinutu djecu ima svoju priču: neko se jednog jutra probudi sa spoznajom da želi pomoći, a neko godinama sazrijeva za taj korak. Knjiga Tatjane Gubine je iskrena i dirljiva ispovijest radnice doma za djecu koja stoji sa one druge strane rijeke i vaga sve „za“ i „protiv“ dok se odlučuje o sudbinama.', 'Пронзительная, честная и бесконечно человечная исповедь о детях, которые очень ждут маму и папу, и о взрослых, решившихся на это чудо.', 'A piercing, honest, and profoundly humane confession about children waiting for parents, and the adults brave enough to answer that call.', 'Dirljiva, iskrena i duboko ljudska ispovijest o djeci koja čekaju porodicu i odraslima koji se usude na to čudo.', '/covers/DP-0264.webp', '#486581', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["adoption","orphanage","parenting","compassion","family"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('читать-265', 'DP-0265', 'Читать', 'Read!', 'Čitati!', 'Марина Аромштам', 'Marina Aromshtam', 'Marina Aromštam', '', '', NULL, NULL, 16, 99, 'adult', 'Книга Марины Аромштам "Читать!" - это предложение поговорить о детском чтении. Какие книги и в каком возрасте необходимы детям? Зачем нужны книги на сложные темы: о страхе и смерти, о красивом и ужасном? Помогут ли книги ответить на больные вопросы: почему семьи такие разные? можно ли простить предательство? что такое любовь?.. Автор ведет разговор с мамами и папами, бабушками и дедушками, педагогами и детскими психологами о том, как сделать книгу для ребенка другом на всю жизнь', 'Marina Aromshtam''s ''Read!'' invites parents, grandparents, and educators into an honest conversation about children''s reading. What books do children truly need at different ages? Why are stories tackling difficult topics like fear, loss, and love so vital? Aromshtam shares warm and insightful advice on how to turn books into lifelong companions for young readers.', 'Knjiga Marine Aromštam ''Čitati!'' poziv je na iskren razgovor o dječijem čitanju. Koje knjige i u kom uzrastu su djeci zaista potrebne? Zašto su važne knjige koje govore o teškim temama poput straha, gubitka i ljubavi? Aromštam nudi tople i pronicljive savjete roditeljima i nastavnicima o tome kako knjigu pretvoriti u djetetovog prijatelja za cijeli život.', 'Мудрый и душевный компас для взрослых, которые мечтают влюбить своего ребёнка в чтение на всю жизнь.', 'A wise, heartwarming roadmap for any parent or teacher eager to turn reading into a lifelong romance for their kids.', 'Mudar i topao vodič za roditelje i nastavnike koji žele da njihovi mališani zavole čitanje za cijeli život.', '/covers/DP-0265.webp', '#9b382c', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["parenting","reading","child psychology","books about books","education"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('что-говорить-детям--266', 'DP-0266', 'Что говорить детям?', 'Just Tell Me What to Say', 'Šta reći djeci?', 'Бетси Броун Браун', 'Betsy Brown Braun', 'Betsi Braun Braun', '', 'Попурри', NULL, NULL, 16, 99, 'adult', 'Типичные формы поведения детей и их извечные каверзные вопросы ставят многих родителей в тупик. Это практическое руководство даст вам много полезных советов и подскажет оптимальные варианты, как выходить из самых разных сложных положений. Какой бы ни была ваша проблема или вопрос по воспитанию - Бетси Браун предлагает вам разумные советы, чтобы вы могли наиболее легко и безболезненно познакомить с нашим большим миром своего подрастающего малыша.', 'Tricky child behavior and endless challenging questions leave many parents scratching their heads. This practical parenting guide offers sensible scripts and thoughtful strategies to navigate everyday dilemmas, helping you guide your growing child through the big world with calm confidence.', 'Tipično ponašanje djece i njihova vječita škakljiva pitanja često zbunjuju roditelje. Ovaj praktični priručnik nudi obilje korisnih savjeta i gotovih odgovora za najrazličitije situacije, pomažući vam da bez muke i stresa vodite svoje dijete kroz svijet odrastanja.', 'Настоящий спасательный круг для родителей в моменты, когда ребенок задает тот самый вопрос, от которого перехватывает дыхание!', 'A true parenting lifesaver packed with ready-to-use scripts for those moments when your kid asks *that* question and your mind goes completely blank!', 'Pojas za spasavanje za svakog roditelja u trenucima kada dijete postavi *ono* pitanje pred kojim jednostavno zanijemite!', '/covers/DP-0266.webp', '#3b82a6', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["parenting","family","communication","child psychology","advice"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('домашняя-скорая-помощь-267', 'DP-0267', 'Домашняя скорая помощь', 'Home First Aid: Quick Help for Kids', 'Kućna prva pomoć: Brza pomoć za djecu', 'Янко фон Риббек', 'Janko von Ribbeck', 'Janko fon Ribek', '', 'Теревинф', NULL, NULL, 16, 99, 'adult', 'Автор, педиатр с большим опытом работы в службе скорой помощи, в краткой и наглядной форме рассказывает, как помочь ребенку в экстренной ситуации. Вы также узнаете, как грамотно справиться с высокой температурой, укусами насекомых, болью в ушах и многими другими проблемами с помощью мягких естественных методов. Здесь же вы найдете продуманные рекомендации по составу домашней аптечки. Книгу отличает простота, ясность изложения, четкая структура, проверенная система поиска. Полученные знания помогут не только сделать жизнь ваших детей более безопасной, но и позволят в трудную минуту прийти на помощь всем, кто в этом нуждается.', 'Written by an experienced pediatric emergency doctor, this practical, clear guide explains how to act swiftly and calmly in emergency situations involving children. From managing high fevers and insect bites to dealing with earaches using gentle methods, the book also provides practical tips on assembling a reliable home medicine cabinet. Simple, well-structured, and essential for every household.', 'Napisana od strane pedijatra s bogatim iskustvom u hitnoj pomoći, ova praktična i pregledna knjiga objašnjava kako brzo i staloženo pomoći djetetu u hitnim situacijama. Saznaćete kako pravilno postupiti kod visoke temperature, uboda insekata ili bolova u ušima uz pomoć blagih prirodnih metoda, kao i kako pametno opremiti kućnu apoteku. Jasna, strukturisana i dragocjena za svaku porodicu.', 'Настольная шпаргалка для каждого родителя, которая превращает панику в спокойную и чёткую уверенность.', 'The ultimate bedside guide for parents that instantly turns panic into calm, decisive confidence.', 'Neophodan vodič za svakog roditelja koji roditeljsku paniku pretvara u smirenu i sigurnu reakciju.', '/covers/DP-0267.webp', '#d9433b', 'adults', 'ru', 'available', 'Категория: родителям', '["real"]', '["first aid","parenting","health","safety","pediatrics"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('парадокс-любви-268', 'DP-0268', 'Парадокс любви', 'The Paradox of Love', 'Paradoks ljubavi', 'Паскаль Брюкнер', 'Pascal Bruckner', 'Pascal Bruckner', '', 'Лимбус пресс', NULL, NULL, 16, 99, 'adult', '"Парадокс любви" - новое эссе известного французского писателя Паскаля Брюкнера. Тема, которую затрагивает Брюкнер на этот раз, опираясь на опыт своего поколения, вряд ли может оставить кого-то равнодушным. Что изменилось, что осталось неизменным в любовной психологии современного человека? Сексуальная революция, декларации "свободной любви": как повлияли социокультурные сдвиги последней трети XX века на мир чувств, отношений и ценностей? Достижима ли свобода в любви? Продолжая традицию французской эссеистики, автор в своих размышлениях и серьезен, и ироничен, он блещет эрудицией, совершая экскурсы в историю и историю литературы, и вместе с тем живо и эмоционально беседует с читателем.', 'In ''The Paradox of Love,'' renowned French philosopher and essayist Pascal Bruckner explores the shifting landscape of romantic psychology. Reflecting on the aftermath of the sexual revolution and the pursuit of ''free love,'' Bruckner examines how the drive for absolute individual freedom has transformed modern intimacy. Continuing the rich tradition of French essay writing, he blends erudition, literary history, and playful irony in an engaging conversation about the enduring mysteries of human connection.', 'U ''Paradoksu ljubavi'', poznati francuski esejista i filozof Paskal Brukner istražuje promjene u psihologiji ljubavi i modernim vezama. Osvrćući se na nasljeđe seksualne revolucije i ideale ''slobodne ljubavi'', autor ispituje kako su društveni preokreti uticali na svijet osjećanja i međuljudskih odnosa. Nastavljajući bogatu tradiciju francuskog eseja, Brukner kombinuje duboku erudiciju i finu ironiju, vodeći otvoren i nadahnut razgovor sa čitaocem.', 'Остроумная и глубокая французская эссеистика для тех, кто пытается разгадать главную головоломку современных отношений.', 'A sharp, witty French essay for anyone trying to navigate the beautiful contradictions of modern romance.', 'Duhovit i pronicljiv francuski esej za sve koji žele da bolje razumiju zagonetke savremene ljubavi.', '/covers/DP-0268.webp', '#8b263e', 'adults', 'ru', 'available', 'Категория: взрослым: психология', '["real"]', '["philosophy","relationships","love","psychology","essays"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('психология-масс-и-анализ-челов-269', 'DP-0269', 'Психология масс и анализ человеческого "Я"', 'Group Psychology and the Analysis of the Ego', 'Psihologija mase i analiza ega', 'Зигмунд Фрейд', 'Sigmund Freud', 'Sigmund Frojd', '', 'АСТ', NULL, NULL, 16, 99, 'adult', 'Зигмунд Фрейд - знаменитый австрийский психолог и психиатр, основоположник психоанализа, ученый, чьи открытия обогатили многие области современных знаний. Его работы "Толкование сновидений", "Введение в психоанализ", "По ту сторону принципа наслаждения", "Тотем и табу", "Я и Оно" вызывают интерес не только у специалистов-психологов, но и у самого широкого круга читателей. В настоящем издании представлена работа "Психология масс и анализ человеческого "Я"" (1921), в которой положения психоанализа впервые использованы Фрейдом для объяснения социальных явлений. Фрейда интересует поведение толпы: откуда у масс потребность в вожде, почему вождь влияет на поведение толпы, в чем основа престижа? Вниманию читателей также предлагается работа Фрейда "Будущее одной иллюзии" (1927), рассматривающая социальный и культурный феномен религии.', 'Sigmund Freud, the father of psychoanalysis, investigates the mysteries of human social behavior in this groundbreaking collection. In ''Group Psychology and the Analysis of the Ego'' (1921), Freud explores why individuals surrender their autonomy to crowds, how leaders exert hypnotic influence, and what fuels our psychological ties to authority. Also included is ''The Future of an Illusion'' (1927), a piercing psychoanalytic examination of the social and cultural phenomenon of religion.', 'Sigmund Frojd, otac psihoanalize, istražuje tajne kolektivnog ponašanja u ovom uticajnom djelu. U radu „Psihologija mase i analiza ega“ (1921), Frojd objašnjava zašto pojedinci prepuštaju sopstvenu volju gomili, kako vođe vrše hipnotički uticaj i šta pokreće naše vezivanje za autoritet. Izdanje takođe obuhvata i rad „Budućnost jedne iluzije“ (1927), koji ispituje psihološke i kulturne korijene religije.', 'Загляните в скрытые механизмы толпы и харизмы вождей вместе с отцом психоанализа, чтобы понять, почему мы ведём себя в группе совсем не так, как наедине с собой.', 'Dive into the mechanics of crowd mentality and charismatic leadership with the father of psychoanalysis to discover why we think so differently in a herd.', 'Zavirite u tajne ponašanja mase i harizme vođa uz oca psihoanalize i otkrijte zašto u gomili djelujemo sasvim drugačije nego sami sa sobom.', '/covers/DP-0269.webp', '#5c2429', 'adults', 'ru', 'available', 'Категория: взрослым: психология', '["real"]', '["psychology","psychoanalysis","society","philosophy","classics"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('заклятие-девственности-270', 'DP-0270', 'Заклятие девственности', 'The Taboo of Virginity', 'Tabu nevinosti', 'Зигмунд Фрейд', 'Sigmund Freud', 'Sigmund Frojd', '', 'Азбука классика', NULL, NULL, 16, 99, 'adult', 'В настоящем сборнике представлены статьи, посвященные довольно часто во времена Фрейда замалчиваемой теме - взаимосвязи психологического здоровья и сексуальной жизни человека. Первым решившись заговорить о любви на языке науки, Фрейд был обречен на то, чтобы его объявили одним из провозвестников сексуальной революции в Европе середины XX столетия.', 'This collection brings together essays on a topic that was largely silenced in Freud''s era: the delicate link between psychological well-being and human sexuality. By daring to examine love and intimacy through the lens of science, Freud inevitably became known as one of the key harbingers of the mid-20th-century sexual revolution in Europe.', 'Ova zbirka sadrži eseje posvećene temi koja se u Frojdovo doba prećutkivala — vezi između psihičkog zdravlja i seksualnog života čovjeka. Kao prvi koji se usudio da o ljubavi progovori jezikom nauke, Frojd je bio predodređen da postane jedan od vjesnika seksualne revolucije u Evropi sredinom 20. vijeka.', 'Для взрослых читателей нашей библиотеки, готовых заглянуть к истокам психоанализа и узнать, как век назад рушились строгие викторианские табу.', 'For adult readers eager to explore the foundations of psychoanalysis and discover how century-old taboos were boldly challenged by science.', 'Za odrasle čitaoce koji žele da istraže korijene psihoanalize i otkriju kako su se prije jednog vijeka rušili strogi tabui.', '/covers/DP-0270.webp', '#5a2a27', 'adults', 'ru', 'available', 'Категория: взрослым: психология', '["real"]', '["психоанализ","психология","классика","наука","философия"]', 1792836322695, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бить-или-не-бить--271', 'DP-0271', 'Бить или не бить?', 'To Beat or Not to Beat?', 'Tući ili ne tući?', 'Игорь Кон', 'Igor Kon', 'Igor Kon', '', 'Время', NULL, NULL, 16, 99, 'adult', '"Бить или не бить?" - последняя книга выдающегося российского ученого-обществоведа Игоря Семеновича Кона, написанная им незадолго до смерти весной 2011 года. В этой книге, опираясь на многочисленные мировые и отечественные антропологические, социологические, исторические, психолого-педагогические, сексологические и иные научные исследования, автор попытался представить общую картину телесных наказаний детей как социокультурного явления. Какой их социальный и педагогический смысл, насколько они эффективны и почему вдруг эти почтенные тысячелетние практики вышли из моды? Или только кажется, что вышли? Задача этой книги, как сформулировал ее сам И.С. Кон, - помочь читателям, прежде всего педагогам и родителям, осмысленно, а не догматически сформировать собственную жизненную позицию по этим непростым вопросам.', '"To Beat or Not to Beat?" is the final work of prominent social scientist Igor Kon, written shortly before his passing in 2011. Drawing on extensive global research across anthropology, sociology, history, psychology, and pedagogy, the author presents a comprehensive study of corporal punishment as a sociocultural phenomenon. Exploring why this millennia-old tradition has fallen out of favor and how effective it truly is, the book invites parents and educators to examine their views thoughtfully and free from dogma.', '„Tući ili ne tući?” posljednja je knjiga istaknutog ruskog sociologa Igora Kona, napisana neposredno prije njegove smrti 2011. godine. Oslanjajući se na brojna svjetska antropološka, sociološka, istorijska i psihološko-pedagoška istraživanja, autor daje cjelovitu sliku fizičkog kažnjavanja đece kao sociokulturnog fenomena. Istražujući smisao, efikasnost i korijene ove vjekovne prakse, knjiga pomaže roditeljima i pedagozima da svjesno i bez dogmi izgrade sopstveni stav.', 'Глубокое и отрезвляющее исследование выдающегося социолога, помогающее родителям и педагогам без догм взглянуть на вековые методы воспитания.', 'A profound and eye-opening sociological journey into parenting history that empowers adults to break generational cycles with wisdom and empathy.', 'Duboko i otrežnjujuće istraživanje koje pomaže roditeljima i pedagozima da prevaziđu vjekovne mitove i grade odnos pun razumijevanja.', '/covers/DP-0271.webp', '#3b5166', 'adults', 'ru', 'available', 'Категория: взрослым: психология', '["real"]', '["parenting","psychology","sociology","education","history"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сексуальная-культура-в-россии-272', 'DP-0272', 'Сексуальная культура в России', 'Sexual Culture in Russia', 'Seksualna kultura u Rusiji', 'Игорь Кон', 'Igor Kon', 'Igor Kon', '', 'Время', NULL, NULL, 16, 99, 'adult', 'Игорь Кон всю жизнь работал на стыке разных общественных и гуманитарных наук: социологии, истории, антропологии, психологии и сексологии. С его именем тесно связано рождение в России таких дисциплин, как история социологии, социология личности, психология юношеского возраста, этнография детства, сексология. Некоторые его книги ломали привычные представления и становились бестселлерами. "Клубничка на березке" - систематический очерк истории русской сексуальной культуры с дохристианских времен до современности. 3-е издание книги отличается от первых двух (1997, 2005) не только привлечением многочисленных новых фактов, но и точкой отсчета. В 1994 году автор сформулировал прогноз, в каком направлении будет (может) развиваться сексуальная культура в России. Прошло пятнадцать лет, и пришла пора посмотреть, оправдались ли его предсказания, как произошедшие перемены сказываются на сексуальном здоровье и повседневной жизни россиян и чего мы можем ожидать в ближайшем будущем.', 'Igor Kon, a pioneering Russian sociologist, anthropologist, and sexologist, presents a comprehensive and fascinating history of Russian sexual culture from pre-Christian traditions to the 21st century. This revised edition analyzes societal transformations, intimacy, taboo, and sex education, examining how historical shifts have reshaped everyday relationships and what the future might hold.', 'Igor Kon, pionir ruske sociologije, antropologije i seksologije, pruža sveobuhvatnu i fascinantnu istoriju ruske seksualne kulture od prehrišćanskih vremena do 21. vijeka. Ovo izdanje analizira društvene transformacije, intimnost, tabue i seksualno obrazovanje, osvjetljavajući kako su istorijske promjene oblikovale svakodnevicu i šta donosi budućnost.', 'Фундаментальное, смелое и парадоксально увлекательное исследование академика Кона, которое заставляет взглянуть на историю общества под совершенно новым углом.', 'A brilliant, candid, and eye-opening sociological journey into the hidden history of Russian society, written by a true pioneer of modern sexology.', 'Sjajno, pronicljivo i odvažno sociološko istraživanje koje otvara oči o istoriji skrivenih tema i pruža novi pogled na razvoj društva.', '/covers/DP-0272.webp', '#8c2d38', 'adults', 'ru', 'available', 'Категория: взрослым: психология', '["real"]', '["sociology","history","culture","psychology","non-fiction"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секс-для-науки-науа-для-секса-273', 'DP-0273', 'Секс для науки, науа для секса', 'Bonk: The Curious Coupling of Science and Sex', 'Bonk: Neobičan spoj nauke i seksa', 'Мэри Роуч', 'Mary Roach', 'Meri Rouč', '', 'Альпина', NULL, NULL, 16, 99, 'adult', 'До середины XX века сексуальную психологию и физиологию практически не изучали, словно секс был постыдной тайной, а не обычным биологическим явлением. Состояние этой науки и поведение ученых определял страх - они боялись общественного мнения, религиозной нетерпимости, политического давления, фанатизма и предрассудков. Теперь, когда значение этой сферы в полной мере оценено обществом, трудно даже представить, с чем приходилось сталкиваться первопроходцам лабораторного секса. Впрочем, и сегодня мало кто задумывается о том, что специалисты изучают секс, как любой другой аспект человеческой физиологии. Виртуозно сочетая научный энтузиазм, журналистскую раскрепощенность, спасительный юмор и неизменный вкус, Мэри Роуч рассказывает, как и зачем развивалась эта наука.', 'Until the mid-twentieth century, the physiology and psychology of sex were hardly studied at all, shrouded in taboo and religious or social prejudice. Mary Roach steps into the quirky, intrepid world of researchers who dared to put intimacy under the microscope. Balancing scientific curiosity, intrepid investigative journalism, and irrepressible humor, this book reveals the astonishing history and bizarre laboratory experiments behind the science of human sexuality.', 'Do sredine dvadesetog vijeka, fiziologija i psihologija intimnosti bile su gotovo tabu tema, potisnute strahom od društvene osude i predrasuda. Meri Rouč nas vodi na duhovito i smjelo putovanje kroz istoriju seksualnih istraživanja i upoznaje sa naučnicima koji su se usudili da intimu stave pod laboratorijski mikroskop. Kroz savršeni spoj naučne radoznalosti i inteligentnog humora, otkrijte fascinantne tajne ljudske biologije.', 'Невероятно остроумный и смелый научпоп о том, как учёные исследовали самое интимное явление в мире — без капли пошлости, но с огромным зарядом юмора!', 'A brilliantly witty and unabashedly curious dive into the weird and wonderful history of laboratory sex science, told with immense charm and zero awkwardness.', 'Nevjerovatno duhovita i smjela knjiga o tome kako naučnici proučavaju najintimnije aspekte ljudskog tijela — bez trunke vulgarnosti i sa puno zaraznog humora!', '/covers/DP-0273.webp', '#d1495b', 'adults', 'ru', 'available', 'Категория: взрослым: психология', '["funny","real"]', '["popular science","human body","biology","humor","history of science"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('игры-в-которые-играют-люди-люд-274', 'DP-0274', 'Игры, в которые играют люди, Люди, которые играют в игры', 'Games People Play / What Do You Say After You Say Hello?', 'Igre koje ljudi igraju / Ljudi koji igraju igre', 'Эрик Берн', 'Eric Berne', 'Erik Bern', '', '', NULL, NULL, 16, 99, 'adult', 'По мнению автора, жизнь каждого человека протекает по определенному сценарию, заложенному еще в раннем детстве. Согласно этому сценарию человек общается со своими коллегами, родными и друзьями, выбирает спутника жизни, строит карьеру, становится счастливым и успешным или же напротив, терпит неудачи. В книге вы найдете подробное описание каждого возможного сценария, а главное узнаете, как любой человек может сам изменять свой жизненный сценарий и добиваться желаемого.Об авторе: Эрик Леннард Берн (1910-1970) – одна из ключевых фигур в современной психологии, создатель оригинального направления в психотерапии – «трансакционного анализа», рассматривающего игру в качестве основы человеческих взаимоотношений. Разработка этой теории принесла ученому мировую известность.', 'According to Eric Berne, human life follows hidden scripts written in early childhood. These scripts dictate how we communicate with colleagues, family, and friends, how we pick partners, build careers, and succeed or fail. This groundbreaking work of transactional analysis uncovers the psychological games we play daily and offers readers the tools to rewrite their life stories and reclaim genuine autonomy.', 'Prema Eriku Bernu, ljudski život se odvija prema skrivenim scenarijima napisanim još u ranom djetinjstvu. Ti scenariji određuju način na koji komuniciramo sa kolegama, porodicom i prijateljima, kako biramo partnere i gradimo karijeru. Ovo kapitalno djelo transakcione analize detaljno opisuje psihološke igre koje igramo svakodnevno i nudi smjernice kako da promijenimo sopstveni životni scenario.', 'Классика практической психологии, которая наглядно объяснит скрытые правила нашего общения и поможет переписать жизненный сценарий.', 'A psychology classic that brilliantly decodes our unconscious social habits and shows how to rewrite the scripts of our everyday lives.', 'Bezvremeni psihološki klasik koji razotkriva skrivene obrasce svakodnevne komunikacije i pomaže nam da napišemo bolji životni scenario.', '/covers/DP-0274.webp', '#2c3e50', 'adults', 'ru', 'available', 'Категория: взрослым: психология', '["real"]', '["psychology","relationships","self-discovery","transactional analysis","non-fiction"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('превращение-275', 'DP-0275', 'Превращение', 'The Metamorphosis', 'Preobražaj', 'Кафка', 'Franz Kafka', 'Franc Kafka', '', 'Азбука классика', NULL, NULL, 16, 99, 'adult', 'В настоящий сборник вошли рассказы и афоризмы выдающегося австрийского писателя Франца Кафки. Все эти произведения перевел один из старейших и наиболее известных в России переводчиков немецкоязычной литературы Соломон Апт. Сборник сопровождается статьей специалиста по творчеству Кафки А.Белобратова и послесловием переводчика. Перевод с немецкого С. Апта.', 'This collection brings together celebrated short stories and aphorisms by the iconic Austrian writer Franz Kafka, masterfully translated by Solomon Apt and accompanied by scholarly insights from Kafka expert A. Belobratov.', 'Ova zbirka objedinjuje pripovijetke i aforizme istaknutog austrijskog pisca Franca Kafke u majstorskom prevodu Solomona Apta, uz esej stručnjaka za Kafkino djelo A. Belobratova i pogovor prevodioca.', 'Если вы проснулись и чувствуете себя немного жуком, эта экзистенциальная классика напомнит, что вы не одиноки в своей уязвимости.', 'If you ever wake up feeling utterly alienated from the bustling world, Kafka''s timeless masterwork is here to keep you hauntingly poignant company.', 'Ako se ikada probudite sa osjećajem da vas svijet ne razumije, ova vanvremenska klasika ponudiće vam duboko i utješno saosjećanje.', '/covers/DP-0275.webp', '#4a3c31', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["spooky","real"]', '["classics","existentialism","philosophy","short stories","austrian literature"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сто-лет-одиночества-276', 'DP-0276', 'Сто лет одиночества', 'One Hundred Years of Solitude', 'Sto godina samoće', 'Габриэль Гарсиа Маркес', 'Gabriel García Márquez', 'Gabrijel Garsija Markes', '', 'Азбука-классика', 2007, '978-5-91181-489-2', 16, 99, 'adult', '', 'A monumental cornerstone of magical realism, this novel chronicles seven generations of the Buendía family in the mythical town of Macondo. Blending historical reality with boundless imagination, Márquez weaves a hypnotic tale of love, war, memory, and the inescapable cycle of solitude.', 'Monumentalno remek-djelo magičnog realizma prati sedam generacija porodice Buendija u mitskom gradiću Makondo. Spajajući istoriju, mit i bujnu maštu, Markes tka hipnotišuću priču o ljubavi, ratu, sudbini i neizbježnoj samoći.', 'Держите генеалогическое древо Буэндиа под рукой и приготовьтесь навсегда влюбиться в тягучую магию Макондо!', 'Keep the Buendía family tree handy and prepare to get utterly lost in the timeless, spellbinding magic of Macondo!', 'Držite porodično stablo Buendija pri ruci i prepustite se nezaboravnoj, začaranoj magiji Makonda!', '/covers/DP-0276.webp', '#c2893f', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["magic","real"]', '["magical realism","family saga","classics","destiny","latin america"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('восьмигранник-277', 'DP-0277', 'Восьмигранник', 'Octahedron', 'Oktaedar', 'Хулио Кортасар', 'Julio Cortázar', 'Julio Cortázar', '', 'АСТ, Астрель (в рамках классической серии / Neoclassic)', 2010, '978-5-17-064371-4', 16, 99, 'adult', 'Книга, которую испаноязычная критика называла "бомбой, взорвавшейся в среде современной литературы". Идеальный, эталонный образец "концептуального сборника". Восемь рассказов - восемь граней реальности, обычной и вымышленной. Восемь завораживающих историй-лабиринтов, где за внешней легкостью и неброскостью скрывается поразительная глубина содержания. На первый взгляд, эти тексты никак не связаны между собой, - но в действительности связь между ними есть, хотя и тонкая, еле уловимая. В чем же она заключается? Ответ на этот вопрос принадлежит самому читателю...', 'Eight dazzling stories form the eight facets of this conceptual masterpiece, effortlessly blending ordinary life with the surreal and uncanny. Cortázar crafts intricate labyrinths where subtle, hidden threads link seemingly unconnected realities, leaving the final revelation in the reader''s hands.', 'Osam blistavih priča čini osam stranica ovog konceptualnog remek-djela, preplićući svakodnevicu sa nesvakidašnjim u Kortasarovom prepoznatljivom stilu lavirinta. Iza prividne nepovezanosti tekstova krije se suptilna, jedva primjetna nit koju svaki čitalac otkriva za sebe.', 'Идеальная головоломка от маэстро магического реализма: восемь историй, восемь граней и бесконечное число отражений для вдумчивого вечера!', 'The ultimate puzzle from the maestro of magical realism: eight tales, eight facets, and endless reflections for an exquisite evening read.', 'Savršena književna zagonetka majstora magijskog realizma: osam priča, osam ploha i bezbroj odraza za jedno magično veče.', '/covers/DP-0277.webp', '#23415e', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["magic","real"]', '["short stories","magical realism","latin american literature","mystery","classics"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мерзкая-плоть-278', 'DP-0278', 'Мерзкая плоть', 'Vile Bodies', 'Podla tijela', 'Ивлин Во', 'Evelyn Waugh', 'Ivlin Vo', '', 'Азбука классика', NULL, NULL, 16, 99, 'adult', 'Блестящий роман Ивлина Во, одного из самых знаменитых писателей ХХ века, повествует жизни английской аристократии двадцатых годов, о развлечениях и экстравагантных выходках "золотой молодежи", отбросившей пуританскую мораль. Перевод с английского М. Лорие.', 'Evelyn Waugh''s razor-sharp, sparkling satire captures the dizzying whirl, wild parties, and existential disillusionment of the Bright Young Things in 1920s London aristocracy.', 'Blistavi satirični roman Ivlina Voa prati burni život britanske aristokratije dvadesetih godina prošlog vijeka, kroz prizmu ekstravagantnih zabava i lakomislenosti „zlatne omladine”.', 'Едкая, искромётная сатира на праздную «золотую молодёжь» межвоенного Лондона, от которой просто невозможно оторваться.', 'A razor-sharp and hilarious portrait of the Bright Young Things dancing carelessly on the edge of the abyss.', 'Britka i beskrajno duhovita satira o razuzdanoj „zlatnoj omladini” koja bezbrižno pleše na ivici ponora.', '/covers/DP-0278.webp', '#842b35', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","real"]', '["satire","british literature","classics","1920s","aristocracy"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('заводной-апельсин-279', 'DP-0279', 'Заводной апельсин', 'A Clockwork Orange', 'Paklena pomorandža', 'Энтони Берджесс', 'Anthony Burgess', 'Entoni Berdžes', '', 'Эксмо', 2003, '5-699-03945-7', 16, 99, 'adult', 'Энтони Бёрджесса - английского прозаика, поэта, литературоведа, лингвиста и композитора - по праву называют одним из величайших интеллектуалов своего времени. "Заводной апельсин" - самое знаменитое произведение автора. Оно принесло ему мировую славу и одновременно скандальную известность отца-основателя "киберпанковской субкультуры". Перевод с английского В. Бошняка.', 'Anthony Burgess — English novelist, poet, composer, and linguist — was recognized as one of the sharpest literary minds of his era. ''A Clockwork Orange'' is his most famous and provocative masterpiece, exploring the dark edges of free will, morality, and state control in a dystopian vision of youth rebellion.', 'Entoni Berdžes — engleski pisac, kompozitor i lingvista — bio je jedan od najistaknutijih intelektualaca svoga doba. „Paklena pomorandža“ njegovo je najslavnije i najkontroverznije djelo koje preispituje granice slobodne volje, morala i represije u distopijskom društvu.', 'Провокационная и гипнотическая классика о свободе выбора, от которой невозможно оторваться, даже когда становится по-настоящему неуютно.', 'A razor-sharp, hypnotic classic that cuts straight to the core of human free will and morality.', 'Provokativan i hipnotišući klasik koji postavlja neugodna, ali neophodna pitanja o prirodi slobodnog izbora.', '/covers/DP-0279.webp', '#e65100', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","spooky"]', '["dystopia","classic","psychological","cult-classic","philosophy"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ящик-для-письменных-принадлежн-280', 'DP-0280', 'ящик для письменных принадлежностей', 'The Writing Box', 'Kutija za pisanje', 'Милорад Павич', 'Milorad Pavić', 'Milorad Pavić', '', 'Азбука классика', NULL, NULL, 16, 99, 'adult', 'Этому роману знаменитого сербского писателя Милорада Павича присущи многозначность и нелинейная направленность повествования, свободное обращение с пространством и временем. "Инвентаризация" случайно купленного старинного ящика для письменных принадлежностей, обследование его отделений и потаенных закоулков оборачиваются раскрытием космоса человеческой души. В настоящем издании помещено также эссе М. Павича "Писать во имя отца, во имя сына или во имя духа братства?" и статьи Я. Михайлович и Д. Рамадански, посвященные прозе писателя. Перевод с сербского Л. Савельевой.', 'This captivating novel by renowned Serbian writer Milorad Pavić showcases his signature non-linear storytelling and fluid play with space and time. An inventory of an antique writing box bought by chance turns into an exploration of the cosmos of the human soul. This edition also includes essays delving into Pavić''s mesmerizing literary labyrinths.', 'Ovaj roman slavnog srpskog pisca Milorada Pavića odlikuju višeznačnost i nelinearna naracija, uz slobodno poigravanje prostorom i vremenom. Detaljno istraživanje pregrada i skrivenih kutaka jedne slučajno kupljene starinske kutije za pisanje pretvara se u otkrivanje čitavog kosmosa ljudske duše.', 'Загляните в потайные ящички старинного секретера и откройте бесконечный лабиринт историй от сербского мага слова!', 'Peek into the secret drawers of an antique writing box and lose yourself in a dazzling labyrinth woven by a master of magical realism!', 'Zavirite u tajne pregrade jedne starinske kutije za pisanje i otkrijte čarobni lavirint priča velikog majstora riječi!', '/covers/DP-0280.webp', '#7c482b', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["magic","adventure"]', '["serbian literature","postmodernism","labyrinth","mystery","secrets"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('повесть-огосподине-зоммере-281', 'DP-0281', 'Повесть огосподине Зоммере', 'The Story of Mr. Sommer', 'Priča o gospodinu Zomeru', 'Патрик Зюскинд', 'Patrick Süskind', 'Patrik Ziskind', '', 'Азбука классика', NULL, NULL, 16, 99, 'adult', 'В "Повести о господине Зоммере" Патрик Зюскинд, известный во всем мире автор романа "Парфюмер" и пьесы "Контрабас", обращается к внутреннему миру подростка, рассказывая о нем с неподдельной нежностью и легкой иронией. Книга иллюстрирована Жан-Жаком Семпе. Перевод с немецкого Э. Венгеровой.', 'In ''The Story of Mr. Sommer'', Patrick Süskind, acclaimed author of ''Perfume'', explores the inner world of a growing boy with genuine tenderness and gentle irony. Masterfully illustrated by Jean-Jacques Sempé, this novella is an evocative, bittersweet meditation on childhood, unspoken sorrow, and the mysterious neighbor who is always in a hurry.', 'U ''Priči o gospodinu Zomeru'', Patrik Ziskind, autor čuvenog romana ''Parfem'', okreće se unutrašnjem svijetu dječaka, pripovijedajući o njemu s iskrenom toplinom i blagom ironijom. Obogaćena predivnim ilustracijama Žan-Žaka Sempea, ova nostalgična novela oslikava djetinjstvo, skrivene tuge i tajnu neobičnog čovjeka koji neprestano nekuda žuri.', 'Пронзительная и удивительно светлая акварельная повесть о детстве, первой любви и загадочном соседе, который всегда куда-то бежит.', 'A poignant, bittersweet, and delicately illustrated tale of growing up, climbing trees, and the mysterious man who was always in a hurry.', 'Dirljiva i nostalgična priča o odrastanju, prvim ljubavima i zagonetnom čovjeku koji neprestano bježi od sopstvenog nemira.', '/covers/DP-0281.webp', '#668066', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["coming of age","nostalgia","illustrated","classic","philosophy"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пьесы-282', 'DP-0282', 'Пьесы', 'Plays', 'Drame', 'Жан-Поль Сартр', 'Jean-Paul Sartre', 'Žan-Pol Sartr', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'Жан-Поль Сартр (1905-1980) - выдающийся французский писатель и философ, литературный критик и публицист, общественный деятель и драматург - давно стал легендой, но до сих пор остается одной из самых неоднозначных и загадочных фигур ХХ века. Перевод с французского Л. Большинцова, Л. Зонина, Е. Пучкова, Е. Якушкина', 'Jean-Paul Sartre (1905–1980) — outstanding French writer, philosopher, literary critic, and playwright — remains one of the most enigmatic and influential minds of the 20th century. This collection brings together his most famous dramatic works exploring freedom, guilt, and the human condition.', 'Žan-Pol Sartr (1905–1980) — istaknuti francuski pisac, filozof, književni kritičar i dramski pisac — ostaje jedna od najzagonetnijih i najuticajnijih ličnosti 20. vijeka. Ova zbirka sadrži njegove najpoznatije drame koje istražuju slobodu, krivicu i ljudsku egzistenciju.', 'Загляните за кулисы экзистенциализма: здесь кипят нешуточные страсти, а фраза «ад — это другие» звучит острее любого детектива.', 'Step behind the curtain of existential drama where burning philosophical questions feel as gripping as any thriller.', 'Zavirite iza kulisa egzistencijalizma gdje goruća filozofska pitanja postaju uzbudljiva poput najnapetijeg trilera.', '/covers/DP-0282.webp', '#2c3437', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["drama","philosophy","french literature","theatre","classics"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сила-обстоятельств-283', 'DP-0283', 'Сила обстоятельств', 'Force of Circumstance', 'Snaga okolnosti', 'Симона де Бовуар', 'Simone de Beauvoir', 'Simone de Beauvoir', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'Cимона де Бовуар (1908-1986) - одна из самых известных французских писательниц и самых ярких "феминисток" XX века. Жан Поль Сартр, Альбер Камю, Андре Жид, Жан Жене, Борис Виан и многие другие - это та среда, в которой проходила ее незаурядная жизнь. Натура свободолюбивая и независимая, она порождала многочисленные слухи, легенды и скандалы. Но правда отнюдь не всегда соответствует легендам. Так какой же на самом деле была эта великая женщина, опередившая свое время и шагнувшая в вечность? О себе и о людях ее окружавших, о творчестве, о любовных историях и злоключениях, - обо всем она откровенно рассказывает в своей автобиографической книге "Сила обстоятельств".', 'Simone de Beauvoir (1908–1986) was one of the most prominent French writers and iconic feminist thinkers of the twentieth century. Surrounded by intellectual giants like Jean-Paul Sartre, Albert Camus, and Boris Vian, her life was as brilliant as it was unconventional. In this candid autobiographical account, Beauvoir chronicles the post-war years, her creative passions, political battles, and complex personal relationships, cutting through the myths to reveal the fearless woman behind the legend.', 'Simon de Bovoar (1908–1986) bila je jedna od najuticajnijih francuskih književnica i ikona feminizma dvadesetog vijeka. Živeći u središtu pariskog intelektualnog kruga uz Žan-Pola Sartra, Albera Kamija i Borisa Vijana, vodila je nesvakidašnji i slobodouman život. U ovom autobiografskom djelu, ona iskreno piše o poslijeratnim godinama, stvaralaštvu, političkim previranjima, ljubavima i razočaranjima, otkrivajući istinu iza legende o ženi koja je hrabro išla ispred svog vremena.', 'Погрузитесь в кипящий интеллектуальный Париж середины века вместе с женщиной, которая дерзко переписала правила литературы, философии и самой жизни!', 'Dive into the vibrant mid-century Parisian intellectual scene alongside a woman who boldly rewrote the rules of philosophy, literature, and life itself!', 'Zavirite u uzbudljivi poslijeratni Pariz kroz oči žene koja je hrabro pomjerala granice filozofije, književnosti i sopstvene slobode!', '/covers/DP-0283.webp', '#7a2e3b', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["autobiography","memoir","feminism","philosophy","french literature"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('голоса-летнего-дня-284', 'DP-0284', 'Голоса летнего дня', 'Voices of a Summer Day', 'Glasovi ljetnjeg dana', 'Ирвин Шоу', 'Irwin Shaw', 'Irvin Šo', '', 'АСТ', 2021, '978-5-17-139349-6', 16, 99, 'adult', 'Жизнь человека - лишь крошечная песчинка в пустыне времени. Это - золотые двадцатые и непроглядная чернота Великой депрессии. Это - кошмар Второй мировой и отчаянное счастье уцелевших. Это - горькие утраты и восхитительные победы. Ибо, пока еще не ушли, мы - эпицентр мира, а когда уйдем, уже для детей наших зазвучат, как когда-то для нас Голоса летнего дня...', 'A human life is a fleeting grain of sand in the vast expanse of time. Sitting on the bleachers watching his young son play baseball on an idyllic afternoon, a middle-aged father revisits his past: the Roaring Twenties, the bitter depths of the Great Depression, the horrors of World War II, and the hard-won joys of survival. Irwin Shaw crafts a lyrical, deeply moving tapestry of memory, loss, and enduring love.', 'Čovjekov život samo je zrnce pijeska u pustinji vremena. Dok sjedi na tribinama i posmatra svog sina kako igra bejzbol jednog mirnog popodneva, otac premotava film sopstvene prošlosti: od ludih dvadesetih i mraka Velike depresije, do užasa Drugog svjetskog rata i očajničke sreće preživjelih. Irvin Šo tka dirljivu i lirsku priču o sjećanjima, gubicima i trajnoj ljubavi.', 'Тонкая и пронзительная ретроспектива целой человеческой жизни, подслушанная за один тёплый летний день.', 'A tender, poignant retrospective of an entire life, quietly unraveled across the innings of a single summer baseball game.', 'Nježna i dirljiva retrospektiva jednog života, tiho dočarana tokom jednog sunčanog popodneva.', '/covers/DP-0284.webp', '#d69642', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["nostalgia","american classic","family","memory","20th century"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('1984-скотный-двор-285', 'DP-0285', '1984, Скотный двор', '1984 & Animal Farm', '1984. i Životinjska farma', 'Джордж Оруэлл', 'George Orwell', 'Džordž Orvel', '', 'Капик', NULL, NULL, 16, 99, 'adult', 'Своеобразный антипод второй великой антиутопии XX века - "О дивный новый мир" Олдоса Хаксли. Что, в сущности, страшнее: доведенное до абсурда "общество потребления" - или доведенное до абсолюта "общество идеи"? По Оруэллу, нет и не может быть ничего ужаснее тотальной несвободы... Каждый день Уинстон Смит переписывает историю в соответствии с новой линией Министерства Правды. С каждой ложью, которую он переносит на бумагу, Уинстон всё больше ненавидит Партию, которая не интересуется ничем кроме власти, и которая не терпит инакомыслия. Но чем больше Уинстон старается думать иначе, тем сложнее ему становится избежать ареста, ведь Большой Брат всегда следит за тобой…', 'A quintessential counterpart to Aldous Huxley''s ''Brave New World'', George Orwell''s classic masterpieces examine the terrifying extremes of absolute ideological control versus personal freedom. In ''1984'', Winston Smith rewrites history daily according to the Party''s changing dictates, all while harboring a quiet rebellion in a world where Big Brother is always watching. Paired with the satirical allegory ''Animal Farm'', this volume presents an enduring warning against tyranny and the manipulation of truth.', 'Izuzetan antipod drugoj velikoj distopiji 20. vijeka — Hakslijevom ''Vrlim novom svijetu''. Šta je zapravo strašnije: društvo konzumerizma dovedeno do apsurda ili ideološko društvo dovedeno do apsoluta? Za Orvela nema ničeg strašnijeg od totalnog gubitka slobode. U ''1984'', Vinston Smit svakodnevno prepravlja istoriju po nalogu Ministarstva istine, boreći se sa sopstvenom pobunom u svijetu gdje Veliki Brat uvijek posmatra, dok ''Životinjska farma'' donosi britku basnu o tome kako se plemeniti ideali pretvaraju u tiraniju.', 'Две бессмертные антиутопии под одной обложкой — лучшая прививка от слепой веры в авторитеты и напоминание о том, как драгоценна свобода мысли.', 'Two essential literary warnings in one volume—the ultimate wake-up call to protect your freedom of thought and always question absolute power.', 'Dvije neprolazne distopije među istim koricama — savršen podsjetnik zašto uvijek treba čuvati slobodu mišljenja i preispitivati nametnute istine.', NULL, '#4a5568', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","spooky","animals"]', '["dystopia","classics","politics","freedom","satire"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вокруг-света-за-80-дней-286', 'DP-0286', 'Вокруг света за 80 дней', 'Round the World in 80 Days: My First Voyage', 'Put oko svijeta za 80 dana: Moje prvo putovanje', 'Жан Кокто', 'Jean Cocteau', 'Žan Kokto', '', 'Текст', NULL, NULL, 16, 99, 'adult', 'Два француза решают повторить маршрут героев романа Жюля Верна. Что это? Погоня за детской мечтой или причуда скучающих интеллектуалов? Время действия - 1936 год.Книга Жана Кокто "Вокруг света за 80 дней. Мое первое путешествие" родилась в результате контракта с французской газетой "Paris-Soir". Повторив маршрут Филеаса Фогга из романа Жюля Верна, писатель обобщил свой опыт в этой книге: тонкие наблюдения, романтический взгляд на мир 1936 года, обилие важных деталей, характеризующих переломную для Европы эпоху.', 'In 1936, Jean Cocteau and his companion set off to retrace Phileas Fogg''s legendary itinerary from Jules Verne''s novel on an assignment for Paris-Soir. Part childhood dream, part intellectual escapade, this travelogue offers exquisite observations, sparkling wit, and a poignant snapshot of a world teetering on the brink of global upheaval.', 'Godine 1936. Žan Kokto i njegov saputnik kreću na put oko svijeta prateći korake Fileasa Foga iz čuvenog romana Žila Verna, a sve po zadatku za novine „Paris-Soir“. Da li je to potraga za dječačkim snom ili hir radoznalih intelektualaca? Ova knjiga nudi pronicljiva zapažanja, poetski duh i dragocjen uvid u atmosferu svijeta neposredno pred Drugi svjetski rat.', 'Изысканный литературный вояж по следам Филеаса Фогга глазами блестящего поэта и эстета накануне надвигающейся мировой бури.', 'Step aboard a poetic, sharp-witted 1936 globetrotting adventure alongside one of France''s most brilliant artistic minds.', 'Krenite na poetsko i duhovito putovanje oko svijeta iz 1936. godine u društvu jednog od najblistavijih francuskih umjetnika.', '/covers/DP-0286.webp', '#2b4c6f', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["adventure","real"]', '["travel","memoir","1930s","french literature","journey"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('люблинский-штукарь-287', 'DP-0287', 'Люблинский штукарь', 'The Magician of Lublin', 'Mađioničar iz Lublina', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', '', 'Текст', NULL, NULL, 16, 99, 'adult', '"Люблинский штукарь" - один из самых прославленных романов нобелевского лауреата Исаака Башевиса Зингера. Действие происходит в конце XIX века. Герой романа Яша Мазур - штукарь - гениальный фокусник, акробат, чревовещатель, дрессировщик, музыкант. Слава о нем идет по всей Польше. Но не трюками едиными жив артист, не чужды ему и человеческие страсти - от высоких до самых низких... Используя свой дар, он пытается похитить крупную сумму, чтобы разрешить житейские проблемы. Из-за своей страстной любви к католичке Эмилии он едва не становится вором и убийцей, а затем становится виновником самоубийства влюбленной в него девушки. В ужасе Яша отказывается от всех соблазнов мира… и в конце концов находит путь к спасению. Совсем иной. Блестящий переводчик Асар Эппель сумел по-русски передать этот завораживающий читателей во всем мире стиль - Исаака Башевиса Зингера.', 'Set in late 19th-century Poland, Nobel laureate Isaac Bashevis Singer''s acclaimed novel follows Yasha Mazur, a brilliant magician, acrobat, and ventriloquist whose fame stretches across the country. Yet beyond astonishing stage tricks, Yasha is torn apart by worldly temptations, pride, and entangled loves. Attempting a daring theft to escape his turmoil, his moral descent triggers a devastating tragedy. Horrified by the consequences of his actions, Yasha renounces worldly delights to embark on an extraordinary, ascetic path to spiritual redemption.', 'Radnja ovog slavnog romana nobelovca Isaka Baševisa Singera smještena je u Poljsku s kraja 19. vijeka i prati Jašu Mazura — genijalnog mađioničara, akrobatu i iluzionistu čija slava odjekuje čitavom zemljom. Ipak, iza blistavih scenskih trikova krije se čovjek rastrzan strastima i teškim zabludama. Pokušaj prevare dovodi ga na ivicu duhovnog ponora i tragedije, tjerajući ga da se odrekne svih ovozemaljskih iskušenja u potrazi za radikalnim, neočekivanim putem ka iskupljenju.', 'Глубокая и захватывающая притча о гениальном фокуснике, который умел взламывать любые замки, кроме засова на собственной совести.', 'A gripping, atmospheric tale of a master illusionist who could pick any lock in the world except the one guarding his own conscience.', 'Upečatljiva i duboka priča o virtuoznom iluzionisti koji je mogao da otključa svaku bravu osim one na sopstvenoj savjesti.', '/covers/DP-0287.webp', '#4a1d24', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["adventure","real"]', '["nobel prize","classic","illusionist","drama","redemption"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('семья-мускат-288', 'DP-0288', 'Семья Мускат', 'The Family Moskat', 'Porodica Moškat', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', '', 'Текст', NULL, NULL, 16, 99, 'adult', 'Выдающийся писатель, лауреат Нобелевской премии Исаак Башевис Зингер посвятил роман "Семья Мускат" (1950) памяти своего старшего брата. Посвящение подчеркивает преемственность творческой эстафеты, - ведь именно Исроэл Йошуа Зингер своим знаменитым произведением "Братья Ашкенази" заложил основы еврейского семейного романа. В "Семье Мускат" изображена жизнь варшавских евреев на протяжении нескольких десятилетий - мы застаем многочисленное семейство в переломный момент, когда под влиянием обстоятельств начинает меняться отлаженное веками существование польских евреев, и прослеживаем его жизнь на протяжении десятилетий. Роман существует в двух версиях - идишской и английской, перевод которой мы и предлагаем читателю.', 'Nobel laureate Isaac Bashevis Singer dedicated ''The Family Moskat'' (1950) to the memory of his older brother, Israel Joshua Singer. This monumental family saga chronicles the gradual decline of a wealthy Warsaw Jewish dynasty across several turbulent decades, capturing a vibrant culture on the brink of profound historical change.', 'Nobelovac Isak Baševis Singer posvetio je roman „Porodica Moškat” sjećanju na svog starijeg brata. Ova monumentalna porodična hronika vjerno oslikava život varšavskih Jevreja tokom nekoliko decenija, bilježeći prelomni trenutak u kom se vjekovima utemeljeni svijet nepovratno mijenja pod pritiskom istorijskih previranja.', 'Масштабная, живая и пронзительная сага о мире предвоенной Варшавы, ушедшем навсегда.', 'A sweeping, deeply poignant family epic that brings the vanished world of pre-war Warsaw brilliantly to life.', 'Monumentalna i dirljiva porodična saga koja majstorski oživljava iščezli svijet predratne Varšave.', '/covers/DP-0288.webp', '#633c37', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["family saga","warsaw","jewish history","historical fiction","classics"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('страсти-289', 'DP-0289', 'Страсти', 'Passions', 'Strasti', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', '', 'Текст', NULL, NULL, 16, 99, 'adult', 'За свою жизнь лауреат Нобелевской премии Исаак Башевис Зингер (1904-1991) написал десятки романов и множество рассказов для взрослых и детей. Сборник "Страсти" объединяет рассказы о евреях, разбросанных судьбой по всему миру, переживших Холокост и сумевших сохранить веру в добро, в человеческое благородство. Герои Зингера любят и ненавидят, изучают Талмуд и грешат, философствуют и подсмеиваются над собой. Это третье издание сборника, литературные достоинства которого были высоко оценены самыми строгими российскими читателями.', 'Nobel Prize laureate Isaac Bashevis Singer brings together vibrant, poignant stories of Jewish men and women scattered across the globe after the Holocaust. Rich in philosophy, subtle humor, and mystical wonder, these tales explore the full spectrum of human passions—from love and sin to faith, doubt, and resilience.', 'Dobitnik Nobelove nagrade Isak Baševis Singer u zbirci ''Strasti'' sabira dirljive priče o ljudima rasutim širom svijeta nakon Holokausta. Kroz ljubav, grijeh, vjeru i blagu samoironiju, Singerovi junaci mudro čuvaju plemenitost duha i vječnu strast prema životu.', 'Мудрые, глубокие и удивительно человечные рассказы лауреата Нобелевской премии о том, как сквозь любые бури пронести любовь, веру и искру юмора.', 'Wise, touching, and masterfully told stories revealing how faith, longing, and humor endure through life''s deepest trials.', 'Mudre, tople i duboke priče nobelovca o tome kako kroz sve životne oluje sačuvati ljubav, vjeru i iskru humora.', '/covers/DP-0289.webp', '#7a2b37', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","magic"]', '["short stories","nobel prize","jewish literature","philosophy","classics"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('раб-290', 'DP-0290', 'Раб', 'The Slave', 'Rob', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', '', 'Текст', NULL, NULL, 16, 99, 'adult', 'Опубликованный в 1961 году на идише роман лауреата Нобелевской премии Исаака Башевиса Зингера "Раб" был через год переведен на английский и вскоре стал мировым бестселлером. Действие романа происходит в Польше в XVII в. После резни, учиненной гайдамаками в еврейском местечке, талмудист Яков лишается всех своих родных и становится рабом польского крестьянина. Но воля к жизни творит чудеса: пройдя через многие унижения, не раз рискуя погибнуть, он сумел сохранить свою веру и обрести любовь. Трогательная история любви Якова и польской девушки Ванды, оставившей католическую веру и ставшей Саррой, продолжает волновать умы и души читателей и по сей день.', 'Set in seventeenth-century Poland in the aftermath of the Khmelnytsky massacres, this Nobel Prize-winning masterpiece tells the story of Jacob, a devout Talmudist sold into servitude to a Polish peasant. Amid grueling hardships and prejudice, Jacob stubbornly clings to his faith and ethics until an impossible, transformative love with his master''s widowed daughter, Wanda, defies every boundary of religion, society, and survival.', 'Smješten u Poljsku sedamnaestog vijeka nakon kozačkih pogroma, ovaj roman nobelovca Isaka Baševisa Singera donosi priču o Jakovu, pobožnom jevrejskom učenjaku koji postaje rob kod poljskog seljaka. Kroz patnju i poniženja, Jakov uspijeva da sačuva svoju duhovnost i ljudsko dostojanstvo, pronalazeći zabranjenu, ali spasonosnu ljubav sa seljankom Vandom, koja zbog njega prihvata jevrejsku vjeru.', 'Мощная и пронзительная притча лауреата Нобелевской премии о том, что даже в кандалах рабства истинная вера и чистая любовь делают человека свободным.', 'A deeply moving Nobel-winning parable proving that neither bondage nor hatred can break a soul anchored in faith and love.', 'Moćna i dirljiva priča nobelovca o tome kako prava ljubav i unutrašnja vjera mogu donijeti slobodu čak i u najtežem ropstvu.', '/covers/DP-0290.webp', '#8b5a2b', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","adventure"]', '["nobel prize","historical fiction","love story","classic","faith"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шоша-291', 'DP-0291', 'Шоша', 'Shosha', 'Šoša', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', '', 'Текст', 2017, '978-5-7516-1398-3', 16, 99, 'adult', 'Американский прозаик польского происхождения Исаак Башевис Зингер (1904-1991), писавший на идиш, пользуется славой бесподобного рассказчика и стилиста. В 1978 г. ему была присуждена Нобелевская премия по литературе. Роман "Шоша", своего рода визитная карточка писателя, представляет его как истинного мастера слова.', 'Set in Warsaw on the eve of World War II, this poignant masterpiece by Nobel laureate Isaac Bashevis Singer tells the story of Aaron Greidinger, an aspiring writer who remains deeply loyal to his childhood love, the fragile and innocent Shosha, as the world around them teeters on the brink of catastrophe.', 'Smješten u Varšavi uoči Drugog svjetskog rata, ovaj dirljivi roman nobelovca Isaka Baševisa Singera priča je o Aronu Grajdingeru, mladom piscu koji ostaje odan svojoj ljubavi iz djetinjstva, krhkoj i nedužnoj Šoši, dok svijet oko njih nepovratno srlja u propast.', 'Пронзительная история преданности и чистой любви в тревожной Варшаве тридцатых годов, написанная неподражаемым нобелевским лауреатом.', 'A haunting, tender portrait of devotion and innocence in pre-war Warsaw from one of the greatest storytellers of the twentieth century.', 'Nježna i dirljiva priča o iskrenoj privrženosti i nevinosti u predratnoj Varšavi, iz pera maestralnog nobelovca.', '/covers/DP-0291.webp', '#8c564b', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","friends"]', '["nobel prize","historical fiction","jewish culture","love story","warsaw"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('расскаявшийся-292', 'DP-0292', 'Расскаявшийся', 'The Penitent', 'Pokajnik', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', '', 'Текст', NULL, NULL, 16, 99, 'adult', 'Исаак Башевис Зингер (1904-1991), лауреат Нобелевской премии, родился в Польше, в семье потомственных раввинов. В 1935 году эмигрировал в США. За долгую жизнь написал десятки романов, множество рассказов, книги для детей, воспоминания. Герой романа "Раскаявшийся", Иосиф Шапиро, который пережил Холокост и сумел достичь благополучия, начинает испытывать отвращение к соблазнам и лжи окружающей жизни. Душа Иосифа становится ареной борьбы Бога и дьявола. Какой смысл в соблюдении религиозных предписаний? Справедлив ли Бог, допустивший немыслимые страдания его народа? Так ли отвратительны простые человеческие желания и слабости? В конце концов Иосиф Шапиро находит ответ на эти вопросы, но согласен ли с его суровым, бескомпромиссным решением автор? Перевод с английского Виталия Ананьева.', 'Written by Nobel laureate Isaac Bashevis Singer, this searing novel follows Joseph Shapiro, a Holocaust survivor who achieves prosperity in America only to find himself disgusted by the moral bankruptcy and hedonism around him. Forsaking his wealth, mistresses, and secular lifestyle, Shapiro embarks on an intense spiritual pilgrimage to Jerusalem. Through Shapiro''s uncompromising monologue, Singer explores the harrowing struggle between divine commandments, human temptation, and the quest for purity in a shattered post-war world.', 'Napisao nobelovac Isak Baševis Singer, ovaj potresni roman prati Jozefa Šapira, čovjeka koji je preživio Holokaust i stekao bogatstvo u Americi, ali počinje osjećati duboko gađenje prema lažima i iskušenjima modernog društva. Napuštajući uspjeh, luksuz i svjetovni način života, Šapiro kreće na duhovno hodočašće u Jerusalim. Kroz njegovu beskompromisnu ispovijest, Singer postavlja teška pitanja o vjeri, patnji, grijehu i potrazi za duševnim mirom.', 'Глубокая и бескомпромиссная исповедь человека, который бросил вызов соблазнам современного мира в поисках истинной веры.', 'A searing, uncompromising confession of a man who abandons modern comforts to seek peace and spiritual purity in a fractured world.', 'Duboka i beskompromisna ispovijest čovjeka koji odbacuje zablude modernog svijeta u potrazi za istinskom vjerom.', '/covers/DP-0292.webp', '#4a2e2b', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["jewish literature","philosophy","spiritual quest","classics","nobel laureate"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мальчик-моттл-293', 'DP-0293', 'Мальчик Моттл', 'The Adventures of Mottel, the Cantor''s Son', 'Dječak Motl', 'Шолом-Алейхем', 'Sholem Aleichem', 'Šolom Alejhem', '', 'Теревинф', NULL, NULL, 16, 99, 'adult', 'Цикл всемирно известных новелл Шолом-Алейхема в переводе Пейсаха-Мендла Шамбадала с иллюстрациями Григория Ингера. Художник-иллюстратор: Григорий Ингер.', 'Sholem Aleichem''s world-famous classic cycle of stories told through the mischievous and optimistic eyes of young Mottel. Presented in classic translation and accompanied by poignant illustrations by Grigory Inger.', 'Svjetski poznati ciklus priča Šoloma Alejhema o doživljajima dječaka Motla, ispričan sa neponovljivim humorom, toplinom i sjetom, uz upečatljive ilustracije Grigorija Ingera.', 'Трогательная и светлая классика о том, как сохранять озорство и радость жизни даже в самые непростые времена («Мне хорошо — я сирота!»).', 'A poignant, sparkling Jewish classic showing how boundless childish optimism can light up even the hardest of times.', 'Dirljiv i nevjerovatno duhovit klasik koji kroz dječji pogled slavi neuništivi optimizam i u najtežim životnim okolnostima.', '/covers/DP-0293.webp', '#9c5a3c', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","real"]', '["classic","jewish culture","humor","childhood","illustrated"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дело-малоссена-294', 'DP-0294', 'Дело Малоссена', 'The Malaussène Case', 'Slučaj Malosen', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'На дворе XXI век. Процветают коррупция и терроризм. Кто же может этому противостоять? Конечно, семейство Малоссенов: младшие его члены подросли и сами устанавливают справедливость, а старшие - им помогают. Все, кроме профессионального "козла отпущения", Бенжамена Малоссена. Нет, он не против, он просто не в курсе! Но обвинения во всех смертных грехах предъявят именно Бенжамену. Впрочем, не волнуйтесь, он выпутается!', 'In the 21st century, corruption and terrorism are rampant. Who could possibly push back? The legendary Malaussène tribe, of course: the younger generation has grown up and is ready to take justice into their own hands, while the elders provide backup. Everyone, that is, except Benjamin Malaussène—the world''s favorite professional scapegoat. He isn''t against it, he''s just happily out of the loop! Naturally, every single crime gets pinned on him. But don''t worry, he always finds a chaotic way out.', 'U dvadeset prvom vijeku cvjetaju korupcija i terorizam. Ko se tome može suprotstaviti? Naravno, neponovljiva porodica Malosen: mlađi članovi su odrasli i sami uzimaju pravdu u svoje ruke, dok im stariji pomažu. Svi, osim Benžamena Malosena, profesionalnog „žrtvenog jarca“. On nema ništa protiv, samo ništa ne shvata! Ipak, za sve grijehe ponovo će okriviti upravo njega. Ali ne brinite, naći će on izlaz!', 'Настоящий французский карнавал, где семейный хаос превращается в лучшее лекарство от мировых бедствий!', 'A delightfully chaotic French carnival where family madness turns out to be the ultimate antidote to the world''s troubles!', 'Pravi francuski karneval u kojem porodični haos postaje najbolji lijek za sve svjetske nevolje!', '/covers/DP-0294.webp', '#8f2d38', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","adventure"]', '["french literature","detective","family","satire","humor"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('людоедское-счастье-295', 'DP-0295', 'Людоедское счастье', 'The Scapegoat', 'Za sreću ljudoždera', 'Даниэль Пеннак', 'Daniel Pennac', 'Daniel Pennac', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Это первый роман саги о старшем брате из огромного семейства и профессиональном "козле отпущения" Бенжамене Малоссене. Каждый его рабочий день похож на другой, но в канун Рождества привычная рутина рушится, в гигантском супермаркете, где он трудится, начинают взрываться бомбы. И каждый раз поблизости оказывается Бенжамен...', 'This is the first novel in the famous Belleville saga about Benjamin Malaussène, the oldest sibling of an eccentric, sprawling clan and a professional scapegoat by trade. His daily grind at a bustling Parisian department store is strange enough, but right before Christmas, mysterious parcel bombs start exploding—and Benjamin inexplicably finds himself at the scene of every single crime.', 'Ovo je prvi roman čuvene sage o Benjaminu Malosenu, najstarijem bratu u ogromnoj, neobičnoj porodici i profesionalnom „žrtvenom jarcu”. Njegova radna rutina u velikoj pariskoj robnoj kući pretvara se u haos uoči Božića, kada na raznim odjeljenjima počinju da eksplodiraju bombe — a Benjamin se svaki put nađe u neposrednoj blizini...', 'Искрометный парижский детектив о самом обаятельном «козле отпущения» в мире и его безумной, но потрясающе любящей семье.', 'A brilliantly witty Parisian mystery about the world''s most charming professional scapegoat and his gloriously chaotic, loving family.', 'Pronicljiv i duhovit pariski misterij o najšarmantnijem „žrtvenom jarcu” na svijetu i njegovoj divno haotičnoj porodici.', '/covers/DP-0295.webp', '#b83828', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","adventure"]', '["detective","humor","family","french literature","mystery"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленькая-торговка-прозой-296', 'DP-0296', 'Маленькая торговка прозой', 'The Little Prose Vendor', 'Mala prodavačica proze', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Писательство - мирное ремесло до той поры, пока у автора не отнимают заслуженную славу. Но вот уже по Парижу несутся автомобили полиции и "Скорой помощи"... В третьем романе саги о профессиональном "козле отпущения" Бенжамене Малоссене ее главный герой едва не лишится жизни и почти всех органов, а на Землю спустится самый настоящий ангел.', 'Writing seems like a peaceful craft until someone steals an author''s hard-earned glory. Suddenly, police sirens and ambulances are wailing across Paris... In the third installment of the Malaussène saga, our favorite professional scapegoat Benjamin barely escapes with his life and vital organs intact, while a real angel descends to Earth.', 'Pisanje je miran zanat sve dok autoru ne oduzmu zasluženu slavu. No, Parizom već jure policijska kola i hitna pomoć... U trećem romanu sage o profesionalnom „žrtvenom jarcu” Benžamenu Malosenu, glavni junak će zamalo ostati bez života i organa, dok na Zemlju silazi pravi pravcati anđeo.', 'Блестящая литературная комедия положений в самом сердце Парижа: семейка Малоссенов снова влипает в уморительные и смертельно опасные неприятности!', 'A brilliant literary comedy of errors in the heart of Paris: the eccentric Malaussène tribe is back, stumbling into hilariously mortal danger!', 'Briljantna književna komedija zabune u srcu Pariza: ekscentrična porodica Malosen ponovo upada u urnebesne i smrtonosne nevolje!', '/covers/DP-0296.webp', '#9a3324', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","adventure"]', '["french literature","paris","malaussene","satire","family saga"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('господин-малоссен-297', 'DP-0297', 'Господин Малоссен', 'Monsieur Malaussène', 'Gospodin Malosen', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Бенжамен, старший в "племени Малоссенов", и его возлюбленная Жюли решают обзавестись наследником и спасти от сноса старый кинотеатр "Зебра". Казалось бы, ничего сложного. Но вдруг как из-под земли вырастают старые враги. Убийства, взрывы, похищения, оговоры и подлог - они готовы на всё, лишь бы стереть Бенжамена и его родных с лица Земли. Но не тут-то было!..', 'Benjamin, the eldest of the unruly Malaussène clan, and his beloved Julie are about to embark on their wildest adventure yet: having a baby and saving the vintage Zebra cinema from demolition. But suddenly, old foes resurface from the shadows. Explosions, frame-ups, kidnappings, and murder threaten to wipe the family off the face of Paris, but the legendary Malaussène resilience is not so easily broken.', 'Benžamen, najstariji član otkačenog „plemena Malosen“, i njegova voljena Žili odlučuju da dobiju dijete i spasu stari bioskop „Zebra“ od rušenja. Sve djeluje idilično dok iz sjenke ne izrone stari neprijatelji. Ubistva, podmetanja, otmice i eksplozije prijete da unište porodicu, ali Maloseni nikada ne odustaju bez urnebesne i vješte borbe.', 'Виртуозная парижская круговерть, где безумная семейка Малоссенов спасает старый кинотеатр, ждёт малыша и уворачивается от пуль с фирменным французским шармом!', 'A dizzying Parisian whirlwind where the delightfully chaotic Malaussène clan saves a vintage cinema, awaits a baby, and dodges trouble with unmatched French flair!', 'Vrtoglava pariska avantura u kojoj otkačena porodica Malosen spasava stari bioskop, čeka bebu i izbjegava nevolje uz neodoljivi francuski šarm!', '/covers/DP-0297.webp', '#c2412d', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","adventure","real"]', '["french literature","detective","humor","family saga","paris"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('христиане-и-мавры-плоды-страст-298', 'DP-0298', 'Христиане и мавры. Плоды страсти', 'Christians and Moors. Passion Fruit', 'Hrišćani i Mavri. Plodovi strasti', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Все дети племени Малоссенов - плоды искренней и горячей любви. Правда, взращивают их не родные отцы, а глава семейства и профессиональный "козел отпущения" Бенжамен. А заодно ему приходится распутывать криминальные истории пропажи папаш: одну другой страшнее!', 'All children of the Malaussène tribe are born of sincere, fiery love, yet raised not by their elusive fathers, but by Benjamin—the devoted big brother and professional scapegoat. Along the way, Benjamin must untangle the bizarre and perilous disappearances of these absent fathers, each mystery more outrageous than the last.', 'Sva djeca plemena Malosen rođena su iz iskrene i vatrene ljubavi, ali ih ne odgajaju očevi, već Benjamin — glava porodice i profesionalni dežurni krivac. Pored toga, Benjamin mora da razmrsi bizarne kriminalne misterije nestanaka odbjeglih očeva, od kojih je svaka luđa od prethodne.', 'Ироничный парижский балаган, детективная интрига и нерушимая семейная верность от неподражаемого Даниэля Пеннака.', 'An ironic Parisian circus of crime, eccentric siblings, and unbreakable family loyalty from the inimitable Daniel Pennac.', 'Ironični pariski haos, uvrnuta kriminalistička misterija i nepokolebljiva porodična odanost u režiji neponovljivog Danijela Penaka.', '/covers/DP-0298.webp', '#8a3324', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","adventure","friends"]', '["malaussene","french literature","family","humor","detective"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('фея-карабина-299', 'DP-0299', 'Фея Карабина', 'The Fairy Gunmother', 'Vila Karabina', 'Даниэль Пеннак', 'Daniel Pennac', 'Danijel Penak', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Второй роман французского писателя Даниэля Пеннака (р. 1944), продолжающий серию иронических детективов о похождениях профессионального "козла отпущения" Бенжамена Малоссена.', 'The second installment in Daniel Pennac''s celebrated saga, this witty and eccentric mystery follows Benjamin Malaussène—a professional scapegoat—as he navigates family chaos and a string of mysterious crimes in the heart of Paris.', 'Drugi roman u proslavljenoj sagi Danijela Penaka, ovaj duhoviti i ekscentrični detektivski roman prati Benžamena Malosena — profesionalnog „žrtvenog jarca” — usred porodičnog haosa i niza misterioznih zločina u srcu Pariza.', 'Париж, шумная семейка Малоссенов и таинственные бабушки с карабинами — искромётный и обаятельный детектив с неповторимым французским шармом!', 'Parisian chaos, the unruly Malaussène clan, and armed-to-the-teeth grandmothers make for a delightfully clever detective romp full of heart!', 'Pariz, haotična porodica Malosen i naoružane bakice — neodoljivo vrcav detektivski roman prepun francuskog šarma!', '/covers/DP-0299.webp', '#2c3e50', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","adventure","real"]', '["detective","humor","paris","family","french literature"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('апельсиновая-девушка-300', 'DP-0300', 'Апельсиновая девушка', 'The Orange Girl', 'Djevojka s narandžama', 'Юстейн Гордер', 'Jostein Gaarder', 'Jostein Gaarder', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Имя норвежского писателя Юстейна Гордера - одно из крупнейших в современной литературе. В его книгах удивительным образом сочетаются лучшие традиции мировой классики и новизна и свежесть взгляда. "Апельсиновая Девушка" - это своеобразная книга в книге, ибо рассказ в ней ведут два человека. Мальчик Георг слышит голос своего отца спустя одиннадцать лет после его смерти...', 'A tender and philosophical novel from the acclaimed author of Sophie''s World. Fifteen-year-old Georg unexpectedly receives a long letter written by his father before he died eleven years earlier. Through the captivating and enigmatic story of the elusive ''Orange Girl'', his father poses timeless questions about the universe, love, and the courage it takes to live fully despite knowing life is fleeting.', 'Dirljiv i filozofski roman autora „Sofijinog svijeta“. Petnaestogodišnji Georg pronalazi pismo koje mu je otac ostavio prije jedanaest godina, neposredno prije nego što je preminuo. Kroz očaravajuću i zagonetnu priču o tajanstvenoj „Djevojci s narandžama“, otac postavlja vječna pitanja o univerzumu, prolaznosti i pravoj vrijednosti svakog proživljenog trenutka.', 'Письмо из прошлого, пахнущее цитрусами и тайной, которое заставит вас заново влюбиться в жизнь и ценить каждое её мгновение.', 'A citrus-scented letter from the past that unravels a tender mystery and reminds us why life''s fleeting moments are worth every heartbeat.', 'Pismo iz prošlosti koje miriše na citruse i tajnu, podsjećajući nas zašto vrijedi disati punim plućima i čuvati svaki trenutak.', '/covers/DP-0300.webp', '#d96b27', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["philosophy","family","love story","letters","norwegian literature"]', 1792836322696, 1792845622992);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('декоратор-книга-вещноси-301', 'DP-0301', 'Декоратор, книга вещноси', 'The Decorator: The Book of Things', 'Dekorater: Knjiga o stvarima', 'Тургрим Эгген', 'Torgrim Eggen', 'Torgrim Egen', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Именно этим произведением Тургрим Эгген, норвежский писатель, журналист и музыкант, прославился в России. Ироничный и удивительно стильный роман в жестком ракурсе описывает мир вещей, в котором рядом с талантом и профессионализмом соседствуют самые темные человеческие чувства.', 'This stylish, darkly ironic novel by acclaimed Norwegian writer, journalist, and musician Torgrim Eggen examines modern consumerism and design obsession, revealing how professional brilliance can intertwine with humanity''s darkest impulses.', 'Ovim stilski besprekornim i oštro ironičnim romanom norveški pisac, novinar i muzičar Torgrim Egen secira svijet materijalizma i opsesije dizajnom, otkrivajući kako se vrhunski profesionalizam prepliće s najmračnijim ljudskim porivima.', 'Едкая и невероятно стильная скандинавская сатира для взрослых эстетов, знающих цену безупречному интерьеру.', 'A razor-sharp, darkly stylish Scandinavian satire for adults who appreciate pristine interior design and wicked psychological twists.', 'Oštroumna i stilski besprekorna skandinavska satira za odrasle estete koji znaju pravu cijenu savršenog dizajna.', '/covers/DP-0301.webp', '#2c3e50', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","spooky"]', '["scandinavian literature","satire","design","dark comedy","adult fiction"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шторм-302', 'DP-0302', 'Шторм', 'Storm', 'Oluja', 'Эйнар Карасон', 'Einar Kárason', 'Einar Kárason', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'Есть ли жизнь в Исландии? Сомнениям положен конец: перед вами книга известного исландского писателя Эйнара Карасона, номинированная на премию Северного совета, Исландскую премию по литературе и уже переведенная на несколько языков. Главный герой романа, талантливый и наглый пьяница и мизантроп по прозвищу Шторм, одержим манией величия. Он живет в кредит, который не собирается выплачивать, разъезжает в лимузине по Флориде; повинуясь порыву, разбивает бейсбольной битой все компьютеры в офисе своих благодетелей. Неожиданно для себя Шторм оказывается автором грандиозного бестселлера, сфабрикованного группой "литературных негров".', 'Is there life in Iceland? Look no further: this novel by celebrated author Einar Kárason was nominated for the prestigious Nordic Council Literature Prize. The protagonist, a brazen, brilliant drunkard and misanthrope nicknamed Storm, is possessed by pure megalomania. Living entirely on credit he never plans to repay, cruising through Florida in a limousine, and smashing office computers with a baseball bat, Storm suddenly finds himself celebrated as the author of a sensational bestseller penned by ghostwriters.', 'Ima li života na Islandu? Pred vama je roman proslavljenog islandskog pisca Einara Karasona, nominovan za književnu nagradu Nordijskog savjeta. Glavni junak, drski i talentovani pijanac i mizantrop s nadimkom Oluja, pati od manije veličine. Živeći na veresiju koju ne namjerava da vrati, vozeći se limuzinom po Floridi i razbijajući bejzbol palicom računare svojih dobročinitelja, Oluja neočekivano postaje slavljen kao autor bestselera koji je zapravo napisao neko drugi.', 'Неистовая исландская сатирическая трагикомедия об обаятельном хаосе, который несёт за собой человек-ураган.', 'A wild Icelandic tragicomedy about an outrageous rogue who blusters through life with the devastating force of an Arctic hurricane.', 'Divlja islandska tragikomedija o neodoljivom mangupu koji kroz život prolazi rušeći sve pred sobom poput arktičkog uragana.', '/covers/DP-0302.webp', '#2c4857', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","real"]', '["iceland","scandinavian literature","satire","tragicomedy","bohemian life"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('где-ты-теперь--303', 'DP-0303', 'Где ты теперь?', 'Buzz Aldrin, What Happened to You in All the Confusion?', 'Gdje si sada?', 'Юхан Харстад', 'Johan Harstad', 'Johan Harstad', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'На краю бездны находятся Фарерские острова, где царят смерть, любовь и океан. Где слезы смешиваются со снегом. В одной галактике живут иные люди: одни целуются на фоне заходящего солнца под пение китов в бухте, другие забивают этих китов багром и купаются в море крови, а третьи засовывают руки в их раны, чтобы согреться теплом только что убитых животных. Волей обстоятельств туда занесло юного норвежца Матиаса, который родился в то мгновение, когда первый космонавт шагнул на Луну. Эта необыкновенно лиричная, остроумная и жизнеутверждающая книга, по отзывам критиков, "стоит бессонной ночи". Космический роман молодого скандинава удостоен международной премии Бьернстьерне Бьернсона и переведен на многие языки. Переводчик: Анастасия Наумова.', 'On the edge of the world lie the Faroe Islands, where death, love, and the vast Atlantic collide. Mathias, a young Norwegian born at the exact moment man first walked on the moon, aspires only to be a content number two—just like Buzz Aldrin. But after his life unravels and washes him ashore in a sanctuary on the windswept archipelago, he must navigate grief, whale hunts, and unexpected kindred spirits. An immensely lyrical, witty, and life-affirming Scandinavian novel about finding peace when the spotlight is blinding.', 'Na samoj ivici svijeta leže Farska Ostrva, gdje se sudaraju smrt, ljubav i beskrajni Atlantik. Matijas, mladi Norvežanin rođen tačno u trenutku kada je prvi čovjek zakoračio na Mjesec, želi samo da bude zadovoljan kao „broj dva“ — baš poput Baza Oldrina. Međutim, kada mu se život raspadne i baci ga u neobično utočište na vjetrovitom arhipelagu, moraće da se suoči sa samim sobom i pronađe novi smisao. Izuzetno liričan, duhovit i dirljiv roman o traženju mira daleko od reflektora.', 'Щемящая, ироничная и глубокая скандинавская драма для всех, кто хоть раз мечтал остаться в тени, как Базз Олдрин.', 'A tender, melancholic, and witty Scandinavian gem for anyone who has ever dreamed of simply being a quiet number two.', 'Nježna, melanholična i duhovita skandinavska priča za svakoga ko je ikada poželio da ostane u sjenci, poput Baza Oldrina.', '/covers/DP-0303.webp', '#2c4c5e', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","friends"]', '["faroe islands","scandinavian literature","coming of age","solitude","psychology"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('блаженны-мертвые-304', 'DP-0304', 'Блаженны мертвые', 'Handling the Undead', 'Blagosloveni mrtvi', 'Юн Айвиде Линдквист', 'John Ajvide Lindqvist', 'Jon Ajvide Lindkvist', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'Шведский писатель Юн Айвиде Линдквист - признанный мастер жанра ужасов. По роману "Блаженны мертвые" снимает фильм государственный телеканал Швеции, за права на экранизацию вели борьбу 16 крупнейших продюсеров. Стокгольм, середина августа. Небывалая жара в сочетании с электромагнитными излучениями влечет за собой необъяснимый феномен - тысячи усопших неожиданно возвращаются к жизни. Как быть их близким? Любовь и простые человеческие отношения подвергаются жестоким испытаниям перед лицом иррационального. Перевод со шведского Натальи Банке.', 'Stockholm, mid-August. During an oppressive heatwave combined with an unexplained electromagnetic anomaly, thousands of recently deceased suddenly reawaken and return home. Instead of ravenous monsters, these undead are confused and silent remnants of loved ones, forcing grieving families into an agonizing test of love, ethics, and acceptance in the face of the unexplainable.', 'Stokholm, sredina avgusta. Tokom nezapamćene ljetnje žege i neobjašnjivog elektromagnetnog talasa, hiljade preminulih iznenada oživljava. Ovi „povratnici” nijesu krvožedna čudovišta, već nijeme sjenke onih koji su otišli, primoravajući svoje voljene na teška moralna i emotivna iskušenja pred zagonetkom smrti i nepokolebljive ljubavi.', 'Пронзительная скандинавская драма под маской зомби-хоррора о том, что происходит, когда ушедшие возвращаются, а горе сталкивается с невозможностью отпустить.', 'A haunting Scandinavian masterpiece disguised as a zombie tale, asking what truly happens when grief is confronted with the impossible return of those we lost.', 'Dirljiva skandinavska drama prerušena u horor o zombijima, koja duboko preispituje šta se događa kada tuga sretne nemoguć povratak onih koje smo voljeli.', '/covers/DP-0304.webp', '#3b4a59', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["spooky","real"]', '["horror","grief","scandinavian literature","zombies","psychological drama"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('преимущества-и-недостатки-суще-305', 'DP-0305', 'Преимущества и недостатки существования', 'The Advantages and Disadvantages of Existence', 'Prednosti i mane postojanja', 'Вигдис Йорт', 'Vigdis Hjorth', 'Vigdis Hjorth', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'Жизнь прекрасна и удивительна! Все будет хорошо! - уверяет нас Нина, героиня романа "Преимущества и недостатки существования". Шумит море, светит солнце, вино льется рекой, праздник жизни не прекращается ни на мгновение. Давайте радоваться, напиваться, рвать на себе рубашку, а наутро просыпаться в кустах рододендрона! Щемящее и пронзительное счастье от короткого норвежского лета, море и солнце, хруст мидий под ногами и радость жизни буквально во всем: начиная с безмолвного созерцания суровых камней и заканчивая гастрономическим беспределом - вот о чем эта книга. Норвежская писательница Вигдис Йорт знает секрет счастливой жизни. Если вы хотите приблизиться к пониманию самых главных преимуществ и недостатков существования, эта книга для вас. Переводчик: Вера Дьяконова.', 'Life is wonderful and amazing, and everything will turn out fine—at least that is what Nina, the heroine of Vigdis Hjorth’s novel, insists. The sea whispers, the sun shines, wine flows generously, and the feast of life never stops, even if you wake up the next morning nestled in the rhododendron bushes. A bittersweet, piercing ode to a fleeting Norwegian summer, sensory hedonism, and quiet coastal rocks, this frank novel explores the tangled joys and hardships of simply being alive.', 'Život je divan i čudesan, a na kraju će sve biti u redu – uvjerava nas Nina, junakinja romana Vigdis Hjorth. More šumi, sunce grije, vino teče u potocima, a slavlje života ne prestaje ni na tren, čak i ako se jutro dočeka u grmu rododendrona. Dirljiva i iskrena oda kratkom norveškom ljetu, čistom hedonizmu i stijenama okupanim morem, ovaj roman istražuje sve skrivene prednosti i neizbježne mane samog postojanja.', 'Остроумный и пьянящий гимн короткому скандинавскому лету, где бурный гедонизм и тихое созерцание камней мирят нас со всеми превратностями бытия.', 'A delightfully dizzying and honest ode to wine, sea breezes, and waking up in bushes, reminding us why living is entirely worth the trouble.', 'Duhovita, opojna i iskrena oda ljetu i vinu koja nas podsjeća zašto vrijedi prigrliti sav haos i ljepotu življenja.', '/covers/DP-0305.webp', '#b85358', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","funny"]', '["norwegian literature","summer","existentialism","hedonism","humor"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('благословенное-дитя-306', 'DP-0306', 'Благословенное дитя', 'A Blessed Child', 'Blagosloveno dijete', 'Лин Ульман', 'Linn Ullmann', 'Lin Ulman', '', 'Текст', NULL, NULL, 16, 99, 'adult', 'Лин Ульман могла бы легко добиться успеха, сыграв на имени любого из родителей, но вместо этого она извлекла уроки из их творчества. "Нью-Йорк таймс" Лин Ульман - талантливая норвежская писательница, литературный критик, дочь знаменитого режиссера Ингмара Бергмана и актрисы Лив Ульман. "Благословенное дитя" - один из лучших романов писательницы. Три сестры, Эрика, Лаура и Молли, собираются навестить отца, уединенно живущего на острове. Они не видели его много лет, и эта поездка представляется им своего рода прощанием: отец стар и жить ему осталось недолго. Сестры, каждая по-своему, вспоминают последнее лето, проведенное ими на острове. Именно тогда и произошел трагический и таинственный случай, в котором замешаны они все.', 'Three half-sisters—Erika, Laura, and Molly—travel to a remote Baltic island to visit their aging, eccentric father for what feels like a final farewell. Each sister carries her own fragmented memories of one fateful summer twenty-five years ago, gradually revealing a tragic secret that marked their lives forever.', 'Tri polusestre — Erika, Laura i Moli — odlaze na zabačeno ostrvo u posjetu ostarjelom ocu, svjesne da je to možda njihov posljednji susret. Svaka od njih na svoj način oživljava uspomene na jedno presudno ljeto iz mladosti, polako otkrivajući tragičnu i potisnutu tajnu koja ih je zauvijek povezala.', 'Тонкая скандинавская психологическая драма о трёх сёстрах, хрупкой памяти и невысказанной тайне северного острова.', 'A poignant Scandinavian drama about three sisters, fragile memory, and an unspoken secret buried on a northern island.', 'Dirljiva skandinavska drama o tri sestre, krhkom sjećanju i prećutanoj tajni jednog sjevernog ostrva.', '/covers/DP-0306.webp', '#4b6577', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["family drama","scandinavian literature","sisters","memory","island life"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прежде-чем-ты-уснешь-307', 'DP-0307', 'Прежде чем ты уснешь', 'Before You Sleep', 'Prije nego što zaspiš', 'Лин Ульман', 'Linn Ullmann', 'Lin Ulman', '', 'Слово', NULL, NULL, 16, 99, 'adult', 'Роман норвежской писательницы Лин Ульман, дочери знаменитого режиссера Ингмара Бергмана и актрисы Лив Ульман, - это рассказ юной и сумасбродной Карин Блум о себе и о своей необыкновенной семье. Фантазия, правда и мистика так тесно переплелись в ее ироничной истории, что провести между ними грань уже невозможно.', 'The debut novel by Norwegian author Linn Ullmann, daughter of Ingmar Bergman and Liv Ullmann, tells the story of the eccentric young Karin Blom and her extraordinary family. Fantasy, truth, and subtle mysticism intertwine in Karin''s witty narrative so seamlessly that reality and invention become one.', 'Debi roman norveške autorke Lin Ulman, kćerke Ingmara Bergmana i Liv Ulman, priča je ekscentrične mlade Karin Blom o sebi i svojoj neobičnoj porodici. Fantazija, istina i dašak misticizma prepliću se u ovoj duhovitoj priči tako vješto da je nemoguće razdvojiti stvarnost od izmišljotine.', 'Ироничная, тонкая и немного сумасбродная семейная сага о любви, выдумках и взрослении, от которой невозможно оторваться перед сном.', 'An ironic, delicate, and wonderfully eccentric family saga where memories and tall tales blend into pure bedtime magic.', 'Ironična, nježna i divno ekscentrična porodična saga u kojoj se sjećanja i mašta stapaju u pravu književnu čaroliju.', '/covers/DP-0307.webp', '#2d3a4b', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","magic"]', '["norwegian literature","family saga","memories","eccentric family","coming of age"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('апрельская-ведьма-308', 'DP-0308', 'Апрельская ведьма', 'April Witch', 'Aprilska vještica', 'Майгуль АКсельсон', 'Majgull Axelsson', 'Majgul Akselson', '', 'Корпус', NULL, NULL, 16, 99, 'adult', 'Роман "Апрельская ведьма" принес своему автору, писательнице и журналистке Майгулль Аксельссон, головокружительный успех во всем мире, а также премию имени Августа Стриндберга - главную литературную награду Швеции. Книгу перевели на пятнадцать языков, а тиражи ее на сегодняшний день исчисляются семизначными цифрами. В центре пронзительной современной драмы - переплетение судеб четырех женщин, четырех сестер. Первая из них с рождения прикована к постели, другая - успешный врач, третья - ученый-физик, четвертая - конченая наркоманка... Парализованная, брошенная матерью на попечение социальных служб Дезире - из тех, кого зовут ведьмами. Она наделена острым умом и удивительной способностью летать сквозь время и пространство, вмешиваясь в жизнь тех, кто ей дорог или, напротив, причинил зло. "Одна из моих сестер украла жизнь, которая предназначалась мне. Я хочу знать, которая из них", - такова цель лишенной всех земных радостей Дезире. Борьба за выживание, взросление, преодоление одиночества и поиск любви - вот тот эмоциональный фон, на котором разворачивается захватывающая фантасмагория, где реальное и бытовое органично уживается со сверхъестественным и волшебным.', 'Desirée lies severely disabled in an institution, abandoned as a child, but possessing a fierce mind and the supernatural gift of an ''April witch''—the ability to soar through space, see through others'' eyes, and subtly alter their fates. Knowing that her mother fostered three healthy girls in her place, Desirée sets out to discover which sister stole the life meant to be hers. A mesmerizing Swedish masterpiece blending searing social realism with dark psychological fantasy.', 'Desire leži u bolničkoj postelji, nepokretna i odbačena, ali posjeduje zadivljujući um i natprirodni dar aprilske vještice — sposobnost da leti kroz vrijeme i prostor i ulazi u tuđe živote. Saznavši da je njena majka usvojila tri zdrave djevojčice umjesto nje, ona kreće u potragu da otkrije koja joj je sestra ukrala sudbinu. Ova nagrađivana švedska drama majstorski prepliće surovu realnost, porodične traume i elemente magijskog realizma.', 'Мощная скандинавская сага о судьбе, зависти и невидимых нитях, связывающих четырех непохожих сестер.', 'A gripping Scandinavian masterpiece where raw family drama meets dark magic realism in a story of stolen lives.', 'Moćna skandinavska priča o sudbini, zavisti i nevidljivim nitima koje povezuju četiri sasvim različite sestre.', '/covers/DP-0308.webp', '#2c4059', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["magic","real","spooky"]', '["magic realism","family drama","scandinavian literature","sisters","dark mystery"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('укусы-рассвета-309', 'DP-0309', 'Укусы рассвета', 'Bites of the Dawn', 'Ugrizi zore', 'Тонино Бенаквиста', 'Tonino Benacquista', 'Tonino Benakvista', '', 'Флюид', 2006, '5-98358-116-3', 16, 99, 'adult', 'Популярный французский писатель Тонино Бенаквиста ("Сага", "Охота на зайца" и "Три красных квадрата на черном фоне") знакомит нас в этой книге с закрытой для посторонних глаз ночной жизнью Парижа. Социальная сатира с любопытными зарисовками нравов "по ту сторону дня" лихо закручена в криминальную авантюру с динамичным и непредсказуемым развитием сюжета - от Дракулы и Фрейда до американской мафии. Главные герои романа - Антуан и Бертран - молодые парижские безработные, избравшие путь "профессиональных тусовщиков-халявщиков". Впечатления, блеск, причастность к успеху - все это оказывается доступным при ночном образе жизни. Вот только ночь - это особое измерение, параллельный мир, в котором живут другие люди. И порой с наступлением утра ночные кошмары превращаются в дневную реальность. Французская пресса назвала роман анти-яппи-манифестом 90-х годов. Роман экранизирован в 2001 году, режиссер Антуан де Кон, в главных ролях Гийом Кане, Жерар Ланвен, Азиа Ардженто.', 'Step into the glamorous yet sinister nocturnal underbelly of Paris alongside Antoine and Bertrand, two professional party-crashers surviving on charm and free champagne. When an eccentric night-owl offers Antoine a mysterious assignment, the carefree thrill of Parisian nightlife spirals into a gritty crime caper featuring dark secrets, oddball gangsters, and dawn''s unforgiving bite. A biting 1990s social satire and hard-boiled noir.', 'Zavirite u glamurozno, ali mračno podzemlje noćnog Pariza sa Antoanom i Bertranom, dvojicom profesionalnih žurka-slepih putnika koji žive od šarma i besplatnog šampanjca. Kada ekscentrični noćni tip ponudi Antoanu tajanstveni zadatak, bezbrižna noćna avantura pretvara se u opasnu kriminalističku zbrku prepunu čudnih gangstera i osvete koja vreba u zoru. Oštra satira devedesetih i brzi noir triler.', 'Ироничный парижский нуар о том, как опасно заигрывать с ночью, если ты всего лишь беззаботный охотник за бесплатным шампанским.', 'A razor-sharp Parisian noir proving that chasing free champagne into the dead of night can quickly turn into a dangerous game of survival.', 'Ironičan pariski noar o tome koliko je opasno flertovati s noćnim životom ako si samo bezbrižni lovac na besplatan šampanjac.', '/covers/DP-0309.webp', '#2d1629', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["adventure","friends","real"]', '["noir","paris","nightlife","crime","satire"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мясорубка-для-маленьких-девоче-310', 'DP-0310', 'Мясорубка для маленьких девочек', 'The Meat Grinder for Little Girls', 'Mašina za mljevenje malih djevojčica', 'Тонино Бенаквиста', 'Tonino Benacquista', 'Tonino Benakvista', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'Тонино Бенаквиста (р. 1961) - один из самых популярных европейских писателей современности. Француз итальянских кровей, литературовед и киновед по образованию, кем он только ни работал - проводником поезда, декоратором, продавцом пиццы. В 24 года опубликовал свой первый роман, к 30 уже имел в своем активе несколько литературных премий. На сегодня по праву может гордиться завидной коллекцией наград в области литературы и кино, мировой известностью, а главное - неповторимым "фирменным" стилем.', 'A collection of sharp, eccentric, and darkly humorous stories by acclaimed French-Italian author Tonino Benacquista. With his signature noir flair and keen eye for human quirks, he turns everyday situations into gripping, ironic, and cinematic tales.', 'Zbirka oštrih, ekscentričnih i crnohumornih priča priznatog francusko-italijanskog pisca Tonina Benakviste. Sa prepoznatljivim noar stilom i oštrim okom za ljudske neobičnosti, Benakvista svakodnevne situacije pretvara u napete, cinične i filmski uzbudljive zaplete.', 'Остроумная, дерзкая и кинематографичная проза для взрослых читателей, ценящих французский нуар и ироничный черный юмор.', 'A witty, sharp, and cinematic collection for adult readers who relish French noir and audacious dark humor.', 'Duhovita, oštra i filmski dinamična proza za odrasle koji cijene francuski noar i smjeli crni humor.', '/covers/DP-0310.webp', '#7d232c', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","spooky","real"]', '["short stories","french literature","noir","dark humor","irony"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('а-еще-я-танцую-311', 'DP-0311', 'А еще я танцую', 'And I Dance, Too', 'I još plešem', 'Жан-Клод Мурлева, Анн-Лор Бонду', 'Jean-Claude Mourlevat, Anne-Laure Bondoux', 'Žan-Klod Murleva, An-Lor Bondu', '', 'Синдбад', NULL, NULL, 16, 99, 'adult', 'Однажды утром известный писатель, лауреат Гонкуровской премии Пьер-Мари Сотто находит в своем почтовом ящике толстый пакет. Очередная рукопись неизвестного графомана? Пьер-Мари никогда не читает чужих рукописей! Он собирается отослать пакет отправителю, но там нет обратного адреса, только электронная почта некой Аделины Пармелан. Чтобы узнать почтовый адрес, Пьер-Мари пишет Аделине письмо, получает немного странный ответ, пишет новое, получает еще один ответ и... постепенно втягивается в переписку, которая скоро перестает быть формальной и захватывает обоих участников. Загадочный пакет так и лежит нераскрытым на полке книжного шкафа, словно дожидаясь, когда писатель, переживающий после таинственного исчезновения жены жестокий личный и творческий кризис, очнется от тоски и вновь поверит, что жизнь прекрасна. "А еще я танцую" - написанный "в четыре руки" трогательный и остроумный роман о потерянной и вновь обретенной любви, о двух одиноких сердцах, которые из статистов вдруг превращаются в главных героев захватывающей драмы.', 'One morning, celebrated Goncourt Prize-winning author Pierre-Marie Sotto finds a bulky envelope in his mailbox. Vowing never to read unsolicited manuscripts, he emails the sender, Adeline Parmelan, asking for a return address. But one quick query sparks an eccentric reply, followed by another, weaving into an irresistible email exchange between two wounded souls. As the unopened package sits quietly on a shelf, Pierre-Marie gradually awakens from creative paralysis and grief. Written collaboratively with charm, wit, and tenderness, this epistolary novel celebrates healing, unexpected friendship, and the joy of rediscovering life.', 'Jednog jutra, proslavljeni pisac i dobitnik Gonkurove nagrade Pjer-Mari Soto u svom poštanskom sandučetu pronalazi debelu kovertu. Odlučan da ne čita rukopise nepoznatih autora, piše pošiljaocu, Adelin Parmelan, kako bi saznao adresu za povratak. No, kratka poruka pokreće neobičnu prepisku koja brzo prerasta u duboku i duhovitu vezu dvoje usamljenih ljudi. Dok tajanstveni paket i dalje stoji neotvoren na polici, Pjer-Mari polako izlazi iz stvaralačke i lične krize. Pisan u četiri ruke, ovo je dirljiv i iskričav epistolarni roman o gubicima, novim počecima i ponovnom otkrivanju radosti života.', 'Искрометный роман в письмах, который доказывает: иногда одно случайное электронное письмо способно вытащить сердце из долгой спячки.', 'A sparkling novel in emails that proves sometimes a single accidental message can coax a bruised heart back into the dance of life.', 'Iskričav roman u pismima koji dokazuje da samo jedna slučajna poruka može probuditi usamljeno srce i vratiti ga u ples života.', '/covers/DP-0311.webp', '#d97736', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","friends","funny"]', '["epistolary novel","letters","french literature","healing","second chances"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('долгое-падение-312', 'DP-0312', 'Долгое падение', 'A Long Way Down', 'Dug put do dna', 'Ник Хорнби', 'Nick Hornby', 'Nik Hornbi', '', 'Амфора', NULL, NULL, 16, 99, 'adult', 'Смешной, грустный и глубоко трогательный роман "Долгое падение" задает нам важные вопросы: о жизни и смерти, о незнакомцах и дружбе, о любви и боли, а также о том, сможет ли каждый из четырех неудачников разглядеть себя сквозь долгую, темную ночь души.', 'Funny, heartbreaking, and deeply moving, ''A Long Way Down'' asks essential questions about life and death, strangers and friendship, love and pain, following four unlikely misfits through the darkest night of their souls.', 'Duhovit, dirljiv i gorko-sladak roman ''Dug put do dna'' postavlja suštinska pitanja o životu i smrti, strancima i prijateljstvu, ljubavi i bolu, prateći četiri slučajna prolaznika kroz njihovu najmračniju noć.', 'Что делать, если четверо незнакомцев встречаются на крыше в новогоднюю ночь? Передумать прыгать, поговорить по душам и заказать пиццу!', 'What happens when four strangers meet on a London rooftop on New Year''s Eve? They rethink their dramatic plans, talk it out, and find unexpected reasons to live.', 'Šta se desi kad se četvoro neznanaca sretne na krovu u novogodišnjoj noći? Odlože dramatične planove, porazgovaraju od srca i pronađu razlog za život.', '/covers/DP-0312.webp', '#2c3e50', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","friends","real"]', '["black humor","friendship","british literature","life crisis","new year"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пианисты-313', 'DP-0313', 'Пианисты', 'To Music', 'Pijanisti', 'Кетиль Бьорнстад', 'Ketil Bjørnstad', 'Ketil Bjernstad', '', 'КомпасГид', NULL, NULL, 16, 99, 'adult', 'Роман "Пианисты" норвежского писателя Кетиля Бьёрнстада открывает малознакомый нам мир, где музыка похожа на спорт, где важны техника, выносливость и амбиции, мир, где малейшая ошибка может стать фатальной… 15-летний пианист Аксель Виндинг своей любовью к музыке обязан матери. Они проводят вечера вместе, слушая концерты классической музыки, пойманные на плохоньком радиоприемнике. Их семья небогата, но мама готова пойти на все ради того, чтобы сын стал выдающимся пианистом. Когда внезапно она погибает, Аксель бросает школу, чтобы все силы отдать подготовке к конкурсу молодых пианистов в Осло. Но в этом он не уникален. Среди горстки отобранных для участия в конкурсе учеников оказывается и Аня Скууг - соседка, в которую он влюблен. На молодых пианистов давит многое: воля родителей, самолюбие преподавателей и - самое главное - их собственные амбиции.', 'Norwegian author and pianist Ketil Bjørnstad reveals a ruthless world where classical music demands the stamina of an extreme sport, and where a single slip can ruin everything. Fifteen-year-old Aksel Vinding owes his devotion to music to his mother. Following her sudden death, Aksel drops out of school to pour every ounce of energy into preparing for a prestigious piano competition in Oslo. Among his fierce competitors is Anja Skoog, the neighbor he secretly loves. Caught between parental expectations, tyrannical mentors, and overwhelming personal ambition, these young prodigies learn the true cost of perfection.', 'Roman norveškog pisca i muzičara Ketila Bjernstada otvara nemilosrdan svijet u kojem je klasična muzika poput vrhunskog sporta — gdje su presudne tehnika, izdržljivost i ambicija, a i najmanja greška može biti kobna. Petnaestogodišnji Aksel Vinding duguje strast prema klaviru svojoj majci. Nakon njene iznenadne pogibije, Aksel napušta školu kako bi se potpuno posvetio pripremi za takmičenje mladih pijanista u Oslu. Među rijetkim izabranim talentima nalazi se i Anja Skug, djevojka iz susjedstva u koju je zaljubljen. Mlade umjetnike pritiska teret roditeljske volje, sujeta profesora i sopstvene razorne ambicije.', 'Пронзительный роман взросления о музыке, цене амбиций и первой любви, где клавиши ранят острее лезвия.', 'A gripping, lyrical coming-of-age story where classical music is a high-stakes arena and piano keys cut deeper than blades.', 'Dirljiv i dramatičan roman o odrastanju uz klavir, cijeni umjetnosti i prvoj ljubavi koja gori jače od ambicije.', '/covers/DP-0313.webp', '#233142', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["classical music","coming of age","norway","rivalry","drama"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('река-314', 'DP-0314', 'Река', 'The River', 'Rijeka', 'Кетиль Бьорнстад', 'Ketil Bjørnstad', 'Ketil Bjernstad', '', 'КомпасГид', NULL, NULL, 16, 99, 'adult', '"Река" норвежца Кетиля Бьёрнстада - долгожданное продолжение "Пианистов", истории об Акселе Виндинге, подающем надежды музыканте, чье упорство и воля к победе по праву достойны восхищения. Ему уже восемнадцать, и он все еще горюет о потере любимой девушки Ани, в то же время он окончательно определился с целью жизни и теперь устремляется по намеченному пути, с головой погрузившись в подготовку к дебютному концерту. Но в жизни есть две вещи, с которыми никогда не стоит торопиться: коньяк и любовь, - и теперь Аксель научился чувствовать это. Он распробовал вкус жизни: терпкий, порой сладковатый, иногда с горчинкой. Он уже не нетерпеливый мальчишка, он - сильная личность, к нему тянутся сильные женщины, он отдается чувствам и готов принять на себя ответственность. В "Реке" Брамс звучит одновременно с Джони Митчелл, герои обсуждают войну во Вьетнаме, независимость женщин и их право на аборт, а Бетховен, Бах и Шопен смешиваются с искренним и тревожным произведением самого Акселя, который пытается удержаться на плаву в водовороте жизни.', '"The River" by Norwegian author Ketil Bjørnstad is the long-awaited sequel to "To Music" ("The Pianists"), continuing the story of young pianist Aksel Vinding. Now eighteen, Aksel is still grieving the tragic loss of his beloved Anja while intensely preparing for his debut concert. Caught between the disciplined world of Brahms, Bach, and Chopin and the turbulent cultural shifts of the late 1960s—from Joni Mitchell to protests against the Vietnam War—Aksel navigates passion, independence, and the overwhelming current of growing up.', '"Rijeka" norveškog pisca Ketila Bjernstada dugo je očekivani nastavak romana "Pijanisti", priče o mladom pijanisti Akselu Vindigu. Sa osamnaest godina, dok još tuguje za voljenom Anjom, Aksel se potpuno posvećuje pripremama za svoj debitantski koncert. Između svijeta klasične muzike i društvenih previranja kasnih šezdesetih godina, on spoznaje opor, sladak i gorak ukus života, učeći kako da pliva u snažnim virovima ljubavi, umjetnosti i odrastanja.', 'Пронзительный скандинавский роман о взрослении, музыке и любви, где под звуки рояля рождается настоящая зрелость.', 'A poignant Nordic novel about music, passion, and turbulent youth, charting the fragile yet powerful current of growing up.', 'Dirljiva skandinavska priča o muzici i strasti, đe se pod zvucima klavira rađa prava životna zrelost.', '/covers/DP-0314.webp', '#2c4a6f', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["music","piano","coming-of-age","norway","relationships"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дама-из-долины-315', 'DP-0315', 'Дама из долины', 'The Lady in the Valley', 'Dama iz doline', 'Кетиль Бьорнстад', 'Ketil Bjørnstad', 'Ketil Bjernstad', '', 'КомпасГид', NULL, NULL, 16, 99, 'adult', '"Дама из Долины" норвежца Кетиля Бьёрнстада - заключительная часть трилогии об Акселе Виндинге, выдающемся музыканте, одним своим дебютом сорвавшем главный куш - славу и признание критиков. В тот день, убрав с рояля дрожащие руки, он стал знаменитым. Его ждут лучшие концертные залы Европы, импресарио и педагог составляют такую программу, которая должна сохранить его в вечности. Самый молодой, самый талантливый, самый смелый и самый несчастный. В день его дебюта, ровно тогда, когда его пальцы чувственно скользили по черно-белым клавишам рояля, его жена Марианне покончила с собой… Акселю вот-вот исполнится двадцать, в его биографии это уже третья трагическая потеря. И кажется, что с этим водоворотом он уже не сможет справиться. Попытка самоубийства, много алкоголя, очередной болезненный роман и надрывный Рахманинов. Он уезжает из суетного Осло, в снега, на границу с Россией, туда, где люди живут, растворившись в безвременье северного сияния. Удастся ли Акселю выбраться из цепких лап прошлого? Проходит много месяцев, и вот в программе светской столичной жизни вновь Аксель Виндинг…', 'The Lady in the Valley is the powerful conclusion to Ketil Bjørnstad''s acclaimed trilogy about young piano prodigy Aksel Vinding. At barely twenty, Aksel has already gained international renown and endured devastating loss—culminating in his wife''s suicide on the night of his triumphant debut. Spiraling through grief, alcohol, and the tempestuous music of Rachmaninoff, Aksel flees bustling Oslo for the frozen northern frontier. Surrounded by silence and the northern lights, he seeks redemption and the courage to touch the piano keys once more.', '„Dama iz doline” je završni dio čuvene trilogije Ketila Bjernstada o mladom pijanističkom virtuozu Akselu Vindingu. Sa nepunih dvadeset godina, Aksel stiče svjetsku slavu, ali i doživljava razorne lične tragedije — uključujući samoubistvo supruge u noći njegovog trijumfa. Toneći u očaj, alkohol i strastvene akorde Rahmanjinova, on bježi iz Osla na daleki, zaleđeni sjever. U tišini snijega i polarne svjetlosti traži mir i snagu da se ponovo vrati muzici i životu.', 'Пронзительный скандинавский роман о музыке, горечи утрат и исцеляющей силе искусства посреди северных снегов.', 'A poignant Scandinavian novel about musical genius, heartbreak, and finding the will to live again amidst northern snows.', 'Dirljiv skandinavski roman o muzičkom geniju, bolnim gubicima i iscjeljujućoj snazi umjetnosti usred polarnih snjegova.', '/covers/DP-0315.webp', '#23395d', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["piano","scandinavian literature","coming of age","music","drama","norway"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('странники-в-ночи-316', 'DP-0316', 'Странники в ночи', 'Strangers in the Night', 'Stranci u noći', 'Марк Ламброн', 'Marc Lambron', 'Mark Lambron', '', 'Флюид / FreeFly', 2004, '5-98358-020-5', 16, 99, 'adult', 'История легендарной эпохи, ярких судеб и большой любви. Роман "Странники в ночи" переносит нас в самую гущу культурной жизни 60-70-х годов, воссоздавая противоречивый дух и колорит того времени.', 'A chronicle of a legendary era, turbulent destinies, and an unforgettable love story. The novel plunges the reader into the heart of the cultural whirlwind of the 1960s and 70s, capturing the contradictory, electric spirit of a vibrant generation.', 'Hronika jedne legendarne epohe, burnih sudbina i nezaboravne ljubavi. Roman nas uvodi u samo središte kulturnog života šezdesetih i sedamdesetih godina, oživljavajući kontradiktorni duh i puls tog vremena.', 'Изысканный роман для родителей о бурной богемной эпохе 60-х и 70-х, где стиль, музыка и ностальгия сплетаются в чарующую историю.', 'A sophisticated Parisian dive into the electric bohemian spirit of the 60s and 70s, perfect for grown-ups seeking vintage glamour and longing.', 'Prefinjen roman za roditelje o boemskom duhu šezdesetih i sedamdesetih, gdje se stil, muzika i nostalgija prepliću u neodoljivu priču.', '/covers/DP-0316.webp', '#2c3e50', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["bohemia","1960s","love story","french literature","nostalgia"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('человек-который-спит-317', 'DP-0317', 'Человек, который спит', 'A Man Asleep', 'Čovjek koji spava', 'Жорж Перек', 'Georges Perec', 'Žorž Perek', '', 'флюид', NULL, NULL, 16, 99, 'adult', 'Третье по счету произведение знаменитого французского писателя Жоржа Перека (1936 - 1982) "Человек, который спит", было опубликовано накануне революционных событий 1968 года во Франции. Причудливая хроника отторжения внешнего мира и медленного погружения в полное отрешение, скрупулезное описание постепенного ухода от людей и вещей в зону "риторических мест безразличия" может восприниматься как программный манифест целого поколения, протестующего против идеалов общества потребления, и как автобиографическое осмысление личного утопического проекта. "За виртуозной игрой Перека с буквами и словами, за тонкой пародией, за бурлескной стилизацией стоит не только осмысление многовековой традиции, не только развенчивающее и развинчивающее новаторство - здесь и муки самоопределения, и вся сложность быстро меняющегося мира, который требует постоянно искать и находить новые средства выражения". Перевод с французского Валерия Кислова.', 'Written on the eve of the May 1968 French student protests, Georges Perec''s hypnotic existential novella chronicles a young student''s radical withdrawal from the world. Refusing to take his exams or bow to the ambitions of modern consumer society, the protagonist retreats into quiet, ascetic indifference, drifting through the streets of Paris in search of utter detachment.', 'Napisana uoči studentskih protesta u Francuskoj 1968. godine, ova hipnotična egzistencijalistička novela Žorža Pereka prati mladog studenta koji bira radikalno povlačenje iz svijeta. Odbijajući ispite i ambicije potrošačkog društva, junak tone u asketsku ravnodušnost i besciljno luta pariskim ulicama, istražujući granice unutrašnje slobode i otuđenja.', 'Гипнотический путеводитель по искусству замирания и побега от суеты — для каждого взрослого, кто хоть раз мечтал просто не вставать с кровати.', 'A hypnotic, beautifully written ode to radical indifference — for any adult who has ever wished they could just stay in bed and let the world pass by.', 'Hipnotična oda radikalnoj ravnodušnosti i povlačenju u tišinu — za svakog odraslog koji je bar jednom poželio da ostane u krevetu i pusti svijet da prođe.', '/covers/DP-0317.webp', '#3f4a59', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["french literature","existentialism","solitude","paris","classic"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('черная-скрипка-318', 'DP-0318', 'Черная скрипка', 'The Black Violin', 'Crna violina', 'Максанс Фермин', 'Maxence Fermine', 'Maksans Fermin', '', 'симпозиум', NULL, NULL, 16, 99, 'adult', 'Максанс Фермин (род. в 1968) принадлежит к известнейшим французским авторам. Венеция, музыка и любовь - таковы составляющие одного из самых романтических его произведений "Черная скрипка" (1999).', 'Maxence Fermine is one of France''s most celebrated contemporary authors. Venice, music, and elusive love are the timeless threads woven into ''The Black Violin'' (1999), one of his most delicate, poetic, and enchanting novels.', 'Maksans Fermin spada među najpoznatije savremene francuske pisce. Venecija, muzika i tajanstvena ljubav čine suštinu njegovog poetskog i duboko romantičnog romana „Crna violina” (1999).', 'Тонкая и завораживающая притча о музыке, роковой страсти и тайне старинного инструмента среди туманов Венеции.', 'A haunting, lyrical novella of music, obsession, and secrets wrapped in the misty waterways of Venice.', 'Prefinjena i očaravajuća priča o muzici, strasti i tajnama skrivenim u maglama mistične Venecije.', '/covers/DP-0318.webp', '#282a36', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["magic","real"]', '["music","venice","violin","french literature","romance"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('с-ними-по-хорошему-нельзя-319', 'DP-0319', 'С ними по-хорошему нельзя', 'We Always Treat Women Too Well', 'S njima se ne može na lijep način', 'Раймон Кено', 'Raymond Queneau', 'Raymond Queneau', '', 'симпозиум', NULL, NULL, 16, 99, 'adult', 'Наследие знаменитого французского писателя Раймона Кено (1903-1976) включает в себя три произведения, опубликованные им под псевдонимом (якобы) существующей ирландской писательницы Салли Мара. Два из них - исторически не вполне корректный роман "С ними по-хорошему нельзя" (1947), посвященный дублинскому Пасхальному восстанию 1916 года, и полная трагизма автобиография "Интимный дневник Салли Мара" (1950) - вошли в эту книгу.', 'The legacy of celebrated French author Raymond Queneau includes three scandalous works published under the guise of fictional Irish writer Sally Mara. This volume brings together two of them: the delightfully irreverent, satirical novel ''We Always Treat Women Too Well'' (1947), set during the 1916 Dublin Easter Rising, and the tragicomic parody ''The Intimate Diary of Sally Mara'' (1950).', 'Književno nasljeđe proslavljenog francuskog pisca Remona Kenoa obuhvata i djela objavljena pod maskom navodne irske autorke Sali Mare. Ova knjiga donosi dva takva bisera: drski, satirični roman ''S njima se ne može na lijep način'' (1947), smješten u dane Uskršnjeg ustanka u Dablinu 1916. godine, i tragikomični ''Intimni dnevnik Sali Mare'' (1950).', 'Блестящая литературная мистификация мэтра французского авангарда — дерзкая, гомерически смешная и полная парадоксов.', 'A brilliant literary hoax from the master of French wordplay, packed with biting satire, absurd twists, and scandalous fun.', 'Briljantna književna mistifikacija majstora francuske avangarde — drska, urnebesno duhovita i puna neodoljivih paradoksa.', '/covers/DP-0319.webp', '#8c2d19', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["funny","adventure"]', '["satire","french literature","humor","parody","historical fiction"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('команда-320', 'DP-0320', 'Команда', 'The Crew', 'Ekipa', 'Дуги Бримсон', 'Dougie Brimson', 'Dugi Brimson', '', 'Аркадия', NULL, NULL, 16, 99, 'adult', 'Английский писатель Дуги Бримсон, футбольный болельщик со стажем, предлагает взглянуть на мир футбольных вандалов изнутри. Триллер "Команда" - ужасающая в своей обыденности история борьбы пестрой компании английских хулсов со стражами правопорядка. Главарь одной из группировок, удачливый бизнесмен Билли Эванс, задумывает хитроумную аферу, надеясь с помощью "бойцов" обвести полицию вокруг пальца. И футбол для него - далеко не всегда на первом месте.', 'English author and seasoned football supporter Dougie Brimson offers an insider''s look into the gritty world of football hooligans. The thriller ''The Crew'' is a chilling, raw account of clashes between a notorious English firm and law enforcement. When crew leader and successful businessman Billy Evans plots an audacious scheme using his street fighters to outsmart the police, it becomes clear that football is only the opening play.', 'Engleski pisac i dugogodišnji fudbalski navijač Dugi Brimson donosi pogled iznutra u sirovi svijet fudbalskih huligana. Triler „Ekipa“ je zastrašujuća i autentična priča o sukobu ozloglašene engleske navijačke grupe sa policijom. Kada vođa ekipe i uspješan biznismen Bili Evans osmisli smjelu prevaru kako bi uz pomoć svojih uličnih boraca nadmudrio zakon, postaje jasno da fudbal nije njihova jedina igra.', 'Жёсткое, адреналиновое погружение в околофутбольную культуру Британии, где ставки куда выше забитых голов.', 'A raw, adrenaline-fueled plunge into British football hooligan culture, where the stakes run far higher than any scoreline.', 'Žestoko i puno adrenalina uranjanje u britansku navijačku kulturu, gdje su ulozi daleko veći od rezultata na terenu.', '/covers/DP-0320.webp', '#2b3a4a', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","adventure"]', '["football","thriller","crime","subcultures","britain"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('манчестерская-тусовка-321', 'DP-0321', 'Манчестерская тусовка', 'Manchester Slingback', 'Mančesterska ekipa', 'Николас Блинкоу', 'Nicholas Blincoe', 'Nikolas Blinkou', '', 'флюид', NULL, NULL, 16, 99, 'adult', '"Манчестерская тусовка" - как всегда у Блинкоу, роман очень жизненный, своего рода социальный срез современной субкультуры, предлогом для которого служит детективный сюжет. Действие происходит в двух временных пластах. Манчестерский следователь Дэйви Грин (этакий Жсглов минус романтика плюс пройдошистость и своеобразное мужланское чувство юмора) приезжает в Лондон и делает Джейку, менеджеру казино, предложение, от которого тот не сможет отказаться. Дело в том, что в начале 80-х Джейк был информатором Грина. И теперь пришла пора отдавать должок. Пласт "настоящего" перемежается сценками из прошлого Джейка и его друзей. Время и нравы изображены очень выпукло и достоверно, аж дрожь пробирает, но не от детективной интриги, а от мастерского описания язв современного общества, где понятия плохой/хороший переплетены настолько, что не всегда и разберешь. Перевод с английского Ирины Шебуковой.', 'A sharp, atmospheric crime drama and a vivid snapshot of British subcultures across two eras. When gritty Manchester detective Davey Green tracks down London casino manager Jake to call in an old informant debt from the early 1980s, past and present collide. Interweaving tension in neon-lit gaming rooms with raw flashbacks of youth, Blincoe crafts a razor-sharp social noir where the lines between good and bad are masterfully blurred.', 'Oštar i autentičan kriminalistički roman koji donosi upečatljiv društveni presjek britanske potkulture. Mančesterski inspektor Dejvi Grin dolazi u London sa ponudom koju Džejk, menadžer kazina, nikako ne može da odbije: osamdesetih godina Džejk je bio njegov doušnik, a sada je stiglo vrijeme za naplatu starih dugova. Preplićući napetu sadašnjost sa scenama iz prošlosti, Blinkou majstorski oslikava svijet u kom su granice između dobra i zla potpuno zamagljene.', 'Глубокое, хлесткое и колоритное погружение в британский нуар, где тайны рейв-прошлого настигают героев среди блеска столичных казино.', 'A gritty, razor-sharp British noir diving into murky casino deals, nostalgic subcultures, and old debts that refuse to stay buried.', 'Oštar i uzbudljiv britanski noar koji vas vodi kroz mračne tajne mančesterske scene i neonski sjaj londonskih kazina.', '/covers/DP-0321.webp', '#2c3440', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","friends"]', '["детектив","нуар","британская проза","криминал","субкультуры"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('канувшие-и-спасенные-322', 'DP-0322', 'Канувшие и спасенные', 'The Drowned and the Saved', 'Potonuli i spaseni', 'Примо Леви', 'Primo Levi', 'Primo Levi', '', 'Новое', NULL, NULL, 16, 99, 'adult', 'Примо Леви родился в 1919 году в Турине. Окончил химический факультет Туринского университета. В 1943-1945 годах - узник Освенцима. После освобождения работал химиком, занимался литературой и переводами. Автор двух автобиографических книг о лагерном опыте - "Человек ли это?.. (1947), "Передышка" (1963), нескольких романов и повестей. Покончил с собой в 1987 году.', 'Primo Levi was born in Turin in 1919 and graduated in chemistry before surviving Auschwitz (1943–1945). In this definitive and searing final work, Levi offers an unflinching philosophical exploration of memory, the moral complexities of the camps, and the fragile nature of human dignity.', 'Primo Levi je rođen 1919. u Torinu. Diplomirao je hemiju na Univerzitetu u Torinu, a od 1943. do 1945. bio je zatočenik Aušvica. U svojoj posljednjoj, beskompromisnoj knjizi, Levi nudi duboko filozofsko promišljanje o mehanizmima pamćenja, etičkim dilemama i krhkosti ljudskosti.', 'Кристально ясное, мужественное и необходимое каждому взрослому размышление о памяти, совести и границах человечности.', 'A piercing, lucid, and essential meditation on memory, morality, and the quiet depths of the human spirit.', 'Duboko, bistro i neophodno promišljanje o sjećanju, etici i granicama ljudskosti.', '/covers/DP-0322.webp', '#3e424b', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real"]', '["memoir","history","philosophy","holocaust","classic"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('роисся-вперде-323', 'DP-0323', 'Роисся вперде', 'Roissya Vperde', 'Roisja vperde', 'Олег Кашин', 'Oleg Kashin', 'Oleg Kašin', '', 'Ад маргинем', NULL, NULL, 16, 99, 'adult', 'В ночь с пятого на шестое ноября 2010 года журналист Олег Кашин был зверски избит неизвестными во дворе собственного дома. За два месяца до этого взбудоражившего всю страну события Олег прислал к нам в редакцию свою повесть "Роисся вперде". В основе ее сюжета - фантастическая история об одном эксперименте над людьми, проводимом в закрытом санатории неподалеку от Москвы. Попытка вывести в лабораторных условиях "нового человека" приводит к цепи таинственных смертей и преступлений. Прочитав повесть, читатель наверняка сможет догадаться, кто в действительности стоит за покушением на жизнь Олега Кашина.', 'In November 2010, investigative journalist Oleg Kashin was brutally attacked outside his Moscow home. Just two months prior, he completed this satirical, grotesque novella revolving around a clandestine experiment conducted in a sanatorium near Moscow. The attempt to engineer a genetically and ideologically ''new human'' triggers a chain of mysterious deaths and crimes, offering uncanny and chilling insights into modern political intrigue.', 'U novembru 2010. godine novinar Oleg Kašin brutalno je pretučen ispred svoje zgrade u Moskvi. Samo dva mjeseca prije tog događaja završio je ovu satiričnu grotesknu novelu o tajnom eksperimentu nad ljudima u zatvorenom sanatorijumu u blizini prestonice. Pokušaj stvaranja „novog čovjeka” pokreće lanac zagonetnih smrti i zločina, pružajući jezivo pronicljiv pogled u mračne mehanizme političke moći.', 'Острая политическая гротеск-антиутопия десятых годов, которая сегодня читается как жутковато-пророческий детектив.', 'A biting political satire and grotesque mystery from the 2010s that reads today like an eerily prophetic thriller.', 'Oštra politička groteska iz prošle decenije koja se danas čita kao jezivo proročanski triler.', '/covers/DP-0323.webp', '#8b2626', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["spooky","real"]', '["satire","dystopia","political fiction","mystery","grotesque"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('любовь-стратегического-назначе-324', 'DP-0324', 'Любовь стратегического назначения', 'Strategic Love', 'Ljubav strateške namjene', 'Олег Гладов', 'Oleg Gladov', 'Oleg Gladov', '', 'флюид', NULL, NULL, 16, 99, 'adult', 'Однажды каждый из нас оказывается один на один с Тьмой. Один на один потому, что общение с Тьмой - не групповое занятие... Сделать шаг или вернуться? Что там? Может быть вход? Решись. Где бы ты не находился - в кипящем мегаполисе или на замерзшем полустанке, продолжай искать свою дорогу. Не сдавайся безнадеге и беспомощности. Любовь не одолеть. Даже когда реактивные чувства разрывают тебя на миллиард маленьких осколков и каждый из них продолжает любить...', 'One day, each of us finds ourselves face-to-face with the Darkness, an encounter meant solely for one. Do you take a step forward or retreat? Wherever you are—in a throbbing metropolis or at a freezing train whistle-stop—keep searching for your way out. Never surrender to despair and helplessness, because true love cannot be defeated, even when explosive feelings shatter you into a billion pieces, every single one still fiercely in love.', 'Jednog dana svako od nas ostane sam nasamo sa Tamom, jer suočavanje s njom nije grupna aktivnost. Napraviti korak ili se povući? Gdje god da se nalaziš — u uzavreloj metropoli ili na zaleđenoj provincijskoj stanici — nastavi da tražiš svoj put. Ne predaj se beznađu, jer ljubav se ne može poraziti, čak ni kada te razorne emocije raznesu u milijardu sitnih komada od kojih svaki nastavlja da voli.', 'Проникновенная и кинематографичная проза для взрослых читателей о том, как не потерять свет и любовь посреди экзистенциального холода.', 'A poignant and cinematic read for grown-ups about holding onto warmth and love right when existential darkness seems all-consuming.', 'Dirljiva i kinematografska proza za odrasle o tome kako sačuvati svjetlost i ljubav usred egzistencijalne tame.', '/covers/DP-0324.webp', '#382d47', 'adults', 'ru', 'available', 'Категория: Художественная литература', '["real","adventure"]', '["adult fiction","love story","urban drama","existential","contemporary prose"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('pink-floyd-325', 'DP-0325', 'pink floyd', 'Pink Floyd: Inside Out', 'Pink Floyd: Lična istorija', 'Ник Мейсон', 'Nick Mason', 'Nik Mejson', '', 'Амфора', NULL, NULL, 16, 99, 'adult', 'В книге, написанной бессменным ударником "Pink Floyd" Ником Мейсоном, прослежен творческий путь великой рок-группы - от первых проб и ошибок до всемирной популярности.', 'Written by Pink Floyd''s legendary and constant drummer Nick Mason, this intimate memoir chronicles the epic creative journey of the iconic rock band—from psychedelic student trials to global superstardom.', 'Napisana od strane nezamjenjivog bubnjara Pink Floyda, Nika Mejsona, ova knjiga prati kreativni put legendarnog rok sastava — od prvih psihodeličnih eksperimenata do planetarne slave.', 'Взгляните на историю легендарных Pink Floyd из-за барабанной установки единственного музыканта, прошедшего с группой весь путь от начала и до конца!', 'Experience the legendary ride of Pink Floyd straight from behind the drum kit of the only member who lived through every chapter!', 'Doživite epsko putovanje Pink Flojda pravo iza bubnjeva jedinog člana koji je bio tu od prvog do posljednjeg akorda!', '/covers/DP-0325.webp', '#2c2438', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["real","friends"]', '["music","rock","biography","history","pink floyd"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('моррисон-326', 'DP-0326', 'Моррисон', 'Morrison', 'Morison', 'Алексей Поликовский', 'Alexei Polikovsky', 'Aleksej Polikovski', '', 'Колибри', NULL, NULL, 16, 99, 'adult', 'О Джиме Моррисоне написаны горы книг и статей, снято полдюжины художественных фильмов. Все запечатлевшие его кадры кинохроники и студенческие короткометражки собраны воедино, а сохранившиеся записи концертов "The Doors" выпущены в виде бутлегов. Многие из тех, кто имел к нему хоть какое-то отношение, опубликовали свои мемуары. И тем не менее, мы не понимаем - кем же был Моррисон на самом деле? И в чем секрет его гипнотического воздействия? Пытаясь ответить на эти вопросы, Алексей Поликовский переносится из заснеженной Москвы конца 70-х, где ему приходилось убегать от милицейских облав с подпольного рынка западных пластинок, в хиппующую Калифорнию 60-х, где на берегу теплого океана молодой бродяга Джим сочинял свои первые (и лучшие) стихи. И еще дальше - на остров Крит: здесь автор встречает грузного бородача, удивительно похожего на постаревшего Моррисона. Он или не он? Это не столь важно. Ведь волшебный билет в 68-й год - на концерт "The Doors" - уже лежит у вас под подушкой.', 'Endless books, articles, and half a dozen feature films have explored Jim Morrison. Footage, student films, and bootlegged live recordings of The Doors have all been cataloged, and nearly anyone who crossed his path penned a memoir. Yet the question lingers: who was Morrison really, and where did his hypnotic power come from? Seeking answers, Alexei Polikovsky takes readers from the snowy alleys of late 1970s Moscow—fleeing police raids at black-market vinyl spots—to sun-drenched 1960s California, where a nomadic young Jim wrote his first and finest verses, and all the way to Crete, chasing a mysterious bearded figure who looks suspiciously familiar. Ultimately, you''re holding a magical ticket straight into 1968, front row at a Doors concert.', 'O Džimu Morisonu napisane su gomile knjiga i članaka, snimljeno je pola tuceta igranih filmova. Svi arhivski snimci i studentski kratki filmovi odavno su sakupljeni, a sačuvani koncerti grupe „The Doors“ kruže na butleg izdanjima. Ipak, misterija ostaje: ko je Morison zapravo bio i u čemu se krije tajna njegovog hipnotišućeg uticaja? Tragajući za odgovorima, Aleksej Polikovski nas vodi iz snijegom pokrivene Moskve s kraja 70-ih i bjekstva od policijskih racija na tajnoj berzi ploča, pravo u hipi Kaliforniju 60-ih, a zatim i na sunčani Krit u potragu za Morisonovim duhom. Čarobna karta za koncert iz 1968. godine već vas čeka pod jastukom.', 'Захватывающее и очень личное путешествие во вселенную Джима Моррисона — от фарцовщиков советской Москвы до психоделических пляжей Калифорнии.', 'A gripping and intensely personal pilgrimage into Jim Morrison’s universe, stretching from underground vinyl hunts in Soviet Moscow to the sun-soaked shores of California.', 'Uzbudljivo i duboko lično putovanje u svijet Džima Morisona — od tajnih berzi ploča u sovjetskoj Moskvi do psihodeličnih kalifornijskih plaža.', '/covers/DP-0326.webp', '#4a2c22', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["real","adventure"]', '["the doors","jim morrison","rock music","biography","counterculture"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('последний-проклятый-поэт-327', 'DP-0327', 'Последний проклятый поэт', 'The Last Accursed Poet', 'Posljednji ukleti pjesnik', 'Джим Моррисон', 'Jim Morrison', 'Džim Morison', '', 'Ультра Культура', NULL, NULL, 16, 99, 'adult', 'Сборник посвящен жизни и поэтическому творчеству Джима Моррисона, лидера группы The Doors. Он включает переводы поэзии Моррисона и разнообразные материалы, посвященные жизни и творчеству поэта (интервью, которые давал Моррисон и музыканты его группы; литературоведческие статьи; мемуары, в т. ч. Роберта Шекли; библиографические материалы). Большая часть переводов публикуется впервые. Книга снабжена иллюстрациями.', 'This collection is dedicated to the life and poetic work of Jim Morrison, the enigmatic frontman of The Doors. It features Morrison''s poetry alongside an array of archival materials exploring his legacy: candid interviews with Morrison and his bandmates, literary essays, memoirs (including recollections by Robert Sheckley), and detailed bibliographical notes, accompanied by rare illustrations.', 'Ova zbirka posvećena je životu i pjesničkom stvaralaštvu Džima Morisona, legendarnog frontmena grupe The Doors. Knjiga sadrži prevode Morisonove poezije i raznovrsne materijale o njegovom životu: intervjue s Morisonom i muzičarima benda, književne eseje, memoare (uključujući sjećanja Roberta Šeklija) i bibliografske bilješke, obogaćene ilustracijama.', 'Погрузитесь в мистическую поэзию рок-идола шестидесятых — это не просто рок-н-ролл, а бунтарская шаманская лирика без цензуры.', 'Step into the hypnotic, raw poetic universe of the Lizard King himself—where rock and roll meets timeless counterculture mysticism.', 'Zavirite u hipnotički, sirovi poetski svijet samog Kralja guštera — mjesto gdje se rokenrol spaja s mistikom šezdesetih.', '/covers/DP-0327.webp', '#781a28', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["real","magic"]', '["poetry","rock music","the doors","biography","counterculture"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прошу-убей-меня-подлинная-исто-328', 'DP-0328', 'Прошу, убей меня! Подлинная история панк-рока в рассказах участников', 'Please Kill Me: The Uncensored Oral History of Punk', 'Molim te, ubij me: Necenzurisana usmena istorija panka', 'Легс Макнил', 'Legs McNeil', 'Legs Maknil', '', 'Альпина', NULL, NULL, 16, 99, 'adult', '"Прошу, убей меня" - первая подлинная история самого нигилистичного из всех поп-движений, всеобъемлющий отчёт о разнузданной и взрывной "эре панка" устами непосредственных участников, начиная со времён расцвета Фабрики Энди Уорхола в шестидесятые и до агонии в тисках "корпоративного рока" восьмидесятых. Лу Рид, Игги Поп, Дэвид Йохансен, Ди Ди Рамон, Нико, Патти Смит, Ричард Хелл, Малькольм Макларен и множество других культовых фигур панк-поколения говорят со страниц этой откровенной и шокирующей книги - фактически "документального романа" по формуле "секс, наркотики, рок-н-ролл".', 'The definitive, uncensored oral history of the punk movement, from the Velvet Underground and Andy Warhol''s Factory to the Ramones, Iggy Pop, and the Sex Pistols. Told directly through the voices of the musicians, poets, and insiders who lived through this explosive cultural revolution.', 'Konačna i necenzurisana usmena istorija pank pokreta, od Vorholove ''Fabrike'' i Velvet Undergrounda do Ramonsa, Igija Popa i Seks Pistolsa. Ispričana direktno kroz glasove muzičara, pjesnika i insajdera koji su proživjeli divlju eksploziju rokenrola.', 'Бескомпромиссное, дикое и невероятно живое путешествие на задворки музыкальной революции — чтение для взрослых с рок-н-роллом в сердце!', 'A raw, wild, and unapologetic ride through the birth of punk rock, told straight from the mouths of the legends who lived it.', 'Sirova, divlja i beskompromisna vožnja kroz rođenje pank roka, ispričana glasovima samih legendi koje su ga stvorile.', '/covers/DP-0328.webp', '#c2185b', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["real"]', '["punk rock","music","oral history","counterculture","rock and roll"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('майк-из-группы-зоопарк--329', 'DP-0329', 'Майк из группы "Зоопарк"', 'Mike from the Band "Zoopark"', 'Majk iz grupe "Zoopark"', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 16, 99, 'adult', 'В 1996 г. вышла книга "Майк из группы "Зоопарк" ( ее второе название - "Право на рок"). Тот, кто читал, конечно, заметил множество ошибок и опечаток, сильно испортивших впечатление. Данная книга является исправленной и дополненной. Теперь вы можете прочитать ранее нигде не опубликованные воспоминания друзей Майка и увидеть редкие фотографии.', 'In 1996, the book "Mike from the Band ''Zoopark''" (also known as "The Right to Rock") was published. This updated edition has been thoroughly corrected and expanded, offering readers previously unpublished memoirs by Mike Naumenko''s close friends alongside rare archival photographs.', 'Godine 1996. objavljena je knjiga "Majk iz grupe ''Zoopark''" (poznata i pod naslovom "Pravo na rok"). Ovo izdanje je ispravljeno i dopunjeno, te donosi ranije neobjavljena sjećanja prijatelja Majka Naumenka i rijetke arhivske fotografije.', 'Искреннее, живое и честное погружение в ленинградский рок-н-ролл 80-х глазами тех, кто делил с Майком сцену и жизнь.', 'A raw, heartfelt deep dive into 1980s Leningrad rock ''n'' roll through the eyes of those who shared the stage and life with Mike Naumenko.', 'Iskren i dirljiv uvid u lenjingradski rokenrol osamdesetih kroz sjećanja onih koji su sa Majkom dijelili scenu i život.', '/covers/DP-0329.webp', '#2c3437', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["real","friends"]', '["rock music","biography","memoirs","subculture","soviet rock"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('интеграл-похож-на-саксофон-330', 'DP-0330', 'Интеграл похож на саксофон', 'An Integral Looks Like a Saxophone', 'Integral liči na saksofon', 'Сева Новгородцев', 'Seva Novgorodtsev', 'Seva Novgorodcev', '', 'Амфора', NULL, NULL, 16, 99, 'adult', '"Ранним холодным темным утром 18 ноября 1975 года мы прибыли в ленинградский аэропорт "Пулково"... По розовым выездным визам нас пропустили в нейтральную полосу, где кончался Советский Союз. Сзади, за барьером, стояли друзья, родственники... Я почему-то вспомнил гастроли в Волгограде, гигантский монумент Родины-матери из напряженного железобетона, ее карающий меч, рот, раскрытый в гневном крике. Мы были уже не ее дети..." Сева Новгородцев Автобиографию знаменитого радиоведущего Русской службы "Би-би-си" Севы Новгородцева без преувеличения можно назвать энциклопедией советской жизни 1960-х-1970-х. Рассказывая о себе, автор рисует яркую, правдивую и ироничную картину нравов и быта последней империи.', '"Early on a cold, dark morning of November 18, 1975, we arrived at Leningrad''s Pulkovo airport..." The autobiography of legendary BBC Russian Service host Seva Novgorodtsev can rightly be called an encyclopedia of Soviet life in the 1960s and 1970s. Recounting his life, the author paints a vivid, honest, and keenly ironic portrait of everyday customs, music, and society in the twilight of an empire.', '"U rano, hladno i mračno jutro 18. novembra 1975. stigli smo na lenjingradski aerodrom Pulkovo..." Autobiografija legendarnog voditelja BBC-jevog ruskog servisa, Seve Novgorodceva, bez pretjerivanja predstavlja enciklopediju sovjetskog života 1960-ih i 1970-ih godina. Kroz ličnu priču, autor donosi živopisnu, iskrenu i pronicljivo ironičnu sliku svakodnevice i duha epohe na zalasku jedne imperije.', 'Ироничные, остроумные и невероятно живые мемуары легенды радио BBC о джазе, советской эпохе и пути к внутренней свободе.', 'A witty, candid, and soulful memoir by the legendary BBC radio host about jazz, late-Soviet absurdities, and the quest for freedom.', 'Duhoviti, iskreni i upečatljivi memoari legende radio BBC-ja o džezu, sovjetskim apsurdima i potrazi za slobodom.', '/covers/DP-0330.webp', '#a35c34', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["real","funny","adventure"]', '["memoir","biography","music","history","ussr"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рок-глазами-джазмена-331', 'DP-0331', 'Рок глазами джазмена', 'Rock Through the Eyes of a Jazzman', 'Rok očima džezera', 'Алексей Козлов', 'Alexey Kozlov', 'Aleksej Kozlov', '', 'Флюид', NULL, NULL, 16, 99, 'adult', 'Книга представляет собой своеобразный анализ истории музыкальной культуры второй половины 20 века с целью систематизировать многие из популярных жанров, имеющих то или иное отношение к понятию "рок". Автор книги - известный российский джазмен, саксофонист, композитор, создатель первого в СССР джаз-рок ансамбля "Арсенал" - народный артист России Алексей Козлов. Его взгляд на рок-музыку сделан изнутри, поскольку автор провел большую часть жизни в джазовом и рок-подполье. Объективный и доброжелательный подход автора к изложению материала может послужить залогом того, что данная книга вызовет доверие у тех, кто интересуется проблемами музыкальной культуры.', 'A unique analysis of late 20th-century music culture by legendary saxophonist, composer, and founder of the USSR''s pioneering jazz-rock band ''Arsenal'', Alexey Kozlov. Having spent decades in the musical underground, Kozlov shares an authentic insider perspective on the evolution of rock, deftly mapping out genres with sharp intellect, warmth, and profound respect for the craft.', 'Jedinstvena analiza muzičke kulture druge polovine 20. vijeka iz pera legendarnog saksofoniste, kompozitora i osnivača pionirskog sovjetskog džez-rok sastava „Arsenal“, Alekseja Kozlova. Kao neko ko je proveo decenije u muzičkom podzemlju, Kozlov donosi autentičan pogled iznutra, s toplinom i stručnošću rasvjetljavajući razvoj roka i srodnih žanrova.', 'Честный и захватывающий путеводитель по золотой эпохе рок- и джаз-подполья от легенды, которая стояла у самых истоков.', 'An honest, captivating insider guide to the golden age of the rock and jazz underground by a legend who lived it all.', 'Iskren i uzbudljiv vodič kroz zlatno doba rok i džez podzemlja iz pera muzičara koji je bio u samom središtu zbivanja.', '/covers/DP-0331.webp', '#2c3549', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["real"]', '["music","rock","jazz","history","biography"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дэвид-линч-332', 'DP-0332', 'Дэвид Линч', 'David Lynch', 'Dejvid Linč', '', 'Unknown', 'Nepoznato', '', 'Азбука', NULL, NULL, 16, 99, 'adult', 'Дэвид Линч из редкой (особенно для американского кино) породы режиссеров - чистых визионеров. Он создает альтернативные миры, которые оказываются реальнее, чем сама реальность. Многие воспринимают его фильмы как мистические загадки. Но когда у Линча спрашивают, какой смысл он вкладывал в тот или иной эпизод, в ту или иную картину, режиссер отвечает: кинообразы нельзя пересказать словами, само кино - это и есть наиболее адекватный язык для снов и фантазмов. В цикле бесед, предлагаемом вашему вниманию, Линч рассказывает не только обо всех своих кинопроектах, но также о занятиях живописью, фотографией и музыкой, о съемках рекламных роликов для Майкла Джексона и Джорджо Армани, о своем комиксе "Самая злая собака в мире".', 'David Lynch belongs to a rare breed of directors: the pure visionaries. He crafts alternate worlds that feel more tangible than reality itself. While many see his films as mystical riddles, Lynch insists that cinematic imagery cannot be translated into words—cinema itself is the true language of dreams and phantasms. In this collection of conversations, Lynch opens up not only about all his film projects, but also about his painting, photography, music, directing commercials for Michael Jackson and Giorgio Armani, and his comic strip ''The Angriest Dog in the World''.', 'Dejvid Linč pripada rijetkoj vrsti režisera — čistim vizionarima. On stvara alternativne svjetove koji djeluju stvarnije od same stvarnosti. Mnogi njegova djela doživljavaju kao mistične zagonetke, ali Linč poručuje da se filmske slike ne mogu prepričati riječima — sam film je najprecizniji jezik za snove i fantazme. U ovoj seriji razgovora, Linč govori ne samo o svim svojim filmskim projektima, već i o slikarstvu, fotografiji, muzici, snimanju reklama za Majkla Džeksona i Đorđa Armanija, kao i o svom stripu ''Najljući pas na svijetu''.', 'Загляните за красную бархатную штору подсознания главного визионера мирового кино — желательно с чашечкой чертовски хорошего кофе!', 'Step behind the red velvet curtain into the subconscious of cinema''s greatest visionary—best enjoyed with a damn fine cup of coffee!', 'Zakoračite iza crvene somotske zavjese u podsvijest najvećeg vizionara filma — po mogućnosti uz šoljicu prokleto dobre kafe!', '/covers/DP-0332.webp', '#7a1f2d', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["spooky","magic","real"]', '["cinema","biography","interviews","directing","art"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('твин-пикс-333', 'DP-0333', 'Твин пикс', 'Twin Peaks', 'Tvin Piks', 'Дженнифер Линч, Скотт Фрост', 'Jennifer Lynch, Scott Frost', 'Dženifer Linč, Skot Frost', '', 'Вагриус', NULL, NULL, 16, 99, 'adult', 'Двадцать пять лет назад Дэвид Линч и Марк Фрост свели весь мир с ума культовым сериалом «Твин Пикс», раз и навсегда изменившим отношение публики к сериальной культуре. Вместе с агентом ФБР Дейлом Купером зрители пытались разгадать загадку: «Кто убил Лору Палмер?» — и четко усвоили: «Совы — не то, чем они кажутся». .В финале оборванного на полуслове второго сезона Лора Палмер пообещала Куперу, что они встретятся через двадцать пять лет. И вот четверть века спустя легендарный проект возобновляется: тот же Марк Фрост написал сценарий третьего сезона «Твин Пикс», выйдет на телеэкраны в 2017 году. А чтобы раздразнить аппетит зрителей, осенью 2016 года Марк Фрост выпускает книгу «Тайная история Твин Пикс». Написанная в уникальном жанре «датафикшн», насыщенная документами и богатым иллюстративным материалом, она приподнимает завесу тайны над тем, что происходило в городке и его окрестностях не только за минувшие двадцать пять лет, но и за последние два века — с тех пор, как первые следопыты услышали от индейцев о загадочном месте, где «в верховьях река раздваивается и течет сквозь две горы, с которых обрушивается великий водопад»; о месте, как-то связанном с могущественными и не всегда добрыми силами…', 'A legendary companion to David Lynch and Mark Frost''s cult masterpiece, this book uncovers the darkest secrets of the quiet town in the Pacific Northwest. Between the raw, intimate confessions of Laura Palmer''s secret diary and the meticulous tapes of Special Agent Dale Cooper, readers are drawn into the uncanny atmosphere where cherry pie and damn fine coffee coexist with ancient, brooding woods and supernatural dread. Remember: the owls are not what they seem.', 'Legendarni pratilac kultnog remek-djela Dejvida Linča i Marka Frosta, ova knjiga otkriva najmračnije tajne naizgled mirnog gradića. Kroz intimne ispovijesti iz tajnog dnevnika Lore Palmer i fascinantne audio-zapise specijalnog agenta Dejla Kupera, čitaoci ulaze u zagonetni svijet gdje pita od višanja i odlična kafa dijele prostor sa prastarim šumama i nadrealnim silama. Ne zaboravite: sove nisu ono što se čine.', 'Заварите чертовски хороший кофе, отрежьте кусок вишнёвого пирога и приготовьтесь узнать, о чём на самом деле молчат совы.', 'Pour yourself a damn fine cup of coffee, grab a slice of cherry pie, and dive in to discover what the owls are truly whispering about.', 'Sipajte sebi vraški dobru kafu, uzmite parče pite od višanja i saznajte o čemu to sove zapravo ćute.', '/covers/DP-0333.webp', '#8b1e2d', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["spooky","magic"]', '["twin peaks","mystery","cult classic","detective","secrets"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайная-история-твин-пикс-334', 'DP-0334', 'Тайная история Твин Пикс', 'The Secret History of Twin Peaks', 'Tajna istorija Tvin Piksa', 'Марк Фрост', 'Mark Frost', 'Mark Frost', '', 'Азбука', NULL, NULL, 16, 99, 'adult', 'Предлагаем поклонникам «Твин-Пикс» познакомиться с воспоминаниями специального агента ФБР Дейла Купера, зафиксированными Скоттом Фростом — братом Марка Фроста, основного сценариста сериала, и также сценаристом в том числе нескольких серий собственно «Твин-Пикс». Вы узнаете о переписке юного Дейла Купера с директором ФБР Эдгаром Гувером, о том, как Купер с младых лет.увлекся сыскным делом и получил свой первый диктофон, о знакомстве с агентом Уиндомом Эрлом и о том, кто же такая эта загадочная Диана, которой Купер адресует свои записи в сериале Линча… Тот самый дневник Лоры Палмер, найденный агентом Купером. Зрителям его содержание стало известно лишь отрывочно, и любопытство их удовлетворила Дженнифер Линч — известный режиссер и сценарист, дочь Дэвида Линча. Именно в этой книге отношения Лоры Палмер с таинственной инфернальной сущностью, известной как Боб, показаны во всей полноте и в развитии.', 'A deep dive into the enigmatic lore of Twin Peaks, presented as a confidential FBI dossier full of classified files, journals, and strange historical records. Expanding far beyond Laura Palmer''s tragic murder, it traces centuries of unexplained phenomena and dark cosmic mysteries hidden deep within the Pacific Northwest woods.', 'Duboko uranjanje u zagonetnu mitologiju Tvin Piksa, predstavljeno kao povjerljivi dosije FBI-a prepun tajnih dokumenata, dnevnika i neobičnih istorijskih zapisa. Knjiga seže daleko izvan tragičnog ubistva Lore Palmer, prateći vjekove neobjašnjivih pojava i mračnih misterija skrivenih u šumama Pacifičkog sjeverozapada.', 'Заварите чертовски хороший кофе, отрежьте вишневого пирога и приготовьтесь погрузиться в секретный архив городка, где совы точно не то, чем кажутся.', 'Brew a damn fine cup of coffee, grab a slice of cherry pie, and plunge into the secret archives of a town where the owls are definitely not what they seem.', 'Skuvajte prokleto dobru kafu, uzmite parče pite od višanja i zaronite u tajni arhiv grada u kojem sove definitivno nijesu ono što se čini.', '/covers/DP-0334.webp', '#23382b', 'adults', 'ru', 'available', 'Категория: про музыку и кино', '["spooky","magic"]', '["twin peaks","mystery","investigation","secrets","cult classic"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('астрид-линдгрен-этот-день-и-ес-335', 'DP-0335', 'Астрид Линдгрен Этот день и есть жизнь', 'Astrid Lindgren: The Woman Behind Pippi Longstocking', 'Astrid Lindgren: Ovaj dan je život', 'Йенс Андерсен', 'Jens Andersen', 'Jens Andersen', '', 'Колибри', NULL, NULL, 16, 99, 'adult', '«Этот день и есть жизнь» – первая за 40 лет биография великой сказочницы, книги которой многие десятилетий помогают детям во всем мире справляться с нелегким делом взросления. Эта книга о ней самой – бунтарке в брюках и мужском пиджаке, первой в родном городке остригшей длинные волосы, матери-одиночке в пуританской Швеции, жене человека, фамилию которого она прославила на весь мир… Вдове, художнике, благотворительнице, «мудрой старице» – духовной наставнице всей Скандинавии, человеке, в совершенстве владевшем искусством понимать. Той самой женщине, чью независимость и жизнелюбие унаследовала знаменитая Пеппи Длинныйчулок. В ее письмах, дневниках, фотографиях, воспоминаниях близких оживают ее сражения, поражения и победы, моменты вдохновения и минуты отчаяния.', 'The first major biography of Astrid Lindgren in forty years reveals the complex, rebellious, and deeply compassionate woman behind Pippi Longstocking. Drawing on personal diaries, letters, and rare photographs, Jens Andersen portrays a visionary mother, fierce activist, and beloved storyteller who transformed world literature while navigating her own profound struggles and quiet triumphs.', 'Prva velika biografija Astrid Lindgren u posljednjih četrdeset godina otkriva izuzetnu, buntovnu i empatičnu ženu koja je stvorila Pipi Dugu Čarapu. Kroz lična pisma, dnevnike i porodične fotografije, Jens Andersen oživljava portret samohrane majke, neustrašive aktivistkinje i mudre pripovjedačice čija su nezavisnost i ljubav prema životu osvojile čitav svijet.', 'Проникновенная и честная история о женщине, которая подарила миру Пеппи и Карлсона, показав, как сохранить детскую искренность и отвагу даже перед лицом самых суровых жизненных бурь.', 'A deeply moving and honest portrait of the remarkable woman who gave us Pippi Longstocking, proving that courage, wit, and inner freedom can conquer life''s toughest storms.', 'Topla i iskrena priča o ženi koja nam je podarila Pipi Dugu Čarapu, dokazujući da unutrašnja sloboda i dječja iskrenost mogu savladati i najteže životne oluje.', '/covers/DP-0335.webp', '#b85d34', 'adults', 'ru', 'available', 'Категория: про писателей', '["real"]', '["биография","астрид линдгрен","писатели","вдохновение","история жизни"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('астрид-линдгрен-детство-длиною-336', 'DP-0336', 'Астрид Линдгрен Детство длиною в жизнь ЖЗЛ', 'Astrid Lindgren: A Lifelong Childhood', 'Astrid Lindgren: Djetinjstvo dugo čitav život', 'Биргит Данкерт', 'Birgit Dankert', 'Birgit Dankert', '', 'Молодая гвардия', NULL, NULL, 16, 99, 'adult', 'Книга рассказывает о непростом жизненном и творческом пути выдающейся шведской писательницы, классика мировой детской литературы Астрид Линдгрен, «мамы» Пеппи Длинный чулок, Карлсона, который живет на крыше, знаменитого сыщика Калле Блюмквиста и многих других литературных героев, знакомых большинству из нас с детства. Автор книги — немецкая исследовательница Биргит Данкерт, признанный эксперт в области детской литературы, автор многочисленных публикаций — в первую очередь об Астрид Линдгрен.', 'This biography explores the complex life and creative journey of the legendary Swedish author Astrid Lindgren, creator of Pippi Longstocking, Karlsson-on-the-Roof, and Kalle Blomkvist. Written by renowned German children''s literature expert Birgit Dankert, the book paints a candid portrait of a woman who preserved the wonder and resilience of childhood throughout her entire life.', 'Knjiga osvjetljava nesvakidašnji život i stvaralački put čuvene švedske književnice Astrid Lindgren, autorke Pipi Duge Čarape, Karlsona s krova i mnogih drugih omiljenih junaka. Priznata njemačka istraživačica književnosti za djecu Birgit Dankert donosi dirljiv i iskren portret žene koja je djetinjstvo nosila u srcu kroz sve životne izazove.', 'Узнайте, из каких радостей, драм и неподдельной искренности выросли любимые Карлсон и Пеппи.', 'Discover the real joys, struggles, and boundless inner child behind the creator of Pippi Longstocking and Karlsson.', 'Otkrijte dirljivu i fascinantnu životnu priču žene koja je svijetu podarila Pipi Dugu Čarapu.', '/covers/DP-0336.webp', '#3f546c', 'adults', 'ru', 'available', 'Категория: про писателей', '["real"]', '["biography","astrid lindgren","literature","non-fiction","writers"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('туве-янссон-работай-и-люби-337', 'DP-0337', 'Туве Янссон: работай и люби', 'Tove Jansson: Work and Love', 'Tuve Janson: Radi i voli', 'Туула Карьялайнен', 'Tuula Karjalainen', 'Tula Karjalajnen', '', 'АСТ', NULL, NULL, 16, 99, 'adult', 'Туве Янссон - не только мама Муми-тролля, но и автор множества картин и иллюстраций, повестей и рассказов, песен и сценариев. Ее книги читают во всем мире, более чем на сорока языках. Туула Карьялайнен провела огромную исследовательскую работу и написала удивительную, прекрасно иллюстрированную биографию, в которой длинная и яркая жизнь Туве Янссон вплетена в историю XX века. Проведя огромную исследовательскую работу, Туула Карьялайнен написала большую и очень интересную книгу обо всем и обо всех, кого Туве Янссон любила в своей жизни. - Hufvudstadsbladet Туула Карьялайнен рассказывает о жизни Туве Янссон и той удивительной храбрости, с которой она ее прожила. - YLE', 'Tove Jansson is celebrated not only as the creator of the Moomins, but also as an extraordinary painter, illustrator, novelist, and poet. In this richly illustrated and deeply researched biography, art historian Tuula Karjalainen weaves Jansson’s vibrant life story into the cultural tapestry of the twentieth century, illuminating her fearless pursuit of creative freedom and romantic passion.', 'Tuve Janson nije samo stvoriteljica Mumina, već i cijenjena slikarka, ilustratorka i književnica. U ovoj bogato ilustrovanoj i temeljno istraženoj biografiji, istoričarka umjetnosti Tula Karjalajnen prepliće buran život Tuve Janson sa istorijom dvadesetog vijeka, otkrivajući njenu nevjerovatnu hrabrost, ljubav i umjetničku slobodu.', 'Загляните за кулисы Муми-дола и откройте для себя настоящую Туве Янссон — смелую бунтарку, страстную художницу и потрясающую женщину.', 'Peek behind the scenes of Moominvalley to meet the real Tove Jansson — a bold rebel, passionate painter, and deeply inspiring woman.', 'Zavirite iza kulisa Mumindola i upoznajte pravu Tuve Janson — hrabru buntovnicu, strastvenu slikarku i nevjerovatnu ženu.', '/covers/DP-0337.webp', '#2b4c6f', 'adults', 'ru', 'available', 'Категория: про писателей', '["real"]', '["biography","moomins","art","women in history","nordic literature"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('памяти-детства-мой-отец-корней-338', 'DP-0338', 'Памяти детства Мой отец - Корней Чуковский', 'In Memory of Childhood: My Father, Korney Chukovsky', 'U sjećanje na djetinjstvo: Moj otac Kornej Čukovski', 'Лидия Чуковская', 'Lydia Chukovskaya', 'Lidija Čukovska', '', 'Волчок', NULL, NULL, 16, 99, 'adult', '"Памяти детства" - книга воспоминаний Лидии Чуковской о детских годах, проведенных в дачном поселке Куоккала (Репино), и об отце Корнее Чуковском (1882-1969) - внимательном, харизматичном, порывистом родителе, сумевшем сделать своих детей счастливыми. Корней Чуковский здесь - не знаменитый критик, не писатель, не детский поэт, автор "Крокодила" и "Айболита", но молодой, любимый, талантливый папа. В издании вы найдете множество редких фотографий из архива семьи Чуковских и рукописные фрагменты дневника Корнея Ивановича. Дневниковые записи "куоккальского" периода содержат наблюдения за особенностями взросления детей - Коли (Николая Корнеевича Чуковского, 1904-1965), Лиды (Лидии Корнеевны Чуковской, 1907-1996) и Бобы (Бориса Корнеевича Чуковского, 1910-1941).', 'In Memory of Childhood is Lydia Chukovskaya''s luminous memoir of growing up in the seaside village of Kuokkala, centered around her father, Korney Chukovsky (1882–1969)—an attentive, spirited, and magnetic parent who made his children truly happy. Here, Chukovsky appears not as a formidable literary critic or the famous author of Doctor Aybolit, but simply as a young, loving, and passionately involved father. This edition includes rare family photographs and handwritten excerpts from Chukovsky''s diaries documenting the joys and quirks of his children''s upbringing.', '„U sjećanje na djetinjstvo“ su dirljiva sjećanja Lidije Čukovske na dječje dane provedene u primorskom naselju Kuokala i na njenog oca Korneja Čukovskog (1882–1969) — pažljivog, harizmatičnog i poletnog roditelja koji je umio da usreći svoju djecu. Čukovski ovdje nije slavni književni kritičar ni autor nezaboravnih dječjih stihova, već mladi, voljeni i nadahnuti tata. Knjiga sadrži rijetke porodične fotografije i rukopisne odlomke iz očevih dnevnika koji bilježe magiju odrastanja.', 'Взгляните на создателя «Мойдодыра» глазами его собственной дочери — не как на бронзового классика, а как на самого весёлого и чуткого папу на свете.', 'Meet the legendary children''s poet through his daughter''s eyes—not as a literary monument, but as the warmest, most inventive father imaginable.', 'Upoznajte legendarnog dječjeg pisca kroz oči njegove kćerke — ne kao književnog velikana, već kao najtoplijeg i najmaštovitijeg tatu na svijetu.', '/covers/DP-0338.webp', '#7a5c43', 'adults', 'ru', 'available', 'Категория: про писателей', '["real","friends"]', '["memoir","parenting","childhood","family","biography"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-я-был-маленьким-339', 'DP-0339', 'Когда я был маленьким', 'When I Was a Little Boy', 'Kad sam bio mali', 'Эрих Кестнер', 'Erich Kästner', 'Erih Kestner', '', 'Самокат', NULL, NULL, 16, 99, 'adult', 'Знаменитый немецкий писатель Эрих Кестнер (1899-1974), лауреат Золотой медали имени Андерсена (1960), принадлежит к числу лучших взрослых, которые никогда не перестают быть детьми. В повести "Когда я был маленьким" он рассказывает юным читателям о своем детстве так увлекательно и живо, что мы смеемся и плачем вместе с маленьким Эрихом, переживаем за его первый учебный день, несемся с горы на велосипеде вслед за ним и его кузиной. И кажется, что все это случилось сейчас и с нами, а не сто лет тому назад в далеком Дрездене. В своей книге "Когда я был маленьким" Кёстнер не рассказывает удивительных историй: у него было обычное детство, такое же, как у его маленьких читателей, со своими горестями и радостями. Но то, как он рассказывает об этом, заставляет и больших, и маленьких смеяться от души, переживать не на шутку и просто наслаждаться чтением.', 'Renowned German author and Hans Christian Andersen Award winner Erich Kästner was one of those rare adults who never stopped being a child at heart. In this autobiographical memoir, he recounts his childhood in Dresden with such charm, wit, and tenderness that readers instantly feel transported a century back in time. Without grand adventures, Kästner turns everyday triumphs and schoolboy troubles into an unforgettable, deeply heartwarming celebration of growing up.', 'Poznati njemački pisac i dobitnik Andersenove medalje, Erih Kestner, pripadao je onim rijetkim odraslima koji u duši nikada nisu prestali da budu djeca. U ovoj autobiografskoj priči on dočarava svoje djetinjstvo u Drezdenu s tolikom toplinom i humorom da se čini kao da se sve dešava danas pred našim očima. Kestner ne priča o nevjerovatnim čudima, već o običnom odrastanju puno radosti i sitnih briga, podsjećajući nas na ljepotu samog djetinjstva.', 'Нежнейшее и остроумное путешествие в детство от великого классика, которое вернёт любому взрослому вкус к жизни и детскую искренность.', 'A tender, witty journey back into childhood from a master storyteller, guaranteed to awaken the inner kid in any grown-up.', 'Nježan i duhovit povratak u djetinjstvo iz pera velikog pisca koji će podsjetiti svakog odraslog kako je lijepo biti dijete.', '/covers/DP-0339.webp', '#c36b42', 'adults', 'ru', 'available', 'Для среднего школьного возраста', '["real","funny"]', '["childhood","memoir","nostalgia","dresden","growing up"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('urban-jungle-340', 'DP-0340', 'Urban jungle', 'Urban Jungle: Living and Styling with Plants', 'Urban Jungle: Život i stilizovanje uz biljke', 'Игорь Йосифович, Джудит Граф', 'Igor Josifovic, Judith de Graaff', 'Igor Josifović, Džudit de Graf', '', 'МИФ', NULL, NULL, 16, 99, 'adult', 'Это книга о любви к цветам. Она отправит вас в незабываемое путешествие по зеленым домам Европы и покажет, какими красивыми, оригинальными и художественно ценными могут быть интерьеры с растениями. "Блогеры городских джунглей" поделятся доступными идеями оформления, описания цветов, а простые советы по уходу за ними вдохновят поскорее принести в дом нового зеленого друга. Приготовьтесь отправиться в сказочное зеленое путешествие! Добавьте интерьеру стиля и жизни, создав собственные городские джунгли. Обязательное чтение для любителей растений и всех, кто стремится озеленить свою жизнь. Экскурсии по зеленым домам, советы по дизайну и уходу за растениями - все в одной вдохновляющей книге. Идеи для энтузиастов и начинающих садоводов. Больше зелени в каждый дом!', 'This book is all about love for greenery. It takes you on an unforgettable journey through plant-filled homes across Europe, demonstrating how vibrant, artistic, and unique interiors can become with houseplants. The creators of the Urban Jungle Bloggers community share accessible styling ideas, plant profiles, and practical care tips that will inspire you to welcome a new green companion into your home. A must-read guide for plant lovers and aspiring indoor gardeners alike.', 'Ova knjiga slavi ljubav prema zelenilu. Vodi vas na nezaboravno putovanje kroz domove širom Evrope ispunjene biljkama, pokazujući koliko enterijeri mogu biti lijepi, originalni i umjetnički vrijedni uz sobno bilje. Kreatori zajednice Urban Jungle Bloggers dijele pristupačne ideje za stilizovanje, profile biljaka i praktične savjete za njegu koji će vas inspirisati da unesete još jednog zelenog prijatelja u svoj dom. Nezaobilazno štivo za sve ljubitelje prirode i uređenja prostora.', 'Вдохновляющая зелёная библия для всех, кто мечтает превратить свою квартиру в уютный тропический оазис!', 'An inspiring green bible for anyone dreaming of turning their cozy living room into a lush, thriving oasis!', 'Inspirativna zelena biblija za sve koji sanjaju da svoj stan pretvore u udobnu i bujnu oazu!', '/covers/DP-0340.webp', '#2e5d34', 'adults', 'ru', 'available', 'Категория: про растения', '["real"]', '["houseplants","interior design","gardening","inspiration","home decor"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ботаника-для-садоводов-341', 'DP-0341', 'Ботаника для садоводов', 'Botany for Gardeners', 'Botanika za baštovane', '', 'Unknown', 'Nepoznati autor', '', 'Азбука', NULL, NULL, 16, 99, 'adult', 'Доступный, подробный и прекрасно иллюстрированный путеводитель по тайнам науки о растениях поможет садоводам понять язык ботаники и ее основные принципы. Благодаря четкой и практичной структуре в книге очень удобно ориентироваться: она разделена на 9 глав, каждая из которых посвящена той или иной области ботаники, важной для садоводства. Так, есть главы, посвященные классификации растений (глава 1), проращиванию и культивированию семян (глава 5), обрезке деревьев (глава 7), борьбе с болезнями и вредителями растений (глава 9). Наряду со множеством великолепных ботанических иллюстраций издание украшают понятные технические диаграммы. Это роскошный подарок для любого человека, который любит растения и хочет, чтобы его сад и огород процветали.', 'An accessible, beautifully illustrated guide to the secrets of plant science designed to help gardeners understand botany and its core principles. Divided into nine practical chapters covering plant classification, seed germination, pruning, and pest management, this book is packed with gorgeous botanical artwork and clear diagrams—a true treasure for anyone wishing to make their garden thrive.', 'Pristupačan i raskošno ilustrovan vodič kroz tajne nauke o biljkama pomoći će baštovanima da razumiju jezik botanike i njene osnovne principe. Podijeljena u devet praktičnih poglavlja o klasifikaciji biljaka, klijanju sjemena, orezivanju i zaštiti od štetočina, knjiga nudi prelijepe botaničke ilustracije i jasne dijagrame — savršen poklon za sve koji žele bujan i zdrav vrt.', 'Книга-ключ к тайнам зелёного мира, которая превратит даже самый капризный садик в цветущий оазис!', 'The ultimate visual key to plant science that will help you speak fluent ''green'' and make any garden flourish!', 'Knjiga-ključ za tajne biljnog svijeta koja će i najzahtjevniju baštu pretvoriti u raskošnu zelenu oazu!', '/covers/DP-0341.webp', '#2e5d34', 'adults', 'ru', 'available', 'Категория: про растения', '["real"]', '["botany","gardening","nature","plants","illustrated"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('удобная-книга-начинающего-садо-342', 'DP-0342', 'Удобная книга начинающего садовода-огородника', 'The Handy Book for Beginner Gardeners', 'Praktična knjiga za baštovane početnike', 'Октябрина Ганичкина', 'Oktyabrina Ganichkina', 'Oktjabrina Ganičkina', '', 'Эксмо', NULL, NULL, 16, 99, 'adult', 'Самое удобное справочное руководство для начинающих дачников, в котором вся информация четко структурирована и вы за секунды найдете ответ на любой вопрос: какие сорта выбрать, как посадить, как ухаживать, чем подкормить, как защитить от болезней и вредителей и гарантированно получить богатый урожай с первого сезона. 80 самых популярных садовых, ягодных, овощных культур. Книга для тех, кто ценит свое время, доверяет многолетнему опыту и не желает "наступать на собственные грабли". Октябрина Ганичкина - признанный эксперт в области дачного хозяйства, кандидат сельскохозяйственных наук, автор множества бестселлеров по выращиванию овощей, фруктов и ягод, самая популярная в России телеведущая программ по садоводству и огородничеству. Александр Ганичкин - дипломированный ученый-агроном.', 'A clearly structured and comprehensive reference guide designed to help rookie gardeners achieve an abundant harvest right from their very first season. Featuring practical care instructions for 80 popular fruit, berry, and vegetable crops, it provides instant answers on selecting the right varieties, fertilizing, and protecting plants from common pests and diseases.', 'Najpregledniji priručnik za vrtlare početnike koji žele bogatu berbu već u prvoj sezoni bez lutanja i grešaka. Knjiga nudi provjerene savjete za uzgoj 80 najpopularnijih voćnih, bobičastih i povrtarskih kultura, od izbora sorti i sadnje do zaštite od bolesti i štetočina.', 'Ваш верный дачный навигатор, чтобы первый урожай вызвал искреннюю зависть у всех соседей по участку!', 'The ultimate green-thumb cheat sheet to make your very first harvest the envy of the entire neighborhood!', 'Pravi vodič za baštu uz koji će vaša prva berba zadiviti i najiskusnije komšije!', '/covers/DP-0342.webp', '#3f7a4d', 'adults', 'ru', 'available', 'Категория: про растения', '["real"]', '["gardening","horticulture","plants","nature","handbook"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цветочный-сад-343', 'DP-0343', 'Цветочный сад', 'Cut Flower Garden', 'Cvjetna bašta', 'Эрин Бензакейн', 'Erin Benzakein', 'Erin Benzakejn', '', 'МИФ', NULL, NULL, 16, 99, 'adult', 'Выдающийся цветовод и владелица известной на весь мир цветочной фермы "Флорет" Эрин Бензакейн делится опытом создания цветочной плантации своими руками и использования самых разных растений для составления роскошных, воздушных аранжировок: эффектных букетов, гирлянд и венков, в которых любой цветок раскрывает все свое великолепие. В книге вы найдете все, что нужно, чтобы создать свой цветник: советы по посадке, уходу и срезке более 175 сортов растений, а также подсказки, как сохранить их свежими и прекрасными - от грядки до букета.', 'World-renowned flower farmer and Floret Farm founder Erin Benzakein shares her secrets to cultivating an abundant cut flower patch and crafting breathtaking seasonal arrangements. Featuring expert advice on planting, tending, and harvesting over 175 flower varieties, this lush, beautifully photographed guide reveals how to bring fresh, vibrant floral beauty from garden to vase.', 'Svjetski poznata uzgajivačica cvijeća i osnivačica farme „Floret“, Erin Benzakejn, dijeli svoje tajne stvaranja bujne bašte i kreiranja raskošnih sezonskih aranžmana. Uz praktične savjete o sadnji, njezi i branju više od 175 sorti biljaka, ovaj inspirativni vodič pomoći će vam da donesete svježinu i čaroliju prirode pravo u svoj dom.', 'Вдохновляющее руководство от хозяйки знаменитой фермы Floret, после которого невозможно удержаться от посадки хотя бы крошечной клумбы на балконе!', 'An utterly inspiring guide from Floret Farm that will tempt anyone to turn their windowsill or backyard into a flourishing floral wonderland!', 'Neodoljivo inspirativan vodič s farme Floret koji će vas očarati i probuditi želju da čak i na balkonu stvorite sopstvenu oazu cvijeća!', '/covers/DP-0343.webp', '#5b8258', 'adults', 'ru', 'available', 'Категория: про растения', '["real","magic"]', '["gardening","flowers","floristry","nature","inspiration"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('алиса-в-стране-чудес-344', 'DP-0344', 'Алиса в стране чудес', 'Alice''s Adventures in Wonderland', 'Alisa u zemlji čuda', 'Льюис Кэролл', 'Lewis Carroll', 'Luis Kerol', 'Ребекка Дотермер', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Уникальное издание "Алиса в стране чудес" с потрясающими иллюстрациями знаменитой французской художницы Ребекки Дотремер позволит вам и вашему ребенку окунуться в загадочный мир волшебной страны. Книги проиллюстрированы Ребеккой Дотремер - известной французской художницей, автором визуального ряда рекламной компании парфюмерии Kenzo. Каждая иллюстрация - произведение искусства!', 'A breathtaking collector''s edition of Lewis Carroll''s timeless masterpiece, brought to life through the hauntingly beautiful, painterly illustrations of acclaimed French artist Rébecca Dautremer. Follow Alice down the rabbit hole into a mesmerizing world of quirky logic, dreamlike poetry, and genuine artistic magic.', 'Jedinstveno izdanje vanvremenskog remek-djela Luisa Kerola, oživljeno kroz očaravajuće i poetične ilustracije čuvene francuske umjetnice Rebeke Dotremer. Zaronite sa Alisom niz zečju rupu u svijet čiste mašte, neobične logike i prave likovne čarolije.', 'Приготовьтесь затаить дыхание: в завораживающих иллюстрациях Ребекки Дотремер знакомая Страна чудес открывается с совершенно новой, таинственной стороны!', 'Prepare to be spellbound: Rébecca Dautremer''s mesmerizing artwork transforms Alice''s whimsical journey into an unforgettable visual feast!', 'Pripremite se da ostanete bez daha: magične ilustracije Rebeke Dotremer otkrivaju poznatu Zemlju čuda na sasvim nov, bajkovit način!', '/covers/DP-0344.webp', '#9b2226', 'classics', 'ru', 'available', 'Категория: классика', '["magic","adventure"]', '["classics","wonderland","illustrated","fantasy","fairytale"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('алиса-в-стране-чудес-с-илл-тув-345', 'DP-0345', 'Алиса в стране чудес с илл. Туве', 'Alice in Wonderland (illustrated by Tove Jansson)', 'Alisa u zemlji čuda (sa ilustracijama Tuve Janson)', '', 'Lewis Carroll', 'Luis Kerol', '', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Алиса, Чеширский Кот, Герцогиня, Мартовский Заяц, Соня и другие герои самой читаемой детской книги в мире развлекают и удивляют многие поколения читателей. Иллюстрации Туве Янссон, создательницы сказок о мумми-троллях, позволяют по-новому взглянуть на известный сюжет "Алисы в Стране чудес". Впервые изданная в России - стране, где любят и ценят творчество Туве Янссон и Льюиса Кэролла - книжка с картинками, разговорами и большим количеством путаницы приглашает вас юркнуть в нору вслед за Белым Кроликом.', 'Alice, the Cheshire Cat, the March Hare, and other unforgettable characters return in Lewis Carroll''s timeless masterpiece, uniquely illuminated by the whimsical, dreamy illustrations of Moomin creator Tove Jansson. This delightful edition invites readers of all ages to tumble down the rabbit hole and rediscover Wonderland through an enchanting Nordic lens full of charm, wit, and gentle nonsense.', 'Alisa, Češirski Mačak, Martovski Zec i ostali nezaboravni junaci bezvremenog remek-djela Luisa Kerola oživljavaju uz sanjive i poetične ilustracije Tuve Janson, autorke čuvenih Mumina. Ovo posebno izdanje poziva čitaoce svih uzrasta da ponovo uskoče u zečiju rupu i dožive Zemlju čuda na sasvim nov, topao i očaravajući način.', 'Знакомая с детства сказка обретает совершенно неповторимый скандинавский уют и нежность благодаря волшебным рисункам мамы муми-троллей!', 'Lewis Carroll''s whimsical nonsense meets the cozy, dreamy brushwork of Moomin creator Tove Jansson—pure magic on every page!', 'Omiljena priča o Alisi dobija poseban nordijski šarm i toplinu kroz čarobne ilustracije mame Mumina!', '/covers/DP-0345.webp', '#3f6377', 'classics', 'ru', 'available', 'повреждена обложка', '["magic","adventure","funny"]', '["classics","wonderland","fairy tale","tove jansson","fantasy"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-алисы-в-стране-чуд-346', 'DP-0346', 'Приключения Алисы в стране чудес', 'Alice''s Adventures in Wonderland', 'Alisa u Zemlji čuda', 'пер. Нины Демуровой', 'Lewis Carroll (trans. Nina Demurova)', 'Luis Kerol (prev. Nina Demurova)', 'илл. Евгения Чистюгина', '', NULL, NULL, 6, 14, 'middle', 'Однажды девочка Алиса поступила несколько неосторожно не задумываясь, она побежала вслед за белым кроликом и попала в Страну чудес! Там с ней начали происходить самые невероятные приключения. Говорящие черепахи, ожившая колода карт, танцующие омары, Синяя Гусеница, которая курит кальян и улыбающийся Чеширский Кот далеко не все, с кем познакомилась Алиса. Но самое главное Алиса учит нас: чтобы идти верной дорогой, необходимо хорошо знать, куда и с какой целью ты хочешь придти!', 'One day, curious Alice tumbled down a rabbit hole straight into Wonderland, where logic turns completely upside-down! From a grinning Cheshire Cat and a hookah-smoking Caterpillar to dancing lobsters and an imperious Queen of Hearts, Alice navigates a world of delightful absurdity that reminds readers to always keep their wits about them.', 'Jednoga dana, radoznala Alisa potrčala je za Bijelim Zecom i upala pravo u magičnu Zemlju čuda! Tamo je čekaju najneobičnije pustolovine uz kornjače koje govore, oživljeni špil karata i nasmijanog Češirskog Mačka — svijet predivnog besmisla koji nas uči da nađemo svoj put čak i kad pravila ne važe.', 'Прыгайте смело за Белым Кроликом: эта бессмертная классика научит не терять голову, даже если весь мир вокруг сошёл с ума на безумном чаепитии!', 'Tumble down the rabbit hole into a topsy-turvy masterpiece where mad tea parties and riddles prove that imagination rules all!', 'Skočite za Bijelim Zecom u svijet gdje je sve naopako i uvjerite se zašto je ova neobična čajanka osvojila čitavu planetu!', '/covers/DP-0346.webp', '#2c7da0', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","magic","funny"]', '["classic","wonderland","nonsense","fantasy","fairy tale"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бременские-музыканты-347', 'DP-0347', 'Бременские музыканты', 'The Bremen Town Musicians', 'Bremenski muzikanti', 'Братья Гримм', 'Brothers Grimm', 'Braća Grim', 'Герда Мюллер', 'Лабиринт', NULL, NULL, 6, 14, 'middle', 'История о четырех музыкантах из города Бремен известна всему миру. Она издавалась множество раз в самых разных вариантах. Новинка издательства "Лабиринт Пресс" - приятная книга в твердом переплете, удобного увеличенного формата, с иллюстрациями голландской художницы Герды Мюллер. Её рисунки, спокойные и гармоничные, завораживают детальностью и тонкостью работы. Сюжет знакомой сказки раскрывается по-новому благодаря чудным пейзажам, симпатичным героям и совсем нестрашным разбойникам. Герда Мюллер, известная художница и автор детских книг, родом из Нидерландов. Сейчас ей 90 лет, и уже больше полувека она работает с лучшими европейскими издательствами. История музыкантов из Бремена - ее любимая, Герда иллюстрирует эту сказку в третий раз. Простые и гармоничные рисунки поражают тонкостью и деятельностью, пейзажи чудо как хороши, герои удивительно симпатичны, и разбойники, кажется, им ничуть не страшны. В пересказе Леонида Яхнина.', 'The timeless tale of four animal companions journeying to Bremen comes alive in this exquisite edition illustrated by celebrated Dutch artist Gerda Muller. With gentle, richly detailed artwork and not-so-scary robbers, this retelling by Leonid Yakhnin warmly proves that true friendship, clever teamwork, and a spirited song can overcome any hardship.', 'Bezvremena priča o četiri životinjska prijatelja na putu za Bremen oživljava u ovom predivnom izdanju koje je ilustrovala čuvena holandska umjetnica Gerda Miler. Uz tople, detaljne crteže i razbojnike koji uopšte nijesu strašni, ova bajka u prepričavanju Leonida Jahnina podsjeća da složna družina i hrabro srce mogu pobijediti svaku nevolju.', 'Когда четверо верных четвероногих друзей берут судьбу в свои лапы и копыта, разбойникам остаётся только удирать без оглядки!', 'When four aging animal pals unite, their chaotic choir is more than enough to send a gang of robbers packing!', 'Kad četiri odana četvoronožna prijatelja udruže snage, razbojnicima ne preostaje ništa drugo nego da bježe glavom bez obzira!', '/covers/DP-0347.webp', '#4a6b47', 'classics', 'ru', 'available', 'Для детей дошкольного возраста.', '["adventure","friends","animals"]', '["fairy tale","classics","teamwork","friendship","folklore"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('доктор-айболит-и-морские-пират-348', 'DP-0348', 'Доктор Айболит и морские пираты', 'Doctor Aybolit and Sea Pirates', 'Doktor Jojboli i morski pirati', '', 'Korney Chukovsky', 'Kornej Čukovski', 'Виктор Чижиков', 'Амфора', NULL, NULL, 6, 14, 'middle', 'В этом выпуске коллекции "Сказки на ночь" вам вместе с доктором Айболитом, мальчиком Пентой и их верными друзьями предстоит побывать в плену у самых настоящих, отпетых морских пиратов… Книга иллюстрирована замечательным детским художником В.Чижиковым. Читайте волшебные сказки своим детям на ночь, разглядывайте вместе яркие картинки, и в вашем доме прибавится добра и красоты!', 'Join Doctor Aybolit, little Penta, and their loyal animal friends on a thrilling sea voyage where they end up captured by ruthless pirates! Masterfully illustrated by the beloved Viktor Chizhikov, this classic tale turns bedtime reading into an unforgettable journey filled with bravery, kindness, and triumphant camaraderie.', 'Pridružite se dobrom doktoru Jojboliju, dječaku Penti i njihovim vjernim prijateljima na uzbudljivom morskom putovanju gdje upadaju u ruke pravim morskim razbojnicima! Uz divne ilustracije Viktora Čižikova, ova klasična bajka donosi toplinu, hrabrost i pravu avanturu pred spavanje.', 'Свистать всех наверх: добрый доктор и его хвостатая команда докажут грозным пиратам, что дружба и доброта сильнее любой сабли!', 'All hands on deck: the kindest doctor and his animal crew prove that courage and true friendship can outwit any pirate!', 'Svi na palubu: omiljeni doktor i njegovi životinjski prijatelji pokazaće opasnim piratima da dobrota i sloga pobjeđuju svaku sablju!', '/covers/DP-0348.webp', '#1e6b8c', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","animals","friends"]', '["pirates","sea adventure","doctor aybolit","classics","animals"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('девочка-маша-и-кукла-наташа-349', 'DP-0349', 'Девочка Маша и кукла Наташа', 'Little Girl Masha and Natasha the Doll', 'Djevojčica Maša i lutka Nataša', 'Виктор Чижиков', 'Viktor Chizhikov', 'Viktor Čižikov', '', 'Мелик-Пашаев', NULL, NULL, 6, 14, 'middle', 'Это сборник юмористических рисунков и стихов для детей из архивных выпусков журнала "Веселые картинки". Название журнала говорит само за себя - маленьким детям всегда нравятся забавные и веселые картинки, сопровождаемые короткими остроумными надписями. Каневский, Васнецов, Ротов, Конашевич, Лаптев, Сутеев, Чижиков, Елисеев, Битный - это далеко не исчерпывающий перечень мэтров изобразительного искусства, которые сотрудничали с редакцией. Об истории "Веселых картинок" можно написать не одну книгу. Но у нас была другая задача. Мы хотели подарить современным детям некоторые страницы из первых номеров журнала, над которыми смеялись их бабушки и дедушки.', 'A delightful collection of humorous comics and short verses from archive issues of the legendary children''s magazine "Merry Pictures" (Vesyolye Kartinki). Illustrated by Soviet masters of art led by Viktor Chizhikov, these witty, vintage visual adventures of a clever little girl and her doll bring timeless laughs that delighted parents and grandparents when they were kids.', 'Šarmantna zbirka šaljivih stripova i kratkih pjesmica za djecu iz arhivskih brojeva legendarnog časopisa „Vesele sličice”. Uz tople i duhovite ilustracije majstora predvođenih Viktorom Čižikovom, ove vesele dogodovštine domišljate djevojčice i njene lutke donose bezvremensku radost uz koju su odrastali naši roditelji, bake i djedovi.', 'Золотая классика детского комикса: остроумные и добрые зарисовки, над которыми заливались смехом ещё наши бабушки!', 'A pure vintage treasure of early comic strips and warm humor that made generations of kids giggle with delight!', 'Pravi biser klasičnog humora i bezvremenskih stripova koji će podjednako nasmijati i djecu i roditelje!', '/covers/DP-0349.webp', '#e25034', 'classics', 'ru', 'available', 'Категория: классика', '["funny","friends"]', '["comics","vintage","humor","classics","nostalgia"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сладкоежка-350', 'DP-0350', 'Сладкоежка', 'Sweet Tooth', 'Sladokusac', '', 'Various Authors', 'Grupa autora', '', 'Мелик-Пашаев', NULL, NULL, 6, 14, 'middle', 'второй выпуск сборника весёлых и поучительных историй в картинках. Как и первый выпуск ("Девочка Маша, кукла Наташа и все-все-все"), он создан на основе архивных выпусков журнала "Весёлые картинки". Картинки созданы прекрасными рисовальщиками, неиссякаемыми выдумщиками и юмористами А. Сазоновым, С. Бялковской, И. Семёновым, В. Стацинским, Н. Радловым. Сборник получился очень смешным, фантастически разножанровым, с колоссальным разнообразием тем: истории в картинках, картинки-загадки, сказки-загадки, лабиринты, парные картинки, в которых надо искать отличия, увлекательные рассказы-комиксы. "Гвоздь программы" - два приключенческих комикса о Пете Рыжике и его верных друзьях, обаятельных и харизматичных собаках Мике и Муке, созданные талантливейшим художником Иваном Семеновым.', 'The second treasury of cheerful, witty picture stories from the archives of the legendary children''s magazine ''Vesyolye Kartinki''. Packed with charming cartoon strips, mazes, visual riddles, and ''spot the difference'' games by master illustrators, this book features exciting retro comic adventures of Petya Ryzhik and his clever dogs, Mik and Muk.', 'Drugi tom zbirke veselih i poučnih priča u slikama iz arhiva kultnog dječijeg časopisa „Vesjolije kartinki“. Bogato ilustrovana knjiga puna stripova, zagonetki, lavirinata i igara traženja razlika donosi i čuvene avanture dječaka Petje Rižika i njegovih vjernih pasa Mika i Muka koje su stvorili majstori klasične ilustracije.', 'Настоящая машина времени и море смеха под одной обложкой: листайте легендарные комиксы, разгадывайте визуальные шарады и отправляйтесь в походы с Петей Рыжиком!', 'A delightful retro blast from the past packed with classic comic strips, visual puzzles, and timeless laughs for the whole family!', 'Prava mašina vremena puna smijeha: uživajte u legendarnim retro stripovima, zabavnim zagonetkama i avanturama koje nikada ne stare!', '/covers/DP-0350.webp', '#e86e24', 'classics', 'ru', 'available', 'Категория: классика', '["funny","adventure","friends"]', '["comics","retro","puzzles","humor","dogs"]', 1792836322696, 1792845628434);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-матушки-гусыни-351', 'DP-0351', 'Сказки матушки Гусыни', 'Tales of Mother Goose', 'Priče majke Guske', 'Шарль Перро', 'Charles Perrault', 'Šarl Pero', 'Ника Гольц', 'Правда', NULL, NULL, 6, 14, 'middle', 'В настоящий сборник включены не только все сказки Шарля Перро, прозаические и стихотворные, но также и некоторые наиболее известные сказки его продолжателей и последователей (д&#39;Онуа, Леритье де Виллодон, Лепренс де Бомон) как образцы французской сказочной литературы XVII—XVIII веков.', 'This collection features not only all of Charles Perrault''s fairy tales in prose and verse, but also some of the most famous works by his contemporaries and successors (d''Aulnoy, L''Héritier de Villandon, Leprince de Beaumont), representing the golden age of 17th–18th century French fairy-tale literature.', 'Ova zbirka obuhvata ne samo sve bajke Šarla Peroa u prozi i stihu, već i najpoznatije priče njegovih književnih nasljednika (d''Onoa, Leritije de Vilodon, Leprens de Bomon), kao vrhunske primjere francuske bajkovite književnosti 17. i 18. vijeka.', 'Здесь живут настоящие, неурезанные Золушка, Кот в сапогах и Синяя Борода — какими их задумал сам великий французский сказочник!', 'Meet the original, unvarnished Cinderella, Puss in Boots, and Bluebeard exactly as the great French master imagined them!', 'Upoznajte originalnu Pepeljugu, Mačka u čizmama i Plavobradog baš onako kako ih je zamislio slavni francuski pripovjedač!', '/covers/DP-0351.webp', '#2b4570', 'classics', 'ru', 'available', 'Категория: классика', '["magic","adventure"]', '["fairy tales","classics","french literature","folklore","cinderella"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('русские-народные-сказки-352', 'DP-0352', 'Русские народные сказки', 'Russian Folk Tales', 'Ruske narodne bajke', '', 'Traditional', 'Narodno stvaralaštvo', 'Иван Билибин', 'Издательство Мещерякова', NULL, NULL, 6, 14, 'middle', 'Русские народные сказки, оформленные Иваном Яковлевичем Билибиным, — единственные в своём роде. Они создают неповторимо трогательную атмосферу волшебства, которая сопровождает нас с самого детства до глубокой зрелости. Для многих поколений читателей имя художника неразрывно связано с миром сказок, былин, с образами Древней Руси.', 'Russian folk tales illustrated by Ivan Bilibin are truly one of a kind. They conjure a uniquely touching atmosphere of wonder and enchantment that stays with readers from early childhood into adulthood, bringing the mythical spirit of Ancient Rus to vibrant life.', 'Ruske narodne bajke s nezaboravnim ilustracijama Ivana Bilibina stvaraju jedinstvenu, dirljivu čaroliju koja nas prati od djetinjstva do odraslog doba, oživljavajući magični svijet legendi i drevne Rusije.', 'Погрузитесь в настоящее узорное волшебство с шедеврами Билибина — эти сказки пахнут дремучим лесом, тайной и детством!', 'Step inside an intricately woven fairy tale realm with Bilibin''s iconic art—these legends smell of enchanted forests, mystery, and pure childhood wonder!', 'Zaronite u raskošno ilustrovani svijet Bilibinovih remek-djela—ove bajke mirišu na začaranu šumu, drevne tajne i djetinjstvo!', '/covers/DP-0352.webp', '#8f2d22', 'classics', 'ru', 'available', 'Категория: классика', '["magic","adventure","spooky"]', '["fairy tales","folklore","bilibin","classics","legends"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-353', 'DP-0353', 'Сказки', 'Fairy Tales', 'Bajke', 'Пушкин', 'Alexander Pushkin', 'Aleksandar Puškin', 'Билибин, Назарук', 'Издательский Дом Ридерз Дайджест', 2002, '5-89355-021-8', 6, 14, 'middle', '', 'A glorious collection of timeless poetic tales by Alexander Pushkin. From the Golden Fish and Tsar Saltan to the Dead Princess and the Golden Cockerel, these rhythmic masterpieces bring classic folklore, wondrous islands, and sparkling magic to life.', 'Raskošna zbirka bezvremenskih bajki u stihovima Aleksandra Puškina. Od zlatne ribice i cara Saltana do mrtve princeze i zlatnog pjetlića, ove rime oživljavaju čuda drevnih predanja i narodnu mudrost.', 'Волшебные пушкинские строки, которые мгновенно запоминаются наизусть и переносят прямо к Лукоморью с ученым котом!', 'Dive into poetic wonders where golden fish grant wishes, squirrels crack emerald nuts, and learned cats tell tales!', 'Uronite u čarobne stihove gdje zlatne ribice ispunjavaju želje, a mačak naučnik kazuje najljepše bajke!', '/covers/DP-0353.webp', '#2c3e6b', 'classics', 'ru', 'available', 'Категория: классика', '["magic","adventure"]', '["fairy tales","poetry","classics","folklore","magic"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-354', 'DP-0354', 'Сказки', 'Fairy Tales', 'Bajke', 'Братья Гримм', 'Brothers Grimm', 'Braća Grim', 'Лизабет Цвергер', 'Стрекоза', NULL, NULL, 6, 14, 'middle', 'В книге собраны Сказки знаменитых немецких фольклористов - братьев Якоба и Вильгельма Гримм - с иллюстрациями всемирно известной художницы, лауреата премии Х.К. Андерсена за вклад в детскую литературу Лизбет Цвергер. Лизбет с самого детства мечтала стать художником-иллюстратором и достигла всемирного признания, выработав свой индивидуальный стиль и художественную манеру. В своих работах Лизбет Цвергер не пытается разгадать и объяснить сюжет, она старается усилить магию текста, сделать его ещё более волшебным и загадочным. Характеры её героев сложны и многообразны, в них сочетаются романтика и юмор, искажённые, вытянутые пропорции и танцевальные динамичные позы, нежность и гротеск. Лизбет Цвергер иллюстрировала Э.Т.А. Гофмана, Ч. Диккенса, О. Уайльда, Э. Несбит, Х.К. Андерсена, Л. Кэрролла, Л.Ф. Баума.', 'This edition brings together the timeless fairy tales of Jacob and Wilhelm Grimm, accompanied by breathtaking illustrations from Hans Christian Andersen Award winner Lisbeth Zwerger. Rather than simply illustrating the plot, Zwerger enhances the atmospheric magic of the text, combining delicate romance, dynamic silhouettes, and subtle mystery to create an unforgettable visual experience.', 'Ovo izdanje objedinjuje bezvremenske bajke braće Jakoba i Vilhelma Grima, obogaćene očaravajućim ilustracijama dobitnice nagrade H. K. Andersen, Lizbet Cverger. Umjesto pukog prepričavanja radnje, njene profinjene i poetične ilustracije produbljuju tajanstvenu magiju priča, spajajući nježnost, suptilni humor i jedinstvenu vizuelnu draž.', 'Знакомые с детства сказки братьев Гримм оживают в совершенно новом, изысканно-волшебном свете благодаря акварелям гениальной Лизбет Цвергер!', 'Rediscover the classic Grimm fairy tales made even more mesmerizing through the delicate, poetic, and slightly mysterious art of Lisbeth Zwerger!', 'Otkrijte dobro poznate bajke braće Grim u sasvim novom, poetskom i magičnom ruhu zahvaljujući maestralnim ilustracijama Lizbet Cverger!', '/covers/DP-0354.webp', '#795c34', 'classics', 'ru', 'available', 'Для младшего школьного возраста.', '["magic","adventure","spooky"]', '["fairy tales","classics","folklore","illustrated","brothers grimm"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-355', 'DP-0355', 'Сказки', 'Fairy Tales', 'Bajke', 'Корней Чуковский', 'Korney Chukovsky', 'Kornej Čukovski', 'Конашевич', 'Малыш', NULL, NULL, 6, 14, 'middle', 'В эту красочно оформленную книгу знаменитого детского поэта и сказочника Корнея Ивановича Чуковского вошли следующие Сказки: "Муха-Цокотуха", "Тараканище", "Мойдодыр", "Чудо-дерево", "Что сделала Мура, когда ей прочитали сказку "Чудо-дерево"", "Айболит", "Бармалей", "Федорино горе", "Краденое солнце", "Телефон", "Путаница" и "Крокодил". Забавные и добрые сказки Чуковского сопровождаются такими же забавными и добрыми иллюстрациями художников В.Сутеева, В.Конашевича и В.Дувидова. В книге достаточно крупный шрифт, поэтому ребята постарше, которым уже пора читать самим, вполне смогут учиться читать по этой книге.', 'A vibrant collection of timeless rhymes and tales by beloved storyteller Korney Chukovsky, featuring gems like "Fly-Tsokotuha", "Moydodyr", "Doctor Aybolit", "Barmaley", and "The Stolen Sun", illustrated by masters V. Suteev, V. Konashevich, and V. Duvidov. With its large, clear print, it is also perfect for children taking their first steps in independent reading.', 'Raskošna zbirka bezvremenskih klasika omiljenog pisca Korneja Čukovskog, koja donosi nezaboravne priče u stihu poput „Doktora Jojbolija“, „Moidodira“, „Barmaleja“ i „Ukradenog sunca“, oživljene legendarnim ilustracijama V. Sutejeva, V. Konaševiča i V. Duvidova. Zahvaljujući krupnijem fontu, knjiga je savršen izbor i za djecu koja vježbaju samostalno čitanje.', 'Знакомые наизусть с колыбели ритмы и неунывающие герои Чуковского, к которым так радостно возвращаться в любом возрасте!', 'The bouncy rhythms and unforgettable characters of Chukovsky that delight little listeners and grown-up readers alike!', 'Pjevni stihovi i nezaboravni junaci Čukovskog kojima se s radošću vraćamo u baš svakom uzrastu!', '/covers/DP-0355.webp', '#e25822', 'classics', 'ru', 'available', '?', '["funny","animals","magic"]', '["classics","fairy tales","poetry","animals","illustrated"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-дядюшки-римуса-356', 'DP-0356', 'Сказки дядюшки Римуса', 'Tales of Uncle Remus', 'Priče čika Rimusa', 'Джоэль Чендлен Харрис', 'Joel Chandler Harris', 'Džoel Čendler Haris', 'Геннадий Калиновский', 'Речь', NULL, NULL, 6, 14, 'middle', 'Часто прибегал маленький Джоэль к старому дядюшке Римусу, чтобы послушать сказки. Про Братца Волка, Братца Медведя, Братца Черепаху, Сестрицу Лягушку, Матушку Корову… Но главное - про вечных соперников: Братца Кролика и Братца Лиса. Ну никак Лису не удавалось обмануть хитрюгу и плута Кролика! Весёлые истории о ловком Кролике и простоватом Лисе ещё в конце XIX века записал и обработал американский писатель-фольклорист Джоэль Чандлер Харрис. На русском языке часть сказок впервые была опубликована в 1936 году в ставшей уже классической обработке Михаила Гершензона, чьи тексты используются и в этом издании. В 1970-х годах Геннадий Калиновский создал иллюстрации к "Сказкам дядюшки Римуса", которые принесли художнику две престижные награды - серебряную медаль книжной ярмарки в Лейпциге и "Золотое яблоко" Международной биеннале иллюстрации в Братиславе. Выполненные в необычной технике "колючие", острые рисунки Калиновского сегодня считаются не только одной из вершин творчества художника, но и шедевром отечественной иллюстрации.', 'Little Joel loves visiting old Uncle Remus to hear timeless folklore about Brer Bear, Brer Wolf, and above all, the eternal rivalry between sly Brer Rabbit and unlucky Brer Fox. No matter what trap Fox sets, Rabbit''s wits always save the day! Originally collected in the late 19th century by Joel Chandler Harris, this classic edition features Mikhail Gershenzon''s beloved Russian adaptation and Gennady Kalinovsky''s world-renowned, award-winning scratchy illustrations.', 'Dječak Džoel često trči kod mudrog čika Rimusa da sluša priče o šumskim životinjama, a posebno o vječitim suparnicima — dovitljivom Bati Zeki i nespretnom Bati Liscu. Bez obzira na lukavstva lisca, zec uvijek pronalazi način da ga nadmudri! Ova zbirka američkih basni obogaćena je kultnim, nagrađivanim ilustracijama Genadija Kalinovskog koje vizuelno oživljavaju ove vesele i poučne priče.', 'Уморительные и мудрые сказки, доказывающие, что изобретательность и находчивость всегда побеждают клыки и когти!', 'A brilliant, witty classic proving that quick thinking and mischief will always outsmart brute force!', 'Duhovite i bezvremenske basne koje dokazuju da bistar um i dovitljivost uvijek pobjeđuju sirovu snagu!', '/covers/DP-0356.webp', '#b85d34', 'classics', 'ru', 'available', 'Для дошкольного и младшего школьного возраста.', '["funny","animals","adventure"]', '["classics","folklore","trickster","animals","bedtime stories"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('скандинавские-сказки-357', 'DP-0357', 'Скандинавские сказки', 'Scandinavian Fairy Tales', 'Skandinavske bajke', '', 'Folk Tales', 'Narodne bajke', 'Виктор Пивоваров', 'Белая ворона', NULL, NULL, 6, 14, 'middle', 'Впервые "Скандинавские сказки", проиллюстрированные московским художником-концептуалистом Виктором Пивоваровым, опубликовало "взрослое" издательство "Художественная литература" четверть века назад, в 1982 году. Книга вышла минимальным по тем временам тиражом - тридцать тысяч экземпляров, сразу превратилась в дефицит, а сегодня стала библиографической редкостью. Переводы скандинавских сказок подготовили семь лучших профессионалов своего времени. Иллюстрации в неярких, приглушенных, северных цветах с троллями, скессами, великанами, драконами и привидениями стали одной из самых масштабных книжных работ Виктора Пивоварова. Вступительную статью "О скандинавской сказке" написал знаменитый писатель Вениамин Каверин. Издательство посчитало нужным сохранить примечательные особенности знаменитой книги. В новом издании исправлены лишь опечатки, а также по просьбе художника внесены небольшие изменения в макет.', 'A rich collection of Scandinavian folk tales featuring trolls, giants, dragons, and eerie northern legends, masterfully illustrated in atmospheric, muted tones by conceptual artist Viktor Pivovarov. First published in 1982 and instantly becoming a collector''s treasure, this carefully restored edition preserves the iconic translations and poetic Nordic spirit.', 'Bogata zbirka skandinavskih narodnih bajki u kojoj oživljavaju trolovi, divovi, zmajevi i mistične sjeverne legende, uz legendarne ilustracije konceptualnog umjetnika Viktora Pivovarova. Prvi put objavljena 1982. godine, ova knjiga je postala pravi bibliofilski biser koji donosi autentičnu magiju sjevera novim generacijama čitalaca.', 'Закутайтесь в тёплый плед: эти северные сказки с троллями и туманными фьордами — настоящее произведение искусства, от которого сладко замирает сердце.', 'Wrap yourself in a cozy blanket: these northern tales of trolls and misty fjords are a hauntingly atmospheric work of art.', 'Umotajte se u toplo ćebe: ove sjeverne bajke o trolovima i maglovitim fjordovima pravo su malo umjetničko remek-djelo.', '/covers/DP-0357.webp', '#2d4a58', 'classics', 'ru', 'available', 'дома', '["magic","spooky","adventure"]', '["fairy tales","folklore","scandinavia","trolls","mythology"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-358', 'DP-0358', 'Сказки', 'Tales in Verse', 'Bajke u stihovima', 'Янош Пилински', 'János Pilinszky', 'Janoš Pilinski', 'Иштван Орос', 'КомпасГид', NULL, NULL, 6, 14, 'middle', 'Янош Пилински (1921-1981) - выдающийся венгерский поэт, удостоенный премий Ференца Баумгартена (1947), Аттилы Йожефа (1971), Лайоша Кошута (1980) и переведенный на десяток иностранных языков. Его взрослую поэзию читали и знают многие, но тот факт, что Пилински писал и стихотворные сказки для детей, для кого-то станет открытием. Обращаясь к традициям венгерского и европейского фольклора, Пилински творит светлый мир, где правда и добро одерживают верх над злом и ложью. Прекрасные принцессы, храбрые молодцы, драконы, короли, сказочные птицы - все это и знакомо, и незнакомо, и увлекает как детей, так и взрослых. Нам, русским читателям, эти произведения напомнят, конечно, сказки Пушкина. Но напомнят лишь отдаленно: иная национальная основа, иная эпоха, иное мироощущение - все это обеспечивает сказкам Яноша Пилински свою тональность, свой неповторимый колорит. Особую ценность этому сборнику придают иллюстрации всемирно известного художника Иштвана Ороса.', 'János Pilinszky (1921–1981), a celebrated Hungarian poet, weaves an enchanting collection of verse fairy tales inspired by traditional European folklore. In this luminous world of brave youths, wise kings, mystical birds, and dragons, goodness and truth inevitably prevail. Complemented by the mesmerizing artwork of world-renowned graphic artist István Orosz, this poetic anthology offers a fresh, timeless reading experience for all ages.', 'Janoš Pilinski (1921–1981), proslavljeni mađarski pjesnik, stvara čarobnu zbirku stihovanih bajki oslonjenih na evropski i mađarski folklor. U ovom svijetlom svijetu hrabrih junaka, mudrih vladara, čudesnih ptica i zmajeva, dobro i istina uvijek nadvladavaju zlo. Posebnu vrijednost ovoj zbirci daju fascinantne ilustracije svjetski poznatog grafičara Ištvana Orosa, čineći je bezvremenskim draguljem za sve generacije.', 'Мудрые и чарующие венгерские сказки в стихах, дополненные завораживающей графикой великого Иштвана Ороса.', 'Wise and enchanting Hungarian tales in verse, elevated by the mesmerizing artwork of the great István Orosz.', 'Mudre i očaravajuće mađarske bajke u stihovima, oživljene magičnim ilustracijama slavnog Ištvana Orosa.', '/covers/DP-0358.webp', '#304352', 'classics', 'ru', 'available', 'Категория: классика', '["magic","adventure"]', '["fairy tales","poetry","folklore","hungarian literature","classics"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('снежная-королева-359', 'DP-0359', 'Снежная королева', 'The Snow Queen', 'Snježna kraljica', 'Андерсен', 'Hans Christian Andersen', 'Hans Kristijan Andersen', 'Ращектаев', 'Стрекоза', NULL, NULL, 6, 14, 'middle', 'Эта сказка с таким холодным названием вот уже почти 200 лет согревает миллионы детских сердец во всем мире. Ее автор - гениальный сказочник Ханс Кристиан Андерсен (1805 - 1875).', 'This fairy tale with such a frosty title has been warming millions of children''s hearts around the world for nearly two centuries. It is one of the most celebrated works by the legendary storyteller Hans Christian Andersen.', 'Ova bajka sa tako hladnim naslovom već skoro dva vijeka grije milione dječjih srca širom svijeta. Jedno je od najljepših djela slavnog danskog bajkopisca Hansa Kristijana Andersena.', 'Запасайтесь горячим чаем: отправляемся вместе с отважной Гердой на ледяной север, чтобы растопить осколки льда силой искренней любви!', 'Grab a mug of hot cocoa and join brave Gerda on her perilous trek to the icy North to melt Kai''s frozen heart!', 'Pripremite topli čaj i krenite sa hrabrom Gerdom na daleki sjever kako biste otopili zaleđeno srce snagom iskrene ljubavi!', '/covers/DP-0359.webp', '#4b8da3', 'classics', 'ru', 'available', '?', '["magic","adventure","friends"]', '["classic fairy tale","winter","friendship","courage","quest"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гаргантюа-и-пантагрюэль-360', 'DP-0360', 'Гаргантюа и Пантагрюэль', 'Gargantua and Pantagruel', 'Gargantua i Pantagruel', 'Франсуа Рабле', 'François Rabelais', 'Fransoa Rable', 'Гюстав Доре', 'Авторская песня', 1993, '5-87060-019-7', 6, 14, 'middle', 'Известный сатирический роман великого француз­ского писателя Франсуа Рабле (1494-1553) о жизни и чудесных приключениях великана Гаргантюа и его сына Пантагрюэля в обработке для детей Николая Заболоцкого с великолепными рисунками Гюстава Доре.', 'The famous satirical masterpiece by French author François Rabelais recounts the marvelous and hilarious adventures of the giant Gargantua and his son Pantagruel, adapted for young readers by Nikolai Zabolotsky and accompanied by Gustave Doré''s iconic illustrations.', 'Čuveni satirični roman velikog francuskog pisca Fransoa Rablea o životu i čudesnim avanturama diva Gargantue i njegovog sina Pantagruela, u adaptaciji za djecu Nikolaja Zabolockog, uz veličanstvene ilustracije Gistava Dorea.', 'Приготовьтесь к колоссальным порциям смеха и приключений вместе с самыми добродушными великанами в истории мировой литературы!', 'Get ready for monumental helpings of laughter and adventure alongside the most good-natured giants in world literature!', 'Pripremite se za džinovske porcije smijeha i pustolovina sa najdobrodušnijim divovima u istoriji književnosti!', '/covers/DP-0360.webp', '#5c3a21', 'classics', 'ru', 'available', 'Для среднего школьного возраста', '["funny","adventure"]', '["giants","classics","french literature","humor","gustave dore"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленькая-баба-яга-маленькое-п-361', 'DP-0361', 'Маленькая Баба-Яга, маленькое привидение, маленький водяной', 'The Little Witch, The Little Ghost, The Little Water Sprite', 'Mala vještica, Mali duh, Mali vodeni', 'Отфрид Пройслер', 'Otfried Preussler', 'Otfrid Projsler', '', 'Эксмо', NULL, NULL, 6, 14, 'middle', 'Отфрид Пройслер (1923-2013) - известный немецкий писатель. В Германии он чрезвычайно популярен и принадлежит к числу самых известных детских писателей. Наши читатели знают Пройслера именно по сказочным повестям "Маленькая Баба-Яга", "Маленький Водяной" и "Маленькое Привидение". Все три эти знаменитые сказки собраны в одной книге.', 'Otfried Preussler (1923–2013) is one of Germany’s most renowned and beloved storytellers for young readers. This wonderful collection unites three of his timeless fairy-tale novellas: ''The Little Witch'', ''The Little Ghost'', and ''The Little Water Sprite''. Together in one volume, these mischievous, kind-hearted characters discover their world, learn how to do good, and share unforgettable adventures.', 'Otfrid Projsler (1923–2013) je čuveni njemački pisac i jedan od najomiljenijih autora dječije književnosti. Ova zbirka objedinjuje njegove tri najpoznatije bajkovite pripovijetke: „Mala vještica“, „Mali duh“ i „Mali vodeni“. U jednoj knjizi čekaju vas nestašna, topla i radoznala bića koja dokazuju da dobro srce i vedar duh čine prava čuda.', 'Три невероятно добрые сказки о маленьких волшебных созданиях, которые вместо того, чтобы всех пугать, решили дружить и творить добрые дела.', 'Three delightfully cozy classics about magical little creatures who would much rather do good deeds and make friends than scare anyone.', 'Tri predivne, tople bajke o malim čarobnim bićima koja, umjesto da plaše ljude, biraju prijateljstvo i dobra djela.', '/covers/DP-0361.webp', '#2d5a3f', 'classics', 'ru', 'available', 'Для среднего школьного возраста.', '["magic","funny","adventure"]', '["classics","fairytales","witchcraft","ghosts","german literature"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-книга-о-разбойнике-гра-362', 'DP-0362', 'Большая книга о разбойнике Грабше', 'The Big Book of Robber Grapsch', 'Velika knjiga o razbojniku Grapšu', 'Гудрун Паузеванг', 'Gudrun Pausewang', 'Gudrun Pauzevang', '', 'Белая ворона', NULL, NULL, 6, 14, 'middle', 'Грабш - потомственный разбойник, которого придумала классик немецкой детской литературы Гудрун Паузеванг. Этот заросший волосами великан наводит ужас на всю Чихенбургскую округу. Он живет в пещере среди болот в Вороновом лесу и добывает себе пропитание и одежду, грабя жителей Чихенау и Чихендорфа. Но все меняется, когда в его пещере оказывается маленькая женщина - Олли Чистик. В этой книге собраны четыре большие истории про огромную семью разбойника, который хотя в конце концов и перевоспитался, но на старости лет иногда с удовольствием вспоминает о своих былых приключениях', 'Grapsch is a rough-and-tumble robber giant who has terrorized the local townsfolk for years from his cave deep in the Raven Forest. But his rowdy bandit ways are turned upside down when a neat, brave little woman named Olli moves in. This delightful collection gathers four full stories about the giant''s ever-growing, loving bandit family and their merry adventures on the path to reform.', 'Grapš je strašni, čupavi razbojnik koji godinama plaši mještane iz svoje pećine usred Vranine šume. Međutim, njegov divlji samotnjački život potpuno se mijenja kada u pećinu zakorači sićušna i uredna gospođica Oli. Ova knjiga objedinjuje četiri tople i urnebesne priče o neobičnoj porodici, neočekivanoj ljubavi i razbojničkim nestašlucima.', 'Даже самый грозный лесной разбойник не устоит перед домашним уютом, большой семьёй и настоящей любовью!', 'Even the fiercest, hairiest forest bandit can''t resist a cozy hearth, family warmth, and true love!', 'Čak ni najstrašniji šumski razbojnik ne može odoljeti toplom domu, velikoj porodici i pravoj ljubavi!', '/covers/DP-0362.webp', '#3f6346', 'classics', 'ru', 'available', 'Для среднего школьного возраста.', '["funny","adventure","friends"]', '["robbers","family","forest","german classic","humor"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('для-маленьких-363', 'DP-0363', 'Для маленьких', 'For the Little Ones', 'Za najmlađe', 'Васнецов', 'Yuri Vasnetsov', 'Jurij Vasnjecov', '', 'Лабиринт', NULL, NULL, 6, 14, 'middle', 'Стихи известного советского поэта Александра Прокофьева радуют уже не одно поколение маленьких читателей. Замечательные рисунки Юрия Васнецова как нельзя лучше передают их мягкий сказочный колорит и радостное настроение.', 'The playful verses by renowned poet Alexander Prokofyev have brought joy to generations of young readers. Yuri Vasnetsov’s iconic, vibrant folklore illustrations perfectly capture their gentle fairy-tale warmth and cheerful spirit.', 'Razigrani stihovi poznatog pjesnika Aleksandra Prokofjeva uveseljavaju generacije malih čitalaca, dok prepoznatljive, tople narodne ilustracije Jurija Vasnjecova savršeno dočaravaju bajkovitost i vedrinu.', 'Золотая классика детской книги: душевные сказочные стихи и те самые васнецовские иллюстрации, от которых веет теплом и уютом.', 'A timeless picture-book treasure where cheerful folk rhymes meet Yuri Vasnetsov''s legendary, cozy fairytale artwork.', 'Zlatni klasik dječije književnosti: vedri stihovi i legendarne tople ilustracije koje donose čistu čaroliju djetinjstva.', '/covers/DP-0363.webp', '#d95f3b', 'classics', 'ru', 'available', 'Для детей 2-5 лет.', '["magic","animals"]', '["poetry","classics","folklore","illustrations","bedtime"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('удивительный-волшебник-из-стра-364', 'DP-0364', 'Удивительный волшебник из страны Оз', 'The Wonderful Wizard of Oz', 'Čudesni čarobnjak iz Oza', 'Лаймен Френк Баум', 'L. Frank Baum', 'L. Frenk Baum', 'Лизбет Цвергер', 'Стрекоза', NULL, NULL, 6, 14, 'middle', 'На страницах нашей книги вы увидите глазами художника любимых героев сказки Лаймена Фрэнка Баума "Удивительный волшебник из страны Оз".', 'Follow Dorothy, Toto, and their extraordinary companions along the Yellow Brick Road in a timeless journey to find heart, courage, wisdom, and home.', 'Krenite sa Doroti, Totom i njihovim neobičnim saputnicima na put od žutih cigli u bezvremenoj priči o potrazi za srcem, hrabrošću, pameću i povratkom kući.', 'Надевайте серебряные башмачки и шагайте по дороге из жёлтого кирпича — впереди ждут великие чудеса и верные друзья!', 'Slip on your silver slippers and follow the Yellow Brick Road — true courage and loyal friends are waiting at the end!', 'Obujte svoje srebrne cipele i pođite stazom od žutih cigli — čekaju vas velika čuda i najvjerniji prijatelji!', '/covers/DP-0364.webp', '#2a9d59', 'classics', 'ru', 'available', 'Для среднего школьного возраста.', '["adventure","magic","friends"]', '["classics","fairy tale","journey","friendship","fantasy"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хоббит-365', 'DP-0365', 'Хоббит', 'The Hobbit', 'Hobit', 'Толкин', 'J.R.R. Tolkien', 'Dž. R. R. Tolkin', 'Толкин', 'АСТ', NULL, NULL, 6, 14, 'middle', 'Знаменитый роман Джона Р.Р. Толкина "Хоббит" впервые публикуется на русском языке с иллюстрациями самого автора и в совершенно новом переводе Владимира Баканова и Екатерины Доброхотовой-Майковой! "В земле была нора, а в норе жил хоббит". Эта нехитрая фраза послужила началом одного из самых грандиозных и известных литературных приключений XX века. Странствия хоббита Бильбо Бэггинса покорили сердца миллионов читателей по всему миру и послужили началом возникновения удивительной вселенной - Средиземья.', 'J.R.R. Tolkien''s timeless classic, ''The Hobbit'', accompanied by the author''s original illustrations. ''In a hole in the ground there lived a hobbit.'' This simple sentence marks the beginning of one of the greatest literary quests of the twentieth century, launching Bilbo Baggins into an unforgettable journey across Middle-earth.', 'Bezvremeni klasik Dž. R. R. Tolkina, ''Hobit'', obogaćen originalnim ilustracijama samog autora. ''U jednoj rupi u zemlji živio je hobit.'' Ova jednostavna rečenica označila je početak jedne od najvećih književnih avantura dvadesetog vijeka, vodeći čitaoce na uzbudljivo putovanje kroz čarobnu Srednju zemlju.', 'Заварите чай, запаситесь печеньем и приготовьтесь шагнуть за порог навстречу драконам и великим подвигам!', 'Put the kettle on, grab your favorite blanket, and step outside into the grandest quest of all time!', 'Skuvajte čaj, uzmite omiljene kolačiće i zakoračite kroz vrata pravo u susret zmajevima i velikoj avanturi!', '/covers/DP-0365.webp', '#2d5a3f', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","magic"]', '["fantasy","dragons","middle-earth","bilbo baggins","journey"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('письма-рождественского-деда-366', 'DP-0366', 'Письма Рождественского Деда', 'Letters from Father Christmas', 'Pisma Deda Mraza', 'Толкин', 'J.R.R. Tolkien', 'Dž. R. R. Tolkin', 'Толкин', 'АСТ', NULL, NULL, 6, 14, 'middle', '"Письма Рождественского деда" - сказка, которую Толкин рассказывал своим детям на протяжении более двадцати лет (первое письмо написано старшему сыну в 1920 году и последнее - дочери в 1943). Письма приходили на Рождество, и дети на них отвечали. Рождественский Дед описывал свой дом, друзей и помощников, события, забавные, а порой тревожные, которые случались на Северном полюсе. Это чудесный подарок для каждого, кто хочет узнать Толкина не только как великого писателя, но и великого отца.', 'Letters from Father Christmas is a heartwarming collection of festive tales that J.R.R. Tolkien created for his children over the span of more than twenty years, from 1920 to 1943. Arriving each December with frosty stamps, these illustrated letters recount hilarious and thrilling escapades at the North Pole—from the clumsy antics of the North Polar Bear to underground goblin battles. A tender masterpiece showcasing Tolkien as both an unmatched world-builder and an extraordinarily loving father.', '„Pisma Deda Mraza“ su topla zbirka priča koje je Dž. R. R. Tolkin pisao i ilustrovao za svoju djecu tokom više od dvadeset godina, od 1920. do 1943. godine. Pisma su stizala svakog decembra sa sniježnim poštanskim markicama, donoseći zabavne i uzbudljive zgode sa Sjevernog pola — o nespretnom Sjevernom Polarnom Medvjedu, prazničnim vilenjacima i bitkama protiv goblina. Ova knjiga otkriva velikog pisca u ulozi privrženog i maštovitog oca.', 'Загляните на заснеженный Северный полюс и узнайте, как великий создатель Средиземья больше двадцати лет творил живое новогоднее чудо для своих детей!', 'Peek into the snowy North Pole and discover how the creator of Middle-earth spun over twenty years of pure holiday magic for his own children!', 'Zavirite na sniježni Sjeverni pol i otkrijte kako je tvorac Srednje zemlje više od dvadeset godina stvarao prazničnu čaroliju za svoju djecu!', '/covers/DP-0366.webp', '#a62828', 'classics', 'ru', 'available', 'Категория: классика', '["magic","funny","adventure"]', '["christmas","letters","north pole","family","classics"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('легенда-о-рождестенской-розе-367', 'DP-0367', 'Легенда о рождестенской розе', 'The Legend of the Christmas Rose', 'Legenda o božićnoj ruži', 'Сельма Лагерлёф', 'Selma Lagerlöf', 'Selma Lagerlef', '', 'Белая ворона', NULL, NULL, 6, 14, 'middle', 'Высоко в горах в лесной пещере жил разбойник, наводивший ужас на всю округу. Как-то раз жена разбойника вместе с детьми пожаловала в Оведский монастырь за подаянием. Монастырский цветник не впечатлил разбойницу - она поведала настоятелю, что в рождественскую ночь в их лесу распускаются волшебные цветы, равных которым нет во всем Сконе. Старый настоятель мечтает увидеть чудо своими глазами. Но можно ли доверять словам попрошайки? Эту прекрасную сказку о вере, прощении и настоящем рождественском чуде сочинила знаменитая шведская писательница Сельма Лагерлёф.', 'High in the mountains, hidden in a forest cave, lived an outlawed robber whose family terrified the province. One day, his wife visited Övid Cloister begging for alms. Unimpressed by the monastery''s manicured garden, she told the elderly abbot that on Holy Night their wild forest transforms into a heavenly blooming paradise. Yearning to witness this marvel with his own eyes, the abbot ventures into the wilderness. A timeless Scandinavian masterpiece about faith, forgiveness, and Christmas wonder by Nobel laureate Selma Lagerlöf.', 'Visoko u planinama, u šumskoj pećini, živio je razbojnik koji je ulivao strah čitavom kraju. Jednoga dana, razbojnikova žena s đecom zakucala je na vrata manastira Ovid tražeći milostinju. Manastirski vrt je nimalo nije zadivio — povjerila je starom igumanu da se u božićnoj noći njihova divlja šuma pretvara u čaroban rascvjetali raj. U želji da vidi to čudo svojim očima, iguman kreće u nepoznato. Prekrasna priča o vjeri, praštanju i božićnom čudu iz pera slavne Selme Lagerlef.', 'Невероятно трогательная рождественская притча о том, что настоящее чудо открывается лишь тем, чьё сердце свободно от сомнений и обид.', 'A breathtaking Scandinavian tale reminding us that the greatest miracles bloom only when met with an open and forgiving heart.', 'Dirljiva skandinavska bajka koja nas podsjeća da istinska čuda cvjetaju samo pred blagim i otvorenim srcem.', '/covers/DP-0367.webp', '#2d4a3e', 'classics', 'ru', 'available', 'Для младшего школьного возраста.', '["magic","adventure"]', '["christmas","winter","miracle","classics","legend"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('щелкунчик-368', 'DP-0368', 'Щелкунчик', 'The Nutcracker and the Mouse King', 'Krcko Oraščić i Kralj miševa', 'Гофман', 'E. T. A. Hoffmann', 'E. T. A. Hofman', 'Мария Михальская', 'Малыш', NULL, NULL, 6, 14, 'middle', 'В сочельник случаются чудеса: красивая нарядная ёлка, много сладостей и… ожившие игрушки, которые увлекают брата и сестру, Фрица и Мари, в мир сказочных приключений и отважных героев, в мир волшебства и рождественской тайны. Отважный Щелкунчик, Мышиный король, нежная Мари и непоседливый Франц оживают на страницах этой удивительной книги с иллюстрациями Марии Михальской. Эти иллюстрации получили медаль на биеннале в Хорватии. Мария Михальская - лауреат множества премий, в том числе и "Образ книги". Невероятно-атмосферные, трогательные, магические иллюстрации завораживают с первого взгляда и хочется самим попасть в сказку, чтобы помочь Щелкунчику в его битве с Мышиным королём!', 'On Christmas Eve, miracles happen: a sparkling tree, heaps of sweets, and toys that spring to life, whisking Fritz and Marie away into a world of daring adventure and festive enchantment. The brave Nutcracker, the villainous Mouse King, and gentle Marie come alive on the pages of this stunning edition, brought to life by award-winning illustrator Maria Mikhalskaya. Her mesmerizing, atmospheric artwork invites you straight into a timeless holiday fairy tale where courage conquers all.', 'Na Badnje veče dešavaju se prava čuda: okićena jelka, mnoštvo poslastica i igračke koje oživljavaju, vodeći Frica i Mari u svijet bajkovitih avantura i praznične magije. Hrabri Krcko Oraščić, strašni Kralj miševa i nježna Mari oživljavaju na stranicama ove predivne knjige sa nagrađivanim ilustracijama Marije Mihalske, koje očaravaju na prvi pogled i mame nas da i sami uskočimo u bajku.', 'Загляните под рождественскую ёлку: там прячется не просто деревянная игрушка, а отважный принц, готовый победить Мышиного короля!', 'Peek beneath the Christmas tree: that wooden toy is actually a brave prince ready to take on the Mouse King!', 'Zavirite ispod novogodišnje jelke: tu se ne krije samo drvena igračka, već hrabri princ spreman za megdan sa Kraljem miševa!', '/covers/DP-0368.webp', '#8c1d2e', 'classics', 'ru', 'available', 'Категория: классика', '["magic","adventure","spooky"]', '["christmas","classics","fairytale","toys","winter"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('легенда-о-короле-артуре-369', 'DP-0369', 'Легенда о короле Артуре', 'The Legend of King Arthur', 'Legenda o kralju Arturu', 'Джон Мэтьюз', 'John Matthews', 'Džon Metjuz', 'Павел Татарников', 'Рипол Кит', NULL, NULL, 6, 14, 'middle', 'Почти каждый что-нибудь когда-нибудь слышал о короле Артуре и его Круглом столе, о рыцарях Ланселоте, Тристане и Галахаде, о прекрасной Изольде и королеве Гиньевре, о волшебнике Мерлине, мече Экскалибуре и городе Камелоте. Для детей младшего школьного возраста предлагается красочно иллюстрированная книга "Легенда о короле Артуре".', 'Almost everyone has heard of King Arthur and his Round Table, the noble knights Lancelot, Tristan, and Galahad, the fair Isolde and Queen Guinevere, the wizard Merlin, the sword Excalibur, and legendary Camelot. This beautifully illustrated edition brings timeless Arthurian tales to life for young readers.', 'Gotovo svako je čuo za kralja Artura i njegov Okrugli sto, vitezove Lanselota, Tristana i Galahada, lijepu Izoldu i kraljicu Gvineviru, čarobnjaka Merlina, mač Ekskalibur i slavni Kamelot. Ova bogato ilustrovana knjiga oživljava vječne arturijanske legende za mlade čitaoce.', 'Доставайте воображаемые мечи и занимайте почётное место за Круглым столом — рыцарские подвиги начинаются прямо здесь!', 'Draw your imaginary swords and take an honorable seat at the Round Table — legendary knightly quests start right here!', 'Izvucite zamišljene mačeve i zauzmite počasno mjesto za Okruglim stolom — viteški podvizi počinju upravo ovdje!', '/covers/DP-0369.webp', '#8b1e2e', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","magic"]', '["king arthur","knights","merlin","legends","chivalry"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('золотой-ключик-или-приключения-370', 'DP-0370', 'Золотой ключик или приключения Буратино', 'The Golden Key, or the Adventures of Buratino', 'Zlatni ključić ili Buratinove pustolovine', 'Алексей Толстой', 'Alexei Tolstoy', 'Aleksej Tolstoj', 'Н. Шеварев', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Эта одна из самых любимых книжек нашей детворы. История деревянного человечка, озорного и непослушного, но доброго, искреннего и простодушного. Пройдя сквозь вереницу различных злоключений и испытаний, Буратино учится отличать добро от зла, набирается ума-разума, становится сильным и уверенным защитником для своих друзей и папы Карло. Получив от черепахи Тортилы золотой ключик и одолев злого Карабаса Барабаса, Буратино вместе с друзьями открывают свой собственный театр и начинают новую счастливую жизнь. Художник Н. Шеварев.', 'One of the most cherished children''s books of all time! It tells the tale of Buratino, a cheeky and restless yet warm-hearted and trusting wooden boy. Wandering through a whirlwind of trials and misadventures, he learns to tell right from wrong, grows into a brave protector for his friends and Papa Carlo, and receives a mysterious golden key from the ancient tortoise Tortila. Together, the puppet friends defeat the wicked Karabas Barabas and unlock the secret door to their very own dream theater. Illustrated by N. Shevarev.', 'Jedna od najomiljenijih knjiga našeg djetinjstva! Ovo je priča o nestašnom i neposlušnom, ali dobrodušnom i iskrenom drvenom dječaku Buratinu. Prolazeći kroz niz nezgoda i iskušenja, Buratino uči da razlikuje dobro od zla, stiče mudrost i postaje hrabar zaštitnik svojih prijatelja i tate Karla. Dobivši čarobni zlatni ključić od kornjače Tortile i pobijedivši zlog Karabasa Barabasa, družina otvara sopstveno pozorište i započinje novi, srećan život. Ilustrovao N. Ševarev.', 'Вечная сказка о деревянном сорванце с длинным носом, золотым сердцем и верным ключиком к настоящей дружбе!', 'A timeless tale of a cheeky wooden rascal with a long nose, a heart of gold, and the secret key to true friendship!', 'Bezvremena bajka o nestašnom drvenom dječaku dugog nosa, zlatnog srca i tajnog ključa pravog prijateljstva!', '/covers/DP-0370.webp', '#d99b26', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","friends","magic"]', '["buratino","classics","fairytale","puppets","friendship"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('удивительные-истории-из-жизни--371', 'DP-0371', 'Удивительные истории из жизни Дельфины и Маринетты', 'The Wonderful Stories of Delphine and Marinette', 'Čudesne priče o Delfini i Marineti', 'Марсель Эме', 'Marcel Aymé', 'Marsel Eme', '', 'Лабиринт', NULL, NULL, 6, 14, 'middle', 'Живут на свете две сестры, Дельфина и Маринетта. Живут они в сказках, но сказки эти очень похожи на настоящую жизнь. Написал эти сказки известный французский писатель Марсель Эме. По его словам, он услышал их от большого пушистого кота. Пересказала с французского Ирина Кузнецова. Для детей 7-9 лет.', 'Sisters Delphine and Marinette live on a French farm where the animals can talk, think, and get up to all sorts of clever mischief. Originally whispered to the author by a big fluffy cat, these delightful and humorous stories blend daily farmyard reality with timeless fairy-tale wonder.', 'Sestre Delfina i Marineta žive na francuskoj farmi gdje životinje govore, misle i prave nestašluke sa puno duha. Ove tople i duhovite priče, koje je piscu navodno ispričao jedan čupavi mačak, na neodoljiv način prepliću stvarni seoski život sa magijom bajke.', 'Французская классика от лица пушистого кота: озорные сёстры, говорящие коровы и волки, с которыми легко договориться!', 'French farmyard classics told by a cat: meet two witty sisters and farm animals who always know how to outsmart adults!', 'Francuski klasik koji je navodno šapnuo jedan mačak: oštroumne sestre i životinje koje uvijek nadmudre odrasle!', '/covers/DP-0371.webp', '#e07a38', 'classics', 'ru', 'available', 'Категория: классика', '["funny","animals","magic"]', '["farm animals","talking animals","sisters","french classics","mischief"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('истории-тряпичного-энди-372', 'DP-0372', 'Истории тряпичного Энди', 'Raggedy Andy Stories', 'Priče o Krpenom Endiju', 'Дженни Груэл', 'Johnny Gruelle', 'Džoni Gruel', '', 'Вектор', NULL, NULL, 6, 14, 'middle', 'Тряпичный Энди - добрый друг Тряпичной Энн, живущий в детской девочки Марселлы. Как только Энди появился, куклы сразу полюбили его за широкую улыбку и весёлый нрав. А кто ещё мог придумать сделать конфеты для детей или кататься со свистом по водосточному жёлобу? Только замечательный тряпичный мальчишка, который всё превращает в интересную игру. И даже Пасхальный кролик пригласил Энди и кукол в гости, чтобы они увидели настоящие чудеса. А как волновались игрушки, когда Тряпичный Энди застрял в водосточной трубе! Для детей дошкольного возраста. Для чтения взрослыми детям.', 'Meet Raggedy Andy, the cheerful yarn-haired boy doll and loyal friend of Raggedy Ann! Living in Marcella''s cozy nursery, Andy wins everyone''s heart with his sunny smile and lively spirit. Whether he''s making molasses candy, sliding down the rain gutter, or paying a magical visit to the Easter Bunny, Raggedy Andy turns every secret hour into pure joy.', 'Upoznajte Krpenog Endija, veselog krpenog dječaka i nerazdvojnog prijatelja Krpene En! Živeći u ušuškanoj dječjoj sobi djevojčice Marsele, Endi osvaja sve igračke zaraznim osmijehom i nepresušnom maštom. Bilo da kuva bombone, spušta se niz oluk ili putuje u posjetu Uskršnjem zecu, on svaki trenutak pretvara u čistu čaroliju.', 'Узнайте, что затевают игрушки, когда дети засыпают — спойлер: варят карамель и катаются с ветерком по водосточной трубе!', 'Ever wonder what toys get up to after bedtime? Spoiler: they make homemade candy and slide down drainpipes!', 'Zavirite u sobu sa igračkama kad djeca zaspe — spojler: kuvaju bombone i jure niz oluk sa osmijehom!', '/covers/DP-0372.webp', '#3a6ea5', 'classics', 'ru', 'available', 'Категория: классика', '["friends","adventure","magic"]', '["classic","dolls","toys","friendship","bedtime"]', 1792836322696, 1792845634844);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-373', 'DP-0373', 'Сказки', 'Fairy Tales', 'Bajke', 'Ханс Кристиан Андерсен', 'Hans Christian Andersen', 'Hans Kristijan Andersen', 'Ника Гольц', '', NULL, NULL, 6, 14, 'middle', 'Ханс Кристиан Андерсен (1805-1875) завоевал всемирную любовь благодаря своим сказкам, которые, как он сам утверждал, были написаны для взрослых. Однако не только взрослым, но и детям они очень полюбились. В книгу вошли "Гадкий утёнок", "Огниво", "Свинопас", "Дикие лебеди" и многие другие известные сказки. Их проиллюстрировала Ника Гольц (1925-2012) - заслуженный художник Российской Федерации и обладатель диплома Х.К. Андерсена. Благодаря художнику даже самая страшная сказка приобрела добрые и светлые очертания, а отрицательные персонажи сказок получились не отпугивающими. За удивительную способность проникаться чувством глубокого уважения к маленькому читателю Нику Гольц полюбили читатели всех возрастов. Для среднего школьного возраста', 'Hans Christian Andersen won hearts worldwide with fairy tales that, though originally intended for adults, became timeless treasures for readers of all ages. This volume includes classics such as ''The Ugly Duckling'', ''The Tinderbox'', ''The Swineherd'', and ''The Wild Swans''. Illustrated by the renowned Nika Golts, Andersen''s diploma laureate, these pages bring warmth and gentle light even to the darker corners of the tales.', 'Hans Kristijan Andersen osvojio je svijet svojim bajkama za koje je govorio da su pisane za odrasle, ali su ih najdublje zavoljela djeca. Ova zbirka obuhvata bisere poput „Ružnog pačeta“, „Kresiva“, „Svinjara“ i „Divljih labudova“, uz predivne ilustracije Nike Golc koje svakoj priči daruju svjetlost, dobrotu i vanvremensku čaroliju.', 'Вечная классика Андерсена с невероятно нежными иллюстрациями Ники Гольц, которые дарят тепло даже самым грустным сказочным сюжетам.', 'Timeless Andersen fairy tales brought to life by Nika Golts''s delicate art, wrapping even the bittersweet moments in warmth and wonder.', 'Vječne Andersenove bajke oživljene nježnim ilustracijama Nike Golc koje svakoj priči donose nevjerovatnu toplinu i čaroliju.', '/covers/DP-0373.webp', '#38657d', 'classics', 'ru', 'available', 'Категория: классика', '["magic","adventure"]', '["fairy tales","classics","danish literature","illustrations","growing up"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('принц-и-нищий-374', 'DP-0374', 'принц и нищий', 'The Prince and the Pauper', 'Kraljević i prosjak', 'Марк Твен', 'Mark Twain', 'Mark Tven', 'перевод Корней Чуковский', '', NULL, NULL, 6, 14, 'middle', 'Жизнь порой преподносит удивительные сюрпризы. Ещё вчера Том Кенти, сын самого обычного бедняка из Двора Отбросов, засыпал голодный на охапке соломы, а сегодня он — принц Англии, наследник королевского престола. Как же такое могло случиться? Случай свёл двух похожих друг на друга мальчиков с разными судьбами, чтобы проверить, кто достойно пройдёт выпавшие испытания, а кого ослепит тщеславие и гордость.', 'Life can deliver the most astonishing twists. Just yesterday, Tom Canty, a poor boy from London''s Offal Court, fell asleep hungry on a bed of straw—and today he is the Prince of England and heir to the throne! A chance encounter brings two identical boys from opposite worlds together, testing their character, kindness, and courage as each steps into the other''s shoes.', 'Život ponekad priređuje nevjerovatna iznenađenja. Još juče je Tom Kenti, dječak iz siromašnog londonskog dvorišta, zaspao gladan na slami, a već danas je postao princ Engleske i prijestolonasljednik. Slučajan susret spojiće dva identična dječaka potpuno različitih sudbina kako bi provjerio ko će se dostojanstveno nositi sa izazovima, a koga će zaslijepiti ponos i taština.', 'Что, если поменяться местами с принцем всего на день? Классическая история о том, что корона не делает человека благородным, а лохмотья — недостойным.', 'What if you could trade shoes with a prince for just one day? A timeless adventure proving that true nobility lies in the heart, not the crown.', 'Šta ako biste samo na jedan dan zamijenili uloge sa kraljevićem? Legendarna priča koja dokazuje da se pravo plemstvo krije u srcu, a ne u kruni.', '/covers/DP-0374.webp', '#8a1c27', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","real"]', '["classics","royalty","identity swap","england","mark twain"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('остров-сокровищ-375', 'DP-0375', 'Остров сокровищ', 'Treasure Island', 'Ostrvo s blagom', 'Роберт Льюис Стивенсон', 'Robert Louis Stevenson', 'Robert Luis Stivenson', 'серия Внеклассное чтение', '', NULL, NULL, 6, 14, 'middle', 'Какой мальчишка не мечтает отправиться в путешествие на поиски сокровищ? Джим Хокинс, сын трактирщика, волею случая оказывается обладателем карты, с помощью которой можно отыскать золото знаменитого капитана Флинта. Но сможет ли Джим вместе с товарищами разгадать тайну этой карты и найти сокровища?', 'What young adventurer hasn''t dreamed of setting sail in search of hidden riches? Jim Hawkins, an innkeeper''s son, unexpectedly gets hold of a map leading to the legendary buried gold of Captain Flint. But can Jim and his companions outsmart cunning pirates and survive the perilous voyage?', 'Koji dječak ne sanja o tome da zaplovi u potragu za skrivenim blagom? Džim Hokins, sin krčmara, sticajem okolnosti dolazi do mape koja vodi pravo do zlata ozloglašenog kapetana Flinta. Ali, da li će Džim i njegovi prijatelji uspjeti da nadmudre lukave pirate i pronađu tajanstveno blago?', 'Свистать всех наверх: берегитесь Джона Сильвера, держите карту крепче и приготовьтесь к главному морскому приключению детства!', 'All hands on deck: keep a sharp eye on Long John Silver, clutch that map tight, and dive into the ultimate seafaring adventure!', 'Svi na palubu: čuvajte se Dugačkog Džona Silvera, čvrsto držite mapu i uskočite u najveću pomorsku avanturu svih vremena!', '/covers/DP-0375.webp', '#27566b', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","friends"]', '["pirates","treasure hunt","sea adventures","classics","courage"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-чиполлино-376', 'DP-0376', 'Приключения Чиполлино', 'The Adventures of Cipollino', 'Čipolinove pustolovine', 'Джанни Родари', 'Gianni Rodari', 'Đani Rodari', 'илл. Вадим Челак', '', NULL, NULL, 6, 14, 'middle', 'Известная сказка итальянского писателя Джанни Родари, рассказывающая о приключениях мальчика-луковки в фруктово-овощной стране. Среди персонажей сказки Кавалер Помидор, Графини Вишни, Кум Тыква. Сказка в классическом переводе Златы Потаповой выходит с прекрасными, тонкими и ироничными иллюстрациями Вадима Челака. Эта книга поможет вернуться в детство родителям, дедушкам и бабушкам, а маленьким читателям— вступить в новую сказку с чудесными живыми картинками .', 'The beloved classic tale by Italian author Gianni Rodari follows the plucky little onion boy, Cipollino, as he stands up for justice against greedy rulers in a colorful kingdom of fruits and vegetables. Alongside loyal friends like Godfather Pumpkin and Little Cherry, Cipollino proves that courage and kindness can topple even the haughtiest tyrants like Signor Tomato and Prince Lemon.', 'Čuvena bajka italijanskog pisca Đanija Rodarija donosi uzbudljivu priču o neustrašivom dječaku-luku Čipolinu, koji se bori za pravdu i slobodu u kraljevstvu oholih voćki i povrća. Uz pomoć odanih prijatelja poput Kuma Bundeve i Grofića Višnjice, Čipolino dokazuje da hrabrost i drugarstvo mogu nadmudriti Sinjora Paradajza i Princa Limuna.', 'Приготовьтесь плакать только от смеха: неунывающий луковый мальчишка покажет зазнавшимся фруктовым вельможам, что такое настоящая дружба и справедливость!', 'Get ready to cry only tears of laughter, as the spunky onion boy shows sour-faced tyrants what true friendship and courage can do!', 'Pripremite se da pustite suzu samo od smijeha, jer hrabri dječak-luk uči uobražene vladare šta zaista znače prijateljstvo i pravda!', '/covers/DP-0376.webp', '#e07a2c', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","funny","friends"]', '["classics","fairytale","friendship","justice","vegetables"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-барона-мюнгхаузена-377', 'DP-0377', 'Приключения барона Мюнгхаузена', 'The Adventures of Baron Munchausen', 'Pustolovine barona Minhauzena', 'Эрих Распэ', 'Rudolf Erich Raspe', 'Rudolf Erih Raspe', 'илл. Алимов, перевод К. Чуковский', '', NULL, NULL, 6, 14, 'middle', 'Знаменитая книга Рудольфа Эриха Распе (1736-1794) о невероятных приключениях "самого правдивого человека на Земле", великолепного барона Мюнхаузена, пересказанная для детей Корнеем Ивановичем Чуковским (1882-1969), входит в золотой фонд отечественной детской литературы. Несомненным украшением книги являются весёлые и тоже "очень правдивые" иллюстрации Сергея Алимова. Для младшего школьного возраста.', 'The legendary tales of Rudolf Erich Raspe recount the unbelievable exploits of Baron Munchausen, self-proclaimed as the most truthful man on Earth. From riding cannonballs across battlefields to pulling himself out of a swamp by his own hair, these delightfully absurd tall tales have captivated generations of young dreamers and lovers of humor.', 'Čuvena knjiga Rudolfa Eriha Raspea donosi nevjerovatne priče o podvizima barona Minhauzena, „najiskrenijeg čovjeka na svijetu”. Od jahanja na topovskom đuletu do izvlačenja samog sebe iz močvare za sopstvenu periku, ove duhovite i vesele lovačke priče dio su zlatnog fonda dječje književnosti.', 'Полетать на пушечном ядре или вытащить себя за косичку из болота? Для барона нет ничего невозможного!', 'Fancy a flight on a cannonball or pulling yourself out of a swamp by your own pigtail? Nothing is impossible for the Baron!', 'Letjeti na topovskom đuletu ili se izvući iz močvare za sopstveni repić? Za barona ništa nije nemoguće!', '/covers/DP-0377.webp', '#b83b26', 'classics', 'ru', 'available', 'Категория: классика', '["funny","adventure"]', '["classics","tall tales","humor","inventions","travel"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лиловый-шар-378', 'DP-0378', 'Лиловый шар', 'The Lilac Ball', 'Ljubičasta kugla', 'Кир Булычов', 'Kir Bulychev', 'Kir Buličov', 'илл. Евгения Мигунова', '', NULL, NULL, 6, 14, 'middle', 'Экипаж космического корабля обнаруживает в заброшенной инопланетной станции данные о доставленном на Землю много тысяч лет назад лиловом шаре, в котором находится вирус вражды. Этот вирус может привести к гибели людей. Бесстрашная девочка Алиса на машине времени отправляется в эпоху легенд, чтобы найти и обезвредить лиловый шар.', 'The crew of a spaceship discovers records on an abandoned alien station revealing that thousands of years ago, a mysterious lilac ball containing an enmity virus was brought to Earth. If it opens, humanity will perish. Fearless schoolgirl Alisa boards a time machine and travels back into the legendary mythical era to track down and neutralize the dangerous sphere.', 'Posada svemirskog broda na napuštenoj vanzemaljskoj stanici otkriva podatke o misterioznoj ljubičastoj kugli koja je prije više hiljada godina donijeta na Zemlju i u kojoj se krije virus neprijateljstva. Kako bi spasila čovječanstvo od propasti, neustrašiva djevojčica Alisa sjeda u vremensku mašinu i putuje u eru bajki i legendi da pronađe i neutrališe opasnu kuglu.', 'Запрыгивайте в машину времени вместе с Алисой: спасать мир от древнего вируса вражды в компании сказочных героев — дело невероятно захватывающее!', 'Hop into the time machine with Alisa: saving humanity from an ancient hatred virus alongside legendary mythical creatures is the ultimate sci-fi quest!', 'Uskočite u vremensku mašinu sa Alisom: spašavanje svijeta od drevnog virusa mržnje u društvu bajkovitih bića prava je svemirska avantura!', '/covers/DP-0378.webp', '#6a407e', 'classics', 'ru', 'available', 'Категория: классика', '["adventure","magic"]', '["sci-fi","time travel","space","classic","heroines"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('незнайка-в-солнечном-городе-379', 'DP-0379', 'Незнайка в солнечном городе', 'Dunno in Sun City', 'Neznajko u Sunčanom gradu', 'Николай Носов', 'Nikolay Nosov', 'Nikolaj Nosov', '', '', NULL, NULL, 6, 14, 'middle', '«Незнайка в Солнечном городе» – вторая часть знаменитой трилогии замечательного классика детской литературы о Незнайке и его друзьях – малышах из Цветочного города. Однажды у Незнайки появился волшебный автомобиль, и Незнайка с Кнопочкой отправились на нём в Солнечный город – за новыми приключениями…', 'The second installment of the beloved classic trilogy follows Dunno and his friend Button as they set off in a wondrous automobile on a journey to Sun City. Armed with a real magic wand, Dunno encounters a futuristic wonderland of dazzling inventions, talking machines, and hilarious mix-ups.', 'Drugi dio čuvene trilogije Nikolaja Nosova prati Neznajka i njegovu drugaricu Dugmicu na putovanju u Sunčani grad. Naoružan pravim čarobnim štapićem i neobičnim automobilom, Neznajko otkriva grad budućnosti prepun nevjerovatnih izuma, robota i urnebesnih zavrzlama.', 'Запрыгивайте в чудо-машину: вас ждет путешествие в город будущего с роботами, превращениями и самыми добрыми проделками Незнайки!', 'Hop into the wonder-car for a whirlwind tour of a futuristic utopia powered by wacky inventions, a real magic wand, and Dunno''s unforgettable mischief!', 'Uskočite u čudesni automobil i pođite u grad budućnosti prepun robota, magije i Neznajkovih neodoljivih nestašluka!', '/covers/DP-0379.webp', '#f4a226', 'classics', 'ru', 'available', 'Категория: классика', '["funny","adventure","magic"]', '["classic","magic wand","inventions","fairy tale","friendship"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мэри-поппинс-380', 'DP-0380', 'Мэри Поппинс', 'Mary Poppins', 'Meri Popins', 'Памела Трэверс', 'P. L. Travers', 'P. L. Travers', 'илл. Вадим Челак', '', NULL, NULL, 6, 14, 'middle', 'Знаменитая сказочная повесть английской писательницы Памелы Трэверс о необыкновенной няне Мэри Поппинс, которая появляется неизвестно откуда вместе с западным ветром и исчезает, когда ей заблагорассудится. Ее любят дети во всех странах мира. Еще бы! Ведь она понимает язык зверей и птиц, а когда бывает в хорошем настроении, может даже взлететь под потолок. Повесть в пересказе Бориса Заходера. "Вы знакомы с Мэри Поппинс? Нет? Очень, очень странно! Ведь она необычайно знаменита! Про нее написаны не одна, не две и даже не три, а целых четыре книжки! А вспомните - даже про такие знаменитости, как Робинзон Крузо или Буратино, написано всего по одной книжке! О Мэри Поппинс надо прежде всего сказать, что... Впрочем, замечу только, что, если Мэри Поппинс покажется вам сначала слишком строгой и даже суровой, не пугайтесь. Если бы она была только строгой, ее вряд ли бы так полюбили все без исключения ребята, которым удалось познакомиться с Мэри"', 'The famous classic tale by P. L. Travers introduces the world''s most extraordinary nanny, Mary Poppins, who arrives at Number Seventeen Cherry Tree Lane blown in by the East Wind. Beloved by generations, she slides up banisters, understands the speech of animals, pulls an entire armchair out of an empty carpet bag, and reminds us all that everyday life can become pure magic.', 'Čuvena klasična priča Pamele Travers predstavlja najneobičniju dadilju na svijetu, Meri Popins, koja stiže u Trešnjinu ulicu nošena istočnim vjetrom. Obožavana od generacija djece, ona klizi uz gelender, razumije jezik životinja i ptica, iz prazne torbe vadi čitav namještaj i podsjeća nas da svakodnevica u trenu može postati prava čarolija.', 'Если вы думаете, что няни бывают только строгими и скучными, раскройте зонтик и приготовьтесь к невероятным полётам и чудесам с Мэри Поппинс!', 'Open your parrot-headed umbrella and get ready for pure wonder—because life is never ordinary when Mary Poppins is in charge!', 'Otvorite kišobran i spremite se za pravu čaroliju — jer uz Meri Popins nijedan dan ne može biti običan i dosadan!', '/covers/DP-0380.webp', '#28497a', 'classics', 'ru', 'available', 'Категория: классика', '["magic","funny","adventure"]', '["волшебство","няня","классика","семья","чудеса"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('book-381', 'DP-0381', '', 'Old Genie Khottabych', 'Starac Hotabič', 'Старик Хотабыч', 'Lazar Lagin', 'Lazar Lagin', 'Лазарь Лагин, илл. Г. Вальк', '', NULL, NULL, 6, 14, 'middle', 'Волька Костыльков и не предполагал, к чему может привести обычное купание в речке: таинственный сосуд, необычный старичок с волшебной бородой, полёт на ковре-самолёте и многое-многое другое. Захватывающие приключения, добрый юмор и курьёзные происшествия ждут на страницах чудесной сказки, которая научит честности, справедливости, заботе о близких, верности и настоящей дружбе. Серия «Книги для внеклассного чтения» — это подборка главных произведений русских и зарубежных авторов, входящих в школьную программу. Лучшие произведения детской литературы с цветными иллюстрациями помогут привить ребёнку любовь к чтению.', 'Schoolboy Volka Kostylkov never imagined what a simple dive in the river would bring: a mysterious ancient jug, an extraordinary old genie with a magical beard, carpet flights, and plenty of hilarious mix-ups. A classic adventure celebrating genuine friendship, kindness, and magic in everyday life.', 'Školarac Voljka Kostiljkov nije ni slutio do čega može dovesti obično kupanje u rijeci: tajanstvena drevna posuda, neobični starac sa čarobnom bradom, let na letećem ćilimu i bezbroj komičnih nezgoda. Klasik dječje književnosti koji slavi pravo prijateljstvo, dobrotu i magiju svakodnevnog života.', 'Осторожно: выдёргивая волосок из бороды доброго джинна Хоттабыча, можно случайно наколдовать табун слонов или мраморный дворец прямо посреди города!', 'Watch out: one pluck of a hair from genie Khottabych''s beard might conjure a herd of elephants or a marble palace right in the middle of town!', 'Oprezno: samo jedna iščupana dlaka iz brade dobrog duha Hotabiča može stvoriti krdo slonova ili mermernu palatu usred grada!', NULL, '#e0892c', 'classics', 'ru', 'available', 'Категория: классика', '["funny","adventure","magic"]', '["genie","magic","friendship","classics","humor"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-книга-стихов-382', 'DP-0382', 'Большая книга стихов', 'The Big Book of Poems', 'Velika knjiga pjesama', 'Агния Барто', 'Agniya Barto', 'Agnija Barto', '', '', NULL, NULL, 6, 14, 'middle', 'Стихи Агнии Львовны Барто - это необыкновенная, удивительная страна детства, радости, веселья. Нет ни одного читателя, которого ее произведения оставили бы равнодушным. Добрые, трогательные, озорные стихотворения помогут ребенку по-иному взглянуть на окружающий мир и увидеть, сколько в нем разноцветных красок, света, улыбок. Вырастая, юный читатель еще не раз будет возвращаться к любимым стихотворениям, открывая для себя что-то новое и прекрасное. "Большая книга стихов" Агнии Барто - несомненно, лучший подарок вашему ребенку! Пусть его знакомство с волшебным миром детской литературы начнется с этих замечательных стихотворений!', 'Agniya Barto''s poetry is a magical world of childhood, joy, and laughter. These warm, touching, and playful verses help young readers see the vibrant colors and smiles in everyday life. Growing up, children will return to these beloved lines again and again, discovering fresh wonders each time. A timeless classic and a wonderful gift for any bookshelf!', 'Pjesme Agnije Barto otvaraju čudesan svijet djetinjstva, radosti i vedrine. Ovi topli, dirljivi i nestašni stihovi pomažu djeci da uoče ljepotu i osmijehe u svakodnevnom životu. Odrastajući, mali čitaoci će se iznova vraćati ovim dragim rimama, svaki put otkrivajući nešto novo i lijepo. Bezvremenski klasik i savršen poklon za svako dijete!', 'Любимые строчки, которые согревают с первых шагов и остаются с нами навсегда — читайте вслух всей семьёй!', 'Timeless rhymes that turn everyday moments into sunny childhood adventures meant to be read aloud together!', 'Bezvremeni stihovi uz koje su odrastale generacije, stvoreni za toplo zajedničko čitanje naglas!', '/covers/DP-0382.webp', '#e67e22', 'classics', 'ru', 'available', 'Категория: классика', '["funny","friends","real"]', '["поэзия","стихи","классика","детство","юмор"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('нет-насилию-383', 'DP-0383', 'Нет насилию', 'Never Violence!', 'Ne nasilju!', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Стина Вирсен', 'Белая ворона', NULL, NULL, 6, 14, 'middle', 'В 1978 году Астрид Линдгрен выступила со знаменитой речью в защиту прав детей на вручении престижной Премии мира немецких книготорговцев. Выступление писательницы наделало много шума. Благодаря нему начались споры о телесных наказаниях и правах ребенка. Спустя 40 лет вопрос о воспитании детей еще не решен однозначно, и мы надеемся, что выход книги напомнит о недопустимости любого насилия. В издание на русском языке войдет послесловие психолога Людмилы Петрановской и стихотворение Астрид Линдгрен «Будь я Богом».', 'In 1978, Astrid Lindgren delivered her groundbreaking speech defending children''s rights upon receiving the Peace Prize of the German Book Trade. Her passionate words ignited vital conversations on corporal punishment and child welfare that changed history. Decades later, her timeless appeal remains an urgent, compassionate call to raise future generations in empathy, dignity, and love.', 'Godine 1978, Astrid Lindgren je održala čuveni govor u odbranu dječjih prava prilikom primanja Mirovne nagrade njemačkih knjižara. Njeno obraćanje pokrenulo je važne rasprave o tjelesnom kažnjavanju i pravima djeteta širom svijeta. Decenijama kasnije, ova knjiga snažno podsjeća na nedopustivost bilo kog oblika nasilja i važnost odrastanja u ljubavi.', 'Мудрое и горячее напоминание от любимой сказочницы о том, что мир без жестокости начинается с безусловного уважения к ребенку.', 'A deeply moving and powerful plea from our favorite storyteller that a peaceful world begins with unconditional love and respect for children.', 'Duboko dirljiv i snažan podsjetnik voljene spisateljice da miran svijet počinje bezuslovnim poštovanjem i ljubavlju prema djetetu.', '/covers/DP-0383.webp', '#c0392b', 'classics', 'ru', 'available', 'Категория: Астрид Линдгрен', '["real"]', '["children''s rights","parenting","peace","astrid lindgren","empathy"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('не-спит-лишь-гном-384', 'DP-0384', 'Не спит лишь гном', 'The Tomten', 'Patuljak bdi', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Китти Краутер', 'Белая ворона', NULL, NULL, 6, 14, 'middle', 'На дворе глубокая ночь. Где-то в лесной чаще под покровом снега уснул старый хутор и все его обитатели. Не спит лишь маленький гном. В свете луны он тихонько крадется по двору. Пришло время ночного обхода: надо заглянуть в хлев, на конюшню, навестить курятник, амбар. Книга проникнута благоговением перед жизнью и заботой обо всех живых существах.', 'Deep into a snowy winter night, an old farm sleeps peacefully beneath the silent forest canopy. Only the little Tomten is awake, quietly padding through the moonlight to check on the cows, horses, sheep, and hens. A tender, timeless tale steeped in gentle wonder, peace, and loving care for every living soul.', 'Usred duboke sniježne noći, staro seosko imanje mirno spava pod okriljem tihe šume. Budan je jedino mali patuljak čuvar. Pod mjesečinom se nečujno šunja po dvorištu, provjerava staju, konjušnicu i kokošinjac, brinući o svima. Nježna priča ispunjena mirom i brigom za sva živa bića.', 'Идеальная сонная книга о крошечном хранителе, который шепчет зверям добрые сны морозной зимней ночью.', 'The ultimate bedtime classic about a tiny winter guardian whispering sweet dreams to sleeping farm animals.', 'Najljepša zimska priča za laku noć o malom čuvaru koji šapuće tople snove usnulim životinjama.', '/covers/DP-0384.webp', '#283b54', 'classics', 'ru', 'available', 'Категория: Астрид Линдгрен', '["magic","animals"]', '["winter","snow","night","bedtime","folklore","care"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('теленок-на-рождество-385', 'DP-0385', 'Теленок на Рождество', 'A Calf for Christmas', 'Tele za Božić', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Марит Торнквист', 'Добрая книга', NULL, NULL, 6, 14, 'middle', 'Накануне Рождества в семью Юхана приходит беда: умирает их единственная корова, и у мамы с папой нет денег на покупку новой. Но оказывается, что в самых тяжёлых жизненных ситуациях обстоятельства зачастую складываются столь удивительным образом, что происходящее кажется настоящим чудом - словно высшие силы плетут ткань нашей жизни так, чтобы оберегать нас, и уравновешивают добром всякое творящееся в мире зло. Эта замечательная рождественская история Астрид Линдгрен, ставшая классикой детской литературы, впервые выходит в свет в переводе на русский язык с великолепными иллюстрациями голландской художницы Марит Торнквист. Для детей достигших возраста 6-ти лет.', 'On Christmas Eve, tragedy strikes young Johan''s family when their only cow dies and his parents have no money to buy another. Yet in life''s hardest moments, quiet miracles happen, balancing hardship with kindness. Astrid Lindgren''s heartwarming holiday classic, beautifully illustrated by Marit Törnqvist, is an inspiring tale of community, compassion, and hope.', 'Uoči Božića, Johanovu porodicu zadesi nevolja: uginula im je jedina krava, a roditelji nemaju novca za drugu. Ipak, u najtežim trenucima događaju se tiha čuda, kao da skrivena dobrota tka naš svijet donoseći utjehu kada je najpotrebnija. Ova prelijepa božićna priča Astrid Lindgren pravo je svjedočanstvo o saosjećanju, nadi i toplini zajedništva.', 'Щемящая и добрая зимняя история от Астрид Линдгрен, напоминающая, что даже в самый морозный день надежда и добро обязательно согреют дом.', 'A tender, snow-dusted tale by Astrid Lindgren that gently proves unexpected kindness and quiet miracles always find their way home for Christmas.', 'Nježna, snijegom obavijena priča Astrid Lindgren koja podsjeća da dobrota i neočekivana čuda uvijek pronađu put do naših srca.', '/covers/DP-0385.webp', '#a3382c', 'classics', 'ru', 'available', '6+', '["animals","real"]', '["christmas","winter","cows","kindness","swedish classics"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мио-мой-мио-386', 'DP-0386', 'Мио, мой Мио', 'Mio, My Son', 'Mio, moj Mio', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Владимир Аникин', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Хорошо, если у тебя есть и папа и мама. А если ты совсем один? Если тебе одиноко, как невыносимо одиноко девятилетнему мальчику Буссе из сказочной повести Астрид Линдгрен? Тогда воображение может унести тебя в Страну Далёкую, где король – твой отец, а сам ты прекрасный принц Мио. И даже если тебе грозит опасность и придётся сразиться с ужасным и коварным рыцарем Като, ты способен преодолеть любой страх, потому что в той волшебной стране всё, о чём ты мечтаешь, обязательно сбудется.', 'It''s wonderful to have loving parents, but what if you are completely alone like nine-year-old Bosse? Whispered away to the magical Land of Faraway, he discovers that his father is the King and he is Prince Mio. But dark forces loom: Mio must mount his flying steed and face the terrifying Knight Kato, finding the courage within himself to save stolen children and conquer deep-rooted fear.', 'Divno je imati roditelje, ali šta ako si sasvim sam na svijetu poput devetogodišnjeg dječaka Bosea? Čarolija ga odvodi u Daleku zemlju, gdje saznaje da je njegov otac kralj, a on princ Mio. Ipak, pred njim je opasna misija: mora se suočiti sa strašnim vitezom Katom kamenog srca i dokazati da hrabrost i ljubav pobjeđuju i najdublje strahove.', 'Пронзительная и величественная сказка о том, как одинокий мальчик находит отца, верного коня и смелость победить даже каменное сердце.', 'A breathtaking, poetic fairy tale proving that love, a faithful horse, and an open heart can melt even the coldest stone.', 'Dirljiva i uzvišena bajka koja podsjeća da ljubav, odani prijatelji i hrabrost mogu pobijediti i najmračnije sile.', '/covers/DP-0386.webp', '#2c3e6b', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["magic","adventure","friends"]', '["classics","bravery","friendship","fantasy quest","horses"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('знаешь-ли-ты-пеппи-длинныйчуло-387', 'DP-0387', 'Знаешь ли ты Пеппи Длинныйчулок?', 'Do You Know Pippi Longstocking?', 'Da li znaš Pipi Dugu Čarapu?', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Ингрид Ванг Нюман', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Книжка «Знаешь ли ты Пеппи Длинныйчулок?» является ярким дополнением к известной истории про девочку с рыжими косичками. В ней собраны три рассказа, в которых Астрид Линдгрен по-новому описала самые важные моменты из жизни Пеппи и которые замечательная шведская художница Ингрид Ванг Нюман красочно проиллюстрировала. В книжке очень много картинок, и она будет интересна и тем, кто уже знаком с Пеппи, и тем, кто только собирается с ней познакомиться.', '"Do You Know Pippi Longstocking?" is a delightful picture book bringing together three classic stories about the world''s strongest, most mischievous red-haired girl. Richly illustrated with the iconic original artwork of Ingrid Vang Nyman, it is the perfect introduction for beginners as well as a joyous treat for longtime fans.', 'Knjiga „Da li znaš Pipi Dugu Čarapu?” predivan je slikoviti uvod u pustolovine najjače pjegave djevojčice na svijetu. Sadrži tri priče koje je Astrid Lindgren iznova oživjela uz originalne, vesele ilustracije Ingrid Vang Niman, savršene kako za one koji Pipi tek upoznaju, tako i za njene vjerne obožavaoce.', 'Познакомьтесь с самой сильной и весёлой девчонкой на свете — рыжие косички, чемодан золота и море смеха прилагаются!', 'Meet the strongest, wildest girl in the world—red braids, a suitcase full of gold, and unstoppable fun included!', 'Upoznajte najjaču i najsmješniju djevojčicu na svijetu — crvene pletenice, kofer pun zlata i beskrajna zabava su zagarantovani!', '/covers/DP-0387.webp', '#e66728', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["funny","adventure","friends"]', '["pippi longstocking","astrid lindgren","classics","picture book","humor"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пеппи-длинныйчулок-388', 'DP-0388', 'Пеппи Длинныйчулок', 'Pippi Longstocking', 'Pipi Duga Čarapa', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Ингрид Ванг Нюман', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Героиня сказочной повести АСТРИД ЛИНДГРЕН Пеппи Длинныйчулок – великая фантазёрка и выдумщица. Рядом с ней никому не хочется становиться взрослым. У неё даже есть пилюли, которые помогают детям не взрослеть. Да и зачем, если «взрослых вечно донимают мозоли, налоги и всякие другие неприятности»?! И хотя порой Пеппи ведёт себя очень странно, она самая добрая, самая удивительная, самая лучшая девочка на свете. В книге использованы оригинальные рисунки замечательной художницы Ингрид Ванг Нюман, которые создавались в сотрудничестве с самой писательницей. Именно с этими иллюстрациями книга «Пеппи Длинныйчулок» впервые вышла в свет и стала бестселлером.', 'Pippi Longstocking, the heroine of Astrid Lindgren''s beloved story, is an extraordinary dreamer and inventor. Around her, no one ever wants to grow up—after all, why bother when adults are plagued by taxes, corns, and endless worries? With her superhuman strength, boundless kindness, and a horse on the porch, Pippi turns everyday life into pure joy. This edition features the timeless original illustrations by Ingrid Vang Nyman, created in close collaboration with Lindgren herself.', 'Junakinja nezaboravne priče Astrid Lindgren, Pipi Duga Čarapa, neiscrpna je maštarka i najjača djevojčica na svijetu. Pored nje niko ne želi da odraste—jer zašto bi, kad odrasle stalno muče žuljevi, porezi i dosadne brige? Iako se ponekad ponaša neobično, Pipi je najtoplije i najplemenitije stvorenje na svijetu. Ovo izdanje donosi originalne ilustracije Ingrid Vang Niman, uz koje je knjiga prvi put osvojila srca čitalaca širom planete.', 'Запасайтесь пилюлями против взросления: самая сильная и озорная девчонка в мире научит вас ходить задом наперёд и радоваться каждому дню!', 'Grab your never-grow-up pills: the strongest, freckliest girl in the world is here to teach you how to walk backwards and turn every day into a riotous adventure!', 'Pripremite pilule protiv odrastanja: najjača i najveselija djevojčica na svijetu naučiće vas kako da hodate unatraške i uživate u svakom danu!', '/covers/DP-0388.webp', '#e76f51', 'classics', 'ru', 'available', 'книга без суперобложки, красная с золотым тиснением', '["funny","adventure","friends"]', '["classics","astrid lindgren","pippi longstocking","humor","childhood"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('разграбление-рождественской-ел-389', 'DP-0389', 'Разграбление Рождественской елки хватай что хочешь', 'Pippi''s After-Christmas Party: Grab What You Want', 'Pipi Duga Čarapa čisti jelku: Uzmi šta hoćeš', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Ингрид Ванг Нюман', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Однажды во время рождественских каникул в маленьком-премаленьком городке случилось нечто невероятное. К дверям ратуши кто-то прикрепил плакат, приглашающий на праздник «ХВАТАЙЧТОХОЧЕШЬ!», который устраивала Пеппи Длинныйчулок, озорная девчонка с рыжими косичками. Все дети сгорали от нетерпения, когда же наступит вечер, чтобы отправиться на Виллу Вверхтормашками. Рождественская ёлка у Пеппи – что может быть лучше?! Эту вечеринку они точно никогда не забудут!..', 'One holiday season in a tiny little town, something extraordinary happened: a notice appeared on the town hall door inviting everyone to a ''GRAB-WHAT-YOU-WANT'' feast hosted by Pippi Longstocking. All the local children can hardly wait for nightfall to head over to Villa Villekulla. A Christmas party with Pippi—what could possibly be better? It''s an evening no one will ever forget!', 'Tokom božićnog raspusta u jednom sasvim malom gradiću desilo se nešto nevjerovatno: na vratima gradske kuće osvanuo je plakat koji poziva sve na zabavu ''UZMI ŠTA HOĆEŠ!'' koju priređuje Pipi Duga Čarapa. Sva djeca s nestrpljenjem čekaju veče da otrče u Vilu Vilakulu. Novogodišnja jelka kod Pipi — zar postoji išta bolje? Ovu žurku sigurno nikada neće zaboraviti!', 'Забудьте про скучные чинные хороводы — у Пеппи Длинныйчулок Новый год празднуют с размахом, горами сладостей и весёлым кавардаком!', 'Forget polite and quiet holiday gatherings—Pippi Longstocking throws a festive bash packed with cake, treats, and pure joyous chaos!', 'Zaboravite na dosadne proslave — kod Pipi Duge Čarape praznik jelke znači planine slatkiša, poklone i nezaboravan veseli haos!', '/covers/DP-0389.webp', '#c73926', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["funny","adventure","friends"]', '["christmas","winter","pippi longstocking","party","humor"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пеппи-длинныйчулок-поселяется--390', 'DP-0390', 'Пеппи Длинныйчулок поселяется в вилле «Курица»', 'Pippi Longstocking Moves into Villa Villekulla', 'Pipi Duga Čarapa useljava se u Vilu Vilakulu', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Лев Токмаков', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Повесть-сказка замечательной шведской писательницы Астрид Линдгрен об удивительных приключениях озорной девчонки с рыжими косичками Пеппилотты-Виктуалины-Рольгардины, а проще – Пеппи Длинныйчулок.', 'The timeless classic tale by wonderful Swedish author Astrid Lindgren about the incredible adventures of the mischievous red-haired girl Pippilotta Delicatessa Windowshade Mackrelmint, known simply as Pippi Longstocking.', 'Bezvremenska priča čuvene švedske autorke Astrid Lindgren o nevjerovatnim avanturama nestašne crvenokose djevojčice Pipilote, svima poznate kao Pipi Duga Čarapa.', 'Приготовьтесь печь блины прямо на полу и поднимать лошадей одной левой — самая независимая бунтарка на свете заезжает по соседству!', 'Get ready to fry pancakes on the floor and lift horses with one hand — the world''s most delightfully unstoppable girl has just moved in!', 'Pripremite se za palačinke na podu i dizanje konja jednom rukom — najjača i najslobodnija djevojčica na svijetu useljava se u komšiluk!', '/covers/DP-0390.webp', '#ea580c', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["funny","adventure","friends"]', '["classic","pippi longstocking","humor","mischief","friendship"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пьесы-391', 'DP-0391', 'Пьесы', 'Plays', 'Pozorišni komadi', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Таня Кормер', 'Белая ворона', NULL, NULL, 6, 14, 'middle', 'Астрид Линдгрен получила международное признание благодаря своим книгам для детей. Сегодня постановки по ним идут в разных театрах мира. Однако Линдгрен написала и множество собственно пьес и сценариев для кино и радио. Настоящее собрание знакомит с этой стороной ее творчества, до сих пор не открытой нашим читателем. Впервые на русском языке.', 'Astrid Lindgren gained worldwide renown for her children''s books, which continue to inspire stage productions across the globe. However, she also penned numerous original plays and scripts for film and radio. This unique collection introduces readers to this delightful, theatrical side of her storytelling.', 'Astrid Lindgren stekla je svjetsku slavu zahvaljujući svojim knjigama za đecu, po kojima se i danas igraju predstave širom svijeta. Ipak, napisala je i brojne originalne drame i scenarije za film i radio. Ova zbirka otkriva dosad manje poznatu, ali podjednako čarobnu stranu njenog stvaralaštva.', 'Приготовьте реквизит и костюмы: остроумные и озорные истории Астрид Линдгрен оживают прямо на домашней сцене!', 'Gather your costumes and props: Astrid Lindgren''s beloved wit and spark come alive right on your living room stage!', 'Pripremite kostime i rekvizite: razigrane priče Astrid Lindgren oživljavaju pravo na vašoj kućnoj sceni!', '/covers/DP-0391.webp', '#b84236', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["funny","adventure","friends"]', '["theatre","plays","classic","astrid lindgren","acting"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-эмиля-из-л-ннеберг-392', 'DP-0392', 'Приключения Эмиля из Лённеберги', 'The Adventures of Emil of Lönneberga', 'Avanture Emila iz Leneberje', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Бьорн Берг', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Весёлая повесть про Эмиля из Лённеберги, которую написала замечательная шведская писательница Астрид Линдгрен, а на русский язык блистательно пересказала Лилианна Лунгина, полюбилась и взрослым и детям всей планеты. Этот вихрастый мальчуган — ужасный озорник, он и дня не проживёт, не напроказничав. Ну кому придёт в голову гонять кошку, чтобы проверить, хорошо ли она прыгает?! Или надеть на себя супницу? Или поджечь перо на шляпе у пасторши? Или поймать в крысоловку родного отца, а поросёнка накормить пьяными вишнями?..', 'The hilarious tales of Emil of Lönneberga, created by world-renowned Swedish author Astrid Lindgren, have charmed readers of all ages across the globe. Emil is an unstoppable, mischievous boy who can''t spend a single day without some wild escapade. Who else would get their head stuck in a soup tureen, hoisted their little sister up a flagpole, or fed a pet piglet fermented cherries?', 'Urnebesna priča o Emilu iz Leneberje, čuvene švedske spisateljice Astrid Lindgren, osvojila je srca djece i odraslih širom svijeta. Ovaj plavokosi dječak je neumorni vragolan koji ne može provesti dan bez neke smicalice. Kome bi drugom palo na pamet da zaglavi glavu u činiju za supu, podigne sestricu na jarbol ili nahrani prase pijanim višnjama?', 'Приготовьтесь хохотать до колик над проделками самого обаятельного и неутомимого сорванца на свете!', 'Get ready to laugh until your sides ache at the escapades of the world''s most charming and inventive rascal!', 'Pripremite se za smijeh do suza uz vragolije najneodoljivijeg i najnemirnijeg dječaka na svijetu!', '/covers/DP-0392.webp', '#3b6998', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["funny","adventure","real"]', '["mischief","countryside","classic","humor","childhood"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-лотту-с-горластой-улицы-393', 'DP-0393', 'Про Лотту с Горластой улицы', 'Lotta on Troublemaker Street', 'Lota iz Ulice larmadžija', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Илон Викланд', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Лотта с Горластой улицы умеет почти всё. Например, она здорово свистит. И вообще, когда её никто не видит, у Лотты всё получается. Правда, бывают и промахи. Да и как можно ездить на старом трёхколёсном велосипеде, который то и дело дёргается, если тебе на день рождения пообещали новый двухколёсный! Ведь Лотте уже целых пять лет!', 'Lotta from Troublemaker Street can do almost anything. For instance, she can whistle like a pro! And whenever nobody is watching, everything she does turns out just right. Well, almost everything. After all, how can anyone be expected to ride a clunky old tricycle when you''ve been promised a real two-wheeler for your birthday? Especially when you are already a whole five years old!', 'Lota iz Ulice larmadžija zna skoro sve. Na primjer, sjajno zviždi! I uopšte, kad je niko ne gleda, Loti sve polazi za rukom. Doduše, desi se i poneki kiks. A i kako se uopšte može voziti stari tricikl koji stalno zapinje, kad su ti za rođendan obećali pravi bicikl na dva točka? Pa Lota ipak ima već čitavih pet godina!', 'Неподражаемая и упрямая пятилетка Лотта напомнит каждому взрослому, каково это — когда мир вокруг тебя ещё такой большой, а ты уже такой самостоятельный!', 'Feisty and unstoppable five-year-old Lotta will warmly remind every reader what it feels like to conquer the world on two wheels (or at least try to)!', 'Nezaboravna i tvrdoglava petogodišnja Lota podsjetiće vas na to kako izgleda kad si ubijeđen da možeš baš sve — čak i da ukradeš pravi bicikl!', '/covers/DP-0393.webp', '#e06343', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["funny","real"]', '["childhood","humor","family","growing up","classic"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-в-бюллербю-394', 'DP-0394', 'Приключения в Бюллербю', 'Adventures in Noisy Village', 'Avanture u Bilerbiju', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Илон Викланд', 'Махаон', NULL, NULL, 6, 14, 'middle', '«Нигде не бывает так весело, как у нас на хуторе», – говорят дети из Бюллербю, хотя их всего шестеро, если не считать крошку Черстин, которая слишком мала, чтобы сойти за целого ребёнка. Однажды дети решили устроить для неё настоящий праздник. Что из этого получилось, вы узнаете, прочитав эту книжку с очаровательными иллюстрациями Илон Викланд, любимой художницы Астрид Линдгрен.', '“Nowhere is quite as fun as our little village,” say the children of Noisy Village—even though there are only six of them, not counting tiny Kerstin. When they decide to throw a grand, unforgettable celebration just for little Kerstin, playful mishaps and heartwarming antics unfold. A cozy Swedish classic brought to life by Astrid Lindgren''s beloved illustrator, Ilon Wikland.', '„Nigdje nije tako zabavno kao kod nas na selu”, kažu djeca iz Bilerbija, iako ih je samo šestoro, ne računajući malu Kerstin. Jednog dana djeca odlučuju da za nju prirede pravi praznik. Šta je iz toga ispalo, saznaćete u ovoj divnoj knjizi sa šarmantnim ilustracijama Ilon Vikland, omiljene ilustratorke Astrid Lindgren.', 'Теплее этой книги только чашка какао у бабушки в деревне — идеальная порция беззаботного счастливого детства!', 'Warmer than a hot mug of cocoa at grandma''s cottage—this is pure, sun-drenched childhood happiness on every page!', 'Toplija od šolje kakaa na selu kod bake — ovo je čista, sunčana radost bezbrižnog djetinjstva!', '/covers/DP-0394.webp', '#d97736', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["friends","funny","real"]', '["noisy village","countryside","childhood","friendship","astrid lindgren"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пеппи-длинныйчулок-большая-кни-395', 'DP-0395', 'Пеппи Длинныйчулок. Большая книга комиксов', 'Pippi Longstocking: The Big Comic Book', 'Pipi Duga Čarapa: Velika knjiga stripova', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Ингрид Ванг Нюман', 'Планета дества АСТ', NULL, NULL, 6, 14, 'middle', 'Большая книга комиксов о Пеппи Длинныйчулок. Для младшего школьного возраста.', 'A vibrant and joyful collection of classic comic strips featuring Pippi Longstocking, the strongest and most mischievous girl in the world, accompanied by her monkey Mr. Nilsson, her horse, and her best friends Tommy and Annika.', 'Živopisna i vesela zbirka stripova o Pipi Dugoj Čarapi, najsnažnijoj i najnestašnijoj djevojčici na svijetu, njenom konju, majmunčetu Gospodinu Nilsonu i vjernim prijateljima Tomiju i Aniki.', 'Зарядитесь суперсилой, озорством и смехом вместе с самой независимой девчонкой на свете — теперь в формате ярких комиксов!', 'Power up with mischief, laughter, and freckled superpower alongside the world''s most independent girl — now in delightful comics!', 'Napunite se nestašlucima, smijehom i supermoćima uz najsamostalniju djevojčicu na svijetu — sada u obliku sjajnih stripova!', '/covers/DP-0395.webp', '#e65100', 'classics', 'ru', 'available', 'комиксы', '["funny","adventure","friends"]', '["comics","classics","humor","girl power","childhood"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('на-острове-сальткрока-396', 'DP-0396', 'На острове Сальткрока', 'Seacrow Island', 'Na ostrvu Saltkroka', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Носкович, Фитиногф', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Чудаковатый писатель и отец семейства отправляется со своими детьми на Сальткроку, маленький, затерявшийся в Балтийском море островок. Именно там, вдали от городской суеты, им предстоит провести незабываемое лето. Каникулы сулят что-то необыкновенное. Каждый день полон приключений и соткан из воспоминаний, ощущений, запахов и вкусов. Невольно посещают мысли о вечных человеческих ценностях: дружбе, любви, семье.', 'An eccentric writer and devoted father takes his children to Seacrow Island, a tiny haven hidden in the Baltic Sea. Far from the city bustle, they embark on an unforgettable summer filled with sunlit mishaps, swimming adventures, sea breezes, and the simple, timeless warmth of family and true friendship.', 'Neobični pisac i otac upućuje se sa svojom djecom na malo, skrovito ostrvo Saltkroka u Baltičkom moru. Daleko od gradske vreve, pred njima je nezaboravno ljeto ispunjeno morskim pustolovinama, mirisom borovine, novim prijateljstvima i toplinom porodičnog zajedništva.', 'Самое теплое и соленое лето в вашей жизни — приготовьтесь влюбиться в этот остров, верного пса Боцмана и неунывающее семейство Мелькерссонов!', 'The sunniest, saltiest summer of your life awaits—get ready to fall in love with island adventures, a big friendly dog named Bootsman, and the chaotic Melkerson family!', 'Najtoplije i najljepše ljeto vašeg života — pripremite se da se zaljubite u čarobno ostrvo, vjernog psa Bocmana i veselu porodicu Melkerson!', '/covers/DP-0396.webp', '#2d7f9d', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["adventure","friends","real"]', '["summer","island","family","sea","friendship"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кати-в-америке-397', 'DP-0397', 'Кати в Америке', 'Kati in America', 'Kati u Americi', '', 'Astrid Lindgren', 'Astrid Lindgren', '', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Путешествие в Америку... О, какая это авантюра! Кати безумно счастлива, даже если придётся взять с собой тётушку, которая не устаёт повторять: «Не смей выходить замуж за американца, это не принесёт тебе счастья!» Подумать только, Кати предстоит увидеть мир своими глазами! Да, есть чему удивляться и чему радоваться! А ещё можно столько себе позволить... и не позволить тоже...', 'A trip to America—what an incredible adventure! Kati is overjoyed, even if she has to bring along her grumpy aunt, who never tires of warning: ''Never marry an American, it will only bring you grief!'' Just imagine, Kati gets to see the vast new world with her own eyes, discovering wonders, laughter, and romance along the way.', 'Putovanje u Ameriku—kakva nevjerovatna avantura! Kati je presrećna, čak i ako mora da povede svoju strogu tetku koja ne prestaje da opominje: ''Ni slučajno se ne udaj za Amerikanca!'' Samo zamislite, Kati će vidjeti svijet sopstvenim očima, otkrivajući nova čuda, radosti i neočekivane izazove.', 'Пакуйте чемоданы и держите тётушку крепче: вас ждёт упоительное и весёлое заокеанское путешествие от неподражаемой Астрид Линдгрен!', 'Pack your bags and hold onto your grumpy aunt—Astrid Lindgren is taking us on a sparkling, hilarious voyage across the Atlantic!', 'Spakujte kofere i pazite na tetku—čeka vas neodoljivo i duhovito putovanje preko okeana iz pera Astrid Lindgren!', '/covers/DP-0397.webp', '#d9534f', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["adventure","funny","real"]', '["travel","america","growing up","humor","lindgren"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кати-в-италии-398', 'DP-0398', 'Кати в Италии', 'Kati in Italy', 'Kati u Italiji', '', 'Astrid Lindgren', 'Astrid Lindgren', '', 'Махаон', NULL, NULL, 6, 14, 'middle', 'В городе Стокгольме в маленькой уютной квартирке живут две подруги, Кати и Ева. Однажды, сделав ставку на разные футбольные команды, девушки выигрывают три тысячи шведских крон. Как потратить выигрыш? Кати уже побывала в Америке и мечтает об Италии. Что может быть лучше сказочной, божественной, сладостной Италии! И совсем не важно, что ты не знаешь итальянского языка. Главное, обучиться самым необходимым фразам вроде «Какой у вас пламенный взгляд, синьор!» или что-нибудь в этом духе...', 'In Stockholm, two best friends, Kati and Eva, share a cozy little flat. One lucky day, placing opposite bets on a football match, they win three thousand Swedish kronor! How to spend the windfall? Kati dreams of Italy. What could be more divine than romantic, sun-drenched Italy? And it doesn''t matter in the least that they don''t speak a word of Italian—as long as they master essential phrases like ''What fiery eyes you have, signor!''', 'U Stokholmu, dvije nerazdvojne prijateljice, Kati i Eva, dijele udoban mali stan. Jednog srećnog dana, kladeći se na suparničke fudbalske timove, osvajaju tri hiljade švedskih kruna! Kako potrošiti dobitak? Kati sanja o Italiji. Šta može biti čarobnije od sunčane, romantične Italije? I uopšte nije važno što ne govore italijanski — najvažnije je naučiti ključne fraze poput: „Kakav vatren pogled imate, sinjore!“', 'Собирайте чемоданы и готовьтесь хохотать: две неунывающие подружки отправляются покорять солнечную Италию!', 'Pack your bags and get ready to laugh out loud: two unstoppable best friends are setting off to conquer sunny Italy!', 'Spakujte kofere i spremite se za smijeh: dvije nerazdvojne prijateljice kreću u osvajanje sunčane Italije!', '/covers/DP-0398.webp', '#d96b43', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["funny","adventure","friends"]', '["travel","friendship","italy","humor","classic"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('остров-сальткрока-кролик-для-п-399', 'DP-0399', 'Остров Сальткрока. Кролик для Пелле', 'Seacrow Island: A Rabbit for Pelle', 'Ostrvo Saltkroka: Zec za Pelea', '', 'Astrid Lindgren', 'Astrid Lindgren', 'Мария Нильсон Тор', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Семилетний Пелле обожает животных и мечтает о кролике. Когда же он попадает на остров Сальткрока, лето для него становится одним большим приключением. Но главное, исполняется его мечта – у него появляется кролик! Обо всех приключениях Пелле и его жизни на удивительном острове можно прочитать в замечательной книге Астрид Линдгрен «На острове Сальткрока».', 'Seven-year-old Pelle adores animals and dreams of having a rabbit of his own. When he arrives on Seacrow Island, his summer turns into one big adventure. Best of all, his greatest dream comes true—he gets a bunny! Step into Pelle''s sunny, seaside world in this heartwarming tale by Astrid Lindgren.', 'Sedmogodišnji Pele obožava životinje i sanja o zecu. Kada stigne na ostrvo Saltkroka, ljeto za njega postaje jedna velika avantura. A najbolje od svega, ostvaruje se njegov san – dobija pravog zeca! Doživite Peleove ostrvske avanture u ovoj toploj priči legendarne Astrid Lindgren.', 'Теплые соленые брызги, пушистый кролик в руках и беззаботное лето на шведском острове, куда хочется сбежать сию же секунду!', 'Salty sea breezes, a soft fluffy bunny, and that unforgettable magic of an endless island summer!', 'Morski povjetarac, mekani zeko u naručju i bezbrižno ostrvsko ljeto u koje ćete se odmah zaljubiti!', '/covers/DP-0399.webp', '#3882a5', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["adventure","animals","friends"]', '["summer","island","rabbit","pets","astrid lindgren"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('детство-астрид-400', 'DP-0400', 'Детство Астрид', 'Astrid''s Childhood', 'Astridino djetinjstvo', 'Кристина Бьорк, Эва Эриксон', 'Christina Björk, Eva Eriksson', 'Christina Björk, Eva Eriksson', '', 'Белая ворона', NULL, NULL, 6, 14, 'middle', 'Из этой книги ты узнаешь о трех важных вещах. Во-первых, она расскажет о том времени, когда Астрид была маленькой. Звали ее Астрид Эриксон, и говорила она на смоландском диалекте. Во-вторых, ты узнаешь о том, как Астрид Линдгрен использовала воспоминания в своих книгах. Если ты читаешь книги о Пеппи, детях из Бюллербю, Мадикен, Эмиле и суперсыщике Калле Блумквисте, многое будет знакомым. Наконец, в-третьих, если ты когда-нибудь окажешься в родном городке Астрид - Виммербю, эта книга поможет тебе найти лимонадное дерево Пеппи Длинныйчулок, Бюллербю и усадьбу Каттхульт. Многое из того, о чем пишет Астрид Линдгрен, сохранилось до наших дней, хотя прошло уже больше ста лет.', 'This enchanting book reveals three wonderful secrets: what Astrid Ericsson''s childhood in Småland was like before she became Lindgren; how her sweetest memories shaped beloved tales of Pippi, Emil, and Bullerby; and how you can still find Pippi''s lemonade tree and the real Katthult farm in Vimmerby today.', 'Ova očaravajuća knjiga otkriva tri važne stvari: kako je izgledalo djetinjstvo male Astrid Erikson u švedskom Smolandu; kako su njene stvarne uspomene oživjele u pričama o Pipi, Emilu i djeci iz Bulerbija; i kako danas u njenom rodnom Vimerbiju možete pronaći pravo Pipino drvo limunade i farmu Kathult.', 'Загляните за кулисы любимых историй и узнайте, как озорное детство в шведской деревне подарило миру Пеппи Длинныйчулок и Эмиля из Лённеберги!', 'Step behind the pages of beloved classics and discover how a mischievous childhood in rural Sweden inspired Pippi Longstocking and Emil of Lönneberga!', 'Zavirite iza stranica omiljenih priča i otkrijte kako je jedno nestašno seosko djetinjstvo u Švedskoj iznjedrilo Pipi Dugu Čarapu i Emila!', '/covers/DP-0400.webp', '#d99b43', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["real","adventure","friends"]', '["astrid lindgren","biography","childhood","sweden","writers"]', 1792836322696, 1792845634845);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рони-дочь-разбойника-401', 'DP-0401', 'Рони дочь разбойника', 'Ronia, the Robber''s Daughter', 'Ronja, razbojnička kći', '', 'Astrid Lindgren', 'Astrid Lindgren', 'иллиюстрации студии Миядзаки', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Это необычное издание знаменитой сказочной повести Астрид Линдгрен "Рони, дочь разбойника" проиллюстрировано японским художником Кацуя Кондо. Рисунки к книге были созданы в процессе работы над анимационным сериалом, снятым режиссёром Горо Миядзаки на легендарной студии "Гибли".', 'This special edition of Astrid Lindgren''s beloved classic, ''Ronia, the Robber''s Daughter'', features vivid illustrations by Japanese artist Katsuya Kondo. The artwork was created during the production of the animated series directed by Goro Miyazaki at the legendary Studio Ghibli.', 'Ovo posebno izdanje čuvenog klasika Astrid Lindgren, „Ronja, razbojnička kći“, ilustrovao je japanski umjetnik Katsuja Kondo. Crteži su nastali tokom rada na animiranoj seriji u režiji Goroa Mijazakija u legendarnom studiju „Ghibli“.', 'Бессмертная лесная сказка Астрид Линдгрен в завораживающем визуальном стиле студии «Гибли» — идеальный побег в дикую природу и настоящую дружбу!', 'Astrid Lindgren’s timeless forest tale brought to life with enchanting Studio Ghibli art—an unforgettable story of wild courage and friendship.', 'Bezvremenska šumska bajka Astrid Lindgren oživljena magičnim crtežima studija „Ghibli“ — priča o divljoj hrabrosti i neraskidivom prijateljstvu.', '/covers/DP-0401.webp', '#2e5a36', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["adventure","friends","magic"]', '["classics","forest","friendship","robbers","studio ghibli"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('братья-львиное-сердце-402', 'DP-0402', 'Братья Львиное сердце', 'The Brothers Lionheart', 'Braća Lavlje Srce', '', 'Astrid Lindgren', 'Astrid Lindgren', '', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Сказочная повесть о судьбе двух братьев, об их необычайном путешествии в волшебную страну, где с ними происходят самые разные события и где они учатся отваге, мужеству, любви и доброте. За книгу «Братья Львиное Сердце» Астрид Линдгрен была удостоена литературной премии Януша Корчака.', 'A fairy-tale novel about the bond between two brothers and their breathtaking journey to the magical land of Nangijala. Facing great trials, legendary beasts, and ruthless tyrants, they discover the true meaning of bravery, sacrifice, and boundless love.', 'Bajkoviti roman o sudbini dva brata i njihovom nevjerovatnom putovanju u čarobnu zemlju Nangijalu. Kroz brojne opasnosti i borbu protiv tiranije, braća uče šta su istinska hrabrost, požrtvovanost, ljubav i dobrota.', 'Пронзительная и невероятно светлая сказка о братской преданности, драконах и отваге, которая сильнее любого страха.', 'A breathtakingly tender and heroic tale of two brothers whose love and courage can conquer even the darkest shadows.', 'Dirljiva i herojska bajka o neraskidivoj bratskoj ljubavi i hrabrosti koja pobjeđuje i najveće tame.', '/covers/DP-0402.webp', '#3a506b', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["adventure","magic","friends"]', '["brotherhood","courage","fantasy","classics","dragons"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('отважная-кайса-403', 'DP-0403', 'Отважная Кайса', 'Brenda Brave', 'Hrabra Kajsa', 'Ингрид Ванг Нюман', 'Ingrid Vang Nyman', 'Ingrid Vang Niman', '', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Маленькая Кайса живёт одна с бабушкой, но всего за неделю до Рождества бабушка ломает ногу. Кто же теперь пойдёт на ярмарку продавать сладости и подготовит дом к празднику? И тут Кайса и принимается за дело… Сборник рассказов Астрид Линдгрен о самых разных детях, счастливых и не очень. Но почти все они смелые, отважные, умные, с огоньком в глазах.', 'Little Brenda lives with her grandmother, but just a week before Christmas, Grandma breaks her leg. Who will sell homemade sweets at the holiday market and get the house ready in time? Brenda bravely takes charge! This heartwarming collection of stories by Astrid Lindgren features remarkable children who face life''s challenges with grit, kindness, and clever optimism.', 'Mala Kajsa živi sa svojom bakom, ali samo sedmicu dana pred Božić baka slomi nogu. Ko će sada ići na pijacu da prodaje slatkiše i pripremi kuću za praznik? Hrabra Kajsa preuzima stvar u svoje ruke! Zbirka dirljivih priča Astrid Lindgren o deci koja se suočavaju sa životnim izazovima uz mnogo hrabrosti, pameti i topline.', 'Трогательные и уютные истории о маленьких героях с огромным сердцем, которые не боятся трудностей даже накануне Рождества.', 'Cozy, heartwarming stories about spunky children with big hearts who prove no problem is too big when met with courage.', 'Tople i nježne priče o malim junacima velikog srca koji dokazuju da hrabrost i dobrota čine prava praznična čuda.', '/covers/DP-0403.webp', '#b84136', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["real","friends","adventure"]', '["christmas","winter","courage","family","short stories"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мы-все-из-бюллербю-404', 'DP-0404', 'Мы все из Бюллербю', 'The Children of Noisy Village', 'Mi djeca iz Bilerbija', 'Ингрид Ванг Нюман', 'Astrid Lindgren, Ingrid Vang Nyman', 'Astrid Lindgren, Ingrid Vang Niman', '', 'Махаон', NULL, NULL, 6, 14, 'middle', '"Нигде не бывает так весело, как у нас в Бюллербю, это самое лучшее место на Земле", -- считают дети, которые там живут, и писательница Астрид Линдгрен, чьё детство прошло в такой же маленькой деревушке на юге Швеции. И хотя детей в Бюллербю всего шестеро, если не считать крошку Черстин, которая слишком мала, чтобы сойти за целого ребёнка, им никогда не бывает скучно, как не было скучно и великой писательнице, ведь именно там сформировалось её мировоззрение. С обычным для неё блеском и юмором она описывает их беззаботное детство, в котором есть место и прекрасным семейным праздникам, и шалостям , и радостям, и мимолётным огорчениям. Книга представлена с замечательными иллюстрациями Ингрид Ванг Нюман.', 'In the tiny Swedish village of Bullerby, there are just three farms and six lively children. From sleeping out in the hayloft and hunting for hidden treasure to baking gingerbread and celebrating Midsummer, their days are filled with genuine warmth, innocent mischief, and the blissful magic of a free-range childhood.', 'U malom švedskom selu Bilerbi postoje samo tri kuće i šestoro vesele djece. Od spavanja na sijeniku i traženja skrivenog blaga do pečenja medenjaka i ljetnjih proslava, njihovi dani ispunjeni su bezbrižnim avanturama, toplinom doma i istinskom čarolijom djetinjstva.', 'Лучшее в мире лекарство от хандры: ныряйте в беззаботное лето, где пахнет сеном, свежей земляникой и настоящей дружбой!', 'The ultimate antidote to gloomy days: dive into an idyllic countryside summer filled with the scent of hay, wild strawberries, and pure joy!', 'Najbolji lijek za tmurne dane: zaronite u bezbrižno ljeto puno mirisa sijena, šumskih jagoda i iskrenog drugarstva!', '/covers/DP-0404.webp', '#d97724', 'classics', 'ru', 'available', 'Категория: Гном и лис', '["friends","funny","real"]', '["childhood","village","friendship","sweden","family","summer"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чему-я-могу-научиться-у-туве-я-405', 'DP-0405', 'Чему я могу научиться у Туве Янссон', 'What I Can Learn from Tove Jansson', 'Šta mogu naučiti od Tuve Janson', 'Александра Баженова-Сорокина', 'Alexandra Bazhenova-Sorokina', 'Aleksandra Baženova-Sorokina', '', 'Альпина', NULL, NULL, 6, 14, 'middle', 'Мы знаем Туве Янссон как знаменитую финскую детскую писательницу и художницу. Ей удалось подарить читателям из самых разных стран уютный мир, куда можно вернуться в любом возрасте – мир Муми-троллей. Эти милые и мудрые персонажи стали частью общечеловеческой культуры. Но Туве Янссон была не только сказочницей. Она всю жизнь писала картины, рисовала комиксы, работала в театре, а ещё стала знаменитой взрослой писательницей. Эта иллюстрированная биография расскажет не только о том, как были придуманы знаменитые муми-тролли. Вы узнаете, как Туве начала рисовать и почему она не считала себя писательницей, зачем она расписывала стены домов и какой язык является её родным на самом деле. Множество интересных фактов раскроют личность этой удивительной творческой натуры, жизнь которой пришлась на турбулентное время мировых войн, что не помешало ей создавать удивительные добрые и мудрые сказки.', 'We know Tove Jansson as the beloved creator of Moominvalley, but she was so much more than a children’s storyteller. Throughout her life, Tove painted murals, drew satirical comics, designed theatre sets, and wrote poignant adult fiction. This illustrated biography reveals how a free-spirited artist navigated turbulent wartime eras while cultivating profound warmth and wisdom, inspiring young readers to follow their own creative compass.', 'Znamo Tuve Janson kao omiljenu tvoriteljicu doline Mumina, ali ona je bila mnogo više od bajkovite spisateljice. Tokom života slikala je murale, crtala stripove, radila u pozorištu i pisala romane za odrasle. Ova ilustrovana biografija otkriva kako je umjetnica slobodnog duha stvarala u burnim vremenima ratova, ne gubeći toplinu i dobrotu, te inspiriše mlade čitaoce da prate sopstveni stvaralački put.', 'Узнайте, как создательница муми-троллей расписывала стены, бросала вызов невзгодам и учила весь мир ценить свободу, доброту и чашечку тёплого чая.', 'Discover how the creator of the Moomins painted murals, defied hard times, and taught the world that freedom, kindness, and cozy tea parties conquer all.', 'Otkrijte kako je stvoriteljica Mumina oslikavala zidove, prkosila nedaćama i naučila svijet da su sloboda, dobrota i šolja toplog čaja jači od svega.', '/covers/DP-0405.webp', '#3e7c8f', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["real","magic"]', '["biography","tove jansson","moomins","art","creativity","inspiration"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кто-утешит-кнютта--406', 'DP-0406', 'Кто утешит Кнютта?', 'Who Will Comfort Toffle?', 'Ko će utješiti Kniuta?', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Даже самый маленький и пугливый Кнютт может стать настоящим героем! Перестать бояться всего на свете на самом деле не так уж сложно, иногда достаточно просто поговорить с тем, кто рядом. Хочешь узнать, как малыш Кнютт поборол свои страхи и спас маленькую Скрютту? Эта чудесная поэма была создана и проиллюстрирована Туве Янссон в конце пятидесятых годов прошлого века и за это время нисколько не утратила свежести и очарования. Знаменитые истории о муми-троллях, стихи и проза Туве Янссон так любимы в России во многом благодаря замечательным переводчикам. И в этом издании мы с радостью представляем читателям уже знакомую многим историю в новом прекрасном переводе Марины Бородицкой.', 'Even the tiniest and most timid creature can become a true hero! It turns out that overcoming fears is much easier when you find someone to care about. When lonely Toffle discovers an SOS in a bottle from little Miffle, he summons all his courage to journey through a strange and spooky world to rescue her. Written and illustrated in verse by Tove Jansson, this timeless poetic masterpiece about loneliness, bravery, and friendship glows with tender charm.', 'Čak i najmanji i najplašljiviji stvor može postati pravi junak! Prestati se plašiti svijeta oko sebe uopšte nije tako teško kada pronađeš nekoga kome si potreban. Kada usamljeni Kniut pronađe pismo u boci od prestrašene Skriute, pronalazi neočekivanu hrabrost da pođe na put i spasi je. Ova čudesna poema u stihovima Tove Janson bezvremenska je priča o usamljenosti, ljubavi i prevazilaženju sopstvenih strahova.', 'Нежная и поэтичная сказка Туве Янссон о том, что даже самое робкое сердце обретает львиную храбрость, когда спешит на помощь другу.', 'Tove Jansson''s poetic and tender picture book proves that even the most timid heart discovers lionhearted courage when helping a friend.', 'Nježna i poetična priča Tuve Janson koja pokazuje kako i najplašljivije srce dobija lavovsku hrabrost kada pruži ruku prijatelju.', '/covers/DP-0406.webp', '#1f3b64', 'classics', 'ru', 'available', 'книжка-картинка', '["friends","magic","adventure"]', '["tove jansson","overcoming fear","friendship","poetry","classic","bravery"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('что-дальше--407', 'DP-0407', 'Что дальше?', 'The Book about Moomin, Mymble and Little My', 'Šta je bilo poslije?', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Эта книга – настоящее сокровище, неизменно вызывающее восторг и детей, и взрослых! Всемирно известная финская писательница Туве Янссон сочинила и проиллюстрировала её в 1952 году. Это не только очаровательная история о её любимых героях, рассказанная в стихах (и замечательно переведённая Натальей Шаховской!), но книжка-игра, создающая ни с чем не сравнимое волшебное пространство, в котором неразрывно сплетаются литературное и изобразительное мастерство писательницы. Вместе с Муми-троллем мы пройдем весь этот сказочный путь, помогая рыдающей Мюмле найти её сестрёнку – своенравную малышку Мю. И на каждой странице нас будет ждать загадка. Пускаясь в это нелёгкое путешествие, придется запастись воображением! Иначе как угадать, что дальше?!', 'Created in 1952 by beloved Finnish storyteller Tove Jansson, this delightful picture book is a true masterwork of verse, art, and play. Join Moomintroll on a brisk journey home with a can of milk as he encounters a sobbing Mymble looking for little runaway Little My. Featuring clever cut-out holes on every page that offer sneaky peeks ahead, readers must use all their imagination to discover: what happened next?', 'Stvorena 1952. godine od strane čuvene finske autorke Tuve Janson, ova predivna slikovnica u stihovima pravo je blago dječje književnosti i umjetnosti. Krenite s Muminom na put kroz šumu dok nosi mlijeko mami i pomaže uplakanoj Mimbli da pronađe nestašnu malu Mu. Kroz maštovite izreze na svakoj stranici proviruje sljedeća scena, tjerajući nas da se pitamo: šta je bilo poslije?', 'Заглядывайте в прорезанные окошки на страницах и спасайте малышку Мю вместе с Муми-троллем — оторваться от этой книги-игры просто невозможно!', 'Peek through the clever cutout holes on each page and help Moomintroll find Little My — pure interactive magic from Tove Jansson!', 'Zavirite kroz prozorčiće na svakoj stranici i krenite sa Muminom u potragu za malom Mu u ovoj nezaboravnoj interaktivnoj bajci!', '/covers/DP-0407.webp', '#e76f51', 'classics', 'ru', 'available', 'книжка-картинка', '["adventure","magic","friends"]', '["moomins","interactive","cut-out book","verse","classic","scandinavian"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тут-все-не-так-408', 'DP-0408', 'Тут все не так', 'The Dangerous Journey', 'Opasno putovanje', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Порой бывает так, что всё идёт не так! Происходят непонятные вещи, случаются странные события, которые сначала немного пугают, но зато влекут за собой долгожданные приключения, удивительные встречи и сказочные впечатления! Именно это произошло с героиней волшебной поэмы Туве Янссон, девочкой Сусанной, которой повезло познакомиться с обитателями Муми-долины и совершить удивительное, полное восхитительных опасностей путешествие!', 'Sometimes everything goes topsy-turvy! Strange, baffling things start to happen—a bit scary at first, but leading straight to long-awaited adventures, wondrous encounters, and magical experiences. That is exactly what happens to little Susanna in Tove Jansson''s delightful verse tale, when she sets off across Moominvalley on a journey packed with marvelous perils!', 'Ponekad se desi da sve krene naopako! Događaju se neobične stvari koje u početku pomalo plaše, ali donose dugo očekivane avanture, čudesne susrete i magične doživljaje. Upravo se to događa djevojčici Suzani u stihovanoj bajci Tuve Janson, kada kreće na uzbudljivo putovanje kroz Mumin-dolinu puno čarobnih opasnosti!', 'Если день кажется слишком серым и скучным, примерьте волшебные очки Сусанны и шагайте прямиком в загадочную Муми-долину!', 'If your day feels a bit too dull, slip on Susanna''s magical glasses and step right into the thrilling perils of Moominvalley!', 'Ako vam dan djeluje previše obično, stavite Suzanine čarobne naočare i zakoračite pravo u uzbudljivu Mumin-dolinu!', '/covers/DP-0408.webp', '#d65a31', 'classics', 'ru', 'available', 'книжка-картинка', '["magic","adventure","spooky"]', '["moomins","tove jansson","verse tale","journey","classic"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('опасное-лето-409', 'DP-0409', 'Опасное лето', 'Moominsummer Madness', 'Opasno ljeto', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Лето выдалось тревожным – наводнение пришло в Долину и затопило дом мумии-троллей. Семья отправилась искать новое жилье. На удачу, волнами к берегу прибило вполне подходящий дом, который, правда, вёл себя немного странно. У него была крыша, похожая на створку раковины, и вращающийся пол, а если дернуть за шнурок – с потолка упадет картина. Или польет дождь. Или зажгутся сотни разноцветных огней. Едва семейство немного прибралось и село пить чай, как объявился один из прежних обитателей и заявил, что весь дом – театр. И тогда Муми-папа берётся за постановку пьесы собственного сочинения!', 'A sudden flood sweeps through Moominvalley, submerging the family home and sending the Moomins in search of refuge. By a stroke of luck, a bizarre floating building drifts by—a place with revolving floors, mysterious cords, and shell-shaped roofs. It turns out to be an abandoned theater! Soon Moominpappa is inspired to write a grand tragedy, turning their perilous summer into an unforgettable theatrical extravaganza.', 'Velika poplava potopila je Mumin dolinu i natjerala porodicu Mumin da napusti svoj dom. Srećom, talasi donose neobičnu plutajuću građevinu punu tajanstvenih konopaca, kulisa i rotirajućih podova. Ispostavlja se da je to pravo pozorište, a Mumin-tata odmah odlučuje da napiše i postavi sopstvenu predstavu, pretvarajući ljetnje nevolje u pravu pozorišnu čaroliju.', 'Даже если наводнение смыло твой дом, не вешай нос — возможно, прямо к тебе приплыл целый плавучий театр!', 'When a flood carries away your house, don''t despair—you might just drift straight into a marvelous floating theater!', 'Čak i kad vam poplava odnese dom, ne očajavajte — možda vam pravo pred noge doplovi čitavo pozorište!', '/covers/DP-0409.webp', '#2b6b7f', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","magic","friends"]', '["moomins","theater","flood","summer","classic"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленькие-тролли-и-большое-нав-410', 'DP-0410', 'Маленькие тролли и большое наводнение', 'The Moomins and the Great Flood', 'Mali troli i velika poplava', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Близится осень, а это значит, что муми-троллю и его маме нужно поскорее найти уютное местечко и построить там дом. Раньше муми-троллям не нужно было бродить по лесам и болотам в поисках жилья — они жили за печками в домах людей. Но теперь печек стало совсем мало, а паровое отопление муми-троллям не годится. Вот поэтому муми-тролль с мамой рискнули отправиться в путь, мечтая найти не только новый дом, но и папу муми-тролля, который пропал когда-то давно. А тем временем грядет большое наводнение… Но как знать, может, именно оно подарит маленьким троллям долгожданную встречу.', 'Autumn is fast approaching, which means Moomintroll and Moominmamma urgently need to find a cozy spot to build a house before winter sets in. Gone are the days when Moomins lived safely behind people''s tiled stoves; steam heating just doesn''t suit them. Venturing into dark, magical forests and wading through marshes, they embark on a journey hoping not only to build a new home, but also to find the missing Moominpappa. Meanwhile, a great flood is coming...', 'Jesen se bliži, a to znači da Mumintrol i Muminmama moraju brzo pronaći udobno mjesto i sagraditi novu kuću. Nekada su Mumini bezbrižno živjeli iza peći u ljudskim domovima, ali parno grijanje im nikako ne prija. Zato kreću u nepoznato, kroz mračne šume i močvare, nadajući se da će pronaći topao kutak, ali i Muminpatu koji je odavno nestao. A velika poplava samo što nije počela...', 'С этой трогательной и чуточку тревожной сказки начинается великая сага о Муми-доле — идеальное чтение под шум дождя.', 'This touching and wondrous tale is where the entire Moomin universe began—best enjoyed wrapped in a warm blanket.', 'Ova dirljiva i čarobna priča označava početak čitavog svijeta Mumina — savršeno štivo za ušuškavanje dok napolju pada kiša.', '/covers/DP-0410.webp', '#4a708b', 'classics', 'ru', 'available', 'Вероника?', '["adventure","magic","friends"]', '["moomins","classic","journey","family","fantasy"]', 1792836322696, 1792845640935);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-глубине-ноября-411', 'DP-0411', 'В глубине ноября', 'Moominvalley in November', 'U novembru', '', 'Tove Jansson', 'Tuve Janson', '', '', NULL, NULL, 6, 14, 'middle', 'Лето прошло, и зима не за горами. Снусмумрик, как обычно, отправляется в странствие. Но почему-то на этот раз у него не получается беспечно покинуть Муми-долину – ноги словно сами собой возвращают его обратно. И к закату года многие друзья и знакомые муми-семейства вдруг решают, что сейчас самое подходящее время нанести визит в Муми-дом. И вот на веранде вновь загорается золотистый огонек керосиновой лампы, возле которого осенние вечера становятся теплее, и все так рады видеть друг друга.', 'Summer has passed and winter is just around the corner. Snufkin, as usual, sets out wandering, but somehow his feet carry him back toward Moominvalley. As the year draws to an end, many friends of the Moomin family suddenly decide it is the perfect time to visit the Moominhouse. Soon, a golden kerosene lamp flickers on the veranda, making quiet autumn evenings cozy and full of tender reunions.', 'Ljeto je prošlo i zima je pred vratima. Snusmumrik, kao i obično, kreće na lutanje, ali se nekako ponovo vraća prema Mumin-dolini. Dok godina izmiče, mnogi prijatelji porodice Mumin odlučuju da je pravo vrijeme za posjetu njihovom domu. Zlatasti plamičak petrolejke ponovo osvjetljava verandu, grijući prohladne jesenje večeri i donoseći utjehu zajedništva.', 'Самая меланхоличная, поэтичная и согревающая осенняя повесть о поисках уюта и тепла в Муми-доле.', 'The most poignant and comforting autumn tale about longing, friendship, and finding warmth even when loved ones are away.', 'Najdirljivija i najtoplija jesenja priča o čežnji, prijateljstvu i pronalaženju svjetlosti u Mumin-dolini.', '/covers/DP-0411.webp', '#9c6644', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["friends","magic"]', '["moomins","autumn","scandinavian literature","friendship","comfort reading"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('невидимая-девочка-и-другие-ист-412', 'DP-0412', 'Невидимая девочка и другие истории', 'The Invisible Child and Other Stories', 'Nevidljivo dijete i druge priče', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Мир муми-троллей — «это мир, по которому в глубине души тоскует каждый из нас». Правоту этого утверждения знаменитой шведско-финской писательницы и художницы Туве Янссон доказывают ее книги, ставшие неотъемлемой частью детства уже нескольких поколений. Наивный и мудрый, теплый и добрый, несмотря на все бури, пытающиеся его сокрушить, этот мир всегда открыт и детям, и взрослым.', 'The world of Moominvalley is a place deep down each of us longs for. These poetic, gentle, and profoundly wise stories by Tove Jansson follow Ninny, the shy girl made visible again by love and kindness, along with other eccentric and lovable inhabitants of the Moomin house.', 'Svijet Mumijevih je mjesto za kojim duboko u sebi svako od nas čezne. Ove tople, poetične i mudre priče Tuve Janson donose susret sa Nini, djevojčicom koja je postala nevidljiva od straha i ponovo se pojavila zahvaljujući pažnji i ljubavi, kao i sa mnogim drugim dragim bićima iz Mumindola.', 'Целебное чтение для тех, кто устал, застеснялся или просто хочет, чтобы его согрели заботой и оладьями.', 'A deeply comforting read for anyone who has ever felt unseen, shy, or in need of warm tea and unconditional kindness.', 'Prava ljekovita knjiga za svakoga ko se ikada osjetio nevidljivim ili mu jednostavno treba toplina, čaj i malo razumijevanja.', '/covers/DP-0412.webp', '#5c7c8a', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","friends","animals"]', '["moomins","kindness","short stories","scandinavian classics","acceptance"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зима-муми-тролля-413', 'DP-0413', 'Зима Муми-тролля', 'Moominland Midwinter', 'Zima u Mumindolu', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Зимой мир становится другим — белым, неподвижным, холодным. Кругом сугробы и лёд, а там, где росли яблоки, теперь растёт снег. Только всего этого Муми-троллю знать не полагается. Потому что с ноября по апрель все порядочные муми-тролли спят и видят сны. Но так уж вышло, что этой зимой Муми-тролль проснулся и не смог обратно заснуть. Поначалу зимний мир показался ему чужим и даже каким-то неправильным. Но Муми-тролль увидел снег, познакомился с Туу-тикки, которая поселилась в папиной купальне, повстречал Ледяную Даму, покатался с горки и даже побывал в самом сердце снежной бури. И вот удивительно: зимний мир оказался ничуть не хуже летнего. Муми-тролль стал первым муми-троллем, который прожил по-настоящему целый год. Хотя бы ради этого стоило проснуться посреди зимы! Книга, которую вы держите в руках, — настоящее событие. Впервые за долгие годы весь цикл о муми-троллях заново переведён на русский язык! Тем, кто уже знаком с обитателями Муми-долины, будет любопытно по-новому взглянуть на их приключения. А тем, кому первая встреча со сказочным миром Туве Янссон только предстоит, можно лишь по-хорошему позавидовать!', 'Winter changes everything: the world turns white, quiet, and cold, blanketed in snow and ice. Moomins are supposed to hibernate peacefully from November through April, but one winter, Moomintroll wakes up and cannot drift back to sleep. At first, this frozen, unfamiliar world feels lonely and alien. Yet step by step, guided by the wise and cheerful Too-ticky who moved into the bathhouse, he discovers snow, braves the Lady of the Cold, rides toboggans, and faces a howling blizzard. Moomintroll becomes the very first Moomin to experience an entire year, discovering that winter has its own quiet magic, warmth, and wonders.', 'Zimi svijet postaje drugačiji — bijel, nepomičan i tih, prekriven debelim snijegom i ledom. Pristojni Mumini spavaju zimski san od novembra do aprila, ali ove zime Mumintrol se budi usred noći i više ne može zaspati. U početku mu se zaleđena dolina čini tuđom i opasnom, ali susret s mudrom Tu-tiki, tajanstvenom Ledenom gospođom i prvim snježnim mećavama otkriva mu potpuno novu vrstu čarolije. Mumintrol postaje prvi Mumin u istoriji koji je doživio sva četiri godišnja doba i shvatio da je zima podjednako predivna kao i ljeto.', 'Идеальное зимнее чтение под теплым пледом о том, что даже самый холодный и незнакомый мир полон тепла, если не бояться сделать шаг наружу.', 'A deeply comforting winter masterpiece about finding light, warmth, and brave new friends when the whole familiar world is fast asleep.', 'Najtoplija zimska priča pod ćebencetom o tome kako nepoznat i hladan svijet može postati čaroban kada u njega zakoračimo otvorenog srca.', '/covers/DP-0413.webp', '#3f6789', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","adventure","friends"]', '["moomins","winter","snow","classics","friendship"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-прилетит-комета-414', 'DP-0414', 'Когда прилетит комета', 'Comet in Moominland', 'Komet u Dolini Mumina', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'На Муми-долину надвигается конец света! Где-то далеко в непроглядно-чёрной Вселенной движется звезда с пылающим хвостом — комета, — которая вот-вот упадёт на Землю. И тогда неизвестно, что ожидает всех земных обитателей. Муми-троллю и Сниффу рассказал об этом их новый друг Снусмумрик, которого они повстречали по пути в обсерваторию (они отправились туда узнать, правда ли Вселенная такая чёрная. И это было очень опасное путешествие!) А учёные в обсерватории даже назвали день и час, когда прилетит комета. Медлить нельзя — нужно как можно скорее попасть домой. Ведь мама с папой непременно придумают, как спасти мир! Книга, которую вы держите в руках, — настоящее событие. Впервые за долгие годы весь цикл о муми-троллях заново переведён на русский язык! Тем, кто уже знаком с обитателями Муми-долины, будет любопытно по-новому взглянуть на их приключения. А тем, кому первая встреча со сказочным миром Туве Янссон только предстоит, можно лишь по-хорошему позавидовать!', 'Doom looms over Moominvalley! Far out in the pitch-black cosmos, a fiery-tailed comet is hurtling toward Earth. Accompanied by their wanderer friend Snufkin, Moomintroll and Sniff embark on a perilous trek to the Lonely Mountains observatory to uncover when the cosmic threat strikes. With the countdown ticking, the friends must dash home, knowing Moominmamma and Moominpappa will surely brew a plan to keep them all safe. A timeless, thrilling classic about facing fear together.', 'Smak svijeta prijeti Dolini Mumina! Daleko u tami svemira, vatrena kometa juri pravo ka Zemlji. Mumin i Njuško kreću na opasnu ekspediciju ka opservatoriji na Usamljenim planinama, gdje upoznaju nezaboravnog skitnicu Snusmumrika i saznaju tačan trenutak udara. Vremena je malo, a povratak kući jedina je nada — jer Mumin-mama i Mumin-tata sigurno znaju kako spasiti svijet!', 'Захватывающее космическое приключение с кометой, пещерами и неизменным уютом маминых оладий в разгар надвигающейся катастрофы!', 'A thrilling cosmic quest featuring mysterious comets, daring cave hideouts, and Moominmamma''s pancakes in the face of doom!', 'Uzbudljiva kosmička avantura puna tajanstvenih kometa, pećina i toplih palačinki dok svijet iščekuje udar!', '/covers/DP-0414.webp', '#2c4a6f', 'classics', 'ru', 'available', 'Вероника?', '["adventure","friends","magic"]', '["moomins","comet","space","journey","scandinavia","classics"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шляпа-волшебника-415', 'DP-0415', 'Шляпа волшебника', 'Finn Family Moomintroll', 'Čarobnjakov šešir', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Всю зиму Муми-тролль, как известно, проводит в спячке — и этим он ничем не отличается от любого другого муми-тролля. Зато весной, проснувшись, он очень даже не прочь предпринять что-нибудь необычное. Например, подняться на гору в компании своих друзей Снусмумрика и Сниффа и обнаружить на вершине забытый кем-то чёрный цилиндр. И, оказывается, это не просто красивая шляпа, а шляпа, умеющая творить чудеса! С её помощью можно победить Муравьиного Льва и покататься на симпатичных тучках, но есть одна беда: никогда не знаешь, что шляпа выкинет в следующий раз. Может быть, стоит от неё избавиться? Но, как выяснилось, и это не так-то просто. А главное волшебство начнётся, когда в Муми-долину явится настоящий хозяин шляпы… Книга, которую вы держите в руках, — настоящее событие. Впервые за долгие годы весь цикл о муми-троллях заново переведён на русский язык! Тем, кто уже знаком с обитателями Муми-долины, будет любопытно по-новому взглянуть на их приключения. А тем, кому первая встреча со сказочным миром Туве Янссон только предстоит, можно лишь по-хорошему позавидовать!', 'After a long winter hibernation, Moomintroll and his companions Snufkin and Sniff climb a mountain and stumble upon a mysterious black top hat. It turns out to be no ordinary hat, but one that turns eggshells into rideable clouds and causes bizarre transformations. Anything dropped inside morphs into something unexpected, bringing chaos, laughter, and wonder to Moominvalley. But what will happen when the mysterious Hobgoblin comes searching for his lost magical treasure?', 'Nakon dugog zimskog sna, Mumi-trol i njegovi nerazdvojni prijatelji Snusmumrik i Snif pronalaze na vrhu planine neobičan crni cilindar. Ispostavlja se da to nije običan šešir, već magični predmet koji ljuske jaja pretvara u meke oblačiće za jahanje i stvara nevjerovatne transformacije. Dolina Mumijevih postaje poprište čuda i neočekivanih nevolja, a prava čarolija tek počinje kada se pojavi tajanstveni vlasnik šešira.', 'Главный рецепт счастливого лета в Муми-доле: верные друзья, сладкие оладьи и один загадочный цилиндр, превращающий всё вокруг в сплошное волшебство!', 'The ultimate recipe for a sunny Moominvalley summer: loyal friends, warm pancakes, and a runaway magical top hat that turns ordinary days into pure wonder!', 'Savršen recept za nezaboravno ljeto u Mumijevoj dolini: vjerni prijatelji, tople palačinke i jedan tajanstveni šešir koji običan dan pretvara u čaroliju!', '/covers/DP-0415.webp', '#433364', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","adventure","friends"]', '["moomins","magic hat","friendship","summer","fantasy","classics"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('папа-и-море-416', 'DP-0416', 'Папа и море', 'Moominpappa at Sea', 'Mumin-tata i more', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Муми-троллям уже доводилось переезжать, а Муми-папа – тот вообще великий путешественник. Вот и сейчас, к концу лета, Муми-папа решил, что размеренная жизнь в Долине – не для его мятежной души. Его призвание – жить на острове с маяком, средь бушующего моря, и указывать путь кораблям. Cемейство отправляется в путь. Маяк на первый взгляд кажется довольно скучным и неуютным местом. Однако это только на первый взгляд. Ведь Муми-мама сумеет сделать уютным даже голый утес, а тайн, опасностей и бушующего моря семейству хватит надолго!', 'Moominpappa feels that the quiet, predictable life of Moominvalley is no longer enough for his restless spirit. Convinced his true calling is to keep a lighthouse on a windswept island in the middle of a stormy sea, he sets sail with his family. The barren rock seems desolate and strange at first, but with Moominmamma''s warmth and plenty of mysteries lurking in the waves, an unforgettable adventure begins.', 'Mumin-tati se čini da je miran život u Mumin-dolini postao pretijesan za njegov nemirni duh. Ubijeđen da je njegov pravi poziv čuvanje svjetionika na stjenovitom ostrvu usred uzburkanog mora, on vodi čitavu porodicu u novu plovidbu. Svjetionik u početku djeluje pusto i strano, ali uz Mumin-maminu toplinu i tajne koje kriju morski talasi, njihova nova avantura tek počinje.', 'Глубокая, поэтичная и немного таинственная история о том, как научиться понимать бушующее море и самых близких людей.', 'A poetic, slightly mysterious, and beautifully atmospheric tale about understanding the wild sea and those closest to you.', 'Duboka, poetična i pomalo tajanstvena priča o tome kako razumjeti divlje more i one koji su nam najdraži.', '/covers/DP-0416.webp', '#2c4c64', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","magic","friends"]', '["moomins","sea","lighthouse","family","classics"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мемуары-муми-папы-417', 'DP-0417', 'Мемуары Муми-папы', 'The Memoirs of Moominpappa', 'Memoari Mumin-tate', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Однажды в самую летнюю жару Муми-папа умудрился простудиться. Никогда не знаешь, чем может закончиться простуда — особенно, если простужаешься впервые. Поэтому лучше заранее позаботиться о том, чтобы ты остался в памяти грядущих поколений. Ведь, если речь идет о Муми-папе, в его биографии полным-полно невероятных происшествий, грозных опасностей, трагических поворотов и героических деяний. А вы что думали? До того как сделаться почтенным отцом семейства Муми-папа был искателем приключений и бороздил речные и морские волны на корабле с поэтичным названием «Морзкой оркестор». Обо всем этом потомки (а вместе с ними и вы) однажды прочтут в мемуарах, которые Муми-папа начал писать, едва оправившись от простуды… Книга, которую вы держите в руках, — настоящее событие. Впервые за долгие годы весь цикл о муми-троллях заново переведён на русский язык! Тем, кто уже знаком с обитателями Муми-долины, будет любопытно по-новому взглянуть на их приключения. А тем, кому первая встреча со сказочным миром Туве Янссон только предстоит, можно лишь по-хорошему позавидовать!', 'One sweltering summer day, Moominpappa catches a cold. Convinced that even a simple sneeze could be fatal, he decides it is high time to write down the daring exploits of his youth before it is too late! Long before settling down in Moominvalley, he was an intrepid adventurer escaping an orphanage, sailing stormy seas on the amphibious ship ''Oshun Oxtra'', and crossing paths with eccentric companions. This lively classic is a celebration of courage, friendship, and the tall tales we tell of our grandest adventures.', 'Jednog vrelog ljetnjeg dana, Mumin-tata je uspio da se prehladi i, uplašen za svoju sudbinu, odlučio da odmah zabilježi nevjerovatne avanture iz svoje mladosti za buduća pokoljenja! Mnogo prije nego što je postao miran porodični čovjek, bježao je iz sirotišta, plovio burnim morima na čudesnom brodu i upoznavao neobične saputnike. Ova topla i duhovita priča otkriva tajne prošlosti voljenih likova iz Mumin-doline i slavi duh nesputane avanture.', 'Загляните в бурную юность Муми-папы: здесь строят летающие пароходы, спасаются от привидений и доказывают, что за каждым степенным родителем скрывается отчаянный искатель приключений!', 'Discover Moominpappa''s wild youth full of sea monsters, ghost encounters, and river voyages—proof that behind every respectable parent lies a daring adventurer!', 'Zavirite u burnu mladost Mumin-tate punu morskih avantura i duhova — dokaz da se iza svakog ozbiljnog roditelja krije pravi pustolov!', '/covers/DP-0417.webp', '#38708f', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","funny","friends"]', '["mumini","moomins","sea adventures","classic","youth","friendship"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('незванный-гость-в-муми-доме-418', 'DP-0418', 'Незванный гость в Муми-доме', 'An Unwanted Guest in the Moominhouse', 'Nezvani gost u Mumin-kući', '', 'Tove Jansson', 'Tuve Janson', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Однажды в тихую лунную ночь, в дом муми-троллей пробралось нечто странное. Малышка Мю первой почуяла неладное – в буквальном смысле. Неладное грызло всё подряд, включая мебель, и весьма вызывающе пахло. Чтобы раскрыть тайну загадочного пришельца потребовались усилия всех обитателей Муми-дома! Мир муми-троллей, придуманный Туве Янссон, никогда не перестаёт удивлять и радовать. «Незванный гость в Муми-доме» впервые выходит на русском языке, а иллюстрациями для этой необычной книги стали постановочные фотографии кукольного Муми-дома и его обитателей, которых создали Туве Янссон, Туулика Пиетиле и Пенти Эйстула. А ещё здесь появляется персонаж, которого нет больше ни в одной повести!', 'One quiet moonlit night, something strange sneaks into the Moominhouse. Little My is the first to smell trouble—literally! The intruder gnaws on everything, including the furniture, and gives off a very pungent scent. It will take the entire Moomin family to solve the mystery of this curious visitor. Featuring photographic illustrations of the famous dollhouse crafted by Tove Jansson, Tuulikki Pietilä, and Pentti Eistola, this delightful tale introduces a peculiar character found nowhere else in the Moomin canon.', 'Jedne tihe noći obasjane mjesečinom, nešto neobično se ušunjalo u Mumin-kuću. Mala Mu je prva nanjušila nevolju — i to doslovno! Uljez grize sve redom, čak i namještaj, i prilično čudno miriše. Da bi se riješila tajna ovog zagonetnog gosta, biće potreban trud svih stanovnika kuće. Uz jedinstvene fotografije pravog modela Mumin-kuće koji su izradili Tuve Janson, Tuliki Pjetila i Penti Eistola, ova priča predstavlja i posebnog lika koji se ne pojavljuje ni u jednoj drugoj knjizi!', 'Настоящий ночной детектив в кукольном Муми-доме с фотографиями, где таинственного грызуна вычисляют всем дружным семейством!', 'A charming midnight mystery set in the real handmade Moominhouse, complete with cozy dollhouse photos and an unforgettable visitor!', 'Pravi noćni detektivski zaplet u čarobnoj Mumin-kućici, obogaćen jedinstvenim fotografijama lutkarskog svijeta Mumina!', '/covers/DP-0418.webp', '#2c435e', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","funny","spooky"]', '["moomins","mystery","dollhouse","nighttime","tove jansson"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('походная-книга-муми-тролля-419', 'DP-0419', 'Походная книга Муми-тролля', 'Moomintroll''s Camping Book', 'Muminova knjiga za kampovanje', '', 'Unknown', 'Nepoznati autor', '', 'Амфора', NULL, NULL, 6, 14, 'middle', 'Тому, кто хочет отправиться в поход, как Муми-тролль, как он, жарить блинчики на костре, пригодится эта книга финского писателя. Она содержит немало полезных советов юному туристу и отрывки из увлекательных историй Туве Янссон про обитателей Муми-дола.', 'For anyone dreaming of setting off on a hike like Moomintroll and frying golden pancakes over a campfire, this guide is a trusty companion. Packed with practical outdoor tips for young adventurers, it also features delightful excerpts from Tove Jansson''s classic Moominvalley stories.', 'Za sve one koji žele da krenu na izlet poput Mumina i prže palačinke na logorskoj vatri, ova knjiga je savršen vodič. Sadrži mnoštvo korisnih savjeta za mlade kampere i odlomke iz uzbudljivih priča Tuve Janson o stanovnicima Muminove doline.', 'Берём рюкзак, сковородку для оладий и открываем Муми-дол прямо в ближайшем лесу!', 'Pack your rucksack, grab a pancake pan, and bring Moominvalley''s trail magic to your very next hike!', 'Spakujte ranac, ponesite tiganj za palačinke i stvorite pravu Muminovu avanturu u obližnjoj šumi!', '/covers/DP-0419.webp', '#4a7c59', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","friends"]', '["moomins","camping","hiking","nature","scouting"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('поваренная-книга-муми-мамы-420', 'DP-0420', 'Поваренная книга Муми-мамы', 'Moomin Mamma''s Cookbook', 'Kuvar Mumi-mame', '', 'Sami Malila', 'Sami Malila', '', 'Амфора', NULL, NULL, 6, 14, 'middle', 'Книга финского писателя Сами Малилы - это своеобразное кулинарное путешествие в Долину муми-троллей, где живут знаменитые герои Туве Янсон. С помощью рецептов, собранных на этих страницах, и дети, и взрослые смогут приготовить любимые лакомства Мумии-мамы, Снусмумрика и их друзей и еще много самых разных вкусных и полезных блюд.', 'Finnish author Sami Malila invites readers on a delightful culinary journey to Moominvalley, home to Tove Jansson''s beloved characters. With easy, family-friendly recipes, children and adults alike can whip up favorite treats of Moominmamma, Snufkin, and their friends, bringing warmth and good cheer straight to the table.', 'Knjiga finskog pisca Samija Malile pravo je kulinarsko putovanje u Dolinu mumina, dom čuvenih junaka Tuve Janson. Uz pomoć recepata sabranih na ovim stranicama, i djeca i odrasli mogu pripremiti omiljene poslastice Mumi-mame, Snusmumrika i njihovih prijatelja, kao i mnoštvo drugih ukusnih i zdravih jela.', 'Идеальное руководство для тех, кто мечтает превратить свою кухню в уютный муми-дом и научиться печь самые вкусные оладьи на свете!', 'The ultimate guide for anyone longing to turn their kitchen into a cozy Moominhouse and master the art of the perfect pancake!', 'Savršen vodič za sve koji žele da pretvore svoju kuhinju u udobnu kuću mumina i nauče da peku najslasnije palačinke na svijetu!', '/covers/DP-0420.webp', '#c84b31', 'classics', 'ru', 'available', 'кулинарная книга с рецептами', '["magic","friends","real"]', '["cooking","moomins","recipes","comfort food","family"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мт-и-морской-оркестр-421', 'DP-0421', 'МТ и морской оркестр', 'Moomin and the Ocean Orchestra', 'Mumintrol i morski orkestar', '', 'Tove Jansson', 'Tuve Janson', '', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'Как-то раз солнечным утром Муми-тролль и его друзья отправились на опушку леса, где Муми-папа собирался показать им нечто важное. Что же их там ждёт? На всякий случай Снифф даже прихватил с собой рюкзак со всеми своими драгоценностями. Оказывается, муми-троллей ждёт невероятное морское приключение на огромном, широком и надёжном корабле "Морской оркестр". Эта невероятная история основана на оригинальном сюжете Туве Янссон и адаптирована для маленьких читателей. И, конечно, на каждом развороте можно встретить Малышку Мю, Снусмумрика, Муми-тролля и Фрекен Снорк.', 'One sunny morning, Moomintroll and his friends set off for the edge of the forest, where Moominpappa has something very special to show them. Sniff even packs his backpack full of all his treasures, just in case! It turns out an incredible sea adventure awaits aboard the grand, trusty ship named the Ocean Orchestra. Adapted for young readers from Tove Jansson''s classic world, this delightful tale features Little My, Snufkin, and the whole beloved gang.', 'Jednog sunčanog jutra, Mumintrol i njegovi prijatelji odlaze na ivicu šume gdje Muminpapa želi da im pokaže nešto važno. Njušo je za svaki slučaj ponio ranac sa svim svojim dragocjenostima! Ispostavlja se da ih čeka nevjerovatna morska avantura na čvrstom i velikom brodu „Morski orkestar“. Ova priča, zasnovana na omiljenim motivima Tuve Janson i prilagođena malim čitaocima, vodi nas na talase sa Malom Mu, Snusmumrikom i Muminima.', 'Поднять паруса и припрятать сокровища: семейство Муми-троллей отправляется в самое тёплое и весёлое морское плавание!', 'Hoist the sails and guard your treasures: the Moomin family is embarking on the coziest, splashiest sea voyage!', 'Podignite jedra i čuvajte blago: porodica Mumin kreće u najtopliju i najveseliju morsku plovidbu!', '/covers/DP-0421.webp', '#3b7a99', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","friends","magic"]', '["moomins","sea voyage","ships","classic","friendship"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мт-и-нг-елка-422', 'DP-0422', 'МТ и НГ елка', 'Moomins and the Christmas Tree', 'Mumijevi i novogodišnja jelka', '', 'Tove Jansson', 'Tuve Janson', '', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'В Муми-доле зима. Море спит подо льдом, маленькие букашки спят под землей, муми-тролли спят под одеялами и видят долгие зимние сны. Они залегли в спячку в октябре и намереваются проспать до самой весны. Но Хемуль не таков. Он стоит на крыше и разгребает глубокий снег. Ищет люк, потому что не намерен встречать его в одиночку. Нужно срочно разбудить Муми-тролля. Эта снежная история основана на оригинальном сюжете Туве Янссон и адаптирована для маленьких читателей. И, конечно, на каждом развороте можно встретить Малышку Мю, Снусмумрика, Муми-тролля и Фрекен Снорк.', 'Winter has arrived in Moominvalley. The sea sleeps beneath the ice, tiny creatures rest underground, and the Moomin family is fast asleep tucked warmly under their blankets. They usually hibernate straight through until spring, but the Hemulen has other plans! He''s shoveling through the deep snow on the roof, determined to wake Moomintroll up to celebrate. Based on Tove Jansson''s classic winter tale, this cozy picture book brings little readers face-to-face with Little My, Snufkin, Snorkmaiden, and Christmas magic.', 'Zima je stigla u Mumin dolinu. More spava pod ledom, a porodica Mumi utonula je u topli zimski san sve do proljeća. Međutim, Hemul ima sasvim druge planove: kopa duboki snijeg na krovu kako bi probudio Mumina i zajedno s njim dočekao tajanstveni Božić. Ova topla sniježna priča, stvorena prema klasičnoj priči Tuve Janson, savršeno dočarava zimsku čaroliju i ponovno okuplja Malu Mu, Snusmumrika i Mumintrola.', 'Что делать, если вас разбудили среди зимы ради загадочной «Ёлки»? Заварить чай, позвать друзей и устроить самый тёплый зимний праздник!', 'What do you do when you are woken from hibernation for a mysterious thing called Christmas? Make tea, gather your friends, and make it cozy!', 'Šta uraditi ako vas probude usred zimskog sna zbog tajanstvene „jelke”? Skuvajte topli čaj, okupite prijatelje i stvorite najljepšu zimsku čaroliju!', '/covers/DP-0422.webp', '#3b6e8c', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","friends","adventure"]', '["moomins","winter","christmas","snow","classic"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мт-и-самый-последний-на-свете--423', 'DP-0423', 'МТ и самый последний на свете дракон', 'Moomintroll and the Very Last Dragon', 'Mumintrol i posljednji zmaj na svijetu', '', 'Tove Jansson', 'Tuve Janson', '', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'В Муми-доле зима. Море спит подо льдом, маленькие букашки спят под землей, муми-тролли спят под одеялами и видят долгие зимние сны. Они залегли в спячку в октябре и намереваются проспать до самой весны. Но Хемуль не таков. Он стоит на крыше и разгребает глубокий снег. Ищет люк, потому что не намерен встречать его в одиночку. Нужно срочно разбудить Муми-тролля.', 'Winter has descended upon Moominvalley. The sea slumbers under the ice, creatures hide underground, and the Moomins are fast asleep under their quilts until spring. But the Hemulen has other plans—standing on the snow-covered roof, he is determined to dig out the hatch and wake Moomintroll right away, because some winter mysteries cannot be faced alone.', 'Zima je stigla u Mumindol. More spava pod ledom, bube pod zemljom, a Mumini pod toplim jorganima čekaju proljeće. Ali Hemul ne namjerava da čeka! Popeo se na krov, razgrće dubok snijeg i traži tavan, odlučan da smjesta probudi Mumintrola kako ne bi morao sam da se suoči s velikom zimskom avanturom.', 'Даже если весь Муми-дол сладко посапывает под одеялом, зов приключений разбудит кого угодно!', 'Even when the whole Moominvalley is tucked into winter slumber, curiosity and friendship will always wake you up!', 'Čak i kad cijeli Mumindol slatko hrče pod jorganom, velika zimska pustolovina ne čeka proljeće!', '/covers/DP-0423.webp', '#3e708a', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","adventure","friends"]', '["moomins","winter","friendship","magic","tove jansson"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мт-и-невидимая-гостья-424', 'DP-0424', 'МТ и невидимая гостья', 'Moomintroll and the Invisible Guest', 'Mumi i nevidljiva gošća', '', 'Tove Jansson', 'Tuve Janson', '', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'Ох, какая на улице непогода! В такую грозу лучше всего сидеть возле печки в домике, напоминающем изразцовую печку, пить горячий кофе, болтать о разных пустяках и чистить ароматные грибы, чтобы засушить их на зиму. Но вот в дверь домика муми-троллей кто-то настойчиво стучится. Кто там пришёл? И что делать, если гостья оказалась невидимой?', 'Outside, a thunderstorm is raging—the perfect evening to gather round the warm stove in the Moominhouse, sip hot coffee, and clean fragrant mushrooms for winter. But suddenly, there is a persistent knock at the door! Who could be braving the storm, and what should the Moomin family do when their new guest turns out to be completely invisible?', 'Kakvo je samo nevrijeme napolju! Za vrijeme takve oluje najbolje je sjedjeti kraj tople peći u Mumi kući, piti toplu kafu i pripremati mirisne pečurke za zimu. Odjednom, neko uporno kuca na vrata. Ko je to došao i šta raditi kada je nova gošća sasvim nevidljiva?', 'Уютная и трогательная история о том, как доброта, забота и чашечка тёплого чая могут вернуть уверенность даже самой невидимой девочке на свете.', 'A tender, heartwarming tale showing that a little warmth, patience, and love can help anyone step back into the spotlight.', 'Nježna i topla priča o tome kako ljubav, prihvatanje i šolja toplog čaja mogu pomoći i najnevidljivijem biću da ponovo zablista.', '/covers/DP-0424.webp', '#3b6978', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","friends"]', '["moomins","kindness","rainy day","acceptance","classic"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мт-и-остров-хаттифнатов-425', 'DP-0425', 'МТ и остров Хаттифнатов', 'Moomins and the Hattifatteners'' Island', 'Mumi-troli i ostrvo Hatifnata', '', 'Tove Jansson', 'Tuve Janson', '', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'В середине лета в Муми-доле стояла страшная жара. Семейство муми-троллей и их друзья совершенно извелись и постоянно ссорились. Чтобы хоть немного освежиться, они решают отправиться на морской берег, где находят лодку. Куда плыть? На какой-нибудь остров. Но что их там ждёт? Истории о муми-троллях и других обитателях Муми-дола знают и любят по всему миру уже долгие годы. Классический оригинальный рассказ Туве Янссон о дружбе теперь адаптирован специально для малышей. История "Муми-тролли и остров хатифнаттов" выходит теперь отдельным изданием. Ранее она издавалась в составе сборника "Муми-тролли и новые истории Муми-дола".', 'Midsummer brings unbearable heat to Moominvalley, making the Moomin family and their friends grumpy and restless. To cool off, they head to the seaside, find an abandoned sailboat, and embark on a voyage across the waves to a mysterious island. But who lives there, and what secrets are hidden among the electric Hattifatteners? Tove Jansson''s beloved classic tale of friendship and adventure is adapted here especially for young readers.', 'Usred ljeta u Mumin-dolini zavladala je strašna vrućina, pa su Mumi-porodica i prijatelji postali nervozni i svadljivi. Da se osvježe, kreću na obalu mora, pronalaze čamac i započinju plovidbu ka misterioznom ostrvu. Ko ih tamo čeka i kakve tajne kriju neobični Hatifnati? Omiljena priča Tuve Janson o prijateljstvu i pustolovinama prilagođena je najmlađim čitaocima.', 'Спасаясь от зноя, Муми-семейство отправляется в морской поход — прямо навстречу загадкам и наэлектризованным хатифнаттам!', 'Escaping the summer heat, the Moomin family sets sail for a sea voyage straight toward mysterious, electric Hattifatteners!', 'Bježeći od ljetnje žege, Mumi-porodica isplovljava na more pravo u susret tajanstvenim, naelektrisanim Hatifnatima!', '/covers/DP-0425.webp', '#2c7287', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","friends","magic"]', '["moomins","island","sea","summer","adventure"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мт-и-остров-с-маяком-426', 'DP-0426', 'МТ и остров с маяком', 'Moomins and the Lighthouse Island', 'Mumini i ostrvo sa svjetionikom', '', 'Tove Jansson', 'Tuve Janson', '', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'Муми-папа мечтает вернуться на Остров, который настолько маленький, что Крошка Мю подумала, что это просто муха села на карту. И вот, путешествие к Острову с маяком открывает семейству муми-троллей новый мир. Любовь к морю и морским приключениям - неотъемлемая часть рассказов Туве Янссон. В этой книге вы сможете совершить настоящее морское путешествие, в котором можно будет исследовать природу и тайны архипелага, научиться любить море и беречь его. Семейство муми-троллей отправляется на парусной лодке к Острову с маяком, а во время своего плавания они изучают навигацию, знакомятся с морскими обитателями и встречают смотрителя маяка, который расскажет им, как правильно позаботиться о море.', 'Moominpappa dreams of sailing to an island so tiny that Little My mistook it for a fly sitting on the map! Setting off in a sailboat toward the mysterious lighthouse island, the Moomin family discovers a whole new world. Throughout their nautical adventure, they learn navigation, meet sea creatures, and find out from the lighthouse keeper how to truly love and care for the ocean.', 'Mumin-tata sanja o povratku na ostrvo koje je toliko sićušno da je Mala Mu pomislila da je to samo muva sletjela na kartu! Plovidba ka ostrvu sa svjetionikom otvara porodici Mumina čitav jedan novi svijet. Tokom svoje morske avanture, oni uče osnove navigacije, upoznaju morske stanovnike i otkrivaju kako da vole i čuvaju more.', 'Поднимайте паруса: отправляемся с муми-троллями к далёкому маяку разгадывать морские тайны и учиться беречь океан!', 'Hoist the sails and journey with the Moomins to a lonely lighthouse to unravel maritime secrets and learn how to protect the ocean!', 'Podignite jedra i zaplovite s Muminima ka usamljenom svjetioniku kako biste otkrili morske tajne i naučili kako da čuvate more!', '/covers/DP-0426.webp', '#1f5f7a', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","friends","magic"]', '["moomins","sea","lighthouse","sailing","ecology"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мт-и-новые-истории-муми-дола-427', 'DP-0427', 'МТ и новые истории Муми-дола', 'Moomintroll and New Stories from Moominvalley', 'Mumintrol i nove priče iz Mumin-dola', '', 'Tove Jansson', 'Tuve Janson', '', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'В историях Туве Янссон про долину Муми-троллей может произойти всё что угодно: волны потопа однажды унесли Муми-папу, электрические хатифнатты неожиданно оказались на необитаемом острове, а волшебная шляпа устроила настоящий кавардак. И в центре всех этих приключений - круглый домик, где живёт Муми-семья. Три удивительные истории в этом сборнике основаны на оригинальных сюжетах Туве Янссон и адаптированы для маленьких читателей, а яркие иллюстрации трогательных муми-троллей, Крошки Мю и неутомимого искателя приключений Снусмумрика просто не могут оставить равнодушными.', 'In Tove Jansson''s tales of Moominvalley, anything can happen: a flood once swept Moominpappa away, electric Hattifatteners appeared on a deserted island, and a wizard''s hat caused utter chaos! At the heart of it all stands the cozy round house where the Moomin family lives. These three wonderful stories, adapted for younger readers from original classics, bring Moomintroll, Little My, and Snufkin to life with vibrant, heartwarming illustrations.', 'U pričama Tuve Janson o Mumin-dolu sve je moguće: poplava je jednom odnijela Mumin-tatu, električni Hatifnati su se iznenada pojavili na pustom ostrvu, a čarobni šešir stvorio je potpuni haos! U središtu svih ovih pustolovina stoji topla okrugla kućica u kojoj živi porodica Mumin. Tri predivne priče u ovoj zbirci, prilagođene mlađim čitaocima prema originalnim motivima, oživljavaju Mumintrola, Malu Mu i Snusmumrika uz neodoljive ilustracije.', 'Загляните в гостеприимный круглый домик Муми-дола — здесь всегда пахнет оладьями и ждут новые тёплые приключения!', 'Step inside the welcoming round house of Moominvalley — it always smells of fresh pancakes and promises gentle, magical adventures!', 'Zavirite u gostoljubivu okruglu kućicu Mumin-dola — ovdje uvijek miriše na tople palačinke i čekaju nove nježne avanture!', '/covers/DP-0427.webp', '#4b86b4', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","adventure","friends"]', '["moomins","scandinavian classics","family","friendship","bedtime stories"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('муми-тролли-на-рыбалке-428', 'DP-0428', 'Муми-тролли на рыбалке', 'Moomins Go Fishing', 'Mumijevi na pecanju', '', 'Unknown', 'Nepoznat autor', 'Туве Янссон', 'Вилли-винки', NULL, NULL, 6, 14, 'middle', 'Увлекательный гид для любителей природы всех возрастов! Отправляйтесь на рыбалку вместе со Снусмумриком и исследуйте обитателей озёр, рек и Балтийского моря. Невероятное погружение в удивительный подводный мир. В книге собраны полезные факты и рисунки почти сотни рыб, обитающих в Северной Европе, проиллюстрированные чёрно-белыми рисунками Туве Янссон.', 'A captivating guide for nature enthusiasts of all ages! Join Snufkin on a fishing trip and explore the creatures inhabiting lakes, rivers, and the Baltic Sea. This book gathers fascinating facts about nearly a hundred Northern European fish species, complemented by classic black-and-white drawings by Tove Jansson.', 'Fascinantan vodič za ljubitelje prirode svih uzrasta! Krenite na pecanje sa Snufkinom i istražite stanovnike jezera, rijeka i Baltičkog mora. Knjiga donosi korisne činjenice i opise skoro stotinu vrsta riba Sjeverne Evrope, obogaćene originalnim crno-bijelim crtežima Tuve Janson.', 'Забрасывайте удочку вместе со Снусмумриком: это не просто сказка, а настоящий иллюстрированный атлас подводного мира!', 'Cast your line alongside Snufkin: this isn''t just a fairy tale, but a wonderful illustrated field guide to the underwater world!', 'Zabacite udicu zajedno sa Snufkinom: ovo nije samo bajka, već pravi ilustrovani atlas podvodnog svijeta!', '/covers/DP-0428.webp', '#2c6c8c', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","animals","real"]', '["moomins","fishing","nature","fish","guide"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кыш-и-двапортфеля-429', 'DP-0429', 'Кыш и Двапортфеля', 'Kysh and Two Briefcases', 'Kiš i Dva ranca', 'Юз Алешковский', 'Yuz Aleshkovsky', 'Juz Alješkovski', '', '', NULL, NULL, 6, 14, 'middle', 'Юза Алешковского принято считать "взрослым" писателем, однако это не совсем верно. Помимо романов и песен, он создал несколько замечательных, добрых, поучительных повестей для детей. Одна из них - "Кыш и Двапортфеля" - вошла в нашу книгу. История о дружбе первоклассника Алёши Сероглазова и его щенка Кыша написана Юзом Алешковским с большой любовью к детям и братьям нашим меньшим. Именно поэтому Кыш получился таким живым, ярким, а Алёша - настоящим верным товарищем, отважным, смелым и способным на удивительные поступки. В издании представлены оригинальные иллюстрации Н. Бугославской. Для среднего школьного возраста.', 'A beloved classic about first-grader Alyosha, nicknamed ''Two Briefcases'' due to his small height, and his devoted puppy, Kysh. Together, the inseparable duo navigates the triumphs and tribulations of starting school, neighbourhood squabbles, and even amateur detective work, proving that true courage and loyalty have nothing to do with size.', 'Omiljeni dječji klasik o prvačiću Aljoši, koga zbog sitnog rasta zovu „Dva ranca“, i njegovom vjernom štenetu Kišu. Nerazdvojni dvojac prolazi kroz školske izazove, komšijske nestašluke i pravu malu detektivsku istragu, dokazujući da pravo junaštvo i odanost nemaju nikakve veze s visinom.', 'Невероятно добрая и смешная школьная повесть о настоящей дружбе мальчишки и щенка, полная дворовых приключений и детективных интриг!', 'A delightful, laughter-filled schoolyard adventure showing that even the smallest kid and scruffiest pup can have the biggest hearts!', 'Neodoljivo topla i duhovita priča o prvačiću i štenetu koja dokazuje da su najveća prijateljstva i najhrabrija srca često najmanjeg rasta!', '/covers/DP-0429.webp', '#d97d27', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["funny","friends","animals"]', '["puppy","school life","friendship","first grade","classic"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебная-галоша-430', 'DP-0430', 'Волшебная галоша', 'The Magic Galosh', 'Čarobna kaljača', 'Марк Сергеев', 'Mark Sergeev', 'Mark Sergejev', '', 'Эксмо', NULL, NULL, 6, 14, 'middle', 'Новая сказочная повесть в серии расскажет об удивительном исчезновении 33 школьников. А всё произошло из-за обычной, на первый взгляд, галоши, которую подарил Вадиму Смирнову старичок с зелёной бородой. Если надеть эту галошу и произнести волшебные слова, можно стать невидимым! И тогда, делай, что хочешь: можешь сбежать из школы и отправиться в далёкое путешествие, не покупая билет; или съесть незаметно столько мороженого, чтобы мурашки по коже пошли. А можешь помочь родной футбольной команде выиграть матч или наказать дворового хулигана. Быть невидимкой очень увлекательно! Вот только снова стать видимым намного сложнее. Для среднего школьного возраста.', 'A captivating fairytale adventure about the mysterious disappearance of 33 schoolchildren, all sparked by a seemingly ordinary galosh gifted to Vadim by a green-bearded old man. Putting on this footwear and uttering magic words turns you invisible! Suddenly, you can skip school, travel without a ticket, eat mountains of ice cream, or help your football team win. Being invisible feels like the ultimate fun—until you realize that turning visible again is far trickier than it seems.', 'Ova uzbudljiva bajkovita priča prati nevjerovatan nestanak trideset troje školaraca, a sve je počelo zbog naizgled obične kaljače koju je dječaku Vadimu poklonio starac sa zelenom bradom. Čim je obuje i izgovori čarobne riječi, postaje nevidljiv! Može da pobjegne sa časova, putuje bez karte, smaže brdo sladoleda ili pomogne svom fudbalskom timu da pobijedi. Biti nevidljiv je nevjerovatna avantura — sve dok ne shvati da je ponovo postati vidljiv mnogo teže.', 'Осторожно: эта озорная книга заставит мечтать о волшебной обувке и напомнит, что у любого трюка с невидимостью есть забавные последствия!', 'Careful what you wish for: this mischievous tale proves that invisibility is pure fun—right up until you have to turn visible again!', 'Pazi šta želiš: ova nestašna priča dokazuje da je nevidljivost sjajna zabava, sve dok ne pokušaš ponovo da postaneš vidljiv!', '/covers/DP-0430.webp', '#2d7a46', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","adventure","funny"]', '["invisibility","school adventures","childhood classics","magic artifact","mischief"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('королевство-кривых-зеркал-431', 'DP-0431', 'Королевство кривых зеркал', 'The Kingdom of Crooked Mirrors', 'Kraljevstvo krivih ogledala', 'Виталий Губарев', 'Vitaly Gubarev', 'Vitalij Gubarev', '', '', NULL, NULL, 6, 14, 'middle', 'Однажды девочка Оля, шагнув через зеркало, попала в Королевство кривых зеркал, где ей пришлось пережить немало опасных приключений. Ей удалось увидеть себя со стороны, познакомившись с точно такой же, как она, девочкой по имени Яло. Наблюдая за этой девочкой, как за самой собой, Оля смогла избавиться от недостатков, которых раньше в себе не замечала. Для среднего школьного возраста.', 'One day, stepping straight through a looking glass, ordinary schoolgirl Olya finds herself trapped in the deceptive Kingdom of Crooked Mirrors. Facing danger at every turn alongside Yalo—her own lively reflection—Olya gets a rare chance to look at herself from the outside and overcome the very flaws she never cared to notice before. A beloved classic fantasy adventure.', 'Jednog dana, zakoračivši kroz ogledalo, djevojčica Olja dospijeva u Kraljevstvo krivih ogledala, gdje je čekaju brojne opasne avanture. Tamo upoznaje Jalo, svoj živi odraz. Posmatrajući svoje ponašanje sa strane, Olja uspijeva da prepozna i ispravi mane koje ranije kod sebe nikada nije primjećivala. Omiljeni klasik fantastične književnosti.', 'Загляни за зеркальную гладь: удастся ли тебе вместе с Олей и Яло победить коварных злодеев и взглянуть на свои капризы со стороны?', 'Step through the looking glass to help Olya and Yalo topple tyrannical villains and learn how funny our own flaws look from the outside!', 'Zakoračite kroz ogledalo i pomozite Olji i Jalo da pobijede zle velikaše i shvate kako naše sopstvene mane izgledaju spolja!', '/covers/DP-0431.webp', '#3c4d79', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","magic","friends"]', '["mirrors","parallel worlds","classic","self-discovery","friendship"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('момо-432', 'DP-0432', 'Момо', 'Momo', 'Momo', 'Михаэль Энде', 'Michael Ende', 'Mihael Ende', '', 'Махаон', NULL, NULL, 6, 14, 'middle', 'Написанная в 1973 году, книга известного немецкого писателя Михаэля Энде сегодня звучит как нельзя более современно. В ней рассказывается об удивительной девочке Момо, обладавшей редким даром – слушать других людей. В мужском пиджаке с подвёрнутыми рукавами, с Цветком Времени и черепахой под мышкой, она вступает в неравную борьбу с жестоким миром Серых господ, с миром прагматиков и материалистов, забывших о настоящих человеческих ценностях, о доброте и сочувствии к ближнему. Книга оформлена рисунками автора.', 'Written in 1973, this timeless masterpiece by renowned German author Michael Ende feels more relevant than ever. It tells the story of Momo, an extraordinary little girl who possesses the rare gift of truly listening to others. In an oversized jacket with rolled-up sleeves, carrying a magical Hour-Lily and accompanied by a clairvoyant tortoise, she embarks on a daring quest against the sinister Men in Grey—thieves who trick people into hoarding and wasting away their precious lifetimes. Illustrated with original drawings by the author.', 'Napisana 1973. godine, ova bezvremena priča slavnog njemačkog pisca Mihaela Endea danas je aktuelnija nego ikada. Govori o čudesnoj djevojčici Momo koja ima rijedak dar — sposobnost da istinski sasluša druge ljude. U prevelikom muškom sakou, sa Časom-cvijetom i mudrom kornjačom pod miškom, ona ulazi u neravnopravnu borbu protiv jezivih Sivih gospodara, kradljivaca vremena koji ljude lišavaju topline, saosjećanja i radosti. Knjiga je obogaćena originalnim autorovim ilustracijama.', 'Невероятно глубокая сказка-притча, напоминающая и детям, и вечно спешащим взрослым о том, что самое ценное время — то, которое мы искренне дарим друг другу.', 'A deeply touching fairytale reminding both children and perpetually rushed adults that the most precious time is the time we genuinely give to each other.', 'Duboka i dirljiva bajka koja podsjeća i djecu i vječito užurbane odrasle da je najdragocjenije vrijeme ono koje iskreno poklanjamo jedni drugima.', '/covers/DP-0432.webp', '#5a6b7c', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["magic","adventure","friends"]', '["time","friendship","classic fantasy","kindness","allegory"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-тома-сойера-433', 'DP-0433', 'Приключения Тома Сойера', 'The Adventures of Tom Sawyer', 'Pustolovine Toma Sojera', 'Марк Твен', 'Mark Twain', 'Mark Tven', '', 'Азбука', NULL, NULL, 6, 14, 'middle', 'Повесть Марка Твена «Приключения Тома Сойера» без преувеличения можно назвать одной из самых любимых во всём мире. Впервые увидевшие свет в 1876 году, приключения озорного, неугомонного, но безумно очаровательного проказника Тома из небольшого американского городка и сегодня захватывают воображение детей и взрослых. Читатели с удовольствием становятся участниками всех проделок Тома и его друзей и без оглядки пускаются вместе с ними в рискованные авантюры, от которых захватывает дух. Текст в этом издании адаптирован с учётом возрастных особенностей детей, уже освоивших самостоятельное чтение и обладающих достаточным словарным запасом.', 'Mark Twain''s timeless masterpiece brings to life the unforgettable escapades of the clever and spirited Tom Sawyer along the Mississippi River. From cunningly tricking his friends into whitewashing Aunt Polly''s fence to hunting for lost treasure and braving eerie caves with Huck Finn, Tom''s world is an exhilarating celebration of boyhood, freedom, and wit. This accessible edition is thoughtfully adapted for young independent readers.', 'Bezvremeni klasik Marka Tvena oživljava nezaboravne nestašluke dovitljivog i neustrašivog dječaka Toma Sojera na obalama rijeke Misisipi. Od prepredenog farbanja ograde tetke Poli do potrage za skrivenim blagom i istraživanja tajanstvenih pećina sa Hakom Finom, Tomove avanture slave slobodu, djetinjstvo i prijateljstvo. Ovo izdanje je prilagođeno mladim čitaocima koji samostalno čitaju.', 'Кто откажется научиться красить забор чужими руками и найти настоящий клад на пару с лучшим другом?', 'Who wouldn''t want to learn how to trick friends into painting a fence and hunt for real buried treasure?', 'Ko bi odbio da nauči kako da nagovori druge da mu ofarbaju ogradu i pritom iskopa pravo gusarsko blago?', '/covers/DP-0433.webp', '#c96f3b', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["adventure","funny","friends"]', '["classics","mississippi","childhood","treasure","mischief"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вредные-советы-для-детей-434', 'DP-0434', 'Вредные советы для детей', 'Bad Advice for Children', 'Štetni savjeti za djecu', 'Остер Григорий Бенционович', 'Grigory Oster', 'Grigorij Oster', '', 'АСТ', NULL, NULL, 6, 14, 'middle', 'Хулиганская классика детской литературы – замечательная книга-путеводитель по хорошему и плохому поведению! Современная классика хулиганского юмора для детей – веселое собрание вредных советов от писателя Григория Остера и издательства «Малыш»! Ярких мастеров редчайшего жанра хулиганской детской литературы, писателя Григория Остера и художника Николая Воронцова, заслуженно называют современными детскими классиками. Что, впрочем, никак не мешает детям нового поколения гомерически хохотать над их совместными творениями. Ироничные стихи «Вредных советов» Григория Остера давно разобраны на цитаты и выросли в отдельный и вполне самостоятельный жанр, который неизменно дарит радость поколениям читателей. Иллюстрации Николая Воронцова также отличает нестандартная подача: он часто использует коллажи, цитаты из книг и фильмов. «В детской книге должно быть много деталей — десять тысяч, не меньше. Дети любят их рассматривать. Да и взрослые любят», — говорит художник. Встречайте отборные «Вредные советы» Григория Остера – отличный подарок ребёнку, мальчику или девочке, и книгу, которую нужно читать всей семьей! Григорий Остер — детский писатель, прославившийся «Вредными советами» и учебником для детей «Папамамалогия». А еще он написал сценарии к мультипликационным фильмам «38 попугаев», «Котенок по имени Гав», «Обезьянки», повесть «Петька — микроб» и роман для дошколят «Сказка с подробностями».', 'A legendary classic of mischievous children''s literature! Grigory Oster''s hilarious collection of satirical verses masterfully uses reverse psychology to teach good manners by playfully recommending the absolute opposite. Filled with Nikolai Vorontsov''s rich, detail-packed cartoon collages, this timeless comedy guarantees side-splitting laughter for mischievous rascals and their parents alike.', 'Legendarni klasik nestašne dječje književnosti! Zbirka satiričnih stihova Grigorija Ostera majstorski koristi obrnutu psihologiju kako bi djecu naučila lijepom ponašanju savjetujući im upravo suprotno. Uz dinamične i duhovite ilustracije Nikolaja Voroncova prepune detalja, ova bezvremenska knjiga garantuje smijeh do suza i djeci i roditeljima.', 'Идеальное руководство от противного для тех, кто устал быть паинькой и хочет посмеяться от души всей семьей!', 'The ultimate reverse-psychology handbook for anyone tired of being on their best behavior and ready for serious family giggles!', 'Vrhunski vodič obrnute psihologije za sve mališane kojima je dosadilo da budu poslušni i koji žele da nasmiju cijelu porodicu!', '/covers/DP-0434.webp', '#e65100', 'classics', 'ru', 'available', 'Категория: Туве Янссон', '["funny","real"]', '["humor","poetry","mischief","classics","family reading"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рыцари-изумруда-2-435', 'DP-0435', 'Рыцари Изумруда 2', 'The Knights of Emerald 2', 'Smaragdni vitezovi 2', '', 'Anne Robillard', 'Anne Robillard', '', '', NULL, NULL, 8, 16, 'middle', 'Приключения "Рыцарей Изумруда" продолжаются! Это новый эпизод оригинальной истории Анн Робийар. Волшебник Элунд уверен в умении Рыцарей обращаться с оружием, но готовы ли они использовать всю силу своей магии? С помощью своего старого друга Элунд приготовил для своих учеников новое испытание.', 'The adventures of the Knights of Emerald continue! In this dynamic graphic novel chapter of Anne Robillard''s saga, the wizard Elund knows his knights can handle weapons, but are they ready to unlock the full power of their magic? With help from an old friend, Elund sets up a daring new trial for his apprentices.', 'Avanture Smaragdnih vitezova se nastavljaju! U ovom uzbudljivom stripu prema sagi An Robijar, čarobnjak Elund zna da njegovi vitezovi vladaju oružjem, ali jesu li spremni da oslobode svu moć svoje magije? Uz pomoć starog prijatelja, Elund priprema novi izazov za svoje učenike.', 'Мечи наготове, заклинания на подходе — погрузитесь в захватывающее рыцарское фэнтези, где магия решает всё!', 'Swords drawn and spells at the ready—dive into an epic fantasy comic where mastering magic is the ultimate test!', 'Isučite mačeve i pripremite čarolije — uronite u uzbudljivi strip đe je magija najveći ispit za mlade vitezove!', '/covers/DP-0435.webp', '#1d6f42', 'comics', 'ru', 'available', '', '["adventure","magic","friends"]', '["fantasy","knights","magic","graphic novel","comics"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('война-катрин-436', 'DP-0436', 'Война Катрин', 'Catherine''s War', 'Katrinin rat', '', 'Julia Billet, Claire Fauvel', 'Žilija Bije, Kler Fovel', '', 'Самокат', NULL, NULL, 8, 16, 'middle', '«Война Катрин» — графический роман о войне, в котором нет ни одной военной сцены. Рассказ об оккупации Франции ведётся от лица девочки-еврейки, которая была вынуждена сменить имя и искать убежища от нацистов в разных уголках страны. Из ценных вещей у неё с собой лишь фотоаппарат. Она запечатлевает всех приютивших её людей и таким образом составляет галерею свидетельств о Второй мировой. Объектив её камеры фокусируется на добре, и через него мы видим Францию 1940-х годов глазами взрослеющего в войну подростка. Художница Клер Фовель создала графический роман «Война Катрин», вдохновившись одноимённым произведением Юлии Бийе. В 2018 году авторы получили премию Международного фестиваля комиксов в Ангулеме, самую престижную в этой области. Художественный роман «Война Катрин» вышел в издательстве «Самокат» в 2021 году.', 'Catherine''s War is a poignant graphic novel about World War II without a single battlefield scene. Set during the Nazi occupation of France, it tells the story of a young Jewish girl who must change her name and flee from refuge to refuge across the country. Her most prized possession is a camera, which she uses to capture portraits of the brave, kind people who shelter her. Through her lens, we witness France in the 1940s through the eyes of a growing teenager who chooses to focus on kindness, resilience, and hope.', '„Katrinin rat” je dirljiv grafički roman o Drugom svjetskom ratu u kojem nema nijedne scene sa ratišta. Smještena u okupiranu Francusku, priča prati jevrejsku djevojčicu primoranu da promijeni ime i skriva se širom zemlje. Njena jedina dragocjenost je foto-aparat, kojim bilježi portrete hrabrih i dobrih ljudi koji joj pružaju utočište. Kroz njen objektiv otkrivamo Francusku četrdesetih godina prošlog vijeka očima tinejdžerke koja u mračnim vremenima bira da svjedoči o dobroti i nadi.', 'Пронзительный и светлый графический роман о том, как один маленький фотоаппарат может победить страх и сохранить память о человечности.', 'A tender and luminous graphic novel proving that a camera lens and a brave heart can capture light even in the darkest times.', 'Nježan i svijetao grafički roman koji pokazuje kako foto-aparat i hrabro srce mogu sačuvati svjetlost i ljudskost u najtežim vremenima.', '/covers/DP-0436.webp', '#c86d49', 'comics', 'ru', 'available', '', '["real","friends","adventure"]', '["graphic novel","wwii","photography","courage","history"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sapiens-графическая-история-ча-437', 'DP-0437', 'Sapiens. Графическая история. Часть 1. Рождение человечества:', 'Sapiens: A Graphic History, Volume 1: The Birth of Humankind', 'Sapiens: Grafička istorija, 1. dio: Rođenje čovječanstva', 'Юваль Ной Харари, Вандермелен', 'Yuval Noah Harari, David Vandermeulen', 'Juval Noj Harari, Dejvid Vandermulen', '', 'Синдбад', NULL, NULL, 8, 16, 'middle', 'Это ошеломляющая история о том, как ничем не примечательное млекопитающие стало человеком, который научился расщеплять атом, летать на Луну, манипулировать генетическим кодом и обрел абсолютную власть над планетой. В этом захватывающем дух путешествии в глубокие дерби истории вашим гидом будет Юваль Ной Харари, а компанию вам составят Первобытный Билл, доктор Фантазия и детектив Лопес. Иллюстрированный формат позволит взглянуть на события нашего далекого прошлого другими глазами: эволюция человека представлена через телевизионное реалити-шоу, первая встреча сапиенсов и неандертальцев осмысляется через шедевры современного искусства, а исчезновение с лица Земли мамонтов и саблезубых кошек становится предметом расследования в кинодетективе. Так об истории человечества не рассказывал еще никто. Юваль Ной Харари - историк и философ, автор всемирного бестселлера "Sapiens. Краткая история человечества". Защитил докторскую диссертацию в Оксфордском университете. Профессор Еврейского университета в Иерусалиме, преподает всемирную историю. В своих исследованиях Харари концентрируется на таких макроисторических вопросах, как: "Какова связь между историей и биологией?", "Существует ли историческая справедливость?", "Становятся ли люди по мере исторического развития счастливее?", "Какие этические вопросы порождает развитие науки и технологий в XXI веке?"', 'A breathtaking graphic adaptation of the global phenomenon, revealing how an unremarkable ape conquered planet Earth. Joined by colorful fictional guides like Prehistoric Bill and Detective Lopez, readers explore human evolution through a reality TV show, marvel at Neanderthal encounters framed as modern art, and solve prehistoric mysteries in a thrilling noir style. Deep history has never been this vibrant, funny, and accessible.', 'Očaravajuća grafička adaptacija svjetskog fenomena koja otkriva kako je neugledni primat zagospodario planetom Zemljom. Uz duhovite vodiče poput Prvobitnog Bila i detektivke Lopez, čitaoci istražuju ljudsku evoluciju kroz TV rijaliti, posmatraju susret sa neandertalcima kao modernu umjetnost i rješavaju misterije praistorije u noar stilu. Istorija čovječanstva nikada nije bila ovako uzbudljiva i zabavna.', 'Кто бы мог подумать, что вся история эволюции человека может читаться на одном дыхании, как остроумный детективный комикс!', 'Who knew the epic saga of human evolution could read like a witty detective comic full of reality shows and prehistoric mysteries!', 'Ko bi rekao da čitava evolucija čovječanstva može da se čita u jednom dahu, poput duhovitog i pametnog detektivskog stripa!', '/covers/DP-0437.webp', '#e68923', 'comics', 'ru', 'available', '', '["adventure","real","funny"]', '["history","evolution","graphic novel","comics","science"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('поход-к-мандрагорам-или-истори-438', 'DP-0438', 'Поход к мандрагорам, или История о льве, слоне, жирафе и еже, который хотел стать совой', 'The Mandrake Expedition, or the Story of a Lion, an Elephant, a Giraffe, and a Hedgehog Who Wanted to Be an Owl', 'Pohod na mandragore, ili Priča o lavu, slonu, žirafi i ježu koji je želio da postane sova', 'Анна Красильщик, Юрий Сапрыкин-мл', 'Anna Krasilshchik, Yuri Saprykin Jr.', 'Ana Krasiljščik, Jurij Saprjkin ml.', 'Иллюстрации Тима Яржомбека', 'Белая ворона', NULL, NULL, 8, 16, 'middle', 'Однажды Совоеж, Лев, Жираф и Слон решили сгонять в город, развеяться, кофе попить. И сходить в музей, в зал, целиком посвященный старинным мандрагорам. Сказано — сделано. Всего пара деньков пути, но вот незадача: музей закрылся на реконструкцию, а мандрагоры в опасности! Что ж, вместо культурного отдыха друзьям предстоит спасти произведения искусства. Одобрено «Страдающим Средневековьем»!', 'One day, Owlhog, Lion, Giraffe, and Elephant decide to pop into the city for a quick getaway and a cup of coffee—and, of course, to visit the museum hall dedicated entirely to ancient mandrakes. But disaster strikes: the museum is closed for renovations, and the mandrakes are in grave peril! Instead of a relaxing cultural retreat, the crew embarks on a daring art-saving rescue mission. Endorsed by the legendary ''Suffering Middle Ages'' creators!', 'Jednog dana, Sovojjež, Lav, Žirafa i Slon odlučuju da skoknu do grada, popiju kafu i posjete muzej kako bi vidjeli drevne mandragore. Međutim, muzej je zatvoren zbog renoviranja, a vrijedne mandragore su u opasnosti! Umjesto mirnog kulturnog izleta, ovu neobičnu družinu čeka prava spasilačka misija. Strip odobren od strane tvoraca ''Stradalnog srednjeg vijeka''!', 'Настоящий средневековый квест с чашечкой кофе, спасением музейных мандрагор и неподражаемой бандой зверей-интеллектуалов!', 'A hilarious medieval-style graphic quest complete with coffee breaks, rare mandrake rescues, and the most charmingly quirky animal squad around!', 'Urnebesna srednjovjekovna strip-avantura uz šoljicu kafe, spašavanje rijetkih mandragora i najotkačeniju ekipu životinja-intelektualaca!', '/covers/DP-0438.webp', '#d68936', 'comics', 'ru', 'available', 'Для среднего и старшего школьного возраста', '["funny","adventure","animals"]', '["comics","graphic novel","museum","medieval","friendship","art heist"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневники-вишенки-каменный-зооп-439', 'DP-0439', 'Дневники Вишенки. Каменный зоопарк. Том 1', 'Cerise''s Diary: The Stone Zoo. Volume 1', 'Višnjini dnevnici: Kameni zoološki vrt. Tom 1', 'Жорис Шамблен, Орели Нейре', 'Joris Chamblain, Aurélie Neyret', 'Joris Chamblain, Aurélie Neyret', '', 'Миф', NULL, NULL, 8, 16, 'middle', 'Вишенке 10 лет и она мечтает стать писателем. По совету писательницы мадам Дежарден она начинает вести дневник, ведь писатель должен уметь выстраивать историю, собирать факты, брать интервью, а главное — наблюдать. Больше всего Вишенке нравится наблюдать за людьми, особенно взрослыми, у которых всегда столько таинственных дел — попробуй, разгадай, что они скрывают! Однажды, когда Вишенка вместе с подружками сидела в домике на дереве, они заметили в лесу старика с банками краски в руках. Кто это? Что он делает? И почему весь перепачкан в краске? С твердым намерением раскрыть эту тайну Вишенка начинает свое первое расследование.', 'Ten-year-old Cerise dreams of becoming a novelist. Encouraged by writer Madame Desjardins, she starts keeping a diary to practice observation and storytelling. From her secret treehouse, Cerise and her friends notice a mysterious elderly man carrying cans of paint into the woods. Who is he, and why is he covered in colors? Armed with her diary and boundless curiosity, Cerise launches her very first investigation.', 'Višnjica ima deset godina i sanja o tome da postane spisateljica. Po savjetu autorke gospođe Dežarden, počinje da vodi dnevnik kako bi naučila da posmatra svijet i stvara priče. Iz svoje kućice na drvetu, sa najboljim drugaricama primjećuje zagonetnog starca koji nosi kante s farbom duboko u šumu. Ko je on i šta krije? Sa sveskom u ruci, Višnjica započinje svoju prvu veliku istragu.', 'Невероятно красивый графический детектив о том, как детская чуткость и любопытство способны оживить забытое чудо.', 'A breathtakingly illustrated graphic mystery showing how gentle curiosity and a keen eye can bring forgotten wonders back to life.', 'Predivno ilustrovani grafički roman o tome kako dječja radoznalost i toplo srce mogu oživjeti zaboravljena čuda.', '/covers/DP-0439.webp', '#3b6e52', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","friends","real"]', '["graphic novel","detective","friendship","diary","treehouse","forest"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневники-вишенки-таинственная--440', 'DP-0440', 'Дневники Вишенки. Таинственная книга. Том 2', 'Cerise''s Diary: The Mysterious Book. Vol. 2', 'Višnjin dnevnik: Tajanstvena knjiga. Tom 2', 'Жорис Шамблен, Орели Нейре', 'Joris Chamblain, Aurélie Neyret', 'Joris Chamblain, Aurélie Neyret', '', 'Миф', NULL, NULL, 8, 16, 'middle', 'Каникулы в самом разгаре, и Вишенке не сидится на месте. В поисках вдохновения для новой истории в дневнике девочка пытается найти еще одну тайну, стоящую расследования. И вот однажды она замечает пожилую женщину, которая каждый вторник садится на один и тот же автобус в одно и то же время, едет в библиотеку и берет там одну и ту же книгу... Что такого в этой книге? Зачем она старушке? И выдержит ли мама еще одно расследование?.. Детектив Вишенка приступает ко второму делу.', 'Summer vacation is in full swing, and Cerise is searching for a fresh mystery to write about. Soon, she notices an elderly woman who catches the exact same bus every Tuesday, heads straight to the library, and borrows the very same book each time. What secret does this mysterious volume hold, and will Cerise''s mom survive another investigation?', 'Raspust je u punom jeku, a Višnjica traži novu misteriju za svoj dnevnik. Ubrzo primjećuje stariju gospođu koja svakog utorka u isto vrijeme sjeda na isti autobus, odlazi u biblioteku i uvijek uzima istu knjigu... Kakvu tajnu krije ta knjiga i hoće li mama preživjeti još jednu kćerkinu detektivsku avanturu?', 'Библиотечные тайны — самые захватывающие, особенно когда за одной неприметной книгой прячется трогательная история целой жизни!', 'Library mysteries are always the best, especially when a single well-worn book holds the secret to a lifetime of love and memory!', 'Bibliotečke misterije su najljepše, naročito kada jedna obična knjiga krije dirljivu priču o čitavom jednom životu!', '/covers/DP-0440.webp', '#c87a3e', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","friends","real"]', '["graphic novel","detective","library","summer","family"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневники-вишенки-последнее-из--441', 'DP-0441', 'Дневники Вишенки. Последнее из пяти сокровищ. Том 3', 'The Diaries of Cerise: The Last of the Five Treasures (Vol. 3)', 'Dnevnici Višnjice: Posljednje od pet blaga (Tom 3)', '', 'Joris Chamblain, Aurélie Neyret', 'Žoris Šamblen, Oreli Nejre', '', 'Миф', NULL, NULL, 8, 16, 'middle', 'Наступила зима, Вишенка и ее подруги готовятся к праздникам. Пытаясь придумать лучший подарок для мамы, Вишенка попадает в старинное переплетное ателье и знакомится с его владелицей. Одним уютным зимним вечером в сундуке ателье девочки находят посылку с надписью «Первое из пяти сокровищ». Так начинается череда невероятных событий, связывающих воедино судьбы героев. Что это за сокровища и почему они много лет были спрятаны? Какую тайну хранит переплетчица? Детектив Вишенка берется за свое третье расследование. Этот том серии — кладезь уютных зимних сюрпризов. Вас ждут французские рецепты печенья, идеи подарков и совместных развлечений для семьи и друзей, а также по-настоящему теплые иллюстрации и история.', 'Winter has arrived, and Cerise is searching for the perfect holiday gift for her mother when she stumbles upon an old bookbinding atelier. In a dusty chest, she and her friends uncover an intriguing package labeled ''The First of Five Treasures.'' Cerise dives straight into her third detective mystery to unravel decades-old secrets. Complete with cozy winter scenes, French biscuit recipes, and heartwarming crafts, this graphic novel is pure festive comfort.', 'Zima je stigla i Višnjica traži savršen praznični poklon za mamu, što je dovodi do stare knjigoveznice i njene tajanstvene vlasnice. Kada u starom sanduku djevojčice pronađu paket s natpisom „Prvo od pet blaga“, počinje nova topla detektivska avantura. Pored predivnih ilustracija i dirljive priče o prijateljstvu i prošlosti, ovaj grafički roman donosi i prave recepte za zimske kolačiće i praznične ideje.', 'Нежнейший зимний детектив с ароматом старых книг, французского печенья и теплоты, которая согреет в любой мороз!', 'A tender winter mystery brimming with the scent of old books, French cookies, and heart-melting friendship!', 'Nježna zimska detektivska priča koja miriše na stare knjige, francuske kolačiće i topla prijateljstva!', '/covers/DP-0441.webp', '#8c3b4a', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","friends","real"]', '["graphic novel","detective","winter","friendship","family"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневники-вишенки-богиня-без-ли-442', 'DP-0442', 'Дневники Вишенки. Богиня без лица. Том 4', 'The Diaries of Cerise: The Faceless Goddess (Vol. 4)', 'Dnevnici Višnjice: Boginja bez lica (Tom 4)', '', 'Joris Chamblain, Aurélie Neyret', 'Joris Chamblain, Aurélie Neyret', '', '', NULL, NULL, 8, 16, 'middle', 'В новой истории Вишенка с мамой отправляются на берег моря в старинный Замок Тысячи тайн. В этом замке устраивают квесты для настоящих детективов! Вишенка сразу же берется за дело, ведь ее загадка звучит очень необычно: «Когда ведущий цирка устремится к Венере?» По ходу расследования девочка знакомится с симпатичными мальчиками-пиратами, раскрывает тайны замка и неожиданно узнает секрет своей подруги Аннабель Дежарден. Как все эти секреты сплетены между собой? Сможет ли мама Вишенки справиться с еще одним расследованием, ведь новая книга приближает нас к тайне их семьи?', 'In this fourth volume, Cerise and her mother head to the seaside to visit the mysterious Castle of a Thousand Secrets. The castle hosts immersive mystery quests for true sleuths, and Cerise dives straight into solving an enigmatic riddle about a circus ringmaster and Venus. Along the way, she meets friendly boy-pirates, uncovers the castle''s hidden history, and inches closer to understanding a heartfelt secret within her own family.', 'U novoj avanturi, Višnjica i njena majka odlaze na morsku obalu u drevni Dvorac hiljadu tajni. Tamo se organizuju uzbudljive detektivske potrage, a Višnjica odmah prihvata izazov sa neobičnom zagonetkom. Istražujući hodnike, upoznaje simpatične dječake-pirate, otkriva tajne dvorca i polako sklapa kockice važne tajne iz prošlosti sopstvene porodice.', 'Потрясающе красивый детективный комикс у моря: старинный замок, хитрые шифры и очень трогательная семейная история!', 'A breathtaking seaside mystery comic full of clever riddles, old castle secrets, and touching family discoveries.', 'Predivan morski detektivski strip prepun mudrih zagonetki, tajni starog dvorca i dirljivih porodičnih otkrića.', '/covers/DP-0442.webp', '#2c6475', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","friends","real"]', '["comics","detective","seaside","castle","family secrets"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневники-вишенки-от-первого-сн-443', 'DP-0443', 'Дневники Вишенки. От первого снега до Персеид. Том 5', 'Cici''s Journal: From First Snow to the Perseids (Vol. 5)', 'Višnjini dnevnici: Od prvog snijega do Perseida (Tom 5)', '', 'Joris Chamblain, Aurélie Neyret', 'Joris Chamblain, Aurélie Neyret', '', '', NULL, NULL, 8, 16, 'middle', 'Новая история серии раскроет тайну семьи самой Вишенки. Девочка долго шла к ней, помогая всем вокруг. Теперь пришло время погрузиться в свое прошлое — через переписку с мамой. Пятый том серии откроет нам и секрет самих дневников девочки — мы, наконец, поймем, почему она так не любит, когда взрослые что-то скрывают.', 'In this touching finale of the beloved series, Cici turns her detective skills inward to uncover the secrets of her own family. Through letters and heartfelt memories shared with her mother, Cici finally discovers why she has always kept diaries and why it hurts so much when grown-ups keep secrets. A tender, beautifully illustrated exploration of love, loss, and healing.', 'U dirljivoj završnici omiljenog serijala, Višnja napokon okreće svoju radoznalost ka sopstvenoj porodici. Kroz pisma i iskrene razgovore sa mamom, saznaće zašto je uopšte počela da piše dnevnike i zašto joj toliko teško pada kad odrasli skrivaju istinu. Topla i vizuelno raskošna priča o ljubavi, sjećanjima i iscjeljenju.', 'Запасайтесь пледом и платочками: в этой части Вишенка раскрывает самую главную и трогательную тайну — тайну собственной семьи.', 'Grab a cozy blanket and some tissues: in this volume, Cici solves the most personal mystery of all—the secret of her own family.', 'Pripremite toplo ćebe i maramice: u ovom dijelu Višnja otkriva najvažniju i najdirljiviju tajnu — tajnu sopstvene porodice.', '/covers/DP-0443.webp', '#3c5878', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real","friends"]', '["graphic novel","family secrets","growing up","emotions","mother-daughter"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневники-вишенки-том-6-новое-н-444', 'DP-0444', 'Дневники Вишенки. Том 6. Новое начало', 'The Secret Diaries of Cerise: Volume 6. A New Beginning', 'Višnjini dnevnici: Tom 6. Novi početak', '', 'Joris Chamblain, Aurélie Neyret', 'Žoris Šamblen, Oreli Nejre', '', '', NULL, NULL, 8, 16, 'middle', 'Долгожданное продолжение любимой серии про юную Вишенку, которая мечтает стать писателем. Вишенка отправляется в кругосветное путешествие вместе с мамой, маминым другом Стефаном и маленьким Валентином, сыном Стефана. Их ждет приключение длиною в целый год. Они объедут Европу, Южную Америку и Африку, понаблюдают за китами и северным сиянием, погуляют по марокканским улочкам и амазонскому лесу, обретут новых удивительных знакомых и встретят старых друзей. А главное — найдут ответы на вопросы о том, как залечить старые раны и можно ли обрести счастье тогда, когда этого совсем не ждешь.', 'The long-awaited continuation of the beloved graphic novel series about Cerise, an observant girl who dreams of becoming a writer. Cerise sets off on a year-long journey around the world with her mother, her mother''s partner Stefan, and little Valentin. Across Europe, South America, and Africa, they watch whales, marvel at the northern lights, wander the vibrant alleys of Morocco, and explore the Amazon rainforest. Along the way, Cerise learns how to mend old wounds and embrace happiness when it is least expected.', 'Dugo očekivani nastavak omiljenog strip serijala o pronicljivoj djevojčici Višnji koja sanja da postane spisateljica. Višnja kreće na put oko svijeta sa mamom, maminim prijateljem Stefanom i malim Valentinom. Tokom cjelogodišnjeg putovanja kroz Evropu, Južnu Ameriku i Afriku, posmatraće kitove i polarnu svjetlost, šetati marokanskim sokacima i amazonskom prašumom. Kroz ove avanture Višnja otkriva kako zacijeliti stare rane i pronaći istinsku sreću.', 'Собирайте чемоданы и приготовьте платочки: Вишенка отправляется в кругосветку, чтобы залечить душевные раны и открыть сердце новому счастью!', 'Pack your bags and keep some tissues handy: Cerise takes us on a breathtaking round-the-world journey to heal old wounds and welcome new beginnings!', 'Spakujte kofere i pripremite maramice: Višnja nas vodi na nezaboravan put oko svijeta koji liječi srce i donosi novi početak!', '/covers/DP-0444.webp', '#3f7a8c', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","friends","real"]', '["графический роман","кругосветное путешествие","взросление","семья","дневник"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('евгений-онегин-графический-пут-445', 'DP-0445', 'Евгений Онегин. Графический путеводитель', 'Eugene Onegin: A Graphic Guide', 'Evgenije Onjegin: Grafički vodič', 'Алексей Олейников', 'Alexey Oleynikov', 'Aleksej Olejnikov', 'Наталья Яскина', 'Самокат', NULL, NULL, 8, 16, 'middle', 'Перед вами графический путеводитель по роману «Евгений Онегин» Александра Пушкина. Его написал писатель Алексей Олейников, а нарисовала художница Наташа Яскина. Для чего нужна эта книга? Чтобы помочь понять мир великого романа Пушкина. Чтобы снять страх и острое неприятие, которые так часто возникают у подростка, когда он сталкивается с русской классической литературой. В путеводителе в формате комикса сжато передаётся сюжетная линия романа и подробно разъясняются «тёмные» места текста ― детали и подробности далекой от нас жизни аристократической России времён Александра I.', 'Here is a graphic guide to Alexander Pushkin''s novel in verse, ''Eugene Onegin'', written by Alexey Oleynikov and illustrated by Natasha Yaskina. This book helps readers explore Pushkin''s world without intimidation, translating the classic story into a vivid graphic format while decoding the etiquette, duels, fashion, and social realities of 19th-century aristocratic Russia.', 'Pred vama je grafički vodič kroz čuveni roman Aleksandra Puškina „Evgenije Onjegin“, koji je napisao Aleksej Olejnikov, a ilustrovala Nataša Jaskina. Ova knjiga pomaže mladima da bez straha zarone u ruski klasik: u formi stripa sažeto prenosi radnju i objašnjava detalje svakodnevnog života, mode i dvoboja aristokratske Rusije 19. vijeka.', 'Классика без духоты и страха: остроумный путеводитель по роману Пушкина, где балы, дуэли и тайные смыслы разложены по полочкам и нарисованы с блестящим вкусом!', 'Classic literature without the dread: a vibrant graphic guide where Pushkin''s balls, duels, and 19th-century quirks are brilliantly decoded!', 'Klasik bez dosade i straha: slikoviti vodič u formi stripa koji duhovito otkriva sve tajne Puškinovog remek-djela!', '/covers/DP-0445.webp', '#2b4c59', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real","adventure"]', '["comics","classic literature","history","pushkin","illustrated"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('горе-от-ума-графический-путево-446', 'DP-0446', 'Горе от ума. Графический путеводитель', 'Woe from Wit: A Graphic Guide', 'Nevolja zbog pameti: Grafički vodič', 'Алексей Олейников', 'Alexei Oleynikov', 'Aleksej Olejnikov', 'Наталья Яскина', 'Самокат', NULL, NULL, 8, 16, 'middle', '«Горе от ума» — бессмертная комедия Александра Грибоедова. Вершина классицистической драматургии, которая также сочетает в себе элементы романтизма и сентиментализма, эта пьеса мгновенно разошлась по спискам, но впервые была полностью поставлена спустя шесть лет. Уже заскучали? Тогда почитайте эту книгу! Потому что она: не пьеса в стихах, а пьеса в стихах и комиксах (что есть дьявольская разница); проясняет тонкости и нюансы ушедшей культуры — например, почему пьесу считали скандальной (как молодой человек мог пробыть у девушки в комнате до утра?!); рассказывает о жизни, быте и нравах высшего московского общества XIX века (как выходили замуж, учили девиц, гуляли в Москве два века назад); показывает структуру пьесы, её тайные пружины (например, поговорим о глухоте и безумии, о сплетнях и тайной женской власти); переоткрывает классический текст — и он оказывается невероятно современным именно сейчас, когда так важно ясно видеть правду и не бояться ее говорить.', 'Alexander Griboyedov''s masterpiece ''Woe from Wit'' gets a fresh, dynamic makeover! Part comic book, part historical detective guide, this volume breaks down 19th-century Moscow high society, scandalous gossip, secret codes, and unwritten rules, revealing why speaking truth to power remains timeless.', 'Remek-djelo Aleksandra Gribojedova „Nevolja zbog pameti“ dobija novo, dinamično ruho! Dio strip, dio istorijski detektivski vodič, ova knjiga dešifruje visoko društvo Moskve 19. vijeka, tračeve, tajne kodove i nepisana pravila, pokazujući zašto je govorenje istine uvijek aktuelno.', 'Думали, школьная классика — это скучно? Этот остроумный графический гид докажет, что московские сплетни XIX века покруче любого современного сериала!', 'Thought 19th-century school classics were a snooze? This witty graphic guide proves historical high-society gossip beats any modern teen drama!', 'Mislili ste da su školski klasici dosadni? Ovaj duhoviti grafički vodič dokazuje da su tračevi moskovskog visokog društva uzbudljiviji od bilo koje serije!', '/covers/DP-0446.webp', '#d89c38', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["funny","real"]', '["comics","graphic novel","classics","history","satire"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-принц-447', 'DP-0447', 'Маленький принц', 'The Little Prince (Graphic Novel)', 'Mali princ (Grafički roman)', 'Экзюпери', 'Antoine de Saint-Exupéry, Joann Sfar', 'Antoan de Sent Egziperi, Žoan Sfar', 'Жоан Сфар', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Удивительная, нежная, грустная и умная сказка!.. Вы полюбите «Маленького принца» с первых страниц и навсегда. Ольга Лаврентьева, автор комиксов «Сурвило» и «ШУВ» Если вы давно не перечитывали Экзюпери — смело берите этот комикс. Это отличный повод вернуться к сентиментальной философии французского лётчика. ComicsBoom!', 'A tender, timeless, and poetic masterpiece reimagined in vibrant graphic novel form. Joann Sfar''s stunning visual interpretation breathes fresh life into Saint-Exupéry’s beloved tale of an aviator, a golden-haired boy from Asteroid B-612, and the essential things that remain invisible to the eye.', 'Nježna, vanvremenska i poetična priča pretočena u očaravajući grafički roman. Ilustrator Žoan Sfar udahnjuje novi život voljenom remek-djelu Sent Egziperija o pilotu, zlatokosom dječaku sa asteroida B-612 i istinama koje se samo srcem dobro vide.', 'Знакомая до слёз философская сказка в нежнейшем комикс-формате — лучший повод приручить своего Лиса заново.', 'The classic philosophical tale reborn as a breathtaking graphic novel — the perfect excuse to tame your Fox all over again.', 'Predivna filozofska bajka u ruhu grafičkog romana — savršen povod da ponovo pripitomite svoju Lisicu.', '/covers/DP-0447.webp', '#2b5c8f', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["magic","friends","adventure"]', '["graphic novel","classics","friendship","philosophy","stars"]', 1792836322696, 1792845640936);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-гамаюн-448', 'DP-0448', 'Сказки Гамаюн', 'Gamayun Tales', 'Bajke ptice Gamajun', 'Александр Уткин', 'Alexander Utkin', 'Aleksandar Utkin', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', '«Сказки Гамаюн» — новый взгляд на знакомые с детства русские народные сказки. Благодаря мастерству Александра Уткина их сюжеты переплетаются друг с другом, образуя единую волшебную вселенную, и раскрываются с неожиданных сторон. Магические испытания, встречи с мифическими существами, смертельные опасности и захватывающие приключения — книга не даст заскучать ни на минуту! Во второй книге серии волшебная птица Гамаюн поведает историю о Василисе, Бабе-яге и негасимом огне, а также расскажет о невероятных приключениях Царевны-воительницы и Ивана-царевича, судьбы которых сплелись благодаря золотым яблокам.', 'A breathtaking graphic novel reimagining of traditional Slavic folklore. Alexander Utkin weaves familiar legends into an interconnected mythical universe full of magical trials and perilous quests. In this volume, the prophetic bird Gamayun tells the stories of Vasilisa confronting Baba Yaga, and the daring adventures of the Warrior Princess and Ivan Tsarevich, brought together by golden apples.', 'Očaravajući grafički roman koji donosi nov i moderan pogled na tradicionalne slovenske bajke. Kroz majstorsko pripovijedanje Aleksandra Utkina, poznati zapleti se prepliću u jedinstven magični univerzum. Čarobna ptica Gamajun pripovijeda o Vasilisi i Babi Jagi, kao i o nevjerovatnim pustolovinama princeze-ratnice i Ivana-carevića.', 'Завораживающий фолк-комикс, в котором знакомые с детства сказки превращаются в эпический визуальный шедевр!', 'A visually stunning graphic folklore masterpiece where ancient tales transform into an epic, cinematic adventure!', 'Očaravajući strip u kojem se drevne slovenske bajke pretvaraju u pravu epsku avanturu!', '/covers/DP-0448.webp', '#244b6e', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["magic","adventure","spooky"]', '["comics","folklore","graphic novel","slavic mythology","fairy tales"]', 1792836322696, 1792845640937);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маус-449', 'DP-0449', 'Маус', 'Maus', 'Maus', 'Арт Шпигельман', 'Art Spiegelman', 'Art Špigelman', '', 'Corpus (АСТ)', 2013, '978-5-17-080250-0', 8, 16, 'middle', '', 'A monumental graphic novel depicting the harrowing realities of the Holocaust through the metaphor of mice and cats, capturing the true story of survival and the delicate relationship between father and son.', 'Izvanredan grafički roman koji kroz metaforu miševa i mačaka prikazuje potresne istine o Holokaustu, preživljavanju i složenom odnosu oca i sina.', 'Единственный в истории комикс, удостоенный Пулитцеровской премии — глубокий, честный и незабываемый рассказ о человечности и памяти.', 'The only graphic novel ever to win a Pulitzer Prize, this is a profoundly honest and unforgettable masterpiece about memory and survival.', 'Jedini grafički roman ovjenčan Pulicerovom nagradom — duboko, iskreno i nezaboravno djelo o sjećanju i preživljavanju.', '/covers/DP-0449.webp', '#2d2d2d', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real","animals"]', '["graphic novel","comics","history","biography","pulitzer"]', 1792836322696, 1792845640937);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('родина-450', 'DP-0450', 'Родина', 'Belonging: A German Reckons with History and Home', 'Domovina', 'Нора Круг', 'Nora Krug', 'Nora Krug', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Немецкая художница Нора Круг родилась спустя десятилетия после падения нацистского режима, но, несмотря на это, неразрывно связывала своё гражданство с Холокостом и его невыразимыми зверствами. Нора мало что знала об участии своей семьи во Второй мировой: хотя все её бабушки и дедушки пережили войну, они никогда не говорили о ней. Лишь спустя двадцать лет жизни за границей Нора осознала потребность задать вопросы, которые не осмеливалась озвучить ребёнком. Вернувшись в Германию и изучив архивы, семейные фотоальбомы и письма, она узнала истории Вилли, своего деда по материнской линии, которого принудили вступить в нацистскую партию, и Франца-Карла, брата её отца, добровольно вступившего в ряды СС и погибшего ещё подростком в Италии. В своём уникальном графическом эссе Нора стирает границы между комиксом, скрапбукингом и коллажем, пытаясь осмыслить одни из самых трагичных событий XX века, роль своей семьи в них и чувство стыда, которое продолжает передаваться из поколения в поколение немцев.', 'German illustrator Nora Krug grew up decades after the fall of the Nazi regime, yet felt an inescapable tie between her heritage and the horrors of the Holocaust. Knowing little about her family''s wartime past, she returns to Germany after twenty years abroad to uncover long-buried truths through archives, letters, and family albums. Blending graphic narrative, scrapbook collage, and memoir, this powerful visual essay explores generational guilt, memory, and what it truly means to belong.', 'Njemačka ilustratorka Nora Krug rođena je decenijama nakon pada nacističkog režima, ali je njemački identitet za nju ostao neraskidivo vezan za traumu Holokausta. Znajući vrlo malo o prošlosti svoje porodice tokom Drugog svjetskog rata, nakon dvadeset godina života u inostranstvu vraća se u Njemačku kako bi istražila arhive, pisma i stare albume. Kroz jedinstven spoj stripa, kolaža i memoara, ovo snažno grafičko djelo preispituje krivicu, sjećanje i hrabrost potrebnu za suočavanje sa sopstvenom istorijom.', 'Потрясающий и честный графический детектив по закоулкам семейной памяти, доказывающий, что прошлое нельзя замалчивать — его нужно бережно исследовать.', 'A breathtaking, honest graphic exploration of family memory that proves confronting history is the bravest way to understand who you are.', 'Dirljivo i iskreno grafičko putovanje kroz porodična sjećanja koje dokazuje da je suočavanje s prošlošću najhrabriji korak ka razumijevanju sebe.', '/covers/DP-0450.webp', '#4b5d43', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real"]', '["graphic novel","history","memoir","family","wwii"]', 1792836322696, 1792845640937);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('готовим-с-кафкой-451', 'DP-0451', 'Готовим с Кафкой', 'Baking with Kafka', 'Kuvamo s Kafkom', 'Том Голд', 'Tom Gauld', 'Tom Gold', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Том Голд — британский иллюстратор и автор комиксов. Он сотрудничает с изданиями The New Yorker, The New York Times, The Guardian, The Believer и New Scientist. «Готовим с Кафкой» — второй сборник комиксов, которые Том Голд пишет для газеты The Guardian. Смешивая литературу и поп-культуру, Голд дразнит читателя колкими шутками, которые заставляют окинуть критическим взглядом современный мир. В 2018 году книга получила премию имени Уилла Айснера в номинации «Лучший юмористический комикс».', 'Tom Gauld is a renowned British illustrator and cartoonist whose work regularly graces The New Yorker, The New York Times, and The Guardian. ''Baking with Kafka'' is his second celebrated collection of weekly cultural cartoons from The Guardian. Deftly blending classic literature, sci-fi tropes, and modern pop culture, Gauld delivers dry wit and sharp satire that playfully dissects our creative world. Winner of the 2018 Eisner Award for Best Humor Publication.', 'Tom Gold je britanski ilustrator i strip-autor koji sarađuje sa magazinima The New Yorker, The New York Times i The Guardian. „Kuvamo s Kafkom“ je njegova druga zbirka stripova kreiranih za The Guardian. Spajajući klasičnu književnost, naučnu fantastiku i savremenu pop-kulturu, Gold osvaja britkim humorom i ironičnim pogledom na moderni svijet. Knjiga je 2018. godine osvojila prestižnu nagradu „Vil Ajzner“ za najbolje humorističko strip-izdanje.', 'Идеальное книжное лакомство для остроумных читателей: тонкий британский юмор о писателях, технологиях и забавных нелепостях нашей жизни!', 'The ultimate treat for clever book lovers: razor-sharp British humor poking fun at classic literature, modern tech, and creative struggles!', 'Prava poslastica za male i velike ljubitelje knjiga: britki britanski humor o piscima, tehnologiji i slatkim mukama kreativnosti!', '/covers/DP-0451.webp', '#d16b53', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["funny","real"]', '["comics","humor","literature","satire","books"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мария-и-я-452', 'DP-0452', 'Мария и я', 'Maria and I', 'Marija i ja', '', 'Miguel Gallardo', 'Migel Galjardo', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Мария живёт на Канарских островах. У неё феноменальная память, заразительная улыбка, своеобразное чувство юмора и аутизм. В первой части книги Марии 12 лет, она отправляется с отцом на летние каникулы. Здесь воссозданы бытовые случаи, с которыми приходится сталкиваться сотням семей с ребёнком-аутистом из-за того, что окружающий мир плохо приспособлен для таких детей. Во второй части Марии исполняется 20 лет. Она и её отец по-прежнему проводят летние каникулы вместе, много смеются и составляют списки, однако в жизни повзрослевшей Марии многое изменилось. В 2009 году комикс «Мария и я» получил Национальную премию Правительства Каталонии, в 2010-м по нему был снят полнометражный документальный фильм, а в 2018-м в Театре юного зрителя города Хабаровска состоялась премьера спектакля-контакта, созданного по его мотивам.', 'Maria lives in the Canary Islands. She possesses a phenomenal memory, an infectious smile, a peculiar sense of humor, and autism. In the first part of the graphic memoir, 12-year-old Maria spends summer vacation with her father, revealing the everyday challenges families with autistic children face in a world ill-adapted to them. In the second part, Maria is twenty; she and her father still holiday together, laugh endlessly, and draw lists, navigating the bittersweet shifts of growing up.', 'Marija živi na Kanarskim ostrvima. Ima nevjerovatno pamćenje, zarazan osmijeh, jedinstven smisao za humor i autizam. U prvom dijelu stripa dvanaestogodišnja Marija odlazi na ljetovanje s ocem, otkrivajući svakodnevne izazove sa kojima se suočavaju porodice djece s autizmom u svijetu koji im nije prilagođen. U drugom dijelu Marija puni dvadeset godina; njih dvoje i dalje ljetuju zajedno, smiju se i crtaju spiskove, koračajući kroz novo poglavlje odrastanja.', 'Невероятно трогательный, честный и солнечный графический роман о безусловной отцовской любви и мире девочки с аутизмом.', 'A deeply touching, radiant, and honest graphic memoir celebrating unconditional father-daughter love and the unique world of an autistic girl.', 'Nevjerovatno dirljiv, iskren i sunčan grafički roman o bezuslovnoj očevoj ljubavi i svijetu viđenom Marijinim očima.', '/covers/DP-0452.webp', '#e05a47', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real","friends"]', '["graphic novel","autism","father and daughter","family","summer vacation"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('имущество-453', 'DP-0453', 'Имущество', 'The Property', 'Imovina', 'Руту Модан', 'Rutu Modan', 'Rutu Modan', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'После смерти сына Регина Сегал вместе с внучкой Микой из Тель-Авива летит в Варшаву, надеясь вернуть недвижимость, которая до Второй мировой войны принадлежала её родителям. Однако довольно скоро Мика начинает подозревать, что бабушка скрывает от неё истинную причину путешествия. В остроумном, многослойном романе Руту Модан размышляет о любовных узах, деньгах и семейных секретах. Графический роман «Имущество» отмечен премией имени Уилла Айснера (2014), номинировался на премию Игнаца и премию Международного фестиваля комиксов в Ангулеме, а также вошёл в топ-10 книг года таких крупнейших изданий, как The Guardian, Publishers Weekly, Salon и The Washington Post.', 'After her son''s death, Regina Segal travels from Tel Aviv to Warsaw with her granddaughter Mica, ostensibly to reclaim family real estate lost during World War II. But as they navigate modern Warsaw, Mica begins to suspect that her grandmother''s true motive has very little to do with property. In this witty, multi-layered graphic novel, Rutu Modan explores family secrets, memory, and love. Winner of the 2014 Will Eisner Comic Industry Award.', 'Nakon smrti svog sina, Regina Segal putuje iz Tel Aviva u Varšavu sa unukom Mikom, navodno kako bi povratila porodičnu imovinu izgubljenu tokom Drugog svjetskog rata. Međutim, Mika ubrzo počinje da sumnja da baka krije pravi razlog njihovog putovanja. U ovom duhovitom, višeslojnom grafičkom romanu, Rutu Modan istražuje porodične tajne, ljubav i sjećanje. Dobitnik prestižne nagrade Vil Ajzner za 2014. godinu.', 'Трогательный, ироничный и детективный графический роман о поездке в Варшаву, где за поисками старой квартиры прячется настоящая тайна бабушкиного сердца.', 'A tender, witty, and subtly suspenseful graphic novel where a quest for lost family property turns into an unforgettable excavation of the heart.', 'Dirljiv, duhovit i suptilno misteriozan grafički roman u kojem potraga za starim stanom postaje uzbudljivo otkrivanje bakinih tajni.', '/covers/DP-0453.webp', '#3d6470', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real","adventure"]', '["graphic novel","family secrets","warsaw","journey","history"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('корто-мальезе-баллада-сол-ного-454', 'DP-0454', 'Корто Мальезе: «Баллада солёного моря»', 'Corto Maltese: The Ballad of the Salty Sea', 'Korto Malteze: Balada o slanom moru', 'Уго Пратт', 'Hugo Pratt', 'Hugo Pratt', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', '1913 год, южная часть Тихого океана. Даже здесь, на другом конце света, надвигающаяся Первая мировая война грозит серьёзно изменить существующий расклад сил. Таинственный Монах, главарь могущественного пиратского синдиката, стремится извлечь из этого свою выгоду, в чём ему помогает опытный моряк Корто Мальтезе. Однако вскоре ситуация выходит из-под контроля, а грянувший глобальный конфликт окончательно путает карты… В 1976 году книга «Баллада солёного моря» получила премию в номинации «Лучшее произведение иностранного автора» на Международном фестивале комиксов в Ангулеме во Франции. Среди тысяч персонажей, созданных за более чем вековую историю комикса, лишь единицам удалось добиться статуса мифа, стать одной из визитных карточек девятого вида искусства. Корто Мальтезе — один из них. Искусный моряк, неисправимый романтик, пламенный революционер, стихийный философ, благородный пират, вечный искатель приключений был придуман в 1967 году итальянским автором Уго Праттом (1927–1995 гг.). Его похождения в лучших традициях Роберта Льюиса Стивенсона, Джозефа Конрада и Германа Мелвилла заставили мечтать не одно поколение читателей во всех уголках земного шара. Человек вне времени, настоящий гражданин мира, которому одинаково близки голубые лагуны южных морей и заснеженные просторы Сибири, переулки Гонконга и авениды Буэнос-Айреса… Ирландия и Бразилия, Самарканд и Венеция, Эквадор и Карибы, Базель и Занзибар — вот лишь некоторые этапы удивительной одиссеи капитана Корто. Серия книг о Корто Мальтезе неоднократно получала премии в Италии, Франции, Бельгии и Германии. В 2005 году в США имя Уго Пратта было внесено в Зал славы Уилла Айснера.', 'Set on the eve of World War I across the sweeping expanse of the South Pacific, this legendary graphic masterpiece follows the enigmatic sailor of fortune, Corto Maltese. Caught amidst competing imperial navies, ruthless pirate clans led by the mysterious Monk, and native uprisings, Corto navigates shifting loyalties and the boundless ocean. A poetic, atmospheric epic celebrated as a monumental milestone in European comics storytelling.', 'Smještena u osvit Prvog svjetskog rata na prostranstvima Južnog Pacifika, ova legendarna grafička novela prati zagonetnog mornara i pustolova, Korta Maltezea. Zatečen između sukobljenih carskih mornarica, nemilosrdnih pirata pod vođstvom tajanstvenog Monaha i pobuna lokalnih plemena, Korto vješto krmari kroz burne saveze i beskrajni okean. Pravo remek-djelo devete umjetnosti, puno morske soli, romantike i melanholije.', 'Легендарный шедевр графического романа о благородном бунтаре, пиратах и соленом ветре свободы Тихого океана.', 'Set sail with the coolest, most poetic rogue of the high seas in this timeless graphic novel classic.', 'Zaplovite sa najpoznatijim i najromantičnijim lutalicom svjetskog stripa kroz uzburkane vode Južnog mora.', '/covers/DP-0454.webp', '#204060', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","real"]', '["comics","pirates","sea","history","classics","pacific"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('корто-мальезе-сибирь-455', 'DP-0455', 'Корто Мальезе: Сибирь', 'Corto Maltese in Siberia', 'Korto Malteze: Sibir', 'Уго Пратт', 'Hugo Pratt', 'Hugo Pratt', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', '1919 год. В Европе война окончена, но в Сибири она продолжается. Адмирал Колчак только что провозгласил себя Верховным правителем России, а барон фон Унгерн-Штернберг готовится основать великую азиатскую империю. По бескрайним просторам снуют бронепоезда, на одном из которых, по слухам, перевозят царское золото… За ним охотятся китайские военные правители, маньчжурские банды, союзники и многочисленные тайные общества. Впрочем, у Корто Мальтезе и его вечного спутника, капитана Распутина, на этот счёт свои планы… Среди тысяч персонажей, созданных за более чем вековую историю комикса, лишь единицам удалось добиться статуса мифа, стать одной из визитных карточек девятого вида искусства. Корто Мальтезе — один из них. Искусный моряк, неисправимый романтик, пламенный революционер, стихийный философ, благородный пират, вечный искатель приключений был придуман в 1967 году итальянским автором Уго Праттом (1927–1995 гг.). Его похождения в лучших традициях Роберта Льюиса Стивенсона, Джозефа Конрада и Германа Мелвилла заставили мечтать не одно поколение читателей во всех уголках земного шара. Человек вне времени, настоящий гражданин мира, которому одинаково близки голубые лагуны южных морей и заснеженные просторы Сибири, переулки Гонконга и авениды Буэнос-Айреса… Ирландия и Бразилия, Самарканд и Венеция, Эквадор и Карибы, Базель и Занзибар — вот лишь некоторые этапы удивительной одиссеи капитана Корто. Серия книг о Корто Мальтезе неоднократно получала премии в Италии, Франции, Бельгии и Германии. В 2005 году в США имя Уго Пратта было внесено в Зал славы Уилла Айснера.', 'It is 1919. While the war in Europe is over, turmoil grips Siberia. Armored trains thunder across the frozen steppes, carrying rumors of the Tsar''s lost imperial gold. Chinese warlords, Manchurian bandits, secret societies, and foreign armies are all on the hunt—but Corto Maltese and his unpredictable companion Rasputin have plans of their own. A timeless graphic novel masterpiece by Hugo Pratt that blends romantic high adventure, rich history, and poetic mystery.', 'Godina je 1919. Rat u Evropi je završen, ali u Sibiru i dalje bukti. Oklopni vozovi jure kroz sniježna prostranstva, a priča se da jedan od njih prevozi nestalo carsko zlato. Za blagom tragaju kineski vojni gospodari, mandžurske bande i tajna društva, no Korto Malteze i njegov nepredvidivi saputnik Raspućin imaju sopstvene planove. Bezvremenski grafički roman Iga Prata donosi epsku istorijsku avanturu punu tajni, romantike i opasnosti.', 'Запрыгивайте на подножку легендарного бронепоезда — вас ждёт романтика бескрайних снегов, погоня за царским золотом и непревзойдённый Корто Мальтезе!', 'Hop aboard the legendary armored train for an unforgettable ride through the snowy steppes with the ultimate romantic adventurer, Corto Maltese!', 'Uskočite u legendarni oklopni voz i zaputite se kroz sibirski snijeg u nezaboravnu potjeru za carskim zlatom sa nepokolebljivim Kortom Maltezeom!', '/covers/DP-0455.webp', '#2c4a6f', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","real"]', '["comics","graphic novel","adventure","history","trains"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('наобортия-456', 'DP-0456', 'Наобортия', 'Backwardland', 'Zemlja naopačke', 'Хенинг Вагенбрет', 'Henning Wagenbreth', 'Hening Vagenbret', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Хотелось ли вам повернуть время вспять, чтобы изменить решение, поступок или сказанные слова? Немецкий художник Хеннинг Вагенбрет даёт вам такой шанс и приглашает в Наоборотию! В этой стране всё идёт… наоборот: тонущие корабли как по волшебству выскакивают из волн и невредимыми возвращаются домой, футбольные матчи и шахматные турниры неизменно завершаются ничьей, а газеты пишут о том, что произойдёт только завтра. Не чудо ли? Вооружившись меткими стихами и красочными иллюстрациями, Хеннинг Вагенбрет переворачивает логику повседневной жизни и позволяет вдоволь насладиться абсурдной, но такой желанной реальностью.', 'Have you ever wished you could turn back time to undo a mistake or unsay hasty words? German artist Henning Wagenbreth invites you to Backwardland, where everything unfolds in reverse! Sinking ships leap gracefully out of turbulent waves to sail safely home, every match ends in a peaceful draw, and newspapers report tomorrow''s news today. Packed with witty rhymes and striking graphic illustrations, this book turns everyday logic upside down in a delightfully absurd adventure.', 'Jeste li ikada poželjeli da vratite vrijeme unazad i promijenite odluku ili izrečene riječi? Njemački ilustrator Hening Vagenbret vodi vas u Zemlju naopačke, gdje sve teče u rikverc! Potopljeni brodovi čudesno iskaču iz talasa i sigurni se vraćaju kući, svaka utakmica se završava neriješeno, a novine pišu o onome što će se tek sjutra dogoditi. Uz duhovite stihove i upečatljive ilustracije, ova knjiga izvrće logiku naglavačke.', 'Приготовьтесь читать задом наперёд и хохотать от души: в этом графическом шедевре время послушно течёт вспять!', 'Get ready to rewind reality and laugh out loud: in this bold graphic masterpiece, time cheerfully marches backwards!', 'Spremite se da premotate stvarnost unazad i nasmijete se do suza: u ovom grafičkom remek-djelu vrijeme teče u rikverc!', '/covers/DP-0456.webp', '#e64a19', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["funny","magic"]', '["graphic novel","reverse time","absurdism","poetry","quirky art"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ульф-457', 'DP-0457', 'Ульф', 'Ulf', 'Ulf', 'Таня Эш', 'Tanja Esch', 'Tanja Eš', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Ульф, Тита, Хайко и Отто — одноклассники, лучшие друзья и отважные детективы, которые могут отыскать любого преступника! Вернее, им того хотелось бы. Вот только вокруг не происходит ничего интересного… пока однажды в класс не приходит новенькая. Ведёт себя она очень подозрительно: странно одевается, ничего не ест, показывает невероятные эквилибристические трюки, в огромных количествах покупает фольгу и пластиковые крышечки. А что если она инопланетянка? Докопаться до правды под силу только юным детективам! Немецкая художница Таня Эш приглашает читателей в увлекательное приключение, объединяющее в себе тайны, опасности, юмор и настоящую дружбу.', 'Ulf, Tita, Heiko, and Otto are classmates, best friends, and daring detectives ready to crack any case—or so they wish. Nothing exciting ever happens around them until a new girl joins their class. She acts extremely suspiciously: wears bizarre clothes, never eats, performs impossible acrobatic stunts, and buys mountains of aluminum foil and bottle caps. Could she be an alien? It''s up to the junior sleuths to uncover the hilarious truth in this vibrant graphic novel.', 'Ulf, Tita, Hajko i Oto su školski drugari, najbolji prijatelji i neustrašivi detektivi spremni da riješe svaki misteriozni slučaj—ili bi barem to voljeli. Ništa se uzbudljivo ne dešava dok se u razredu ne pojavi nova učenica. Ona se ponaša izuzetno sumnjivo: čudno se oblači, nikad ništa ne jede, izvodi nevjerovatne akrobacije i kupuje brda folije i plastičnih čepova. Da nije možda vanzemaljac? Vrijeme je da mladi detektivi istraže slučaj!', 'Готовьте лупы и шапочки из фольги: наши юные сыщики берутся за расследование дела новенькой, которая слишком уж похожа на пришельца!', 'Grab your magnifying glasses and tinfoil hats: these junior sleuths are on the case of a new classmate who is suspiciously like an alien!', 'Pripremite lupe i kape od aluminijumske folije: mladi detektivi kreću u istragu nove učenice koja previše liči na vanzemaljca!', '/covers/DP-0457.webp', '#e28a2b', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["funny","adventure","friends"]', '["graphic novel","detective","aliens","school","friendship"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('леонард-коэн-458', 'DP-0458', 'Леонард Коэн', 'Leonard Cohen: On a Wire', 'Leonard Koen: Na žici', 'Филипп Жирар', 'Philippe Girard', 'Filip Žirar', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', '«Леонард Коэн. На проводе» — графическая биография одного из величайших поющих поэтов XX столетия, глубокий и чувственный голос которого узнаваем из тысячи. Канадский художник Филипп Жирар отдаёт дань уважения этому легендарному певцу любви и смерти и приглашает читателя вместе с Коэном пережить самые важные события в жизни музыканта: отказ от семейного бизнеса и выбор пути поэта, запись первого альбома в тридцатилетнем возрасте, потеря прав на песню Suzanne и рост популярности каверов на Hallelujah, судьбоносные встречи с Дженис Джоплин, Лу Ридом, Филом Спектором, обманы недобросовестных агентов, почти полное разорение и внезапный взлёт карьеры в семидесятилетнем возрасте.', 'Leonard Cohen: On a Wire is a graphic biography of one of the 20th century’s most iconic singer-songwriters, whose deep, velvety voice is instantly recognizable. Canadian artist Philippe Girard pays homage to this legendary bard of love and longing, inviting readers to follow Cohen through the turning points of his life: walking away from the family business for poetry, recording his first album at thirty, the loss of rights to ''Suzanne'', the rise of ''Hallelujah'', fateful encounters with Janis Joplin and Lou Reed, financial ruin, and an astounding late-career resurgence in his seventies.', '„Leonard Koen: Na žici“ je grafička biografija jednog od najvećih kantautora 20. vijeka, čiji je dubok i osjećajan glas prepoznatljiv širom svijeta. Kanadski autor Filip Žirar odaje počast ovom legendarnom pjesniku ljubavi i melanholije, vodeći čitaoca kroz ključne trenutke njegovog života: odustajanje od porodičnog biznisa zarad poezije, snimanje prvog albuma u tridesetim, gubitak prava na pjesmu „Suzanne“, planetarni uspjeh pjesme „Hallelujah“, sudbonosne susrete sa Dženis Džoplin i Lu Ridom, te nevjerovatan trijumfalni povratak na scenu u sedamdesetim godinama.', 'Вдохновляющая графическая ода великому поэту и музыканту, доказывающая, что никогда не поздно петь своим голосом и заново покорять мир.', 'An inspiring graphic tribute to a legendary bard, proving that it is never too late to find your voice and captivate the world.', 'Inspirativna grafička priča o legendarnom pjesniku i muzičaru koja dokazuje da nikada nije kasno pronaći svoj glas i osvojiti svijet.', '/covers/DP-0458.webp', '#273238', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real"]', '["graphic novel","biography","music","poetry","creativity"]', 1792836322696, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('голод-459', 'DP-0459', 'Голод', 'Hunger', 'Glad', 'Кнут Гамсун', 'Knut Hamsun, Martin Ernstsen', 'Knut Hamsun, Martin Ernstsen', '', 'Городец', NULL, NULL, 8, 16, 'middle', 'Роман Кнута Гамсуна "Голод" и сегодня, спустя 130 лет после его первой публикации, продолжает привлекать новых читателей. Норвежский художник Мартин Эрнстсен переосмысливает произведение в формате комикса, еще полнее раскрывая его психологическую глубину и подчеркивая средствами графики отчаянную и безнадежную борьбу героя за жизнь. Оригинальная трактовка знаменитого романа позволит по-новому взглянуть на историю молодого писателя, страдающего от голода и безденежья в Кристиании - "удивительном городе, который не отпускает никого, покуда не оставит на нем своих отметин". Графический роман Мартина Эрнстсена удостоился ряда престижных литературных премий: премии Браги в номинации "Иллюстрированные книги для детей и взрослых" в 2019 году, читательской премии "Ordknappen" и двух премий "Grafill" в номинациях "Лучший комикс года" и "Лучшая литературная адаптация года" в 2020 году. По мнению жюри конкурса, автору комикса удалось в этом достаточно амбициозном проекте достичь высочайшего результата. Визуальное повествование погружает читателя в богатый и разнообразный мир романа: от подробных изображений городской среды 1880-х годов до красочных видений, лихорадочных фантазий главного героя, наполненных оригинальными метафорами. На русском языке публикуется впервые.', 'Over 130 years after its original publication, Knut Hamsun''s masterpiece ''Hunger'' finds new life in this multi-award-winning graphic novel adaptation by Norwegian artist Martin Ernstsen. Through striking visual storytelling, the comic deepens the psychological journey of a destitute young writer struggling to survive in 1880s Kristiania. From vivid historical streetscapes to intense, feverish hallucinatory visions, Ernstsen''s expressive artwork captures the desperate and haunting battle for dignity and life.', 'Više od 130 godina nakon objavljivanja, remek-djelo Knuta Hamsuna „Glad“ oživljava u nagrađivanoj adaptaciji norveškog umjetnika Martina Ernstsena u formi grafičkog romana. Kroz upečatljiv vizuelni jezik, strip produbljuje psihološku dramu mladog pisca koji se bori za opstanak u Kristijaniji s kraja 19. vijeka. Od detaljnih gradskih pejzaža do grozničavih, maštovitih vizija, ova adaptacija na izuzetan način prenosi unutrašnju borbu glavnog junaka za dostojanstvo i život.', 'Пронзительная классика в формате графического романа, где голод, гордость и творческая лихорадка оживают в каждом выразительном штрихе.', 'A gripping graphic novel adaptation of a literary classic, where hunger, pride, and feverish dreams leap right off the page.', 'Upečatljiva adaptacija književnog klasika u formi grafičkog romana, gdje se ponos, glad i stvaralačka groznica osjećaju u svakom crtežu.', '/covers/DP-0459.webp', '#b85d19', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["real"]', '["graphic novel","classics","adaptation","norwegian literature","art"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('викинги-истории-в-комиксах-460', 'DP-0460', 'Викинги. Истории в комиксах', 'The Histronauts: A Viking Adventure', 'Vikinzi: Priče u stripu', 'Френсис Дюркин, Грейс Кук', 'Frances Durkin, Grace Cooke', 'Fransis Derkin, Grejs Kuk', '', 'Эксмо', NULL, NULL, 8, 16, 'middle', 'Юные историонавты совершат прыжок во времени и окажутся в эпохе викингов, им понадобится твоя помощь, чтобы разгадать все тайны прошлого. Это будет захватывающие путешествие, ведь ты будешь расшифровывать руны, строить красивые корабли и узнаешь всё о набегах викингов. Эта книга - увлекательнейшая смесь комиксов, фактов и игр.', 'Young histronauts leap back in time to the Viking Age, and they need your help to uncover the secrets of the past! Crack ancient runes, explore magnificent longships, and learn the truth about Viking raids in this engaging mix of comic strip adventures, historical facts, and interactive challenges.', 'Mladi historonauti skaču kroz vrijeme pravo u doba Vikinga, a potrebna im je tvoja pomoć da razotkriju sve tajne prošlosti. Dešifruj rune, istraži brze vikinške drakare i saznaj sve o njihovim pohodima u ovoj uzbudljivoj mješavini stripa, istorijskih činjenica i zabavnih igara!', 'Запрыгивай на борт драккара — комиксы, рунические загадки и суровые викинги сделают из тебя настоящего знатока северной истории!', 'Hop aboard a longship—vibrant comics, runic puzzles, and legendary Norsemen will turn any curious reader into a true Viking history buff!', 'Uskoči na vikinški drakar — uzbudljivi stripovi, zagonetne rune i neustrašivi moreplovci pretvoriće te u pravog stručnjaka za istoriju!', '/covers/DP-0460.webp', '#1f6f8b', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","real"]', '["vikings","history","comics","time travel","interactive"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('древняя-греция-истории-в-еомик-461', 'DP-0461', 'Древняя Греция. Истории в еомиксах', 'The Histronauts: An Ancient Greek Adventure', 'Drevna Grčka: Strip avantura', 'Френсис Дюркин, Грейс Кук', 'Frances Durkin, Grace Cooke', 'Frensis Darkin, Grejs Kuk', '', 'Эксмо', NULL, NULL, 8, 16, 'middle', 'На сей раз Историонавты отправляются в Древнюю Грецию! И без твоей помощи им не вернуться домой! Побывай вместе с ребятами в древнегреческом театре, прогуляйся по древним Афинам и узнай о том, как проходили Олимпийские игры тысячи лет назад! По пути тебя ждут замечательные поделки, весёлые игры и увлекательные головоломки. Помоги Историонавтам найти путь назад, в наше время. Приключения начинаются!', 'Join the Histronauts on an exciting time-travel journey to Ancient Greece! Wander the bustling streets of Athens, take a seat in an amphitheatre, and uncover how the original Olympic Games were celebrated thousands of years ago. Packed with comic strips, engaging crafts, and brain-teasing puzzles, this adventure invites young readers to help the team navigate history and find their way back home.', 'Pridruži se Istoronautima na uzbudljivom putovanju kroz vrijeme u Drevnu Grčku! Prošetaj živopisnim ulicama drevne Atine, zaviri u antičko pozorište i otkrij kako su izgledale prve Olimpijske igre prije više hiljada godina. Uz pregršt duhovitih stripova, kreativnih zadataka i mozgalica, pomozi našim junacima da uspješno pronađu put nazad u sadašnjost.', 'Хватай сандалии и оливковую ветвь — Историонавты зовут исследовать Афины через весёлые комиксы и хитрые головоломки!', 'Strap on your sandals and grab an olive branch — the Histronauts need your sharp puzzle skills to navigate Ancient Greece!', 'Obuj sandale i spremi se za akciju — Istoronautima treba tvoja pomoć da riješe zagonetke i istraže Drevnu Grčku!', '/covers/DP-0461.webp', '#e28743', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","real"]', '["ancient greece","history","comics","puzzles","olympics"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('древний-египет-истории-в-комик-462', 'DP-0462', 'Древний Египет. Истории в комиксах', 'Ancient Egypt: History in Comics', 'Drevni Egipat: Istorija u stripu', 'Френсис Дюркин, Грейс Кук', 'Frances Durkin, Grace Cooke', 'Frances Durkin, Grace Cooke', '', 'Эксмо', NULL, NULL, 8, 16, 'middle', 'Отправляйся с юными исследователями в Древний Египет! Тебя ждет захватывающие путешествие - исследование богатых гробниц, расшифровка иероглифов, изучение искусства мумификации и еще множество всего! Эта книга - увлекательнейшая смесь комиксов, фактов и игр', 'Set off with young time-traveling explorers to Ancient Egypt! An exciting journey awaits you: discovering rich pharaoh tombs, deciphering hieroglyphs, unraveling the art of mummification, and much more. This book is a delightful mix of engaging comics, fun historical facts, and brain-teasing puzzles.', 'Kreni sa mladim istraživačima kroz vrijeme pravo u Drevni Egipat! Očekuje te uzbudljivo putovanje — istraživanje raskošnih grobnica, dešifrovanje hijeroglifa, otkrivanje tajni mumifikacije i još mnogo toga. Ova knjiga je sjajan spoj stripa, istorijskih činjenica i zanimljivih igara.', 'Путешествие во времени, расшифровка иероглифов и тайны гробниц — история Древнего Египта еще никогда не была такой наглядной и увлекательной!', 'Secret hieroglyphs, tomb mysteries, and interactive puzzles — learning Ancient Egyptian history has never been this playful and graphic!', 'Putovanje kroz vrijeme, hijeroglifi i tajne faraona — istorija Drevnog Egipta nikada nije bila ovako zabavna i slikovita!', '/covers/DP-0462.webp', '#d69837', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","real"]', '["comics","ancient egypt","history","archaeology","puzzles"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рататуй-463', 'DP-0463', 'Рататуй', 'Ratatouille: The Graphic Novel', 'Ratatuj', 'комикс', 'Didier Le Bornec', 'Didije Le Bornek', '', 'Эксмо', NULL, NULL, 8, 16, 'middle', 'Реми - очень необычный крыс. У него, без преувеличений, самый чуткий нос и изысканные кулинарные вкусы. А еще у Реми есть тайная заветная мечта - стать шеф-поваром, как великий Огюст Гюсто! По нелепой случайности Реми оказывается в своем любимом городе Париже - столице высокой кухни! Ему выпадает шанс показать свой кулинарный талант, но вот незадача - он родился крысой. Справится ли Реми со всеми трудностями, которые поджидают его на пути к мечте, и сможет ли доказать, что готовить может каждый? Адаптация сценария Дидье Ле Борнек. Для среднего школьного возраста.', 'Remy is no ordinary rat. He boasts an exquisitely sensitive nose and refined culinary tastes. Above all, Remy has a secret dream: to become a master chef just like the great Auguste Gusteau! By a twist of fate, Remy finds himself in his dream city—Paris, the capital of haute cuisine. He gets a chance to showcase his culinary brilliance, but there is one tiny catch: he''s a rat. Can Remy overcome every obstacle and prove to the world that anyone can cook?', 'Remi je sasvim neobičan pacov sa izuzetno istančanim čulom mirisa i prefinjenim kulinarskim ukusom. Njegov najveći tajni san je da postane vrhunski šef kuhinje, baš poput slavnog Ogista Gistoa! Igrom sudbine, Remi se nađe u Parizu, prijestonici visoke kuhinje. Pruža mu se prilika da pokaže nevjerovatan kulinarski talenat, ali postoji samo jedna prepreka — on je pacov. Može li Remi savladati sve izazove i dokazati da svako može da kuva?', 'Аппетитный комикс, доказывающий: чтобы стать великим шефом, важен не вид и не размер, а щепотка смелости и безграничная любовь к кулинарии!', 'A mouth-watering graphic novel proving that anyone can become a great chef with a dash of courage and a whole lot of heart!', 'Slasni strip koji dokazuje da za velikog kuvara nijesu važni vrsta ni veličina, već prstohvat hrabrosti i ogromna ljubav prema kuvanju!', '/covers/DP-0463.webp', '#c73824', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["animals","funny","friends"]', '["comics","cooking","paris","rats","dreams"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('роботы-научный-комикс-464', 'DP-0464', 'Роботы. Научный комикс', 'Science Comics: Robots and Drones', 'Roboti: Naučni strip', 'Мейргрид Скотт, Джейкоб Чабот', 'Mairghread Scott, Jacob Chabot', 'Mairgrid Skot, Džejkob Čabot', 'МИФ', 'Манн, Иванов и Фербер', 2024, '978-5-00169-350-5', 8, 16, 'middle', 'Роботы окружают нас везде — дома, в школе и на улице, в офисах и больницах, в небе и на земле. Они помогают человеку, но мало кто знает, как роботы устроены. Вместе с Пули, первой механической птицей, отправляйтесь в путешествие по истории робототехники — от подающих чай кукол в древней Японии до современных марсоходов. Вы узнаете, кто придумал первого робота, чем робот отличается от дрона, как устроены простые и сложные домашние помощники, как работает марсоход, как запрограммировать робота и многое другое. А главное, эта книга может стать вдохновением для нового поколения инженеров и программистов роботов!', 'Robots are all around us—at home, at school, in hospitals, and even on Mars! But how do these incredible machines actually work? Join Pouli, the world''s first mechanical pigeon, on a thrilling journey through robotics history—from ancient Japanese tea-serving automata to cutting-edge rovers and drones. Packed with humor and science, this graphic novel will inspire tomorrow''s engineers and programmers.', 'Roboti su svuda oko nas — kod kuće, u školi, u bolnicama, na nebu i na zemlji! Ali malo ko zna kako oni zapravo funkcionišu. Zajedno sa Pulijem, prvim mehaničkim golubom, krenite na uzbudljivo putovanje kroz istoriju robotike — od drevnih japanskih automata koji služe čaj do savremenih marsovskih rovera. Ovaj zabavni grafički roman inspiriše novu generaciju inženjera i programera.', 'Загляните под капот робототехники вместе с остроумным механическим голубем и вдохновитесь на создание собственного марсохода!', 'Take a peek under the hood of robotics with a witty mechanical bird leading the way through the history of engineering!', 'Zavirite pod haubu robotike uz duhovitog mehaničkog goluba i pronađite inspiraciju da stvorite sopstvenog robota!', '/covers/DP-0464.webp', '#2c7a9b', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["adventure","real"]', '["comics","stem","robots","technology","science","inventions"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жан-мишель-супергерой-любовь-с-465', 'DP-0465', 'Жан-Мишель супергерой. Любовь с первого взгляда', 'Jean-Michel the Superhero: Love at First Sight', 'Žan-Mišel superhero: Ljubav na prvi pogled', '', 'Magali Le Huche', 'Magali Le Uš', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Супергерой Жан-Мишель влюбился в прекрасную верблюдицу Жизель с первого взгляда. Отважный северный олень готов рассказать ей о своих чувствах, но признание в любви — сложная задача даже для супергероя. Каждый раз при виде Жизель с Жан-Мишелем происходит что-то странное: путаются буквы, забываются слова, подкашиваются ноги, ему хочется убежать и спрятаться. К счастью, у влюбленного супергероя есть друзья, которые всегда готовы прийти на помощь. У каждого из них свой рецепт успеха. Но чем ближе Жан-Мишель к своей цели, тем ему тревожней: ответит ли взаимностью прекрасная Жизель?', 'Superhero caribou Jean-Michel has fallen head over hooves for the lovely camel Gisèle at first sight! But confessing his feelings turns out to be much harder than saving the world: his knees tremble, his words get jumbled, and he just wants to hide. Luckily, his trusty animal friends are ready to step in with hilarious advice. Will their quirky recipes for romance help Jean-Michel win Gisèle''s heart?', 'Superhero irvas Žan-Mišel zaljubio se u prelijepu kamilu Žizel na prvi pogled! Ali izjaviti ljubav pokazuje se težim zadatkom od spasavanja svijeta: koljena mu klecaju, riječi se petljaju i najradije bi pobjegao i sakrio se. Na sreću, tu su prijatelji sa gomilom smiješnih savjeta za osvajanje srca. Hoće li Žan-Mišel uspjeti da smogne hrabrosti?', 'Оказывается, признаться в любви куда страшнее, чем победить злодея, но с верными друзьями супергерой справится даже с бабочками в животе!', 'Turns out confessing your crush is way scarier than fighting supervillains, but with loyal friends by your side, even a superhero can handle butterflies in the stomach!', 'Ispostavlja se da je izjaviti ljubav mnogo strašnije nego pobijediti zlikovca, ali uz prave prijatelje i superherojski irvas može da savlada tremu!', '/covers/DP-0465.webp', '#e2583e', 'comics', 'ru', 'available', 'Категория: Дневники Вишенки', '["funny","animals","friends"]', '["comics","superheroes","first love","friendship","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-витаем-в-облаках-466', 'DP-0466', 'Эмиль и Марго. Витаем в облаках', 'Emile and Margot: Head in the Clouds', 'Emil i Margo: S glavom u oblacima', 'Энн Дидье и Оливье Мэллер', 'Anne Didier and Olivier Muller', 'Anne Didier i Olivier Muller', '', '', NULL, NULL, 8, 16, 'middle', 'В замке, где живут Эмиль и Марго, всегда происходит что-нибудь невероятное. Все благодаря неугомонным монстрикам, с которыми точно никогда не соскучишься — они умеют превращать обычный день в фейерверк веселья и неожиданностей. Стоит им появиться — и вот уже скучный урок становится захватывающим путешествием по облачным замкам, наказание оборачивается отдыхом на солнечном пляже, а из школьного портфеля выглядывает любопытная мордочка Зайки-Знайки, готового к новым проделкам. Вместе с этими озорниками Эмиль и Марго успевают все на свете: устроить переполох в школе наоборот, где учебники взрываются разноцветным конфетти, победить коварную жаднянку щекоткой и смехом и даже провести экскурсию для крошечных монстриков... внутри пылесоса.', 'Life in a royal castle is never dull when you have mischievous little monsters as friends! Emile and Margot turn boring lessons into breathtaking journeys through cloud castles and transform strict punishments into sunny beach getaways. Together with their monster companions, they turn the school upside down with confetti explosions, defeat greed with tickles and laughter, and even embark on a tour inside a vacuum cleaner.', 'U kraljevskom dvorcu u kom žive Emil i Margo nikada nije dosadno, a sve zahvaljujući nestašnim čudovištancima! Sa njima se dosadna nastava pretvara u čudesno putovanje kroz oblake, a kazna u sunčani odmor na plaži. Pridružite se princu i princezi dok okreću školu naopačke, pobjeđuju pohlepu golicanjem i smijehom i vode male monstrume u nezaboravnu ekspediciju kroz usisivač.', 'Лучшее лекарство от скуки и строгих гувернанток — озорные монстры в кармане и пара билетов в облачные замки!', 'The ultimate antidote to boring homework and strict tutors: a pocketful of playful monsters ready to fly into the clouds!', 'Najbolji lijek protiv dosade i strogih guvernanti: džepna čudovištanca spremna za let među oblake!', '/covers/DP-0466.webp', '#63a4d8', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","royalty","humor","fantasy"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-монстрам-вход-за-467', 'DP-0467', 'Эмиль и Марго. Монстрам вход запрещен!', 'Emil and Margot: Monsters Strictly Forbidden!', 'Emil i Margo: Ulaz čudovištima zabranjen!', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Тяжело быть принцем и принцессой. Приходится учиться этикету, выполнять скучные задания гувернантки, мадам Дисциплинды, и успевать ходить в школу. Но как же здорово, что рядом всегда есть монстры, готовые прийти на помощь и устроить незабываемое веселье! Эмиля и Марго ждут потрясающие приключения: они устроят охоту на ночные кошмары, сорвут урок садоводства, отправятся на экскурсию за зеркальную раму и сделают многое-многое другое. Главное, не попасться гувернантке: она терпеть не может монстров. В замок им вход запрещен!', 'Being a royal prince and princess isn''t all fun and games—there is strict etiquette to study and dreary chores from Madame Diciplinda. Luckily, Emil and Margot have a secret: an army of friendly, eccentric monsters always ready to help turn everyday boredom into hilarious chaos. From hunting bad dreams to exploring worlds behind mirror frames, their castle life is anything but dull, as long as the governess doesn''t catch on!', 'Nije nimalo lako biti princ i princeza: bonton, dosadni zadaci stroge guvernante i svakodnevna škola. Srećom, u blizini su uvijek nestašna čudovišta spremna za nezaboravnu zabavu! Emil i Margo kreću u lov na noćne more, prave pometnju na času baštovanstva i istražuju tajne iza ogledala. Najvažnije je da ih guvernanta ne primijeti, jer u dvorcu je čudovištima ulaz strogo zabranjen!', 'Скучные уроки этикета отменяются, когда в королевский замок тайком пробираются самые забавные и безобидные чудища!', 'Stuffy royal etiquette lessons are promptly cancelled whenever the goofiest monsters in the kingdom sneak into the castle!', 'Dosadni časovi kraljevskog bontona se smjesta otkazuju čim se u dvorac ušunjaju najsmješnija čudovišta na svijetu!', '/covers/DP-0467.webp', '#2da5af', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","prince and princess","castle","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-чудовищные-глупо-468', 'DP-0468', 'Эмиль и Марго. Чудовищные глупости', 'Emile and Margot: Monstrous Silliness', 'Emil i Margo: Čudovišne gluposti', '', 'Anne Didier, Olivier Muller', 'An Didije, Olivije Miler', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Когда просишь монстров помочь с домашним заданием, когда нянчишься с малышом-бедламом, когда приносишь домой учебник плохих манер или подливаешь мадемуазель Дисциплинде добробиотик в чай... неприятности гарантированы! Читайте об этих и других чудовищных глупостях в новой книге о приключениях Эмиля и Марго!', 'When you ask friendly monsters to help with your homework, babysit a baby Bedlam, bring home a handbook of terrible manners, or sneak a dose of kindness potion into Miss Discipline''s tea... utter chaos is guaranteed! Dive into these hilarious and monstrous misadventures with royal siblings Emile and Margot.', 'Kada zamoliš čudovišta da ti pomognu oko domaćeg, čuvaš bebu-haos, doneseš kući udžbenik lošeg ponašanja ili sipaš gospođici Disciplindi napitak dobrote u čaj... nevolje su zagarantovane! Uživajte u ovim i drugim nestašlucima u novim avanturama princa Emila i princeze Margo.', 'Если строгая гувернантка совсем замучила нотациями, пора звать монстров — они точно знают, как превратить скучные уроки в весёлый кавардак!', 'Whenever strict governesses get completely unbearable, call in the monster crew—they know exactly how to turn dreary chores into glorious chaos!', 'Kad stroga guvernanta pretjera sa lekcijama, vrijeme je da pozovete čudovišta — ona najbolje znaju kako da učenje pretvore u zabavni haos!', '/covers/DP-0468.webp', '#4a9fa8', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","mischief","siblings","graphic novel"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-ветер-свободы-469', 'DP-0469', 'Эмиль и Марго. Ветер свободы', 'Emil and Margot: Wind of Freedom', 'Emil i Margo: Vjetar slobode', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Кто превратил фонтан в гигантское мороженое? Кто надел на статую носок? Кто заставил птиц мяукать, а кошек чирикать? Конечно же, монстры. Они всегда готовы устроить кавардак в замке... На радость Эмилю и Марго! Читайте всей семьей и хихикайте над новыми приключениями озорных принца и принцессы. Фишки книги — Волшебный мир, населенный забавными монстриками — вовсе не страшными, а дружелюбными. — Яркие герои, которые будут близки детям. — Веселые добрые истории о повседневных делах с примесью волшебства. Описанные ситуации знакомы каждому ребенку: принц и принцесса убираются в комнате, болеют, сажают цветы в огороде, наряжают елку, ходят в школу. — Короткие рассказы (в каждом всего шесть страниц) идеально подойдут для маленьких читателей — перед сном можно прочитать две-три истории и спокойно засыпать.', 'Who turned the castle fountain into a mountain of ice cream and made birds meow? The friendly monsters, of course! Prince Emil and Princess Margot find everyday royal chores far more exciting when their goofy creature pals drop by to cause hilarious magical chaos.', 'Ko je fontanu pretvorio u džinovski sladoled, a ptice natjerao da mjauču? Naravno, čudovišta! Princ Emil i princeza Margo pretvaraju dosadne dvorske obaveze u pravu zabavu uz pomoć svojih luckastih, magičnih i nimalo strašnih prijatelja.', 'Идеальное лекарство от скучных королевских манер — щепотка монстро-магии и море заразительного детского хохота!', 'The ultimate antidote to boring etiquette: a sprinkle of friendly monster magic and pure, unadulterated giggles!', 'Najbolji kraljevski lijek protiv dosadnih manira: prstohvat magije simpatičnih čudovišta i more smijeha!', '/covers/DP-0469.webp', '#2e86ab', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","friends"]', '["comics","monsters","royalty","humor","family"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-чудеса-без-пробл-470', 'DP-0470', 'Эмиль и Марго. Чудеса без проблем', 'Emile and Margot: Trouble-Free Magic', 'Emil i Margo: Čuda bez problema', '', 'Anne Didier, Olivier Muller', 'En Didije, Olivije Miler', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Кто ещё подскажет, как продлить каникулы на неделю? Или сделать замечательных клонов, которые пойдут за тебя в школу? Кто поможет вырастить невероятный гигантский огород за ночь? Ну, а то, что иногда с ними всё идёт наперекосяк... это даже весело! Новые приключения Эмиля и Марго, конечно же, не обойдутся без настоящих монстров. Они не делают ничего ужасного, наоборот, всегда готовы помочь. Монстры появляются именно тогда, когда нужны, с ответами на вопросы и чудесным решением всех проблем.', 'Who else knows how to stretch the holidays for another week, build clones to attend school in your place, or grow a giant vegetable garden overnight? Naturally, it''s the friendly monsters! While things don''t always go entirely as planned when they''re around, prince Emile and princess Margot are always up for chaotic, lighthearted fun in this delightful and witty comic series.', 'Ko još zna kako da produži raspust za još nedelju dana, napravi klonove koji će umjesto tebe ići u školu ili preko noći uzgoji džinovsku baštu? Naravno, čudovišta! Iako uz njih ponekad sve pođe naopako, princ Emil i princeza Margo znaju da je to zapravo najzabavniji dio svake magične pustolovine.', 'Когда уроки надоели, а каникулы слишком коротки, на помощь приходят самые весёлые и безобидные монстры на свете!', 'Whenever homework feels impossible and vacations too short, the friendliest monsters in the kingdom are here to save the day!', 'Kad dosade domaći zadaci, najsmješnija čudovišta na svijetu stižu u pomoć sa svojim blesavim čarolijama!', '/covers/DP-0470.webp', '#e26d38', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","siblings","magic","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-монстры-повсюду--471', 'DP-0471', 'Эмиль и Марго. Монстры повсюду!', 'Emil and Margot: Monsters Everywhere!', 'Emil i Margo: Čudovišta svuda!', '', 'Anne Didier, Olivier Muller', 'An Didije, Olivije Miler', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'В лесу вокруг замка Эмиля и Марго живёт целая орава монстриков, от ужасного Головокружа до милейшего Амурчика, — и они тут как тут даже в самой безвыходной ситуации. Выручат с контрольной по географии, даже если для этого нужно перенести горы, помогут присмотреть за беспокойной малышкой, запрут в сарае кошмарную мадам Вамзадам... Они забавные и добрые! Но с ними каждое небольшое происшествие мгновенно превращается в уморительную катастрофу... и именно тогда, когда мадемуазель Дисциплинда рядом!', 'In the woods surrounding Prince Emil and Princess Margot''s castle lives a whole horde of monsters, ready to pop up whenever trouble strikes! They are always glad to lend a hand—whether it means moving literal mountains for a geography test, babysitting a chaotic toddler, or locking their dreadful governess in a shed. They mean well and are wonderfully kind, but every little rescue mission inevitably spirals into a hilarious catastrophe right under the nose of Miss Discipline!', 'U šumi oko dvorca Emila i Margo živi čitava družina nestašnih čudovišta, spremnih da pritrče u pomoć u svakoj nevolji! Pomoći će oko kontrolnog iz geografije (čak i ako moraju pomjeriti planine), pričuvati nemirnu bebu ili zaključati strogu gospođu u šupu. Ona su dobroćudna i urnebesna, ali svaka njihova pomoć pretvara se u komičnu katastrofu — naročito kad je stroga guvernanta u blizini!', 'Идеальное противоядие от строгих гувернанток и скучных уроков: весёлая банда лесных монстров всегда спешит на помощь!', 'The ultimate antidote to strict governesses and dull homework: a delightfully goofy monster squad is always ready to save the day!', 'Savršen lijek protiv strogih guvernanti i dosadnih lekcija: vesela družina šumskih čudovišta uvijek pritrčava u pomoć!', '/covers/DP-0471.webp', '#4a8505', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","humor","castle","pranks"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-грандиозный-побе-472', 'DP-0472', 'Эмиль и Марго. Грандиозный побег', 'Emile and Margot: The Great Escape', 'Emil i Margo: Veliko bjekstvo', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'В замке, где живут Эмиль и Марго, всегда происходит что-нибудь невероятное: то в нём поселится русалка и заколдует всех своей песней, то королевский трон захватит монстр тишины, то в комнату прокрадётся зловредная муха, укус которой вызывает неудержимое любопытство. Хорошо, что у друзей-монстриков есть решение на все случаи жизни! И даже наказание от строгой мадемуазель Дисциплинды — не беда: монстры непременно помогут выпутаться... а может, вообще ускользнуть из замка. Например, на Луну!', 'In the castle where royal siblings Emile and Margot live, everyday life is far from ordinary: a visiting mermaid enchants everyone with her song, a silence monster takes over the throne, and a pesky bug bite sparks uncontrollable curiosity. Luckily, their secret monster pals have a wacky solution for every mess! Even strict Miss Discipline''s punishments can''t stop them — the monsters are always ready to stage a daring escape, perhaps even all the way to the Moon!', 'U dvorcu u kom žive Emil i Margo uvijek se dešava nešto nevjerovatno: čas se useli sirena i začara sve pjesmom, čas čudovište tišine zauzme prijesto, a nestašna muva svojim ujedom izazove neobuzdanu radoznalost. Srećom, njihovi prijatelji čudovišta imaju otkačeno rješenje za svaku nevolju! Čak ni stroga gospođica Disciplinda ne može da ih zaustavi — čudovišta će im pomoći da pobjegnu iz dvorca, možda čak i na Mjesec!', 'Если гувернантка замучила правилами, спасут только верные монстры и билет в один конец до самой Луны!', 'When your governess gets too strict, nothing beats friendly monsters and a secret escape hatch straight to the Moon!', 'Kad guvernanta pretjera sa pravilima, u pomoć stižu vjerna čudovišta i tajni bijeg pravo na Mjesec!', '/covers/DP-0472.webp', '#3d6cb9', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","castle","prince and princess","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-каникулы-с-монст-473', 'DP-0473', 'Эмиль и Марго. Каникулы с монстрами', 'Emile and Margot: Monster Holidays', 'Emil i Margo: Raspust sa čudovištima', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Эмиль и Марго — очень удачливые принц и принцесса. Ещё бы: их друзья — самые настоящие монстрики! Эти забавные и неугомонные создания всегда знают, как привнести в жизнь немного веселья... а иногда и хаоса! Вот и на этот раз Эмиля и Марго ждет много сюрпризов: встреча с ожившими персонажами сказок, сражение с жуткими монстрами-пугалками и даже визит в дом троллей. А уж когда дети решат поработать вожатыми в Монстролагере, без приключений точно не обойтись: ведь самая безобидная вылазка может закончиться чем-то непредсказуемым!', 'Emil and Margot are a very lucky prince and princess: their best friends are real monsters! These funny, restless creatures always know how to bring fun and delightful chaos into castle life. This time, Emil and Margot encounter fairy-tale characters come to life, battle spooky scare-monsters, visit a troll house, and even try being camp counselors at a Monster Camp where anything can happen!', 'Emil i Margo su nevjerovatno srećni princ i princeza: njihovi najbolji prijatelji su prava pravcata čudovišta! Ova smiješna i nemirna stvorenja uvijek unose pregršt zabave i haosa u dvorac. Ovog puta ih čekaju oživjeli likovi iz bajki, susret sa strašilima, posjeta kući trolova, pa čak i uloga vaspitača u kampu za čudovišta gdje je svaka avantura nepredvidiva!', 'Королевские каникулы точно не будут скучными, если ваши лучшие друзья — озорные монстры, готовые устроить переполох в замке!', 'Royal vacations are never boring when your best buddies are mischievous monsters ready to turn the castle upside down!', 'Kraljevski raspust nikada nije dosadan kada su ti najbolji drugari nestašna čudovišta spremna na svaku ludoriju!', '/covers/DP-0473.webp', '#38a169', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","adventure","magic"]', '["monsters","royalty","comics","summer","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-монстры-в-игре-474', 'DP-0474', 'Эмиль и Марго. Монстры в игре', 'Emil and Margot: Monsters in the Game', 'Emil i Margo: Čudovišta u igri', '', 'Anne Didier, Olivier Muller', 'An Didije, Olivije Miler', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Чем заняться в замке, когда вся королевская свита уехала на праздник? А если вас наказали и заперли в комнате? Эмиль и Марго не унывают: с друзьями-монстриками скучать некогда! Ведь можно пригласить Монстра игр, у которого полно тузов в рукаве, сыграть в захватывающую «Монстрополию» с друзьями из подземелья или искупаться в сладостях на ежегодном Автокарнавале. И даже скучные уроки и проделки вредного кузена Родриго — не повод для грусти: любимые монстры всегда помогут добавить щепотку веселья!', 'What do you do in a castle when the royal court is away at a grand party, or when you''ve been sent to your room as a punishment? Prince Emil and Princess Margot never despair, because their friendly monster pals know how to turn boredom into pure fun! Call in the Game Monster with tricks up its sleeve, dive into a round of subterranean Monstr-opoly, or gorge on candy during the annual Auto-Carnival. With monsters around, even dull lessons and sneaky cousin Rodrigo are no match for their mischievous cheer!', 'Šta raditi u dvorcu kad je cijela kraljevska svita otišla na zabavu, ili kad ste kažnjeni i zaključani u sobi? Princ Emil i princeza Margo nikada ne očajavaju, jer njihovi prijatelji-čudovišta uvijek nađu lijek protiv dosade! Mogu pozvati Čudovište igara, odigrati partiju podzemne „Monstropolije” ili uživati u slatkišima na velikom Autokaravalu. Čak ni dosadne lekcije ni smicalice nestašnog rođaka Rodriga nisu problem — čudovišta su tu da svaki dan pretvore u urnebesnu avanturu!', 'Заперли в комнате за шалости? Не беда: зовите ручных монстриков и готовьтесь к самой уморительной вечеринке в замке!', 'Grounded in your royal bedroom? Don''t worry—just invite your monster buddies over for the most hilarious castle party ever!', 'Kažnjeni ste u svojoj sobi? Nema brige: pozovite čudovišta i pripremite se za najotkačeniju žurku u dvorcu!', '/covers/DP-0474.webp', '#e25822', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","prince and princess","castle","humor","games"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-неугомонные-монс-475', 'DP-0475', 'Эмиль и Марго. Неугомонные монстры', 'Emile and Margot: Restless Monsters', 'Emil i Margo: Nemirna čudovišta', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Принц Эмиль и принцесса Марго умеют веселиться, а друзья-монстрики с радостью им помогают! Учитель заставил сидеть в библиотеке всю перемену? Не беда: монстры-книголюбы угостят винегретом из слов. Взрослые не дают как следует пошалить? Душечка-веселушечка готова устроить в замке настоящий переполох! А еще можно побывать в магазине пианино с хвостами и перьями, слетать в астрозоопарк с животными-зоодиаками и побывать в гостях у заботливой (чересчур!) монстрихи Маман. С друзьями-монстриками Эмиль и Марго готовы к любым поворотам!', 'Prince Emile and Princess Margot certainly know how to have fun, and their cheerful monster pals are always ready to help! Stuck in the library all recess? Monster bookworms will serve up a tasty word salad. Grown-ups being dull and strict? A party-loving monster is on hand to turn the royal castle upside down. Join the royal siblings as they visit a feathery piano shop, fly to an astro-zoo, and drop by for tea with an over-doting monster mum!', 'Princ Emil i princeza Margo znaju kako da se zabave, a njihovi veseli drugari čudovišta uvijek su tu da priskoče u pomoć! Da li vas je učitelj kaznio da provedete odmor u biblioteci? Nema problema, čudovišta-knjigoljupci donose salatu od riječi. Odrasli ne daju da se nestašluci nastave? Čudovište za žurke spremno je da napravi pravi rusvaj u dvorcu! Uz ove neobične prijatelje, dosada jednostavno nema nikakve šanse.', 'Спасение от занудства взрослых: озорной комикс о королевских буднях, где монстрики превращают любое строгое правило в праздник!', 'The ultimate antidote to adult boredom: a hilarious royal comic where mischievous monsters turn every strict rule into an unruly party!', 'Savršen lijek protiv dosade: urnebesni strip u kom nemirna čudovišta svako strogo pravilo u dvorcu pretvaraju u pravu zabavu!', '/covers/DP-0475.webp', '#e85d34', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","friends"]', '["comics","monsters","prince and princess","mischief","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-а-вот-и-не-страш-476', 'DP-0476', 'Эмиль и Марго. А вот и не страшно!', 'Emil and Margot: Not Scared at All!', 'Emil i Margo: Uopšte nije strašno!', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '9 том', '', NULL, NULL, 8, 16, 'middle', 'Как здорово, когда рядом есть друзья, всегда готовые не только пошалить, но и прийти на помощь! Вместе гораздо проще отыскать лучшие мыслишки для сочинения, устроить лучший день рождения, разобраться с коварными Бзззошибкам или внезапной контрольной. И даже проучить заносчивого двоюродного братца, уверенного, что все его выходки сойдут ему с рук! Потому что друзья Эмиля и Марго — самые настоящие монстры. Монстры, которых мечтает встретить каждый ребёнок! С таким друзьями весело и совсем не страшно!', 'It is wonderful to have friends who are always ready not only for mischief, but also to lend a helping hand! Together, it is much easier to brainstorm brilliant essay ideas, throw the coolest birthday party, deal with sneaky typo-bugs, or survive a sudden pop quiz. You can even teach a lesson to an arrogant cousin who thinks he can get away with anything! That is because Emil and Margot''s best pals are real, friendly monsters—the kind every kid secretly dreams of meeting.', 'Divno je imati prijatelje koji su uvijek spremni ne samo za nestašluke, već i da priteknu u pomoć! Zajedno je mnogo lakše pronaći najbolje misli za pismeni sastav, prirediti najbolju rođendansku proslavu ili izaći na kraj sa dosadnim greškicama i iznenadnim testovima. Pa čak i očitati lekciju uobraženom rođaku koji misli da mu sve prolazi nekažnjeno! Jer Emilovi i Margini prijatelji su prava pravcata čudovišta — ona kakva svako dijete priželjkuje da sretne.', 'Кто сказал, что монстры — это страшно, когда с ними можно закатить лучшую в мире вечеринку и проучить вредного кузена?', 'Who said monsters are scary when they can help you throw epic parties, ace pop quizzes, and outsmart a pesky cousin?', 'Ko kaže da su čudovišta strašna kad vam mogu pomoći da napravite najbolju zabavu i nadmudrite dosadnog rođaka?', '/covers/DP-0476.webp', '#4a7bb0', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","friends"]', '["monsters","comics","friendship","magic","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-весь-мир-кувырко-477', 'DP-0477', 'Эмиль и Марго. Весь мир кувырком', 'Emil and Margot: Upside Down World', 'Emil i Margo: Svijet naglavačke', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', '', NULL, NULL, 8, 16, 'middle', 'Самое время отвлечься от уроков и бесконечного заточения в замке — встречайте пятый том серии о приключениях озорных принца и принцессы! В новой книге Эмиля и Марго ждут встречи с любимыми монстриками и фантастические события! Ведь монстры ставят все с ног на голову... Они могут сделать людей разговорчивыми или вызвать провалы в памяти, им под силу состарить каждого на сто лет, остановить время и даже заменить лето на зиму. Вот принц и принцесса на глазах у оторопевшей гувернантки крадутся ночью из замка, следуя за манящим звуком флейты. Или ищут пропавший рюкзак возле фонтана, которого никогда не было. А куда их приведет этот странный туннель из подвала? Наконец-то вся жизнь кувырком!', 'Time to ditch boring lessons and palace etiquette—welcome to volume five of the mischievous royal siblings'' adventures! Emil and Margot dive into magical mischief with their beloved monster pals who can freeze time, swap summer for winter, or turn etiquette totally upside down. From midnight flutes echoing outside castle walls to phantom fountains and mysterious basement tunnels, order is out the window and fun reigns supreme!', 'Vrijeme je za bijeg od dosadnih časova i strogih dvorskih pravila — stiže peti tom avantura nestašnog princa i princeze! Emila i Margo čekaju nova druženja s omiljenim čudovištima koja mogu zaustaviti vrijeme, zamijeniti ljeto zimom ili izazvati potpunu zbrku. Noćni izlasci iz zamka, nevidljive fontane i tajni podzemni tuneli okreću čitav dvorac naglavačke!', 'Идеальное лекарство от скучных уроков и строгих гувернанток — просто добавьте щепотку дружелюбного монстро-хаоса!', 'The ultimate cure for boring homework and strict governesses—just invite your favorite monster friends over for some chaos!', 'Najbolji lijek protiv dosadnih lekcija i strogih guvernanti — samo pozovite svoja omiljena čudovišta u dvorac!', '/covers/DP-0477.webp', '#3b82f6', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","adventure"]', '["comics","monsters","royalty","humor","magic"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-время-шалостей--478', 'DP-0478', 'Эмиль и Марго. Время шалостей!', 'Emile and Margot: Time for Mischief!', 'Emil i Margo: Vrijeme za nestašluke!', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', '', NULL, NULL, 8, 16, 'middle', 'Эмиль и Марго — королевские дети, поэтому они должны быть мудрыми, вежливыми, разумными и хорошо себя вести! Веселье в замке допускается только с чистыми руками и ушами и строго в тщательно выглаженных вещах... Только когда их друзья монстры заглядывают в гости, Эмиль и Марго могут наконец-то повеселиться по-настоящему. Отправиться в Монстротеку, где вежливость и правила под запретом, побаловать себя семиярусным бургером в «Монстробургере» и даже посетить настоящий Монстросклад, где есть все на свете для хаоса и бардака. Ведь чтобы быть счастливым, нужно просто находить время для шалостей!', 'Emil and Margot are royal children, which means they are supposed to be polite, sensible, and impeccably behaved at all times. Fun in the castle is strictly regulated—clean ears and ironed clothes required! Luckily, whenever their secret monster pals drop by, the royal siblings can finally cut loose. From dancing at the Monster Club where manners are banned to stacking seven-layer monster burgers, this hilarious comic proves that true happiness starts with a little dose of mischief.', 'Emil i Margo su kraljevska djeca, što znači da uvijek moraju biti mudri, pristojni i besprekorno vaspitani. Zabava u dvorcu dozvoljena je samo čistih ruku i u savršeno ispeglanoj odjeći! Srećom, čim im u posjetu svrate prijatelji čudovišta, Emil i Margo konačno mogu da zaborave na bonton. Uz Monstro-klub gdje su pravila zabranjena i sedmospratne burgere, ovaj strip dokazuje da je za pravu sreću potrebno samo malo nestašluka.', 'Лучшее лекарство от дворцовой скуки и чопорных гувернанток — банда добродушных монстров и щепотка королевского озорства!', 'The ultimate antidote to stuffy palace rules: a secret gang of quirky monsters and a generous helping of royal mischief!', 'Najbolji lijek protiv dosadnih dvorjanskih pravila: družina otkačenih čudovišta i pregršt kraljevskih nestašluka!', '/covers/DP-0478.webp', '#2ba882', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","friends"]', '["comics","monsters","royalty","mischief","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-ни-дня-без-прикл-479', 'DP-0479', 'Эмиль и Марго. Ни дня без приключений', 'Emile and Margot: Not a Day Without Adventure', 'Emil i Margo: Ni dana bez avanture', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', '', NULL, NULL, 8, 16, 'middle', 'Ура! Эмиля и Марго ждут новые, настоящие приключения — и на этот раз всё самое интересное будет происходить не только в замке, но и за его пределами. Озорному принцу и принцессе предстоит взобраться на горы Пик, Шпиль и Макушку, переночевать в палатке в лесу... И как же здорово, что во время путешествия рядом с ними монстры! Ведь они подскажут, как покорить Пик, Шпиль и Макушку поскорее и не устать, устроиться вожатыми в Монстролагерь, договориться с Монстром туманов расчистить путь, чтобы покататься на лыжах, и даже перенестись на самый настоящий Бал монстров прямо из скучной комнаты!', 'Hooray! Emil and Margot are heading out for real adventures—and this time beyond the castle walls! The mischievous royal siblings are ready to climb steep mountain peaks, camp overnight in a forest tent, and discover that outdoor expeditions are ten times funnier when you have monster pals tagging along. Whether running a monster summer camp or sneaking out to a dazzling monster ball, boredom doesn''t stand a chance!', 'Ura! Emila i Margo čekaju nove, prave avanture — ovoga puta i van zidina dvorca! Nestašni princ i princeza penju se na visoke planinske vrhove, noće u šatoru usred šume i otkrivaju da su izleti još zabavniji uz čudovišta. Uz njihovu pomoć postaće vaspitači u kampu za čudovišta, zamoliće Čudovište od magle da im oslobodi skijašku stazu i otputovaće na raskošni bal čudovišta pravo iz dosadne spavaće sobe!', 'Даже скучные королевские правила трещат по швам, когда в поход с палатками и на лыжные склоны отправляется банда добродушных монстров!', 'Royal etiquette doesn''t stand a chance when a crew of friendly, quirky monsters joins your camping trip!', 'Kraljevski bonton pada u vodu čim se u planinarenje i kampovanje umiješa ekipa simpatičnih čudovišta!', '/covers/DP-0479.webp', '#e65c40', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","adventure","magic"]', '["comics","monsters","prince and princess","camping","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-каменный-монстр--480', 'DP-0480', 'Эмиль и Марго. Каменный монстр. Книга для первого чтения', 'Émile and Margot: The Stone Monster (Early Reader)', 'Emil i Margo: Kameno čudovište (Knjiga za prve čitaoce)', '', 'Anne Didier, Olivier Muller', 'Anne Didier, Olivier Muller', '', '', NULL, NULL, 8, 16, 'middle', 'Вторая книга приключений Эмиля и Марго и их друзей-монстриков — в формате рассказов для первого чтения. Отлично подойдет для детей, которые только учатся читать. Героям предстоит спасти обитателей замка, ведь злой монстр Горгон превратил их в камень своим взглядом. Хорошо, что у Эмиля и Марго есть неунывающие друзья, которые всегда готовы прийти на помощь. Правда, и они стали жертвой каменного монстра — теперь вся надежда только на Эмиля и Марго, принца и принцессу. Смогут ли они победить ужасного Горгона и спасти всех окаменевших? В этой книге приключения Эмиля и Марго излагаются не в комиксах, а в прозе — так дети смогут легко приобщиться к самостоятельному чтению вместе с любимыми героями. 4 коротких рассказа с простым и увлекательным сюжетом помогут ребенку сделать первые шаги в чтении, а озорные иллюстрации не дадут отвлечься и заскучать.', 'The second early reader book in the adventures of prince Émile, princess Margot, and their monster friends! A wicked monster named Gorgon has turned the castle''s inhabitants to stone with his chilling gaze, and even their monster buddies have fallen victim. Now everything depends on Émile and Margot. Will they outsmart the petrifying beast and save everyone? Featuring four short, engaging prose stories and vibrant, playful illustrations, this book makes taking the first steps into independent reading an absolute joy.', 'Druga knjiga priča za rano čitanje o avanturama princa Emila, princeze Margo i njihovih neobičnih čudovišta! Zlo čudovište Gorgon pretvorilo je stanovnike dvorca u kamen svojim pogledom, a čak su i njihovi vjerni prijatelji nastradali. Sada je sva nada u Emilu i Margo. Mogu li nadmudriti strašnog Gorgona i spasiti sve okamenjene? Sa četiri kratke, uzbudljive priče u prozi i razigranim ilustracijama, ova knjiga je savršena za prve samostalne čitalačke korake.', 'Спасать замок от окаменения куда веселее, когда учишься читать вместе с самыми озорными принцем и принцессой на свете!', 'Rescuing a castle from turning to stone is so much fun when you are taking your first reading steps with royal pranksters!', 'Spašavanje dvorca od pretvaranja u kamen mnogo je zabavnije kada prve čitalačke korake pravite uz nestašnog princa i princezu!', '/covers/DP-0480.webp', '#6e7b8b', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","adventure","magic"]', '["early reader","monsters","castle","magic","funny","prince and princess"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-страшно-важная-ц-481', 'DP-0481', 'Эмиль и Марго. Страшно важная церемония Книга для первого чтения', 'Emile and Margot: A Terrifically Important Ceremony', 'Emil i Margo: Strašno važna ceremonija', '', 'Anne Didier, Olivier Muller', 'An Didije, Olivije Miler', '', '', NULL, NULL, 8, 16, 'middle', 'Приключения Эмиля и Марго и их друзей-монстриков — теперь не только в комиксах, но и в формате рассказов для первого чтения! В замке, где живут Эмиль и Марго, готовится большое событие — грандиозная церемония в честь столетия мира между королевствами. Соберется не меньше пятидесяти гостей, а Эмиль и Марго, как принц и принцесса, должны за день выучить наизусть все имена. Задачка кажется нерешаемой, но с друзьями-монстриками осуществимо всё! Правда, кое-что может пойти не по плану... В этой книге приключения Эмиля и Марго впервые излагаются не в комиксах, а в прозе — так дети смогут легко приобщиться к самостоятельному чтению вместе с любимыми героями. Короткий рассказ с простым и забавным сюжетом поможет ребенку сделать первые шаги в чтении, а озорные иллюстрации от художника не дадут заскучать!', 'The adventures of Prince Emile, Princess Margot, and their monster buddies now come in a delightful early reader chapter format! A grand celebration is taking place at the castle to mark a century of peace. At least fifty royal guests are coming, and the siblings must memorize every single name in just one day. It seems like an impossible task, but with a little help from friendly monsters, anything can happen—even if things don''t go entirely according to plan!', 'Avanture princa Emila, princeze Margo i njihovih čudovišnih prijatelja sada stižu u formatu za rano samostalno čitanje! U zamku se sprema velika ceremonija povodom stogodišnjice mira među kraljevstvima. Dolazi najmanje pedeset gostiju, a brat i sestra moraju za jedan dan naučiti sva imena napamet. Zadatak djeluje nemoguće, ali uz pomoć nestašnih čudovištaca sve je ostvarivo — iako stvari brzo krenu naopačke!', 'Выучить имена пятидесяти важных гостей за одни сутки невозможно — если только на помощь не поспешат самые озорные замковые монстрики!', 'Memorizing fifty royal guests in a single day is totally impossible—unless you invite the castle''s naughtiest monsters to help!', 'Zapamtiti pedeset uvaženih zvanica za samo jedan dan je nemoguća misija — osim ako u pomoć ne pozovete nestašna čudovišta!', '/covers/DP-0481.webp', '#8a4f9e', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","magic","friends"]', '["early reader","monsters","castle","prince and princess","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('эмиль-и-марго-бесконечное-чаеп-482', 'DP-0482', 'Эмиль и Марго. Бесконечное чаепитие. Книга для первого чтения', 'Emil and Margot: The Endless Tea Party', 'Emil i Margo: Beskrajna čajanka', '', 'Anne Didier, Olivier Muller', 'An Didije, Olivije Miler', '', '', NULL, NULL, 8, 16, 'middle', 'Третья книга приключений Эмиля и Марго и их друзей-монстриков — в формате рассказов для первого чтения. Детективная история с любимыми героями, которую ребенок захочет прочитать сам. В замке появляется новый дворецкий — элегантный, вежливый и очень приветливый. Он без конца предлагает всем чай, и отказаться невозможно: уж больно обходителен. Только вот после каждого чаепития король, королева и даже строгая гувернантка начинают беспрекословно выполнять любые его приказы. Эмиль и Марго чувствуют неладное — они-то чай тайком выливают в фонтан. Успеют ли принц и принцесса разгадать тайну, пока не стало слишком поздно? Короткие рассказы, крупный шрифт и озорные иллюстрации на каждом развороте помогут ребенку «расчитаться» — без страха перед «слишком большим текстом», зато с удовольствием от целой самостоятельно прочитанной книги.', 'The third book of adventures featuring royal siblings Emil and Margot and their quirky monster friends—now specially tailored for early readers. A brand-new butler arrives at the castle, unfailingly polite and constantly offering tea that seems impossible to refuse. But soon, the king, the queen, and even the strict governess start obeying his every bizarre command! Emil and Margot secretly pour their cups into the courtyard fountain, realizing something fishy is going on. Can the prince and princess solve the mystery before the whole kingdom falls under a hypnotic tea spell? With large print, short chapters, and playful illustrations, it''s the perfect bridge to confident independent reading.', 'Treća knjiga avantura nestašnih kraljevskih blizanaca Emila i Margo i njihovih prijatelja čudovišta — u formatu stvorenom za prve samostalne čitaoce! U dvorac stiže novi batler: izuzetno uglađen, ljubazan i neumoran u nuđenju čaja. Međutim, nakon svakog gutljaja, kralj, kraljica i stroga guvernanta bespogovorno izvršavaju sve njegove naredbe. Emil i Margo naslućuju prevaru i krišom prosipaju svoj čaj u fontanu. Hoće li princ i princeza uspjeti da razotkriju ovu tajnu na vrijeme? Krupna slova i vesele ilustracije čine ovu knjigu pravim uživanjem za djecu koja tek počinju samostalno da čitaju.', 'Осторожнее с вежливыми дворецкими и их чаем — распутать этот дворцовый заговор под силу только хитрым детям и озорным монстрикам!', 'Beware of overly polite butlers serving endless tea—only clever royal kids and their monster pals can crack this bubbly mystery!', 'Pazite se previše ljubaznih batlera koji nude čaj — ovu dvorsku zagonetku mogu riješiti samo snalažljiva djeca i njihova čudovišta!', '/covers/DP-0482.webp', '#6c4f8d', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","adventure","magic"]', '["monsters","castle","early reader","mystery","humor"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('adventure-time-дельные-советы--483', 'DP-0483', 'Adventure time дельные советы, как стать потрясающим', 'Adventure Time: How to Be Awesome', 'Vrijeme je za avanturu: Kako biti nevjerovatan', 'Джейк Блэк', 'Jake Black', 'Džejk Blek', '', 'Комильфо', 2014, '978-5-91339-258-9', 8, 16, 'middle', '', 'Want to battle evil, master epic sword fights, and keep your chill like Finn and Jake? Packed with witty advice, hilarious illustrations, and secrets from the Land of Ooo, this guide reveals everything you need to know to become utterly, undeniably awesome.', 'Želiš li da pobijediš zloće, naučiš junačke trikove i sačuvaš kul stav poput Fina i Džejka? Uz duhovite savjete, otkačene ilustracije i tajne iz Zemlje U, ovaj vodič otkriva sve što ti je potrebno da postaneš apsolutno i neodoljivo nevjerovatan.', 'Финн и Джейк лично научат тебя побеждать ледяных магов и оставаться самым крутым героем Земли Ууу!', 'Finn and Jake are here to teach you how to beat ice wizards and become the most mathematical hero in Ooo!', 'Fin i Džejk te uče kako da pobijediš zlikovce i ostaneš najkul heroj u Zemlji U!', '/covers/DP-0483.webp', '#f4c430', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","adventure","friends"]', '["adventure time","comics","humor","heroes","guide"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('белая-птица-484', 'DP-0484', 'Белая птица', 'White Bird', 'Bijela ptica', 'Паласио Р. Дж.', 'R. J. Palacio', 'R. Dž. Palasio', '', 'Розовый жираф', NULL, NULL, 8, 16, 'middle', 'Миллионы читателей «Чуда» знают Джулиана как главного обидчика Августа Пулмана. Но Джулиан очень изменился — и всё благодаря истории, которую он услышал от бабушки и которую вы узнаете, прочитав «Белую птицу». Трогательная и страшная, эта книга — о еврейской девочке и французском мальчике, который прятал её от нацистов. «Доброта требует мужества. В те дни, когда доброта могла стоить всего — свободы, жизни, — она стала чудом», — говорит бабушка. И всё же в любые времена находятся люди, способные не бояться и помогать другим. Другие книги серии Р. Дж. Паласио, посвящëнные Августу Пулману и его одноклассникам: «Чудо», «Глава Джулиана», «Плутон», «Глава Шарлотты» и «Чудо. 365 дней».', 'Millions of Wonder readers know Julian as Auggie Pullman’s bully, but Julian changed forever thanks to a story his grandmother shared. In this poignant and unforgettable graphic novel, Grandmère recounts her childhood as a young Jewish girl hidden by a brave classmate in Nazi-occupied France, reminding us that kindness requires true courage and can perform miracles.', 'Milioni čitalaca knjige „Čudo“ pamte Džulijana kao dječaka koji je povrijedio Ogija Pulmana, ali Džulijan se promijenio zahvaljujući priči svoje bake. Ovaj dirljiv i snažan grafički roman donosi priču o jevrejskoj djevojčici i hrabrom dječaku koji ju je skrivao od nacista u okupiranoj Francuskoj, podsjećajući nas da dobrota zahtijeva istinsku hrabrost.', 'Пронзительный графический роман о том, как простое сострадание и смелость способны зажечь свет даже в самые тёмные времена.', 'A deeply moving graphic novel reminding us that everyday kindness is the ultimate act of courage.', 'Dirljiv grafički roman koji nas podsjeća da je dobrota pravo junaštvo, posebno u najmračnijim vremenima.', '/covers/DP-0484.webp', '#234169', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["real","friends"]', '["графический роман","вторая мировая","доброта","история","дружба"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('быстренько-луизетта-мадам-крот-485', 'DP-0485', 'Быстренько Луизетта мадам Крот', 'Quickly, Louisette the Mole', 'Brzo, Luizet gospođa Krtica', 'Брюно Хейтц', 'Bruno Heitz', 'Bruno Heitz', '', 'Шиповничек', NULL, NULL, 8, 16, 'middle', 'Луизетта - это Крот. Мадам Крот. Она живет со своими друзьями во Франции, где ее знают и любят многие читатели. Теперь и у нас есть возможность познакомиться с ними! Читая эту веселую и добрую серию комиксов, вы откроете для себя мир братьев наших меньших, узнаете секреты рецептов французской кухни, а также совершите путешествие в самые разные уголки незнакомой страны, и все это будет приправлено тонким французским юмором. Первая книга "Быстренько" поведает вам о том, на какие поступки бывают готовы ради дружбы, какие опасности могут подстерегать на каждом шагу и как легко сменить обстановку, находясь вблизи от своего родного дома.', 'Louisette is a mole. Madame Mole! Living in the French countryside with her quirky woodland friends, she stars in a delightfully witty comic book series. In this first escapade, discover a world of tiny creatures, a dash of French culinary flair, and see how far true friends will go for each other when unexpected dangers pop up right next to home.', 'Luizet je krtica. Gospođa Krtica! Živeći u francuskoj prirodi sa svojim šumskim prijateljima, ona je junakinja izuzetno šarmantnog i duhovitog stripa. U ovoj prvoj pustolovini otkrijte svijet malih stvorenja, tajne francuske kuhinje i saznajte na šta su sve pravi prijatelji spremni kada se neočekivane opasnosti pojave tik pored kućnog praga.', 'Остроумный французский комикс о кротихе с изысканным вкусом и верным сердцем — осторожно, вызывает непреодолимую тягу к круассанам и приключениям!', 'A witty French comic about a mole with exquisite taste and a loyal heart—watch out, it might spark an irresistible craving for croissants and cozy adventures!', 'Duhovit francuski strip o krtici prefinjenog ukusa i vjernog srca — pripazite, mogao bi probuditi želju za kroasanima i novim avanturama!', '/covers/DP-0485.webp', '#8b5a2b', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["funny","animals","friends"]', '["comics","animals","humor","france","friendship"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('уроки-рыбалки-486', 'DP-0486', 'Уроки Рыбалки', 'Fishing Lessons', 'Lekcije iz ribolova', 'Генрих Бёлль', 'Heinrich Böll', 'Hajnrih Bel', 'Эмиль Браво', 'Поляндрия', NULL, NULL, 8, 16, 'middle', 'Новелла нобелевского лауреата Генриха Бёлля, пересказанная Бернаром Фрио для детей В тихом портовом городке отдыхает старый рыбак. К нему подходит любопытный турист и начинает разговор. У этих людей нет ничего общего, и всё-таки один важный вопрос их объединит… Пересказ Бернара Фрио.', 'A classic parable by Nobel laureate Heinrich Böll, adapted for young readers by Bernard Friot. In a sleepy seaside harbor, an old fisherman dozes lazily in the sun. An ambitious tourist walks up and tries to teach him how to maximize his catch, only to discover a profound truth about what actually brings happiness in life.', 'Klasična priča nobelovca Hajnriha Bela, koju je za mlade čitaoce prilagodio Bernar Frio. U mirnoj morskoj luci, stari ribar bezbrižno drijema na suncu. Prilazi mu ambiciozni turista u želji da ga nauči kako da zaradi više, ali neočekivani razgovor otkriva pravu suštinu sreće i slobode.', 'Мудрая и невероятно актуальная графическая притча о том, что для истинного счастья порой нужно просто греться на солнышке у моря и никуда не спешить.', 'A wise and witty graphic parable reminding us that true happiness often means simply enjoying the sunshine by the sea without rushing anywhere.', 'Mudra i duhovita grafička priča koja nas podsjeća da prava sreća često leži u jednostavnom uživanju na suncu kraj mora bez ikakve žurbe.', '/covers/DP-0486.webp', '#2c6e85', 'comics', 'ru', 'available', 'Категория: Эмиль и Марго', '["real","funny"]', '["graphic novel","sea","philosophy","parable","happiness"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('космический-постальон-487', 'DP-0487', 'Космический постальон', 'The Postman from Space', 'Svemirski poštar', 'Гийом Перро', 'Guillaume Perreault', 'Gijom Pero', '', 'Белая ворона', NULL, NULL, 8, 16, 'middle', 'Боб — Космический почтальон. Каждый день он отправляется по одному и тому же маршруту, доставляя космическую почту. Но вот однажды что-то пошло не так, и Боб оказался в совершенно не знакомых местах, странных и населенных какими-то непонятными существами...', 'Bob is a dedicated space postman who loves his predictable daily delivery route. But when headquarters unexpectedly changes his schedule, Bob finds himself venturing into bizarre, uncharted corners of the galaxy filled with eccentric alien creatures and hilarious cosmic surprises.', 'Bob je svemirski poštar koji obožava svoju mirnu, predvidivu svakodnevnu rutu. Međutim, jednog dana šef mu mijenja raspored i Bob završava u potpuno nepoznatim, otkačenim kutcima galaksije prepunim čudnih bića i neočekivanih avantura.', 'Думаете, разносить письма скучно? Только если вы не доставляете бандероли капризным инопланетянам на другой конец галактики!', 'Think mail delivery is dull? Not when your regular route takes you across wacky galaxies to deliver parcels to eccentric aliens!', 'Mislite da je posao poštara dosadan? Nipošto, ako pakete morate uručiti hirovitim vanzemaljcima na drugom kraju galaksije!', '/covers/DP-0487.webp', '#3a7bd5', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure"]', '["comics","space","aliens","humor","journey"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('космический-почтальон-2-воры-н-488', 'DP-0488', 'Космический почтальон-2. Воры на моторах', 'The Space Postman 2: Motorized Thieves', 'Svemirski poštar 2: Lopovi na motorima', '', 'Guillaume Perreault', 'Gijom Pero', '', 'Белая ворона', NULL, NULL, 8, 16, 'middle', 'Уже знакомый многим космический (а вовсе не комический) почтальон Боб достиг такого уровня опыта в доставке писем и посылок на разные планеты, что теперь ему выделили стажерку для обучения. Но Боб страшно недоволен: он-то привык развозить посылки в одиночку. Но что поделаешь — работа есть работа, к тому же в этот день ему поручено отвезти всего лишь одно письмо, так что он уже планирует освободиться к утреннему перерыву на кофе. Но не тут-то было. В дело вмешивается безответственность адресата, не сообщившего о смене адреса, а еще — грозные космические воры на моторах. Как и в первой книге, во время поездки почтальоны будут посещать разные планеты и встречаться с разнообразными жителями галактики — космическим автостопщиком и музыкантом Йоленом, нерадивой космической полицией и самовлюбленным Королем. Боб, как всегда недовольный тем, что ему приходится работать в непривычных условиях, в конце концов понимает, что иногда смена рутины идет только на пользу.', 'Bob the space postman is seasoned enough to be assigned a new intern, much to his grumbling dismay. All he wants is to deliver one quick letter alone and be back in time for his morning coffee break. But an unnotified change of address and a menacing gang of motorized space thieves turn a routine run into an interplanetary wild-goose chase. From planetary hitchhikers to vain celestial kings, Bob discovers that shaking up your daily routine might actually be the best adventure of all.', 'Bob, iskusni svemirski poštar, protiv svoje volje dobija pripravnicu na obuku. Planirao je samo da uruči jedno obično pismo i brzo stigne na jutarnju kafu, ali neažurirana adresa primaoca i opasni lopovi na svemirskim motorima pretvaraju običan radni dan u galaktičku jurnjavu. Putujući od planete do planete, Bob shvata da razbijanje ustaljene rutine ponekad donosi najbolje avanture.', 'Даже если вы ворчливый почтальон с аллергией на перемены, космические воры на моторах мигом научат вас ценить командную работу!', 'Even if you are a grumpy postman allergic to company, a gang of motorized space bandits will teach you to embrace teamwork in no time!', 'Čak i ako ste džangrizavi svemirski poštar koji mrzi promjene, banda letećih bajkera brzo će vas naučiti timskom radu!', '/covers/DP-0488.webp', '#e0533c', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure","friends"]', '["space","comics","aliens","humor","adventure"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('космический-почтальон-3-голодн-489', 'DP-0489', 'Космический почтальон — 3. Голодный рейс', 'Bob the Postman from Space 3: The Hungry Flight', 'Svemirski poštar 3: Gladni let', '', 'Guillaume Perreault', 'Gijom Pero', '', 'Белая ворона', NULL, NULL, 8, 16, 'middle', 'Космический почтальон Боб, уже знакомый читателям по двум предыдущим книгам, продолжает бороздить просторы Вселенной, развозя почту и преодолевая всевозможные трудности. На этот раз его день не задался с самого начала: он не успел позавтракать и приехал на работу голодный. Во время насыщенного рабочего дня он пытается урвать возможность хоть чуть-чуть перекусить, но то ему предлагают личинки с метеоритами, то нужно срочно спасать друга, то долгожданная закуска оказывается такой горячей, что обжигает бедному Бобу язык… Но, как всегда, благодаря находчивости и терпению наш герой с блеском справляется со всеми испытаниями и возвращается на базу, где вожделенный сандвич уже совсем близок…', 'Bob the space postman is back, traveling across galaxies to deliver mail against all odds! But today started off on the wrong foot: Bob skipped breakfast and had to rush to work on an empty stomach. Between avoiding alien larva snacks, dodging meteor storms, and rushing to rescue a friend in trouble, will poor Bob ever get a chance to savor his long-awaited sandwich?', 'Svemirski poštar Bob se vraća i juri kroz galaksije kako bi na vrijeme isporučio sve pošiljke! Ali ovaj radni dan je počeo naopako: Bob nije stigao da doručkuje i krenuo je na put gladan. Između vanzemaljskih grickalica od larvi, spasavanja prijatelja u nevolji i svemirskih meteora, hoće li jadni Bob napokon stići da pojede svoj zasluženi sendvič?', 'Никогда не выходите в открытый космос голодными — уморительный комикс о том, как спасать галактику, когда в животе предательски урчит!', 'Never venture into deep space on an empty stomach — a hilarious cosmic comic about saving the galaxy while desperately dreaming of a sandwich!', 'Nikada ne letite u kosmos praznog stomaka — urnebesni strip o spasavanju galaksije dok vam u stomaku krče gladne zvijezde!', '/covers/DP-0489.webp', '#e76f51', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure"]', '["space","comics","humor","aliens","food"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('космический-почтальон-4-только-490', 'DP-0490', 'Космический почтальон — 4. Только без паники!', 'The Postman from Space 4: Don''t Panic!', 'Svemirski poštar 4: Bez panike!', 'Гийом Перро', 'Guillaume Perreault', 'Gijom Pero', '', '', NULL, NULL, 8, 16, 'middle', 'Эта полная драматизма история случилась сразу после того, как космическая почтальонка Марсель вернулась с очередного задания и привезла на своём космолёте неведомое существо! Обнаружив свою оплошность и не желая сообщать об этом шефу, Марсель решает все исправить самостоятельно и просит Боба помочь. Вместе они обнаружат, что в отделении завёлся пришелец с другой планеты, которого надо как можно скорее отправить домой… Как всегда, Боб и Марсель проявляют чудеса изобретательности и настойчивости, и в конце концов порядок в почтовом отделении будет восстановлен.', 'This dramatic and hilarious adventure begins right after cosmic mail carrier Marcelle returns from an assignment, accidentally bringing an unknown creature aboard her spaceship! Terrified of alerting the boss, Marcelle enlists Bob''s help to secretly fix the blunder. Together, they discover an alien roaming around the post office who must be safely returned home as fast as possible. With ingenuity and grit, Bob and Marcelle will surely set things right!', 'Ova uzbudljiva i duhovita priča počinje čim se svemirska poštarka Marsel vrati sa zadatka, nesvjesno dovozeći nepoznato biće u svom svemirskom brodu! U strahu da ne sazna šef, Marsel moli Boba za pomoć kako bi sve riješili u tajnosti. Zajedno shvataju da se po stanici šeta vanzemaljac kojeg treba hitno vratiti kući. Uz pregršt dovitljivosti i upornosti, red u svemirskoj pošti biće ponovo uspostavljen.', 'Главное правило космической почты: если из посылки сбежал загадочный пришелец, сохраняйте спокойствие и зовите верного друга!', 'Rule number one at the cosmic post office: if an unexpected alien escapes from your cargo, whatever you do, don''t panic!', 'Glavno pravilo svemirske pošte: ako neobični vanzemaljac pobjegne iz pošiljke, samo bez panike i zovite najboljeg prijatelja!', '/covers/DP-0490.webp', '#2c3e6b', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure","friends"]', '["space","comics","aliens","friendship","graphic novel"]', 1792836322697, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('луи-среди-призраков-491', 'DP-0491', 'Луи среди призраков', 'Louis Undercover', 'Luj među duhovima', 'Фанни Бритт', 'Fanny Britt', 'Fani Brit', 'Изабель ,Арсено', 'Белая ворона', NULL, NULL, 8, 16, 'middle', 'Этот графический роман рассказывает о коротком эпизоде из жизни мальчика-подростка. Родители Луи переживают сложный период в отношениях, а мальчик пытается почувствовать свое место не только во взрослом мире, но и в детском - с одноклассниками, лучшим другом и первой, едва зарождающейся любовью. Изабель Арсено и Фанни Бритт удалось запечатлеть тончайший момент превращения ребенка во взрослого.', 'A poignant and beautifully illustrated graphic novel about Louis, a young boy navigating his parents'' separation, school life, and the quiet tremors of a first crush. Fanny Britt and Isabelle Arsenault tenderly capture the fragile, honest moments of growing up amidst family struggles.', 'Ovaj dirljivi i prelijepo ilustrovani grafički roman prati dječaka Luja dok se suočava s krizom u braku svojih roditelja, školskim brigama i prvom stidljivom zaljubljenošću. Fani Brit i Izabel Arseno s nevjerovatnom nježnošću dočaravaju osjetljivi prelazak iz djetinjstva u svijet odraslih.', 'Трогательный и честный комикс о том, как научиться храбрости и не бояться внутренних призраков, когда семейный мир штормит.', 'A tender and honest graphic novel about finding your courage and facing quiet ghosts when life around you gets stormy.', 'Dirljiva i iskrena priča u stripu o pronalaženju hrabrosti onda kada oko nas bjesne tihe porodične oluje.', '/covers/DP-0491.webp', '#3f5a70', 'comics', 'ru', 'available', 'Для детей среднего и старшего школьного возраста.', '["real","friends"]', '["graphic novel","growing up","family","first love","courage"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('попугай-колетт-492', 'DP-0492', 'Попугай Колетт', 'Colette''s Lost Pet', 'Koletin papagaj', 'Изабель Арсено', 'Isabelle Arsenault', 'Izabel Arseno', 'Изабель ,Арсено', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Колетт, как и многие дети, мечтает о домашнем питомце. Она только-только переехала в новый дом и не успела завести друзей. Ей скучно и одиноко. Поэтому когда возле дома появляются двое ребят, она решает выдумать попугайчика. Домашнего попугайчика, который от неё улетел. История о пропавшем питомце Колетт разносится по округе, становится почти легендой. Все дети по соседству участвуют в поисках попугайчика. Вот так можно быстро обрести друзей, когда у тебя есть фантастический питомец.', 'Colette has just moved to a new neighborhood and is desperate for a pet. Feeling lonely and shy, she suddenly bluffs to the neighborhood kids that her pet parrot has flown away. As all the local children band together to find the runaway bird, Colette''s imagination takes flight—turning a little white lie into the beginning of true friendship.', 'Kolet se tek doselila u novi kraj i silno želi kućnog ljubimca. Osjećajući se usamljeno, u trenutku izmišlja priču o odbjeglom papagaju kako bi privukla pažnju dvoje djece iz ulice. Dok se cijelo susjedstvo udružuje u potrazi za neobičnom pticom, njena maštarija prerasta u početak pravog i iskrenog prijateljstva.', 'Нежный и стильный комикс о том, как маленькая детская выдумка может положить начало самой настоящей дружбе.', 'A tender and gorgeously illustrated graphic novel about how a harmless little white lie can spark the greatest real-life friendships.', 'Nježan i prelijepo ilustrovan strip o tome kako mala dječja maštarija može stvoriti velika i stvarna prijateljstva.', '/covers/DP-0492.webp', '#e5a924', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["friends","animals","real"]', '["graphic novel","friendship","imagination","new neighborhood","pets"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('путешествие-к-центру-земли-493', 'DP-0493', 'Путешествие к центру Земли', 'Journey to the Center of the Earth', 'Putovanje u središte Zemlje', '', 'Jules Verne, Matteo Berton', 'Žil Vern, Mateo Berton', 'Маттео Бертон', 'Белая ворона', NULL, NULL, 8, 16, 'middle', 'Всемирно известное произведение основоположника фантастики Жюля Верна! полное опасностей невероятное путешествие сквозь исландские скалы к центру земли, которое совершили профессор Отто Лиденброк и его племянник Аксель, - теперь в графическом пересказе художника Маттео Бертона!', 'The world-famous classic by sci-fi pioneer Jules Verne! The perilous, breathtaking journey deep through Icelandic rocks to the center of the Earth, undertaken by Professor Otto Lidenbrock and his nephew Axel, is now brought to life in a stunning graphic novel adaptation by Matteo Berton.', 'Svjetski poznati klasik pionira naučne fantastike Žila Verna! Opasno i nevjerovatno putovanje kroz islandske stijene ka središtu Zemlje, koje su preduzeli profesor Oto Lidenbrok i njegov nećak Aksel — sada u sjajnoj grafičkoj adaptaciji umjetnika Matea Bertona.', 'Готовы спуститься прямо в жерло вулкана и открыть затерянный доисторический мир на страницах этого захватывающего комикса?', 'Ready to plunge into the crater of an Icelandic volcano and uncover a prehistoric underworld in this breathtaking graphic novel?', 'Jeste li spremni da se spustite pravo u grotlo vulkana i otkrijete zaboravljeni praistorijski svijet na stranicama ovog sjajnog stripa?', '/covers/DP-0493.webp', '#c45a32', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure"]', '["комиксы","приключения","научная фантастика","классика","подземелья"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кот-раввина-494', 'DP-0494', 'Кот раввина', 'The Rabbi''s Cat', 'Rabinov mačak', 'Жоан Сфар', 'Joann Sfar', 'Žoan Sfar', '', 'Комильфо', NULL, NULL, 8, 16, 'middle', 'Французский графический роман, рассказывающий о смышленом коте раввина, который в результате неожиданного происшествия обрел дар речи. Книга издана при поддержке Посольства Франции в России.', 'A charming and philosophical French graphic novel set in 1930s Algeria, following an outspoken cat who suddenly gains the ability to speak—and immediately begins questioning everything from religion to daily life.', 'Očaravajući i filozofski francuski grafički roman smješten u Alžir 1930-ih, koji prati brbljivog mačka koji iznenada progovori i odmah počne da preispituje svijet, vjeru i običaje oko sebe.', 'Что будет, если язвительный кот съест попугая и внезапно заговорит о вере, любви и жизни? Настоящий шедевр французского комикса!', 'What happens when a witty cat eats a parrot and suddenly starts philosophizing about life, love, and faith? A pure graphic novel masterpiece!', 'Šta se desi kada cinični mačak pojede papagaja i odjednom progovori o vjeri, ljubavi i životu? Pravo remek-djelo stripa!', '/covers/DP-0494.webp', '#d96f32', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","animals","adventure"]', '["comics","cat","philosophy","humor","algeria"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рыцари-изумруда-495', 'DP-0495', 'Рыцари изумруда', 'The Knights of Emerald', 'Vitezovi Smaragda', 'Ожэ', 'Tiburce Oger, Anne Robillard', 'Tiburs Ože, En Robijar', '', '', NULL, NULL, 8, 16, 'middle', '"Слушайте все! Король Изумруд 1-ый и Волшебник Элунд ищут детей пяти-шести лет со сверхъестественными способностями! Привезите их в Королевство Изумруда, где они пройдут испытание, и мы узнаем, достаточно ли они сильны, чтобы стать Рыцарями Изумруда!" Это начало невероятной героической саги о приключениях, рыцарях, магии. На Анкидьев, континент, где живут люди, эльфы, феи, готовится нападение империей тьмы: империей насекомых. Ужасная угроза нависла над ним. Единственная надежда - воспитать настоящих Рыцарей, бесстрашных и сильных, способных защитить Анкидьев и его жителей. Первая книга серии комиксов по мотивам оригинальной истории известной канадской писательницы Анн Робийар "Рыцари Изумруда", переведенной на многие языки мира и выпущенной тиражом более четырех миллионов. Впервые на русском языке. Рисунки французского художника и автора многих известных в Европе комиксов Тибурса Ожэ.', '"Hear ye, hear ye! King Emerald I and Elund the Magician seek children aged five to six with supernatural gifts!" So begins an epic heroic saga of chivalry, courage, and sorcery. On the continent of Enkidiev, home to humans, elves, and fairies, a terrifying threat looms: the dreaded insect army of the dark empire is preparing to invade. The land''s only hope is to train a new order of fearless Knights capable of standing against the darkness. This is the first graphic novel adapting Anne Robillard''s international bestselling fantasy series, vividly illustrated by French comic artist Tiburce Oger.', '"Čujte svi! Kralj Smaragd I i čarobnjak Elund traže djecu uzrasta od pet do šest godina sa natprirodnim moćima!" Tako počinje epska saga o viteštvu, magiji i hrabrosti. Kontinentu Enkidijev, domu ljudi, vilenjaka i vila, prijeti mračna imperija insekata. Jedina nada za spas jeste odgojiti novi red neustrašivih vitezova sposobnih da odbrane svijet. Prvi dio grafičke novele zasnovane na čuvenom kanadskom bestseler serijalu En Robijar, sa upečatljivim ilustracijama francuskog strip-autora Tibursa Ožea.', 'Захватывающий эпический комикс о юных магах, суровых тренировках и великой битве за спасение волшебного королевства!', 'A gripping epic graphic novel full of young mages, rigorous trials, and an impending clash to save an enchanted realm!', 'Uzbudljiv epski strip o mladim čarobnjacima, teškim ispitima i borbi za spas začaranog kraljevstva!', '/covers/DP-0495.webp', '#1b5e3a', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","magic"]', '["comics","knights","magic","epic fantasy","monsters"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('никополь-496', 'DP-0496', 'Никополь', 'The Nikopol Trilogy', 'Nikopol', 'Энки Билал', 'Enki Bilal', 'Enki Bilal', '', 'Зангавар', NULL, NULL, 8, 16, 'middle', 'Впервые на русском языке выходит трилогия самых грандиозных графических романов-антиутопий ХХ века авторства Энки Билала. Сюжеты этих историй служат грозным предостережением всему человечеству... 2023 год, Париж - столица мрачной послевоенной Европы - во власти фашистской диктатуры. Город перенаселён, в нём царит разруха и свирепствуют болезни. В небе над мегаполисом зависает гигантская пирамида с могущественными пришельцами, в которых без труда угадывается пантеон древнеегипетских богов. Пришельцы требуют у правительства доступ к природным ресурсам в обмен на безопасность жителей. В это же время на одну из парижских улиц падает таинственная космическая капсула, в которой находится замороженное тело человека...', 'One of the most monumental 20th-century dystopian graphic novel trilogies by Enki Bilal serves as a haunting warning to humanity. In 2023, Paris—the grim capital of a post-war Europe—is locked under a fascist dictatorship, plagued by decay and rampant disease. Suddenly, a colossal pyramid carrying alien beings resembling ancient Egyptian gods hovers over the metropolis, demanding fuel in exchange for the city''s survival. At that exact moment, a stray space capsule crashes onto the Parisian streets, carrying the cryogenically frozen body of political dissident Alcide Nikopol...', 'Kultna distopijska trilogija grafičkih romana legendarnog Enkija Bilala donosi vizionarsku opomenu čitavom čovječanstvu. Godina je 2023, a Pariz je tmurna prijestonica poslijeratne Evrope pod čizmom fašističke diktature, shrvan prenaseljenošću i bolestima. Iznad metropole lebdi džinovska piramida s moćnim vanzemaljcima koji neodoljivo podsjećaju na drevne egipatske bogove i traže resurse u zamjenu za mir. U isto vrijeme, na pariske ulice pada zagonetna svemirska kapsula sa zaleđenim tijelom političkog bjegunca Alkida Nikopola...', 'Египетские боги над футуристическим Парижем и бунтарь из криосна — приготовьтесь к невероятному погружению в шедевр европейского комикса!', 'Egyptian gods hovering over a futuristic Paris and a rebel thawed from cryo-sleep—get ready to dive into a monumental European graphic novel masterpiece!', 'Egipatski bogovi iznad futurističkog Pariza i buntovnik probuđen iz krio-sna — pripremite se za remek-djelo evropskog stripa koje oduzima dah!', '/covers/DP-0496.webp', '#2c4154', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","magic"]', '["graphic novel","sci-fi","dystopia","egyptian gods","paris"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('отсрочка-497', 'DP-0497', 'Отсрочка', 'The Reprieve', 'Odgoda', 'Жибра', 'Jean-Pierre Gibrat', 'Žan-Pjer Žibra', '', 'Карьера пресс', NULL, NULL, 8, 16, 'middle', 'Вторая мировая война. Жюльен прячется от немцев в пустующей квартире и становится наблюдателем драматических событий военного времени. Жан-Пьер Жибра - крупнейший художник современности, автор замечательных графических романов, снискал славу во Франции и за рубежом. Это первое издание графического романа Ж.-П. Жибра на русском языке.', 'Set in occupied France during World War II, young Julien escapes a labor train bound for Germany and hides in a deserted village house. From his secret attic perch, he becomes an invisible observer of his neighbors'' quiet courage, betrayal, and daily survival. Jean-Pierre Gibrat''s acclaimed graphic novel is a visual masterpiece rendered in breathtaking watercolors, weaving history, romance, and human resilience.', 'Tokom Drugog svjetskog rata u okupiranoj Francuskoj, mladi Žilijen bježi iz voza za Njemačku i pronalazi utočište u napuštenoj kući svog rodnog sela. Iz svog skrovišta u potkrovlju, on neprimijećen posmatra svakodnevni život, tihi otpor i složene izbore svojih sugrađana. Hvaljeno remek-djelo Žan-Pjera Žibroa je veličanstven akvarelni grafički roman o ljubavi, hrabrosti i nadi.', 'Атмосферный акварельный шедевр о войне, где сквозь чердачное окно мы заново открываем любовь, смелость и жизнь вопреки всему.', 'A breathtaking watercolor masterpiece set in occupied France, proving that the quietest hideout can reveal the true power of courage and love.', 'Zadivljujući akvarelni grafički roman o okupaciji, gdje kroz prozor potkrovlja posmatramo ono najvažnije — ljubav, hrabrost i snagu života.', '/covers/DP-0497.webp', '#8b5a3c', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["real","adventure"]', '["graphic novel","wwii","france","history","art"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кот-саймона-сам-по-себе-498', 'DP-0498', 'Кот саймона сам по себе', 'Simon''s Cat: Beyond the Fence', 'Sajmonov mačak: Sam za sebe', 'Саймон Тофилд', 'Simon Tofield', 'Sajmon Tofild', '', 'livebook', NULL, NULL, 8, 16, 'middle', 'Вот кот, сам по себе. Вот Саймон, который помыл кота, который сам по себе. Вот снова кот, который сам по себе, который обиделся на Саймона, который помыл кота, который сам по себе… и ушел из дому. А вот и книжка. Которую об этом придумал Саймон.', 'Meet the cat who walks by himself—until Simon makes the grave mistake of giving him a bath. Deeply offended, the furious feline packs his dignity and ventures out beyond the garden fence into the great unknown. A laugh-out-loud comic adventure about feline stubbornness.', 'Upoznajte mačka koji ide svojim putem — sve dok Sajmon ne napravi kobnu grešku i odluči da ga okupa. Smrtno uvrijeđen, mačak pakuje svoj ponos i odlazi preko ograde u nepoznato. Urnebesan strip bez riječi o mačijoj tvrdoglavosti i velikom svijetu.', 'Узнайте, что бывает, когда вы решите помыть кота: обида вселенского масштаба и грандиозный побег за забор!', 'Find out what happens when you dare give a cat a bath: cosmic-level offense and an epic escape beyond the fence!', 'Saznajte šta se dogodi kad se usudite da okupate mačka: kosmička uvrijeđenost i epski bijeg preko ograde!', '/covers/DP-0498.webp', '#5a9e32', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","animals","adventure"]', '["comics","cats","humor","pets"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шув-499', 'DP-0499', 'Шув', 'Shuv', 'Šuv', 'Ольга Лаврентьева', 'Olga Lavrentieva', 'Olga Lavrentijeva', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', '«ШУВ» Лаврентьевой — это вещь, которую стоит включить в список лучшего, что появилось в российском комиксе за последнее двадцатилетие. Алексей Павловский, специалист-исследователь факультета истории ЕУСПб, организатор проекта «Наука о комиксах»', 'Set in a 1990s dacha village, this acclaimed graphic novel follows a brother and sister as they investigate the mysterious death of their neighbor Shuv, turning eerie village rumors and childhood fears into a gripping gothic detective story.', 'Smešten u selo devedesetih godina, ovaj hvaljeni grafički roman prati brata i sestru koji istražuju misterioznu smrt komšije Šuva, pretvarajući seoske glasine i dečje strahove u napetu gotičku detektivsku priču.', 'Атмосферный и пробирающий графический детектив о дачном детстве девяностых, детских страшилках и настоящей дружбе.', 'An atmospheric, chilling graphic detective story about growing up in the 90s, backyard mysteries, and conquering fears through storytelling.', 'Atmosferičan i misteriozan grafički roman o detinjstvu devedesetih, strašnim pričama i istrazi koja oduzima dah.', '/covers/DP-0499.webp', '#2c2d30', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["spooky","adventure","real"]', '["graphic novel","mystery","detective","childhood","nostalgia"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лунный-коп-500', 'DP-0500', 'Лунный коп', 'Mooncop', 'Mjesečev policajac', 'Том Голд', 'Tom Gauld', 'Tom Gold', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Люди сворачивают колонизацию луны и разъезжаются кто куда. Остаются роботы и единственный полицейский, которому опять отказали в переводе. Взамен к нему отправляют робота-психотерапевта. В новой книге Тома Голда люди и роботы практически неразличимы, разве что у роботов больше чувства юмора. "Лунный коп" - это и невесёлое размышление о будущем, и маленький роман о маленьком человеке, и просто смешная и грустная история с богатым послевкусием. Для неторопливого читателя.', 'Colonization of the moon is winding down, and people are drifting back to Earth. All that''s left are a few robots and a lone police officer whose transfer request was just denied again. Instead, headquarters sends him a therapy robot. In Tom Gauld’s graphic novel, humans and robots are nearly indistinguishable—except perhaps the robots have a better sense of humor. ''Mooncop'' is a poignant, deadpan meditation on the future, solitude, and small everyday moments.', 'Kolonizacija Mjeseca se privodi kraju i ljudi polako odlaze. Ostaju samo roboti i jedan jedini policajac, kome je premještaj ponovo odbijen. Umjesto povratka kući, šalju mu robota-terapeuta. U stripu Toma Golda ljudi i roboti su gotovo nerazdvojni, samo što roboti imaju malo više smisla za humor. ''Mjesečev policajac'' je nježna, sjetna i duhovita priča o malom čovjeku i budućnosti, stvorena za tiho i promišljeno čitanje.', 'Тихий, меланхоличный и удивительно уютный комикс о самом одиноком полицейском во вселенной, лунных пончиках и прелести неторопливой жизни.', 'A quiet, melancholic, and wonderfully warm comic about the loneliest cop in the universe, moon donuts, and the beauty of slow days.', 'Tih, melanholičan i nevjerovatno topao strip o najusamljenijem policajcu u svemiru, krofnicama na Mjesecu i ljepoti sporog života.', '/covers/DP-0500.webp', '#2c3e50', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","real"]', '["комиксы","космос","роботы","луна","юмор"]', 1792836322698, 1792845646934);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('по-ту-сторону-изгороди-over-th-501', 'DP-0501', 'По ту сторону изгороди/Over the gardenwall', 'Over the Garden Wall', 'Preko ograde', 'Кемпбелл Дж.', 'Jim Campbell', 'Džim Kembel', '', 'Комильфо', NULL, NULL, 8, 16, 'middle', 'Сборник-компаньон, основанный на мини-сериале Cartoon Network, обладателе премии Эмми. Он повествует о приключениях Вирта и Грега, единоутробных братьев, которые потерялись в странном, безграничном лесу под названием Неизведанное. Чтобы найти путь домой, они должны пройти через это жуткое место, где их единственными проводниками являются язвительная сиалия по имени Беатрис и старый Лесник. Но когда события становятся всё более и более странными, смогут ли они выбраться… живыми?', 'A companion graphic novel based on the Emmy-winning Cartoon Network miniseries. Follow the eerie adventures of half-brothers Wirt and Greg, who find themselves lost in a strange, twilight forest known as the Unknown. With only a sassy bluebird named Beatrice and a weary Woodsman to guide them, can the brothers uncover the secrets of the woods and find their way back home?', 'Prateći strip zasnovan na kultnoj mini-seriji kuće Cartoon Network nagrađenoj Emijem. Prati avanture polubraće Virta i Grega, koji su se izgubili u čudnoj, beskrajnoj šumi zvanoj Nepoznato. Dok im put pokazuju drska ptica plavoperka Beatris i zagonetni Drvosječa, dječaci pokušavaju da pronađu put kući prije nego što ih maglovite tajne šume zauvijek zarobe.', 'Атмосферная осенняя сказка с нотками светлой грусти и таинственности, где за каждым деревом прячется говорящая птица или древний секрет.', 'An atmospheric autumnal journey packed with cozy folk mystery, quirky tunes, and delightfully spooky woods!', 'Prava jesenja bajka puna magle, humora i neobičnih stvorenja koja će vas očarati svojom misterijom.', '/covers/DP-0501.webp', '#2d3a27', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","spooky","magic"]', '["comics","graphic novel","autumn","mystery","brothers"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-band-502', 'DP-0502', 'The Band', 'The Band', 'The Band', 'Мавил', 'Mawil', 'Mavil', '', 'Бумкнига', NULL, NULL, 8, 16, 'middle', 'Кто из нас в юности не мечтал стать рок-музыкантом? И неважно - умеешь ты играть или нет, всегда найдутся друзья, которые тебе в этом помогут. И через некоторое время ты уже стоишь на сцене и стараешься попасть в нужный ритм. Известный немецкий автор комиксов Мавил, неоднократный обладатель независимой премии в области рисованных историй ICOM, в этой книге рассказывает о своем музыкальном юношеском опыте, когда он играл в группе на бас-гитаре. Дружба, любовь и постоянный поиск вдохновения - это то, что окружает главного героя, да и любого молодого музыканта. Мавил и сейчас играет в группе, даже в целом оркестре, но теперь на балалайке.', 'Who hasn''t dreamed of becoming a rock star in their youth? Whether you know how to play or not, there are always friends ready to jump in and start making noise together. In this graphic memoir, acclaimed German comic creator Mawil recalls his chaotic teenage adventures as a bass guitarist in a garage band. Full of humor, awkward first loves, creative struggles, and genuine camaraderie, it strikes a chord with anyone who has ever dreamed of taking the stage.', 'Ko u mladosti nije sanjao da postane rok zvijezda? Nije ni važno znaš li da sviraš ili ne, uvijek će se naći prijatelji koji će ti pomoći da osnuješ bend. Poznati njemački strip autor Mavil u ovom autobiografskom stripu priča o svom tinejdžerskom muzičkom iskustvu sviranja bas-gitare. Prijateljstvo, prve ljubavi, nespretne probe i potraga za ritmom čine ovu priču neodoljivom za svakoga ko je ikada sanjao o bini.', 'Честный, смешной и до боли знакомый графический роман о том, как гаражный рок рождается из дружбы, упорства и парочки фальшивых нот.', 'A hilarious and heartwarming graphic memoir proving that true rock ''n'' roll is all about great friends, big dreams, and hitting at least a few right notes!', 'Duhovit i topao strip koji dokazuje da pravi rokenrol čine dobri prijatelji, veliki snovi i tek poneka pogođena nota!', '/covers/DP-0502.webp', '#e05a36', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","real"]', '["comics","graphic novel","music","friendship","growing up"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('принц-вэлиант-503', 'DP-0503', 'Принц Вэлиант', 'Prince Valiant', 'Princ Valijant', 'Хэл Фостер', 'Hal Foster', 'Hal Foster', '', 'Зангавар', NULL, NULL, 8, 16, 'middle', 'Книга Хэла Фостера "Принц Вэлиант во времена короля Артура. Том 1 (1937-1938)" не оставит равнодушным ни одного юного читателя, а также поклонников европейских комиксов. Легенды о короле Артуре, атмосфера Средневековья и магия сочетаются на страницах комикса, рассказывая захватывающую, полную героических подвигов историю.', 'Hal Foster''s legendary graphic masterpiece ''Prince Valiant in the Days of King Arthur: Volume 1 (1937–1938)'' invites young readers and graphic novel lovers alike into a grand medieval epic. Combining Arthurian legend, breathtaking historical draftsmanship, and chivalric heroics, this classic strip follows a courageous prince on an unforgettable quest.', 'Remek-djelo Hala Fostera „Princ Valijant u doba kralja Artura: Tom 1 (1937–1938)“ osvojiće svakog mladog čitaoca i ljubitelja klasičnog stripa. Legende o kralju Arturu, dojmljiva atmosfera srednjeg vijeka i junački podvizi spajaju se u uzbudljivu priču o hrabrosti, časti i viteštvu.', 'Легендарная рыцарская классика с иллюстрациями музейной красоты — идеальный комикс для искателей приключений любого возраста!', 'A legendary chivalric epic rendered with breathtaking vintage artistry — pure gold for every young adventurer!', 'Legendarni viteški strip sa crtežima muzejske ljepote — pravi užitak za svakog mladog pustolova!', '/covers/DP-0503.webp', '#9e2a2b', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","magic"]', '["comics","knights","king arthur","middle ages","classics"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('история-комиксов-504', 'DP-0504', 'История комиксов', 'The Comic Book History of Comics', 'Istorija stripa', 'Фред Ван Ленте', 'Fred Van Lente', 'Fred Van Lente', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Книга "История комиксов" - самая полная и разносторонняя картина становления и развития комиксов начиная с конца XIX века и до наших дней. Это не учебник, написанный сухим и скучным языком, а веселый комикс с забавными иллюстрациями. При создании книги Фред Ван Ленте и Райан Данлеви одновременно и отошли подальше, чтобы представить общую картину, и шагнули поближе, рассмотрев и проанализировав мелкие детали, которые влияли на ход событий. Вы узнаете, как из простеньких карикатур комиксы превратились в настоящее искусство, и выясните, какие из них стали бестселлерами и почему. Встретитесь с самыми успешными авторами и издателями и познакомитесь с историей таких гигантов, как Marvel, Disney и DC, без которых мы никогда бы не узнали о Супермене, Бэтмене, Капитане Америке и других любимых героях.', 'A vibrant, comprehensive, and delightfully humorous graphic history of comic books, spanning from late-nineteenth-century newspaper funnies to the modern superhero renaissance. Instead of a dusty textbook, Fred Van Lente and artist Ryan Dunlavey deliver a dynamic comic journey exploring the pioneers, secret rivalries, legal battles, and cultural shifts behind legendary titans like Marvel, DC, and Disney. Discover how simple newspaper caricatures transformed into beloved world-class art and gave birth to cultural icons like Superman, Batman, and Captain America.', 'Živopisna, sveobuhvatna i duhovita grafička priča o razvoju stripa — od novinskih karikatura s kraja XIX vijeka pa sve do današnjeg doba superheroja. Umjesto suvoparnog udžbenika, Fred Van Lente i crtač Rajan Danlevi vode nas kroz dinamičan strip prepun zanimljivih anegdota, legendarnih rivalstava i uspona divova poput Marvela, DC-ja i Diznija. Otkrijte kako je deveta umjetnost osvojila svijet i stvorila vječne ikone kao što su Supermen, Betmen i Kapetan Amerika.', 'Захватывающий графический роман о том, как смешные картинки в газетах покорили мир и подарили нам Бэтмена, Человека-паука и целую вселенную гиковской культуры!', 'A blast of a graphic novel revealing how newspaper doodles took over the world to give us Batman, Spider-Man, and modern pop culture!', 'Uzbudljiv strip o tome kako su novinske karikature osvojile svijet i podarile nam Betmena, Spajdermena i čitavu pop-kulturu!', '/covers/DP-0504.webp', '#e63946', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["real","funny","adventure"]', '["comics","history","pop-culture","superheroes","non-fiction"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('контракт-с-богом-505', 'DP-0505', 'Контракт с Богом', 'A Contract with God', 'Ugovor s Bogom', 'Уилл Айснер', 'Will Eisner', 'Vil Ajzner', '', 'МИФ', NULL, NULL, 8, 16, 'middle', 'Выход "Контракта с Богом" в конце 70-х годов произвел революцию в мире американских комиксов. Уилл Айснер, признанный комиксист, решил создать комикс, не похожий ни на какую другую работу в этом формате. И рассказал четыре истории, происходящие с жителями одного арендного дома в Нью-Йорке в 30-е. Четыре истории о любви, вере, предательстве на фоне арендного дома № 55 на Дропси-авеню. Эти проникновенные рассказы соединились в невероятный графический роман, ставший классикой комикса и по-прежнему остающийся близким и трогающим образцом настоящей большой литературы.', 'First published in the late 1970s, ''A Contract with God'' revolutionized the world of graphic storytelling. Will Eisner weaves four poignant tales of faith, love, grief, and resilience among the residents of a Bronx tenement at 55 Dropsie Avenue during the Great Depression, establishing the graphic novel as a profound form of modern literature.', 'Objavljivanje stripa ''Ugovor s Bogom'' krajem 70-ih godina napravilo je pravu revoluciju u svijetu devete umjetnosti. Vil Ajzner kroz četiri dirljive priče o vjeri, ljubavi i nadi prati stanovnike jedne zgrade u Bronksu tokom Velike depresije, stvarajući remek-djelo koje se s pravom smatra temeljem modernog grafičkog romana.', 'Основополагающий графический роман в истории: глубокий, честный и невероятно живой портрет надежд и разочарований обычных людей.', 'The legendary masterpiece that gave birth to the modern graphic novel, offering an unforgettable and deeply human look into the heart of 1930s New York.', 'Legendarno remek-djelo koje je definisalo moderni grafički roman – dirljiv, iskren i duboko ljudski pogled na život u Njujorku tridesetih godina.', '/covers/DP-0505.webp', '#3b3834', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["real"]', '["graphic novel","classics","new york","history","drama"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тринити-история-создания-атомн-506', 'DP-0506', 'Тринити история создания атомной бомбы', 'Trinity: A Graphic History of the First Atomic Bomb', 'Triniti: Grafička istorija stvaranja atomske bombe', 'Джонатан Феттер-Ворм', 'Jonathan Fetter-Vorm', 'Džonatan Feter-Vorm', '', 'МИФ', NULL, NULL, 8, 16, 'middle', '"Тринити" - графический роман, рассказывающий об истоках атомной теории, масштабном Манхэттенском проекте и первом боевом применении атомной бомбы. Мощные и выразительные иллюстрации показывают катастрофические последствия, пожалуй, самого неоднозначного открытия в истории человечества. "Тринити" - это не просто научный комикс, это история, которая заставляет задуматься о том, где граница научного знания, дозволенного человеку.', '"Trinity" is a gripping graphic novel tracing the birth of atomic theory, the secret race of the Manhattan Project, and the fateful dawn of the nuclear age. Through stark, evocative illustrations and rigorous research, Jonathan Fetter-Vorm captures both the astounding scientific triumph and the profound moral reckoning that forever changed our world.', '"Triniti" je upečatljiv grafički roman koji prati rađanje atomske teorije, tajni rad na projektu Menhetn i zoru nuklearnog doba. Kroz snažne ilustracije i istorijske činjenice, Džonatan Feter-Vorm prikazuje nevjerovatan naučni podvig, ali i zastrašujuće moralne dileme i posljedice otkrića koje je zauvijek promijenilo svijet.', 'Захватывающий и отрезвляющий графический роман о физиках, которые изменили ход истории и заставили человечество взглянуть в лицо собственному могуществу.', 'A riveting, thought-provoking graphic novel about the scientists who reshaped history and forced humanity to face the devastating power of its own ingenuity.', 'Napet i duboko poučan grafički roman o naučnicima koji su promijenili tok istorije i suočili čovječanstvo sa posljedicama sopstvene moći.', '/covers/DP-0506.webp', '#b85d19', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["real","spooky"]', '["graphic novel","history","science","physics","wwii"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('капитан-подштаник-и-ужасные-ун-507', 'DP-0507', 'Капитан Подштаник и ужасные унитазы-убийцы', 'Captain Underpants and the Attack of the Talking Toilets', 'Kapetan Gaćerone i napad klozetskih šolja-ubica', 'Дэв Пилки', 'Dav Pilkey', 'Dejv Pilki', '', 'Машинки творения', NULL, NULL, 8, 16, 'middle', 'Это второе эпическое сочинение о приключениях знаменитого Капитана Подштанника. Джордж и Харольд - "очень ответственные" ребята: если происходит что-нибудь плохое, ответственность за это обычно лежит на Джордже и Харольде. И вот они снова взялись за старое. Сначала сорвали своими выходками устроенный в школе праздник, а потом создали "армию злобных, свирепых унитазов-убийц, которые были твёрдо намерены захватить власть над миром..." Кто остановит фаянсовых монстров? Это под силу только Капитану Подштаннику!', 'In this second epic adventure, pranksters George and Harold accidentally bring a horde of vicious, carnivorous talking toilets to life! With their school and the entire world in grave danger, who can flush away this porcelain menace? It''s a job for the one and only Captain Underpants!', 'U ovoj drugoj epskoj avanturi, nestašni Džordž i Harold slučajno oživljavaju armiju krvožednih klozetskih šolja koje žele da zavladaju svijetom! Ko može zaustaviti ove keramičke nemani prije nego što bude prekasno? To je zadatak samo za velikog Kapetana Gaćeronea!', 'Приготовьтесь хохотать до колик: эта уморительная история со взбесившимися унитазами рассмешит даже тех, кто терпеть не может читать!', 'Prepare for non-stop belly laughs — this wildly silly, superhero comic will turn even the most reluctant reader into a book lover!', 'Pripremite se za buran smijeh — ovaj urnebesni strip u gaćama osvojiće čak i one koji inače uopšte ne vole da čitaju!', '/covers/DP-0507.webp', '#e05338', 'comics', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","adventure"]', '["comics","humor","superheroes","school","pranks"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('капитан-подштаник-и-преступный-508', 'DP-0508', 'Капитан Подштаник и преступный план профессора пуперпопса', 'Captain Underpants and the Perilous Plot of Professor Poopypants', 'Kapetan Gaćonja i opaki plan profesora Pipi-Pelenića', 'Дэв Пилки', 'Dav Pilkey', 'Dejv Pilki', '', 'Машинки творения', NULL, NULL, 8, 16, 'middle', 'Джордж и Харольд - совсем не вредные ребята. Они просто стараются немножко скрасить жизнь себе и всем остальным. К сожалению, из-за этого они иногда попадают в очень трудные ситуации. И когда их новым учителем естествознания стал профессор Пуперпопс, изобретательность Джорджа и Харольда чуть не привела к захвату всей нашей планеты безжалостным маньяком, засевшим внутри гигантского робота... Кто сорвет преступный план профессора Пуперпопса? Это под силу только Капитану Подштаннику!', 'George and Harold aren''t really bad kids—they just like to liven things up! Unfortunately, their harmless pranks go wildly awry when their new science teacher turns out to be the unhinged Professor Poopypants. With a mad scientist on the loose in a giant robot, will Captain Underpants be able to save the day once again?', 'Džordž i Harold uopšte nijesu zlonamjerni dječaci — oni samo žele da unesu malo radosti u školski dan. Nažalost, njihove šale izazivaju neviđenu pometnju kada im novi nastavnik postane uvrijeđeni profesor Pipi-Pelenić, spreman da osvoji svijet u džinovskom robotu. Ovo je posao koji može riješiti samo Kapetan Gaćonja!', 'Приготовьтесь безудержно хохотать: профессор со смешным именем, гигантский робот и самый нелепый супергерой на свете уже спешат на помощь!', 'Prepare to laugh until your stomach hurts: a villain with a ridiculous name, a giant robot, and the goofiest superhero alive are here to save the planet!', 'Spremite se za glasan smijeh: profesor sa najsmješnijim imenom, džinovski robot i najluđi heroj u gaćama stižu u akciju!', '/covers/DP-0508.webp', '#e65100', 'comics', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","adventure"]', '["superheroes","comics","school","humor","robots"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('капитан-подштаник-и-вторжение--509', 'DP-0509', 'Капитан подштаник и вторжение чрезвычайно беспощадных буфетчиц из открытого космоса', 'Captain Underpants and the Invasion of the Incredibly Naughty Cafeteria Ladies from Outer Space', 'Kapetan Gaće i invazija nevjerovatno zlih kuvarica iz svemira', 'Дэв Пилки', 'Dav Pilkey', 'Dejv Pilki', '', 'Машинки творения', NULL, NULL, 8, 16, 'middle', 'Голопузый герой вернулся! Он победил злого профессора Памперса... Он одержал верх над ужасными унитазами-убийцами... Он дрался за Правду, Справедливость и Натуральный Хлопок, но теперь он борется за свою жизнь! Сможет ли Капитан Подштанник дать отпор трем осьминогоподобным инопланетным пришельцам (выдающим себя за буфетчиц), которые хотят захватить нашу планету, а нас с вами сделать своими покорными космическими рабами? Только без па-а-а-ни-и-ки-и-и-и! и да пребудет с нами Сила нижнего белья!!!', 'The waist-banded superhero is back! He defeated Dr. Diaper and put an end to the Turbo Toilet 2000, but now he faces his greatest menace yet: three sneaky tentacled aliens disguised as lunch ladies, ready to turn everyone into zombie nerds and take over the Earth. Get ready for total wedgie-powered madness!', 'Najsmješniji superheroj u gaćama se vratio! Pobijedio je opake neprijatelje, ali sada ga čeka najveći izazov: tri opasna vanzemaljca s pipcima prerušena u školske kuvarice koji žele da pokore Zemlju. Spremite se za ludu avanturu i snagu stopostotnog pamuka!', 'Пристегните ремни и держитесь за трусы: школьный обед еще никогда не был настолько инопланетно опасным и гомерически смешным!', 'Hold onto your undies: school cafeteria food has never been quite this outrageously alien or ridiculously hilarious!', 'Držite se za gaće: školski ručak nikada nije bio ovoliko vanzemaljski opasan i urnebesno smiješan!', '/covers/DP-0509.webp', '#76b041', 'comics', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","adventure"]', '["comics","superheroes","aliens","school life","humor"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('капитан-подштаник-и-его-удивит-510', 'DP-0510', 'Капитан подштаник и его удивительные приключения', 'The Adventures of Captain Underpants', 'Avanture Kapetana Gaćerona', 'Дэв Пилки', 'Dav Pilkey', 'Dejv Pilki', '', 'Машинки творения', NULL, NULL, 8, 16, 'middle', 'Четвертоклашки Харольд и Джордж сочиняют комиксы о супергероях, которых придумывают сами. И вот однажды их супергерой ожил... Автор - американский писатель и художник-иллюстратор, лауреат Колдекоттовской премии. Он позаботился о том, чтобы облегчить процесс чтения: главы короткие, сюжет динамичный, на каждой странице - картинка. Так что может быть, история капитана увлечет и того, кого невозможно оторвать от телевизора…', 'Fourth-graders George and Harold love playing pranks and creating their own comic books starring an unlikely superhero. But everything changes when their silliest creation accidentally springs to life! Packed with lively action, short chapters, and hilarious flip-o-ramas, this graphic novel will hook even the most reluctant readers.', 'Četvrtaci Džordž i Harold obožavaju smicalice i crtanje stripova o neobičnom superheroju. Ali jednog dana njihov crtani junak neočekivano oživljava! Uz kratka poglavlja, brzu radnju i otkačene ilustracije na svakoj stranici, ova urnebesna avantura privući će i one koje je inače nemoguće odvojiti od ekrana.', 'Приготовьтесь к безудержному хохоту — эта уморительная история про супергероя в трусах способна превратить любого нехочуху в заядлого книгочея!', 'Get ready to laugh out loud—this goofy tale of a superhero in his undies can turn even the most stubborn screen-lover into an avid reader!', 'Spremite se za buran smijeh — ova otkačena priča o superheroju u gaćama pretvoriće svakog ljubitelja ekrana u pravog knjigoljupca!', '/covers/DP-0510.webp', '#d32f2f', 'comics', 'ru', 'available', 'Для детей младшего школьного возраста.', '["funny","adventure","friends"]', '["superheroes","comics","school","humor","pranks"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гримм-манга-511', 'DP-0511', 'Гримм - манга', 'Grimm Manga', 'Grim Manga', 'Кей Исияма', 'Kei Ishiyama', 'Kei Išijama', '', 'фабрика комиксов', NULL, NULL, 8, 16, 'middle', 'Эти сказки известны каждому с раннего детства. Без них не обходится ни одна сказочная антология, ни одна учебно-развивающая программа. Они выдержали несметное количество всевозможных интерпретаций и экранизаций. Однако писатель и художник Исияма Кеи решил взглянуть на них под особым углом, и в результате старые герои обрели совершенно новую жизнь. Таких братьев Гримм вы еще не видели! В книгу вошли сказки "Рапунцель", "Красная Шапочка", "Хансель и Гретель", "Два брата" и "Двенадцать охотников".', 'These fairy tales are familiar to everyone from earliest childhood, yet artist and writer Kei Ishiyama looks at them from a remarkably fresh perspective. Classic characters are reborn in a dynamic manga style full of unexpected twists and deep emotion. You’ve never seen the Brothers Grimm quite like this! Includes retellings of ''Rapunzel'', ''Little Red Riding Hood'', ''Hansel and Gretel'', ''The Two Brothers'', and ''The Twelve Huntsmen''.', 'Ove bajke svi znamo još od ranog djetinjstva, ali autor i ilustrator Kei Išijama posmatra ih iz sasvim novog ugla. Klasični likovi oživljavaju u dinamičnom manga stilu, punom neočekivanih obrta i emocija. Ovakve priče braće Grim još niste vidjeli! Knjiga obuhvata adaptacije bajki: „Zlatokosa“, „Crvenkapa“, „Ivica i Marica“, „Dva brata“ i „Dvanaest lovaca“.', 'Любимые сказки детства в дерзком ритме манги — приготовьтесь удивиться знакомым сюжетам заново!', 'Your favorite childhood fairy tales reborn with manga flair and surprising twists you won''t see coming!', 'Omiljene bajke iz djetinjstva u živopisnom manga stilu — pripremite se da vas poznate priče ponovo iznenade!', '/covers/DP-0511.webp', '#8b1e2f', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","adventure","spooky"]', '["manga","comics","fairy tales","retellings","brothers grimm"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('адзуманга-1-4-том-512', 'DP-0512', 'Адзуманга 1-4 том', 'Azumanga Daioh, Vols. 1-4', 'Azumanga Daioh, tomovi 1-4', 'Адзума Киёхико', 'Kiyohiko Azuma', 'Kijohiko Azuma', '', 'Пальма пресс', NULL, NULL, 8, 16, 'middle', 'Если вы думаете, что уже читали комедийную мангу - забудьте об этом! Перед вами манга, ставшая библией этого жанра, которая перевернет ваше представление о шутках. Манга, послужившая основой для двадцатишестисерийного аниме, обожаемого поклонниками на всех континентах. Манга, над которой смеются без остановки уже более десяти лет. Манга, героини которой входят в сотню самых любимых аниме персонажей. Теперь эта манга добралась и до России - встречайте, ее величество "Адзуманга"!', 'Think you know comedy manga? Think again! This legendary slice-of-life masterpiece redefined school humor worldwide. Follow the wonderfully eccentric everyday adventures of ten-year-old child prodigy Chiyo-chan and her delightfully quirky high school classmates and teachers in this timeless four-panel classic that spawned a beloved anime.', 'Mislite da ste već čitali pravu humorističku mangu? Razmislite ponovo! Ovo kultno remek-djelo školske komedije osvojilo je čitaoce širom svijeta. Pratite preslatku desetogodišnju vunderkindicu Čijo i njeno neobično društvo iz srednje škole kroz urnebesne svakodnevne situacije koje mame osmijeh na svakoj stranici.', 'Приготовьтесь смеяться до слёз: здесь десятилетняя отличница учится в старшей школе, а её эксцентричные одноклассницы чудят без перерыва!', 'Get ready to giggle non-stop at the delightfully absurd high school days of a ten-year-old prodigy and her wonderfully eccentric crew!', 'Spremite se za buru smijeha uz nesvakidašnje srednjoškolske dogodovštine desetogodišnje genijalke i njenih urnebesnih drugarica!', '/covers/DP-0512.webp', '#f39c12', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","real"]', '["manga","school life","friendship","humor","slice of life"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ранма-1-15-том-513', 'DP-0513', 'Ранма 1-15 том', 'Ranma ½, Vols. 1-15', 'Ranma ½, tomovi 1-15', 'Румико Такахаси', 'Rumiko Takahashi', 'Rumiko Takaši', '', 'Сакура пресс', NULL, NULL, 8, 16, 'middle', 'Токио, наши дни. Владелец школы боевых искусств по имени Соун Тендо объявляет трём своим дочерям, что скоро приедет его давний друг, Генма Саотоме, вместе со своим сыном Ранмой и одна из девушек должна будет выйти за него замуж - Соун и Генма договорились об этом много лет назад. Но вот на пороге появляются... огромная панда и симпатичная девушка! Что? Эта девушка - Ранма?', 'In modern-day Tokyo, martial arts dojo master Soun Tendo announces to his three daughters that his old friend Genma Saotome is visiting with his son, Ranma, who is arranged to marry one of them. But when the guests arrive, they find an enormous panda and a feisty girl! Splashed with cold water, Ranma becomes a girl and his father turns into a panda—leading to non-stop martial arts chaos and romantic rivalry.', 'U savremenom Tokiju, majstor borilačkih vještina Soun Tendo saopštava svojim trima ćerkama da stiže njegov stari prijatelj Genma Saotome sa sinom Ranmom, koji treba da se oženi jednom od njih. Međutim, na pragu se pojavljuju ogromna panda i simpatična djevojka! Pod hladnom vodom Ranma se pretvara u djevojčicu, a pod toplom ponovo u dječaka—i tako počinje legendarna borilačka zbrka.', 'Приготовьте чайник с кипятком и держитесь за животы: эта культовая комедия о превращениях и боевых искусствах рассмешит абсолютно каждого!', 'Keep a kettle of hot water handy and get ready to laugh until your sides hurt with this iconic shape-shifting martial arts comedy!', 'Držite čajnik sa toplom vodom pri ruci i pripremite se za smijeh do suza uz ovu kultnu komediju o borilačkim vještinama i čarobnim transformacijama!', '/covers/DP-0513.webp', '#d9383a', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure","magic"]', '["manga","martial arts","comedy","transformations","japan"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('dragonball-1-6-514', 'DP-0514', 'Dragonball 1-6', 'Dragon Ball, Vols. 1-6', 'Dragon Ball 1-6', 'Акира Торияма', 'Akira Toriyama', 'Akira Torijama', '', 'Эксмо', NULL, NULL, 8, 16, 'middle', 'Давным-давно в глухих горах жил мальчик по имени Сон Гоку. Весьма необычный мальчик, надо сказать. Как-то раз встретился он с девушкой по имени Булма, которая поведала ему о жемчуге дракона: семи волшебных шариках с искорками внутри. Если собрать все семь жемчужин вместе, то Шеньлун, божественный дракон, явится и исполнит любое твое желание. В поисках легендарного жемчуга наши герои отправляются в путешествие, полное приключений…', 'Deep in the mountains lived a boy named Son Goku—a rather unusual kid with incredible strength and a monkey tail. One day, he encounters Bulma, a brilliant girl searching for the seven mystical Dragon Balls. Legend says that gathering all seven will summon the eternal dragon Shenron, who grants any single wish. Together, they embark on a hilarious, wild, and action-packed quest!', 'Duboko u divljim planinama živio je dječak po imenu Son Goku — zaista neobičan dječak s majmunskim repom. Jednog dana upoznaje Bulmu, koja mu otkriva tajnu zmajevih kugli: sedam čarobnih kristala koji kriju veliku moć. Ako sakupi svih sedam, pojaviće se zmaj Šenron i ispuniti bilo koju želju. Tako počinje njihovo nezaboravno putovanje puno akcije, humora i nevjerovatnih avantura.', 'Легендарная манга, с которой началась целая эпоха: хвостатый каратист Гоку ищет волшебные сферы и заряжает неукротимым оптимизмом!', 'The legendary manga that kicked off an entire era: follow the tail-wagging martial artist Goku on a quest full of laughs, wild fights, and magic!', 'Legendarna manga od koje je sve počelo: pratite malog borca Gokua u nezaboravnoj potrazi punoj smijeha, akcije i magičnih zmajevih kugli!', '/covers/DP-0514.webp', '#e86d1f', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","funny","magic"]', '["manga","martial arts","quest","dragons","classic"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('путешествие-515', 'DP-0515', 'Путешествие', 'Travel', 'Putovanje', 'Ёкояма Юити', 'Yuichi Yokoyama', 'Juići Jokojama', '', 'Фабрика комиксов', NULL, NULL, 8, 16, 'middle', 'Экспериментальная манга, посвященная дзенскому искусству путешествия на скоростном поезде.', 'An experimental, wordless manga exploring the hypnotic, Zen-like rhythm and art of journeying on a high-speed bullet train.', 'Eksperimentalna manga posvećena zen umjetnosti putovanja brzim vozom i čistom vizuelnom ritmu bez riječi.', 'Запрыгивайте в скоростной экспресс и забудьте о словах — вас ждёт завораживающее и медитативное графическое путешествие!', 'Hop aboard this bullet train and leave words behind for a mesmerizing, meditative visual ride!', 'Uskočite u brzi voz i zaboravite na riječi — čeka vas hipnotišuće i meditativno vizuelno putovanje!', '/covers/DP-0515.webp', '#3d4a5d', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","real"]', '["manga","train","travel","visual storytelling","experimental"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хеллбой-hellboy-семя-разрушени-516', 'DP-0516', 'Хеллбой/Hellboy семя разрушения', 'Hellboy: Seed of Destruction', 'Helboj: Seme uništenja', 'Майкл Миньола', 'Mike Mignola', 'Majk Minjola', 'Джон Берн', 'Dark horse comics', NULL, NULL, 8, 16, 'middle', 'Когда Вторая мировая приняла неудачный для нацистов оборот, те попытались переломить ход войны при помощи магии, но проведенный ими ритуал имел неожиданный результат: во-первых, призванный в наш мир демон попал не к нацистам, а к американцам, а во-вторых, он оказался всего лишь маленьким ребенком. Его прозвали "Хеллбой" - "мальчик из Ада". Спустя много лет повзрослевший Хеллбой работает в Бюро расследований паранормальной деятельности и вместе со своими коллегами - такими же необычными существами, как и он сам - занимается различными делами, связанными со сверхъестественным. Очередное дело приводит Хеллбоя в дом рода Кавендишей - загадочного семейства, которое на протяжении уже ста пятидесяти лет одержимо поисками некоего старинного храма... Впервые в России знаменитый комикс про Хеллбоя, получивший множество премий Айснера и Харви, выходит в виде цветных сборников в твердой обложке, с примечаниями и всеми дополнениями, существующими на данный момент.', 'When World War II took a bad turn for the Nazis, they attempted to alter the war''s outcome through dark occult rituals. But their magic backfired: the demon summoned into our world wasn''t a terrible weapon, but a bewildered little boy with horns who fell into Allied hands. Raised as Hellboy, he grows up to become the star investigator of the Bureau for Paranormal Research and Defense. Alongside an eccentric cast of unusual companions, Hellboy takes on supernatural threats—leading him straight to the ominous Cavendish family estate and an ancient temple holding dark cosmic secrets.', 'Kada je Drugi svjetski rat krenuo po zlu za naciste, pokušali su da preokrenu situaciju mračnim okultnim ritualom. Međutim, prizvani demon nije završio u njihovim rukama, već kod saveznika — i bio je samo malo dijete sa rogovima. Nazvan Helboj, odrastao je u vrhunskog istražitelja Biroa za paranormalna istraživanja i odbranu. Zajedno sa neobičnim kolegama bori se protiv natprirodnih prijetnji, a novi slučaj vodi ga u zlokobnu vilu porodice Kevendiš i tajanstveni hram koji krije opasne tajne.', 'Легендарный краснокожий герой с каменной десницей доказывает, что кем бы ты ни родился — судьбу выбираешь только ты сам!', 'The legendary red-skinned investigator with a stone hand proves that no matter where you come from, you choose your own destiny!', 'Legendarni crveni heroj sa kamenom rukom dokazuje da bez obzira na to odakle potičeš, sudbinu biraš sam!', '/covers/DP-0516.webp', '#8b1e1e', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","spooky","magic"]', '["comics","superheroes","monsters","occult","mystery"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('малость-подавленный-парень-517', 'DP-0517', 'Малость подавленный парень', 'The Li''l Depressed Boy', 'Pomalo potišteni momak', 'Стивен Страбл', 'Shaun Steven Struble', 'Šon Stiven Strabl', 'Сина Грейс', 'Рамона', NULL, NULL, 8, 16, 'middle', 'Трогательный комикс о поиске счастья, красивых девушках и инди-роке Впервые на русском языке! Li&#39;l Depressed Boy Шона Стивена Страбла и Сины Грейс, история понурого юноши, преданного видеоиграм и инди-музыке, и отчаянно ищущего свою вторую половинку. Никаких супергероев, никаких зомби - только правда жизни.', 'A touching indie comic about video games, indie rock, awkward crushes, and the quiet quest for happiness. Meet the Li''l Depressed Boy—a cloth-faced outsider navigating everyday life with no superheroes and no monsters, just the bittersweet, relatable truth of growing up.', 'Dirljiv indi strip o video-igricama, indi roku, nespretnim simpatijama i tihoj potrazi za srećom. Upoznajte pomalo potištenog momka u svijetu bez superheroja i zombija — samo iskrena, slatko-gorka priča o odrastanju i traženju srodne duše.', 'Идеальный меланхоличный комикс под чашку какао для каждого, кто хоть раз чувствовал себя чуточку неуклюжим и потерянным в этом шумном мире.', 'The ultimate cozy, indie-rock comic to curl up with whenever you feel a little awkward, quiet, or out of place in this big world.', 'Savršen, melanholični indi strip uz topli čaj za sve koji su se ikada osjećali pomalo nespretno ili izgubljeno u ovom bučnom svijetu.', '/covers/DP-0517.webp', '#5b7b88', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["real","friends"]', '["comics","indie rock","growing up","first love","graphic novel"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мезмо-518', 'DP-0518', 'Мезмо', 'Mesmo Delivery', 'Mesmo Delivery', 'Грампа', 'Rafael Grampá', 'Rafael Grampa', '', 'Dark horse comics', NULL, NULL, 8, 16, 'middle', 'Имперсонатор Элвиса и бывший боксер берутся за работу по перевозке загадочного груза для службы доставки Мезмо. Их окольный путь до захолустного городка начинается с безобидной забегаловки, посещение которой превращается в кровавую резню, пробудившую ото сна самого дьявола. "Служба доставки Мезмо" - динамичное, кровавое произведение, блестящая постановка автора и художника Рафаэля Грампа. Вступление к этому выпуску написано легендарным Брайаном Азарелло ("100 bullets", "Joker"), кроме того, в данное издание входят пин-ап постеры от лучших современных художников-комиксистов, таких как Майк Оллред, Эдуардо Риссо, Крейг Томпсон и Фабио Мун; также оно включает в себя историю создания комикса "Служба доставки Мезмо".', 'An Elvis impersonator and an ex-boxer take a job transporting a mysterious cargo for the Mesmo Delivery service. Their detour to an off-the-beaten-path town begins at an unassuming roadside diner, which soon escalates into a wild, supernatural showdown capable of waking the devil himself. ''Mesmo Delivery'' is a kinetic, fiercely stylish graphic novella written and illustrated by acclaimed creator Rafael Grampá, featuring an introduction by Brian Azzarello and bonus pin-ups by comic legends like Mike Allred, Eduardo Risso, Craig Thompson, and Fábio Moon.', 'Imitator Elvisa i bivši bokser prihvataju posao prevoza tajanstvenog tereta za službu Mesmo Delivery. Njihovo putovanje do zabačenog gradića započinje u naizgled bezazlenom drumskom restoranu, koji se brzo pretvara u eksplozivan, natprirodni obračun koji bi mogao probuditi i samog đavola. ''Mesmo Delivery'' je dinamičan, vizuelno upečatljiv strip proslavljenog autora Rafaela Grampe, sa uvodom Brajana Azarela i pin-ap ilustracijama vrhunskih strip-majstora.', 'Сумасшедший микс из рок-н-ролла, мистики и ураганного экшена с потрясающим визуальным стилем от бразильского мастера комиксов!', 'A wild, rock-and-roll supernatural ride with breathtaking artwork that teen comic fans won''t be able to put down!', 'Luda kombinacija rokenrola, misterije i nevjerovatne akcije sa fantastičnim crtežom koji osvaja na prvi pogled!', '/covers/DP-0518.webp', '#b8261c', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","spooky"]', '["graphic novel","comics","dark horse","action","mystery","supernatural"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('наше-детство-519', 'DP-0519', 'Наше детство', 'Our Childhood', 'Naše djetinjstvo', '', 'Various Authors', 'Grupa autora', '', 'Комильфо', NULL, NULL, 8, 16, 'middle', '', 'A vibrant and heartfelt comic anthology capturing the essence of growing up: courtyard games, secret clubhouses, scraped knees, and the unforgettable little moments that shape who we become.', 'Topla i živopisna strip-antologija koja oslikava odrastanje: igre u dvorištu, tajna skrovišta, oguljena koljena i sve one nezaboravne male trenutke koji nas oblikuju.', 'Трогательный и забавный комикс-сборник, в котором каждый узнает свои разбитые коленки, дворовые секреты и самые тёплые летние каникулы!', 'A tender and hilarious comic anthology where everyone will recognize their own scraped knees, backyard secrets, and golden summer days!', 'Dirljiva i zabavna zbirka stripova u kojoj će svako prepoznati svoja oguljena koljena, tajne iz dvorišta i najljepše dane raspusta!', NULL, '#e28743', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["friends","real","funny"]', '["comics","growing up","nostalgia","friendship","everyday life"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мороженое-и-грусть-цианид-и-сч-520', 'DP-0520', 'Мороженое и грусть Цианид и счастье', 'Cyanide & Happiness: Ice Cream & Sadness', 'Cijanid i sreća: Sladoled i tuga', 'Крис, Роб, Мэт, Дэйв', 'Kris Wilson, Rob DenBleyker, Matt Melvin, Dave McElfatrick', 'Kris Vilson, Rob DenBlejker, Met Melvin, Dejv Makelfatrik', '', 'Комильфо', NULL, NULL, 8, 16, 'middle', 'Самый циничный комикс Интернета теперь в формате книги! 150 лучших комиксов серии, включая 30 совершенно новых стрипов и новейший интерактивный раздел, гарантируют - вы будете кататься со смеху!', 'The internet''s most iconic darkly absurd webcomic comes to print! Featuring 150 of the best strips, including 30 exclusive new sketches and a quirky interactive section, this punchy collection guarantees unstoppable laughter.', 'Kultni, cinični veb-strip sa interneta stigao je u obliku knjige! Sa 150 najboljih stripova, uključujući 30 potpuno novih i otkačeni interaktivni dio, ova zbirka garantuje smijeh do suza.', 'Осторожно: этот сборник взрывного и абсурдного юмора заставит вас смеяться вслух прямо посреди тихих библиотечных полок!', 'Fair warning: this burst of absurd internet humor will have you giggling uncontrollably right in the middle of our quiet library aisles!', 'Upozorenje: ovaj zbornik apsurdnog internet humora natjeraće vas da prsnete u smijeh usred mirnih bibliotečkih polica!', '/covers/DP-0520.webp', '#38b6db', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny"]', '["comics","webcomic","humor","satire","gag cartoon"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хранители-521', 'DP-0521', 'Хранители', 'Watchmen', 'Nadzirači', 'Алан Мур', 'Alan Moore', 'Alan Mur', 'Дэйв Гибонс', 'Азбука', NULL, NULL, 8, 16, 'middle', 'Самое полное издание в мире. В книгу вошли статьи авторов об истории создания графического романа, эскизы и наброски, выдержки из сценария, подробные комментарии к тексту романа. Не надо быть энтузиастом массовой культуры, чтобы по первым двадцати страницам понять, что "Хранители" - образец высокого, очень высокого искусства; а уж что будет на следующих двадцати... Не удивительно, что именно этот роман чаще прочих оказывается на верхней строчке в списках "комиксов для людей, которые не читают комиксы".', 'The most complete edition in the world, featuring behind-the-scenes essays by the creators, sketches, script excerpts, and detailed commentary. You don''t have to be a pop-culture buff to realize within the first twenty pages that Watchmen is a profound work of high art—the definitive graphic novel even for people who think they don''t read comics.', 'Najpotpunije izdanje na svijetu. Knjiga sadrži autorske tekstove o nastanku grafičkog romana, skice, odlomke scenarija i detaljne komentare. Ne morate biti poznavalac pop-kulture da biste već na prvih dvadeset stranica shvatili da su „Nadzirači“ remek-djelo visoke umjetnosti — savršena knjiga čak i za one koji misle da ne vole stripove.', 'Абсолютная классика графических романов для вдумчивых подростков, которая навсегда перевернёт ваше представление о супергероях.', 'The ultimate graphic novel masterpiece for thoughtful teens that will change the way you look at superheroes forever.', 'Vrhunski klasik grafičkih romana za pronicljive tinejdžere koji će zauvijek promijeniti vaše viđenje superheroja.', '/covers/DP-0521.webp', '#eab308', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","real"]', '["graphic novel","superheroes","mystery","dystopia","cult classic"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('темная-башня-рождение-стрелка-522', 'DP-0522', 'Темная башня рождение стрелка', 'The Dark Tower: The Gunslinger Born', 'Mračna kula: Rođenje revolveraša', 'Стивен Кинг', 'Stephen King', 'Stiven King', '', 'АСТ', NULL, NULL, 8, 16, 'middle', '"Темная башня" Цикл романов известнейшего на весь мир американского писателя Стивена Кинга, повествующий о странствиях и приключениях стрелка Роланда Дискейна. Он бродит по миру в поисках легендарной Темной башни, некоего средоточия сил, удерживающих не только мир стрелка, но и другие миры хаоса и разрушения. С 2007 г. компания "Marvel Comics" начала публиковать серию комиксов, сюжет которых основан на цикле "темная башня". главным директором этого проекта является сам автор, Стивен Кинг. Вашему вниманию предлагается первая книга серии - "рождение стрелка", - которая рассказывает о том, с чего все началось...', 'Stephen King''s dark fantasy epic comes to life in this vibrant Marvel graphic novel. Follow young Roland Deschain during his coming-of-age trials in Gilead, as he faces treachery, forbidden love, and sorcery. This stunning adaptation reveals the tragic origins that set the lone gunslinger on his fateful quest toward the Dark Tower.', 'Legendarni ep Stivena Kinga oživljava u ovoj upečatljivoj Marvelovoj grafičkoj noveli. Pratite mladog Rolanda Diskejna kroz iskušenja odrastanja u Gileadu, gdje se suočava sa izdajom, zabranjenom ljubavlju i mračnim silama. Ovo izdanje otkriva same početke sudbonosnog putovanja ka tajanstvenoj Mračnoj kuli.', 'Захватывающее графическое погружение в юность легендарного стрелка Роланда, где каждый выбор и выстрел решают судьбу целых миров!', 'Step into Mid-World and witness how a young boy took up his revolvers to become the legendary wanderer of the Dark Tower!', 'Zakoračite u Srednji svijet i otkrijte kako je mladi dječak postao legendarni revolveraš na sudbonosnom putu ka Mračnoj kuli!', '/covers/DP-0522.webp', '#7a2b22', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","magic","spooky"]', '["graphic novel","fantasy","gunslinger","stephen king","comics"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('темная-башня-долгая-дорога-дом-523', 'DP-0523', 'Темная башня Долгая дорога домой', 'The Dark Tower: The Long Road Home', 'Mračna kula: Dug put kući', 'Стивен Кинг', 'Stephen King', 'Stiven King', '', 'АСТ', NULL, NULL, 8, 16, 'middle', 'Зло разрастается. Ка-тет вот-вот распадется. Сюзан Дельгадо мертва. Клэй Рейнолдс, последний из Больших охотников за гробами, пустился в погоню. Зло разрастается, и ка-тет вот-вот распадется. Дорога домой будет долгой. Роланд, похоже, затерялся внутри призрачного мира "грейпфрута Мерлина", и за его душу борются злые силы; его ка-тету потребуется все их мужество, чтобы выбраться из Хэмбри и вернуться домой. Но Доган не дремлет, выпуская на свободу зло, от которого Роланду и его ка-тету не спастись, и очень может быть, что стрелок, который так недавно родился, следует долгой дорогой к смерти.', 'Evil is spreading, and the ka-tet teeters on the brink of falling apart. Susan Delgado is dead, and the last of the Big Coffin Hunters is on the hunt. Roland''s spirit is trapped within the haunted depths of Maerlyn''s Grapefruit, fighting dark forces for his very soul. It will take every ounce of courage for his loyal companions to escape Hambry and navigate the treacherous road home before unseen evils swallow them whole.', 'Zlo se širi, a ka-tet je na ivici raspada. Suzan Delgado je mrtva, a lovci su im za petama. Rolandova duša luta zatočena u sablasnom svijetu Merlinovog grejpfruta dok se mračne sile bore za nju. Njegovim prijateljima biće potrebna sva hrabrost svijeta da napuste Hembri i krenu na dug i opasan put kući, dok ih vrebaju nemilosrdne sjenke.', 'Захватывающее и мрачновато-прекрасное графическое путешествие для тех смельчаков, кто готов отправиться по следам юного Стрелка!', 'A gripping and darkly stunning graphic quest for brave teen readers ready to walk the dusty trail beside the young Gunslinger!', 'Uzbudljivo i mistično grafičko putovanje za sve hrabre tinejdžere koji se usuđuju da prate stope mladog Revolveraša!', '/covers/DP-0523.webp', '#7a2a22', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","magic","spooky"]', '["graphic novel","dark fantasy","gunslinger","journey","friendship"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('противостояние-капитан-шустрик-524', 'DP-0524', 'Противостояние/ Капитан Шустрик', 'The Stand: Captain Trips', 'Uporište: Kapetan Trips', 'Стивен Кинг', 'Stephen King', 'Stiven King', '', 'АСТ', NULL, NULL, 8, 16, 'middle', 'Стивен Кинг. "Противостояние: Капитан Шустрик" часть 1 из 5. Классическая история о борьбе Добра и Зла, когда на одной чаше весов - отчаяние и утраты, а на другой - искупление и надежда. Это апокалипсическое видение битвы человека за жизнь против охватившей весь мир смертельной болезни. Ибо когда "Капитан Шустрик" прокладывает себе путь по земле, приходит время для противостояния.', 'Stephen King''s epic saga "The Stand: Captain Trips" (Part 1 of 5) comes alive in graphic novel form. This legendary tale of Good versus Evil balances despair and loss against redemption and hope in an apocalyptic vision of humanity''s battle for survival against a devastating super-flu. When Captain Trips sweeps across the world, the time comes to make a stand.', 'Epska saga Stivena Kinga „Uporište: Kapetan Trips” (prvi dio od pet) oživljava u formi grafičkog romana. Ova legendarna priča o vječnoj borbi Dobra i Zla vaga očaj i gubitak naspram iskupljenja i nade, donoseći apokaliptičnu viziju preživljavanja u svijetu poharanom smrtonosnom pandemijom.', 'Завораживающий и мрачный графический роман для смелых подростков, готовых испытать свои нервы на прочность вместе со Стивеном Кингом!', 'A gripping and darkly atmospheric graphic novel for brave teens ready to test their courage alongside the master of suspense!', 'Napet i mračno privlačan grafički roman za hrabre tinejdžere spremne da testiraju svoju hrabrost uz majstora napetosti!', '/covers/DP-0524.webp', '#4a1c1d', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["spooky","adventure"]', '["graphic novel","stephen king","post-apocalyptic","comics","survival"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('черный-жук-1-525', 'DP-0525', 'Черный жук 1', 'The Black Beetle, Vol. 1: No Way Out', 'Crna Buba 1: Nema izlaza', 'Франческо Франкавилла', 'Francesco Francavilla', 'Frančesko Frankavila', '', 'Белый Единорог / Dark Horse Comics', 2014, '978-5-4375-0018-7', 8, 16, 'middle', '', 'In 1941 Colt City, a masked vigilante known as the Black Beetle investigates a deadly explosion at a meeting of rival mob bosses. As he digs deeper into the city''s murky underworld, he uncovers a web of lethal assassins, shadowy conspiracies, and occult forces.', 'U Kolt Sitiju 1941. godine, maskirani osvetnik poznat kao Crna Buba istražuje smrtonosnu eksploziju na sastanku suparničkih mafijaških klanova. Kako zaranja dublje u mračno podzemlje grada, otkriva mrežu plaćenih ubica, opasnih zavjera i okultnih sila.', 'Атмосферный ретро-детектив и чистый визуальный восторг для всех, кто обожает нуар, тайны в масках и стильные комиксы в духе золотого века!', 'Dive into a stylish 1940s pulp-noir mystery where shadows hide danger and only Colt City''s mysterious masked vigilante can crack the case!', 'Uronite u stilizovani retro-detektivski strip iz četrdesetih, gdje se u sjenkama kriju opasnosti koje samo maskirani osvetnik može rasvijetliti!', '/covers/DP-0525.webp', '#d35400', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","spooky"]', '["comics","noir","detective","superheroes","mystery"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жуй-1-526', 'DP-0526', 'Жуй 1', 'Chew, Vol. 1', 'Žvaći 1', 'Лэйман Гилори', 'John Layman, Rob Guillory', 'Džon Lejman, Rob Gilori', '', 'xl media', NULL, NULL, 8, 16, 'middle', 'У детектива Тони Чжуя есть один очень неприятный секрет. Чжуй - цибопат, а это значит, что он может получать экстрасенсорные видения от любой еды, которую попробует. А еще Чжуй не перед чем не остановится ради того, чтобы раскрыть преступление и найти виновного. Даже если это означает попробовать кусочек трупа жертвы, если в этом будет необходимость... Способности Тони оказываются чересчур пугающими для службы в обычной полиции, зато идеально подходят для работы в особом отделе Федеральной Службы Контроля Продуктов, самой могущественной правоохранительной организации в мире. Ему предстоит расследовать самые странные и загадочные нераскрытые дела. Перед вами невероятная нарезка из черного юмора, фантастики и умело обыгранных штампов полицейского боевика, приправленная обязательными ингредиентами второсортного кино: полицейскими, мошенниками, людоедами и экстрасенсами. Вас ждет незабываемое послевкусие и вы наверняка не откажитесь от добавки! В этой книге вас ждут две первые части серии: "Вкус жизни", попавшая в список бестселлеров "Нью-Йорк Таймс", и ее продолжение - "Вкус без границ".', 'Detective Tony Chu has a bizarre secret: he is a cibopath, meaning he gets psychic impressions from whatever he tastes. Driven to solve crimes by any means necessary, Tony is recruited by the FDA—the most powerful law enforcement agency on the planet—to crack their strangest and most twisted cases. Packed with sharp wit, quirky food crimes, and macabre comedy, this graphic novel serves up a feast of dark humor and detective thrills.', 'Detektiv Toni Ču ima prilično uvrnutu tajnu: on je cibopata, što znači da dobija vidovite vizije od svega što proba. Vođen željom da razriješi zločine po svaku cijenu, Toni završava u specijalnom odjeljenju moćne Agencije za hranu, rješavajući najbizarnije slučajeve. Pred vama je urnebesan miks crnog humora, detektivske akcije i fantastike koji garantovano traži repete!', 'Детективный комикс с убойным черным юмором и самым эксцентричным агентом, чья суперсила просыпается прямо за обеденным столом!', 'A delightfully twisted, laugh-out-loud detective comic starring a cop whose psychic powers activate with every single bite he takes!', 'Uvrnuti i urnebesni detektivski strip sa najčudnijim policajcem na svijetu čija se vidovitost budi sa svakim zalogajem!', '/covers/DP-0526.webp', '#7aa434', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","spooky","adventure"]', '["comics","detective","black humor","superpowers","graphic novel"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жуй-2-527', 'DP-0527', 'Жуй 2', 'Chew, Vol. 2', 'Žvaći 2', 'Лэйман Гилори', 'John Layman, Rob Guillory', 'Džon Lejman, Rob Gilori', '', 'xl media', NULL, NULL, 8, 16, 'middle', 'Способности Тони оказываются чересчур пугающими для службы в обычной полиции, зато идеально подходят для работы в особом отделе Федеральной Службы Контроля Продуктов, самой могущественной правоохранительной организации в мире. Ему предстоит расследовать самые странные и загадочные нераскрытые дела. Перед вами невероятная нарезка из черного юмора, фантастики и умело обыгранных штампов полицейского боевика, приправленная обязательными ингредиентами второсортного кино: полицейскими, мошенниками, людоедами и экстрасенсами. Вас ждет незабываемое послевкусие и вы наверняка не откажитесь от добавки! В эту книгу вошли третья и четвертая части серии: "Только десерт" и "Фламбе".', 'Tony Chu''s cibopathic powers are too bizarre for the regular police, but perfect for the FDA—the planet''s most powerful law enforcement agency! Join detective Chu as he cracks the weirdest unsolved cases in this wild blend of dark comedy, sci-fi cop action, psychics, crooks, and culinary madness. This book collects the arcs ''Just Desserts'' and ''Flambé.''', 'Tonijeve sposobnosti su suviše bizarne za običnu policiju, ali su savršene za Specijalni odjel Agencije za hranu i ljekove! Pripremite se za nevjerovatnu mješavinu crnog humora, naučne fantastike, kanibala i neobičnih slučajeva u ovoj otkačenoj detektivskoj priči punoj kulinarskih misterija. Ova knjiga sadrži priče „Samo desert“ i „Flambe“.', 'Остроумный, безбашенный и абсолютно непредсказуемый детектив, после которого вы будете смотреть на еду совсем другими глазами!', 'A wildly original, witty, and slightly gross detective comic that will make you rethink everything you eat!', 'Otkačen, urnebesan i potpuno nepredvidiv detektivski strip nakon koga ćete sasvim drugačije gledati na hranu!', '/covers/DP-0527.webp', '#d64527', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure","spooky"]', '["comics","detective","black comedy","superpowers","food"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жуй-3-528', 'DP-0528', 'Жуй 3', 'Chew, Vol. 3', 'Žvaći 3', 'Лэйман Гилори', 'John Layman, Rob Guillory', 'Džon Lejman, Rob Gilori', '', 'xl media', NULL, NULL, 8, 16, 'middle', 'Тони и Тоня Чжуй - близнецы. Тони - цибопат, а это значит, что он может получать экстрасенсорные впечатления от любой еды, которую ест. А еще Тони может попробовать часть тела умершего человека и узнать, чем тот занимался в прошлом. Тоня - цибо воянт, а это значит, что, укусив любого живого человека, она увидит его будущее. Тони недавно вышибли с работы в особом отделе Федеральной Службы Контроля Продуктов, и он стал простым патрульным Муниципальной дорожной инспекции, а Тоня - действующий агент НАСА, ныне самой могущественной организации в мире. Теперь именно ей предстоит расследовать всякие странные и загадочные нераскрытые дела... Перед вами невероятная нарезка из черного юмора, фантастики и умело обыгранных штампов полицейского боевика, приправленная обязательными ингредиентами второсортного кино: спецагентами, мошенниками, людоедами и экстрасенсами. Вас ждет незабываемое послевкусие, и вы наверняка не откажетесь от добавки! В эту книгу вошли пятая и шестая части серии: "Высшая лига" и "Космические плюшки", а также специальный выпуск о приключениях секретного агента - бойцового петуха Пойо!', 'Tony Chu is a cibopath who gets psychic impressions from anything he eats, while his twin sister Toni is a cibovoyant who bites living people to glimpse their future! Demoted to traffic cop, Tony watches Toni lead NASA''s weirdest secret investigations. Packed with cannibalism, culinary crimes, dark humor, and a special feature starring Secret Agent Poyo the cybernetic fighting rooster, this crazy crime saga collects Volumes 5 and 6: ''Major League'' and ''Space Cakes''.', 'Toni Ču je cibopata koji dobija psihičke vizije od svega što pojede, dok je njegova sestra bliznakinja Tonja cibovojantkinja koja ugrizom za živog čovjeka vidi njegovu budućnost! Dok je Toni degradiran na saobraćajnog policajca, Tonja kao NASA agentkinja istražuje najbizarnije neriješene slučajeve. Uz obilje crnog humora, ludih agenata i specijalnu epizodu o borbenom pijetlu Poju, ova knjiga donosi nezaboravnu detektivsku avanturu.', 'Сумасбродный детектив с чёрным юмором о еде, паранормальных кулинарных талантах и непобедимом боевом петухе Пойо!', 'A brilliantly unhinged food-detective comic bursting with psychic bites, dark humor, and an unstoppable secret-agent rooster!', 'Otkačeni kulinarsko-detektivski strip prepun uvrnutog humora, vidovite hrane i nezaustavljivog borbenog pijetla Poja!', '/covers/DP-0528.webp', '#70a03c', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure","spooky"]', '["comics","detective","dark humor","superpowers","sci-fi"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('1602-529', 'DP-0529', '1602', 'Marvel 1602', 'Marvel 1602', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'АСТ mainstream', NULL, NULL, 8, 16, 'middle', 'Нил Гейман - известный писатель-фантаст и сценарист, его романы "Американские боги", "Сыновья Ананси" и многие другие переведены на множество языков во всём мире, а серия комиксов "The Sandman. Песочный человек" невероятно популярна. Marvel 1602 - графический роман, в котором автор отвечает на вопрос как бы выглядели всем известные супергерои Вселенной Marvel в пугающем и таинственном средневековом прошлом, где правят мудрые и коварные короли и королевы, их окружение плетёт паутину интриг и заговоров, а наёмные убийцы поджидают за каждым углом. Герои и злодеи сменили имена, внешность и оружие, но не свои стремления наказать зло или, напротив, ввергнуть мир в хаос. Переместимся во времени более чем на 400 лет назад и узнаем, какие же приключения ждут Ника Фьюри, Человека-Паука, Доктора Стрэнджа, "Фантастическую четвёрку" и остальных в Англии 1602 года.', 'What if the Marvel Universe had been born four hundred years earlier? In this spellbinding graphic novel crafted by master storyteller Neil Gaiman, iconic heroes and villains—from Spider-Man and Nick Fury to Doctor Strange and the X-Men—emerge in Elizabethan England amid royal conspiracies, shadowy assassins, and apocalyptic portents. Stripped of modern tech but armed with steel, sorcery, and secret identities, they must solve a mysterious threat before the world unravels.', 'Šta ako su se heroji Marvelovog univerzuma pojavili četiri stotine godina ranije? U ovom upečatljivom grafičkom romanu Nila Gejmana, kultni junaci i zlikovci — od Spajdermena i Nika Fjurija do Doktora Strejndža — prebačeni su u elizabetansku Englesku prepunu kraljevskih intriga, magije i tajnih zavjera. Opremljeni mačevima i renesansnim ruhom umjesto visoke tehnologije, moraju spasiti svijet od misteriozne propasti.', 'Что, если бы Человек-паук и Люди Икс жили в елизаветинской Англии среди шпаг, магии и коварных королевских интриг?', 'Imagine your favorite Marvel superheroes trading spandex for Elizabethan ruffs and navigating royal intrigues in 1602!', 'Zamislite omiljene Marvelove superheroje u renesansnim odijelima, suočene s kraljevskim spletkama i drevnom magijom!', '/covers/DP-0529.webp', '#7b242c', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["adventure","magic","spooky"]', '["comics","superheroes","marvel","alternate-history","graphic-novel"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лечебница-аркхем-530', 'DP-0530', 'Лечебница Аркхем', 'Arkham Asylum: A Serious House on Serious Earth', 'Arkam azil: Ozbiljna kuća na ozbiljnoj zemlji', 'Грант Моррисон, Дэйв Маккин', 'Grant Morrison, Dave McKean', 'Grant Morison, Dejv Mekin', '', 'Азбука', NULL, NULL, 8, 16, 'middle', 'В 1920 году, после смерти матери, страдавшей безумием, блестящий психолог Амадей Аркхем превратил фамильное гнездо в клинику для лечения душевных болезней. Он даже не подозревал, что тем самым положил начало кошмарной цепи событий. Более полувека спустя лечебница для душевнобольных преступников Аркхем стала местом, где в унылых коридорах таятся мрачные тени. Дом из дурного сна. Головоломка из камня и дерева, которую лучше и не решать. Годами томились в плену этих давящих стен безумные и изуродованные враги Бэтмена. В обитых войлоком палатах и темных подвалах они вынашивали планы и плели интриги, мечтая о том дне, когда они восстанут и низвергнут царство здравомыслия. И вот этот день настал: первого апреля безумцы захватили лечебницу. Под предводительством Джокера они бросили жуткий вызов человеку, по чьей вине оказались в заточении, - Бэтмену. Один из самых популярных графических романов всех времен впервые на русском языке! Издание включает специальные дополнения, подготовленные к пятнадцатой годовщине выхода: сценарий с авторскими комментариями и первые наброски раскадровок.', 'In the 1920s, psychologist Amadeus Arkham transformed his ancestral home into a sanatorium, unknowingly starting a dark spiral of tragedy. Decades later, the Arkham Asylum houses Batman''s most dangerous and twisted adversaries. On April Fools'' Day, the inmates take over the asylum, led by the Joker, demanding that the Dark Knight enter their nightmare world alone. A haunting, surreal milestone in graphic novel history exploring the fragile boundaries of sanity.', 'Dvadesetih godina prošlog vijeka, psiholog Amadeus Arkam pretvorio je svoje porodično imanje u sanatorijum, nesvjestan košmara koji time započinje. Decenijama kasnije, Arkam azil čuva najopasnije i najizopačenije Betmenove neprijatelje. Na Prvi april, štićenici preuzimaju kontrolu pod vođstvom Džokera i traže da Mračni vitez sam zakorači u njihov mračni lavirint. Nadrealno i vizuelno hipnotišuće remek-djelo grafičkih novela koje istražuje krhke granice razuma.', 'Погрузитесь в сюрреалистичный шедевр графического искусства, где грань между разумом Бэтмена и безумием его врагов растворяется в тенях коридоров Аркхема!', 'Step into a hauntingly surreal graphic masterpiece where the line between Batman''s sanity and his rogues'' madness blurs into dark shadows!', 'Zakoračite u nadrealno grafičko remek-djelo u kom se granica između Betmenovog razuma i ludila njegovih neprijatelja gubi u sjenkama Arkama!', '/covers/DP-0530.webp', '#2c243b', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["spooky","adventure"]', '["batman","joker","graphic-novel","superheroes","dc-comics"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('смерть-цена-жизни-время-жизни-531', 'DP-0531', 'Смерть Цена жизни время жизни', 'Death: The High Cost of Living / The Time of Your Life', 'Smrt: Cijena života / Vrijeme života', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', 'Она - старшая сестра Сна и младшая сестра Судьбы. Она приходит ко всем, от вируса до человека, дважды: в миг рождения и в миг смерти. Она добра, мудра, и у нее отличное чувство юмора. И еще она цитирует Мэри Поппинс. Возможно, потому, что раз в сто лет она берет выходной и проживает один день среди тех, кого ей приходится провожать Бессолнечные Земли. А возможно, потому, что такой ее сделал Нил Гейман, автор культового "Песочного человека", где она и появилась впервые. В настоящее издание вошло все, что когда-либо посвящалось этой героине: две главы из графического романа "The Sandman. Песочный человек", графические романы "Смерть: цена жизни" и "Смерть: время жизни", авторский сценарий к главе "Обличье" из сборника "The Sandman. Песочный человек. Страна снов", несколько коротких историй, опубликованных в разное время, а также множество дополнительных материалов, включая уникальные живописные работы.Книга "Смерть: Цена жизни. Время жизни" повествует о самом мистическом, но неизбежном для человека явлении. Избранные произведения – графические романы, короткие истории – расскажут о том, какой видит смерть, сестру Сна и Судьбы, Нил Гейман.', 'Meet the elder sister of Dream and younger sister of Destiny: Death. Kind, witty, and surprisingly upbeat, she visits every living creature twice—at birth and at passing. Once every century, she spends a single mortal day walking among the living to remember the fragile beauty of life. This definitive collection brings together Neil Gaiman’s celebrated mini-series ''Death: The High Cost of Living'' and ''Death: The Time of Your Life'', along with classic Sandman chapters and rare bonus materials.', 'Upoznajte stariju sestru Sna i mlađu sestru Sudbine: Smrt. Ljubazna, mudra i nevjerovatno vedra, ona obilazi svako biće dva puta — na rođenju i na kraju. Jednom u sto godina, ona uzima slobodan dan i provodi ga kao običan smrtnik kako bi osjetila dragocjenost života. Ovo izdanje okuplja kultne grafičke romane Nila Gejmana ''Smrt: Cijena života'' i ''Smrt: Vrijeme života'', uz klasična poglavlja iz ''Sendmena'' i rijetke ilustracije.', 'Встречайте самую обаятельную, чуткую и жизнерадостную Смерть в истории комиксов, которая учит по-настоящему ценить каждое мгновение жизни!', 'Meet the most charming, empathetic, and cheerful Death in comic history, here to remind us to cherish every fleeting moment!', 'Upoznajte najšarmantniju, najosjećajniju i najvedriju Smrt u istoriji stripa, koja nas uči da istinski cijenimo svaki trenutak života!', '/covers/DP-0531.webp', '#2c2838', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky","real"]', '["graphic novel","sandman","philosophy","life and death","urban fantasy"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-1-прелюдии-и-ноктюрны-532', 'DP-0532', 'Sandman 1 Прелюдии и ноктюрны', 'The Sandman, Vol. 1: Preludes & Nocturnes', 'Sendmen 1: Preludijumi i nokturna', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', '"Сэндмену" недаром нет равных среди графических романов по числу наград и премий, равно как и по числу похвальных отзывов. "Сэндмен" - это полный тайн и открытий сюжет с философским подтекстом, прописанным гениальным пером Нила Геймана и иллюстрированный лучшими художниками, "Сэндмен" - это колдовская смесь мифа и темной фэнтези, где сплетаются воедино множество жанров. Подобных саг, где одна таинственная история плавно перетекает в другую, не менее таинственную, мир графических романов прежде не видел. Однажды прочитав, "Сэндмена" невозможно забыть.', 'Critically acclaimed and recipient of countless literary awards, The Sandman stands peerless among graphic novels. Masterfully penned by Neil Gaiman and illustrated by top artists, this saga weaves myth, occult history, and dark fantasy into a spellbinding tapestry. When Morpheus, the King of Dreams, is captured and held prisoner for decades, his escape sets off an unforgettable journey to rebuild his fallen realm.', 'S pravom slavljen kao remek-djelo među grafičkim romanima, Sendmen donosi zagonetnu priču protkanu filozofijom, mitologijom i mračnom fantastikom iz pera genijalnog Nila Gejmana. Nakon višedecenijskog zatočeništva, Morfej, Gospodar Snova, kreće na neobično putovanje kako bi povratio svoju moć i obnovio izgubljeno kraljevstvo u sagi koju je nemoguće zaboraviti.', 'Готовы шагнуть в таинственное царство Снов, полное древних богов, магии и завораживающих теней?', 'Step quietly into the King of Dreams'' realm—it''s dark, hypnotic, and utterly impossible to put down.', 'Zakoračite tiho u Kraljevstvo Snova — ova mračna i očaravajuća priča ne pušta vas do posljednje stranice.', '/covers/DP-0532.webp', '#231f32', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky","adventure"]', '["comics","dark fantasy","mythology","dreams","graphic novel"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-2-кукольный-домик-533', 'DP-0533', 'Sandman 2 Кукольный домик', 'The Sandman, Vol. 2: The Doll''s House', 'Sendmen 2: Lutkina kuća', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', '"СЭНДМЕНУ" недаром нет равных среди графических романов по числу престижных наград и премий, равно как и по числу похвальных отзывов критиков и читателей. "СЭНДМЕН" - это полный W тайн и открытий сюжет с глубоким философским подтекстом, прописанный гениальным пером Нила Геймана и иллюстрированный лучшими художниками в жанре комикса, "СЭНДМЕН" - это колдовская смесь мифа и темной фэнтези, где сплетаются воедино множество жанров, от исторического романа до детектива. Подобных саг, где одна таинственная, будоражащая душу история плавно перетекает в другую, не менее таинственную, мир графических романов прежде не видел. Однажды прочитав, "СЭНДМЕНА" невозможно забыть.', 'Acclaimed as one of the most celebrated graphic novels of all time, Neil Gaiman’s The Sandman is an enchanting blend of myth, philosophy, and dark fantasy. In this gripping second volume, Morpheus, the Lord of Dreams, must track down rogue nightmares that escaped into the waking world while dealing with a rare and dangerous Dream Vortex that threatens to unravel reality itself.', 'Nagrađivan i slavljen širom svijeta, kultni grafički roman Nila Gejmana ''Sendmen'' očaravajuća je mješavina mita, filozofije i mračne fantastike. U ovom uzbudljivom drugom tomu, Morfej, Gospodar Snova, mora pronaći odbjegle noćne more koje lutaju svijetom budnih, dok se suočava s rijetkim i opasnim vrtlogom snova koji prijeti da uništi samu stvarnost.', 'Погрузитесь в чарующее царство Сна, где древние кошмары бродят среди людей, а каждая страница завораживает мрачной поэзией.', 'Step into the mesmerizing realm of the Dreaming, where ancient nightmares walk among us and every panel weaves dark, poetic magic.', 'Zakoračite u očaravajuće carstvo Snova, gdje drevne noćne more hodaju među ljudima, a svaka stranica nosi mračnu i magičnu poeziju.', '/covers/DP-0533.webp', '#24182e', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky","adventure"]', '["graphic novel","dark fantasy","dreams","mythology","comics"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-3-страна-снов-534', 'DP-0534', 'Sandman 3 страна снов', 'The Sandman, Vol. 3: Dream Country', 'Sendmen 3: Zemlja snova', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', '"Страна Снов" - прекрасный гобелен, сотканный из четырех захватывающих, но порой и жутких историй. Первая постановка шекспировского "Сна в летнюю ночь" (этот выпуск стал лауреатом "Всемирной премии фэнтези")… Писатель, который, лишившись вдохновения, не придумал ничего лучше, чем сделать музу своей рабыней… Кошачий взгляд на мир, где правят люди… И неуязвимая, бессмертная женщина, единственное желание которой - умереть… В сборник также включен авторский сценарий новеллы "Каллиопа" с пометками Нила Геймана и Келли Джонса.', 'Dream Country is a breathtaking tapestry woven from four haunting, standalone tales: Shakespeare staging ''A Midsummer Night''s Dream'' for actual faeries, an uninspired writer who imprisons a Greek muse, a feline vision of a world once ruled by cats, and an immortal woman longing for mortality. This celebrated volume includes the World Fantasy Award-winning issue and original script notes by Neil Gaiman.', '„Zemlja snova” je očaravajuća tapiserija satkana od četiri nezavisne, pomalo jezive priče: od Šekspirovog izvođenja „Sna ljetnje noći” pred pravim vilama i pisca koji zarobljava muzu, do tajnog mačjeg sna o vladavini svijetom i besmrtne žene koja čezne za krajem. Zbirka sadrži strip koji je osvojio prestižnu Svjetsku nagradu za fantastiku, uz originalni scenario i bilješke Nila Gejmana.', 'Четыре гипнотические истории, в которых даже кошки видят сны о величии, а Шекспир играет для настоящих фей.', 'Four hypnotic tales proving that cats dream of ruling the world and Shakespeare really did perform for fairies.', 'Četiri hipnotišuće priče koje otkrivaju o čemu mačke zaista sanjaju i kako Šekspir nastupa pred pravim vilama.', '/covers/DP-0534.webp', '#2c1e3b', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky"]', '["graphic novel","comics","fantasy","mythology","dreams"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-4-пора-туманов-535', 'DP-0535', 'Sandman 4 пора туманов', 'The Sandman, Vol. 4: Season of Mists', 'Sendmen 4: Doba magli', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', 'Добро пожаловать в мир снов, грез и самых невероятных фантазий. "Пора туманов, зрелости полей…" Жатва. Время собирать камни. Время оглянуться назад и понять, что ошибался. Время исправить содеянное. Вечные - Судьба, Сон, Смерть, Страсть, Страдание, Сумасшествие - собираются на семейный совет. Люцифер понимает, что устал от Преисподней. Сон спускается в Ад, чтобы освободить возлюбленную, которую сам же обрек на муки много тысяч лет назад… Нил Гейман сплетает туманы в очередной завораживающий сон. Смотрите…', 'Welcome to the world of dreams, reveries, and wildest fantasies. The Endless—Destiny, Death, Dream, Desire, Despair, and Delirium—gather for a rare family council. Meanwhile, Lucifer grows weary of ruling Hell and decides to walk away. Dream ventures into the underworld to free a lover he condemned to torment millennia ago, only to be handed the ultimate, unwanted gift: the key to the gates of Hell.', 'Dobrodošli u svijet snova, maštanja i najnevjerovatnijih fantazija. Vječni — Sudbina, San, Smrt, Strast, Očaj i Ludilo — okupljaju se na porodičnom vijeću. Lucifer odlučuje da napusti Pakao, a San silazi u Podzemlje kako bi oslobodio nekadašnju ljubav, samo da bi neočekivano dobio ključeve napuštenog carstva. Nil Gejman plete magle u očaravajuće grafičko remek-djelo.', 'Приготовьтесь к мистическому шедевру: Люцифер уходит на покой, вручает ключи от Ада Морфею, и начинается грандиозный мифологический переполох!', 'Get ready for a mythic masterpiece: Lucifer decides to retire, hands the keys of Hell over to Morpheus, and supernatural chaos ensues!', 'Pripremite se za mitsko remek-djelo: Lucifer odlazi u penziju, predaje ključeve Pakla Morfeju i izaziva pravu natprirodnu pometnju!', '/covers/DP-0535.webp', '#3e2f47', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky","adventure"]', '["comics","graphic-novel","mythology","dark-fantasy","dreams"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-5-игра-в-тебя-536', 'DP-0536', 'Sandman 5 игра в тебя', 'The Sandman, Vol. 5: A Game of You', 'Sendmen 5: Igra u tebe', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', '"Игрой в тебя" Гейман сплетает сказку, которая связывает миры - обитателей обшарпанных городских многоэтажек и земель типа Нарнии, захваченных врагом, известным как Кукушка. Гейман умело тасует мировые мифологии, придавая своей серии объем, ощущение времени и многозначный символизм… Если даже вы не читали "Сэндмана" раньше, это хорошее место, чтобы начать. - Элизабет Хэнд, Detroit Metro Times', 'In ''A Game of You'', Neil Gaiman weaves a dark and mesmerizing fairytale bridging two worlds: the eccentric residents of a gritty city apartment building and a magical realm under siege by a sinister force known as the Cuckoo. Gaiman masterfully reimagines world mythologies, giving his graphic epic unforgettable depth, haunting wonder, and rich symbolism.', 'U ''Igri u tebe'', Nil Gejman plete očaravajuću i mračnu bajku koja spaja dva svijeta: neobične stanare jedne gradske zgrade i magičnu zemlju nalik Narniji, koju je osvojila zagonetna sila poznata kao Kukavica. Gejman majstorski prepliće mitologije, dajući priči nevjerovatnu dubinu, simboliku i snagu mašte.', 'Приготовьтесь шагнуть через зеркало в мир забытых снов, где плюшевые игрушки берут в руки мечи, а за каждым углом прячется магия.', 'Step through the looking glass into a realm of forgotten childhood dreams, where plush companions become brave knights and ancient secrets await.', 'Zakoračite kroz ogledalo u svijet zaboravljenih snova, gdje plišane igračke postaju hrabri vitezovi, a magija vreba iza svakog ugla.', '/covers/DP-0536.webp', '#3b2d54', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky","adventure"]', '["graphic novel","dark fantasy","dreams","mythology","comics"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-6-притчи-и-отражения-537', 'DP-0537', 'Sandman 6 притчи и отражения', 'The Sandman, Vol. 6: Fables & Reflections', 'Sendmen 6: Basne i odrazi', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', 'СЭНДМЕН является самой прославленной и вознагражденной множеством премий серией комиксов по очень веской причине: умный и глубокий эпос, элегантно выписанный Нилом Гейманом и проиллюстрированный сменяющимся составом самых популярных художников в сфере комиксов. Это богатая смесь современного мифа и темной фэнтези, в которой литература о современности, историческая драма и легенды сплетены в единое целое. Сага о Сэндмене включает в себя ряд историй, уникальных для графической литературы, и вы её никогда не забудете. В «Притчах и отражениях» Владыка Снов появляется в девяти удивительных повестях, касаясь человеческих жизней в туманах прошлого и кошмарах настоящего. Цари и шпионы, императоры и актёры, во́роны и вервольфы делятся своими историями, мечтами и грезами – грезами о жизни и любви, власти и тьме.', 'The Sandman is celebrated worldwide for good reason: Neil Gaiman''s brilliant and evocative dark fantasy saga seamlessly intertwines modern myth, historical drama, and ancient legends. In ''Fables & Reflections'', the Lord of Dreams weaves through nine standalone tales, leaving his mark on human lives throughout history. Kings and emperors, spies and actors, ravens and werewolves reveal their deepest dreams, desires, and fears across the tapestry of time.', 'Sendmen s razlogom uživa kultni status u svijetu grafičkih novela: to je mudra, mračna i poetom obojena fantazija Nila Gejmana u kojoj se prepliću mitologija, istorijska drama i legende. U šestom tomu, ''Basne i odrazi'', Gospodar Snova vodi nas kroz devet upečatljivih priča smještenih u magle prošlosti i sjenke sadašnjice. Kraljevi, carevi, glumci, gavranovi i vukodlaci dijele svoje snove o moći, ljubavi i tami.', 'Девять чарующих историй о королях, оборотнях и властителе снов Морфее — идеальное погружение в мифологию Нила Геймана!', 'Nine spellbinding standalone tales of emperors, werewolves, and the Dream King himself—a masterpiece of comic storytelling.', 'Devet čarobnih priča o carevima, vukodlacima i Gospodaru Snova Morfeju — pravo remek-djelo grafičke književnosti!', '/covers/DP-0537.webp', '#2c2240', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky","adventure"]', '["comics","graphic novel","mythology","dreams","dark fantasy"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-7-краткие-жизни-538', 'DP-0538', 'Sandman 7 краткие жизни', 'The Sandman, Vol. 7: Brief Lives', 'Sendmen, Knjiga 7: Kratki životi', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', 'СЭНДМЕН является самой прославленной и вознагражденной множеством премий серией комиксов по очень веской причине: умный и глубокий эпос, элегантно выписанный Нилом Гейманом и проиллюстрированный сменяющимся составом самых популярных художников в сфере комиксов. Это богатая смесь современного мифа и темной фэнтези, в которой литература о современности, историческая драма и легенды сплетены в единое целое. Сага о Сэндмене включает в себя ряд историй, уникальных для графической литературы, и вы её никогда не забудете. Сумасшествие, младшая в большой семье Вечных, просит помощи у Сна в поисках их пропавшего брата Сокрушения, который исчез из своих владений много столетий назад. Их путь лежит сквозь бодрствующий мир, заполненный мельканием кратких жизней, чтобы завершится встречей с Сокрушением на острове в Эгейском море, хранящем голову Орфея. Эта встреча многое изменит, изменит навсегда. Вечные сущности или краткие жизни – у них гораздо больше общего, чем им хотелось бы знать. И чтобы сделать это знание выносимым, лучше притворится, что не обладаешь им.', 'Delirium, the youngest of the Endless, persuades her gloomy brother Dream to embark on a bittersweet road trip across the mortal realm in search of their long-lost brother, Destruction. As immortals brush against the flickering fragility of mortal mortals, their quest unravels deep familial grief, long-buried secrets, and the inevitable pain of change. Neil Gaiman''s breathtaking graphic novel weaves mythology, melancholy, and human warmth into one of the most poignant arcs of the Sandman saga.', 'Delirijum, najmlađa među Beskrajnima, nagovara svog mrzovoljnog brata Sna na putovanje kroz svet smrtnika u potrazi za njihovim davno nestalim bratom Uništenjem. Dok se besmrtna bića susreću sa prolaznošću kratkih ljudskih života, ova potraga pokreće porodične rane, drevne tajne i neminovnost promene. Nil Gejman stvara poetsku i duboko dirljivu priču koja prepliće mitologiju i melanholiju u jedno od najlepših poglavlja Sendmen sage.', 'Трогательное дорожное путешествие Повелителя Снов и его чудаковатой сестры Делириум доказывает, что даже вечным созданиям есть чему поучиться у мимолетных человеческих жизней.', 'A poignant cosmic road trip with Dream and his whimsical sister Delirium that proves even immortals have a lot to learn about letting go.', 'Dirljivo kosmičko putovanje Gospodara Snova i njegove luckaste sestre Delirijum pokazuje da čak i besmrtnici imaju šta da nauče o prolaznosti i praštanju.', '/covers/DP-0538.webp', '#2d233c', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","adventure","spooky"]', '["комиксы","нил гейман","сэндмен","мифология","графический роман","темное фэнтези"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sandman-8-у-конца-миров-539', 'DP-0539', 'Sandman 8 у конца миров', 'The Sandman. Vol. 8: Worlds'' End', 'Sendmen, Knjiga 8: Na kraju svjetova', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', '', 'Азбука', NULL, NULL, 8, 16, 'middle', '«Песочный человек» – это умный и глубокий эпос, элегантно выписанный Нилом Гейманом и проиллюстрированный сменяющимся составом самых популярных художников в сфере комиксов. Это богатая смесь современного мифа и темной фэнтези, в которой литература о современности, историческая драма и легенды сплетены в единое целое. Сага о Сэндмене включает в себя ряд историй, уникальных для графической литературы, и вы её никогда не забудете. «У Конца Миров» - это не просто шесть рассказов, поведанных людьми, которых разные причудливые пути привели в странный трактир вне времени и пространства. Это части обширного, единого повествования, вплетающего в себя целые миры. Эти миры сходятся здесь, чтобы растаять в буре, бушующей за стенами трактира, и остаться в историях, которые не умирают никогда.', 'Caught in the wake of a cosmic reality storm, an eccentric cast of cross-dimensional travelers seeks shelter in a mysterious inn at the end of the worlds. To pass the time, they exchange haunting, beautiful, and mythic tales that span times and dimensions, honoring the timeless magic of storytelling.', 'Zatečeni u središtu kosmičke oluje stvarnosti, neobični putnici iz različitih dimenzija pronalaze sklonište u tajanstvenoj krčmi na kraju svjetova. Dok čekaju da nepogoda prođe, oni dijele uzbudljive, magične i bezvremenske priče koje slave vječnu moć pripovijedanja.', 'Заварите чай и спрячьтесь от бури в таинственном трактире на краю Вселенной, слушая завораживающие истории от мастера Нила Геймана.', 'Take shelter from the storm at an inn at the edge of the universe and lose yourself in mesmerizing tales woven by master Neil Gaiman.', 'Sklonite se od bure u tajanstvenu krčmu na kraju univerzuma i prepustite se očaravajućim pričama majstora Nila Gejmana.', '/covers/DP-0539.webp', '#2b2d42', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["magic","spooky","adventure"]', '["comics","graphic novels","dark fantasy","mythology","storytelling"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ариоль-шевалье-мустанг-540', 'DP-0540', 'Ариоль Шевалье мустанг', 'Ariol: Mustang Knight', 'Ariol: Vitez mustang', 'Эмануэль Гибер', 'Emmanuel Guibert', 'Emanuel Giber', 'Марк Бутаван', 'Бумкнига', NULL, NULL, 8, 16, 'middle', '"Ариоль" - это серия веселых комиксов о повседневной жизни маленького ослика и его лучшего друга, непослушного, но очень симпатичного поросёнка. Они вместе ходят в школу, вместе ездят на каникулы, вместе играют и вместе валяют дурака. Их придумал Эмманюэль Гибер, один из наиболее авторитетных французских комиксистов, обладатель премии Рене Госинни за сценарное мастерство, а нарисовал известный детский иллюстратор Марк Бутаван.', 'Ariol is a delightful graphic novel series capturing the everyday life of a little donkey with spectacles and his best friend, a mischievous piglet. Together, they navigate school, family vacations, wild daydreams, and childhood fun. Created by acclaimed French comic artist Emmanuel Guibert and brought to life by renowned illustrator Marc Boutavant.', '„Ariol“ je omiljeni serijal duhovitih stripova o svakodnevici malog magarca s naočarima i njegovog najboljeg druga, nestašnog praseta. Zajedno idu u školu, putuju na raspust, maštaju i upadaju u luckaste dječije avanture. Osmislio ih je čuveni francuski autor Emanuel Giber, a ilustrovao Mark Butavan.', 'Невероятно смешной, честный и тёплый комикс про школьные будни, в котором каждый сразу узнает себя и своего лучшего друга!', 'A wildly relatable and laugh-out-loud graphic novel that captures the messy joy of school days and best friendships with absolute perfection.', 'Neodoljivo duhovit i topao strip o školskim danima u kojem ćete sigurno prepoznati sebe i svog najboljeg druga!', '/covers/DP-0540.webp', '#2c7bb6', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","animals"]', '["comics","graphic novel","school life","friendship","humor"]', 1792836322698, 1792845652047);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пама-мама-я-ослиная-семья-541', 'DP-0541', 'Пама, мама, я - ослиная семья', 'Ariol: Dad, Mom, and Me – A Donkey Family', 'Ariol: Tata, mama i ja – magareća porodica', 'том 9', 'Emmanuel Guibert, Marc Boutavant', 'Emanuel Giber, Mark Butavan', '', '', NULL, NULL, 8, 16, 'middle', '«Ариоль» — это серия весёлых комиксов о повседневной жизни маленького ослика и его лучшего друга, непослушного, но очень симпатичного поросёнка. Они вместе ходят в школу, вместе ездят на каникулы, вместе играют и вместе валяют дурака. Их придумал Эмманюэль Гибер, один из наиболее авторитетных французских комиксистов, обладатель премии Рене Госинни за сценарное мастерство, а нарисовал известный детский иллюстратор Марк Бутаван. Мама, папа и Ариоль — дружная ослиная семья. На первый взгляд их всего трое, но давайте присмотримся повнимательнее! Если учесть, что мама любит папу, папа любит маму, мама любит Ариоля, папа любит Ариоля, а Ариоль любит маму и папу, то это ж сколько народу!', 'Ariol is a charming and hilarious comic series about the everyday life of a blue donkey with big glasses and his mischievous piglet pal. In this volume, we explore Ariol''s close-knit home life with his mom and dad. When counting all the love flowing between parents and kid, this little family of three suddenly feels big, warm, and wonderfully chaotic!', '„Ariol“ je omiljeni francuski serijal stripova o svakodnevici simpatičnog plavog magarenca s naočarima i njegovog najboljeg druga prasenceta. U devetom tomu, Emanuel Giber i Mark Butavan vode nas pravo u Ariolov dom: tata, mama i Ariol čine složnu magareću porodicu punu prepoznatljivih zgoda, nježnosti i zaraznog humora.', 'Добрый, безумно смешной и жизненный комикс о том, как здорово (и шумно!), когда в семье все друг друга искренне любят.', 'A tender, laugh-out-loud graphic novel that captures the pure joy and delightful chaos of everyday family love.', 'Nježan i urnebesno duhovit strip koji savršeno dočarava toplinu i slatki haos jedne srećne porodice.', '/covers/DP-0541.webp', '#4178be', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","animals","friends"]', '["comics","family","humor","growing up","everyday life"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большой-сюрприз-для-маленькой--542', 'DP-0542', 'Большой сюрприз для маленькой лягушки', 'Ariol: A Big Surprise for a Little Frog', 'Ariol: Veliko iznenađenje za malu žabu', 'том 7', 'Emmanuel Guibert, Marc Boutavant', 'Emanuel Giber, Mark Butavan', '', '', NULL, NULL, 8, 16, 'middle', 'Ну и ну! Ариоль купил подарок Ванессе, немного застенчивой лягушке из своего класса. Зачем, интересно знать?.. Тем более что Рамоно с Петулой от этого не в восторге… А может, всё дело в Бизбиль?.. Ответ на эти и многие другие таинственные вопросы вам откроет «Большой сюрприз для маленькой лягушки»!', 'Good grief! Ariol bought a secret present for Vanessa, the shy little frog in his class. What could that be about? Ramono and Petula are definitely not thrilled... and how does Bizbille fit into all of this? Discover all the hilarious schoolyard drama in this heartwarming volume of Ariol''s adventures!', 'Gle čuda! Ariol je kupio poklon za Vanesu, stidljivu žabicu iz svog razreda. Zašto li je to uradio?.. Ramono i Petula uopšte nijesu oduševljeni, a možda sve to ima veze s Bizbil?.. Otkrijte sve školske tajne i simpatične nezgode u ovom veselom stripu!', 'Любимый ослик Ариоль снова попадает в водоворот школьных интриг, детской влюблённости и уморительных недоразумений!', 'Everyone''s favorite blue donkey Ariol is back, navigating school crushes, classroom gossip, and lots of laughs!', 'Omiljeni plavi magarčić Ariol ponovo upada u vrtlog školskih simpatija, tajni i urnebesnih nestašluka!', '/covers/DP-0542.webp', '#58a362', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","animals"]', '["ariol","comics","school","friendship","humor"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('господин-п-с-543', 'DP-0543', 'Господин Пёс', 'Mr. Dog', 'Gospodin Pas', '', 'Emmanuel Guibert, Marc Boutavant', 'Emanuel Giber, Mark Butavan', '', '', NULL, NULL, 8, 16, 'middle', 'Господин пёс — это мсье Лебарбос, классный руководитель Ариоля. Высокий спаниель в очках редко бывает выбрит до блеска, зато неизменным блеском отличаются его замечательные уроки! Ведь у него в запасе всегда есть увлекательная игра или смешная история, чтобы сделать материал понятным. Не верите? Тогда открывайте тетради, берите ручки и слушайте…', 'Mr. Dog is Monsieur Lebarbos, Ariol''s beloved homeroom teacher. A tall, bespectacled spaniel who rarely bothers with a clean shave, his lessons, however, shine brilliantly! He always has an engaging game or a funny story up his sleeve to make tricky subjects easy and fun. Don''t believe it? Open your notebooks, grab your pens, and get ready to listen!', 'Gospodin Pas je gospodin Lebarbos, Ariolov omiljeni razredni starješina. Visoki španijel s naočarima rijetko je svježe obrijan, ali su zato njegovi časovi uvijek nevjerovatno zanimljivi! U rukavu uvijek ima spremnu zabavnu igru ili smiješnu priču koja gradivo čini lakim i razumljivim. Ne vjerujete? Otvorite sveske, pripremite olovke i uživajte!', 'Встречайте лучшего учителя в мире: пусть он лохмат и не брит, зато на его уроках никто и никогда не скучает!', 'Meet the coolest teacher around: he might be scruffy and unshaven, but his classes are pure, unforgettable fun!', 'Upoznajte najboljeg nastavnika na svijetu: možda jeste čupav i neobrijan, ali na njegovim časovima nikome nikad nije dosadno!', '/covers/DP-0543.webp', '#d35400', 'comics', 'ru', 'available', 'м ю', '["funny","friends","animals"]', '["ariol","school","teacher","comics","humor"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-ослик-как-вы-и-я-том-544', 'DP-0544', 'Маленький ослик, как вы и я том 1', 'Ariol: Just Like You and Me (Vol. 1)', 'Ariol: Mali magarac kao vi i ja (Tom 1)', '', 'Emmanuel Guibert, Marc Boutavant', 'Emanuel Giber, Mark Butavan', '', '', NULL, NULL, 8, 16, 'middle', 'Ариоль — обычный маленький ослик в очках. Он живёт в пригороде, со своими мамой и папой. Его лучший друг — поросёнок, его классный руководитель — огромный пёс, а учитель физкультуры — толстый петух. Иными словами, Ариоль точно такой же, как вы и я.', 'Ariol is an ordinary little donkey who wears glasses. He lives in the suburbs with his mom and dad. His best friend is a piglet, his homeroom teacher is a giant dog, and his gym coach is a plump rooster. In other words, Ariol is just like you and me.', 'Ariol je običan mali magarac sa naočarima. Živi u predgrađu sa mamom i tatom. Njegov najbolji drug je prase, razredni starješina mu je ogroman pas, a nastavnik fizičkog punački pijetao. Drugim riječima, Ariol je baš kao vi i ja.', 'Забавный и невероятно жизненный комикс о школьных буднях, в котором каждый узнает себя и своих одноклассников!', 'A hilarious and deeply relatable comic about school days, where everyone will spot themselves and their classmates!', 'Urnebesan i nevjerovatno životan strip o školskim danima u kom će svako prepoznati sebe i svoje drugare iz klupe!', '/covers/DP-0544.webp', '#4a90e2', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","animals"]', '["comics","school","friendship","humor","animals"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('танцуют-все--545', 'DP-0545', 'Танцуют все!', 'Everybody Dance!', 'Svi na ples!', '', 'Emmanuel Guibert, Marc Boutavant', 'Emanuel Giber, Mark Butavan', '', '', NULL, NULL, 8, 16, 'middle', 'Танцуют все! Девчонки и мальчишки, ослята и поросята! И даже мсье Лебарбос, строгий учитель, выделывает уморительные коленца. Но что это? Быть не может! Петула в объятиях Ариоля! И пусть это всего лишь танец, лиха беда начало…', 'Everybody dance! Boys and girls, little donkeys and piglets alike! Even Monsieur Lebarbos, the strict teacher, is busting hilarious moves. But wait—can it really be? Petula in Ariol''s arms! Even if it''s just a slow dance, it''s already a big step for true love...', 'Svi na ples! Djevojčice i dječaci, magarenca i prasići! Čak i strogi učitelj gospodin Lebarbos izvodi urnebesne korake. Ali čekaj malo... Je li moguće? Petula u Ariolovom zagrljaju! Iako je to samo običan ples, dobar početak obećava mnogo...', 'Весёлая школьная дискотека с Ариолем, где сбываются самые сокровенные мечты маленького ослика!', 'A hilarious school dance comic where our favorite donkey Ariol gets the dance of his dreams!', 'Urnebesna školska žurka s Ariolom u kojoj se ostvaruju najslađi snovi jednog malog magarenca!', '/covers/DP-0545.webp', '#4a90e2', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","animals"]', '["ariol","comics","school","first crush","humor"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кот-да-не-тот-546', 'DP-0546', 'Кот, да не тот', 'Ariol: Not Quite That Cat', 'Ariol: Mačak, al'' ne taj', '', 'Emmanuel Guibert, Marc Boutavant', 'Emanuel Giber, Mark Butavan', '', '', NULL, NULL, 8, 16, 'middle', 'Тибер — лучший враг Ариоля. Этот задиристый кот обожает дразниться и высмеивать всех и вся, даже Шевалье Мустанга. А знаете, что самое страшное? Похоже, Петула неравнодушна к несносному грубияну! Как же спокойно в классе было бы без него…', 'Tiberge is Ariol''s ultimate frenemy. This cheeky cat loves teasing and mocking everyone and everything, even the mighty Chevalier Cheval! And do you know what the worst part is? Petula actually seems to fancy this insufferable bully! Life in the classroom would be so much quieter without him...', 'Tiber je Ariolov najbolji neprijatelj. Ovaj drski mačak obožava da zadirkuje i ismijava sve oko sebe, čak i Viteza Mustanga! A znate li šta je najgore? Izgleda da Petula uopšte nije ravnodušna prema ovom nepodnošljivom grubijanu! Eh, kako bi u razredu bilo mirno bez njega...', 'Школьные страсти, безответная влюбленность и несносный задира — безумно смешная и жизненная история о том, как ужиться с классным «врагом номер один»!', 'School drama, unrequited crushes, and a cheeky rival make this Ariol adventure a delightfully funny look at surviving your classroom frenemy!', 'Školske drame, skrivene simpatije i vječiti rival čine ovaj strip urnebesno smiješnim vodičem kroz preživljavanje onih koji nas najviše nerviraju!', '/covers/DP-0546.webp', '#e86b32', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","animals"]', '["comics","school life","ariol","rivalry","friendship","humor"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('могучий-кролик-547', 'DP-0547', 'Могучий кролик', 'The Mighty Rabbit', 'Moćni zec', '', 'Emmanuel Guibert, Marc Boutavant', 'Emanuel Giber, Mark Butavan', '', '', NULL, NULL, 8, 16, 'middle', 'Финтифлю — могучий кролик из класса Ариоля. Он обожает физкультуру и всегда ходит в спортивном костюме. На этой неделе ему будут ставить зубной аппарат, чтобы исправить прикус и улучшить произношение. Впрочем, насчет последнего у Финтифлю свое мнение: «А фто не так ф моим проивнофением?»', 'Fintiflyu is the mighty rabbit from Ariol''s class. He adores gym class and practically lives in his sports tracksuit. This week, he is getting braces to fix his bite and improve his pronunciation. Though Fintiflyu himself doesn''t see the problem: ''Whath wrong with my thpeech anyway?''', 'Fintifli je moćni zec iz Ariolovog razreda. Obožava fizičko i nikada ne skida trenerku. Ove sedmice dobija protezu kako bi ispravio zagriz i popravio izgovor. Mada, on sam ne vidi problem: ''A šta to fali mom govou?''', 'Остроумный и трогательный комикс о том, что новенькие брекеты ничуть не мешают оставаться главным школьным супергероем!', 'A witty, heartfelt comic showing that new braces definitely won''t stop you from being your school''s greatest superhero!', 'Duhovit i topao strip koji dokazuje da fiksna proteza nimalo ne smeta da budeš glavni školski superheroj!', '/covers/DP-0547.webp', '#e65c00', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","animals"]', '["comics","school life","braces","humor","animals"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('муха-горюха-548', 'DP-0548', 'Муха-горюха', 'Mukha-Goryukha', 'Muha-gorjuha', '5', '5', '5', '', '', NULL, NULL, 8, 16, 'middle', '', 'An inventive indie comic reimagining folklore through the eyes of the legendary fly who started it all, blending quirky humor, expressive graphics, and unexpected twists.', 'Inovativni indi strip koji oživljava motive iz bajki kroz oči legendarne muve, spajajući uvrnuti humor, ekspresivan crtež i neočekivane preokrete.', 'Забудьте всё, что вы знали о теремке: эта муха покажет, как выглядит настоящий авторский комикс с характером!', 'Forget the fairy tale you thought you knew—this charismatic fly is here to show what real indie comic grit looks like!', 'Zaboravite staru bajku: ova neobična muva donosi pravi autorski strip pun humora i stava!', '/covers/DP-0548.webp', '#5b7048', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","adventure","animals"]', '["comics","folklore","humor","insects","indie"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лучший-в-мире-поросенок-549', 'DP-0549', 'Лучший в мире поросенок', 'The World''s Best Piglet', 'Najbolje prase na svijetu', 'том 3', 'Vol. 3', 'Tom 3', '', '', NULL, NULL, 8, 16, 'middle', '', 'Dive into the third volume of hilarious graphic adventures featuring the world''s most charming and resilient piglet. Packed with visual gags, wild antics, and heartwarming loyalty, this comic will make readers of all ages squeal with delight.', 'Zaronite u treći tom urnebesnih strip avantura u kojima glavnu riječ vodi najšarmantnije prase na svijetu. Prepun vizuelnih šala, neobuzdanih nestašluka i tople odanosti, ovaj strip će nasmijati čitaoce svih uzrasta.', 'Осторожно: этот неугомонный поросёнок мгновенно покорит ваше сердце и докажет, что любая передряга — это лишь повод для отличной шутки!', 'Warning: this unstoppable little piglet will instantly steal your heart and prove that every puddle of trouble is just a funny adventure in disguise!', 'Oprez: ovo neodoljivo prase će vam začas osvojiti srce i dokazati da je svaka nevolja samo povod za odličnu zabavu!', '/covers/DP-0549.webp', '#f28482', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","animals","adventure"]', '["comics","piglet","humor","friendship","graphic novel"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('телячьи-нежности-550', 'DP-0550', 'Телячьи нежности', 'Puppy Love', 'Teleće nježnosti', '', 'Unknown', 'Nepoznat autor', '', '', NULL, NULL, 8, 16, 'middle', '', 'A vibrant and heartfelt graphic novel exploring the roller coaster of growing up, teenage drama, awkward romantic dilemmas, and true friendship.', 'Upečatljiv i iskren strip o odrastanju, tinejdžerskim dramama, nespretnim prvim simpatijama i pravom prijateljstvu.', 'Идеальный комикс для всех, кто хоть раз краснел от смущения или прятал улыбку, переживая первую любовь!', 'The perfect comic for anyone who has ever blushed over a secret crush or survived the awkward drama of first love!', 'Savršen strip za svakoga ko se ikada zacrvenio od stida ili preživio slatke drame prvih simpatija!', '/covers/DP-0550.webp', '#e27396', 'comics', 'ru', 'available', 'Категория: Космический почтальон', '["funny","friends","real"]', '["comics","growing up","first crush","friendship","school life"]', 1792836322698, 1792845652048);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('все-бегут-летят-и-скачут-551', 'DP-0551', 'Все бегут, летят и скачут', 'Everyone Runs, Flies, and Gallops', 'Svi trče, lete i skaču', 'Даниил Хармс', 'Daniil Kharms', 'Danil Harms', 'Игорь Олейников', 'Азбука', NULL, NULL, 3, 12, 'little', 'В этом издании озорные, весёлые, искромётные стихи Хармса прозвучали совсем по-новому благодаря удивительным, виртуозным иллюстрациям замечательного художника Игоря Олейникова, который в 2018 году получил золотую медаль Международной премии имени Андерсена – самую престижную награду в области детской книги.', 'In this edition, the mischievous, sparkling, and delightfully eccentric poems of Daniil Kharms come alive anew thanks to virtuosic illustrations by Igor Oleynikov, winner of the prestigious 2018 Hans Christian Andersen Award.', 'U ovom izdanju, vragolasti, veseli i iskričavi stihovi Danila Harmsa zvuče sasvim novo zahvaljujući virtuoznim ilustracijama Igora Olejnjikova, dobitnika prestižne Andersenove nagrade 2018. godine.', 'Пристегните ремни: озорные стихи Хармса в иллюстрациях лауреата премии Андерсена Игоря Олейникова закружат вас в настоящем поэтическом вихре!', 'Fasten your seatbelts: Kharms’s whirlwind nonsense poetry and Oleynikov’s award-winning art make for an unforgettable, joyful ride!', 'Vežite se: vragolasti Harms i nagrađivane ilustracije Olejnjikova pretvaraju svaku stranicu u pravi razigrani vihor!', '/covers/DP-0551.webp', '#3b7a8a', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","animals"]', '["poetry","humor","nonsense","animals","illustrated"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('баллада-о-маленьком-буксире-552', 'DP-0552', 'Баллада о маленьком буксире', 'The Ballad of a Little Tugboat', 'Balada o malom remorkeru', 'Даниил Хармс', 'Daniil Kharms', 'Danil Harms', 'Игорь Олейников', 'Азбука', NULL, NULL, 3, 12, 'little', '«Баллада о маленьком буксире» — одно из детских стихотворений Иосифа Бродского, ставшее благодаря публикации в 1962 году в журнале «Костёр» первым его стихотворением, увидевшим свет в СССР. Иллюстрации к этой книге сделал Игорь Олейников — художник и мультипликатор, лауреат Болонской книжной выставки.', '"The Ballad of a Little Tugboat" is a classic children''s poem by Joseph Brodsky and notably the very first poem he had officially published in the USSR, appearing in 1962 in the magazine "Kostyor". This edition features rich, evocative artwork by Igor Oleynikov, a renowned animator and Bologna Children''s Book Fair laureate.', '„Balada o malom remorkeru“ jedna je od najpoznatijih pjesama za djecu Josifa Brodskog, koja je 1962. godine u časopisu „Kostjor“ postala njegova prva pjesma objavljena u SSSR-u. Knjigu krase izuzetne ilustracije Igora Olejnjikova, proslavljenog umjetnika, animatora i dobitnika prestižne nagrade na Sajmu dječje knjige u Bolonji.', 'Трогательная поэтическая ода скромному труженику гавани, который преданно помогает великанам-кораблям уйти в далёкое плавание.', 'A poignant poetic tribute to an unsung harbor hero who faithfully guides majestic ocean liners out toward the horizon.', 'Dirljiva i nježna pjesma o neumornom lučkom radniku koji vjerno pomaže velikim brodovima da zaplove u daleki svijet.', '/covers/DP-0552.webp', '#284d72', 'poetry', 'ru', 'available', 'Категория: стихи', '["real","adventure"]', '["poetry","sea","ships","harbor","classic"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('баллада-о-маленьком-буксире-553', 'DP-0553', 'Баллада о маленьком буксире', 'The Ballad of a Little Tugboat', 'Balada o malom remorkeru', 'Иосиф Бродский', 'Joseph Brodsky', 'Josif Brodski', 'Кася Денисевич', 'Подписные издания', NULL, NULL, 3, 12, 'little', 'В жизни каждого из нас есть похожие один на другой дни и сказочные сны, ошеломляющие ночью; рутина и приключения; обязанности и мечты. Сны заканчиваются пробуждением, но иногда запоминаются и будто бы переносятся в реальность. Мечты сбываются нечасто, но как тоскливо было бы нам без них. Об этом — «Баллада о маленьком буксире», впервые напечатанная в 1962 году в ленинградском журнале «Костёр». Для Иосифа Бродского, которому было тогда двадцать два года, эта публикация стала первой и почти на четверть века одной из очень немногих на родине. Кажется, Бродский предчувствовал испытания, ждавшие его впереди. Сердце портового буксира, который словно запрещает себе мечтать, принадлежит океану, и мечта сама сбывается рядом с ним — в порту, на набережных Невы, за окном. И в конце концов увлекает его за собой, вдаль. Молодой поэт и тем более его маленький герой не говорят об этом прямо, для них это, кажется, только догадка, зримые черты которой придала художница Кася Денисевич.', 'Every life is made of routine duties and boundless dreams, repetitive days and breathtaking voyages in the mind. ''The Ballad of a Little Tugboat'', first published in 1962 in the children''s magazine Koster, was twenty-two-year-old Joseph Brodsky''s debut in his homeland. The hardworking harbor tugboat faithfully guides giant ocean liners, secretely dreaming of distant shores while staying true to his post. Kasia Denisevich''s tender, evocative illustrations breathe new life into Brodsky''s luminous poem about purpose, devotion, and quiet longing.', 'U svačijem životu prepliću se svakodnevne obaveze i čudesni snovi, rutina i čežnja za daljinama. „Balada o malom remorkeru“, prvi put objavljena 1962. godine, bila je književni prvenac dvadesetdvogodišnjeg Josifa Brodskog u domovini. Maleni lučki remorker neumorno pomaže prekookeanskim brodovima da uplove u luku, sanjareći o plavim prostranstvima, ali ostajući vjeran svom mjestu pod suncem. Topla i poetska priča uz divne ilustracije Kasje Denisevič govori o tome koliko je važan svaki, pa i najmanji posao na svijetu.', 'Пронзительная и невероятно красивая поэтическая история о том, как важно быть на своём месте и при этом никогда не забывать мечтать.', 'A deeply touching, lyrical masterpiece about finding meaning right where you are while still letting your heart drift to the open sea.', 'Dirljiva i prelijepa poetska priča o tome kako je važno voljeti svoj poziv, a pritom nikada ne prestati sanjariti o dalekim morima.', '/covers/DP-0553.webp', '#385b78', 'poetry', 'ru', 'available', 'Категория: стихи', '["real","adventure"]', '["стихи","корабли","море","мечты","классика"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('иван-иваныч-самовар-554', 'DP-0554', 'Иван Иваныч самовар', 'Ivan Ivanych Samovar', 'Ivan Ivanič Samovar', 'Даниил Хармс', 'Daniil Kharms', 'Danil Harms', 'Надежда Богуславская', 'Эксмо', NULL, NULL, 3, 12, 'little', 'Имя Даниила Хармса, автора замечательных произведений для детей, известно не только в России, но и далеко за её пределами. Его стихи, сказки, занимательные истории с большим удовольствием читают и дети и взрослые. Обязательно познакомьте вашего ребёнка с творчеством Даниила Хармса - подарите ему книгу "Иван Иваныч Самовар". В ней собраны самые известные стихи, картинки к которым нарисовал талантливый художник Надежда Богуславская', 'The name of Daniil Kharms, master of eccentric and delightful children''s literature, is celebrated worldwide. His inventive poems, fairy tales, and playful stories bring immense joy to kids and adults alike. Introduce your little ones to Kharms'' unique brilliance with this collection of his most beloved poems, richly brought to life by illustrator Nadezhda Boguslavskaya.', 'Ime Danila Harmsa, tvorca izuzetnih djela za djecu, poznato je daleko van granica njegove domovine. Njegove pjesme, bajke i duhovite priče s uživanjem čitaju i djeca i odrasli. Upoznajte svoje dijete sa čudesnim Harmskovim stvaralaštvom kroz ovu zbirku njegovih najpoznatijih stihova, obogaćenu divnim ilustracijama Nadežde Boguslavske.', 'Озорные, ритмичные и ни на что не похожие стихи Хармса научат детей смеяться во весь голос и пить чай с настоящим размахом!', 'Kharms’ delightfully absurd and rhythmic poems will have the whole family giggling and boiling with tea-time joy!', 'Harmskovi vrckavi i ritmični stihovi nasmijaće cijelu porodicu i pretvoriti svaku čajanku u pravu avanturu!', '/covers/DP-0554.webp', '#c86d3b', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","friends"]', '["poetry","humor","tea party","classics","rhymes"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('птица-в-клетке-555', 'DP-0555', 'Птица в клетке', 'Bird in a Cage', 'Ptica u kavezu', 'Олег Григорьев', 'Oleg Grigoryev', 'Oleg Grigorjev', '', 'Лимбус пресс', NULL, NULL, 3, 12, 'little', '"Птица в клетке" наиболее полное собрание стихов и прозы известного ленинградского поэта Олега Григорьева (1943-1992). Книга проиллюстрирована работами фотохудожников, принадлежащих, как и сам Григорьев, петербургскому андеграунду.', '"Bird in a Cage" is the most comprehensive collection of poetry and short prose by the celebrated Leningrad underground poet Oleg Grigoryev (1943–1992). The volume is uniquely illustrated with photography by fellow Saint Petersburg underground artists.', '"Ptica u kavezu" je najpotpunija zbirka poezije i proze čuvenog lenjingradskog pjesnika Olega Grigorjeva (1943–1992). Knjiga je obogaćena autentičnim fotografijama umjetnika iz peterburškog andergraunda.', 'Озорные, парадоксальные и до колик смешные стихи питерского классика, в которых привычный мир весело переворачивается с ног на голову!', 'Mischievous, absurd, and laugh-out-loud funny poems from a Saint Petersburg legend, playfully turning everyday life upside down!', 'Nestašne, apsurdne i nevjerovatno duhovite pjesme peterburškog majstora koje svakodnevicu okreću naglavačke!', '/covers/DP-0555.webp', '#4a443f', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","real"]', '["poetry","humor","absurdism","classics","childhood"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-битвы-и-сражения-556', 'DP-0556', 'Про битвы и сражения', 'About Battles and Skirmishes', 'O bitkama i bojevima', 'Эдуард Шендерович', 'Eduard Shenderovich', 'Eduard Šenderovič', 'Соня Уткина', 'Самокат', NULL, NULL, 3, 12, 'little', 'Настоящая детская поэзия от Эдуарда Шендеровича: яркие, веселые и запоминающиеся стихи для мальчиков (и девочек тоже) всех возрастов.', 'Genuine children''s poetry by Eduard Shenderovich: vibrant, lively, and memorable verses brimming with boyish daring and spirited humor for readers of all ages.', 'Prava dječja poezija Eduarda Šenderoviča: živopisni, veseli i pamtljivi stihovi puni hrabrosti i humora za dječake (i djevojčice takođe) svih uzrasta.', 'Озорные и ритмичные стихи о рыцарских подвигах и эпических битвах, которые так здорово читать вслух во весь голос!', 'Mischievous, rhythmic verses about brave feats and epic battles meant to be declaimed aloud at the top of your lungs!', 'Nestašni i ritmični stihovi o viteškim podvizima i epskim bitkama koje je najljepše čitati naglas iz sveg glasa!', '/covers/DP-0556.webp', '#c8432b', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","adventure"]', '["poetry","battles","knights","humor","rhymes"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-некогда-557', 'DP-0557', 'Когда некогда', 'When There''s No Time', 'Kad se nema vremena', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Ирина Дешалыт', 'Самокат', NULL, NULL, 3, 12, 'little', '"Играет папа в переходе. Над ним проходит магистраль. Нам с мамой очень надоело Таскать туда ему рояль".', '"Dad plays piano in the subway hall, traffic rumbles right above. Mom and I are tired of dragging his grand piano there with love." A brilliant collection of witty, absurd, and delightfully cheeky poems about everyday childhood, school pranks, and eccentric parents.', '"Tata svira klavir u prolazu, gore tutnji magistrala. Mami i meni je već dosadilo da mu tamo vučemo klavir." Sjajna zbirka duhovitih, apsurdnih i simpatično nestašnih pjesama o djetinjstvu, školi i neobičnim roditeljima.', 'Осторожно: эти озорные и парадоксальные стихи вызывают неудержимый хохот как у детей, так и у вечно занятых взрослых!', 'Caution: Givargizov''s mischievously absurd poems are guaranteed to cause uncontrollable giggles in both kids and busy parents!', 'Oprez: ove vesele i luckaste pjesme izazivaju nekontrolisane napade smijeha i kod djece i kod zauzetih roditelja!', '/covers/DP-0557.webp', '#e2583e', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","real"]', '["poetry","humor","family","absurd","childhood"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('собиратель-сосулек-558', 'DP-0558', 'Собиратель сосулек', 'The Icicle Collector', 'Sakupljač ledenica', 'Михаил Яснов', 'Mikhail Yasnov', 'Mihail Jasnov', 'Зина Сурова', 'Самокат', NULL, NULL, 3, 12, 'little', 'Поэт Михаил Яснов давно любим и маленькими читателями, и их родителями. Его книги для малышей широко известны. В новой книге "Собиратель сосулек" он не только остается верен своей аудитории, но и расширяет ее, во многих своих стихах обращаясь к подросткам, и находит для этого неожиданные сюжеты и темы. Это стихи веселые и лирические, философские и игровые; как всегда, Михаилу Яснову важно подчеркнуть, насколько богат наш язык, какие в нем открываются тайны и возможности. А тогда оказывается, что с юным читателем можно говорить о самых серьезных вещах, и делать это тактично, тонко и поэтически совершенно. Для младшего и среднего школьного возраста.', 'Beloved children''s poet Mikhail Yasnov presents a sparkling collection of verses that bridges childhood and youth. In ''The Icicle Collector'', playful linguistic games stand shoulder to shoulder with quiet, philosophical reflections on growing up. With characteristic warmth and rhythmic grace, Yasnov proves that poetry can address life''s biggest questions with lightness, wit, and sublime tenderness.', 'Omiljeni dječji pjesnik Mihail Jasnov donosi zbirku stihova koja spaja djetinjstvo i odrastanje. U knjizi ''Sakupljač ledenica'', razigrane jezičke bravure stoje rame uz rame s tihim, filozofskim razmišljanjima o svijetu oko nas. S prepoznatljivom toplinom i ritmičkom lakoćom, Jasnov pokazuje kako poezija može govoriti o najvažnijim temama suptilno, duhovito i s mjerom.', 'Остроумные и трогательные стихи, в которых даже весенняя капель звенит как настоящая музыка взросления.', 'Clever and tender verses that catch the fleeting magic of childhood and turn every melting icicle into pure music.', 'Duhoviti i dirljivi stihovi koji hvataju prolaznu čaroliju djetinjstva i pretvaraju svaku ledenicu u čistu muziku.', '/covers/DP-0558.webp', '#3b82a6', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","real"]', '["poetry","childhood","growing up","wordplay","humor"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('луна-за-диваном-559', 'DP-0559', 'Луна за диваном', 'The Moon Behind the Sofa', 'Mjesec iza kauča', 'Михаил Есеновский', 'Mikhail Yesenovsky', 'Mihail Jesenovski', 'Илья Донец, Рита Щетинская', 'Жук', NULL, NULL, 3, 12, 'little', 'Писать смешно и трогательно - отличительная черта творчества Михаила Есеновского. Именно такой и получилась новая книга его стихов - трогательной и смешной. И ещё умной. Но физика и астрономия здесь ни при чём. Они служат лишь отправной точкой. А дальше из законов мироздания Есеновский выводит свои собственные законы - "квантовую механику" нашей повседневной жизни, насыщенной невероятными событиями, происходящими в школе и дома, в магазине и зоопарке, в Новосибирске и Ялте, на Луне и Альфе Центавра.', 'Writing both hilariously and tenderly is Mikhail Yesenovsky''s hallmark, and this collection of poems is wonderfully witty, clever, and heartwarming. Using playful physics and backyard astronomy as jumping-off points, the poet invents his own whimsical ''quantum mechanics'' of everyday childhood life—from school and the zoo to the Moon and Alpha Centauri.', 'Pisati duhovito i dirljivo prepoznatljiv je stil Mihaila Jesenovskog, a upravo je takva i ova zbirka pjesama — pametna, topla i beskrajno smiješna. Koristeći osnove fizike i astronomije samo kao odskočnu dasku, pjesnik stvara sopstvene zakone svakodnevice pune nevjerovatnih dogodovština: u školi, zoološkom vrtu, na Mjesecu ili čak na Alfi Kentauri.', 'Приготовьтесь хохотать и разглядывать квантовые законы Вселенной прямо в собственной гостиной!', 'Get ready to giggle and uncover the whimsical laws of the cosmos hiding right behind your living room sofa!', 'Pripremite se za glasan smijeh i otkrivanje kosmičkih zakona skrivenih pravo iza vašeg kauča!', '/covers/DP-0559.webp', '#394b73', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","magic"]', '["poetry","humor","space","imagination","everyday life"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('письмо-с-парохода-560', 'DP-0560', 'Письмо с парохода', 'A Letter from a Steamboat', 'Pismo s parobroda', 'Григорий Кружков', 'Grigory Kruzhkov', 'Grigorij Kruškov', 'Таня Кормер', 'Самокат', NULL, NULL, 3, 12, 'little', 'Замечательный поэт и мастер художественного перевода Григорий Кружков, более известный взрослым читателям, теперь решил поделиться и с детьми своим талантом. В каждом стихотворении Кружкова бросается в глаза любовь к парадоксальности, неожиданным ходам, легкому абсурду, который на поверку оказывается реальностью, только увиденной глазами не взрослого, а ребенка. Легкость словесной игры сочетается в поэзии Григория Кружкова с очень личной интонацией, словно поэт обращается к каждому своему читателю - большому ли, маленькому - как к близкому другу: "Я пишу тебе стихи, каждый стих с картинкой..."', 'Renowned poet and master translator Grigory Kruzhkov brings his sparkling wit and gentle absurdity to young readers. Each poem turns everyday life into playful wonder, capturing the whimsical perspective of a child. Written with an intimate and affectionate tone, this collection feels like an envelope full of rhymes sent directly to a cherished friend.', 'Izvanredni pjesnik i majstor književnog prevođenja Grigorij Kruškov dijeli svoj razigrani dar sa najmlađima. U svakoj pjesmi krije se vedri apsurd, neočekivani obrti i stihovi koji svijet prikazuju kroz iskrene dječje oči, obraćajući se čitaocu toplo i prisno, poput dragog prijatelja s dalekog putovanja.', 'Озорные и душевные стихи мастера слова, которые читаются как тёплое письмо от лучшего друга из дальнего плавания!', 'Witty, rhythmic, and delightfully absurd poems that feel just like a warm letter mailed from an old friend on a sunny voyage!', 'Duhoviti i topli stihovi koji se čitaju kao drago pismo od najboljeg prijatelja s dalekog morskog putovanja!', '/covers/DP-0560.webp', '#3d708f', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","adventure","friends"]', '["стихи","юмор","море","игра слов","детская поэзия"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прогульщик-и-прогульщица-561', 'DP-0561', 'Прогульщик и прогульщица', 'The Truant Boy and the Truant Girl', 'Markirant i markirantkinja', 'Марина Бородицкая', 'Marina Boroditskaya', 'Marina Borodickaja', 'Ирина Иванова', 'Самокат', NULL, NULL, 3, 12, 'little', 'В новую книгу одной из лучших русских современных поэтесс Марины Бородицкой вошли и уже давно известные, многими любимые стихотворения для маленьких читателей, и новые, написанные немножко "на вырост". Лирические и смешные, ее стихи станут близкими самым разным читателям: это и воспоминания о раннем детстве, и сегодняшние насущные проблемы школьного бытия, нередко облаченные в игровую, веселую форму, и детали самого разного детского быта, старого и современного.', 'This collection by one of Russia''s finest contemporary children''s poets, Marina Boroditskaya, brings together beloved classic verses and fresh poems written ''to grow into.'' Lyrical, witty, and delightfully observant, these poems celebrate childhood memories, the everyday adventures of school life, and the tender, funny details of growing up.', 'Ova zbirka jedne od najomiljenijih savremenih dječjih pjesnikinja, Marine Borodickaje, objedinjuje dobro poznate stihove za mališane, kao i nove pjesme „za odrastanje“. Lirske i duhovite, njene pjesme dočaravaju rano djetinjstvo, školske muke i radosti, te tople i smiješne detalje svakodnevnog dječjeg života.', 'Эти озорные и чуткие стихи лучше любого будильника разбудят улыбку — даже если за окном пасмурно, а в школу совсем не хочется!', 'These playful and heartwarming verses will coax a bright smile out of anyone, even on mornings when walking to school feels impossible!', 'Ovi razigrani i topli stihovi izmamiće osmijeh svakome, čak i onih jutara kada se nikome baš ne ide u školu!', '/covers/DP-0561.webp', '#e68436', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","real","friends"]', '["poetry","school life","humor","childhood","growing up"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('яблочки-пятки-562', 'DP-0562', 'Яблочки-пятки', 'Little Apples, Tiny Heels', 'Jabukice-petice', 'Анастасия Орлова', 'Anastasia Orlova', 'Anastasija Orlova', '', 'Гриф', NULL, NULL, 3, 12, 'little', 'Красочно иллюстрированная книга стихов Анастасии Орловой для самых маленьких.', 'A colorfully illustrated collection of gentle nursery rhymes and playful poems by Anastasia Orlova, crafted especially for the very youngest readers.', 'Raskošno ilustrovana zbirka nježnih i razigranih pjesmica Anastasije Orlove, stvorena posebno za najmlađe čitaoce.', 'Тёплые, звонкие и ласковые стихи-пестушки, от которых так и хочется щекотать детские пяточки и смеяться вместе!', 'Warm, bouncy, and tender rhymes that turn everyday moments into tickly, giggly cuddle sessions!', 'Tople, ritmične i nježne pjesmice koje pretvaraju svaki dan u škakljivo maženje i najslađi smijeh!', '/covers/DP-0562.webp', '#e85d4e', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","real"]', '["poetry","rhymes","toddlers","growing up","family"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-осьминога-563', 'DP-0563', 'Про осьминога', 'About the Octopus', 'O hobotnici', 'Рената Муха', 'Renata Mukha', 'Renata Muha', 'Вера Марова', 'Октопус', NULL, NULL, 3, 12, 'little', 'Сборник стихов для детей до 3-х лет. С красочными иллюстрациями Веры Маровой.', 'A playful collection of charming verses crafted for the youngest listeners, featuring delightfully colorful illustrations by Vera Marova.', 'Razigrana zbirka šarmantnih stihova za najmlađe čitaoce, ukrašena vedrim i živopisnim ilustracijama Vere Marove.', 'Остроумные, лёгкие и невероятно добрые стихи Ренаты Мухи мгновенно рассмешат и малышей, и читающих им родителей!', 'Renata Mukha''s sparkling, witty verses bring effortless giggles to little listeners and parents alike!', 'Duhoviti i nježni stihovi Renate Muhe donose bezbroj osmijeha i najmlađim čitaocima i njihovim roditeljima!', '/covers/DP-0563.webp', '#2d7f9d', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","animals"]', '["poetry","animals","humor","rhymes","toddlers"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('посыпайте-голову-перцем-стихи--564', 'DP-0564', 'Посыпайте голову перцем. Стихи американских поэтов', 'Sprinkle Pepper on Your Head: Poems by American Poets', 'Pospite glavu biberom: Pjesme američkih pjesnika', 'Григорий Кружков', 'Grigory Kruzhkov', 'Grigorij Kruškov', 'Андрей Бондаренко', 'Детская литература', NULL, NULL, 3, 12, 'little', 'Знаете ли вы, где живёт пугливый дракончик по имени Пончик? И зачем медведь поселился в холодильнике? Или почему каждый день нужно посыпать голову перцем? Григорий Михайлович Кружков предлагает по-новому взглянуть на детскую американскую поэзию. Маленькие читатели познакомятся со множеством забавных и смешных историй. Они и весёлые, и грустные, и загадочные одновременно. Для младшего школьного возраста.', 'Do you know where a timid dragon named Donut lives? Or why a bear moved into a refrigerator? And why one might sprinkle pepper on their head every day? Master translator Grigory Kruzhkov offers a delightfully fresh look at American children''s verse, introducing young readers to a wonderland of whimsical, nonsensical, and heartwarming rhymes.', 'Da li znate gdje živi plašljivi zmajčić zvani Krofica? Ili zašto se medvjed uselio u frižider? A zašto bi trebalo svakog dana posuti glavu biberom? Izvanredni prevodilac Grigorij Kruškov pruža svjež i veseo pogled na američku dječju poeziju, vodeći mlade čitaoce kroz neobične, šaljive i tople stihove.', 'Задорные, озорные и парадоксальные стихи в гениальном переводе Григория Кружкова, над которыми от души хохочут и дети, и взрослые!', 'Cheeky, whimsical, and wonderfully absurd verses translated with dazzling wit that will make kids and grown-ups giggle aloud together!', 'Razigrani, otkačeni i maštoviti stihovi u maestralnom prevodu uz koje će se od srca smijati i djeca i roditelji!', '/covers/DP-0564.webp', '#d9432f', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","magic"]', '["стихи","переводная поэзия","юмор","небылицы","американская поэзия"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хорошо-что-я-такой-а-не-какой--565', 'DP-0565', 'Хорошо, что я такой, а не какой-нибудь другой', 'It''s Good That I''m Me and Not Somebody Else', 'Dobro je što sam ja ovakav, a ne neki drugi', 'Герман Лукомников', 'German Lukomnikov', 'German Lukomnikov', 'Коля Филиппов', 'Самокат', NULL, NULL, 3, 12, 'little', 'Стихи Германа Лукомникова и картинки Коли Филиппова созданы друг для друга. И для вас!', 'The playful, eccentric poems of German Lukomnikov and the whimsical drawings of Kolya Filippov were made for each other—and especially for you!', 'Razigrane, šašave pjesme Germana Lukomnikova i ilustracije Kolje Filipova stvorene su jedno za drugo — i za svakog od vas!', 'Озорные и уморительные микро-стихи, которые мгновенно поднимают настроение и учат любить свою неповторимость!', 'Mischievous, bite-sized poems bursting with wordplay that celebrate being completely, delightfully yourself!', 'Nestašne i urnebesne kratke pjesmice pune igara riječima koje slave radost toga da budeš baš svoj!', '/covers/DP-0565.webp', '#f05a36', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","real"]', '["poetry","humor","wordplay","self-acceptance"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('стихи-французских-поэтов-566', 'DP-0566', 'Стихи французских поэтов', 'Poems by French Poets', 'Pjesme francuskih pjesnika', 'Жак Превер', 'Jacques Prévert', 'Žak Prever', 'Таня Кормер', 'Самокат', NULL, NULL, 3, 12, 'little', 'Французские стихи для детей - большая редкость в нашей стране. Давно уже настало время, когда можно представить широкой аудитории читателей избранное из того, что уже было опубликовано, и новые переводы. Этим целям и должна служить предлагаемая книга, в которую входят стихи для детей признанных классиков французской поэзии ХХ века: Жака Превера, Мадлен Лей, Робера Десноса, Клода Руа и Рене де Обальдиа. Перевод с французского Михаила Яснова.', 'French children''s poetry is a rare and joyful treasure. Masterfully translated by Mikhail Yasnov, this anthology brings together whimsical, witty, and lyrical verses by iconic 20th-century French authors, including Jacques Prévert, Robert Desnos, Claude Roy, Madeleine Ley, and René de Obaldia.', 'Francuska poezija za djecu rijetko je i radosno blago. U virtuoznom prevodu Mihaila Jasnova, ova zbirka okuplja vesele, duhovite i lirske stihove velikih francuskih pjesnika dvadesetog vijeka, među kojima su Žak Prever, Rober Desnos, Klod Roa, Madlen Lej i Rene de Obaldija.', 'Настоящая парижская карусель из задорных, лёгких и парадоксальных стихов, которые так приятно читать вслух и декламировать на ходу!', 'A delightful Parisian carousel of breezy, witty, and playful verses that are an absolute joy to read out loud together!', 'Pravi pariski ringišpil razigranih, lepršavih i duhovitih stihova koje je pravo uživanje čitati naglas u jednom dahu!', '/covers/DP-0566.webp', '#356b88', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","magic"]', '["poetry","french literature","humor","rhymes","classics"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рабочая-азбука-567', 'DP-0567', 'Рабочая азбука', 'Working Alphabet', 'Radna azbuka', 'Иосиф Бродский', 'Joseph Brodsky', 'Josif Brodski', 'Игорь Олейников', 'Акварель', NULL, NULL, 3, 12, 'little', 'Иосиф Бродский - Нобелевский лауреат и один из крупнейших русских поэтов ХХ века - написал стихотворение "Рабочая Азбука", когда ему было немногим более двадцати лет. Как и многие другие его стихи для детей, оно учит ценить разнообразие жизни и радоваться самым простым, повседневным вещам. Иллюстрации к этой книге сделал Игорь Олейников - художник и мультипликатор, лауреат Болонской книжной выставки.', 'Written in his twenties by Nobel laureate Joseph Brodsky, ''Working Alphabet'' celebrates the dignity of diverse professions and the simple joys of everyday life. Paired with the extraordinary, atmospheric artwork of acclaimed artist Igor Oleynikov, this playful poetic primer turns learning letters into a vibrant tribute to makers, dreamers, and doers.', 'Napisana u mladosti nobelovca Josifa Brodskog, ''Radna azbuka'' slavi ljepotu različitih zanimanja i jednostavnih svakodnevnih stvari. Uz izuzetne ilustracije proslavljenog majstora Igora Olejnjikova, ovaj stihovani bukvar pretvara učenje slova u toplo i ritmično putovanje kroz svijet rada i zanata.', 'Нобелевский лауреат и гениальный иллюстратор показывают, что любая профессия — от плотника до поэта — полна поэзии и чудес!', 'A Nobel laureate and a master illustrator team up to show that every profession is pure poetry in disguise!', 'Nobelovac i majstorski ilustrator otkrivaju da svako zanimanje nosi u sebi pravu poeziju i čaroliju!', '/covers/DP-0567.webp', '#b85736', 'poetry', 'ru', 'available', 'Для старшего дошкольного и младшего школьного возраста.', '["real","funny"]', '["alphabet","professions","poetry","classic","illustrated"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('два-трамвая-568', 'DP-0568', 'Два трамвая', 'Two Trams', 'Dva tramvaja', 'Иомиф Бродский', 'Joseph Brodsky', 'Josif Brodski', 'Анна Десницкая', 'Самокат', NULL, NULL, 3, 12, 'little', 'Иллюстрации к книге родились не только из бумаги и красок, но и из картона, клея, трубочек для напитков, старых пуговиц, медной проволоки, крышек пластиковых бутылок. С их помощью появились сначала «герои» стихотворения — трамваи, а потом и вырос целый город — с улицами, домами, рельсами и жителями. Благодаря оформлению, напоминающему театральные декорации, действие «Двух трамваев» разыгрывается перед вами как будто на сцене, настолько объемными и живыми иллюстрации выглядят на бумаге. Благодаря им с детьми можно не только читать стихи, но и внимательно рассматривать картинки, пытаясь угадать, из чего все сделано.', 'The artwork for this poetic book was crafted not just with paper and paints, but with cardboard, glue, drinking straws, vintage buttons, copper wire, and bottle caps. Out of these materials arose the poem''s protagonists — two trams — and around them an entire bustling city with streets, rails, and residents. Designed like theatrical stage sets, the pages feel wonderfully three-dimensional and alive, inviting young readers to savor Brodsky''s verses while gleefully guessing what every charming detail is made of.', 'Ilustracije za ovu poetsku slikovnicu nijesu nastale samo od papira i boja, već i od kartona, ljepila, slamčica, starih dugmića, bakarne žice i čepova plastičnih flaša. Uz njihovu pomoć oživjeli su junaci ove pjesme — dva tramvaja — a zatim je izrastao i čitav grad sa ulicama, šinama i prolaznicima. Zahvaljujući scenografskom pristupu, priča se odvija kao na pravoj pozorišnoj sceni, podstičući djecu da pažljivo istražuju stranice i pogađaju od čega je svaki detalj napravljen.', 'Трогательная история Иосифа Бродского о дружбе двух трамваев в удивительном городе из картона, проволоки и пуговиц!', 'A tender poetic tale of friendship between two trams, rolling through a marvelous city built of cardboard, wire, and buttons!', 'Dirljiva pjesnička priča Josifa Brodskog o prijateljstvu dva tramvaja u čudesnom gradu od kartona, žice i dugmića!', '/covers/DP-0568.webp', '#c8523b', 'poetry', 'ru', 'available', 'Категория: стихи', '["friends","real"]', '["poetry","trams","city","friendship","collage"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жили-были-зайки-569', 'DP-0569', 'Жили-были зайки', 'Once Upon a Time There Lived Bunnies', 'Bili jednom zečići', 'Андрей Усачев', 'Andrey Usachev', 'Andrej Usačov', '', 'Вакоша', NULL, NULL, 3, 12, 'little', 'В книгу вошли стихотворения одного из самых популярных детских поэтов Андрея Усачёва. Остроумные и весёлые, они наполнены особым, "усачёвским" юмором и заставляют детей не только посмеяться, но и задуматься над некоторыми моментами в жизни. Вот почему его стихи так нравятся мальчишкам и девчонкам, и они не только с удовольствием читают их, но и легко заучивают наизусть, чем очень радуют своих родителей.', 'This collection brings together delightful verses by one of the most beloved children''s poets, Andrey Usachev. Witty and joyful, filled with his trademark humor, these poems make young readers giggle while gently nudging them to ponder life''s little curiosities. Kids fall in love with them at first listen, effortlessly memorizing the catchy rhymes to the absolute delight of their parents.', 'Ova zbirka donosi vesele pjesmice jednog od najpopularnijih dječjih pjesnika, Andreja Usačova. Puni duha, vedrine i prepoznatljivog humora, ovi stihovi ne samo da mame osmijeh već podstiču djecu na razmišljanje o svakodnevnim sitnicama. Mališani ih s lakoćom pamte i recituju na radost čitave porodice.', 'Озорные и легко запоминающиеся стихи про ушастых непосед, которые подарят заряд бодрости и улыбок всей семье!', 'Mischievous and wonderfully catchy bunny rhymes guaranteed to bring giggles and cheerful rhythms into your family reading!', 'Nestašni i pamtljivi stihovi o zečićima koji će unijeti osmijehe i razigran ritam u vaše porodično čitanje!', '/covers/DP-0569.webp', '#e29b46', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","animals"]', '["стихи","зайчики","юмор","животные","детская поэзия"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шел-по-городу-скелет-570', 'DP-0570', 'Шел по городу скелет', 'A Skeleton Was Walking Down the Street', 'Kostur je šetao gradom', 'Алексей Ерошин', 'Aleksey Eroshin', 'Aleksej Jerošin', '', 'Мелик-Пашаев', 2017, '978-5-00041-244-2', 3, 12, 'little', '', 'A delightfully mischievous and witty collection of poems where friendly skeletons stroll down city streets, comical monsters get into silly mix-ups, and playful laughter echoes from every single page.', 'Izuzetno duhovita i razigrana zbirka pjesama u kojoj dobroćudni kosturi šetaju gradskim ulicama, a nestašne rime pretvaraju svaku strašnu priču u urnebesnu zabavu.', 'Не бойтесь этого скелета: он вовсе не страшный, а ужасно смешной и обожает озорные стихи!', 'Don''t fear this skeleton: he isn''t spooky at all, just wonderfully silly and eager to tickle your funny bone!', 'Ne bojte se ovog kostura: uopšte nije strašan, već beskrajno smiješan i spreman da vas nasmije do suza!', '/covers/DP-0570.webp', '#23395d', 'poetry', 'ru', 'available', 'Категория: стихи', '["funny","spooky"]', '["poetry","humor","rhymes","monsters","laughter"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('еж-игнат-ищет-клад-571', 'DP-0571', 'Еж Игнат ищет клад', 'Ignat the Hedgehog Searches for Treasure', 'Jež Ignjat traži blago', 'Диск Хеннинг', 'Dirk Hennig', 'Dirk Henig', '', '', NULL, NULL, 3, 12, 'little', '', 'Join Ignat the cheerful hedgehog on a delightful rhyming quest across forest trails and leafy clearings. Equipped with a map, a keen nose, and boundless curiosity, Ignat sets out to find buried pirate gold—only to uncover the wonders of the woods and the joys of an adventurous heart.', 'Pridružite se veselom ježu Ignjatu u razigranoj avanturi u stihovima kroz šumske staze i skrovite kutke. Sa mapom u šapicama i velikom radoznalošću, Ignjat kreće u potragu za skrivenim blagom—otkrivajući usput da su pravo bogatstvo priroda, igra i šumski prijatelji.', 'Запасайтесь лупой и хорошим настроением: вместе с колючим следопытом Игнатом даже обычная шишка покажется сказочным сокровищем!', 'Grab your magnifying glass and brightest smile: with prickly little Ignat leading the hunt, every forest secret turns into pirate gold!', 'Uzmite lupu i osmijeh: uz bodljikavog tragača Ignjata, svaka šumska staza krije pravo gusarsko blago!', NULL, '#4e7d43', 'poetry', 'ru', 'available', 'Категория: стихи', '["animals","adventure","funny"]', '["hedgehog","treasure hunt","poetry","forest animals","rhymes"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('kako-muzej-ivi--572', 'DP-0572', '', 'How a Museum Lives', 'Kako muzej živi', '', 'Unknown', 'Nepoznati autor', '', 'Skolska kniga', NULL, NULL, 4, 14, 'middle', '', 'A fascinating illustrated journey behind the scenes of the museum world. Discover how curators choose exhibits, how restorers breathe new life into ancient treasures, and why a museum is never just quiet rooms with paintings, but a vibrant, living organism full of secrets waiting to be uncovered.', 'Fascinantno ilustrovano putovanje iza kulisa muzejskog svijeta. Otkrijte ko bira eksponate, kako ih restauratori čuvaju od zuba vremena i zašto muzej nisu samo tihe dvorane, već živ i dinamičan organizam prepun uzbudljivih otkrića.', 'Загляните за бархатные канаты и узнайте, чем дышит музей, когда гаснет свет и расходятся посетители!', 'Peek behind the velvet ropes to discover how a museum truly breathes and thrives behind closed doors!', 'Zavirite iza crvenih traka i otkrijte kako muzej zaista živi kada se svjetla ugase i posjetioci odu!', '/covers/DP-0572.webp', '#9c5b36', 'me_sr', 'me', 'available', '', '["real","adventure"]', '["museum","history","art","behind-the-scenes","non-fiction"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('povijest-slika-za-djecu-573', 'DP-0573', '', 'A History of Pictures for Children', 'Povijest slika za djecu', '', 'David Hockney, Martin Gayford', 'David Hockney, Martin Gayford', '', 'Skolska kniga', NULL, NULL, 4, 14, 'middle', '', 'A captivating journey through the history of image-making, from ancient cave drawings and classical masterpieces to movies and digital screens, told in an engaging dialogue between world-renowned painter David Hockney and art critic Martin Gayford.', 'Uzbudljivo putovanje kroz istoriju stvaranja slika – od praistorijskih pećinskih crteža i klasičnih remek-djela do filmova i digitalne umjetnosti, ispričano kroz topao razgovor slavnog slikara Dejvida Hoknija i likovnog kritičara Martina Gejforda.', 'Загляните в мастерскую великих художников и узнайте, как люди научились ловить мир в рамку — от наскальных рисунков до экранов планшетов!', 'Step into the artists'' studio and discover how humanity learned to capture the world — from prehistoric cave walls to iPad screens!', 'Zavirite u atelje velikih majstora i saznajte kako su ljudi naučili da „uhvate“ svijet oko sebe — od pećinskih zidova do ekrana tableta!', '/covers/DP-0573.webp', '#e25822', 'me_sr', 'me', 'available', '', '["real","adventure"]', '["art","history","painting","creativity","encyclopedia"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-arobno-pero-574', 'DP-0574', '', 'The Magic Feather', 'Čarobno pero', '', 'Unknown', 'Nepoznati autor', '', 'Skolska kniga', NULL, NULL, 4, 14, 'middle', '', 'A delightful collection of enchanting tales and bedtime stories that invite young readers into an imaginative world of wonder, kindness, and discovery.', 'Divna zbirka maštovitih priča i bajki koja vodi male i velike čitaoce u čudesni svijet snova, dobrote i nezaboravnih avantura.', 'Возьмите в руки это волшебное перо и отправляйтесь в путешествие по страницам самых чудесных и добрых историй!', 'Pick up this magic quill and set off on an unforgettable journey through pages brimming with wonder and warmth!', 'Uzmite ovo čarobno pero i poletite kroz stranice najljepših priča koje bude maštu!', '/covers/DP-0574.webp', '#3a539b', 'me_sr', 'me', 'available', '', '["magic","adventure"]', '["fairy tales","stories","imagination","bedtime","balkan literature"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('oskar-i-ja-575', 'DP-0575', '', 'Oskar and I', 'Oskar i ja', '', 'Maria Parr', 'Marija Par', '', 'Kreativni centar', NULL, NULL, 4, 14, 'middle', '', 'Meet Ida and her lively younger brother Oskar, a boy brimming with wild ideas, boundless energy, and muddy boots. Written by the beloved Norwegian storyteller Maria Parr, this is a heartwarming, funny, and deeply authentic chronicle of growing up together, full of outdoor adventures, backyard rivalries, and tender sibling love.', 'Upoznajte Idu i njenog mlađeg brata Oskara, neumornog dječaka prepunog otkačenih ideja i beskrajne energije. Iz pera omiljene norveške autorke Marije Par stiže topla, duhovita i dirljiva priča o odrastanju, zajedničkim igrama u prirodi i posebnoj povezanosti između brata i sestre.', 'Искромётные, трогательные и невероятно жизненные истории о взрослении от Марии Парр — лучшее лекарство для не всегда ладящих братьев и сестёр!', 'Maria Parr works her magic once more with this hilarious, tender, and wonderfully authentic tale of sibling life in all its muddy glory.', 'Pregršt smijeha, blata i dirljivih trenutaka u savršenoj priči o bratu i sestri iz pera čuvene Marije Par!', '/covers/DP-0575.webp', '#5b8c32', 'me_sr', 'me', 'available', '', '["funny","friends","real"]', '["siblings","family","childhood","adventures","growing up"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('higijena-ivopisna-povijest-ist-576', 'DP-0576', '', 'Hygiene: A Colorful History of Cleanliness', 'Higijena: Živopisna povijest čistoće', '', 'Monika Utnik-Strugała, Piotr Socha', 'Monika Utnik-Strugała, Pjotr Soha', '', 'Skolska kniga', NULL, NULL, 4, 14, 'middle', '', 'From ancient Roman public baths and royal perfume tricks to modern soap-making and toothbrushes, this richly illustrated encyclopedia explores how humans have kept themselves clean—or surprisingly dirty—across centuries and cultures.', 'Od antičkih rimskih termi i dvorova koji su se kupali u parfemima, do pronalaska sapuna i četkica za zube, ova bogato ilustrovana knjiga otkriva fascinantnu i pomalo zapanjujuću priču o čistoći kroz istoriju čovječanstva.', 'Невероятно увлекательное и на удивление весёлое путешествие по истории ванн, мыла и человеческих чудачеств!', 'A delightfully witty, richly illustrated romp through the bubbly (and occasionally stinky!) history of human hygiene.', 'Neobično zabavno i raskošno ilustrovano putovanje kroz mirisnu — i ponekad prilično prljavu — istoriju čovječanstva!', '/covers/DP-0576.webp', '#3883a4', 'me_sr', 'me', 'available', '', '["funny","real"]', '["history","hygiene","encyclopedia","illustrated","facts"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дрвече-577', 'DP-0577', '', 'The Book of Trees', 'Drveće', '', 'Piotr Socha and Wojciech Grajkowski', 'Pjotr Soha i Vojćeh Grajkovski', 'Петр Соха', 'Козикас', NULL, NULL, 4, 14, 'middle', '', 'A magnificent, oversized illustrated celebration of trees: explore the tallest giants, oldest living wonders, creatures of the canopy, and the incredible ways trees shape life on Earth.', 'Raskošno ilustrovana velika enciklopedija o drveću: otkrijte najviša i najstarija stabla na planeti, šumske stanovnike, legende i nezamjenjivu ulogu šuma u našem svijetu.', 'Огромная и невероятно красивая энциклопедия, после которой каждая прогулка по лесу или парку превратится в настоящее исследование!', 'A gorgeous, oversized celebration of nature that will turn every walk in the woods into a thrilling expedition!', 'Predivna i raskošna enciklopedija uz koju će svaka šetnja šumom postati pravo malo istraživanje prirode!', '/covers/DP-0577.webp', '#2d6a4f', 'me_sr', 'me', 'available', 'книга большого формата', '["adventure","real"]', '["trees","nature","forest","encyclopedia","illustrated"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пчеле-578', 'DP-0578', '', 'Bees', 'Pčele', '', 'Unknown', 'Nepoznati autor', 'Петр Соха', 'Козикас', NULL, NULL, 4, 14, 'middle', '', 'An engaging and informative guide into the fascinating world of bees, showing how these tiny pollinators build hives, work together, and help keep our planet blooming.', 'Uzbudljiv i poučan vodič kroz čudesni svijet pčela, koji otkriva kako ove neumorne radilice prave košnice, sarađuju i čuvaju prirodu oko nas.', 'Загляните в жужжащий улей и узнайте, почему без этих крошечных полосатых тружеников наш мир был бы совсем другим!', 'Peek inside the busy hive and discover why our whole green planet depends on these tiny, buzzing workers!', 'Zavirite u zujavu košnicu i otkrijte zašto čitava naša planeta zavisi od ovih malih, vrijednih radilica!', '/covers/DP-0578.webp', '#e5a93b', 'me_sr', 'me', 'available', 'книга большого формата', '["animals","real"]', '["bees","insects","nature","ecology","wildlife"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('грозон-579', 'DP-0579', '', 'The Gruffalo', 'Grozon', '', 'Julia Donaldson', 'Džulija Donaldson', 'Аксел Шефлер', '', NULL, NULL, 4, 14, 'middle', '', 'A clever little mouse goes for a walk in the deep dark wood and invents a terrifying creature called the Gruffalo to outsmart hungry predators — only to come face-to-face with the beast of his own imagination!', 'Domišljati mali miš šeta kroz mračnu šumu i smišlja strašno čudovište Grozona kako bi nadmudrio gladne predatore — sve dok se ne suoči licem u lice sa stvorenjem iz svoje mašte!', 'Остроумная и весёлая сказка в стихах, доказывающая, что смекалка и богатое воображение сильнее любых грозных клыков и когтей!', 'A witty modern classic proving that quick wits and a clever imagination are mightier than the sharpest claws and teeth!', 'Duhovita i neodoljiva priča u stihovima koja dokazuje da su bistar um i mašta moćniji od najoštrijih kandži!', '/covers/DP-0579.webp', '#6e4726', 'me_sr', 'me', 'available', '', '["funny","adventure","animals"]', '["forest","rhymes","monsters","clever mouse","picture book"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('грозоново-дете-580', 'DP-0580', '', 'The Gruffalo''s Child', 'Grozonovo dete', '', 'Julia Donaldson', 'Džulija Donaldson', 'Аксел Шефлер', '', NULL, NULL, 4, 14, 'middle', '', 'One wild and windy night, the Gruffalo''s child ignores her father''s warnings and tiptoes out into the deep dark wood to find out if the Big Bad Mouse really exists.', 'Jedne zimske i vetrovite noći, Grozonovo dete ignoriše očeva upozorenja i na prstima se iskrada u mračnu šumu kako bi pronašlo strašnog i moćnog Velikog zlog miša.', 'Даже самым маленьким чудищам ужасно любопытно проверить, действительно ли тот мышонок такой великий и ужасный!', 'Even the tiniest Gruffalos cannot resist sneaking into the snowy woods to see if the Big Bad Mouse is actually real.', 'Čak ni mali grozoni ne mogu da odole da ne provjere da li je taj famozni Veliki zli miš zaista toliko strašan!', '/covers/DP-0580.webp', '#2c4563', 'me_sr', 'me', 'available', '', '["adventure","funny","animals"]', '["monsters","clever mouse","winter","curiosity","picture book"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прутко-581', 'DP-0581', '', 'Stick Man', 'Prutko', '', 'Julia Donaldson', 'Džulija Donaldson', '', '', NULL, NULL, 4, 14, 'middle', '', 'Stick Man lives happily in the family tree with his Stick Lady Love and their three stick children. But when a morning jog turns into an unexpected journey involving playful dogs, nest-building swans, and a roaring fireplace, Stick Man must brave every danger to find his way back home in time for Christmas.', 'Prutko živi mirno u porodičnom stablu sa svojom gospođom Prutkom i njihovo troje prutića. Međutim, običan jutarnji džoging pretvara se u opasnu avanturu sa razigranim psima, labudovim gnijezdima i kaminom u plamenu. Uz malo novogodišnje čarolije, Prutko će učiniti sve da se vrati svojoj porodici.', 'Трогательная и захватывающая зимняя сказка о том, что даже обычная веточка мечтает вернуться домой к празднику.', 'A delightfully suspenseful and heartwarming holiday adventure proving that no stick is too ordinary to find his way back home.', 'Topla i uzbudljiva priča u stihovima o hrabrom prutiću koji samo želi da se vrati kući svojoj porodici za praznike.', '/covers/DP-0581.webp', '#8b5a2b', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["adventure","magic","funny"]', '["julia donaldson","rhyme","christmas","family","journey"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гужва-на-метли-582', 'DP-0582', '', 'Room on the Broom', 'Gužva na metli', '', 'Julia Donaldson', 'Džulija Donaldson', '', '', NULL, NULL, 4, 14, 'middle', '', 'A cheerful witch and her faithful cat soar happily through the sky, but sudden gusts of wind send her belongings tumbling to the ground. Friendly animals help recover each lost treasure in exchange for a ride on the broomstick—until it snaps under the weight, just as a hungry dragon swoops in!', 'Vesela vještica i njena mačka jezde nebom, ali im vjetar raznosi šešir, mašnu i čarobni štapić. Svaka životinja koja pomogne u potrazi zamoli za vožnju na metli — ali ima li mjesta za sve i šta se dešava kada se iznenada pojavi gladni zmaj?', 'Запрыгивайте на метлу к доброй ведьме и ее зверятам: в дружной компании места хватит абсолютно всем, даже когда метла трещит по швам!', 'Hop aboard the kind witch''s broom with an ever-growing crew of animal pals, where there''s always room for one more friend!', 'Uskočite na metlu dobre vještice i njenih veselih saputnika, jer za prave prijatelje uvijek ima mjesta!', '/covers/DP-0582.webp', '#d95f24', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["magic","friends","funny"]', '["witch","animals","friendship","rhymes","dragon"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('торта-од-палачинки-583', 'DP-0583', '', 'Pancakes for Findus', 'Torta od palačinki', '', 'Sven Nordqvist', 'Sven Nurdkvist', '', '', NULL, NULL, 4, 14, 'middle', '', 'Cat Findus celebrates his birthday three times a year, and every time Old Man Pettson bakes him a glorious pancake cake. But today, finding the flour turns into a wonderfully absurd chain of mishaps involving a locked shed, a fishing rod, and a very grumpy bull!', 'Mačak Findus slavi rođendan tri puta godišnje, a čiča Petson mu svaki put sprema čuvenu tortu od palačinki. Međutim, običan odlazak po brašno pretvara se u urnebesnu avanturu s merdevinama, tavanom, štapom za pecanje i jednim namrgođenim bikom!', 'Классика про Финдуса и Петсона, где обычная выпечка блинов оборачивается грандиозной и невероятно смешной комедией положений!', 'Baking a birthday pancake cake turns into the most wonderfully chaotic and hilarious adventure in this beloved classic!', 'Priprema rođendanske torte od palačinki pretvara se u neodoljivo smiješnu avanturu punu zbrke i majstorskih dosjetki!', '/covers/DP-0583.webp', '#e27238', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["funny","friends","animals"]', '["cats","baking","friendship","inventing","humor"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лов-на-лисицу-584', 'DP-0584', '', 'The Fox Hunt', 'Lov na lisicu', '', 'Sven Nordqvist', 'Sven Nurdkvist', '', '', NULL, NULL, 4, 14, 'middle', '', 'When a hungry fox begins sniffing around the farm, Pettson and his spirited cat Findus hatch an ingenious, non-violent scheme to scare it off using a pepper-stuffed trick hen, fireworks, and a very spooky ghost costume.', 'Kada se gladna lisica pojavi oko Petsonovog kokošinjca, stari Petson i mačak Findus smišljaju lukav i bezopasan plan: napraviće lažnu kokošku punjenu biberom, prirediti vatromet i uplašiti nezvanog gosta zauvijek!', 'Зачем стрелять в лису, если можно смастерить курицу с перцем, устроить ночной фейерверк и напугать непрошеную гостью до кошачьего визга!', 'Why shoot a fox when you can build a pepper-packed trick hen, stage a firework show, and scare it away with pure Nordic ingenuity!', 'Zašto pucati na lisicu kad možete napraviti lažnu kokošku sa biberom, prirediti vatromet i nasmijati se do suza!', '/covers/DP-0584.webp', '#d35400', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["funny","animals","adventure"]', '["pettson and findus","fox","inventions","cat","humor"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('петсон-кампуе-585', 'DP-0585', '', 'Findus Goes Camping', 'Petson kampuje', '', 'Sven Nordqvist', 'Sven Nordkvist', '', '', NULL, NULL, 4, 14, 'middle', '', 'Findus has discovered a tent in the attic and desperately wants to go camping. Pettson agrees to an expedition, but will they make it past their own vegetable patch? A hilarious, heartwarming tale of a backyard adventure, wacky inventions, and curious hens.', 'Findus je na tavanu pronašao stari šator i po svaku cijenu želi da kampuje. Petson pristaje na ekspediciju, ali hoće li uopšte stići dalje od svog dvorišta? Topla i beskrajno duhovita priča o kampovanju, neobičnim izumima i radoznalim kokoškama.', 'Зачем ехать на край света, если самое захватывающее приключение с палаткой и рыбалкой можно устроить прямо в собственном саду?', 'Who needs to travel far when the wildest camping adventure and best fishing spots are right in your own backyard?', 'Ko kaže da morate ići daleko kad se najuzbudljivija avantura sa šatorom i ribolovom krije u vašem dvorištu?', '/covers/DP-0585.webp', '#4a7c59', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["funny","adventure","animals"]', '["pettson and findus","camping","tent","nature","humor"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('финдус-се-сели-586', 'DP-0586', '', 'Findus Moves Out', 'Findus se seli', '', 'Sven Nordqvist', 'Sven Nurdkvist', '', '', NULL, NULL, 4, 14, 'middle', '', 'Findus loves bouncing on his bed at four in the morning, but Pettson desperately needs his sleep! To solve the morning uproar, Pettson renovates the old outhouse into a private cottage for the energetic kitten. Independent life feels grand at first, but sleeping all alone turns out to be much spookier than expected.', 'Findus obožava da skače po krevetu u četiri ujutru, ali Petsonu je neophodan miran san! Zato Petson preuređuje staru kućicu u dvorištu za svog nemirnog mačka. Samostalan život u početku djeluje uzbudljivo, ali noć donosi neočekivanu nostalgiju i strah od mraka.', 'Трогательная и очень смешная история о первом шаге к самостоятельности и о том, как приятно знать, что тебя всегда ждут дома.', 'A hilarious and heartwarming tale about taking the first brave steps toward independence and realizing how sweet it is to come back home.', 'Duhovita i topla priča o prvim koracima ka samostalnosti i o tome kako je najljepše ipak se vratiti starom prijatelju.', '/covers/DP-0586.webp', '#d97724', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["funny","friends","animals"]', '["cats","friendship","growing up","humor","independence"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('jадни-петсон-587', 'DP-0587', '', 'Poor Pettson', 'Jadni Petson', '', 'Sven Nordqvist', 'Sven Nordkvist', '', '', NULL, NULL, 4, 14, 'middle', '', 'Old Man Pettson is in a terrible mood and wants nothing more than to sulk in peace. Luckily, his lively kitten Findus has big plans to cheer him up, even if it means inventing the most stubborn fishing expedition ever.', 'Starac Petson se probudio neraspoložen i samo želi da gunđa u miru. Srećom, njegov neumorni mačak Findus spreman je na sve kako bi ga nasmijao i odvukao u avanturu na jezeru.', 'Лучшее средство от осенней хандры — наблюдать, как неугомонный Финдус возвращает улыбку ворчливому старику Петсону.', 'The sweetest remedy for a grumpy day, proving no bad mood can survive the cheerful persistence of kitten Findus.', 'Savršen lijek za loše raspoloženje uz najdraži tandem — mrzovoljnog starca i njegovog upornog prugastog mačka.', '/covers/DP-0587.webp', '#3b6b58', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["funny","friends","animals"]', '["pettson and findus","cats","friendship","emotions","fishing"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('петсон-слави-божич-588', 'DP-0588', '', 'Pettson''s Christmas', 'Petson slavi Božić', '', 'Sven Nordqvist', 'Sven Nordkvist', '', '', NULL, NULL, 4, 14, 'middle', '', 'Christmas is just around the corner, but poor Pettson sprains his ankle while chopping pine boughs. With no tree, no ham, and no ginger cookies ready, Findus worries the holiday will be ruined. Luckily, good neighbors and inventive spirits make this the most memorable and warmest Christmas ever.', 'Bliži se Božić, a jadni Petson je uganuo nogu dok je sekao jelove grančice. Kako će spremiti prazničnu trpezu, okititi jelku i ispeći medenjake? Findus je u brizi, ali uz pomoć dovitljivosti i divnih komšija, ovo će postati najtopliji i najsrećniji Božić u njihovoj maloj kući.', 'Даже когда всё идёт кувырком, настоящие друзья и тёплые соседи способны превратить любую охапку веток в самое душевное Рождество!', 'Even when everything goes topsy-turvy, true friendship and kind neighbors can turn a bunch of spruce twigs into the coziest Christmas ever!', 'Kad stvari krenu naopako, uz vjerne prijatelje i pažljive komšije čak i obična metla može da zasija poput najljepše jelke!', '/covers/DP-0588.webp', '#b83b32', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["funny","friends","animals"]', '["christmas","winter","neighbors","kindness","cats"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зар-ти-баш-ништа-ни-умеш-петсо-589', 'DP-0589', '', 'Can''t You Do Anything, Pettson?', 'Zar ti baš ništa ne umiješ, Petso?', '', 'Sven Nordqvist', 'Sven Nurdkvist', '', '', NULL, NULL, 4, 14, 'middle', '', 'Findus the kitten can jump high, climb fences, and chase mice—so why can''t old Pettson do any of those things? In this sweet and humorous story, Findus tests the old man''s abilities, discovering that while Pettson might not be good at cat games, he is unbeatable at cozy companionship and making things just right.', 'Mačak Findus može da skače visoko, penje se na ogradu i juri miševe — pa zašto čiča Petson ništa od toga ne umije? U ovoj toploj i duhovitoj priči, radoznali mačak isprobava šta sve starac može da uradi, otkrivajući da Petson možda ne zna mačije vještine, ali zato pravi najbolje palačinke i pruža najtopliji zagrljaj.', 'Озорной Финдус проверяет старика Петсона на прочность и ловкость, доказывая, что дружить здорово, даже если ты совершенно не умеешь ловить мышей!', 'Cheeky Findus puts old Pettson to the test, proving that the best companions don''t need to hop like cats to be absolutely wonderful.', 'Nestašni Findus stavlja čiča Petsona na probu, dokazujući da pravi prijatelji ne moraju da skaču po drveću da bi bili savršeno društvo!', '/covers/DP-0589.webp', '#e08d3c', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["funny","friends","animals"]', '["pettson and findus","cats","friendship","cozy","humor"]', 1792836322698, 1792845657596);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лео-и-горгонина-клетва-590', 'DP-0590', '', 'Leo and the Gorgon''s Curse', 'Leo i Gorgonina kletva', '', 'Joe Todd-Stanton', 'Džo Tod-Stenton', '', 'Креативни центар', NULL, NULL, 4, 14, 'middle', '', 'Young Leo Brownstone dreams of becoming a legendary hero like the great warriors of ancient Greece. Sent on a quest to hunt mythical beasts, Leo discovers that bravery isn''t about fighting monsters with brute force, but understanding compassion and true courage. A visually stunning mythological graphic novel packed with Greek legends and breathtaking illustrations.', 'Mladi Leo Braunston mašta o tome da postane slavni heroj poput drevnih grčkih ratnika. Kada krene u pohod na mitske nemani i zloglasnu Gorgonu, Leo shvata da se pravo junaštvo ne mjeri oružjem, već razumijevanjem i dobrotom. Raskošno ilustrovani grafički roman koji oživljava grčke mitove na svjež i topao način.', 'Захватывающий графический роман о древнегреческих чудовищах, в котором побеждает не грозный меч, а доброе сердце!', 'A breathtaking mythological adventure proving that facing monsters takes more heart and empathy than brute force!', 'Uzbudljivi mitološki strip o susretu sa čudovištima, u kom pobjeđuju mudrost i dobrota umjesto oštrog mača!', '/covers/DP-0590.webp', '#4a2d59', 'me_sr', 'me', 'available', 'комикс', '["adventure","magic","spooky"]', '["graphic novel","greek mythology","monsters","courage","brownstone"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хилда-и-поворка-птица-591', 'DP-0591', '', 'Hilda and the Bird Parade', 'Hilda i povorka ptica', '', 'Luke Pearson', 'Luk Pirson', '', 'Мала лагуна', NULL, NULL, 4, 14, 'middle', '', 'Hilda moves to the bustling city of Trolberg, missing her beloved enchanted wilderness. But she soon discovers that the city holds its own secret wonders when she rescues an unusual talking bird with amnesia right before the famous Bird Parade.', 'Nakon preseljenja u bučni grad Trolberg, Hilda čezne za svojom začaranom divljinom. Ipak, ubrzo otkriva da i grad krije čuda kada naiđe na neobičnu pticu koja govori i koja je izgubila pamćenje, i to baš uoči velike Parade ptica.', 'Даже если кажется, что в каменном городе нет места магии, бесстрашная Хильда и её пернатый друг докажут обратное!', 'Even if city life seems dull after living in an enchanted wilderness, Hilda proves that magical surprises hide around every corner!', 'Čak i ako gradski život djeluje dosadno poslije začarane šume, Hilda dokazuje da se magija krije na svakom ćošku!', '/covers/DP-0591.webp', '#d96b27', 'me_sr', 'me', 'available', 'комикс', '["adventure","magic","animals"]', '["comic","trolberg","urban fantasy","birds","friendship"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-ежева-ку-ица-592', 'DP-0592', '', 'Hedgehog''s Home', 'Ježeva kućica', '', 'Branko Ćopić', 'Branko Ćopić', '', '', NULL, NULL, 4, 14, 'middle', '', 'A beloved classic fable in verse about Hedgehog Ježurka Ježić, a proud woodland hunter who cherishes his humble leafy home above all the treasures and feasts in the world, teaching the vain forest animals a timeless lesson about love and contentment.', 'Bezvremenska priča u stihovima o Ježurki Ježiću, čuvenom lovcu koji iznad svega na svijetu voli i brani svoj skromni dom, dokazujući vuku, medi i divljoj svinji pravu vrijednost slobode i topline sopstvenog ognjišta.', 'Легендарная сказка в стихах о том, что нет места лучше и уютнее родного дома — даже если это просто ворох сухих листьев под старым дубом!', 'The ultimate classic of Balkan children''s literature, proving that no feast or palace compares to the cozy comfort of one''s own humble home.', 'Najljepša i najvoljenija pjesmica našeg djetinjstva koja nas uči da je rođeni dom najdraže i najsvetije mjesto na svijetu.', '/covers/DP-0592.webp', '#5b7042', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["animals","funny","adventure"]', '["classics","rhymes","hedgehog","forest","home"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('hari-poter-i-zatvorenik-azkaba-593', 'DP-0593', '', 'Harry Potter and the Prisoner of Azkaban', 'Hari Poter i zatvorenik iz Askabana', '', 'J.K. Rowling', 'Dž. K. Rouling', '', '', NULL, NULL, 4, 14, 'middle', '', 'During his third year at Hogwarts, Harry Potter encounters terrifying Dementors guarding the castle after notorious fugitive Sirius Black escapes from the wizard prison, Azkaban. With the help of Ron, Hermione, and a mysterious Marauder''s Map, Harry unravels secrets of the past and masters the powerful Patronus charm.', 'Tokom treće godine na Hogvortsu, Hari Poter se suočava sa zastrašujućim dementorima nakon što ozloglašeni zatvorenik Sirijus Blek bježi iz čarobnjačkog zatvora Askaban. Uz pomoć Rona, Hermione i misteriozne Mape za haranje, Hari otkriva tajne iz prošlosti i uči moćnu čaroliju Patronus.', 'Время крутить Маховик времени, осваивать Патронуса и узнать, кто же на самом деле скрывается под маской узника Азкабана!', 'Turn back the Time-Turner, cast your happiest Patronus, and uncover the real secret behind Hogwarts'' most notorious fugitive!', 'Okrenite Vremepolov, prizovite svog Patronusa i otkrijte pravu istinu o najtraženijem bjeguncu čarobnjačkog svijeta!', '/covers/DP-0593.webp', '#483d8b', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["magic","adventure","spooky"]', '["wizards","hogwarts","magic","mystery","friendship"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('hari-poter-i-vatreni-pehar-594', 'DP-0594', '', 'Harry Potter and the Goblet of Fire', 'Hari Poter i vatreni pehar', '', 'J.K. Rowling', 'Dž. K. Rouling', '', '', NULL, NULL, 4, 14, 'middle', '', 'Harry Potter unexpectedly finds his name pulled from the Goblet of Fire, forcing him to compete in the legendary and perilous Triwizard Tournament against older, more experienced wizards.', 'Hari Poter se neočekivano suočava sa plamenom Vatrenog pehara koji izbacuje njegovo ime, primoravajući ga da učestvuje u opasnom Tročarobnjačkom turniru punom zmajeva, morskih tajni i mračnih izazova.', 'Осторожно: драконы, русалки и Турнир Трёх Волшебников затянут вас так, что оторваться будет просто невозможно!', 'Brace yourself: dragons, deep-lake mysteries, and the Triwizard Tournament will keep you turning pages well past bedtime!', 'Pripremite se za zmajeve, tajanstvene podvodne dubine i Tročarobnjački turnir od koga zastaje dah!', '/covers/DP-0594.webp', '#b83824', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["magic","adventure","friends"]', '["hogwarts","wizards","dragons","tournament","fantasy"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('vremeplovac-iz-kamenog-doba-595', 'DP-0595', '', 'The Stone Age Time Traveler', 'Vremeplovac iz kamenog doba', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'An exciting adventure that whisks young explorers through time straight back to prehistoric caves, mammoths, and wild challenges where wit and humor save the day.', 'Uzbudljiva avantura koja vodi mlade istraživače kroz vrijeme pravo u praistoriju među mamute, pećine i neobične izazove đe snalažljivost donosi spas.', 'Пристегните ремни: мы отправляемся на машине времени прямиком к мамонтам, кострам и первобытным тайнам!', 'Fasten your seatbelts: we''re hopping in the time machine straight to mammoths, campfires, and prehistoric fun!', 'Vežite pojaseve: krećemo vremeplovom pravo među mamute, pećinske vatre i praistorijske tajne!', '/covers/DP-0595.webp', '#b86b35', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["adventure","funny","magic"]', '["time travel","stone age","prehistory","humor","mammoths"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-kola-dobrote-gospo-ice-mile-596', 'DP-0596', '', 'Miss Molly''s School of Kindness', 'Škola dobrote gospođice Mile', '', 'James Maclaine', 'Džejms Maklejn', '', '3-6 лет', NULL, NULL, 4, 14, 'middle', '', 'Step inside Miss Molly''s charming school where woodland animals learn the most valuable lessons of all: how to be kind, listen to friends, share smiles, and care for each other. Filled with heartwarming animal characters and relatable everyday situations, this gentle story shows that even the smallest acts of thoughtfulness can make a big difference.', 'Zavirite u čarobnu školu gospođice Mile u kojoj šumske životinjice uče najvažnije lekcije: kako biti pažljiv, slušati prijatelje, dijeliti osmijehe i brinuti o drugima. Kroz tople likove i prepoznatljive svakodnevne situacije, ova nježna slikovnica pokazuje da i najmanja djela dobrote mogu promijeniti svijet oko nas.', 'Теплейшая и полезная сказка о том, как внимание и забота к друзьям превращают даже самый хмурый день в настоящий праздник!', 'A delightfully sweet guide to empathy that shows little ones how superpowers like listening and sharing make the world brighter!', 'Predivna i topla priča koja najmlađima na zabavan način pokazuje kako empatija i lijepa riječ čine prava mala čuda!', '/covers/DP-0596.webp', '#76b583', 'me_sr', 'me', 'available', 'Категория: Грозон Бака', '["animals","friends"]', '["kindness","empathy","animals","manners","friendship"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('желите-ли-да-видите-звезду--597', 'DP-0597', '', 'Would You Like to See a Star?', 'Želite li da vidite zvezdu?', '', 'Unknown', 'Nepoznati autor', 'Мати Леп', '', NULL, NULL, 4, 14, 'middle', '', 'A captivating journey into the wonders of the night sky, inviting young stargazers to look up, discover the constellations, and marvel at the magic of the cosmos.', 'Fascinantno putovanje među čuda noćnog neba koje poziva mlade posmatrače da podignu pogled, otkriju sazvežđa i dive se tajnama beskrajnog kosmosa.', 'Поднимите голову к ночному небу и приготовьтесь загадывать самые заветные желания вместе с этой сияющей книгой!', 'Look up at the midnight sky and get ready to make a wish alongside this dazzling starry guide!', 'Podignite pogled ka noćnom nebu i pripremite se da zamislite želju uz ovu blistavu zvjezdanu priču!', '/covers/DP-0597.webp', '#1c2b4b', 'me_sr', 'me', 'available', '8-11 лет', '["magic","real","adventure"]', '["stars","night sky","astronomy","universe","curiosity"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чаробне-патике-мог-приятеля-пе-598', 'DP-0598', '', 'The Magic Sneakers of My Friend Peca', 'Čarobne patike mog prijatelja Pece', '', 'Unknown', 'Nepoznati autor', '', 'Креативни центар', NULL, NULL, 4, 14, 'middle', '', 'Can an ordinary pair of sneakers possess real magic, or is the true magic found in friendship and childhood imagination? This warm and humorous story follows two best friends through everyday school adventures, outdoor games, and big childhood dreams, proving that with the right companion by your side, every step feels like flying.', 'Mogu li obične patike zaista biti čarobne ili se prava magija krije u dječijoj mašti i prijateljstvu? Ova topla i duhovita priča prati dvojicu najboljih drugara kroz školske dogodovštine, igre u dvorištu i velike snove, pokazujući da uz pravog prijatelja svaki korak postaje čudesna avantura.', 'Зашнуруйте кеды покрепче: с верным другом даже обычный прыжок через лужу превращается в настоящий полет!', 'Lace up your sneakers tight: with a great best friend, even jumping over puddles feels like pure magic!', 'Vežite dobro pertle: uz najboljeg druga i običan skok preko bare postaje pravo letenje!', '/covers/DP-0598.webp', '#2c699a', 'me_sr', 'me', 'available', '9-12 лет', '["friends","funny","magic"]', '["sneakers","friendship","childhood","school life","adventures"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мо-при-ате-шеик-у-стуреби-у-599', 'DP-0599', '', 'My Friend Sheikh', 'Moj prijatelj Šeik', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A heartwarming adventure celebrating an unbreakable bond of loyalty and bravery across unexpected journeys. Full of charm, lively twists, and warmth, this story reminds young readers that true companionship is the greatest treasure of all.', 'Topla i uzbudljiva avantura o neraskidivom prijateljstvu, vjernosti i hrabrosti na neočekivanim životnim stazama. Kroz niz dirljivih i duhovitih obrta, ova priča podsjeća mlade čitaoce na pravu vrijednost odanosti i međusobne podrške.', 'Трогательная и полная приключений история о настоящей преданности, которая непременно согреет сердце читателя любого возраста!', 'A touching, adventure-filled tale of loyalty and companionship that will warm the heart of readers of any age!', 'Dirljiva i uzbudljiva priča o iskrenoj odanosti i drugarstvu koja će osvojiti srce čitalaca svih uzrasta!', '/covers/DP-0599.webp', '#d97736', 'me_sr', 'me', 'available', 'Категория: Ульф Старк', '["friends","adventure"]', '["friendship","adventure","loyalty","growing up","illustrated"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('планина-три-печине-600', 'DP-0600', '', 'The Mountain of Three Caves', 'Planina tri pećine', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'Deep within the mysterious Mountain of Three Caves lie ancient secrets, hidden pathways, and legends waiting to be uncovered by brave young explorers. A timeless adventure story steeped in folklore and the rugged beauty of mountain tales.', 'Duboko u tajanstvenoj Planini tri pećine kriju se drevne zagonetke, skrivene staze i legende koje čekaju na najhrabrije istraživače. Uzbudljiva planinska priča protkana duhom predanja i neustrašivim avanturama.', 'Захватите воображаемый фонарик и крепкие ботинки — эта таинственная гора полна загадок, эха и древних секретов!', 'Pack a sturdy pair of boots and a curious mind — this mysterious mountain echoes with ancient legends and hidden surprises!', 'Ponesite dobru baterijsku lampu i hrabro srce — ova planina krije tajne koje čekaju samo prave istraživače!', '/covers/DP-0600.webp', '#3f564d', 'me_sr', 'me', 'available', 'Категория: Ульф Старк', '["adventure","magic"]', '["mountains","caves","secrets","adventure","folklore"]', 1792836322698, 1792845657597);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('порука-у-боци-601', 'DP-0601', '', 'Message in a Bottle', 'Poruka u boci', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A captivating sea adventure inspired by the timeless wonder of finding a drifting message in a bottle, inviting young dreamers to follow the trail of maritime secrets and unexpected friendships.', 'Uzbudljiva morska pustolovina inspirisana vječitim čudom pronalaženja tajanstvene poruke u boci, koja poziva mlade sanjare da prate trag morskih tajni i neočekivanih prijateljstava.', 'Загляните в эту таинственную бутылку, выброшенную на берег, чтобы разгадать её морские секреты!', 'Uncork this seaside mystery and discover what hidden secrets the waves have brought ashore!', 'Otčepite ovu morsku tajnu i saznajte kakvu je skrivenu poruku more izbacilo na obalu!', '/covers/DP-0601.webp', '#20688a', 'me_sr', 'me', 'available', 'Категория: Ульф Старк', '["adventure","friends"]', '["sea","adventure","mystery","friendship","secrets"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('knige-magije-602', 'DP-0602', '', 'The Books of Magic', 'Knjige magije', '', 'Neil Gaiman', 'Nil Gejman', '', 'Darkwood', NULL, NULL, 4, 14, 'middle', '', 'When young Tim Hunter is discovered to have the potential to become the world''s greatest magician, four mysterious occult guides take him on an eye-opening journey across time, dreams, and alternate realms to decide his magical destiny.', 'Kada se ispostavi da dječak Tim Hanter nosi potencijal da postane najveći čarobnjak na svijetu, četiri tajanstvena mistika vode ga na nezaboravno putovanje kroz prošlost, sadašnjost i opasne svjetove magije.', 'Приготовьтесь к завораживающему и таинственному путешествию сквозь миры волшебства вместе с юным Тимом в культовом графическом романе Нила Геймана!', 'Step into a mesmerizing tour of mystical realms alongside young Tim Hunter in Neil Gaiman''s spellbinding graphic novel.', 'Zavirite u očaravajući i tajanstveni svijet čarobnjaštva sa mladim Timom Hanterom u ovom kultnom stripu Nila Gejmana!', '/covers/DP-0602.webp', '#2c1b4d', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["magic","adventure","spooky"]', '["comics","graphic novel","fantasy","magic","wizards"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('bdenje-603', 'DP-0603', '', 'The Vigil', 'Bdenje', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A reflective and atmospheric collection of prose and verse that invites readers to slow down, listen to the quiet whisper of the night, and ponder the gentle mysteries of life and nature.', 'Atmosferična i misaona zbirka koja poziva mlade čitaoce da uspore, oslušnu šapat noći i razmisle o tihim tajnama prirode i ljudske duše.', 'Идеальное вечернее чтение для тех, кто любит разгадывать тихие тайны под мерцание звёзд.', 'A soothing twilight read for thoughtful dreamers who love to unravel quiet mysteries under starlit skies.', 'Savršeno večernje štivo za zamišljene sanjare koji vole da otkrivaju tihe tajne pod zvjezdanim nebom.', '/covers/DP-0603.webp', '#2c3e50', 'me_sr', 'me', 'available', 'Darkwood', '["magic","real"]', '["poetry","night","bedtime","contemplation","balkan literature"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('crna-orhideja-604', 'DP-0604', '', 'The Black Orchid', 'Crna orhideja', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A thrilling and mysterious tale centered on the quest for the legendary black orchid, leading bold young adventurers through secrets, puzzles, and unexpected encounters.', 'Uzbudljiva i zagonetna priča usredsređena na potragu za legendarnom crnom orhidejom, koja vodi mlade avanturiste kroz tajne, zagonetke i neočekivane susrete.', 'Окунитесь в загадочное приключение в поисках неуловимой черной орхидеи, скрывающей древние тайны!', 'Dive into a gripping mystery tracking down the elusive black orchid and its well-kept secrets!', 'Uronite u uzbudljivu misteriju i krenite u potragu za tajanstvenom crnom orhidejom!', '/covers/DP-0604.webp', '#2c1d3b', 'me_sr', 'me', 'available', 'Darkwood', '["adventure","magic"]', '["mystery","adventure","secrets","quest","nature"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('americki-bogovi-605', 'DP-0605', '', 'American Gods', 'Američki bogovi', '', 'Neil Gaiman', 'Nil Gejman', '', '', NULL, NULL, 4, 14, 'middle', '', 'Released from prison right after his wife''s tragic death, Shadow Moon takes a job as bodyguard to the mysterious Mr. Wednesday. He soon finds himself swept into a hidden, brewing war between forgotten mythological gods and modern deities of technology, money, and media.', 'Nakon prijevremenog izlaska iz zatvora i tragične smrti supruge, Sjenka Mun prihvata posao tjelohranitelja zagonetnog gospodina Srijede. Tako biva uvučen u skriveni rat epskih razmjera između starih bogova iz mitologije i modernih božanstava tehnologije i medija.', 'Приготовьтесь к захватывающему дорожному путешествию по тайным тропам Америки, где оживают древние мифы и верования!', 'Fasten your seatbelts for an unforgettable road trip across America alongside forgotten gods and legendary myths!', 'Vežite se za nezaboravno putovanje skrivenim drumovima Amerike u društvu zaboravljenih božanstava i drevnih legendi!', '/covers/DP-0605.webp', '#1f2a44', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["magic","adventure","spooky"]', '["mythology","gods","fantasy","mystery","legends"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('sve-smrti-lejle-star-606', 'DP-0606', '', 'The Many Deaths of Laila Starr', 'Sve smrti Lejle Star', '', 'Ram V, Filipe Andrade', 'Ram V, Filipe Andrade', '', 'Darkwood', NULL, NULL, 4, 14, 'middle', '', 'When humanity is on the verge of discovering immortality, the Avatar of Death is forced to live out a mortal existence on Earth as twenty-something Laila Starr in Mumbai. A poetic, breathtakingly illustrated graphic novel meditating on life, mortality, and what makes every fleeting moment precious.', 'Kada se čovječanstvo nađe na korak od otkrića besmrtnosti, boginja smrti biva protjerana na Zemlju kako bi živjela kao obična smrtnica Lejla Star u užurbanom Mumbaju. Poetičan, magično ilustrovani grafički roman o životu, prolaznosti i svemu što nas čini ljudima.', 'Мудрая, пронзительная и потрясающе красивая графическая притча о том, почему жизнь по-настоящему ценна только смертным.', 'A breathtakingly poetic graphic novel showing that life is only precious precisely because it doesn''t last forever.', 'Očaravajuća i dirljiva grafička priča koja nas podsjeća zašto je svaki prolazni trenutak života neprocjenjiv.', '/covers/DP-0606.webp', '#c23678', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["magic","real","adventure"]', '["graphic novel","comics","mythology","philosophy","mumbai"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('mali-nemo-607', 'DP-0607', '', 'Little Nemo', 'Mali Nemo', '', 'Winsor McCay', 'Vinsor Mekej', '', '', NULL, NULL, 4, 14, 'middle', '', 'Step into the wondrous, ever-shifting world of Slumberland alongside Little Nemo. Each night brings breathtaking dream adventures, whimsical creatures, and mind-bending landscapes where anything is possible until morning breaks.', 'Zakoračite u čudesni, nestvarni svijet Zemlje snova sa Malim Nemom. Svaka noć donosi nevjerovatne avanture, maštovita bića i predjele u kojima je sve moguće — sve dok ne svane jutro.', 'Классическое визуальное волшебство: приготовьтесь падать с кровати прямо в самые невероятные и сказочные сны!', 'A timeless classic of dreamlike wonder: get ready to tumble straight out of bed into the most fantastical dreamscapes ever imagined!', 'Bezvremena vizuelna čarolija: pripremite se da iz kreveta zakoračite pravo u najnevjerovatnije snove!', '/covers/DP-0607.webp', '#2c3e6b', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["magic","adventure"]', '["dreams","slumberland","classic","graphic novel","fantasy"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('klimt-608', 'DP-0608', '', 'Klimt', 'Klimt', '', 'Unknown', 'Nepoznati autor', '', 'Dibidus/Makondo', NULL, NULL, 4, 14, 'middle', '', 'An enchanting illustrated introduction to the golden world of Gustav Klimt. Young readers will discover how the great Austrian master turned swirling patterns, shimmering gold, and vivid imagination into timeless masterpieces of modern art.', 'Očaravajuće ilustrovani uvod u zlatni svijet Gustava Klimta. Mladi čitaoci će otkriti kako je čuveni austrijski slikar pretvorio spiralne šare, svjetlucavo zlato i bujnu maštu u vanvremenska remek-djela moderne umjetnosti.', 'Погрузитесь в море сияющего золота и завитков — эта книга вдохновит каждого юного художника на собственные смелые шедевры!', 'Dive into a swirling world of shimmering gold — this inspiring book will spark the imagination of every budding young artist!', 'Zaronite u čarobni svijet svjetlucavog zlata i ornamenata — ova knjiga će probuditi pravog malog umjetnika u vama!', '/covers/DP-0608.webp', '#d4af37', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["magic","real"]', '["art","painting","creativity","biography","masterpieces"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('u-glavi-serloka-holmsa-1-609', 'DP-0609', '', 'Inside the Mind of Sherlock Holmes: Volume 1', 'U glavi Šerloka Holmsa 1', '', 'Cyril Liéron, Benoît Dahan', 'Siril Ljeron, Benoa Dahan', '', '', NULL, NULL, 4, 14, 'middle', '', 'A visually breathtaking graphic novel that takes readers directly inside the fascinating labyrinth of Sherlock Holmes''s thoughts, unraveling a mysterious web of clues page by inventive page.', 'Vizuelno očaravajući strip koji vodi čitaoce pravo u fascinantne lavirinte uma Šerloka Holmsa dok korak po korak rješava tajanstvenu zagonetku prateći najsitnije tragove.', 'Загляните прямо в чертоги разума гениального сыщика на страницах этого невероятно красивого комикса!', 'Take a literal peek inside the genius detective''s mind in this brilliantly inventive graphic novel masterpiece!', 'Zavirite pravo u misli genijalnog detektiva na stranicama ovog nevjerovatno maštovitog stripa!', '/covers/DP-0609.webp', '#1b365d', 'me_sr', 'me', 'available', 'Makondo', '["adventure","friends"]', '["graphic novel","detective","sherlock holmes","mystery","adventure"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('u-glavi-serloka-holmsa-2-610', 'DP-0610', '', 'Inside the Mind of Sherlock Holmes: Vol. 2', 'U glavi Šerloka Holmsa: Tom 2', '', 'Cyril Liéron, Benoît Dahan', 'Cyril Liéron, Benoît Dahan', '', '', NULL, NULL, 4, 14, 'middle', '', 'Dive back into the ingenious labyrinth of Sherlock Holmes''s mind in this stunning conclusion to the mystery. Through dazzling visual architecture, secret threads, and brilliant deductions, Holmes and Watson race through the foggy streets of London to unravel an extraordinary conspiracy.', 'Zaronite ponovo u briljantni lavirint uma slavnog detektiva u uzbudljivom završetku grafičke misterije. Kroz spektakularnu vizuelnu arhitekturu, skrivene tragove i genijalnu dedukciju, Holms i Votson jure maglovitim ulicama Londona kako bi razotkrili veliku zavjeru.', 'Приготовьтесь буквально заглянуть в чертоги разума великого сыщика через невероятные визуальные головоломки!', 'Step directly into the world''s greatest detective''s mind palace and watch clues connect in breathtaking comic art!', 'Zavirite pravo u genijalne moždane vijuge slavnog detektiva i pratite tragove u ovom vizuelnom remek-djelu!', '/covers/DP-0610.webp', '#7b241c', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["adventure","real"]', '["graphic novel","sherlock holmes","detective","mystery","comics"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('robin-hud-611', 'DP-0611', '', 'Robin Hood', 'Robin Hud', '', 'Traditional', 'Narodna priča', '', 'Pčelica', 2015, '978-86-6089-582-2', 4, 14, 'middle', '', 'Deep in Sherwood Forest, brave Robin Hood and his Merry Men stand up to the greedy Sheriff of Nottingham. An engaging, richly illustrated retelling of the classic legend of honor, friendship, and justice.', 'Duboko u Šervudskoj šumi, hrabri Robin Hud i njegova vesela družina staju na put pohlepnom šerifu od Notingema. Uzbudljiva i bogato ilustrovana priča o legendarnom borcu za pravdu i prijateljstvo.', 'Хватай лук и стрелы — в Шервудском лесу снова восстанавливают справедливость с весёлыми песнями и меткими выстрелами!', 'Grab your bow and arrow — justice is being served in Sherwood Forest with quick wits, brave hearts, and unbeatable aim!', 'Zgrabi luk i strijelu — u Šervudskoj šumi pravda se dijeli uz osmijeh, hrabrost i nepogrešiv pogodak!', '/covers/DP-0611.webp', '#2e6f40', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["adventure","friends"]', '["robin hood","legends","justice","sherwood","heroes"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('beovulf-ubica-cudovista-612', 'DP-0612', '', 'Beowulf: The Monster Slayer', 'Beovulf: Ubica čudovišta', '', 'Unknown', 'Nepoznati autor', '', 'Pčelica', 2015, '9788660895686', 4, 14, 'middle', '', 'A thrilling adaptation of the ancient epic tale of Beowulf, the mighty warrior who sets out to protect a kingdom from the terrifying monster Grendel, his vengeful mother, and a fire-breathing dragon.', 'Uzbudljiva adaptacija drevnog epa o neustrašivom junaku Beovulfu, koji brani kraljevstvo od zastrašujućeg čudovišta Grendela, njegove osvetoljubive majke i plamenog zmaja.', 'Древний эпос оживает на этих страницах — приготовьтесь к грандиозным битвам плечом к плечу с бесстрашным героем!', 'An ancient epic roars to life—get ready to face terrifying beasts alongside legend''s bravest hero!', 'Drevni ep oživljava na ovim stranicama — pripremite se za epske bitke rame uz rame s neustrašivim junakom!', '/covers/DP-0612.webp', '#7e2a22', 'me_sr', 'me', 'available', 'Категория: комиксы взрослые', '["adventure","magic","spooky"]', '["myths and legends","monsters","bravery","dragons","epic"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пипи-дуга-чарапа-613', 'DP-0613', '', 'Pippi Longstocking', 'Pipi Duga Čarapa', '', 'Astrid Lindgren', 'Astrid Lindgren', '', 'Ободско слово', NULL, NULL, 4, 14, 'middle', '', 'Meet Pippi Longstocking, the strongest, bravest, and most independent red-haired girl in the world, who lives all alone in Villa Villekulla with her horse, her monkey, and an endless imagination.', 'Upoznajte Pipi Dugu Čarapu, najjaču, najhrabriju i najduhovitiju djevojčicu na svijetu, koja živi sama u Vili Vilakuli sa svojim konjem, majmunčetom i koferom punim zlatnika.', 'Готовы спать ногами на подушке и поднимать лошадь одной левой? Самая озорная бунтарка на свете ждёт вас!', 'Ready to sleep with your feet on the pillow and lift a horse with one hand? The world''s favorite rebel is waiting for you!', 'Spremni da spavate sa nogama na jastuku i podignete konja jednom rukom? Najveselija buntovnica na svijetu vas čeka!', '/covers/DP-0613.webp', '#e65100', 'me_sr', 'me', 'available', '2 разред', '["funny","adventure","friends"]', '["pippi longstocking","classic","humor","girl power","friendship"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хаjди-614', 'DP-0614', '', 'Heidi', 'Hajdi', '', 'Johanna Spyri', 'Johana Špiri', '', 'Ободско слово', NULL, NULL, 4, 14, 'middle', '', 'The timeless story of Heidi, a cheerful orphan girl sent to live high in the Swiss Alps with her grumpy grandfather. Through her boundless warmth, love for nature, and joyful spirit, she brings light and healing to everyone she meets, from young goatherd Peter to sickly Clara in Frankfurt.', 'Bezvremena priča o Hajdi, veseloj djevojčici bez roditelja koja odlazi da živi visoko na švajcarskim Alpima sa svojim osamljenim djedom. Svojom dobrotom, ljubavlju prema prirodi i zaraznim optimizmom, Hajdi unosi radost u živote svih oko sebe — od kozara Petra do bolesne Klare u Frankfurtu.', 'Залитая солнцем альпийская классика о том, как искреннее сердце и свежий горный воздух способны вылечить любую тоску.', 'A heartwarming alpine classic that proves fresh mountain air, pure friendship, and a joyful heart can work true miracles.', 'Dirljivi planinski klasik koji podsjeća da čisto srce, pravo prijateljstvo i planinski vazduh liječe svaku tugu.', '/covers/DP-0614.webp', '#5b8a5a', 'me_sr', 'me', 'available', 'Категория: школьная программа, классика, лектире', '["adventure","friends","real"]', '["mountains","alps","classic","friendship","nature","kindness"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пинокио-615', 'DP-0615', '', 'Pinocchio', 'Pinokio', '', 'Carlo Collodi', 'Karlo Kolodi', '', '', NULL, NULL, 4, 14, 'middle', '', 'The timeless fairy tale of a mischievous wooden puppet carved by Geppetto who dreams of becoming a real boy, discovering bravery, honesty, and love through a series of wild misadventures.', 'Vječna bajka o nestašnom drvenom lutku kojeg je stvorio Đepeto i koji sanja da postane pravi dječak, otkrivajući hrabrost, iskrenost i ljubav kroz nevjerovatne avanture.', 'Берегите носы от лжи и приготовьтесь к невероятным приключениям самого известного деревянного мальчишки на свете!', 'Keep your nose out of fibs and follow the world''s most curious wooden puppet on his bumpy journey to becoming a real boy!', 'Pazite na nos kad govorite neistine i zaplovite u nezaboravnu pustolovinu sa najpoznatijim drvenim dječakom!', '/covers/DP-0615.webp', '#d9534f', 'me_sr', 'me', 'available', '2 разред', '["adventure","magic"]', '["pinocchio","fairy tale","classic","puppet","growing up"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дожив-а-и-мачка-тоше-616', 'DP-0616', '', 'The Adventures of Toša the Cat', 'Doživljaji mačka Toše', '', 'Branko Ćopić', 'Branko Ćopić', '', '', NULL, NULL, 4, 14, 'middle', '', 'A timeless classic of Balkan children''s literature, this charming and hilarious tale follows the clever, bacon-loving cat Toša, grandfather Triša, and faithful dog Žuća on an unforgettable journey filled with mischief and laughs.', 'Bezvremenski biser dječije književnosti donosi vesele doživljaje prevejanog mačka Toše, dobroćudnog deda Triše i vjernog psa Žuće na njihovim urnebesnim zajedničkim lutanjima.', 'Приготовьтесь хохотать над проделками кота Тоши, который ради ломтика сала готов обхитрить целый свет!', 'Get ready to chuckle at the antics of Toša the cat, who would gladly outwit the whole world for a slice of bacon!', 'Spremite se za grohotan smijeh uz nestašnog mačka Tošu koji bi za komadić slanine nadmudrio čitav svijet!', '/covers/DP-0616.webp', '#e67e22', 'me_sr', 'me', 'available', '4 разред', '["funny","adventure","animals"]', '["classic","cats","humor","friendship","serbian literature"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('alisa-u-zemlji-uda-617', 'DP-0617', '', 'Alice''s Adventures in Wonderland', 'Alisa u zemlji čuda', '', 'Lewis Carroll', 'Luis Kerol', '', 'Vulkan izdavaštvo', 2024, '978-86-10-05149-0', 4, 14, 'middle', '', 'When curious Alice follows a White Rabbit down a mysterious burrow, she discovers a topsy-turvy realm where animals speak in riddles, cats vanish leaving only smiles, and a mad tea party never ends. Lewis Carroll''s beloved classic invites readers of all ages to test the limits of pure imagination.', 'Kada radoznala Alisa krene za Bijelim Zecom niz tajanstvenu rupu, upada u čarobni i uvrnuti svijet gdje životinje govore u zagonetkama, mačke nestaju ostavljajući samo osmijeh, a luda čajanka nikad ne prestaje. Vanvremenski klasik Luisa Kerola očarava čitaoce svih generacija.', 'Прыгайте смелее в кроличью нору — здесь безумное чаепитие никогда не кончается, а логика выворачивается наизнанку самым волшебным образом!', 'Tumble down the rabbit hole where mad tea parties never end and nonsense makes the most delightful kind of sense!', 'Skočite pravo u zečju rupu gdje čajanke nikad ne prestaju, a mašta i najslađa besmislica stvaraju čistu magiju!', '/covers/DP-0617.webp', '#20639b', 'me_sr', 'me', 'available', '5 разред', '["magic","adventure","funny"]', '["classic","wonderland","fantasy","fairy tale","animals"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('bajke-i-basne-raznih-naroda-618', 'DP-0618', '', 'Fairy Tales and Fables of Various Nations', 'Bajke i basne raznih naroda', '', 'Traditional / Folklore', 'Narodno stvaralaštvo', '', '', NULL, NULL, 4, 14, 'middle', '', 'A rich anthology of fairy tales and fables from around the globe, preserving timeless wisdom through magical adventures, witty folklore, and clever lessons featuring talking animals and brave heroes.', 'Bogata zbirka bajki i basni naroda svijeta koja kroz čarobne priče, dovitljive životinje i bezvremene pouke čuva vjekovnu tradiciju i maštu različitih kultura.', 'Откройте эту книгу — и вы отправитесь в кругосветное путешествие по самым мудрым и волшебным сказкам планеты!', 'Open this book and set off on an enchanting journey through the wisest and most captivating folk tales from around the world!', 'Otvorite ovu knjigu i krenite na čarobno putovanje oko svijeta kroz najljepše i najmudrije narodne priče!', '/covers/DP-0618.webp', '#b85d38', 'me_sr', 'me', 'available', '4 разред', '["magic","adventure","animals"]', '["fairy tales","fables","folklore","wisdom","animals"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('mala-sirena-619', 'DP-0619', '', 'The Little Mermaid', 'Mala sirena', '', 'Hans Christian Andersen', 'Hans Kristijan Andersen', '', '', NULL, NULL, 4, 14, 'middle', '', 'The timeless fairy tale of a young mermaid who yearns to discover the world above the waves, learning about love, courage, and sacrifice along the way.', 'Bezvremena bajka o mladoj sireni koja čezne da otkrije svijet iznad morskih talasa, učeći o pravoj ljubavi, hrabrosti i požrtvovanosti.', 'Погрузитесь на самое дно морского царства, где рождаются великие мечты и настоящая сказочная магия!', 'Dive into the depths of an enchanted ocean kingdom where big dreams meet timeless fairy-tale magic!', 'Zaronite u dubine čarobnog morskog kraljevstva gdje se susreću veliki snovi i bajkovita magija!', '/covers/DP-0619.webp', '#207e8c', 'me_sr', 'me', 'available', '5 разред', '["magic","adventure"]', '["mermaid","ocean","fairy tale","classic","sea adventures"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('биленьакова-тайна-620', 'DP-0620', '', 'Biljenjak''s Secret', 'Biljenjakova tajna', '', 'Unknown', 'Nepoznati autor', '', 'Српска књижевна задруга (СКЗ)', 2003, '9788637908036', 4, 14, 'middle', '', 'A classic story from the Serbian Literary Guild (SKZ) collection that leads young readers into a magical world of nature''s mysteries, herb spirits, and folklore wonders tucked away in meadows and deep forests.', 'Čudesna priča iz riznice Srpske književne zadruge koja vodi mlade čitaoce u svijet zagonetnih biljnih duhova, narodnih predanja i tajni skrivenih u poljima i drevnim šumama.', 'Загляните в тайны трав и лесных духов — эта поэтичная история пахнет луговыми цветами и древними легендами!', 'Uncover the herbal secrets of the forest—this enchanting tale smells of wild meadows and timeless folk mystery!', 'Zavirite u tajne ljekovitih trava i šumskih duhova — ova čarobna priča miriše na divlje livade i drevne legende!', '/covers/DP-0620.webp', '#2e6f40', 'me_sr', 'me', 'available', 'Категория: 4 разред', '["magic","adventure"]', '["folklore","nature","mystery","fairy tale","classics"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('емил-и-детективи-621', 'DP-0621', '', 'Emil and the Detectives', 'Emil i detektivi', '', 'Erich Kästner', 'Erih Kestner', '', '', NULL, NULL, 4, 14, 'middle', '', 'When young Emil Tischbein is robbed of his grandmother''s savings on a train to Berlin, he sets out to track down the mysterious thief with the help of a clever street gang of local children.', 'Kada dječaku Emilu Tišbajnu u vozu za Berlin drski lopov ukrade sav novac, on ne odustaje, već se udružuje sa dovitljivom družinom gradskih dječaka u uzbudljivoj potjeri ulicama metropole.', 'Один из лучших детских детективов всех времён, доказывающий: дружная команда находчивых ребят способна поймать вора быстрее любой взрослой полиции!', 'A timeless classic detective adventure proving that a plucky crew of kids can crack a case and catch a crook faster than the police!', 'Bezvremeni detektivski klasik koji dokazuje da složna i dovitljiva ekipa djece može nadmudriti lopova brže od policije!', '/covers/DP-0621.webp', '#2c4a6f', 'me_sr', 'me', 'available', '6 разред', '["adventure","friends","real"]', '["detective","berlin","mystery","classic","teamwork","city life"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('robinson-kruso-622', 'DP-0622', '', 'Robinson Crusoe', 'Robinzon Kruso', '', 'Daniel Defoe', 'Danijel Defo', '', 'Laguna', 2020, '978-86-521-3838-8', 4, 14, 'middle', '', 'The classic adventure of a shipwrecked mariner who spends twenty-eight years on a remote tropical island, mastering the wild, building a home from scratch, and learning the true meaning of resilience and friendship.', 'Čuvena priča o mornaru koji nakon brodoloma provodi dvadeset osam godina na pustom ostrvu, boreći se sa divljom prirodom, savladavajući usamljenost i gradeći čitav novi život uz vjernog prijatelja Petka.', 'Главный литературный путеводитель по выживанию на необитаемом острове, доказывающий, что смекалка и труд творят настоящие чудеса!', 'The ultimate desert island survival classic that proves ingenuity, courage, and a loyal friend can conquer any storm!', 'Vrhunska avantura o preživljavanju na pustom ostrvu koja dokazuje da se uz domišljatost i hrabrost može savladati svaka nevolja!', '/covers/DP-0622.webp', '#2d6a8f', 'me_sr', 'me', 'available', '6 разред', '["adventure","friends","real"]', '["desert island","survival","classic","shipwreck","friendship"]', 1792836322698, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хайдуци-623', 'DP-0623', '', 'The Outlaws', 'Hajduci', '', 'Branislav Nušić', 'Branislav Nušić', '', 'Креативни центар', 2026, '978-86-529-1437-1', 4, 14, 'middle', '', 'A timeless comedic masterpiece of Balkan children''s literature, chronicling the misadventures of a band of mischievous schoolboys who decide to abandon school and become fearless outlaws in the woods, only to face the hilarious and sobering realities of surviving on their own.', 'Vanvremenski humoristički klasik dječje književnosti prati družinu nestašnih dječaka koji odlučuju da pobjegnu od škole i postanu opasni hajduci u šumi, gdje ih ubrzo sustižu urnebesne nezgode i surova stvarnost preživljavanja u divljini.', 'Замучили двойки и скучные уроки? Пора бежать в дубраву и становиться грозными разбойниками — главное, не проголодаться к вечеру!', 'Tired of bad grades and boring classes? It''s time to run away into the woods and become outlaws—as long as you can make it back before hunger strikes!', 'Dosadila vam je škola i loše ocjene? Vrijeme je za bijeg u šumu i hajdučke podvige — samo pazite da vas glad ne vrati kući prije mraka!', '/covers/DP-0623.webp', '#8c4a2f', 'me_sr', 'me', 'available', '6 разред', '["funny","adventure","friends"]', '["classic","school","humor","friendship","childhood"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('разговор-уз-огань-624', 'DP-0624', '', 'Tales by the Hearth', 'Razgovor uz oganj', '', 'Unknown', 'Nepoznat autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A rich collection of traditional tales, legends, and fireside stories passed down through generations, evoking the warm atmosphere of storytelling by the crackling hearth.', 'Zbirka tradicionalnih narodnih priča, predanja i mudrosti koje se prenose s koljena na koljeno, dočaravajući toplinu drevnih pripovijedanja uz plamen ognjišta.', 'Заварите травяной чай и представьте, как трещат поленья в очаге: эти старинные предания согреют в любой вечер!', 'Brew some herbal tea and gather around the crackling hearth for timeless tales of courage, folklore, and wonder!', 'Skuvajte topli čaj i okupite se oko ognjišta uz ove bezvremene narodne priče punih mudrosti!', NULL, '#b84a29', 'me_sr', 'me', 'available', '6 разред', '["magic","adventure","real"]', '["folklore","legends","storytelling","tradition","fireside tales"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сречни-принц-и-друге-байке-625', 'DP-0625', '', 'The Happy Prince and Other Tales', 'Srećni princ i druge bajke', '', 'Oscar Wilde', 'Oskar Vajld', '', '', NULL, NULL, 4, 14, 'middle', '', 'A timeless collection of poetic fairy tales by Oscar Wilde, featuring ''The Happy Prince'', ''The Selfish Giant'', and other unforgettable stories about empathy, devotion, and the true beauty of a generous heart.', 'Bezvremena zbirka poetičnih bajki Oskara Vajlda, koja uključuje priče ''Srećni princ'', ''Sebični džin'' i druge nezaboravne pripovijesti o saosjećanju, odanosti i ljepoti nesebičnog srca.', 'Трогательные и глубокие сказки Оскара Уайльда растопят даже самое холодное сердце и напомнят о настоящей доброте.', 'Oscar Wilde’s poignant, poetic fairy tales will melt any heart and remind young readers what true kindness really means.', 'Dirljive i poetične bajke Oskara Vajlda otopiće svako srce i podsjetiti nas na pravu snagu plemenitosti.', '/covers/DP-0625.webp', '#2c4a6f', 'me_sr', 'me', 'available', '7 разред', '["magic","friends"]', '["fairy tales","classics","kindness","friendship","empathy"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('орлове-рано-лете-626', 'DP-0626', '', 'Eagles Fly Early', 'Orlovi rano lete', '', 'Branko Ćopić', 'Branko Ćopić', '', 'Креативни центар', 2003, '9788677811945', 4, 14, 'middle', '', 'A beloved classic of Balkan children''s literature following Jovanče and his band of spirited schoolmates who create a secret woodland haven to escape their strict teacher. Their days of carefree mischief and secret campfires take a dramatic turn when World War II arrives, forcing the young ''eagles'' to grow up and show true courage.', 'Nezaboravni dječji roman o Jovančetovoj družini iz Prokinog gaja, njihovim tajnama, bezbrižnim nestašlucima i prvoj ljubavi. Kada rat zahvati njihov mirni kraj, bezazlene dječje igre prerastaju u istinsko junaštvo, a dječaci preko noći postaju hrabri branioci svog zavičaja.', 'Невероятно тёплая, смешная и трогательная классика о детских проделках в тайном убежище, верности и настоящей отваге перед лицом взрослой беды.', 'A spirited, warm, and poignant classic about boyhood mischief, secret woodland hideouts, and courage that takes flight too soon.', 'Topla i vječna priča o Jovančetovoj družini koja podsjeća da pravo prijateljstvo i hrabrost pobjeđuju i najteže nevolje.', '/covers/DP-0626.webp', '#4b6f44', 'me_sr', 'me', 'available', '7 разред', '["adventure","friends","real"]', '["classic","friendship","growing up","school","history"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-о-джунгли-627', 'DP-0627', '', 'The Jungle Book', 'Knjiga o džungli', '', 'Rudyard Kipling', 'Radjard Kipling', '', 'Креативни центар', 2023, '9788652911462', 4, 14, 'middle', '', 'The timeless tale of Mowgli, a boy raised by a wolf pack in the Indian jungle, learning the law of the wild alongside Baloo the bear, Bagheera the panther, and confronting the fearsome tiger Shere Khan.', 'Vječna priča o dječaku Mogliju koga prihvata vučji čopor u indijskoj džungli, gdje uz medvjeda Balua i pantera Bagiru uči zakone divljine i suočava se sa strašnim tigrom Šir Kanom.', 'Прислушайтесь к зову джунглей и узнайте, каково это — расти в волчьей стае по строгим, но справедливым законам природы!', 'Listen closely to the call of the wild and join Mowgli on his thrilling, timeless adventures deep in the jungle!', 'Oslušnite zov divljine i krenite u nezaboravnu pustolovinu sa Moglijem i njegovim vjernim prijateljima iz džungle!', '/covers/DP-0627.webp', '#2e6f40', 'me_sr', 'me', 'available', '7 разред', '["adventure","animals","friends"]', '["jungle","classic","mowgli","wild animals","growing up"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зов-дивльине-628', 'DP-0628', '', 'The Call of the Wild', 'Zov divljine', '', 'Jack London', 'Džek London', '', '', NULL, NULL, 4, 14, 'middle', '', 'A gripping and poignant classic following Buck, a domestic dog stolen from his sun-drenched home and thrust into the brutal cold of the Klondike Gold Rush, where he must awaken his primordial instincts to survive and lead.', 'Uzbudljiva i dirljiva priča o psu Baku, koji iz udobnog doma biva odveden u surovu, zaleđenu divljinu Klondajka u doba zlatne groznice, gdje u sebi otkriva drevne vučje instinkte i slobodu.', 'Укутайтесь потеплее и отправляйтесь в снежный Юкон вместе с верным и отважным Баком — эта великая классика никого не оставит равнодушным!', 'Bundle up for a breathtaking Yukon trek alongside brave Buck — a timeless classic that will make your spirit howl with courage!', 'Utoplite se za nezaboravno putovanje kroz sniježni Jukon sa hrabrim Bakom — bezvremenski klasik koji budi iskru slobode i hrabrosti!', NULL, '#2c4c5e', 'me_sr', 'me', 'available', '7 разред', '["adventure","animals"]', '["dogs","nature","survival","classic","gold rush"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('tom-sojer-629', 'DP-0629', '', 'The Adventures of Tom Sawyer', 'Doživljaji Toma Sojera', '', 'Mark Twain', 'Mark Tven', '', 'Zavod za udžbenike', 2017, '978-86-17-19617-0', 4, 14, 'middle', '', 'Follow the lively and mischievous Tom Sawyer as he turns whitewashing a fence into a masterclass of persuasion, hunts for buried treasure, and embarks on unforgettable escapades along the Mississippi River.', 'Pratite nestašnog i dovitljivog dječaka Toma Sojera dok krečenje ograde pretvara u umjetnost ubjeđivanja, traga za skrivenim blagom i upada u nezaboravne pustolovine duž rijeke Misisipi.', 'Главное пособие по превращению любого занудного дела в весёлую авантюру и настоящий гимн босоногому детству!', 'The ultimate guide to turning boring chores into thrilling escapades and celebrating the golden days of childhood!', 'Najbolji vodič kako da dosadno krečenje ograde pretvoriš u sjajnu zabavu i oda slobodnom djetinjstvu!', '/covers/DP-0629.webp', '#b86b35', 'me_sr', 'me', 'available', '7 разред', '["adventure","funny","friends"]', '["classic","childhood","mississippi","pranks","friendship"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сага-о-нилсу-холгерсону-630', 'DP-0630', '', 'The Wonderful Adventures of Nils', 'Saga o Nilsu Holgersonu', '', 'Selma Lagerlöf', 'Selma Lagerlef', '', 'Завод за уџбенике', 2006, '86-17-13775-4', 4, 14, 'middle', '', 'Turned into a tiny pixie as punishment for his mischief, stubborn Nils takes flight across the skies on the back of Martin the white farm gander. Together with a wild flock, he embarks on an unforgettable journey filled with perils, learning empathy, bravery, and deep respect for the natural world.', 'Za kaznu zbog svojih nestašluka pretvoren u patuljka, dječak Nils polijeće u nebeske visine na leđima domaćeg guska Martina. U društvu jata divljih gusaka, Nils prolazi kroz brojne opasnosti i prepreke, učeći o empatiji, hrabrosti i poštovanju prema prirodi.', 'Держитесь крепче за перья: верхом на гусе Мартине мир покажется огромным, а сердце станет гораздо добрее!', 'Hold tight to the feathers: soaring high on gooseback, the world looks vast and little hearts grow remarkably noble!', 'Držite se čvrsto za perje: u letu na leđima guska Martina svijet izgleda čarobno, a srce postaje plemenitije!', '/covers/DP-0630.webp', '#3a7d9c', 'me_sr', 'me', 'available', '7 разред', '["adventure","animals","magic"]', '["geese","journey","classic","growing up","folktale","nature"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дечаци-павлове-улице-631', 'DP-0631', '', 'The Paul Street Boys', 'Dečaci Pavlove ulice', '', 'Ferenc Molnár', 'Ferenc Molnar', '', 'Креативни центар', 2025, '978-86-529-1293-3', 4, 14, 'middle', '', 'A beloved classic of youth literature about two rival schoolboy gangs in Budapest defending their cherished vacant lot. This poignant tale remains a timeless tribute to camaraderie, loyalty, and the bravery of little heroes.', 'Legendarni omladinski roman o dvije suparničke družine dječaka u Budimpešti koje brane svoje drago igralište u Pavlovoj ulici. Dirljiva priča o časti, neustrašivosti i snazi pravog prijateljstva.', 'Трогательная классика о дворовом братстве, чести и маленьких героях с огромными сердцами.', 'A deeply moving classic about brotherhood, honour, and a vacant lot worth defending with all your heart.', 'Dirljiv i neprolazan klasik o drugarstvu, časti i malim herojima velikog srca.', '/covers/DP-0631.webp', '#7c5c3e', 'me_sr', 'me', 'available', '7 разред', '["adventure","friends","real"]', '["classic","friendship","loyalty","childhood","budapest"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гласам-за-льубав-632', 'DP-0632', '', 'I Vote for Love', 'Glasam za ljubav', '', 'Grozdana Olujić', 'Grozdana Olujić', '', '', NULL, NULL, 4, 14, 'middle', '', 'A tender and enduring classic of youth literature following Slobodan and Rašida as they navigate first love, turbulent family ties, and the delicate complexities of growing up in a provincial town.', 'Bezvremena priča o odrastanju, prvoj ljubavi Slobodana i Rašide i unutrašnjim burama mladosti u provincijskom gradu, protkana nježnošću i iskrenim buntom.', 'Искренняя и поэтичная повесть о первой любви, которая безошибочно напоминает, как трепетно бьётся сердце в юности.', 'A tender, timeless coming-of-age story that captures the fragile beauty and sweet heartache of first love.', 'Dirljiva i iskrena priča o prvoj ljubavi i odrastanju koja nepogrešivo pogađa pravo u srce.', NULL, '#c45b54', 'me_sr', 'me', 'available', '8 разред', '["friends","real"]', '["first love","growing up","classic","youth","friendship"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('dru-ina-prstena-633', 'DP-0633', '', 'The Fellowship of the Ring', 'Družina prstena', '', 'J. R. R. Tolkien', 'Dž. R. R. Tolkin', '', '', NULL, NULL, 4, 14, 'middle', '', 'The epic beginning of young hobbit Frodo Baggins''s perilous journey across Middle-earth alongside faithful companions to destroy the One Ring in Mount Doom.', 'Veliki početak epskog putovanja mladog hobita Froda Baginsa i njegovih vjernih saputnika kroz opasnosti Srednje zemlje s ciljem uništenja Jedinog prstena.', 'Запасайтесь вторым завтраком и собирайтесь в путь: величайшее эпическое путешествие по Средиземью начинается прямо с порога!', 'Pack a second breakfast and lace up your walking shoes — the greatest quest in Middle-earth begins right on your doorstep!', 'Spakujte drugi doručak i vežite pertle — najveća avantura u Srednjoj zemlji počinje pravo na vašem pragu!', '/covers/DP-0633.webp', '#234d37', 'me_sr', 'me', 'available', '8 разред', '["adventure","magic","friends"]', '["fantasy","middle-earth","hobbits","quest","friendship"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ostrvo-s-blagom-634', 'DP-0634', '', 'Treasure Island', 'Ostrvo s blagom', '', 'Robert Louis Stevenson', 'Robert Luis Stivenson', '', '', NULL, NULL, 4, 14, 'middle', '', 'When young Jim Hawkins discovers a mysterious map belonging to an old sea dog, he embarks on a perilous voyage across the high seas aboard the Hispaniola. Along the way, he must face mutinous cutthroats and the charismatic, two-faced pirate Long John Silver in a legendary race for buried treasure.', 'Kada mladi Džim Hokins pronađe tajanstvenu mapu starog gusara, kreće na uzbudljivu plovidbu brodom Hispanjola ka nepoznatim morima. Na putu do zakopanog blaga moraće da nadmudri opasne pirate i legendarnog Dugog Džona Silvera.', 'Поднять паруса: нестареющая пиратская классика с картой сокровищ, опасностями открытого моря и хитрым Джоном Сильвером!', 'Hoist the sails for the ultimate pirate adventure packed with buried gold, secret maps, and the cunning Long John Silver!', 'Podignite jedra za vrhunsku gusarsku avanturu punu zakopanog zlata, tajnih mapa i lukavog Dugog Džona Silvera!', '/covers/DP-0634.webp', '#2c5282', 'me_sr', 'me', 'available', 'Категория: 8 разред', '["adventure"]', '["pirates","treasure","sea","classic","adventure"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('zid-i-krilac-635', 'DP-0635', '', 'The Wall and the Winged One', 'Zid i Krilac', '', 'Unknown', 'Nepoznati autor', '', 'IPS Media / Prosveta', 2009, '978-86-7274-345-6', 4, 14, 'middle', '', 'A poetic and evocative tale exploring boundaries and dreams. When a steadfast wall meets Krilac, a gentle winged being full of imagination, both discover that no barrier is too high for true freedom, companionship, and boundless wonder to transcend.', 'Poetična i topla priča koja istražuje granice, snove i slobodu mašte. Kroz susret nepomičnog zida i nježnog Krilca, ova knjiga podsjeća djecu i odrasle da prijateljstvo i slobodan duh mogu preletjeti svaku prepreku.', 'Трогательная философская сказка о том, как даже самые глухие стены отступают перед силой мечты и настоящими крыльями!', 'A poetic and gentle tale reminding readers that even the highest walls crumble before imagination and true flight!', 'Nježna i mudra priča koja nas podsjeća da mašta i prijateljstvo mogu preletjeti i najviše zidove!', '/covers/DP-0635.webp', '#5b7d9a', 'me_sr', 'me', 'available', 'Категория: 8 разред', '["magic","friends"]', '["imagination","freedom","friendship","allegory","tales"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('to-636', 'DP-0636', '', 'Tales and Legends of Montenegro', 'Crnogorske bajke i predanja', '', 'Unknown', 'Nepoznat autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A rich collection of traditional South Slavic stories, timeless folktales, and heroic legends passed down through generations.', 'Bogata zbirka tradicionalnih narodnih priča, bajki i legendi koje se vjekovima prenose s koljena na koljeno.', 'Настоящая сокровищница историй, где оживают тайны старинных гор и мудрость народных преданий!', 'A true treasure trove of tales where ancient mountain mysteries and age-old wisdom come alive!', 'Prava riznica priča u kojoj oživljavaju tajne drevnih gora i mudrost narodnih predanja!', '/covers/DP-0636.webp', '#2e5b88', 'me_sr', 'me', 'available', 'Категория: 8 разред', '["adventure","magic"]', '["bajke","folktales","legends","montenegro","tradition"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('dnevnik-jednog-smotanka-lijevo-637', 'DP-0637', '', 'Diary of a Wimpy Kid: The Third Wheel', 'Dnevnik jednog smotanka: Lijevo smetalo', '', 'Jeff Kinney', 'Džef Kini', '', '', NULL, NULL, 4, 14, 'middle', '', 'Greg Heffley is determined to find a date for the Valentine''s Day school dance, but nothing goes according to plan. When he and Rowley manage to team up with an unexpected partner, the dance turns into a hilarious disaster that only Greg could orchestrate.', 'Greg Hefli je riješio da pod svaku cijenu pronađe pratilju za školski ples za Dan zaljubljenih, ali malo šta ide po planu. Kada on i Rouli nekako završe u društvu neočekivane partnerke, veče se pretvara u komičnu katastrofu kakvu samo Greg može da priredi.', 'Если вы думали, что школьные балы — это сплошная романтика, то Грег Хэффли готов доказать, что это чистая комедия положений!', 'If you thought school dances were all about romance, Greg Heffley is here to prove they are pure, laugh-out-loud chaos!', 'Ako ste mislili da su školski plesovi samo romantični, Greg Hefli će vam dokazati da su zapravo urnebesan haos!', '/covers/DP-0637.webp', '#8b5239', 'me_sr', 'me', 'available', 'Категория: 8 разред', '["funny","friends","real"]', '["school life","humor","middle school","diary","growing up"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зачарана-учионица-638', 'DP-0638', '', 'The Enchanted Classroom', 'Začarana učionica', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'Step into a magical classroom where ordinary lessons turn into extraordinary adventures, sparking curiosity, laughter, and a lifelong love for reading and wonder.', 'Uđite u čarobnu učionicu u kojoj se obični školski časovi pretvaraju u nevjerovatne avanture, budeći maštu, smijeh i ljubav prema knjigama.', 'А что, если школьные парты и доска умеют творить чудеса, стоит лишь включить воображение?', 'What if desks, chalkboards, and notebooks could weave real magic whenever imagination takes over?', 'Šta ako obične školske klupe i tabla mogu da stvaraju čaroliju čim proradi mašta?', '/covers/DP-0638.webp', '#357266', 'me_sr', 'me', 'available', 'Категория: Dnevnik jednog smotanka. Okrutna istina', '["magic","friends","funny"]', '["school","magic","classroom","short stories","imagination"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('исидора-мун-иде-на-екскурзиjу-639', 'DP-0639', '', 'Isadora Moon Goes on a School Trip', 'Isidora Mun ide na ekskurziju', '', 'Harriet Muncaster', 'Harijet Mankaster', '', '', NULL, NULL, 4, 14, 'middle', '', 'Half fairy, half vampire, and totally unique! Isadora Moon is thrilled to head out on a school trip to a spooky historic castle. But when things get a little eerie and she meets a lonely ghost boy, Isadora and Pink Rabbit must find a way to help him feel brave again.', 'Pola vila, pola vampir i sasvim posebna! Isidora Mun jedva čeka da sa razredom pođe na izlet u drevni dvorac. Kada tamo upozna usamljenog dječaka-duha, Isidora i njen vjerni Ružičasti Zeko potrudiće se da mu pokažu kako istorija uopšte ne mora biti dosadna ni strašna.', 'Поездка в старинный замок с классом фей и вампиров превращается в искрящееся и чуточку призрачное приключение!', 'A school trip to an old castle with fairies and vampires turns into a delightfully sparkly and gently spooky adventure!', 'Školski izlet u stari dvorac sa vilama i vampirima pretvara se u pravu svjetlucavu i pomalo duhovitu avanturu!', '/covers/DP-0639.webp', '#d94b8e', 'me_sr', 'me', 'available', 'Категория: Исидора Мун', '["magic","adventure","spooky"]', '["vampires","fairies","school trip","castle","friendship"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('иде-у-луна-парк-640', 'DP-0640', '', 'Off to the Amusement Park', 'Ide u luna-park', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A cheerful and vibrant picture book capturing all the thrills of a magical day at the amusement park, from spinning carousels to fluffy cotton candy.', 'Vesela i šarena slikovnica koja dočarava uzbuđenje čarobnog dana u luna-parku, od šarenih ringišpila do slatke šećerne vune.', 'Хватайте билет на самый веселый аттракцион — яркий день в луна-парке подарит море смеха и сладкой ваты!', 'Grab your ticket for the happiest ride around — a day at the funfair packed with laughs, carousels, and sweet treats!', 'Zgrabite kartu za najveseliji ringišpil — uzbudljiv dan u luna-parku donosi pregršt smijeha i slatke zabave!', '/covers/DP-0640.webp', '#f25c54', 'me_sr', 'me', 'available', 'Категория: Исидора Мун', '["funny","adventure"]', '["amusement park","funfair","carousel","childhood","adventure"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('иде-на-балет-641', 'DP-0641', '', 'Going to Ballet', 'Ide na balet', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A charmingly illustrated book following the enchanting first steps into the world of dance, ballet shoes, and stage performances.', 'Divna ilustrovana knjiga o prvim koracima u svijetu plesa, baletskim patikicama, muzici i čaroliji nastupa na sceni.', 'Надевайте пуанты и пачку — сегодня мы отправляемся на наш самый первый настоящий урок балета!', 'Slip into your ballet shoes and tutu — today we''re pirouetting into our very first ballet class!', 'Obujte baletanke i zavrtite se — danas idemo na naš prvi pravi čas baleta!', '/covers/DP-0641.webp', '#e899a8', 'me_sr', 'me', 'available', 'Категория: Исидора Мун', '["real","friends","magic"]', '["ballet","dance","growing up","theatre","hobbies"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('слави-ро-ендан-642', 'DP-0642', '', 'Celebrates Birthday', 'Slavi rođendan', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A cheerful tale all about the excitement of celebrating a birthday with games, presents, good friends, and lots of festive joy.', 'Vesela priča o radosti i uzbuđenju proslave rođendana uz igre, poklone, drage prijatelje i pregršt svečane zabave.', 'Какой же день рождения без торта, воздушных шариков и лучших друзей — скорее открывай и присоединяйся к празднику!', 'What kind of birthday is complete without cake, balloons, and best friends? Jump right in and join the celebration!', 'Kakav bi to rođendan bio bez torte, balona i najboljih drugara — otvori knjigu i pridruži se veseloj zabavi!', '/covers/DP-0642.webp', '#e05638', 'me_sr', 'me', 'available', 'Категория: Исидора Мун', '["friends","funny"]', '["birthday","celebration","friends","party","family"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('упадда-у-неволю-643', 'DP-0643', '', 'Gets into Trouble', 'Upada u nevolju', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A lighthearted and cautionary tale about curiosity, comical mischief, and the unexpected mishaps that happen when little heroes follow their adventurous impulses. Full of lessons on honesty, resilience, and finding creative ways out of sticky situations.', 'Duhovita i poučna priča o radoznalosti, nestašlucima i neočekivanim nezgodama u koje upadaju mali junaci kada prate svoje avanturističke impulse. Knjiga puna topline o tome kako pronaći izlaz iz svake nevolje i naučiti važnu lekciju.', 'Забавная и жизненная история о том, как легко попасть в переплёт из-за любопытства и как весело выпутываться из любых передряг!', 'A delightfully relatable tale proving that while getting into trouble is easy, getting out of it takes heart, humor, and a bit of wit!', 'Zabavna i poučna priča koja dokazuje da je u nevolju lako upasti, ali da se uz malo mudrosti i humora iz svake može naći izlaz!', '/covers/DP-0643.webp', '#d9534f', 'me_sr', 'me', 'available', 'Категория: Исидора Мун', '["funny","adventure"]', '["mischief","humor","adventures","growing up","life lessons"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('иде-на-кампованье-644', 'DP-0644', '', 'Going Camping', 'Ide na kampovanje', '', 'Unknown', 'Nepoznato', '', '', NULL, NULL, 4, 14, 'middle', '', 'A cheerful and heartwarming story about preparing for an outdoor journey, pitching a tent, and discovering the little wonders of camping in nature.', 'Vesela i topla priča o pripremama za izlet u prirodu, postavljanju šatora i otkrivanju malih avantura na kampovanju.', 'Пакуйте спальники и фонарики: впереди ночь в палатке, треск костра и звёздное небо!', 'Pack your sleeping bags and flashlights: cozy tent adventures and starry skies await!', 'Spakujte vreće za spavanje i baterijske lampe: čeka vas uzbudljiva noć pod šatorom i zvjezdanim nebom!', '/covers/DP-0644.webp', '#3f7a4d', 'me_sr', 'me', 'available', 'Категория: Исидора Мун', '["adventure","funny","friends"]', '["camping","nature","outdoors","tent","friendship"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('крече-у-школу-645', 'DP-0645', '', 'Off to School', 'Kreće u školu', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A cheerful and encouraging guide created to help young children take their exciting first steps into the school world, easing first-day jitters and introducing everyday classroom routines.', 'Vesela i ohrabrujuća knjiga osmišljena da podrži mališane dok prave svoje prve korake ka školi, razbija tremu i priprema ih za nove navike i drugare u školskoj klupi.', 'Идеальная поддержка для маленьких храбрецов, готовых уверенно сделать свой первый шаг в школьный класс!', 'The perfect companion to boost confidence and turn first-day school jitters into pure excitement!', 'Savršeno ohrabrenje za male đake koji s osmijehom i radoznalošću kreću u prve školske pobjede!', '/covers/DP-0645.webp', '#3b7aa3', 'me_sr', 'me', 'available', 'Категория: Исидора Мун', '["real","friends"]', '["school","first day of school","growing up","learning","friendship"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ubica-demona-4-646', 'DP-0646', '', 'Demon Slayer: Kimetsu no Yaiba, Vol. 4', 'Ubica demona 4', '', 'Koyoharu Gotouge', 'Kojoharu Gotoge', '', 'Darkwood', 2022, '9788661635823', 4, 14, 'middle', '', 'Tanjiro, Inosuke, and Zenitsu venture onto Mount Natagumo, where terrifying spider demons lurk in the dark canopy. As webs tighten and venom spreads, the young demon slayers must push past their limits to survive their deadliest trial yet.', 'Tanđiro, Inosuke i Zenicu kreću na planinu Natagumo, gdje se u mračnoj šumi kriju jezivi demoni pauci. Dok se smrtonosne mreže stežu, mladi lovci na demone moraće da pređu sve svoje granice kako bi preživjeli.', 'Держитесь крепче за свои клинки: на горе Натагумо Тандзиро и друзей ждут самые жуткие и захватывающие паучьи битвы!', 'Hold tight to your swords—Mount Natagumo plunges Tanjiro and his companions into their spookiest, most thrilling battles yet!', 'Držite se čvrsto za mačeve: na paukovoj planini Natagumo Tanđira i drugare čekaju najjezivije i najuzbudljivije borbe do sada!', '/covers/DP-0646.webp', '#234566', 'me_sr', 'me', 'available', 'Категория: Naruto 8 borba opasna po život', '["adventure","magic","spooky"]', '["manga","demon slayer","anime","action","samurai"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('drevni-egipat-647', 'DP-0647', '', 'Ancient Egypt', 'Drevni Egipat', '', 'Unknown', 'Nepoznat autor', '', 'Pobjeda / Liber Novus', 2011, '978-86-309-0310-6', 4, 14, 'middle', '', 'A captivating illustrated journey into Ancient Egypt: from the construction of majestic pyramids and the secrets of pharaohs'' tombs to everyday life along the banks of the Nile. This book introduces young explorers to the mysteries of mummies, hieroglyphs, and mythology of an ancient civilization.', 'Uzbudljivo ilustrovano putovanje u Drevni Egipat: od izgradnje veličanstvenih piramida i tajni faraonskih grobnica do svakodnevnog života na obalama Nila. Knjiga upoznaje mlade istraživače sa zagonetkama mumija, hijeroglifima i mitovima drevne civilizacije.', 'Примерьте золотую маску фараона и раскройте тайны пирамид, не отряхивая песок пустыни со страниц!', 'Put on the golden mask of a pharaoh and unravel the secrets of the pyramids without getting desert sand on your carpet!', 'Stavite zlatnu masku faraona i otkrijte tajne piramida bez potrebe da tresete pustinjski pijesak sa knjige!', '/covers/DP-0647.webp', '#c5903b', 'me_sr', 'me', 'available', 'Категория: Naruto 8 borba opasna po život', '["adventure","real"]', '["ancient egypt","pyramids","history","encyclopedia","archaeology"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вируси-школска-енциклопедиjа-648', 'DP-0648', '', 'Viruses: School Encyclopedia', 'Virusi: Školska enciklopedija', '', 'Unknown', 'Nepoznat autor', '', 'Књига-комерц / Политика', 2007, '978-86-7712-195-2', 4, 14, 'middle', '', 'An informative children''s encyclopedia exploring the microscopic world of viruses and bacteria. Discover how these tiny organisms function, reproduce, spread illness, and how our immune system defends the human body against invisible invaders.', 'Informativna dječja enciklopedija koja istražuje mikroskopski svijet virusa i bakterija. Otkrijte kako ovi sićušni organizmi funkcionišu, razmnožavaju se, izazivaju bolesti i kako naš imuni sistem brani tijelo od nevidljivih napadača.', 'Загляните в микроскоп и узнайте все секреты коварных вирусов и супергероев нашего иммунитета!', 'Peer through the microscope and uncover all the secrets of tricky viruses and our immune system''s superhero defenders!', 'Zaviri kroz mikroskop i otkrij sve tajne lukavih virusa i superheroja našeg imunog sistema!', '/covers/DP-0648.webp', '#2c7a7b', 'me_sr', 'me', 'available', 'Категория: Naruto 8 borba opasna po život', '["real","adventure"]', '["science","biology","health","encyclopedia","microbiology"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мали-принц-649', 'DP-0649', '', 'The Little Prince', 'Mali princ', '', 'Antoine de Saint-Exupéry', 'Antoan de Sent Egziperi', '', 'Вулкан знање', 2020, '9788610031713', 4, 14, 'middle', '', 'A poetic and timeless philosophical tale about a gentle young prince who journeys across planets, tames a wise fox, and learns that what is most essential is invisible to the eye.', 'Poetska i bezvremena priča o malom dječaku sa daleke zvijezde koji putuje svemirom, uči kako pripitomiti lisicu i podsjeća nas da se samo srcem dobro vidi.', 'Трогательная история о звёздах, розах и дружбе, которая напоминает взрослым и детям о самом главном на свете.', 'A tender classic reminding dreamers of all ages that the most wondrous things in the universe can only be felt with the heart.', 'Nježni klasik koji nas uči da se samo srcem dobro vidi i da su najvažnije stvari na svijetu oku nevidljive.', '/covers/DP-0649.webp', '#dca238', 'me_sr', 'me', 'available', 'Категория: доктор jojболи', '["magic","friends","adventure"]', '["classic","friendship","stars","philosophy","growing up"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('у-свиjету-медведева-и-лептиров-650', 'DP-0650', '', 'In the World of Bears and Butterflies', 'U svijetu medvjeda i leptirova', '', 'Branko Ćopić', 'Branko Ćopić', '', 'Ringier Axel Springer / Блиц библиотека', 2016, '978-86-6389-038-1', 4, 14, 'middle', '', 'A delightful collection of lyrical and humorous stories by the beloved classic storyteller Branko Ćopić. Step into an enchanting forest realm where clumsy bears, carefree butterflies, and cheeky woodland critters share unforgettable lessons about friendship, freedom, and the whimsy of nature.', 'Divna zbirka lirskih i vedrih priča omiljenog pisca Branka Ćopića. Zakoračite u šumski svijet u kom nespretni medvjedi, lepršavi leptiri i vesele šumske životinje dijele tople lekcije o prijateljstvu, slobodi i ljepoti prirode.', 'Добрые и поэтичные лесные сказки Бранко Чопича научат смотреть на природу с улыбкой и нежностью!', 'Branko Ćopić’s whimsical forest fables are pure sunshine, full of playful bears and gentle woodland charm!', 'Ćopićeve tople i duhovite šumske zgode izmamiće osmijeh svakom malom i velikom sanjaru!', '/covers/DP-0650.webp', '#4a7c59', 'me_sr', 'me', 'available', 'Категория: Синдбад морепловац', '["animals","funny","adventure"]', '["forest animals","classic tales","short stories","balkan classics","friendship"]', 1792836322699, 1792845663715);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('jednorog-necurog-651', 'DP-0651', '', 'The Unicorn That Said No', 'Jednorog Nećurog', '', 'Marc-Uwe Kling', 'Mark-Uve Kling', 'Astrid Hen', 'Pčelica izdavaštvo', 2021, '9788660880347', 4, 14, 'middle', '', 'In the sugary sweet Heart Forest, a fluffy unicorn is born who stubbornly refuses to be sweet and compliant—to absolutely everything, he replies with a resolute "NO!". Fed up with rainbows and polite chatter, the defiant NEINhorn ventures into the wide world, teaming up with a raccoon who doesn''t listen, a dog who couldn''t care less, and a contrary princess. Together, they prove that being a little grumpy is so much better with great friends.', 'U carstvu duga i oblaka od šećerne vune rodio se ljupki jednorog koji odbija da se uklopi u savršeni svijet – na sve što mu ponude, on drsko odgovara sa „NEĆU!“. Sit pretjerane slatkoće, Nećurog odlazi u svijet i pronalazi družinu tvrdoglavih osobenjaka: medvjeda koji ne sluša, psa koga baš briga za sve i princezu koja stalno protivrječi. Biti tvrdoglav u društvu pravih prijatelja postaje prava avantura!', 'Терапевтическая и уморительно смешная сказка для каждого маленького бунтаря, чьё главное коронное слово — громкое «Неть!».', 'A laugh-out-loud, cheeky adventure celebrating every child''s favorite superpower: a firm and resounding ''NO!''.', 'Umorna od slatkih bajki, ova presmiješna priča savršen je melem za sve male tvrdoglavce čija je omiljena riječ „NEĆU!“.', '/covers/DP-0651.webp', '#e85d88', 'me_sr', 'me', 'available', 'Категория: Три красна прстена', '["funny","magic","friends"]', '["unicorns","humor","friendship","stubbornness","animals"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('снежне-речи-652', 'DP-0652', '', 'Snowy Words', 'Snježne riječi', '', 'Various Authors', 'Grupa autora', 'Кjaра Нази', 'Пчелица издаваштво', 2023, '978-86-6088-137-5', 4, 14, 'middle', '', 'A charming winter anthology published by Pčelica, gathering sparkling poems and short stories full of frost, sledding, holidays, and the magic of winter.', 'Šarmantna zimska zbirka u izdanju Pčelice, puna razigranih pjesama i priča o snijegu, sankanju, praznicima i zimskim čarolijama.', 'Идеальная книга для чтения укутавшись в тёплый плед, пока за окном кружатся пушистые снежинки!', 'The ultimate cozy read to snuggle up with while fluffy snowflakes swirl past the window!', 'Savršena knjiga za ušuškavanje pod toplim ćebetom dok napolju viju snježne pahulje!', '/covers/DP-0652.webp', '#4a85b6', 'me_sr', 'me', 'available', 'Категория: Три красна прстена', '["magic","friends","real"]', '["winter","snow","poetry","stories","holidays"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('одабране-песме-653', 'DP-0653', '', 'Selected Poems', 'Odabrane pjesme', '', 'Various Authors', 'Grupa autora', 'Чувари', 'Чувари', 2021, NULL, 4, 14, 'middle', '', 'A beautiful treasury of selected verses that celebrate childhood, nature, and the musicality of words, ideal for shared family reading and reciting.', 'Predivna zbirka odabranih stihova koji slave djetinjstvo, prirodu i muzikalnost riječi, savršena za porodično čitanje i recitovanje naglas.', 'В этих мелодичных строчках прячутся звонкое детство, радость и стихи, которые так приятно разучивать и читать вслух всей семьёй.', 'Inside these melodic verses hide the gentle rhythms of childhood and rhymes that are a pure joy to read aloud together.', 'U ovim melodioznim stihovima kriju se radost djetinjstva i rime koje je pravo uživanje čitati i recitovati naglas.', '/covers/DP-0653.webp', '#a63a3a', 'me_sr', 'me', 'available', 'Категория: Три красна прстена', '["friends","magic"]', '["poetry","verses","anthology","classics","rhymes"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-раскраски-bajke-bojanke-654', 'DP-0654', '', 'Fairy Tales: Coloring Book', 'Bajke bojanke', '', 'Unknown', 'Nepoznati autor', '', '', NULL, NULL, 4, 14, 'middle', '', 'A delightful collection of timeless fairy tales paired with engaging coloring illustrations, inviting young artists to bring magical castles, brave heroes, and wondrous creatures to life with their own vibrant colors.', 'Divna zbirka bezvremenih bajki praćena ilustracijama za bojenje, koja poziva male umjetnike da ožive čarobne dvorce, hrabre junake i čudesna stvorenja svojim omiljenim bojama.', 'Любимые сказочные герои ждут, когда ты вдохнёшь в них жизнь с помощью цветных карандашей и капельки волшебства!', 'Timeless fairy tales are waiting for your colorful touch to bring their magical worlds to life!', 'Omiljeni junaci iz bajki jedva čekaju da ih oživiš svojim bojicama i maštom!', NULL, '#e67e22', 'me_sr', 'me', 'available', 'Категория: Три красна прстена', '["magic","adventure"]', '["fairy tales","coloring book","creativity","classic stories","activity book"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('treasure-island-655', 'DP-0655', '', 'Treasure island', '', '', 'Robert Louis Stevenson', '', '', 'Bonney Press', 2019, '9781865151502', 4, 14, 'middle', '', '', '', '', '', '', '/covers/DP-0655.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792841613367);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-gruffalo-656', 'DP-0656', '', 'The Gruffalo', '', '', 'Julia Donaldson', '', '', '', NULL, NULL, 4, 14, 'middle', '', 'Julia Donaldson&#39;s characters are loved around the world, and none more so than the Gruffalo. It has been more than two decades since the little mouse took a stroll through the deep dark wood, and millions of kids and adults worldwide fell in love with the creature with terrible tusks and claws.', '', '', '', '', '/covers/DP-0656.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-gruffalo-39-s-child-657', 'DP-0657', '', 'The Gruffalo&#39;s Child', '', '', '', '', '', '', NULL, NULL, 4, 14, 'middle', '', 'Step back into the deep, dark woods for a special celebration with The Gruffalo’s Child 20th Anniversary Edition! This beloved story of curiosity and bravery comes with a sparkly new cover and fantastic bonus content. Follow the Gruffalo’s Child as she ventures out in search of the Big Bad Mouse, with captivating rhymes that have delighted families for two decades. Plus, with fun extras like character headbands and a sing-along song, this edition brings extra magic to storytime.', '', '', '', '', '/covers/DP-0657.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('charlie-cook-s-favourite-book-658', 'DP-0658', '', 'Charlie Cook’s Favourite Book', '', '', '', '', '', '', NULL, NULL, 4, 14, 'middle', '', 'A celebration of the joy of reading, Charlie Cook’s Favourite Book is a story about how anyone can find magic within the pages of a book. With Julia Donaldson’s trademark rhyming verse and Axel Scheffler’s illustrations, celebrate the thirtieth anniversary of this iconic partnership and embark on an adventure with Charlie Cook as he comes across aliens, frogs, monarchs and even Goldilocks!', '', '', '', '', '/covers/DP-0658.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-smartest-giant-in-town-659', 'DP-0659', '', 'The Smartest Giant in Town', '', '', '', '', '', '', NULL, NULL, 4, 14, 'middle', '', 'With bonus content, this hardback edition of Julia Donaldson&#39;s classic tale of friendship with one very scruffy, but very kind and much-loved giant. George doesn’t want to be the scruffiest giant in town, so when he sees a giant-sized clothes shop he decides it’s time for a smart new look. His new clothes make him the smartest giant in town, until some new friends need his help.', '', '', '', '', '/covers/DP-0659.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-snail-and-the-whale-660', 'DP-0660', '', 'The Snail and the Whale', '', '', '', '', '', '', NULL, NULL, 4, 14, 'middle', '', 'Go on an adventure with a tiny snail and the great big grey-blue humpback whale in this anniversary edition of the much-loved The Snail and the Whale. A little snail hitches a ride on the tail of a whale and feels so small in the vast world he sees. But when disaster strikes, it’s the tiny snail who saves the day. Julia Donaldson&#39;s characters will charm little ones in this story of friendship.', '', '', '', '', '/covers/DP-0660.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('super-stella-661', 'DP-0661', '', 'Super Stella', '', '', 'Marina Cupic', '', 'Bad brain studio', 'Europska kuca', NULL, NULL, 4, 14, 'middle', '', 'comics about european countries for kids', '', '', '', '', '/covers/DP-0661.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-little-wooden-robot-and-th-662', 'DP-0662', '', 'The Little Wooden Robot and the Log princess', '', '', 'Tom Gauld', '', 'Tom Gauld', '', NULL, NULL, 4, 14, 'middle', '', 'In this fresh new fairy tale, a wooden robot embarks on a quest to find his missing sister-- making for a memorable contemporary bedtime story in acclaimed graphic novelist Tom Gauld&#39;s first picture book for children. For years, the king and queen have tried desperately to have a baby. Their wish was granted twice, when an engineer and a witch gave them a little wooden robot and an enchanted log princess. But there&#39;s just one catch: every night when the log princess sleeps, she transforms back into an ordinary log, and can only be woken up with magic words. The princess and her robot brother are are inseparable, until the sleeping princess, mistaken for lumber, is accidentally carted off to parts unknown. Now it&#39;s up to her devoted brother to find her, and get them safely back home. They need to take turns to get each other home, and on the way, they face a host of adventures involving the Queen of Mushrooms, a magic pudding, a baby in a rosebush, and an old lady in a bottle. This is acclaimed graphic novelist Tom Gauld&#39;s first picture book for children, inspired by a bedtime story he made up for his daughters. In his words, "I was trying to make a book inspired by three different sets of books: The books that I remember enjoying as a child, the books that I watched my daughters enjoying, and the books I enjoy now as an adult. I wanted the book to have its own quirky feeling but also to function like a classic bedtime story."', '', '', '', '', '/covers/DP-0662.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('making-the-moose-out-of-life-663', 'DP-0663', '', 'Making the moose out of life', '', '', 'Oldland', '', '', 'kids can press', NULL, NULL, 4, 14, 'middle', '', 'From the creator of Big Bear Hug comes the comic-adventure story of a mild-mannered moose who learns how to take life by the antlers. This moose may live in the wild, but he doesn’t act it --- he watches from the sidelines as his friends have fun. Every now and then, he wonders if he’s missing out on anything. When the moose finally takes a chance and goes on a solo sailing trip, a raging storm carries him far from everything he knows. Will he curl up in a ball and cry, or make the most of it? The moose’s unlikely hero-journey is a lighthearted, contemporary fable that celebrates living life to the fullest.', '', '', '', '', '/covers/DP-0663.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('maisys-bathtime-664', 'DP-0664', '', 'Maisys bathtime', '', '', 'Luciy Cousins', '', '', 'Walker Books', NULL, NULL, 4, 14, 'middle', '', 'Very young children will go crazy for Maisy — and bathtubs! Maisy and her friends act out the lively adventures young children have — or dream of having — every day. In Maisy Takes a Bath, Tallulah doesn&#39;t want Maisy to take a bubble bath just now. She wants her to come out and play instead. What will Maisy&#39;s friend do next? Here&#39;s another very good reason to be crazy for Maisy!', '', '', '', '', '/covers/DP-0664.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('red-and-the-city-665', 'DP-0665', '', 'Red and the city', '', '', 'Marie Voigt', '', '', 'Oxford', NULL, NULL, 4, 14, 'middle', '', 'A contemporary and beautifully illustrated retelling of Little Red Riding Hood. Can Red find her way to Grandma&#39;s house, or will she be swallowed up by the choices awaiting her in the big city? Published On: 2023-04-18', '', '', '', '', '/covers/DP-0665.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('singing-in-the-rain-666', 'DP-0666', '', 'Singing in the rain', '', '', 'Tim Hopgood', '', '', 'Oxford', NULL, NULL, 4, 14, 'middle', '', 'I&#39;m singing in the rain, just singing in the rain, Oh, what a glorious feeling! Spring calls in this classic Broadway number, brought to life in a beautiful picture book―perfect for sharing! Jump in puddles, raise umbrellas, and dance with joy through the pages of this visual story. With colorful, springy scenes and the familiar lyrics, this is a beautiful, gift-worthy, feel-good read-aloud.', '', '', '', '', '/covers/DP-0666.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('cyril-the-lonely-cloud-667', 'DP-0667', '', 'Cyril the lonely cloud', '', '', 'Tim Hopgood', '', '', 'Oxford', NULL, NULL, 4, 14, 'middle', '', 'It is sad but true that no one is ever pleased to see Cyril the cloud. He&#39;s always being blamed for ruining everyone&#39;s fun: casting shadows over everywhere he goes, and making things look dull and miserable. So, one day, Cyril drifts far, far away in search of a friendly face: over farmland, towns, and an ocean . . . Eventually he arrives in a new land whose ground is baking hot. Here everyone welcomes the shade Cyril gives. This makes Cyril so happy that he cries big glorious tears of joy. And his tears soak the land and everything seems to smile. And that is all Cyril ever wanted - to look down on the world and see a happy smile. A beautiful story that taps right into what Tim Hopgood&#39;s books are all about: celebrating the natural world and promoting a positive outlook on life.', '', '', '', '', '/covers/DP-0667.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('tibble-and-grandpa-668', 'DP-0668', '', 'Tibble and grandpa', '', '', 'Wendy Meddour', '', 'Daniel Egnius', 'Oxford', NULL, NULL, 4, 14, 'middle', '', 'A touching intergenerational story of love and resilience. Tibble loves talking to Grandpa. But Grandpa has stopped listening. Mum says just give him time. But Tibble wants to talk to Grandpa now. . . So Tibble tries his favourite game - TOP THREES! And something amazing happens. Grandpa starts talking again . . . A moving story about love, loss, and the wonder of families.', '', '', '', '', '/covers/DP-0668.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('when-lions-roar-669', 'DP-0669', '', 'When lions roar', '', '', 'Robie H. Harris', '', 'Chris Raschka', 'Orchard books', NULL, NULL, 4, 14, 'middle', '', 'WHEN LIONS ROAR is a caring and reassuring story of a young child who faces his fear and makes his world a safe place again. 2012 Caldecott Medalist Chris Raschka and bestselling author Robie H. Harris pair together to create a comforting story for young readers when their world becomes unsettled.Thunder is booming!A big dog is barking!Sometimes the world seems scary--too scary. But what if you shout, "GO AWAY!" Will the sun come out? Will a flower bloom?', '', '', '', '', '/covers/DP-0669.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('bella-lost-and-found-670', 'DP-0670', '', 'Bella lost and found', '', '', 'Ryan o&#39;Rourke', '', '', 'Harper', NULL, NULL, 4, 14, 'middle', '', 'Bella is an indoor cat who lives inside a lighthouse and who has always imagined exploring the high seas. One day, Bella hops onto a sailboat and drifts away. . . . In this whimsical picture book, author-illustrator Ryan O&#39;Rourke introduces lovable Bella, whose travels bring her to new friends and magical under-the-sea adventures and, ultimately, return her home. O&#39;Rourke&#39;s distinctive artwork conveys the humor and curiosity of Bella and her friends, including a friendly whale and a wise octopus. Sea dogs and landlubbers alike will delight in the beautiful seascapes inspired by O&#39;Rourke&#39;s summers on Cape Cod.', '', '', '', '', '/covers/DP-0670.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('tiger-671', 'DP-0671', '', 'Tiger', '', '', 'Sherry Been', '', 'Cathy Morrison', 'Odyssey', NULL, NULL, 4, 14, 'middle', '', 'If you were a tiger, we would call you KING! You are the ruler of all cats! Strong, smart, and swift, the beautiful tiger has roamed the wild for centuries. This first look is especially designed for emerging and early readers, in a fashion that offers a close look at one of the most beautiful cats in the world. Tactile, full-color illustrations enhance the text, which is easy to follow yet full of facts about tiger bodies, habitat, lifestyle, diet, and more. Youngsters will delight in the text-to-self comparisons while learning how these big cats love to swim, stalk through tall grass, and speed silently through the jungles. Join in the learning for a read that s positively beastly!', '', '', '', '', '/covers/DP-0671.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('subway-story-672', 'DP-0672', '', 'Subway story', '', '', 'Julia Sarcone-Roach', '', '', 'Knopf', NULL, NULL, 4, 14, 'middle', '', 'Never was there a subway car who loved her job more than Jessie. From morning to night she carried all sorts of people all sorts of places—to work and school and World&#39;s Fairs, over bridges and through tunnels—sometimes she even took a pigeon along for the ride! But as time passed, sleek new silver cars began to take over the tracks, banishing Jessie to an abandoned lot. What will she do with no passengers to carry? And where will she go now that she&#39;s no longer welcome on the tracks? Based on the true story of 1960&#39;s-era subway cars that are now being used to create artificial reefs in the Atlantic, this stunningly illustrated second book from Julia Sarcone-Roach is sure to delight scuba diving historians and kids alike.', '', '', '', '', '/covers/DP-0672.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('my-little-book-of-trains-673', 'DP-0673', '', 'My little book of trains', '', '', '', '', '', 'QEB', NULL, NULL, 4, 14, 'middle', '', 'From early steam engines to Hyperloop trains of the future, this information book offers descriptions of the different types of train, introducing some special locomotives, their history and the jobs they do, accompanied by colour photographs and a glossary and index. Age 4+', '', '', '', '', '/covers/DP-0673.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('countdown-to-christmas-674', 'DP-0674', '', 'Countdown to Christmas', '', '', '', '', '', 'Dysney', NULL, NULL, 4, 14, 'middle', '', 'Celebrate the spirit of Christmas with this enchanting 64-page picture book complete with ribbon marker, featuring one story for each of the 25 days of December leading up to Christmas.', '', '', '', '', '/covers/DP-0674.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('you-got-a-rock-charlie-brown--675', 'DP-0675', '', 'You got a rock, Charlie Brown!', '', '', 'Charles M. Shulz', '', '', 'Simon&Shuster', NULL, NULL, 4, 14, 'middle', '', 'Join Charlie Brown, Snoopy, Lucy, and the rest of the Peanuts gang as they go trick-or-treating in this Level 2 Ready-to-Read! It’s Halloween and that means one thing…it’s time for Charlie Brown and his friends to go trick-or-treating! Pigpen gets a chocolate bar. Schroeder gets a quarter. While all of Charlie Brown’s friends are getting treats, he gets…a rock! Good grief—what a trick!', '', '', '', '', '/covers/DP-0675.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('my-book-about-me-676', 'DP-0676', '', 'My book about me', '', '', 'Mr Men', '', '', 'Egmont', NULL, NULL, 4, 14, 'middle', '', '', '', '', '', '', '/covers/DP-0676.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('luna-loves-world-book-day-677', 'DP-0677', '', 'Luna loves World book day', '', '', 'Joseph Coelho', '', 'Fiona Lumbers', '', NULL, NULL, 4, 14, 'middle', '', 'A special mini adventure with Luna for World Book Day 2021, from the creators of Luna Loves Library Day and Luna Loves Art. Today is World Book Day and Luna can’t wait. She has the whole day planned... Dress up as her favourite book character: a unicorn! Meet an author and an illustrator. Buy a new book with her book token. But - disaster! - Luna the Unicorn&#39;s costume has ripped! Can Dad come to the rescue with a potato and a little bit of book magic?', '', '', '', '', '/covers/DP-0677.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('where-are-the-beatles-678', 'DP-0678', '', 'Where are the Beatles', '', '', '', '', '', 'Arka', NULL, NULL, 4, 14, 'middle', '', 'Help! Can you find the Fab Four? This quirky, vibrant, and comically-illustrated book features scenes inspired by The Beatles&#39; rock star lives and their rapid rise to fame. Find Yoko Ono, George Martin, David Bowie, and many others, too. Between us, we can work it out (with a little help from our friends)!', '', '', '', '', '/covers/DP-0678.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-story-of-the-little-mole-w-679', 'DP-0679', '', 'The story of the little mole who knew it was none of his business', '', '', 'Werner Holzwarth', '', 'Wolf Erlbruch', 'Pavilion', NULL, NULL, 4, 14, 'middle', '', 'Since its first publication in 1993, The Story of the Little Mole Who Went in Search of Whodunit has been charming readers young and old with its unconditionally candid tale that raises bathroom humor to new heights. Splendidly straightforward and comic, it is at first unbelievable and then irresistible. When Little Mole looks out of his hole one morning�PLOP!�something lands on his head. Whodunit? In this irreverent, forthright mystery, Little Mole questions each of his neighbors, trying to find out whodunit on his head. In the end, with the help of some flies, Little Mole gets his revenge. Now a new generation of readers will enjoy this one-of-a-kind, stinky, and delightful story for the first time.', '', '', '', '', '/covers/DP-0679.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
