INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('things-that-go-688', 'DP-0688', '', 'Things that go', '', '', '', '', '', 'Clever', NULL, NULL, 4, 14, 'middle', '', 'Для современного человека знание английского языка - это необходимость. Исследования показывают, что иностранные языки лучше всего осваивать с детства. Специальная методика поможет вам воспитать билингвального ребёнка. Используйте для занятий книги из серии Мой первый английский и добивайтесь успеха! Эта книжка-игра с весёлыми заданиями идеально подходит для первого знакомства с английским языком! Малыш выучит названия 25 видов транспорта, 5 базовых фигур и 9 основных цветов. Удобный формат, яркие рисунки, плотный картон - вам пнравится играть с этой книгой снова и снова!', '', '', '', '', '/covers/DP-0688.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('how-are-you-689', 'DP-0689', '', 'How are you', '', '', '', '', '', 'Clever', 2019, '978-5-00154-008-3', 4, 14, 'middle', '', '', '', '', '', '', '/covers/DP-0689.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792841762907);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('lets-count-690', 'DP-0690', '', 'Lets count', '', '', '', '', '', 'Clever', NULL, NULL, 4, 14, 'middle', '', '20 минут в день с этой книгой - и через неделю ваш ребёнок ответит на вопрос How many? (Сколько?) по-английски. С книгами серии Мой первый английский учить язык легко и интересно. Яркие иллюстрации и озвучка активируют зрительную, слуховую и ассоциативную память. Герои книги, Питер и Эмили, полюбятся вашему малышу и помогут ему заниматься с удовольствием.', '', '', '', '', '/covers/DP-0690.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('what-colour-is-it-691', 'DP-0691', '', 'What colour is it', '', '', '', '', '', 'Clever', NULL, NULL, 4, 14, 'middle', '', '20 минут в день с этой книгой - и через неделю ваш ребёнок ответит на вопрос What colour is it? (Какой это цвет?) по-английски. С книгами серии Мой первый английский учить язык легко и интересно. Яркие иллюстрации и озвучка активируют зрительную, слуховую и ассоциативную память. Герои книги, Питер и Эмили, полюбятся вашему малышу и помогут ему заниматься с удовольствием.', '', '', '', '', '/covers/DP-0691.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('whats-your-name-692', 'DP-0692', '', 'Whats your name', '', '', '', '', '', 'Clever', 2019, '978-5-00154-011-3', 4, 14, 'middle', '', '', '', '', '', '', '/covers/DP-0692.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792841771543);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('i-can-read-by-myself-693', 'DP-0693', '', 'I can read by myself', '', '', '', '', '', 'Clever', 2024, '978-5-00211-656-0', 4, 14, 'middle', '', '', '', '', '', '', '/covers/DP-0693.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792841780369);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('the-race-694', 'DP-0694', '', 'The race', '', '', 'Caroline Repchuk', '', 'I&#39;ll. Alison Jay', '', NULL, NULL, 4, 14, 'middle', '', 'The classic Aesop fable has been given a contemporary twist in The Race. Featuring the instantly recognizable Tortoise and Hare, this delightful re-telling features a rhyming text and an exciting race around the world, via boats, planes and even a hot air balloon. In Hares haste, he runs into all kinds of traveling trouble, while slow-and-steady Tortoise makes a leisurely trip to the end destination -New York! Lush illustrations combine with witty text to make the familiar morals of patience and diligence ring true for a whole generation.', '', '', '', '', '/covers/DP-0694.webp', '#2f8a84', 'en', 'en', 'available', '', '[]', '[]', 1792836322699, 1792844969699);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('cars-695', 'DP-0695', '', 'Cars', '', '', 'Disney/Pixar', '', '', 'Эксмодетство', 2019, '978-5-04-101994-5', 4, 14, 'middle', '', '', '', '', '', '', '/covers/DP-0695.webp', '#2f8a84', 'en', 'en', 'available', 'Категория: Hansel & Gretel', '[]', '["Hansel & Gretel"]', 1792836322699, 1792841788742);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('super-stella-696', 'DP-0696', '', 'super Stella', '', '', 'Evropska kuca', '', '', 'Evropska kuća', 2024, '978-9940-9725-8-5', 4, 14, 'middle', '', '', '', '', '', '', '/covers/DP-0696.webp', '#2f8a84', 'en', 'en', 'available', 'Категория: Hansel & Gretel', '[]', '["Hansel & Gretel"]', 1792836322699, 1792841805391);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('название-697', 'DP-0697', 'Название', 'Title', 'Naslov', 'Автор', 'Author', 'Autor', 'Иллюстрации', 'Издательство', NULL, NULL, 6, 16, 'middle', 'Аннотация', 'An engaging non-fiction guide packed with fascinating facts and discoveries to spark the curiosity of inquisitive young minds.', 'Zanimljiva edukativna knjiga puna fascinantnih činjenica i otkrića koja će probuditi radoznalost svakog mladog istraživača.', 'Идеальная книга для всех «почемучек», готовых открывать секреты окружающего мира страница за страницей!', 'The ultimate pick for curious minds who love uncovering the secrets of how our world really works!', 'Savršena knjiga za sve radoznalce spremne da otkrivaju tajne svijeta oko nas, stranicu po stranicu!', NULL, '#2e6f9e', 'nonfiction', 'ru', 'available', 'Возрастная адресация | Примечания | Читатели | Дата выдачи (текущая) | Дата возврата (текущая)', '["real","adventure"]', '["nonfiction","curiosity","discovery","knowledge","science"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('анатомикум-698', 'DP-0698', 'Анатомикум', 'Anatomicum', 'Anatomikum', 'Дженнифер Пакстон', 'Jennifer Paxton', 'Dženifer Pakston', 'Кэти Видеманн', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Добро пожаловать в наш «Анатомикум». Этот постоянно открытый музей готов познакомить посетителей с экспонатами, рассказывающими об удивительном строении человеческого тела. Вы увидите, как самые разные части тела — от скелета и лицевых мышц до клеток мозга, отвечающих за наши мысли, — слаженно работают вместе. Заходите к нам и совершите потрясающее путешествие по человеческому организму.', 'Welcome to Anatomicum, a museum that never closes, ready to introduce visitors to the marvelous architecture of the human body. Discover how diverse systems—from the skeleton and facial muscles to the brain cells responsible for our thoughts—work seamlessly together in this fascinating journey beneath the skin.', 'Dobro došli u Anatomikum, muzej koji je uvijek otvoren i spreman da vas upozna sa čudesnom građom ljudskog tijela. Otkrijte kako različiti djelovi organizma — od kostura i mišića lica do moždanih ćelija zaduženih za misli — skladno sarađuju na ovom nevjerovatnom putovanju kroz ljudsko tijelo.', 'Загляните под собственную кожу без скальпеля и страха — это самый красивый музей человеческого тела, от которого просто захватывает дух!', 'Step inside a breathtaking museum of human anatomy, where you can marvel at our intricate inner workings without needing a scalpel!', 'Zavirite pod sopstvenu kožu bez straha i skalpela — ovo je najljepši anatomski muzej u formi knjige koji oduzima dah!', '/covers/DP-0698.webp', '#8c3426', 'nonfiction', 'ru', 'available', '6+ | Энциклопедия', '["real","adventure"]', '["human body","anatomy","science","encyclopedia","biology"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('анималиум-699', 'DP-0699', 'Анималиум', 'Animalium', 'Animalijum', 'Дженни Брум', 'Jenny Broom', 'Dženi Brum', 'Кейти Скотт', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Добро пожаловать в наш «Анималиум». Этот постоянно открытый музей готов познакомить посетителей любого пола и возраста с удивительной коллекцией, включающей более 160 видов животных. Вы узнаете, как они эволюционировали, заглянете в анатомическую лабораторию и познакомитесь с разнообразнейшими местообитаниями нашей планеты… Заходите к нам и изучайте животный мир во всем его великолепии.', 'Welcome to Animalium! This museum is open all hours and invites visitors of all ages to explore an astonishing collection of over 160 animal species. Discover how creatures evolved, peer into the dissection lab, and journey through the planet''s most diverse habitats. Step inside and marvel at the animal kingdom in all its vintage grandeur.', 'Dobro došli u Animalijum! Ovaj muzej je otvoren u svako doba i poziva posjetioce svih uzrasta da istraže nevjerovatnu zbirku od preko 160 životinjskih vrsta. Otkrijte kako su se životinje razvijale kroz evoluciju, zavirite u anatomsku laboratoriju i upoznajte najraznovrsnija staništa naše planete.', 'Грандиозный музей живой природы на книжных страницах, где нет очередей и можно рассматривать великолепные винтажные гравюры часами!', 'A breathtaking natural history museum in book form, where there are no entry queues and you can marvel at gorgeous vintage engravings for hours!', 'Veličanstveni prirodnjački muzej među koricama knjige, gdje nema redova na ulazu i možete satima uživati u prelijepim gravurama!', '/covers/DP-0699.webp', '#2c3e35', 'nonfiction', 'ru', 'available', '6+ | Энциклопедия', '["animals","real"]', '["animals","encyclopedia","nature","evolution","wildlife"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ботаникум-700', 'DP-0700', 'Ботаникум', 'Botanicum', 'Botanikum', 'Кэти Уиллис', 'Kathy Willis', 'Keti Vilis', 'Кейти Скотт', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Добро пожаловать в наш «Ботаникум». Этот постоянно открытый музей представляет посетителям коллекцию, включающую грибы, лишайники и самые разнообразные растения – от крошечных одноклеточных водорослей до гигантских секвойядендронов, от нежного лютика до хищной росянки. Вы узнаете об эволюции многих растений и приспособлениях, позволивших им выжить. Заходите к нам и изучайте удивительный мир растений во всем его великолепии.', 'Welcome to Botanicum. This always-open museum invites visitors to discover an extraordinary collection of fungi, lichens, and plants of every variety — from microscopic single-celled algae to towering giant sequoias, from delicate buttercups to carnivorous sundews. Learn about the remarkable evolution of flora and the ingenious adaptations that allowed them to survive across millennia, all presented in breathtaking detail.', 'Dobrodošli u Botanikum. Ovaj muzej sa stalno otvorenim vratima vodi posjetioce kroz izuzetnu zbirku gljiva, lišajeva i najraznovrsnijih biljaka — od sićušnih jednoćelijskih algi do divovskih sekvoja, od nježnog ljutića do biljki mesožderki. Otkrijte nevjerovatnu evoluciju biljnog carstva i domišljata prilagođavanja koja su im omogućila preživljavanje u svoj njihovoj raskoši.', 'Грандиозный ботанический музей прямо у вас на коленях — разглядывать эти роскошные винтажные иллюстрации можно бесконечно!', 'A breathtaking botanical museum right in your lap, bursting with vintage-style illustrations you could get lost in for hours!', 'Veličanstveni botanički muzej u vašem krilu, prepun raskošnih ilustracija u kojima se možete gubiti satima!', '/covers/DP-0700.webp', '#2d5236', 'nonfiction', 'ru', 'available', '6+ | Энциклопедия', '["real","adventure"]', '["botany","nature","plants","encyclopedia","science"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('динозавриум-701', 'DP-0701', 'Динозавриум', 'Dinosaurium', 'Dinosaurijum', 'Лили Маррей, Кейти Скотт, Джейми Брун', 'Lily Murray, Katie Scott', 'Lili Marej, Kejti Skot', 'Крисс Уормелл', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Добро пожаловать в наш «Динозавриум». Этот круглосуточный музей работает без выходных и перерывов на обед. Он знакомит посетителей с впечатляющей коллекцией мезозойских ящеров: от миниатюрных троодонов до гигантских брахиозавров. Вы узнаете, как эволюционировали динозавры, почему одни были покрыты перьями, а другие – чешуей. Заходите к нам и полюбуйтесь динозаврами во всем их великолепии.', 'Welcome to Dinosaurium! This museum is open every day, around the clock, with no closing time. Step inside to explore an astonishing collection of Mesozoic marvels, from tiny Troodons to colossal Brachiosaurs. Learn how dinosaurs evolved, uncover why some had feathers while others wore armor of scales, and marvel at the prehistoric giants in all their breathtaking glory.', 'Dobro došli u Dinosaurijum! Ovaj jedinstveni muzej otvoren je bez prestanka, 24 sata dnevno. U njemu vas čeka impresivna kolekcija mezozojskih bića: od majušnih troodona do divovskih brahiozaura. Otkrijte kako su dinosaurusi evoluirali, zašto su jedni imali perje, a drugi krljušti, i zakoračite među praistorijske džinove u njihovom punom sjaju.', 'Бессрочный билет в самый грандиозный музей планеты: открывайте гигантские страницы и гуляйте среди мезозойских исполинов хоть до самого утра!', 'Your ticket to this breathtaking museum never expires: open these grand pages and wander among Mesozoic giants to your heart''s content!', 'Ulaznica za ovaj veličanstveni muzej važi zauvijek: otvorite ogromne stranice i šetajte među mezozojskim divovima kad god poželite!', '/covers/DP-0701.webp', '#2e4334', 'nonfiction', 'ru', 'available', '6+ | Энциклопедия | Настя Ж.', '["animals","real","adventure"]', '["dinosaurs","paleontology","encyclopedia","museum","prehistoric"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('океанариум-702', 'DP-0702', 'Океанариум', 'Oceanarium', 'Okeanarijum', 'Лавдэй Триник', 'Loveday Trinick', 'Lavdej Trinik', 'Тиган Уайт', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Добро пожаловать в наш «Океанариум»! Этот постоянно открытый музей приглашает посетителей в путешествие по Мировому океану – уникальной экосистеме, наполненной всевозможными формами жизни. Вы увидите множество морских обитателей – от микроскопического планктона и разноцветных медуз до удивительных глубоководных рыб и огромных китов. Океан – невероятная тайна, которую нам ещё только предстоит раскрыть. Заходите в наш музей и познакомьтесь с потрясающим подводным миром.', 'Welcome to the Oceanarium! This museum that never closes invites visitors on a grand journey through the World Ocean—a breathtaking ecosystem teeming with life. Discover astonishing marine creatures, from microscopic plankton and glowing jellyfish to mysterious deep-sea dwellers and gentle giant whales. Step inside and explore the wonders of the deep blue!', 'Dobro došli u „Okeanarijum“! Ovaj muzej koji je uvijek otvoren vodi vas na nezaboravno putovanje kroz Svjetski okean — jedinstveni ekosistem prepun raznovrsnog života. Otkrijte čudesna morska stvorenja, od mikroskopskog planktona i svjetlucavih meduza do tajanstvenih dubokomorskih riba i džinovskih kitova. Zaronite u čarobni podvodni svijet!', 'Захватывающий подводный музей прямо под обложкой: погружаемся без акваланга, но с широко открытыми глазами!', 'A jaw-dropping underwater museum right between two covers—dive in without scuba gear and prepare to be amazed!', 'Nevjerovatan podvodni muzej među koricama: zaronite bez ronilačke opreme i prepustite se divljenju!', '/covers/DP-0702.webp', '#1a4760', 'nonfiction', 'ru', 'available', '6+ | Энциклопедия', '["animals","adventure","real"]', '["ocean","marine life","sea creatures","encyclopedia","nature"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('планетариум-703', 'DP-0703', 'Планетариум', 'Planetarium', 'Planetarijum', 'Раман Принджа', 'Raman Prinja', 'Raman Prindža', 'Крисс Уормелл', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Добро пожаловать в наш «Планетариум». Этот постоянно открытый музей готов познакомить посетителей с коллекцией астрономических объектов — от крошечных ледяных спутников до гигантских галактик. Экспозиция включает выполненные по научным данным картины Солнечной системы, дальнего космоса, галактических скоплений и туманностей, показывающих разнообразие и бесконечность Вселенной. Заходите к нам и прикоснитесь к тайнам космоса.', 'Welcome to the Planetarium! This museum that never closes invites visitors to explore a stunning collection of astronomical wonders — from tiny icy moons to colossal galaxies. Featuring breathtaking, scientifically accurate artwork of the Solar System, deep space, star clusters, and nebulae, it unveils the infinite mysteries of the cosmos.', 'Dobrodošli u naš „Planetarijum“! Ovaj muzej koji nikada ne zatvara svoja vrata spreman je da upozna posjetioce sa zbirkom nebeskih tijela — od sićušnih ledenih satelita do gigantskih galaksija. Izložba obuhvata predivne i naučno utemeljene ilustracije Sunčevog sistema, dubokog svemira i maglina, otkrivajući beskrajnu ljepotu univerzuma.', 'Билет в самый грандиозный музей Вселенной прямо на вашей полке — и телескоп не понадобится!', 'A VIP pass to the grandest museum in the universe right in your hands — no telescope required!', 'Karta za najveličanstveniji muzej u svemiru pravo u tvojim rukama — teleskop ti uopšte nije potreban!', '/covers/DP-0703.webp', '#1b2038', 'nonfiction', 'ru', 'available', '6+ | Энциклопедия', '["real","adventure"]', '["space","astronomy","universe","planets","encyclopedia"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('грибы-704', 'DP-0704', 'Грибы', 'Mushrooms', 'Gljive', '', 'Unknown', 'Nepoznati autor', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Грибы — одни из самых удивительных обитателей нашей планеты; царство грибов поражает впечатляющими масштабами, невероятным разнообразием видов и форм. В залах музея представлена обширная коллекция, посвящённая наиболее интересным представителям грибного царства. Она включает в себя микроскопические организмы, неразличимые невооружённым глазом, трутовики и лишайники, грибы тропических лесов, грибы-гиганты, съедобные грибы и многие другие. Вы узнаете, как размножаются грибы, какую роль они играют в жизни растений, животных и человека, с кем взаимодействуют и… на кого охотятся. Заходите к нам за новыми знаниями и впечатлениями и полюбуйтесь грибами во всём их великолепии.', 'Fungi are among the most fascinating inhabitants of our planet; their kingdom astounds with its immense scale and incredible variety of shapes and species. Formatted like a grand museum tour, this book explores microscopic organisms invisible to the naked eye, bracket fungi, lichens, rainforest giants, and edible delicacies. Discover how fungi reproduce, how they shape the ecosystems of plants, animals, and humans, and even who they secretly hunt.', 'Gljive su jedni od najfascinantnijih stanovnika naše planete, a njihovo carstvo zadivljuje ogromnim razmjerama i nevjerovatnom raznolikošću vrsta. Ova knjiga osmišljena kao šetnja kroz muzej vodi vas kroz bogatu zbirku: od mikroskopskih spora, guba i lišajeva, do tropskih gljiva, šumskih džinova i jestivih poslastica. Saznajte kako se razmnožavaju, kakvu ulogu igraju u prirodi i koga sve ove tajanstvene mreže zapravo love.', 'Загляните под лесную подстилку и раскройте тайную паутину Земли: оказывается, грибы умеют не только дружить с деревьями, но и выходить на настоящую охоту!', 'Step into an illustrated museum of fungi and uncover the Earth''s secret web—where mushrooms don''t just nourish trees, but sometimes even go hunting!', 'Zavirite u ovaj čudesni muzej gljiva i otkrijte tajnu mrežu prirode — gdje pečurke ne samo da pomažu drveću, već ponekad idu i u pravi lov!', '/covers/DP-0704.webp', '#5c6f48', 'nonfiction', 'ru', 'available', '7+', '["real"]', '["nonfiction","nature","mushrooms","biology","encyclopedia"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('языки-мира-705', 'DP-0705', 'Языки мира', 'Languages of the World', 'Jezici svijeta', '', 'Unknown', 'Nepoznati autor', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'В мире существуют тысячи языков. На некоторых говорят миллионы людей, на других — единицы. Есть языки, которые совсем исчезли и оставили загадочные следы, другие возродились. Языки свистящие, придуманные, запрещенные, жестовые — если прислушаться к этому разнообразию, нам откроется настоящее сокровище. Эта книга — путешествие по всей планете, в котором языки доведут до самых удивительных мест. Они покажут, как можно думать о мире, как разговаривать и понимать друг друга.', 'Thousands of languages exist across the globe: some are spoken by millions, others by only a handful of people. Some have vanished leaving mysterious traces, while others have been brought back to life. Whistling languages, invented ones, forbidden tongues, and sign languages—listen closely to this rich diversity, and a true treasure unfolds. This book is a journey around the planet where languages lead to the most fascinating places, revealing how different people perceive the world, converse, and understand one another.', 'Širom svijeta postoje hiljade jezika: nekima govore milioni ljudi, a drugima tek nekolicina. Neki su sasvim nestali ostavljajući zagonetne tragove, dok su drugi ponovo oživjeli. Zviždeći, izmišljeni, zabranjeni jezici i znakovni jezici — ako pažljivo oslušnemo ovu raznolikost, otkrićemo pravo blago. Ova knjiga je putovanje oko planete na kojem će vas jezici odvesti na najnevjerovatnija mjesta i pokazati vam kako promišljamo svijet, razgovaramo i razumijemo jedni druge.', 'Увлекательное кругосветное путешествие по звукам, жестам и тайнам человеческой речи, доказывающее: общий язык можно найти всегда!', 'A fascinating round-the-world journey through sounds, signs, and the secrets of human speech that proves there''s always a way to understand each other!', 'Fascinantno putovanje oko svijeta kroz zvukove, znakove i tajne ljudskog govora koje dokazuje da uvijek možemo naći zajednički jezik!', '/covers/DP-0705.webp', '#2f6b88', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["languages","linguistics","geography","culture","communication"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('а-антарктида-706', 'DP-0706', 'А - Антарктида', 'A is for Antarctica', 'A kao Antarktik', 'Давид Бём', 'David Böhm', 'David Böhm', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Детская книжка-картинка, написанная и проиллюстрированная чешским автором Давидом Бёмом, посвящает юных читателей в тайны ледяного континента. Среди тем — история открытия и изучения Антарктиды, особенности ее климата, флоры и фауны, хроника знаменитых экспедиций к Южному полюсу, особенности жизни ученых на полярных станциях и даже веселый комикс.', 'An award-winning illustrated guide by Czech artist David Böhm that unlocks the secrets of Earth''s iciest continent. Readers will discover the history of polar expeditions, extreme climates, astonishing wildlife, daily routines at research stations, and even a witty comic strip about life on the ice.', 'Raskošno ilustrovana knjiga češkog autora Davida Bema otkriva fascinantne tajne najhladnijeg kontinenta na planeti. Kroz zadivljujuće crteže i duhovite stripove, čitaoci upoznaju istoriju polarnih ekspedicija, neobičan biljni i životinjski svijet, te svakodnevicu naučnika u istraživačkim stanicama.', 'Закутайтесь в тёплый плед и отправляйтесь в самую морозную, остроумную и захватывающую экспедицию на край Земли!', 'Wrap yourself in a warm blanket and set off on the coolest, wittiest, and most thrilling expedition to the bottom of the world!', 'Umotajte se u toplo ćebe i krenite u najsmjeliju, najhladniju i najuzbudljiviju ekspediciju na kraj svijeta!', '/covers/DP-0706.webp', '#1f6f8b', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","animals","real"]', '["antarctica","polar expeditions","geography","nonfiction","comics"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большой-атлас-мира-в-картинках-707', 'DP-0707', 'Большой атлас мира в картинках |', 'Big Picture Atlas', 'Veliki atlas svijeta u slikama', 'Боне Эмили', 'Emily Bone', 'Emili Boun', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Как совершить кругосветное путешествие, не выходя из дома? Очень просто: открыть эту книгу на любой странице! Этот атлас – не просто собрание географических карт, а живой, интересный рассказ о нашей планете. Вы узнаете о самых длинных реках и самых обширных пустынях мира, самых высоких горах и самом глубоководном желобе, познакомитесь с традициями и обычаями разных народов. На картах отмечены растения и животные шести континентов, изображены памятники истории и культуры. Познавайте окружающий мир – это очень интересно.', 'How can you travel around the world without leaving your room? It''s simple: just open this book to any page! More than just a collection of maps, this lively atlas takes readers on a captivating journey across our planet. Discover the longest rivers, vastest deserts, towering mountains, and deepest ocean trenches, while exploring the diverse wildlife, cultures, and iconic landmarks of all six continents.', 'Kako proputovati svijet a ne izaći iz svoje sobe? Vrlo jednostavno: otvorite ovu knjigu na bilo kojoj stranici! Ovaj atlas nije samo zbirka geografskih karata, već uzbudljiva priča o našoj planeti. Otkrijte najduže rijeke, najprostranije pustinje, najviše planine i najdublje morske brazde, upoznajući se sa tradicijama, prirodom i čuvenim spomenicima sa svih šest kontinenata.', 'Зачем покупать билеты на самолёт, когда можно совершить кругосветное путешествие прямо на уютном библиотечном диване?', 'Why buy plane tickets when you can circumnavigate the entire globe right from our coziest library armchair?', 'Zašto kupovati avionske karte kada možete obići čitavu zemaljsku kuglu sa udobnog bibliotečkog kauča?', '/covers/DP-0707.webp', '#2f7ea1', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["atlas","geography","travel","maps","continents","nature"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('карты-708', 'DP-0708', 'Карты', 'Maps', 'Mape', 'Мизельиньские', 'Aleksandra Mizielińska, Daniel Mizieliński', 'Aleksandra Mizielinska, Danijel Mizielinski', 'Мизелиньские', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Географическая карта может быть скучным школьным пособием, а может стать и игрой, развивающей воображение, тренирующей память и позволяющей овладевать новыми знаниями. Рисованный атлас «Карты» польских художников Александры и Даниэля Мизелиньских можно уподобить старинным картам мира, на которых картографы помещали много полезных сведений о странах и людях, в них живущих. И с его помощью художники приглашают нас в необычное путешествие вокруг света, которое можно совершить из дома. Четыре тысячи картинок рассказывают о 41 стране: кто в ней живет, какие самые распространенные имена, какие достопримечательности — природные, архитектурные, самые распространенные и самые редкие представители флоры и фауны, обычаи и традиции, исторические персонажи, прославившие свою родину, виды спорта, национальная кухня... И еще очень много всего, что заставит вас всей семьей часами бродить по африканским пустыням, осваивать приветствие новозеландских маори или изучать арктическую фауну. Вперед, к новым открытиям! 2013 — Премия Сорсьер (Ассоциация библиотекарей Франции) 2013 — Премия Андерсена (Книжный салон в Турине, Италия)', 'A map can be a dry school tool, or an inspiring journey that sparks curiosity, memory, and wonder. This illustrated atlas by Polish artists Aleksandra and Daniel Mizieliński recalls antique world maps packed with fascinating details about lands and their inhabitants. Through four thousand hand-drawn illustrations covering 41 countries, young explorers can discover local wildlife, architectural gems, historical figures, cultural traditions, and national foods—all without leaving the living room rug.', 'Geografska karta može biti dosadno školsko pomagalo, ali i uzbudljiva igra koja razvija maštu i budi radoznalost. Ovaj raskošno ilustrovani atlas poljskih umjetnika Aleksandre i Danijela Mizielinskih podsjeća na stare mape pune zapanjujućih detalja o zemljama i ljudima. Sa preko četiri hiljade minijaturnih crteža kroz 41 zemlju, knjiga vas vodi na putovanje oko svijeta gdje istražujete floru, faunu, arhitektonska čuda, tradiciju i kulturu.', 'Раскладывайте этот гигантский атлас прямо на полу и отправляйтесь в кругосветку — гарантируем, что вся семья застрянет над деталями на несколько часов!', 'Spread this giant atlas out on the living room floor and pack your bags—the whole family will be happily lost in its quirky details for hours!', 'Raširite ovaj ogromni atlas po podu i krenite na put oko svijeta — garantujemo da će cijela porodica satima uživati u svakom detalju!', '/covers/DP-0708.webp', '#4a7e8c', 'nonfiction', 'ru', 'available', '6+ | Энциклопедия', '["adventure","real"]', '["atlas","geography","world-travel","illustrations","cultures"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('транссиб-709', 'DP-0709', 'Транссиб', 'The Trans-Siberian Railway: A Trip Across Russia', 'Transsibirska željeznica', 'Литвина Александра', 'Alexandra Litvina', 'Aleksandra Litvina', 'Десницкая Анна', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Цифры, исторические факты и сведения о географии, которые можно найти в учебниках, дополнили реальные истории людей, связанных с Транссибом, рассказы о любимых местах, рецепты блюд и советы, что посмотреть, которыми щедро поделились дети и взрослые. Собирали эти истории, подбирали факты, создавали панорамы и зарисовки из мегаполисов и маленьких поселков — Александра Литвина и Аня Десницкая, создатели известной книги «История старой квартиры», настоящего события на российском и международном книжном рынке, лауреаты множества российских и международных наград.', 'Dry textbook figures, historical milestones, and geographic maps come alive alongside real personal stories from people living along the Trans-Siberian Railway. Children and adults along the route generously share insider travel tips, favorite local spots, legends, and regional recipes. Created by Alexandra Litvina and acclaimed illustrator Anya Desnitskaya—creators of the award-winning ''The Apartment''—this panoramic visual journey brings bustling megacities, quiet taiga stops, and remote settlements directly to your hands.', 'Statističke podatke, istorijske prekretnice i geografske karte oživljavaju stvarne priče ljudi koji žive duž trase čuvene Transsibirske željeznice. Djeca i odrasli iz raznih gradova nesebično dijele savjete za putovanja, omiljena lokalna mjesta i tradicionalne recepte. Ovu panoramsku vizuelnu avanturu osmislile su Aleksandra Litvina i ilustratorka Anja Desnickaja, autorke nagrađivane knjige „Istorija starog stana“.', 'Заварите чаю в подстаканнике: эта невероятная книга-путешествие провезёт вас через всю страну от Москвы до Владивостока прямо с библиотечного дивана!', 'Pour yourself a hot cup of train tea: this breathtaking visual expedition takes you across thousands of miles from Moscow to Vladivostok right from our library couch!', 'Sipajte topli čaj i spremite se za polazak: ovo veličanstveno vizuelno putovanje vodi vas kroz hiljade kilometara vozom pravo sa naše bibliotečke sofe!', '/covers/DP-0709.webp', '#2c5b73', 'nonfiction', 'ru', 'available', '6+ | у нас дома', '["adventure","real"]', '["trains","travel","geography","history","nonfiction"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('с-востока-на-запад-710', 'DP-0710', 'С Востока на Запад', 'From East to West', 'Od istoka do zapada', 'Марина Бабанская', 'Marina Babanskaya', 'Marina Babanskaja', 'Наталья Карпова', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Отправить письмо бутылочной почтой решил смотритель маяка Пётр Круглов. Он попросил каждого, кому попадёт в руки его послание, дополнить его небольшим письмом о себе: где человек живёт, как проводит время, какие традиции есть в его семье и окружении. Бутылка странствует по огромной территории России, от Владивостока до Санкт-Петербурга, оказываясь в местах, где подавляющему большинству читателей наверняка не доводилось бывать. И люди, выловившие бутылку, дополняют послание в ней своим рассказом — как им живётся в вечной мерзлоте; какие традиции есть у горных народов; почему на Урале люди даже разговаривают чуть иначе, чем в Центральной России.', 'Lighthouse keeper Pyotr Kruglov sends a message adrift in a bottle, asking whoever finds it to add a short letter about their home, daily life, and traditions. Drifting from Vladivostok to Saint Petersburg, the bottle visits remote permafrost regions, mountain communities, and the Urals, weaving an inspiring tapestry of diverse cultures and landscapes across a vast continent.', 'Svjetioničar Pjotr Kruglov odlučio je da pošalje pismo u boci, zamolivši svakoga ko ga pronađe da doda priču o sebi: gdje živi, kako provodi dane i kakve običaje njeguje njegova porodica. Putujući od Vladivostoka do Sankt Peterburga, boca posjećuje daleki sjever, planinska sela i Ural, stvarajući toplu priču o raznolikosti kultura i krajeva.', 'Загляните в путешествующую бутылку с письмами, чтобы открыть удивительное разнообразие судеб, обычаев и уголков необъятной страны!', 'Catch this traveling bottle of letters and set off on a breathtaking cross-country journey through authentic local stories!', 'Uhvatite ovu putujuću bocu s porukama i krenite na uzbudljivo putovanje kroz priče i običaje dalekih krajeva!', '/covers/DP-0710.webp', '#2a6b82', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["geography","travel","traditions","letters","culture"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('горы-мира-история-восхождений--711', 'DP-0711', 'Горы мира. История восхождений и открытий', 'Mountains of the World: A History of Ascents and Discoveries', 'Planine svijeta: Istorija uspona i otkrića', '', 'Unknown', 'Nepoznat autor', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'На счастье непосед, авантюристов и путешественников, на Земле есть горы — от совсем невысоких до непостижимо огромных. До поры до времени люди обходили их стороной, а потом решили взойти и посмотреть, что там наверху. Так начался и длится до сих пор роман человека и гор. Перед вами книга о том, как люди впервые поднялись в Альпы, на Кавказ и в Гималаи, о покорении Эвереста и всех восьмитысячников, об опасностях, отваге и приключениях. И конечно, о любви к горам, красоте и смысле жизни. Как устроены горы? Какие флаги водружали на вершины первопроходцы? Когда в горы впервые отправились женщины? Зачем альпинистам кошки, ледорубы и кислородные баллоны? Кого и почему называют «Великим»? Ответы на эти и многие другие вопросы ты найдёшь на страницах этой удивительной книги.', 'Luckily for restless adventurers and explorers, the Earth is dotted with mountains—from gentle peaks to unfathomable giants. For centuries, people kept their distance, until curiosity led them to venture up and see what lies at the summit. This book chronicles humanity''s enduring romance with mountains: the pioneering climbs across the Alps, the Caucasus, and the Himalayas; the conquest of Everest and all fourteen eight-thousanders; the perils, gear, pioneering women climbers, and breathtaking courage required to conquer the highest points on Earth.', 'Na sreću avanturista i radoznalih putnika, na Zemlji postoje planine — od blagih visova do nesagledivih divova. Ljudi su ih dugo zaobilazili u širokom luku, sve dok nisu odlučili da se popnu i otkriju šta se krije na vrhu. Ova knjiga priča o vječitoj ljubavi čovjeka i planina: o prvim podvizima u Alpima, na Kavkazu i Himalajima, osvajanju Everesta i svih četrnaest osamhiljadaša, opremi, opasnostima i hrabrosti koja pomjera granice.', 'Захватывающая хроника покорения величайших вершин планеты для каждого, кто хоть раз мечтал дотянуться до облаков!', 'A breathtaking chronicle of conquering the planet''s highest peaks for anyone who has ever dreamed of touching the clouds!', 'Uzbudljiva hronika osvajanja najviših vrhova planete za svakoga ko je ikada sanjao da dodirne oblake!', '/covers/DP-0711.webp', '#2b5b84', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["mountains","mountaineering","history","geography","expeditions"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вс-теч-т-великие-реки-мира-712', 'DP-0712', 'Всё течёт: великие реки мира', 'Everything Flows: Great Rivers of the World', 'Sve teče: Velike rijeke svijeta', '', 'Volker Mehnert', 'Volker Menert', 'Мартин Хааке', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Какая река самая длинная в мире — Нил или Амазонка? Через какие страны протекает Дунай? Как река Колорадо проложила себе путь через скалы Большого каньона? Как Волга и Лена определили облик России? Политическая или культурная граница, торговый путь или религиозный символ — реки всегда имели для нас особое значение. В этой книге представлены 18 легендарных рек со всех пяти континентов, и мы познакомимся с разнообразной жизнью и знаменитыми достопримечательностями, которые можно обнаружить на реках и вокруг них.', 'Which river is the longest in the world: the Nile or the Amazon? How many countries does the Danube flow through, and how did the Colorado River carve out the Grand Canyon? As political borders, vital trade arteries, or sacred symbols, rivers have always shaped human history. This beautifully illustrated book takes readers on an epic journey along 18 legendary rivers across five continents, uncovering vibrant wildlife, ancient legends, and bustling cities along their shores.', 'Koja je rijeka najduža na svijetu — Nil ili Amazon? Kroz koje zemlje protiče Dunav i kako je rijeka Kolorado izdubila Veliki kanjon? Kao granice, trgovački putevi ili sveti simboli, rijeke su oduvijek oblikovale ljudsku istoriju. Ova raskošno ilustrovana knjiga vodi nas na putovanje duž 18 legendarnih rijeka sa pet kontinenata, otkrivajući raznovrsni biljni i životinjski svijet, drevne mitove i znamenite gradove duž njihovih obala.', 'Запрыгивайте в лодку: вас ждёт грандиозное путешествие по самым великим рекам планеты от истоков до самого океана!', 'Hop aboard: you''re embarking on a breathtaking journey along the planet''s greatest waterways, from babbling springs to the vast ocean!', 'Uskočite u čamac: čeka vas spektakularno putovanje duž najvećih rijeka planete, od planinskih izvora do beskrajnog okeana!', '/covers/DP-0712.webp', '#2a7593', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["rivers","geography","world history","nature","travel"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('атлас-города-713', 'DP-0713', 'Атлас города', 'City Atlas', 'Atlas gradova', 'Мартин Хааке', 'Martin Haake', 'Martin Hake', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Чем Москва отличается от Лондона, Рио-де-Жанейро - от Токио, а Берлин и Рим - от Нью-Йорка? Какой город самый большой, и что обязательно надо сделать, если ты оказался в одной из известнейших столиц мира? "Атлас города" - иллюстрированный путеводитель, который рассказывает все о культурных достопримечательностях, знаменитостях, культовых зданиях, национальных блюдах, праздниках и традициях 30 городов мира. Среди них: Лиссабон, Барселона, Лондон, Амстердам, Париж, Рим, Берлин, Хельсинки, Осло, Копенгаген, Стокгольм, Афины, Стамбул, Прага, Будапешт, Москва, Монреаль, Торонто, Чикаго, Нью-Йорк, Сан-Франциско, Мехико, Рио-де-Жанейро, Буэнос-Айрес, Гонконг, Токио, Сеул, Мумбай и Сидней. Отправляйтесь в захватывающее кругосветное путешествие с незаменимым помощником для детей и взрослых!', 'How does Moscow differ from London, Rio de Janeiro from Tokyo, or Berlin and Rome from New York? Which city is the largest, and what must you do when visiting the world''s most iconic capitals? "City Atlas" is a vibrant illustrated guide packed with cultural landmarks, famous figures, culinary treats, festivals, and traditions across 30 cities worldwide. Pack your bags for an unforgettable journey around the globe!', 'Po čemu se Moskva razlikuje od Londona, Rio de Žaneiro od Tokija, a Berlin i Rim od Njujorka? Koji je grad najveći i šta obavezno morate vidjeti i probati u svjetskim metropolama? „Atlas gradova“ je divno ilustrovani vodič kroz kulturne znamenitosti, slavne ličnosti, kultne građevine, tradicionalna jela i festivale u 30 gradova širom svijeta. Spakujte kofere za uzbudljivo putovanje oko planete!', 'Открывайте этот потрясающий атлас, выбирайте любой из 30 мегаполисов и отправляйтесь в кругосветное путешествие прямо из уютного кресла!', 'Open this stunning atlas, pick any of the 30 vibrant metropolises, and embark on a world tour straight from your cozy armchair!', 'Otvorite ovaj predivni atlas, izaberite bilo koju od 30 metropola i krenite na put oko svijeta pravo iz udobne fotelje!', '/covers/DP-0713.webp', '#2d7f8d', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["cities","travel","geography","maps","architecture"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('это-лондон-714', 'DP-0714', 'Это Лондон', 'This is London', 'Ovo je London', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Это Лондон. Это его неповторимые улицы, парки и скверы, известные всему миру центральные площади, музеи, памятники, здания, двухэтажные автобусы, телефонные будки... Дожди и туманы. Это жители Лондона - конечно, они не похожи на жителей других городов, у них своя манера одеваться, свой образ жизни. И есть в Лондоне такое, что иногда ускользает от глаз взрослого, но зато очень интересно ребёнку! Замечательные виды одного из самых прекрасных городов мира создал в 1959 году Мирослав Шашек. Эта и 17 других его книг-путешествий по городам и странам стали классикой детской литературы. Мирослав Шашек родился 18 ноября 1916 года в Праге, умер в 1980 году в Швейцарии. По образованию архитектор. В 1948 году эмигрировал в ФРГ, жил в Мюнхене. Работал на радио "Свободная Европа". Известный художник, автор детских книг, книжный иллюстратор. "Это Лондон" - для любопытных маленьких читателей, которые читают сами и любят, когда им читают вслух.', 'This is London—with its bustling streets, foggy mornings, iconic red double-decker buses, guards in tall bearskin hats, and historic landmarks. Created in 1959 by Czech architect and illustrator Miroslav Šašek, this timeless travel classic captures the lively spirit, charm, and quirky everyday details of the British capital through a child''s curious eyes.', 'Ovo je London — sa svojim živahnim ulicama, maglovitim jutrima, prepoznatljivim crvenim dabldekerima, stražarima sa čupavim kapama i slavnim trgovima. Stvorena 1959. godine iz pera češkog arhitekte i ilustratora Miroslava Šašeka, ova vanvremenska knjiga-vodič kroz oči djeteta otkriva duh, ljepotu i šarm britanske prijestonice.', 'Запрыгивайте на второй этаж красного автобуса и отправляйтесь на самую элегантную ретро-прогулку по туманному Лондону!', 'Hop onto the top deck of a big red bus for the most stylish, witty vintage tour of foggy London!', 'Uskočite na sprat crvenog autobusa i krenite u najotmjeniju retro šetnju kroz magloviti London!', '/covers/DP-0714.webp', '#c8322b', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["london","travel","cities","architecture","retro illustration"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('это-нью-йорк-715', 'DP-0715', 'Это Нью-Йорк', 'This is New York', 'Ovo je Njujork', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Это Нью-Йорк. Один из крупнейших городов мира... Здесь самые большие магазины, здания и пробки! Мы посетим Манхэттен, Бруклин и Гарлем, увидим статую Свободы. Замечательные виды одного из самых прекрасных городов мира создал в 1959 году Мирослав Шашек. Эта и 17 других его книг-путешествий по городам и странам стали классикой детской литературы.', 'Welcome to New York, one of the greatest cities on Earth! Packed with soaring skyscrapers, bustling stores, and legendary traffic jams, this retro masterpiece takes readers on a whirlwind tour from Manhattan and Brooklyn to Harlem and the Statue of Liberty. First published in 1959, Miroslav Šašek’s witty observations and stylish illustrations remain a timeless classic of children''s non-fiction.', 'Dobrodošli u Njujork, jedan od najvećih gradova na svijetu! Pun nebodera koji paraju oblake, ogromnih robnih kuća i čuvenih saobraćajnih gužvi, ovo remek-djelo vodi nas kroz Menhetn, Bruklin, Harlem sve do Kipa slobode. Stvorena još 1959. godine, predivna i duhovita putopisna slikovnica Miroslava Šašeka postala je vanvremenski klasik dječije književnosti.', 'Наденьте удобную обувь: мы отправляемся прямиком на шумные авеню Манхэттена 1960-х с самым стильным гидом в истории!', 'Lace up your walking shoes: we are off to the bustling avenues of 1960s Manhattan with the most stylish tour guide ever!', 'Obujte udobne patike: krećemo pravo na živahne avenije Menhetna iz šezdesetih uz najstilizovanijeg vodiča na svijetu!', '/covers/DP-0715.webp', '#e59b2b', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["нью-йорк","путешествия","города","архитектура","ретро-иллюстрация"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('это-париж-716', 'DP-0716', 'Это Париж', 'This is Paris', 'Ovo je Pariz', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Это Париж. Величественные дворцы и храмы, исторические памятники, прекрасные сады, музеи, улицы… И жители города - художники, продавщицы цветов, уличные артисты и даже тысячи кошек! Пройдемся по набережной Сены, заглянем в Лувр, поднимемся на Эйфелеву башню, узнаем историю города. Замечательные виды одного из самых прекрасных городов мира создал в 1959 году Мирослав Шашек. Эта и 17 других его книг-путешествий по городам и странам стали классикой детской литературы. "Это Париж" - для любопытных маленьких читателей, которые читают сами и любят, когда им читают вслух.', 'This is Paris! Majestic palaces and cathedrals, historic monuments, beautiful gardens, museums, charming streets... and the city''s inhabitants—painters, flower sellers, street artists, and even thousands of cats! Stroll along the banks of the Seine, peek into the Louvre, climb the Eiffel Tower, and discover the history of the City of Light. Created by Miroslav Šašek in 1959, this vintage travel classic remains an absolute masterpiece for curious explorers of all ages.', 'Ovo je Pariz! Veličanstvene palate i katedrale, istorijski spomenici, prelijepe bašte, muzeji, ulice... i stanovnici grada — slikari, cvjećarke, ulični umjetnici, pa čak i hiljade mačaka! Prošetajte obalom Sene, zavirite u Luvr, popnite se na Ajfelov toranj i upoznajte istoriju Grada svjetlosti. Miroslav Šašek je davne 1959. godine stvorio ove čudesne panorame jednog od najljepših gradova svijeta, stvorivši bezvremenski vodič za sve male i velike radoznalce.', 'Идеальный билет в Париж без виз и чемоданов — просто откройте эту стильную ретро-книгу и поднимитесь на Эйфелеву башню!', 'The ultimate ticket to Paris without packing a single suitcase—just open this stylish retro classic and stroll straight to the Eiffel Tower!', 'Savršena karta za Pariz bez kofera i viza — samo otvorite ovaj retro klasik i popnite se pravo na Ajfelov toranj!', '/covers/DP-0716.webp', '#395c79', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["paris","travel","architecture","retro","cities"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('это-рим-717', 'DP-0717', 'Это Рим', 'This is Rome', 'Ovo je Rim', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Мирослав Шашек ведет нас в незабываемое путешествие по Риму. Его иллюстрации - неожиданные, забавные и яркие покажут нам Рим древний и Рим современный - фонтаны, плещущие под ярким голубым небом, Римский Форум, Испанская лестница, древняя Аппиева дорога, самый знаменитый собор в мире - Базилика Святого Петра. Мы увидим апельсины и лимоны, созревающие в городских двориках, пальмы, растущие на крышах домов. Увидим статуи и мотоциклы. И жизнерадостных римлян, которые живут в "вечном городе". Эта книга как для тех, кто уже бросил монету в фонтан Треви, так и для тех, кто не бросал. Для юных и взрослых читателей, путешествующих по дорогам и страницам книг. Мирослав Шашек создал 18 книг-путешествий по миру, они получили множество наград и стали детской классикой. На русском языке в серии путешествий с Мирославом Шашеком выходили книги: Это Париж, Это Лондон, Это Нью-Йорк, Это Венеция.', 'Miroslav Šašek takes us on an unforgettable journey through the Eternal City. His witty, vibrant, and surprising illustrations capture both ancient ruins and bustling modern life: fountains splashing beneath azure skies, the Roman Forum, the Spanish Steps, and St. Peter''s Basilica. Peek into sun-drenched courtyards bursting with citrus trees, spot rooftop palms, marble statues, and zippy scooters, and meet the cheerful Romans who call this city home. A timeless travel classic for anyone who has ever tossed a coin into the Trevi Fountain—or is just dreaming of it.', 'Miroslav Šašek nas vodi na nezaboravno putovanje kroz Vječni grad. Njegove vesele, duhovite i živopisne ilustracije spajaju antički Rim sa savremenim ritmom grada: fontane pod jarkoplavim nebom, Rimski forum, Španske stepenice i veličanstvenu Baziliku Svetog Petra. Otkrijte dvorišta prepuna zrelih narandži i limuna, palme na krovovima, antičke statue i vesele skutere na ulicama. Ovaj vanvremenski klasik namijenjen je svima koji su ikada bacili novčić u Fontanu di Trevi — ili tek maštaju o tome.', 'Запрыгивайте на воображаемый мотороллер: вас ждет самая солнечная, остроумная и стильная экскурсия по Вечному городу!', 'Hop on a vintage scooter for the sunniest, most delightfully stylish tour of the Eternal City you''ll ever take!', 'Skočite na vespu i krenite u najsunčaniji, najduhovitiji i najstilizovaniji obilazak Vječnog grada!', '/covers/DP-0717.webp', '#d66138', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real","funny"]', '["rome","travel","cities","architecture","history"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('флаги-мира-718', 'DP-0718', 'Флаги мира', 'Flags of the World', 'Zastave svijeta', 'Сильви Беднар', 'Sylvie Bednar', 'Silvi Bednar', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'У каждого флага своя история. Откуда взялся знаменитый канадский кленовый листок? Как называется единственная в мире страна, изобразившая на флаге свои географические очертания? Какая латиноамериканская страна является обладательницей уникального двустороннего флага? Давайте быстрее нырнём в этот мир разноцветных полос и причудливых символов. Для среднего школьного возраста.', 'Every flag tells its own story. Where did the famous Canadian maple leaf come from? Which is the only country in the world to depict its geographic contours on its flag? Which Latin American country boasts a unique double-sided flag? Dive right into this vibrant world of colorful stripes, intricate symbols, and fascinating tales. For middle grade readers.', 'Svaka zastava ima svoju priču. Odakle potiče čuveni kanadski javorov list? Kako se zove jedina zemlja na svijetu koja je na svojoj zastavi prikazala sopstvene geografske konture? Koja latinoamerička država posjeduje jedinstvenu dvostranu zastavu? Zaronimo u ovaj šareni svijet raznobojnih pruga i neobičnih simbola. Za osnovce.', 'Увлекательное кругосветное путешествие по полосам, крестам и звёздам, после которого ты станешь главным знатоком флагов в классе!', 'A colorful world tour through stripes, crosses, and stars that will instantly turn you into your class''s top flag expert!', 'Uzbudljivo putovanje oko svijeta kroz pruge, krstove i zvijezde koje će te pretvoriti u pravog stručnjaka za zastave!', '/covers/DP-0718.webp', '#2b5c8f', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["flags","geography","history","symbols","world"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайны-глобуса-блау-719', 'DP-0719', 'Тайны глобуса Блау', 'Secrets of the Blaeu Globe', 'Tajne Blaeuvog globusa', 'Мария Пономаренко', 'Maria Ponomarenko', 'Marija Ponomarenko', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Эта книга посвящена непростой и полной тайн судьбе огромного 300-летнего глобуса. Прежде чем оказаться в одном из залов Государственного исторического музея, этот медный шар, на который нанесена карта мира с изображением диковинных животных и морских сражений, преодолел около 4 тысяч километров по морю и заснеженным российским полям, не раз переезжал из Москвы в Санкт-Петербург, подвергался варварскому обращению и бережной реставрации. Автор книги предлагает читателю вместе поломать голову над загадками, связанными с этим громадным молчаливым экспонатом. Кто был первым владельцем глобуса? Почему он оказался в России и как его к нам везли? Почему глобус был важным оружием в торговой борьбе разных стран? Наконец, что шуршит внутри глобуса? Книга, где все вертится вокруг одного медного шара, иллюстрирована множеством старинных карт, фотографиями удивительных деталей глобуса, которые обычным посетителям рассмотреть не удается.', 'This book unravels the complex and mysterious destiny of an enormous 300-year-old globe. Before finding its home at the State Historical Museum, this giant copper sphere—adorned with maps of fantastical beasts and dramatic naval battles—traveled over 4,000 kilometers across stormy seas and snowbound plains, survived rough handling, and underwent delicate restorations. Join this historical detective quest: Who originally owned the globe? How did it become a secret weapon in trade rivalries? And most intriguingly, what is rustling inside? Packed with archival maps and close-up photographs of hidden details, this volume turns cartography into an unforgettable adventure.', 'Ova knjiga posvećena je neobičnoj i tajnama obavijenoj sudbini ogromnog globusa starog tri vijeka. Prije nego što se smjestila u Državnom istorijskom muzeju, ova bakarna sfera — iscrtana mapama sa neobičnim zvijerima i pomorskim bitkama — prešla je oko četiri hiljade kilometara preko mora i sniježnih prostranstava, trpjela grubo postupanje i doživjela pažljivu restauraciju. Autorka poziva čitaoce da zajedno rješavaju zagonetke: ko je bio prvi vlasnik, zašto je globus bio moćno oružje u trgovačkim ratovima i šta to šuška u njegovoj unutrašnjosti? Obogaćena starim mapama i rijetkim fotografijama detalja, ova knjiga pretvara istoriju u uzbudljivu avanturu.', 'Настоящий исторический детектив вокруг гигантского медного шара: со старинными картами, морскими битвами и тайной того, что шуршит внутри!', 'A real historical detective quest centered around a giant copper globe, filled with antique maps, sea battles, and a secret rustling inside!', 'Pravi istorijski detektivski poduhvat o ogromnom bakarnom globusu, drevnim mapama, pomorskim bitkama i misteriji šta to šuška u njegovoj unutrašnjosti!', '/covers/DP-0719.webp', '#9c6838', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["history","geography","maps","museums","detective"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('фермерские-рынки-мира-720', 'DP-0720', 'Фермерские рынки мира', 'Farmers'' Markets of the World', 'Pijace svijeta', 'Мария Бахарева', 'Maria Bakhareva', 'Marija Bahareva', 'Анна Десницкая', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Доводилось ли вам побывать на настоящем фермерском рынке, куда идёшь с утра пораньше с сумкой-тележкой, чтобы успеть купить самые свежие продукты? А что насчёт рынков в других странах мира? Взять, например, Израиль: зимой там сезон клубники, и можно хоть каждый день лакомиться сладкими ягодами! На тайском рынке можно найти самые экзотические фрукты, в том числе дуриан, который запрещено вывозить из Таиланда. Загляни на рынок в Эфиопии и попробуй местную выпечку самбусу — пальчики оближешь! На рынке в Сан-Франциско продаётся мороженое с самыми невероятными вкусами — «Арахисовая паста с шоколадным печеньем» или «Клубника с засахаренным халапеньо». Открывай книгу и отправляйся в кругосветное гастрономическое путешествие по 24 фермерским рынкам в 12 странах мира — от Европы до Африки. Ты узнаешь, как выглядят рынки в разных уголках планеты и что на них можно купить. А ещё тебя ждут увлекательные квесты на каждом из рынков и рецепты национальных блюд.', 'Have you ever visited a bustling farmers'' market, pulling a cart early in the morning to snag the freshest treats? Now imagine touring markets around the globe! In Israel, winter brings sweet strawberries, while Thailand surprises with exotic fruits like durian. In Ethiopia, you can savor crispy sambusa pastries, and in San Francisco, daring foodies can try strawberry and candied jalapeño ice cream. Embark on a mouth-watering world tour across 24 vibrant markets in 12 countries, packed with search-and-find games and authentic local recipes.', 'Jeste li ikada posjetili pravu pijacu rano ujutro, sa cegerom u ruci, kako biste ugrabili najsvježije voće i povrće? A šta je sa pijacama širom planete? U Izraelu je zimi sezona jagoda, na tajlandskim tezgama čekaju vas egzotični plodovi poput durijana, u Etiopiji miriše hrskava sambusa, a u San Francisku možete probati sladoled od jagoda i halapenjo papričica! Krenite na gastronomsko putovanje kroz 24 pijace u 12 zemalja svijeta, uz zabavne zadatke i autentične recepte.', 'Хватайте авоськи и готовьте аппетит: это кругосветное гастрономическое путешествие по самым колоритным рынкам планеты вдохновит готовить и пробовать новое!', 'Grab your shopping bag and a big appetite: this mouth-watering tour of the world’s most vibrant markets will inspire young chefs and travelers alike!', 'Pripremite cegere i dobar apetit, jer vas ova ukusna šetnja najšarenijim svjetskim pijacama vodi pravo u pravu kulinarsku avanturu!', '/covers/DP-0720.webp', '#e0633b', 'nonfiction', 'ru', 'available', '6+', '["adventure","real"]', '["food","travel","geography","cooking","cultures","markets"]', 1792836322699, 1792845670628);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хлеб-вкус-мира-721', 'DP-0721', 'Хлеб. Вкус мира', 'Bread: The Taste of the World', 'Hljeb: Ukus svijeta', 'Бахарева Мария', 'Maria Bakhareva', 'Marija Bahareva', 'Десницкая Анна', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Скажи, какой хлеб любят у тебя дома, и я угадаю, откуда ты родом. А пробовал ли ты когда-нибудь итальянскую фокаччу, индийскую булочку пав, японский хлеб сёкупан и маорийский картофельный хлеб рэвену? Всего четыре ингредиента — мука, вода, соль и дрожжи. А хлеб получается разный. Хлеб ценят и любят везде. Давай отправимся в кругосветное хлебное путешествие. Побываем на разных континентах, в разных странах, городах и даже на полярной станции. А по дороге заглянем в местные булочные и пекарни и узнаем, как готовят хлеб по всему миру. Тебя ждут увлекательные квесты и национальные рецепты. Что может быть вкуснее свежего хлеба?', 'Tell me what bread you bake at home, and I''ll guess where you are from! Have you ever tasted Italian focaccia, Indian pav buns, Japanese shokupan, or Māori potato rēwena? Just four humble ingredients—flour, water, salt, and yeast—yield endless delicious varieties. Set off on a mouthwatering around-the-world voyage across continents, busy cities, and even a remote polar station. Peek inside local bakeries, discover fun cultural quests, and bake authentic international recipes together.', 'Reci mi kakav hljeb jedeš kod kuće, i pogodiću odakle si! Jesi li ikada probao italijansku fokaču, indijsko pecivo pav, japanski šokupan ili maorsku krompirovu reveni? Samo četiri sastojka — brašno, voda, so i kvasac — a hljeb je svuda drugačiji. Kreni na ukusno putovanje oko svijeta kroz kontinente, gradove i daleke polarne stanice. Zavirite u lokalne pekare, otkrijte uzbudljive priče i isprobajte tradicionalne recepte.', 'Не открывайте эту книгу на голодный желудок: после каждой страницы вам нестерпимо захочется отломить хрустящую корочку свежего багета!', 'Do not open this book on an empty stomach: every single page will make you crave a slice of warm, crusty bread!', 'Ne otvarajte ovu knjigu praznog stomaka: sa svake stranice zamirisaće vam topla, hrskava korica svježeg hljeba!', '/covers/DP-0721.webp', '#d68334', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["bread","cooking","world cultures","geography","recipes"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('смотри-байкал-книга-путешестви-722', 'DP-0722', 'Смотри: Байкал! Книга-путешествие', 'Look: Baikal! A Journey Book', 'Pogledaj: Bajkal! Knjiga-putovanje', 'Ольга Патрушева', 'Olga Patrusheva', 'Olga Patruševa', 'Аня и Варя Кендель', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Величественный и неповторимый Байкал, красивейшее и самое глубокое озеро в мире, — достояние всей планеты. Но для каждого из нас Байкал — свой, особенный. Хочешь и ты узнать свой Байкал?Величественный и неповторимый Байкал, красивейшее и самое глубокое озеро в мире, — достояние всей планеты. Но для каждого из нас Байкал — свой, особенный. Хочешь и ты узнать свой Байкал? Тогда тебе нужен хороший проводник. Уникальное книжное путешествие, в которое ты отправляешься, подготовит тебя к встрече с настоящим Байкалом: мы собрали самые разные факты — об истории озера, его характере и обитателях, о маршрутах разной степени сложности — и постарались рассказать о проблемах, которые стоят перед Байкалом прямо сейчас. Их столько, что огромному древнему озеру очень нужна сегодня и твоя помощь. И мы подскажем тебе, как помогать Байкалу и участвовать в его жизни из любой точки Земли. Аня и Варя Кендель — российские художницы, сёстры-близнецы, которые очень любят путешествовать и вместе делают иллюстрации для книг. В 2021 году Аня пять месяцев провела на берегу Байкала, а за два года до этого прошла на байдарке 400 километров вдоль западного берега. В том походе и родилась идея сделать книгу о Байкале.', 'Lake Baikal, the deepest and oldest lake on Earth, is a marvel of the natural world. But how do you truly discover its secrets? You need an experienced guide! This illustrated expedition takes readers into the heart of Baikal: uncovering its endemic wildlife, wild winds, ancient legends, and trekking routes, while also addressing urgent ecological challenges. With breathtaking artwork by expedition artists Anya and Varya Kendel, this book shows how every one of us can help protect this ancient wonder from anywhere on the planet.', 'Veličanstveni i jedinstveni Bajkal, najdublje i najstarije jezero na planeti, pravo je prirodno čudo. Da biste ga doista upoznali, potreban vam je pouzdan vodič! Ovo ilustrovano putovanje vodi mlade istraživače u samo srce Bajkala: otkriva nevjerovatne činjenice o njegovom nastanku, jedinstvenom životinjskom svijetu i planinarskim rutama, ali i otvara važna ekološka pitanja. Uz predivne ilustracije sestara Kendel, saznaćete kako svako od nas može pomoći u očuvanju ove vodene riznice, ma gdje se nalazio.', 'Пакуйте воображаемый рюкзак: вас ждёт захватывающая экспедиция по ледяным просторам и тайнам самого глубокого озера планеты!', 'Pack your imaginary backpack: you''re off on a breathtaking expedition across the ice, depths, and secrets of the world''s deepest lake!', 'Spakujte ruksak: čeka vas uzbudljiva ekspedicija preko zaleđenih prostranstava i tajni najdubljeg jezera na planeti!', '/covers/DP-0722.webp', '#1c5274', 'nonfiction', 'ru', 'available', '6+', '["adventure","real","animals"]', '["байкал","природа","экология","путешествия","география"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('смотри-урал-книга-путешествие-723', 'DP-0723', 'Смотри: Урал! Книга-путешествие', 'Look: The Urals! A Journey Book', 'Pogledaj: Ural! Knjiga-putovanje', 'Аня и Вапя Кендель, Олег Чегодаев', 'Anya Kendel, Varya Kendel, Oleg Chegodaev', 'Anja Kendel, Varja Kendel, Oleg Čegodajev', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Уральские горы, каменный рубеж между Европой и Азией, — природная сокровищница России. Многоликий, протянувшийся на тысячи километров с юга на север, Урал каждому открывается по-своему. Хочешь и ты узнать свой Урал? Тогда тебе нужен проводник. Захватывающее книжное путешествие, в которое ты отправляешься, подготовит тебя к встрече с настоящим Уралом. Ты многое узнаешь об истории горного хребта, его природных памятниках и заповедных территориях, познакомишься с обитателями Урала, местными легендами и преданиями. Пройдёшь разнотравные степи, широколиственные леса, таёжные буреломы и бескрайние тундры по следам опытного путешественника, что оставил подсказки — маршруты по Уралу разной степени сложности, правила поведения в дикой природе и рекомендации для подготовки к твоему первому походу в горы.', 'The Ural Mountains, a rocky boundary between Europe and Asia, are a natural treasure trove stretching thousands of kilometers from south to north. This fascinating illustrated journey prepares young explorers for a real encounter with the Urals. Discover the history of the mountain range, its nature reserves and wildlife, as well as local myths and legends. Follow an experienced traveler across blooming steppes, broadleaf forests, wild taiga, and endless tundra, complete with routes of varying difficulty, wilderness survival tips, and packing advice for your very first mountain trek.', 'Uralske planine, kamena granica između Evrope i Azije, prirodna su riznica koja se pruža hiljadama kilometara od juga ka sjeveru. Ovo uzbudljivo ilustrovano putovanje pripremiće mlade istraživače za susret sa pravim Uralom. Saznajte više o istoriji ovog planinskog lanca, njegovim rezervatima prirode, životinjskom svijetu i drevnim legendama. Prođite kroz cvjetne stepe, guste tajge i beskrajne tundre prateći savjete iskusnog putnika — sa označenim planinarskim rutama i korisnim vodičem za vaš prvi pohod u planine.', 'Пакуйте воображаемый рюкзак: здесь вас ждут величественные хребты, дикие звери и настоящие маршруты от бывалого путешественника!', 'Pack your imaginary backpack: majestic mountain ridges, wild creatures, and real trekking routes from an experienced explorer await!', 'Spakujte maštu u ranac: čekaju vas veličanstveni planinski vrhovi, divlje životinje i prave staze iskusnog istraživača!', '/covers/DP-0723.webp', '#2d5a43', 'nonfiction', 'ru', 'available', 'Категория: география', '["adventure","real"]', '["mountains","nature","travel","geography","hiking"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-растут-овощи-724', 'DP-0724', 'Как растут овощи', 'How Does My Garden Grow?', 'Kako raste povrće', 'Герда Мюллер', 'Gerda Muller', 'Gerda Miler', '', 'Добрая книга', NULL, NULL, 6, 16, 'middle', 'Огород - это волшебное место, где дети, выросшие в городе, могут наблюдать за жизнью и ростом растений. Девочка Таня, героиня этой истории, поехала на каникулы в деревню к бабушке и дедушке, которые учат её сажать и выращивать овощи, обращаться с садовыми инструментами и собирать урожай. Таня узнаёт много интересного о тех растениях, плоды которых она прежде видела только на полках магазинов: как рождается и растет зеленый горошек, какую роль в жизни растений играют насекомые и птицы, как приготовить вкусный салат и как вырастить хрустящую редиску и сочную зелень в собственной квартире, устроив небольшой огород на балконе или подоконнике.', 'A vegetable garden is a wondrous place where city kids can uncover the secrets of plant life. Young Tanya spends her school holidays in the countryside with her grandparents, who show her how to sow seeds, tend to crops, use garden tools, and harvest fresh produce. Along the way, Tanya discovers how sweet peas sprout, how birds and insects help gardens flourish, and how anyone can grow crunchy radishes and fragrant herbs right on a city balcony or windowsill.', 'Povrtnjak je čarobno mjesto gdje gradska djeca mogu otkriti tajne prirode i rasta biljaka. Djevojčica Tanja provodi raspust na selu kod bake i djeda, koji je uče kako se sije sjeme, njeguju biljke, koristi baštenski alat i bere ljetina. Tanja saznaje kako niče zeleni grašak, kakvu ulogu imaju pčele i ptice, kako napraviti najukusniju salatu i kako čak i na sopstvenom balkonu ili prozorskoj dasci uzgojiti hrskave rotkvice i sočno začinsko bilje.', 'Красочный и вдохновляющий путеводитель по грядкам, после которого вам немедленно захочется посадить на подоконнике как минимум лучок и горошек!', 'A charming and wonderfully illustrated garden guide that will inspire you to plant your own peas and radishes right on the windowsill!', 'Predivno ilustrovani baštenski vodič poslije kojeg ćete poželjeti da odmah posadite grašak i rotkvice barem na svojoj prozorskoj dasci!', '/covers/DP-0724.webp', '#4e7d42', 'nonfiction', 'ru', 'available', 'поврежден корешок книги', '["real"]', '["огород","природа","растения","садоводство","экология"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дары-природы-725', 'DP-0725', 'Дары природы', 'Gifts of Nature: An Illustrated Guide', 'Darovi prirode', 'Аладжиди, Чукриэль', 'Virginie Aladjidi, Emmanuelle Tchoukriel', 'Virginie Aladjidi, Emmanuelle Tchoukriel', '', 'Clever', NULL, NULL, 6, 16, 'middle', 'Эта увлекательная энциклопедия познакомит вас с фруктами, овощами, различными плодами и съедобными грибами. Рассматривайте удивительные реалистичные иллюстрации в классическом стиле, читайте об интересных фактах и познавайте чудесный мир, окружающий нас. Гид для родителей: Новая книга будет интересна каждому ребенку и родителям, а также бабушкам и дедушкам, сестрам и братьям, ведь путешествовать и познавать мир увлекательно для каждого! Иллюстрированная энциклопедия адресована детям от 6 лет и она станет прекрасным помощником в школе. Ее можно просто читать и рассматривать иллюстрации, а кроме этого готовить доклады и рефераты, и планировать летний отпуск по ней тоже приветствуется. Раскрывая "Дары природы. Иллюстрированный справочник" вы попадаете в интересный мир съедобных растений, фруктов, различными плодами и съедобных грибов и многого другого.', 'This captivating botanical encyclopedia introduces young readers to fruits, vegetables, wild berries, and edible mushrooms. Featuring exquisite, lifelike vintage-style watercolor illustrations and curious facts, it turns exploring edible wonders into an inspiring family adventure and a handy companion for school projects.', 'Ova fascinantna ilustrovana enciklopedija vodi djecu kroz bogat svijet voća, povrća, šumskih plodova i jestivih gljiva. Uz predivne, realistične akvarele u klasičnom stilu i mnoštvo zanimljivih činjenica, knjiga budi ljubav prema prirodi i služi kao savršen priručnik za školske projekte i porodična istraživanja.', 'Вкусная и невероятно красивая ботаническая прогулка по садам, лесам и огородам!', 'A mouthwatering and exquisitely illustrated botanical stroll through gardens, forests, and orchards!', 'Predivno ilustrovana botanička šetnja kroz bašte i šume koja budi i radoznalost i apetit!', '/covers/DP-0725.webp', '#4c7744', 'nonfiction', 'ru', 'available', '?', '["real"]', '["nature","botany","plants","mushrooms","encyclopedia"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('насекомые-726', 'DP-0726', 'Насекомые', 'Insects', 'Insekti', 'Аладжиди, Чукриэль', 'Virginie Aladjidi, Emmanuelle Tchoukriel', 'Virginie Aladjidi, Emmanuelle Tchoukriel', '', 'Clever', NULL, NULL, 6, 16, 'middle', 'Почувствуйте себя великим естесствоиспытателем! Вы познакомитесь с насекомыми, составляющими 80% животного мира, - от хорошо знакомых бабочек и ос до экзотических жуков-голиафов и скарабеев. Рассматривайте удивительные реалистичные иллюстрации в классическом стиле, читайте об интересных фактах и познавайте чудесный мир, окружающий нас.', 'Feel like a true naturalist! Discover the fascinating world of insects, which make up 80% of the animal kingdom—from familiar butterflies and wasps to exotic Goliath beetles and sacred scarabs. Enjoy breathtaking, realistic botanical-style illustrations, explore intriguing scientific facts, and marvel at the tiny wonders of nature.', 'Osjećajte se kao pravi prirodnjak! Upoznajte nevjerovatan svijet insekata koji čine čak 80% životinjskog carstva — od dobro poznatih leptira i osa do egzotičnih golijat buba i skarabeja. Uživajte u izuzetnim realističnim ilustracijama u stilu starih prirodnjačkih dnevnika i otkrijte tajne čudesnog mikrosvijeta.', 'Вооружитесь лупой и любопытством: эта изысканная иллюстрированная энциклопедия вмиг превратит вас в заправского энтомолога!', 'Grab your magnifying glass and get ready: this exquisite vintage-style guide turns any curious reader into a passionate bug explorer!', 'Uzmite lupu i pripremite se za otkrića: ova prefinjena ilustrovana enciklopedija pretvoriće vas u pravog malog entomologa!', '/covers/DP-0726.webp', '#4c734b', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real"]', '["insects","nature","encyclopedia","biology","wildlife","science"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-лесу-727', 'DP-0727', 'В лесу', 'In the Forest', 'U šumi', 'Петр Багин', 'Pyotr Bagin', 'Petar Bagin', '', 'Мелик-Пашаев', NULL, NULL, 6, 16, 'middle', 'Разворотные иллюстрации, посвящённые каждому месяцу в году, не просто выразительны и живописны, они еще и абсолютно точны с зоологической точки зрения. За зимой приходит весна, вслед за весной - лето и осень… Вокруг маленького читателя ходят медведи, олени, лоси, белки, лисы, зайчата, рыси. Птицы строят гнезда, звери роют норы. Птенцы выбираются из яиц, головастики - из икринок, зверята сосут материнское молоко. Для дошкольного возраста.', 'Double-page spreads dedicated to each month of the year are not only picturesque and expressive, but also meticulously accurate from a zoological standpoint. As winter turns to spring, and spring gives way to summer and autumn, young readers will watch bears, deer, foxes, and lynxes go about their lives. Birds build nests, animals dig burrows, chicks hatch, and wild cubs grow—a living forest calendar painted with boundless warmth.', 'Raskošne ilustracije posvećene svakom mjesecu u godini nijesu samo slikovite već i zapanjujuće precizne sa zoološkog stanovišta. Zima prelazi u proljeće, proljeće u ljeto i jesen... Mali čitaoci prate medvjede, jelene, lisice i risove kako grade skrovišta, podižu mladunce i dijele šumski dom kroz četiri godišnja doba.', 'Целый год лесных секретов в изумительных картинах, где каждую букашку и медвежонка хочется разглядывать с лупой!', 'A full year of forest wonders in breathtaking panoramas where you''ll want a magnifying glass to spot every little critter!', 'Čitava godina šumskih tajni u predivnim slikama đe ćete poželjeti lupu da istražite svaki skriveni kutak i šapu!', '/covers/DP-0727.webp', '#3b6938', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real"]', '["forest","nature","seasons","wildlife","illustrated guide"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('моя-книга-бабочек-728', 'DP-0728', 'Моя книга бабочек', 'My Butterfly Book', 'Moja knjiga leptira', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Эмма Тиннерт', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'В книге доступным и увлекательным языком описаны более тридцати видов бабочек, распространенных в России и других странах мира. Благодаря подробным и точным иллюстрациям книгу можно использовать как определитель бабочек. Издание адресовано широкому кругу читателей. Для младшего и среднего школьного возраста.', 'Written in an engaging and accessible style, this book introduces over thirty butterfly species found across Europe and beyond. With delicate, accurate, and vivid illustrations, it serves as both an inspiring read and a wonderful field guide for young naturalists exploring the outdoors.', 'Napisana jednostavnim i zanimljivim jezikom, ova knjiga opisuje više od trideset vrsta leptira. Zahvaljujući detaljnim i vjerodostojnim ilustracijama, služi i kao uzbudljivo štivo i kao praktičan vodič za prepoznavanje ovih krilatih ljepotana tokom svake šetnje kroz prirodu.', 'Возьмите эту книгу на прогулку, и обычная полянка превратится в настоящий музей живых порхающих сокровищ!', 'Take this guide on your next walk and watch any ordinary meadow turn into an open-air gallery of fluttering wonders!', 'Ponesite ovu knjigu u šetnju i obična livada pretvoriće se u pravu galeriju lepršavih, živih dragulja!', '/covers/DP-0728.webp', '#e09438', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real"]', '["butterflies","nature","insects","field guide","wildlife"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мышиная-книга-729', 'DP-0729', 'Мышиная книга', 'The Mouse Book', 'Mišja knjiga', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Стаффан Ульстрем', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'В этой книге речь пойдет о самых важных животных на свете - полевках и мышах. Мы заглянем в их мир и увидим их в родной стихии. Встретим красивую красно-серую полевку, таинственного лесного лемминга, самую обычную рыжую полевку и многих, многих других! Надеемся, что эта книга поможет тебе по-другому взглянуть на жизнь мелких зверьков, которые незаметно живут рядом с нами. Шведский писатель Стефан Каста хорошо известен во всём мире, как автор подростковых романов, которые принесли ему множество международных наград. Однако его творчество не ограничивается только ими. Одна из наиболее известных серий Стефана о природе - книги-путеводители по полям и лесам с муравьишкой Софи. "Белая ворона" выпустила на русском языке все пять книг серии.', 'This captivating guide introduces young readers to some of the most important little creatures on Earth—voles, mice, and lemmings. Step into their secret habitats and meet the elusive wood lemming, the bank vole, and many other tiny neighbors. Acclaimed Swedish author Stefan Casta invites us to look closely at the ground beneath our feet and discover the astonishing hidden lives of these furry survivors.', 'Ova knjiga vodi mlade čitaoce u fascinantan svijet nekih od najvažnijih malih stvorenja na planeti — voluharica, miševa i leminga. Zavirite u njihova skrivena staništa i upoznajte tajanstvenog šumskog leminga, riđu voluharicu i mnoge druge krznene komšije. Poznati švedski pisac Stefan Kasta pomaže nam da prirodu pogledamo novim očima i otkrijemo čudesni život bića koja neprimjetno trčkaraju tik pored nas.', 'Приготовьтесь заглянуть под каждый листик и корягу — оказывается, у полёвок и леммингов кипит жизнь покруче любого детектива!', 'Get ready to peek beneath the fallen leaves—turns out mice and voles live lives more thrilling than any detective story!', 'Spremite se da zavirite pod svaki list i panj — ispostavilo se da miševi i voluharice vode uzbudljiviji život od bilo kog detektiva!', '/covers/DP-0729.webp', '#8b5a2b', 'nonfiction', 'ru', 'available', '6+', '["animals","real"]', '["mice","rodents","nature","wildlife","nonfiction"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-мире-жуков-730', 'DP-0730', 'В мире жуков', 'The Beetle Book', 'U svijetu buba', 'Стив Дженкинс', 'Steve Jenkins', 'Stiv Dženkins', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'В своей необычной книге знаменитый иллюстратор Стив Дженкинс демонстрирует самых разных жуков во всей красе и знакомит маленьких читателей с удивительными фактами из их жизни. Как устроены насекомые, как они растут, чем питаются, где живут, как общаются между собой? Ваш ребенок найдет ответы на эти и многие другие вопросы во время увлекательного путешествия в фантастический мир жуков.', 'In this extraordinary book, celebrated illustrator Steve Jenkins showcases beetles of every shape and size, revealing the fascinating marvels of their daily lives. Young readers will discover how these insects are built, how they grow, what they eat, and how they communicate, embarking on an eye-opening journey into a stunningly diverse miniature world.', 'U ovoj nesvakidašnjoj knjizi, proslavljeni ilustrator Stiv Dženkins predstavlja najrazličitije bube u punom sjaju i otkriva nevjerovatne činjenice iz njihovog života. Kako su građeni insekti, kako rastu, čime se hrane i kako komuniciraju? Djeca će pronaći odgovore na ova i mnoga druga pitanja na uzbudljivom putovanju kroz čudesni mikrosvijet buba.', 'Приготовьтесь заглянуть под лупу: великолепные коллажи Стива Дженкинса доказывают, что жуки — самые стильные и удивительные инженеры дикой природы!', 'Grab a magnifying glass: Steve Jenkins’ breathtaking collages prove that beetles are nature''s most stylish and ingenious little marvels!', 'Pripremite lupu: veličanstveni kolaži Stiva Dženkinsa dokazuju da su bube najotmjenija i najčudesnija mala stvorenja u prirodi!', '/covers/DP-0730.webp', '#2d6a4f', 'nonfiction', 'ru', 'available', '4+ | поврежден корешок книги', '["animals","real"]', '["beetles","insects","nature","nonfiction","biology"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('софи-в-мире-деревьев-731', 'DP-0731', 'Софи в мире деревьев', 'Sophie in the World of Trees', 'Sofi u svijetu drveća', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Бу Мосберг', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Знаешь ли ты, из какого дерева сделана бумага, на которой напечатана эта книжка? А из каких деревьев делают музыкальные инструменты и военные корабли, зубочистки и уголь для рисования, палочки для мороженого и лыжи? Сколько лет самому старому дубу России, и почему дубы растут поодиночке? Почему кленовые листья осенью становятся разноцветными? Муравьишка Софи приглашает тебя в удивительную экспедицию. Вместе с ней мы узнаем много интересного о жизни деревьев и цветов, которые мы встречаем каждый день. Для детей дошкольного и младшего школьного возраста', 'Do you know which tree gave us the paper in this book? Or which trees are crafted into violins, warships, toothpicks, and skis? Why do maple leaves turn fiery red in autumn, and how old can an oak really get? Join Sophie the curious little ant on an eye-opening expedition into the forest, uncovering the extraordinary secrets of the trees and plants we pass by every day.', 'Znaš li od kojeg drveta je napravljen papir ove knjige? A od kojeg se prave muzički instrumenti, brodovi, čačkalice ili skije? Zašto javorovo lišće u jesen mijenja boju i koliko je star najstariji hrast? Mala radoznala mravica Sofi vodi te u čudesnu šumsku ekspediciju u kojoj ćeš otkriti nevjerovatne tajne drveća koje svakodnevno susrećemo.', 'Вместе с любопытной муравьишкой Софи даже привычная прогулка по парку превратится в захватывающее ботаническое расследование!', 'With curious Sophie the ant as your guide, an everyday stroll through the park turns into a thrilling botanical adventure!', 'Uz radoznalu mravicu Sofi kao vodiča, svaka obična šetnja parkom pretvoriće se u uzbudljivu botaničku avanturu!', '/covers/DP-0731.webp', '#386641', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","adventure","animals"]', '["trees","nature","forest","botany","ecology"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('софи-в-мире-грибов-732', 'DP-0732', 'Софи в мире грибов', 'Sophie in the Mushroom Forest', 'Sofi u svijetu gljiva', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Бу Мосберг', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Хочешь больше узнать про грибы? Тогда эта книга для тебя! В ней мы не только расскажем о грибах, но и постараемся раскрыть тебе душу леса. Мы, авторы этой книги, думаем, что лисички, рыжики, сыроежки и белые - не просто грибы. У них есть своя тайна! Во всяком случае, нам так кажется. Мы расскажем тебе о грибах, которые растут в соседнем лесу. Со временем ты тоже научишься их узнавать, полюбишь собирать и будешь с удовольствием заниматься этим в свободное время. Для младшего и среднего школьного возраста.', 'Curious to discover the hidden wonders of mushrooms? This charming guide introduces chanterelles, porcini, russulas, and more, unveiling the quiet soul of the forest and turning any casual walk into a delightful woodland treasure hunt.', 'Želite li da otkrijete tajne šumskih gljiva? Ova topla i poučna knjiga vodi vas kroz svijet lisičarki, vrganja i golubača, otkrivajući skrivenu dušu šume i učeći vas kako da postanete pravi mali istraživači prirode.', 'Возьмите эту уютную книгу на прогулку в лес — и вы сразу почувствуете себя настоящим исследователем грибных тайн!', 'Take this delightful guide along on your next woodland stroll, and every patch of moss will turn into a fascinating treasure hunt!', 'Ponesite ovaj šarmantni vodič u šetnju šumom i svaki mahovinasti kutak postaće prava mala ekspedicija!', '/covers/DP-0732.webp', '#5a784b', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","adventure"]', '["mushrooms","nature","forest","ecology","guide"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('софи-в-мире-ягод-733', 'DP-0733', 'Софи в мире ягод', 'Sophie in the World of Berries', 'Sofi u svijetu bobica', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Бу Мосберг', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Умеешь ли ты отличать дикую малину от костяники? Знаешь ли, что ягоды можно собирать круглый год, даже зимой? А из какой ягоды получается самое вкусное желе? В этой книге мы расскажем о том, что за ягоды встречаются в наших лесах, научим тебя различать даже такие малоизвестные ягоды, как куманика, княженика и водяника. Ты узнаешь, какие ягоды ядовиты, а какие съедобны, как их лучше собирать и что из них можно приготовить. И главное: ты снова встретишься с муравьишкой Софи и попадешь на большой Ягодный Пир! Для младшего и среднего школьного возраста.', 'Do you know how to tell wild raspberries apart from stone brambles, or that berries can be foraged all year round, even in winter? Guided by Sophie the curious little ant, young naturalists will explore forests and meadows to discover both delicious and poisonous berries, learn foraging secrets, and find out what treats to make from the harvest.', 'Znaš li kako da razlikuješ divlju malinu od kostunice, ili da se bobice mogu sakupljati tokom cijele godine, pa čak i zimi? Uz vođstvo radoznale mravice Sofi, mali prirodnjaci će istražiti šume i livade, otkriti jestive i otrovne bobice, naučiti tajne branja i saznati koje se poslastice od njih mogu napraviti.', 'Отправляйтесь в лес вместе с неутомимой муравьишкой Софи, чтобы стать настоящим экспертом по лесным ягодам и сладким лакомствам!', 'Head into the woods with curious little Sophie the ant and become a certified expert on wild berries and forest treats!', 'Krenite u šumu sa radoznalom mravicom Sofi i postanite pravi stručnjak za šumsko voće i slasne đakonije!', '/covers/DP-0733.webp', '#a82b42', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["adventure","animals","real"]', '["berries","nature","botany","foraging","forest"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цветочная-книга-шмеля-734', 'DP-0734', 'Цветочная книга шмеля', 'The Bumblebee''s Flower Book', 'Bumbarova knjiga o cvijeću', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Май Фагерберг', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Многое в природе скрыто от наших глаз, и многое нам непонятно. Но случайностей в ней очень мало. Даже насекомые и те не кружат просто так. Подобно миру людей, их мир продуман и упорядочен. В этой книге мы расскажем вам правдивую сказку о жизни шмелей. Знаете ли вы, что на цветах для шмелей нанесены особые дорожные знаки? А что шмели обожают синие и жёлтые цветы, слышали? А что, летая, они оставляют в воздухе невидимый ароматный след? Раздел ботаники, изучающий цветение и опыление растений, называется «антэкология», и это очень увлекательная наука! Возможно, для кого-то эта книга станет первым определителем растений.', 'Much in nature is hidden from our eyes, yet very little in it is accidental. Even insects don''t just buzz around without a purpose! Just like our world, theirs is thoughtfully organized. This book tells the true story of bumblebees'' lives. Did you know flowers display special ''road signs'' just for bumblebees? Or that bumblebees love blue and yellow petals and leave an invisible scented trail in the air? The study of pollination, anthecology, is a fascinating science—and this book might just become your first botanical field guide.', 'Mnogo toga u prirodi skriveno je od naših očiju i malo toga je slučajno. Čak ni insekti ne zuje unaokolo tek tako! Baš kao i ljudski svijet, i njihov je osmišljen i uređen. Ova knjiga donosi istinitu priču o životu bumbara. Da li ste znali da cvijeće ima posebne „saobraćajne znakove“ za bumbare? Ili da bumbari obožavaju plave i žute cvjetove i za sobom ostavljaju nevidljiv mirisni trag? Nauka o oprašivanju je nevjerovatno uzbudljiva, a ova knjiga može postati vaš prvi pravi vodič kroz svijet biljaka.', 'Наденьте воображаемые усики и взгляните на летнюю полянку глазами пушистого шмеля — здесь каждый лепесток хранит свою тайну!', 'Put on your imaginary antennae and see the meadow through the eyes of a fuzzy bumblebee—where every petal holds a secret sign!', 'Stavite zamišljene antenice i pogledajte livadu očima čupavog bumbara — gdje svaka latica krije posebnu tajnu!', '/covers/DP-0734.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real"]', '["bumblebees","flowers","botany","insects","nature guide"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-удивительные-летучие-мыши--735', 'DP-0735', '«Удивительные летучие мыши»', 'Fantastic Bats', 'Čudesni slijepi miševi', 'Мартин Эмтенес', 'Martin Emtenäs', 'Martin Emtenes', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Небольшая, но познавательная книга ученого-зоолога Мартина Эмтенеса с иллюстрациями Свена Нурдквиста. Летучих мышей принято опасаться, вокруг них сложилось много мифов и легенд. Из этой книги маленький читатель узнает интересные и достоверные факты о летучих мышах и перестанет их бояться (если когда-нибудь боялся). Книга поможет снять страх перед летучими мышами и узнать этих животных получше. Иллюстрации всемирно известного шведского художника Свена Нурдквиста. Автор — ученый и научный журналист.', 'A captivating and informative guide by zoologist Martin Emtenäs, brought to life with witty illustrations by Sven Nordqvist. Bats are often shrouded in spooky myths, but this book debunks the rumors with fascinating science and irresistible facts. Young readers will discover how incredible these nocturnal creatures truly are and will never look at night skies the same way again.', 'Fascinantna i poučna knjiga zoologa Martina Emtenesa, oživljena duhovitim ilustracijama čuvenog Svena Nurdkvista. Slijepi miševi su često obavijeni zastrašujućim mitovima, ali ova knjiga razbija predrasude istinitim naučnim činjenicama. Mali čitaoci će saznati koliko su ova noćna bića zapravo nevjerovatna i prestati da ih se plaše.', 'Забудьте о вампирах — с рисунками Свена Нурдквиста эти ночные летуны окажутся самыми очаровательными пушистиками на свете!', 'Forget the vampire myths—paired with Sven Nordqvist''s charming illustrations, these nighttime flutterers turn out to be utterly adorable!', 'Zaboravite na vampire — uz ilustracije Svena Nurdkvista ovi noćni letači postaće vam najslađa stvorenja na svijetu!', '/covers/DP-0735.webp', '#2c344e', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real","spooky"]', '["bats","zoology","nature","sven nordqvist","science for kids"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('круглый-год-736', 'DP-0736', 'Круглый год', 'All Year Round', 'Kroz cijelu godinu', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Замечательный шведский путеводитель по лесам, полям и берегам. Проводником в мире животных и растений выступает девочка Майя - она наблюдает за природой Круглый год и отлично знает, чем отличается лесная мышь от мыши-полевки, почему спящие птицы не падают с веток, где зимуют пчелы, как поступают зайцы со своим пометом и как можно сделать подводный бинокль, поймать окуня и приготовить клевер с кефиром. Для младшего и среднего школьного возраста.', 'A delightful Swedish nature guide through forests, meadows, and riverbanks. Your guide through the wonders of wildlife and flora is a curious girl named Maja. Observing nature across all four seasons, she discovers the difference between a wood mouse and a field vole, why sleeping birds don''t fall off branches, where bees spend the winter, and how to craft an underwater viewer, catch a perch, or brew a tasty clover-kefir drink.', 'Divan švedski vodič kroz šume, polja i obale. Kroz čarobni svijet životinja i biljaka vodi vas radoznala djevojčica Maja. Posmatrajući prirodu tokom cijele godine, ona otkriva razliku između šumskog i poljskog miša, zašto ptice dok spavaju ne padaju s grana, gdje pčele provode zimu i kako napraviti podvodni dvogled, upecati grgeča ili pripremiti napitak od djeteline i kefira.', 'Хватайте эту книгу и лупу: непоседа Майя научит вас разгадывать лесные тайны и превращать каждую прогулку в экспедицию!', 'Grab this book and a magnifying glass: curious Maja is ready to turn every outdoor stroll into a thrilling seasonal expedition!', 'Uzmite ovu knjigu i lupu u ruke: radoznala Maja je spremna da svaku običnu šetnju pretvori u uzbudljivu ekspediciju!', '/covers/DP-0736.webp', '#4b7d52', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["adventure","animals","real"]', '["nature","seasons","wildlife","plants","experiments"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('все-о-цветущих-растениях-737', 'DP-0737', 'Все о цветущих растениях', 'All About Flowering Plants', 'Sve o cvjetnicama', '', 'Unknown', 'Nepoznat autor', 'Малкольм Парчетт', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Около 450 цветковых растений из всех уголков мира с научными латинскими названиями. Сотни великолепных иллюстраций, сделанных специально для этого издания. Подробные иллюстрированные справки об отдельных растениях с описанием их биологических особенностей. Роскошные и скромные, известные и редкие - цветковые растения покоряют наши сердца, украшают наши квартиры, сады и парки.', 'Explore around 450 flowering plants from every corner of the globe, complete with their scientific Latin names and hundreds of bespoke botanical illustrations. From modest wildflowers to opulent blooms, this guide reveals the fascinating biological features of the plants that adorn our homes, gardens, and parks.', 'Upoznajte oko 450 cvjetnica iz svih krajeva svijeta sa naučnim latinskim nazivima i stotinama predivnih ilustracija izrađenih posebno za ovo izdanje. Od skromnih poljskih cvjetova do raskošnih latica, ovaj vodič otkriva biološke tajne biljaka koje krase naše domove, vrtove i parkove.', 'Превратите обычную прогулку в настоящую ботаническую экспедицию с этой роскошной цветущей энциклопедией!', 'Turn an ordinary walk into a thrilling botanical expedition with this blooming treasure of an encyclopedia!', 'Pretvorite običnu šetnju u pravu botaničku ekspediciju uz ovu raskošnu enciklopediju rascvjetalog svijeta!', '/covers/DP-0737.webp', '#3b7a57', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real"]', '["botany","flowers","plants","nature","encyclopedia"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('огород-на-подоконнике-738', 'DP-0738', 'Огород на подоконнике', 'Garden on the Windowsill', 'Bašta na prozorskoj dasci', 'Клара Лидстрем', 'Klara Lidström', 'Klara Lidstrem', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Во все времена людей восхищало все, что растет и зеленеет. Авторы этой книги не только рассказывают, как выращивать съедобные и декоративные растения, но и описывают всякие сумасшедшие эксперименты - например, как "прорастить" заячий помет или как сделать смешные прически из травы. Иллюстрации и пошаговые инструкции помогут детям проделать все эксперименты самостоятельно, почти без помощи взрослых. Для работы не потребуется ни дорогих материалов, ни сложных инструментов. И места надо совсем немного - для разведения этих растений достаточно подоконника, балкона или грядки на даче. Другими словами, это книжка для всех!', 'Throughout history, people have always been fascinated by anything that sprouts and turns green. This practical, cheerful handbook explains how to cultivate edible crops and houseplants, packed with whimsical DIY experiments like making funny grassy hairstyles. With clear step-by-step instructions and lively illustrations, kids can easily grow their own green oasis right on a windowsill or balcony using everyday materials.', 'Ljudi su oduvijek bili očarani svime što raste i zeleni se. Ovaj veseli i praktični priručnik ne samo da uči kako uzgajati jestive i ukrasne biljke, već nudi i gomilu zabavnih eksperimenata, poput pravljenja smiješnih frizura od trave. Uz jasna uputstva korak po korak, djeca mogu sama pretvoriti običnu prozorsku dasku ili balkon u pravu malu zelenu oazu.', 'Превратите обычный подоконник в зелёные джунгли с забавными травяными причёсками и настоящим мини-огородом!', 'Turn any sunny windowsill into a lush green jungle with funny grass haircuts and your very own mini-harvest!', 'Pretvorite običnu prozorsku dasku u malu zelenu džunglu sa smiješnim travnatim frizurama i pravom mini-baštom!', '/covers/DP-0738.webp', '#4e8c46', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","funny"]', '["gardening","plants","experiments","nature","diy"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мой-первый-огород-739', 'DP-0739', 'Мой первый огород', 'My First Garden', 'Moja prva bašta', 'Белла Линде', 'Bella Linde', 'Bela Linde', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Любишь копаться в земле? Хочешь вырастить свой урожай? Отлично! Ты на верном пути и скоро поймешь, это проще простого! Тебя ждут удивительные открытия, ведь огород - самое интересное, почти волшебное место на даче. Ты только представь: закапываешь в землю крошечные семечки и клубни, а из них вырастает самая настоящая еда. Будет огород большим или маленьким - решать тебе. Можешь устроить его на грядках под открытым небом, в ящиках или цветочных горшках. Тебе понадобятся: земля, семена, рассада и несколько картофелин - и, разумеется, немного терпения. Все, что нужно, - это чуть-чуть поливать, удобрять, пропалывать, ждать и наблюдать.', 'Do you love digging in the dirt and dream of harvesting your own crunchy vegetables? You''re on the right track! A garden is an almost magical place where tiny seeds and tubers buried in the soil turn into real, delicious food. Whether you have a big backyard patch or just a few pots on a sunny windowsill, this hands-on guide shows you how easy it is to plant, water, weed, and watch the wonders of nature grow.', 'Voliš li da čeprkaš po zemlji i maštaš o tome da ubereš sopstveno povrće? Na pravom si putu! Bašta je gotovo čarobno mjesto gdje se sitno sjeme zakopano u zemlju pretvara u pravu, ukusnu hranu. Bilo da imaš pravu baštensku leju ili tek nekoliko saksija na osunčanoj prozorskoj dasci, ovaj praktični vodič naučiće te kako da sadiš, zalivaš i uživaš u čudima prirode.', 'Превратите подоконник или дачную грядку в настоящую лабораторию вкусностей вместе с этим вдохновляющим зеленым гидом!', 'Turn your windowsill or backyard into a thriving, delicious plant lab with this wonderfully hands-on beginner''s guide!', 'Pretvorite prozorsku dasku ili baštu u pravu malu laboratoriju ukusa uz ovaj jednostavan i inspirativan zeleni vodič!', '/covers/DP-0739.webp', '#4a8542', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real"]', '["gardening","nature","plants","diy","food"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('живая-природа-за-городом-740', 'DP-0740', 'Живая природа за городом', 'Wildlife in the Countryside', 'Živi svijet u prirodi', 'Кэролин Пелиссье, Аладжиди, Чукриэль', 'Caroline Pellissier, Virginie Aladjidi, Emmanuelle Tchoukriel', 'Karolin Pelisje, Viržini Aladžidi, Emanuel Čukrijel', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Что может быть лучше прогулки за город? Смотри, сколько цветов на лугу! Как они называются? А вот ползет улитка: зачем ей нужна раковинка? Слышишь, как громко квакают лягушки: почему они селятся рядом с водой? Видишь, ежик спешит в лес: какой домик он готовит себе к зиме? Книга познакомит ребенка с удивительным миром природы и задаст немало загадок. Ответы ребенок узнает, отогнув странички-клапаны. Прекрасные натуралистичные иллюстрации Эммануэль Чукриэль покажут красоту природы. Не удивляйтесь, если ребенок вдруг предложит вам отправиться за город.', 'What could be better than a trip to the countryside? Discover meadow wildflowers, find out why snails carry shells, why frogs live near water, and how hedgehogs prepare their winter nests. Packed with curious flaps to lift and stunning, lifelike illustrations by Emmanuelle Tchoukriel, this interactive guide invites young explorers to uncover the secrets of the living world around us.', 'Šta može biti ljepše od izleta van grada? Otkrijte livadsko cvijeće, saznajte zašto puž nosi kućicu, zašto žabe krekeću pored vode i kako se jež priprema za zimu. Uz interaktivne prozorčiće koji kriju odgovore i predivne naturalističke ilustracije Emanuel Čukrijel, ova knjiga budi radoznalost i poziva na pravo istraživanje prirode.', 'Загляните под каждый клапан и превратите обычную прогулку за город в настоящее детективное исследование природы!', 'Lift the flaps and turn an ordinary walk in the countryside into a wonderful nature-detective adventure!', 'Zavirite ispod svakog prozorčića i pretvorite običnu šetnju u prirodi u pravo detektivsko istraživanje!', '/covers/DP-0740.webp', '#5b8a54', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real"]', '["nature","wildlife","interactive","countryside","plants"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('горячие-факты-про-лед-741', 'DP-0741', 'Горячие факты про лед', 'Hot Facts About Ice', 'Vruće činjenice o ledu', 'Лена Шеберг', 'Lena Sjöberg', 'Lena Šeberg', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Все знают, что лед - это замерзшая вода, он холодный, а в тепле тает. Но со льдом связана еще куча интересных вещей! Например, когда придумали холодильник? Почему лед мычит как корова? Как замерзает текучая вода? Какие животные зимуют во льду? И кто он такой - таинственный Ледяной Человек? Эта занимательная книга и ее автор, художник Лена Шёберг в 2009 году победили на шведском конкурсе научно-популярных изданий. В 2014 году в "Самокате" вышла другая познавательная книга Лены Шёберг "Крутые факты о яйцах".', 'Everyone knows ice is just frozen water, but did you know it has countless bizarre secrets? Discover when the first refrigerator was invented, why frozen lakes can moo like cows, how running water freezes, and what animals actually hibernate inside ice. Lena Sjöberg''s award-winning illustrated guide takes young explorers on a captivating, frosty journey across science, history, and nature.', 'Svi znaju da je led smrznuta voda, hladan na dodir i topiv na toploti, ali led krije čitav nevjerovatan svijet! Kada je izmišljen prvi frižider? Zašto led ponekad muče poput krave? Kako se ledi tekuća voda i koje životinje zimuju u ledu? Ova nagrađivana i bogato ilustrovana knjiga Lene Šeberg otkriva najuzbudljivije ledene tajne kroz nauku, istoriju i prirodu.', 'Приготовьте варежки: вас ждут самые ошеломительные, звонкие и забавные тайны ледяного мира, от поющих озер до ледяных мумий!', 'Grab your mittens and get ready to discover why ice moos like a cow, how animals survive inside it, and other frozen wonders!', 'Stavite rukavice: saznajte zašto zaleđena jezera muču poput krava i kako životinje mogu preživjeti okovane ledom!', '/covers/DP-0741.webp', '#4392b5', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","animals","adventure"]', '["ice","nature","science","winter","nonfiction"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('крутые-факты-о-яйцах-742', 'DP-0742', 'Крутые факты о яйцах', 'Cool Facts About Eggs', 'Nevjerovatne činjenice o jajima', 'Лена Шеберг', 'Lena Sjöberg', 'Lena Šeberg', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Познавательная книга не только для школьников, но и взрослых — об одной из двух частей известной дилеммы о курице и яйце. Хотя и курице, и другим птицам в книге тоже уделено немало внимания. Что такое яйцо, что происходит внутри него, у каких живых существ они встречаются, для чего нужны, что символизирует яйцо в разных культурах, какие есть традиции и приметы, и многие другие «крутые» сведения о яйцах.', 'An engaging and informative guide for curious minds of all ages exploring one side of the eternal chicken-and-egg dilemma. Discover what an egg really is, what goes on beneath the shell, which surprising creatures lay them, and how eggs are celebrated in nature, folklore, and cultures around the world.', 'Edukativna i zabavna knjiga za radoznalce svih uzrasta koja istražuje jednu stranu vječne dileme o kokoški i jajetu. Otkrijte šta je zapravo jaje, šta se dešava ispod ljuske, koja ga sve neobična bića legu, kao i kakvo simbolično značenje i običaje nosi u kulturama širom svijeta.', 'Приготовьтесь удивиться: оказывается, яйца несут не только куры, а внутри этой хрупкой скорлупы скрыта целая вселенная!', 'Get ready to be amazed: turns out birds aren''t the only ones laying eggs, and inside that fragile shell lies an entire incredible universe!', 'Spremite se za pravo iznenađenje: jaja ne nose samo ptice, a unutar te krhke ljuske krije se čitav jedan čudesan univerzum!', '/covers/DP-0742.webp', '#e59b2b', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real"]', '["eggs","birds","biology","nature","science"]', 1792836322699, 1792845670629);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('трогательные-факты-о-сердце-743', 'DP-0743', 'Трогательные факты о сердце', 'Touching Facts About the Heart', 'Dirljive činjenice o srcu', 'Лена Шеберг', 'Lena Sjöberg', 'Lena Šeberg', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Сердце — это самая важная мышца в нашего тела. День и ночь оно бьётся в груди, один удар в секунду, всю жизнь. Нет другой части тела, которая была бы так популярна, как сердце. Оно встречается повсюду: в песнях, стихах, искусстве и рекламе. И, конечно же, в нашей речи. Сердце может открываться и закрываться, может упасть, уйти в пятки, разбиться или пылать. У человека бывает разное сердце: ледяное, чёрствое, каменное, золотое и даже сердце льва. Слушать своё сердце — значит уметь сделать правильный выбор, даже если это порой очень трудно. В нашем сердце живут разные чувства: печаль, радость, тревога, любовь. Если любишь кого-то по-настоящему, сердце даёт тебе это понять. Знаешь ли ты, что сердце голубого кита размером с автомобиль? Или что твоё сердце такое же уникальное, как твои отпечатки пальцев? Почему кровеносные сосуды голубые, если кровь красная? Сколько сердец у дождевого червя? И что делает сердце на двери уличного туалета? В сердце столько всего сокрыто! Давайте вместе отправимся в самую глубину сердца.', 'The heart is the most hardworking muscle in our body, beating day and night for our entire life. But it is also so much more: it appears in songs, poetry, art, and everyday sayings, capturing all of our biggest emotions. From why veins look blue to the car-sized heart of a blue whale and the multiple hearts of an earthworm, this fascinating book journeys deep into both the science and the soul of the heart.', 'Srce je najvažniji mišić u našem tijelu koji neumorno kuca dan i noć. Nijedan drugi organ nije toliko prisutan u pjesmama, umjetnosti, jeziku i našim osjećanjima. Da li ste znali da je srce plavog kita veličine automobila, zašto su krvni sudovi plavi i koliko srca ima kišna glista? Ova predivna knjiga vodi nas na fascinantno putovanje kroz biologiju, emocije i nevjerovatne tajne srca.', 'Удивительная и тёплая энциклопедия, которая объяснит анатомию лучше любого учебника и покажет, почему сердце — это не просто насос, а настоящее чудо.', 'A warm, wonderfully illustrated guide that explains anatomy better than any textbook while showing that the heart is far more than just a muscle.', 'Topla i prelijepo ilustrovana knjiga koja otkriva sve tajne anatomije i pokazuje da srce nije samo obična pumpa, već pravo čudo prirode.', '/covers/DP-0743.webp', '#b82b3d', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","animals"]', '["human body","anatomy","biology","heart","science","feelings"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('календарь-линнеи-744', 'DP-0744', 'Календарь Линнеи', 'Linnea''s Almanac', 'Linejin kalendar', 'Лена Андерсон, Кристина Бьорк', 'Christina Björk, Lena Anderson', 'Kristina Bjork, Lena Anderson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', '"Линнея - так меня назвали в честь маленького розового лесного цветочка. Но если я и цветок, то городской: я ведь живу в центре города. Впрочем, я люблю цветы, листья и вообще все живое". Некоторым кажется, будто в городе природы не существует, но это совсем не так. Линнея расскажет нам много интересного о том, что происходит с городской природой в разные времена года: каких птиц можно повстречать на улице, есть ли жизнь под снегом, как устроить маленький огородик прямо у себя во дворе. Впервые Линнея появилась на детской страничке популярной шведской газеты Dagens Nyheter в 1976 году. Кристина Бьорк и Лена Андерсон придумывали небольшие истории о девочке, которая любит растения и цветы. Рубрика стала очень популярной, и ее авторам даже предложили вести детскую телевизионную передачу о садоводстве. Книга была впервые издана в Швеции в 1982 году. Для младшего и среднего школьного возраста', 'Linnea was named after a tiny pink forest flower, but she is a city girl who discovers that nature thrives even among urban streets. In this delightful month-by-month guide, she invites readers into her world: watching winter birds, uncovering life beneath the snow, and planting a mini-garden right on the balcony or in the yard. First created for a popular Swedish newspaper column in the 1970s, this beloved Scandinavian classic inspires children to spot everyday green wonders in any neighborhood.', 'Lineja je dobila ime po malom ružičastom šumskom cvijetu, ali ona živi u centru grada i dokazuje da priroda buja čak i među zgradama i pločnicima. U ovom šarmantnom vodiču kroz dvanaest mjeseci, Lineja pokazuje koje ptice posjećuju balkone zimi, kakav se život krije pod snijegom i kako napraviti malu bašticu u sopstvenom dvorištu. Ovaj vanvremenski švedski klasik uči djecu da posmatraju i čuvaju prirodu u svom svakodnevnom okruženju.', 'Возьмите эту книгу на прогулку, и вы удивитесь, сколько зелёных чудес прячется прямо под ногами посреди шумного города!', 'Tuck this book into your backpack, step outside, and discover wild green miracles blooming right beneath your city sneakers!', 'Ponesite ovu knjigu u šetnju i otkrijte koliko se skrivenih zelenih čuda krije među gradskim ulicama!', '/covers/DP-0744.webp', '#5b8a54', 'nonfiction', 'ru', 'available', 'поврежден корешок книги', '["real","animals"]', '["gardening","nature","seasons","plants","urban wildlife"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('электрические-рыбы-745', 'DP-0745', 'Электрические рыбы', 'Electric Fish', 'Električne ribe', 'Эрик Харви-Жирар', 'Éric Harvey-Girard', 'Erik Harvi-Žirar', 'Стефан Пуарье', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Осторожно! Под обложкой этой книги живут электрические скаты, угри, сомы и другие животные, использующие электрическую энергию для охоты, обороны или ориентации в пространстве. Вы узнаете, где можно встретить этих удивительных и порой опасных существ, как они устроены и какой след оставили в истории человечества. Книга завоевала Гран-при конкурсов Lux и Grafika канадского агентства Infopresse за иллюстрации и графический дизайн. Попала в шорт-лист премии Хьюберта-Ривза, вручающейся научно-популярным книгам для детей и подростков. Для среднего и старшего школьного возраста.', 'Caution! Lurking beneath the cover of this book are electric rays, eels, catfish, and other creatures that harness electrical energy for hunting, defense, and navigation. You will discover where to find these astonishing and sometimes dangerous animals, how their biological circuits work, and the spark they left in human history. Awarded Grand Prix honors at the Lux and Grafika competitions for illustration and graphic design, and shortlisted for the Hubert Reeves Science Prize.', 'Oprez! Ispod korica ove knjige kriju se električne raže, jegulje, somovi i druga stvorenja koja koriste električnu energiju za lov, odbranu ili snalaženje u prostoru. Saznaćete gdje možete sresti ova zadivljujuća i ponekad opasna bića, kako funkcionišu njihove biološke baterije i kakav su trag ostavila u istoriji čovječanstva. Knjiga je osvojila prestižne nagrade za ilustraciju i grafički dizajn i nominovana je za nagradu Iber Riv.', 'Настоящая энциклопедия подводного напряжения: берегите пальцы и готовьтесь искренне удивляться скрытым суперсилам природы!', 'A genuinely high-voltage deep dive: mind your fingers and get ready to be shocked by nature''s real-life superpowers!', 'Prava visokonaponska enciklopedija podmorja: pazite na prste i spremite se za fascinantne prirodne supermoći!', '/covers/DP-0745.webp', '#1b4d6e', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","real","adventure"]', '["fish","marine life","electricity","science","ocean"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('анатомия-океана-746', 'DP-0746', 'Анатомия океана', 'Ocean Anatomy', 'Anatomija okeana', 'Джулия Ротман', 'Julia Rothman', 'Džulija Rotman', 'Джулия Ротман', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Вас ждут настоящие приключения в этом красочном кругосветном туре по океанам планеты! Исследуйте коралловые рифы, странствуйте по полярным морям и погружайтесь в глубины, чтобы познакомиться с их необычными обитателями. Восхитительные рисунки Джулии Ротман, сочетающие искусство и науку, отражают множество увлекательных аспектов жизни на поверхности моря и под его волнами.', 'Embark on a colorful voyage across the world''s oceans! Explore vibrant coral reefs, brave the icy polar seas, and dive deep into mysterious abyssal trenches to meet bizarre sea creatures. Blending art and science, Julia Rothman''s delightful illustrations capture the wonders of marine life both above and below the waves.', 'Prava avantura vas čeka na ovom živopisnom putovanju oko svijeta kroz okeane naše planete! Istražite koralne grebene, plovite polarnim morima i zaronite u mračne dubine kako biste upoznali neobična morska bića. Divne ilustracije Džulije Rotman spajaju umjetnost i nauku, otkrivajući tajne morskog svijeta na površini i pod talasima.', 'Захватите воображаемую маску и ласты: с этой книгой нырять в тайны океана можно прямо с уютного дивана!', 'Grab an imaginary snorkel and flippers: this beautifully illustrated guide lets you explore the deepest ocean trenches without getting your feet wet!', 'Stavite zamišljenu masku i peraja: ova predivna knjiga vodi vas u najdublje morske ponore bez kapi vode!', '/covers/DP-0746.webp', '#1b638a', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["adventure","animals","real"]', '["ocean","marine life","nature","encyclopedia","illustration"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чарльз-дарвин-происхождение-ви-747', 'DP-0747', 'Чарльз Дарвин происхождение видов', 'Charles Darwin''s On the Origin of Species', 'Čarls Darvin: O porijeklu vrsta', '', 'Sabina Radeva, Charles Darwin', 'Sabina Radeva, Čarls Darvin', 'Сабина Радева', 'Махаон', NULL, NULL, 6, 16, 'middle', 'В 1859 г. Чарлз Дарвин, английский натуралист и биолог, написал книгу «Происхождение видов», в которой объяснил процесс эволюции различных видов животных. Идеи Дарвина актуальны до сих пор, и благодаря иллюстратору Сабине Радевой теперь доступны и юным читателям.', 'In 1859, naturalist Charles Darwin published ''On the Origin of Species'', revolutionizing how we understand life on Earth. Now, molecular biologist and illustrator Sabina Radeva brings this monumental scientific breakthrough to young minds through clear explanations and breathtaking artwork.', 'Godine 1859. engleski prirodnjak Čarls Darvin objavio je ''O porijeklu vrsta'', objašnjavajući proces evolucije živog svijeta. Zahvaljujući ilustratorki Sabini Radevoj, ove revolucionarne naučne ideje sada su na predivan i pristupačan način predstavljene i mladim čitaocima.', 'От динозавров и вьюрков до нас с вами: узнайте главную тайну жизни на Земле в потрясающе красивом и понятном пересказе!', 'From Galapagos finches to all of us—discover the grand mystery of life on Earth through this stunning, kid-friendly masterpiece!', 'Od zeba i leptira pa sve do nas — otkrijte veliku tajnu života na Zemlji kroz predivne i svima razumljive ilustracije!', '/covers/DP-0747.webp', '#2a5d52', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","animals","adventure"]', '["evolution","science","biology","nature","animals"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секреты-кошек-как-понять-свою--748', 'DP-0748', 'Секреты кошек Как понять свою кошку и подружиться с ней', 'Cat Secrets: How to Understand Your Cat and Become Friends', 'Tajne mačaka: Kako razumjeti svoju mačku i sprijateljiti se s njom', 'Саша Рауш', 'Sasha Rausch', 'Saša Rauš', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Все любят кошек (ну, или почти все). А вот любят ли кошки нас? Как им живется с людьми? Эта книга — не просто детская энциклопедия, это уникальный путеводитель по миру наших любимых питомцев. Автор книги — зоопсихолог Саша Рауш — отвечает на самые распространенные детские вопросы о кошках, их анатомии и повадках. Но особое внимание автор уделяет психологии животного. Как понять, что кошке плохо? Как научиться читать сигналы ее тела? Почему нельзя играть с кошкой лазерной указкой? Почему кошки любят забираться в коробки и ящики? Правда ли, что они умеют мстить? Узнав ответы на эти и многие другие вопросы, вы точно сможете подружиться со своим питомцем.', 'Everyone loves cats (well, almost everyone), but do cats love us back? This book is not just a children''s encyclopedia; it is a unique guide to the inner world of our favorite pets. Zoopsychologist Sasha Rausch answers the most intriguing questions about feline behavior and body language. Why do cats cram themselves into tiny boxes? Why shouldn''t you play with laser pointers? Do cats ever hold grudges? Packed with fun facts and practical advice, this guide will teach young readers how to truly understand and bond with their purring companions.', 'Svi vole mačke (ili skoro svi), ali da li mačke vole nas? Ova knjiga nije samo dječja enciklopedija, već jedinstveni vodič kroz unutrašnji svijet naših omiljenih ljubimaca. Zoopsiholog Saša Rauš odgovara na najčešća pitanja o mačijem ponašanju i govoru tijela. Zašto se mačke guraju u kartonske kutije? Zašto se ne preporučuje igra sa laserom? Da li mačke umiju da se svete? Otkrivajući ove tajne, naučićete kako da zaista razumijete svog ljubimca i postanete nerazdvojni prijatelji.', 'Настоящий переводчик с кошачьего на человеческий: наконец-то станет понятно, почему картонная коробка лучше любой лежанки, а виляющий хвост — вовсе не повод для объятий!', 'The ultimate cat-to-human translator: you''ll finally learn why an empty box beats any fancy pet bed and what that flicking tail really means!', 'Pravi prevodilac sa mačjeg na ljudski: konačno ćete shvatiti zašto je kartonska kutija bolja od skupog kreveta i šta vam mačka zapravo poručuje mahanjem repa!', '/covers/DP-0748.webp', '#e07a5f', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["animals","friends","real"]', '["кошки","домашние питомцы","зоопсихология","энциклопедия","cats"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('невероятно-опасная-слизь-ледян-749', 'DP-0749', 'Невероятно! Опасная слизь, ледяные мышки, съедобные камни и еще 95 историй о мире вокруг нас', 'Incredible! Dangerous Slime, Glacier Mice, Edible Stones, and 95 More Stories About the World Around Us', 'Nevjerovatno! Opasna sluz, ledeni miševi, jestivo kamenje i još 95 priča o svijetu oko nas', 'Ася Ванякина Настя Троян', 'Asya Vanyakina, Nastya Troyan', 'Asja Vanjakina, Nastja Trojan', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Каждый день ученые по всему миру совершают удивительные открытия. Они узнают новые факты о суперспособностях животных и растений, выясняют захватывающие подробности об истории Вселенной. Чаще всего все эти истории остаются на страницах научных журналов. А жаль — ведь детям и родителям это тоже интересно!', 'Every day, scientists around the world make astonishing discoveries. They uncover new facts about the superpowers of animals and plants, and reveal fascinating details about the history of the universe. All too often, these stories stay locked away in scientific journals—which is a pity, because kids and parents find them just as thrilling!', 'Svakog dana naučnici širom svijeta dolaze do nevjerovatnih otkrića. Otkrivaju nove činjenice o supermoćima biljaka i životinja i rasvjetljavaju uzbudljive tajne istorije univerzuma. Najčešće ove priče ostaju zaključane u naučnim časopisima — a šteta je, jer su podjednako fascinantne i djeci i roditeljima!', 'Приготовьтесь удивляться на каждой странице: настоящая наука покруче любых фантастических комиксов!', 'Get ready to be amazed on every single page: real science is way cooler than any superhero comic!', 'Pripremite se za čuđenje na svakoj stranici: stvarna nauka je mnogo uzbudljivija od bilo kog stripa o superherojima!', '/covers/DP-0749.webp', '#2b9348', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","animals","funny"]', '["science","nature","animals","fun facts","curiosity"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мой-гербарий-волшебные-цветы-750', 'DP-0750', 'Мой гербарий. Волшебные цветы', 'My Herbarium: Magical Flowers', 'Moj herbarijum: Čarobno cvijeće', 'Стефани Циск', 'Stephanie Zisk', 'Stefani Zisk', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Эта книга посвящена 16 садовым растениям - про каждое из них ребенок узнает много интересного. Точные рисунки, сделанные художником с натуры, помогут легко найти и распознать эти растения в саду и на даче. Книга - увлекательное подспорье в учебе. Если в школе задали на лето сделать гербарий, скучное задание учителя станет волшебным! Советы по сбору и высушиванию растений пригодятся для создания собственного гербария. Весело и доступно книга рассказывает, с чего начать, как работать и на что обращать внимание при сборе и засушивании растений.', 'This charming guide introduces young naturalists to 16 common garden plants through lifelike botanical illustrations. Packed with practical, step-by-step advice on gathering, pressing, and preserving blossoms, it effortlessly turns an ordinary school assignment into an inspiring and creative botanical project.', 'Ova predivna knjiga vodi mlade prirodnjake kroz svijet 16 baštenskih biljaka uz vjerne botaničke ilustracije. Uz praktične savjete o branju, sušenju i čuvanju latica, uobičajeni školski zadatak pravljenja herbarijuma pretvara se u pravo kreativno uživanje i uzbudljiv hobi.', 'Вооружитесь ножницами и промокашкой: с этой книгой школьный гербарий превратится в настоящее ботаническое творчество!', 'Grab your scissors and blotting paper—this book turns ordinary flower pressing into a truly magical botanical craft!', 'Uzmite papir za sušenje i krenite u baštu — ova knjiga pretvara pravljenje herbarijuma u pravu malu botaničku čaroliju!', '/covers/DP-0750.webp', '#528c68', 'nonfiction', 'ru', 'available', '?', '["real","magic"]', '["botany","flowers","plants","nature","crafts"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мой-лесной-гербарий-751', 'DP-0751', 'Мой лесной гербарий', 'My Forest Herbarium', 'Moj šumski herbarijum', 'Анна Томас-Белли', 'Anne Thomas-Belli', 'Ana Tomas-Beli', '', '', NULL, NULL, 6, 16, 'middle', 'Берёза, липа, клён, ясень, пихта, сосна, лиственница - как не запутаться малышу в таком разнообразии деревьев? Как определить, какие растения, грибы и ягоды в лесу ядовиты, а какие безопасны? С помощью этого познавательного альбома-гербария ваш ребёнок сделает свои первые открытия в мире природы! Из этой книги он узнает массу полезной информации о лесе: кто там живёт и что растёт, чем деревья отличаются друг от друга, а также как связаны между собой все части удивительной системы под названием "лес". А прекрасная коллекция листьев и семян будет долгие годы напоминать вам и вашему ребёнку о совместных прогулках! Для детей младше 6 лет.', 'Birch, linden, maple, ash, fir, pine, larch—how can a young explorer tell them apart in such a vast world of trees? How do you recognize which forest plants, mushrooms, and berries are edible and which are dangerous? With this interactive guide and herbarium album, children will uncover how the forest ecosystem lives and breathes, while gathering leaves and seeds to turn family walks into lasting memories.', 'Breza, lipa, javor, jasen, jela, bor, ariš — kako se snaći u tolikom bogatstvu drveća? Kako prepoznati koje su šumske biljke, gljive i bobice otrovne, a koje bezbjedne? Uz ovaj edukativni herbarijum, mali istraživači prirode otkriće ko sve živi u šumi i kako funkcioniše ovaj čudesni ekosistem, a zbirka osušenih listova i sjemenki čuvaće uspomene na zajedničke šetnje godinama.', 'Хватайте лупу, надевайте удобные кроссовки и отправляйтесь в лес превращать шуршащие листья в собственный научный шедевр!', 'Grab a magnifying glass, lace up your sneakers, and turn fallen leaves into your very own botanical treasure trove!', 'Zgrabite lupu, obujte udobne patike i pretvorite šuškanje šumskog lišća u svoje pravo malo botaničko remek-djelo!', '/covers/DP-0751.webp', '#3d6b4f', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","adventure"]', '["nature","forest","trees","plants","herbarium"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('деревья-752', 'DP-0752', 'Деревья', 'Trees', 'Drveće', 'Камилла де ла Бедуайер', 'Camilla de la Bédoyère', 'Camilla de la Bédoyère', '', '', NULL, NULL, 6, 16, 'middle', 'Эта книга рассказывает о лиственных и хвойных Деревьях. Благодаря наглядным иллюстрациям и увлекательным текстам читатель научится распознавать разные виды деревьев, растущих в парках, лесах и садах. Для среднего школьного возраста.', 'This vividly illustrated guide introduces young readers to deciduous and coniferous trees, showing how to identify various species across forests, parks, and gardens.', 'Ova slikovita knjiga vodi mlade čitaoce kroz svijet bjelogoričnog i crnogoričnog drveća, učeći ih kako da lako prepoznaju različite vrste u parkovima, šumama i baštama.', 'Загляните под шелестящие кроны — после этой книги вы будете здороваться с каждым дубом и сосной в Баре по имени!', 'Take a look beneath the leafy canopies — after reading this, you''ll be greeting every pine and oak around Bar by name!', 'Zavirite pod šuštavu krošnju — nakon ove knjige prepoznavaćete svaki bor i hrast tokom šetnje Barom!', '/covers/DP-0752.webp', '#2d6a4f', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real"]', '["trees","nature","botany","forests","plants"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ветер-753', 'DP-0753', 'Ветер', 'Wind', 'Vjetar', '', 'Anna Skowrońska', 'Anna Skovronska', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Как объяснить ребенку то, что нельзя увидеть и потрогать? С помощью книги отправиться в необыкновенное путешествие! Автор доступным языком рассказала практически обо всем, что связано с ветром, а команда дизайнеров красочно и с юмором проиллюстрировала даже самые сложные темы. Где рождается ветер и как превратить его в электричество? Есть ли ветер в космосе?Чем он полезен животным и растениям? Что такое эффект Кориолиса? Стоит ли знакомиться с Дорианом и Катриной, если они — циклоны? Отличное дополнение к урокам окружающего мира. Книга номинирована на премию IBBY «Книга года 2020» в категории «иллюстрации» и премию имени Фердинанда Великолепного в категории «лучшая детская книга». Большой формат. Доступно и наглядно обо всем, что связано с ветром.', 'How do you explain something you can neither see nor touch? By taking a fascinating journey through this book! With clear language and witty, colorful illustrations, it explores everything connected to wind—from how it is born and transformed into clean energy to solar wind in deep space, the Coriolis effect, and fierce hurricanes named Dorian and Katrina. A beautifully illustrated, large-format guide that turns invisible atmospheric wonders into captivating science.', 'Kako djetetu objasniti nešto što se ne može vidjeti niti dodirnuti? Kroz ovu knjigu krenite na uzbudljivo putovanje! Na pristupačan način i uz duhovite, živopisne ilustracije, saznaćete sve o vjetru: gdje se rađa, kako stvara električnu energiju, postoji li vjetar u svemiru, šta je Koriolisov efekat i zašto cikloni nose imena poput Dorijana i Katrine. Prelijepo osmišljena enciklopedija velikog formata koja nevidljive prirodne sile čini jasnim i zabavnim.', 'Захватывающая и остроумная энциклопедия, которая наглядно покажет всё, что выдувает, закручивает и переносит ветер на Земле и даже в космосе!', 'A breezy, witty, and brilliantly illustrated visual guide that makes the invisible power of wind completely unforgettable!', 'Duhovita i raskošno ilustrovana knjiga koja na zabavan način otkriva sve tajne nevidljive snage vjetra!', '/covers/DP-0753.webp', '#5b92b6', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["adventure","real"]', '["nature","weather","science","encyclopedia","ecology"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-работает-маяк--754', 'DP-0754', 'Как работает маяк?', 'How Does a Lighthouse Work?', 'Kako radi svjetionik?', 'Роман Беляев', 'Roman Belyaev', 'Roman Beljajev', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Маяки — одни из самых древних инженерных сооружений на земле. За многие тысячелетия, что маяки помогают кораблям преодолевать опасности и находить правильный путь в море, они из архитектурных сооружений превратились в настоящие символы надежды. О маяках пишут стихи, песни, их рисуют художники. И все, взрослые и дети, мечтают побывать хотя бы раз на настоящем маяке, чтобы узнать, как он работает. Художник и дизайнер Роман Беляев, с детства неравнодушный к разным особенным инженерным сооружениям, придумал и создал удивительную серию про самые интересные изобретения человека в области инженерного строительства. Книга «Как работает маяк» открывает серию, в которую войдут позже истории мостов, мельниц и других необыкновенных сооружений.', 'Lighthouses are among the oldest and most fascinating engineering wonders on Earth, guiding ships safely through raging storms and standing as enduring beacons of hope. Artist and designer Roman Belyaev explores the secrets of these solitary towers: how they are constructed on wave-battered rocks, how their powerful lenses pierce the thickest fog, and what daily life looks like for a lighthouse keeper.', 'Svjetionici su među najstarijim i najfascinantnijim inženjerskim čudima na svijetu, vodeći brodove kroz oluje i služeći kao vječni simboli nade. Umjetnik i dizajner Roman Beljajev otkriva tajne ovih usamljenih kula: kako se grade na hridima koje zapljuskuju talasi, kako njihova sočiva probijaju najgušću maglu i kako izgleda svakodnevni život svjetioničara.', 'Загляните внутрь самого романтичного и отважного стража морей — после этой книги вам точно захочется стать смотрителем маяка!', 'Peek inside the world''s most romantic and resilient sea sentinels—after this book, you might just dream of becoming a lighthouse keeper!', 'Zavirite u unutrašnjost najhrabrijih morskih stražara — poslije ove knjige poželjećete da i sami postanete svjetioničar!', '/covers/DP-0754.webp', '#1d3557', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","adventure"]', '["маяки","море","инженерия","архитектура","научпоп"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('история-велосипеда-быстрые-ног-755', 'DP-0755', 'История велосипеда. Быстрые ноги', 'The History of the Bicycle: Swift Feet', 'Istorija bicikla: Brze noge', 'Фомин Владимир, Попова Виктория', 'Vladimir Fomin, Viktoriya Popova', 'Vladimir Fomin, Viktorija Popova', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'С велосипедом многие из нас знакомы с детства. На нем ездят на работу и возят грузы, ставят рекорды и совершают кругосветные путешествия. Велосипедиста можно встретить практически везде. В некоторых странах велосипедов больше, чем людей. Он настолько привычен, что мы редко задумываемся о том, как и когда он был изобретен. Между тем это сравнительно недавнее изобретение — хорошая иллюстрация технологического прогресса последних столетий и в какой-то степени один из двигателей этого прогресса. Внешне простой, велосипед собрал в себе самые передовые технические достижения — от вулканизированной резины и шарикового подшипника до углепластика и компьютерного моделирования аэродинамики. Каждый раз, глядя на велосипед, мы восхищаемся его изящной простотой, за которой, если присмотреться, видны плоды трудов огромного количества людей. В этой книге приводится краткий, но яркий рассказ об истории велосипеда, его эволюции, влиянии на общество и основных элементах его конструкции. История велосипеда — это рассказ о самых передовых достижениях техники, о революции в умах и изменении облика городов.', 'Most of us have known bicycles since childhood—we commute, haul cargo, break records, and journey around the globe on two wheels. Yet we rarely wonder how and when this brilliant contraption was invented. Bicycles embody centuries of cutting-edge technological progress: from vulcanized rubber and ball bearings to carbon fiber and computer-modeled aerodynamics. This vibrant, beautifully illustrated book tells the fascinating story of the bicycle''s evolution, its impact on society, and the ingenious engineering behind its elegant simplicity.', 'Većina nas vozi bicikl još od djetinjstva — na njemu idemo na posao, prevozimo teret, obaramo rekorde i putujemo oko svijeta. Ipak, rijetko razmišljamo o tome kako je i kada nastao ovaj genijalni izum. Bicikl u sebi spaja vjekove tehnološkog napretka: od vulkanizovane gume i kugličnih ležajeva do ugljeničnih vlakana i aerodinamičkog dizajna. Ova dinamična i bogato ilustrovana knjiga otkriva uzbudljivu priču o evoluciji dvotočkaša, njegovom uticaju na društvo i inženjerskim tajnama koje stoje iza njegove jednostavnosti.', 'Оседлайте педали сквозь века: узнайте, как деревянная «машина для бега» перевернула весь мир и подарила нам чистую радость скорости!', 'Pedal back through time and discover how a quirky wooden running machine sparked a worldwide revolution of two-wheeled speed!', 'Zavrtite pedale kroz vjekove i saznajte kako je obična drvena sprava pokrenula revoluciju i osvojila čitavu planetu!', '/covers/DP-0755.webp', '#2d757d', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","adventure"]', '["bicycles","inventions","transport","history","engineering"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('book-756', 'DP-0756', '', 'The History of the Telephone', 'Istorija telefona', '', 'Unknown', 'Nepoznati autor', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', '«Забыл дома телефон» сегодня звучит как приговор. В смартфонах сосредоточена вся наша жизнь. Вызвать такси, расплатиться в магазине, послушать любимую музыку, почитать новости и, конечно, договориться о встрече – все это можно сделать нажатием пары кнопок. Трудно поверить, но таким телефон был не всегда. Еще каких-нибудь двадцать лет назад по мобильному телефону можно было только разговаривать и обмениваться короткими сообщениями. Пятьдесят лет назад домашний (стационарный) телефон был единственным средством связи, но и он стоял не в каждой квартире, и приходилось бегать к таксофону в соседний квартал. А было время, когда люди жили вообще без телефона. Как же тогда они общались друг с другом? И кто придумал устройства, передающие звук? В этой книге история средств связи от Древнего Рима до наших дней. Она ставит перед читателями множество интересных вопросов, благодаря которым можно наблюдать, как в диалоге между учёными разных стран и эпох развивалась наука и техника. Какие изобретения прошлого лежат в основе современной техники? Как помогли телеграфу «точки» и «тире»? Зачем телефонной трубке угольный порошок? Что изменилось благодаря радио? И как удалось перейти от аналога к цифре? А ещё из «Истории телефона» вы узнаете про секретный семафор Наполеона, радио на борту «Титаника», кабель на дне океана и взлом телефонной сети с помощью свистульки.', 'Today, leaving your smartphone at home feels like a disaster, but communication wasn''t always this simple! Journey through the history of telecommunications from ancient messenger networks and Napoleon''s secret optical semaphore to underwater ocean cables, the Titanic''s wireless radio, and modern digital networks. Discover the clever scientists, forgotten gadgets, and quirky technological breakthroughs that paved the way for the tiny supercomputers we carry in our pockets today.', 'Danas zaboraviti telefon kod kuće zvuči kao prava propast, ali komunikacija nije oduvijek bila jednostavna! Krenite na putovanje kroz istoriju telekomunikacija — od antičkih glasnika i Napoleonovog optičkog semafora, do podvodnih okeanskih kablova, radija na Titaniku i savremenih digitalnih mreža. Saznajte koji su genijalni izumi i neobični tehnološki preokreti omogućili da danas u džepu nosimo čitav svijet.', 'Загляните под корпус привычного смартфона и узнайте, как свистулька могла взломать телефонную сеть, а кабель на дне океана соединил континенты!', 'Peek behind the screen of your smartphone to discover how ocean-floor cables connected continents and a toy whistle once hacked a phone network!', 'Zavirite iza ekrana pametnog telefona i otkrijte kako su kablovi na dnu okeana povezali kontinente, a obična pištaljka uspjela da hakuje telefonsku mrežu!', '/covers/DP-0756.webp', '#1d6388', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real","adventure"]', '["telephone","technology","inventions","history","science","gadgets"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кибер-без-опасности-757', 'DP-0757', 'Кибер без опасности', 'Cyber Without Danger', 'Sajber bez opasnosti', 'Юрий Тихоглаз', 'Yuri Tikhoglaz', 'Jurij Tihoglaz', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', '«Шпион, который всегда с тобой», — так называют смартфон. Действительно, в умелых руках злонамеренного человека твой телефон и компьютер могут превратиться в мощную угрозу твоей личной безопасности. К счастью, риск можно сократить, если знать, откуда может прийти угроза, и соблюдать определенные правила. Автор этой книги — специалист в области компьютерной криминалистики — рассказывает о том, кто такие хакеры и зачем им разноцветные шляпы, приводит примеры известных хакеров, описывает основные угрозы, с которыми может столкнуться любой обладатель мобильного телефона или аккаунта в социальной сети. Но главное — он говорит о том, какие конкретные шаги нужно предпринять и какие правила соблюдать, чтобы не оказаться объектом высмеивания в Сети, чтобы не лишиться доступа к собственной электронной почте или денег с банковской карточки. Прочитав эту книгу, начинающий компьютерный пользователь сможет обезопасить себя. А еще из книги можно узнать, что хакеры — не обязательно злодеи, а также чем занимаются компьютерные криминалисты.', 'They say a smartphone is a spy you carry in your pocket—and in careless hands, your gadget can turn into a serious security risk. Written by a computer forensics expert, this handbook decodes the world of hackers, breaks down real digital threats, and equips young users with practical rules for online life. Learn how to protect your passwords, dodge online bullies, keep bank cards secure, and discover why not all hackers wear black hats.', 'Kažu da je pametni telefon špijun kog uvijek nosimo sa sobom — i u neopreznim rukama može postati stvarna prijetnja ličnoj bezbjednosti. Ovu knjigu napisao je stručnjak za kompjutersku forenziku kako bi mladim korisnicima objasnio ko su zapravo hakeri, kako prepoznati zamke na mrežama i zaštititi svoje naloge, lozinke i podatke. Uz jednostavna pravila i primjere iz stvarnog života, internet postaje bezbjedno i zabavno mjesto za istraživanje.', 'Превратите смартфон из карманного шпиона в надёжного союзника с помощью советов настоящего цифрового детектива!', 'Turn your smartphone from a sneaky double agent into your safest digital ally with expert tips from a real cyber detective!', 'Pretvorite svoj telefon iz lukavog špijuna u vjernog saveznika uz super savjete pravog digitalnog detektiva!', '/covers/DP-0757.webp', '#1d6b8a', 'nonfiction', 'ru', 'available', 'Категория: про природу', '["real"]', '["cybersecurity","internet safety","hackers","digital literacy","gadgets"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тысяча-лиц-энергии-758', 'DP-0758', 'Тысяча лиц энергии', 'A Thousand Faces of Energy', 'Hiljadu lica energije', 'Роман Фишман', 'Roman Fishman', 'Roman Fišman', 'Алина Рубан', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Энергии трудно дать определение. Это не вещество, не субстанция, не жидкость и не газ. Но что бы мы ни делали, мы постоянно ее расходуем. Причем не только тогда, когда включаем компьютер или едем на автомобиле, но и когда думаем или просто лежим на диване. Поэтому вопрос, откуда энергию взять, — вечный. Но кроме этого вопроса, возникает и множество других. Откуда берется электричество и как попадает к нам в дом? Можно ли жить без проводов? Как использовать энергию молнии? Почему качели качаются, а рогатки еще двести лет назад просто не существовали? Если тебе интересно об этом узнать — эта книга для тебя. И помни, вопросы — тот самый шаг, с которого начинается путь науки. Книга «Тысяча лиц энергии» выпущена при поддержке нашего постоянного партнера — Политехнического музея.', 'Energy is tricky to define: it is not a substance, not a liquid, and not a gas. Yet whatever we do, we constantly consume it — not only when powering up a computer or driving a car, but even while pondering or lounging on the couch. Where does energy come from, how does electricity reach our homes, and can we harness lightning? Created with the Polytechnic Museum, this engaging science book proves that curious questions are where the grand journey of science begins.', 'Energiju je teško definisati: ona nije materija, tečnost ili gas. Pa ipak, šta god radili, neprestano je trošimo — ne samo kad uključujemo računar ili vozimo automobil, već i dok razmišljamo ili prosto ležimo na kauču. Odakle energija dolazi, kako struja stiže u naš dom i možemo li ukrotiti munju? Stvorena u saradnji sa Politehničkim muzejom, ova uzbudljiva knjiga dokazuje da velika nauka počinje upravo radoznalim pitanjima.', 'Заряжающая научная книга, которая докажет, сколько чистой физики скрывается даже в самом ленивом отдыхе на диване!', 'An energizing science read proving that even lounging on the couch requires a surprising spark of real physics!', 'Prava energetska bomba od knjige koja dokazuje koliko se fizike krije čak i u najljenijem odmaranju na kauču!', '/covers/DP-0758.webp', '#f5a623', 'nonfiction', 'ru', 'available', 'новое в библиотеке', '["real"]', '["energy","physics","science","electricity","nonfiction"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-приготовить-пирог-из-цифр-759', 'DP-0759', 'Как приготовить пирог из цифр', 'How to Bake a Pie of Numbers', 'Kako napraviti pitu od brojeva', 'Наталья Крупенина', 'Natalia Krupenina', 'Natalija Krupenjina', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Что такое информация и чем она отличается от данных? Как благодаря данным учёные совершают открытия, а врачи ставят диагнозы? Как сайты решают, какой мультфильм нам посоветовать? И какое отношение ко всему этому имеют пироги, облака и водопады? Наконец-то появилась книга, в которой об информации и данных рассказывается интересно и просто — так, что будет понятно и детям и взрослым.', 'What is information, and how is it different from raw data? How do numbers help scientists make breakthroughs and doctors save lives? How do streaming services know which cartoon you will love next, and what on earth do pies, clouds, and waterfalls have to do with it? This brilliant guide unpacks big data and computer science in a way that is utterly tasty, clear, and fascinating for both curious kids and their parents.', 'Šta je informacija i po čemu se razlikuje od podataka? Kako zahvaljujući podacima naučnici dolaze do velikih otkrića, a ljekari postavljaju dijagnoze? Kako veb-sajtovi biraju koji crtani film da nam preporuče? I kakve veze sa svim tim imaju pite, oblaci i vodopadi? Pred vama je knjiga koja o podacima i informacijama govori zabavno i jednostavno — razumljivo i djeci i odraslima.', 'Оказывается, из терабайтов данных можно испечь вкуснейший пирог знаний и легко понять, как устроен цифровой мир вокруг нас!', 'Turns out you can bake a delicious pie out of gigabytes of data and finally discover how algorithms quietly run our world!', 'Ispostavlja se da se od silnih podataka može ispeći najukusnija pita znanja i shvatiti kako zapravo funkcioniše digitalni svijet!', '/covers/DP-0759.webp', '#e06d53', 'nonfiction', 'ru', 'available', 'Категория: библиотека карманного ученого', '["real","funny"]', '["data","science","technology","math","algorithms"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-несъедобное-становится-съе-760', 'DP-0760', 'Как несъедобное становится съедобным', 'How the Inedible Becomes Edible', 'Kako nejestivo postaje jestivo', 'Тим Скоренко', 'Tim Skorenko', 'Tim Skorenko', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Что происходит, когда популяризатор науки и кулинар встречаются на одной кухне? Она превращается в химическую лабораторию! Почему, если сварить картошку, она станет мягкой? А яйцо, наоборот, затвердеет? Почему мясо шипит на сковородке? И, кстати, почему нельзя всё есть сырым? Удивительные превращения, секретные ингредиенты и всевозможные методы обработки продуктов станут известны тем, кто прочтёт эту книгу, созданную в сотрудничестве с экспертами Политехнического музея.', 'What happens when a science communicator and a chef meet in the same kitchen? It turns into a real chemistry laboratory! Why does boiling a potato make it soft, while an egg turns hard? Why does meat sizzle in a hot pan, and why can''t we just eat everything raw? Readers will discover fascinating culinary transformations, secret kitchen reactions, and ingenious food processing methods in this engaging science guide created with experts from the Polytechnic Museum.', 'Šta se dešava kada se naučnik i kuvar sretnu u istoj kuhinji? Ona se pretvara u pravu hemijsku laboratoriju! Zašto kuvani krompir omekša, a jaje otvrdne? Zašto meso cvrči u tiganju i zašto zapravo ne možemo sve da jedemo sirovo? Nevjerovatne transformacije, tajni kulinarski procesi i naučne metode pripreme hrane čekaju radoznale čitaoce u ovoj zabavnoj knjizi stvorenoj u saradnji sa stručnjacima Politehničkog muzeja.', 'Превращаем обычную кухню в секретную лабораторию: теперь каждая кастрюля с супом станет захватывающим научным экспериментом!', 'Turn your everyday kitchen into a secret lab where every boiling pot of soup is an exciting science experiment!', 'Pretvorite običnu kuhinju u tajnu laboratoriju u kojoj svaki lonac supe postaje uzbudljiv naučni eksperiment!', '/covers/DP-0760.webp', '#d96b27', 'nonfiction', 'ru', 'available', 'Категория: библиотека карманного ученого', '["real","funny"]', '["food science","cooking","chemistry","experiments","curiosity"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('почему-бриллианты-дороже-воды--761', 'DP-0761', 'Почему бриллианты дороже воды? и еще 47 вопросов про экономику', 'Why Are Diamonds More Expensive than Water? And 47 More Questions About Economics', 'Zašto su dijamanti skuplji od vode? I još 47 pitanja o ekonomiji', 'Мария Бойко', 'Maria Boyko', 'Marija Bojko', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Как устроены экономические отношения в обществе? Что такое рынок и какие у него законы? Почему одни страны богатые, а другие бедные? В книге Марии Бойко эти и многие другие вопросы объясняются интересно и просто — так, что становится понятно и детям, и взрослым.', 'How do economic relations work in society? What is a market and what rules does it follow? Why are some countries rich while others are poor? In Maria Boyko''s book, these and many other questions are explained clearly and engagingly, making economics accessible and fascinating to children and adults alike.', 'Kako funkcionišu ekonomski odnosi u društvu? Šta je to tržište i koja su njegova pravila? Zašto su neke zemlje bogate, a druge siromašne? U knjizi Marije Bojko ova i mnoga druga pitanja objašnjena su zanimljivo i jednostavno — tako da postaju jasna i djeci i odraslima.', 'Остроумный и ясный путеводитель по миру денег и рыночных законов, который ответит даже на самые заковыристые финансовые вопросы!', 'A witty and crystal-clear guide to the world of money and markets that tackles even the trickiest financial questions with ease!', 'Duhovit i kristalno jasan vodič kroz svijet novca i tržišnih zakona koji s lakoćom odgovara i na najzamršenija ekonomska pitanja!', '/covers/DP-0761.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: библиотека карманного ученого', '["real"]', '["economics","money","nonfiction","society","curiosity"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('политика-то-о-чем-взрослые-теб-762', 'DP-0762', 'Политика. То, о чем взрослые тебе не говорят', 'Politics: What Grown-Ups Don''t Tell You', 'Politika: Ono o čemu ti odrasli ne govore', 'Автор книги Богусь Янишевский – известный польский популяризатор науки – умеет простыми словами рассказывать детям про такие важные и непростые вещи.', 'Boguś Janiszewski', 'Boguś Janiszewski', 'Его дуэт с иллюстратором Максом Скорвидером', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Сложно представить себе современного ребенка, который бы хоть раз не поинтересовался: кто такой президент? Что такое налоги? Почему в стране постоянно кого-то выбирают? И вообще зачем вся эта политика? Родителям порой трудно ответить на подобные вопросы кратко и емко. Политика – это одна из тех тем, про которые родители не разговаривают с детьми, потому что – как справедливо отмечает автор – часто и сами в ней не разбираются. Великолепный образец современного подхода к обучению, в котором нет места сухим формулировкам, зато полно живых примеров и классного визуального материала.', 'Who is the president, where do taxes go, and why are elections constantly happening? Grown-ups often dodge these questions simply because they find politics confusing themselves! This witty, visually packed non-fiction guide ditches dry definitions and breaks down government, power, and society through hilarious comics and real-world examples.', 'Ko je zapravo predsjednik, gdje odlazi porez i zašto se stalno neko bira? Odrasli često izbjegavaju ove teme jer se, ruku na srce, ni sami u njih previše ne razumiju. Ovaj duhoviti i vizuelno dinamični vodič zaobilazi suve udžbeničke fraze i kroz zabavne ilustracije jednostavno objašnjava kako funkcionišu država, vlast i društvo.', 'Наконец-то книга, которая честно и с юмором разложит по полочкам всё про выборы и налоги — даже если сами взрослые окончательно запутались!', 'Finally, a hilarious and honest guide that cracks the code on elections and taxes—even when grown-ups are completely stumped!', 'Konačno knjiga koja iskreno i duhovito objašnjava izbore i poreze — čak i onda kada su odrasli potpuno zbunjeni!', '/covers/DP-0762.webp', '#e8a825', 'nonfiction', 'ru', 'available', 'Категория: библиотека карманного ученого', '["real","funny"]', '["politics","nonfiction","society","citizenship","humor"]', 1792836322699, 1792845677483);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('экономика-то-о-чем-взрослые-те-763', 'DP-0763', 'Экономика. То, о чем взрослые тебе не рассказывают', 'Economics: What Grown-Ups Don''t Tell You', 'Ekonomija: Ono o čemu ti odrasli ne govore', '', 'Boguś Janiszewski', 'Boguś Janiszewski', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Все, что образованному человеку любого возраста нужно знать об экономике, вы найдете в этой книге. Кто платит бабушке и дедушке пенсию? Что такое банк и зачем он дает кредиты? Где прячутся налоги? Как формируется бюджет государства? И даже – как спасти экономику от кризиса? Экономика – это одна из тех тем, которые родители не обсуждают с детьми, потому что – как справедливо отмечает автор – часто и сами не разбираются. Автор книги Богусь Янишевский – известный польский популяризатор науки – умеет простыми словами рассказывать детям про такие, казалось бы, сложные вещи. Его дуэт с иллюстратором Максом Скорвидером – великолепный образец современного подхода к обучению, в котором нет места сухим формулировкам, зато полно живых примеров и классного визуального материала. Они доказали: с детьми можно и нужно говорить о финансах, ведь они однажды вырастут и получат возможность влиять на будущее нашей страны.', 'Everything an educated person of any age needs to know about economics is packed right into this book. Who pays grandma and grandpa''s pension? What is a bank, and why does it issue loans? Where do taxes hide? How does a state budget work, and how can we rescue an economy in crisis? Economics is often swept under the rug by parents because, let''s be honest, they rarely understand it fully themselves! Polish science popularizer Boguś Janiszewski and illustrator Max Skorwider break down complicated financial concepts with humor, relatable examples, and lively comic-style illustrations, proving that talking to kids about money can be both fun and empowering.', 'Sve što obrazovana osoba bilo kog uzrasta treba da zna o ekonomiji sabrano je u ovoj knjizi. Ko isplaćuje penziju baki i deki? Šta je banka i zašto daje kredite? Gdje se kriju porezi, kako se stvara državni budžet i kako spasiti privredu od krize? Ekonomija je tema o kojoj roditelji rijetko razgovaraju s djecom jer je često ni sami do kraja ne razumiju. Poljski popularizator nauke Boguš Janiševski i ilustrator Maks Skorvider jednostavnim jezikom, duhovitim primjerima i sjajnim strip-crtežima razbijaju komplikovane finansijske pojmove, dokazujući da razgovor o novcu može biti lak i nevjerovatno zabavan.', 'Остроумный и честный путеводитель по миру денег, налогов и кризисов, в котором даже взрослые наконец-то разберутся, как устроена экономика!', 'A witty and wonderfully honest guide to money, taxes, and inflation that finally explains how the economy works—even to the grown-ups!', 'Duhovit i iskren vodič kroz svijet novca, poreza i inflacije uz koji će napokon i odrasli shvatiti kako zapravo funkcioniše ekonomija!', '/covers/DP-0763.webp', '#f2a900', 'nonfiction', 'ru', 'available', 'Категория: библиотека карманного ученого', '["real","funny"]', '["economics","money","nonfiction","financial literacy","comics"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('луи-пастер-ученый-детектив-764', 'DP-0764', 'Луи Пастер Ученый-детектив', 'Louis Pasteur: Scientist Detective', 'Luj Paster: Naučnik detektiv', 'Флоранс Пино', 'Florence Pinaud', 'Florens Pino', 'Жюльен Билодо', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Наука XIX века — настоящее приключение. Физики и химики пытаются понять, из чего состоит материя, биологи уже знают, что существуют крошечные организмы, но еще не понимают, что это такое, а работа в лаборатории скорее напоминает домашние опыты. В это время Луи Пастер совершает свои удивительные открытия: обнаруживает микроорганизмы, от которых портится вино и гибнет шелкопряд, доказывает, что жизнь не может зародиться «из ничего», изобретает вакцину от бешенства... И каждая новая задача — как детективное расследование. Книга получила специальный приз Bologna Ragazzi Award в категории Non/fiction на престижной Болонской детской книжной ярмарке.', 'Nineteenth-century science was a thrilling adventure. Physicists and chemists were untangling the secrets of matter, biologists knew tiny organisms existed without fully understanding them, and laboratory work looked like wild kitchen experiments. Amidst this curiosity, Louis Pasteur made groundbreaking discoveries: identifying the microbes spoiling wine, saving silkworms, proving life doesn''t appear out of thin air, and developing the rabies vaccine. Every mystery was solved like a true detective case! Winner of the prestigious Bologna Ragazzi Award in the Non-Fiction category.', 'Nauka devetnaestog vijeka bila je prava uzbudljiva avantura. Dok su fizičari i hemičari odgonetali tajne materije, a rad u laboratoriji ličio na kućne eksperimente, Luj Paster je pravio revolucionarna otkrića. Pronašao je mikrobe koji kvare vino i uništavaju svilene bube, dokazao da život ne nastaje »ni iz čega« i stvorio vakcinu protiv bjesnila. Svaki njegov naučni izazov bio je poput napete detektivske istrage! Knjiga je nagrađena prestižnim priznanjem Bologna Ragazzi Award.', 'Приготовьте лупы и пробирки: вас ждёт захватывающее научное расследование, где микробы — главные подозреваемые!', 'Grab your magnifying glasses and flasks: get ready for a gripping scientific investigation where elusive microbes are the prime suspects!', 'Pripremite lupe i epruvete: čeka vas prava naučna istraga u kojoj su neuhvatljivi mikrobi glavni osumnjičeni!', '/covers/DP-0764.webp', '#3a7d84', 'nonfiction', 'ru', 'available', 'Категория: про учёных', '["adventure","real"]', '["наука","биография","история","медицина","открытия"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чарлз-дарвин-революция-765', 'DP-0765', 'Чарлз Дарвин Революция', 'Charles Darwin: A Revolution', 'Čarls Darvin: Revolucija', 'Анабель Крамер', 'Annabelle Kremer', 'Anabel Kremer', 'Франсуа Олислеже', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Это не просто рассказ о подробностях жизни великого Чарлза Дарвина — эта книга помогает понять, как мыслит ученый. Каким образом из хаоса информации, обрушившейся на него во время кругосветного путешествия на корабле «Бигль», молодой натуралист смог извлечь закономерности и построить на них теорию, которая стала основополагающей для современной науки? Давайте взглянем на мир глазами Чарлза Дарвин и проследим за ходом его мысли.', 'This is more than just a biography of the great Charles Darwin—it is an inspiring dive into how a scientist actually thinks. How did a young naturalist transform the overwhelming whirlwind of observations gathered aboard the HMS Beagle into the groundbreaking theory that shaped modern biology? Step inside Darwin''s world and follow the thrilling journey of a brilliant mind.', 'Ovo nije samo priča o životu Čarlsa Darvina — ova knjiga nam pomaže da shvatimo kako naučnik razmišlja. Kako je mladi prirodnjak iz bujice zapažanja tokom plovidbe brodom „Bigl” uspio da uoči skrivene zakonitosti i izgradi teoriju koja je promijenila modernu nauku? Pogledajte svijet Darvinovim očima i pratite tragove njegovih revolucionarnih otkrića.', 'Хотите узнать, как кругосветка на деревянном паруснике и горстка галапагосских вьюрков навсегда перевернули научный мир?', 'Hop aboard the Beagle to find out how one curious young observer with a notebook changed the way we understand life on Earth forever!', 'Ukrcajte se na brod „Bigl” i otkrijte kako je jedan radoznali mladić sa bilježnicom zauvijek promijenio naš pogled na živi svijet!', '/covers/DP-0765.webp', '#3d5e48', 'nonfiction', 'ru', 'available', 'Категория: про учёных', '["real","adventure","animals"]', '["science","evolution","charles darwin","biology","nature"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('магистр-рассеянных-наук-766', 'DP-0766', 'Магистр рассеянных наук', 'Master of Scatterbrained Sciences', 'Magistar rasijanih nauka', 'Владимир Лёвшин', 'Vladimir Lyovshin', 'Vladimir Ljovšin', '', 'ИД Мещерякова', NULL, NULL, 6, 16, 'middle', 'Герои этой книги носятся по всему белому свету в поисках приключений: плывут по океану, катаются на льдине, гуляют по краю кратера вулкана. Они знают, как заставить Черепаху и Гепарда бежать, не обгоняя друг друга, почему пятиконечную звезду древние называли золотой, а также умеют подобрать математический ключ к любому фруктовому магазину. С помощью участников Клуба Рассеянного Магистра читатель мгновенно запоминает правила и парадоксы самой точной в мире науки.', 'The characters of this book travel all around the world in search of adventure: sailing across oceans, drifting on ice floes, and strolling along the rims of active volcanoes. They know how to make a Tortoise and a Cheetah race without overtaking each other, why the ancients called the five-pointed star golden, and how to crack the mathematical code to any fruit shop. With the help of the Absent-Minded Master''s Club, readers effortlessly discover the secrets, tricks, and paradoxes of the world''s most exact science.', 'Junaci ove knjige jure širom svijeta u potrazi za avanturom: plove okeanom, voze se na santi leda i šetaju ivicom kratera vulkana. Oni znaju kako da natjeraju Kornjaču i Geparda da trče bez preticanja, zašto su drevni narodi petokraku zvijezdu zvali zlatnom i kako pronaći matematički ključ za svaku voćarnu. Uz članove Kluba Rasijanog Magistra, čitaoci s lakoćom savladavaju pravila i paradokse najtačnije nauke na svijetu.', 'Докажет даже самым убеждённым гуманитариям, что математика — это невероятно весёлое кругосветное путешествие с головоломками!', 'Proves even to the most devoted daydreamers that math is actually a thrilling, hilarious globe-trotting adventure full of puzzles!', 'Dokazaće čak i najvećim sanjarima da je matematika zapravo uzbudljiva i duhovita avantura oko svijeta puna zagonetki!', '/covers/DP-0766.webp', '#2b6b88', 'nonfiction', 'ru', 'available', 'Категория: про учёных', '["funny","adventure"]', '["math","puzzles","science","humor","adventures"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('занимательная-физика-767', 'DP-0767', 'Занимательная физика', 'Physics for Entertainment', 'Zanimljiva fizika', 'Я. И. Перельман', 'Yakov Perelman', 'Jakov Perelman', '', 'АСТ', NULL, NULL, 6, 16, 'middle', 'Одно из лучших классических пособий по физике. Хитрые головоломки, замысловатые вопросы, забавные задачи и парадоксы заинтересуют и помогут успешно освоить физику.', 'One of the greatest science classics ever written. Packed with clever brainteasers, intriguing questions, entertaining problems, and paradoxical phenomena, this book turns learning physics into an irresistible adventure.', 'Jedan od najboljih klasičnih priručnika iz fizike. Lukave zagonetke, neobična pitanja, zabavni zadaci i paradoksi zainteresovaće svakog mladog istraživača i pomoći mu da s lakoćom savlada zakone prirode.', 'Физика вокруг нас полна чудес, и Перельман виртуозно доказывает, что наука может быть увлекательнее любого детектива!', 'Physics is full of mind-bending wonders, and Perelman brilliantly proves that science is more thrilling than any detective story!', 'Fizika oko nas puna je pravih čuda, a Perelman majstorski dokazuje da nauka može biti uzbudljivija od svakog detektivskog romana!', '/covers/DP-0767.webp', '#1b4965', 'nonfiction', 'ru', 'available', 'Категория: про учёных', '["real"]', '["physics","science","riddles","experiments","nonfiction"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('занимательная-механика-768', 'DP-0768', 'Занимательная механика', 'Entertaining Mechanics', 'Zanimljiva mehanika', 'Я. И. Перельман', 'Yakov Perelman', 'Jakov Pereljman', '', 'АСТ', 2022, '978-5-17-147856-8', 6, 16, 'middle', 'Почему человеку, сидящему в поезде, кажется, что поезд стоит на месте, а движется перрон? Если ударить яйцом о яйцо, какое из них разобьется первым? О чем спорили Коперник и Птолемей? Каков принцип действия аэродинамической трубы?.. Теория относительности и инерция, действие и противодействие и многое, многое другое из области прикладной и теоретической механики — вот о чем в простой, увлекательной и доступной форме, с помощью наглядных примеров из жизни, рассказывается в книге Якова Перельмана "Занимательная механика".', 'Why does a passenger on a train feel like the train is standing still while the platform moves? If you smash two eggs together, which one cracks first? What did Copernicus and Ptolemy argue about? Through simple everyday puzzles, brilliant paradoxes, and vivid examples, legendary science popularizer Yakov Perelman makes the fundamental laws of motion, inertia, and mechanics delightfully clear and utterly fascinating.', 'Zašto putniku u vozu izgleda kao da voz stoji, a peron se kreće? Ako udarite jaje o jaje, koje će prvo pući? Kroz jednostavne svakodnevne zagonetke, neobične eksperimente i slikovite primjere, legendarni autor Jakov Pereljman pretvara osnovne zakone kretanja, inercije i mehanike u pravu naučnu pustolovinu.', 'Хотите щелкать законы физики как орешки и узнать, почему не падает волчок и летают ракеты? Эта легендарная книга объяснит механику увлекательнее любого учебника!', 'Want to crack the laws of physics with ease and discover why spinning tops stay upright and rockets fly? This timeless classic makes mechanics endlessly fun!', 'Želite li s lakoćom savladati zakone fizike i saznati zašto čigra ne pada? Ovaj bezvremenski klasik objašnjava svijet mehanike bolje od bilo kog udžbenika!', '/covers/DP-0768.webp', '#235789', 'nonfiction', 'ru', 'available', 'Категория: про учёных', '["real","adventure"]', '["physics","science","experiments","mechanics","stem"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('101-головоломка-769', 'DP-0769', '101 головоломка', '101 Puzzles', '101 mozgalica', 'Я. И. Перельман', 'Yakov Perelman', 'Jakov Pereljman', '', 'АСТ', NULL, NULL, 6, 16, 'middle', 'Сотня увлекательных головоломок для юных математиков. Это непростые, но интересные задачи научат логически рассуждать и нестандартно мыслить.', 'A collection of captivating brainteasers for young mathematicians. These tricky yet engaging problems train sharp logic, curiosity, and creative out-of-the-box thinking.', 'Zbirka uzbudljivih mozgalica za mlade matematičare. Ovi izazovni, ali zabavni zadaci podstiču logičko razmišljanje i kreativno rješavanje problema.', 'Настоящая зарядка для ума от легендарного классика занимательной науки — пощекочите извилины всей семьёй!', 'The ultimate brain workout from the master of playful science—get ready to flex those mental muscles together as a family!', 'Prava gimnastika za mozak od legendarnog majstora zabavne nauke — razmrdajte vijuge zajedno sa cijelom porodicom!', '/covers/DP-0769.webp', '#2a6f97', 'nonfiction', 'ru', 'available', 'Категория: про учёных', '["real"]', '["puzzles","math","logic","brainteasers","nonfiction"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большое-путешествие-по-телу-че-770', 'DP-0770', 'Большое путешествие по телу человека', 'The Great Journey Through the Human Body', 'Veliko putovanje kroz ljudsko tijelo', 'Джон Фарндон', 'John Farndon', 'Džon Farndon', 'Джон Фарндон', 'Лабиринт', NULL, NULL, 6, 16, 'middle', 'В этой книге подробно, наглядно и невероятно увлекательно рассказано о том, как устроен и как работает человеческий организм. Из чего состоит наше тело, что такое клетки, ткани и органы? Как работают мышцы, нервы и гормоны? Для чего нужны вода и еда и что с ними происходит в организме человека? Почему мы болеем и как выздоравливаем, как распознаем запахи и вкусы? Как мы думаем? Почему мы похожи на своих родителей? Подробный ответ на каждый вопрос разбит на удобные блоки и проиллюстрирован так, что становится ясно не только как устроено человеческое тело, но и как именно происходят в нем все жизненные процессы. Современная и оригинальная по замыслу и исполнению научно-популярная книга написана известным британским писателем Джоном Фарндоном, лауреатом книжных премий в США и Великобритании. Для детей 8-12 лет.', 'This richly illustrated and engaging book takes young readers on a tour of the human body. Discover how cells, muscles, hormones, and nerves work together, what happens to food and water inside us, why we get sick and heal, and even why we look like our parents. Divided into clear, easy-to-digest sections, it brings complex biology to life with vibrant infographics by award-winning science author John Farndon.', 'Ova bogato ilustrovana i uzbudljiva knjiga vodi mlade čitaoce na fascinantno putovanje kroz ljudski organizam. Otkrijte kako funkcionišu ćelije, mišići, nervi i hormoni, šta se u tijelu dešava s hranom i vodom, zašto se razbolijevamo i kako ozdravljamo, pa čak i zašto ličimo na svoje roditelje. Uz jasne cjeline i sjajne ilustracije, ova knjiga čini biologiju zabavnom i razumljivom svima.', 'Приготовьтесь к захватывающей экскурсии внутрь самих себя — от макушки до кончиков пальцев!', 'Get ready for a thrilling expedition inside yourself, exploring every wondrous gear and gadget from head to toe!', 'Spremite se za nevjerovatnu ekspediciju unutar sopstvenog tijela — od glave pa sve do pete!', '/covers/DP-0770.webp', '#d64541', 'nonfiction', 'ru', 'available', 'Категория: анатомия', '["adventure","real"]', '["human body","anatomy","biology","science","encyclopedia"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайны-анатомии-771', 'DP-0771', 'Тайны анатомии', 'The Magic Anatomy Book', 'Tajne anatomije', 'Кэрол Доннер', 'Carol Donner', 'Kerol Doner', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Как устроено мое собственное тело? Почему желудок не пожирает сам себя? Зачем нужна иммунная система? Макс и Молли, герои книги "Тайны анатомии", как и все дети, задаются этими вопросами. Только в отличие от обычных детей из реального мира, читающих энциклопедии, расспрашивающих родителей и учителей, с Максом и Молли случилась невероятная история. Как-то на бабушкином чердаке они нашли старую книгу об анатомии человека, и как только они открыли книгу, детей ослепила внезапная вспышка яркого света. И вот, Макс и Молли уже не на чердаке бабушкиного дома, а путешествуют внутри живого человеческого тела. Книга Кэрол Доннер "Тайны анатомии" издавалась по-русски и прежде, в конце восьмидесятых. Этот увлекательный триллер-путешествие внутри человеческого тела моментально стал бестселлером. Многие мамы и папы, выросшие на этой книге, долго пытались найти ее для собственных детей - по библиотекам, в букинистических лавках, у друзей и знакомых. Мы решили ее переиздать, ведь нам, как и родителям наших читателей, тоже приходится отвечать на бесконечные вопросы собственных детей о том, почему человек устроен так, а не этак. А более полного, достоверного, а главное - увлекательного! - ответа на вопрос об устройстве человеческого тела нам встречать не приходилось. Для детей старшего школьного возраста.', 'How does our body work? Why doesn''t the stomach digest itself, and what keeps the immune system ticking? Max and Molly wonder just like any curious kid, but their search for answers takes an extraordinary turn. Discovering an old anatomy volume in their grandmother''s attic, a flash of blinding light suddenly shrinks them and zips them directly inside a living human body! A timeless blend of thrilling fantasy and solid science, Carol Donner''s classic bestseller turns biology into an unforgettable rollercoaster journey through cells, muscles, and bloodstreams.', 'Kako zapravo funkcioniše ljudsko tijelo? Zašto želudac ne svari sam sebe i kako nas brani imuni sistem? Maks i Moli, radoznali brat i sestra, pronašli su na bakinom tavanu staru knjigu o anatomiji — a čim su je otvorili, bljesak svjetlosti ih je smanjio i uvukao pravo u unutrašnjost živog ljudskog tijela! Ovaj uzbudljivi klasik Kerol Doner majstorski pretvara biologiju u nezaboravnu pustolovinu kroz krvotok, organe i mišiće, pružajući najfascinantnije odgovore na vječna dječja pitanja.', 'Забудьте скучные уроки биологии: здесь вас уменьшат до микроскопических размеров и отправят в захватывающий сплав по кровеносным сосудам!', 'Forget dry biology lectures: prepare to shrink down and embark on a pulse-pounding, microscopic safari through the human bloodstream!', 'Zaboravite dosadne lekcije iz biologije: smanjite se na mikroskopsku veličinu i krenite u uzbudljivu ekspediciju kroz ljudski krvotok!', '/covers/DP-0771.webp', '#c0392b', 'nonfiction', 'ru', 'available', 'Категория: анатомия', '["adventure","real"]', '["human body","anatomy","science","journey","biology"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('почему-мы-спим-772', 'DP-0772', 'Почему мы спим', 'Why We Sleep', 'Zašto spavamo', 'Кэти Эванс', 'Katie Evans', 'Kejti Evans', 'Поля Плавинская', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Всё, что вы хотели знать о сне, но проспали! Зачем мы спим? Какие бывают циклы сна? Чем отличается сон животных? Можно ли избавиться от ночных кошмаров? Мы проводим около трети своей жизни во сне. Но что же на самом деле происходит в эти часы? Эта книга приглашает в увлекательное путешествие по миру сна и расскажет, что происходит, когда мы спим. 5 причин купить книгу «Почему мы спим?» Гипнотическая книга перенесет в яркое путешествие по царству сновидений — и даже дальше; Словно плед, книга будто соткана из фактурных иллюстраций Поли Плавинской; Сон интересовал человека с древних времен и сейчас, в век бесконечной стимуляции, тема как никогда волнующая; Не только интересные факты о биологических и культурных процессах, связанных со сном, но и советы как наладить режим; Увлекательное дополнение к учебным программам по биологии и естественным наукам для детей от 6 лет.', 'Everything you wanted to know about sleep but snoozed through! Why do we need to sleep, and how do sleep cycles work? How do animals snooze, and can you really banish nightmares? We spend about a third of our lives fast asleep, and this mesmerizing book—warm as a cozy blanket and gorgeously illustrated by Polya Plavinskaya—takes curious young minds on an illuminating journey through the science, culture, and wonders of dreams and bedtime.', 'Sve što ste željeli da znate o snu, a prespavali ste! Zašto spavamo i kako funkcionišu ciklusi sna? Kako spavaju životinje i možemo li se riješiti ružnih snova? Oko trećine života provedemo spavajući, a ova topla i čarobno ilustrovana knjiga vodi radoznale čitaoce na uzbudljivo putovanje kroz tajne biologije, snova i zdravog odmora.', 'Уютная и познавательная книга, которая превратит обычный отход ко сну в самое настоящее научное приключение под одеялом!', 'A delightfully cozy and fascinating guide that turns bedtime into a mesmerizing scientific adventure under the covers!', 'Nevjerovatno topla i zanimljiva knjiga koja odlazak na spavanje pretvara u pravu naučnu avanturu pod jorganom!', '/covers/DP-0772.webp', '#2c3e6b', 'nonfiction', 'ru', 'available', 'Категория: анатомия', '["real","animals"]', '["sleep","dreams","human body","science","bedtime","animals"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('женщины-в-науке-773', 'DP-0773', 'Женщины в науке', 'Women in Science: 50 Fearless Pioneers Who Changed the World', 'Žene u nauci: 50 neustrašivih pionirki koje su promijenile svijet', 'Рэйчел Игнатовски', 'Rachel Ignotofsky', 'Rejčel Ignotofski', 'Рэйчел Игнатовски', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Великолепно иллюстрированная книга знаменитого дизайнера Рэйчел Игнатовски посвящена 50 выдающимся женщинам науки древнего и современного мира. Героини книги - физик и химик Мария Кюри, американский математик Кэтрин Джонсон, рассчитавшая траекторию полета Аполлона-11 на Луну, Валентина Терешкова, первая женщина-космонавт и многие другие бесстрашные женщины, проложившие путь для новых поколений женщин-инженеров, биологов, генетиков, математиков, врачей, астронавтов, физиков.', 'A gloriously illustrated and inspiring collection celebrating 50 fearless female pioneers in STEM from the ancient to the modern world, including Marie Curie, Katherine Johnson, and Valentina Tereshkova, who paved the way for generations to come.', 'Raskošno ilustrovana i inspirativna knjiga dizajnerke Rejčel Ignotofski slavi 50 izuzetnih žena koje su promijenile svijet nauke od antike do danas — uključujući Mariju Kiri, Ketrin Džonson i Valentinu Tereškovu.', 'Вдохновляющие и невероятно стильные истории о первооткрывательницах, доказавших, что науку двигают смелость и любопытство!', 'An inspiring and stylish tribute to the fearless trailblazers who proved that curiosity and courage change the world!', 'Nadahnjujuće i prelijepo ilustrovane priče o neustrašivim pionirkama koje su dokazale da radoznalost mijenja svijet!', '/covers/DP-0773.webp', '#254153', 'nonfiction', 'ru', 'available', 'Категория: анатомия', '["real"]', '["science","biography","stem","women pioneers","history"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('женщины-в-искуссве-774', 'DP-0774', 'Женщины в искуссве', 'Women in Art: 50 Fearless Creatives Who Inspired the World', 'Žene u umjetnosti: 50 neustrašivih stvarateljki koje su inspirisale svijet', 'Рэйчел Игнатовски', 'Rachel Ignotofsky', 'Rejčel Ignotofski', 'Рэйчел Игнатовски', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Искусство - это нечто большее, чем просто красота, - это сила! Всё, что нас окружает, независимо от того, осознаем мы это или нет, создано художниками. Здание, в котором мы живем, рекламный щит на улице, узор у тебя на рубашке - всё это начиналось с идеи в голове у творца. Многие считают, что наша способность к самовыражению через творчество - и есть то, что делает людей особенными. Богато иллюстрированная книга знаменитого дизайнера Рэйчел Игнатовски посвящена 50 выдающимся женщинам искусства древнего и современного мира. Героини книги - художницы Фрида Кало и Джорджия О&#39;Киф, писательница Беатрис Поттер и многие другие бесстрашные женщины, проложившие путь для новых поколений женщин-художниц, скульпторов и писательниц. Читай, вдохновляйся и присоединяйся к сообществу творческих женщин!', 'Art is more than just beauty—it is a powerful force! From architecture to the patterns on our clothes, the world around us was shaped by creative visionaries. Gorgeously illustrated by Rachel Ignotofsky, this inspiring volume celebrates fifty fearless women artists—from Frida Kahlo and Georgia O''Keeffe to Beatrix Potter—who paved the way for future generations of painters, sculptors, and storytellers.', 'Umjetnost je mnogo više od same ljepote — to je stvarna moć! Sve što nas okružuje poteklo je iz mašte umjetnika. Raskošno ilustrovana knjiga Rejčel Ignotofski slavi pedeset neustrašivih stvarateljki, od Fride Kalo i Džordžije O''Kif do Beatriks Poter, koje su utrle put novim generacijama slikarki, vajarki i spisateljica.', 'Откройте эту невероятно красивую книгу, чтобы познакомиться с пятьюдесятью бунтарками, изменившими мир кистью, резцом и силой воображения!', 'Crack open this brilliantly illustrated gem to meet fifty fearless trailblazers who reshaped our world with brushes, chisels, and pure imagination!', 'Otvorite ovu predivno ilustrovanu knjigu i upoznajte pedeset neustrašivih buntovnica koje su promijenile svijet kistom, dlijetom i maštom!', '/covers/DP-0774.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real"]', '["art","women in history","biography","creativity","inspiration"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-инвентаризация-искусст-775', 'DP-0775', 'Большая инвентаризация искусства', 'The Great Art Inventory', 'Veliki inventar umjetnosti', 'Луиза Локхарт', 'Louise Lockhart', 'Luiz Lokhart', 'Луиза Локхарт', 'А+А', NULL, NULL, 6, 16, 'middle', 'Вместе с авторами этого издания читатель поучаствует в настоящей инвентаризации произведений искусства со всего мира. Книга состоит из десяти глав. Первый разворот каждой главы — краткая характеристика периода в истории искусств с древних времен и до современности, второй — импровизированная коллекция художественных артефактов эпохи. Это художники, картины, строения, скульптуры, явления, инструменты — все, из чего состоит художественное пространство времени.', 'Join a vibrant journey through world art across ten distinct eras, from ancient beginnings to modern creativity. Each chapter opens with a vivid overview of an artistic period, followed by a playful collection of iconic paintings, sculptures, architecture, tools, and masters that defined their age.', 'Krenite u veliku inventuru svjetske umjetnosti kroz deset uzbudljivih epoha, od praistorije do savremenog doba. Svako poglavlje nudi pregled jedne ere, a zatim raskošnu kolekciju slika, skulptura, građevina, alata i umjetnika koji su oblikovali svoje vrijeme.', 'Загляните в сокровищницу мирового искусства — здесь на каждой странице оживают шедевры, эпохи и тайны великих мастеров!', 'Step into the ultimate treasury of world art, where centuries of masterpieces, iconic architecture, and artist tools unfold before your eyes!', 'Zavirite u riznicu svjetske umjetnosti gdje remek-djela, arhitektonska čuda i tajne starih majstora oživljavaju pred vašim očima!', '/covers/DP-0775.webp', '#d45d3a', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real","adventure"]', '["art history","creativity","encyclopedia","painting","culture"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('по-следам-современного-искусст-776', 'DP-0776', 'По следам современного искусства Иллюстрированная книга для детей о произведениях современного искусства из собрания Национального музея современного искусства — Центра Жоржа Помпиду в Париже.', 'In Search of Modern Art: An Illustrated Guide to the Centre Pompidou', 'Tragom savremene umjetnosti: Ilustrovani vodič kroz Centar Pompidu', '', 'Alice Harman, Serge Bloch', 'Elis Harman, Serž Blok', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Увлекательная книга-квест, написанная британкой Элис Харман и искрометно проиллюстрированная известным французским художником Сержем Блоком, проведет юных читателей и всех, кому интересно современное искусство, по его истории и по залам парижского Центра Помпиду. Обозревая лучшие экспонаты этого музея, непринужденно беседуя с их авторами и порой подшучивая над ними, текст не оставит сомнений в том, что искусство — одна из самых веселых вещей на свете.', 'An exciting quest-book written by British author Alice Harman and wittily illustrated by acclaimed French artist Serge Bloch takes young readers on a tour through the history of modern art and the vibrant halls of Paris''s Centre Pompidou. Exploring iconic masterpieces, casually chatting with the artists, and playfully teasing them along the way, this book proves beyond a doubt that modern art is one of the most fun adventures in the world.', 'Uzbudljiva knjiga-potraga britanske autorke Elis Harman, duhovito ilustrovana od strane poznatog francuskog umjetnika Serža Bloka, vodi mlade čitaoce kroz istoriju savremene umjetnosti i dvorane pariskog Centra Pompidu. Istražujući najpoznatija remek-djela uz opuštene razgovore i vedre šale o umjetnicima, ova knjiga nepobitno dokazuje da je savremena umjetnost jedna od najzabavnijih stvari na svijetu.', 'Забудьте про скучный шёпот в музеях: эта книга превратит прогулку по залам Центра Помпиду в дерзкий, смешной и полный открытий квест!', 'Forget boring museum whispers: this book turns a stroll through the Centre Pompidou into a bold, hilarious, and eye-opening adventure!', 'Zaboravite na dosadno šaputanje u muzejima: ova knjiga pretvara šetnju kroz Centar Pompidu u smjelu, urnebesnu i razigranu avanturu!', '/covers/DP-0776.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["adventure","funny","real"]', '["art","museums","centre pompidou","creativity","quest"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('архитектура-глазами-голубя-777', 'DP-0777', 'Архитектура глазами голубя', 'Architecture According to Pigeons', 'Arhitektura očima goluba', 'Крап Ли Пернхвост', 'Speck Lee Tailfeather', 'Spek Li Telveder', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Увлекательное путешествие по главным мировым достопримечательностям от лица голубя по имени Крап. Рассказ сопровождается красочными иллюстрациями и учит наслаждаться красотой зданий самых юных путешественников. Уникальная возможность узнать о шедеврах архитектуры буквально с высоты птичьего полета.', 'Join Speck Lee Tailfeather, the world''s most cultured pigeon, on a whirlwind journey around the globe''s greatest architectural wonders. Filled with vibrant illustrations and fascinating insights, this charming guide teaches young explorers to admire buildings and discover timeless masterpieces from a true bird''s-eye view.', 'Pridružite se Speku, najučenijem golubu na svijetu, na uzbudljivom putovanju kroz najznačajnija arhitektonska čuda naše planete. Bogato ilustrovana i puna zanimljivih činjenica, ova knjiga podučava mlade istraživače da cijene ljepotu građevina iz prave ptičje perspektive.', 'Приготовьтесь к захватывающему полёту над Колизеем и Сиднейской оперой под крылом самого эрудированного голубя в мире!', 'Get ready to swoop over the Colosseum and the Sydney Opera House under the wing of the most cultured pigeon on Earth!', 'Pripremite se za spektakularan let iznad Koloseuma i Sidnejske opere pod krilom najučenijeg goluba na svijetu!', '/covers/DP-0777.webp', '#3f849d', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real","adventure","animals"]', '["architecture","travel","world landmarks","birds","art for kids"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кто-это-построил-778', 'DP-0778', 'Кто это построил', 'Who Built This', 'Ko je ovo izgradio', 'Полина Фадеева, Анна Алямова', 'Polina Fadeeva, Anna Alyamova', 'Polina Fadjejeva, Ana Aljamova', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Задумывались ли вы, глядя на дома и улицы, отели и музеи, магазины и моллы, о том, кто всё это построил? А ведь кто-то придумал и возвёл целые города, порты, мосты, парки. И даже памятники кто-то спроектировал так, чтобы они не падали. Эта книга о людях, которые построили всё то, что не создала сама природа, — об архитекторах. Они не всегда строят сами, они разрабатывают проекты и планы, продумывают использование и развитие территорий. Это сложнейшая и очень ответственная работа, и результат ее у всех на виду. Однако самих архитекторов мы видим редко, иногда знаем по имени и почти никогда — в лицо. А ведь эти мастера и творцы — живые люди, шутники и мечтатели. Анна Алямова и Полина Фадеева, потомственные архитекторы и подруги с детства, решили рассказать детям и взрослым не только о зданиях, планах, конструкциях и концепциях, но и об их создателях, которые были маленькими, придумывали затейливые штуки, любили конструкторы, помогали родителям, а когда выросли, не стали скучными взрослыми, а продолжили играть с реальностью и создавать новое и удивительное. Даже если окружающим всё это порой казалось странным ребячеством, со временем герои книги изменили мир, в котором мы живем.', 'Have you ever looked at houses, museums, bridges, and bustling streets and wondered who actually built them? Behind every skyline are architects—visionaries who design entire cities, harbors, and parks. Lifelong friends and hereditary architects Polina Fadeeva and Anna Alyamova introduce readers to the incredible creators behind human-made wonders. From childhood games with building blocks to bold blueprints that reshaped the globe, this book reveals that great architects never stopped being playful dreamers.', 'Jeste li se ikada, gledajući zgrade, muzeje, mostove i parkove, zapitali ko je sve to stvorio? Iza svakog grada stoje arhitekte — vizionari koji osmišljavaju prostore u kojima živimo. Arhitektice i prijateljice iz djetinjstva Polina Fadjejeva i Ana Aljamova otkrivaju priče o majstorima koji su promijenili svijet. Kroz zabavne detalje saznajte kako su djeca koja su voljela kockice i maštanje izrasla u genijalne stvaraoce koji su se usudili da promijene stvarnost.', 'Вдохновляющий путеводитель по миру архитектуры, который доказывает: великие здания строят выросшие дети, не разучившиеся мечтать!', 'An inspiring peek behind the blueprints that proves the world''s greatest buildings were dreamed up by kids who never stopped playing!', 'Nadahnjujuća priča koja dokazuje da najljepše zgrade i gradove svijeta grade djeca koja nikada nijesu prestala da maštaju!', '/covers/DP-0778.webp', '#2b6cb0', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real"]', '["архитектура","города","профессии","история","творчество"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('алексей-щусев-архитектор-котор-779', 'DP-0779', 'Алексей Щусев, архитектор который покорил время', 'Alexey Shchusev: The Architect Who Conquered Time', 'Aleksej Šćusev: Arhitekta koji je pobijedio vrijeme', 'Ксения Смирнова, Полина Покладок', 'Ksenia Smirnova, Polina Pokladok', 'Ksenija Smirnova, Polina Pokladok', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Первая популярная книга об Алексее Щусеве — человеке, который спроектировал и воплотил в жизнь десятки знаковых зданий (среди них Марфо-Мариинская обитель, Казанский Вокзал и Мавзолей Ленина в Москве, Театр оперы и балета в Ташкенте и Русский павильон в Венеции). Щусев был великим архитектором — но чтобы достичь того, что сам он называл «неплохими результатами», недостаточно просто уметь строить дома. Нужны и другие знания, умения и способности, которые позволяют нам назвать Алексея Викторовича замечательным реставратором, градостроителем, преподавателем, художником. На жизнь Щусева выпало множество событий, кардинально изменивших вкусы людей, скорость жизни, политический строй и отношение к прошлому. Но он смог «покорить время», оставаясь одним из лидеров отечественной архитектуры, что бы ни происходило в жизни, искусстве и стране. Авторы книги, научные сотрудники Государственного музея архитектуры, который носит имя Алексея Щусева, увлекательно и с любовью говорят о великом человеке, на примере которого дети и их родители узнают, как талант, трудолюбие и любовь к своему делу позволяют, несмотря на революции, войны и смену власти, не только идти в ногу со временем, но и остаться в памяти потомков.', 'The first accessible book about Alexey Shchusev — the mastermind behind iconic landmarks ranging from the Kazansky Railway Station and Lenin''s Mausoleum to the Opera House in Tashkent and the Russian Pavilion in Venice. Written by curators of the Shchusev State Museum of Architecture, this vibrant book shows how curiosity, boundless talent, and genuine love for one''s craft help an architect conquer time itself despite wars and revolutions.', 'Prva pristupačna knjiga o Alekseju Šćusevu — čovjeku koji je osmislio i oživio na desetine kultnih građevina, od Kazanske stanice i Lenjinovog mauzoleja do Opere u Taškentu i Ruskog paviljona u Veneciji. Autorke, kustoskinje Muzeja arhitekture, na topao i živopisan način otkrivaju djeci i roditeljima kako istinski talenat i radost stvaranja pobjeđuju vrijeme, uprkos ratovima i smjenama epoha.', 'Увлекательное путешествие по чертежам и тайнам великого мастера, чьи здания пережили смену целых эпох!', 'An inspiring dive into the drawings and secrets of a visionary architect whose iconic buildings outlived changing empires!', 'Zavirite u nacrte i tajne legendarnog majstora čija su remek-djela nadživjela preokrete čitavih epoha!', '/covers/DP-0779.webp', '#b84a39', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real"]', '["architecture","biography","history","cities","art"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-фотограф-780', 'DP-0780', 'Я - фотограф', 'I Am a Photographer', 'Ja sam fotograf', 'Ольга Аверьянова, Олеся Гонсеровская', 'Olga Averyanova, Olesya Gonserovskaya', 'Olga Averjanova, Olesja Gonserovska', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Все мы фотографируем! Порой кажется, что так было всегда. Но это заблуждение. Фотография — магия, наука и искусство — так думали на заре её истории. Сегодня — это просто касание пальцем кнопки смартфона. Или все-таки нет? Для детей и их родителей в книге можно найти ответы на этот и другие вопросы. Почитаем и посмотрим.', 'We all take pictures every day! It might feel like it has always been this easy, but photography began as an incredible mix of magic, science, and high art. Today, it seems like nothing more than tapping a smartphone screen—or is there still more to it? Children and curious parents will discover the captivating answers to this and many other questions inside.', 'Svi mi stalno fotografišemo! Ponekad se čini da je tako bilo oduvijek, ali to je zabluda. Na samom početku, fotografija je smatrana pravom magijom, naukom i umjetnošću. Danas izgleda kao običan dodir ekrana pametnog telefona — ili ipak nije tako jednostavno? Djeca i roditelji će u ovoj knjizi otkriti fascinantne tajne hvatanja trenutka.', 'Загляните за объектив камеры и узнайте, как магия света и науки превратила обычные мгновения в искусство!', 'Peek behind the camera lens and discover how the magic of light and science turned fleeting moments into unforgettable art!', 'Zavirite iza objektiva kamere i otkrijte kako je spoj svjetlosti i nauke pretvorio obične trenutke u pravu umjetnost!', '/covers/DP-0780.webp', '#3b6978', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real","magic"]', '["photography","art","history","science","creativity"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мир-инженера-шухова-как-работа-781', 'DP-0781', 'Мир инженера Шухова Как работает мозг изобретателя', 'The World of Engineer Shukhov: How an Inventor''s Mind Works', 'Svijet inženjera Šuhova: Kako radi um pronalazača', 'Айрат Багаутдинов', 'Airat Bagautdinov', 'Ajrat Bagautdinov', 'Полина Шевчук', 'Альпина', NULL, NULL, 6, 16, 'middle', '', 'Step into the fascinating world of Vladimir Shukhov, the visionary pioneer who invented lightweight hyperboloid towers, revolutionary bridges, and modern oil infrastructure. With engaging explanations and vibrant architectural drawings, this book reveals how an engineer''s curiosity transforms bold mathematical dreams into real-world marvels.', 'Zakoračite u uzbudljiv svijet Vladimira Šuhova, inženjerskog pionira koji je izumio hiperboloidne kule, revolucionarne mostove i prve naftovode. Uz zanimljiva objašnjenja i slikovite crteže, ova knjiga pokazuje kako inženjerska radoznalost pretvara smjele matematičke ideje u prava graditeljska čuda.', 'Загляните в чертежи и мысли гениального инженера, чтобы научиться видеть конструкции будущего в самых простых вещах вокруг нас!', 'Peek into the mind of a legendary engineer and discover how simple, elegant ideas can turn into breathtaking towers and bridges!', 'Zavirite u um legendarnog inženjera i otkrijte kako se jednostavne ideje pretvaraju u zadivljujuće kule i mostove!', '/covers/DP-0781.webp', '#2c4c64', 'nonfiction', 'ru', 'available', '6+', '["real","adventure"]', '["engineering","architecture","inventions","science","biography"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('история-книги-своими-руками-782', 'DP-0782', 'История книги своими руками', 'DIY History of Books', 'Istorija knjige sopstvenim rukama', 'Светлана Прудовская', 'Svetlana Prudovskaya', 'Svetlana Prudovskaja', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Вы знаете, какой была книга 4 тысячи лет назад? Хотите, не выходя из дома, сделать глиняную табличку, папирусный свиток, берестяную грамоту или бумажную гармошку? А изготовить собственную бумагу с цветами или с укропом? Читателю этой книги предстоит не только узнать, какой долгий путь прошла книга, но и пережить этот сюжет мировой истории на собственном опыте - через эксперименты с разными материалами и создание собственных рукотворных книг. Попутно читатель откроет для себя множество секретов художественного ремесла, которыми владели древние мастера. Книга богато иллюстрирована; в ней вы найдёте сказки, пословицы, скороговорки и рецепты, которые пригодятся для изготовления необычных рукодельных книжек. Автор книги - художник, педагог и искусствовед Светлана Прудовская. Для среднего школьного возраста.', 'Do you know what a book looked like four thousand years ago? Would you like to craft a clay tablet, a papyrus scroll, a birch bark manuscript, or an accordion book right at home? How about making custom paper with dried flowers or dill? Readers will not only discover the long journey the book has taken through the ages, but will also experience world history firsthand by experimenting with diverse materials and binding their own volumes. Richly illustrated and packed with historical lore, tales, and creative craft recipes, this guide is created by artist, educator, and art historian Svetlana Prudovskaya.', 'Da li znate kako je knjiga izgledala prije četiri hiljade godina? Želite li da kod kuće napravite glinenu tablicu, svitak od papirusa, zapis na brezovoj kori ili papirnu harmoniku? Ili da sami napravite papir sa suvim cvijećem? Ova knjiga vodi čitaoce kroz vjekovni razvoj pisane riječi i omogućava im da kroz praktične eksperimente sami stvore unikatne rukotvorine. Uz pregršt ilustracija, starih priča i recepata za izradu papira, umjetnica i istoričarka umjetnosti Svetlana Prudovskaja otkriva tajne drevnih majstora zanata.', 'Превратите детскую комнату в мастерскую древнего писца и создайте свою первую глиняную табличку или папирусный свиток!', 'Turn your room into an ancient scribe''s workshop and craft your very own clay tablets, papyrus scrolls, and botanical paper!', 'Pretvorite dječju sobu u radionicu drevnih pisara i napravite sopstvene glinene tablice i svitke od papirusa!', '/covers/DP-0782.webp', '#c47a46', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real","adventure"]', '["history","crafts","diy","books","nonfiction"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-знаю-такого-художника-783', 'DP-0783', 'Я знаю такого художника', 'I Know an Artist', 'Znam tog umjetnika', 'Сьюзи Ходж', 'Susie Hodge', 'Suzi Hodž', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Я знаю такого художника - это восемьдесят четыре очерка о выдающихся художниках XIX-XXI веков, оказавших решающее влияние на ход истории искусства. А еще это история неожиданных встреч и удивительных пересечений судеб. Одних художников - например, Пауля Клее и Анни Альберс - связывали отношения преподавателя и студента, других, как Джексона Поллока и Ли Краснер, - любовь и супружество, третьих - общий источник вдохновения, как, например, цветы в творчестве Джорджии О&#39;Кифф и Такаси Мураками.', 'I Know an Artist presents eighty-four engaging profiles of pivotal 19th- to 21st-century creators who shaped modern art history. Beyond standalone biographies, the book highlights intriguing intersections: mentors and students like Paul Klee and Anni Albers, artistic soulmates like Jackson Pollock and Lee Krasner, and shared muses like the vibrant flowers that inspired both Georgia O''Keeffe and Takashi Murakami.', '„Znam tog umjetnika“ donosi osamdeset četiri inspirativne priče o stvaraocima XIX–XXI vijeka koji su promijenili tok istorije umjetnosti. Ovo nije samo zbirka biografija, već uzbudljiva hronika neočekivanih susreta: mentora i učenika poput Paula Klea i Ani Albers, kreativnih partnera poput Džeksona Poloka i Li Krasner, ili umjetnika koje spaja ista fascinacija, poput cvijeća kod Džordžije O''Kif i Takašija Murakamija.', 'Откройте тайные нити, связывающие великих мастеров, и взгляните на историю искусства как на увлекательный круг творческих друзей!', 'Discover the hidden threads connecting world-renowned masters and explore art history as one wonderfully interconnected circle of friends!', 'Otkrijte skrivene veze među velikanima i doživite istoriju umjetnosti kao uzbudljiv krug stvaralačkih prijateljstava!', '/covers/DP-0783.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real","friends"]', '["art","biography","history","creativity","inspiration"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('старые-мастера-рулят--784', 'DP-0784', 'Старые мастера рулят!', 'Old Masters Rock!', 'Stari majstori su zakon!', 'Сайн-Витгенштейн Ноттебом Мария-Кристина', 'Maria-Christina Sayn-Wittgenstein Nottebohm', 'Maria-Christina Sayn-Wittgenstein Nottebohm', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Книга для детей и родителей, открывающая новые стороны знакомых произведений искусства. «Старые мастера рулят!» включает в себя 50 картин как известных художников: Леонардо да Винчи, Винсента ван Гога, Эдварда Мунка, Питера Пауля Рубенса, Эдгара Дега, Эдуарда Мане, так и менее знакомых. Все они сгруппированы по темам — «Животные», «Природа», «Герои», «Мифы», «Магия» и другие — и наиболее полно рассказывают о художественных произведениях с XII до XX века.', 'A vibrant guide for curious kids and parents that turns classical art into an exciting visual treasure hunt. Featuring 50 masterpieces by Leonardo da Vinci, Vincent van Gogh, Edvard Munch, and other legendary artists, this book organizes centuries of creativity by lively themes—from animals and nature to myths and magic—proving that historical art is anything but boring.', 'Uzbudljiv vodič kroz klasičnu umjetnost za radoznalu djecu i roditelje. Sa 50 remek-djela čuvenih slikara poput Leonarda da Vinčija, Vinsenta van Goga i Edvarda Munka, ova knjiga grupiše vijekove stvaralaštva po zabavnim temama — od životinja i prirode do mitova i magije — dokazujući da remek-djela prošlosti nikada ne gube svoj sjaj.', 'Думаете, классические картины скучные и пыльные? Эта книга докажет, что старые мастера умели зажигать круче современных художников!', 'Think museum paintings are dusty and boring? This book proves the old masters knew how to rock and spark pure imagination!', 'Mislite da su muzejske slike prašnjave i dosadne? Ova knjiga će vam dokazati da su stari majstori bili pravi rokeri svog doba!', '/covers/DP-0784.webp', '#d97724', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real","adventure","magic"]', '["art","history of art","paintings","museums","creativity"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('школа-искусств-785', 'DP-0785', 'Школа искусств', 'The School of Art', 'Škola umjetnosti', 'Тил Триггс', 'Teal Triggs', 'Til Trigs', 'Дэниел Фрост', 'МИФ', NULL, NULL, 6, 16, 'middle', '"Школа искусств" - не просто книга. Это полноценный курс, который познакомит вашего ребенка с основами изобразительного искусства и дизайна. Вы попадете в настоящую школу, профессора которой расскажут вам все самое важное о главных элементах дизайна: линиях, геометрических фигурах, пространстве и цвете. Вы узнаете: какой может быть линия, как превратить двухмерную фигуру в трёхмерную, передать движение, работать с тенями, текстурой, штриховкой, паттернами и, конечно, цветом. После этого вы изучите основные правила, которые помогают собрать все элементы дизайна вместе. Темами уроков станут: композиция и модульная сетка, пропорции, перспектива, негативное и позитивное пространство, визуальный вес, ритм и многое другое. Ну, и наконец, последние уроки будут посвящены тому, как применять новые знания в жизни: как мыслить образами и отражать их на бумаге, как с помощью рисунков объяснять сложные идеи, рисовать комиксы и инфографику.', 'A comprehensive and playful art school course in book form. Five quirky professors guide young creators through the fundamental principles of visual art and design—from lines, shapes, and color theory to perspective, rhythm, composition, and even crafting your own comics and infographics.', 'Sveobuhvatan i razigran uvodni kurs umjetnosti u formi knjige. Pet neobičnih profesora vodi mlade stvaraoce kroz osnovne principe vizuelne umjetnosti i dizajna — od linija, oblika i teorije boja do perspektive, ritma, kompozicije, crtanja stripova i infografika.', 'Поступаем в самую весёлую художественную академию в мире, где профессора учат мыслить линиями, формой и цветом!', 'Step into the world''s most whimsical art academy, where eccentric professors teach you how to think, see, and create like a real designer!', 'Zakoračite u najveseliju akademiju umjetnosti na svijetu, gdje vas neobični profesori uče kako da razmišljate i stvarate kao pravi dizajneri!', '/covers/DP-0785.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: об искусстве', '["real"]', '["art","design","creativity","drawing","education"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('линнея-в-саду-художника-786', 'DP-0786', 'Линнея в саду художника', 'Linnea in Monet''s Garden', 'Lineja u slikarevom vrtu', 'Лена андерсон, Кристина Бьорк', 'Christina Björk, Lena Anderson', 'Kristina Bjork, Lena Anderson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Линнея - маленькая девочка, которая очень любит цветы. Вместе со своим другом, садовником Блумквистом, она совершает путешествие в Париж, на родину великого художника Клода Моне. Им удается не только побывать в музее, где хранятся его картины, но и заглянуть в дом художника, посмотреть на цветы в его саду и пройтись по знаменитому японскому мостику, который Моне так часто изображал на своих полотнах. А самое интересное о жизни Моне они узнают от его правнука, который повстречался им рядом с домом Моне. "Линнея в саду художника" - это книга об искусстве, написанная специально для детей. Она была переведена на 30 языков, только в Америке продано более 700 000 экземпляров! В Германии книга получила престижную премию в области юношеской литературы (1988) в номинации "Познавательная книга".', 'Linnea loves flowers, so a trip to Paris and Giverny with her neighbor Mr. Bloom to explore Claude Monet''s home is a dream come true! Together, they wander through the blooming gardens, cross the iconic Japanese bridge, admire the famous water lilies, and even meet the painter''s great-grandson. An internationally beloved, award-winning introduction to art and impressionism created especially for young discoverers.', 'Lineja je djevojčica koja obožava cvijeće. Zajedno sa svojim prijateljem, baštovanom Blumkvistom, putuje u Pariz i Živerni kako bi posjetila dom slavnog slikara Kloda Monea. Tamo prelaze čuveni japanski mostić, dive se vodenim ljiljanima i otkrivaju tajne slikarstva iz prve ruke od Moneovog praunuka. Ova nagrađivana knjiga na topao i pristupačan način uvodi djecu u čarobni svijet umjetnosti i impresionizma.', 'Идеальное путешествие в Живерни прямо с дивана: ловите солнечных зайчиков импрессионизма вместе с любознательной Линнеей!', 'The ultimate armchair voyage to Giverny: chase impressionist light and water lilies with the delightfully curious Linnea!', 'Savršeno putovanje u Živerni pravo iz fotelje: uhvatite sunčeve zrake impresionizma i lokvanje zajedno sa radoznalom Linejom!', '/covers/DP-0786.webp', '#488b69', 'nonfiction', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["real","friends","adventure"]', '["art","claude monet","impressionism","gardening","travel"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('оркестр-787', 'DP-0787', 'Оркестр', 'The Orchestra', 'Orkestar', 'Авалон Нуово', 'Avalon Nuovo', 'Avalon Nuovo', 'Дэвид Доран', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Как устроен оркестр и на какие группы делятся музыкальные инструменты? Что значит «читать ноты» и как сочиняют музыку? Из чего состоят скрипка, труба и кларнет? Чем орган отличается от пианино? Почему так важна акустика концертного зала? Эта книга адресована и начинающим музыкантам, и всем тем, кто неравнодушен к волшебному миру музыки. Вы узнаете, как появились первые оркестры, кто из композиторов совершил настоящую музыкальную революцию, в чём секрет знаменитого цикла концертов Антонио Вивальди «Времена года» и ещё много-много интересного.', 'How does an orchestra work, and how are musical instruments grouped? What does it mean to read sheet music, and how is music composed? From the anatomy of violins and trumpets to the acoustics of grand concert halls, this book invites budding musicians and music lovers alike to uncover the secrets behind sound, legendary composers, and timeless masterpieces like Vivaldi''s Four Seasons.', 'Kako funkcioniše orkestar i na koje se grupe dijele muzički instrumenti? Šta znači „čitati note” i kako nastaje muzika? Od čega se sastoje violina, truba i klarinet i zašto je akustika koncertne dvorane toliko važna? Ova knjiga vodi mlade muzičare i radoznalce na putovanje kroz istoriju instrumenata, revolucionarnih kompozitora i remek-djela poput Vivaldijevih „Godišnjih doba”.', 'Загляните за кулисы филармонии и узнайте, как десятки разных инструментов сливаются в единую гармонию!', 'Peek behind the concert hall curtain to discover how dozens of unique instruments join in breathtaking harmony!', 'Zavirite iza kulisa filharmonije i otkrijte kako se desetine različitih instrumenata stapaju u jedinstvenu harmoniju!', '/covers/DP-0787.webp', '#1a4754', 'nonfiction', 'ru', 'available', 'Категория: про музыку', '["magic","real"]', '["music","orchestra","instruments","art","composers"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('иллюстрированная-история-рока-788', 'DP-0788', 'Иллюстрированная история рока', 'An Illustrated History of Rock', 'Ilustrovana istorija roka', 'Сусана Монтеагудо', 'Susana Monteagudo', 'Susana Monteagudo', 'Луис Демано', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Точная дата рождения рока не известна. Нет у него и какого-то одного отца-основателя. Рок возник в Америке из смеси блюза, джаза, кантри, ритм-энд-блюза и других музыкальных стилей. Музыканты 1950-х годов соединили эти формы и ритмы, еще не понимая, что получившаяся смесь положит начало большой революции. "Иллюстрированная история рока" - книга про эту революцию. Она расскажет о группах и исполнителях, о самых важных песнях и альбомах, о фестивалях и фанатах, о звукозаписывающих компаниях, музыкальных журналах и передачах - короче, обо всем!', 'Rock music has no single birthdate and no solitary founding father. Born in America from a vibrant clash of blues, jazz, country, and rhythm and blues, rock started a cultural earthquake that shook the whole world. This vibrant, encyclopedic visual guide chronicles that revolution from the ground up: legendary bands, iconic albums, wild festivals, devoted fans, record labels, and music subcultures that changed history forever.', 'Tačan datum rođenja roka nije poznat, niti postoji jedan jedini osnivač. Rok je nastao u Americi iz eksplozivne mješavine bluza, džeza, kantrija i ritam-i-bluza. Muzičari 1950-ih spojili su ove stilove pokrenuvši pravu kulturnu revoluciju. Ova bogato ilustrovana knjiga vodi vas kroz istoriju te muzičke pobune — od kultnih bendova, pjesama i festivala do gramofonskih ploča i vjernih fanova.', 'Включайте звук на полную: перед вами драйвовая и невероятно стильная хроника того, как гитарные риффы перевернули планету!', 'Crank up the volume to eleven: here is a stunningly illustrated, groovy celebration of the guitars, legends, and revolutions that changed the world!', 'Pojačajte zvuk do daske: ovo je uzbudljiva i nevjerovatno stilizovana priča o tome kako su gitarski rifovi promijenili svijet!', '/covers/DP-0788.webp', '#d93829', 'nonfiction', 'ru', 'available', 'Категория: про музыку', '["real","adventure"]', '["music","rock","history","subcultures","nonfiction"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('школа-музыки-789', 'DP-0789', 'Школа музыки', 'The School of Music', 'Škola muzike', 'МАйриг и Рэйчел Боуэн', 'Meurig and Rachel Bowen', 'Meurig i Rejčel Bouen', 'Дэниел Фрост', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Продолжение "Школы искусств". Теперь пришло время обратить внимание на музыку! Мы снова стоим на пороге невероятной школы, где вас ждут профессиональные учителя и репетиторы. Они расскажут вам об особенностях вокала, инструментальной музыки, оркестрового исполнения. Лучшие в своих областях: Классическая оперная певица, Дирижер в оркестре (руководит музыкальными коллективами разных жанров) Эксперт по струнным инструментам, Виртуоз ударных инструментов, Богиня духовых инструментов Если ваш ребенок уже занимается музыкой, хотел бы начать ее изучение или ему просто интересно понять, как все устроено, - эта книга идеальный проводник в волшебный мир музыки. В книге есть музыкальные отрывки, которые можно найти и прослушать в интернете.', 'Step inside an extraordinary academy where seasoned musical pros introduce young readers to the wonders of melody, rhythm, and performance. Guided by an opera singer, an orchestra conductor, and virtuosic tutors of strings, brass, and percussion, kids explore how instruments work and how sound turns into art, complete with curated audio tracks to listen to online.', 'Zakoračite u neobičnu muzičku akademiju gdje vrhunski muzičari i dirigenti otkrivaju čari melodije, ritma i orkestarskog zvuka. Uz opersku divu, virtuoze na gudačkim, duvačkim i udaračkim instrumentima, mladi čitaoci će saznati kako nastaje muzika i istražiti predložene numere za slušanje na internetu.', 'Загляните за кулисы оркестра и узнайте, как разрозненные звуки превращаются в чистую магию!', 'Step behind the concert hall curtains and discover how wild sounds come together to create pure acoustic magic!', 'Zavirite iza kulisa koncertne dvorane i otkrijte kako se zvuci instrumenata pretvaraju u pravu magiju!', '/covers/DP-0789.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Для кого эта книга Для детей от 8 лет увлеченных музыкой и их родителей, которые хотят узнать о ней больше.', '["real","magic"]', '["music","orchestra","instruments","creativity","nonfiction"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('история-музыки-в-картинках-790', 'DP-0790', 'История музыки в картинках', 'The History of Music in Pictures', 'Istorija muzike u slikama', 'Бернар Дейрие Дени Лемери Майкл Сэдлер', 'Bernard Deyriès, Denis Lemery, Michael Sadler', 'Bernard Dejrije, Deni Lemeri, Majkl Sadler', '', 'Классика 21', NULL, NULL, 6, 16, 'middle', 'Приглашаем в захватывающее путешествие "по следам классической музыки"! В этой "Истории" есть все, что нужно ученику или меломану: сведения о великих музыкантах древности и современности, о музыкальных инструментах и музыкальных нравах. Здесь есть классика, рок, джаз и авангард. Здесь есть даже то, о чем и педагоги узнают с удовольствием. А именно: - какая музыка была модной в каменном и других веках - что танцевали на дискотеке пять или семь столетий назад - кто придумал сочинения для ужинов короля… для двери и вздоха… для пишущей машинки… для магнитофона с симфоническим оркестром… А самое главное, что… "История музыки в картинках": веселая форма - но не в ущерб исторической достоверности. Просто учить и учиться станет намного интереснее!', 'Take an exciting and witty journey through the history of music! Illustrated in a playful comic style without losing historical precision, this guide covers everything from Stone Age beats and medieval dance floors to royal dinners, jazz, rock, and avant-garde symphonies for typewriters and squeaky doors. Perfect for budding musicians and curious music lovers alike.', 'Krenite na uzbudljivo i duhovito putovanje kroz istoriju muzike! Ilustrovan u formi stripa, ali uz poštovanje istorijskih činjenica, ovaj vodič obuhvata sve: od ritmova kamenog doba i srednjovjekovnih plesova do džeza, roka i avangardnih simfonija za pisaće mašine. Nezaobilazno štivo za sve mlade muzičare i znatiželjne ljubitelje muzike.', 'Оказывается, история музыки полна безумных открытий, весёлых курьёзов и композиций для пишущих машинок — оторваться невозможно!', 'Turns out music history is full of wild experiments, dance beats, and symphonies for typewriters — you won''t be able to put it down!', 'Ispostavlja se da je istorija muzike puna otkačenih otkrića, zabavnih anegdota i simfonija za pisaće mašine — nemoguće je odvojiti se od nje!', '/covers/DP-0790.webp', '#d48b28', 'nonfiction', 'ru', 'available', 'комикс', '["real","funny"]', '["music","history","comics","instruments","art","encyclopedia"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('цой-история-рок-звезды-в-буква-791', 'DP-0791', 'Цой История рок-звезды в буквах и картинках', 'Tsoi: The Story of a Rock Star in Letters and Pictures', 'Coj: Priča o rok zvijezdi u slovima i slikama', 'Денис Бояринов', 'Denis Boyarinov', 'Denis Bojarinov', 'Мария Шишова', 'Альпина', NULL, NULL, 6, 16, 'middle', '«Цой. История рок-звезды в буквах и картинках» — иллюстративный нонфикшн, в котором из отдельных эпизодов истории группы «Кино» и жизни Виктора Цоя складывается картина больших перемен, и для каждого она получается своей. Эта книга — собирательный образ, метафора эпохи, рассказ о кумире поколений, который понравится и подросткам, и взрослым. Всем, кто хотя бы раз в жизни подпевал уличным музыкантам, пел на кухне «Пачку сигарет» (про «самолет с серебристым крылом»), а может, и сам учился играть песни группы «Кино».', 'An illustrated non-fiction journey through the life of Viktor Tsoi and the legendary band Kino, capturing the spirit of a changing era. Packed with vivid graphics and compelling anecdotes, this book brings to life the idol of generations for both teens and adults who have ever sung his anthems to an acoustic guitar.', 'Ilustrovana publicistika kroz epizode iz života Viktora Coja i kultne grupe „Kino“, koja dočarava duh epohe velikih promjena. Ova knjiga je oda idolu generacija, privlačna podjednako i tinejdžerima i roditeljima koji su ikada uz gitaru pjevali njegove legendarne pjesme.', 'Включайте гитарные риффы и готовьтесь петь «Перемен!» — это стильное и честное погружение в жизнь легенды рока для мечтателей и бунтарей любого возраста.', 'Crank up the guitar chords and get ready for a stylish journey into the life of a legendary rock icon who defined an entire generation.', 'Uključite gitare i spremite se za buntovno, ali toplo putovanje kroz život istinske muzičke legende koja i danas inspiriše mlade.', '/covers/DP-0791.webp', '#c83e2b', 'nonfiction', 'ru', 'available', 'Категория: про музыку', '["real"]', '["biography","rock music","viktor tsoi","illustrated history","music"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мусорная-революция-792', 'DP-0792', 'Мусорная революция', 'Trash Revolution: Breaking the Cycle of Waste', 'Revolucija otpada', 'Эрика Файви', 'Erica Fyvie', 'Erika Fajvi', 'Билл Салвин', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Задумывался ли ты когда-нибудь, что происходит с мусором, который мы ежедневно выбрасываем? Куда едет мусоровоз и что случается с обёрткой от шоколадки после того, как ты выкинул её в урну? Чаще всего мы просто выбрасываем ненужные вещи, тем самым всё больше и больше загрязняя окружающую природу. Но иногда мир можно изменить к лучшему, просто изменив свои привычки. Мы выбрали эту книгу для издания на русском языке, чтобы дети и взрослые могли разобраться, как именно устроен мир вещей вокруг нас, откуда мы получаем воду, одежду, продукты, книги и мобильные телефоны. А ещё для того, чтобы помочь миру стать чище. Мы надеемся, что читатель осознает масштаб всей мусорной проблемы в нашей стране и захочет на неё повлиять. И тогда мир станет лучше! Далеко ли можно уехать на бумажном велосипеде? И как съесть на обед свою ложку? Эта книга расскажет и покажет, как работает водоочистная станция, куда уходят пищевые отходы, как построить дом из переработанной бумаги и, самое главное, как избежать напрасной траты природных ресурсов и сохранить нашу планету для будущих поколений.', 'Have you ever wondered what happens to the candy wrapper you toss away, or where the garbage truck really goes? This eye-opening book explores the life cycle of everyday things—from water, clothes, and food to smartphones and paper. Discover how water treatment plants work, whether you could actually ride a bicycle made of paper, and how small changes in our daily habits can break the cycle of waste to protect the planet for the future.', 'Da li ste se ikada zapitali šta se dešava sa omotom od čokolade koji bacite u kantu ili kuda zapravo ide kamion za smeće? Ova fascinantna knjiga istražuje životni ciklus svakodnevnih stvari — od vode, odjeće i hrane do mobilnih telefona. Otkrijte kako rade postrojenja za prečišćavanje vode, može li se voziti bicikl od papira i kako jednostavna promjena navika može pomoći očuvanju naše planete.', 'Загляните за кулисы мусорного ведра и узнайте, как спасти планету и можно ли на самом деле прокатиться на бумажном велосипеде!', 'Peek inside your trash can to discover how everyday stuff gets made, recycled, and how we can save the planet one wrapper at a time!', 'Zavirite s nama iza kulisa kante za smeće i saznajte kako pametnim navikama možemo spasiti planetu i udahnuti novi život starim stvarima!', '/covers/DP-0792.webp', '#3b7a57', 'nonfiction', 'ru', 'available', 'Категория: про экологию', '["real"]', '["ecology","recycling","science","nature","environment"]', 1792836322699, 1792845677484);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прощай-нефть--793', 'DP-0793', 'Прощай, нефть!', 'Goodbye Oil!', 'Zbogom, nafto!', 'Харриет Рассел', 'Harriet Russell', 'Harriet Russell', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Иллюстрированная книга о том, как добывают нефть, как мы можем уменьшить нашу зависимость от нее, почему нам стоит перейти на альтернативные способы добычи топлива и уделять больше внимания проблеме раздельного сбора и переработки мусора. Нефть, как известно, - невозобновляемый ресурс. Но откуда она берется? Как ее производят? И что будет, если она закончится? На страницах книги автор поднимает все эти вопросы и предлагает изменить наши привычки, чтобы в один день нам всем не пришлось действительно попрощаться с нефтью.', 'An engaging, illustrated guide exploring how oil is extracted, why the world has become so reliant on it, and what will happen when it inevitably runs out. Through clear explanations and witty illustrations, Harriet Russell invites young readers to discover renewable energy alternatives, embrace recycling, and adopt everyday eco-habits to protect our planet.', 'Zanimljiv i ilustrovan vodič koji objašnjava kako se nafta vadi, zašto je svijet postao toliko zavisan od nje i šta će se desiti kada je nestane. Kroz jasna objašnjenja i duhovite crteže, Harijet Rasel podstiče mlade čitaoce da istraže obnovljive izvore energije, prihvate reciklažu i razviju ekološke navike za očuvanje naše planete.', 'Остроумный и наглядный эко-гид, который вдохновит юных изобретателей беречь планету и искать зелёные альтернативы чёрному золоту!', 'A witty and vivid eco-guide that will inspire young inventors to protect the planet and look beyond black gold to a greener future!', 'Duhovit i slikovit eko-vodič koji će inspirisati mlade pronalazače da čuvaju planetu i potraže zelene alternative crnom zlatu!', '/covers/DP-0793.webp', '#2b4a41', 'nonfiction', 'ru', 'available', 'Категория: про экологию', '["real","funny"]', '["ecology","science","green energy","recycling","planet"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-пальмы-на-северном-полюсе-бол-794', 'DP-0794', '«Пальмы на Северном полюсе. Большой рассказ об изменении климата»', 'Palm Trees at the North Pole: The Big Story of Climate Change', 'Palme na Sjevernom polu: Velika priča o klimatskim promjenama', 'Марк тер Хорст', 'Marc ter Horst', 'Marc ter Horst', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Тема изменения климата на Земле часто вызывает жаркие споры. Спорят политики, эксперты в публицистических передачах, спорят коллеги на работе или члены семей. Действительно, вопрос этот очень сложный, и сходу в нем не разобраться. Нидерландский детский писатель и популяризатор науки Марк тер Хорст несколько лет собирал сведения об истории климатических изменений и решил поделиться с читателями полученными знаниями, попутно рассказывая о физике современных п прошлых изменений климата, об ученых-климатологах, о том, какой климат нас ждет в будущем и придется ли нам менять из-за климатических зименений свой образ жизни. Книга написана легко и с юмором, при этом она заставит задуматься об этой проблеме не только детей, но и взрослых.', 'Climate change sparks heated debates across politics, media, and family dinner tables. Dutch science writer Marc ter Horst spent years gathering facts about Earth''s changing climate to break down this complex topic into an engaging, humorous, and accessible guide for curious minds. He explores the physics behind weather shifts, introduces pioneering climate scientists, and imagines what the future holds—and how our daily habits might need to evolve.', 'Pitanje klimatskih promjena na Zemlji često izaziva burne rasprave među političarima, stručnjacima i unutar porodica. Holandski pisac za djecu i popularizator nauke Mark ter Horst godinama je prikupljao podatke o istoriji promjena klime i stvorio duhovit, pristupačan i poučan vodič kroz ovu složenu temu. Knjiga objašnjava fiziku klimatskih fenomena, predstavlja naučnike i istražuje kako bi naša budućnost i svakodnevne navike mogle izgledati.', 'Загляните в эту на удивление весёлую и доступную энциклопедию, чтобы узнать, действительно ли на Северном полюсе когда-то росли пальмы и что ждёт нашу планету дальше!', 'Dive into this surprisingly witty and crystal-clear climate guide to find out if palm trees truly once grew at the North Pole and what that means for our future!', 'Zavirite u ovaj iznenađujuće duhovit i jasan vodič kroz klimu da biste otkrili jesu li na Sjevernom polu zaista nekada rasle palme i šta to znači za našu planetu!', '/covers/DP-0794.webp', '#2d8a86', 'nonfiction', 'ru', 'available', 'Категория: про экологию', '["real","funny"]', '["экология","климат","научпоп","планета земля","природа"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-дети-против-пластика--795', 'DP-0795', '«Дети против пластика»', 'Kids Fight Plastic', 'Djeca protiv plastike', 'Мартин Дори', 'Martin Dorey', 'Martin Dori', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Могут ли дети взять на себя такую сложную миссию, как борьба с пластиком? Или такое дело им не по плечу? Океан задыхается от мусорных островов, огромные свалки подступают к нашим городам, и даже в озерах Антарктиды обнаружен микропластик. Ни один супергерой не сумеет мгновенно избавить мир от накопившихся отходов. Наверное, без волшебства тут не обойтись... Удивительно! Самая большая трудность в борьбе с мусором — бросить вызов собственным привычкам, а самая большая победа — это когда друзья и близкие люди поверят тебе и последуют твоим экосоветам. Книга «Дети против пластика» поможет вдохновить на новые экологические подвиги не только маленьких читателей, но и их родителей и друзей. Кое-что из того, что вы найдете на ее страницах, будущие экологи изучают в университетах. Загрязнение пластиком — это, пожалуй, самая заметная составляющая глобальной проблемы отходов, но, разумеется, не стоит забывать и о других видах мусора.', 'Can children really tackle a challenge as vast as global plastic pollution? Absolutely! From floating trash islands in our oceans to microplastics in remote polar lakes, the crisis is huge, but every real superpower starts with simple daily habits. Packed with engaging, accessible missions, this guide turns young readers and their families into real-life eco-heroes equipped to cut waste and protect the planet.', 'Mogu li djeca zaista riješiti ogroman problem zagađenja plastikom? I te kako! Od gigantskih ostrva otpada u okeanima do mikroplastike u zabačenim jezerima, izazov djeluje zastrašujuće, ali svaka superherojska misija počinje malim svakodnevnim navikama. Kroz jasne i praktične zadatke, ova knjiga motiviše mlade čitaoce i njihove porodice da smanje otpad i postanu pravi zaštitnici prirode.', 'Готовы стать супергероями за пару минут в день и спасти океаны от пластикового нашествия?', 'Ready to become a two-minute superhero and rescue our oceans from the plastic invasion?', 'Jeste li spremni da postanete dvominutni eko-heroji i spasite okeane od najezde plastike?', '/covers/DP-0795.webp', '#1f8a70', 'nonfiction', 'ru', 'available', 'Категория: про экологию', '["real","friends"]', '["ecology","plastic","nature","planet","activism"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мусорный-остров-796', 'DP-0796', 'Мусорный остров', 'Plastic Island', 'Ostrvo smeća', '', 'Lee Myung-ae', 'Li Mjong-e', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Разноцветный остров посреди океана — зрелище на первый взгляд завораживающее. Яркий и красочный, он весь состоит из неведомых предметов разных форм и размеров. Для чего они? Съедобны ли? И можно ли на этом острове жить? 5 причин купить книгу «Мусорный остров»: Красочная, тонкая и нежная история о жизни тупика на мусорном острове; Ли Мёнэ — южнокорейская художница, лауреат международных премий, чьи книги издаются на 5 языках; Книга-помощник в первом разговоре об экологии с ребенком, а также об ответственности человека перед окружающим миром, перед населяющими его существами и будущими поколениями; История мусорного острова и его обитателей — пронзительное напоминание о том, как хрупок и уязвим наш мир; Книга рассказана от лица тупика и раскрывает множество опасностей, которые в себе таит мусорный остров.', 'A colorful island in the middle of the ocean might seem fascinating at first glance. Bright and vibrant, it is composed of strange objects of every shape and size. What are they for? Are they edible? And can anyone truly live here? Told from the poignant perspective of a little sea bird, this deeply moving picture book by award-winning South Korean author Lee Myung-ae serves as a gentle, tender introduction to ecology, plastic pollution, and our responsibility to protect the fragile natural world.', 'Šareno ostrvo usred okeana na prvi pogled djeluje očaravajuće. Jarko i raznobojno, sačinjeno je od neobičnih predmeta raznih oblika i veličina. Čemu služe? Da li su jestivi? I može li se na takvom ostrvu uopšte živjeti? Ispričana iz perspektive male morske ptice, ova dirljiva i nježna slikovnica nagrađivane južnokorejske autorke Li Mjong-e predstavlja predivan povod za prvi razgovor s djecom o ekologiji, plastici i očuvanju prirode.', 'Взгляните на проблему пластика глазами маленького тупика — эта пронзительная и завораживающе красивая книга никого не оставит равнодушным к судьбе океана.', 'See the plastic crisis through the innocent eyes of a little sea bird in this poignant, gorgeously illustrated ecological tale.', 'Pogledajte problem zagađenja plastikom očima jedne male ptice u ovoj dirljivoj i prelijepo ilustrovanoj ekološkoj priči.', '/covers/DP-0796.webp', '#3d8296', 'nonfiction', 'ru', 'available', 'Категория: про экологию', '["animals","real"]', '["экология","океан","пластик","птицы","природа"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('спасем-воду-вместе-учебник-юно-797', 'DP-0797', 'Спасем воду вместе. Учебник юного эколога', 'Save Water Together: A Young Ecologist''s Guidebook', 'Spasimo vodu zajedno: Priručnik za mlade ekologe', '', 'Water Family', 'Water Family', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Совсем недавно мы принимали воду как должное и не задумывались над опасностями, которые ей угрожают. Высыхание водоёмов, таяние ледников, мусор в мировом океане, загрязнение воды отходами промышленных предприятий – к сожалению, сейчас эти проблемы стали реальностью. Настал момент, когда необходимо действовать. Эта книга расскажет о том, как вода необходима человеку и природе, и что можно сделать для её защиты. Французские спортсмены из Water Family и российские эко-активисты объяснят, что каждый из нас может сделать для защиты воды. Ведь даже ребенок может внести свой вклад в сохранение чистой воды в масштабе целой планеты.', 'Not long ago, we took water for granted without thinking about the dangers threatening it. Vanishing reservoirs, melting glaciers, ocean plastic, and industrial pollution have all become stark realities. It is time to act. This book explains why water is essential to humans and nature, and how to protect it. French athletes from Water Family and Russian eco-activists show practical ways anyone can make a difference, proving that even a child can help safeguard the planet''s most vital resource.', 'Donedavno smo vodu uzimali zdravo za gotovo, ne razmišljajući o opasnostima koje joj prijete. Isušivanje vodenih tokova, topljenje glečera, plastični otpad u okeanima i industrijsko zagađenje postali su naša stvarnost. Vrijeme je za akciju! Ova knjiga objašnjava koliko je voda dragocjena čovjeku i prirodi te šta možemo preduzeti da je zaštitimo. Francuski sportisti iz organizacije Water Family i eko-aktivisti nude praktične korake, pokazujući da čak i dijete može dati ogroman doprinos očuvanju čiste vode na planeti.', 'Капля за каплей собирается океан — эта вдохновляющая книга научит беречь воду весело, осознанно и с пользой для всей планеты!', 'Drop by drop makes an ocean — this inspiring handbook shows that becoming a water guardian is not only vital, but surprisingly fun!', 'Kap po kap stvara okean — ovaj inspirativni priručnik uči djecu kako da čuvaju vodu lako, zabavno i na dobrobit cijele planete!', '/covers/DP-0797.webp', '#2388b6', 'nonfiction', 'ru', 'available', 'Категория: про экологию', '["real"]', '["ecology","water","nature","planet","activism"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-дела-земля--798', 'DP-0798', 'Как дела, Земля?', 'How Are You Doing, Earth?', 'Kako si, Zemljo?', 'Дюваль', 'Duval', 'Duval', '', 'Мир детства', NULL, NULL, 6, 16, 'middle', 'Книга "Как дела, Земля?" рассказывает детям школьного возраста об экологических проблемах Земли. Но делает это не скучно, а при помощи любопытных картинок и тестов. Лучше всего книгу характеризует цитата из Сент-Экзюпери: "Мы не наследуем землю предков, мы берем ее в долг у наших детей". Эта полезная книжка для классного или внеклассного чтения открывает серию книг "Этот огромный мир", в которую также входят другие книги - о том, как устроены средства массовой информации и о том, с какими трудностями приходится сталкиваться жителям больших городов.', 'The book ''How Are You Doing, Earth?'' introduces school-age readers to global ecological challenges—not with dry lectures, but through lively illustrations, engaging quizzes, and practical facts. It brings to life Saint-Exupéry’s timeless wisdom: ''We do not inherit the Earth from our ancestors; we borrow it from our children.'' A wonderful guide for curious minds ready to understand and protect our shared home.', 'Knjiga „Kako si, Zemljo?” upoznaje školarce sa ekološkim izazovima naše planete, i to ne kroz dosadna predavanja, već pomoću zabavnih ilustracija, kvizova i zanimljivih činjenica. Najbolje je opisuje misao Sent-Egziperija: „Zemlju nismo naslijedili od predaka, već smo je pozajmili od svoje djece.” Odličan vodič za mlade čuvare prirode.', 'Узнайте, почему у нашей планеты иногда «болит голова» и как каждый из нас может стать её заботливым супергероем!', 'Find out why our planet sometimes feels under the weather and how any kid can become its everyday superhero!', 'Saznajte zašto našu planetu ponekad „boli glava” i kako svako od nas može postati njen pravi zaštitnik!', '/covers/DP-0798.webp', '#3a7d44', 'nonfiction', 'ru', 'available', 'Категория: про экологию', '["real"]', '["ecology","planet earth","nature","environment","nonfiction"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-ничто-и-бесконечно-много-799', 'DP-0799', 'Тайна ничто и бесконечно много глупостей', 'The Mystery of Nothing and Endless Nonsense', 'Tajna ničega i beskrajno mnogo gluposti', 'Ян Паул Схюттен', 'Jan Paul Schutten', 'Jan Paul Schutten', 'Флоор Ридер', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Задумайся: Вселенная бесконечна и всеобъемлюща. Но когда-то ее не существовало. А что же было до нее? Неужели пустота? Но как из пустоты возникло все? И правда ли, что вселенных может быть бесконечно много? С помощью этой книги ты отправишься в путешествие во времени и увидишь, как выглядела Вселенная всего через миллионную долю триллионной доли триллион триллионной доли секунды после возникновения. Попутно ты узнаешь, что такое черные дыры, частицы и античастицы, бозон Хиггса и многое другое. Ты сможешь понять, что значит самая знаменитая формула в мире - E = mc2, каким может быть мир, где двадцать измерений, что случилось 14 сентября 2015 года, почему Вселенная похожа на черничный пирог и как этот пирог испечь. И хотя в этой книге объясняется далеко не все, она научит тебя задавать правильные вопросы. А правильно поставленный вопрос - это первый шаг на пути к ответу, который, возможно, найдешь именно ты.', 'Think about it: the universe is vast and all-encompassing, but once upon a time, it didn''t exist at all. What was there before? Could everything really have emerged from absolute nothingness? In this thrilling and witty dive into astrophysics and quantum mechanics, you will travel back to a tiny fraction of a second after the Big Bang. Along the way, you''ll discover black holes, antiparticles, the Higgs boson, and the true meaning of E = mc². You will explore worlds with twenty dimensions, find out why the cosmos resembles a blueberry pie, and learn how to ask the big questions that could one day change science forever.', 'Razmisli: univerzum je beskrajan i obuhvata sve, ali nekada uopšte nije postojao. Šta je bilo prije njega? Kako je iz potpunog ništavila nastalo sve? Kroz ovu uzbudljivu i duhovitu naučnu avanturu otputovaćeš u djelić sekunde nakon Velikog praska. Usput ćeš otkriti šta su to crne rupe, antičestice, Higsov bozon i čuvena formula E = mc². Saznaćeš kako bi izgledao svijet sa dvadeset dimenzija, zašto svemir podsjeća na pitu od borovnica i kako da postavljaš prava pitanja na koja bi upravo ti jednog dana mogao pronaći odgovor.', 'Приготовьтесь сломать голову и от души посмеяться: оказывается, сложнейшие тайны космоса и квантовой физики проще всего понять с помощью черничного пирога!', 'Get ready to stretch your mind and giggle: it turns out the deepest cosmic mysteries are best explained with a hearty dose of humor and a blueberry pie!', 'Spremite se za veliku mozgalicu i glasan smijeh: najdublje tajne kosmosa najlakše se shvataju uz dobar humor i pitu od borovnica!', '/covers/DP-0799.webp', '#24204b', 'nonfiction', 'ru', 'available', 'Категория: про космос', '["real","funny","adventure"]', '["space","physics","universe","science","big-bang"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вот-это-космос--800', 'DP-0800', 'Вот это космос!', 'Out of This World: The Great Space Book', 'Kakav svemir!', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', '', 'Речь', NULL, NULL, 6, 16, 'middle', 'Все, что описано в этой книге, происходит в далеком будущем - в 3001 году. Космические путешествия стали обычным делом, земляне живут и работают на астероидах, Марсе, Луне и даже на далеких звездах. Жители других планет больше не инопланетяне, а друзья и знакомые. Космические корабли, НЛО и автобусы курсируют со скоростью света (ну почти) - и вся галактика обожает пиццу! Занимайте места в школьном автобусе! Маури Куннас проведет увлекательную экскурсию по Солнечной системе. Незабываемые впечатления гарантированы!', 'Fast forward to the year 3001! Space travel has become as ordinary as a bus commute, and Earthlings happily live and work on asteroids, Mars, and the Moon. Extraterrestrials are simply everyday pals, starships zip along near lightspeed, and the entire galaxy shares an unstoppable love for pizza. Hop aboard the cosmic school bus as Mauri Kunnas takes curious young explorers on an unforgettable, laugh-out-loud tour across the Solar System!', 'Dobrodošli u daleku 3001. godinu! Putovanje svemirom postalo je sasvim uobičajena stvar, a Zemljani žive i rade na asteroidima, Marsu i Mjesecu. Bića s drugih planeta više nisu nepoznati vanzemaljci, već komšije i drugari, dok čitava galaksija obožava picu! Uskočite u školski svemirski autobus jer vas Mauri Kunas vodi na urnebesnu i poučnu ekskurziju kroz Sunčev sistem.', 'Пристегните ремни: школьный космобус отправляется на Марс, а на борту обещают бесконечную пиццу и фирменный юмор Маури Куннаса!', 'Buckle up your seatbelts: the cosmic school bus is heading for Mars with galaxy pizza and Mauri Kunnas''s signature quirky humor on board!', 'Vežite pojaseve: školski svemirski autobus polijeće ka Marsu, a na putu nas čekaju galaktička pica i neodoljivi humor Maurija Kunasa!', '/covers/cellImage_0_102.jpg', '#1c2b59', 'nonfiction', 'ru', 'available', 'Категория: про космос', '["funny","adventure","animals"]', '["space","solar system","future","aliens","picture book"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('космос-801', 'DP-0801', 'Космос', 'Space', 'Kosmos', 'Зина Сурова, Дмитрий Костюков', 'Zina Surova, Dmitry Kostyukov', 'Zina Surova, Dmitrij Kostjukov', '', 'издательский домик Дорофеевой', NULL, NULL, 6, 16, 'middle', '"Космос" - необычная книга! Она познавательна, как настоящая энциклопедия, и увлекательна, как весёлый комикс. У книги два автора: фотограф Дмитрий Костюков и художник Зина Сурова. Они вместе писали тексты и придумывали иллюстрации. Дмитрий много раз летал на Байконур, фотографировал старт и посадку космического корабля "Союз", сборку ракет и тренировки космонавтов. Зина делала иллюстрации в технике коллажа, соединяя фотографии, рисунки и комиксы на огромных листах бумаги. В процессе двухлетней работы над книгой авторы неоднократно консультировались с космонавтами.', '''Space'' is an extraordinary book: informative as an encyclopedia and thrilling as a comic strip! Created by photographer Dmitry Kostyukov and artist Zina Surova, it blends real photographs from the Baikonur Cosmodrome—showing rocket assemblies, launches, and cosmonaut drills—with dynamic collages and comics. Crafted over two years in consultation with real space travelers, it brings the marvels of space exploration to life.', '„Kosmos“ je izuzetna knjiga: poučna poput prave enciklopedije i uzbudljiva poput stripa! Autori, fotograf Dmitrij Kostjukov i umjetnica Zina Surova, osmislili su je zajedno tokom dvogodišnjeg rada uz savjete pravih kosmonauta. Dmitrij je fotografisao lansiranja raketa i treninge na Bajkonuru, dok je Zina od fotografija i crteža stvorila upečatljive kolaže.', 'Настоящий путеводитель на орбиту: здесь фотографии с Байконура и комиксы объясняют устройство ракет лучше любого учебника!', 'A brilliant visual journey into orbit where real Baikonur photographs and vibrant collage comics explain rocket science better than any textbook!', 'Pravi vodič u orbitu gdje fotografije sa Bajkonura i strip-kolaži objašnjavaju tajne raketa bolje od bilo kog udžbenika!', '/covers/DP-0801.webp', '#1e2952', 'nonfiction', 'ru', 'available', 'Категория: про космос', '["real","adventure"]', '["space","cosmonauts","rockets","science","comics"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('космическое-приключение-802', 'DP-0802', 'Космическое приключение', 'Tatu and Patu: Space Adventure', 'Tatu i Patu: Svemirska avantura', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', '"Вперед, вверх и в космос! - крикнул Тату, когда межзвездный космический корабль "Бананас", или МКК "Бананас", взмыл в небо. Звездные пилоты А. Т. Лантич, или Тату, и Термо Бокс, или Пату, отправились в космическую даль проверить, все ли кольца Сатурна на месте. Неизвестная сила вовлекает их в невероятное, захватывающее приключение, в котором планеты исчезают, а орбиты меняют свои траектории. Только отвага и смекалка звездных пилотов могут спасти Вселенную.Космическое приключение разворачивается со скоростью света и проникает в самые потаенные уголки читательских галактик"', '"Up, up and into space!" shouts Tatu as the interstellar starship Bananas blasts off into the starry sky. Star pilots Tatu and Patu head into the cosmic unknown to check whether all of Saturn''s rings are safely in place. Soon, a mysterious force plunges them into a wild, whirlwind escapade where planets vanish and orbits go haywire. Only the bravery and sheer ingenuity of our eccentric pilots can save the Universe! A hilarious, high-speed galactic journey that turns space science into pure fun.', '"Naprijed, u visine i pravo u svemir!" povikao je Tatu dok je međuzvjezdani brod "Bananas" jurio ka zvijezdama. Zvjezdani piloti Tatu i Patu kreću u kosmička prostranstva da provjere jesu li svi Saturnovi prstenovi na broju. Misteriozna sila uvlači ih u nevjerovatnu avanturu u kojoj planete nestaju, a orbite mijenjaju putanje. Samo hrabrost i domišljatost neustrašivih junaka mogu spasiti univerzum!', 'Пристегните ремни на борту звездолета «Бананас»: Тату и Пату спасают кольца Сатурна и всю Вселенную с фирменным финским юмором!', 'Fasten your seatbelts aboard the starship Bananas: Tatu and Patu are on a mission to save Saturn''s rings and the entire galaxy with signature Finnish wit!', 'Vežite pojaseve na svemirskom brodu "Bananas": Tatu i Patu kreću u urnebesnu misiju spasavanja kosmosa uz pregršt smijeha!', '/covers/cellImage_0_104.jpg', '#1f3b73', 'nonfiction', 'ru', 'available', 'комикс', '["funny","adventure"]', '["space","astronomy","humor","planets","inventions"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('энциклопедия-балбесов-803', 'DP-0803', 'Энциклопедия балбесов', 'The Encyclopedia of Goof-Offs, Dropouts, and Other Geniuses', 'Enciklopedija neznalica i ostalih genija', '', 'Unknown', 'Nepoznati autor', 'Серж Блок', 'Clever', NULL, NULL, 6, 16, 'middle', '«Энциклопедия балбесов, неучей и прочих гениев» расскажет Вам о детстве знаменитых талантливых людей. Все мы прекрасно знаем, что Пикассо — великий художник, Наполеон покорил всю Европу, Эйнштейн сформулировал теорию относительности, а Агата Кристи — самая знаменитая писательница детективов всех времен и народов. Но мало кому известно, что Пикассо носил в школу голубя, чтобы не скучать на уроках, Агате Кристи запрещали читать до восьми лет (что не помешало ей научиться делать это еще в пять), а гений Эйнштейн не говорил до трех лет и в школе считался тугодумом. И что многие выдающиеся люди в детстве отличались ужасным поведением. Со временем история увенчала их лаврами. Но это живые люди, биографии которых более увлекательны, чем любой приключенческий роман. Приглашаем вас окунуться в их детство и юность, почувствовать дыхание истории и попытаться понять, почему они стали великими.', 'The Encyclopedia of Goof-Offs, Dropouts, and Other Geniuses shares the childhood stories of famous luminaries. We all know Picasso as a master artist, Napoleon as a conqueror, Einstein as the father of relativity, and Agatha Christie as the queen of mystery. Yet few know Picasso snuck a live pigeon into school to fend off boredom, Christie was forbidden to read until age eight (which didn''t stop her from reading at five), and Einstein didn''t speak until age three and was considered a slow thinker. Many brilliant minds were rebellious misfits as kids, and their true stories are more thrilling than any fiction novel.', '„Enciklopedija neznalica, neradnika i ostalih genija“ otkriva djetinjstvo slavnih i talentovanih ličnosti. Svi znamo da je Pikaso bio veliki slikar, Napoleon osvajač, Ajnštajn tvorac teorije relativnosti, a Agata Kristi kraljica krimića. Ipak, malo ko zna da je Pikaso nosio goluba u školu da mu ne bude dosadno, Agati Kristi su branili da čita do osme godine (što je nije spriječilo da nauči već sa pet), a Ajnštajn nije progovorio do treće godine i smatran je usporenim učenikom. Mnogi velikani su u djetinjstvu bili nemirni i neposlušni, a njihove prave biografije uzbudljivije su od bilo kog avanturističkog romana.', 'Утешительное и невероятно весёлое доказательство того, что двойка в дневнике и проделки на уроках вовсе не мешают вырасти настоящим гением!', 'A delightfully reassuring proof that bad grades and goofing off in class won''t stop you from becoming an absolute genius!', 'Utješno i urnebesno svjedočanstvo o tome da loša ocjena ili nestašluci na času uopšte ne smetaju da jednoga dana postaneš genije!', '/covers/DP-0803.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: Энциклопедии', '["funny","real"]', '["biography","history","great people","childhood","humor"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('монстры-и-чудовища-804', 'DP-0804', 'Монстры и чудовища', 'The Atlas of Monsters: Mythical Creatures from Around the World', 'Atlas čudovišta: Mitska bića iz cijelog svijeta', 'Сандра Лоуренс', 'Sandra Lawrence', 'Sandra Lorens', 'Стюарт Хилл', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Тайны этой книги спрятаны на пожелтевших страницах карт и дневников, найденных в старинной английской усадьбе. Быть библиотекарем не так спокойно, как может показаться: вас может затянуть в историю, из которой вы не сможете выбраться! В книге собраны 227 самых странных фантастических существ и монстров. Переходите на следующий уровень! Для старшего школьного возраста.', 'Hidden within yellowed maps and journals discovered in an old English manor lie the secrets of this book. Being a librarian isn''t always quiet—sometimes you stumble into a legendary mystery you can''t escape! This beautifully illustrated compendium catalogues 227 of the world''s most bizarre mythical creatures, folklore beasts, and legendary monsters.', 'Tajne ove knjige skrivene su na požutjelim stranicama mapa i dnevnika pronađenih u starom engleskom imanju. Biti bibliotekar nije uvijek mirno: ponekad upadnete u priču iz koje nema lakog izlaza! Ovaj raskošni vodič predstavlja 227 najneobičnijih mitskih bića i čudovišta iz folklora cijelog svijeta.', 'Вооружитесь лупой и смелостью: этот великолепный иллюстрированный атлас откроет 227 чудовищ со всего света и докажет, что библиотечные архивы полны захватывающих тайн!', 'Grab a magnifying glass and your bravest face: this stunning monster atlas unearths 227 legendary beasts and proves that dusty library archives hold wild mysteries!', 'Naoružajte se lupom i hrabrošću: ovaj prelijepi atlas otkriva 227 mitskih čudovišta i dokazuje da su bibliotečke arhive pune nevjerovatnih tajni!', '/covers/DP-0804.webp', '#2c4c47', 'nonfiction', 'ru', 'available', 'Категория: Энциклопедии', '["adventure","magic","spooky"]', '["monsters","mythology","maps","encyclopedia","legends"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('герои-мифов-и-легенд-805', 'DP-0805', 'Герои мифов и легенд', 'Heroes of Myths and Legends', 'Heroji mitova i legendi', 'Сандра Лоуренс', 'Sandra Lawrence', 'Sandra Lorens', 'Стюарт Хилл', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Начните распутывать загадочный клубок из странных символов, спрятанных на картах. Понадобится не только знания, но весь запас эмоционального интеллекта, внимательность, усидчивость и … свободное время. Ведь вы не сможете оторваться от этой книги. Для старшего школьного возраста.', 'Unravel the mysterious tangle of strange symbols hidden across ancient maps and lore. You will need knowledge, keen observation, patience, and plenty of free time—because putting this mythological quest book down is practically impossible!', 'Počnite da odmotavate tajanstveno klupko neobičnih simbola skrivenih na mapama i drevnim pričama. Biće vam potrebno znanje, oštro oko, strpljenje i dosta slobodnog vremena — jer je ovu knjigu nemoguće ispustiti iz ruku!', 'Приготовьтесь к захватывающему квесту по древним легендам — оторваться от этих карт и таинственных шифров просто невозможно!', 'Grab your magnifying glass and get ready for an epic mythological quest—you won''t be able to look away from these cryptic maps!', 'Pripremite se za uzbudljivu mitološku avanturu punu zagonetki — od ovih tajanstvenih mapa je prosto nemoguće odvojiti se!', '/covers/DP-0805.webp', '#2e4a62', 'nonfiction', 'ru', 'available', 'Категория: Энциклопедии', '["adventure","magic"]', '["myths","legends","maps","puzzles","history"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('метро-подземный-город-806', 'DP-0806', 'Метро. Подземный город', 'Metro: The Underground City', 'Metro: Podzemni grad', 'Наталия и Василий Волковы', 'Natalia Volkova, Vasily Volkov', 'Natalija Volkova, Vasilij Volkov', 'Кондратова Наталия', 'Настя и Никита', NULL, NULL, 6, 16, 'middle', 'Эта книга расскажет не только об истории строительства Московского метрополитена, который считается самым красивым, но и о том, как устроен этот подземный мир - огромный, сложный и очень интересный. Кто придумал первые "подземки", как проектировалось и строилось метро, что такое "плывун" и "проходческий щит", откуда под землю попадает свежий воздух, где ночуют поезда? Эта книга - уникальное путешествие по самым красивым станциям, по знаменитым метрополитенам больших городов, путешествие сквозь землю и сквозь время. Для младшего и среднего школьного возраста.', 'This fascinating guide takes readers on an engineering adventure into the vast world hidden beneath our feet. From the earliest underground tracks to the world-renowned palatial stations of the Moscow Metro, discover how tunnels are carved out, where sleeping trains go at night, how fresh air flows deep subterranean, and what wonders lie beneath bustling city streets.', 'Ova fascinantna knjiga vodi mlade čitaoce na uzbudljivo inženjersko putovanje kroz ogroman svijet skriven ispod naših nogu. Od prvih podzemnih pruga do raskošnih stanica nalik na dvorce, saznajte kako se buše tuneli, gdje vozovi noće, odakle pod zemljom svjež vazduh i koje se sve tajne kriju ispod gradskog asfalta.', 'Загляните под асфальт мегаполиса — там прячется настоящий сверкающий город со своими тайнами, поездами и чудесами инженерии!', 'Peek beneath the city streets to discover a bustling, secret world of tunnels, train depots, and marvels of engineering!', 'Zavirite ispod gradskog asfalta i otkrijte čitav tajni svijet tunela, palata od mermera i pravih inženjerskih čuda!', '/covers/DP-0806.webp', '#b93226', 'nonfiction', 'ru', 'available', 'дома', '["real","adventure"]', '["metro","trains","engineering","transport","architecture"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пособие-по-бессмертию-для-начи-807', 'DP-0807', 'Пособие по бессмертию для начинающих', 'A Beginner''s Guide to Immortality: From Alchemy to Avatars', 'Vodič kroz besmrtnost za početnike', 'Мария Бирмингем', 'Maria Birmingham', 'Marija Birmingem', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Вы хотите перехитрить смерть? Если ответ "да", то именно сейчас в ваших руках нужная вещь - путеводитель по бессмертию! Эта книга расскажет, на какие свершения были способны люди в стремлении обрести вечную жизнь... или как безумные мечтатели находили смерть в бесплодных поисках. "За последние два столетия продолжительность жизни увеличилась более чем вдвое. Человек, родившийся в начале XIX в., едва мог надеяться пересечь 35-летний рубеж, а сегодня средняя продолжительность жизни в развитой стране составляет 78 лет. Однако продлить жизнь на несколько десятилетий - это еще куда ни шло. Но жить вечно?.. В общем, устраивайтесь поудобнее и слушайте, как человечество пыталось (и продолжает пытаться) раскрыть секрет бессмертия". Для среднего и старшего школьного возраста', 'Do you want to outsmart death? If so, you''re holding the perfect manual! Discover the wild, ingenious, and downright bizarre ways humans have attempted to live forever throughout history—from ancient elixirs of life and alchemy to futuristic cryonics, digital avatars, and cutting-edge genetic science. A witty, thought-provoking journey into humanity''s ultimate quest.', 'Želite li da nadmudrite smrt? Ako je odgovor potvrdan, držite u rukama pravi vodič! Ova knjiga istražuje na šta su sve ljudi bili spremni u potrazi za vječnim životom — od drevnih eliksira mladosti i alhemičarskih tajni do krionike, digitalnih avatara i moderne genetike. Duhovito, intrigantno i nevjerovatno poučno putovanje kroz vječitu ljudsku fascinaciju.', 'Захватывающее и ироничное исследование того, как человечество веками пыталось обмануть время — от философского камня до заморозки в жидком азоте!', 'A delightfully witty and fascinating look at how humans have spent centuries trying to outsmart time, from alchemy to cryonics!', 'Duhovito i fascinantno istraživanje vjekovnog ljudskog pokušaja da prevari vrijeme — od kamena mudrosti do digitalne svijesti!', '/covers/DP-0807.webp', '#4a3b68', 'nonfiction', 'ru', 'available', 'Категория: про медицину', '["real","funny"]', '["science","history","curious facts","philosophy","inventions"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('умираю-как-хочу-спросить-38-жи-808', 'DP-0808', 'Умираю как хочу спросить! 38 жизненно важных вопросов про смерть', 'Dying to Ask! 38 Vital Questions About Death', 'Umirem od želje da pitam! 38 životnih pitanja o smrti', 'Автор: Кантавелья Хуан Анна, Дьюти Эллен Иллюстратор: Антинори Андреа', 'Anna Juan Cantavella, Ellen Duthie, Andrea Antinori', 'Anna Juan Cantavella, Ellen Duthie, Andrea Antinori', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Когда умираешь, у тебя пропадают мысли? Откуда мне знать, что, когда я сплю, я не умер? Если я умру, что будет с моей приставкой? Смерть — это страшно? Правда, что когда отрубают голову, твое тело бегает без головы? Если умирает кто-то, кого ты любишь, сколько времени ты горюешь? В будущем появятся машины для оживления людей? Почему говорят «покойся с миром», а не «веселись с миром»? Две писательницы и один иллюстратор погружаются в тему и встречаются с 38 вопросами о смерти от девочек и мальчиков от 5 до 15 лет. Что они ответят? Эта нежная, без предрассудков книга, строгая и странным образом веселая, приглашает к разговорам, размышлениям и новым вопросам о смерти.', 'When you die, do your thoughts disappear? How do I know I''m not dead when I''m asleep? If I die, what happens to my video game console? Tackling 38 candid questions asked by children aged 5 to 15, two authors and an illustrator dive deep into mortality. Tender, honest, thoughtful, and surprisingly uplifting, this illustrated philosophy guide invites readers into open, fearless conversations about life, grief, and curiosity.', 'Kad umreš, nestaju li tvoje misli? Kako da znam da nijesam mrtav dok spavam? Šta će biti s mojom igračkom konzolom ako umrem? Kroz 38 iskrenih pitanja djece uzrasta od 5 do 15 godina, dvije autorke i ilustrator hrabro i nježno istražuju temu prolaznosti. Ova topla, otvorena i na neobičan način vedra knjiga podstiče važne razgovore i pomaže da bez straha promišljamo o životu i smrti.', 'Удивительно тёплый, честный и даже чуточку забавный разговор на сложную тему, где ни один детский вопрос не остаётся без уважительного ответа.', 'A surprisingly warm, frank, and gently humorous guide to life''s biggest mystery, treating every curious question with deep respect.', 'Iznenađujuće topao, iskren i blago duhovit vodič kroz veliku životnu temu, u kojem svako dječje pitanje dobija pažljiv odgovor.', '/covers/DP-0808.webp', '#388f86', 'nonfiction', 'ru', 'available', 'Категория: про медицину', '["real","funny"]', '["nonfiction","philosophy","death","emotions","questions"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('внимание-доктор--809', 'DP-0809', 'Внимание, доктор!', 'Attention, Doctor!', 'Pažnja, doktore!', 'Петр Свободны', 'Petr Svobodný', 'Petr Svobodni', 'Робин Краль', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Книга "Внимание, доктор!" - это не сюжетное повествование и не энциклопедия. Ее автор стремится лишь указать читателю на поворотные моменты в истории медицины. В этом ему помогают герои книги - обычная чешская семья. На протяжении семи глав мы вместе с ними узнаем, какие проблемы со здоровьем испытывали люди с древнейших времен до наших дней, знакомимся с революционны ми способами их решения, найденными по большей части уже в XIX и XX веках. Для среднего школьного возраста.', 'Neither a dry encyclopedia nor a simple story, "Attention, Doctor!" guides readers through turning points in the history of medicine alongside an ordinary Czech family. Across seven captivating chapters, readers learn about health challenges humans faced from antiquity to the present day and discover the revolutionary treatments and scientific breakthroughs pioneered mostly in the 19th and 20th centuries.', 'Knjiga „Pažnja, doktore!“ nije obična priča niti suva enciklopedija. Autor vodi mlade čitaoce kroz prelomne trenutke u istoriji medicine, a u tome mu pomaže jedna obična češka porodica. Kroz sedam poglavlja saznajemo sa kakvim su se zdravstvenim problemima ljudi suočavali od pradavnih vremena do danas i otkrivamo revolucionarna medicinska dostignuća nastala pretežno u XIX i XX vijeku.', 'Загляните в медицинский чемоданчик истории: вместе с забавной семьёй мы узнаем, как лечили людей в древности и как наука победила грозные болезни!', 'Peek inside history''s medical kit: join a lively Czech family to discover how doctors healed in the past and how modern science conquered terrible diseases!', 'Zavirite u ljekarsku torbu istorije: sa jednom vedrom češkom porodicom otkrijte kako su se ljudi liječili u prošlosti i kako je nauka pobijedila opake bolesti!', '/covers/DP-0809.webp', '#2a7f82', 'nonfiction', 'ru', 'available', 'Категория: про медицину', '["real","adventure"]', '["medicine","history","science","human body","nonfiction"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('поразительные-паразиты-растени-810', 'DP-0810', 'Поразительные паразиты: растения, грибы, животные', 'Astounding Parasites: Plants, Fungi, Animals', 'Zapanjujući paraziti: biljke, gljive, životinje', '', 'Unknown', 'Nepoznati autor', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', '«Ну и паразит же ты!» – говорит хозяин своему коту, утащившему со стола сосиску. «Паразиты окаянные!» – кричит старушка птицам, клюющим ягоды на огороде. Да мы часто используем это слово, не думая о его научном смысле. Но для учёных «паразит» совсем не ругательство, не прозвище, а серьёзный научный термин. В биологии так именуются организмы, живущие за счёт других. Мы окружены паразитами со всех сторон, хотя порой и не подозреваем об этом. Они всюду: в воде и на суше, в диком лесу и в современном городе. Иногда и внутри нас самих! Кого только нет в этом огромном сообществе! Растения и грибы, черви и моллюски, насекомые и раки. Есть даже рыбы, птицы и звери. Все они очень разные, но всех объединяет одна общая черта – стремление пожить за чужой счёт. Мир паразитов фантастически необычен – словно мир инопланетян, чудом оказавшихся на нашей планете. Нам зачастую трудно понять их вкусы и привычки. Трудно вообще принять само их существование. Но это часть нашей природы. Это вполне земные твари и в какой-то степени наши эволюционные родичи. Просто они пошли другим путём. Многие спросят: «Зачем вообще надо задумываться об этой гадости?» Не будем обобщать, паразиты – это далеко не всегда гадость. Например, вряд ли кто-то назовёт гадостью омелу, с которой связаны традиции многих народов. И повернётся ли язык называть гадостью романтичную кукушечку, воспетую в стихах и песнях? А ведь она тоже паразит. Как, вы об этом не знали? Или вот грибы, вырастающие паразитическим образом, но приносящие нам, людям, пользу. Берёзовый трутовик, например, он же чага, служит сырьём для противоопухолевых препаратов. Кордицепс, паразитирующий на некоторых видах насекомых, также служит сырьём для изготовления лекарств. Про пенициллин и говорить нечего, этот грибок-паразит, совершивший переворот в медицине, известен всем. И примеров таких необыкновенных паразитов можно привести ещё много. О том, как живут паразиты, зачем они нужны в природе и что могут дать людям, вы узнаете из этой книги. Кстати, первой детской книги в России на подобную тему!', 'We often use the word ''parasite'' as a lighthearted insult, but in biology, it is a fascinating scientific phenomenon: creatures that survive at the expense of others. They are everywhere—on land, deep in the water, in city parks, and even inside our bodies! From romantic mistletoe and mischievous cuckoos to medicinal fungi like chaga and penicillin, parasites are far more diverse, ingenious, and beneficial than we think. This engaging popular science book invites curious minds on an unforgettable journey into one of nature''s most bizarre yet vital realms.', 'Riječ „parazit” često koristimo kao prijekor ili šalu, ali u biologiji je to fascinantan naučni pojam za bića koja žive na račun drugih. Oni su svuda oko nas — na kopnu, pod vodom, u gradovima, pa čak i u našim tijelima! Od romantične imele i dovitljive kukavice, pa sve do ljekovitih gljiva poput čage i penicilina, paraziti su mnogo raznovrsniji, lukaviji i korisniji nego što zamišljamo. Ova uzbudljiva enciklopedija otkriva najnevjerovatnija stvorenja koja dokazuju koliko je priroda čudesno povezana.', 'Забудьте слово-ругательство: перед вами захватывающий гид по самым хитрым, странным и порой чрезвычайно полезным соседям нашей планеты!', 'Forget the playground insult: here is a fascinating guide to the cleverest, weirdest, and surprisingly useful freeloaders on Earth!', 'Zaboravite na uvredu: ovo je uzbudljiv vodič kroz najlukavije, najneobičnije i nevjerovatno korisne komšije na našoj planeti!', '/covers/DP-0810.webp', '#5b8c32', 'nonfiction', 'ru', 'available', 'Категория: про медицину', '["real","animals","spooky"]', '["biology","parasites","nature","science","insects"]', 1792836322699, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хворые-истории-811', 'DP-0811', 'Хворые истории', 'Sick Stories: Plagues, Bugs, and Outbreaks Through History', 'Zarazne priče: Istorija kuge, virusa i epidemija', 'Гося Кулик, Томек Жарнецкий', 'Gosia Kulik, Tomek Żarnecki', 'Gosja Kulik, Tomek Žarnecki', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Похожи ли вирусы на зомби? Можно ли полюбить вшей? Кто придумал использовать болезни в качестве оружия? Зачем "чумному доктору" клюв? Как полиомиелит помог поймать Усаму бен Ладена? Эта книга - не скучная энциклопедия и не сухой справочник, на ее страницах вы можете найти все: и практические советы, и исторические анекдоты, узнаете о вакцинации и опасных для жизни похоронных обрядах. Пятнадцать вирусов и бактерий. Пятнадцать смертельных напастей. Как с ними боролись наши предки - и что знаем о них мы? Вот же зараза! Научный редактор и автор главы о коронавирусе Алексей Паевский. Для среднего школьного возраста.', 'Are viruses a bit like zombies? Can anyone ever love head lice? Why did plague doctors wear beak masks, and how did polio help track down Osama bin Laden? Far from a dry textbook, this engaging book dives into fifteen notorious bugs and bacteria, sharing bizarre historical trivia, daring medical discoveries, and practical science about vaccines and deadly outbreaks.', 'Da li su virusi nalik na zombije? Može li iko voljeti vaši? Zašto je ljekar u doba kuge nosio masku s kljunom i kako je dječja paraliza pomogla u hvatanju Osame bin Ladena? Ova knjiga nije suvoparna enciklopedija, već uzbudljivo putovanje kroz petnaest smrtonosnih zaraza, istorijske anegdote i naučnu borbu čovjeka protiv mikroba.', 'Захватывающий и местами жутковатый путеводитель по эпидемиям и микробам, от которого просто невозможно оторваться!', 'A delightfully gross and fascinating romp through the history of deadly plagues, odd medicine, and stubborn viruses.', 'Fascinantno i pomalo jezivo putovanje kroz istoriju epidemija i medicine od kojeg se nećete moći odvojiti!', '/covers/DP-0811.webp', '#4a7c59', 'nonfiction', 'ru', 'available', 'Категория: про медицину', '["real","spooky","funny"]', '["science","medicine","history","viruses","biology"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('что-там-внутри-путеводитель-по-812', 'DP-0812', 'Что там внутри? Путеводитель по нашему мозгу', 'What''s Inside? A Guide to Our Brain', 'Šta je unutra? Vodič kroz naš mozak', 'Мартинш Изабель Миньош, Педроза Мария Мануэль', 'Isabel Minhós Martins, Maria Manuel Pedrosa', 'Izabel Minjoš Martins, Marija Manuel Pedrosa', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Сегодня мы знаем, что наши мысли, чувства, решения, озарения — результат работы мозга во взаимодействии с другими органами и частями тела. Но как рождается мысль? Как функционирует мозг? Как сохраняет способность к обучению вплоть до старости? Как мозг чувствует, изобретает, творит и делает каждого из нас уникальной и неповторимой личностью? Книга «Что там внутри?» написана при участии команды нейробиологов, философов и психологов. Её авторы исследуют эволюцию мозга человека от рождения до старости, открывают невероятную реальность, построенную с помощью чувств, объясняют, как мы учимся, принимаем решения и действуем и как мы связаны с другими людьми и другими мозгами. И если, как утверждается в этой книге, на развитие мозга влияет любой жизненный опыт, мы надеемся, что знакомство с ней сделает ваш мозг еще более любознательным и счастливым! Несколько лет назад в Португалии, а затем на русском в «Самокате» вышла книга об удивительном мире природы— «Шагни за порог. Путеводитель по природе». За ней авторы и издатели решили сделать ответную книгу — про то, как важно заглянуть куда-нибудь внутрь. Но о чем могла бы быть эта книга? О человеческом теле? О тайнах, скрытых в центре Земли? Но больше других авторов вдохновила идея написать книгу о мозге, чтобы помочь самим себе и читателям лучше понять этот удивительный феномен, благодаря которому мы имеем возможность чувствовать, помнить, изучать, сравнивать, принимать решения, действовать, творить... (список глаголов бесконечен). К работе над книгой авторы привлекли большую команду экспертов. Их специализации, регалии, тезисы также перечислены в книге. Также читатели найдут в конце книги и большой список вышедшей на русском литературы о работе мозга, видеолекций, статей и ресурсов на эту тему.', 'Created in collaboration with neuroscientists, philosophers, and psychologists, this captivating book takes readers on an incredible voyage inside the human head. Discover how thoughts and feelings are born, how memories are stored, why we dream, and what makes every single personality truly unique. From birth through old age, our brain constantly learns, creates, and reshapes itself—and reading this fascinating, beautifully illustrated guide is guaranteed to make your own brain work with even greater curiosity and joy!', 'Stvorena u saradnji sa neurobiolozima, filozofima i psiholozima, ova očaravajuća knjiga vodi čitaoce na uzbudljivo putovanje u unutrašnjost ljudske glave. Saznajte kako se rađaju misli i osjećanja, kako pamtimo, zašto maštamo i šta je to što svakoga od nas čini potpuno jedinstvenom ličnošću. Od rođenja pa sve do starosti naš mozak neprestano uči i stvara nove veze, a druženje sa ovim predivno ilustrovanim vodičem učiniće da vaš mozak postane još radoznaliji i srećniji!', 'Грандиозная и наглядная экспедиция в самый загадочный уголок вселенной — собственную голову!', 'A vibrant, eye-opening expedition into the most mysterious corner of the universe—your very own brain!', 'Uzbudljiva i slikovita ekspedicija u najtajanstveniji kutak univerzuma — tvoju sopstvenu glavu!', '/covers/DP-0812.webp', '#e98a35', 'nonfiction', 'ru', 'available', 'Категория: про медицину', '["real","adventure"]', '["brain","human body","science","neuroscience","nonfiction"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('убийственный-стиль-813', 'DP-0813', 'Убийственный стиль', 'Killer Style: The Dark History of Fashion', 'Ubitačni stil', 'Элисон Мэтьюс-Дэвид', 'Alison Matthews David', 'Alison Metjuz-Dejvid', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Тот, кто стремится быть стильным и модным, подчас подвергает себя смертельной опасности. Не веришь? Прочитай эту книгу, и узнаешь про зеленый цвет — убийцу, про травмы из-за неудобных юбок и обуви, про тех, кто лишился жизни, производя одежду, и о многих других случаях, когда мода калечила людей. В общем, эта книга — предупреждение для всех модников. Для среднего и старшего школьного возраста.', 'Those who strive to be chic and fashionable sometimes put their very lives at risk. Discover the shocking history of lethal arsenic green dyes, perilous hoop skirts, hazardous footwear, and the tragic price paid by garment workers throughout history. A chillingly fascinating warning for every fashion lover!', 'Oni koji žele da budu moderni i u trendu ponekad stavljaju svoj život na kocku. Pročitajte ovu knjigu i otkrijte priče o smrtonosnoj zelenoj boji punoj arsena, opasnim krinolinama, obući koja sakati i radnicima koji su gubili živote stvarajući garderobu. Fascinantno i jezivo upozorenje za sve ljubitelje mode.', 'Думаете, мода безобидна? Загляните под подол истории и узнайте, почему красота буквально требовала смертельных жертв!', 'Think fashion is harmless? Peek behind the catwalk of history to see how beauty literally demanded deadly sacrifices!', 'Mislite da je moda bezazlena? Zavirite iza kulisa istorije i saznajte kako je ljepota nekada doslovno zahtijevala smrtonosne žrtve!', '/covers/DP-0813.webp', '#1b4d3e', 'nonfiction', 'ru', 'available', 'Категория: про медицину', '["real","spooky"]', '["fashion","history","nonfiction","curiosities","science"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хильда-и-твиг-прогулка-под-дож-814', 'DP-0814', 'Хильда и Твиг, прогулка под дождем', 'Hilda and Twig: Hide from the Rain', 'Hilda i Tvig: Šetnja po kiši', '', 'Luke Pearson', 'Luk Pirson', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Новая серия о приключениях Хильды и Твига еще до переезда в Тролльберг. История, в которой безобидная прогулка под дождем приносит чешуйчатые неприятности. Кажется, маленькому лисоленю придется набраться храбрости и спасти подругу... Хильда и Твиг не сидят дома, даже если за окном дождь. Каждый день они отправляются исследовать окрестности: скалы, пещеры, водопады... Но однажды прогулку прерывает сильная гроза, и друзьям приходится укрыться внутри таинственного кургана. Твиг быстро понимает: здесь совсем не безопасно. Маленький лисолень никогда не считал себя смельчаком, но теперь ему придется набраться храбрости, чтобы спасти лучшую подругу от больших чешуйчатых неприятностей. Эта история о том, что настоящая смелость — это готовность преодолеть страх ради того, кто тебе дорог. Даже самый осторожный из нас способен на подвиг, если рядом оказался тот, кто нуждается в помощи.', 'Before they ever moved to Trollberg, Hilda and her faithful deerfox Twig set out to explore the wilderness no matter the weather. But when a sudden thunderstorm traps them inside a mysterious mound, Twig realizes they are not alone. To protect his best friend from scaly trouble lurking in the dark, this tiny, cautious deerfox must summon every ounce of courage. A heartwarming adventure proving that true bravery is simply overcoming fear for someone you love.', 'Prije nego što su se preselili u Trolberg, Hilda i njen vjerni jelisac Tvig istraživali su divljinu bez obzira na vremenske prilike. Kada ih iznenadna oluja natjera da potraže sklonište u tajanstvenoj humci, Tvig brzo shvata da to mjesto krije opasnost. Kako bi spasio svoju najbolju prijateljicu od krljuštastih nevolja, mali, oprezni jelisac moraće da pokaže ogromnu hrabrost. Topla avantura koja podsjeća da pravo junaštvo leži u ljubavi prema prijatelju.', 'Загляните под дождевик Хильды и узнайте, как верный лисолень Твиг совершил свой самый храбрый подвиг!', 'Peek beneath Hilda''s raincoat to discover how little deerfox Twig stepped up for his very bravest rescue!', 'Zavirite pod Hildinu kabanicu i otkrijte kako je mali jelisac Tvig izveo svoj najhrabriji podvig!', '/covers/DP-0814.webp', '#2c5d73', 'nonfiction', 'ru', 'available', 'Категория: Хильда', '["adventure","friends","magic"]', '["comics","deerfox","friendship","bravery","rainy day"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('1-хильда-и-тролль-815', 'DP-0815', '1. Хильда и тролль', 'Hilda and the Troll', 'Hilda i trol', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Познакомьтесь с Хильдой - она ни дня не может провести без приключений! Морские духи, великаны, крошечные эльфы, тролли и подозрительные древесные люди - ее окружение никак нельзя назвать обычным. Каждый день Хильда бесстрашно изучает мир, полный истинно скандинавской магии. Но после встречи с каменным троллем события принимают совсем уж неожиданный поворот. Впрочем, как верно говорит сама Хильда - "Такова жизнь искателя приключений". Скорее отправляйтесь в путь вместе с Хильдой и ее питомцем Твигом!', 'Meet Hilda — she can''t spend a single day without an adventure! Sea spirits, giants, tiny elves, trolls, and curious wood men make her world anything but ordinary. Hilda fearlessly explores the Nordic wilderness, full of folklore and magic, until a bell tied to a stone troll leads to an unexpectedly wild encounter. Pack your sketchbook, bring your deer-fox Twig, and set off on an unforgettable journey!', 'Upoznajte Hildu — djevojčicu koja ne može zamisliti dan bez pustolovina! Morski duhovi, divovi, sićušni vilenjaci, trolovi i zagonetni drveni ljudi čine njen svijet potpuno čarobnim. Hilda neustrašivo istražuje prostranstva skandinavskog folklora, sve dok susret sa kamenim trolom ne donese neočekivan obrt. Spakujte skicenblok, povedite vjernog lisičića Tviga i zakoračite u uzbudljivu avanturu!', 'Захватите скетчбук, колокольчик и верного лисоленя: мы отправляемся исследовать самые волшебные скандинавские фьорды вместе с неугомонной Хильдой!', 'Pack your sketchbook, a tiny bell, and your trusty deer-fox: we''re venturing into the enchanted Nordic wilderness with the fearless Hilda!', 'Spakujte skicenblok, zvonce i vjernog lisičića: krećemo u čarobnu skandinavsku divljinu sa neustrašivom Hildom!', '/covers/DP-0815.webp', '#2e637a', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","magic","animals"]', '["graphic novel","scandinavian folklore","trolls","exploring","mythical creatures"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('2-хильда-и-полуночный-великан-816', 'DP-0816', '2. Хильда и полуночный великан', 'Hilda and the Midnight Giant', 'Hilda i ponoćni div', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Люк Пирсон', 'МИФ', NULL, NULL, 6, 16, 'middle', 'В новой истории Хильда узнает, что ее дом стоит прямо посреди города невидимых крошечных эльфов. И те требуют, чтобы Хильда с мамой перестали им мешать и покинули долину... Почему люди не могут видеть маленьких эльфов? Что нужно таинственному великану, который каждую ночь приходит к дому Хильды? И на что она пойдет, чтобы добиться справедливости?.. Как всегда в историях про Хильду, вас ждет таинственный и загадочный скандинавский мир, полный невероятных существ, неожиданные повороты событий и непростые вопросы, на которые нужно найти ответы.', 'In this exciting chapter of Hilda''s adventures, she discovers that her cozy house stands right in the middle of an invisible city of tiny elves—and they want her and Mum gone! Why can''t humans see these little creatures? Who is the mysterious giant wandering outside their window every night? And how far will Hilda go to protect her home and find the truth? Dive into a breathtaking Scandinavian world full of legendary creatures, twists, and heart.', 'U ovoj novoj avanturi, Hilda saznaje da je njena kuća sagrađena usred nevidljivog grada sićušnih vilenjaka koji zahtijevaju da ona i njena mama napuste dolinu. Zašto ljudi ne vide male vilenjake? Šta traži zagonetni div koji svake noći posjećuje njihovo dvorište? Čeka vas čaroban skandinavski svijet pun neobičnih stvorenja, uzbudljivih preokreta i važne priče o poštovanju i prijateljstvu.', 'Даже если вас пытаются выселить невидимые эльфы, а по ночам в окна заглядывает великан, неутомимая Хильда научит договариваться с любыми волшебными соседями!', 'When invisible elves threaten eviction and a mysterious giant wanders by night, Hilda proves that curiosity and kindness are the greatest superpowers.', 'Kad vam nevidljivi vilenjaci zatraže iseljenje, a tajanstveni div luta oko kuće, neustrašiva Hilda dokazuje da hrabrost i razumijevanje rješavaju sve nesporazume!', '/covers/DP-0816.webp', '#23415e', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","magic","friends"]', '["graphic novel","scandinavian folklore","giants","elves","comics"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('3-хильда-и-птичий-парад-817', 'DP-0817', '3. Хильда и птичий парад', 'Hilda and the Bird Parade', 'Hilda i parada ptica', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Люк Пирсон', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Хильду ждут новые приключения - она погружается в жизнь шумного города Тролльберга. Вдали от волшебных фьордов Хильде предстоит выяснить, сможет ли она быть счастлива в этом непривычном бетонном лесу... Совсем скоро Хильда узнает, что и новый дом полон удивительных сюрпризов и магических созданий. Ведь ее ждет таинственный Птичий парад! Новая книга Люка Пирсона, номинанта премии Айснера, продолжает серию "Хильдафолк", уже снискавшую мировую славу и получившую множество наград.', 'New adventures await Hilda as she navigates life in the bustling city of Trolberg. Far from her beloved enchanted fjords, can she find happiness in this unfamiliar concrete jungle? Hilda soon discovers that her new home holds its own wondrous surprises and secret magical creatures, culminating in the dazzling and mysterious annual Bird Parade. A standout chapter in Luke Pearson''s award-winning graphic novel series.', 'Hildu čekaju nove avanture dok se privikava na život u bučnom gradu Trolbergu. Daleko od svojih magičnih fjordova, može li pronaći sreću u ovoj neobičnoj betonskoj šumi? Uskoro otkriva da i novi dom krije čudesna iznenađenja i magična bića, vodeći je pravo na tajanstvenu Paradu ptica. Još jedno izvanredno poglavlje iz nagrađivanog serijala stripova Luka Pirsona.', 'Даже шумный город полон магии и пернатых тайн, если уметь смотреть на мир бесстрашными глазами Хильды!', 'Even a bustling city has room for soaring magic if you explore its rooftops through Hilda''s fearless eyes!', 'Čak i bučan grad krije bezbroj čuda i pernatih tajni ako ga istražujete Hildinim hrabrim očima!', '/covers/DP-0817.webp', '#d98b2b', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","magic","animals"]', '["graphic novel","comics","city life","magical creatures","birds"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('4-хильда-и-черный-пес-818', 'DP-0818', '4. Хильда и черный пес', 'Hilda and the Black Hound', 'Hilda i crni pas', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Люк Пирсон', 'МИФ', NULL, NULL, 6, 16, 'middle', 'В новой истории Хильда узнает, что Тролльберг хранит еще множество секретов. Жители взволнованы исчезновениями горожан, в округе несколько раз видели огромного черного пса, а Хильда даже у себя дома обнаруживает волшебных существ - вредных, но обаятельных ниссе. Почему по всему городу озорников-ниссе выгоняют из квартир? Куда пропадают вещи? И что за создание бродит вокруг, нагоняя страх на жителей Тролльберга?.. На этот раз Хильде предстоит разгадать настоящую детективную загадку в полном волшебства скандинавском мире.', 'Trolberg holds more mysteries than Hilda ever imagined: townspeople are on edge, whispers spread of a colossal black hound prowling the outskirts, and cheeky house-spirits called Nisse are suddenly homeless. Hilda leaps into a thrilling detective adventure to discover what truly lurks in the shadows.', 'U Trolbergu se dešavaju čudne stvari: ljudi nestaju, po gradu se šapuće o ogromnom crnom psu koji luta noću, a Hilda u sopstvenom domu pronalazi nestašne nise. Naša junakinja kreće u pravu detektivsku avanturu punu skandinavske magije kako bi otkrila ko zaista vreba iz sjenki.', 'Загадочный гигантский пес, своенравные домовые в шкафу и отважная девочка с синими волосами — идеальный скандинавский детектив!', 'A giant spectral hound, cheeky house-sprites hidden in cupboards, and our favorite blue-haired adventurer tackling a spooky mystery!', 'Misteriozni džinovski pas, vragolasti kućni duhovi i neustrašiva plavokosa Hilda u neodoljivoj skandinavskoj detektivskoj priči!', '/covers/DP-0818.webp', '#1f2a44', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","magic","spooky"]', '["comics","folklore","mystery","dogs","graphic novel"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('5-хильда-и-каменный-лес-819', 'DP-0819', '5. Хильда и каменный лес', 'Hilda and the Stone Forest', 'Hilda i kamena šuma', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Люк Пирсон', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Хильда почти не появляется дома - целыми днями она вместе с Тонту и Твигом исследует окрестности Тролльберга, а ее мама всё сильнее за нее волнуется... Напряжение нарастает, когда однажды Хильду вместе с мамой в момент ссоры внезапно забрасывает в загадочный и мрачный каменный лес - на землю троллей! Смогут ли они вдвоем найти путь обратно и вырваться из лап свирепого народа? И можно ли безнаказанно пройти по чужим владениям?', 'Hilda barely spends any time at home these days—spending whole days wandering the outskirts of Trollberg with Tontu and Twig, leaving her mother sick with worry. Tensions bubble over, and during a heated argument, Hilda and her mom are suddenly transported deep into a mysterious, eerie stone forest right in the trolls'' domain! Will they be able to set aside their differences, escape the clutches of dangerous creatures, and find their way back home?', 'Hilda jedva da provodi vrijeme kod kuće — po čitave dane sa Tontuom i Tvigom istražuje okolinu Trolberga, dok njena mama sve više brine. Napetost dostiže vrhunac kada usred jedne svađe Hilda i njena mama iznenada bivaju prebačene u zagonetnu i mračnu kamenu šumu — pravo u zemlju trolova! Hoće li uspjeti da nađu put nazad i pobjegnu od opasnih bića?', 'Опасное и трогательное путешествие, доказывающее, что даже ссора с мамой может обернуться грандиозным походом в логово троллей!', 'A thrilling and heartfelt trek into troll territory proving that even an argument with mom can turn into the ultimate survival adventure!', 'Uzbudljiva i dirljiva avantura u zemlji trolova koja dokazuje da se i rasprava s mamom može pretvoriti u nevjerovatno putovanje!', '/covers/DP-0819.webp', '#33495d', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","magic","spooky"]', '["graphic novel","trolls","fantasy","family","monsters"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('6-хильда-и-горный-король-820', 'DP-0820', '6. Хильда и горный король', 'Hilda and the Mountain King', 'Hilda i Planinski kralj', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Люк Пирсон', 'МИФ', NULL, NULL, 6, 16, 'middle', 'В пятом томе мы оставили Хильду в очень неожиданной ситуации, и в триумфальном завершении серии ей предстоит выпутаться из нее! Хотя события принимают совсем уж зловещий оборот, герои волшебного мира не изменяют себе - ищут способ мирно разрешить конфликты. Но вот страшный король горных троллей явно настроен крайне сурово... Смогут ли герои вернуть мир в Тролльберг и в компанию своих друзей?', 'In the fifth volume we left Hilda in quite an unexpected predicament, and in this triumphant grand finale of the graphic novel series, she has to find a way out! Even when things take a truly menacing turn, the heroes of this magical realm stay true to themselves, seeking peaceful solutions. But the dreaded Mountain King of the trolls seems determined to wage war... Can Hilda and her companions restore harmony to Trollberg and get back to their loved ones?', 'U petom tomu ostavili smo Hildu u potpuno neočekivanoj situaciji, a u ovom trijumfalnom finalu serijala moraće nekako da se izbavi! Iako događaji postaju prilično zlokobni, junaci čarobnog svijeta ostaju vjerni sebi — tragaju za mirnim rješenjem sukoba. Ipak, strašni kralj planinskih trolova odlučan je u svojoj namjeri... Mogu li naši junaci vratiti mir u Trolberg i među svoje prijatelje?', 'Грандиозный и трогательный финал приключений синеволосой бунтарки — о том, что даже с грозными троллями можно договориться по-человечески!', 'A grand, heartfelt finale to the blue-haired girl''s adventures, proving that empathy can bridge the gap even with giant stone trolls!', 'Veličanstveno i dirljivo finale avantura plavokose djevojčice koje dokazuje da se i sa strašnim trolovima može razgovarati srcem!', '/covers/DP-0820.webp', '#d35400', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","magic","friends"]', '["graphic novel","trolls","fantasy","hilda","folklore"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('изобретатели-821', 'DP-0821', 'Изобретатели', 'Tatu and Patu''s Marvelous Inventions', 'Tatu i Patu: Čudesni izumi', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', '', 'Речь', NULL, NULL, 6, 16, 'middle', 'Братья Тату и Пату - неутомимые изобретатели. Они приехали из далёкой страны Чудляндии, где всё устроено совсем по-другому. Тату и Пату изучают разные предметы и явления и хотят сделать мир чуточку лучше. Они придумали 14 устройств, которые, несомненно, пригодятся каждому ребёнку! К удобным изобретениям быстро привыкаешь - осторожнее, вдруг вы потом не сможете заходить в комнату без букопугателя или просыпаться без будильно-кормильно-одевального аппарата? Хотите узнать, как они устроены? Скорее открывайте книгу и изучайте!', 'Brothers Tatu and Patu are relentless inventors from the whimsical land of Oddville, where everything works a bit differently. Determined to make everyday life easier, they have designed 14 ingenious contraptions every child truly needs—from a monster detector to a wake-up-feed-and-dress-o-matic machine! Beware: once you discover these clever blueprints, you will wonder how you ever lived without them.', 'Braća Tatu i Patu su neumorni izumitelji iz daleke zemlje Čudnovatije, gdje sve funkcioniše potpuno drugačije. U želji da učine svijet boljim, smislili su 14 genijalnih naprava koje su neophodne svakom djetetu — od aparata za plašenje bauka do mašine koja te istovremeno budi, hrani i oblači! Otvorite knjigu i otkrijte kako ove nevjerovatne mašine zapravo rade.', 'Осторожно: после этой невероятно смешной книги дети требуют немедленно собрать дома будильно-кормильно-одевальный аппарат из подручных коробок!', 'Be warned: after reading this delightfully absurd guide, kids will immediately try to assemble their own wake-up-and-dress-o-matic machines out of cardboard boxes!', 'Oprez: nakon ove urnebesne knjige, djeca će odmah pokušati da od kartonskih kutija naprave aparat za buđenje, hranjenje i oblačenje!', '/covers/DP-0821.webp', '#e8921e', 'nonfiction', 'ru', 'available', 'комикс | ?', '["funny","friends"]', '["inventions","humor","brothers","contraptions","stem"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('идут-на-работу-822', 'DP-0822', 'Идут на работу', 'Tatu and Patu at Work', 'Tatu i Patu idu na posao', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Куда так спешат взрослые каждое утро? Может быть, они торопятся за бесплатным мороженым? Тату и Пату должны это выяснить! Оказывается, по утрам взрослые бегут... на работу. Наверное, это ужасно интересно - работать пекарем или парикмахером, журналистом или музыкантом, строителем или пожарным! Любопытства Тату и Пату не занимать, и они решают попробовать себя во всех профессиях, какие только попались им на доске объявлений. Что же из этого выйдет?..', 'Where do grown-ups rush every morning? Could it be free ice cream? Tatu and Patu are determined to find out! It turns out adults rush to... work. Being a baker, hairdresser, journalist, builder, or firefighter must be terribly exciting! Driven by pure curiosity, the goofy brothers decide to test out every profession on the bulletin board. What could possibly go wrong?', 'Gdje to odrasli žure svakog jutra? Možda trče po besplatan sladoled? Tatu i Patu moraju to da istraže! Ispostavlja se da odrasli trče na... posao. Biti pekar, frizer, novinar, građevinar ili vatrogasac zvuči nevjerovatno uzbudljivo! Radoznala braća odlučuju da isprobaju sva zanimanja koja pronađu na oglasnoj tabli — šta li će ispasti iz ovog urnebesnog eksperimenta?', 'Гомерически смешной гид по миру взрослых профессий, после которого любая работа покажется самым весёлым приключением на свете!', 'An uproariously funny guide to the working world that proves any job can become pure, joyful chaos with Tatu and Patu around!', 'Urnebesno smiješan vodič kroz svijet zanimanja uz koji svaki posao izgleda kao najluđa zabava na planeti!', '/covers/DP-0822.webp', '#f39c12', 'nonfiction', 'ru', 'available', 'комикс', '["funny","real"]', '["professions","humor","tatu and patu","jobs","picture book"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('супергерои-823', 'DP-0823', 'Супергерои', 'Superheroes', 'Superheroji', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Тату и Пату уже давно следят за невероятными приключениями Наномегачеловека. "Вот бы превратиться в супергероев!" - мечтают они, как вдруг - щёлк! - и с помощью пульта управления киберсилой превращаются в Кибертату и Гиперпату! Отважные герои готовы вступить в схватку с суперопасными злодеями и спасти Ваусити от гигантских упаковок, превративших жизнь города в настоящий хаос.', 'Tatu and Patu have long been avid fans of the amazing Nanomegaman. Wishing to become superheroes themselves, they click a cyber-power remote and suddenly transform into Cybertatu and Hyperpatu! Armed with wacky ingenuity, the brave duo must take on supervillains and save Wow City from a catastrophic invasion of runaway giant packaging.', 'Tatu i Patu već dugo prate nevjerovatne avanture Nanomega-čovjeka. „Kada bismo bar mi mogli postati superheroji!” — maštaju oni, i odjednom — klik! Pomoću daljinskog upravljača za kibernetičku moć pretvaraju se u Kibertatua i Hiperpatua! Hrabri heroji spremni su da se suprotstave zlikovcima i spasu Vausiti od džinovskih ambalaža koje prijete gradu.', 'Приготовьтесь хохотать до слёз, пока Тату и Пату надевают суперкостюмы и спасают мир от картонного хаоса самым нелепым образом!', 'Get ready to laugh your capes off as Tatu and Patu suit up to save the city from runaway packaging chaos in the most hilarious way possible!', 'Spremite se za buru smijeha dok Tatu i Patu oblače kostime superheroja i spasavaju grad od ambalažnog haosa na najluđi mogući način!', '/covers/DP-0823.webp', '#d92b27', 'nonfiction', 'ru', 'available', 'комикс', '["funny","adventure","friends"]', '["superheroes","humor","inventions","tatu and patu","comics"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('феноменальная-книга-сказок-824', 'DP-0824', 'Феноменальная книга сказок', 'The Phenomenal Book of Fairy Tales', 'Fenomenalna knjiga bajki', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Эта невероятная книга перевернет ваше отношение к чтению сказок! Она предлагает вам не только шесть новейших сказок, но и инструкции по прочтению, разработанные специально к каждой сказке! Не стойте на месте, приступайте к чтению!', 'This incredible book will turn your whole idea of reading fairy tales upside down! Not only does it offer six brand-new fairy tales, but it also includes hilarious reading instructions specially crafted for each one. Don''t just stand there—dive right in!', 'Ova nevjerovatna knjiga potpuno će promijeniti vaš pogled na čitanje bajki! Ona nudi ne samo šest sasvim novih bajki, već i urnebesna uputstva za čitanje stvorena posebno za svaku od njih. Ne čekajte, zaronite u avanturu!', 'Приготовьтесь хохотать во весь голос, ведь неподражаемые Тату и Пату покажут, как на самом деле нужно читать и исследовать сказки!', 'Get ready to laugh out loud as Tatu and Patu demonstrate the absolute wildest ways to read and test-drive fairy tales!', 'Pripremite se za glasan smijeh dok vam Tatu i Patu pokazuju najotkačenije načine za čitanje i testiranje bajki!', '/covers/DP-0824.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: Тату и Пату', '["funny","magic"]', '["fairy tales","humor","tatu and patu","interactive","finnish literature"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вера-у-врача-825', 'DP-0825', 'Вера у врача', 'Veera at the Doctor', 'Vera kod ljekara', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Вера собирается в поликлинику на приём к врачу. Могут ли Тату и Пату усидеть дома? Конечно, они отправятся вместе с ней! Ведь им любопытно: что это за место - поликлиника? Зачем туда ходят дети? Врач - он какой: страшный или не очень? В кабинете у врача оказывается столько всего интересного! Здесь можно измерить температуру, рост и вес. Проверить зрение с помощью картинок, а рефлексы - с помощью молоточка. Теперь Тату и Пату знают, что такое стетоскоп, отоскоп и тонометр! Зачем мыть руки перед едой, почему питаться надо правильно, а одеваться по погоде. И самое главное - врачи им теперь не страшны!', 'Veera is heading to the clinic for a checkup, and there''s no way Tatu and Patu are staying behind! They are burning with curiosity: what kind of place is a clinic? Why do kids go there, and are doctors actually scary? It turns out the doctor''s office is packed with fascinating wonders: you can measure height and weight, check your eyesight with picture charts, and test your reflexes with a tiny rubber hammer. Now Tatu and Patu know what a stethoscope, otoscope, and tonometer do, why washing hands matters—and that doctors aren''t frightening at all!', 'Vera se sprema za posjetu klinici i pregled kod ljekara, a Tatu i Patu nikako ne mogu ostati kod kuće! Neizmjerno su radoznali: kakvo je to mjesto klinika, zašto djeca tamo idu i da li je ljekar strašan? U ordinaciji se nalazi pregršt zanimljivih sprava: mjere se visina, težina i temperatura, vid se provjerava uz sličice, a refleksi malim čekićem. Sada Tatu i Patu znaju čemu služe stetoskop, otoskop i aparat za pritisak, zašto treba prati ruke—i što je najvažnije, da doktori uopšte nisu strašni!', 'Забудьте про страх белых халатов: неугомонные Тату и Пату превратят поход в поликлинику в весёлое исследовательское приключение!', 'Wave goodbye to fear of white coats: mischievous Tatu and Patu turn an ordinary doctor visit into a hilarious scientific expedition!', 'Zaboravite na strah od bijelih mantila: radoznali Tatu i Patu pretvaraju običan odlazak ljekaru u urnebesnu istraživačku avanturu!', '/covers/DP-0825.webp', '#36a9a0', 'nonfiction', 'ru', 'available', 'комикс | ?', '["funny","real"]', '["tatu and patu","doctor","health","clinic","humor"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вера-на-кухне-826', 'DP-0826', 'Вера на кухне', 'Veera in the Kitchen', 'Vera u kuhinji', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Тату и Пату гостят у Веры. Они проголодались, но на кухню идти боятся: кажется, там много опасных предметов. Да и готовить они пока не умеют... Но научиться не так уж и сложно! Вера знает, как обращаться с электроплитой, умеет выбирать нужные продукты и готовить с помощью рецепта. До ужина друзья успеют замесить тесто, приготовить начинку, испечь пиццу и изучить правила поведения за столом. Они познакомятся со множеством кухонных предметов, узнают названия приправ, научатся делать уборку на кухне и даже сервировать стол! Не забывая при этом шалить и веселиться. Ведь вместе веселее и готовить, и учиться, и шутить. И, конечно же, ужинать!', 'Tatu and Patu are visiting Veera and they are starving, but the kitchen seems full of mysterious and dangerous gadgets! Luckily, Veera is ready to teach them everything: from safely using the stove and following recipes to choosing fresh ingredients. Together, the trio kneads dough, prepares toppings, bakes a mouth-watering pizza, cleans up the mess, and masters table manners—all while having hilarious misadventures along the way.', 'Tatu i Patu su u posjeti kod Vere i strašno su ogladnjeli, ali se plaše kuhinje jer im djeluje puno opasnih sprava. Srećom, Vera tačno zna kako se koristi šporet, kako se biraju namirnice i prate recepti! Zajedno će umijesiti tijesto, ispeći picu, savladati bonton za stolom i pospremiti kuhinju — naravno, uz pregršt smijeha, nestašluka i zabave.', 'Превратите кухонный хаос в аппетитный шедевр и море веселья вместе с неугомонными Тату, Пату и рассудительной Верой!', 'Turn kitchen chaos into a delicious masterpiece and a storm of laughter with Tatu, Patu, and practical Veera!', 'Pretvorite kuhinjski haos u ukusno remek-djelo i more smijeha uz Tatua, Patua i snalažljivu Veru!', '/covers/DP-0826.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'комикс', '["funny","friends","real"]', '["cooking","pizza","humor","recipes","friendship"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('невероятный-новый-год-827', 'DP-0827', 'Невероятный новый год', 'Tatu and Patu''s Incredible New Year', 'Tatu i Patu: Nevjerovatna Nova godina', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Кто бы мог подумать, что братья перепутают дом? Не найдя Веры, Тату и Пату решают, что пришли на день раньше, и начинают готовиться к празднику! Что же они успеют натворить и какие сюрпризы их ждут? Поймут ли они, что пришли не туда? Скорее открывайте книгу, вас ждёт невероятное новогоднее приключение!', 'Who would have thought the eccentric brothers would show up at the wrong house? Not finding their friend Veera, Tatu and Patu assume they arrived a day early and eagerly dive into holiday preparations! What hilarious chaos will they cause, and will they ever realize their silly mistake? Open this book for an utterly unforgettable holiday adventure!', 'Ko bi rekao da će braća promašiti kuću? Ne zatekavši Veru, Tatu i Patu zaključuju da su stigli dan ranije i odmah počinju pripreme za praznik! Kakve će sve smicalice smisliti i koja ih iznenađenja čekaju? Hoće li uopšte shvatiti da su na pogrešnoj adresi? Otvorite knjigu i uživajte u urnebesnoj novogodišnjoj avanturi!', 'Приготовьтесь хохотать до слёз, пока Тату и Пату с полной серьёзностью наряжают чужую гостиную и изобретают праздничные традиции заново!', 'Get ready to laugh out loud as Tatu and Patu enthusiastically deck the halls of a total stranger''s house in the most delightfully absurd ways!', 'Spremite se za smijeh do suza dok Tatu i Patu sa punim žarom spremaju praznike u tuđoj kući na najsmješniji mogući način!', '/covers/DP-0827.webp', '#c83226', 'nonfiction', 'ru', 'available', 'комикс', '["funny","adventure"]', '["tatu and patu","humor","new year","winter holidays","brothers"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('детективы-дело-о-половинщике-828', 'DP-0828', 'Детективы: дело о половинщике', 'Tatu and Patu, Detectives: The Case of the Halfer', 'Detektivi Tatu i Patu: Slučaj prepolovljivača', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'В семье Нико, старого знакомого Тату и Пату, происходят странные вещи. Сначала исчезла половина папиного бифштекса, а затем оказалось, что ополовиниться может что угодно: новые ползунки, чехол для телефона и даже макияж! Как это могло произойти? И кто за этим стоит? Разумеется, Тату и Пату не бросают друзей в беде и берутся расследовать тёмное дело! Тем более что они - настоящие профессионалы, мастера частного сыска и гении маскировки! Для чтения взрослыми детям.', 'Bizarre things are happening at Niko''s house: first, half of dad''s steak vanishes, followed by half a baby romper, half a phone case, and even half of mom''s makeup! Who is behind this half-snatching mystery? Armed with hilarious disguises, absurd detective gadgets, and boundless enthusiasm, Tatu and Patu jump in to crack the case.', 'Čudne stvari se dešavaju u kući Nika, prijatelja Tatua i Patua: prvo nestaje pola tatinog odreska, a zatim se prepolovi sve redom — nova benkica, futrola za telefon, pa čak i šminka! Ko stoji iza ove zagonetke? Tatu i Patu, majstori otkačene kamuflaže i privatne istrage, kreću u urnebesnu akciju rješavanja misterije.', 'Хватайте лупы и готовьтесь хохотать: самые эксцентричные сыщики Финляндии расследуют самое загадочное половинчатое преступление века!', 'Grab your magnifying glass and get ready to giggle: Finland''s most eccentric detectives are tackling their funniest, half-sized mystery yet!', 'Uzmite lupu i pripremite se za smijeh: najotkačeniji finski detektivi kreću u potragu za tajanstvenim kradljivcem polovina!', '/covers/DP-0828.webp', '#e9a124', 'nonfiction', 'ru', 'available', 'комикс', '["funny","adventure"]', '["detective","tatu and patu","humor","mystery","illustrations"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-детском-саду-829', 'DP-0829', 'В детском саду', 'Tatu and Patu at Kindergarten', 'Tatu i Patu u vrtiću', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Тату и Пату собираются в аквапарк. Но случайно спутав названия, попадают в детский сад по соседству. Вы думаете, братья расстроились? Ничего подобного! Грязевые ванны в песочнице, игры и танцы, дневной сон после сытного обеда и репетиция праздничного спектакля - оказывается, в детском саду ещё как интересно и весело! Книги о Тату и Пату - одна из самых популярных книжных серий в Финляндии, на родине её авторов. Захватывающие и смешные истории о приключениях братьев-чудиков отмечены множеством литературных наград и не оставят равнодушным ни одного читателя!', 'Tatu and Patu set out for a wild day at the water park, but mistakenly walk straight into the neighborhood kindergarten instead! Are the eccentric brothers upset? Not in the slightest! Between mud baths in the sandbox, lively dancing, delicious lunches, and epic naps, they discover that daycare is packed with the craziest fun imaginable.', 'Tatu i Patu su krenuli u akva-park, ali su greškom zalutali u obližnji vrtić. Da li su se braća razočarala? Ni najmanje! Blatne kupke u pješčaniku, igre, popodnevni san i proba pozorišne predstave dokazuju da u vrtiću nema mjesta za dosadu. Urnebesno duhovita finska priča koja osvaja srca malih i velikih čitalaca.', 'Думаете, детский сад — это скучно? Пустите туда двух неугомонных чудаков Тату и Пату, и обычный тихий час превратится в феерическое шоу!', 'Think kindergarten is ordinary? Drop in the delightfully confused brothers Tatu and Patu and watch naptime turn into a riot of fun!', 'Mislite da je u vrtiću dosadno? Pustite tamo šašavu braću Tatua i Patua i gledajte kako se običan dan pretvara u urnebesnu avanturu!', '/covers/DP-0829.webp', '#e88d25', 'nonfiction', 'ru', 'available', 'комикс | ?', '["funny","adventure"]', '["kindergarten","humor","brothers","finnish literature","adventures"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жизнь-и-творчество-830', 'DP-0830', 'Жизнь и творчество', 'Tatu and Patu: Life and Works', 'Tatu i Patu: Život i djelo', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Уважаемые читатели, вы держите в руках необычное издание. Эта книга рассказывает не только о невероятных приключениях братьев из Чудляндии, но и об их происхождении! Пришло время приоткрыть завесу тайны. Причудливо ли чудляндское детство? Как Тату и Пату стали исследователями и изобретателями? Что такое состояние чудофории? Где находится загадочная Чудляндия? И как из двух маленьких чудляндцев смогли вырасти такие популярные личности? Это издание знакомит читателей как с детски ми годами и бурной молодостью знаменитых братьев, так и с трудностями и достижениями последних лет.', 'Curious readers, you hold a truly extraordinary chronicle in your hands! Uncover the quirky origins of Oddsville''s favorite brothers, Tatu and Patu. What was their bizarre childhood like? How did they become such eccentric researchers and inventors? What on earth is ''oddphoria'', and where is Oddsville located anyway? From wacky childhood experiments and turbulent youth to breakthrough inventions and worldwide fame, this illustrated biography reveals all the hilarious secrets of the beloved duo.', 'Dragi čitaoci, u rukama držite zaista neobično izdanje! Otkrijte otkačeno porijeklo najdražih istraživača iz Čudnolandije, braće Tatua i Patua. Kako je izgledalo njihovo čudnovato djetinjstvo? Kako su postali neumorni pronalazači i naučnici? Šta je to stanje ''čudoforije'' i gdje se zapravo nalazi ta zagonetna zemlja? Od prvih luckastih koraka i burne mladosti pa sve do genijalnih izuma i slave, ova zabavna biografija otkriva sve tajne legendarnog dvojca.', 'Хотите узнать, откуда взялись главные чудаки скандинавской литературы и как они додумались до своих безумных изобретений? Загляните в их секретное досье!', 'Ever wondered how the world''s quirkiest Finnish brothers grew up to invent the craziest gadgets? Dive into their hilarious official biography!', 'Jeste li se ikada pitali kako su najluckastija braća na svijetu odrasla i smislila sve one lude izume? Zavirite u njihovu urnebesnu biografiju!', '/covers/DP-0830.webp', '#f39c12', 'nonfiction', 'ru', 'available', 'комикс', '["funny","friends","adventure"]', '["tatu and patu","inventors","humor","biography","oddsville"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('инструкция-по-засыпанию-831', 'DP-0831', 'Инструкция по засыпанию', 'Instruction Manual for Falling Asleep', 'Uputstvo za uspavljivanje', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Обязательно для прочтения каждому, кто любит спать (или нет) В гости к Тату и Пату приходит племянница Соня, и братья придумывают тысячу разных способов, как уложить малышку спать. Они даже составили специальный справочник: в нём рассказано, как выбрать идеальную игрушку для засыпания, что произойдёт, если долго не ложиться спать, почему родителям можно не спать до поздней ночи, а детям - нет, и многое другое. Хотите погрузиться в мир сноучения и дремотологии? Перед вами самая полная инструкция по засыпанию!', 'When niece Sonya comes to visit Tatu and Patu, the inventive brothers come up with a thousand wacky ways to put the little one to bed. They even compiled this hilarious guide covering sleepology and dream research: how to pick the ultimate bedtime toy, what happens if you refuse to sleep, and why grown-ups get to stay up late while kids don''t!', 'Kada im u goste dođe nećaka Sonja, braća Tatu i Patu smišljaju hiljadu ludih načina da je uspavaju. Čak su sastavili i poseban vodič kroz „dremkologiju“: kako izabrati savršenu plišanu igračku za spavanje, šta se događa ako ne odemo na vrijeme u krevet i zašto odrasli smiju da ostanu budni do kasno, a djeca ne!', 'Если уложить кого-то спать для вас непосильная задача, доверьтесь чудаковатым братьям Тату и Пату — хохотать будете всей семьёй!', 'If bedtime is a nightly battle in your house, let oddball inventors Tatu and Patu guide the way with belly laughs for the whole family!', 'Ako vam je odlazak na spavanje vječiti izazov, prepustite se luckastoj braći Tatuu i Patuu i smijte se zajedno do suza!', '/covers/DP-0831.webp', '#283b6b', 'nonfiction', 'ru', 'available', 'комикс | ?', '["funny","friends","real"]', '["bedtime","sleep","humor","brothers","inventions"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пора-обедать-832', 'DP-0832', 'Пора обедать', 'Tatu and Patu: Time to Eat!', 'Tatu i Patu: Vrijeme je za ručak!', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Айно Хавукайнен, Сами Тойвонен', 'Речь', NULL, NULL, 6, 16, 'middle', 'Какие продукты чаще всего разливаются и разбрызгиваются? Что за проблемы возникают во время приготовления бутерброда? Каковы отличительные признаки большого мешалочника? Что такое древние вкусовые искусства? Ответить на эти вопросы способны только Тату и Пату! Братья из Чудляндии подготовили для вас свыше ста страниц - одна смешнее другой! А также тесты - несколько промежуточных и один заключительный.Только для наружного применения. Подходит взрослым и детям. Легко читается и легко усваивается.', 'Which foods spill and splatter the most? What hidden hazards lurk inside a simple sandwich? Tatu and Patu, the inventive brothers from Oddville, dive deep into the culinary universe with hilarious diagrams, wacky food inventions, and taste tests. Over a hundred pages of laugh-out-loud antics that are wonderfully easy to read and digest!', 'Koja se hrana najčešće prosipa i prska? Koji neočekivani problemi vrebaju pri pravljenju običnog sendviča? Braća Tatu i Patu iz Čudnovatije istražuju kulinarski svijet na svoj prepoznatljiv, urnebesan način! Očekuje vas preko stotinu zabavnih stranica s luckastim dijagramima, izumima i kulinarskim testovima — lako se čita i još lakše vari.', 'Самый аппетитный и гомерически смешной гид по еде от Тату и Пату, после которого вы посмотрите на обычный бутерброд совершенно другими глазами!', 'A wildly hilarious culinary guide from Tatu and Patu that will make you look at an ordinary sandwich in a whole new, laugh-out-loud light!', 'Nevjerovatno duhovit kulinarski vodič od Tatua i Patua nakon kog ćete običan sendvič gledati sasvim drugim očima!', '/covers/DP-0832.webp', '#e8732a', 'nonfiction', 'ru', 'available', 'Настя ж.', '["funny","real"]', '["food","humor","tatu and patu","kitchen","inventions"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пункт-назначения-луна-833', 'DP-0833', 'Пункт назначения-луна', 'Destination Moon', 'Odredište Mjesec', 'Эрже', 'Hergé', 'Hergé', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Тинтин - один из самых любимых персонажей, о его приключениях написано более 20 историй, автором которых является знаменитый бельгийский художник комиксов Эрже. Истории переведены на десятки языков и расходятся многомиллионными тиражами по всему миру. Американский режиссёр Стивен Спилберг по их мотивам снял художественный фильм "Приключения Тинтина. Тайна "Единорога"". Наш приятель бельгийский репортёр Тинтин снова попадает в очередную авантюру. Да ещё какую! Всё началось с загадочной телеграммы от знакомого профессора, в которой он приглашает Тинтина и его постоянного спутника во всех путешествиях капитана Хэддока в Сильдавию. В этой стране Тинтин уже был однажды и помог раскрыть заговор против её короля. Но что же на этот раз? Оказалось, профессор занимается подготовкой полёта… на Луну. И Тинтину вместе с капитаном Хэддоком предстоит составить ему компанию в этой рискованной экспедиции…', 'Tintin, the intrepid young reporter, and his trusty companion Captain Haddock receive a mysterious telegram inviting them to Syldavia. Upon arrival, they discover that their friend Professor Calculus is working on the most ambitious scientific project of the century: a manned rocket mission to the Moon! But with spies, sabotage, and dangerous test flights in the way, will they make it into the cosmos?', 'Tintin, neustrašivi mladi novinar, i njegov vjerni saputnik kapetan Hadok dobijaju tajanstveni telegram koji ih vodi pravo u Sildaviju. Tamo saznaju da profesor Suncokret radi na najsmjelijem poduhvatu u istoriji čovječanstva: pripremi rakete za let na Mjesec! Između špijunaže, sabotaža i opasnih proba, avantura vanzemaljskih razmjera tek počinje.', 'Легендарная красно-белая ракета на старте: приготовьтесь к головокружительному космическому полёту вместе с неунывающим Тинтином и ворчливым капитаном Хэддоком!', 'Fasten your seatbelts for the ultimate classic space adventure alongside intrepid Tintin and an ever-grumpy Captain Haddock!', 'Vežite pojaseve za legendarnu svemirsku avanturu uz radoznalog Tintina i vječno gunđavog kapetana Hadoka!', '/covers/DP-0833.webp', '#c8232b', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends","funny"]', '["comics","tintin","space","adventure","moon"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сломанное-ухо-834', 'DP-0834', 'Сломанное ухо', 'The Broken Ear', 'Slomljeno uvo', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Тинтин - один из самых любимых персонажей, о его приключениях написано более 20 историй, автором которых является знаменитый бельгийский художник комиксов Эрже. Истории переведены на десятки языков и расходятся многомиллионными тиражами по всему миру. Американский режиссёр Стивен Спилберг по их мотивам снял художественный фильм "Приключения Тинтина. Тайна "Единорога"". Из Этнографического музея похищен ценный экспонат - идол южноафриканского племени арумбайя. Но на следующее утро экспонат был обнаружен на прежнем месте в музее. Казалось бы, всё в порядке, если бы не маленькая деталь: у настоящего идола одно ухо повреждено, а ухо возвращённого абсолютно целое. Значит, это подделка! Но тогда где подлинник? Кто его украл? И самое главное - какую тайну хранит этот загадочный идол? Тинтин решает найти ответы на все эти вопросы…', 'When a sacred Arumbaya fetish is stolen from the ethnographic museum and replaced with a replica lacking the original''s broken ear, Tintin senses foul play. Eager to solve the mystery, the intrepid reporter and his faithful dog Snowy set off on a perilous journey into the heart of South America, braving revolution, jungle perils, and cunning rivals.', 'Kada iz etnografskog muzeja nestane sveti idol plemena Arumbaja i misteriozno se vrati bez svog prepoznatljivog slomljenog uva, Tintin shvata da je posrijedi vješta prevara. Hrabri reporter i njegov vjerni pas Sneško kreću na opasnu ekspediciju u srce Južne Amerike, suočavajući se sa revolucijama, džunglom i lukavim neprijateljima u potrazi za pravim originalom.', 'Хватайте лупу и пакуйте чемоданы в джунгли: Тинтин и Милу идут по следу загадочного идола с подозрительно целым ухом!', 'Grab your magnifying glass and pack for the jungle: Tintin and Snowy are hot on the trail of a stolen idol with a suspiciously intact ear!', 'Uzmite lupu i spakujte kofere za džunglu: Tintin i Sneško prate trag ukradenog idola sa sumnjivo čitavim uvom!', '/covers/DP-0834.webp', '#2c6941', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends"]', '["comics","tintin","detective","mystery","journey"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('таинственная-звезда-835', 'DP-0835', 'Таинственная звезда', 'The Shooting Star', 'Tajanstvena zvijezda', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Молодой репортёр Тинтин, любитель приключений, опять попадает в историю! Всё началось с… конца света, который предсказал некий пророк Филиппулус. Но конца света не случилось, зато случилось кое-что другое - где-то в Северном Ледовитом океане упал метеорит, содержащий неизвестный науке металл. Это же сенсация! Срочно организуется экспедиция, и Тинтин с группой учёных отправляется в плавание, которое превращается в настоящую гонку. Кто же пытается опередить их и добраться до метеорита первым?', 'Young reporter Tintin finds himself in the middle of another thrilling escapade! When a mysterious meteorite containing an unknown metal crashes into the Arctic Ocean, an urgent scientific expedition sets sail. But Tintin and his team soon discover they are not alone—a rival ship is also racing at full throttle to claim the extraterrestrial prize!', 'Mladi novinar Tintin ponovo uleće u uzbudljivu avanturu! Kada misteriozni meteorit koji sadrži nauci nepoznat metal padne u Sjeverni ledeni okean, hitno se organizuje ekspedicija. Tintin i tim naučnika kreću na plovidbu koja se pretvara u pravu trku s vremenom—ko to još po svaku cijenu želi da stigne prvi do meteorita?', 'Запасайтесь тёплыми куртками: Тинтин и капитан Хэддок мчат к Северному полюсу наперегонки с конкурентами!', 'Pack your warmest coat: Tintin and Captain Haddock are in a high-stakes Arctic race across the frozen seas!', 'Pripremite tople jakne: Tintin i kapetan Hadok jure kroz zaleđeni okean u trci za vanzemaljskom tajnom!', '/covers/DP-0835.webp', '#1c4966', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","funny","friends"]', '["comics","tintin","expedition","sea voyage","meteorite"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-стране-черного-золота-836', 'DP-0836', 'В стране черного золота', 'Land of Black Gold', 'U zemlji crnog zlata', 'Эрже', 'Hergé', 'Herže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Тинтину, молодому бельгийскому репортёру, скучать не приходится! Вот и на этот раз намечается кое-что любопытное. А дело вот в чём. С некоторых пор странная "эпидемия" распространилась среди автомобильных моторов: они взрываются без всякой видимой причины. Владельцы машин в панике, продажи горючего резко упали, нефтяные скважины закрываются… Неужели всё дело в качестве бензина? А может, это диверсия? Тинтину здесь есть над чем поломать голову…', 'Young Belgian reporter Tintin is off on another thrilling investigation! A strange epidemic of exploding car engines is causing worldwide panic, fuel sales have collapsed, and oil supplies are in jeopardy. Is it faulty petrol or deliberate sabotage? Tintin heads to the Middle East, diving headfirst into desert intrigue, mirages, and dangerous schemes.', 'Tintin, mladi belgijski reporter, ponovo kreće u uzbudljivu istragu! Čudna „epidemija“ eksplodiranja automobilskih motora izaziva paniku, prodaja goriva naglo opada, a naftni izvori se zatvaraju. Da li je problem u lošem benzinu ili opasnoj sabotaži? Tintina put vodi pravo u pustinju punu spletki, fatamorgana i tajni.', 'Взрывающиеся моторы, загадки среди барханов и неутомимый Тинтин — приготовьтесь к захватывающему детективному сафари!', 'Exploding engines, desert mirages, and our fearless Tintin — buckle up for a wild mystery under the scorching sun!', 'Motori koji eksplodiraju, pustinjske tajne i neustrašivi Tintin — pripremite se za pravu detektivsku avanturu pod vrelim suncem!', '/covers/DP-0836.webp', '#d9822b', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","funny"]', '["комиксы","тинтин","детектив","пустыня","приключения"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рейс-714-на-сидней-837', 'DP-0837', 'Рейс 714 на Сидней', 'Flight 714 to Sydney', 'Let 714 za Sidnej', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'В каких только передрягах не оказывался юный репортёр Тинтин, где он только не побывал! И в гробнице фараона, и на таинственном Чёрном острове, и в пекле пустыни Сахары, и в диком африканском племени, и даже на Луне! Но вот в жерле дремавшего сотни лет и вдруг пробудившегося вулкана - такого он не припомнит. А всё началось с конференции по астронавтике в Сиднее, на которую Тинтин направлялся вместе с капитаном Хэддоком и профессором. Вот так поворот!', 'Young reporter Tintin has faced countless perils across the globe, but getting trapped inside the crater of an awakening volcano is a first! It all began as a routine trip to an astronautics conference in Sydney alongside Captain Haddock and Professor Calculus. But after their private jet is hijacked, Tintin and his companions find themselves stranded on an uncharted Pacific island teeming with old foes, ancient secrets, and cosmic wonders.', 'Mladi reporter Tintin prošao je kroz mnoge nevjerovatne avanture, ali se nikada ranije nije našao u grotlu vulkana koji se iznenada budi! Sve je počelo jednostavnim putovanjem na astronautički kongres u Sidneju sa kapetanom Hadokom i profesorom Kalkulusom. Međutim, otmica privatnog aviona odvešće ih pravo na zabačeno pacifičko ostrvo puno starih neprijatelja, misterija i kosmičkih tajni.', 'Пристегните ремни: обычный перелёт на научную конференцию обернётся захватом самолёта, проснувшимся вулканом и самыми настоящими космическими тайнами!', 'Fasten your seatbelts: a routine flight to a science conference takes a wild turn into hijackings, erupting volcanoes, and cosmic mysteries!', 'Vežite pojaseve: običan let na naučni kongres pretvara se u uzbudljivu otmicu, erupciju vulkana i pravu kosmičku misteriju!', '/covers/DP-0837.webp', '#1b4d7e', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","funny","friends"]', '["tintin","comics","graphic novel","mystery","island"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('драгоценности-катастфьоре-838', 'DP-0838', 'Драгоценности Катастфьоре', 'The Castafiore Emerald', 'Kastafjorini dragulji', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Однажды в замок Муленсар, принадлежавший капитану Хэддоку, приехала погостить Бьянка Кастафьоре - известная оперная дива, давняя знакомая Тинтина и капитана. И надо же было такому случиться - прямо из её комнаты пропал ценнейший изумруд, подарок махараджи Гопала. Под подозрением оказались все обитатели замка. И кто взялся за расследование? Конечно, Тинтин! Но каково же было его изумление, когда наконец он понял, ктo скрывался под маской вора…', 'When the glamorous opera diva Bianca Castafiore arrives at Marlinspike Hall, Captain Haddock''s peaceful sanctuary is turned upside down. Chaos peaks when her priceless emerald mysteriously vanishes, casting suspicion on everyone in the estate. Tintin jumps into action to unravel this delightfully witty country-house mystery!', 'Kada čuvena operska diva Bjanka Kastafjore dođe u posjetu dvorcu Mulensar, miran život kapetana Hadoka pretvara se u pravi cirkus. Prava pometnja nastaje kada nestane njen neprocjenjivi smaragd, pa Tintin kreće u istragu ove urnebesne detektivske zagonetke.', 'Настоящий комедийный детектив в замке капитана Хэддока, где пропавший изумруд перевернет всё вверх дном!', 'A sparkling comic-mystery where a missing emerald and an opera diva completely turn Marlinspike Hall upside down!', 'Prava komična detektivska avantura u dvorcu gdje nestali smaragd okreće sve naglavačke!', '/covers/DP-0838.webp', '#2e7d58', 'nonfiction', 'ru', 'available', 'комикс', '["funny","adventure"]', '["tintin","comics","mystery","detective","humor"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пикаросы-839', 'DP-0839', 'Пикаросы', 'Tintin and the Picaros', 'Tintin i Pikarosi', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Невероятно! Тинтина и его друзей обвиняют в заговоре против генерала Тапиоки! Кроме того, выясняется, что арестовали Бьянку Кастафьоре и двух Дюпонов, давних знакомых Тинтина. Юный репортёр намерен вернуть себе честное имя и выручить из беды друзей, но для этого ему надо понять, при чём здесь пикаросы - партизаны, которые хотят свергнуть ненавистного им Тапиоку и его режим. Похоже, Тинтину пора снова собираться в путь, на этот раз в Латинскую Америку.', 'Unbelievable! Tintin and his companions are accused of plotting against General Tapioca! To make matters worse, Bianca Castafiore and the bumbling detectives Thomson and Thompson have been thrown into prison. Determined to clear his good name and rescue his friends, the young reporter journeys deep into the South American jungle to find the Picaros—guerrillas aiming to topple the tyrant''s regime.', 'Nevjerovatno! Tintin i njegovi prijatelji optuženi su za zavjeru protiv generala Tapioke! Štaviše, uhapšeni su slavna Bjanka Kastafjore i smotani detektivi Tomson i Tompson. Hrabri mladi reporter kreće na opasan put u srce Južne Amerike kako bi spasio prijatelje i otkrio kakvu ulogu u svemu tome igraju Pikarosi — misteriozni gerilci iz džungle.', 'Захватывающий финал легендарной серии комиксов: джунгли, военный переворот, коварные интриги и верные друзья, готовые прийти на помощь!', 'Pack your bags for South America, dodge a military coup, and uncover jungle secrets alongside Tintin and Snowy!', 'Spakujte kofere za Južnu Ameriku, izbjegnite vojni puč i krenite u uzbudljivu avanturu kroz džunglu sa Tintinom i Miluom!', '/covers/DP-0839.webp', '#2d7f3e', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends","funny"]', '["comics","tintin","latin america","detective","investigation"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дело-профессора-840', 'DP-0840', 'Дело профессора', 'The Calculus Affair', 'Slučaj profesora Turnesola', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'В замке Муленсар, имении капитана Хэддока, начали происходить необъяснимые события - вдребезги разлетаются прямо в руках чашки и стаканы, трескаются зеркала, от окон остаются лишь мелкие осколки, а драгоценные старинные вазы превращаются в груду черепков... Обитатели замка в панике. Юный бельгийский репортёр Тинтин, который всегда готов к любым авантюрам, подозревает, что разгадка кроется в загадочных экспериментах профессора, его давнего знакомого...', 'Unexplained phenomena shatter the peace at Marlinspike Hall: mirrors crack, windows burst into tiny shards, and antique vases turn to dust! Tintin and Captain Haddock suspect that the bizarre chaos is connected to the ultra-secret ultrasonic experiments of Professor Calculus. When the brilliant scientist vanishes, Tintin plunges straight into a high-stakes Cold War espionage thriller.', 'Neobjašnjivi događaji potresaju dvorac Mulensar: ogledala pucaju, prozori se raspršuju u komadiće, a skupocjene vaze pretvaraju u prah! Tintin i kapetan Hadok slute da iza svega stoje tajanstveni ultrazvučni eksperimenti njihovog prijatelja profesora Turnesola. Kada profesor iznenada nestane, počinje uzbudljiva špijunska potraga preko pola Evrope.', 'Осторожно, разлетаются стёкла: Тинтин и капитан Хэддок бросаются в шпионскую погоню спасать гениального учёного!', 'Watch out for shattering glass: Tintin and Captain Haddock leap into a nail-biting spy chase to save their brilliant friend!', 'Pazite na staklo: Tintin i kapetan Hadok kreću u špijunsku potjeru da spasu genijalnog naučnika!', '/covers/DP-0840.webp', '#2d5a3e', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","funny","friends"]', '["comics","tintin","detective","espionage","adventure"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('акулы-красного-моря-841', 'DP-0841', 'Акулы красного моря', 'The Red Sea Sharks', 'Ajkule Crvenog mora', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Куда же на этот раз приведёт неуёмная жажда приключений молодого бельгийского репортёра Тинтина? А привела она юношу в далёкую страну, на родину его давнего знакомого — эмира Бен Калиш Эзаба. Казалось, приключение обещает быть захватывающим, и Тинтин, как всегда, готов к любому повороту событий. В каких только авантюрах он не бывал! Но вот с чем ему ещё не доводилось сталкиваться, так это с… работорговлей. Неужели эта дикость ещё где-то существует?..', 'Where will Tintin''s relentless thirst for adventure lead him this time? Across the sea to the realm of his old friend, Emir Ben Kalish Ezab. While Tintin and Captain Haddock are prepared for perilous conspiracies, they uncover a far darker plot: an international ring of modern-day smugglers operating across the Red Sea.', 'Gdje će ovog puta nemirna žeđ za avanturom odvesti mladog belgijskog reportera Tintina? Pravo u daleku zemlju njegovog starog prijatelja, emira Ben Kališ Ezaba. Dok rješavaju misterije i bježe od opasnosti, Tintin i kapetan Hadok suočavaju se sa mračnom mrežom krijumčara na Crvenom moru.', 'Классический захватывающий комикс о Тинтине, где морские интриги, тайны и погони не дадут оторваться до последней страницы!', 'A gripping classic Tintin adventure packed with naval chases, sneaky villains, and brave escapes across treacherous waters!', 'Uzbudljivi klasični strip o Tintinu gdje vas morske intrige, tajne i opasne potjere drže u neizvjesnosti do samog kraja!', '/covers/DP-0841.webp', '#1b4e6b', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends"]', '["comics","tintin","sea adventure","investigation","graphic novel"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('7-хрустальных-шаров-842', 'DP-0842', '7 хрустальных шаров', 'The Seven Crystal Balls', 'Sedam kristalnih kugli', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Сенсация! Европейские учёные, исследовавшие малоизученные территории Перу и Боливии, обнаружили и вскрыли гробницу Великого Инки! И сразу с ними стало происходить нечто необъяснимое - все они, один за другим, впадали в летаргический сон. Неужели это месть Великого Инки за осквернение гробницы? Тинтина очень заинтересовала эта история, а когда похитили его знакомого профессора, он понял, что два события связаны между собой, и отправился на поиски в Южную Америку…', 'Sensational news! European explorers unearth an ancient Inca tomb in South America, only to fall victim to a mysterious sleeping curse one by one. Could this be the wrath of the ancient king? When his dear friend Professor Calculus is kidnapped, Tintin sets off on a perilous journey unraveling supernatural mysteries and thrilling secrets.', 'Senzacija! Evropski naučnici otkrili su i otvorili grobnicu Velikog Inke u Peruu i Boliviji, a ubrzo zatim misteriozna bolest počinje da ih obara jednog po jednog u dubok san. Kada profesor nestane, Tintin shvata da su događaji povezani i kreće u opasnu ekspediciju ka Južnoj Americi.', 'Приготовьтесь к леденящей душу тайне инков, звону разбивающегося хрусталя и верному Тинтину, который не бросит друзей даже на краю света!', 'Hold onto your hats for ancient curses, mysterious crystal orbs, and Tintin''s relentless courage in one of the most suspenseful comic adventures ever drawn!', 'Spremite se za drevnu kletvu Inka, misteriju rasutih kristalnih kugli i neodoljivu Tintinovu hrabrost u jednoj od najnapetijih strip-avantura!', '/covers/DP-0842.webp', '#1c3d5a', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","spooky","friends"]', '["comics","tintin","mystery","inca","detective"]', 1792836322700, 1792845681924);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('храм-солнца-843', 'DP-0843', 'Храм солнца', 'Prisoners of the Sun', 'Hram sunca', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', '"Храм Солнца" - продолжение книги "7 хрустальных шаров", в которой рассказывается о загадочных происшествиях, случившихся с европейскими учёными в Южной Америке, и о странном исчезновении знаменитого профессора. Юный репортёр Тинтин в компании капитана Хэддока и верного пса Снежка отправляется на поиски профессора. Им предстоит преодолеть немало трудностей, порой опасных для жизни. Но самое невероятное путешественников ждёт в конце пути, когда они неожиданным образом попадают в храм Солнца…', 'The thrilling sequel to The Seven Crystal Balls! Young reporter Tintin, Captain Haddock, and faithful dog Snowy journey deep into the Peruvian Andes on a dangerous rescue mission to save the kidnapped Professor Calculus, leading them straight into the hidden and treacherous Temple of the Sun.', 'Uzbudljivi nastavak stripa „Sedam kristalnih kugli“! Mladi reporter Tintin, kapetan Hadok i vjerni pas Sneško kreću duboko u peruanske Ande u opasnu spasilačku misiju kako bi pronašli profesora Kalkulusa, što ih vodi pravo do skrivenog i tajanstvenog Hrama sunca.', 'Запасайтесь ламами и держите шляпы: Тинтин и капитан Хэддок отправляются в Анды навстречу древним тайнам инков!', 'Pack your llamas and hold onto your hats: Tintin and Captain Haddock are trekking through the Andes to uncover ancient Inca secrets!', 'Pripremite lame i čuvajte šešire: Tintin i kapetan Hadok kreću kroz Ande u susret drevnim tajnama Inka!', '/covers/DP-0843.webp', '#e09228', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends","funny"]', '["comics","tintin","incas","peru","mystery"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-америке-844', 'DP-0844', 'в Америке', 'Tintin in America', 'Tintin u Americi', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Тинтин продолжает борьбу с мощнейшим преступным синдикатом - чикагской бандой, которая пыталась взять под контроль добычу алмазов в Африке. Юному бельгийскому репортёру всё-таки удалось нарушить планы гангстеров! Судьба привела его в Чикаго, именно тут Тинтин намерен поставить точку в этом запутанном и очень опасном деле. Не раз он, преследуя бандитов, оказывался на краю гибели. Так неужели ему повезёт и с мафией будет покончено?', 'Tintin heads straight into 1930s Chicago to take down a notorious criminal syndicate. Armed with courage, quick wit, and accompanied by his loyal dog Snowy, the intrepid young reporter braves high-speed chases and mob traps in this legendary graphic novel adventure.', 'Tintin stiže u Čikago tridesetih godina prošlog vijeka kako bi stao na put moćnom gangsterskom klanu. Uz pomoć svog vjernog psa Milua, neustrašivi reporter upada u opasne zamke, jurnjave i nevjerovatne preokrete u ovom uzbudljivom klasičnom stripu.', 'Пристегните ремни: неутомимый Тинтин и храбрый Милу объявляют войну чикагским гангстерам в классическом остросюжетном комиксе!', 'Fasten your seatbelts: Tintin and his loyal pup Snowy take on Chicago''s fiercest mobsters in this whirlwind classic comic caper!', 'Vežite pojaseve: neumorni Tintin i njegov vjerni pas Milu kreću u obračun s čikaškim gangsterima u kultnom stripovskom klasiku!', '/covers/DP-0844.webp', '#b83a24', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","funny","friends"]', '["comics","tintin","detective","gangsters","investigation"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-конго-845', 'DP-0845', 'в Конго', 'Tintin in the Congo', 'Tintin u Kongu', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Известный своими авантюрными приключениями молодой бельгийский репортёр Тинтин отправился в путешествие по Африке. Но он даже не предполагал, чем это для него обернётся! Разве Тинтин мог подумать, что окажется в центре хитроумной операции короля чикагских гангстеров, который намеревался взять под контроль добычу алмазов в Африке? Юноша встал у бандита на пути, и его решили убрать… Чем же закончатся африканские приключения репортёра?', 'The intrepid young Belgian reporter Tintin sets off on an expedition to Africa, unaware of the dangers in store! He could never have imagined crossing paths with a syndicate of Chicago gangsters plotting to seize control of the diamond trade. Marked for elimination, Tintin must outsmart the criminals to survive this high-stakes safari adventure.', 'Mladi belgijski reporter Tintin kreće na uzbudljivo putovanje po Africi, ni ne sluteći kakve ga opasnosti čekaju! Ko bi pomislio da će se naći usred lukave operacije čikaških gangstera koji žele da preuzmu kontrolu nad afričkim dijamantima? Tintin im staje na put i moraće da upotrijebi svu svoju snalažljivost da bi se izvukao.', 'Пристегните ремни: отважный репортёр Тинтин и его верный пёс Милу бросают вызов мафии прямо посреди саванны!', 'Fasten your seatbelts: brave reporter Tintin and his loyal dog Snowy face off against big-city mobsters in the heart of the African wilderness!', 'Vežite pojaseve: neustrašivi reporter Tintin i njegov vjerni pas Miki kreću u obračun sa mafijom usred afričke divljine!', '/covers/DP-0845.webp', '#e2a926', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","animals"]', '["tintin","comics","detective","travel","africa"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('скипетр-оттокара-846', 'DP-0846', 'скипетр Оттокара', 'King Ottokar''s Sceptre', 'Žezlo kralja Otokara', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Молодой репортёр Тинтин случайно знакомится с профессором Мудрено, специалистом по сигиллографии – науке, занимающейся изучением печатей. Профессор намерен отправиться в далёкую страну Сильдавию для дальнейшей исследовательской работы, и Тинтин едет с ним. И вот тут начинают происходить странные события, которые наводят репортёра на мысль: против короля Сильдавии готовится заговор. К тому же оказывается, что похищен главный символ королевской власти государства – скипетр…', 'Young reporter Tintin accidentally crosses paths with Professor Alembick, an expert in sigillography—the study of seals. Tintin accompanies him on a research trip to the remote kingdom of Syldavia. Soon, mysterious and threatening events reveal a dangerous conspiracy against the King, as well as the shocking theft of the nation''s sacred royal sceptre.', 'Mladi reporter Tintin slučajno upoznaje profesora Alembika, stručnjaka za sigilografiju – nauku o pečatima. Kada profesor krene u daleku zemlju Sildaviju, Tintin putuje s njim. Ubrzo počinju da se nižu sumnjivi događaji koji novinara navode na trag opasne zavjere protiv kralja i krađe najvažnijeg simbola vlasti – kraljevskog žezla.', 'Захватывающий балканский детектив с королевскими тайнами, погонями и отважным Тинтином, который всегда готов спасти корону!', 'A thrilling royal mystery packed with high-stakes intrigue, chases, and Tintin ready to save the kingdom!', 'Uzbudljiva kraljevska misterija puna intriga, jurnjave i neustrašivog Tintina koji je uvijek spreman da spasi presto!', '/covers/DP-0846.webp', '#9c2c27', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends"]', '["tintin","detective","comics","royal mystery","investigation"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('путешественники-на-луне-847', 'DP-0847', 'путешественники на Луне', 'Explorers on the Moon', 'Istraživači na Mjesecu', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'В этой книге - продолжение приключений Тинтина и его постоянных спутников - капитана Хэддока и забавного пса Снежка. Читатель уже знаком с тем, как начались эти, пожалуй, самые рискованные, самые грандиозные приключения троицы, они описаны в книге "Пункт назначения - Луна". Так вот, полёт на эту далёкую планету всё-таки состоялся! Что ждёт путешественников там? Какие опасности их подстерегают? И главное - вернутся ли они на Землю? А это, как выяснилось, проблема…', 'The epic lunar journey of Tintin, Captain Haddock, and their faithful dog Snowy continues! Following their departure in ''Destination Moon'', our intrepid explorers have actually landed on the lunar surface. But what perils lurk in the silence of space, and will the crew ever manage to return safely to Earth?', 'U ovoj knjizi nastavljaju se avanture Tintina i njegovih nerazdvojnih saputnika — kapetana Hadoka i vjernog psa Sneška. Let na Mjesec je uspio, ali šta ih tamo čeka? Koje opasnosti vrebaju u tami svemira i, što je najvažnije, hoće li uopšte uspjeti da se vrate nazad na Zemlju?', 'Пристегните ремни: легендарная красно-белая ракета уже на Луне, а капитан Хэддок в скафандре — это незабываемое зрелище!', 'Fasten your seatbelts: Tintin’s iconic rocket has landed on the Moon, and Captain Haddock floating in a spacesuit is sheer delight!', 'Vežite pojaseve: Tintinova čuvena raketa sletjela je na Mjesec, a kapetan Hadok u svemirskom odijelu prizor je koji se ne zaboravlja!', '/covers/DP-0847.webp', '#1d2951', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","funny","friends"]', '["tintin","comics","space","moon","classic"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-тибете-848', 'DP-0848', 'в Тибете', 'Tintin in Tibet', 'Tintin na Tibetu', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Произошла катастрофа – самолёт, летевший в Катманду, потерпел крушение где-то в районе горного массива. Молодой бельгийский репортёр Тинтин с ужасом узнаёт, что в самолёте находился его китайский друг Чан. Неужели он погиб?! Юноша отказывается в это верить, тем более ему приснился сон, в котором Чан, находясь в снежной западне, просит о помощи. Пусть это всего лишь сон и Чана наверняка уже нет в живых, Тинтин всё-таки решает отправиться на его поиски…', 'When a plane crashes in the Himalayas, Tintin is devastated to learn his dear friend Chang was aboard. Refusing to believe the worst after a vivid dream where Chang cries out for help, the brave reporter sets off across the treacherous snowy peaks of Tibet on an unforgettable rescue mission.', 'Nakon avionske nesreće na Himalajima, Tintin s užasom saznaje da je u avionu bio njegov prijatelj Čang. Odbijajući da povjeruje da je stradao nakon neobičnog sna u kojem ga Čang doziva u pomoć, mladi reporter kreće u opasnu spasilačku misiju kroz sniježne i nepristupačne tibetanske vrhove.', 'Запасайтесь тёплым шарфом и мужеством: отправляемся вместе с Тинтином и Снежком в снежные Гималаи спасать верного друга!', 'Bundle up with your warmest scarf: join Tintin and Snowy on a breathtaking Himalayan trek proving that true friendship can move mountains!', 'Pripremite najtopliji šal: pođite sa Tintinom u sniježne Himalaje na dirljivo i uzbudljivo putovanje koje dokazuje da pravo prijateljstvo pomjera planine!', '/covers/DP-0848.webp', '#3b7a99', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends"]', '["комиксы","горы","дружба","путешествия","спасение"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секрет-единогрога-849', 'DP-0849', 'Секрет единогрога', 'The Secret of the Unicorn', 'Tajna Jednoroga', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Однажды Тинтин на блошином рынке купил модель великолепного старинного корабля, носящего гордое имя "Единорог". "Неплохой подарок!" - подумал он, намереваясь преподнести корабль своему другу, капитану Хэддоку, бывалому морскому волку. Но… корабль похитили! Бросившись на его поиски, Тинтин с капитаном убеждаются, что это не простое ограбление: слишком много тайн с ним связано, слишком много вопросов. И самое главное - какую роль во всём этом играет пергаментный свиток, обнаруженный в мачте "Единорога"?..', 'While browsing a flea market, Tintin buys an antique model ship named the Unicorn as a gift for Captain Haddock. But when the model is mysteriously stolen, Tintin and the blustery Captain dive into an exhilarating investigation involving hidden parchments, pirate ancestors, and long-lost treasure.', 'Kada Tintin na buvljaku kupi prelijepu maketu drevnog broda „Jednorog” za kapetana Hadoka, model biva misteriozno ukraden! Ubrzo otkrivaju da to nije obična pljačka, već početak uzbudljive potrage za skrivenim pergamentima, piratskim tajnama i zaboravljenim blagom.', 'Классический детектив в комиксах: старинный корабль, тайники в мачтах и капитан Хэддок во всем блеске своего морского темперамента!', 'A masterclass in comic book mystery with antique ships, coded riddles, and Captain Haddock at his blustering best!', 'Klasična stripovska misterija sa drevnim jedrenjacima, šifrovanim mapama i kapetanom Hadokom u punom pomorskom žaru!', '/covers/DP-0849.webp', '#1c446c', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends","funny"]', '["tintin","comics","detective","sea adventure","treasures"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('краб-с-золотыми-клешнями-850', 'DP-0850', 'Краб с золотыми клешнями', 'The Crab with the Golden Claws', 'Rak sa zlatnim kliještima', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Очередные захватывающие приключения молодого репортёра Тинтина не заставили себя долго ждать. Иначе и быть не могло - у этого юноши поразительный нюх на всякого рода авантюры. Погони, перестрелки, опасные путешествия и даже долгий, изнурительный переход пустыни Сахары! Отважный Тинтин ни перед чем не остановится, чтобы обезвредить преступную группировку, которая занимается распространением опиума, спрятав его в консервных банках из-под краба. Но противник слишком хитёр и коварен. Что же предпримет Тинтин на этот раз?.', 'Young reporter Tintin is hot on the trail of a cunning gang of smugglers hiding contraband inside harmless-looking tins of crab meat. From perilous sea voyages and gunfights to an exhausting trek across the scorching Sahara desert, Tintin will stop at nothing—and on this unforgettable journey, he meets Captain Haddock for the very first time!', 'Mladi reporter Tintin ulazi u trag opasnoj bandi krijumčara koji skrivaju nedozvoljene supstance u konzervama kraba. Od uzbudljivih potjera i pucnjava na pučini mora do iscrpljujućeg prelaska preko vrele Sahare, hrabri novinar neće ustuknuti ni pred čim — a upravo ovdje po prvi put upoznaje nezaboravnog kapetana Hadoka!', 'Пристегните ремни: именно в этой классической истории Тинтин среди песков Сахары знакомится с неподражаемым капитаном Хэддоком!', 'Buckle up: this is the historic adventure where Tintin first meets the loud and lovable Captain Haddock among desert sands and crab tins!', 'Vežite pojaseve: upravo u ovoj nezaboravnoj avanturi Tintin po prvi put sreće neponovljivog kapetana Hadoka usred pustinjskog pijeska!', '/covers/DP-0850.webp', '#d9822b', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","funny","friends"]', '["comics","tintin","detective","desert","travel"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сокровище-красного-ракхама-851', 'DP-0851', 'сокровище красного ракхама', 'Red Rackham''s Treasure', 'Blago Crvenog Rakama', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Наконец-то Тинтин и его друг капитан Хэддок выяснили, какую тайну хранит старинный пергаментный свиток, обнаруженный в мачте корабля "Единорог"! Впоследствии оказалось, что свитков на самом деле было три! Собрав их вместе, друзья поняли, что в них зашифрованы координаты места, где находится сокровище Красного Ракхама - предводителя пиратов. Но до него не так-то просто добраться. Тинтин и капитан смело отправляются в опасное путешествие, которое обещает стать невероятно захватывающим приключением!', 'At last, Tintin and his faithful friend Captain Haddock have deciphered the ancient mystery of the scrolls hidden within the ship Unicorn! Combining the clues reveals the exact coordinates of pirate leader Red Rackham''s fabled sunken treasure. Braving deep waters, underwater perils, and Professor Calculus''s quirky submarine invention, the duo embarks on an unforgettable maritime expedition.', 'Napokon su Tintin i kapetan Hadok odgonetnuli tajnu starog pergamenta pronađenog u jarbolu broda „Jednorog“! Spojivši sva tri pronađena svitka, prijatelji otkrivaju koordinate basnoslovnog blaga gusarskog vođe Crvenog Rakama. Hrabro zaplovivši u nepoznate vode, kreću u nezaboravnu morsku ekspediciju punu neobičnih izuma i uzbudljivih ronilačkih avantura.', 'Надевайте водолазный шлем и готовьтесь нырять за пиратским золотом вместе с неунывающими Тинтином и капитаном Хэддоком!', 'Fasten your diving helmet and get ready to plunge into the deep blue for sunken pirate gold alongside Tintin and Captain Haddock!', 'Stavite ronilački šljem i zaronite u potragu za potopljenim gusarskim zlatom u društvu Tintina i kapetana Hadoka!', '/covers/DP-0851.webp', '#1e5b7c', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends","funny"]', '["comics","pirates","treasure","sea voyage","diving"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('голубой-лотос-852', 'DP-0852', 'голубой лотос', 'The Blue Lotus', 'Plavi lotos', 'Эрже', 'Hergé', 'Erže', 'Эрже', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Приключения Тинтина продолжаются! В книге «Сигары фараона» молодому репортёру удалось разоблачить международное преступное сообщество, занимавшееся контрабандой наркотиков. Казалось бы, дело закрыто. Но не тут-то было – после прибытия Тинтина в Шанхай на него вновь начинают охоту члены преступной группировки. С этого момента репортёр попадает в водоворот невероятных событий и захватывающих приключений, пытаясь выяснить, кто же всё-таки стоит во главе сети торговцев наркотиками.', 'Tintin''s adventures continue! Following the events of ''Cigars of the Pharaoh'', the intrepid young reporter arrives in 1930s Shanghai, only to find himself hunted once again by a ruthless criminal syndicate. Plunged into a whirlwind of dangerous mysteries, Tintin risks everything to uncover the shadowy mastermind behind an international smuggling ring.', 'Tintinove avanture se nastavljaju! Nakon događaja iz „Faraonovih cigara“, mladi reporter stiže u Šangaj tridesetih godina prošlog vijeka, gdje se ponovo nađe na meti opasne kriminalne grupe. Uvučen u vrtlog napetih događaja i misterija, Tintin rizikuje sve kako bi otkrio ko zapravo stoji na čelu međunarodne švercerske mreže.', 'Отправляйтесь вместе с бесстрашным Тинтином и верным Милу на колоритные улочки Шанхая разгадывать опасные тайны!', 'Pack your bags for 1930s Shanghai and join Tintin and Snowy on one of their most iconic, action-packed mystery investigations!', 'Spakujte kofere za Šangaj tridesetih godina i pridružite se Tintinu i Snešku u jednoj od njihovih najuzbudljivijih detektivskih avantura!', '/covers/DP-0852.webp', '#b82326', 'nonfiction', 'ru', 'available', 'комикс', '["adventure","friends"]', '["comics","tintin","detective","china","travel"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('астерикс-из-галлии-853', 'DP-0853', 'Астерикс из Галлии', 'Asterix the Gaul', 'Asteriks Gal', 'Госини, Удерзо', 'René Goscinny, Albert Uderzo', 'Rene Gosini, Alber Uderzo', 'Госини, Удерзо', 'Махаон', NULL, NULL, 6, 16, 'middle', 'АСТЕРИКС и ОБЕЛИКС – пожалуй, самые знаменитые герои комиксов, об их приключениях написано более 30 историй, авторами которых являются известный французский писатель Рене Госинни и его соотечественник художник Альбер Удерзо.', 'Asterix and Obelix are perhaps the world''s most famous comic duo. Created by René Goscinny and Albert Uderzo, their hilarious adventures follow a tiny, indomitable Gaulish village holding out against the mighty Roman Empire with the help of a secret magic potion.', 'Asteriks i Obeliks su vjerovatno najslavniji strip junaci na svijetu. Duhovite avanture ovog nerazdvojnog dvojca iz nepokornog galskog sela koje prkosi moćnom Rimskom carstvu, stvorene iz pera Renea Gosinija i Albera Uderzoa, osvajaju generacije čitalaca.', 'Глоток волшебного зелья, щепотка остроумия — и непобедимые галлы снова готовы проучить самоуверенных римлян!', 'A sip of magic potion, a dash of brilliant wit, and these indomitable Gauls are ready to send the Romans flying once again!', 'Gutljaj čarobnog napitka, zrno vrcavog humora — i nepokorni Gali su spremni da opet pošalju rimske legionare u vazduh!', '/covers/DP-0853.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'комикс', '["funny","adventure","friends"]', '["comics","gauls","romans","humor","adventure"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('астерикс-и-транситалика-854', 'DP-0854', 'Астерикс и транситалика', 'Asterix and the Chariot Race', 'Asteriks i Transitalika', 'Госини, Удерзо', 'René Goscinny, Albert Uderzo', 'Rene Gosini, Alber Uderzo', 'Госини, Удерзо', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Состояние римских дорог вызывает у народов Италии всё больше нареканий... Однако сенатор Лакт Бактерий, отвечающий за дорожную сеть, не намерен признавать очевидное: он устраивает невиданную доселе гонку колесниц через весь полуостров! К участию приглашаются экипажи со всего известного мира... Само собой, галлы из деревни неукротимых не могли остаться в стороне от такого события! Но у Юлия Цезаря другие планы: в гонке во что бы то ни стало должен победить представитель Рима.', 'The state of Roman roads is causing outrage across Italy... But Senator Lactus Bifidus, responsible for the road network, refuses to admit the problem. Instead, he organizes an epic chariot race across the entire peninsula, inviting racers from across the known world! Naturally, the indomitable Gauls cannot resist such a challenge, but Julius Caesar has other plans: a Roman must win at all costs.', 'Stanje rimskih puteva izaziva sve veće nezadovoljstvo među stanovnicima Italije... Međutim, korumpirani senator Laktus Bifidus ne priznaje krivicu: umjesto toga organizuje spektakularnu trku dvokolica duž čitavog poluostrva! Ekipe stižu sa svih strana poznatog svijeta... Naravno, nepokorni Gali ne propuštaju priliku da se takmiče, ali Julije Cezar ima drugačije planove: pobjedu po svaku cijenu mora odnijeti Rim.', 'Пристегните ремни на колесницах: Астерикс и Обеликс мчат по солнечной Италии, обгоняя коварных римлян и поедая горы местных деликатесов!', 'Buckle up your chariot belts: Asterix and Obelix are racing across sunny Italy, outsmarting Roman rivals and sampling every local delicacy along the way!', 'Vežite se u dvokolicama: Asteriks i Obeliks jure kroz sunčanu Italiju, nadmudruju Rimljanje i usput uživaju u svim mogućim đakonijama!', '/covers/DP-0854.webp', '#d64527', 'nonfiction', 'ru', 'available', 'комикс', '["funny","adventure","friends"]', '["comics","asterix","chariot race","ancient rome","italy"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кот-в-шляпе-855', 'DP-0855', 'Кот в шляпе', 'The Cat in the Hat', 'Mačak u šeširu', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Seuss', 'Доктор Сьюз', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Вы слышали про Доктора Сьюза? Он пишет детские стихи и сказки, сам рисует к ним картинки и даже умеет делать мультики. Его книги переведены на множество языков и вот уже несколько десятков лет расходятся миллионными тиражами. Между прочим, Доктор Сьюз самый продаваемый в мире англоязычный автор книжек для малышей. По его стихам снимались мультфильмы, ставились мюзиклы и радиоспектакли, его именем названа престижная литературная премия, а в Америке есть целый парк со скульптурами его героев. Многие поколения детей выросли бок о бок с добродушным слоном Хортоном, котом в шляпе и Гринчем, зловредным похитителем Рождества. Предположим, сидите вы дома с младшей сестрёнкой. День — скучнее не придумаешь. За окном дождик, и заняться решительно нечем. И тут на вашем пороге объявляется… КОТ В ШЛЯПЕ! Говорящими котами нынче никого не удивишь, но этот-то к тому же ещё и редкостный озорник, затейник и фокусник. И чего он только не выделывает! Всё у него в лапах ходит ходуном, а дом переворачивается вверх дном. Вашей скуки как не бывало! Только вот что скажет на всё это мама, когда вернётся?..', 'Bored and stuck inside on a dreary, rainy afternoon with nothing to do, two siblings get an unexpected visitor: a tall, mischievous cat in a red-and-white striped top hat! With his boundless energy, balancing tricks, and unruly companions Thing One and Thing Two, the Cat turns the entire house upside down in a whirlwind of fun. But can they tidy up the chaotic mess before Mom comes home?', 'Zarobljeni u kući po kišnom, dosadnom danu, brat i sestra ne znaju šta bi sa sobom — sve dok na vrata ne zakuca neobičan gost: visoki, nestašni mačak u prugastom šeširu! Sa svojim ludim trikovima i nepredvidivim pomoćnicima Stvarcom Jedan i Stvarcom Dva, on kuću okreće naglavačke. Ali hoće li uspjeti sve pospremiti prije nego što se mama vrati?', 'Осторожно: эта озорная рифмованная классика Доктора Сьюза мигом прогонит скуку и превратит любой дождливый день в невероятный карнавал!', 'Warning: this playful, rhyming classic is guaranteed to cure rainy-day boredom and turn your living room into a whirlwind of joy!', 'Pazite se: ova nestašna rima Doktora Susa začas će otjerati dosadu i svaki kišni dan pretvoriti u urnebesni cirkus!', '/covers/DP-0855.webp', '#d8232a', 'nonfiction', 'ru', 'available', 'Категория: Доктор Сьюз', '["funny","animals","adventure"]', '["rhymes","cats","classic","mischief","rainy day"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дриад-856', 'DP-0856', 'Дриад', 'The Lorax', 'Loraks', 'Доктор Сьюз', 'Dr. Seuss', 'Dr Sus', 'Доктор Сьюз', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Познакомьтесь же и вы с замечательными героями этих книг! Например, с чудесным Дриадом. Однажды, давным-давно в прекрасной роще пуховых пальм, населённой удивительными зверюшками, каких больше нигде не встретишь, жил-поживал добрый Дриад. Но однажды пропал, вместе с дивной рощей и сказочным зверьём. Что же случилось, где они теперь и как их вернуть? Всё расскажет нелюдимый Мак-Глот…', 'Long ago, in a vibrant grove of Truffula Trees filled with wondrous creatures, lived the gentle Lorax, who spoke for the trees. But one day, greed took over and the paradise vanished into thin air. What happened to the lush forest, where did all the animals go, and is there any hope to bring them back? The reclusive Once-ler is finally ready to reveal the cautionary tale.', 'Nekada davno, u predivnom gaju mekih stabala prepunom neobičnih stvorenja kakva se nigdje drugo ne sreću, živio je dobrodušni Loraks. Ali jednoga dana čitav raj je nestao bez traga. Šta se zapravo dogodilo, kuda su otišle čudesne životinje i postoji li način da se sve vrati? Usamljeni zanesenjak spreman je da ispriča cijelu istinu...', 'Мудрая и трогательная экологическая притча о том, как одно крошечное семечко и искренняя забота способны спасти целый мир.', 'A wise and wonderfully rhythmic fable reminding us that one tiny seed—and one caring heart—can heal an entire world.', 'Mudro i dirljivo podsjećanje da samo jedno malo sjeme i pažljivo srce mogu spasiti čitavu prirodu.', '/covers/DP-0856.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: Доктор Сьюз', '["adventure","animals","real"]', '["ecology","nature","trees","classic","fable"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хортон-высиживает-яйцо-857', 'DP-0857', 'Хортон высиживает яйцо', 'Horton Hatches the Egg', 'Horton leži na jajetu', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Seuss', 'Доктор Сьюз', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Птичке Мэйзи надоело высиживать яйцо. Легкомысленная особа эта Мэйзи — подавай ей отпуск, и всё тут! Раз такое дело, необходимо найти того, кто согласится вместо неё посидеть на гнезде. И оглядевшись по сторонам, Мэйзи обнаруживает… слона Хортона! Почему бы и нет? Слон, конечно, не птичка, но он такой добрый и заботливый! Решено: Мэйзи уговаривает Хортона занять своё место на гнезде, а сама улетает прохлаждаться в Майами. Хортон же отнёсся к делу со всей ответственностью... Что из этого вышло, читайте в книжке Доктора Сьюза!', 'Lazy bird Mayzie is bored of sitting on her egg and decides she desperately needs a vacation in Miami. Looking around for a substitute sitter, she spots Horton the elephant. He is kind, gentle, and agrees to keep the egg warm until she returns. While Mayzie sunbathes, faithful Horton braves storms, hunters, and ridicule, keeping his promise no matter what! Find out what hatches in this hilarious and heartwarming classic by Dr. Seuss.', 'Ptici Mejzi je dosadilo da leži na svom jajetu — njoj se ide na odmor u sunčani Majami! Kako bi zbrisala, traži nekoga ko će je zamijeniti u gnijezdu i pronalazi dobronamjernog slona Hortona. Iako slonovi rijetko sjede po drveću, Horton preuzima zadatak sa stopostotnom odgovornošću. Šta se desi kada slon odluči da po svaku cijenu održi riječ, saznajte u ovoj predivnoj priči u stihovima Doktora Susa!', 'Слон на дереве — это само по себе умора, но верность и благородство Хортона растопят сердце любого читателя!', 'An elephant up in a tree is funny enough, but Horton''s unwavering loyalty to an egg will completely steal your heart!', 'Slon na drvetu je već sam po sebi urnebesan, a Hortonova nepokolebljiva odanost malom jajetu rastopiće svako srce!', '/covers/DP-0857.webp', '#3f829d', 'nonfiction', 'ru', 'available', 'Категория: Доктор Сьюз', '["funny","animals","friends"]', '["rhymes","elephants","loyalty","kindness","humor"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('это-только-начало-858', 'DP-0858', 'Это только начало', 'Oh, the Places You''ll Go!', 'Mjesta na koja ćeš stići!', 'Доктор Сьюз', 'Dr. Seuss', 'Doktor Sus', 'Доктор Сьюз', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Представьте, что сегодня самый замечательный в мире день. День, когда можно выбрать что угодно и пойти куда угодно — все пути открыты, нужно только немножко решимости! Ведь если есть голова на плечах и две ноги в башмаках, значит, никакие тупые тупики, глухие заборы и окна без света не страшны. Эта книжка Доктора Сьюза, которую вы держите в руках, — лучшее на свете напутствие. Берите его — и вперёд! Ведь это только начало!', 'Imagine today is the most wonderful day in the world—a day when every path is wide open, waiting only for a dash of courage! With brains in your head and feet in your shoes, no dead ends or gloomy walls can ever hold you back. Dr. Seuss''s iconic, heartwarming guide to life''s grand journey is the ultimate send-off into the big world. Take a deep breath and step forward—after all, this is only the beginning!', 'Zamislite da je danas najdivniji dan na svijetu — dan kada su vam svi putevi otvoreni i kada je potrebno samo malo odlučnosti! Jer kad imate pamet u glavi i noge u cipelama, nijedan ćorsokak ni visoki zid ne mogu vas zaustaviti. Ova bezvremena knjiga Doktora Susa najljepši je vodič kroz sve uspone i padove koje život nosi. Uzmite je i krenite hrabro naprijed, jer ovo je tek početak!', 'Идеальное стихотворное напутствие для каждого, кто отправляется покорять новые горизонты — даже если этот горизонт пока просто первый класс!', 'The ultimate rhyming pep talk for anyone setting off to conquer new horizons—even if that horizon is simply stepping into a new classroom!', 'Savršeni stihovani podsticaj za svakoga ko kreće u osvajanje novih visina — čak i ako je ta avantura tek polazak u novu školu!', '/covers/DP-0858.webp', '#e5b842', 'nonfiction', 'ru', 'available', 'Категория: Доктор Сьюз', '["adventure","funny"]', '["dr seuss","growing up","motivation","rhymes","life lessons"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хортон-слышит-ктошку-859', 'DP-0859', 'Хортон слышит ктошку', 'Horton Hears a Who!', 'Horton čuje Koga!', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Seuss', 'Доктор Сьюз', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Однажды в джунглях Чавка слон Хортон услышал странный звук. Как-будто кто-то очень маленький – такой маленький, что уже невидимый! – звал на помощь. Конечно, Хортон не мог остаться в стороне. И отзывчивость великодушного слона спасла целый Ктошкоград!', 'One day in the Jungle of Nool, Horton the elephant hears a faint cry for help coming from a tiny speck of dust. It turns out an entire microscopic community called Whoville lives on that speck! Despite mockery and danger from his jungle neighbors, big-hearted Horton vows to protect them all, because after all, ''a person''s a person, no matter how small.''', 'Jednog dana u džungli Nul, slon Horton čuje tihi poziv u pomoć koji dopire sa sićušnog zrnca prašine. Ispostavlja se da na tom zrncu živi čitav minijaturni grad! Uprkos ruganju i opasnostima od ostalih stanovnika džungle, dobrodušni Horton odlučuje da ih zaštiti, jer ipak — osoba je osoba, ma koliko bila mala.', 'Трогательная и звонкая классика, напоминающая о том, что даже самое крошечное существо заслуживает большого и верного защитника.', 'A timeless, rhythmic reminder that kindness knows no size and that a person''s a person, no matter how small!', 'Dirljiva i ritmična priča koja nas podsjeća da dobrota nema veličinu i da je svako biće važno, ma koliko malo bilo!', '/covers/DP-0859.webp', '#4a92c4', 'nonfiction', 'ru', 'available', 'Категория: Доктор Сьюз', '["animals","friends","funny"]', '["elephants","kindness","rhymes","classic","friendship"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('с-днем-рождения--860', 'DP-0860', 'С днем рождения!', 'Happy Birthday to You!', 'Srećan rođendan!', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Sus', 'Доктор Сьюз', 'Азбука', NULL, NULL, 6, 16, 'middle', 'А с Деньрожденной Птицей хотите познакомиться? С ней вы можете попасть в сказочную страну Трубению, где день рождения празднуют с неслыханным размахом! Или даже не дожидаясь этого дня, прямо сейчас пуститься в волшебное приключение!', 'Would you like to meet the Great Birthday Bird? Together you will journey to the fabulous land of Katroo, where birthdays are celebrated on a truly unmatched, spectacular scale! You don''t even have to wait for your special day to begin this joyful adventure right now.', 'Želite li da upoznate Rođendansku Pticu? Sa njom možete odletjeti u čarobnu zemlju Katru, gdje se rođendani slave sa nezapamćenim veseljem i sjajem! Ne morate čekati svoj poseban dan — prepustite se ovoj otkačenoj avanturi odmah.', 'Даже если до праздника ещё далеко, эта уморительная история подарит стопроцентное ощущение самого грандиозного дня рождения в мире!', 'Even if your special day is months away, this whimsical classic makes you feel like the most celebrated kid in the whole wide universe!', 'Čak i ako ti rođendan nije skoro, ova vesela knjiga učiniće da se osjećaš kao najvažniji slavljenik na planeti!', '/covers/DP-0860.webp', '#f5a623', 'nonfiction', 'ru', 'available', 'Категория: Доктор Сьюз', '["funny","magic","adventure"]', '["birthday","rhymes","party","celebration","dr seuss"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вот-ужас--861', 'DP-0861', 'Вот ужас!', 'The Book of Spooks', 'Kakva strava!', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Приведения и домовые, ужасный снежный человек и мумия фараона, граф Дракула и ведьма тётушка Кривонос… Вот Ужас! Кто ещё прячется в этой книге? Но не бойтесь, она вовсе не страшная - ведь каждая история Маури Куннаса сдобрена юмором и обязательно хорошо заканчивается.', 'Ghosts, house brownies, the abominable snowman, a pharaoh''s mummy, Count Dracula, and witch Auntie Crooknose... What a scare! Who else is lurking in this book? Don''t worry at all—it isn''t truly frightening, because every story by Mauri Kunnas is packed with cheerful humor and always has a happy ending.', 'Duhovi i kućni patuljci, strašni jeti i faraonova mumija, grof Drakula i vještica Krivonosić... Kakva strava! Ko se još krije među ovim stranicama? Ne bojte se, nije nimalo strašno – svaka priča Maurija Kunasa začinjena je humorom i uvjek se srećno završava.', 'Самая уютная и уморительная перепись сказочной нечисти, которую совершенно невозможно бояться!', 'The coziest and most hilarious encyclopedia of legendary creeps and ghouls you''ll ever laugh through!', 'Najsmješniji i najtopliji vodič kroz čudovišta i duhove kojih se uopšte ne možete uplašiti!', '/covers/DP-0861.webp', '#382d54', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["spooky","funny","magic"]', '["monsters","ghosts","humor","folklore","picture book"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('веселые-машинки-862', 'DP-0862', 'Веселые машинки', 'Funny Cars', 'Veseli automobili', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Грузовики, фургоны, электромобили, гоночные машины, драгстеры, пожарные машины, автобусы, мусоровозы, мотоциклы, джипы... В этой книге есть все средства передвижения от бабушкиного кабриолета до самого суперсовременного автомобиля на солнечных батареях. А это кто там на заправочной станции? Уж не Красная ли Шапочка с Серым Волком? А кто плачет в темноте подземной парковки? Гензель и Гретель? Маури Куннас рассказывает об их приключениях в своей неподражаемой манере, на радость всем юным автомобилистам перенося в мир машин героев известных сказок: "Три желания", "Гензель и Гретель", "Красная Шапочка", "Три брата" и "Золушка".', 'Trucks, vans, sports cars, dragsters, fire engines, buses, garbage trucks, and even solar-powered futuristic vehicles—you will find every kind of transport imaginable here! But wait, who is that pumping gas at the station? Could it be Little Red Riding Hood and the Big Bad Wolf? Mauri Kunnas blends bustling motor mechanics with beloved fairy tales in his trademark hilarious style, sending classic characters on wheel-spinning adventures.', 'Kamioni, kombiji, električni automobili, trkačke mašine, vatrogasna vozila, autobusi, pa čak i automobili na solarni pogon — u ovoj knjizi nalazi se baš svako prevozno sredstvo! Ali ko je to na benzinskoj pumpi? Zar to nijesu Crvenkapa i Vuk? Mauri Kunas spaja svijet točkova i omiljenih bajki u svom prepoznatljivom duhovitom stilu, vodeći junake kroz urnebesne vožnje i saobraćajne avanture.', 'Любимые сказки жмут на газ: здесь Серый Волк рулит спорткаром, а на каждой странице спрятано столько забавных деталей, что оторваться просто невозможно!', 'Classic fairy tales hit the gas pedal: watch the Big Bad Wolf cruise in a sports car across pages bursting with hilarious hidden details!', 'Omiljene bajke daju pun gas: pogledajte Vuka za volanom trkačkog auta i otkrijte bezbroj urnebesnih detalja na svakoj stranici!', '/covers/DP-0862.webp', '#d83a2b', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["funny","adventure"]', '["cars","transport","fairy-tales","humor","picture-book"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рождественские-истории-863', 'DP-0863', 'Рождественские истории', 'Christmas Stories', 'Božićne priče', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Красочные, весёлые и захватывающие рождественские истории Маури Куннаса теперь собраны под одной обложкой! Выбирай подарки с гномом Вилле, попробуй поймать хитрого шамана и, конечно, загляни в гости к самому Санта-Клаусу! Скорее открывай эту книгу - и вперёд в деревню Корватунтури!', 'Colorful, humorous, and heartwarming Christmas tales by Mauri Kunnas are gathered together in one festive volume! Choose gifts with the cheerful elf Wille, track down a cunning trickster shaman, and visit Santa Claus himself at his magical village in Korvatunturi.', 'Šarene, vesele i uzbudljive božićne priče Maurija Kunasa sakupljene su u jednoj predivnoj knjizi! Birajte poklone sa patuljkom Vileom, nadmudrite lukavog šamana i zavirite u selo Deda Mraza u dalekom Korvatunturiju.', 'Загляните за кулисы мастерской Санты: столько уморительных гномов, секретных подарков и северного уюта вы ещё не видели!', 'Peek behind the scenes of Santa''s workshop: you''ve never met so many hilarious elves, secret surprises, and pure Nordic holiday cheer!', 'Zavirite iza kulisa radionice Deda Mraza: toliko veselih patuljaka, tajnih poklona i praznične topline još nijeste vidjeli!', '/covers/DP-0863.webp', '#b82626', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["magic","funny","adventure"]', '["christmas","santa claus","elves","winter","illustrations"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('марта-на-колядках-864', 'DP-0864', 'Марта на колядках', 'Martha Goes Caroling', 'Marta ide u koledare', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Накануне Рождества Марта и мама покидают Пёсью горку и отправляются в город навестить родных. Что за чудесная пора! На улицах разворачивается рождественское представление! Жители города собрались посмотреть, как школьники будут разыгрывать традиционные сценки из репертуара народного театра. Туомас нарядился мавританским царём, Матиас - царём Иродом, а Август несёт настоящую рождественскую звезду! Петух часовщика чуть было не сорвал представление, но горожане не дали артистов в обиду. Жители городка подпевали и аплодировали юным актёрам и разошлись по домам только тогда, когда на небе зажглись тысячи звёзд. А вам знакомы эти песни? Если нет, скорее открывайте эту книгу! В ней вы найдёте ноты, тексты песен, весёлую историю и неповторимую уютную атмосферу зимнего праздника!', 'On Christmas Eve, Martha and her mother leave Doghill behind to visit family in town. What a magical time! A lively Christmas pageant fills the snowy streets as schoolchildren perform beloved folk plays. Tuomas dresses as the Moorish king, Mathias as King Herod, and August proudly carries the Christmas star! Even a mischievous rooster can''t ruin the fun. Complete with sheet music, lyrics, and warm holiday cheer, this vibrant tale invites readers to sing along.', 'Uoči Božića, Marta i njena mama napuštaju Pasje brdo i odlaze u grad u posjetu rodbini. Na sniježnim ulicama odvija se pravo praznično veselje — đaci pripremaju tradicionalnu božićnu predstavu sa kraljevima, mudracima i zvijezdom vodiljom! Uz note, tekstove tradicionalnih pjesama i veselu priču, ova knjiga donosi neodoljivu toplinu i duh zimskih praznika u vaš dom.', 'Тёплая и весёлая рождественская сказка с нотами и песнями, которая мгновенно наполнит дом праздничным уютом!', 'A warm and merry Christmas treat packed with carols, sheet music, and festive cheer that will have the whole family singing along!', 'Topla i vesela božićna priča puna pjesme i nota koja će unijeti pravi praznični duh u vaš dom!', '/covers/DP-0864.webp', '#c43b2f', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["animals","friends","funny"]', '["christmas","carols","traditions","dogs","music"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('водяной-на-песьей-горке-865', 'DP-0865', 'Водяной на песьей горке', 'The Water Spirit of Doghill', 'Vodenjak na Psećem brdu', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'На Пёсьей горке любят рассказывать страшные истории. Про леших, домовых, призраков и лесных разбойников. Правда, иногда на поверку оказывается, что злая ведьма - это всего лишь соседская старушка, а водяной - переодевшийся работник Юсси… Но зато все лешие и призраки - самые настоящие! Не верите? Прочтите книгу Маури Куннаса - и убедитесь сами !', 'On Doghill, everyone loves sharing spooky tales about wood goblins, brownie spirits, phantoms, and forest bandits. Sometimes the wicked witch turns out to be just the granny next door and the terrifying water spirit is farmhand Jussi in disguise... but some ghosts are undeniably real! Dive into Mauri Kunnas''s delightfully mischievous folklore and discover for yourself!', 'Na Psećem brdu svi obožavaju strašne priče o šumskim duhovima, babarogama, utvarama i šumskim razbojnicima. Ponekad se ispostavi da je zla vještica samo baka iz komšiluka, a vodeni duh preobučeni sluga Jusi... Ali neki duhovi su i te kako stvarni! Zavirite u ovu vragolastu knjigu Maurija Kunasa i uvjerite se sami!', 'Страшилки с национальным финским колоритом и фирменным пушистым юмором Маури Куннаса — совсем не страшные, а ужасно уютные!', 'Chilly folklore tales with Finnish flair and Mauri Kunnas''s signature doggy humor — not truly terrifying, but wildly cozy!', 'Finski folklor i vesele strašne priče uz prepoznatljiv humor Maurija Kunasa — nimalo strašne, već nevjerovatno tople i zabavne!', '/covers/DP-0865.webp', '#2c656b', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["spooky","funny","magic"]', '["folklore","scandinavian tales","spirits","dogs","humor"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зима-на-песьей-горке-866', 'DP-0866', 'Зима на песьей горке', 'Winter at Doghill', 'Zima na Pasjem brdu', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'На Пёсьей горке наступила зима, а вместе с ней - новые заботы. Жизнь на ферме наполнена трудом. Целыми днями не прекращается работа в лесу и хлеве, вечера проходят за рукоделием и домашними хлопотами под рассказы долгожителей. Иногда будни уступают место праздникам, и тогда на Пёсьей горке пируют и веселятся от всего сердца. О старых временах редко пишут столь увлекательно и красочно, как в серии книг Маури Куннаса. Весёлые и правдивые истории будет интересно почитать детям и взрослым.', 'Winter has arrived at Doghill, bringing along a flurry of seasonal chores and cozy traditions. Life on the farm never slows down: days are filled with fetching firewood in the frosty forest and caring for barn animals, while evenings are spent doing handicrafts by candlelight to the tales of the elders. And when hard work gives way to winter festivities, the whole village rejoices and feasts with all their heart! Mauri Kunnas brings bygone times to life with humor, vivid details, and heartwarming dog characters that both children and adults will adore.', 'Zima je stigla na Pasje brdo, a sa njom i novi poslovi i tople tradicije. Život na seoskom imanju pun je rada: dani prolaze u sječi drva u zaleđenoj šumi i brizi o stoci, dok su večeri rezervisane za ručni rad uz svijeće i priče starih mudraca. A kada dođe vrijeme praznika, na Pasjem brdu se slavi i gosti od srca! Rijetko ko o starim vremenima piše tako duhovito i živopisno kao Mauri Kunas u ovoj predivnoj i poučnoj priči za sve uzraste.', 'Загляните на старинную заснеженную ферму, где симпатичные пёсики рубят дрова, прядут шерсть и весело празднуют Рождество!', 'Step into a bustling snow-covered farm where adorable dogs chop firewood, craft by the fire, and celebrate winter with unmatched cheer!', 'Zavirite na starinsko snježno imanje gdje simpatični psići cijepaju drva, predu vunu i veselo dočekuju zimske praznike!', '/covers/DP-0866.webp', '#4b6b94', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["animals","real","funny"]', '["winter","history","farm life","traditions","dogs","folklore"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('господин-хакарайнен-считает-ов-867', 'DP-0867', 'Господин Хакарайнен считает овец', 'Mr. Clutterbuck Counts Sheep', 'Gospodin Hakarajnen broji ovce', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'В этой книге ты познакомишься с множеством забавных персонажей. Сколько их на самом деле? Отважный господин Хаккарайнен снова гуляет во сне. Он встречает пять диких ковбоев, десять лающих собак и целых двенадцать милых привидений... Скорее отправляйся в путешествие вместе с господином Хаккарайненом и научись считать от одного до двадцати!', 'Meet a host of quirky characters alongside the beloved sleepwalking goat, Mr. Clutterbuck! As he strolls through his dreams, he encounters five wild cowboys, ten barking dogs, and even twelve friendly ghosts. Join Mr. Clutterbuck on this nocturnal romp and master counting from one to twenty!', 'U ovoj zabavnoj knjizi upoznaćete mnoštvo neobičnih likova dok neustrašivi gospodin Hakarajnen ponovo mjesečari! Srešće pet divljih kauboja, deset pasa koji laju i čak dvanaest simpatičnih duhova. Pođite s njim u noćnu avanturu i naučite da brojite od jedan do dvadeset!', 'Осторожно: с лунатиком господином Хакарайненом считать перед сном настолько весело, что можно случайно прохохотать весь отбой!', 'Counting sheep before bed has never been this hilariously chaotic—thanks to our favorite sleepwalking goat!', 'Brojanje pred spavanje nikad nije bilo ovoliko smiješno—pazite samo da vas gospodin Hakarajnen ne uvuče u noćno mjesečarenje!', '/covers/DP-0867.webp', '#2c4068', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["funny","adventure","animals"]', '["counting","numbers","sleepwalking","picture book","humor"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('господин-хакарайнен-заблудился-868', 'DP-0868', 'Господин Хакарайнен заблудился', 'Mr. Hakkarainen Gets Lost', 'Gospodin Hakarainen se izgubio', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Господин Хаккарайнен - большой любитель увлекательных прогулок. Он уже побывал в парке развлечений, в цирке Буффало Билла, и даже в Шервудском лесу. Одна беда - гулять господин Хаккарайнен предпочитает… во сне. Неудивительно, что однажды он заблудился! Теперь господину Хаккарайнену нужна твоя помощь. Скорее открывай эту книгу - внутри тебя ждёт множество интересных заданий! А справиться с ними помогут воображение и внимательность.', 'Mr. Hakkarainen loves taking adventurous strolls. He has visited amusement parks, Buffalo Bill''s wild west show, and even Sherwood Forest. There is just one catch: he only strolls while fast asleep! It''s no wonder that he ended up completely lost one night. Open this vibrant activity book, sharpen your observation skills, and help the world''s most famous sleepwalking goat find his way home through tons of playful search-and-find puzzles.', 'Gospodin Hakarainen obožava uzbudljive šetnje. Već je posjetio zabavni park, cirkus Bafala Bila, pa čak i Šervudsku šumu. Jedina nevolja je što najradije šeta — u snu! Zato nije čudo što se jedne noći potpuno izgubio. Sada mu je potrebna tvoja pomoć! Otvori ovu knjigu prepunu zabavnih skrivalica i zadataka za koje će ti biti potrebna oštra zapažanja i mašta.', 'Осторожно, лунатик на свободе: вооружайтесь внимательностью и спасайте обаятельного козлика от его ночных приключений!', 'Sleepwalker on the loose: grab your keenest eye and help this charming nocturnal goat navigate his dreamy adventures!', 'Pazite se, mjesečar je u akciji: naoružajte se pažnjom i pomozite šarmantnom kozliću da se izvuče iz noćnih avantura!', '/covers/DP-0868.webp', '#2c5282', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["funny","adventure","animals"]', '["wimmelbuch","interactive","animals","humor","sleepwalking"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('спокойной-ночи-господин-хаккар-869', 'DP-0869', 'Спокойной ночи, господин Хаккарайнен', 'Good Night, Mr. Hakkarainen', 'Laku noć, gospodine Hakarainen', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Господин Хаккарайнен сам не знает того, что каждую ночь он отправляется в лунатическом сне на прогулку. Он становится рок-звездой, примиряет враждебные группировки байкеров, танцует на рельсах, спасает мясокомбинат от разорения и даже задерживает преступницу. Всё это - не просыпаясь! Узнает ли он в конце концов о своей ночной жизни? Или только верная морская свинка Маса останется свидетелем его невероятных приключений? Об этом расскажут смешные истории в картинках от Маури Куннаса.', 'Mr. Hakkarainen has no clue that every single night he goes on the wildest sleepwalking adventures imaginable. Completely sound asleep, he becomes a rock star, reconciles rival biker gangs, dances along train tracks, and even nabs a burglar! Will he ever discover his secret nocturnal glory, or will his loyal guinea pig Masa remain the only witness to his slumbering heroics? A riotously funny picture book by celebrated Finnish author Mauri Kunnas.', 'Gospodin Hakarainen ni ne sanja da svake noći u mjesečarskom snu kreće u nevjerovatne pohode. Potpuno uspavan, postaje rok zvijezda, miri zavađene bajkere, pleše po šinama i hvata kradljivicu — a da se nijednom ne probudi! Da li će ikada saznati za svoj dvostruki život, ili će vjerno morsko prase Masa ostati jedini svjedok njegovih podviga? Urnebesna ilustrovana knjiga Maurija Kunasa zabaviće i djecu i roditelje.', 'Настоящая энциклопедия ночного переполоха: пока скромный сонный козлик совершает подвиги, его верная морская свинка седеет от ужаса!', 'A laugh-out-loud nighttime romp proving that while some sleep peacefully, one sleepwalking goat is out rocking stadiums and saving the city!', 'Urnebesna priča pred spavanje koja dokazuje da se najveći podvizi prave zatvorenih očiju — dok vjerno morsko prase pazi na svaki korak!', '/covers/DP-0869.webp', '#23395d', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["funny","adventure","animals"]', '["sleepwalking","humor","picture book","guinea pig","night adventures"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хобби-господина-хаккарайнена-870', 'DP-0870', 'Хобби господина Хаккарайнена', 'Mr. Clutterbuck''s Hobbies', 'Hobiji gospodina Hakarainena', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Танцы, велопрогулки, скейтборд, кросс, дайвинг, шахматы, кулинария… Чтение, рукоделие, сочинение стихов, спортивное ориентирование… Фотография, музыка, прыжки с парашютом, коллекционирование самых невероятных предметов от башмаков до старых электробритв!.. Сколько увлечений существует на свете! Все вокруг чем-то заняты и увлечены! И только господин Хаккарайнен не знает, есть ли у него хобби. Знаменитый лунатик каждую ночь отправляется на поиски своего призвания, нарушая спокойствие маленького городка. И… конечно же, призвание будет найдено! Наконец-то господин Хаккарайнен обнаружит, какое дело для него - самое любимое. Теперь жители городка вздохнут с облегчением и смогут спокойно выспаться!', 'Dancing, skateboarding, diving, poetry, skydiving, or collecting old electric razors—the world is full of incredible hobbies! Everyone in town seems deeply passionate about something, except Mr. Clutterbuck, who has no clue what his true calling might be. But every night, this famous sleepwalking goat sets off in his pyjamas, turning the town upside down on a quest for the perfect hobby. Will the townspeople ever get a quiet night''s sleep again?', 'Ples, vožnja skejtborda, ronjenje, poezija, padobranstvo ili sakupljanje starih aparata za brijanje — svijet je pun nevjerovatnih hobija! Svi u gradu su nečim zaneseni, samo gospodin Hakarainen ne zna da li ima hobi. Zato ovaj čuveni mjesečar svake noći u pidžami kreće u potragu za svojim pozivom, remeteći mir mirnog gradića. Hoće li konačno pronaći svoju strast kako bi komšije mogle mirno da spavaju?', 'Гомерически смешная и уютная история о том, что любимое дело можно найти, даже бродя во сне в пижаме!', 'A laugh-out-loud, delightfully chaotic tale proving that you can discover your true passion—even while sleepwalking in your pyjamas!', 'Urnebesno smiješna i topla priča koja dokazuje da svoj pravi poziv možete pronaći čak i dok mjesečarite u pidžami!', '/covers/DP-0870.webp', '#e59124', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["funny","animals","adventure"]', '["hobbies","sleepwalking","humor","picture book","animals"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('7-чудес-господина-хаккарайнена-871', 'DP-0871', '7 чудес господина Хаккарайнена', 'Mr. Clutterbuck''s Seven Wonders', '7 čuda gospodina Hakarajnena', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Господин Хаккарайнен в компании морской свинки Масы и группы туристов отправляется в путешествие. Египетские пирамиды, остров Пасхи, Ниагарский водопад - ему предстоит посетить самые удивительные уголки земного шара! Не менее удивительны и приключения, которые ждут господина Хаккарайнена и его спутников. Ведь когда Хаккарайнен засыпает, начинается всё самое интересное. Никто не знает, куда заведёт его лунатический сон и что он вытворит на этот раз: совершит хулиганство или доброе дело, потрясёт публику акробатическим номером или сделает важное научное открытие.', 'Mr. Hakkarainen, the world-famous sleepwalking goat, embarks on a grand world tour with his pet guinea pig Masa and a group of tourists. From the Egyptian pyramids to Easter Island and Niagara Falls, he visits iconic landmarks across the globe. But the real fun starts as soon as he falls asleep—nobody can predict what mischief, acrobatic feats, or brilliant discoveries he will make while sleepwalking!', 'Gospodin Hakarajnen, poznata koza mjesečar, kreće na uzbudljivo putovanje oko svijeta u društvu zamorčića Mase i grupe turista. Od egipatskih piramida i Uskršnjeg ostrva do Nijagarinih vodopada, čekaju ih nezaboravne znamenitosti. Ipak, prave avanture počinju tek kada Hakarajnen zaspi, jer u snu izvodi nevjerovatne akrobacije, sitne nestašluke i neočekivana naučna otkrića!', 'Самый уморительный способ изучить чудеса света — отправиться в путь с обаятельным козлом-лунатиком, который вершит историю прямо во сне!', 'The most hilarious way to explore world wonders is alongside a sleepwalking goat who makes world-changing discoveries in his pajamas!', 'Najsmješniji način da obiđete svjetska čuda jeste u društvu simpatične koze mjesečara koji stvara pravu pometnju čim zatvori oči!', '/covers/DP-0871.webp', '#d97736', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["funny","adventure","animals"]', '["world wonders","travel","geography","sleepwalking","humor"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('викинги-идут--872', 'DP-0872', 'Викинги идут!', 'The Vikings Are Coming!', 'Vikinzi dolaze!', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Викинги были отважными мореходами и свирепыми разбойниками. Они плавали на кораблях с драконьими головами и наводили страх на мирных жителей прибрежных районов. А ещё они верили в дерево Иггдрасиль, на которое нанизаны разные миры, мечтали после смерти попасть в Вальгаллу и слагали саги обо всём, что происходило в их жизни. Маури Куннас, живой классик финской детской литературы, сочиняет и иллюстрирует саги, благодаря которым даже малыши поймут, кто же такие были эти викинги. Средневековую Скандинавию Куннаса населяют доблестные собаки, находчивые коты, флегматичные кабаны, свирепые волки и незадачливые барсуки. Коренные жители Америки - еноты с непереносимостью лактозы, а Константинополем правит бегемот. Помимо уморительно смешных сказок-саг в книгу включены описания кораблей, жилищ и городов викингов, перечень скандинавских богов, карта известного викингам обитаемого мира и примерная схема мироустройства по-викингски.', 'Set sail into the Viking Age with Finnish master Mauri Kunnas and his delightful animal crew! Here, fierce Norse seafarers are brave dogs, clever cats, and unruly boars sailing dragon-headed longships to distant shores. Alongside witty comic retellings of legendary sagas, readers will discover fascinating historical details about Viking ships, settlements, daily life, and Norse mythology.', 'Zaplovite u doba Vikinga sa finskim majstorom Maurijem Kunasom i njegovom neodoljivom životinjskom družinom! U ovom svijetu neustrašivi moreplovci su hrabri psi, dovitljive mačke i flegmatični veprovi koji na drakarima osvajaju daleke zemlje. Pored urnebesnih saga, knjiga donosi i pregršt istorijskih zanimljivosti o brodovima, nordijskim bogovima i svakodnevici Vikinga.', 'Приготовьте шлемы и держитесь крепче за борта драккара: пушистые викинги Маури Куннаса отправляются покорять моря и смешить вас до слёз!', 'Grab your helmets and hold tight to the longship: Mauri Kunnas’s furry Vikings are setting sail to conquer your funny bone!', 'Stavite šljemove i čvrsto se držite za drakar: Kunasovi čupavi vikinzi kreću u pohod da vas nasmiju do suza!', '/covers/DP-0872.webp', '#2b5c7d', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["funny","adventure","animals"]', '["vikings","history","scandinavia","sagas","ships"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('на-диком-западе-873', 'DP-0873', 'На диком Западе', 'In the Wild West', 'Na Divljem zapadu', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Маури Куннас переносит нас на Дикий Запад, который населяют смелые ковбои, отважные шерифы, настойчивые золотоискатели, мудрые индейцы, а также отчаянные грабители и бандиты! Здесь неожиданно богатеют, кутят в салунах и лихо скачут по прериям. А истории про местных героев печатают в газете "Правдивые вести Запада". Самые весёлые и захватывающие из них собраны в этой книге!', 'Mauri Kunnas whisks readers away to the Wild West, a lively land of brave cowboys, daring sheriffs, stubborn gold prospectors, wise Native Americans, and notorious outlaws! Discover dramatic saloon standoffs, prairie gallops, and frontier legends as reported in the quirky local newspaper ''True West News''.', 'Mauri Kunas nas vodi na uzbudljivi Divlji zapad, prepun hrabrih kauboja, odvažnih šerifa, upornih tragača za zlatom, mudrih Indijanaca i neustrašivih razbojnika! Otkrijte smiješne i napete priče o jurnjavama prerijom i zgodama iz saluna, zabilježene na stranicama lokalnih novina.', 'Наденьте шляпы и держитесь крепче в седле: вас ждут самые уморительные и лихие приключения на Диком Западе от несравненного Маури Куннаса!', 'Tip your cowboy hats and hold tight to the saddle: Mauri Kunnas brings you the funniest, wildest romp across the frontier!', 'Stavite kaubojske šešire i čvrsto držite uzde: Mauri Kunas vas vodi u najsmješniju i najluđu avanturu po Divljem zapadu!', '/covers/DP-0873.webp', '#c86a32', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["adventure","funny","animals"]', '["wild west","cowboys","humor","history","picture book"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('остров-сокровищ-874', 'DP-0874', 'Остров сокровищ', 'Treasure Island', 'Ostrvo s blagom', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'Маури Куннас', 'Речь', NULL, NULL, 6, 16, 'middle', 'Неожиданно в руки Джима и его мамы попадает карта капитана Флинта, с помощью которой можно отыскать сокровища, зарытые на необитаемом острове. Прощай, спокойная мирная жизнь! Впереди героев и их друзей ждут морское путешествие и путь к сокровищам, полный приключений и опасностей! Ведь за картой сокровищ давно охотятся одноногий Джон Сильвер и целая команда пиратов! На чьей стороне окажется правда - расскажет Маури Куннас в своём весёлом иллюстрированном переложении известнейшего романа шотландского писателя Роберта Льюиса Стивенсона "Остров сокровищ".', 'When young Jim and his mother accidentally discover Captain Flint''s legendary map, their peaceful life ends and a grand voyage begins! Ahead lie uncharted seas, perilous jungle treks, and buried fortune. But the cunning Long John Silver and his pirate crew are already hot on their trail. Mauri Kunnas offers a rollicking, delightfully illustrated canine retelling of Robert Louis Stevenson''s timeless maritime classic.', 'Kada se u rukama malog Džima i njegove mame neočekivano nađe mapa kapetana Flinta, miran život se pretvara u veliku pomorsku avanturu u potrazi za zakopanim zlatom! Ipak, lukavi Dugi Džon Silver i opasna gusarska družina već vrebaju plijen. Mauri Kunas donosi razigranu i neodoljivo ilustrovanu adaptaciju čuvenog romana Roberta Luisa Stivensona.', 'Классическая пиратская сага Стивенсона с фирменным юмором Маури Куннаса и ушасто-хвостатой командой бесстрашных корсаров!', 'Robert Louis Stevenson''s timeless pirate adventure reimagined with Mauri Kunnas''s signature wit and a delightful crew of sea dogs!', 'Klasična piratska avantura oživljena kroz prepoznatljiv humor Maurija Kunasa i njegovu neodoljivu pseću posadu mornara!', '/covers/DP-0874.webp', '#2b6382', 'nonfiction', 'ru', 'available', 'Категория: Маури Куннас', '["adventure","funny","animals"]', '["pirates","treasure hunt","dogs","sea voyage","classic retelling"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('груффало-875', 'DP-0875', 'Груффало', 'The Gruffalo', 'Grozon', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', '"- Какое еще груффало? Мышонок, ты о ком? - О, это очень крупный зверь, я с ним давно знаком..." Чтобы спастись от лисы, совы и змеи маленький мышонок выдумывает страшного груффало - зверя, который очень любит есть лис, сов и змей. Но сможет ли находчивый мышонок перехитрить всех голодных хищников? Ведь он-то хорошо знает, что никаких груффало не бывает... Или бывает? Сегодня трудно представить, что раньше никаких груффало не было. Со дня первого издания в Англии, в 1999 году, уже 26 миллионов книг о страшном звере с лиловыми шипами на спине нашли своих хозяев по всему миру, а сам герой говорит на 86 иностранных языках. Русскому же Груффало исполняется 15 лет. С днём рождения, Груффало! Сказка в стихах для чтения взрослыми детям.', 'A clever little mouse takes a walk through the deep dark wood and invents a terrifying beast called the Gruffalo to scare away a fox, an owl, and a snake. But what will the little mouse do when he comes face-to-face with the very creature he made up? A beloved, rhyming worldwide classic celebrating wit over brawn.', 'Dovitljivi mali miš šeta kroz mračnu šumu i izmišlja strašno čudovište Grozona kako bi preplašio gladnu lisicu, sovu i zmiju. Ali šta će miš učiniti kada se iznenada nađe licem u lice sa stvorenjem iz svoje mašte? Čuveni moderni klasik u stihovima koji slavi pamet i snalažljivost.', 'Абсолютная классика на все времена, доказывающая, что находчивость и смекалка побеждают любые клыки и когти!', 'A timeless rhyming delight proving that sharp wits and bold imagination can outsmart any woodland beast!', 'Bezvremenska rimovana priča koja dokazuje da oštar um i bujna mašta mogu nadmudriti i najstrašnije šumsko čudovište!', '/covers/DP-0875.webp', '#5c3a21', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["funny","adventure","animals"]', '["cunning","rhymes","forest animals","picture book","monsters"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тимоти-скотт-876', 'DP-0876', 'Тимоти Скотт', 'Tabby McTat', 'Tabi MekTet', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', 'Тимоти Скотт, музыкальный кот,С гитаристом по имени ФредПели на улицах круглый год.К ним отовсюду сбегался народИ не жалел монет....Но однажды, пока Тимоти не было рядом, на шляпу с деньгами нацелился вор, схватил её - и наутёк. Фред кинулся вслед и... так два друга потерялись.Встретятся ли они когда-нибудь?Это лиричная, трогательная и смешная история о верной и мур-раз-лучной дружбе, написанная авторами знаменитого "Груффало".Для чтения взрослыми детям.', 'Tabby McTat is a busker''s cat with a loud, melodious mew. He loves singing alongside Fred on the bustling city streets, gathering crowds and coins. But when a thief strikes and Fred gets injured, the two loyal companions are torn apart. Will McTat ever find his musical partner again? A heartwarming, rhyming tale of steadfast friendship and family from the creators of The Gruffalo.', 'MekTet je mačak uličnog muzičara s gromkim, raspjevanim glasom. Zajedno s gitaristom Fredom zabavlja prolaznike na gradskim ulicama, sve dok ih drski lopov zauvijek ne razdvoji. Hoće li se dva nerazdvojna prijatelja ikada ponovo sresti? Dirljiva i duhovita priča u stihovima o odanosti i pravom prijateljstvu, od autora čuvenog „Grobona”.', 'Трогательная песенная баллада о кошачьей верности, музыке и о том, что настоящие друзья обязательно найдут дорогу друг к другу.', 'A melodious, heartwarming tale about a singing cat and a busker that will make every listener believe in lifelong friendship.', 'Predivna muzička priča u stihovima o mačjoj odanosti i neraskidivom prijateljstvu koje odolijeva vremenu i daljini.', '/covers/DP-0876.webp', '#d96b27', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["animals","friends","adventure"]', '["cats","friendship","music","rhymes","julia donaldson"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('верхом-на-помеле-877', 'DP-0877', 'Верхом на помеле', 'Room on the Broom', 'Mjesto na metli', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', '""У ведьмы был кот, / полосатый толстяк, / рыжая коса / и высокий колпак..."" Ведьма мчит по небу на помеле и роняет на землю колпак, волшебную палочку и бантик с рыжей косы. Все это по очереди находят пес, птичка и лягушонок и просят в награду за службу прокатить их на помеле, что ведьма охотно и делает. Но метла ломается: кот, пес и лягушонок падают в болото, а ведьма попадает в лапы дракона; тот уже собирается съесть колдунью на ужин, как вдруг появляется жуткий, грозный зверь - чудище болот - и требует отдать ведьму ему... Куда пропали пес, кот и лягушонок? Что случилось с птичкой и что теперь станет с ведьмой? - читайте еще одну полную сюрпризов, красочную и обаятельную книжку от авторов ""Груффало"".', 'A generous witch and her cat fly through the windy sky, picking up hitchhikers along the way: a helpful dog, a green bird, and a clean frog who all retrieve lost belongings. But when the overloaded broom snaps and a hungry dragon appears eager for witch-and-chips, her loyal animal crew bands together in an ingenious disguise to save the day in this beloved rhyming classic.', 'Velikodušna vještica i njena mačka lete nebom na metli, usput primajući neobične saputnike: psa, zelenu pticu i pedantnu žabu koji joj pronalaze izgubljene stvari. Ali kada metla pukne od težine, a gladni zmaj poželi vješticu za večeru, novi prijatelji smišljaju genijalnu varku kako bi je spasili u ovoj omiljenoj rimovanoj bajci.', 'Добрая и ритмичная сказка доказывает: для настоящих друзей на любой метле всегда найдётся местечко!', 'A delightful rhyming tale proving that with loyal friends by your side, there''s always room on the broom for one more!', 'Predivna rimovana priča koja dokazuje da za prave prijatelje na čarobnoj metli uvijek ima još jedno slobodno mjesto!', '/covers/DP-0877.webp', '#e68a1d', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["magic","friends","funny"]', '["witch","friendship","animals","dragon","rhymes"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('человеткин-878', 'DP-0878', 'Человеткин', 'Stick Man', 'Prutko', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', 'Одним весенним днём Человеткин отправился на пробежку, но был схвачен собакой, которая приняла его за обыкновенную палку. Дети играли и бросили его в реку, а лебедь увидел в нем прутик дня гнезда. Осень сменит лето, придёт снежная зима - горемычный Человеткин перебывает мачтой для флага, шпагой, клюшкой, бумерангом, рукой для снеговика. Неужели он никогда не вернется домой, к челодеткам? Стихи из книги: – Нет! Я не палка! Пусти меня! Стой! Я ЧЕЛОВЕТКИН, разумный, живой! Я Человеткин, мне нужно домой!', 'One spring day, Stick Man goes for a jog and is suddenly grabbed by a dog who thinks he''s just an ordinary stick! Tossed into a river by children, stolen by a swan for a nest, used as a flag mast, a sword, and even a snowman''s arm, poor Stick Man drifts further and further from his family tree. Will he ever make it back to his Stick Lady Love and their stick children three in time for Christmas?', 'Jednog proljećnog dana, Prutko je krenuo na trčanje, ali ga je zgrabio pas misleći da je običan prut! Djeca su ga bacila u rijeku, labud ga je uzeo za gnijezdo, a zimi je služio kao ruka za snješka. Jadni Prutko samo želi da se vrati kući svojoj porodici u porodičnom stablu — hoće li uspjeti prije nego što bude prekasno?', 'Трогательная и полная приключений сказка в стихах о том, что даже обычная веточка может отчаянно стремиться домой к любимым!', 'A charming and dramatic rhyming adventure proving that even a humble twig has a brave heart and a family waiting at home!', 'Dirljiva i uzbudljiva priča u stihovima o tome kako i običan prutić ima hrabro srce i želi samo jedno — da se vrati svojoj porodici!', '/covers/DP-0878.webp', '#6e4726', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["adventure","funny","friends"]', '["rhymes","family","journey","winter","picture book"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('новый-наряд-великана-879', 'DP-0879', 'Новый наряд великана', 'The Smartest Giant in Town', 'Najotmjeniji div u gradu', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', '"Великану Джорджу очень хотелось принарядиться. И как только в городе открылся магазин гигантской одежды, он поспешил туда. Белоснежная рубашка, фасонистые брюки, блестящие ботинки, пёстрый галстук и носки с ромбиками - как приятно чувствовать себя нарядным и красивым! Но по дороге домой Джорджу встречаются жираф - кроткий нрав, пес - чуткий нос, орава мышат-малышат и козлик в маленькой лодке с мачтой в середке. Все эти звери попали в беду и им очень нужна помощь Джорджа… и его новые вещи! Написанная пружинистой прозой и стихами, это история о добром малом, который был богат не щегольским нарядом, а щедрым сердцем.', 'George the giant wants to look smart, so he buys a spiffy new outfit complete with a crisp shirt, fancy trousers, and a striped tie. But on his way home, he meets animals in desperate need of help: a freezing giraffe, a shivering family of mice, and a goat stranded without a sail. George cheerfully gives his new clothes away piece by piece, proving that a generous heart never goes out of style.', 'Div Džordž želi da izgleda dotjerano, pa kupuje divnu novu odjeću: sniježnobijelu košulju, otmjene pantalone i prugastu kravatu. Ali na putu do kuće nailazi na životinje u nevolji: smrznutu žirafu, mišiće kojima treba dom i jarca sa slomljenim jedrom. Džordž nesebično poklanja komad po komad svog novog odijela, pokazujući da je dobro srce najljepši ukras.', 'Уморительная и трогательная сказка о том, что галстук греет жирафа куда лучше, если отдать его от чистого сердца!', 'A heartwarming, laugh-out-loud tale proving that giving away your fancy new trousers can make you the coolest giant around!', 'Dirljiva i smiješna priča koja dokazuje da ste najljepše obučeni onda kada imate najveće i najtoplije srce!', '/covers/DP-0879.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["funny","friends","animals"]', '["kindness","generosity","animals","rhymes","giants"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хочу-к-маме--880', 'DP-0880', 'Хочу к маме!', 'Monkey Puzzle', 'Gdje je moja mama?', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', 'Сможет ли мотылёк помочь мартышке найти маму? Да, но только после многих проб и ошибок, ведь приметы всё время приводят их к "неправильным" зверям. Это познавательная, весёлая, добрая и красочная как сами джунгли книга, написанная авторами знаменитого Груффало. Сказка в стихах для чтения взрослыми детям. Информационная продукция для детей, не достигших возраста шести лет.', 'Can a well-meaning butterfly help a little monkey find his lost mom? Only after plenty of silly mix-ups, as every clue leads them to all the wrong jungle animals! A witty, rhyming, and cheerful tale from the creators of The Gruffalo.', 'Može li dobronamjerni leptirić pomoći izgubljenom majmunčiću da nađe svoju mamu? Može, ali tek nakon niza smiješnih zabuna, jer ih svaki opis vodi do pogrešne životinje u džungli! Vesela priča u stihovima od autora čuvenog Grozona.', 'Остроумная и трогательная рифмованная сказка о том, как мотылёк усердно искал маму мартышки среди слонов, змей и лягушек!', 'A delightfully silly jungle romp where a helpful butterfly tries his best to guess what baby monkey''s mom looks like!', 'Preslatka i duhovita priča o zbunjenom leptiriću koji malom majmunu uporno pronalazi pogrešne mame po cijeloj džungli!', '/covers/DP-0880.webp', '#45893a', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["funny","animals","friends"]', '["jungle","monkeys","family","rhymes","picture book"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тюлька-881', 'DP-0881', 'Тюлька', 'Tiddler', 'Ribica Tili', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', '"Жила на свете Тюлька, малюсенькая рыбка/Простая рыбка в сером чешуйчатом пальто… Рыбка Тюлька каждое утро опаздывает в школу и всякий раз под новым предлогом: то она скакала на морском коньке, то каталась на скате, то нашла сундук сокровищ, то была в плену у гигантского кальмара. Никто не верит в Тюлькины истории, ведь всем известно, что маленькая Тюлька - большая выдумщица. Но однажды Тюлька, чудом спасшись из рыбацких сетей, заблудилась в океане. Помогут ли теперь Тюльке ее выдумки? И верите ли вы им? Сказка в стихах для чтения взрослыми детям."', 'Tiddler is a tiny fish with a huge imagination who is always late for school with an unbelievable excuse. One day, he gets caught in a fisherman''s net and finds himself far away from home in the deep, vast ocean. Can his own tall tales guide him back to his reef?', 'Tili je sićušna ribica sa ogromnom maštom koja stalno kasni u školu uz nevjerovatna opravdanja. Jednog dana upada u ribarsku mrežu i gubi se u beskrajnom okeanu. Hoće li mu njegove sopstvene izmišljene priče pomoći da pronađe put do kuće?', 'Даже если все вокруг считают тебя главным фантазёром, однажды твои сказки могут спасти целый день!', 'Even if everyone thinks you''re just telling tall tales, sometimes a great imagination is the best compass in the sea!', 'Čak i ako svi misle da samo izmišljaš priče, ponekad je bujna mašta najbolji kompas na moru!', '/covers/DP-0881.webp', '#1f829c', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["adventure","animals","funny"]', '["ocean","fish","storytelling","rhymes","imagination"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('улитка-и-кит-882', 'DP-0882', 'Улитка и кит', 'The Snail and the Whale', 'Puž i kit', 'Джулия Дональдсон', 'Julia Donaldson', 'Džulija Donaldson', 'Аксель Шеффлер', 'Машинки творения', NULL, NULL, 6, 16, 'middle', '... Вот скала / Где над морем улитка жила / И вздыхала она то и дело: / - Как мне все надоело! / Мир огромен, а я тут сижу на скале, / А могла бы уплыть на большом корабле... / ...Или... Или, может быть, на хвосте синего кита-великана?! Мир так широк, а улитка так мала - кто мог подумать, что именно крохотная улитка спасет своего большого друга, когда тот попадет в беду? Самая новая сказка в стихах от авторов мировых бестселлеров "Груффало" и "Дочурка Груффало" с большими - на всю страницу - яркими картинками. Победитель конкурса BBC "Blue Reter Award", как лучшая иллюстрированная книга 2005 года для чтения вслух. Для чтения взрослыми детям.', 'A poetic, heartwarming tale of a tiny snail with wanderlust who hitches a ride around the globe on the tail of an enormous humpback whale. When disaster strikes and the gentle giant is stranded in a bay, it''s up to the resourceful little snail to rally help and save her colossal friend.', 'Poetska i dirljiva priča o malenom pužu sa velikim snovima koji putuje oko svijeta na repu grbavog kita. Kada se džinovski prijatelj nasuče na obalu, upravo će sićušni, hrabri pužić naći domišljat način da spasi svog velikog saputnika.', 'Даже самый крошечный путешественник способен совершить великий подвиг ради верного друга!', 'Proof that you don''t need to be big to embark on world-sized adventures and save a giant friend!', 'Dokaz da ne moraš biti velik da bi doživio ogromnu avanturu i spasio džinovskog prijatelja!', '/covers/DP-0882.webp', '#1b629b', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["adventure","friends","animals"]', '["sea","travel","friendship","whale","rhymes"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('если-в-домике-тесно-883', 'DP-0883', 'Если в домике тесно', 'A Squash and a Squeeze', 'Tijesna kućica', 'Джулия Дональдсон', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', '"В домишке за лесом старушка жила, / Был дом невелик и старушка мала. / На полке посуда, у печки дорожка, - / Не дом, а мечта! Только тесно немножко." Как быть если в домике тесно? Верное средство знает старый философ: "Взять курицу в дом. Только чур без вопросов!" А вслед за курицей-несушкой - блохастую козу, обжору-свинью и корову… И только когда прогонишь их обратно на двор, то поймешь, что на самом деле дом не мал, а велик. Это самая первая книга писательницы Джулии Дональдсон и художника Акселя Шеффлера - авторов мировых бестселлеров "Груффало" и "Дочурка Груффало" и обладателей множества литературных наград. Для чтения взрослыми детям.', 'An old woman complains her cottage is far too small, so a wise old man gives her some startling advice: bring in a hen, a goat, a pig, and a cow! A delightfully humorous rhyming tale about perspective and gratitude from the creators of The Gruffalo.', 'Starica se žali kako joj je kućica premala, pa joj mudri starac daje neobičan savjet: neka redom unese kokošku, kozu, prase i kravu! Urnebesna i poučna rimovana priča o promjeni perspektive i zahvalnosti, od tvoraca čuvenog Grozona.', 'Если вам кажется, что в комнате не развернуться, пустите переночевать корову — и вы сразу поймете, как у вас просторно!', 'If your room feels way too cramped, try inviting a cow inside for the night—you will suddenly realize how huge your place truly is!', 'Ako vam se čini da vam je soba pretijesna, pozovite kravu na prenoćište i odjednom ćete shvatiti koliko zapravo imate prostora!', '/covers/DP-0883.webp', '#e69a28', 'nonfiction', 'ru', 'available', 'Категория: Чик и Брики Пугливая улитка', '["funny","animals"]', '["picture book","farm animals","rhyming story","life lessons","folktale"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лучшая-свадьба-на-свете-884', 'DP-0884', 'Лучшая свадьба на свете', 'The Scarecrows'' Wedding', 'Najbolje vjenčanje na svijetu', '', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', '"Пугало Бетти и пугало Билли нежно и крепко друг друга любили. Раз на исходе рабочего дня Билли сказал: - Выходи за меня! …""Согласна! Ура!"" - сказала Бетти, и молодые принялись за приготовления. Портной паучок сшил пышное платье из белых как снег гусиных перьев. Коровы одолжили свои колокольца - чтобы весело трезвонить на свадьбе. Краб нанизал бусы из пестрых раковин. Шустрые мышки обшарили двор - добыли кольца от стареньких штор. Осталось нарвать большущий букет, и Билли отправился за ним. Но вот прошел один день, за ним второй, а Билли все нет. Бетти в тревоге: вдруг он другую навек полюбил? А между тем, фермер выставил в поле новое пугало - Гарри. Он франт и любезник и хочет расстроить свадьбу. Джулию Дональдсон называют ""детским Шекспиром сегодня"", а Аксель Шеффлер - один из самых ярких и узнаваемых иллюстраторов наших дней. ""Самая лучшая свадьба"" - долгожданная новинка этих талантливых авторов. …И, кстати, сможете ли вы найти в книге Груффало?', 'Scarecrows Betty and Billy are madly in love and planning the best wedding ever! With a gown made of white goose feathers, a necklace of shells from a crab, and curtain rings gathered by friendly mice, everything seems ready—until Billy heads off to find flowers and goes missing. When a handsome new scarecrow named Harry attempts to steal Betty''s heart, true love faces its greatest test. A delightful, rhythmic countryside adventure by Julia Donaldson and Axel Scheffler.', 'Strašila Beti i Bili se iskreno vole i pripremaju najdivnije vjenčanje ikada! Uz vjenčanicu od guščijeg perja, zvonca krava i ogrlicu od školjki, sve je spremno dok Bili ne ode po cvijeće i ne nestane. Tada stiže gizdavo novo strašilo Hari, riješen da pokvari svadbu i osvoji Beti. Hoće li prava ljubav pobijediti? Šarmantna i duhovita priča u stihovima od slavnog dvojca Džulije Donaldson i Aksela Šeflera.', 'Трогательная и уморительная сказка в стихах о том, что настоящую любовь не испортят ни коварные соперники, ни охапка соломы!', 'A charming and hilarious rhyming tale proving that true love can conquer any rival—even one made of straw!', 'Dirljiva i urnebesna priča u stihovima koja dokazuje da pravu ljubav ne može pokvariti čak ni lukavo novo strašilo!', '/covers/DP-0884.webp', '#d98f3b', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста. Для чтения взрослыми детям."', '["funny","friends","adventure"]', '["wedding","scarecrows","rhymes","farm","friendship","picture book"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бумажные-куклы-885', 'DP-0885', 'Бумажные куклы', 'The Paper Dolls', 'Papirne lutke', 'Джулия Дональдсон', 'Julia Donaldson', 'Džulija Donaldson', '', 'Машинки творения', NULL, NULL, 6, 16, 'middle', 'Мы сцепили крепко руки, / не страшны нам бяки-злюки! / Неразлучны Кэт и Клод, / Мэри-задом-наперёд, / бедный Джим с двумя носами / и красавица Шарлот… Написанная прозой и стихами, это лиричная и трогательная история о детстве, золотом и быстроногом, и о том, как оно никуда не уходит. Для детей до 6 лет.', 'Holding hands tight, five little paper dolls embark on a whirlwind adventure across the living room, escaping a toy tiger, a snap-snap crocodile, and a fierce dinosaur. But when real scissors appear, their journey takes an unexpectedly tender turn straight into the warm haven of memory. A lyrical and profoundly moving masterpiece about imagination and the indelible beauty of childhood.', 'Držeći se čvrsto za ruke, pet papirnih lutkica kreće u čarobnu avanturu kroz sobu, hrabro bježeći od igračke tigra, krokodila i dinosaurusa. Ali kada se pojave prave makaze, njihovo putovanje dobija neočekivano dirljiv preokret, pravo u toplo utočište sjećanja. Lirska i beskrajno nježna priča o snazi mašte i zlatnom djetinjstvu koje nikada ne nestaje.', 'Щемящая и нежная сказка о том, что настоящая магия детства и любимые бумажные сокровища никогда не исчезают, а бережно хранятся в нашей памяти.', 'A deeply touching, gentle tale proving that the magic of childhood and our favorite paper creations never truly disappear—they live forever in our hearts.', 'Dirljiva i nježna priča koja nas podsjeća da čarolija djetinjstva i drage uspomene nikada ne nestaju, već zauvijek žive u našim srcima.', '/covers/DP-0885.webp', '#e07a68', 'nonfiction', 'ru', 'available', 'Категория: Король и повар', '["magic","friends","real"]', '["paper dolls","childhood","imagination","memories","poetry"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('именинный-пирог-886', 'DP-0886', 'Именинный пирог', 'The Birthday Cake', 'Rođendanska torta', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Котёнок Финдус празднует день рождения три раза в год. А его хозяин Петсон, всегда в этот день печёт ему Именинный пирог. Вот как сегодня. Но чтобы его приготовить, Петсону нужно попасть на чердак, найти удочку, достать ключ из колодца, починить велосипед, а Финдусу - побывать в роли тореадора. Да-да, соседи считают их чудаками. Ещё скажите, что это не так!', 'Findus the cat celebrates his birthday three times a year, and Pettson always bakes him a delicious pancake cake. But today, whipping up the treat turns into a hilarious chain reaction: finding a key in the well, repairing a bicycle, and facing off with a bull in the pasture. No wonder the neighbors think they''re completely out of their minds!', 'Mačak Findus slavi rođendan tri puta godišnje, a čiča Petson mu svaki put peče rođendansku tortu od palačinki. Ali da bi je pripremio danas, mora da pronađe ključ u bunaru, popravi bicikl i nadmudri komšijskog bika na livadi. Komšije su ubijeđene da su njih dvojica skrenuli s uma — a vi prosudite sami!', 'Готовы к безумному квесту с удочкой, колодцем и соседским быком ради самой вкусной в мире стопки блинов?', 'Get ready for a chaotic culinary quest involving a fishing rod, a well, and a neighbor''s bull, all for the sake of one glorious birthday cake!', 'Spremite se za urnebesnu kulinarsku potragu sa pecaljkom, bunarom i bikom, a sve to samo zbog jedne rođendanske torte!', '/covers/DP-0886.webp', '#e89437', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","adventure","animals"]', '["baking","cats","countryside","mishaps","pets"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-финдус-потерялся-когда-был-887', 'DP-0887', 'Как Финдус потерялся когда был маленький', 'When Findus Was Little and Disappeared', 'Kad je Findus bio mali i izgubio se', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Петсон был самым обычным одиноким стариком, пока в один прекрасный день соседка не принесла ему большую коробку, в которой сидел крошечный котёнок. Жизнь Петсона изменилась, теперь ему скучать не приходится! Эта книга о том, почему Финдуса зовут Финдусом, откуда у него такие смешные полосатые штаны и как ему удалось спастись от страшного чудовища. Для детей младшего школьного возраста.Книга Свена Нурдквиста "История о том, как Финдус потерялся, когда был маленьким" отсылает читателей к началу цикла о Петсоне и Финдусе. Вы узнаете, какие обстоятельства привели к судьбоносной встрече старика и котенка.', 'Pettson was an ordinary, lonely old man until one day a kind neighbour brought him a cardboard box containing a tiny kitten. Pettson''s quiet life was turned upside down in the best way possible! This heartwarming story reveals how Findus got his name, where his iconic green striped trousers came from, and how he faced his very first backyard adventure.', 'Petson je bio običan, pomalo usamljen starac sve dok mu jednog dana komšinica nije donijela kutiju u kojoj je čučalo majušno mače. Od tog dana Petsonov život se potpuno mijenja! Ova topla priča otkriva kako je mačak dobio ime Findus, odakle mu prepoznatljive prugaste pantalone i kako se hrabro snašao u svojoj prvoj velikoj avanturi.', 'Трогательная история знакомства любимого дуэта, которая объяснит, откуда у котенка зелёные штаны и как спастись от ночного барсука!', 'Discover the heartwarming origin story of Pettson and Findus—striped green trousers, runaway adventures, and all!', 'Saznajte kako je započelo nerazdvojno prijateljstvo čika Petsona i mačka Findusa u ovoj neodoljivoj, toploj priči!', '/covers/DP-0887.webp', '#5b8e3a', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["funny","friends","animals"]', '["cats","friendship","illustrated","origin story","humor"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чужак-в-огороде-888', 'DP-0888', 'Чужак в огороде', 'The Rooster in the Garden', 'Uljez u bašti', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Однажды старик Петсон принёс домой огромного и наглого петуха. Котёнок Финдус совсем не в восторге от нового соседа, который тотчас завладел вниманием кур и начал кукарекать сутки напролёт. Что же делать? У Финдуса есть план!', 'One day, old man Pettson brings home a huge, boisterous rooster. Findus the kitten is definitely not thrilled with the loud newcomer who immediately steals the hens'' attention and crows non-stop from dusk till dawn. What''s a cat to do? Naturally, Findus comes up with a clever plan!', 'Jednog dana čiča Petson dovodi kući ogromnog i drskog pijetla. Mačak Findus nimalo nije oduševljen novim komšijom, koji je smjesta očarao kokoške i počeo da kukuriče bez prestanka. Šta raditi? Findus, naravno, ima lukav plan!', 'Искромётная история о ревности, петушином эго и кошачьей изобретательности, где Финдус пытается отстоять покой и порядок на любимой ферме.', 'A laugh-out-loud tale about feline jealousy, a noisy intruder, and Findus’s hilarious battle to restore peace and quiet to the farm.', 'Duhovita priča o mačjoj ljubomori i drskom novom komšiji, gdje Findus mora smisliti genijalan plan kako bi povratio mir u dvorištu.', '/covers/DP-0888.webp', '#52843b', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["funny","animals","friends"]', '["cats","farm life","pettson and findus","rooster","jealousy"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('а-ну-ка-петсон--889', 'DP-0889', 'А ну-ка, Петсон!', 'Come on, Pettson!', 'Hajde, Petsone!', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Петсон умеет печь пироги, чинить проколотую шину и ловить рыбу. А может ли он бегать, прыгать и лазить по деревьям, как Финдус? Пора проверить! Свен Нурдквист- шведский художник и писатель, получивший мировую известность благодаря своим книгам для детей. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всём мире. Книга адресована детям от о до 3 лет.', 'Pettson knows how to bake pancakes, fix a flat bicycle tire, and catch fish. But can he run fast, jump high, and climb trees just like Findus? It is time to put the old man to the test! A playful and warm story for the youngest readers about an endearing friendship.', 'Petson zna kako se peku pite, krpi probušena guma i peca riba. Ali može li trčati, skakati i penjati se po drveću kao mačak Findus? Vrijeme je za test! Topla i razigrana slikovnica za najmlađe o neobičnom i veselom prijateljstvu.', 'Проверьте вместе с озорным Финдусом, на какие акробатические подвиги способен добродушный старик Петсон!', 'Join mischievous Findus to see if dear old Pettson can match a bouncy kitten''s wild gymnastics!', 'Provjerite zajedno sa nestašnim Findusom na kakve je sve akrobacije spreman dobri stari Petson!', '/covers/DP-0889.webp', '#4a7c59', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["funny","friends","animals"]', '["pettson and findus","friendship","cats","humor","picture book"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('финдус-переезжает-890', 'DP-0890', 'Финдус переезжает', 'Findus Moves Out', 'Findus se seli', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Прошло более 10 лет с тех пор, как Свен Нурдквист написал последнюю книгу в серии про Петсона и Финдуса. Наконец нас ждет продолжение! По утрам старик Петсон любит поспать - хотя бы до семи часов. А кот Финдус не может прожить без утренней разминки, которая начинается в четыре утра. Всё бы ничего, но друзья живут в одной комнате… Свен Нурдквист - шведский художник и писатель, лауреат премии Астрид Линдгрен (2003 год). Первая книга о старике Петсоне и его умном котёнке Финдусе вышла в 1984 году, после чего серия продолжилась, а автор набирал популярность сначала у себя на родине, в Швеции, а далее и во всей Европе. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всём мире. Книги переведены на 40 языков.', 'Pettson loves to sleep in until at least seven, but Findus cannot start his day without bouncy gymnastics at four in the morning! When living together in one room becomes too noisy, Pettson renovates the old outhouse into a private home for the energetic kitten. Becoming independent turns out to be exciting, but are the two best friends truly ready for life apart? A tender and delightfully funny Swedish classic about growing up.', 'Čiča Petson voli da odspava makar do sedam ujutru, ali mačak Findus započinje svoje bučne jutarnje vježbe već u četiri! Pošto život u istoj sobi postaje nemoguć, Petson pretvara staru dvorišnu kućicu u pravi mali dom za Findusa. Odrastanje i samostalnost donose uzbudljive promjene, ali i pitanje: mogu li nerazdvojni prijatelji zaista živjeti odvojeno? Topla i duhovita švedska priča o privrženosti i samostalnosti.', 'Что делать, если лучший друг обожает прыгать на кровати в четыре утра? Построить ему отдельный дом и тут же начать ужасно скучать!', 'What do you do when your best friend bounces on your bed at four in the morning? Build him his own house—and immediately miss him!', 'Šta uraditi kad vam najbolji prijatelj skače po krevetu u četiri ujutru? Napraviti mu sopstvenu kućicu i odmah početi da vam nedostaje!', '/covers/DP-0890.webp', '#678c4a', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["funny","friends","animals"]', '["cats","friendship","growing up","humor","pettson and findus"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('петсон-грустит-891', 'DP-0891', 'Петсон Грустит', 'Pettson Goes Fishing', 'Petson je tužan', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Что делать, если твой друг ни с того ни с сего загрустил? Надо немедленно вернуть ему хорошее настроение! Самый весёлый и изобретательный в мире кот Финдус способен развеселить кого угодно, даже угрюмого старика Петсона. Как ему эту удается? Одной левой лапой! Свен Нурдквист- шведский художник и писатель, получивший мировую известность благодаря своим книгам для детей. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всём мире.', 'What do you do when your best friend wakes up on the wrong side of the bed and feels thoroughly gloomy? You get him out of the house, of course! Findus the cat is determined to lift old Pettson''s spirits, even if it takes a fishing trip, a little chaos, and a lot of feline persistence. Sven Nordqvist''s wonderfully detailed and heartwarming tale gently shows how patience, companionship, and nature can cure even the gloomiest mood.', 'Šta uraditi kada se tvoj najbolji prijatelj probudi neraspoložen i tužan? Mačak Findus zna odgovor: ne odustajati dok mu ne izmami osmijeh na lice! Uz malo domišljatosti, upornosti i neodoljivog mačjeg šarma, Findus uspijeva da izvuče mrzovoljnog Petsona na pecanje i vrati mu radost. Topla i prelijepo ilustrovana priča čuvenog švedskog autora Svena Nordkvista o pravom prijateljstvu i vedrini.', 'Лучшее лекарство от хандры — неугомонный полосатый кот, готовый перевернуть весь дом ради улыбки лучшего друга!', 'The ultimate cure for a gloomy day is an endlessly inventive striped cat determined to make you smile!', 'Najbolji lijek za loš dan je neumorni mačak na prugice, spreman na sve da bi oraspoložio svog najboljeg prijatelja!', '/covers/DP-0891.webp', '#4a7c59', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["funny","friends","animals"]', '["friendship","cats","humor","pettson and findus","fishing"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('охота-на-лис-892', 'DP-0892', 'Охота на лис', 'The Fox Hunt', 'Lov na lisicu', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nurdkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Однажды к Петсону и Финдусу зашел их сосед Густавсон, который сказал, что в округе появилась лиса, ворующая кур. Но Финдус против охоты на лис, лису надо перехитрить, считает он. Поэтому вместе с Петсоном они придумывают хитроумный способ напугать лису, чтобы ей больше было неповадно наведываться в курятники. Друзья приготовили для лисы настоящее светопредставление: взрывы петард и фейерверков, чучело курицы, наполенной перцем и даже настоящее привидение! И не только отвадили лису от своего курятника, но и навсегда отучили Густавсона от охоты на лис.', 'When neighbor Gustavsson drops by warning Pettson and Findus about a chicken-stealing fox, Findus makes it clear: shooting foxes is completely out of the question! Instead, the clever duo decides to outsmart the sneaky intruder. Armed with a pepper-filled fake hen, firecrackers, and a zip-lining bedsheet ghost, they stage a nocturnal spectacle that scares off the hungry fox—and teaches the neighbor a memorable lesson about hunting.', 'Kada komšija Gustavson javi Petsonu i Findusu da se u okolini pojavila lisica koja krade kokoške, mačak Findus odlučno odbija svaku pomisao na puške. Umjesto lova, stari Petson i njegov domišljati mačak smisle genijalan plan kako da nadmudre lisicu: lažna kokoška punjena biberom, vatromet i leteći duh od čaršava garantuju noćnu predstavu koju ni lisica, a ni namrgođeni lovac Gustavson nikada neće zaboraviti.', 'Зачем ружьё, когда есть перчёная курица, фейерверки и летающее привидение, способное перехитрить любую лису и одного ворчливого соседа?', 'Who needs a rifle when you have a pepper-stuffed decoy hen, fireworks, and a flying bedsheet ghost to outsmart both the fox and a grumpy neighbor?', 'Kome uopšte treba puška kad imate kokošku napunjenu biberom, petarde i duha na sajli koji će nadmudriti i lisicu i komšiju?', '/covers/DP-0892.webp', '#d35427', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["funny","adventure","animals"]', '["петсон и финдус","хитрость","деревня","изобретения","доброта"]', 1792836322700, 1792845686556);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('петсон-идет-в-поход-893', 'DP-0893', 'Петсон идет в поход', 'Findus Goes Camping', 'Petson ide na kampovanje', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Однажды котенок Финдус нашел на чердаке у Петсона старую палатку и ему безудержно захотелось пойти в поход, а Петсону как раз надо испытать его новое изобретение — лук для ловли рыбы. Так что друзья собирают рюкзак и отправляются на озеро. Но по пути к ним привязываются куры, которые никак не хотят отпускать их. Тогда Петсон и Финдус ставят палатку в саду и ночуют под яблоней. И получается почти как настоящий поход.', 'One day, Findus the cat discovers an old tent in Pettson''s attic and is determined to go camping, while Pettson wants to test his new fishing bow invention. The friends pack their bags and head toward the lake, but their persistent hens follow along and refuse to turn back. In the end, Pettson and Findus pitch the tent right in their garden under the apple tree—and it turns out to be just as exciting as a real expedition.', 'Jednog dana mačak Findus pronalazi stari šator na tavanu i silno poželi da ide na kampovanje, a Petson baš želi da isproba svoj novi izum — luk za pecanje. Prijatelji pakuju rance i kreću ka jezeru, ali ih prate radoznale kokoške koje ne žele da odustanu. Tako Petson i Findus postavljaju šator u svojoj bašti pod jabukom, a to ispadne prava pravcata avantura.', 'Петсон и Финдус доказывают: самый незабываемый поход можно устроить прямо в собственном саду pod яблоней!', 'Findus and Pettson prove that the greatest camping adventure can easily happen right in your own backyard!', 'Findus i Petson dokazuju da se najnezaboravnije kampovanje može doživjeti u sopstvenoj bašti ispod jabuke!', '/covers/DP-0893.webp', '#3b7044', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["adventure","funny","friends"]', '["camping","cats","friendship","country life","humor"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рождество-в-домике-петсона-894', 'DP-0894', 'Рождество в домике Петсона', 'Pettson''s Christmas', 'Božić kod Petsona', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Близится Рождество, а у Петсона еще ничего не готово к празднику. Надо успеть сходить в магазин, пока он не закрылся, а еще нужно нарубить дров и принести из леса елку. Но в лесу Петсон подворачивает ногу — и ходить больше не может. Его котенок Финдус в ужасе и расстройстве: Рождество и Новый год без елки, без угощения без подарков? Как такое может быть? Но о беде, случившейся с Петсоном, узнали соседи. И вот кто-то ему нарубил целый сарай дров, кто-то принес ветчины, а кто-то помог Финдусу нарядить елку. Удивительное Рождество получилось у Петсона с Финдусом в этом году!', 'Christmas is just around the corner, but Pettson sprains his ankle before he can chop firewood, buy festive food, or cut down a tree. Findus is heartbroken—will there really be no celebration this year? Luckily, wonderful neighbors hear about Pettson''s trouble and arrive with baskets of treats, logs, and holiday cheer, turning a near-disaster into the coziest Christmas ever.', 'Božić je na pragu, a Petson i mačak Findus još nijesu stigli ništa da pripreme. Kada Petson ugane nogu, Findus je očajan: zar će praznici proći bez jelke, poslastica i poklona? Srećom, brižne komšije priskaču u pomoć i donose drva za ogrijev, ukusna jela i praznično raspoloženje, pretvarajući ovu nezgodu u najtopliji Božić do sada.', 'Самая тёплая зимняя история о том, что лучший праздник получается тогда, когда на помощь приходят заботливые соседи и находчивый кот.', 'A deeply cozy holiday tale proving that the best Christmas magic is made of thoughtful neighbors and one very determined cat.', 'Najtoplija zimska priča koja nas podsjeća da prazničnu čaroliju ne čine savršeni planovi, već dobre komšije i jedan domišljati mačak.', '/covers/DP-0894.webp', '#a83232', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["friends","animals","funny"]', '["christmas","winter","pettson and findus","kindness","neighbors"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('песенник-петсона-и-финдуса-895', 'DP-0895', 'Песенник Петсона и Финдуса', 'Pettson and Findus Songbook', 'Pjesmarica Petsona i Findusa', 'Свен Хедман', 'Sven Hedman', 'Sven Hedman', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Ну что, споем вместе с Петсоном и Финдусом? А может, даже станцуем? Фокстрот, самба, вальс, танго и многое другое в исполнении любимых героев! В книгу вошли двадцать пять песен с нотами по мотивам книг из популярной серии о старичке Петсоне и его котенке Финдусе. Эти песни можно не только разучить на гитаре или фортепьяно, но также послушать или скачать на музыкальных сервисах', 'Shall we sing along with Pettson and Findus, or maybe even dance? Foxtrot, samba, waltz, tango, and more performed by everyone''s favorite characters! This book brings together twenty-five songs with sheet music inspired by the beloved series about old man Pettson and his cheeky cat Findus. The songs are ready to be played on guitar or piano, or enjoyed on music streaming services.', 'Hoćemo li pjevati zajedno sa Petsonom i Findusom? A možda i zaplesati? Fokstrot, samba, valcer, tango i još mnogo toga uz omiljene junake! Ova knjiga sadrži dvadeset pet pjesama s notama inspirisanih čuvenim serijalom o čiča Petsonu i mačku Findusu. Melodije možete naučiti na gitari ili klaviru, ili ih jednostavno slušati na muzičkim platformama.', 'Доставайте гитары и разогревайте связки — старик Петсон и неугомонный Финдус объявляют самый душевный домашний концерт!', 'Dust off your guitar and warm up your vocal cords — old Pettson and lively Findus are throwing the coziest home concert ever!', 'Naštimujte gitare i zagrijte glasne žice — čiča Petson i neumorni Findus priređuju najveseliji domaći koncert!', '/covers/DP-0895.webp', '#e89d38', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["funny","friends","animals"]', '["music","songs","sheet music","cats","pettson and findus"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('поделки-финдуса-896', 'DP-0896', 'Поделки Финдуса', 'The Pettson and Findus Craft Book', 'Findusove majstorije', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Старик Петсон - мастер на все руки, а его котёнок Финдус обожает придумывать. Они научат тебя мастерить фигурки животных из шишек, пересаживать растения и проращивать семена, делать бусы из гороха с фасолью, печь вкусный пирог с красной смородиной, строить домик из палочек для мороженого и даже разводить головастиков! Самое замечательное в том, что всё, описанное в этой книге, можно сделать дома. Для младшего школьного возраста.', 'Old man Pettson is a handyman of all trades, and his curious cat Findus loves inventing things! In this book, they will teach you how to craft animal figurines from pinecones, repot plants, sprout seeds, string necklaces from dried beans, bake a delicious red currant pie, build miniature houses from popsicle sticks, and even raise tadpoles! The best part is that every single project can easily be made at home.', 'Čiča Petson je majstor za sve, a njegov mačak Findus obožava da smišlja nove izume! Oni će te naučiti kako da praviš figurice životinja od šišarki, presađuješ biljke, sadiš sjemenke, praviš perle od pasulja, pečeš slasnu pitu od ribizla, zidaš kućice od štapića za sladoled, pa čak i gajiš punoglavce. Najbolje od svega jeste što sve ove divne ideje možeš lako sprovesti kod kuće!', 'Готовьте шишки, клей и фартуки: Петсон и Финдус докажут, что из обычных веточек и горошин можно сотворить целый мир уютного творчества!', 'Grab your pinecones, glue, and aprons: Pettson and Findus are here to show that everyday twigs and beans can spark pure homemade creative joy!', 'Pripremite šišarke, ljepilo i kecelje: Petson i Findus će vam pokazati da se od običnih grančica i pasulja može stvoriti čitav svijet kućne kreativnosti!', '/covers/DP-0896.webp', '#5c8a42', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["friends","animals","real"]', '["crafts","diy","nature","cats","cooking"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('готовим-с-петсоном-и-финдусом-897', 'DP-0897', 'Готовим с Петсоном и Финдусом', 'Cooking with Pettson and Findus', 'Kuvamo sa Petsom i Findusom', '', 'Sven Nordqvist, Christine Samuelson', 'Sven Nurdkvist, Kristin Samuelson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Ни для кого не секрет, что Петсон - старик немного рассеянный. Мука у него может оказаться под диваном, а перец в велосипедной корзине. Его прекрасные рецепты разбросаны по всему дому. Однажды котёнок Финдус решил, что пора собрать их в кулинарную книгу, и вот что из этого получилось! Петсон и Финдус научат вас печь пироги и плюшки, варить супы, кисели, каши и даже готовить морковный мармелад. Рецепты у Петсона очень простые и вкусные, к тому же каждому из них предшествует небольшая история из жизни старика и котёнка. Большинство блюд дети постарше могут приготовить сами, а для самых маленьких предусмотрены задания попроще, которые обычно выполняет Финдус: скатать из фарша тефтельки, смешать соус, отмерить молоко и муку или натолочь сухари. Для младшего школьного возраста.', 'It’s no secret that Pettson is a bit forgetful—you might find flour under the sofa or pepper in the bicycle basket! His wonderful recipes were scattered all over the house until Findus the kitten decided it was high time to gather them into a proper cookbook. Pettson and Findus will teach you how to bake pies and buns, cook soups, porridge, and even make carrot marmalade. Each simple and delicious recipe is paired with a cozy short story about their countryside adventures, with tasks tailored for both older kids and little helpers.', 'Nije tajna da je čiča Petson pomalo zaboravan — brašno mu se može naći ispod kauča, a biber u korpi bicikla! Njegovi divni recepti bili su razbacani po cijeloj kući dok mačak Findus nije odlučio da ih sakupi u pravu kuvaricu. Petson i Findus će vas naučiti kako da pečete pite i peciva, kuvate supe, kaše i čak napravite marmeladu od šargarepe. Svaki jednostavan i ukusan recept prati topla pričica iz seoskog života, uz zadatke prilagođene i starijoj djeci i malim pomoćnicima.', 'Завязывайте фартуки: здесь столько тепла, историй и корицы, что готовить захочется даже тем, кто никогда не держал поварёшку!', 'Tie your aprons tight: this book is so full of warmth, stories, and cinnamon that even the most reluctant little chefs will want to grab a spoon!', 'Vežite kecelje: ova kuvarica je toliko puna topline, priča i cimeta da će i oni najmanji odmah poželeti da kuvaju!', '/covers/DP-0897.webp', '#d97736', 'nonfiction', 'ru', 'available', 'кулинарная книга с рецептами', '["funny","friends","animals"]', '["cooking","recipes","pettson and findus","baking","family food"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('механический-дед-мороз-898', 'DP-0898', 'Механический Дед Мороз', 'The Mechanical Santa', 'Mehanički Deda Mraz', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nurdkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Старик Петсон и котёнок Финдус готовятся встретить Рождество. "Но какое же Рождество без Деда Мороза?" - думает Финдус. "Но ведь Деда Мороза не существует, где его взять?.." - вздыхает Петсон. И тут ему в голову приходит блестящая идея! Для среднего школьного возраста.', 'Old man Pettson and his mischievous cat Findus are preparing for Christmas. Findus is dreaming of a visit from Santa, but Pettson knows he can''t make promises he can''t keep. To bring pure joy to his little friend, Pettson secretly sets out to build an automated mechanical Santa in his workshop, leading to a winter full of hilarious inventions and unexpected wonders.', 'Čiča Petson i njegov nestašni mačak Findus spremaju se za Božić. Findus silno želi da ih posjeti Deda Mraz, a Petson odlučuje da u svojoj radionici tajno napravi mehaničkog Deda Mraza kako ne bi razočarao prijatelja. Međutim, stvaranje pravog prazničnog čuda pretvara se u nevjerovatnu avanturu punu iznenađenja.', 'Уютная и хитроумная зимняя сказка о том, как ради детской веры в чудо можно сотворить волшебство из винтиков, шестерёнок и безграничной любви.', 'A warm and delightfully clever winter tale proving that to create a holiday miracle, all you need are gears, gizmos, and a big heart.', 'Topla i dovitljiva zimska priča koja pokazuje da je za pravo praznično čudo potrebno samo malo zupčanika, opruga i puno ljubavi.', '/covers/DP-0898.webp', '#9e2a2b', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["magic","friends","funny"]', '["pettson and findus","christmas","inventions","winter","friendship"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мама-му-и-гонщик-кракс-899', 'DP-0899', 'Мама Му и гонщик Кракс', 'Mama Moo and Racer Crow', 'Mama Mu i trkač Kraks', 'Юя Висландер', 'Jujja Wieslander', 'Juja Vislander', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Ну и жара! Мама Му купается в озере и пускает кораблики, а Кракс тем временем проектирует лучшую в мире гоночную лодку. Посмотрим, что из этого выйдет… Книги о Маме Му и Краксе переведены на 30 языков и известны во всем мире. Их авторы - Юя Висландер, почетный член шведской Академии детской книги, и Свен Нурдквист, получивший мировую известность благодаря книгам о Петсоне и Финдусе.', 'What a heatwave! Mama Moo is happily cooling off in the lake and floating toy boats, while Crow is busy engineering the fastest speedboat in the world. Let''s see how that hilarious maiden voyage turns out...', 'Kakva vrućina! Dok se Mama Mu veselo brčka u jezeru i pušta brodiće, Kraks neumorno projektuje najbrži trkački čamac na svijetu. Da vidimo šta će od toga ispasti...', 'Когда на дворе зной, ничто так не освежает, как заплыв беззаботной коровы и грандиозный инженерный провал ворчливого ворона!', 'When summer heat strikes, nothing beats a splash with an adventurous cow and a crow''s hilarious attempt at high-speed naval engineering!', 'Kad ljetnja žega pritisne, nema ničeg boljeg od vesele krave plivačice i vraninog urnebesnog brodograditeljskog poduhvata!', '/covers/DP-0899.webp', '#3a8eb5', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста.', '["funny","animals","friends"]', '["cows","summer","boats","friendship","humor"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мама-му-играет-в-лето-900', 'DP-0900', 'Мама Му играет в лето', 'Mama Moo Plays Summer', 'Mama Mu se igra ljeta', 'Юя Висландер', 'Jujja Wieslander', 'Jujja Wieslander', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Сосульки превращаются в мороженое, а на деревьях вырастает листва, когда у тебя есть друг с богатой фантазией. Мама Му может устроить маленькое лето даже в разгар зимы! Книги о Маме Му и Краксе переведены на 30 языков и известны во всем мире. Их авторы - Юя Висландер, почетный член шведской Академии детской книги, и Свен Нурдквист, получивший мировую известность благодаря книгам о Петсоне и Финдусе. Юя Висландер - шведская детская писательница. Наиболее известна как автор серии рассказов о любознательной корове Маме Му и философствующем вороне Краксе с иллюстрациями Свена Нурдквиста. Юя придумала персонажей вместе с мужем Томасом. Мама Му и Кракс появились как герои радиоспектакля и детских песен, и лишь в 1991 году вышла первая книга. В 2005 году Юя Висландер получила премию Астрид Линдгрен.', 'Icicles turn into ice cream and bare branches bloom with green leaves when you have a friend with boundless imagination! Mama Moo can conjure a sunny little summer even in the dead of winter. A heartwarming story by acclaimed Swedish author Jujja Wieslander and illustrator Sven Nordqvist about finding joy, sharing laughter, and warming up the coldest days alongside Crow.', 'Ledenice se pretvaraju u sladoled, a gole grane prolistaju kada imaš prijatelja sa beskrajnom maštom! Mama Mu uspijeva da stvori pravo malo ljeto usred ciče zime. Topla i duhovita priča proslavljene švedske autorke Jujje Wieslander i ilustratora Svena Nordqvista podsjeća nas da pravo prijateljstvo može ugrijati i najhladniji dan.', 'Кто сказал, что среди сугробов нельзя устроить пляж и полакомиться земляникой, если рядом самая изобретательная корова на свете?', 'Who says you can''t go for a swim and pick wild berries in deep snow when the world''s most inventive cow is your best friend?', 'Ko kaže da se usred snijega ne može plivati i brati jagode kad je uz tebe najmaštovitija krava na svijetu?', '/covers/DP-0900.webp', '#589e47', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста.', '["funny","friends","animals"]', '["mama moo","friendship","imagination","winter","humor"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сотворение-мира-901', 'DP-0901', 'Сотворение мира', 'The Creation of the World', 'Stvaranje svijeta', 'Салли Альтшулер', 'Sally Altschuler', 'Sali Altšuler', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Создавать мир - та еще работенка. Неудивительно, что Бог загрустил и подумал: "Вот бы мне кто-нибудь помог". Тогда рядом с ним сразу появилась Мия. Вдвоем они придумали все на свете, от морей до морковок. А потом решили, что это хорошо, и оставили людям - чтобы мы радовались миру и приглядывали за ним.', 'Creating a whole world is no easy task. No wonder God felt a bit lonely and thought, "If only someone could lend a hand." Just then, Mia appeared by His side. Together, they dreamed up everything under the sun, from vast oceans to crunchy carrots. When they saw that it was good, they entrusted it to humanity—for us to cherish, enjoy, and look after.', 'Stvaranje čitavog svijeta uopšte nije lak posao. Zato nije čudo što se Bog rastužio i pomislio: „Eh, kad bi mi neko pomogao.“ U tom trenu kraj njega se stvorila Mija. Udvoje su izmislili baš sve na svijetu, od sinjih mora do hrskavih šargarepa. A onda su zaključili da je sve ispalo divno i povjerili svijet ljudima — da u njemu uživamo i brižno ga čuvamo.', 'Тёплая и мудрая сказка о том, как в хорошей компании даже сотворение вселенной превращается в радостную созидательную игру!', 'A warm, witty tale reminding us that with a good friend by your side, even inventing the entire universe feels like pure, joyful play!', 'Topla i duhovita priča koja nas podsjeća da je u dobrom društvu čak i stvaranje čitavog svemira prava radosna igra!', '/covers/DP-0901.webp', '#3d7ea6', 'nonfiction', 'ru', 'available', 'Для дошкольного и младшего школьного возраста.', '["magic","friends","funny"]', '["creation","friendship","imagination","nature","philosophy"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('корабль-ноя-902', 'DP-0902', 'Корабль Ноя', 'Noah''s Ark', 'Nojeva barka', 'Салли Альтшулер', 'Sally Altschuler', 'Sali Altšuler', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Дождь лил как из ведра, и Ной торопился поскорее собрать зверей на своем корабле. Вот только Носорог постоянно ворчал и жаловался, что его никто не любит. Так оно поначалу и было, но тут случилось кое-что непредвиденное, и Носорогу удалось доказать, что он настоящий герой. Датский писатель Салли Альтшулер показывает библейскую историю с неожиданной точки зрения. А знаменитый Свен Нурдквист удивительно остроумно изображает события, произошедшие во время Всемирного потопа.', 'It was pouring with rain, and Noah rushed to gather the animals onto his ark. Only Rhino kept grumbling and complaining that nobody loved him. At first, that was true enough—until something unexpected happened, giving Rhino a chance to prove he was a true hero. Danish author Sally Altschuler offers an unexpected perspective on the biblical tale, brilliantly accompanied by Sven Nordqvist''s witty illustrations.', 'Kiša je lila kao iz kabla, a Noje je žurio da sakupi sve životinje na svoju barku. Jedino je Nosorog stalno gunđao i žalio se da ga niko ne voli. U početku je zaista bilo tako, sve dok se nije desilo nešto neočekivano, što je Nosorogu pružilo priliku da dokaže da je pravi heroj. Danski pisac Sali Altšuler prikazuje biblijsku priču iz sasvim neočekivanog ugla, uz duhovite ilustracije slavnog Svena Nurdkvista.', 'Даже самый ворчливый носорог способен спасти целый ковчег, особенно если за дело берётся неподражаемый Свен Нурдквист!', 'Even the grumpiest rhino can save the entire ark, especially when illustrated by the brilliant Sven Nordqvist!', 'Čak i najmrzovoljniji nosorog može spasiti čitavu barku, posebno kad priču oslika neponovljivi Sven Nurdkvist!', '/covers/DP-0902.webp', '#3d6a7d', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста.', '["funny","animals","adventure"]', '["noah''s ark","rhino","sven nordqvist","biblical stories","kindness"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('башня-вавилона-903', 'DP-0903', 'Башня Вавилона', 'The Tower of Babel', 'Vavilonska kula', 'Салли Альтшулер', 'Sally Altschuler', 'Sali Althuler', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Король совсем сбился с ног, чтобы развеселить свою дочку, но принцесса все равно скучает целыми днями: музыканты играют занудную музыку, повар готовит надоевшую еду, а танцоры всегда танцуют один и тот же танец. И тогда король приказал господину Вавилону созвать со всего мира лучших ремесленников и построить самую высокую в мире башню. "Башня господина Вавилона" - свободная трактовка знаменитого древнего мифа с юмористическими иллюстрациями Свена Нурдквиста.', 'The king is desperate to cheer up his bored daughter, who finds the palace musicians dull, the food monotonous, and the dancers entirely predictable. To dazzle her, he tasks Mr. Babylon with summoning the world''s greatest builders to erect the tallest tower in existence. A witty, whimsical retelling of the ancient myth brought vividly to life with Sven Nordqvist’s beloved, detail-packed illustrations.', 'Kralj daje sve od sebe da oraspoloži svoju ćerku, ali princezi je i dalje dosadno: muzičari sviraju uspavanke, kuvar priprema jednolična jela, a plesači stalno ponavljaju isti ples. Zato kralj naređuje gospodinu Vavilonu da okupi najbolje majstore sa svih krajeva svijeta i sagradi najvišu kulu na planeti. Duhovita interpretacija drevnog mita sa prepoznatljivim ilustracijama Svena Nordkvista.', 'Древний миф превращается в уморительную стройку века с фирменными деталями и юмором от несравненного Свена Нурдквиста!', 'An ancient myth turns into a hilarious construction project of the century, packed with Sven Nordqvist’s delightfully chaotic illustrations!', 'Drevni mit pretvoren u urnebesno gradilište vijeka, obogaćeno neodoljivim detaljima i humorom Svena Nordkvista!', '/covers/DP-0903.webp', '#d98236', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста.', '["funny","adventure"]', '["myths","architecture","humor","sven nordqvist","princesses"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-настоящих-рыболовов-904', 'DP-0904', 'Книга настоящих рыболовов', 'The Real Angler''s Book', 'Knjiga pravih ribolovaca', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Свен Нурдквист', 'Рипол Кит', NULL, NULL, 6, 16, 'middle', 'Что может быть интереснее и веселее, чем рыбалка в отличной компании? Особенно если ты настоящий спец в этом деле и знаешь, чем скумбрия отличается от трески, как ловить рыбу на мушку и что с ней делать, когда поймал. Не знаешь? Ничего страшного! Знаменитый шведский художник Свен Нурдквист расскажет и покажет все, что нужно знать настоящему рыболову. Так что смело беги на ближайшую речку (пруд, озеро, море). И не забудь взять с собой книжку!', 'What could be more exciting and fun than going fishing in good company? Especially if you know the difference between mackerel and cod, how to fly-fish, and what to do with your catch. If you don''t know yet, don''t worry! Acclaimed Swedish author and illustrator Sven Nordqvist explains and illustrates everything an aspiring angler needs to know. Grab your gear, head to the nearest river, lake, or sea—and don''t forget this book!', 'Šta može biti uzbudljivije i zabavnije od ribolova u dobrom društvu? Posebno ako već znaš razliku između skuše i bakalara, kako loviti na mušicu i šta raditi s ulovom. Još ne znaš? Ništa strašno! Čuveni švedski autor i ilustrator Sven Nordkvist objašnjava i crta sve što pravi ribolovac treba da zna. Uzmi opremu, kreni ka reci, jezeru ili moru — i ne zaboravi ovu knjigu!', 'Даже если вы ни разу не держали удочку, после этой книги Свена Нурдквиста вам немедленно захочется отправиться на рассвете к морю или реке!', 'Even if you''ve never held a fishing rod, Sven Nordqvist’s delightful guide will have you dreaming of catching fish at dawn by the sea!', 'Čak i ako nikada niste držali štap za pecanje, uz ovu predivnu knjigu Svena Nordkvista odmah ćete poželeti da u zoru krenete na obalu!', '/covers/DP-0904.webp', '#2d758c', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["adventure","animals","real"]', '["рыбалка","природа","рыбы","хобби","энциклопедия"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('минус-и-большой-мир-905', 'DP-0905', 'Минус и большой мир', 'Minus and the Big World', 'Minus i veliki svijet', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Пора мне в дорогу, на мир посмотреть, решил однажды маленький мальчик по имени Минус. Сказано - сделано. В пути Минуса ждут необыкновенные встречи: он познакомится с тремя глуповатыми мудрецами, неумолкающим таратетрисом, разозлит ведьму, утешит грустную девочку Магдалену, поможет потерпевшему крушение воздухоплавателю взлететь в небо, спасет портниху от королевского гнева и научится считать до ста!', '"It''s time for me to hit the road and see the world," a little boy named Minus decides one day. No sooner said than done! On his journey, extraordinary encounters await him: he meets three rather silly wise men, an incessant chatterer, angers a witch, comforts a sad girl named Magdalena, helps a stranded balloonist take to the skies again, saves a seamstress from royal fury, and learns to count to a hundred!', '„Vrijeme je da krenem na put i vidim svijet“, odlučio je jednog dana mali dječak po imenu Minus. Rečeno — učinjeno! Na tom putovanju Minusa čekaju nevjerovatni susreti: upoznaće tri pomalo šašava mudraca, neumornu pričalicu, naljutiti vješticu, utješiti tužnu djevojčicu Magdalenu, pomoći unesrećenom vazduhoplovcu da se ponovo vine u nebo, spasiti krojačicu od kraljevog bijesa i naučiti da broji do sto!', 'Фантастическое и невероятно тёплое путешествие от создателя Петсона и Финдуса, в котором каждая страница полна забавных деталей и доброты.', 'A whimsical, wonderfully detailed journey from the creator of Pettson and Findus, where counting to a hundred turns into a great adventure.', 'Čudesno i toplo putovanje od tvorca Petsona i Findusa, gdje se učenje brojanja pretvara u pravu nezaboravnu pustolovinu.', '/covers/DP-0905.webp', '#4a7c59', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста.', '["adventure","funny","magic"]', '["journey","counting","fairy tale","kindness","illustrations"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прогулка-906', 'DP-0906', 'Прогулка', 'The Walk', 'Šetnja', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Обычная Прогулка с собакой может обернуться приключением, полным приятных неожиданностей. Розовый мамонт грустит в клетке для канарейки, а буйвол играет на ударной установке. Гигантский чайник сам разливает чай, а шляпа притворяется островком в море. В фантастических мирах Свена Нурдквиста возможно все! Свен Нурдквист - шведский художник и писатель, получивший мировую известность благодаря своим книгам для детей. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всем мире.', 'An ordinary walk with a dog turns into an extraordinary journey packed with delightful surprises. Discover a pink mammoth squeezed into a canary cage, a buffalo rocking the drums, and a giant teapot pouring its own tea! In the wondrous, boundless worlds of Sven Nordqvist, absolutely anything is possible. A richly detailed visual feast for dreamers of all ages.', 'Obična šetnja sa psom pretvara se u nevjerovatnu avanturu punu čudesnih iznenađenja. Upoznajte ružičastog mamuta u kavezu za kanarince, bivola koji svira bubnjeve i džinovski čajnik koji sam toči čaj! U čarobnom svijetu mašte Svena Nordqvista sve je moguće — raskošno ilustrovana knjiga za istraživanje bez granica.', 'Забудьте про скучные маршруты: приготовьтесь часами разглядывать безумные и невероятно уютные детали этого волшебного путешествия!', 'Forget boring daily strolls—get ready to lose yourself for hours in the delightfully absurd, magical details of this epic wander!', 'Zaboravite na obične rute i spremite se da satima istražujete razigrane, čarobne detalje ovog nevjerovatnog putovanja!', '/covers/DP-0906.webp', '#3f7a5c', 'nonfiction', 'ru', 'available', 'книга без слов', '["adventure","magic","funny"]', '["picture book","imagination","dogs","whimsical","visual search"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('понятная-математика-907', 'DP-0907', 'Понятная математика', 'Math Made Simple', 'Jasna matematika', 'Кристина Даль', 'Kristin Dahl', 'Kristin Dal', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Думаешь, математика безнадежна и трудна? Возможно, ты даже считаешь, что она явно не для тебя? Так думают только те, кто не знает, что она из себя представляет на самом деле. Прочитав эту книгу, полную интереснейших задач (с ответами) и смешных рисунков Свена Нурдквиста, ты поймешь: математика вовсе не скучная и не сложная! Решая приведенные здесь задачи, не торопись и постарайся придумать несколько вариантов ответа. А иногда потребуется вывернуть ответ наизнанку!', 'Think math is hopelessly dull and difficult? That''s only because you haven''t seen its playful side! Packed with clever puzzles, brainteasers with answers, and hilarious drawings by Sven Nordqvist, this lively guide proves that math is anything but boring when you look at it from a fresh angle.', 'Misliš da je matematika beznadežna i dosadna? Tako misle samo oni koji još nijesu otkrili njenu pravu, zabavnu stranu! Puna neobičnih logičkih zadataka (sa rješenjima) i duhovitih crteža Svena Nurdkvista, ova knjiga pokazuje kako matematika može biti uzbudljiva igra.', 'Остроумные головоломки и фирменные рисунки Свена Нурдквиста превратят даже убеждённого «гуманитария» в азартного исследователя чисел!', 'With Sven Nordqvist''s whimsical art and clever brainteasers, even stubborn math skeptics will fall head over heels for playful logic!', 'Uz duhovite crteže Svena Nurdkvista i vesele mozgalice, čak i oni koji bježe od brojeva postaće pravi istraživači!', '/covers/DP-0907.webp', '#e8982c', 'nonfiction', 'ru', 'available', 'Для среднего школьного возраста.', '["funny","real"]', '["math","puzzles","logic","brainteasers","sven nordqvist"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебные-линзы-и-хитроумные-я-908', 'DP-0908', 'Волшебные линзы и хитроумные ящички', 'Magic Lenses and Clever Boxes', 'Čarobna sočiva i dovitljive kutije', 'Пелле Экерман', 'Pelle Eckerman', 'Pele Ekerman', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Книга посвящена истории развития оптики - с древнейших времен и до наших дней. Здесь не только рассказывается про знаменитых ученых и изобретателей - Пифагора, Леонардо да Винчи, Исаака Ньютона и многих других, но еще приводятся пошаговые инструкции по изготовлению простейших научных приборов - микроскопа, телескопа, ящичного фотоаппарата и не только. Книга иллюстрирована художником Свеном Нурдквистом.', 'This captivating journey through the history of optics travels from ancient times right up to modern breakthroughs. Alongside tales of iconic thinkers like Pythagoras, Leonardo da Vinci, and Isaac Newton, curious minds will find step-by-step DIY guides to build their own microscopes, telescopes, and pinhole cameras—all brought to life with charming illustrations by Sven Nordqvist.', 'Ovo uzbudljivo putovanje kroz istoriju optike vodi nas od antičkih vremena pa sve do modernog doba. Pored priča o genijalnim naučnicima poput Pitagore, Leonarda da Vinčija i Isaka Njutna, radoznalci će pronaći i jasna uputstva kako da sami naprave mikroskop, teleskop ili kameru opskuru — a sve to uz prepoznatljive ilustracije Svena Nurdkvista.', 'Узнайте тайны света вместе с иллюстрациями Свена Нурдквиста и соберите собственный телескоп прямо дома!', 'Uncover the secrets of light with Sven Nordqvist''s whimsical art and build your very own telescope right at home!', 'Otkrijte tajne svjetlosti uz divne crteže Svena Nurdkvista i napravite sopstveni teleskop kod kuće!', '/covers/DP-0908.webp', '#3b7a99', 'nonfiction', 'ru', 'available', 'Для детей среднего и старшего школьного возраста.', '["adventure","real"]', '["optics","science","experiments","inventions","sven nordqvist"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сага-о-людях-из-бирки-909', 'DP-0909', 'Сага о людях из Бирки', 'The Saga of the People of Birka', 'Saga o ljudima iz Birke', 'Матс Валь', 'Mats Wahl', 'Mats Val', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Эпоха викингов необыкновенно притягательна. Драккары и военные походы, скандинавские боги и саги поневоле будят воображение. Однако мы довольно смутно представляем себе, как протекала жизнь тысячу лет назад, как человек ухитрялся выживать в суровом мире. Романтический ореол вокруг викингов не находит ни исторического, ни археологического подтверждения. Зато усилиями ученых что ни год обнаруживаются новые фрагменты рассыпанной головоломки. Их пока слишком мало, чтобы сложить картину целиком. И приходится прибегать к помощи фантазии. В своей повести о событиях в Бирке и на балтийских берегах Матс Валь опирается на факты, полученные благодаря археологическим раскопкам. А иллюстрации Свена Нурдквиста, точно уловившего дух времени, вновь оживляют для нас давно ушедших людей и мир, в котором они жили.', 'The Viking Age holds an irresistible pull, but what was daily life truly like beyond dramatic myths of dragon ships and warrior gods? Drawing on authentic archaeological discoveries and enriched by Sven Nordqvist''s atmospheric illustrations, Mats Wahl reconstructs 10th-century Birka, unveiling the reality of how ordinary craftspeople, traders, and families survived on the rugged Baltic shores.', 'Doba vikinga je nevjerovatno privlačno, ali kako je zapravo izgledao svakodnevni život prije hiljadu godina, mimo mitova o pohodima i bogovima? Oslanjajući se na arheološka iskopavanja i uz maestralne ilustracije Svena Nurdkvista, Mats Val oživljava drevni grad Birku i priča istinitu priču o običnim ljudima koji su živjeli i opstajali na obalama Baltika.', 'Забудьте о мифических рогатых шлемах — откройте настоящий мир викингов с исторической точностью и неподражаемыми рисунками Свена Нурдквиста!', 'Forget horned helmets and Hollywood myths — step right into an authentic Viking trading town brought alive by archaeology and Sven Nordqvist''s vivid art!', 'Zaboravite na mitove o rogatim šljemovima — zakoračite u pravi vikinški trgovački grad kroz arheologiju i nezaboravne crteže Svena Nurdkvista!', '/covers/DP-0909.webp', '#48687a', 'nonfiction', 'ru', 'available', 'Категория: Свен Нурдквист', '["real","adventure"]', '["vikings","history","archaeology","middle ages","sven nordqvist"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дальний-путь-910', 'DP-0910', 'Дальний путь', 'The Long Journey', 'Daleki put', 'Матс Валь', 'Mats Wahl', 'Mats Val', 'Свен Нурдквист', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Кто из нас в детстве не мечтал тайком убежать из дома и отправиться в кругосветное путешествие? В XVIII веке у детей было больше шансов сделать это! На дворе 1743 год. Двое мальчишек незаметно пробираются на борт корабля "Гетеборг", который должен отправиться в Китай. Когда их находят матросы, корабль отплыл уже слишком далеко. Путешествие оказалось не только романтическим, но и весьма опасным.', 'Who hasn''t dreamed of sneaking away from home as a kid to embark on an around-the-world voyage? In the 18th century, runaway kids had a real shot at it! It''s 1743, and two brave boys slip aboard the Swedish merchant ship Götheborg bound for distant China. By the time the crew discovers them, turning back is out of the question. Their grand voyage turns out to be not only romantic, but fraught with real danger, storms, and thrilling discoveries.', 'Ko u djetinjstvu nije sanjao o tome da krišom pobjegne od kuće i krene na put oko svijeta? U 18. vijeku djeca su imala mnogo više šansi za to! Godina je 1743. Dvojica dječaka neprimijećeno se ukrcavaju na švedski trgovački brod „Geteborg”, koji plovi za daleku Kinu. Kada ih mornari otkriju, brod je već predaleko na pučini. Putovanje se ispostavlja ne samo romantičnim, već i prepunim stvarnih opasnosti i avantura.', 'Запрыгивайте на борт парусника XVIII века — только держитесь крепче, ведь впереди бурные шторма и настоящее кругосветное плавание!', 'Sneak aboard an 18th-century tall ship bound for China — just hold on tight, because a stowaway''s voyage is packed with wild storms and true adventure!', 'Ušunjajte se na jedrenjak iz 18. vijeka koji plovi za Kinu — samo se čvrsto držite, jer vas čekaju prave morske oluje i velika avantura!', '/covers/DP-0910.webp', '#1e3d59', 'nonfiction', 'ru', 'available', 'Для среднего школьного возраста.', '["adventure","real","friends"]', '["sea voyage","history","sailing ships","china","stowaways"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('непослушный-пират-911', 'DP-0911', 'Непослушный пират', 'The Disobedient Pirate', 'Neposlušni pirat', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Максим Покалев', 'Эгмонт', NULL, NULL, 6, 16, 'middle', '"Увидеть мир глазами подростка, оставаясь при этом взрослым, - уникальный дар, которым Гиваргизов обладает вполне. Прибавьте к этому парадоксальность мышления - и получите представление о прозе Артура Гиваргизова" (Ксения Молдавская, газета "Книжное обозрение"). "Когда после долгой зимы открывают и моют окна, мир внутри дома и снаружи становится ярким, просторным, праздничным - совсем таким, как на картинках Максима Покалева', 'Seeing the world through the eyes of a mischievous teenager while retaining the playful wisdom of an adult is Givargizov''s unique gift. Packed with paradoxical humor and wonderfully complemented by Maxim Pokalev''s lively illustrations, this book turns ordinary reality delightfully upside down.', 'Gledati svijet očima nestašnog tinejdžera, a pritom zadržati razigranu mudrost odraslog čovjeka — jedinstven je dar Artura Givargizova. Puna paradoksalnog humora i upotpunjena vedrim ilustracijama Maksima Pokaljeva, ova knjiga svakodnevicu pretvara u urnebesnu igru.', 'Искромётные, парадоксальные и до колик смешные истории для всех, кто хоть раз в душе чувствовал себя непослушным бунтарём!', 'Sparkling, paradoxical, and belly-laugh funny tales for anyone who has ever felt like a rebellious pirate at heart!', 'Pjenušave, paradoksalne i urnebesno smiješne priče za svakoga ko se u duši ikada osjećao kao neposlušni pirat!', '/covers/DP-0911.webp', '#2c6d8c', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","adventure"]', '["short stories","humor","pirates","absurdity","growing up"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('контрольный-диктант-и-древнегр-912', 'DP-0912', 'Контрольный диктант и древнегреческая трагедия', 'The Dictation Test and Ancient Greek Tragedy', 'Kontrolni diktat i starogrčka tragedija', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Александр Войцеховский', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Иногда очень хочется пойти в театр. Вдруг! Ночью! Посмотреть какую-нибудь Древнегреческую трагедию. Но нет времени, или билетов. Или ночью в театр без родителей не пускают. Иногда очень не хочется писать контрольный диктант. Но от Веры Петровны не спрячешься даже в лесу. Иногда из-за очень хорошего зрения совсем ничего не видишь, фамилии меняются вместе с временами года, во дворе можно устроить Красное море, поставить олимпийский рекорд, убегая от собаки... Многое бывает иногда. Всё зависит от настроения. А настроение у автора и художника книжки "Контрольный диктант и древнегреческая трагедия" всегда для весёлых и необычных историй подходящее.', 'Sometimes you desperately want to go to the theater. Suddenly! At night! To watch an ancient Greek tragedy. But there''s never time, or tickets, or parents won''t let you out at night. Other times you really don''t want to write a pop dictation test, but there is no hiding from your teacher, even in the woods. Sometimes sharp vision makes you completely blind, surnames change with the seasons, and running from a neighborhood dog turns into an Olympic record. Master of absurd humor Artur Givargizov turns everyday school life into a delightfully witty adventure.', 'Ponekad poželite da odete u pozorište. Iznenada! Noću! Da pogledate neku starogrčku tragediju. Ali nema vremena, nema karata, ili vas roditelji noću ne puštaju napolje. Drugi put vam se nikako ne piše kontrolni diktat, ali od nastavnice se ne možete sakriti čak ni u šumi. Ponekad zbog preoštrog vida ne vidite ništa, prezimena se mijenjaju sa godišnjim dobima, a bježanje od psa u dvorištu pretvara se u olimpijski rekord. Majstor apsurdnog humora Artur Givargizov pretvara običan đački dan u neponovljivu komediju.', 'Фирменный абсурд и тонкая школьная ирония Гиваргизова спасут от хандры любого отличника и двоечника!', 'Givargizov''s signature absurdism and wry school humor are the ultimate cure for homework blues!', 'Givargizovljev prepoznatljivi apsurd i vrcavi đački humor pravi su lijek protiv svakog školskog umora!', '/covers/DP-0912.webp', '#d96b43', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["school","humor","short stories","absurd","growing up"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('записки-собаки-охотника-913', 'DP-0913', 'Записки собаки охотника', 'Notes of a Hunter''s Dog', 'Bilješke lovačkog psa', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Ляля Ваганова', '', NULL, NULL, 6, 16, 'middle', 'Что же такое эти "Записки"? Это стихи. Самые настоящие, добротно сделанные и великолепно выдуманные детские стихи, в духе лучших представителей этого жанра. Читая их, находишь отголоски поэзии Даниила Хармса, Саши Чёрного, Бориса Заходера. Помните "Дневник фокса Микки"? По его мотивам ещё мультфильм сняли, "Записки Пирата". Вот персонаж заглавного стихотворения этой книги - явно его родственник.', 'What are these ''Notes''? They are poems—genuine, masterfully crafted, and wonderfully imaginative children''s verses in the finest traditions of Daniil Kharms, Sasha Chorny, and Boris Zakhoder. Meet an observant, delightfully eccentric four-legged philosopher whose witty reflections on life and hunting will charm readers of all ages.', 'Šta su zapravo ove „Bilješke“? To su pjesme – autentični, majstorski sročeni i maštoviti dječiji stihovi u duhu Danila Harmsa, Saše Čornog i Borisa Zahodera. Upoznajte pronicljivog, neodoljivo šašavog četvoronožnog filozofa čija će duhovita razmišljanja o životu i lovu osvojiti čitaoce svih uzrasta.', 'Невероятно остроумные и озорные стихи от лица пса, который понимает в жизни и людях куда больше своего хозяина-охотника!', 'Incredibly witty and playful verses told from the perspective of a dog who understands life and people far better than his hunter master!', 'Nevjerovatno duhoviti i nestašni stihovi ispričani iz ugla psa koji o životu i ljudima razumije mnogo više od svog vlasnika lovca!', '/covers/DP-0913.webp', '#bf6b35', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","animals"]', '["poetry","dogs","humor","rhymes","pets"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('морж-учитель-и-поэт-914', 'DP-0914', 'Морж, учитель и поэт', 'The Walrus, the Teacher and the Poet', 'Morž, učitelj i pjesnik', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', '', 'розовый жираф', NULL, NULL, 6, 16, 'middle', 'Артур Гиваргизов давно известен как автор детских стихов (сборники "Как-то я летел с рябины", "Генералы", "Когда некогда", "Космонавты" и другие), рассказов и пьес. По образованию Артур профессиональный музыкант, но, читая его стихи, сразу понимаешь, что он настоящий поэт, хулиган и волшебник, который как никто понимает детей, и всегда заодно со своими читателями. Его новая книжка - "Морж, учитель и поэт" - это две истории о шестидесятилетнем Михаиле Михайловиче из поселка Песочный на берегу Северного Ледовитого океана. Но не пугайтесь! Речь совсем не о скучном пенсионере. Миша - человек пожилой, но очень, по-детски, счастливый, и все его зовут просто по имени, "потому что маленький, несерьёзный и мудрый - это одно и то же".', 'Arthur Givargizov, celebrated for his mischievous and whimsical style, presents two heartwarming stories about sixty-year-old Mikhail Mikhailovich living on the shores of the Arctic Ocean. Far from a boring pensioner, Misha possesses the delightfully joyful spirit of a child, and everyone calls him by his first name—because being small, silly, and truly wise often turn out to be the exact same thing.', 'Artur Givargizov, poznat po svom duhovitom i vragolastom stilu, donosi dvije tople priče o šezdesetogodišnjem Mihailu Mihajloviču koji živi na obali Sjevernog ledenog okeana. Daleko od dosadnog penzionera, Miša ima radosnu djetinju dušu i svi ga zovu jednostavno po imenu—jer biti malen, neozbiljan i mudar zapravo je jedno te isto.', 'Трогательные и невероятно смешные арктические зарисовки о том, что настоящая мудрость и детское озорство прекрасно уживаются вместе.', 'Touching and delightfully eccentric Arctic tales proving that true wisdom and playful childhood mischief belong hand in hand.', 'Dirljive i neodoljivo duhovite arktičke priče koje dokazuju da istinska mudrost i djetinja nestašnost idu ruku pod ruku.', '/covers/DP-0914.webp', '#437b8d', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","friends","real"]', '["arctic","humor","short stories","wisdom","eccentric characters"]', 1792836322700, 1792845691095);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('слово-мамонта-915', 'DP-0915', 'Слово мамонта', 'Mammoth''s Word', 'Mamutova riječ', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', '', 'розовый жираф', NULL, NULL, 6, 16, 'middle', 'Миша в новой книге Артура Гиваргизова опять отправляется в путешествие, на Алтай. Если вы не знаете, где это, то скорее посмотрите на карту. А еще лучше купите билет до Барнаула, а оттуда на маршрутку в Тюнгур и возьмите с собой рюкзак, спальник, шерстяные носки… Ой, нет, сперва просто прочитайте, что написано об этом в повести «Как пройти на Белуху». А как приятно после путешествия вернуться домой, туда где все по-старому, уютно и понятно, и рассказывать соседям обо всем, что увидел. Правда, когда Миша вернулся с Алтая, оказалось, что в его родном Песочном назревают удивительные изменения. Такие, что даже мамонт заговорил. Об этом расскажет вторая повесть сборника, «Слово мамонта».', 'In Artur Givargizov''s delightful book, Misha embarks on an unforgettable journey to the rugged Altai Mountains. Before you pack your backpack and wool socks, discover how to find Mount Belukha through his witty travel notes. But the biggest adventure awaits back home in Pesochnoye, where things get so delightfully strange that even a prehistoric mammoth finds its voice!', 'U novoj knjizi Artura Givargizova, dječak Miša ponovo kreće na uzbudljivo putovanje — ovog puta na Altajske planine. Prije nego što spakujete ranac i tople čarape, saznajte kako stići do vrha Beluha kroz njegove duhovite bilješke. Ipak, najveće iznenađenje ga čeka kod kuće u selu Pjesočno, đe se dešavaju toliko neobične stvari da je čak i mamut progovorio!', 'Уморительные путевые заметки и деревенские чудеса от главного мастера доброго и тёплого детского абсурда!', 'Hilarious travel notes and quirky hometown wonders from a true master of warm, clever absurdism!', 'Urnebesne putopisne bilješke i seoska čuda od majstora toplog i pametnog apsurdnog humora!', '/covers/DP-0915.webp', '#c96542', 'nonfiction', 'ru', 'available', '7-9 лет', '["funny","adventure","real"]', '["altai","travel","humor","mountains","mammoth"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ефремовские-сказки-916', 'DP-0916', 'Ефремовские сказки', 'Tales from Yefremov', 'Jefremovske bajke', 'Артур Гиваргизов', 'Arthur Givargizov', 'Artur Givargizov', '', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Ефремов - это город. Сказки - это не сказки. Вернее, для нас, может быть, и сказки, а для жителей Ефремова - каждодневные новости. Например, коробка с серебряными звёздами. Ну конечно, её фокусник оставил. Просто Николаю Михайловичу надо было ещё пять минут подождать-посидеть спокойно, терпения не хватило, жаль. Кстати, вечером того же дня в коробку забрался Трезор. Теперь он чайка. Летает над двором и кричит: "Я собака! Собака!". Превращение Трезора в книжку не вошло, потому что Трезор превратился вечером, а книжку уже днём отправили в типографию. Да тут за полдня ещё столько всего случилось! В Ефремове каждый час случается что-нибудь необычное', 'Yefremov is a real town, but its tales aren''t fairy tales—to locals, they are just daily news! A magician accidentally leaves behind a box of silver stars, a dog named Trezor turns into a seagull and flies overhead yelling that he''s a dog, and miracles happen literally every hour. Arthur Givargizov offers a masterclass in witty absurdist humor where provincial life turns utterly delightful.', 'Jefremov je grad, a ove bajke zapravo i nisu bajke — za lokalne stanovnike to su samo svakodnevne vijesti! Mađioničar zaboravi kutiju sa srebrnim zvijezdama, pas Trezor se pretvori u galeba koji leti i viče da je pas, a neobična čuda dešavaju se svakog sata. Artur Givargizov majstorski plete apsurdne, duhovite minijature koje svakodnevicu pretvaraju u urnebesnu igru.', 'Приготовьтесь удивляться каждую минуту: в Ефремове абсурдные чудеса происходят быстрее, чем книги успевают сдавать в печать!', 'Get ready to laugh and blink in disbelief: in Yefremov, wonderfully absurd miracles happen faster than the printing press can keep up!', 'Pripremite se za smijeh i nevjericu: u Jefremovu se apsurdna čuda dešavaju brže nego što štamparija stigne da ih objavi!', '/covers/DP-0916.webp', '#d88138', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","magic"]', '["absurdist humor","short stories","laughter","provincial life","quirky"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бесконечно-ваши-волк-и-красная-917', 'DP-0917', 'Бесконечно ваши, Волк и Красная Шапочка', 'Yours Truly, Wolf and Little Red Riding Hood', 'Beskrajno vaši, Vuk i Crvenkapa', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Капыч', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Девятнадцать вариаций на известную тему. На очень известную тему. Кажется, что всё уже сыграно… А вот и не всё: "Однажды Красная Шапочка отправилась в дремучий лес в ритме танго. А навстречу ей - Волк в ритме сальсы. На нём был бабушкин чепец, украшенный бумажными розочками, и халат, расшитый хризантемами"', 'Nineteen wildly witty variations on an all-too-familiar fairy tale. You think everything has already been told? Think again: what if Little Red Riding Hood glides into the deep dark woods dancing tango, while the Wolf twirls up in salsa rhythm, wearing Grandma''s lace bonnet adorned with paper roses and a silk robe embroidered with chrysanthemums?', 'Devetnaest izuzetno duhovitih varijacija na dobro poznatu priču. Mislite da je sve već viđeno i ispričano? Nije ni izbliza: šta ako Crvenkapa krene u gustu šumu u ritmu tanga, a u susret joj zapleše Vuk u ritmu salse, sa bakinom kapicom ukrašenom papirnim ružicama i kućnim ogrtačem punim hrizantema?', 'Забудьте всё, что вы знали о сером разбойнике и пирожках: здесь правят искромётный абсурд, танго и чистый писательский драйв!', 'Forget everything you thought you knew about the Big Bad Wolf and grandma''s pies: here rules sparkling absurdity, tango, and sheer literary delight!', 'Zaboravite sve što ste znali o vuku i pitama: ovdje vladaju blistavi apsurd, tango i čista čitalačka zabava!', '/covers/DP-0917.webp', '#b8332a', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","animals"]', '["fairy tale retelling","humor","short stories","red riding hood","parody"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вопрос-номер-25-918', 'DP-0918', 'Вопрос номер 25', 'Question Number 25', 'Pitanje broj 25', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Артем Костюкевич', 'Время', NULL, NULL, 6, 16, 'middle', 'Однажды меня попросили написать о вежливости: "Это очень серьёзная тема. Объясни, пожалуйста, детям, что такое вежливость. Ты же работал учителем?" Да, работал. У меня сначала плохо получалось, дети на моих уроках спали с открытыми глазами. Я разуверился в своих способностях, стал над собой подшучивать… А дети вдруг проснулись и начали внимательно слушать. Тогда я схитрил, придумал для серьёзной темы весёлый пример, рассказ "Прекрасный урок". С "Прекрасным уроком" урок прошёл - прекрасно. Вот из таких примеров и состоит книжка "Вопрос номер двадцать пять".', 'Once upon a time, the author was asked to write about politeness for children: ''It''s a serious topic, and you used to be a teacher, didn''t you?'' Well, he was—and he remembers all too well how kids slept with their eyes open during boring lectures until he learned to laugh at himself. Instead of lecturing, Artur Givargizov serves up witty, cheeky, and laugh-out-loud stories where good manners become an exciting adventure rather than a chore.', 'Jednom su pisca zamolili da napiše nešto o lijepom ponašanju: ''To je ozbiljna tema, a ti si nekada bio učitelj, zar ne?'' Jeste, bio je—i dobro pamti kako su djeca spavala otvorenih očiju na dosadnim časovima sve dok se nije počeo šaliti na sopstveni račun. Umjesto suvoparnih pridika, Artur Givargizov donosi urnebesne i vesele priče u kojima bonton postaje zabavna avantura.', 'Невероятно смешной и честный самоучитель по хорошим манерам от автора, который точно знает, как увлечь класс без скучных нотаций!', 'An outrageously funny and honest etiquette guide from a former teacher who knows how to skip the dull lectures and keep kids laughing!', 'Nevjerovatno duhovit i iskren vodič kroz lijepo ponašanje bivšeg učitelja koji tačno zna kako da privuče pažnju bez dosadnih pridika!', '/covers/DP-0918.webp', '#d97724', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["etiquette","school life","humor","manners","short stories"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('генералы-919', 'DP-0919', 'Генералы', 'Generals', 'Generali', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Максим Покалев', 'Самокат', NULL, NULL, 6, 16, 'middle', '"Генералы" - результат работы поэта Артура Гиваргизова и художника Максима Покалёва. Генералы - персонажи каждого вошедшего в сборник стихотворения. Самые настоящие генералы - на службе, на параде, на рыбалке, в больнице, на футбольном матче или на прогулке с внучкой. Все герои книги симпатичные, а порой и трогательные, но иногда терпят неудачу, иногда оказываются в смешной ситуации, иногда ведут себя как расшалившиеся мальчишки. "И вроде бы и генералы суровые, и строго командуют, в общем, ведут себя как настоящие военные... но ни одно стихотворение нельзя читать без улыбки", - рассказывают в "Самокате".', '“Generals” is a witty poetry collection by Artur Givargizov with illustrations by Maxim Pokalev. Real generals star in every poem—on duty, at a parade, fishing, in a hospital, at a soccer match, or strolling with their granddaughters. Although stern and fond of giving commands, these lovable high-ranking officers stumble into absurd situations and act just like mischievous boys, making it impossible to read a single verse without a smile.', '„Generali” je duhovita zbirka poezije Artura Givargizova sa ilustracijama Maksima Pokaljova. Pravi generali su junaci svake pjesme — na dužnosti, paradi, pecanju, u bolnici, na fudbalskoj utakmici ili u šetnji sa unukom. Iako strogi i naviknuti na naređivanje, ovi visoki oficiri često upadaju u komične situacije i ponašaju se poput nestašnih dječaka, pa je nemoguće pročitati ijednu pjesmu bez osmijeha.', 'Оказывается, даже самые суровые генералы с большими звёздами на погонах на рыбалке или футболе превращаются в озорных мальчишек — приготовьтесь хихикать на каждой странице!', 'Turns out even the sternest decorated generals turn into playful, mischievous boys when they go fishing or play soccer—prepare to giggle on every page!', 'Ispostavlja se da se čak i najstroži generali sa velikim činovima na pecanju ili fudbalu pretvaraju u nestašne dječake — pripremite se za osmijeh na svakoj stranici!', '/covers/DP-0919.webp', '#5d704d', 'nonfiction', 'ru', 'available', 'младшего и среднего школьного возраста', '["funny","real"]', '["poetry","humor","generals","childhood","laughter"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('главные-роли-для-оли-920', 'DP-0920', 'Главные роли для Оли', 'Starring Roles for Olya', 'Glavne uloge za Olju', 'Артур Гиваргизов', 'Arthur Givargizov', 'Artur Givargizov', 'Максим Покалев', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Пятьдесят тысяч поклонников, миллион красных кофт, батоны до Франции, "Битлз" на хамелеоне и трёхметровый пластилиновый памятник!.. Это всё про Олю, всё Оля - хозяйка пятнадцати умных собак и абсолютная чемпионка школы. В Олин день рождения всегда салют. А для вас - художественный альбом со стихами Артура Гиваргизова и рисунками Максима Покалёва, яркий взрывной творческий симбиоз, который украсит домашнюю библиотеку самого взыскательного читателя.', 'Fifty thousand fans, a million red sweaters, baguettes stretching all the way to France, the Beatles on a chameleon, and a three-meter plasticine statue! Meet Olya: proud owner of fifteen brilliant dogs and reigning school champion. Featuring quirky, witty poetry by Arthur Givargizov paired with vibrant artwork by Maxim Pokalyov, this dazzling art book is an explosive celebration of childhood imagination.', 'Pedeset hiljada obožavalaca, milion crvenih džempera, bageti do Francuske, Bitlsi na kameleonu i trometarski spomenik od plastelina! Sve je to Olja – vlasnica petnaest pametnih pasa i apsolutna školska šampionka. Ova živopisna umjetnička zbirka stihova Artura Givargizova i ilustracija Maksima Pokaljova donosi pravu eksploziju kreativnosti i mašte.', 'Эксцентричный, искромётный поэтический артбук, где детская фантазия фонтанирует на каждой странице так, что невозможно не улыбнуться!', 'An eccentric, sparkling poetic artbook where boundless childhood imagination bursts from every page with infectious humor!', 'Ekscentrična i urnebesno duhovita poetska slikovnica koja dokazuje da dječja mašta nema baš nikakvih granica!', '/covers/DP-0920.webp', '#d63f35', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny"]', '["poetry","humor","artbook","imagination","school life"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('такие-разные-оли-921', 'DP-0921', 'Такие разные Оли', 'So Many Different Olyas', 'Tako različite Olje', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Максим Покалев', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Да, Оли очень разные. Или это одна Оля очень разная? Лена говорит, что книжка получилась про Лен, Надя - про Надь... В общем, разбирайтесь сами. Для детей младшего школьного возраста.', 'Yes, Olyas are very different. Or is it just one Olya who is so multifaceted? Lena insists this book turned out to be all about Lenas, while Nadya claims it''s about Nadyas... In short, find out for yourself! A delightful collection of witty everyday sketches for primary school readers.', 'Da, Olje su veoma različite. Ili je to zapravo jedna Olja koja je toliko promjenljiva? Lena tvrdi da je knjiga ispala o Lenama, Nađa misli da je o Nađama... Uostalom, procijenite sami! Zbirka duhovitih crtica iz svakodnevnog života za mlađe školarce.', 'Ироничные, лёгкие и невероятно правдивые зарисовки Артура Гиваргизова, в которых каждый ребёнок (даже если его зовут вовсе не Оля) непременно узнает себя!', 'Artur Givargizov''s witty, lighthearted sketches are so spot-on that every kid—even if their name isn''t Olya—will definitely see themselves in them!', 'Vrcave i tople crtice Artura Givargizova u kojima će se svako dijete – čak i ako se uopšte ne zove Olja – sigurno prepoznati!', '/covers/DP-0921.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["short stories","humor","school life","childhood","irony"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('космонавты-922', 'DP-0922', 'Космонавты', 'Cosmonauts', 'Kosmonauti', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Катя Голованова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Жизнь на Земле в 3228 году…много в ней…странного. Написал, а потом подумал: "Когда книжку буду переиздавать в 3238 году, все равно странное станет привычным". За смородиной на Марс летают, физкультура в невесомости… Везет же! Вспоминаю, как я на своей старинной физкультуре из-за земного притяжения не смог прыгнуть на метр пятьдесят... Но вот по коридорам в 3238-м не побегаешь, как сейчас, в ракете коридора нет. Где же лучше, в 3238-м или 2019-м? Да везде хорошо! Правда, когда я разглядываю картинки Кати Головановой, меня это будущее не завораживает!.. Можно в него переместиться не навсегда, этим-то и хороши книжки. Садишься на ракету, нарисованную на обложке, и : "Поехали!"', 'Life in the year 3228 is full of oddities: weekend trips to Mars for blackcurrants, gym class in zero gravity, and absolutely no school hallways to sprint through inside a rocket ship. Artur Givargizov invites curious readers to hop into a whimsical rocket and test-drive the distant future.', 'Život 3228. godine pun je neobičnosti: vikendom se leti na Mars po ribizle, časovi fizičkog se drže u bestežinskom stanju, a u raketi nema školskih hodnika za jurnjavu. Artur Givargizov poziva mlade čitaoce da uskoče u maštovitu raketu i na kratko istraže daleku budućnost.', 'Запрыгивайте в ракету и летите на Марс за смородиной — с Гиваргизовым будущее всегда веселое, абсурдное и очень уютное!', 'Hop into the rocket and head to Mars for some berries — with Givargizov, the future is wonderfully absurd and delightfully cozy!', 'Uskočite u raketu i poletite na Mars po ribizle — sa Givargizovom je budućnost nevjerovatno duhovita i beskrajno topla!', '/covers/DP-0922.webp', '#2b3a67', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","adventure"]', '["space","future","humor","rockets","sci-fi"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('энциклопедия-с-бабочкой-и-бара-923', 'DP-0923', 'Энциклопедия с бабочкой и барабаном', 'Encyclopedia with a Butterfly and a Drum', 'Enciklopedija sa leptirom i bubnjem', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Максим Покалев', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Может быть, благодаря нашей не очень серьёзной, но правдивой энциклопедии хотя бы 4999 читателей станут не очень серьёзными, но настоящими энциклопедистами? А что, всё может быть!', 'Who says knowledge has to be solemn? Through this slightly whimsical, delightfully tongue-in-cheek yet truthful encyclopedia, readers just might discover that true encyclopedists are curious thinkers who love a hearty laugh.', 'Možda će, zahvaljujući ovoj ne baš preozbiljnoj, ali istinitoj enciklopediji, makar 4999 čitalaca postati ne sasvim ozbiljni, ali pravi enciklopedisti? Zašto da ne, sve je moguće!', 'Остроумные и парадоксальные заметки Артура Гиваргизова превратят в увлечённого исследователя даже самого заядлого озорника.', 'Witty, paradoxical, and delightfully funny entries from Artur Givargizov that turn even the most restless daydreamer into a passionate young scholar.', 'Duhovite i šarmantne crtice Artura Givargizova koje će i najvećeg šaljivdžiju pretvoriti u radoznalog mladog istraživača.', '/covers/DP-0923.webp', '#e26d36', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["encyclopedia","humor","curiosities","witty"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('история-государства-российског-924', 'DP-0924', 'История государства российского в отрывках из школьных сочинений', 'The History of the Russian State in Excerpts from School Essays', 'Istorija ruske države u odlomcima iz školskih sastava', 'Леонид Каминский', 'Leonid Kaminsky', 'Leonid Kaminski', '', 'Детское время', NULL, NULL, 6, 16, 'middle', 'Книга петербургского художника и писателя, знаменитого Учителя смеха Леонида Каминского собрана из многочисленных "ляпов", "смешных ашыпок" и несуразностей, которые юные читатели более двух десятков лет присылали ему в редакцию всероссийского журнала "Костёр". Эти нелепые отрывки из сочинений и ответы у доски составили богатейшую, уникальную коллекцию - настоящую энциклопедию школьного юмора.', 'This hilarious book by renowned artist, writer, and beloved "Teacher of Laughter" Leonid Kaminsky is a treasure trove of real school bloopers, funny blunders, and absurd slips of the pen. For more than two decades, young readers mailed their funniest mistakes and blackboard blunders to the famous children''s magazine "Kostyor," creating an unforgettable encyclopedia of genuine schoolyard humor.', 'Ova urnebesna knjiga čuvenog umjetnika, pisca i voljenog „učitelja smijeha“ Leonida Kaminskog riznica je pravih školskih bisera, smiješnih grešaka i nespretnih izjava. Više od dvije decenije mladi čitaoci su slali svoje najsmješnije lapsuse iz pismenih zadataka i odgovora pred tablom redakciji časopisa „Kostjor“, stvorivši pravu enciklopediju školskog humora.', 'Приготовьтесь хохотать до слёз над самыми невероятными и искренними историческими перлами из школьных тетрадок!', 'Get ready to laugh until your stomach hurts at the most brilliant and accidental historical gems straight from real school notebooks!', 'Spremite se za smijeh do suza uz najnevjerovatnije i najiskrenije istorijske bisere iz đačkih svesaka!', '/covers/DP-0924.webp', '#d66827', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["school humor","history","bloopers","essays","laughter"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('здравствуй-лошадь--925', 'DP-0925', 'Здравствуй, лошадь!', 'Hello, Horse!', 'Zdravo, konju!', 'Ася Кравченко', 'Asya Kravchenko', 'Asja Kravčenko', 'Алена Кудревич', 'Дети ОГИ', NULL, NULL, 6, 16, 'middle', 'Обыкновенные истории про лошадь по имени Кабачок, ее друзей и знакомых, и немножко про людей. Для младшего школьного возраста.', 'Heartwarming and gently humorous everyday tales about a horse named Zucchini, his animal friends and acquaintances, and just a little bit about people.', 'Tople i blago duhovite svakodnevne priče o konju po imenu Tikvica, njegovim prijateljima, poznanicima i pomalo o ljudima.', 'Уютные и мудрые истории о коне по кличке Кабачок, который смотрит на мир с доброй улыбкой и лошадиным благородством.', 'Meet Zucchini the horse, whose quiet wisdom and funny barnyard adventures will charm animal lovers of any age.', 'Upoznajte konja Tikvicu čija će blaga mudrost i zabavne zgode osvojiti srce svakog ljubitelja životinja.', '/covers/DP-0925.webp', '#9c6644', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["animals","friends","funny"]', '["horses","friendship","short stories","humor","animals"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-старого-дома-926', 'DP-0926', 'Сказки старого дома', 'Tales of the Old House', 'Bajke stare kuće', 'Ася Кравченко', 'Asya Kravchenko', 'Asja Kravčenko', '', 'Дети ОГИ', NULL, NULL, 6, 16, 'middle', 'Взрослым всегда некогда, и Ташке приходится со всем справляться самой: пристраивать в хорошие руки крокодила, заканчивать папину статью, устраивать чужую свадьбу. Но с чем никак ей не справиться - дом вот-вот снесут и надо переезжать.', 'Grown-ups are always busy, so young Tashka has to handle life by herself: find a good home for a crocodile, finish her dad''s newspaper article, and even organize someone else''s wedding. But there''s one heartbreak she can''t easily fix—their beloved old house is scheduled for demolition, and moving day is fast approaching.', 'Odrasli nikada nemaju vremena, pa Taška mora sve sama: da udomi krokodila u dobre ruke, završi tatin novinski članak i pripremi tuđe vjenčanje. Ipak, sa jednom stvari nikako ne može da izađe na kraj — njihovu dragu staru kuću uskoro ruše i selidba je neizbježna.', 'Трогательная, смешная и чуточку щемящая повесть о взрослении, старых стенах и о том, как спасти крокодила, пока взрослые заняты делом.', 'A wonderfully touching and funny story about growing up, saving stray crocodiles, and saying goodbye to beloved old walls.', 'Dirljiva i duhovita priča o odrastanju, starim zidovima punim uspomena i spasavanju krokodila dok su odrasli previše zauzeti.', '/covers/DP-0926.webp', '#a85832', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["real","funny","friends"]', '["family","growing up","moving","crocodile","childhood"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('укротитель-сиреневых-бегемотов-927', 'DP-0927', 'Укротитель сиреневых бегемотов', 'The Tamer of Lilac Hippos', 'Krotitelj ljubičastih nilskih konja', 'Сергей Георгиев', 'Sergey Georgiev', 'Sergej Georgijev', '', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Краткость, точность, афористичность – отличительные черты прозы Сергея Георгиева. Его добрый юмор и наблюдения за жизнью и взрослением маленьких людей в сочетании с неповторимой нежной манерой художника-иллюстратора Елены Блиновой увидели свет в сборнике рассказов «Укротитель сиреневых бегемотов». Здесь герои говорят на бегемотском языке, подают сигналы марсианским летающим тарелкам и осваивают маленькие домашние хитрости с волшебными словами, музыкой и заклинаниями.', 'Brevity, precision, and wit are the hallmarks of Sergey Georgiev’s prose. Combined with Elena Blinova''s tender illustrations, this delightful collection captures the gentle humor of childhood. Here, curious youngsters learn the secret Hippo language, signal Martian flying saucers, and master everyday tricks with magic spells, music, and imagination.', 'Kratkoća, preciznost i aforističnost odlike su proze Sergeja Georgijeva. Njegov topli humor i zapažanja o odrastanju malih ljudi, u spoju sa nježnim ilustracijama Jelene Blinove, oživljavaju u ovoj zbirci priča. Ovdje junaci govore nilskokonjskim jezikom, šalju signale marsovskim letećim tanjirima i otkrivaju male kućne čarolije uz muziku i maštu.', 'Идеальные короткие и уморительные истории о детстве, где запросто можно заговорить с бегемотом и передать привет марсианам!', 'Delightfully witty, bite-sized stories where chatting in Hippo language and signaling alien saucers are just everyday parts of growing up!', 'Predivne, duhovite i kratke priče o djetinjstvu u kojima je sasvim normalno pričati nilskokonjski i mahati Marsovcima!', '/covers/DP-0927.webp', '#8e6ea8', 'nonfiction', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["funny","magic","real"]', '["short stories","humor","childhood","imagination","hippos"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('простодушный-ганс-928', 'DP-0928', 'Простодушный Ганс', 'Simple-Hearted Hans', 'Prostodušni Hans', 'Сергей Георгиев', 'Sergey Georgiev', 'Sergej Georgijev', 'Саша Новоселова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Испокон веков люди рассказывают детям сказки. Добрые и забавные, страшные и не очень… А ведь сказки не только в старину рождались. Знаменитый детский писатель Сергей Георгиев сочинил для детей сборник сказок о простодушном Гансе. Сказки не простые: на первый взгляд в них вроде бы о стародавних временах рассказывается, а если вдуматься - то очень даже про нас с вами. Про трудолюбивых крестьян и злых разбойников. Про чванливого маркграфа и обидчивого дракона. Про метлу-голубушку, которая сама собой метёт. Про снежную печку, в которой пекутся ледяные оладушки. И про то, как Ганс нашёл чудесный горшочек, который чем прикажешь, тем и наполнится… А иллюстрации к этим сказкам, созданные художницей Александрой Новосёловой, словно сошли со страниц средневековых манускриптов. И трудно поверить, что книга эта родилась не под сводами старинных мастерских, а в наше время, в издательстве "Эгмонт". Книга продолжает серию "Город мастеров", и сразу ясно - это воистину творение настоящих мастеров своего дела.', 'Fairy tales aren''t just relics of the distant past—acclaimed children''s author Sergey Georgiev proves it with this captivating collection of stories about simple-hearted Hans. Though set in an era of hardworking peasants, wicked bandits, arrogant margraves, and easily offended dragons, these tales mirror our modern world with sharp wit and gentle warmth. Discover an enchanted broom that sweeps by itself, a snowy oven that bakes icy pancakes, and a miraculous pot that fills with whatever you wish. Illustrated by Aleksandra Novosyolova in the intricate style of medieval illuminated manuscripts, this book feels like a treasure unearthed from an ancient artisan guild.', 'Bajke se nijesu rađale samo u drevnim vremenima—čuveni dječji pisac Sergej Georgijev stvorio je novu zbirku priča o prostodušnom Hansu. Iako na prvi pogled govore o starim danima, marljivim seljacima, zlim razbojnicima, uobraženom markgrofu i osjetljivom zmaju, ove priče zapravo govore o svima nama. Upoznajte čarobnu metlu koja sama mete, sniježnu peć u kojoj se peku ledene palačinke i čudesni lončić koji ispunjava želje. Uz raskošne ilustracije Aleksandre Novosjolove nalik srednjovjekovnim rukopisima, ova knjiga donosi duh pravih majstora pripovijedanja.', 'Мудрые, остроумные и невероятно уютные сказки о старых временах, в которых так легко узнать нас сегодняшних!', 'Wise, witty, and heartwarming fairy tales where ancient dragons and magic pots reflect our own everyday quirks!', 'Mudre, duhovite i tople bajke o starim vremenima u kojima ćete lako prepoznati naš današnji svijet!', '/covers/DP-0928.webp', '#a35c36', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["magic","funny","adventure"]', '["fairy tales","humor","medieval","dragons","magic"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-про-королей-929', 'DP-0929', 'Сказки про королей', 'Tales of Kings', 'Bajke o kraljevima', 'Сергей Седов', 'Sergey Sedov', 'Sergej Sedov', 'Надя Суворова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Волнуешься с первых строк: за подданных, за лошадь (упадёт ведь), за короля… Не надо волноваться, в сказках всё хорошо заканчивается. Ещё есть про рассеянного, стеснительного, трусливого… Сказки про королей! Про очень разных. Разных-преразных. Ужасно разных. А вы думали, все короли одинаковые? Вот прочтёте эту книжку и поймёте, как вы были не правы!', 'You worry right from the opening lines: for the loyal subjects, for the horse (it will surely stumble!), for the king himself... No need to panic, fairytales always end well! Meet monarchs who are absent-minded, dreadfully shy, or hilariously cowardly. Did you really think all kings were cut from the same royal cloth? This witty collection will prove you delightfully wrong!', 'Brinete od prvih redova: za podanike, za konja (pašće, sigurno!), za samog kralja... Nema potrebe za brigom, u bajkama se sve dobro završava! Upoznajte kraljeve koji su rasejani, stidljivi, plašljivi i beskrajno neobični. Jeste li mislili da su svi kraljevi isti? Ova duhovita zbirka će vam dokazati koliko ste pogriješili!', 'Искромётные и абсурдные истории о венценосных особах, которые докажут: быть королём — это уморительно сложно!', 'Witty, delightfully absurd tales of royal highnesses that prove wearing a crown can be hilariously complicated!', 'Duhovite i apsurdne priče o krunisanim glavama koje dokazuju da je kraljevski život urnebesno komplikovan!', '/covers/DP-0929.webp', '#d99b26', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","magic"]', '["kings","fairytales","humor","short stories","royalty"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-про-мам-930', 'DP-0930', 'Сказки про мам', 'Tales About Moms', 'Bajke o mamama', 'Сергей Седов', 'Sergey Sedov', 'Sergej Sedov', 'Таня Кормер', 'Самокат', NULL, NULL, 6, 16, 'middle', '"Сказки про мам" Сергея Седова поражают своей невероятной современностью, а их неподдельная вневременная искренность заставит сопереживать любого - будь он сам хоть трижды мамой... И особенно замечательно, что мамы в сказках Сергея Седова очень разные - точно как в жизни! И как в жизни, у них есть одна общая черта - они бесконечно любят своих детей. А так как нет человека в мире, который появился бы на свет без участия мамы, то сказки эти будут интересны всем: маленьким и взрослым, умным и глупым, бедным и богатым, добрым и злым...', 'Sergey Sedov''s ''Tales About Moms'' captivates readers with its modern flair and timeless sincerity that touches everyone, even those who are mothers three times over. The mothers in these tales are wonderfully different—just like in real life—ranging from brave to quirky, yet united by one thing: boundless love for their children. Since everyone has a mother, these witty, poignant stories speak to readers of all ages.', '„Bajke o mamama“ Sergeja Sedova osvajaju nevjerovatnom savremenošću i iskrenošću koja nikoga ne ostavlja ravnodušnim. Mame u ovim bajkama su potpuno različite — baš kao i u stvarnom životu — ali dijele jednu veliku zajedničku osobinu: bezgranično vole svoju djecu. A pošto niko na svijetu nije rođen bez majke, ove duhovite i tople priče biće podjednako zanimljive i djeci i odraslima.', 'Трогательные, остроумные и слегка абсурдные истории о том, что мамы бывают какими угодно, но любят своих детей одинаково преданно и беззаветно.', 'Witty, tender, and playfully absurd tales celebrating the fact that moms come in every shape and temperament, but their love is always unconditional.', 'Dirljive, duhovite i pomalo otkačene priče koje podsjećaju da su mame raznolike, ali da svaka beskrajno voli svoje dijete.', '/covers/DP-0930.webp', '#d94a4a', 'nonfiction', 'ru', 'available', 'Для младшего и среднего школьного возраста.', '["funny","magic","real"]', '["mothers","family","fairy tales","humor","short stories"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-931', 'DP-0931', 'Сказки', 'Fairy Tales', 'Bajke', 'Сергей Седов', 'Sergey Sedov', 'Sergej Sedov', 'Катя Силина', 'Жук', NULL, NULL, 6, 16, 'middle', 'В жизни есть место чуду, и один из самых известных собирателей таких чудес - Сергей Седов. Сказки его полны доброго вымысла, за которым угадывается реальность. Читатель узнаёт себя и своих друзей в героях этих сказок - в королях и волшебниках, рыбаках и дураках. Привычный мир открывается новыми гранями, в нём проявляется тонкое волшебство и весёлое чудачество, и читатель начинает уже смотреть на происходящее с ним мудрыми глазами сказочника.', 'There is always room for a miracle in life, and Sergey Sedov is one of the most famous collectors of such wonders. His tales are full of warm whimsy that mirrors reality. Readers will recognize themselves and their friends in these kings and wizards, fishermen and fools. The familiar world reveals fresh facets, subtle magic, and delightful eccentricities, inviting everyone to see life through the wise, smiling eyes of a storyteller.', 'U životu uvijek ima mjesta za čuda, a Sergej Sedov je jedan od njihovih najpoznatijih sakupljača. Njegove bajke pune su tople mašte iza koje se krije stvarni život. Čitaoci će prepoznati sebe i svoje prijatelje u kraljevima, čarobnjacima, ribarima i šaljivcima. Poznati svijet otkriva se u novim bojama, prožet suptilnom magijom i vedrim luckastim dosjetkama.', 'Ироничные, добрые и совершенно непредсказуемые сказки, в героях которых легко узнать соседа, друга или самого себя!', 'Ironic, warm, and wonderfully unpredictable tales where you’ll easily spot your neighbor, your best friend, or even yourself!', 'Ironične, tople i potpuno nepredvidive bajke u čijim ćete likovima lako prepoznati komšiju, prijatelja ili sebe!', '/covers/DP-0931.webp', '#d97736', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["magic","funny","real"]', '["fairy tales","humor","modern tales","short stories"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('переход-932', 'DP-0932', 'Переход', 'The Crossing', 'Prelaz', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Виктория Семыкина', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Полгода назад Артур Гиваргизов и Виктория Семыкина сидели в кафе, обсуждали будущую книжку. Артур: Ну, если вкратце... Дима любит бродить по городу. По Кибальчича, Касаткина... Через дорогу Переходит осторожно, только на зелёный. Однажды светофор сломался, и Дима день стоял, два, три, четыре, пять, шесть... Родители даже стали волноваться. Виктория: Да, я несколько раз видела этого мальчика на Кибальчича! (Рисует Димин портрет, показывает Артуру.) Он? Артур (радостно): Он! Он! Димины родители (Виктории): И нас нарисуйте, пожалуйста. Автоинспектор: И меня. Водитель автобуса: И меня. Пассажиры и прохожие: И нас. Так Виктория Семыкина нарисовала всю книжку', 'Six months ago, writer Artur Givargizov and artist Victoria Semykina met in a cafe to invent a story. It begins with Dima, a boy who loves strolling the city and only ever crosses on green. But when a traffic light breaks down, exceptionally obedient Dima waits for days on end! A witty urban tale brought vividly to life with portraits of Dima, traffic wardens, bus drivers, and intrigued pedestrians.', 'Prije pola godine pisac Artur Givargizov i ilustratorka Viktorija Semikina sjedjeli su u kafiću smišljajući novu slikovnicu. Priča prati Dima, dječaka koji obožava šetnje gradom i ulicu prelazi isključivo na zeleno svjetlo. Šta se dogodi kada se semafor pokvari, a besprekorno poslušan dječak ostane da čeka danima? Duhovita gradska priča o pravilima i prolaznicima, puna vedrine i šarma.', 'Невероятно смешная городская история о том, к чему может привести абсолютное послушание у светофора, украшенная живыми иллюстрациями Виктории Семыкиной!', 'A delightfully absurd urban story about following the rules a bit too literally, illustrated with warm wit by Victoria Semykina!', 'Neodoljivo duhovita gradska priča o tome šta se desi kada pravila na semaforu shvatite previše doslovno!', '/covers/DP-0932.webp', '#2a7f62', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["traffic rules","city life","humor","pedestrians"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('3-минуты-до-хорошего-настроени-933', 'DP-0933', '3 минуты до хорошего настроения', '3 Minutes to a Good Mood', '3 minuta do dobrog raspoloženja', 'Наталья Евдокимова', 'Natalya Evdokimova', 'Natalija Jevdokimova', 'Катя Голованова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Три минуты - примерно столько нужно, чтобы съесть бутерброд или прочитать один рассказ из этой книги. И читать лучше вслух. А лучше в громкоговоритель. Тогда хорошее настроение настанет сразу у многих людей! Только, читая вслух, будьте готовы, что выстроится очередь: нажать вам на нос. Вдруг у него звон мелодичный - прямо как у Васьки из одного рассказа. К Ваське длинная очередь выстраивалась.', 'Three minutes is roughly the time it takes to eat a sandwich or read one story from this book. And it''s best read out loud—or better yet, through a megaphone! That way, lots of people will instantly catch the good mood. Just beware: if you read aloud, people might line up to press your nose to see if it chimes melodiously, just like Vaska''s does in one of the tales.', 'Tri minuta je otprilike dovoljno da pojedete sendvič ili pročitate jednu priču iz ove knjige. A najbolje ih je čitati naglas — ili još bolje, preko megafona! Tako će se dobro raspoloženje odmah proširiti svuda unaokolo. Samo se pripremite: dok čitate, mogao bi se stvoriti čitav red da vam pritisne nos, baš kao Vaski iz jedne priče čiji je nos zvonio predivnom melodijom.', 'Идеальное карманное средство от хандры: всего три минуты на один забавный рассказ — и улыбка гарантирована на весь день!', 'The ultimate pocket remedy for gloomy days: just three minutes per story, and you''re practically guaranteed to start grinning.', 'Savršen džepni lijek protiv dosade: samo tri minuta po priči i osmijeh vam je zagarantovan za cijeli dan!', '/covers/DP-0933.webp', '#f2994a', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["short stories","humor","laughter","read aloud","childhood"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вкусный-юра-934', 'DP-0934', 'Вкусный Юра', 'Delicious Yura', 'Ukusni Jura', 'Михаил Есеновский', 'Mikhail Yesenovsky', 'Mihail Jesenovski', 'Юрий Скоморохов', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Михаил Есеновский снова написал про Юру. Того, который сначала всего боялся. Точнее, ничего не боялся (в книге "Главный шпионский вопрос"). Который потом болел. Вернее, не болел, а дружил со своими заболеваниями (в книге "Ангина Марина"). Теперь Юра ест. То есть, нет, это его едят. Он же вкусный. Ест лиса, ест волк, ест медведь. И носорог, и бегемот с крокодилом. Даже морская свинка. Даже тушканчик. Как же так? Ведь Юра один, а зверушек много. Ерунда, ничего страшного, хорошего человека на всех хватит.', 'Mikhail Yesenovsky is back with another wonderfully surreal tale about Yura. This time, Yura isn''t just eating—he is being eaten! After all, he is simply delicious. A fox takes a bite, followed by a wolf, a bear, a rhino, and even a tiny guinea pig. How can that be when Yura is just one boy and the animals are many? No worries at all: there is always plenty of a genuinely good person to go around.', 'Mihail Jesenovski se vraća sa još jednom luckastom pričom o dječaku Juri. Ovoga puta Jura ne jede, već njega jedu — jer je neodoljivo ukusan! Grickaju ga lisica, vuk, medvjed, nosorog, pa čak i morsko prase. Kako je to moguće kad je Jura samo jedan, a životinja je mnogo? Nema brige: dobrog čovjeka uvijek ima sasvim dovoljno za sve.', 'Осторожно: этот сборник абсурдных и уморительных историй вызовет неудержимые приступы смеха на всю библиотеку!', 'Warning: this delightfully absurd and topsy-turvy tale might cause uncontrollable giggles across the entire library!', 'Upozorenje: ova luckasta i urnebesna priča o neobičnom dječaku izaziva nekontrolisane napade smijeha!', '/covers/DP-0934.webp', '#d95d39', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","animals"]', '["absurd humor","funny stories","animals","imagination","short stories"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('не-поверишь--935', 'DP-0935', 'Не поверишь!', 'You Won''t Believe It!', 'Nećeš vjerovati!', 'Ирина Зартайская', 'Irina Zartayskaya', 'Irina Zartajska', 'Владислав Суровегин', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Не поверите! Но квадратура круга и задача о перемещении дивана - далеко не самые важные вопросы, издревле волнующие лучшие умы человечества! Чем накормить лужу, как лучше бегать - за дворником или перед кошкой, на каком боку лежать, когда тебе грустно, на какую ногу надо надевать красный носок, чем опасна профессия археолога, можно ли влюбиться зимой, что общего между супом и шоколадом и, наконец, где живёт мальчик Тим? Если хотя бы один из этих вопросов поставил вас в тупик, эта книга для вас, так как вы просто обязаны хотя бы раз в жизни оказаться в тупике! Вы, конечно, не поверите, но там бывает ужасно интересно - особенно если в этот тупик вас поставят Ирина Зартайская и Владислав Суровегин!', 'You won’t believe it, but squaring the circle and moving a couch are hardly the most crucial dilemmas puzzling humanity''s greatest minds! What should you feed a puddle? Which side should you lie on when you''re feeling sad? Which foot gets the red sock, and can you really fall in love in the dead of winter? If any of these questions catch you off guard, this witty, wonderfully quirky book is made just for you.', 'Nećete vjerovati, ali rješavanje kvadrature kruga i pomjeranje kauča uopšte nijesu najvažnija pitanja koja muče čovječanstvo! Čime nahraniti baru, na kom boku treba ležati kad si tužan, na koju nogu ide crvena čarapa i može li se zaljubiti usred zime? Ako vas je makar jedno od ovih pitanja zbunilo, ova duhovita i neobična knjiga je baš za vas — jer naći se u čudu nikad nije bilo ovako zabavno!', 'Сборник уморительных и философских жизненных вопросов, которые помогут взглянуть на мир под самым неожиданным углом!', 'A collection of hilarious and delightfully philosophical everyday dilemmas that turn ordinary logic completely upside down!', 'Zbirka urnebesnih i neočekivano mudrih pitanja koja će vam potpuno preokrenuti svakodnevnu logiku naglavačke!', '/covers/DP-0935.webp', '#e87a38', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["humor","philosophy","curiosity","questions","creativity"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-будто-936', 'DP-0936', 'Как будто', 'As If', 'Kao da', 'Дина Бурачевская', 'Dina Burachevskaya', 'Dina Buračevska', 'Анна Кольцова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Дина Бурачевская очень любит сочинять детские стихи лёжа в кровати, обложившись подушками, а рядом чтоб стояла тарелочка с пряниками и конфетами, а в ногах чтоб урчал любимый кот Лунтик. И ещё она любит выступать перед детьми, а когда она выступает, то машет руками, краснеет и даже подпрыгивает, но детям всё равно это очень нравится. Любимый цветок Дины Бурачевской - это одуванчик, так что если придёте на её выступление, то обязательно принесите букет белых одуванчиков, главное, чтоб в этот день погода была не очень ветреной...', 'Dina Burachevskaya loves writing children''s poems while tucked in bed surrounded by cozy pillows, with a plate of gingerbread and sweets nearby, and her purring cat Luntik at her feet. She also loves performing for kids, gesturing wildly, blushing, and bouncing up and down—and young listeners simply adore it! Dina''s favorite flower is the dandelion, so if you ever come to her poetry reading, be sure to bring a fluffy bouquet, provided it''s not too windy...', 'Dina Buračevska obožava da piše pjesme za djecu ležeći u krevetu, ušuškana jastucima, uz tanjirić pun medenjaka i slatkiša, dok joj mačak Luntik prede kraj nogu. Takođe voli da nastupa pred djecom — dok recituje, ona maše rukama, crveni i poskakuje od radosti, a djeca to jednostavno obožavaju! Dinin omiljeni cvijet je maslačak, pa ako ikada svratite na njen nastup, ponesite joj buket paperjastih bijelih maslačaka, samo pazite da taj dan ne duva vjetar...', 'Задорные, тёплые и озорные стихи, которые лучше всего читать с чашкой какао и котом под боком!', 'Bouncy, warm, and mischievous poems best enjoyed with a warm cup of cocoa and a purring cat nearby!', 'Razigrani, topli i nestašni stihovi u kojima se najbolje uživa uz šolju kakaa i mačku koja prede pored vas!', '/covers/DP-0936.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["poetry","humor","childhood","imagination","rhymes"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прическа-номер-один-937', 'DP-0937', 'Прическа номер один', 'Hairstyle Number One', 'Frizura broj jedan', 'Михаил Есеновский', 'Mikhail Yesenovsky', 'Mihail Jesenovski', 'Маша Згода', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'В этой книге Михаила Есеновского - стихи про всё. И про причёску номер один, и про 303 тысячи 33 волосинки, и про 400 пятен на Солнце. Здесь курица пытается взлететь с палубы авианосца, а мыши - улететь на Луну в ракете. Черепаха копит деньги на ремонт панциря, а рыбка - на аквариум с джакузи. Лев работает парикмахером, а моль - гардеробщицей в Большом театре. И всё это весело, энергично, под музыку. Крот танцует фокстрот, козёл - рок-н-ролл, а муравьи - танец маленьких лебедей. Ну очень маленьких.', 'This playful poetry collection by Mikhail Yesenovsky covers just about everything: Hairstyle Number One, 303,033 hairs, and 400 sunspots. Inside, a chicken attempts to launch from an aircraft carrier, mice rocket to the Moon, a turtle saves up to repair its shell, and a goldfish dreams of a jacuzzi. With barber lions, coat-checking moths, and dancing ants, this rhythmic book is pure whirlwind fun.', 'U ovoj zbirci razigranih pjesama Mihaila Jesenovskog naći ćete stihove o svemu i svačemu: o frizuri broj jedan, 303.033 vlasi i 400 pjega na Suncu. Ovdje kokoška pokušava da poleti s nosača aviona, miševi putuju na Mjesec, kornjača štedi za popravku oklopa, a lav radi kao frizer. Uz mrave koji plešu balet, ova zbirka donosi pravi vatromet smijeha i ritma.', 'Искромётные, задорные и невероятно смешные стихи, где даже муравьи отплясывают лебединый балет, а лев стрижёт клиентов с непревзойдённым шиком!', 'A riotously funny poetic whirlwind where ants dance the ballet, a lion works as a stylish barber, and every page bursts with pure joy!', 'Prava eksplozija duhovitih i ritmičnih stihova u kojima mravi plešu balet, a lav radi kao najbolji frizer na svijetu!', '/covers/DP-0937.webp', '#f39c12', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","animals"]', '["стихи","юмор","poetry","animals","humor"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бублик-для-гуманоида-938', 'DP-0938', 'Бублик для гуманоида', 'A Bagel for a Humanoid', 'Đevrek za humanoida', 'Валентина Дегтева', 'Valentina Degteva', 'Valentina Degtjeva', 'Надя Суворова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Никогда не заглядывайте в водопроводные люки! Вот героиня рассказов Валентины Дегтевой - девочка по имени Нинка - заглянула, и что? Обнаружила там заколдованного принца. Возись с ним ещё, расколдовывай… А Нинке давно домой пора, к маме! Смешные и добрые, весёлые и поучительные - эти истории полны удивительных неожиданностей и забавных приключений. "Атмосфера смешений и превращений - возвышенного и смешного, запутанного и явного,понятного и перевернутого - и есть главная особенность книги Валентины Дегтевой…', 'Never peek into manholes! When Ninka, the spunky heroine of Valentina Degteva''s tales, glanced inside, what did she find? An enchanted prince, of all things! Now she has to figure out how to break the spell, even though it is way past time to be home for dinner. Packed with quirky humor, unexpected surprises, and marvelous mischief, these playful stories turn everyday reality completely upside down.', 'Nikada ne zavirujte u kanalizacione šahtove! Ninka, radoznala junakinja priča Valentine Degtjeve, upravo je to uradila i šta je našla? Začaranog princa! Sad još mora i da skida čini sa njega, a odavno je trebalo da bude kod kuće za večeru. Pune vragolastog humora, neočekivanih obrta i lude zabave, ove priče okreću svakodnevicu naglavačke na najsmješniji mogući način.', 'Осторожно: открыв эту книгу, вы рискуете встретить в обычном люке заколдованного принца, а в космосе — инопланетного любителя свежей выпечки!', 'Warning: crack this book open and you might just discover an enchanted prince inside a manhole and an alien craving bakery treats!', 'Upozorenje: ako otvorite ovu knjigu, rizikujete da u običnom šahtu pronađete začaranog princa, a među zvijezdama vanzemaljca željnog svježeg đevreka!', '/covers/DP-0938.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","magic","adventure"]', '["short stories","humor","fairy tales","quirky adventures","imagination"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('из-переписки-с-коровой-939', 'DP-0939', 'Из переписки с коровой', 'From Correspondence with a Cow', 'Iz prepiske sa kravom', 'Тим Собакин', 'Tim Sobakin', 'Tim Sobakin', 'Зина Сурова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Чудесные стихи Тима Собакина знает и любит уже не одно поколение читателей. На этот раз автор рассказывает о том, как он подружился… с коровой. Да-да, с самой настоящей коровой! Они обмениваются письмами: корова рассказывает своему новому другу о жизни в деревне, автор – о том, как работает вагоновожатым. В этой непринуждённой беседе в полной мере раскрывается яркий талант писателя и искромётное чувство юмора.', 'Generations of readers have cherished Tim Sobakin''s marvelous verses. This time, the author shares the tale of how he befriended... an actual cow! They exchange playful letters: the cow writes about cozy country life, while the author shares his adventures as a city tram driver. Full of sparkling wit and effortless charm, their correspondence reveals Sobakin''s signature humor at its finest.', 'Divne stihove Tima Sobakina voli već nekoliko generacija čitalaca. Ovoga puta pisac priča kako se sprijateljio... sa pravom pravcatom kravom! Oni razmjenjuju pisma: krava opisuje seoski život, dok joj autor priča o svom poslu vozača tramvaja. U ovom opuštenom razgovoru zablistaće autorov razigrani humor i neizmjerna toplina.', 'А вам когда-нибудь писала настоящая корова? Открывайте скорее — вас ждёт море душевного мычания, смеха и историй про трамваи!', 'Have you ever received mail from a real cow? Open this up for heartfelt moos, clever laughs, and tramway adventures!', 'Da li vam je ikada pisala prava krava? Otvorite ovu knjigu za pregršt smijeha, seoskih zgoda i najneobičnijeg prijateljstva!', '/covers/DP-0939.webp', '#529b53', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","animals","friends"]', '["letters","poetry","cows","humor","friendship"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дрессировщик-бутербродов-940', 'DP-0940', 'Дрессировщик бутербродов', 'The Sandwich Tamer', 'Krotitelj sendviča', 'Сергей Георгиев', 'Sergey Georgiev', 'Sergej Georgijev', 'Катя Силина', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Сергей Георгиев - мастер прозаической миниатюры. В "три абзаца" его сказки или рассказа умещается все, что должно быть в хорошей - "большой" - книге: правдивость и наблюдательность, доброта и юмор, а еще - снисходительность, и много житейской мудрости', 'Sergey Georgiev is a master of miniature prose. Within just three paragraphs, his short tales capture everything that makes a great book: keen observation, warmth, gentle humor, and plenty of everyday wisdom.', 'Sergej Georgijev je pravi majstor proznih minijatura. U samo tri pasusa svake priče staje sve što čini veliku knjigu: oštro oko, toplina, nježan humor i pregršt životne mudrosti.', 'Искромётные и добрые мини-истории, которые докажут, что даже самый своенравный бутерброд можно приручить с помощью улыбки!', 'Sparkly, heartwarming flash fiction proving that with a good smile, you can tame even the cheekiest runaway sandwich!', 'Pjenušave i tople mini-priče koje dokazuju da uz malo osmijeha možete ukrotiti čak i najnestašniji sendvič!', '/covers/DP-0940.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["short stories","humor","miniatures","family reading","everyday wisdom"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('новенький-941', 'DP-0941', 'Новенький', 'The New Kid', 'Novi đak', 'Сергей Махотин', 'Sergey Makhotin', 'Sergej Mahotin', 'Ирина Иванова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'В семь лет, как все, я пошёл в школу. Но учился в ней не очень долго. Не потому что меня выгнали. Просто семья переехала в другой дом, и школу пришлось поменять. А заканчивал я уже третью по счёту школу. И хорошо помню ощущение новенького, который вдруг очутился в чужом коллективе. Волнение, тревогу, желание поскорее найти хороших друзей. А ведь этот сборник стихов - тоже Новенький. И тоже, как робкий поначалу школьник, мечтает подружиться с вами, дорогие читатели. Я, Сергей Махотин, и художница этой книжки Ирина Иванова очень надеемся, что так оно и произойдёт.', 'At seven, like everyone else, I started school. But I didn''t stay there long—not because I got expelled, but because my family moved and I had to change schools. By graduation, I was already at my third school. I remember that feeling of being the new kid all too well: the anxiety, the jitters, and the longing to make good friends quickly. This poetry collection is a ''new kid'' too, hoping to make friends with every reader.', 'Sa sedam godina, kao i svi, pošao sam u školu. Ali nisam u njoj dugo ostao — ne zato što su me izbacili, već zato što se porodica preselila i morao sam da promijenim školu. Maturirao sam u svojoj trećoj školi. Dobro se sjećam osjećaja novajlije u nepoznatom razredu: treme, nemira i želje da što prije nađe prave prijatelje. Ova zbirka pjesama je takođe ''novi đak'', koji se nada da će pronaći mjesto u vašem srcu.', 'Трогательные и остроумные стихи о школьных буднях и том самом чувстве, когда впервые входишь в незнакомый класс.', 'Heartfelt and witty poems that capture the exact flutter in your stomach when stepping into a brand-new classroom.', 'Dirljivi i duhoviti stihovi o školskim danima i onom poznatom osjećaju treme kada prvi put zakoračiš u novi razred.', '/covers/DP-0941.webp', '#3b7a99', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["real","friends","funny"]', '["school","poetry","friendship","growing up","childhood"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайный-гонец-942', 'DP-0942', 'Тайный гонец', 'The Secret Messenger', 'Tajni glasnik', 'Марина Бородицкая', 'Marina Boroditskaya', 'Marina Borodickaja', 'Надежда Богуславская', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Марина Бородицкая - автор, который завораживает с первой фразы. Завораживает, облагораживает, завладевает мыслями и чувствами, проникает в сердце, обволакивая, вдохновляя и излечивая кристально-чистыми образами, выверенно-отточенными метафорами, нежностью и глубиной. Будто кто-то из пёстрой разноголосой толпы хватает вдруг за руку и тащит вдоль прилавков, ошеломляющих роскошью', 'Marina Boroditskaya captivates readers from the very first verse. Her crystal-clear imagery, razor-sharp metaphors, tenderness, and soulful depth pull you straight out of the noisy crowd into an astonishingly rich world of poetic wonders.', 'Marina Borodickaja očarava čitaoce već od prvog stiha. Njene kristalno čiste slike, promišljene metafore, nježnost i dubina vuku vas iz šarolike gužve u čudesan i raskošan svijet iskrene poezije.', 'Поэтический билет в мир, где самые точные и трепетные слова находят путь прямиком к сердцу!', 'A poetic ticket to a world where words are chosen with such precision and tenderness they touch your very soul!', 'Pjesnička ulaznica u svijet u kojem najfinije riječi pronalaze direktan put do vašeg srca!', '/covers/DP-0942.webp', '#435075', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["magic","real"]', '["poetry","verses","growing up","emotions","words"]', 1792836322700, 1792845691096);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('послушный-папа-943', 'DP-0943', 'Послушный папа', 'An Obedient Dad', 'Poslušni tata', 'Наталья Евдокимова', 'Natalia Evdokimova', 'Natalija Jevdokimova', 'Елена Станикова', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Наталья Евдокимова - афористичная, тонкая, точная; она подаёт образы своих маленьких героев через призму абсолютного принятия и понимания психологии ребёнка. Она не из тех "писателей", что, подобно герою одного из её рассказов, встретившись с детьми, тушуется и задаёт нелепые вопросы. Евдокимова уверена: ведь маленькому человеку надо-то всего ничего: мира во всём мире, красок акварельных, петушиное перо, воздушный шарик, железную дорогу, горсть гвоздей, лампу накаливания, чашку с отбитой ручкой, рост до потолка и маленькую крысу. И ещё она знает, в чём разница между обычным днём и первым днём каникул; научит, как получше сообщить родителям, что получил двойку, и как заставить папу слушаться - без дисциплины-то никуда!', 'Natalia Evdokimova writes with subtle wit and deep empathy, capturing the inner world of children with genuine warmth and understanding. She knows that kids really don''t ask for much: just world peace, some watercolors, a balloon, a pet rat, and a handful of nails. Inside, you''ll also discover the true magic of the first day of vacation, how best to confess a bad grade to your parents, and how to gently keep your dad well-behaved—after all, family life runs on discipline!', 'Natalija Jevdokimova piše duhovito, toplo i s potpunim razumijevanjem dječje psihologije. Ona tačno zna šta je djetetu zapravo potrebno: mir u svijetu, vodene bojice, balon, pregršt eksera i jedan mali pacov. Otkrijte u čemu je tajna prvog dana raspusta, kako bezbolno saopštiti roditeljima lošu ocjenu i kako privoljeti tatu na poslušnost — jer red se u kući ipak mora znati!', 'Остроумные и бесконечно тёплые истории о том, как устроена детская вселенная и как правильно «воспитывать» любимых взрослых!', 'A delightfully witty and tender look at the secret logic of childhood and the playful art of keeping parents well-behaved!', 'Duhovite i beskrajno tople priče o tajnama dječijeg svijeta i umjetnosti vaspitavanja sopstvenih roditelja!', '/covers/DP-0943.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["family","humor","growing up","short stories","parents"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('все-будет-в-порядке-944', 'DP-0944', 'Все будет в порядке', 'Everything Will Be All Right', 'Sve će biti u redu', 'Валерий Воскобойников', 'Valery Voskoboynikov', 'Valerij Voskobojnikov', '', 'дети ОГИ', NULL, NULL, 6, 16, 'middle', 'Книга Валерия Воскобойникова светлая, смешная и чуть-чуть печальная. Этот доверительный рассказ о приключениях, которые происходят с человеком, когда ему еще не исполнилось одиннадцати лет, в полном грозных опасностей и неожиданных радостей мире, надолго останется в памяти у читателя.', 'Valery Voskoboynikov''s book is bright, funny, and gently touching. This intimate story follows the adventures of a boy who is not yet eleven years old, making sense of a world packed with intimidating challenges and unexpected joys.', 'Knjiga Valerija Voskobojnikova je vedra, duhovita i pomalo sjetna. Ova iskrena priča o avanturama dječaka koji još nema ni jedanaest godina, u svijetu punom neočekivanih opasnosti i radosti, dugo će ostati u sjećanju svakog čitaoca.', 'Трогательная и удивительно светлая книга, напоминающая: какие бы бури ни бушевали вокруг десятилетнего человека, всё обязательно будет хорошо!', 'A tender and genuinely uplifting story showing that no matter how chaotic the world feels to an almost-eleven-year-old, everything really will be just fine.', 'Topla i vedra priča koja podsjeća da će, kakve god oluje pratile desetogodišnjaka, na kraju sve sigurno biti u najboljem redu.', '/covers/DP-0944.webp', '#e29b38', 'nonfiction', 'ru', 'available', 'Для среднего школьного возраста.', '["real","funny","friends"]', '["childhood","growing up","friendship","humor","hope"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('откуда-берутся-дети-945', 'DP-0945', 'Откуда берутся дети', 'Where Do Babies Come From?', 'Odakle dolaze djeca', 'Максим Кронгауз, Мария Бурас', 'Maxim Krongauz, Maria Buras', 'Maksim Krongauz, Marija Buras', 'Алиса Юфа', 'Эгмонт', NULL, NULL, 6, 16, 'middle', 'Мария Бурас и Максим Кронгауз - лингвисты и любят поговорить. Эту любовь они передали своим героям. Братья Петя и Ося постоянно разговаривают: с прохожими и козами, с поэтами и аистами, друг с другом. I Им очень нужно узнать, Откуда берутся дети, чтобы помочь маме, которая... Стоп, это ведь подсказка! В общем, рядом с их домом в деревне был магазин, который попал в Книгу рекордов Гиннесса... стоп... а еще капустное поле, где... стоп... и секретный аистодром, откуда... стоп... а соседская девчонка Женька им всё время то мешала, то помогала... Постепенно и героям, и даже читателям становится ясно: если со всеми разговаривать и ничего не бояться, то всё получится. Для дошкольного и младшего школьного возраста', 'Maria Buras and Maxim Krongauz are linguists who love to chat, and they passed this passion on to their heroes. Brothers Petya and Osya talk endlessly: to passersby, goats, poets, storks, and each other. They urgently need to find out where babies come from to help their mother, who... wait, no spoilers! Along the way, there''s a record-setting village shop, a cabbage patch, a secret stork landing strip, and a neighborhood girl named Zhenya who keeps getting in the way. Step by step, the brothers discover that if you talk to everyone openly, you can solve any mystery.', 'Marija Buras i Maksim Krongauz su lingvisti koji obožavaju razgovor, a tu strast su prenijeli i na svoje junake. Braća Peđa i Osja neprestano pričaju: sa prolaznicima i kozama, sa pjesnicima i rodama, i jedan sa drugim. Hitno moraju da saznaju odakle dolaze bebe kako bi pomogli mami, koja... čekajte, to je tajna! U njihovoj istrazi pomažu im i seoska prodavnica, polje kupusa, tajni aerodrom za rode i radoznala komšinica Ženja. Korak po korak, dječaci uče da se uz iskren razgovor mogu riješiti sve zagonetke.', 'Остроумное и доброе расследование самого волнующего детского вопроса, где капустные грядки и аисты уступают место живой детской смекалке!', 'A witty, heartwarming detective quest tackling childhood''s biggest mystery through charming logic, cabbage patches, and chatty storks!', 'Duhovita i topla avantura u kojoj dva brbljiva brata istražuju najveću tajnu djetinjstva uz pomoć kupusa, roda i beskrajne radoznalosti!', '/covers/DP-0945.webp', '#5b9e5d', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","friends","real"]', '["family","brothers","curiosity","humor","babies"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('брат-юннат-946', 'DP-0946', 'Брат-юннат', 'Brother Naturalist', 'Brat prirodnjak', 'Станислав Востоков', 'Stanislav Vostokov', 'Stanislav Vostokov', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Сергей повернул ко мне нос-крючок и спросил: - Что главное в работе с опасными животными? - Войти в клетку? - предположил я. Сергей покачал головой. - Вовремя из неё выйти! В этой юмористической повести Станислав Востоков рассказывает о том, как начиналась его карьера натуралиста в 90-е годы. Для детей младшего и среднего школьного возраста.', '"What''s the most important rule when working with dangerous animals?" Sergei asked, tilting his hooked nose toward me. "Stepping into the cage?" I guessed. He shook his head: "Getting out of it in time!" In this humorous autobiographical tale, Stanislav Vostokov recounts how his career as a young naturalist began at a city zoo in the 1990s.', '„Šta je najvažnije u radu sa opasnim životinjama?“ pitao me je Sergej s kukastim nosom. „Ući u kavez?“ pretpostavio sam. Odmahnuo je glavom: „Izaći iz njega na vrijeme!“ U ovoj duhovitoj priči Stanislav Vostokov opisuje kako je devedesetih godina započeo svoju karijeru prirodnjaka u zoološkom vrtu.', 'Остроумные и тёплые байки о буднях зоопарка девяностых от автора, который отлично знает, как поладить и с верблюдом, и с директором.', 'Hilarious and heartwarming behind-the-scenes zoo tales from an author who quickly learned how to negotiate with both camels and cage doors.', 'Urnebesne i tople priče iza kulisa zoološkog vrta od autora koji je rano naučio kako izaći na kraj i s kamilama i s opasnim kavezima.', '/covers/DP-0946.webp', '#4a7a44', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["animals","funny","real"]', '["zoo","animals","memoir","humor","nature"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секретный-пес-947', 'DP-0947', 'Секретный пес', 'The Secret Dog', 'Tajni pas', 'Станислав Востоков', 'Stanislav Vostokov', 'Stanislav Vostokov', '', 'clever', NULL, NULL, 6, 16, 'middle', 'Секреты есть у всех: у дошкольников (’секретики’ под стеклом), у бабушек (кулинарные секреты), у бизнесменов (секреты фирмы). Секреты есть у маленьких и больших компаний. Секреты есть у ФСБ и ЦРУ. Так почему их не может быть у собаки? Особенно если она работает в секретном институте.', 'Everyone has secrets: preschoolers bury secret treasures under glass, grandmas keep recipe tricks, and big corporations guard trade secrets. Intelligence agencies are packed with them too. So why can''t a dog have secrets? Especially one on duty at a top-secret research institute!', 'Svi imaju tajne: predškolci čuvaju skriveno blago pod staklom, bake kulinarske tajne, a preduzetnici poslovne tajne. Tajne imaju i obavještajne službe. Pa zašto ih onda ne bi imao i jedan pas? Pogotovo ako radi u strogo povjerljivom institutu!', 'Остроумная и пушистая шпионская хроника о том, что даже у самых преданных хвостатых есть свои государственные тайны!', 'A witty, tail-wagging chronicle proving that even the best four-legged boys can guard top-secret clearance!', 'Duhovita i čupava špijunska priča koja dokazuje da čak i najvjerniji psi mogu čuvati državne tajne!', '/covers/DP-0947.webp', '#2c5d63', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","animals","adventure"]', '["dogs","secrets","humor","science","spies"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ветер-делают-деревья-948', 'DP-0948', 'Ветер делают деревья', 'The Wind Is Made by Trees', 'Vjetar pravi drveće', 'Станислав Востоков', 'Stanislav Vostokov', 'Stanislav Vostokov', '', 'Время', NULL, NULL, 6, 16, 'middle', 'Видели вы такие книжки, где взрослые воспитатели делятся опытом с коллегами и рассказывают, как надо обращаться с ребятами в детском саду? Да сколько угодно! А такие, где шестилетние дети размышляют по поводу воспитательской работы, а заодно о смысле бытия, о сложении стихов по методу китайских поэтов-монахов и о том, для чего в манную кашу добавляют комки? Что, не видели? Ну тогда не теряйте времени: открывайте эту книжку - и читайте. Вы узнаете много нового причем не только о детсадовских буднях, но и о жизни вообще!', 'You''ve seen plenty of books where adult teachers share advice on dealing with kids. But have you ever read one where six-year-olds reflect on educators'' methods, the meaning of life, writing poetry like ancient Chinese monks, and the real reason for lumps in semolina porridge? Dive into this delightfully philosophical book to discover surprising truths about preschool and life in general!', 'Sigurno ste vidjeli knjige u kojima vaspitači dijele savjete o radu s mališanima. Ali jeste li čitali knjigu u kojoj šestogodišnjaci raspravljaju o metodama vaspitanja, smislu postojanja, poeziji drevnih kineskih monaha i zašto griz ima grudvice? Zaronite u ovu neodoljivo duhovitu i filozofsku priču i saznajte velike istine o vrtiću i samom životu!', 'Гомерически смешной и по-настоящему глубокий взгляд на мир глазами шестилеток, знающих о природе ветра и каше с комочками куда больше взрослых.', 'A profoundly wise and hilarious glimpse into the world through the eyes of preschoolers who know far more about the universe than adults do!', 'Neizmjerno mudra i urnebesno duhovita priča o svijetu viđenom očima predškolaca koji o životu znaju mnogo više od odraslih!', '/covers/DP-0948.webp', '#5a9e6f', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["funny","real"]', '["kindergarten","childhood","humor","philosophy","growing up"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('детский-садик-13-949', 'DP-0949', 'Детский садик 13', 'Kindergarten No. 13', 'Dječji vrtić 13', 'Валерий Роньшин', 'Valery Ronshin', 'Valerij Ronjšin', '', 'Время', NULL, NULL, 6, 16, 'middle', 'В нашем городе живут мастера выдумки и фантазии, смеха, игр и приключений - в общем, самые настоящие мастера детской литературы! Загляни в город мастеров - там никто не скучает! У одной принцессы был золотой скелет - у всех обычный, а у неё золотой, и вот однажды этот скелет украли... А один мальчик мог проспать целых пять лет подряд! У одной девочки за спиной росли крылья, но никто в это не верил, зато все верили, что один учитель - не обычный человек, а самый настоящий вампир! А в одной семье вообще были одни только инопланетяне, причём с разных планет... Ой, да что мы тут будем всё тебе рассказывать?! Лучше открывай книжку и читай!', 'Step into a world of pure imagination and wild adventures! Here, a princess has a stolen golden skeleton, a boy can sleep for five years straight, a girl sprouts real wings, and everyone is convinced their teacher is a bona fide vampire. Not to mention the family made entirely of aliens from different planets! Valery Ronshin''s delightfully absurd, witty, and slightly spooky tales will keep young readers grinning from ear to ear.', 'Zavirite u svijet neobuzdane mašte i otkačenih avantura! Ovdje princeza ima ukradeni zlatni kostur, dječak može da prespava punih pet godina, jednoj djevojčici rastu prava krila, dok su svi ubijeđeni da im je učitelj pravi pravcati vampir. Da i ne pominjemo porodicu u kojoj su svi vanzemaljci sa različitih planeta! Apsurdne, duhovite i pomalo jezive priče Valerija Ronjšina nasmijaće vas do suza.', 'Осторожно, эта книга вызывает неудержимый хохот: где ещё вы встретите учителя-вампира, похищенный золотой скелет и семейку инопланетян в одном флаконе?!', 'Beware: this book causes uncontrollable giggles—where else would you find a vampire teacher, a stolen golden skeleton, and a house full of aliens all in one place?!', 'Oprez, ova knjiga izaziva nekontrolisani smijeh: gdje biste još našli učitelja vampira, ukradeni zlatni kostur i porodicu vanzemaljaca na istom mjestu?!', '/covers/DP-0949.webp', '#6c3483', 'nonfiction', 'ru', 'available', '6+', '["funny","spooky","magic"]', '["absurd humor","short stories","spooky tales","imagination","monsters"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вещи-моего-детства-950', 'DP-0950', 'Вещи моего детства', 'Things from My Childhood', 'Stvari mog djetinjstva', 'Александра Ершанская', 'Alexandra Ershanskaya', 'Aleksandra Jeršanskaja', '', 'розовый жираф', NULL, NULL, 6, 16, 'middle', 'Саша Ершанская живет шестьдесят лет назад, в другом веке и даже в другой стране. От Саши нас отделяет целая эпоха. Но, не смотря на это, в чем-то мы с Сашей очень похожи. Все мы хотели быть хорошими и уступали место в автобусе бабушкам, переодически путая возраст бабушек и уступая место тридцатилетним девушкам. Все мы любили кататься на велосипедах и иногда с них падали. У многих из нас есть своя удивительная история о том, как мы наконец-то полюбили читать книги. И, конечно, у всех у нас была в жизни первая любовь, первая драка и первое горе. А вот предметы нас окружали совершенно разные. Кто сейчас знает, что такое шайка и зачем нужна керосинка? Мы сегодня не выходим из дома без мобильника, а у наших бабушек и дедушек были монетки на веревочке, чтобы звонить в телефоне-автомате. Мы умеем печатать на компьютере сто знаков в минуту, а им нужно было красиво и без клякс писать перьевой ручкой. Книга Александры Ершанской «Вещи моего детства» - это возможность заглянуть в другое время, в другую эпоху и лучше понять людей, которые там жили, а благодаря этому, возможно, лучше понять и самих себя.', 'Sasha Ershanskaya lives sixty years ago, in another century and even in another country. A whole era separates us from Sasha. Yet we share so much: the urge to be good, falling off bicycles, falling in love for the first time, and discovering the joy of reading. But the everyday objects around us were completely different! Who today knows what a wash-tub or a kerosene stove was used for? Instead of smartphones, kids carried coins tied to a string for payphones, and wrote neatly with ink dip pens. Alexandra Ershanskaya’s memoir invites young readers to peek into a bygone era, helping us understand the past—and maybe even ourselves.', 'Saša Jeršanskaja živi prije šezdeset godina, u drugom vijeku i sasvim drugoj zemlji. Od Saše nas dijeli čitava jedna epoha, a opet smo joj nevjerovatno slični: svi smo željeli biti dobri, padali s bicikla, doživjeli prve simpatije i trenutak kada smo zavoljeli knjige. Ipak, predmeti koji su je okruživali bili su potpuno drugačiji. Ko danas zna šta je petrolejka i čemu služi drveni lavor? Umjesto mobilnih telefona, djeca su nosila novčiće na konopcu za javne govornice i vježbala pisanje perom bez mrlja od mastila. Ova topla knjiga otvara prozor u prošlost i pomaže nam da bolje razumijemo odrastanje naših baka i djedova — ali i nas same.', 'Увлекательная машина времени в мир керосинок и перьевых ручек, доказывающая: эпохи меняются, а детские радости и шалости остаются прежними!', 'A charming time machine back to kerosene stoves and ink dip pens, proving that while gadgets change, the spirit of childhood never does!', 'Čarobni vremeplov u svijet petrolejki i mastionica koji dokazuje da se tehnologija mijenja, ali dječje radosti ostaju iste!', '/covers/DP-0950.webp', '#c45b43', 'nonfiction', 'ru', 'available', 'Категория: современные русскоязычные писатели и художники', '["real","friends"]', '["childhood","history","everyday life","memories","vintage"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('невероятная-история-о-гиганстс-951', 'DP-0951', 'Невероятная история о гиганстской груше', 'The Incredible Story of the Giant Pear', 'Nevjerovatna priča o džinovskoj krušci', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Якоб Мартин Стрид', 'Clever', NULL, NULL, 6, 16, 'middle', '«Эта история берёт своё начало в Сульбю, прекрасном городе на берегу моря. Сульбю в переводе с датского означает „Солнечный город“» Все начинается с того, что куда-то пропадает бургомистр! А жители сажают семечко, из которого вырастает гигантская груша. А из груши получается отличный корабль, на котором бесстрашные герои плывут спасать своего бургомистра. Смогут ли они добраться до острова и спасти друга? Якоб Мартин Стрид — невероятный выдумщик из сказочной Дании. Обладая выдающимся талантом карикатуриста и тонким чувством юмора, художник создает удивительный мир героев, которых очень любят дети и их родители. Этот необыкновенный датчанин придумал и нарисовал «Невероятную историю о гигантской груше», а также сюжеты о неугомонном слоненке Мимбо-Джимбо и его друзьях (например, о милом бегемотике Мумбо-Джумбо).', 'It all begins in the coastal town of Solby, when the beloved mayor suddenly disappears! Friends Mitcho and Sebastian plant a mysterious seed sent in a bottle, and overnight it grows into a colossal pear. Hollowing it out into an extraordinary sailing vessel, the brave heroes embark on an epic maritime journey past pirates, sea dragons, and phantom islands to bring their mayor home.', 'Sve počinje u primorskom gradiću Solbiju kada omiljeni gradonačelnik iznenada nestane! Prijatelji Mičo i Sebastijan sade neobičnu sjemenku iz boce i preko noći iz nje izraste divovska kruška. Kruška ubrzo postaje sjajan jedrenjak kojim neustrašivi drugari kreću u veliku plovidbu punu gusara, morskih nemani i tajanstvenih ostrva kako bi spasili svog prijatelja.', 'Превратить гигантскую сочную грушу в корабль и отправиться спасать бургомистра через моря с пиратами — вот оно, идеальное приключение!', 'Turning a giant juicy pear into a seaworthy ship to rescue the mayor from uncharted waters is the ultimate voyage of imagination!', 'Pretvoriti džinovsku sočnu krušku u pravi brod i zaploviti preko mora punog gusara u spasilačku misiju – to je prava avantura za male mornare!', '/covers/DP-0951.webp', '#7ba436', 'nonfiction', 'ru', 'available', 'Категория: Якоб Мартин Стрид', '["adventure","funny","friends"]', '["sea voyage","giant pear","inventions","rescue mission","illustrated"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мимбо-джимбо-играет-952', 'DP-0952', 'Мимбо-Джимбо играет', 'Mimbo Jimbo Plays', 'Mimbo Džimbo se igra', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Якоб Мартин Стрид', 'Clever', NULL, NULL, 6, 16, 'middle', 'В новой книге о слоненке Мимбо-Джимбо под названием «Мимбо-Джимбо играет» мы узнаем о том, как он получил посылку с деталями. И вот, как настоящий изобретатель, слоненок сразу же принялся мастерить. Сначала он смастерил машину, а потом из этой самой машины он сделал самолет и распугал попугаев, фламинго и всех, всех, всех... Куда ещё заведёт слонёнка фантазия? Об этом и многом другом мы узнаем на страницах новой книжки. Мимбо-Джимбо — это весёлый дружелюбный слонёнок, которого придумал знаменитый датский художник и писатель Якоб Мартин Стрид. Больше всего на свете Мимбо-Джимбо любит своего лучшего друга бегемотика Мумбо-Джумбо. А ещё ему нравится изобретать и путешествовать. Из-за своей любознательности друзья постоянно попадают в забавные ситуации, о которых вы узнаете в новой серии книг «Мимбо-Джимбо».', 'When the cheerful little elephant Mimbo Jimbo receives a package full of spare parts, his inner inventor immediately gets to work! First, he builds a speedy car, then transforms it into an airplane, startling flamingos and parrots along the way. Together with his best pal Mumbo Jumbo, Mimbo Jimbo discovers that true curiosity and imagination can turn any afternoon into a brilliant, whirring adventure.', 'Kada veselo slonče Mimbo Džimbo dobije paket pun rezervnih djelova, njegov pronalazački duh odmah stupa na scenu! Prvo pravi brzi auto, a zatim ga pretvara u avion koji uzlijeće i iznenađuje papagaje i flamingose. Zajedno sa svojim najboljim drugom Mumbo Džambom, Mimbo Džimbo dokazuje da uz malo mašte i radoznalosti obična igra postaje prava velika avantura.', 'Осторожно: после этой книги ваш ребёнок наверняка захочет разобрать что-нибудь полезное и построить из этого настоящий самолёт!', 'Warning: reading this delightful tale will almost certainly inspire your little inventor to turn cardboard boxes into flying machines!', 'Upozorenje: nakon ove priče vaš mali izumitelj bi mogao poželjeti da pretvori obične kutije u pravi pravcati avion!', '/covers/DP-0952.webp', '#2c9ad6', 'nonfiction', 'ru', 'available', 'Категория: Якоб Мартин Стрид', '["funny","adventure","animals"]', '["inventions","elephants","creativity","picture book","friendship"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мимбо-едет-в-гости-953', 'DP-0953', 'Мимбо едет в гости', 'Mimbo Jimbo Visits a Friend', 'Mimbo Džimbo ide u goste', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Якоб Мартин Стрид', 'Clever', NULL, NULL, 6, 16, 'middle', 'Мимбо-Джимбо — весёлый дружелюбный слонёнок, которого придумал знаменитый датский художник и писатель Якоб Мартин Стрид. Больше всего на свете Мимбо-Джимбо любит своего лучшего друга бегемотика Мумбо-Джумбо. А еще ему нравится изобретать и путешествовать. Из-за своей любознательности друзья постоянно попадают в забавные ситуации. Однажды Мимбо-Джимбо и Мумбо-Джумбо получили письмо — их пригласила в гости подруга. Конечно, надо немедленно собирать вещи и отправляться в аэропорт! Что же увидят друзья в далёкой стране? Какие приключения ждут их там?', 'Mimbo Jimbo is a cheerful, inventive little elephant created by renowned Danish author and illustrator Jakob Martin Strid. When Mimbo Jimbo and his best friend Mumbo Jumbo receive an invitation to visit a friend abroad, they immediately pack their bags and head to the airport. Pack your curiosity and fly along to see what hilarious adventures await them in a distant land!', 'Mimbo Džimbo je veseli plavi slonić kojeg je stvorio poznati danski pisac i ilustrator Jakob Martin Strid. Kada on i njegov najbolji prijatelj, nilski konjić Mumbo Džambo, dobiju pismo s pozivom u goste, odmah pakuju kofere i jure na aerodrom. Krenite na put s njima i otkrijte kakve ih sve zabavne avanture čekaju u dalekoj zemlji!', 'Пакуйте чемоданы и держитесь крепче: с неугомонным слонёнком Мимбо-Джимбо даже обычный перелёт превращается в уморительное приключение!', 'Pack your bags and buckle up: with curious little elephant Mimbo Jimbo, even an ordinary flight turns into a delightfully funny adventure!', 'Spakujte kofere i vežite se: sa radoznalim slonićem Mimbom Džimbom čak i obično putovanje avionom postaje urnebesna avantura!', '/covers/DP-0953.webp', '#3fa9f5', 'nonfiction', 'ru', 'available', '1+', '["adventure","funny","friends"]', '["elephants","travel","friendship","picture book","humor"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мимбо-и-большие-слоны-954', 'DP-0954', 'Мимбо и большие слоны', 'Mimbo Jimbo and the Big Elephants', 'Mimbo Džimbo i veliki slonovi', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Якоб Мартин Стрид', 'Clever', NULL, NULL, 6, 16, 'middle', 'Забавная история про то, как слоненок Мимбо-Джимбо отправился в путешествие к своим реальным сородичам — диким слонам, живущими в саванне. Слоненку предстоит пройти долгий путь по пустыне и по джунглям. Но самое главное, как примут большие серые слоны маленького синего Мимбо-Джимбо? Сумеет ли он с ними подружиться?', 'A funny and heartwarming tale about Mimbo Jimbo the little elephant setting off on a journey to meet his wild cousins roaming the savannah. It''s a long trek across deserts and dense jungles, but the real question is: how will the gigantic grey elephants welcome a tiny, bright-blue relative?', 'Zabavna i topla priča o malom plavom slončetu Mimbu Džimbu koji kreće na daleko putovanje kako bi upoznao svoje divlje rođake u afričkoj savani. Čeka ga dugačak put kroz pustinju i džunglu, ali glavno pitanje glasi: kako će veliki sivi slonovi prihvatiti malog plavog gosta?', 'Быть ярко-синим слонёнком непросто, но Мимбо-Джимбо докажет огромным серым сородичам, что дружба не зависит от роста и цвета ушей!', 'Being a tiny blue elephant in a world of giant grey giants isn''t easy, but Mimbo Jimbo proves that true friendship comes in all shades and sizes!', 'Nije lako biti malo plavo slonče među džinovskim sivim rođacima, ali Mimbo Džimbo dokazuje da prijateljstvo ne zavisi od boje i veličine!', '/covers/DP-0954.webp', '#2c8ed6', 'nonfiction', 'ru', 'available', '1+', '["adventure","animals","funny"]', '["elephants","savannah","journey","friendship","picture book"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мимбо-строит-маяк-955', 'DP-0955', 'Мимбо строит маяк', 'Mimbo-Jimbo Builds a Lighthouse', 'Mimbo-Džimbo gradi svjetionik', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Якоб Мартин Стрид', 'Clever', NULL, NULL, 6, 16, 'middle', '«Мимбо-Джимбо строит маяк» — книга с яркими и веселыми иллюстрациями, которые заинтересуют детей в возрасте от 1 до 5 лет. Красочная, веселая история о слоненке и бегемотике, которые помогают друзьям и зверятам, попавшим в беду, путешествуют и учатся дружить. Больше всего на свете Мимбо-Джимбо любит своего лучшего друга — бегемотика Мумбо-Джумбо. А еще ему нравится изобретать и путешествовать. Из-за своей любознательности друзья постоянно попадают в забавные ситуации. Как-то Мимбо-Джимбо подарили большую лампочку. «Что же с ней делать? — думал слоненок. — Построю-ка я маяк!» Друзья с радостью согласились помочь Мимбо-Джимбо — заготавливали бетонные блоки, возводили стены, строили лестницу, устанавливали окна и двери... Ура, наконец-то можно зажечь маяк! Но... кто это приближается к Мимбо-Джимбо и его друзьям сквозь туман? Детям младшего возраста очень понравятся яркие иллюстрации и добрые персонажи книжки, забавные истории и приключения. А для ребят постарше «Мимбо-Джимбо строит маяк» станет книгой для первого самостоятельного чтения.', 'When blue elephant Mimbo-Jimbo receives a giant light bulb as a present, he knows exactly what to do: build a grand lighthouse! Together with his best buddy Mumbo-Jumbo the hippo and their forest friends, they mix concrete, lay bricks, and assemble windows until the beacon is ready to shine. But just as the light pierces the coastal fog, a mysterious visitor approaches in the mist. A delightfully sunny story about ingenuity, teamwork, and friendship.', 'Kada plavi slonić Mimbo-Džimbo dobije na poklon džinovsku sijalicu, tačno zna šta treba učiniti: sagraditi pravi svjetionik! Zajedno sa svojim najboljim prijateljem, nilskim konjem Mumbo-Džambom, i ostalim šumskim drugarima, on priprema betonske blokove, zida zidove i postavlja prozore sve dok svjetionik ne zasvijetli. Ali čim svjetlost probije gustu obalnu maglu, neko se približava kroz sumrak... Predivna i topla priča o saradnji, mašti i prijateljstvu.', 'Что делать, если тебе подарили огромную лампочку? Конечно же, собрать верных друзей и построить настоящий маяк!', 'What do you do when gifted a giant light bulb? Rally your best friends and build a real lighthouse, of course!', 'Šta raditi kada na poklon dobiješ džinovsku sijalicu? Naravno, okupiti najbolje prijatelje i sagraditi pravi pravcati svjetionik!', '/covers/DP-0955.webp', '#389bc7', 'nonfiction', 'ru', 'available', '3+', '["friends","animals","funny"]', '["lighthouse","elephants","teamwork","friendship","inventions"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мимбо-и-долгая-зима-956', 'DP-0956', 'Мимбо и долгая зима', 'Mimbo Jimbo and the Long Winter', 'Mimbo Džimbo i duga zima', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Якоб Мартин Стрид', 'Clever', NULL, NULL, 6, 16, 'middle', 'На весёлого слонёнка Мимбо-Джимбо и его друзей обрушилась беда. Вместо долгожданной весны неожиданно пришла зима — да какая! Такого снегопада в Африке отродясь не видали. Кто же в этом виноват и что теперь делать? Как заставить Дух пушистого снега отправиться обратно на Северный полюс и спасти зверей от холода? Вперёд, навстречу приключениям вместе с Мимбо-Джимбо и его друзьями!', 'Trouble strikes the cheerful little elephant Mimbo Jimbo and his friends. Instead of the long-awaited spring, an unexpected and unprecedented winter arrives—such snowfall has never been seen in Africa! Who is to blame, and what can they do now? How can they convince the Spirit of Fluffy Snow to return to the North Pole and rescue the animals from the freezing cold? Set off on a chilly and charming adventure with Mimbo Jimbo and his crew!', 'Nevolja je zadesila veselog slončića Mimba Džimba i njegove prijatelje. Umjesto proljeća, stigla je nezapamćena zima — snijeg kakav u Africi nikada nije viđen! Ko je za to kriv i šta sada raditi? Kako nagovoriti Duha pahuljastog snijega da se vrati na Sjeverni pol i spasi životinje od hladnoće? Krenite u nezaboravnu pustolovinu sa Mimbom Džimbom i njegovom družinom!', 'Снег посреди жарких джунглей — не беда, когда за дело берутся изобретательный слонёнок Мимбо-Джимбо и его верная команда!', 'Snow in the sunny tropics is no match for inventive little elephant Mimbo Jimbo and his plucky friends!', 'Snijeg usred tople savane nije problem kad na scenu stupe domišljati slončić Mimbo Džimbo i njegova družina!', '/covers/DP-0956.webp', '#7eb8da', 'nonfiction', 'ru', 'available', 'Категория: Якоб Мартин Стрид', '["adventure","funny","animals"]', '["snow","elephant","winter","friendship","expedition"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мумбо-джумбо-баба-яга-и-волшеб-957', 'DP-0957', 'Мумбо-Джумбо, Баба-Яга и волшебные грибы', 'Mumbo Jumbo, Baba Yaga and the Magic Mushrooms', 'Mumbo Džambo, Baba Jaga i čarobne pečurke', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Якоб Мартин Стрид', 'Clever', NULL, NULL, 6, 16, 'middle', 'Мумбо-Джумбо — милый бегемотик, друг слоненка Мимбо-Джимбо. Однажды жители Маленькой долины решили устроить праздник, поэтому все были заняты уборкой, а Мумбо-Джумбо отправили в лес за лисичками для соуса. Бегемот не знал, как выглядят лисички, и попробовал какие-то неизвестные ему грибы. Ой-ой-ой! Мумбо-Джумбо стал великаном! Что же делать? Как помочь нашему другу, знает только Баба-яга, но она живет в далекой-далекой Сибири… Друзья все вместе отправляются в опасное путешествие, чтобы спасти Мумбо-Джумбо. Они доберутся до Сибири, найдут Бабу-ягу, побывают в Москве и… А что будет дальше, вы узнаете, когда прочитаете историю! Если вы прочитали «Невероятную историю о гигантской груше» и ищете что-то похожее, то эта книга точно для вас. «Мумбо-Джумбо, Баба-яга и волшебные грибы» — это невероятные приключения, динамичный сюжет, любимые герои и уютные вечера в кругу семьи. А еще «Мумбо-Джумбо» может стать первой самостоятельно прочитанной вашим ребенком книгой. Крупный шрифт и картинки-комиксы — идеальное сочетание для тех, кто только-только учится читать.', 'Mumbo Jumbo is a lovable little hippo and best pal of Mimbo Jimbo the elephant. Sent into the woods to harvest chanterelles for a valley feast, he nibbles on strange forest mushrooms by mistake—and suddenly balloons into a towering giant! The only one who holds the cure is Baba Yaga, but she lives far away in deep Siberia. Teaming up for a daring rescue quest, the loyal friends set off across snowy lands and bustling cities to turn Mumbo Jumbo back to normal. Packed with comic-style illustrations, warmth, and wild inventions from the creator of The Incredible Story of the Giant Pear.', 'Mumbo Džambo je simpatični mali nilski konj i najbolji prijatelj slončeta Mimbo Džimba. Dok su se stanovnici Doline pripremali za veliku proslavu, Mumbo Džambo je poslat u šumu po lisičarke za sos. Kako nije znao kako one izgledaju, pojeo je nepoznate pečurke i... paf! Pretvorio se u pravog džina! Jedina koja može da mu pomogne jeste Baba Jaga, ali ona živi u dalekom Sibiru. Družina kreće na uzbudljivo putovanje puno neobičnih prevoznih sredstava, prijateljstva i humora kako bi spasila svog drugara.', 'Ни в коем случае не пробуйте незнакомые лесные грибы — если только вы не мечтаете вырасти до небес и прокатиться на поезде прямо к Бабе-яге!', 'Never snack on unfamiliar forest mushrooms—unless you''re quite keen on growing giant-sized and road-tripping all the way to Siberia to meet Baba Yaga!', 'Nikada ne jedite nepoznate šumske pečurke — osim ako ne želite da narastete do oblaka i krenete na ekspediciju u Sibir kod Babe Jage!', '/covers/DP-0957.webp', '#e2583e', 'nonfiction', 'ru', 'available', 'Категория: Якоб Мартин Стрид', '["funny","adventure","magic"]', '["journey","hippo","comics","magic mushrooms","friendship"]', 1792836322700, 1792845696454);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тося-бося-и-сбежавшие-уши-958', 'DP-0958', 'Тося-Бося и сбежавшие уши', 'Tosya-Bosya and the Runaway Ears', 'Tosja-Bosja i odbjegle uši', 'Лина Жутауте', 'Lina Žutautė', 'Lina Žutaute', '', 'Clever', NULL, NULL, 6, 16, 'middle', 'Ах, эта Тося-Бося! Не слушала маму, не слушала папу, не слушала бабушку. И так каждый день, по сто раз! Ничего удивительного, что однажды случилось невероятное: уши Тоси-Боси, словно по волшебству, спрыгнули на пол, проскакали через всю кухню, наперегонки пронеслись по коридору, без оглядки вылетели за дверь – и во двор!Если вам любопытно, что случилось дальше – читайте новую книгу о приключениях милой упрямицы Тоси-Боси. И не забудьте поискать, где же спрятались ее уши.', 'Ah, that Tosya-Bosya! She never listened to Mom, never listened to Dad, and never listened to Grandma—all day long, on repeat! No wonder something extraordinary happened: her ears suddenly hopped right off, darted across the kitchen, scrambled down the hallway, and dashed straight out the front door! Join this delightfully stubborn girl on her funny quest and see if you can spot where her runaway ears are hiding.', 'Ah, ta Tosja-Bosja! Nije slušala mamu, nije slušala tatu, nije slušala baku — i tako po sto puta svakog dana! Zato nije čudo što se jednog dana dogodilo nešto nevjerovatno: njene uši su prosto poskočile, protrčale kroz kuhinju, pojurile niz hodnik i zbrisale pravo u dvorište! Saznajte šta se dalje desilo sa ovom slatkom tvrdoglavicom i pomozite joj da pronađe svoje odbjegle uši.', 'Идеальное весёлое лекарство для маленьких упрямцев, чьи ушки временами напрочь отказываются слушать взрослых!', 'The ultimate playful remedy for little rascals whose ears occasionally pretend they forgot how to listen!', 'Savršen i duhovit lijek za male tvrdoglavce čije uši s vremena na vrijeme zaborave kako da slušaju roditelje!', '/covers/DP-0958.webp', '#f5a623', 'nonfiction', 'ru', 'available', 'Категория: Якоб Мартин Стрид', '["funny","magic"]', '["listening","picture book","humor","stubbornness","search and find"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('был-бы-я-взрослым-959', 'DP-0959', 'Был бы я взрослым', 'If I Were a Grown-Up', 'Da sam ja odrastao', 'Ева Яниковски', 'Éva Janikovszky', 'Éva Janikovszky', 'Ласло Ребер', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Каждый ребенок в душе больше всего на свете мечтает об одном: наконец-то стать взрослым! Ведь тогда-то и начинается жизнь: можно смело ходить по лужам, не мыть руки перед едой и не убирать игрушки! Вот оно - настоящее счастье! Но вот что странно: взрослые почему-то всего этого не делают. Остается только развести руками. Глупые они, эти взрослые. Книга известной венгерской писательницы Евы Яниковски, проиллюстрированная Ласло Ребером, красочно рассказывает именно об этом - о фантазиях одного мальчишки, которого от счастья отделяет лишь пара десятков лет. И вслед за автором так и хочется повторять: "Каждый ребёнок, даже самый маленький, знает, что быть непослушным куда веселее, чем быть паинькой". Чтобы затем задаваться вопросом: "Но если моим детям достанется самый большой надувной шар, самая большая порция мороженого, самая широкая лужа и самый высоченный сугроб, тогда какой мне толк быть ВЗРОСЛЫМ?"', 'Every child dreams of one thing above all else: finally growing up! After all, that''s when real life begins—you can stomp through puddles, skip washing hands before meals, and leave your toys everywhere. But adults, strangely enough, never seem to do any of these glorious things. What a waste! Renowned Hungarian author Éva Janikovszky and illustrator László Réber bring to life the delightfully candid thoughts of a boy who knows that being mischievous is far more fun than being well-behaved.', 'Svako dijete sanja o jednoj stvari: da napokon odraste! Jer tek tada počinje pravi život — možeš slobodno gaziti po barama, zaboraviti na pranje ruku prije jela i nikada ne spremati igračke. Ali iz nekog čudnog razloga, odrasli ništa od toga ne rade! Ova kultna knjiga mađarske spisateljice Éve Janikovszky, uz legendarne crteže Lászlóa Rébera, kroz iskren i duhovit monolog jednog dječaka otkriva vječnu istinu: biti neposlušan mnogo je zabavnije nego biti poslušan.', 'Остроумный и до боли честный манифест любого ребёнка, который искренне недоумевает, почему взрослые так бездарно распоряжаются своей свободой!', 'A brilliantly witty, laugh-out-loud manifesto from a kid who simply can''t understand why adults waste their absolute freedom on boring things!', 'Duhovit i dirljivo iskren manifest svakog djeteta koje ne razumije zašto odrasli tako uzaludno troše svoju dragocjenu slobodu!', '/covers/DP-0959.webp', '#e8aa38', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real"]', '["growing up","childhood","humor","family","classic"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-кого-пошел-этот-ребенок--960', 'DP-0960', 'В кого пошел этот ребенок?', 'Who Does This Kid Take After?', 'Na koga je ovo dijete?', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', 'Ласло Ребер', 'КомпасГид', NULL, NULL, 6, 16, 'middle', '"В кого пошел этот ребенок?" - еще одна трогательная и знакомая всем история о родителях и детях, которые всячески показывают, что не похожи друг на друга, хотя втайне считают совсем иначе...', 'Who does this child take after? A touching, laugh-out-loud familiar tale about parents and children who insist they are nothing alike, while secretly knowing the exact opposite is true.', 'Na koga je ispalo ovo dijete? Još jedna dirljiva i svima dobro poznata priča o roditeljima i djeci koji se trude da pokažu kako nimalo ne liče jedni na druge, iako u dubini duše misle sasvim suprotno...', 'Искромётное зеркало для всей семьи: читайте вместе, чтобы вволю посмеяться над вечными спорами отцов и детей!', 'A brilliantly witty mirror for the whole family: read it together and chuckle at the eternal back-and-forth between parents and kids!', 'Duhovito ogledalo za cijelu porodicu: čitajte zajedno i slatko se nasmijte vječitim roditeljskim dilemama!', '/covers/DP-0960.webp', '#e05844', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real"]', '["family","humor","parents and children","growing up","illustrated"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вечно-со-мной-что-то-случается-961', 'DP-0961', 'Вечно со мной что то случается', 'Something Always Happens to Me', 'Uvijek se meni nešto dešava', 'Ева Яниковски', 'Eva Janikovszky', 'Eva Janikovski', 'Ласло Ребер', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Искренний и забавный рассказ первоклассника о жизни своей семьи. Каждый день наполнен разными событиями, на которые взрослые не всегда реагируют так, как хотелось бы ребёнку. И в этой круговерти очень важно сохранить взаимопонимание.', 'A sincere and witty monologue of a first-grader reflecting on family life, daily misadventures, and the puzzling ways grown-ups react to childhood mischief. A timeless, heartwarming classic that shows how vital mutual understanding really is.', 'Iskrena i duhovita priča jednog prvaka o njegovoj porodici, svakodnevnim nezgodama i zbunjujućim reakcijama odraslih na dječije smicalice. Topla i bezvremena priča o tome koliko je važno međusobno razumijevanje.', 'Остроумный и трогательный взгляд на мир взрослых глазами первоклассника, который поможет всей семье посмеяться и наконец-то услышать друг друга!', 'A witty, heartfelt look at the adult world through a child''s eyes that will make the whole family laugh and see things from a fresh perspective!', 'Duhovit i dirljiv pogled na svijet odraslih očima jednog prvaka, uz koji će se cijela porodica nasmijati i bolje razumjeti!', '/covers/DP-0961.webp', '#d67935', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real"]', '["family","childhood","humor","growing up","school"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ну-вот-опять--962', 'DP-0962', 'Ну вот, опять...', 'Here We Go Again...', 'Evo ga opet...', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', 'Ласло Ребер', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Очень хочется сделать маме подарок, который потом не окажется в нижнем ящике комода. Очень хочется устроить с другом клуб в подвале. А ещё хочется выиграть приз по лотерейному билету и получить главную роль в фильме… Но больше всего хочется услышать от папы и мамы: "Мы тобой гордимся!"', 'You really want to give Mom a gift that won''t end up forgotten in the bottom drawer. You want to start a secret clubhouse with your best friend in the basement. You also want to win a lottery prize and star in a movie... But most of all, you just want to hear Mom and Dad say: "We are proud of you!"', 'Baš želiš mami pripremiti poklon koji neće završiti zaboravljen u najdonjoj fioci. Želiš sa najboljim drugom napraviti tajni klub u podrumu. Želiš i osvojiti premiju na lutriji ili dobiti glavnu ulogu u filmu... Ali najviše od svega želiš čuti roditelje kako govore: „Ponosni smo na tebe!“', 'Трогательная и удивительно точная книга о сокровенных детских мечтах и о том, как важно вовремя сказать ребёнку: «Мы тобой гордимся!».', 'A tender and razor-sharp look into a child''s heart, reminding us how much every kid yearns to hear "we''re proud of you."', 'Dirljiva i nevjerovatno duhovita knjiga koja nas podsjeća koliko je svakom djetetu važno da čuje: „Ponosni smo na tebe!“', '/covers/DP-0962.webp', '#e09f3e', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real","friends"]', '["childhood","family","growing up","emotions","relatable"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('теперь-и-ты-знаешь-963', 'DP-0963', 'Теперь и ты знаешь', 'Now You Know Too', 'Sad i ti znaš', 'Ева Яниковски', 'Éva Janikovszky', 'Éva Janikovszky', 'Ласло Ребер', 'Эксмо', NULL, NULL, 6, 16, 'middle', '"Почему взрослые не хотят играть со мной?" – недоумевает маленький мальчик. И взрослые рассказывают ему, чем они заняты целый день. Вскоре мальчуган узнаёт, чем занимаются почтальон, полицейский, крановщик, врач и даже… пенсионер! А ты знаешь?', '"Why don''t grown-ups ever want to play with me?" wonders a little boy. Patiently, the adults explain what keeps them so busy all day long. Soon, the curious boy learns all about what mail carriers, police officers, crane operators, doctors, and even retirees do! Do you know too?', '„Zašto odrasli nikada ne žele da se igraju sa mnom?“, pita se jedan radoznali dječak. Odrasli mu strpljivo objašnjavaju čime su to zauzeti po cio dan. Uskoro dječak saznaje šta rade poštari, policajci, kranisti, ljekari, pa čak i... penzioneri! A znaš li ti?', 'Забавная и мудрая книга, которая с лёгким юмором объяснит малышу, почему взрослые вечно заняты и кем они вообще работают.', 'A witty and charming peek into the busy world of grown-ups and all the curious jobs they do all day!', 'Duhovita i topla priča koja djeci na zabavan način otkriva zašto su odrasli uvijek u poslu i kakvih sve zanimanja ima.', '/covers/DP-0963.webp', '#e69c24', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real"]', '["professions","growing up","curiosity","daily life","family"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('отвечай-когда-тебя-спрашивают-964', 'DP-0964', 'Отвечай, когда тебя спрашивают', 'Answer When You''re Spoken To', 'Odgovori kad te pitaju', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', 'Ласло Ребер', 'Эксмо', NULL, NULL, 6, 16, 'middle', '"Почему ты плачешь?" "Почему ты смеёшься?" "Что ты ещё натворил?"… Как же трудно отвечать на вопросы взрослых! Ведь взрослые давно выросли и забыли, как разговаривать с детьми. Но будьте уверены: вы обязательно узнаете, как это надо делать.', '"Why are you crying?" "Why are you laughing?" "What have you done now?"… It is so hard to answer grown-ups'' endless questions! Adults grew up long ago and completely forgot how to speak with children. But don’t worry: this brilliant classic will gently remind everyone how to understand each other.', '"Zašto plačeš?" "Zašto se smiješ?" "Šta si opet napravio?"… Kako je samo teško odgovarati na pitanja odraslih! Odrasli su odavno porasli i sasvim zaboravili kako se razgovara sa djecom. Ali ne brinite: ova duhovita knjiga će vas podsjetiti kako da ponovo nađete zajednički jezik.', 'Остроумный и точный взгляд на мир взрослых глазами ребёнка — читать всей семьёй, чтобы наконец-то услышать друг друга!', 'A delightfully witty look at grown-up habits through a child''s eyes—essential reading for parents and kids trying to speak the same language!', 'Duhovit i iskren pogled na svijet odraslih dječijim očima — obavezno porodično štivo za bolje međusobno razumijevanje!', '/covers/DP-0964.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real"]', '["family","parents and kids","humor","growing up","psychology"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('радуйся-что-девочка-радуйся-чт-965', 'DP-0965', 'Радуйся, что девочка/Радуйся, что мальчик', 'Be Glad It''s a Girl / Be Glad It''s a Boy', 'Raduj se što je djevojčica / Raduj se što je dječak', 'Ева Яниковски', 'Eva Janikovszky', 'Éva Janikovszky', 'Ласло Ребер', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Будущей маме часто кажется, будто она знает, кто у нее родится. Мальчик? Поздравляем! Девчонки все плаксы и воображалы, а у вас будет защитник, сильный и смелый! Как же вам повезло! Говорите, девочка родилась? Так это замечательно! Уж она-то не подастся в автогонщики и будет всегда рядом с вами, никуда от вас не уедет, а если и уедет, то будет писать письма каждый день! И только ленивый на улице не заметит, как она прекрасна и, несомненно, похожа на вас. Ну и самое главное, она наверняка подарит вам внуков. Что вы говорите? Ей всего сутки? Ну что ж, осталось лишь немного подрасти.', 'Expectant mothers often imagine they know who will arrive. A boy? Fantastic! Girls are crybabies and show-offs, while you''ll have a brave, sturdy protector! What incredible luck! Wait, a girl arrived instead? Even better! She won''t become a reckless racecar driver, she''ll stay close, and if she moves away, she''ll write every single day. And everyone on the street will notice how gorgeous she is—a spitting image of you! Best of all, she''ll give you grandchildren. What do you mean she''s only one day old? Well, all that''s left is to grow up a little bit.', 'Buduća mama često misli da tačno zna ko će joj se roditi. Dječak? Čestitamo! Djevojčice su samo plačljivice i princeze, a vi ćete imati snažnog i hrabrog zaštitnika! Kakva sreća! Kažete, rodila se djevojčica? Pa to je prosto divno! Ona sigurno neće juriti automobilima i uvijek će biti uz vas, a ako i ode, pisaće vam svakog dana. Svi na ulici primijetiće koliko je lijepa i da nesumnjivo liči na vas. A što je najvažnije, podariće vam unuke. Šta kažete, stara je tek jedan dan? Pa dobro, ostaje samo malo da poraste.', 'Остроумный двухсторонний путеводитель по родительским надеждам, забавным стереотипам и безусловной любви к новому человеку.', 'A delightfully witty, flip-over book capturing the hilarious clichés, grand expectations, and endless tenderness of welcoming a newborn.', 'Duhovit dvostrani vodič kroz roditeljska maštanja, simpatične stereotipe i bezgraničnu ljubav prema tek rođenoj bebi.', '/covers/DP-0965.webp', '#e07a5f', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real"]', '["parenthood","family","humor","flip-book","baby"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хорошо-мне--966', 'DP-0966', 'Хорошо мне!', 'Lucky Me!', 'Baš mi je dobro!', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', 'Ласло Ребер', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Как же хочется порадовать маму, папу, бабушку, дедушку и младшую сестрёнку! И как же сложно найти то, что обрадует всех… Но мы обязательно разберёмся, кто чему рад!', 'How wonderful it is to make mom, dad, grandma, grandpa, and your little sister happy! But finding something that pleases everyone at the same time is almost impossible... Together, we''ll discover what truly brings joy to each of them!', 'Kako bi samo bilo lijepo obradovati mamu, tatu, babu, đeda i mlađu sestricu! Ali pronaći nešto što će usrećiti baš sve uopšte nije lako... Ipak, sigurno ćemo otkriti ko se čemu zapravo raduje!', 'Остроумный и тёплый взгляд на попытки угодить всем взрослым сразу: спойлер — это невозможно, но наблюдать за этим безумно весело!', 'A witty and heartwarming look at trying to please every grown-up at once: spoiler alert—it''s impossible, but trying is utterly hilarious!', 'Duhovit i topao pogled na pokušaje da udovoljite svim odraslima odjednom: spojler — nemoguće je, ali je beskrajno zabavno!', '/covers/DP-0966.webp', '#e59b2b', 'nonfiction', 'ru', 'available', 'Категория: Ева Яниковски', '["funny","real"]', '["family","humor","growing up","feelings","relationships"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('азбука-в-картинках-967', 'DP-0967', 'Азбука в картинках', 'Alphabet in Pictures', 'Azbuka u slikama', 'Александр Бенуа', 'Alexandre Benois', 'Aleksandar Benoa', '', 'Рипол КИТ', NULL, NULL, 6, 16, 'middle', 'Азбука в картинах – одна из самых знаменитых книг для детей. Изысканная графика Бенуа - до сих пор непревзойденный образец книжной иллюстрации. Каждая страница Азбуки - это удивительный, завораживающий сказочный мир. Самые первые книги в жизни ребенка непременно должны содержать красочные, красивые иллюстрации. Именно они приоткрывают для малышей дверь в волшебный мир сказок и удивительных историй, пробуждая интерес, развивая фантазию и воображение, постепенно прививая любовь к чтению. Яркие образы, созданные Бенуа, хорошо запоминаются и позволяют ребенку с большим вниманием и интересом заниматься таким сложным делом, как изучение алфавита. Современное издание Азбуки в картинах - точная копия оригинала, вышедшего в 1904 году. Книга ценна не только благодаря удивительным картинам Бенуа, но и благодаря тому, что в ней сохранены все буквы дореволюционного алфавита. Изучение Азбуки в картинах Бенуа вместе с детьми – отличный повод поговорить с ними о российской истории, начать ее подробное изучение.', 'Alexandre Benois'' ''Alphabet in Pictures'' is a legendary masterpiece of early 20th-century book illustration, originally published in 1904. Each exquisite page invites children and adults alike into an enchanting theatrical world filled with fairy-tale castles, whimsical creatures, and vivid period details. This faithful modern reprint preserves every letter of the pre-revolutionary Russian alphabet, making it not only a magnificent primer for learning letters and appreciating fine art, but also a captivating gateway into cultural history.', '„Azbuka u slikama“ Aleksandra Benoa iz 1904. godine predstavlja neprevaziđeno remek-djelo ruske književne ilustracije s početka dvadesetog vijeka. Svaka stranica krije raskošan, bajkovit svijet satkan od pozorišne magije, vitezova i začaranih predjela. Ovo izdanje vjerna je replika originala sa svim slovima predrevolucionarne azbuke, pa djeci i roditeljima nudi ne samo učenje slova kroz vanvremensku umjetnost, već i uzbudljiv prozor u istoriju i estetiku jednog prohujalog doba.', 'Этот шедевр 1904 года превращает каждую дореволюционную букву в настоящее театральное волшебство и праздник для глаз!', 'More than just an ABC primer, this 1904 treasure turns every letter into a breathtaking work of theatrical art!', 'Ovo nije samo običan bukvar, već pravo umjetničko blago iz 1904. godine koje svako slovo pretvara u pozorišnu bajku!', '/covers/DP-0967.webp', '#8c4836', 'nonfiction', 'ru', 'available', 'Категория: Азбуки', '["magic","real"]', '["alphabet","art","history","classic illustration","fairy tale"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('игра-в-слова-968', 'DP-0968', 'Игра в слова', 'Playing with Words', 'Igra riječima', 'Дарья Герасимова', 'Daria Gerasimova', 'Darja Gerasimova', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Книги Дарьи Герасимовой смешные, необычные и вместе с тем добрые и искренние. Малыш знакомится с каждой буквой через авторские иллюстрации и ритмичный белый стих, где почти в каждом слове используется изучаемая буква.', 'Daria Gerasimova’s books are funny, whimsical, and genuinely heartwarming. Young readers meet each letter of the alphabet through playful author illustrations and rhythmic blank verse, where almost every word cleverly highlights the letter being learned.', 'Knjige Darje Gerasimove su duhovite, neobične, a ujedno tople i iskrene. Mališani se upoznaju sa svakim slovom kroz autorske ilustracije i ritmičan slobodan stih, u kojem skoro svaka riječ na zabavan način ističe odabrano slovo.', 'Загляните в эту волшебную азбуку, где буквы оживают в стихах и рисунках, превращая чтение в весёлую игру!', 'Peek into this whimsical alphabet book where letters dance through verse and art, turning reading into a delightful game!', 'Zavirite u ovaj maštoviti bukvar gdje slova oživljavaju u stihovima i slikama, pretvarajući učenje u pravu igru!', '/covers/DP-0968.webp', '#e68a3c', 'nonfiction', 'ru', 'available', 'Категория: Азбуки', '["funny","magic"]', '["alphabet","poetry","wordplay","early learning","illustrations"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('такие-разные-буквы-969', 'DP-0969', 'Такие разные буквы', 'Such Different Letters', 'Tako različita slova', '', 'David Plaksin', 'David Plaksin', 'Давид Плаксин', 'Детгиз', NULL, NULL, 6, 16, 'middle', 'Художник Давид Плаксин придумал не совсем обычную азбуку. В обычной азбуке все, что нарисовано, представляют существительные. А в этой азбуке о каждой букве рассказывают имена прилагательные. Умные школьники уже в первом классе знают, что прилагательное - это часть речи, которая обозначает качество, свойство или принадлежность предметов. Вот и здесь все буквы не просто названы, они действительно обладают своими качествами и характерами, иногда неожиданными, поэтому их разглядывать и запоминать - одно удовольствие. Но главное - из слов, придуманных Давидом Плаксиным, можно составить настоящую сказочную историю про все буквы нашего алфавита.', 'Artist David Plaksin created an unusual alphabet book. While typical primers depict letters through nouns, here each letter is vividly described using adjectives. Letters aren''t just shown—they come alive with distinct personalities and quirky traits, making them a joy to explore and remember. Even better, Plaksin''s imaginative word choices can be woven into a whimsical story starring the whole alphabet.', 'Umjetnik David Plaksin osmislio je sasvim neobičnu azbuku. Dok u klasičnim bukvarima slova predstavljaju imenice, u ovoj knjizi svako slovo opisuju pridjevi. Prikazana slova ne nose samo imena već imaju stvarne osobine i neobične karaktere, pa ih je pravo uživanje posmatrati i pamtiti. A najljepše od svega je što se od ponuđenih riječi može sastaviti prava bajkovita priča o čitavoj azbuci.', 'Забудьте про скучные «А — это арбуз»: здесь каждая буква оживает благодаря выразительным прилагательным и собственному взрывному характеру!', 'Forget boring ''A is for Apple'' primers—here, every letter springs to life through quirky adjectives and a distinct personality of its own!', 'Zaboravite dosadno učenje slova – ovdje svako slovo oživljava uz živopisne pridjeve i sopstveni, jedinstveni karakter!', '/covers/DP-0969.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: Азбуки', '["funny","magic"]', '["alphabet","language","illustration","creativity","art"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('азбука-искусство-конца-xix-xx--970', 'DP-0970', 'Азбука: искусство конца XIX-XX веков', 'ABC: Art of the Late 19th and 20th Centuries', 'Azbuka: Umjetnost s kraja XIX i XX vijeka', '', 'Pushkin State Museum of Fine Arts', 'Državni muzej likovnih umjetnosti Puškin', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Тридцать три картины на каждую букву алфавита из собрания Государственного музея изобразительных искусств имени А.С.Пушкина в Москве', 'Thirty-three masterpieces for every letter of the Russian alphabet, selected from the renowned collection of the Pushkin State Museum of Fine Arts.', 'Trideset tri remek-djela za svako slovo azbuke iz čuvene zbirke Državnog muzeja likovnih umjetnosti Puškin u Moskvi.', 'Прогуляйтесь по залам музея с азбукой в руках: разглядывать буквы и одновременно влюбляться в великую живопись — сплошное вдохновение!', 'Take a museum stroll with an alphabet guide in hand: exploring letters while falling in love with iconic modern paintings is pure inspiration!', 'Prošetajte kroz muzej držeći azbuku u rukama: učenje slova uz zaljubljivanje u remek-djela slikarstva donosi pravu inspiraciju!', '/covers/DP-0970.webp', '#c4512e', 'nonfiction', 'ru', 'available', 'Категория: Азбуки', '["real"]', '["art","alphabet","museum","painting","history of art"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кротик-большая-книга-971', 'DP-0971', 'Кротик большая книга', 'The Big Book of Little Mole', 'Krtić: Velika knjiga', 'Зденек Миллер', 'Zdeněk Miler', 'Zdenjek Miler', '', 'Росмэн', NULL, NULL, 6, 16, 'middle', 'В Большой книге Кротика собраны самые любимые истории про героев: "Кротик и штанишки", "Кротик и телевизор", "Кротик и автомобильчик" и "Кротик и ракета". Книга с большим количеством иллюстраций из мультфильмов про Кротика, дополненных текстом про приключения героев – то, что нужно, чтобы маленький читатель не устал. Эту книгу можно просто рассматривать, как книжку-картинку, рассказывая вместе с ребенком свою историю про героев по иллюстрациям или же приглашать ребенка читать самостоятельно.', 'This treasury brings together beloved adventures of the classic character: Mole''s famous trousers with pockets, a television set, a little car, and even a rocket trip! Filled with the timeless, expressive illustrations from the iconic animated series, this volume is ideal for both shared picture-walks and early independent reading.', 'Ova raskošna zbirka okuplja najomiljenije priče o Krtiću: pantalone sa džepovima, televizor, mali automobil i raketu. Bogato opremljena prepoznatljivim ilustracijama iz kultnog animiranog filma, knjiga je savršena i za zajedničko maštanje uz slike i za prve samostalne čitalačke korake.', 'Легендарный обаятельный Кротик возвращается со своими синими штанишками и ракетой, чтобы подарить море ностальгии родителям и чистую радость малышам!', 'The iconic, dungaree-wearing Little Mole is back with cars, rockets, and pure childhood joy across every page!', 'Legendarni i neodoljivi Krtić se vraća sa svojim plavim pantalonama i raketom da osvoji novu generaciju malih čitalaca!', '/covers/DP-0971.webp', '#2c6ca8', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["animals","adventure","funny"]', '["little mole","classic","short stories","illustrations","cartoons"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кротик-лучшие-истории-972', 'DP-0972', 'Кротик лучшие истории', 'The Little Mole: Best Stories', 'Krtić: Najbolje priče', 'Зденек Миллер', 'Zdeněk Miler', 'Zdenjek Miler', '', 'Росмэн', NULL, NULL, 6, 16, 'middle', 'Приключения доброго, веселого Кротика, придуманного Зденеком Милером еще полвека назад, по-прежнему приводят детей в восторг. По многочисленным просьбам родителей выпускаем второй сборник, в который вошли самые лучшие истории про Кротика: "Кротик и зонтик", "Кротик и Орел" и "Как Кротик вылечил Мышку".', 'The heartwarming adventures of the cheerful Little Mole, created by Zdeněk Miler half a century ago, continue to charm young readers. Back by popular demand, this delightful volume brings together three of the most beloved tales: ''The Mole and the Umbrella'', ''The Mole and the Eagle'', and ''How the Mole Cured the Little Mouse''.', 'Topli i veseli doživljaji Krtića, junaka kojeg je Zdenjek Miler osmislio prije više od pola vijeka, i dalje oduševljavaju mališane. Ova zbirka donosi tri omiljene priče puni nježnosti i drugarstva: ''Krtić i kišobran'', ''Krtić i orao'' i ''Kako je Krtić izliječio mišića''.', 'Тот самый легендарный Кротик из нашего детства, который учит доброте, находчивости и выручке лучше любых взрослых наставлений!', 'The iconic Little Mole returns to warm our hearts with timeless lessons on kindness, curiosity, and true friendship.', 'Legendarni Krtić iz našeg djetinjstva ponovo nas uči dobroti, snalažljivosti i pravom prijateljstvu!', '/covers/DP-0972.webp', '#2c6ca7', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["animals","friends","funny"]', '["mole","friendship","classics","forest animals","kindness"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приключения-бабара-973', 'DP-0973', 'Приключения Бабара', 'The Adventures of Babar', 'Babarove avanture', 'Жан де Брюнофф', 'Jean de Brunhoff', 'Žan de Brenof', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Знакомьтесь, этого слона в зелёном костюме зовут Бабар. Французский писатель и иллюстратор Жан де Брюнофф придумал его в 1931 году, и с тех пор Бабар стал одним из самых любимых и известных персонажей по всему миру. Книги про него были переведены на 17 языков, по ним были сняты мультсериалы и анимационные фильмы. В эту книгу вошли истории о невероятных событиях в жизни Бабара. Он попадает в большой город, путешествует на воздушном шаре, плавает на спине кита в открытом море, строит прекрасный город для слонов в джунглях и попадает в дом Деда Мороза! Читайте о всех увлекательных приключениях слонёнка Бабара в этой книге!', 'Meet Babar, the world-famous elephant in the dapper green suit! Created in 1931 by French author and illustrator Jean de Brunhoff, Babar has charmed generations of readers worldwide. This collection brings together his most thrilling escapades: navigating life in the big city, drifting in a hot-air balloon, riding a whale across the ocean, founding a splendid elephant city in the jungle, and even visiting Santa Claus!', 'Upoznajte Babara, najpoznatijeg slona u elegantnom zelenom odijelu! Francuski pisac i ilustrator Žan de Brenof stvorio ga je još 1931. godine, a Babar je od tada osvojio srca djece širom planete. Ova knjiga okuplja njegove najuzbudljivije podvige: od snalaženja u velegradu i letenja balonom, do plovidbe na leđima kita, izgradnje čudesnog grada za slonove u džungli i susreta s Djeda Mrazom!', 'Самый элегантный слон на свете докажет, что жажда приключений и безупречный зелёный костюм созданы друг для друга!', 'The world''s most dapper elephant proves that grand adventures and an immaculate green suit are an unbeatable match!', 'Najelegantniji slon na svijetu dokazaće vam da su velike avanture i otmjeno zeleno odijelo savršen par!', '/covers/DP-0973.webp', '#2e7d32', 'nonfiction', 'ru', 'available', 'Для детей до 3 лет, текст для чтения взрослыми детям.', '["adventure","animals","funny"]', '["elephants","classic tales","travel","kindness","france"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чудесное-путешествие-нильса-с--974', 'DP-0974', 'Чудесное путешествие Нильса с дикими гусями', 'The Wonderful Adventures of Nils', 'Čudesno putovanje Nilsa sa divljim guskama', 'Сельма Лагерлеф', 'Selma Lagerlöf', 'Selma Lagerlef', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Однажды мальчишка Нильс решил пошутить над гномом, и стал маленьким. Его путешествие со стаей гусей описаны Сельмой Лагерлёф и проиллюстрирована Е. Мешковым. Знаменитая сказка шведской писательницы, лауреата Нобелевской премии не только развивает воображение малышей, но и в увлекательной, волшебной, нескучной форме даёт им знания о зоологии и географии. Крупный текст, ударения в словах, полное соответствие требованиям САНПИН. Учиться читать так интересно!', 'When mischievous boy Nils plays a prank on a gnome, he is magically shrunk down to tiny size! Taking to the skies on the back of a farm goose with a flock of wild travelers, he embarks on an unforgettable journey. Selma Lagerlöf''s Nobel Prize-winning masterpiece effortlessly weaves geography, wildlife, and folklore into an inspiring tale of kindness and courage.', 'Kada se nestašni dječak Nils našali sa šumskim patuljkom, biva magično smanjen na veličinu palca! Leteći na leđima gusana u jatu divljih ptica, Nils kreće na nevjerovatno putovanje kroz predivne predjele. Remek-djelo švedske nobelovke Selme Lagerlef na divan način spaja geografiju, životinjski svijet i toplu priču o prijateljstvu i odrastanju.', 'Никогда не дразните гномов, иначе придётся облететь полмира на спине домашнего гуся — хотя, признаться честно, это лучшее приключение на свете!', 'Never tease a gnome, or you might find yourself seeing the world from the feather-soft back of a flying goose!', 'Nikada ne zadirkujte patuljke, inače biste mogli završiti leteći preko pola svijeta na leđima gusana!', '/covers/DP-0974.webp', '#4b86b4', 'nonfiction', 'ru', 'available', 'книга с крупными буквами для первого самостоятельного чтения | книги с очень крупными буквами и ударениями для первого самостоятельного чтения', '["adventure","magic","animals"]', '["journey","birds","classic","nature","geography"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дагфрид-девочка-без-завитушек--975', 'DP-0975', 'Дагфрид. Девочка без завитушек над ушами', 'Dagfrid: A Viking Girl Without Pastry Buns', 'Dagfrid: Djevojčica bez uvojaka', 'Аньес Матьё-Доде', 'Agnès Mathieu-Daudé', 'Anjes Matje-Dode', 'Оливье Таллек', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Многое в собственной жизни удручает Дагфрид. Одно имя чего стоит! Да и в остальном участь девочки-викинга счастливой не назовёшь: приходится заплетать волосы в косы и укладывать их в завитушки над ушами, носить платья до пят и вялить рыбу, единственную пищу викингов. А ещё девочкам не разрешают выходить в море и открывать Америку! Но вечно так продолжаться не могло. Настал день, когда рыба вконец опротивела Дагфрид...', 'Lots of things annoy Dagfrid about Viking life. For starters, her ridiculous name! Not to mention having to style hair into silly pastry buns over her ears, wearing floor-length dresses, and eating dried fish morning, noon, and night. Worst of all: girls aren''t allowed to sail off and discover America! But one fine day, Dagfrid decides she''s had enough of dried fish and boring traditions.', 'Mnogo toga nervira Dagfrid u životu Vikinga. Za početak, njeno sopstveno ime! A i sve ostalo: nošenje teških pletenica smotanih u pužiće preko ušiju, preduge haljine i sušena riba za svaki obrok. Povrh svega, djevojčicama nije dozvoljeno da plove morima i otkrivaju Ameriku! Ali kucnuo je čas kada je Dagfrid riješila da uzme kormilo u svoje ruke.', 'Задорная и дерзкая история о девочке-викинге, которая категорически отказывается сушить рыбу, когда можно открывать новые земли!', 'A witty and rebellious tale of a Viking girl who refuses to dry smelly fish when there is a whole wide world to discover!', 'Duhovita i odvažna priča o vikinškoj djevojčici koja odbija da suši ribu dok je pučina zove na velika otkrića!', '/covers/DP-0975.webp', '#d96b43', 'nonfiction', 'ru', 'available', '?', '["funny","adventure"]', '["vikings","humor","brave girls","rebellion","sea journey"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('саша-и-маша-1-976', 'DP-0976', 'Саша и Маша 1', 'Jip and Janneke 1', 'Saša i Maša 1', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Ani M.G. Šmit', 'Фип Вестендорп', 'Захаров', NULL, NULL, 6, 16, 'middle', 'Вы - молодцы! Вы купили замечательную книжку! И очень знаменитую. В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешные и интересные истории про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке... Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г.Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ганса Христиана Андерсена. Мы надеемся, что книжка про Сашу и Машу вам понравится. И не расстраивайтесь, что она так быстро закончилась, - мы приготовили для вас еще много смешных приключений этих детей. Не успеете вы дочитать одну книжку, как в магазинах появится следующая!', 'Meet two inseparable next-door neighbors in this beloved Dutch classic! Sasha and Masha (originally Jip and Janneke) turn ordinary childhood everyday moments into sparkling adventures, exploring gardens, meeting friendly animals, and sharing innocent mischief. Written by the Hans Christian Andersen Award winner Annie M.G. Schmidt, these bite-sized stories are perfect for reading together.', 'Upoznajte dvoje nerazdvojnih komšija u ovom omiljenom holandskom klasiku! Saša i Maša (u originalu Jip i Janecke) pretvaraju obične dječje dane u blistave avanture, istražujući dvorište, družeći se sa životinjama i dijeleći nestašluke. Napisane perom dobitnice Andersenove nagrade Ani M.G. Šmit, ove tople kratke priče idealne su za prvo samostalno čitanje ili porodično uživanje pred spavanje.', 'Уютные, смешные и очень жизненные истории о дружбе мальчика и девочки, в которых каждый узнает своё детство.', 'Heartwarming, hilarious, and utterly relatable—these timeless tales capture the pure joy of childhood friendship in every little daily wonder.', 'Tople, duhovite i nevjerovatno stvarne priče o prijateljstvu u kojima će svako dijete prepoznati svoje svakodnevne nestašluke.', '/covers/DP-0976.webp', '#d63031', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","friends","real"]', '["everyday adventures","childhood","friendship","short stories","classic"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('саша-и-маша-2-977', 'DP-0977', 'Саша и Маша 2', 'Jip and Janneke: Book 2', 'Saša i Maša 2', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Annie M.G. Schmidt', 'Фип Вестендорп', 'Захаров', NULL, NULL, 6, 16, 'middle', 'В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешных и интересных историй про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке… Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г. Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ханса Кристиана Андерсена.', 'In the Netherlands, there isn''t a child or parent who doesn''t adore the mischievous adventures of Jip and Janneke (known in Russian as Sasha and Masha). Written by Hans Christian Andersen Award winner Annie M.G. Schmidt, these witty, true-to-life mini-stories celebrate the simple joys and everyday discoveries of childhood.', 'U Holandiji ne postoji dijete ni roditelj koji ne voli smiješne i tople priče o Jipu i Janneke (kod nas poznatima kao Saša i Maša). Ove divne, iskrene i zabavne crtice iz svakodnevnog djetinjstva napisala je Annie M.G. Schmidt, najpoznatija holandska autorka za djecu i dobitnica prestižne Andersenove nagrade.', 'Уютные и смешные истории про двух неразлучных соседей, в которых каждый ребёнок непременно узнает свои собственные проделки!', 'Cozy, charming, and bite-sized everyday tales about two inseparable neighbors that will make any child giggle with recognition!', 'Najtoplije kratke pričice o dvoje nerazdvojnih komšija u kojima će svako dijete odmah prepoznati sebe i svoje nestašluke!', '/covers/DP-0977.webp', '#e04a3f', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["friends","funny","real"]', '["friendship","childhood","short stories","everyday life","humor"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('саша-и-маша-3-978', 'DP-0978', 'Саша и Маша 3', 'Sasha and Masha 3', 'Saša i Maša 3', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Annie M.G. Schmidt', 'Фип Вестендорп', 'Захаров', NULL, NULL, 6, 16, 'middle', 'В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешных и интересных историй про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке… Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г. Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ганса Христиана Андерсена.', 'In the Netherlands, every child and parent knows and adores the sweet, witty everyday adventures of Jip and Janneke, affectionately adapted here as Sasha and Masha. Penned by Hans Christian Andersen Award winner Annie M.G. Schmidt, this third collection is brimming with playful antics, backyard curiosity, and the heartwarming reality of best friends exploring the world together.', 'U Holandiji ne postoji roditelj ni dijete koje ne obožava tople i duhovite dogodovštine nerazdvojnih komšija Jipa i Janneke (u ovom izdanju Saše i Maše). Iz pera legendarne autorke Ani M. G. Šmit, dobitnice Andersenove medalje, stiže treća zbirka priča prepuna bezbrižne igre, nestašluka i dragocjenih trenutaka pravog djetinjstva.', 'Идеальные короткие рассказы для первого чтения или уютного вечера перед сном, где самые простые детские шалости превращаются в чистое счастье!', 'Delightfully cozy and bite-sized stories that turn ordinary backyard play and toddler mischief into pure, timeless joy!', 'Savršene kratke priče za čitanje pred spavanje koje svaki običan dječji dan i dvorišnu igru pretvaraju u čistu radost!', '/covers/DP-0978.webp', '#2c7a7b', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["funny","friends","real"]', '["friendship","childhood","short stories","bedtime reading","dutch classic"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('саша-и-маша-4-979', 'DP-0979', 'Саша и Маша 4', 'Jip and Janneke 4', 'Saša i Maša 4', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Ani M. G. Šmit', 'Фип Вестендорп', 'Захаров', NULL, NULL, 6, 16, 'middle', 'В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешных и интересных историй про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке… Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г. Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ганса Христиана Андерсена.', 'The fourth volume of charming everyday tales about two inseparable next-door friends, originally known across the Netherlands as Jip and Janneke. Written by the beloved Hans Christian Andersen Award winner Annie M.G. Schmidt, these witty, bite-sized stories capture the sheer wonder and humor of childhood adventures.', 'Četvrta knjiga toplih i duhovitih priča o dvoje nerazdvojnih malih komšija, u Holandiji poznatih kao Jip i Janneke. Iz pera dobitnice Andersenove nagrade Ani M. G. Šmit, ove kratke zgode na divan i jednostavan način oživljavaju svakodnevna čuda, nestašluke i iskreno dječje prijateljstvo.', 'Уютные, добрые и невероятно смешные истории о двух неразлучных друзьях, которые превращают самый обычный день в весёлое открытие!', 'Cozy, humorous, and heartwarming little adventures of two best friends next door who find wonder in every single day.', 'Tople, bezbrižne i beskrajno šarmantne zgode dvoje komšija koji svaki običan dan pretvaraju u veselu avanturu.', '/covers/DP-0979.webp', '#e26a2c', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["friends","funny","real"]', '["friendship","everyday adventures","short stories","dutch literature","neighborhood"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('люди-и-разбойники-из-кардамона-980', 'DP-0980', 'Люди и разбойники из Кардамона', 'When the Robbers Came to Cardamom Town', 'Ljudi i razbojnici iz Kardamoma', 'Турбьерн Эгнер', 'Thorbjørn Egner', 'Torbjern Egner', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Не во всяком городке можно встретить ручного льва, говорящего верблюда и самого доброго в мире полицмейстера. Но в Кардамоне с ними может познакомиться каждый. Кроме того, жители городка без билета катаются на двухэтажном трамвае, где поют песни и едят ароматные пряники. Правда, иногда в Кардамон наведываются разбойники, но от этого жизнь там становится только интереснее! Книга впервые появилась в СССР в 1956 году и с тех пор пользуется огромной популярностью. Изначально книга была опубликована в Норвегии с иллюстрациями и нотами самого автора - они сохранены в новом издании.', 'Not every town is home to a pet lion, a singing camel, and the friendliest police chief in the world, but in Cardamom Town you will meet them all! Citizens ride double-decker trams for free, sing songs, and snack on warm gingerbread. Occasionally, three clumsy robbers drop in to steal what they need, but even trouble in Cardamom Town turns into delightful fun. Complete with the author''s original charming illustrations and sheet music.', 'Ne možete u svakom gradiću sresti pitomog lava, kamilu koja pjeva i najljubaznijeg policajca na svijetu, ali u Kardamomu je sve to dio svakodnevice! Mještani se besplatno voze tramvajem na sprat, pjevaju vesele pjesme i uživaju u medenjacima. Ponekad u grad svrate tri smotana razbojnika, ali to život čini samo još zabavnijim. Knjiga sadrži originalne autorove ilustracije i note za pjesmice.', 'Уютная скандинавская классика с песнями и нотами, где даже самые отпетые разбойники перевоспитываются добротой и чистотой!', 'A wonderfully cheerful Scandinavian classic packed with songs, where even the most hopeless robbers are reformed by kindness and a warm bath!', 'Predivna i topla skandinavska bajka sa notama i pjesmicama, u kojoj čak i razbojnici postaju bolji ljudi uz malo ljubaznosti!', '/covers/DP-0980.webp', '#d97438', 'nonfiction', 'ru', 'available', 'Для детей среднего школьного возраста.', '["funny","adventure","friends"]', '["norwegian classic","robbers","lion","music and songs","cozy town"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вертихвост-981', 'DP-0981', 'Вертихвост', 'Claus Climbermouse and the Other Animals in the Huckybucky Forest', 'Penjalica i ostale životinje iz Hakebake šume', 'Турбьерн Эгнер', 'Thorbjørn Egner', 'Turbjern Egner', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Мышонок Мортен в своём лесу Пригорок-Сорок-норок был меньше всех. Серенький пшик с хвостом, да и только. Зато парень он был хороший, трудился честно, прилежно и в чужую жизнь не лез. Вот бы, думал мышонок, все брали пример с меня и никого не обижали. К сожалению, пока что это не так. Но Мортен знает, как исправить дело! Настоящее издание представляет собой новый полный перевод книги Турбьёрна Эгнера, ранее выходившей под названием "Приключения в лесу Ёлки-на-Горке".', 'Morten the Forest Mouse might be small, but he has big dreams: what if all the woodland creatures lived in harmony and agreed never to eat each other? Together with his carefree, guitar-strumming friend Claus Climbermouse, Morten drafts a law that turns the entire forest upside down. A delightful, witty Norwegian classic full of humor, catchy spirit, and woodland wisdom.', 'Mišić Morten je najmanji stanovnik šume, ali ima veliku želju: da niko nikoga ne dira i da svi žive u miru! Uz pomoć raspjevanog veseljaka Penjalice, Morten pokušava da uspostavi šumski zakon prijateljstva. Ova topla i duhovita norveška klasična priča podsjeća nas da i najmanji mogu napraviti veliku razliku.', 'Мудрая и уморительно добрая норвежская сказка о том, как маленькие мышата научили весь лес жить дружно и не есть соседей!', 'A charming and wonderfully witty classic showing that even the smallest mouse can teach a whole forest how to live in peace!', 'Šarmantna i beskrajno duhovita priča o tome kako jedan mali miš može naučiti cijelu šumu slozi i prijateljstvu!', '/covers/DP-0981.webp', '#618b4a', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["funny","animals","friends"]', '["forest animals","mice","friendship","norwegian classic","kindness"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кариус-и-бактериус-982', 'DP-0982', 'Кариус и Бактериус', 'Karius and Baktus', 'Karijus i Baktus', 'Турбьерн Эгнер', 'Thorbjørn Egner', 'Turbjern Egner', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Эта история приключилась с мальчиком Йенсом, который обожал сладости, но очень не любил чистить зубы. Маленькие человечки построили два уютных дома у него во рту. Как вы думаете, каково было Йенсу? Для детей дошкольного возраста.', 'This tale happened to little Jens, who adored sweets but utterly disliked brushing his teeth. Two tiny tooth trolls made themselves cozy homes right inside his mouth, chipping away day and night. How do you think Jens felt? A timeless Nordic classic about dental hygiene.', 'Ova priča se desila dječaku Jensu koji je obožavao slatkiše, ali nikako nije volio da pere zube. Dva sićušna zubna vragolana sagradila su udobne domove pravo u njegovim ustima. Šta mislite, kako je bilo Jensu? Bezvremenska priča o pranju zuba za najmlađe.', 'Весёлая и поучительная классика, после которой дети сами с радостью бегут за зубной щёткой!', 'A legendary Scandinavian classic that turns tooth brushing from a daily battle into a hilarious rescue mission!', 'Duhovita i poučna priča poslije koje djeca sama sa osmijehom trče po četkicu za zube!', '/covers/DP-0982.webp', '#2d8898', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["funny","real"]', '["teeth","hygiene","health","habits","classic"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('папа-мама-8-детей-и-грузовик-983', 'DP-0983', 'Папа, мама, 8 детей и грузовик', 'Eight Children and a Truck', 'Tata, mama, osmoro djece i kamion', 'Анне Вестли', 'Anne-Cath. Vestly', 'Ane-Kat. Vestli', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Увлекательные повести о дружном и веселом семействе, в котором ни минуты не бывает тихо, потому что Марен любит танцевать, Мартин - прыгать, Мадс - стучать, Мона - петь, Милли - бить в барабан, Мина - вопить, а Малышка Мортен - колотить чем попало по всему, до чего только дотянется. Жить такой большой семьей, конечно, не просто, но зато тут никто никогда и не скучает. Норвежская писательница Анне-Катарина Вестли, придумавшая истории про дом, где растут сразу восемь мальчиков и девочек, популярна во всей Европе, наверное, не меньше, чем знаменитая Астрид Линдгрен. Герои ее книг - люди простые, но очень симпатичные: добрые, честные, трудолюбивые. Взрослые здесь не теряют умения относиться с юмором к себе самим и друг к другу, какие бы уроки ни преподносила им жизнь. А главное, они удивительно хорошо понимают своих детей и сохраняют это понимание, что бы те ни натворили и что бы еще ни напридумывали.', 'Delightful and heartwarming tales about a vibrant Norwegian family where it''s never quiet: Maren dances, Martin jumps, Mads bangs on pots, Mona sings, and little Morten clatters with anything he can reach. Living in a small city apartment with eight children and one faithful green truck isn''t easy, but with immense love, resilience, and humor, this unforgettable family turns every ordinary day into a joyful adventure.', 'Divne i tople priče o složnoj i bučnoj norveškoj porodici u kojoj nikada nije tiho: Maren voli da pleše, Martin da skače, Mads da lupa, Mona da pjeva, a mali Morten da zvecka čime god stigne. Život s osmoro djece u malom gradskom stanu i jednim vjernim kamionom nije lak, ali uz bezgraničnu ljubav, razumijevanje i vedar duh, ova porodica svaku svakodnevnu prepreku pretvara u pravu avanturu.', 'Самая уютная и жизнерадостная семейная сага на свете, после которой в любом доме становится чуточку теплее и веселее.', 'The coziest and most uplifting family classic around, proving that love and laughter can easily fit into any home, no matter how crowded!', 'Najtoplija i najvedrija porodična priča na svijetu, koja dokazuje da uz malo ljubavi i smijeha u svakom domu ima mjesta za sve!', '/covers/DP-0983.webp', '#2d8a56', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["funny","real","friends"]', '["family","siblings","scandinavian classic","humor","everyday life"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-подарок-антона-984', 'DP-0984', 'Маленький подарок Антона', 'Anton''s Little Gift', 'Antonov mali poklon', 'Анне Вестли', 'Anne-Cath. Vestly', 'Ane-Kat. Vestli', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Помните замечательную книжку про "Папу, маму, бабушку, восемь детей и грузовик"? Ну так вот: теперь у вас в руках новый сборник увлекательных повестей о дружном и веселом семействе, в котором ни минуты не бывает тихо, потому что Марен любит танцевать, Мартин - прыгать, Мадс - стучать, Мона - петь, Милли - бить в барабан, Мина - вопить, а Малышка Мортен - колотить чем попало по всему, до чего только дотянется. Жить такой большой семьей, конечно, не просто, но зато тут никто никогда и не скучает. Норвежская писательница Анне-Катарина Вестли, придумавшая истории про дом, где растут сразу восемь мальчиков и девочек, популярна во всей Европе, наверное, не меньше, чем знаменитая Астрид Линдгрен. Герои ее книг - люди простые, но очень симпатичные: добрые, честные, трудолюбивые. Взрослые здесь не теряют умения относиться с юмором к себе самим и друг к другу, какие бы уроки ни преподносила им жизнь. А главное, они удивительно хорошо понимают своих детей и сохраняют это понимание, что бы те ни натворили и что бы еще ни напридумывали.', 'Meet again the bustling, lovable family from Norway: Mom, Dad, Grandma, eight children, and a trusty truck! With Maren dancing, Martin jumping, and little Morten drumming on anything he can reach, it is never quiet in this household. Yet, this heartwarming collection of stories proves that unconditional love, warm humor, and genuine understanding turn everyday chaos into a true adventure.', 'Upoznajte ponovo veselu i bučnu norvešku porodicu: mamu, tatu, baku, osmoro djece i njihov kamion! Dok Maren pleše, Martin skače, a mali Morten lupa u sve što dohvati, u ovoj kući nikada nema tišine. Ipak, ova topla zbirka priča podsjeća nas na to da dobrota, vedar duh i bezuslovna podrška pretvaraju svakodnevni haos u pravu porodičnu sreću.', 'Уютная и добрая классика, после которой любой домашний кавардак покажется сущей ерундой и чистым счастьем!', 'A delightfully cozy Scandinavian classic that makes everyday family chaos feel like pure joy!', 'Predivna skandinavska priča uz koju svaki porodični haos postaje izvor čiste radosti i smijeha!', '/covers/DP-0984.webp', '#e28743', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["funny","real","friends"]', '["family","humor","norway","classic","kindness"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мах-и-шебестова-путешествуют-985', 'DP-0985', 'Мах и Шебестова путешествуют', 'Mach and Šebestová on Their Travels', 'Mah i Šebestova putuju svijetom', 'Милош Мацуорек', 'Miloš Macourek', 'Miloš Macourek', 'Адольф Борн', 'Мелик-Пашаев', NULL, NULL, 6, 16, 'middle', 'Смешной мальчишка в круглых очках и девчонка с большим бантом, а также их верный друг пёс Йонатан родом из Чехии, где их имена известны чуть ли не каждому жителю страны. И в этом нет ничего удивительного, ведь мультфильмы и книги о приключениях этой троицы начали выходить в Чехии с 1982 года и принесли главным героям огромнейшую популярность и всенародную любовь. Мах и Шебестова - самые обычные ученики начальной школы. Они учатся в одном классе, живут в одном подъезде и любят в свободное от уроков время играть с соседским псом по имени Йонатан. Правда, в распоряжении Маха и Шебестовой есть один необычный предмет - волшебная телефонная трубка, исполняющая любые желания того, кто в неё говорит (о том, как трубка попала в руки детей можно узнать из книги "Мах и Шебестова - волшебники из 3 "Б"). На этот раз Маху и Шебестовой предстоит головокружительное путешествие по всему земному шару. Волшебная трубка помогает друзьям переместиться то в Париж, то на Северный полюс, то в Перу, то в Африканскую деревню, то в Австралию, то в Голливуд, то на Гавайские острова - и повсюду их ждут удивительные приключения. Что самое интересное, Маху и Шебестововой никогда не приходит в голову воспользоваться трубкой ради собственной выгоды. Они прибегают к ее помощи исключительно ради того, чтобы выручить из беды кого-то из своих друзей, а то и вовсе незнакомых им людей, то есть ведут себя как настоящие супергерои! Для детей младшего школьного возраста.', 'Mach, Šebestová, and their clever dog Jonatan are Czech children''s literature legends! Armed with a magical telephone receiver that grants any wish, this daring trio embarks on a whirlwind journey across the globe—from Paris and the North Pole to Peru, Africa, and Hawaii. Best of all, they never use their magic receiver for selfish whims; instead, they dash across continents to lend a helping hand, proving that kind hearts make true superheroes.', 'Mah, Šebestova i njihov vjerni pas Jonatan omiljeni su junaci češke dječje književnosti! Naoružana čarobnom telefonskom slušalicom koja ispunjava svaku želju, ova nerazdvojna trojka kreće na uzbudljivo putovanje oko svijeta — od Pariza i Sjevernog pola do Perua, Afrike i Havaja. Najljepše od svega je što čaroliju nikada ne koriste iz sebičnosti, već da pomognu onima u nevolji, baš poput pravih malih superheroja.', 'Просто наберите номер на волшебной телефонной трубке — и вот вы уже спасаете друзей на Гавайях или гостите на Северном полюсе!', 'Just whisper into the magic telephone receiver, and you''re whisked away from Paris to the North Pole on the funniest rescue mission ever!', 'Samo šapnite želju u čarobnu telefonsku slušalicu i poletite od Pariza do Sjevernog pola u najsmješnijoj avanturi ikada!', '/covers/DP-0985.webp', '#3b82c4', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["adventure","funny","magic"]', '["travel","friendship","czech classics","magic object","dogs"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('налле-лапсон-986', 'DP-0986', 'Налле Лапсон', 'Nalle Lapson', 'Nale Lapson', 'Йоста Кнутсон', 'Gösta Knutsson', 'Jesta Knutson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Налле Лапсона придумал шведский писатель, переводчик и режиссер Йоста Ларс Август Кнутсон (1908-1973) в 1949 году. Налле Лапсон - маленький медвежонок с глазами-бусинками, проснувшись от зимней спячки, не нашел свою маму и отправился в путешествие. Медвежонка ждет множество приключений, он находит настоящих друзей - девочку Лотту и собаку Тяпку, учится читать и считать, путешествует на автомобиле. В Швеции Налле Лапсон так же знаменит, как Винни-Пух и Паддингтон. Это первая книга, в которой медвежонок знакомится со своей подружкой Лоттой.', 'Created in 1949 by celebrated Swedish author Gösta Knutsson, Nalle Lapson is Sweden''s beloved equivalent to Winnie-the-Pooh and Paddington. Waking from his winter hibernation to find his mother gone, this little button-eyed bear cub ventures out into the wide world. A heartwarming journey begins as he learns to read, count, rides in a car, and finds true friends in a kind girl named Lotta and her cheerful puppy.', 'Nale Lapson, kog je 1949. godine stvorio poznati švedski pisac Jesta Knutson, u Švedskoj je omiljen baš kao Vini Pu ili Medvjedić Padington. Mali medvjedić sa očima poput perlica budi se iz zimskog sna, shvata da mu nema mame i hrabro kreće u svijet. Na tom putu upoznaje djevojčicu Lotu i psa Tjapku, uči da čita i broji, vozi se u autu i doživljava pregršt divnih avantura.', 'Если вы обожаете Винни-Пуха и Паддингтона, обязательно познакомьтесь с их обаятельным шведским кузеном — любопытным медвежонком Налле!', 'If you love Winnie-the-Pooh and Paddington, you will fall in love with their charming Swedish cousin—the curious bear cub Nalle!', 'Ako volite Vinija Pua i Padingtona, obavezno upoznajte njihovog neodoljivog švedskog rođaka — radoznalog medvjedića Nalea!', '/covers/DP-0986.webp', '#c87d3a', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["animals","friends","adventure"]', '["bears","friendship","scandinavian literature","growing up","classics"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('налле-лапсон-берется-за-дело-987', 'DP-0987', 'Налле Лапсон берется за дело', 'Nalle Lapson Takes Charge', 'Nale Lapson se baca na posao', 'Йоста Кнутсон', 'Gösta Knutsson', 'Jesta Knutson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Налле Лапсона придумал шведский писатель, переводчик и режиссер Йоста Ларс Август Кнутсон (1908-1973) в 1949 году. Налле Лапсон - маленький медвежонок с глазами-бусинками, проснувшись от зимней спячки, не нашел свою маму и отправился в путешествие. Медвежонка ждет множество приключений, он находит настоящих друзей - девочку Лотту и собаку Тяпку, учится читать и считать, путешествует на автомобиле. В Швеции Налле Лапсон так же знаменит, как Винни-Пух и Паддингтон. Это вторая книга, в которой Налле Лапсон ловит вора.', 'Created in 1949 by beloved Swedish storyteller Gösta Knutsson, Nalle Lapson is a tiny bear cub with button eyes who ventures out into the world and finds true friends in a kind girl named Lotta and her puppy. Just as famous in Sweden as Winnie-the-Pooh or Paddington, Nalle learns to read, count, rides in cars, and gets into all kinds of charming scrapes. In this delightful second book, our plucky little bear turns detective to catch a thief!', 'Nala Lapsona je 1949. godine stvorio omiljeni švedski pisac Jesta Knutson. Nale Lapson je mali medvjedić sa očima poput perlica koji se nakon zimskog sna otisnuo u svijet i stekao prave prijatelje — djevojčicu Lotu i psića Tjapku. U Švedskoj podjednako voljen kao Vini Pu i Padington, Nale uči da čita, računa i vozi se automobilom. U ovoj drugoj knjizi, hrabri i snalažljivi medvjedić preuzima ulogu pravog detektiva kako bi uhvatio lopova!', 'Познакомьтесь со шведским кузеном Винни-Пуха и Паддингтона — этот сообразительный медвежонок раскроет любое дело!', 'Meet the Swedish cousin of Winnie-the-Pooh and Paddington — this clever little bear cub is ready to crack any case!', 'Upoznajte švedskog rođaka Vinija Pua i Padingtona — ovaj bistri mali medvjedić spreman je da riješi svaku zagonetku!', '/covers/DP-0987.webp', '#c87d2a', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["adventure","animals","friends"]', '["bears","detective","friendship","classic","swedish literature"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('налле-лапсон-и-тяпка-988', 'DP-0988', 'Налле Лапсон и Тяпка', 'Nalle Lufs and Skrutten', 'Nale Lapson i Tjapka', 'Йоста Кнутсон', 'Gösta Knutsson', 'Jesta Knutson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Налле Лапсона придумал шведский писатель, переводчик и режиссер Йоста Ларе Август Кнутсон (1908-1973) в 1949 году. Налле Лапсон - маленький медвежонок с глазами-бусинками, проснувшись от зимней спячки, не нашел свою маму и отправился в путешествие. Медвежонка ждет множество приключений, он находит настоящих друзей - девочку Лотту и собаку Тяпку, учится читать и считать, путешествует на автомобиле. В Швеции Налле Лапсон так же знаменит, как Винни-Пух и Паддингтон. Это третья книга, в которой Налле Лапсон отправляется в путешествие со своим другом Тяпкой.', 'Created in 1949 by beloved Swedish author Gösta Knutsson, Nalle Lufs is an adorable bear cub with button eyes who sets off into the wide world after waking from hibernation. In this third installment of Sweden''s cherished classic, little Nalle continues his travels with his devoted canine companion Skrutten, learning about the world and discovering the true meaning of friendship.', 'Nale Lapson je ljupki mali medvjedić očiju poput perlica, kojeg je 1949. godine osmislio čuveni švedski pisac Jesta Knutson. Probudivši se iz zimskog sna, Nale kreće u potragu za svijetom, stiče prave prijatelje i uči važne lekcije. U ovoj trećoj knjizi, omiljeni švedski meda kreće na novo uzbudljivo putovanje sa svojim nerazdvojnim drugom, psom Tjapkom.', 'Очаровательный шведский мишка Налле ничуть не уступает Паддингтону — вас ждут добрые дорожные приключения, уютная дружба и море собачьих восторгов!', 'Meet Sweden''s darling cousin to Paddington: a delightfully polite bear cub whose gentle road-trip escapades will warm the whole family''s heart!', 'Upoznajte švedskog rođaka medvjedića Padingtona: topla i vesela avantura na točkovima koja će izmamiti najširi osmijeh!', '/covers/DP-0988.webp', '#e59b2b', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["adventure","friends","animals"]', '["bears","dogs","friendship","travel","swedish classic"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('адольфус-типс-и-ее-невероятная-989', 'DP-0989', 'Адольфус Типс и ее невероятная история', 'The Amazing Story of Adolphus Tips', 'Nevjerovatna priča o Adolfus Tips', 'Майкл Морпурго', 'Michael Morpurgo', 'Majkl Morpurgo', '', 'Азбука', NULL, NULL, 6, 16, 'middle', '«Адольфус Типс и ее невероятная история» погружает читателя в трудные будни прибрежной английской деревушки, которая в годы Второй мировой войны оказалась в зоне размещения союзных войск. Семья Лили вынуждена покинуть родную ферму, но девочка не может оставить на произвол судьбы свою любимицу – своенравную серую кошку. За эти месяцы изгнания Лили обретет дружбу, которая продлится долгие десятилетия, а кошка обзаведется звучным именем – Адольфус Типс.', 'Set in a coastal English village during World War II, Lily''s family is evacuated to make way for Allied military rehearsals. Heartbroken at leaving behind her beloved, feisty cat, Lily embarks on a journey of quiet courage, unexpected lifelong friendships with American soldiers, and a stubborn cat named Adolphus Tips who refuses to obey human war plans.', 'Smještena u priobalno englesko selo tokom Drugog svjetskog rata, ova dirljiva priča prati Lili i njenu porodicu koji moraju napustiti farmu zbog vježbi savezničkih vojnika. Ipak, Lili ne može da se pomiri sa gubitkom svoje svojoglave mačke. Tokom mjeseci izgnanstva, ona pronalazi prijateljstvo za cijeli život, a mačka dobija slavno ime — Adolfus Tips.', 'Трогательная историческая повесть о том, что даже когда мир вокруг переворачивается с ног на голову, кошачье упрямство и верная дружба способны спасти надежду.', 'A deeply touching wartime tale proving that even when the world turns upside down, feline stubbornness and true friendship can conquer all.', 'Dirljiva ratna priča koja pokazuje da, čak i kad se čitav svijet okrene naopačke, mačja svojeglavost i pravo prijateljstvo mogu sačuvati nadu.', '/covers/DP-0989.webp', '#536b5c', 'nonfiction', 'ru', 'available', 'в 20 коробке', '["real","animals","friends"]', '["cats","world war ii","friendship","history","family"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('орел-на-снегу-990', 'DP-0990', 'Орел на снегу', 'An Eagle in the Snow', 'Orao na snijegu', 'Майкл Морпурго', 'Michael Morpurgo', 'Majkl Morpurgo', '', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Когда-то, сражаясь на полях Первой мировой войны, Билли Барни поступил по совести и проявил милосердие к врагу. Но его благородный поступок обернулся трагедией для всего мира. И пока еще не стало слишком поздно, он должен исправить свою ошибку, искоренить зло. У него просто нет выбора…', 'During the brutal trench warfare of World War I, soldier Billy Byron spared the life of an injured young enemy out of sheer mercy. Years later, he discovers with horror that the young soldier he saved was Adolf Hitler. Plagued by guilt and driven by conscience, Billy sets out on an impossible, daring mission to undo his fateful choice before the world is consumed by fire.', 'Tokom Prvog svjetskog rata, vojnik Bili Barni poštedio je život ranjenom neprijatelju vođen čistim milosrđem. Mnogo godina kasnije shvata kobnu težinu svog plemenitog čina koji je svijet gurnuo u katastrofu. Prije nego što bude prekasno, on mora pokušati da ispravi grešku i zaustavi zlo — jer drugog izbora nema.', 'Захватывающая и пронзительная военная повесть о том, как один миг милосердия может перевернуть ход всемирной истории.', 'A gripping and heartbreaking historical tale showing how a single moment of wartime mercy can inadvertently change the course of human history.', 'Napeta i dirljiva istorijska priča koja pokazuje kako jedan trenutak milosrđa u ratu može promijeniti čitavu sudbinu čovječanstva.', '/covers/DP-0990.webp', '#4b5d67', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["adventure","real"]', '["war","history","courage","moral choice","world war"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('трудно-быть-львом-991', 'DP-0991', 'Трудно быть львом', 'It''s Hard to Be a Lion', 'Teško je biti lav', 'Ури Орлев', 'Uri Orlev', 'Uri Orlev', '', 'Текст', NULL, NULL, 6, 16, 'middle', 'Признайтесь, вы когда-нибудь мечтали стать могучим диким зверем? Чтобы одним ударом лапы победить всех врагов? Нет? А вот герой этой книги с детства хотел побыть львом, чтобы хоть на миг ощутить себя сильным, дерзким - и совершенно свободным. И представьте, его мечта сбылась! Однажды он проснулся и убедился, что он уже не человек, а самый настоящий лев. Вам предстоит узнать, каково ему было жить львом с человеческим разумом, стал он вольным зверем или оказался запертым в клетке, остался в городе или пробрался в Африку... И удалось ли ему снова стать человеком? Прочитав эту книгу, вы наверняка согласитесь с автором, известным израильским писателем Ури Орлевым, что быть львом очень даже нелегко.', 'Admit it, have you ever dreamed of turning into a mighty wild beast to defeat all your enemies with a single swipe of your paw? The hero of this book always wished to be a lion, craving strength, boldness, and ultimate freedom. And imagine: one morning, his wish comes true! Waking up with paws, a mane, and a human mind, he must navigate what it truly means to be a beast in human society, whether to flee to Africa or hide in the city, and whether it''s even possible to turn back. Renowned author Uri Orlev crafts a clever, touching tale about dreams, freedom, and the unexpected perils of getting what you wish for.', 'Priznajte, jeste li ikada poželjeli da postanete moćna divlja zvijer i jednim potezom šape pobijedite sve neprijatelje? Junak ove knjige od djetinjstva je sanjao da bude lav, želeći da makar na trenutak osjeti snagu, hrabrost i potpunu slobodu. I zamislite — želja mu se ostvarila! Jednog jutra se probudio kao pravi pravcati lav, ali sa ljudskim umom. Kako izgleda lavlji život u gradu, hoće li završiti u kavezu ili stići do Afrike, i da li uopšte može ponovo postati čovjek? Čuveni pisac Uri Orlev vodi nas kroz duhovitu i mudru priču o tome koliko je zapravo teško biti lav.', 'Осторожнее с желаниями стать царём зверей — оказывается, у львов тоже хватает неожиданных хлопот!', 'Be careful what you wish for when dreaming of being the king of beasts — lions have plenty of troubles of their own!', 'Pazite šta želite kad maštate da postanete kralj životinja — ispostavlja se da i lavovi imaju gomilu briga!', '/covers/DP-0991.webp', '#d9822b', 'nonfiction', 'ru', 'available', 'Для среднего школьного возраста', '["magic","animals","adventure"]', '["lions","transformation","freedom","wishes","israeli literature"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лоранга-мазарин-и-дартаньян-992', 'DP-0992', 'Лоранга, Мазарин и Дартаньян', 'Loranga, Masarin and Dartanjang', 'Loranga, Mazarin i Dartanjan', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Лоранга слушает только эстрадную музыку, от остальной у него болит живот! Его сын Мазарин ест булочки, читает комиксы и слоняется без дела. По соседству, чтобы на него не попадали микробы, живет дедушка Дартаньян. Они покупают тиграм по тысяче сосисок, болеют "лайрингитом", кормят прапрадедушку семечками, сталкиваются со щуками в собственном гараже, играют в хоккей за Россию и Канаду швабрами и незрелым помидором - и вообще ведут себя самым неподобающим образом. Но несмотря на это Лоранга и его семейство любимы и популярны в Швеции уже почти 40 лет. Став героями мультфильма, аудиокниг, театральных постановок, они к тому же спели в Королевской опере в Стокгольме! А теперь эта троица заговорила по-русски и не прочь с тобой познакомиться...', 'Loranga only listens to pop music—any other kind gives him an awful stomachache! His son Masarin munches on buns, reads comics, and lounges about, while grandpa Dartanjang lives in the shed to avoid germs. Together, they feed thousands of sausages to hungry tigers, catch pikes in their own garage, and play mop hockey with an unripe tomato. A Swedish cult classic packed with sheer, unrestrained absurdity and warm-hearted family freedom.', 'Loranga sluša isključivo pop muziku, jer ga od bilo koje druge zaboli stomak! Njegov sin Mazarin jede slatke zemičke, čita stripove i ljenčari, dok deda Dartanjan živi u šupi da bi izbjegao mikrobe. Zajedno kupuju hiljade kobasica za tigrove, pecaju štuke u sopstvenoj garaži i igraju hokej metlama i zelenim paradajzom. Ovaj švedski klasik donosi najluđu, najsmješniju i najslobodniju porodicu na svijetu.', 'Приготовьтесь к чистому, восхитительному абсурду, где взрослые хулиганят круче детей, а в сарае гостят самые настоящие тигры!', 'Get ready for pure, joyous absurdity where grown-ups act sillier than kids and tigers casually devour thousands of sausages in the yard!', 'Spremite se za čist, urnebesni apsurd u kom odrasli prave veće ludorije od djece, a pravi tigrovi u dvorištu jedu hiljade kobasica!', '/covers/DP-0992.webp', '#e0533c', 'nonfiction', 'ru', 'available', 'Для среднего и старшего школьного возраста.', '["funny","adventure"]', '["absurd humor","swedish literature","family","tigers","fun"]', 1792836322700, 1792845696455);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('меня-зовут-мина-993', 'DP-0993', 'Меня зовут Мина', 'My Name Is Mina', 'Zovem se Mina', 'Дэвид Алмонд', 'David Almond', 'Dejvid Almond', '', 'Качели', NULL, NULL, 6, 16, 'middle', 'Дэвид Алмонд пишет просто. Просто, но о самом сложном. О вопросах, которые бередят душу, когда человеку десять-двенадцать лет, а взрослые не знают ответа: правда ли, что наши лопатки были когда-то крыльями? Могут ли ожить глиняные фигурки, если постараться и слепить их очень хорошо? Помогает ли любовь от болезней? Алмонд пишет так, что его читают дети и взрослые по всему миру - его книги переведены более чем на два десятка языков. В 2010 году он стал лауреатом премии имени Андерсена - высшей награды в мире детской литературы. А всех его наград не счесть. Книга "Скеллиг", написанная в 1998 году, получила медаль Карнеги и Уитбредовскую премию. В 2008 году вышел одноимённый фильм с Тимом Ротом в главной роли. Повесть "Меня зовут Мина" предваряет события, которые развернутся в "Скеллиге". …У Мины не было друзей, её считали странной. Не было отца, он умер. Зато у неё была мама - самая лучшая, всё понимающая мама - и целый мир в голове. Потому что голова - это место для чудес. Но как найти того, с кем можно ими поделиться?', 'Mina is considered eccentric by others, but her head is a boundless place of wonder, poetry, and soaring thoughts. In this lyrical prequel to the award-winning masterpiece ''Skellig'', Hans Christian Andersen Award winner David Almond opens the pages of Mina’s extraordinary journal. Sitting high in her favorite tree under the night sky, Mina ponders whether shoulder blades were once wings, why birds sing, and how to find someone who truly understands the magic inside her.', 'Mina je djevojčica koju mnogi smatraju čudnom, ali njen um je beskrajno prostranstvo čuda, poezije i slobodnih misli. U ovoj lirskoj priči koja prethodi slavnom romanu „Skelig“, dobitnik Andersenove nagrade Dejvid Almond otvara nam stranice Mininog neobičnog dnevnika. Posmatrajući svijet s grana omiljenog drveta, Mina se pita jesu li naše lopatice nekada bila krila i kako pronaći nekoga sa kim može podijeliti svoju unutrašnju svjetlost.', 'Впустите в сердце Мину — девочку, которая сидит на дереве по ночам, верит в силу крыльев за спиной и учит нас замечать дивные чудеса прямо под ногами.', 'Climb up into Mina''s favorite tree and discover that having your head full of questions and wings on your back is the truest way to be yourself.', 'Popnite se na Minino omiljeno drvo i otkrijte kako je divno posmatrati svijet širom otvorenih očiju i s krilima u srcu.', '/covers/DP-0993.webp', '#3a7d8c', 'nonfiction', 'ru', 'available', 'в коробке 20', '["real","magic","friends"]', '["growing up","imagination","journal","birds","individuality"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('медвежонок-паддингтон-994', 'DP-0994', 'Медвежонок Паддингтон', 'A Bear Called Paddington', 'Medvjedić Padington', 'Майкл Бонд', 'Michael Bond', 'Majkl Bond', '', 'Азбука', NULL, NULL, 6, 16, 'middle', 'В канун Рождества 1956 года в большом лондонском магазине писатель Майкл Бонд наткнулся на симпатичного игрушечного медвежонка. Бонд купил мишку и назвал Паддингтоном — в честь близлежащего вокзала. А в 1958 году мир впервые познакомился с неунывающим медвежонком, прибывшим из Дремучего Перу прямиком на Паддингтонский вокзал. Так возник новый литературный символ Англии — книги о Паддингтоне переведены на сорок языков, ему стоит памятник на одноименном вокзале, а туристы бойко раскупают игрушечных медвежат в синих пальтишках. Приключения Паддингтона продолжаются уже более шестидесяти лет — такой уж это медведь! С ним никогда не бывает скучно.', 'On Christmas Eve 1956, author Michael Bond spotted a solitary toy bear on a London shop shelf and named him Paddington after the nearby station. First published in 1958, the story of this polite, well-meaning bear from Darkest Peru quickly became an enduring British literary classic. For over sixty years, Paddington''s delightful misadventures and immense warmth have charmed readers of all ages worldwide.', 'Na Badnje veče 1956. godine, pisac Majkl Bond je u jednoj londonskoj robnoj kući pronašao usamljenog plišanog medvjedića i nazvao ga Padington, po obližnjoj stanici. Prvi put objavljena 1958. godine, priča o učtivom medvjedu iz Najmračnijeg Perua brzo je prerasla u voljeni britanski klasik. Više od šezdeset godina Padingtonove tople i komične nezgode očaravaju čitaoce širom svijeta.', 'Не забудьте спрятать бутерброд с мармеладом под шляпу — самый вежливый медведь в мире уже готов перевернуть ваш дом вверх дном!', 'Keep a marmalade sandwich tucked under your hat — the world’s most polite bear is ready to turn everyday life into delightful chaos!', 'Sačuvajte sendvič sa džemom ispod šešira — najučtiviji medvjedić na svijetu stiže da unese topli haos u vaš dom!', '/covers/DP-0994.webp', '#1b4b72', 'nonfiction', 'ru', 'available', 'Категория: Для первого самостоятельного чтения', '["funny","animals","adventure"]', '["bears","london","classic","humor","kindness"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('соседи-995', 'DP-0995', 'Соседи', 'Neighbors', 'Komšije', 'Кася Денисевич', 'Kasya Denisevich', 'Kasja Denisevič', 'Кася Денисевич', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Город полон домов, в доме много квартир. Кто они, наши Соседи? * Лучшая книга 2020 года, вышедшая США и написанная иностранным автором * Атмосфера московских улочек * Глубокое понимание сомнений и волнений ребенка О тех, кто живет рядом с нами, но при этом загадочно неуловимы. Соседи - они снизу, наверху, сбоку. Но мы часто даже не знаем как они выглядят, и можем догадываться об их присутствии по звуку захлопнутой двери, шагам...', 'A poetic and heartfelt exploration of apartment living through the eyes of a young girl. Living in a tall city building, she wonders about the people who share her walls, floor, and ceiling: Who are they? What do their worlds look like? A contemplative story about connection, solitude, and finding one''s place in a big city.', 'Poetično i toplo istraživanje života u zgradi kroz oči jedne djevojčice. Živeći u velikoj gradskoj zgradi, ona razmišlja o ljudima iza zidova, podova i plafona: ko su oni i kako izgledaju njihovi životi? Priča punog srca o radoznalosti, povezanosti i pronalaženju sopstvenog mjesta u velikom svijetu.', 'Идеальная книга для всех, кто хоть раз прислушивался к таинственным шагам сверху и гадал, кто же там ходит на цыпочках.', 'The perfect read for anyone who has ever listened to mysterious footsteps through the ceiling and wondered who is tiptoeing up there.', 'Savršena knjiga za sve koji su ikada osluškivali zagonetne korake sa sprata i pitali se ko to gore hoda na prstima.', '/covers/DP-0995.webp', '#cf5c36', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["real","friends"]', '["neighbors","city life","imagination","empathy","home"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('привет-москва--996', 'DP-0996', 'Привет, Москва!', 'Hello, Moscow!', 'Zdravo, Moskva!', 'Таня Борисова', 'Tanya Borisova', 'Tanja Borisova', 'Таня Борисова', 'А+А', NULL, NULL, 6, 16, 'middle', 'Таня Борисова живет в Москве, любит ходить на пленэр и делать городские зарисовки. Из них и родилась эта книга - увлекательное обозрение российской столицы, какой она открывается любителю кататься на велосипеде. Люди, здания, музеи и достопримечательности складываются в живой и запоминающийся образ уютного мегаполиса. Это прекрасный повод впервые познакомиться с Москвой - как для ее юных гостей и читателей из других мест России и мира, так и для самих москвичей, у каждого из которых свой образ города, неизбежно оставляющий за кадром многое из того, что в нем есть. Автор показывает Москву с личной и непринужденной точки зрения, предлагает по-новому взглянуть на знакомые места, научиться обращать внимание на интересные здания, музейные экспонаты, устройство города и привычки его жителей. Во время остановок по ходу воображаемой велосипедной прогулки у читателей будет случай поразмышлять о том, есть ли у них свои любимые места и здания, какие музеи им особенно нравятся и почему, а заодно узнать немало примечательных фактов из истории и современной жизни Москвы.', 'Tanya Borisova lives in Moscow, loves plein air sketching, and created this book straight from her sketchbook pages. It is an engaging bicycle tour through the Russian capital: vibrant streets, iconic landmarks, cozy nooks, and the lively rhythm of a cozy metropolis. Packed with charming illustrations and historical tidbits, this visual guide invites young explorers and locals alike to look closer at architecture, notice the quirky habits of city dwellers, and imagine their own favorite routes through a big city.', 'Tanja Borisova živi u Moskvi, obožava crtanje na otvorenom i iz svojih skica stvorila je ovu predivnu knjigu — uzbudljiv vodič kroz rusku prijestonicu viđenu očima bicikliste. Ljudi, arhitektura, muzeji i skriveni kutci spajaju se u živu sliku jedne tople metropole. Ovo je sjajan poziv mladim radoznalcima da otkriju grad, primijete zanimljive zgrade i detalje svakodnevice, ali i razmisle o tome kako sami doživljavaju gradove u kojima žive ili putuju.', 'Крутите педали вместе с художницей и открывайте Москву с самых неожиданных ракурсов — идеальный гид для влюблённых в городские прогулки!', 'Hop on your bike with the artist and explore Moscow''s lively streets and hidden gems through stunning, sketchbook-style illustrations!', 'Sjednite na bicikl zajedno sa umjetnicom i otkrijte najljepše kutke Moskve kroz predivne, tople urbane ilustracije!', '/covers/DP-0996.webp', '#e24c38', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real"]', '["cities","moscow","cycling","architecture","travel"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('буквальная-москва-997', 'DP-0997', 'Буквальная Москва', 'Alphabetical Moscow', 'Bukvalna Moskva', 'Александр Голубев', 'Alexander Golubev', 'Aleksandar Golubev', '', 'Речь', NULL, NULL, 6, 16, 'middle', 'Москва! Как много в этом звуке… Чтобы ничего не упустить, пройдись по достопримечательностям столицы от "А" до "Я". Маршрут тебе подскажет книга "БУКВАльная Москва", а компанию составят два весёлых приятеля - старый знакомый питерский кот Батон и его столичный добрый друг кот Бульон. Будь уверен, эти двое пробежались по всем закоулкам Златоглавой и Белокаменной… Кстати, хочешь узнать, почему Москву так называют? Тогда присоединяйся к ним скорее!', 'Moscow from A to Z! Set off on a vibrant city tour across the capital alongside two hilarious feline pals: Baton, the visiting cat from St. Petersburg, and his hospitable local buddy Bouillon. Together, they explore hidden alleys, magnificent landmarks, and historical curiosities, revealing why Moscow is called ''The City of Golden Domes'' and ''White-Stone Moscow''.', 'Moskva od A do Š! Krenite u živopisnu šetnju ruskom prijestonicom u društvu dva vesela mačja druga — starog znanca mačka Batona iz Sankt Peterburga i njegovog moskovskog prijatelja Buljona. Zajedno će pronjuškati kroz skrivene kutke i znamenite bulevare, otkrivajući djeci sve tajne, istoriju i legende bijele i zlatoglave Moskve.', 'Два усатых гида проведут вас по самым интересным уголкам Москвы от «А» до «Я» — запасайтесь любопытством!', 'Two witty feline guides will take you on an unforgettable journey through Moscow from A to Z!', 'Dva dovitljiva mačja vodiča provešće te kroz najljepše kutke Moskve od A do Š!', '/covers/DP-0997.webp', '#c0392b', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","animals","real"]', '["москва","коты","путешествия","азбука","города"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('путеводитель-по-московскому-ме-998', 'DP-0998', 'Путеводитель по московскому метр с Тимкой и Тинкой', 'Moscow Metro Guide with Timka and Tinka', 'Vodič kroz moskovski metro sa Timkom i Tinkom', '', 'Unknown', 'Nepoznati autor', '', 'Пешком в историю', 2025, '978-5-907793-33-0', 6, 16, 'middle', '', 'Take an unforgettable underground expedition beneath Moscow with two curious mice, Timka and Tinka! Discover the hidden secrets of the world''s most beautiful subterranean palaces, unravel the mysteries of secret tunnels, explore unique architecture, and find out how massive subway trains work behind the scenes.', 'Krenite u uzbudljivu podzemnu ekspediciju kroz Moskvu sa radoznalim miševima Timkom i Tinkom! Otkrijte skrivene tajne najljepših podzemnih palata na svijetu, misterije tajanstvenih tunela, čudesnu arhitekturu i saznajte kako funkcionišu vozovi podzemne željeznice.', 'Загляните под землю и превратите обычную поездку на метро в грандиозную охоту за сокровищами и тайнами архитектуры!', 'Peek beneath the bustling streets and turn an everyday subway ride into a thrilling treasure hunt through underground palaces!', 'Zavirite pod zemlju i pretvorite običnu vožnju metroom u uzbudljivu potragu za skrivenim istorijskim blagom!', '/covers/DP-0998.webp', '#c82333', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real"]', '["metro","moscow","architecture","guidebook","history","transport"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пешком-по-петербургу-с-тимкой--999', 'DP-0999', 'Пешком по Петербургу с Тимкой и Тинкой', 'Walking Through St. Petersburg with Timka and Tinka', 'Šetnja po Sankt Peterburgu sa Timkom i Tinkom', '', 'Unknown', 'Nepoznati autor', '', 'Пешком в историю', 2019, '978-5-906994-30-1', 6, 16, 'middle', '', 'An interactive city guide through Saint Petersburg led by two curious little mice, Timka and Tinka. Young travelers will explore majestic palaces, drawbridges, windy canals, and hidden urban legends through engaging puzzles, maps, and historical facts.', 'Interaktivni vodič kroz Sankt Peterburg na koji vas vode dva radoznala mišića, Timka i Tinka. Mladi istraživači otkriće raskošne palate, pokretne mostove, kanale i gradske legende kroz zabavne mape, zagonetke i istorijske zanimljivosti.', 'Надевайте удобную обувь: два неутомимых мышонка покажут город на Неве увлекательнее любого взрослого экскурсовода!', 'Lace up your walking shoes: two tireless mice will guide you across St. Petersburg far better than any grown-up tour guide!', 'Obujte udobne patike: dva neumorna mišića provešće vas kroz čarobni grad na Nevi bolje od bilo kog turističkog vodiča!', '/covers/DP-0999.webp', '#2e6f89', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real","friends"]', '["saint petersburg","city guide","travel","history","architecture"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чудо-1000', 'DP-1000', 'Чудо', 'Leaf', 'Čudo', 'Сандра Дикманн', 'Sandra Dieckmann', 'Sandra Dikman', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Книга, которая восхищает в первую очередь своей красотой и волшебными атмосферными иллюстрациями, не оставляя никого равнодушным. Несмотря на то что это первая книга художника Сандры Дикманн, она была высоко оценена международным литературным сообществом. Для автора важна проблема экологии - таяние льдов в Арктике и судьба полярных медведей. Через историю белого медведя автор обращается к этой теме и к проблеме чужаков вообще, толерантности, приятия, взаимопомощи и взаимовыручки. То, что на первый взгляд может показаться странным, при ближайшем рассмотрении оказывается настоящим чудом и таит в себе массу возможностей, чтобы стать добрее, мудрее и человечнее.', 'When a bewildered polar bear washes ashore in a lush forest far from his icy home, the woodland creatures are terrified of this strange ''monster.'' As he quietly gathers fallen leaves to build wings and fly home, the forest animals slowly realize that behind differences lies a vulnerable soul in need of warmth, kindness, and help. A breathtakingly illustrated fable about climate change, displacement, empathy, and the magic of friendship.', 'Kada se zbunjeni bijeli medvjed nasuče na obalu šume daleko od svog ledenog doma, šumske životinje se uplaše neobičnog ''čudovišta''. Dok on tiho sakuplja lišće kako bi napravio krila i odletio kući, životinje polako shvataju da se iza različitosti krije ranjiva duša kojoj je potrebna podrška. Raskošno ilustrovana priča o ekologiji, prihvatanju stranaca, empatiji i snazi zajedništva.', 'Невероятно трогательная и живописная история о белом медведе, которая научит сердце видеть чудо там, где поначалу видится лишь чужак.', 'A breathtakingly tender and gorgeous tale of a lost polar bear that gently reminds us how kindness can help anyone find their way home.', 'Dirljiva i čarobno ilustrovana priča o polarnom medvjedu koja nas uči da u nepoznatom ne vidimo opasnost, već priliku za dobrotu.', '/covers/DP-1000.webp', '#3b7a8c', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["animals","friends","real"]', '["polar bear","ecology","friendship","empathy","nature"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пес-проглотивший-мир-1001', 'DP-1001', 'Пес, проглотивший мир', 'The Dog That Swallowed the World', 'Pas koji je progutao svijet', 'Сандра Дикманн', 'Sandra Dieckmann', 'Sandra Dikman', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Однажды в цветущей долине появился огромный черный пёс. Он ломал деревья, сворачивал леса, опустошал реки и моря. Звери и птицы не могли остановить его. Пёс ел всё, что пожелает. Вскоре он проглотил и всех жителей долины! И тогда, окутанные тьмой, звери и птицы решили объединиться и построить новый мир... На иллюстрациях Сандры Дикманн мир дикой природы наполнен волшебством и чудесами. Художник рассказывает глубокую и удивительную историю о дружбе, взаимопомощи и поддержке в самые трудные времена.', 'One day, an enormous black dog appeared in a blooming valley, crushing forests and drinking up rivers until he swallowed every creature whole. Trapped in the dark belly of the beast, the animals and birds decide to unite and build a brand-new world from within. Sandra Dieckmann weaves a breathtaking, allegorical tale of resilience, friendship, and hope in the face of overwhelming darkness.', 'Jednog dana u rascvjetanoj dolini pojavio se ogroman crni pas koji je lomio drveće, pustošio rijeke i mora, dok na kraju nije progutao sve stanovnike doline. U tami njegovog stomaka, životinje i ptice odlučuju da se ujedine i stvore novi svijet pun svjetlosti. Kroz raskošne ilustracije Sandre Dikman, ova dirljiva basna govori o snazi zajedništva, prijateljstvu i nadi u najtežim trenucima.', 'Даже когда огромный черный пёс поглотил всё вокруг, дружба и надежда способны зажечь новый мир прямо из темноты!', 'Even when a giant black dog swallows the whole world, hope and teamwork can ignite a brand-new light from the inside out!', 'Čak i kada ogroman crni pas proguta čitav svijet, zajedništvo i nada mogu upaliti novo svjetlo iz samog mraka!', '/covers/DP-1001.webp', '#1e324b', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","animals","friends"]', '["allegory","fable","nature","hope","friendship"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дома-и-домики-в-бермудском-тре-1002', 'DP-1002', 'Дома и домики в бермудском треугольнике', 'Houses and Tiny Houses in the Bermuda Triangle', 'Kuće i kućice u Bermudskom trouglu', 'Маша Краснова-Шабаева', 'Masha Krasnova-Shabaeva', 'Maša Krasnova-Šabajeva', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Увлекательнейшее занятие - разглядывать устройство домов и домиков! Но заглянуть в домики, которые построены в Бермудском треугольнике, может только человек с невероятной фантазией! Такой, как у художницы Маши Красновой-Шабаевой! Она рисует для The New York Times, Esquire, GQ, устраивает выставки и выпускает иллюстраторские зины, и может показать в своих иллюстрациях даже мир, который никто не видел - удивительные дома Безумного Леса, республики Насекоми, города Ветров или острова Оранжерей. И даже научит их конструировать из того, что есть под рукой и воображения!', 'Exploring how houses are built is always fascinating, but peeking inside houses built right in the Bermuda Triangle requires extraordinary imagination! Acclaimed illustrator Masha Krasnova-Shabaeva takes readers on a journey through unseen worlds—from the Mad Forest and the Republic of Insects to the City of Winds and Greenhouse Island—and even teaches how to invent and build your own dream structures using everyday materials and boundless fantasy.', 'Zavirivanje u arhitekturu neobičnih kuća prava je avantura, ali otkriti domove sagrađene u samom Bermudskom trouglu može samo neko s nevjerovatnom maštom! Priznata ilustratorka Maša Krasnova-Šabajeva vodi nas kroz neviđene svjetove — nevjerovatne kuće Lude šume, republike Insekata, grada Vjetrova ili ostrva Staklenika — i uči djecu kako da osmisle i naprave sopstvene kućice od mašte i svega što im se nađe pod rukom.', 'Приготовьте картон, клей и неуёмную фантазию: эта книга вдохновит спроектировать самые безумные архитектурные шедевры прямо на ковре в гостиной!', 'Grab some cardboard, glue, and wild imagination: this book will inspire you to design the most eccentric architectural wonders right on your living room floor!', 'Pripremite karton, ljepilo i divlju maštu: ova knjiga će vas inspirisati da projektujete najluđa arhitektonska remek-djela usred dnevne sobe!', '/covers/DP-1002.webp', '#2a8b84', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","magic"]', '["architecture","creativity","illustration","imagination","diy"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('умеешь-ли-ты-хранить-секреты--1003', 'DP-1003', 'Умеешь ли ты хранить секреты?', 'Can You Keep a Secret?', 'Umiješ li čuvati tajne?', 'Мелисса Кастрильон', 'Melissa Castrillón', 'Melissa Castrillón', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Сможешь ли ты сохранить в секрете встречу с настоящим драконом? Однажды Винни повстречала дракона, а также его удивительных друзей — грифона, крылатого льва и древочеловека — последних волшебных существ на всём белом свете. Если кто-то узнает об их существовании, может случиться беда. Сумеет ли Винни сохранить этот секрет?', 'Could you keep an encounter with a real dragon secret? One day, Winnie meets a dragon and his magical companions—a griffin, a winged lion, and a tree-man—the very last enchanting creatures left in the world. If anyone discovers they exist, disaster could strike. Will Winnie be able to keep their secret safe?', 'Možeš li sačuvati u tajnosti susret sa pravim zmajem? Jednog dana Vini upoznaje zmaja i njegove čarobne prijatelje — grifona, krilatog lava i čovjeka-drvo — posljednja magična bića na čitavom svijetu. Ako neko sazna za njih, prijeti im velika opasnost. Hoće li Vini uspjeti da sačuva ovu tajnu?', 'Потрясающе иллюстрированная сказка-напоминание о том, как важно беречь хрупкое волшебство природы и уметь хранить чужие тайны!', 'A breathtakingly illustrated tale reminding us how crucial it is to protect the fragile wonders of our world—and keep a friend''s biggest secret!', 'Predivno ilustrovana priča koja nas podsjeća koliko je važno čuvati krhku magiju svijeta i biti prijatelj od povjerenja!', '/covers/DP-1003.webp', '#2d5a43', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","adventure","friends"]', '["dragons","mythical creatures","secrets","friendship","nature"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('супер-обычный-день-1004', 'DP-1004', 'Супер обычный день', 'On a Magical Do-Nothing Day', 'Jedan sasvim običan dan', 'Беатриче Алеманья', 'Beatrice Alemagna', 'Beatriče Alemanja', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Что делать на даче, пока мама работает, а за окном льет дождь? Конечно, играть в приставку, стрелять марсиан! Жаль, мама не согласна и ворчит, что это пустая трата времени! Но, оказывается, на улице, без приставки, тоже есть жизнь, да еще и какая волшебная…Невероятная реальность самого обычного дня в иллюстрациях Беатриче Алеманьи (одной из самых известных художниц книги в мире) завораживает и героя книги, и читателей. Вместе мы заблудимся в лесу, увидим мельтешение неизвестных микроштук в земле, волшебные камушки в пруду и удивительный свет сквозь тучи, услышим грохот собственного сердца. Так удивляться миру могут только дети и самые талантливые авторы детских книг! В этом упоении звуками, видами, шумом природы Беатриче Алеманья высвечивает (в буквальном смысле — своей потрясающей работой с цветом и фактурой) — возможности и необходимость природы для человека. Причем, все это — с ощущением игры и восторга, а не назидательности. Издания книг Беатриче Алеманьи на русском давно ждали многие любители иллюстрации. В 2014 году она приезжала с мастер-классами в Россию.', 'What do you do at a rainy country house while mom works? Play video games, of course! But when mom insists on turning off the console, an extraordinary journey begins outside in the wet drizzle. Beatrice Alemagna paints a magnificent celebration of sensory wonder—splashing in mud, marveling at tiny underground critters, and feeling the wild thump of one''s own heart. A visually stunning, joyful reminder of why children need the untamed outdoors.', 'Šta raditi u vikendici dok mama radi, a napolju lije kiša? Naravno, igrati igrice i pucati u Marsovce! Ali mama misli drugačije i tjera te napolje bez ekrana. Ispostavlja se da tamo leži nevjerovatan, čaroban svijet. Kroz raskošne ilustracije Beatriče Alemanje, jedan naizgled dosadan i običan dan pretvara se u čudesnu pustolovinu u prirodi punu blata, sitnih stvorenja i dječije radoznalosti.', 'Спрячьте планшеты, натяните оранжевый дождевик и бегите месить грязь — там прячется самое настоящее волшебство!', 'Unplug the screens, pull on your brightest raincoat, and jump into the muddy, breathtaking magic of the outdoors!', 'Ostavite ekrane, obucite narandžastu kabanicu i otkrijte blistavu magiju skrivenu u kišnim lokvama!', '/covers/DP-1004.webp', '#e85d26', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","magic","real"]', '["rain","nature","childhood","imagination","outdoors"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вся-правда-о-пиратах-1005', 'DP-1005', 'Вся правда о пиратах', 'The Whole Truth About Pirates', 'Prava istina o piratima', 'Екатерина Степаненко', 'Ekaterina Stepanenko', 'Jekaterina Stepanenko', 'Поля Плавинская', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Просоленные насквозь морским ветром, бесстрашные и свободные, одноногие и одноглазые, с саблей в одной руке и с бутылкой рома в другой. Сражаются они так же неистово, как и ищут сокровища, не боятся ни Бога, ни дьявола, и нет никого, кто бы не трепетал при виде их чёрного флага с черепом и костями! Конечно же, речь о пиратах. Такими рисуют их книги и фильмы и так мы привыкли себе их представлять. Но много ли общего у такого романтического героя с настоящим морским разбойником? Эта книга приглашает читателей в путешествие по морям и океанам, где в разные века плавали пиратские суда, на необитаемые острова, где пираты прятали сокровища, и в порты, где они набирали команду. Она развеет мифы и расскажет всю правду о пиратах! Вам откроется подлинная разбойничья жизнь, полная страхов и опасностей, жестокая, неприглядная, а главное, очень короткая. Вы узнаете, когда появились пираты, на каких кораблях они плавали, кто и почему выбирал себе эту «профессию», действительно ли пираты не признавали никакого закона и никого не боялись.', 'Weathered by salty winds, fearless, wooden-legged, and eye-patched, with a cutlass in one hand and a bottle of rum in the other—this is how movies and adventure books paint pirates. But did romantic heroes really roam the high seas? This book takes readers on a sweeping voyage across centuries of pirate history, deserted islands, and bustling port taverns. Busting popular myths, it reveals the harsh, dangerous, and often short life of genuine sea rovers: their ships, codes of conduct, diets, and what truly drove ordinary sailors to hoist the Jolly Roger.', 'Prekaljeni morskim vjetrovima, neustrašivi, s drvenom nogom i povezom preko oka, sa sabljom u jednoj i bocom ruma u drugoj ruci — tako pirate prikazuju romani i filmovi. Ali koliko zajedničkog ima taj romantični lik sa pravim morskim razbojnikom? Ova knjiga vodi čitaoce na uzbudljivo putovanje kroz vijekove piratske istorije, na pusta ostrva i u lučke krčme. Razbijajući popularne mitove, ona otkriva surovu, opasnu i vrlo kratku svakodnevicu morskih vukova: njihove brodove, pravila ponašanja i prave razloge zbog kojih su mornari birali ovaj opasan zanat.', 'Забудьте про попугаев на плече и закопанные сундуки: эта книга без прикрас и с юмором расскажет, как на самом деле выживали морские разбойники!', 'Forget talking parrots and buried chests: this fascinating, myth-busting guide shows what real pirate life was truly like!', 'Zaboravite na papagaje na ramenu i zakopano blago: ovaj uzbudljivi vodič bez uljepšavanja otkriva kako su pirati zaista živjeli!', '/covers/DP-1005.webp', '#204a62', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real"]', '["pirates","history","ships","sea","nonfiction"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('удивительные-самолеты-1006', 'DP-1006', 'Удивительные самолеты', 'Amazing Airplanes', 'Čudesni avioni', '', 'Tony Mitton', 'Toni Miton', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Книжка для маленьких. Они узнают в веселой красочной книжке о том, как летают самолеты и из чего они состоят. Стихи помогут малышам легко запомнить историю. Тони Миттон родился в Триполи и провел детство в Северной Африке, Германии и Гонконге. Он закончил затем Кембриджский Университет. Окончив университет он какое-то время работал учителем в школе. Но потом оставил учительство, полностью сосредоточившись на написании детских книг.', 'A cheerful, rhyming picture book that introduces young readers to the wonders of aviation. With bright illustrations and catchy verses, children will discover how airplanes take flight, what goes on at the airport, and how these marvelous machines work.', 'Vesela i rimovana slikovnica koja najmlađima otkriva čuda avijacije. Kroz poletne stihove i živopisne ilustracije, mališani će saznati kako avioni lete, šta se sve događa na aerodromu i od kojih se dijelova sastoje čudesne letjelice.', 'Пристегните ремни: этот звонкий стихотворный полёт в деталях объяснит малышам, как огромные крылатые машины взмывают выше облаков!', 'Fasten your seatbelts: this delightful rhyming flight shows young aviators exactly how giant winged machines conquer the skies!', 'Vežite pojaseve: ovaj poletni let u stihovima otkriva malim avijatičarima kako čudesne čelične ptice osvajaju nebo!', '/covers/DP-1006.webp', '#2a82c4', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real"]', '["самолёты","транспорт","в стихах","авиация","познавательное"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('корабли-1007', 'DP-1007', 'Корабли', 'Ships', 'Brodovi', 'Али Митгуш', 'Ali Mitgutsch', 'Ali Mitgutsch', 'Али Митгуш', 'Мелик-Пашаев', NULL, NULL, 6, 16, 'middle', 'Щедро иллюстрированная книга знаменитого немецкого художника Али Митгуша (основоположника жанра "виммельбух") посвящена истории освоения человеком водной стихии и эволюции плавательных средств. Читателей ждет увлекательное путешествие во времени: благодаря мастерству художника можно во всех подробностях рассмотреть древние лодки и первые корабли Тихого океана, берестяные каноэ индейцев, финикийские биремы, драккары викингов, ганзейские когги, парусники времен великих географических открытий, пароходы и баржи 19 века и разнообразные современные корабли специального назначения. Книга расскажет об истории водолазного дела, рыболовного промысла, об устройстве старинных и современных маяков, о самых важных навигационных приборах и о принципах работы различных движителей. Книга Али Митгуша насыщена интересными и редкими фактами, она познавательна и уникальна в своем роде - ведь это, с одной стороны, визуальная история навигации от первобытных времен до наших дней, а с другой - настоящий гимн человеческому разуму, изобретательности и смекалке. Несмотря на относительно небольшое количество текста этот виммельбух достаточно информативен, чтобы удовлетворить запросы даже вполне эрудированных читателей, поэтому его будет интересно изучать как дошкольникам, так и детям более старшего возраста.', 'Richly illustrated by Ali Mitgutsch, the legendary pioneer of the wimmelbook genre, this visual encyclopedia charts humanity''s conquest of the seas and the evolution of watercraft. Readers embark on an engrossing journey through time, discovering prehistoric dugout boats, Native American birchbark canoes, Phoenician biremes, Viking longships, Hanseatic cogs, tall sailing ships, 19th-century steamships, and sophisticated modern vessels. Packed with intricate details on lighthouses, diving gear, navigation instruments, and maritime technology, it stands as both an informative treasure trove and a celebration of human ingenuity.', 'Raskošno ilustrovana knjiga čuvenog njemačkog umjetnika Alija Mitguča (tvorca žanra vimmelbuh) posvećena je istoriji čovjekovog osvajanja vodenih prostranstava i evoluciji plovila. Čitaoce čeka uzbudljivo putovanje kroz vrijeme: od praistorijskih čamaca, indijanskih kanua, feničanskih birema i vikinških drakara, do jedrenjaka iz doba Velikih geografskih otkrića, parobroda i savremenih brodova posebne namjene. Knjiga takođe otkriva tajne ronilaštva, ribarstva, svjetionika i navigacionih instrumenata, slaveći ljudski um i domišljatost u svakom detalju.', 'От долблёных каноэ до океанских гигантов — невероятно детальная энциклопедия для всех, кто мечтает стоять у штурвала!', 'From hollowed-out canoes to ocean giants, this exquisitely detailed visual encyclopedia is pure joy for anyone who dreams of taking the helm!', 'Od praistorijskih čamaca do modernih okeanskih divova, ova detaljna vizuelna enciklopedija pravo je blago za sve koji sanjaju da stanu za kormilo!', '/covers/DP-1007.webp', '#2c6491', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real"]', '["корабли","мореплавание","виммельбух","история","изобретения"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жизнь-одного-корабля-1008', 'DP-1008', 'Жизнь одного корабля', 'The Life of a Ship', 'Život jednog broda', 'Инноченти Роберто', 'Roberto Innocenti', 'Roberto Inoćenti', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Это книга о капитане и его корабле по имени «Клементина». Моряк рассказывает историю своего судна с начала 1930-х годов, когда оно было построено на верфи, и до его гибели. Ступив на борт «Клементины» еще мальчишкой, он провёл на этом грузовом судне почти всю жизнь, пройдя путь от юнги до капитана. С «Клементиной» он смог увидеть весь мир: Гавану и Валенсию, Панаму и Нью-Йорк, Лиссабон и Ливерпуль. «Клементина» побывала с мирными грузами в самых экзотических странах, во время войны через воды Арктики возила боеприпасы и технику для Красной Армии, а в конце своей долгой трудовой жизни обрела покой на морском дне. Капитан стоял за штурвалом своей «Клементины» до самой её гибели. Вместе они совершают путешествие длиною в жизнь. Корабль и его история оживают в удивительных, подробных иллюстрациях Роберто Инноченти, которые показывают, как менялся мир с 1930-х до 1980-х годов. Вместе с моряками мы становимся свидетелями сменяющих друг друга исторических событий: гражданской войны в Испании, Второй мировой войны, забастовок 1980-х годов в Польше, а также любуемся разнообразием пейзажей самых разных уголков мира: Полинезии и Индии, Америки и Европы, извержением вулкана, арктическими льдами, картинами мирной жизни и морских сражений. Историю жизни корабля дополняет карта мирных и военных маршрутов «Клементины», а также схемы внутреннего устройства судна от носа до кормы и от мачт до трюма. Сама «Клементина» - выдуманное судно, но ее судьба повторяет истории многих грузовых кораблей того времени.', 'This is the sweeping chronicle of a merchant vessel named Clementine and the sailor who loved her. Stepping aboard as a young cabin boy in the 1930s, he eventually became her captain, staying at the helm through decades of world exploration and turbulent history. From tranquil voyages delivering cargo to Havana, New York, and Lisbon, to perilous wartime Arctic convoys carrying supplies, the Clementine journeyed through fifty pivotal years before finding her final resting place beneath the waves. Illustrated with breathtaking, hyper-realistic artwork by Roberto Innocenti, the book pairs a moving personal memoir with detailed technical cross-sections and maps, capturing the transformative decades of the twentieth century at sea.', 'Ovo je dirljiva i epska hronika teretnog broda po imenu Klementina i kapetana koji je sa njim vezao čitavu svoju sudbinu. Kao dječak se ukrcao na palubu početkom tridesetih godina prošlog vijeka, prešao put od malog od palube do kapetana i obišao čitav svijet — od Havane i Valensije do Njujorka i Lisabona. Klementina je plovila pod mirnim nebom tropskih luka, prevozila zalihe kroz zaleđeni Arktik tokom Drugog svjetskog rata, i na kraju pronašla mir na morskom dnu. Uz veličanstvene, detaljne ilustracije Roberta Inoćentija, šeme brodske konstrukcije i mape ruta, ova knjiga donosi ne samo život jednog broda već i pedeset godina uzburkane istorije dvadesetog vijeka.', 'Грандиозная одиссея одного верного судна сквозь шторма XX века с потрясающими, кинематографичными иллюстрациями маэстро Инноченти.', 'A sweeping, deeply moving twentieth-century maritime odyssey brought to life by Roberto Innocenti''s breathtaking, cinematic illustrations.', 'Veličanstvena pomorska odiseja jednog vjernog broda kroz burni dvadeseti vijek, oživljena remek-djelima maestra Inoćentija.', '/covers/DP-1008.webp', '#2c4a63', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real"]', '["ships","sea","history","travel","illustrated"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-я-поменял-одного-папу-на-д-1009', 'DP-1009', 'Как я поменял одного папу на двух золотых рыбок', 'The Day I Swapped My Dad for Two Goldfish', 'Dan kad sam zamijenio tatu za dvije zlatne ribice', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', 'Дэйв МакКин', 'livebook', NULL, NULL, 6, 16, 'middle', 'Нил Гейман - английский писатель-фантаст, автор графических романов и комиксов, сценариев к фильмам. Среди самых известных его работ - "Звездная пыль", "Американские боги", "Коралина", "Никогде", серия комиксов "Песочный человек". Гейману присуждены многие награды, включая премию "Хьюго", премию "Небьюла", премию Брэма Стокера, медаль Ньюбери. Книгу "Как я поменял одного папу на двух золотых рыбок" проиллюстрировал британский графический художник, фотограф и автор комиксов Дэйв МакКин. Его смешанная техника - причудливое сочетание рисунков и фотографий - превратила сюрреалистичный мир сказки Геймана о том, как важна семья, в завораживающее произведение искусства. Книга завоевала награду журнала Newsweek как лучшая детская книга года, получила премию Британской ассоциации научной фантастики за короткую художественную прозу и стала основой спектакля Национального театра Шотландии.', 'When a boy makes an impulsive trade with his best friend, swapping his newspaper-reading father for two shiny goldfish, his mother is decidedly not amused. To get dad back before supper, the boy and his little sister must embark on a hilarious suburban quest, chasing dad through a chain of increasingly ridiculous trades. Featuring the striking mixed-media artwork of Dave McKean, this modern classic is a delightfully quirky tale about the value of family.', 'Kada dječak napravi naglu pogodbu sa najboljim drugom i zamijeni svog oca, zadubljenog u novine, za dvije zlatne ribice, mama uopšte nije oduševljena. Kako bi vratili tatu prije večere, brat i sestra kreću u urnebesnu potragu kroz komšiluk, prateći lanac sve smješnijih trampi. Uz upečatljive ilustracije Dejva Mekina, ovaj moderni klasik je neobična i topla priča o tome koliko je porodica zapravo važna.', 'Остроумная и немного сюрреалистичная история о том, почему не стоит менять папу на рыбок — ведь выменивать его обратно через весь район окажется ох как непросто!', 'A wildly funny cautionary tale reminding kids that swapping dad for cool pets is easy, but trading him back across the whole neighborhood is pure chaos!', 'Urnebesno duhovita i pomalo nadrealna priča koja podsjeća zašto nije pametno mijenjati tatu za ribice — jer ga je poslije vraški teško vratiti nazad!', '/covers/DP-1009.webp', '#d97426', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","adventure"]', '["семья","юмор","графический роман","папа","приключения"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-без-названия-1010', 'DP-1010', 'Книга без названия', 'Help! We Need a Title!', 'Knjiga bez naslova', 'Эрве Тюлле', 'Hervé Tullet', 'Erve Tile', '', 'Clever', NULL, NULL, 6, 16, 'middle', 'Эта книга – ещё¸ не вполне книга, а только черновик. Впрочем, в ней уже есть свои персонажи (набросанные на скорую руку) и автор (по уши в работе!).', 'This book isn''t quite finished yet—it''s still just a rough draft! Yet it already has quirky sketched characters and an author caught completely unprepared, scrambling to invent a plot right before your eyes.', 'Ova knjiga još uvijek nije sasvim gotova, već je samo radna skica. Ipak, u njoj već žive na brzinu nacrtani likovi i zbunjeni autor koji u hodu pokušava da dovrši priču!', 'Загляните за кулисы книжного мира: застаньте автора врасплох и помогите незаконченным героям найти свой сюжет!', 'Peek behind the curtain of bookmaking, catch the author unprepared, and help unfinished sketches figure out their story!', 'Zavirite iza kulisa stvaranja knjige, iznenadite autora i pomozite nedovršenim skicama da pronađu svoju priču!', '/covers/DP-1010.webp', '#f4ce2b', 'nonfiction', 'ru', 'available', '?', '["funny","real"]', '["metafiction","creativity","interactive","drawing","art"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('барсук-в-доме-1011', 'DP-1011', 'Барсук в доме', 'A Badger in the House', 'Jazavac u kući', 'Лиза Рагвальс', 'Lisa Ragvals', 'Lisa Ragvals', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Как-то раз в самой обычной семье поселился барсук. Но можно ли держать барсуков в доме? Аббе считает, что можно. Вскоре барсук занимает всю комнату и прорывает ход в квартиру этажом ниже. Что же будет дальше?', 'One day, a badger moves into the home of an ordinary family. But can you really keep a wild badger indoors? Young Abbe certainly thinks so! Soon enough, the nocturnal guest takes over an entire room and digs a secret tunnel straight down into the downstairs neighbor''s apartment. What could possibly happen next?', 'Jednog dana, u jednoj sasvim običnoj porodici nastanio se jazavac. Ali, može li se divlji jazavac uopšte držati u kući? Abe smatra da može! Ubrzo neobični ljubimac zauzima čitavu sobu i prokopava prolaz do stana na spratu ispod. Šta li će se tek sad desiti?', 'Если вы думали, что котики устраивают дома беспорядок, познакомьтесь с барсуком, который затеял ремонт прямо сквозь потолок соседей снизу!', 'If you thought kittens were chaotic roommates, wait until you meet a pet badger who renovates the floor right into the downstairs apartment!', 'Ako ste mislili da mace prave nered, upoznajte jazavca koji je riješio da renovira stan kopajući prolaz do komšija ispod!', '/covers/DP-1011.webp', '#8b5a3c', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","animals","real"]', '["badgers","wild animals","pets","humor","family life"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('почтальон-мышка-1012', 'DP-1012', 'Почтальон Мышка', 'Here Comes Mr. Postmouse', 'Poštar Miš', 'Марианна Дюбюк', 'Marianne Dubuc', 'Marijana Dibik', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Вы бывали дома у крокодилов? А у пингвинов? Нет? Тогда отправляйтесь вслед за Почтальоном Мышкой. Он разносит почту жителям необычной деревни: гнёзда и норы пещеры и коттеджи, хижины и игру полны забавных деталей, которые расскажут много интересного о тех, кто здесь живёт. А напоследок Почтальон Мышка доставит один маленький подарок - угадайте, кому!', 'Have you ever visited a crocodile at home? What about a penguin? Tag along with Mr. Postmouse on his delivery rounds! Peek into nests, burrows, caves, and igloos packed with funny, fascinating cross-section details that reveal how each critter lives. And at the very end of his busy day, there''s one final special parcel left to deliver—can you guess who it''s for?', 'Jeste li ikada zavirili u kuću krokodila? Ili pingvina? Krenite za Poštarom Mišem dok raznosi poštu neobičnim stanovnicima čudesnog sela: gnijezda, jazbine, pećine i iglui prepuni su smiješnih detalja koji otkrivaju kako životinje zaista žive. A na samom kraju radnog dana, Poštar Miš ima još jedan poseban paketić — pogodite za koga!', 'Загляните в гости ко всем лесным жителям сразу — здесь столько очаровательных секретов, что книжку можно разглядывать часами!', 'Peek inside the coziest animal homes imaginable—this delightfully detailed journey will keep curious little eyes busy for hours!', 'Zavirite u najslađe životinjske domove — ova topla slikovnica krije toliko zabavnih detalja da ćete je satima sa osmijehom istraživati!', '/covers/DP-1012.webp', '#4a8c82', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста.', '["animals","adventure","funny"]', '["animals","wimmelbuch","cozy","houses","details"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('невероятные-приключения-почтал-1013', 'DP-1013', 'Невероятные приключения почтальона Мышки', 'The Incredible Adventures of Mr. Postmouse', 'Nevjerovatne pustolovine poštara Mišića', 'Марианна Дюбюк', 'Marianne Dubuc', 'Marijana Dibik', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Вот кто самый отважный почтальон на свете! Почтальон Мышка, герой вот уже третьей книжки-картинки канадской художницы Марианны Дюбюк, отправляется развозить посылки и письма на ракете. Мы уже познакомились с его забавными соседями, объехали вокруг света, а сегодня вместе с ним можем заглянуть в новые миры.', 'Meet the bravest courier in the galaxy! Mr. Postmouse, the beloved hero of Canadian illustrator Marianne Dubuc, hops into a rocket to deliver letters and packages to outer space. Hop aboard to explore whimsical alien landscapes and cosmic neighborhoods brimming with charming hidden details.', 'Upoznajte najhrabrijeg poštara u čitavom svemiru! Poštar Mišić, junak kanadske autorke i ilustratorke Marijane Dibik, sjeda u raketu kako bi raznosio pisma i pakete među zvijezdama. Ukrcajte se s njim i zavirite u čudesne nove svjetove prepune toplih i duhovitih detalja.', 'Пристегните ремни: этот космический виммельбух от Марианны Дюбюк можно разглядывать часами, выискивая забавные посылки для инопланетян!', 'Fasten your seatbelts: this cosmic search-and-find picture book is packed with delightful micro-details that will have you giggling at alien deliveries for hours!', 'Vežite pojaseve: ovu kosmičku slikovnicu možete proučavati satima, tražeći skrivene šale i smiješne paketiće za vanzemaljce!', '/covers/DP-1013.webp', '#2c6c9a', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","animals","funny"]', '["space","animals","mice","wimmelbuch","picture book"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('носорог-витгенштейна-1014', 'DP-1014', 'Носорог Витгенштейна', 'Wittgenstein''s Rhinoceros', 'Vitgenštajnov nosorog', 'Франсуаза Арменьо', 'Françoise Armengaud', 'Fransoaz Armengo', 'Аннабель Бюкстон', 'А+А', NULL, NULL, 6, 16, 'middle', 'Людвиг Витгенштейн (1889–1951) был тем, кто в начале XX века полностью изменил философию, начав анализировать язык. Будучи ещё молодым человеком, мыслитель удивлял кембриджских профессоров. Именно со спора с одним из них начинается «Носорог Витгенштейна», где в попытках найти несуществующего в аудитории носорога молодой философ открывает секреты языка и пишет свой знаменитый «Логико-философский трактат».', 'Ludwig Wittgenstein revolutionized 20th-century philosophy by examining how language shapes our world. As a young scholar, he astonished Cambridge professors—and a famous classroom debate over a supposedly invisible rhinoceros sparked his quest to uncover the secrets of words, logic, and truth.', 'Ludvig Vitgenštajn je u potpunosti promijenio filozofiju 20. vijeka proučavanjem jezika. Još kao mladić zbunjivao je profesore na Kembridžu, a upravo od rasprave o nevidljivom nosorogu u učionici počinje ova uzbudljiva potraga za tajnama riječi, logike i stvarnosti.', 'Кто сказал, что философия — это скучно, если прямо на лекции в Кембридже можно вместе с юным гением ловить невидимого носорога?', 'Who says philosophy has to be dry when you get to hunt for an invisible rhinoceros in a Cambridge lecture hall alongside a brilliant thinker?', 'Ko kaže da je filozofija dosadna kada u društvu mladog genija možete juriti nevidljivog nosoroga po kembridžskoj učionici?', '/covers/DP-1014.webp', '#e09b3d', 'nonfiction', 'ru', 'available', 'потертая обложка', '["funny","real"]', '["philosophy","logic","language","biography","thinking"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-театр-ханны-арендт-1015', 'DP-1015', 'Маленький театр Ханны Арендт', 'The Little Theater of Hannah Arendt', 'Malo pozorište Hane Arent', 'Марион Мюллер-Колар', 'Marion Muller-Colard', 'Marion Miler-Kolar', 'Клеманс Поле', 'А+А', NULL, NULL, 6, 16, 'middle', 'Ханна Арендт (1906–1975) занималась политической философией, особенно её волновали проблемы холокоста и фашизма. «Как люди допустили эти ужасы?» — спрашивала она тех, кто видел, как Германия возвысила Гитлера, и кому удалось сбежать из концлагеря. В детской книге Ханна Арендт встречает девочку Ханну, которая так похожа на неё в детстве. Они путешествуют по разным местам: это и греческий полис, и хмурый лес, и квартира самой Арендт. Взрослая Ханна объясняет маленькой, почему спрятаться от проблем в своей уютной норе — это не выход.', 'Hannah Arendt (1906–1975) was a political philosopher deeply concerned with the dangers of totalitarianism and fascism. In this imaginative introduction to philosophy, adult Hannah meets a young girl named Hannah who looks strikingly like her younger self. Together, they journey through ancient Greek city-states, shadowy forests, and Hannah''s quiet apartment, discovering why hiding away in a cozy burrow is never an option when the world needs our courage.', 'Hana Arent (1906–1975) bila je politička filozofkinja koju su duboko pogađala pitanja fašizma i slobode. U ovoj maštovitoj knjizi za djecu, odrasla Hana susrijeće djevojčicu Hanu, koja neodoljivo podsjeća na nju u djetinjstvu. Zajedno putuju kroz starogrčki polis, tajanstvenu šumu i Hanin stan, otkrivajući zašto skrivanje u sopstvenoj udobnoj jazbini nikada nije rješenje kada svijet traži našu hrabrost.', 'Мудрая философская сказка о том, как научиться думать самостоятельно и почему нельзя прятаться в ракушку, когда вокруг бушует мир.', 'A tender, philosophical journey that gently reminds young thinkers why staying silent is never a real refuge.', 'Nježan filozofski uvod u važne teme koji djecu uči zašto ćutanje i skrivanje nikada nijesu pravi izbor.', '/covers/DP-1015.webp', '#2d4a60', 'nonfiction', 'ru', 'available', 'потертая обложка', '["real","adventure"]', '["philosophy","history","biography","critical thinking","courage"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('соседи-1016', 'DP-1016', 'Соседи', 'Neighbors', 'Komšije', 'Катерина Горелик', 'Katerina Gorelik', 'Katerina Gorelik', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Эта книга - веселый, шумный дом, населенный множеством замечательных соседей. Петушиное семейство и летучие мыши, лисы и кролики, пингвины и медведи, кроты и даже драконы. Хорошо ли им живется рядом? Давайте проверим. Страницы книги "разрезаны" так, что ребенок может самостоятельно решить, кто чьим соседом будет. Их можно менять местами, создавая свой сценарий, а затем смотреть, в какие забавные ситуации попадают герои, и придумывать новые невероятные истории из их жизни.', 'This book is a lively, bustling apartment house inhabited by wonderfully quirky neighbors: a rooster family, bats, foxes, rabbits, penguins, bears, moles, and even dragons! Thanks to clever split pages, children can mix and match who lives next to whom, inventing hilarious scenarios and spinning endless imaginative stories about their chaotic co-living.', 'Ova knjiga je vesela i bučna zgrada puna neobičnih komšija: porodica pijetlova, slijepi miševi, lisice, zečevi, pingvini, medvjedi, krtice, pa čak i zmajevi! Zahvaljujući podijeljenim stranicama, djeca mogu sama odlučivati ko će kome biti komšija, stvarajući beskrajno smiješne situacije i sopstvene uzbudljive priče.', 'Переворачивайте половинки страниц, подселяйте драконов к пингвинам и хохочите над тем, какой шумный кавардак из этого выйдет!', 'Flip the split pages, move dragons in next door to penguins, and laugh at the hilarious neighborhood chaos you create!', 'Prevrćite podijeljene stranice, uselite zmaja tik do pingvina i uživajte u urnebesnom komšijskom haosu!', '/covers/DP-1016.webp', '#e2723c', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","animals","friends"]', '["interactive book","split pages","mix and match","creativity","humor"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мишки-на-новый-год-1017', 'DP-1017', 'Мишки на Новый год', 'Bears for the New Year', 'Medvjedi za Novu godinu', 'Катерина Горелик', 'Katerina Gorelik', 'Katerina Gorelik', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Под Новый год в гости к Мишкам приехали родственники: панда из Китая, гималайский мишка с Тибета и суровый русский медведь. Ведь только здесь, на Севере, можно вкусить все радости зимних каникул: прокатиться на оленях, окунуться в ледяную прорубь, посостязаться в скорости со снежной лавиной, а потом и со снежным человеком... Да еще и Дед Мороз заезжает в гости! Незабываемые впечатления!', 'Just in time for the New Year, relatives arrive to visit the polar bears: a panda from China, a Himalayan bear from Tibet, and a rugged Russian brown bear. Only in the far North can they experience every winter thrill: sleighing with reindeer, plunging into icy waters, racing an avalanche and even the Yeti... Plus, Ded Moroz himself drops by! An unforgettable holiday adventure.', 'Uoči Nove godine polarnim medvjedima stiže rodbina u goste: panda iz Kine, himalajski medvjed sa Tibeta i strogi ruski mrki medvjed. Samo ovdje na dalekom sjeveru mogu iskusiti sve zimske čarolije: juriti na irvasima, kupati se u ledenoj rupi i trkati se s lavinom i Jetićem... Uz to, u posjetu stiže i Deda Mraz!', 'Соберите медведей со всех уголков планеты в одном сугробе — и получите самый уморительный и снежный новогодний переполох!', 'Gather bears from all corners of the globe in one giant snowdrift and you get the most hilarious and frosty holiday mayhem!', 'Okupite medvjede iz svih krajeva svijeta u jednom smetu i dobićete najsmješniju i najsnježniju novogodišnju zbrku!', '/covers/DP-1017.webp', '#4a7c91', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","adventure","animals"]', '["bears","winter","new year","holidays","family"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('в-детском-саду-поросенок-1018', 'DP-1018', 'В детском саду - поросенок', 'A Pig in Kindergarten', 'Prase u vrtiću', 'Юханна Тидель, Шарлотта Рамель', 'Johanna Thydell, Charlotte Ramel', 'Johanna Thydell, Charlotte Ramel', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Что за жизнь! Так продолжаться не может. Вон - детский сад. С горки съезжают дети, пахнет свежеиспеченными булочками. А ты чувствуешь себя самым одиноким поросенком на свете. Но вдруг жизнь поворачивается к тебе своей солнечной стороной!', 'What a life! It simply cannot go on like this. Right across the fence is the kindergarten: children zooming down the slide, the sweet smell of freshly baked buns in the air... while you feel like the loneliest little pig in the world. But out of nowhere, life decides to show its sunniest side!', 'Kakav život! Ovo više ne može ovako. Eno tamo je vrtić: djeca se spuštaju niz tobogan, mirišu svježe pečene kiflice... a ti se osjećaš kao najusamljenije prase na cijelom svijetu. Ali odjednom, život se okreće na svoju najsunčaniju stranu!', 'Трогательная и ужасно забавная история о том, как одно хрюкающее одиночество нашло себе целую ораву лучших друзей!', 'A delightfully touching and funny tale about how one lonely piglet found an entire kindergarten full of best friends!', 'Dirljiva i beskrajno zabavna priča o tome kako je jedno usamljeno prase pronašlo čitav vrtić najboljih prijatelja!', '/covers/DP-1018.webp', '#e8908d', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","friends","animals"]', '["kindergarten","piglet","friendship","belonging","picture book"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('здравствуй-мама--1019', 'DP-1019', 'Здравствуй, мама!', 'Hello, Mama!', 'Zdravo, mama!', 'Катя Герман', 'Katja Gehrmann', 'Katja Gehrmann', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Книжка-картинка иллюстратора Кати Германн, обладательницы премии ЮНИСЕФ и "Золотого яблока" биеннале иллюстраторов в Братиславе. "Мама!" - пискнул маленький непонятный зверь, высунув из яйца голову. Медведь в ужасе посмотрел на существо, внезапно оказавшееся у него в лапах.', 'A tender and hilarious picture book by Katja Gehrmann, winner of the UNICEF Award and the Bratislava Biennial Golden Apple. ''Mama!'' chirps a tiny, mysterious creature poking its head out of an egg. A flabbergasted bear stares down in shock at the newborn baby suddenly thrust into his paws.', 'Dirljiva i duhovita slikovnica ilustratorke Katje German, dobitnice nagrade UNICEF-a i ''Zlatne jabuke'' u Bratislavi. ''Mama!'' – zapijukalo je neobično malo biće promolivši glavu iz jajeta. Medvjed u čudu posmatra stvorenje koje se iznenada našlo u njegovim šapama.', 'Что делать грозному медведю, если только что вылупившийся птенец решительно называет его мамой? Учиться родительской нежности!', 'What is a big, grumpy bear supposed to do when a newly hatched chick firmly calls him mama? Learn to embrace motherhood!', 'Šta da radi krupni šumski medvjed kad tek izleženi ptić čvrsto vjeruje da mu je on mama? Da nauči kako se vole djeca!', '/covers/DP-1019.webp', '#d97d3e', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","animals","friends"]', '["picture book","family","bear","parenthood","humor"]', 1792836322700, 1792845701223);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('школа-трактористов-1020', 'DP-1020', 'Школа трактористов', 'Tractor School', 'Traktorska škola', '', 'Kenneth Andersson', 'Kenet Anderson', 'Салла Саволайнен', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Все любят тракторы, в этом Туре Персон уверен. На своей ферме он открыл школу трактористов. Те, кто сюда пришел, смогут ездить взад и вперед, подниматься и спускаться с горки, объезжать препятствия, ездить в ряд... Но больше всего ученики хотят устроить тракторный слалом. - Ни в коем случае, - говорит Туре. - Вам еще рано. И вот в один прекрасный день… Для дошкольного возраста.', 'Everyone loves tractors, and Tore Persson knows it best! That''s why he opened a tractor driving school right on his farm. The students learn to drive back and forth, conquer steep hills, navigate tricky obstacles, and drive neatly in a row. But what they really want is an exhilarating tractor slalom! "Absolutely not," says Tore. "You''re not ready yet." Until one fine day...', 'Svi vole traktore, u to je Tore Person sasvim siguran! Zato je na svojoj farmi otvorio pravu školu za traktoriste. Đaci ovdje uče kako da voze naprijed i nazad, savladavaju uzbrdice, izbjegavaju prepreke i voze u koloni... Ipak, najviše od svega priželjkuju traktorski slalom! „Nipošto,” kaže Tore, „još je rano.” A onda, jednog lijepog dana...', 'Заводите моторы: на ферме у Туре даже самые юные водители освоят крутые виражи на тракторе!', 'Start your engines: on Tore''s farm, even the youngest drivers can master wild tractor turns and obstacle courses!', 'Upalite motore: na Toreovoj farmi čak i najmlađi vozači uče prave traktorske vratolomije!', '/covers/DP-1020.webp', '#4a7c29', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","adventure"]', '["tractors","farm","vehicles","driving","humor"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гномы-1021', 'DP-1021', 'Гномы', 'Gnomes', 'Patuljci', 'Мацей Шиманович', 'Maciej Szymanowicz', 'Maciej Szymanowicz', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Полная деталей, веселья и невероятных фактов книга о гномах. Узнайте, что эти маленькие создания делают в наших домах, в лесу, сказках и цветочных горшках. Читайте книгу и рассматривайте смешных гномов, их средства передвижения, жилища, спортивные соревнования и игры. А еще узнайте, за что наказаны садовые гномики, какой рост самого маленького гнома, как осуществить восхождение на высоту 8456 к.н.у.к. (калорий над уровнем коржика), что помогает гномам улизнуть из поля зрения человека и что это за болезнь такая - гномический хохотунчик.', 'A detail-packed, hilarious, and fact-filled book all about gnomes! Discover what these tiny creatures are up to inside our homes, deep in the woods, across fairy tales, and right in flower pots. Explore their whimsical vehicles, hidden underground dwellings, sporting tournaments, and games. Find out why garden gnomes are actually being punished, just how tall the world''s tiniest gnome is, and what mysterious ailment causes the uncontrollable gnome giggles!', 'Knjiga prepuna detalja, humora i nevjerovatnih činjenica o patuljcima! Saznajte šta ova sićušna stvorenja rade po našim domovima, u šumi, u bajkama i saksijama za cvijeće. Istražite njihova smiješna prevozna sredstva, tajne domove, sportska takmičenja i igre. Otkrijte zašto su baštenski patuljci zapravo kažnjeni, koliki je najmanji patuljak na svijetu i kakva je to zarazna boljka zvana patuljasti kikot!', 'Остроумная и безумно детальная псевдоэнциклопедия, после которой вы точно начнёте проверять цветочные горшки и карманы на наличие крошечных бородатых соседей!', 'A delightfully witty, intricately illustrated encyclopedia that will have you inspecting every flower pot and coat pocket for tiny bearded neighbors!', 'Duhovita i čudesno detaljna enciklopedija zbog koje ćete sigurno početi da provjeravate saksije i džepove u potrazi za sićušnim bradatim komšijama!', '/covers/DP-1021.webp', '#d84a38', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","magic"]', '["gnomes","encyclopedia","humor","fairy-tale creatures","illustrations"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('летчик-и-маленький-принц-1022', 'DP-1022', 'Летчик и Маленький принц', 'The Pilot and the Little Prince: The Life of Antoine de Saint-Exupéry', 'Pilot i Mali princ: Život Antoana de Sent Egziperija', 'Петр Сис', 'Peter Sís', 'Peter Sis', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Антуан де Сент-Экзюпери родился во Франции в 1900 году. В то время как раз изобрели аэропланы, и Антуан с детства мечтал летать. Он вырос, стал летчиком, и в его жизни начались настоящие приключения. Он был одним из первых пилотов почтовой авиации и вместе с друзьями помогал прокладывать новые воздушные пути в удаленные уголки мира. Антуан летал над горами и пустынями, боролся с ветрами и грозами, и даже пытался поставить авиационные рекорды. Несколько раз он попадал в аварии. Во время полетов он думал о жизни на земле и в небе, эти размышления подтолкнули его написать историю о "Маленьком принце", которую полюбили читатели во всем мире. Книга, созданная Петром Сисом, посвящена автору этой удивительной сказки.', 'Antoine de Saint-Exupéry was born in France in 1900, right when airplanes were invented, and he dreamed of flying from a young age. He grew up to become a pioneering airmail pilot, braving storms and charting uncharted routes across mountains and deserts. His poetic musings during those solitary flights inspired the timeless masterpiece ''The Little Prince''. Celebrated artist Peter Sís weaves an enchanting, breathtakingly illustrated biography of the adventurer and visionary author.', 'Antoan de Sent Egziperi rođen je u Francuskoj 1900. godine, u osvit avijacije, i od malih nogu maštao je o letenju. Odrastao je u hrabrog poštanskog pilota koji je krčio rute preko opasnih planina i pustinja. Tokom samotnih letova između neba i zemlje razmišljao je o životu, što ga je nadahnulo da stvori voljenog ''Malog princa''. Kroz očaravajuće ilustracije, Peter Sis dočarava nevjerovatan život ovog vječnog sanjara.', 'Взлетите выше облаков и откройте удивительную историю смелого мечтателя, подарившего миру «Маленького принца»!', 'Soar high above the clouds and discover the daring, poetic true story of the dreamer who gave us ''The Little Prince''!', 'Uzdignite se iznad oblaka i otkrijte čudesnu istinitu priču o hrabrom sanjaru koji nam je podario ''Malog princa''!', '/covers/DP-1022.webp', '#20436b', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","real","magic"]', '["биография","авиация","маленький принц","самолеты","мечты"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('там-где-живут-чудовища-1023', 'DP-1023', 'Там, где живут чудовища', 'Where the Wild Things Are', 'Tamo gdje su divlja stvorenja', 'Морис Сендак', 'Maurice Sendak', 'Moris Sendak', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', '"В тот вечер Макс нарядился волком и устроил шурум-бурум. А потом бурум-шурум. А мама сказала: "Ах ты чудовище!" А Макс сказал: "Я страхобраз, и я тебя съем!" А мама отправила его спать. Без ужина". Кажется, эта ситуация знакома миллионам родителей во всех уголках света. Ребенок, который так расшалился, что не может остановиться. И мама, которая не хочет терпеть непослушание и невежливость. Что будет дальше? Терапия для взрослых, как проявлять в стрессовых ситуациях выдержку и терпение? Поучительный рассказ для ребенка, как нельзя себя вести и что за это бывает?', 'One night Max puts on his wolf suit and makes mischief of one kind and another, until his mother calls him a ''wild thing'' and sends him to bed without supper. Soon, a wild forest grows in his bedroom, leading Max across the ocean to the land where the wild things are. A world-famous classic celebrating children''s fierce imagination, emotional storms, and the reassuring warmth of returning home to a dinner that is still hot.', 'Jedne večeri dječak Maks oblači svoje vučje odijelo i pravi nestašluke sve dok ga mama ne nazove ''divljim stvorenjem'' i ne pošalje u krevet bez večere. Ubrzo iz njegove sobe izrasta čitava šuma, a okean ga nosi u zemlju gde žive divlja stvorenja. Vanvremenski klasik o neobuzdanoj dječjoj mašti, ljutnji i povratku tamo gdje te neko voli najviše na svijetu.', 'Лучшее в мире напоминание о том, что даже самым свирепым волкам иногда жизненно необходим тёплый мамин ужин.', 'The world''s greatest reminder that even the fiercest little wolves secretly just want a warm supper waiting for them at home.', 'Najljepši podsjetnik na to da čak i najstrašnija divlja stvorenja na kraju žele samo toplu večeru i zagrljaj.', '/covers/DP-1023.webp', '#2c4c47', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","magic","spooky"]', '["monsters","imagination","classic","family","emotions"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кенни-и-его-окно-1024', 'DP-1024', 'Кенни и его окно', 'Kenny''s Window', 'Keni i njegov prozor', 'Морис Сендак', 'Maurice Sendak', 'Moris Sendak', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', '«Кенни и его окно» - первая книга, написанная и проиллюстрированная Морисом Сендаком, автором бестселлера «Там, где живут чудовища». Кенни просыпается посреди ночи и вспоминает, что во сне он видел сад, наполовину лунный, наполовину солнечный, а в саду - четырехногого петуха. Чтобы вернутся в волшебный сад, нужно ответить на семь вопросов, заданных петухом. В этой книге Сендак вновь говорит с ребенком на его тайном языке. На этом же языке говорят игрушки, а взрослые не понимают его так же, как не умеют слушать ночь. Это книга о поисках себя, поисках ответов на сложные, иногда невозможно сложные вопросы. Например, как сдержать нарушенное обещание и как понять, чего ты хочешь на самом деле.', 'Kenny''s Window is the very first book written and illustrated by Maurice Sendak, the beloved creator of Where the Wild Things Are. Kenny wakes up in the middle of the night remembering a dream about a garden that is half sunlit and half moonlit, guarded by a four-legged rooster. To return to this enchanting sanctuary, Kenny must find answers to seven mysterious questions posed by the rooster. In this tender, philosophical tale, Sendak speaks directly to children in their secret language—a language toys know by heart, but adults have forgotten how to hear. It is a quiet quest about growing up, keeping promises, and discovering what you truly wish for.', '„Keni i njegov prozor“ je prva knjiga koju je napisao i ilustrovao Moris Sendak, autor kultnog remek-djela „Tamo gdje su čudovišta“. Keni se budi usred noći sjećajući se sna o vrtu koji je napola obasjan mjesečinom, a napola suncem, i u kojem živi neobičan četvoronogi pijetao. Da bi ponovo pronašao put do tog čarobnog mjesta, mora odgovoriti na sedam zagonetnih pitanja. U ovoj tihoj, poetičnoj priči Sendak se obraća djeci na njihovom tajnom jeziku—onom koji igračke savršeno razumiju, a odrasli prečesto zaboravljaju. To je nježna priča o unutrašnjoj potrazi, savladavanju nedoumica i otkrivanju svojih pravih želja.', 'Тонкая, созерцательная притча о ночных снах, детских секретах и семи загадках, ответы на которые даже взрослые ищут всю жизнь.', 'A tender, dreamy parable about childhood secrets, nighttime wonders, and seven big questions that even grown-ups spend a lifetime trying to answer.', 'Nježna, sanjiva priča o dječijim tajnama, noćnim čudima i sedam zagonetki na koje čak i odrasli čitavog života traže odgovore.', '/covers/DP-1024.webp', '#3b4e6b', 'nonfiction', 'ru', 'available', '4-8 лет', '["magic","real"]', '["dreams","philosophy","growing up","nighttime","classics"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лафкадио-или-лев-который-отстр-1025', 'DP-1025', 'Лафкадио, или Лев, который отстреливался', 'Lafcadio: The Lion Who Shot Back', 'Lafkadio, lav koji je uzvratio paljbu', 'Шел Сильверстайн', 'Shel Silverstein', 'Šel Silverstin', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Как все на свете устроено? Кто-то – охотник, а кто-то – лев. Охотники палят из ружей по львам, а львы стараются съесть охотников. А что случится, если лев и охотник поменяются местами? Лев будет стрелять, ну а охотник, где теперь этот охотник... Герой книги Шела Силверстайна Лафкадио - как раз тот лев, который начал отстреливаться. А еще с элегантной небрежностью носить костюмы, курить сигары и наслаждаться мармеладками, простите, мурр-меладками. Короче, он совсем перестал быть львом, настолько, что отправился однажды на охоту. Изменил ли Лафкадио самому себе, утратив львиную сущность? Стал ли он счастливее? Что случается, когда ты теряешь свое место в жизни, и находишь ли новое? Этими вопросами уже более тридцати лет задаются читатели знаменитой книги Шела Силверстайна. Да и сам автор – поэт, писатель, художник-карикатурист, композитор, музыкант, драматург, иллюстратор – сразу ли он нашел свой путь? Он воевал в Корее, а по возвращению в США стал рисовать карикатуры для журналов, а еще продавать хотдоги и, поверьте, он был чертовски хорошим продавцом хотдогов. А потом почти 20 лет сотрудничал с журналом Playboy, писал пьесы и ставил спектакли, сочинял музыку и тексты песен для популярных музыкантов, пока один друг не уговорил Силверстайна попробовать написать книгу для детей. Шел подумал и согласился. Так появилась на свет эта книга – «Лафкадио. Лев, который отстреливался», затем – Giraffe and a Half, ну и, конечно, знаменитое «Щедрое дерево».', 'What happens when a lion refuses to be hunted and learns to shoot back? Lafcadio becomes a world-renowned marksman, trading the wild jungle for tailored suits, luxury hotel suites, and endless piles of marshmallows. Yet behind the dazzling circus act and high-society fame lies a bittersweet dilemma: is he still a wild lion, or has he become a civilized human? Shel Silverstein''s beloved, delightfully offbeat classic is a profound and witty fable about identity, belonging, and the courage to find one''s true self.', 'Šta se dešava kada lav odbije da bude plijen i nauči da puca? Lafkadio postaje proslavljeni strijelac koji divljinu mijenja za elegantna odijela, hotele i beskrajne gomile maršmelou slatkiša. Ipak, iza glamura visokog društva skriva se velika dilema: da li je on još uvijek lav, ili je postao čovjek? Ovaj bezvremeni, duhoviti i dirljivi klasik Šela Silverstina postavlja važno pitanje o identitetu i pronalaženju sopstvenog mjesta na svijetu.', 'Мудрая и гомерически смешная притча о льве в смокинге с маршмеллоу, которая ненавязчиво учит главному — всегда оставаться собой.', 'A wise and uproariously funny parable about a marshmallow-loving lion in a tuxedo that gently asks the biggest question: who are we really?', 'Mudra i urnebesno smiješna priča o lavu u smokingu koji obožava slatkiše, a koja nas uči onom najvažnijem — kako ostati svoj.', '/covers/DP-1025.webp', '#d97724', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","animals","real"]', '["identity","humor","lions","fable","classic"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('это-книжка-1026', 'DP-1026', 'Это книжка', 'It''s a Book', 'To je knjiga', '', 'Lane Smith', 'Lejn Smit', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Мы все больше зависим от всевозможных приспособлений и гаджетов. Вот, например, этот текст вы читаете на экране своего компьютера или даже телефона. Вы можете прокрутить страницу вниз, чтобы рассмотреть иллюстрации, движением пальцев увеличить или уменьшить кусок страницы и даже поставить «лайк»! Нашим детям не нужно объяснять, как запустить видео в Youtube или сделать фотографию с айфона. Мы читаем в метро e-book, слушаем аудиокниги в машине, и уже привыкаем к спецэффектам в ай-падах. Может, вообще мы все скоро забудем, что такое бумажные книги? Детей будут специально водить в библиотеки, как в музеи, чтобы показать им чудо чудное — толстые и тонкие книжки в твердом переплете или мягкой обложке, со статичными иллюстрациями, не издающими никаких звуков. А, может, у вас есть знакомые взрослые, которые почти забыли, каково это листать страницы, улавливать еле слышный запах типографской краски, ощупывать фактурные элементы на обложке? Чтобы мы все помнили, что такое книга и для чего она нужна, мы и выпустили эту книжку-картинку, книжку-шутку с незамысловатым, но исчерпывающим названием «Это книжка». Ее страницы нельзя прокрутить, ее герои размахивают мечами из слов, она не посылает твиты, и мышки у нее тоже нет. Это просто книжка. Остроумная и симпатичная. Чтобы мы не забыли, какие они, книжки.', 'Can it scroll? Does it text, tweet, or need a Wi-Fi password? In an age dominated by touchscreens and endless notifications, an inquisitive donkey tries to figure out how this strange paper contraption works—only to discover the timeless, rechargeable-free magic of simply reading. A brilliantly witty picture book celebrating the irreplaceable charm of physical books.', 'Može li da skroluje? Šalje li tvitove ili traži lozinku za vaj-faj? U svijetu ekrana i gedžeta, radoznali magarac pokušava da shvati kako ova neobična papirna spravica uopšte radi — i otkriva bezvremensku čaroliju čitanja bez punjača. Pronicljiva i urnebesna slikovnica koja podsjeća i djecu i odrasle na jedinstveni šarm pravih knjiga.', 'Заряжать не нужно, пароль не требуется: уморительный манифест о том, почему бумажная страница всегда победит любой экран!', 'No battery, no Wi-Fi, no password needed: a hilarious, timeless reminder of why real paper books still reign supreme!', 'Ne treba punjač niti vaj-faj: urnebesna slikovnica koja podsjeća zašto je prava papirna knjiga nenadmašna!', '/covers/DP-1026.webp', '#b8352b', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","real"]', '["reading","books","humor","gadgets","picture book"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('люди-в-картинках-1027', 'DP-1027', 'Люди в картинках', 'People', 'Ljudi u slikama', 'Блексболекс', 'Blexbolex', 'Blexbolex', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Чем биолог похож на астронома? А чем спящий отличается от больного? Что общего у художника и маляра? А у полицейского и вора? А у оратора и заклинателя змей? Ну что, много мыслей пришло в голову? Но правильного ответа нет! Ведь все ответы правильны. Блексболекс предлагает читателю или, даже лучше сказать, ЗРИТЕЛЮ бесконечно фантазировать, глядя на самых разных людей, среди которых появляются придуманные и реальные, добрые и злые, взрослые и дети. Как и в жизни, разнообразие людей в этой книге бесконечно, но все здесь они находят себе место, образуя забавные пары - в чем-то похожие, а в чем-то невероятно разные. «Люди в картинках» в 2009 году получила приз «Самая красивая книга в мире» на Лейпцигской книжной ярмарке.', 'How is a biologist like an astronomer? What separates a sleeper from a patient, or an artist from a house painter? French artist Blexbolex invites viewers to imagine without limits as they explore a kaleidoscope of human beings through striking, retro screen-printed illustrations. Awarded the ''World''s Most Beautiful Book'' prize at the Leipzig Book Fair, this visual masterpiece pairs people into clever, thought-provoking contrasts and harmonies.', 'Po čemu je biolog sličan astronomu? Kako se spavač razlikuje od bolesnika, a slikar od molera? Francuski ilustrator Blexbolex poziva posmatrače da maštaju bez granica dok otkrivaju nevjerovatnu raznolikost ljudi kroz upečatljive retro ilustracije. Nagrađena priznanjem za „Najljepšu knjigu na svijetu” na Lajpciškom sajmu knjiga, ova vizuelna poslastica spaja likove u neočekivane, duhovite i mudre parove.', 'Эта потрясающая шелкография учит видеть связи между самыми разными людьми и доказывает, что в искусстве не бывает неправильных ответов!', 'This stunning retro visual feast connects unexpected people across every walk of life, proving there are no wrong answers in how we see each other!', 'Ova očaravajuća vizuelna poslastica spaja najrazličitije ljude i dokazuje da nema pogrešnih odgovora kada posmatramo svijet oko sebe!', '/covers/DP-1027.webp', '#d95338', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["real","funny"]', '["professions","visual arts","screen printing","picture book","philosophy"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('два-трамвая-1028', 'DP-1028', 'Два трамвая', 'Two Trams', 'Dva tramvaja', 'Иосиф Бродский', 'Joseph Brodsky', 'Josif Brodski', 'Анна Десницкая', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Иллюстрации к книге родились не только из бумаги и красок, но и из картона, клея, трубочек для напитков, старых пуговиц, медной проволоки, крышек пластиковых бутылок. С их помощью появились сначала «герои» стихотворения — трамваи, а потом и вырос целый город — с улицами, домами, рельсами и жителями. Благодаря оформлению, напоминающему театральные декорации, действие «Двух трамваев» разыгрывается перед вами как будто на сцене, настолько объемными и живыми иллюстрации выглядят на бумаге. Благодаря им с детьми можно не только читать стихи, но и внимательно рассматривать картинки, пытаясь угадать, из чего все сделано.', 'The illustrations for this book were created not just from paper and paint, but from cardboard, glue, drinking straws, vintage buttons, copper wire, and bottle caps. Through these humble scraps, the tram heroes of Joseph Brodsky''s poem come alive alongside a bustling city of tracks, buildings, and passersby. Reminiscent of miniature theater sets, the 3D paper dioramas invite young readers both to enjoy the melodic verses and to playfully guess what each tiny object was crafted from.', 'Ilustracije za ovu knjigu nijesu nastale samo od papira i boja, već i od kartona, ljepila, slamčica za piće, starih dugmadi, bakarne žice i plastičnih čepova. Uz njihovu pomoć oživjeli su junaci pjesme — dva tramvaja — a potom je izrastao i čitav grad sa ulicama, šinama i prolaznicima. Poput pozorišne scene, ove trodimenzionalne slike vode vas kroz dirljivu poemu Josifa Brodskog i pozivaju djecu da istraže od čega je svaki detalj majstorski napravljen.', 'Поэзия нобелевского лауреата и настоящая театральная магия из картона и пуговиц — вы непременно захотите смастерить свой трамвайчик сразу после прочтения!', 'Nobel laureate poetry meets theatrical diorama magic crafted from buttons and cardboard — you''ll want to build your own little tram right after reading!', 'Poezija nobelovca i prava pozorišna magija od kartona i dugmadi — poželjećete da napravite sopstveni tramvaj čim sklopite korice!', '/covers/DP-1028.webp', '#b84233', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["friends","real"]', '["poetry","trams","city","illustrations","friendship"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('какого-цвета-мистер-лис--1029', 'DP-1029', 'Какого цвета мистер Лис?', 'What Color Is Mr. Fox?', 'Koje je boje gospodin Lisac?', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Во время вечерней прогулки Мистер Лис увидел то, что никогда до этого не замечал. На его пути встречается чудесный голубой цветок, и по сравнению с ним Мистер Лис чувствует себя совершенно бесцветным. В попытке измениться он красит свою шерстку соком ягод, купается в грязи, укутывается в мох. Но каждый раз, когда он спрашивает у других животных, какого он цвета, они воротят нос и советуют ему поскорее помыться... Но однажды весенний дождик смывает с Лиса результаты его неудачных попыток стать другим, его настоящий цвет замечают дети, и Мистер Лис наконец может посмотреть на себя другими глазами! Шведский автор - лауреат премии А. Линдрен - Стефан Каста говорит: можно пытаться изменить внешность, но кто-то обязательно заметит и полюбит тебя таким, какой ты есть. А иллюстратор Стаффан Гносспелиус при помощи раскрашенных офортов виртуозно показывает прекрасный сказочный лес, где Мистер Лис постепенно учится быть собой.', 'During an evening stroll, Mr. Fox spots a breathtakingly vibrant blue flower and suddenly feels completely dull and colorless by comparison. Determined to transform himself, he paints his fur with berry juice, bathes in mud, and wraps himself in moss—only to be told by other forest creatures to go take a bath. But when a gentle spring shower washes away his disguises, children marvel at his gorgeous natural coat, helping him finally see his true worth. A tender, beautifully etched Swedish tale about self-acceptance and the joy of being yourself.', 'Tokom večernje šetnje, gospodin Lisac ugleda predivan plavi cvijet i odjednom se osjeti potpuno bezlično i bezbojno. U želji da se promijeni, on farba svoje krzno sokom od šumskih bobica, valja se u blatu i umotava u mahovinu — ali ostale životinje okreću glavu i savjetuju mu da se hitno okupa. Ipak, kada proljećna kiša spere sve maske, djeca se dive njegovoj predivnoj riđoj boji. Ova dirljiva švedska priča, obogaćena očaravajućim grafikama, uči djecu da prihvate i zavole sebe onakvima kakvi jesu.', 'Трогательная лесная история с потрясающими гравюрами, напоминающая: не нужно краситься черничным соком и мхом, чтобы быть по-настоящему прекрасным!', 'A touching forest tale with stunning etchings, reminding us that there''s no need to dye yourself with berry juice and moss just to be truly wonderful.', 'Dirljiva šumska priča sa predivnim grafikama koja nas podsjeća da ne moramo da se bojimo borovnicama i mahovinom da bismo bili posebni.', '/covers/DP-1029.webp', '#c45524', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста', '["animals","friends"]', '["foxes","self-acceptance","forest","identity","picture book"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('каштанка-1030', 'DP-1030', 'Каштанка', 'Kashtanka', 'Kaštanka', 'Антон Чехов', 'Anton Chekhov', 'Anton Čehov', 'Таня Кормер', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Уникальность настоящего издания "Каштанки" в иллюстрациях Татьяны Кормер, одной из ведущих современных художников книги, которые выполнены в технике хромолитографии. Популярность хромолитографии в книжной иллюстрации, особенно детской, пришлась на вторую половину XIX - первую половину XX вв. К этой технике часто обращались такие известные иллюстраторы как В.Лебедев, Н.Тырса, В. Конашевич и другие. Сейчас же книжные художники практически ее не используют.Стиль и техника Татьяны Кормер в "Каштанке" отсылают нас к книжной эстетике рубежа XIX-XX веков. В 2010 году эскизы иллюстраций Татьяны Кормер к "Каштанке" были удостоены диплома международной премии CJBook Picture. Подробнее: https://www.labirint.ru/books/276542/', 'This exquisite edition of Chekhov''s timeless classic about a lost little dog who joins the circus is brought to life through Tatiana Kormer''s rare chromolithograph illustrations. Echoing the book aesthetics of the turn of the 20th century, this award-winning edition captures Kashtanka''s tender, loyal, and unforgettable journey back to where her heart belongs.', 'Ovo posebno izdanje Čehovljevog vanvremenskog klasika o izgubljenoj kuci koja dospijeva u cirkus oživljeno je rijetkom tehnikom hromolitografije slikarke Tatjane Kormer. Prizivajući estetiku ilustracije s prelaza 19. u 20. vijek, ova nagrađivana knjiga donosi svu nježnost, vjernost i toplinu nezaboravne priče o maloj Kaštanki.', 'Трогательная классика о преданной собачьей душе в потрясающем винтажном оформлении, от которого замирает сердце!', 'A touching classic about a devoted little dog, wrapped in stunning vintage artwork that will warm readers of all ages.', 'Dirljivi klasik o vjernoj riđoj kuci u čarobnom starinskom ruhu koji osvaja i grije srce u svakom uzrastu.', '/covers/DP-1030.webp', '#9a482b', 'nonfiction', 'ru', 'available', 'Для среднего школьного возраста.', '["animals","real","friends"]', '["dogs","classic","circus","loyalty","art"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('записки-и-зарисовки-о-втором-п-1031', 'DP-1031', 'Записки и зарисовки о втором путешествии по острову Синего солнца', 'Notes and Sketches from the Second Journey Across the Island of the Blue Sun', 'Bilješke i skice o drugom putovanju po Ostrvu Plavog Sunca', 'Илья Донец, Маргарита Щетинская', 'Ilya Donets, Margarita Shchetinskaya', 'Ilja Donec, Margarita Ščetinska', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', '"…Где - то в глубине синего океана, на одной синей-синей планете каждый день просыпается Синее Солнце. Отправив в бесконечность остатки своих солнечных снов, светило потягивается, делает несколько наклонов, поворачивается вокруг своей оси и протягивает свои лучи к острову Синего Солнца". Так начинаются "Записки и зарисовки о втором путешествии по острову Синего Солнца", оставленные служащим банка без денег Аркадием. Это фантастическая повесть, в которой мы узнаем силу репейного сока, посетим театр гигантских марионеток, отправимся в путешествие птицерыбами Рыбофлота, чтобы в конце пуститься в погоню за одноглазым Циклоном. Во время своего путешествия Аркадий настолько тщательно вел записи, что, несмотря на фонтан каламбуров и неожиданных поворотов событий, получилось почти научное и энциклопедическое описание острова.', 'Somewhere in the depths of a blue ocean on a deep-blue planet, the Blue Sun awakens every day to shine over its namesake island. Left behind by Arkady, a penniless bank clerk, these notes chronicle an extraordinary expedition. Discover the hidden powers of burdock juice, watch giant marionettes perform, sail with the flying-fish fleet, and join a daring pursuit of a one-eyed Cyclone. With meticulous detail, puns, and whimsical twists, Arkady''s journal reads like an utterly charming, quasi-scientific encyclopedia of an impossible world.', 'Negdje u dubinama plavog okeana na jednoj plavoj planeti, Plavo Sunce se budi svakoga dana i obasjava svoje čudesno ostrvo. Ostavljene od strane Arkadija, bankarskog službenika bez novca, ove bilješke vode nas u nevjerovatnu ekspediciju. Otkrijte tajnu snagu soka od čička, posjetite pozorište džinovskih marioneta, zaplovite flotom riba-ptica i krenite u potjeru za jednookim Ciklonom. Kroz pregršt igara riječima i neočekivanih obrta, Arkadijev dnevnik donosi zabavan i gotovo enciklopedijski vodič kroz potpuno fantastičan svijet.', 'Причудливый псевдонаучный травелог с птицерыбами и каламбурами, который перевернет ваше представление о географии фантастических миров!', 'A whimsical, pseudo-scientific travelogue brimming with flying fish-birds and witty puns that will reinvent how you imagine fantastical geography!', 'Neobičan i duhovit putopis pun riba-ptica i maštovitih dosjetki koji nudi pravu enciklopediju nemogućih svjetova!', '/covers/DP-1031.webp', '#1b4d89', 'nonfiction', 'ru', 'available', 'дома', '["adventure","magic","funny"]', '["travelogue","fantasy","encyclopedia","humor","creatures"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('город-добрых-дел-1032', 'DP-1032', 'Город добрых дел', 'What Do People Do All Day?', 'Šta ljudi rade cijeli dan?', 'Ричард Скарри', 'Richard Scarry', 'Ričard Skeri', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Одна из самых знаменитых книг Ричарда Скарри. Из нее малыши во всем мире узнают о том, что делают их родители на работе. С помощью нее взрослые объясняют малышам, как устроен мир взрослых.', 'One of Richard Scarry''s most celebrated classics. Packed with charming animal characters and bustling cross-sections, it introduces young readers to the grown-up world of work and shows how an entire community thrives together.', 'Jedna od najslavnijih knjiga Ričarda Skerija. Kroz šarmantne životinjske likove i detaljne ilustracije, mališani otkrivaju čime se odrasli bave na poslu i kako zapravo funkcioniše cijeli jedan grad.', 'Загляните за кулисы взрослого мира: здесь свинки строят дома, котята пекут хлеб, и всё вертится как слаженный механизм!', 'Peek behind the scenes of a bustling community where pigs build houses, kittens bake bread, and every job matters!', 'Zavirite u užurbani svijet odraslih gdje prasići grade kuće, a mace peku hljeb — grad u kojem svako ima svoj važan zadatak!', '/covers/DP-1032.webp', '#e58a27', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["animals","real","funny"]', '["professions","city life","community","classic","picture book"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('самая-лучшая-книжка-1033', 'DP-1033', 'Самая лучшая книжка', 'Best Storybook Ever', 'Najbolja knjiga ikada', 'Ричард Скарри', 'Richard Scarry', 'Ričard Skari', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Самые лучшие истории, стихи и сказки - с самыми любимыми персонажами единственного и неповторимого Ричарда Скарри. Как всегда у Ричарда Скарри - ребенок узнает все-все-все про мир: как смешиваются цвета, как устроено человеческое тело, счет, дни недели, времена года, профессии, путешествия и много много другого. 300 миллионов проданных копий - совокупный тираж книг Ричарда Скарри. Скарри переведен на 20 языков Мировая классика детской литературы XX столетия. 60 лет - самый читаемый, самый рассматриваемый и самый любимый детский автор и художник.', 'Packed with delightful stories, verses, and vibrant illustrations featuring Richard Scarry''s most beloved animal characters, this timeless classic explains everything about the world around us. Children will discover how colors mix, how the human body works, counting, days of the week, seasons, professions, travel, and so much more—a joyful encyclopedia of early knowledge loved across generations.', 'Ispunjena omiljenim pričama, pjesmicama i nezaboravnim likovima Ričarda Skarija, ova vanvremenska knjiga vodi djecu kroz čuda svijeta koji ih okružuje. Mališani će saznati kako se miješaju boje, kako funkcioniše ljudsko tijelo, brojeve, dane u sedmici, godišnja doba, razna zanimanja i putovanja. Svjetski klasik dječje književnosti koji se već decenijama sa radošću lista i iznova čita.', 'В этой книжке спрятан целый мир забавных зверят и важных открытий, которые можно с увлечением разглядывать часами напролёт!', 'An entire bustling world of friendly animals and endless discoveries that kids can happily explore for hours!', 'Čitav jedan užurbani svijet simpatičnih životinjica i zabavnih otkrića u kojem djeca mogu uživati satima!', '/covers/DP-1033.webp', '#d90429', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["animals","funny","real"]', '["encyclopedia","classic","animals","professions","discovery"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-из-мира-книг-1034', 'DP-1034', 'Я из мира книг', 'A Child of Books', 'Dijete iz svijeta knjiga', 'Оливер Джефферс', 'Oliver Jeffers, Sam Winston', 'Oliver Džefers, Sem Vinston', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Маленькая девочка - дитя книг - плывёт на своём плоту по морю слов и попадает в дом мальчика. Девочка приглашает его вместе отправиться в путешествие по миру историй… где может случиться всё, что угодно, стоит только это вообразить. Авторы так говорят о своей работе "Я из мира книг": "С самого начала мы хотели создать историю, которая показала бы нашу любовь к классическим детским книгам, но по-новому. Мы хотели поймать ту магию, которая появляется, когда ты теряешься в истории, неподвластной времени. Но сделать это так, как никто раньше не делал". Удивительно симпатичные персонажи Оливера Джефферса на замечательных иллюстрация Сэма Уинстона - настоящая ода миру книг. Сплетённые вместе сюжетом книги, уникальные иллюстрации помогают получить незабываемый опыт чтения, который побудит всех читателей, от мала до велика, исследовать, задавать вопросы и придумывать собственные истории.', 'A little girl sails her raft across a sea of words to invite a boy on an unforgettable journey through the landscapes of classic literature. Together, they scale mountains of make-believe and wander through forests of fairy tales, discovering that imagination knows no bounds. Created with mesmerizing typographical art and poetic text, this masterpiece is a heartfelt tribute to the timeless power of stories and the wonder of reading.', 'Djevojčica plovi na splavu preko mora riječi i poziva jednog dječaka na nezaboravno putovanje kroz predjele klasičnih priča. Zajedno se penju na planine mašte i lutaju kroz začarane šume bajki, otkrivajući da ne postoje granice kada se prepustimo maštanju. Kroz očaravajuću tipografiju i poetski tekst, ovo remek-djelo slavi bezvremenu magiju knjiga i radost čitanja.', 'Настоящее признание в любви к литературе, где иллюстрации буквально сотканы из строк великих историй!', 'A stunning visual love letter to reading, where landscapes and oceans are literally woven from classic tales!', 'Predivno vizuelno ljubavno pismo čitanju, u kojem su čitavi svjetovi i okeani satkani od riječi klasičnih bajki!', '/covers/DP-1034.webp', '#1b3554', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","adventure"]', '["books","reading","imagination","art","journey"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('что-мы-с-тобой-построим-1035', 'DP-1035', 'Что мы с тобой построим', 'What We''ll Build', 'Šta ćemo graditi', 'Оливер Джефферс', 'Oliver Jeffers', 'Oliver Džefers', 'Оливер Джефферс', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Отец и дочь начинают закладывать фундамент общей жизни. Они создают драгоценные воспоминания, строят дом, где будут чувствовать себя в безопасности, и выращивают в своих сердцах любовь, которая их согреет. История о безграничной родительской любви, о бесконечных возможностях, даруемых жизнью, и обо всём, что необходимо для общего будущего. Ещё один шедевр от всемирно известного автора и иллюстратора детских книг Оливера Джефферса.', 'A father and daughter lay the foundation for their shared future. Using special tools, they forge precious memories, build a safe home, and nurture boundless love to keep them warm through any storm. An inspiring and poignant ode to parental love, limitless possibilities, and everything needed to build a bright tomorrow together.', 'Otac i kćerka postavljaju temelje svoje zajedničke budućnosti. Koristeći posebne alate, oni stvaraju dragocjene uspomene, grade siguran dom i njeguju ljubav koja grije srca. Dirljiva i inspirativna priča o bezgraničnoj roditeljskoj ljubavi, prilikama koje život pruža i svemu što je potrebno za zajedničko sutra.', 'Трогательное архитектурное руководство по строительству самого важного — крепких объятий, общих планов и счастливого будущего.', 'A tender architectural blueprint for building what matters most: warm hugs, shared dreams, and a bright future together.', 'Dirljiv arhitektonski vodič za izgradnju onog najvažnijeg: toplih zagrljaja, zajedničkih snova i svijetle budućnosti.', '/covers/DP-1035.webp', '#e05938', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["real","friends"]', '["family","fatherhood","love","future","picture book"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('джек-и-джим-1036', 'DP-1036', 'Джек и Джим', 'Jack and Jim', 'Džek i Džim', 'Китти Краутер', 'Kitty Crowther', 'Kiti Krauter', '', 'Мир детства', NULL, NULL, 6, 16, 'middle', 'В "Джеке и Джиме" рассказывается о чёрном дрозде Джеке, который мечтает увидеть море, и о чайке по имени Джим. Из истории, рассказанной и нарисованной Китти Краутер, можно будет узнать о приключениях этих непохожих друг на друга, но очень дружных птиц. Китти Краутер - бельгийская писательница и иллюстратор, также лауреат премии Астрид Линдгрен 2010 года. Создала иллюстрации к более чем 35 детским книгам. Большинство из них написала она сама.', 'Jack and Jim tells the touching tale of Jack, a blackbird yearning to see the sea, and Jim, a friendly white seagull. Created by Astrid Lindgren Memorial Award winner Kitty Crowther, this poetic story follows two distinct birds who discover a shared love for books and adventure, teaching a gentle lesson about tolerance, openness, and true friendship.', '„Džek i Džim“ donosi priču o crnom kosu Džeku koji mašta o moru i galebu Džimu. Iz pera i kista Kiti Krauter, dobitnice prestižne nagrade Astrid Lindgren, stiže topla i poetska priča o dvoje vrlo različitih ptica koje povezuju ljubav prema knjigama i iskreno prijateljstvo jače od svake predrasude.', 'Мудрая и трепетная сказка о том, что для искренней дружбы черного дрозда и белой чайки не существует никаких предрассудков.', 'A gentle and profound picture book showing how a blackbird and a seagull easily prove that true friendship knows no boundaries.', 'Dirljiva i nježna priča o tome kako pravo prijateljstvo između kosa i galeba s lakoćom pobjeđuje sve razlike i predrasude.', '/covers/DP-1036.webp', '#386b77', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["friends","animals","adventure"]', '["friendship","birds","tolerance","sea","acceptance"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ночные-сказки-1037', 'DP-1037', 'Ночные сказки', 'Stories of the Night', 'Noćne priče', 'Китти Краутер', 'Kitty Crowther', 'Kiti Krauter', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', '- Расскажи мне три сказки, - попросил Медвежонок. - Хорошо, - улыбнулась Мама Медведица. Вместе с Медвежонком мы услышим три чудесные сказки: о Ночке, которая укладывала всех спать, о заблудившейся в лесу Жоре и о человеке по имени Бу, который никогда не снимал пальто.', '''Tell me three stories,'' asks Little Bear. ''Very well,'' smiles Mother Bear. Together with Little Bear, we hear three magical bedtime tales: about Night ringing her gong to put the forest to sleep, about little girl Zhora lost in the woods, and about a peculiar man named Bo who never takes off his warm coat.', '„Ispričaj mi tri priče“, zamolio je Mali Medvjed. „U redu“, nasmiješila se Mama Medvjedica. Zajedno sa Malim Medvjedom čućemo tri čudesne priče: o Noći koja gongom sve sprema na spavanje, o djevojčici Žori izgubljenoj u šumi i o čovjeku po imenu Bu koji nikada ne skida svoj topli kaput.', 'Идеальное неоновое снотворное: три уютные и чуточку таинственные сказки на ночь от лауреатки премии Астрид Линдгрен.', 'The ultimate cozy bedtime companion: three luminous, whimsical tales told under the neon glow of Mother Bear''s love.', 'Savršeni melem pred spavanje: tri tople i zagonetne bajke koje će nježno uljuljkati svakog malog sanjara.', '/covers/DP-1037.webp', '#df4976', 'nonfiction', 'ru', 'available', '?', '["magic","animals","friends"]', '["bedtime","bears","night","forest","comfort"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('перед-моим-домом-1038', 'DP-1038', 'Перед моим домом', 'In Front of My House', 'Ispred moje kuće', 'Марианна Дюбюк', 'Marianne Dubuc', 'Marianne Dubuc', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'В необычное путешествие можно отправиться прямо от порога собственного дома - лишь бы воображения хватило. Книжка-картинка канадской художницы Марианны Дюбюк (автора уже вышедших на русском "Карнавала зверей", "Почтальона Мышки", "Льва и птички") как нитка волшебного клубка ведёт читателя в сказку или в космос, и на каждом развороте нас ждут сюрпризы и загадки. Не только малыши (от 1,5 лет), но и дети постарше наверняка полюбят эту необычную историю и наверняка начнут придумывать свои. Марианна Дюбюк - автор-иллюстратор, который придумывает книжки-картинки со сложными сюжетом и структурой. Ее называют восходящей звездой французской литературы - в своих книгах она создает целые миры, как настоящий писатель.', 'An extraordinary journey can begin right on your doorstep—all you need is a spark of imagination. Acclaimed Canadian illustrator Marianne Dubuc unravels a whimsical visual thread that leaps playfully from a rooftop to an apple, into fairy tales, deep into the ocean, and straight into outer space. Packed with charming surprises and visual riddles on every page, this clever picture book invites readers of all ages to dream up limitless adventures of their own.', 'Nevjerovatno putovanje može početi na samom kućnom pragu — potrebno je samo malo mašte. Poznata kanadska ilustratorka Marianne Dubuc vodi čitaoce kroz čudesnu vizuelnu priču koja se vješto prepliće od krova kuće, preko bajki i morskih dubina, pa sve do svemira. Sa zabavnim iznenađenjima i zagonetkama na svakoj stranici, ova slikovnica osvaja i mališane i stariju djecu, podstičući ih da izmišljaju sopstvene svjetove.', 'Загляните за порог обычного домика — и вы окажетесь на вершине дерева, в сказочной чаще или посреди открытого космоса!', 'Step just outside your front door and discover an endless chain of wonders leading from rooftops to outer space!', 'Zakoračite preko kućnog praga i otkrijte beskrajni lanac čuda koji vodi od krova pa sve do svemira!', '/covers/DP-1038.webp', '#f5c342', 'nonfiction', 'ru', 'available', 'Для дошкольного возраста.', '["adventure","magic","animals"]', '["picture book","imagination","journey","visual storytelling","whimsical"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-волка-1039', 'DP-1039', 'Тайна волка', 'The Wolf''s Secret', 'Vukova tajna', '', 'Myriam Dahman, Nicolas Digard', 'Mirijam Daman, Nikola Digar', 'Джулия Сарда', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Волк — ловкий охотник, которого боится весь лес. И у него есть тайна... В самом сердце леса живёт молодая женщина. Её пение заворожило волка. Но однажды нежный голос стих...', 'The wolf is a cunning hunter feared by the entire forest, but he harbors a secret. Deep in the woods lives a young woman whose enchanting singing has completely captivated him. But one day, the gentle melody falls silent...', 'Vuk je vješt lovac koga se plaši čitava šuma, ali on krije tajnu. U samom srcu šume živi mlada žena čija je čarobna pjesma opčinila divljeg vuka. No jednog dana, nježni glas iznenada utihne...', 'Завораживающая сказка о том, как музыка способна растопить даже самое дикое волчье сердце.', 'A hauntingly beautiful modern fable about how music and kindness can soften the wildest of hearts.', 'Očaravajuća bajka o tome kako muzika i nježnost mogu smekšati i najdivljije vučje srce.', '/covers/DP-1039.webp', '#2c4a45', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","animals","friends"]', '["wolves","forest","music","friendship","fairytale"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('настоящий-кораблик-1040', 'DP-1040', 'Настоящий кораблик', 'The Real Boat', 'Pravi brodić', 'Марина Аромштам', 'Marina Aromshtam', 'Marina Aromštam', 'Виктория Семыкина', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Сказочная история о том, как бумажный кораблик искренне и сильно захотел стать настоящим кораблем. Он отправился в открытое море, чтобы найти большие корабли и понять, как ему стать таким же. Во время его путешествия ему встретятся судна самых разных размеров и назначений. И каждое будет держать свой путь. Без трудностей не обойдется, но маленький кораблик не сдастся даже в шторм. Книга Марины Аромштам и Виктории Семыкиной впервые увидела свет в Великобритании, а позже была опубликована во Франции, США и Австралии. "Настоящий кораблик" уже попадал в списки некоторых престижных конкурсов и премий, например, в шорт-лист американского конкурса 3X3 и лонг-лист 2018 Klaus Flugge Prize. Книга выиграла гран-при жюри BIBF Ananas в Пекине 2019 г и почетный приз жюри Klaus Flugge Prize в Лондоне в 2018 и была в шорт-листе американского конкурса 3X3. Эта красивая книга может стать прекрасным подарком на все случаи жизни. Не только детям, но и взрослым, которые ценят глубокие смыслы и атмосферные иллюстрации.', 'A poetic tale about a little paper boat that yearns to become a real ship. Venturing out into the vast, unpredictable ocean, he encounters vessels of all shapes and sizes, braving towering waves and stormy skies along the way. With internationally award-winning illustrations by Victoria Semykina, this touching story is an unforgettable testament to courage, perseverance, and following big dreams.', 'Bajkovita priča o malom papirnom brodiću koji je žarko želio da postane pravi brod. Otiskujući se na pučinu u potragu za velikim lađama, susreće plovila svih oblika i namjena i ne posustaje čak ni pred najstrašnijom olujom. Uz nagrađivane, očaravajuće ilustracije Viktorije Semikine, ova međunarodno priznata knjiga dira srca i djece i odraslih.', 'Вдохновляющая и невероятно красивая ода храбрости, доказывающая: даже если ты сделан из бумаги, твоему сердцу по плечу самый бурный океан.', 'An exquisitely illustrated, heartwarming voyage proving that even if you''re made of paper, you have the courage to conquer the wildest seas.', 'Raskošno ilustrovana i topla morska priča koja dokazuje da čak i krhki papirni brodić može preploviti najburniji okean.', '/covers/DP-1040.webp', '#1b4965', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","magic"]', '["sea","paper boat","courage","dreams","journey","picture book"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('почему-у-собаки-мокрый-нос-1041', 'DP-1041', 'Почему у собаки мокрый нос', 'Why Dogs Have Wet Noses', 'Zašto psi imaju mokar nos', 'Эйвинд Турсетер', 'Kenneth Steven, Øyvind Torseter', 'Kenet Stiven, Ejvind Torseter', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Давным-давно - так давно, что мир был еще совсем новенький, - пошел дождь. Да такой сильный, что не осталось на земле ни одного сухого места. И вот один человек по имени Ной построил огромный корабль, чтобы спасти людей и животных. Ной собрал всяческих животных, какие только бывают на свете. Он взял с собой даже слизняков и пауков, жуков и всяких противных букашек. Они провели в море двадцать дней и двадцать ночей, и вот однажды ковчег дал течь. "Что же делать?" - ужаснулся Ной. Кто спасет ковчег? Новую версию хорошо известной истории предлагают шотландский писатель Кеннет Стивен и норвежский иллюстратор Эйвинд Турсетер, лауреат престижных премий в области детской книги, в частности Bologna Ragazzi Award.', 'Long ago, when the world was brand new, it began to rain so hard that not a single dry spot was left on Earth. Noah built a huge ark to save people and all kinds of creatures, from towering beasts to tiny bugs. But midway through their stormy journey, the ark sprang a terrible leak! Who could possibly plug the hole and save them all? Scottish writer Kenneth Steven and acclaimed Norwegian illustrator Øyvind Torseter present an inventive, heartwarming twist on the classic tale of Noah''s Ark.', 'Davno, u vrijeme kada je svijet bio sasvim nov, pala je kiša toliko jaka da na Zemlji nije ostalo nijedno suvo mjesto. Noje je sagradio ogromnu barku kako bi spasio ljude i životinje svih vrsta. No, usred oluje na pučini, barka je počela da propušta vodu! Ko će začepiti rupu i spasiti posadu? Škotski pisac Kenet Stiven i nagrađivani norveški ilustrator Ejvind Torseter donose maštovitu i dirljivu novu verziju drevne legende o Nojevoj barci.', 'Забавный и трогательный миф о том, как любопытный и смелый собачий нос спас Ноев ковчег от неминуемого крушения!', 'A charming and witty legend revealing how one brave pup''s curious cold nose miraculously saved Noah''s Ark from sinking!', 'Šarmantna i duhovita legenda koja otkriva kako je jedna hrabra pseća njuškica spasila Nojevu barku od potopa!', '/covers/DP-1041.webp', '#4a7c8f', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["animals","funny","adventure"]', '["dogs","noah''s ark","legends","animals","illustrated"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебная-лавка-1042', 'DP-1042', 'Волшебная лавка', 'The Magic Shop', 'Čarobna prodavnica', 'Герберт Уэллс', 'H. G. Wells', 'H. Dž. Vels', 'Кирилл Челушкин', '', NULL, NULL, 6, 16, 'middle', '"Волшебная лавка" - один из самых парадоксальных и загадочных рассказов известного английского фантаста Герберта Уэллса, автора романов "Человек-невидимка", "Война миров" и др. Оригинальные иллюстрации Кирилла Челушкина, художника с мировым именем, делают книгу поистине художественным альбомом. Уникальная авторская техника и своеобразный подход к тексту превращают издание в объект культуры. Волшебная лавка, куда Уэллс приводит читателя, открывает свои двери не каждому. Это место превращений, метаморфоз, которые так легко происходят с человеком в детстве и остаются воспоминаниями на всю жизнь.', 'One of H. G. Wells''s most enchanting and enigmatic tales, ''The Magic Shop'' explores the delicate boundary between sleight-of-hand illusion and genuine wonder. Accompanied by mesmerizing illustrations from renowned artist Kirill Chelushkin, this edition turns a classic story into an exquisite art piece. It reveals a peculiar shop whose doors open only to the chosen few, capturing the elusive mystery of childhood imagination.', 'Jedna od najzagonetnijih priča H. Dž. Velsa, ''Čarobna prodavnica'' istražuje tanku granicu između mađioničarskih trikova i prave čarolije. Uz očaravajuće ilustracije Kirila Čeluškina, ovo izdanje predstavlja pravo umjetničko djelo. Vrata ovog neobičnog dućana otvaraju se samo onima koji istinski vjeruju, čuvajući nezaboravnu tajanstvenost djetinjstva.', 'Загляните за порог этой лавки, если осмелитесь поверить в настоящие чудеса, спрятанные среди теней и старинных фокусов!', 'Step across the threshold of this mysterious shop if you dare to discover real illusions lurking behind antique curiosities!', 'Zakoračite preko praga ove neobične radnje ako se usuđujete da povjerujete u pravu magiju skrivenu iza sjenki!', '/covers/DP-1042.webp', '#2b303a', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","spooky"]', '["classic","magic","illusions","mystery","art book"]', 1792836322700, 1792845701224);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ничья-вещь-1043', 'DP-1043', 'Ничья вещь', 'The Lost Thing', 'Izgubljena stvar', 'Шон Тан', 'Shaun Tan', 'Šon Tan', '', 'Мир детства', NULL, NULL, 6, 16, 'middle', 'Герой этой книги, собирая на пляже коллекцию бутылочных крышечек, встретил странное создание - вещь без хозяина и применения. Он пытается найти ей место, открывая для себя мир удивительных вещей, которых никто не замечает, потому что они не вписываются, или потому, что люди слишком заняты другими важными вещами - например, лежанием на пляже или чтением газет. В этой, как и в других своих книгах, знаменитый австралийский иллюстратор Шон Тан создает целую страну - Окраину - с возносящимися в небо небоскребами и населяющими их странными существами и предметами. Его книги из тех, что можно рассматривать до бесконечности, с каждым разом открывая для себя что-то новое. В 2001 году "Ничья вещь" была выбрана в Австралии книжкой-картинкой года. Она получила почетное упоминание на Международной книжной ярмарке в Болонье, премии в области книжной иллюстрации Aurelius и Spectrum в США. Снятый по ней мультфильм в 2010 году был назван лучшим короткометражным фильмом года на крупнейшем в мире международном анимационном фестивале в Аннеси.', 'While searching for bottle tops along a crowded beach, a young boy stumbles upon a bizarre, unclassifiable creature—a lost thing with no owner and no obvious purpose. In a busy, indifferent world filled with towering skyscrapers and preoccupied adults, he sets out to find where it truly belongs. Shaun Tan’s internationally acclaimed picture book is a hauntingly beautiful, philosophical tale about belonging, conformity, and noticing the hidden magic in everyday life.', 'Dok na plaži sakuplja čepove za svoju kolekciju, jedan dječak pronalazi čudno, neobično stvorenje — izgubljenu stvar bez vlasnika i jasne svrhe. U užurbanom svijetu punom nebodera i ravnodušnih odraslih, on pokušava da joj pronađe dom, otkrivajući skriveni kutak pun čuda koja rijetko ko primjećuje. Ova nagrađivana priča Šona Tana pravo je vizuelno i filozofsko remek-djelo o pripadanju i empatiji.', 'Трогательная и глубокая притча о том, как важно заметить и согреть того, кто совершенно не вписывается в привычный мир.', 'A tender, surreal masterpiece that gently reminds us to slow down, look closely, and make room for the wonderfully odd.', 'Dirljivo i nadrealno remek-djelo koje nas podsjeća da zastanemo, pogledamo pažljivije i pronađemo mjesto za neobična čuda.', '/covers/DP-1043.webp', '#b85c38', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","friends","real"]', '["picture book","friendship","philosophy","surrealism","acceptance"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прибытие-1044', 'DP-1044', 'Прибытие', 'The Arrival', 'Dolazak', 'Шон Тан', 'Shaun Tan', 'Šon Tan', '', 'Комильфо', NULL, NULL, 6, 16, 'middle', '"Что заставляет многих людей бросить все и отправиться в одинокое путешествие в неизведанную страну, где нет ни семьи, ни друзей, где все зыбко, где будущее неопределенно? Этот графический роман - история каждого переселенца, каждого беженца, каждого, кто был вынужден покинуть родные места. Это дань уважения всем тем, кто проделал подобный путь." Шон Тан - автор и художник-иллюстратор таких книг, как "Ничья вещь", "Красное дерево" и "The Arrival. Прибытие". Все они были удостоены многочисленных международных наград. Мультфильм по книге "Ничья вещь" в 2011 году получил "Оскар" как самый лучший анимационный короткометражный фильм. Графический роман "The Arrival. Прибытие" получил премию Болонья Рагацци, а также был признан лучшей книгой с картинками. Книги Шона активно переводятся и издаются по всему миру. В 2001 году Шон получил премию как лучший художник-фантаст, а в 2011 году он стал лауреатом премии Астрид Линдгрен - самой авторитетной награды в области детской литературы. Шона Тана называют "непревзойденным мастером визуального повествования"', 'What drives so many people to leave everything behind and embark on a solitary journey to an unknown land with no family, no friends, and an uncertain future? Shaun Tan''s wordless graphic masterpiece is a timeless tribute to every migrant, refugee, and displaced soul navigating an unfamiliar world to build a new home.', 'Šta navodi ljude da ostave sve iza sebe i sami krenu u nepoznatu zemlju, bez porodice i prijatelja, s neizvjesnom budućnošću? Ovaj tihi grafički roman Šona Tana dirljiva je posveta svakom migrantu, izbjeglici i putniku koji traži nadu i gradi novi život u stranom i čudesnom svijetu.', 'В этой пронзительной книге нет ни единого слова, но её дивные сепийные иллюстрации рассказывают о надежде и поиске нового дома громче тысячи голосов.', 'There isn''t a single word in this breathtaking masterpiece, yet its quiet, surreal pages speak louder than a thousand stories about courage, belonging, and hope.', 'U ovom remek-djelu nema nijedne jedine riječi, ali njegove čudesne sepija ilustracije govore o nadi i novim počecima glasnije od hiljadu knjiga.', '/covers/DP-1044.webp', '#937452', 'nonfiction', 'ru', 'available', 'дома', '["adventure","real"]', '["graphic novel","wordless","immigration","journey","hope"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('истории-далекого-пригорода-1045', 'DP-1045', 'Истории далекого пригорода', 'Tales from Outer Suburbia', 'Priče iz dalekog predgrađa', 'Шон Тан', 'Shaun Tan', 'Šon Tan', '', 'Комильфо', NULL, NULL, 6, 16, 'middle', 'Прославленный австралийский художник Шон Тан, обладатель многочисленных премий, автор знамениого графического романа "Прибытие", раскрывает тайны повседневной жизни: питомцы, сделанные своими руками, опасные свадьбы, выброшенные на берег морские млекопитающие, крохотные студенты по обмену и тайные комнаты, наполненные тьмой и восторгом.', 'Acclaimed Australian artist and creator of ''The Arrival'', Shaun Tan, unveils the quiet wonders and surreal mysteries of everyday life: DIY pets, perilous weddings, stranded sea creatures, tiny foreign exchange students, and secret rooms filled with darkness and delight.', 'Proslavljeni australijski umjetnik i autor grafičkog romana „Dolazak“, Šon Tan, otkriva tiha čuda i nadrealne tajne svakodnevnog života: domaće ljubimce iz kućne radinosti, opasna vjenčanja, nasukana morska stvorenja, sićušne studente na razmjeni i tajne sobe pune tame i ushićenja.', 'Приготовьтесь удивляться: в самом обычном спальном районе вас ждут домашние водяные буйволы, микроскопические гости и настоящие тайны прямо на заднем дворе!', 'Prepare to be amazed: in the most ordinary suburban neighborhood, you''ll discover backyard water buffaloes, microscopic exchange students, and quiet magic hidden in plain sight!', 'Pripremite se za čuđenje: u najobičnijem predgrađu čekaju vas domaći vodeni bivoli, mikroskopski gosti i prava tiha magija u dvorištu!', '/covers/DP-1045.webp', '#b47b48', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","adventure"]', '["magical realism","short stories","illustrations","suburbia","imagination"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('линдберг-1046', 'DP-1046', 'Линдберг', 'Lindbergh: The Tale of a Flying Mouse', 'Lindberg: Priča o letećem mišu', 'Торбен Кульманн', 'Torben Kuhlmann', 'Torben Kulman', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Давным-давно в огромном городе жил мышонок, который был до того любознательным, что месяцами просиживал в библиотеках за чтением книг. Однажды он заметил, что мышей в городе почти не осталось. Опасности прогнали его сородичей: голодные кошки и хищные совы подстерегают на улицах, а в домах людей повсюду расставлены зловещие устройства — мышеловки! Вот только куда отправились его друзья? Может быть, в Америку? У мышонка родился отчаянный план — научиться летать и пересечь Атлантический океан!', 'Long ago in a bustling city lived a little mouse so curious that he spent months tucked away in library corners reading books. One day, he realized that all his fellow mice had vanished—driven away by hungry cats, predatory owls, and sinister mousetraps. Where did they go? Could they have fled to America? The brave mouse devises an audacious plan: to master the art of flight and cross the vast Atlantic Ocean!', 'Nekada davno u velikom gradu živio je mali miš toliko radoznao da je mjesece provodio u bibliotekama čitajući knjige. Jednog dana shvatio je da su svi njegovi rođaci nestali, bježeći od gladnih mačaka, sova i opasnih mišolovki. Gdje su otišli? Možda u Ameriku? Mali miš smišlja smio plan: naučiće da leti i preletjeće Atlantski okean!', 'Невероятно вдохновляющая история с кинематографичными иллюстрациями о том, что даже самый крошечный мечтатель способен покорить бескрайнее небо.', 'A breathtakingly illustrated adventure proving that even the tiniest dreamer can conquer the highest skies with courage and a little ingenuity.', 'Očaravajuća priča sa predivnim ilustracijama koja dokazuje da i najmanji sanjar može osvojiti nebo uz hrabrost i malo domišljatosti.', '/covers/DP-1046.webp', '#8b5a2b', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","animals"]', '["mice","aviation","inventions","courage","history"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мой-дом-1047', 'DP-1047', 'Мой дом', 'My Home', 'Moj dom', 'Давид Кали', 'Davide Calì', 'Davide Kali', 'Себастьян Муррен', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Мне всегда было трудно считать какое-то место, город или здание своим домом. Но ведь дом должен быть у каждого человека, правда?', 'It has always been hard for me to consider a specific place, city, or building as my home. But surely, everyone deserves to have a home, right? A touching and gentle picture-book meditation on searching for belonging.', 'Uvijek mi je bilo teško da neko određeno mjesto, grad ili zgradu nazovem svojim domom. Ali zar svako ne bi trebalo da ima dom? Dirljivo i nježno promišljanje o tome gdje zaista pripadamo.', 'Уютное и трогательное размышление о том, что настоящий дом — это не просто стены и крыша, а тепло, которое мы носим в себе.', 'A quiet, heartfelt meditation reminding readers of all ages that home is far more than just four walls and a roof.', 'Nježna i topla priča koja nas podsjeća da dom nijesu samo četiri zida, već osjećaj koji nosimo u srcu.', '/covers/DP-1047.webp', '#d97443', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["real"]', '["home","belonging","feelings","family","growing up"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-не-сделал-уроки-потому-что--1048', 'DP-1048', 'Я не сделал уроки потому что...', 'I Didn''t Do My Homework Because...', 'Nisam uradio domaći zato što...', 'Давид Кали', 'Davide Cali', 'Davide Cali', 'Бенжамен Шо', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Главное - не растеряться! И если учитель задает вопрос в лоб - почему не сделано домашнее задание - надо отвечать. Действительно, мало ли что могло случиться? Дом заполонили роботы... Обезьяны... Похитили инопланетяне... Супермашина по изготовлению уроков сломалась... Дедушка и его друзья слишком громко музицировали в соседней комнате... Налетел ветер...', 'The key is never to lose your cool! When your teacher demands to know why the homework isn''t done, you''ve got to have an answer ready. After all, so many things could have happened: a sudden invasion of escapee monkeys, giant reptiles, an alien abduction, or an unexpected breakdown of your homework-solving machine. A delightfully absurd, brilliantly illustrated catalog of the wildest excuses ever invented.', 'Glavno je da se ne zbunite! Kad vas nastavnik bez uvijanja pita zašto domaći zadatak nije urađen — morate imati spreman odgovor. Uostalom, svašta je moglo da pođe po zlu: upali su vanzemaljci, pobegli nestašni majmuni, ili se pokvarila supermašina za izradu zadataka... Urnebesan i maštovit katalog najluđih izgovora na svijetu.', 'Идеальное пособие по изобретательному выживанию в школе для всех, кто хоть раз забывал тетрадь дома!', 'The ultimate witty survival guide for any student ever caught red-handed without their homework!', 'Genijalan vodič za školsko preživljavanje za sve koji su ikada „zaboravili“ svesku kod kuće!', '/covers/DP-1048.webp', '#f29927', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["funny"]', '["school","humor","excuses","imagination","homework"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('горошек-1049', 'DP-1049', 'Горошек', 'Little Pea', 'Graščić', 'Давид Кали', 'Davide Calì', 'Davide Calì', 'Себастьян Муррен', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Книжка всемирно известного детского писателя Давида Кали - это притча о необычном, очень маленьком герое. Но этого кроху не забудешь! Он из тех, кто неизменно вызывает восхищение: потому, что он умеет быть счастливым, свободным и наслаждаться тем, что у него есть. Кто-то расстраивается из-за маленького роста... Но только не Горошек! Ему не подходит ни одна парта, он скатывается по ступенькам, потому что не может по ним шагать, он не может играть с друзьями в баскетбол, но он не унывает и преодолевает трудности при помощи изобретательности, нестандартного мышления и хорошего настроения. Вокруг этого современного Мальчика-с-пальчик Давид Кали и художник Себастьян Мурен создают смешной, уютный, полный прелестных деталей мир, который понравится рассматривать и детям, и взрослым.', 'This charming modern parable tells the story of Little Pea, a boy so tiny that he sleeps in a matchbox and slides down the stairs instead of walking. While others might fret about being small, Little Pea embraces his size with boundless optimism, clever ingenuity, and an artist''s heart. Together with illustrator Sébastien Mourrain, Davide Calì creates a whimsical, cozy world filled with delightful details that celebrate uniqueness and the joy of being oneself.', 'Ova šarmantna savremena priča prati Graščića, dječaka toliko sićušnog da spava u kutiji šibica i spušta se niz stepenice kao niz tobogan. Iako je premali za obične školske klupe i ne može da igra košarku s vršnjacima, on ne gubi vedrinu: uz maštu, dosjetljivost i umjetnički dar pretvara svaku prepreku u igru. Predivno ilustrovana i topla slikovnica o tome kako velika sreća ne zavisi od visine.', 'Вдохновляющая и невероятно уютная история о том, что для великих дел и огромного счастья вовсе не обязательно быть великаном!', 'An uplifting and cozy reminder that you don''t need to be tall to live a truly grand and colorful life!', 'Neodoljivo topla i ohrabrujuća priča koja dokazuje da za velika djela uopšte ne moraš biti visok!', '/covers/DP-1049.webp', '#83a854', 'nonfiction', 'ru', 'available', 'Для дошкольного и младшего школьного возраста.', '["funny","friends","real"]', '["uniqueness","optimism","creativity","self-acceptance","picture book"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зубное-приключение-1050', 'DP-1050', 'Зубное приключение', 'The Tooth Adventure', 'Zubna avantura', 'Эва Эриксон', 'Eva Eriksson', 'Eva Erikson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Наконец-то у Беллы выпал зуб! Это значит, что она уже совсем большая и может одна ездить на автобусе. Вместе с младшим братом и другом Густавом Белла отправляется к бабушке. Вот только в квартире бабушки все какое-то странное — может быть, они не туда попали? А вдруг здесь живет настоящая ведьма? Эва Эриксон — шведская художница и писательница. Помимо собственных книг, проиллюстрировала книги самых известных шведских писателей. Лауреат множества премий, в том числе премии Астрид Линдгрен и медали Эльзы Бесков.', 'Bella has finally lost a tooth! That means she is officially a big kid and can ride the bus all by herself. Along with her little brother and their friend Gustav, Bella sets off on a trip to Grandma''s house. But inside Grandma''s apartment, everything feels unusually strange—could they have entered the wrong flat? And what if a real witch lives there instead? Eva Eriksson is an acclaimed Swedish author and illustrator, honored with both the Astrid Lindgren Prize and the Elsa Beskow Plaque.', 'Beli je konačno ispao prvi zub! To znači da je sada sasvim velika i može sama da putuje autobusom. Zajedno sa mlađim bratom i drugarom Gustavom, Bela kreće u posjetu baki. Ali u bakinom stanu sve djeluje nekako čudno — da nisu možda promašili vrata? Šta ako tu zapravo živi prava vještica? Eva Erikson je proslavljena švedska spisateljica i ilustratorka, dobitnica nagrade Astrid Lindgren i medalje Elze Beskov.', 'Потерянный молочный зуб превращается в грандиозную городскую экспедицию с щепоткой шпионской тайны!', 'Losing a first tooth turns into an epic big-kid expedition packed with suspense, fun, and mistaken doors!', 'Ispadanje prvog zuba pretvara se u pravu pravcatu gradsku ekspediciju sa malom dozom detektivske misterije!', '/covers/DP-1050.webp', '#e08d6c', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","adventure","friends"]', '["first tooth","growing up","family","journey","swedish literature"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('парко-1051', 'DP-1051', 'Парко', 'Parco', 'Parko', 'Гуриди', 'Guridi', 'Guridi', 'Алекс Ногес', 'Белая ворона', NULL, NULL, 6, 16, 'middle', '"Покойся с миром!" - сказали они. Но почему же тогда мир продолжает вертеться? Парко поднялся из могилы и пошел в город. И там он узнал что-то очень важное. С древнейших времен мы, люди, относились к смерти со страхом и почтением, создав бесконечное количество похоронных обычаев, религий и философских течений. Когда художник Гуриди попросил Алекса Ногеса написать веселую сказку о смерти, события и персонажи, которых он стал представлять, сами собой перенеслись в Мексику. Если и существует культура, в которой люди весело и с любовью относятся к своим мертвым, то это, без сомнения культура Мексики. Вот так и появился на свет Парко - самый обычный оживший мексиканский мертвец.', '"Rest in peace!" they said. But why, then, does the world keep on spinning? Parco rises from his grave and sets off for the city, where he discovers something profound. Since ancient times, humankind has treated death with fear and reverence, inventing rituals, religions, and philosophical views. When illustrator Guridi asked writer Álex Nogués to craft a joyful tale about mortality, the vibrant culture of Mexico was the natural home. Thus Parco was born: an ordinary, good-humored Mexican skeleton wandering among the living.', '„Počivaj u miru!“, rekli su mu. Ali zašto se onda svijet i dalje vrti? Parko je ustao iz groba i krenuo put grada, gdje je otkrio nešto veoma važno. Od davnina su se ljudi prema smrti odnosili sa strahopoštovanjem, stvarajući bezbroj običaja i vjerovanja. Kada je ilustrator Guridi zamolio Aleksa Nogesa da napiše veselu priču o prolaznosti, priča se prirodno preselila u Meksiko — kulturu punu ljubavi i radosti prema preminulima. Tako je oživio Parko, sasvim običan i vedar meksički kostur.', 'Необыкновенно тёплая и светлая мексиканская история о том, что любовь и добрая память сильнее любого кладбищенского покоя!', 'An unexpectedly heartwarming Mexican fiesta showing that memory and love are far more lively than resting quietly in peace!', 'Neobično topla i vedra meksička priča koja pokazuje da su ljubav i sjećanje mnogo življi od vječnog mira!', '/covers/DP-1051.webp', '#d65a31', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","spooky","real"]', '["mexico","day of the dead","philosophy","humor","life and death"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('малюсенький-паровозик-1052', 'DP-1052', 'Малюсенький паровозик', 'Little Train', 'Mali vozić', 'Крис Галл', 'Chris Gall', 'Kris Gal', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Малюсенький паровозик, который привык бегать по кругу своей игрушечной железной дороги вдруг оказался за пределами дома и повстречался с настоящими поездами. Что узнает о мире наш паровозик?', 'A tiny toy train accustomed to chugging in circles on his nursery track suddenly ends up outside, face-to-face with enormous real trains. What exciting wonders will our brave little engine discover about the vast world?', 'Mali igračkasti vozić, naviknut da juri u krug po svojoj dječijoj pruzi, odjednom se obreo napolju i susreo sa pravim, ogromnim vozovima. Šta će sve naš hrabri mališan otkriti o velikom svijetu?', 'Трогательная и вдохновляющая история о том, что даже самый крошечный паровозик способен на грандиозное путешествие!', 'A touching and inspiring tale showing that even the tiniest engine is capable of embarking on a grand adventure!', 'Dirljiva i inspirativna priča koja dokazuje da je čak i najmanji vozić stvoren za velika putovanja!', '/covers/DP-1052.webp', '#d83a2a', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","friends"]', '["trains","toys","curiosity","growing up","journey"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('замечтательная-книжка--1053', 'DP-1053', 'Замечтательная книжка!', 'An Awesome Book!', 'Sjajna knjiga!', 'Даллас Клейтон', 'Dallas Clayton', 'Dallas Clayton', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Замечательная книжка для детей. Для чтения взрослыми детям', 'A vibrant and joyful manifesto that encourages dreamers of all ages to dream big, wild, and wonder-filled dreams instead of settling for the mundane.', 'Živopisna i topla slikovnica koja ohrabruje male i velike sanjare da maštaju o nevjerovatnim, čudesnim i čarobnim stvarima umjesto o običnoj svakodnevici.', 'Вдохновляющий манифест о том, как важно мечтать о ракетах, радугах и невероятных приключениях, а не о скучных взрослых вещах!', 'A joyful, colorful reminder that you should dream of rockets, friendly monsters, and wonders instead of boring everyday routines!', 'Veseli i šareni podsjetnik da treba sanjati o raketama, čudovištima i čudima umjesto o dosadnim stvarima za odrasle!', '/covers/DP-1053.webp', '#f4b324', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","adventure"]', '["dreams","imagination","inspiration","creativity","picture book"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('защитник-детей-1054', 'DP-1054', 'Защитник детей', 'The Champion of Children: The Story of Janusz Korczak', 'Zaštitnik djece: Priča o Janušu Korčaku', 'Томек Богацкий', 'Tomek Bogacki', 'Tomek Bogacki', '', 'Текст', NULL, NULL, 6, 16, 'middle', 'Януш Корчак вел специальную программу на варшавском радио, где давал детям советы, как справиться с разными сложностями в их жизни. Януш Корчак всю свою жизнь посвятил детям - лечил их, писал о них, защищал от несправедливости. Писал для них книги - его сказочная повесть "Король Матиуш первый" любима многими поколениями детей во всем мире. Януш Корчак создал в Варшаве удивительный приют для еврейских сирот, которым управляли сами дети. А когда нацисты отправили их в концлагерь, где детей ожидала неминуемая смерть, он не оставил своих маленьких воспитанников и погиб вместе с ними. Эту книгу о Януше Корчаке написал и нарисовал американский детский писатель и художник Томек Богацкий.', 'Janusz Korczak devoted his entire life to children: healing them as a doctor, giving warm guidance on Warsaw radio, writing beloved books like ''King Matt the First'', and creating a unique orphanage run democratically by the children themselves. When tragic times struck and his pupils were sent to a concentration camp, he refused to abandon them and stayed by their side until the end. Written and illustrated by Tomek Bogacki, this touching picture book tells the moving true story of an extraordinary humanitarian.', 'Januš Korčak je cijeli svoj život posvetio djeci: liječio ih je kao ljekar, davao im savjete na radiju, pisao voljene knjige poput ''Kralja Matijuša Prvog'' i stvorio jedinstveni dom za siročad kojim su upravljala sama djeca. Kada su djeca u Drugom svjetskom ratu poslata u logor, odbio je priliku da se spasi i ostao sa svojim mališanima do samog kraja. Ova dirljiva i prelijepo ilustrovana knjiga Tomeka Bogackog svjedočanstvo je o istinskom heroju humanosti.', 'Пронзительная и светлая история о человеке с бесконечно большим сердцем, который доказал, что уважать и защищать детей — важнее всего на свете.', 'A deeply moving and luminous biography of a man whose boundless heart proved that loving, respecting, and protecting children is the most important calling of all.', 'Duboko dirljiva i plemenita priča o čovjeku velikog srca koji je dokazao da su ljubav, poštovanje i zaštita djece najvažnije stvari na svijetu.', '/covers/DP-1054.webp', '#6b5b4d', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["real","friends"]', '["biography","history","janusz korczak","courage","compassion"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мечтатель-из-местечка-1055', 'DP-1055', 'Мечтатель из местечка', 'The Dreamer from the Shtetl', 'Sanjar iz varošice', '', 'Unknown', 'Nepoznat autor', '', 'Текст', NULL, NULL, 6, 16, 'middle', 'Марк Шагал был одним из первых художников, которые выразили в своем творчестве внутренний мир - мечты, фантазии, воспоминания. Его картины отличаются богатством красок, его образная система сюрреалистична. Мойше Сегал родился 7 июля 1887 года в местечке Лиозно близ Витебска (сейчас этот город находится в Беларуси). Позднее он изменил имя, и оно стало звучать на французский манер - Марк Шагал. Мальчик рос в религиозной еврейской среде, и позднее это нашло отражение в сюжетах его картин.', 'Marc Chagall was one of the first painters to portray his inner world—dreams, fantasies, and memories—in his art. His canvases burst with vibrant colors and surreal imagery. Born Moishe Segal in 1887 near Vitebsk, he grew up in a traditional Jewish home, an environment that profoundly shaped the themes and poetic soul of his masterpieces.', 'Mark Šagal je bio jedan od prvih slikara koji su kroz umjetnost izrazili svoj unutrašnji svijet — snove, maštanja i uspomene. Njegove slike odlikuju se bogatstvom boja i nadrealnim prizorima. Rođen kao Mojše Segal 1887. godine u varošici blizu Vitebska, odrastao je u jevrejskoj tradiciji, što je zauvijek ostavilo neizbrisiv trag na njegovim remek-djelima.', 'Взгляните на мир глазами Марка Шагала, где влюблённые парят в облаках, а детские мечты оживают яркими красками!', 'See the world through Marc Chagall''s eyes, where lovers float among the clouds and childhood dreams take flight on canvas!', 'Pogledajte svijet očima Marka Šagala, gdje zaljubljeni lebde u oblacima, a dječiji snovi oživljavaju na platnu!', '/covers/DP-1055.webp', '#1d4e89', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["real","magic"]', '["art","biography","marc chagall","painting","creativity"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('простая-бандероль-1056', 'DP-1056', 'Простая бандероль', 'A Simple Parcel', 'Obična pošiljka', 'Брюно Хейтц', 'Bruno Heitz', 'Bruno Hajc', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Брюно Хейтц нарисовал и написал за всю свою жизнь более пятидесяти книг; и ни одна из них не похожа на другую. Используя различные техники, - черно-белую графику, линогравюру, коллажи, фотографии сделанных им самим скульптур, - Брюно Хейтц создает оригинальные и забавные истории, которые любят и взрослые и дети. "Простая бандероль" - прекрасный образец современного французского искусства книги.', 'Over his lifetime, Bruno Heitz has created over fifty unique books using an array of distinct techniques—black-and-white drawings, linocuts, collages, and photographs of his own handmade sculptures. ''A Simple Parcel'' is an extraordinary and playful showcase of modern French book artistry that delights curious readers of all ages.', 'Tokom svog života, Bruno Hajc je stvorio više od pedeset unikatnih knjiga koristeći različite tehnike — crno-bijelu grafiku, linorez, kolaže i fotografije skulptura koje je sam izradio. „Obična pošiljka“ je izuzetan i razigran primjer savremene francuske umjetnosti knjige u kojoj uživaju radoznali čitaoci svih uzrasta.', 'Удивительное визуальное путешествие, в котором обычная посылка превращается в настоящий шедевр французской книжной графики!', 'A delightful visual journey where an ordinary parcel unfolds into a genuine masterpiece of French book art!', 'Čudesno vizuelno putovanje u kojem se obična pošiljka pretvara u pravo remek-djelo francuske umjetnosti knjige!', '/covers/DP-1056.webp', '#b88654', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","real"]', '["art","illustrations","creativity","french literature","visual storytelling"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('расмус-в-кругосветном-путешест-1057', 'DP-1057', 'Расмус в кругосветном путешествии', 'Rasmus Klump Around the World', 'Rasmus na putu oko svijeta', 'Карла ХАнсен', 'Carla Hansen', 'Karla Hansen', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Знакомьтесь с медвежонком Расмусом и его друзьями - Пинго, Пелле и Тюленем! Они большие выдумщики и искатели приключений и постоянно попадают в весёлые истории! Отправляйтесь в самое захватывающее кругосветное путешествие вместе с нашими друзьями. За 80 дней они преодолеют моря и страны, им предстоит проехать на поезде, на спине слона, пролететь на дирижабле, проплыть в пасти кита и даже облететь вокруг Луны! Эту весёлую историю в картинках сможет понять даже тот, кто ещё не умеет читать. Выразительные иллюстрации шаг за шагом передают ход сюжета - можно просто рассматривать странички. А для тех, кто уже умеет читать, книга станет отличной дополнительной тренировкой навыков - в ней крупные буквы и простые короткие фразы.', 'Meet Rasmus the bear cub and his faithful crew—Pingo, Pelle, and the Seal! In this whirlwind 80-day journey around the globe, the intrepid friends travel by train, ride an elephant, soar in an airship, slip inside a whale''s belly, and even take a loop around the Moon. Told through vivid comic-strip illustrations paired with short, simple sentences in large print, this timeless adventure is delightful both for prereaders to browse and for beginners practicing their first words.', 'Upoznajte medvjedića Rasmusa i njegovu družinu—Pinga, Pelea i Tuljana! U ovoj uzbudljivoj pustolovini obilaska svijeta za 80 dana, veseli prijatelji putuju vozom, jašu slona, lete dirižablom, završavaju u kitovoj utrobi i čak prave krug oko Mjeseca. Uz izražajne strip-ilustracije i kratak, krupan tekst, ova topla priča savršena je kako za znatiželjno prelistavanje, tako i za prve samostalne čitalačke korake.', 'Кругосветка на слоне, в пасти кита и вокруг Луны — идеальный иллюстрированный билет в большое плавание даже для тех, кто ещё только учится читать!', 'An around-the-world voyage on elephant back, inside a whale, and past the Moon—the ultimate comic adventure for budding young readers!', 'Put oko svijeta na leđima slona i pored Mjeseca—savršen strip-izlet za male radoznalce koji tek otkrivaju radost čitanja!', '/covers/DP-1057.webp', '#e63946', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста | комикс', '["adventure","animals","friends"]', '["travel","comics","animals","friendship","first reading"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сокровища-лесных-эльфов-1058', 'DP-1058', 'Сокровища лесных эльфов', 'Treasures of the Forest Elves', 'Blaga šumskih vilenjaka', 'Реетта Ниемеля', 'Reetta Niemelä', 'Reetta Niemelä', '', 'Детгиз', NULL, NULL, 6, 16, 'middle', '"Это самая любимая и самая важная для меня книжка. Ведь она объединяет дорогие мне вещи: игру, фантазию, радость, дружбу, понимание, поддержку, тепло и любовь в семье. Я думаю, что весь мир состоит из таких вот очень маленьких и удивительных историй. Надо только наклониться и заглянуть, или зажмуриться и нырнуть, а может даже залезть в какую-нибудь маленькую норку. И тогда ты обязательно их найдешь!" Реетта Ниемеля. Художник-иллюстратор: Матти Пиккуямся.', '"This is my most cherished book, bringing together what matters most: play, imagination, joy, friendship, and the cozy warmth of family. The whole world is woven from tiny, wondrous stories—you only need to bend down, look closely, or peek into a secret hollow to discover them!" Richly illustrated by award-winning artist Matti Pikkujämsä.', '„Ovo je moja najdraža knjiga koja spaja sve ono najvažnije: igru, maštu, radost, prijateljstvo i porodičnu toplinu. Čitav svijet je satkan od ovakvih sićušnih, čudesnih priča — dovoljno je samo da se sagnete, zavirite u mahovinu ili provirite u neku malu jazbinu da biste ih pronašli!“ Bogato ilustrovao Mati Pikujamsa.', 'Наденьте невидимую шапку следопыта: под каждой корягой и мшистым камушком здесь прячется настоящее лесное чудо!', 'Put on your explorer''s cap: beneath every mossy stone and pine branch, a tiny spark of woodland wonder awaits!', 'Stavite svoju istraživačku kapu: ispod svakog mahovinastog panja krije se pravo malo šumsko čudo!', '/covers/DP-1058.webp', '#386641', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","real","adventure"]', '["forest","nature","fairies","imagination","scandinavia"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бига-и-каса-1059', 'DP-1059', 'Бига и Каса', 'Biga and Kasa', 'Biga i Kasa', 'Илья Донец, Маргарита Щетинская', 'Ilya Donets, Margarita Shchetinskaya', 'Ilja Donec, Margarita Ščetinskaja', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Бига и Каса живут у подножия большого дерева. Их мир ограничивается небольшой полянкой у корней деревьев и необходимостью каждый вечер включать на всем дереве свет. Всё, что не входит в их обычный распорядок, друзья считают неприятным и пугающим. Но однажды случается авария - перегорает главная лампочка - и, чтобы её заменить, друзьям приходится отправиться в путешествие на самую вершину дерева. Во время своего путешествия Бига и Каса решают инженерные задачи, знакомятся с другими обитателями дерева, преодолевают свои страхи и узнают, что мир гораздо больше и интереснее, чем они думали. Герои книги вылеплены из пластилина, а иллюстрации совмещают фотографии, рисунки и компьютерную обработку. В 2011 году "Бига и Каса" были отмечены премией "Образ книги".', 'Biga and Kasa live at the foot of a giant tree, keeping to their cozy clearing and faithfully turning on the tree''s lights every evening. But when the main light bulb burns out, the timid friends must embark on an unexpected expedition all the way to the treetop. Along the way, they solve clever engineering puzzles, meet quirky canopy dwellers, overcome fears, and discover how wonderfully vast the world really is. Illustrated with charming plasticine sculptures blended with photography and digital art, this book won the prestigious ''Image of the Book'' award in 2011.', 'Biga i Kasa žive u podnožju velikog drveta, čuvajući svoju malu čistinu i svake večeri paleći svjetla na cijelom stablu. Kada pregori glavna sijalica, dvoje plašljivih prijatelja moraju da krenu na hrabro putovanje do samog vrha krošnje. Usput rješavaju inženjerske zagonetke, upoznaju neobične stanovnike drveta, savladavaju strahove i otkrivaju koliko je svijet zapravo čaroban i prostran. Likovi su izvajani od plastelina, a ilustracije spajaju fotografiju i grafiku, zbog čega je knjiga 2011. godine nagrađena priznanjem ''Slika knjige''.', 'Трогательная пластилиновая экспедиция на вершину великого дерева, доказывающая, что даже самое маленькое существо способно на большие инженерные подвиги!', 'A charming claymation-style treetop expedition showing that even the tiniest creatures can conquer great engineering feats and big fears!', 'Dirljiva ekspedicija od plastelina do vrha velikog drveta koja dokazuje da i najmanja bića mogu izvesti prave inženjerske podvige!', '/covers/DP-1059.webp', '#768c45', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["adventure","friends"]', '["clay animation","tree","journey","engineering","overcoming fear"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дзен-в-коротеньких-штанишках-1060', 'DP-1060', 'Дзен в коротеньких штанишках', 'Zen Shorts', 'Zen u kratkim pantalonama', 'Джон Мут', 'Jon J. Muth', 'Džon Dž. Mut', '', 'Планета детства', NULL, NULL, 6, 16, 'middle', '"Дзен в коротких штанишках" - это несколько коротких историй, которые помогают приблизиться к медитации. Медитация доводит до совершенства нашу способность прислушиваться к собственной интуиции. В медитации нет никакой цели, но она зачастую позволяет нам проанализировать наши привычки, желания, представления и страхи. Истории "Дядюшка Рю и луна" и "Тяжелая ноша" относятся к дзен-буддийской литературе далекого прошлого. Рассказ "Удача фермера" восходит корнями к даосизму, история которого насчитывает несколько тысяч лет. Вариантов каждой из этих историй существует очень много. Автор выбрал те, которые показались наиболее доступными для юных читателей.', 'Zen Shorts brings timeless ancient parables to life for young readers through the gentle wisdom of a friendly giant panda named Stillwater. Rooted in Zen Buddhist and Daoist traditions, these short tales help children explore mindfulness, look past quick assumptions, let go of emotional burdens, and listen quietly to their own inner intuition.', '„Zen u kratkim pantalonama“ donosi bezvremenske mudre priče koje djecu i mlade uvode u svijet meditacije i unutrašnjeg mira kroz nježno vođstvo džinovskog pande Stilvotera. Ukorijenjene u drevnim tradicijama zen-budizma i taoizma, ove tople pouke uče nas kako da osluškujemo intuiciju, otpustimo teške terete i pronađemo spokoj u svakodnevici.', 'Мудрая и уютная панда делится древними притчами, которые учат выдыхать, отпускать обиды и радоваться простым вещам.', 'A gentle giant panda shares timeless parables that help readers of all ages take a deep breath, let go of burdens, and find calm.', 'Mudra i nježna džinovska panda dijeli bezvremenske zen priče koje nas uče kako da odahnemo, otpustimo brige i pronađemo mir.', '/covers/DP-1060.webp', '#5a7d65', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["friends","animals","real"]', '["mindfulness","philosophy","parables","panda","wisdom"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('если-плакать-как-фонтан-1061', 'DP-1061', 'Если плакать как фонтан', 'If You Cry Like a Fountain', 'Ako plačeš kao fontana', 'Ноэми Вола', 'Noemi Vola', 'Noemi Vola', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Причудливая и удивительно забавная книжка с картинками о множестве практических применений слез. Стараясь развеселить грустного червяка, рассказчик усугубляет ситуацию, заставляя червяка плакать. Пытаясь исправить ситуацию, рассказчик начинает думать о различных способах продуктивного использования слез. К примеру, если вам грустно в обед, плачьте, пока не наполните кастрюлю слезами и не сварите макароны — можно даже не солить! Слезы служат множеству различных целей. Без слез реки бы пересохли. Тучи становились бы все больше и больше, и фермеры бы сердились. Слезы помогают грушам расти, а из груш можно сварить варенье. Варенье делает людей счастливыми и помогает остановить слезы... по крайней мере, пока не кончится! Присоединяйтесь к плачущему червяку и неуклюжему рассказчику, которые исследуют множество способов использования слез.', 'A whimsical and remarkably funny picture book exploring the countless practical uses of tears. While attempting to cheer up a sad little worm, our well-meaning narrator only manages to make things worse, sending the worm into deep sobs. To turn things around, the narrator ponders creative ways to put crying to good use. For instance, crying into a pot at lunchtime produces salty water ready for cooking pasta! Tears nourish pears, pear jam brings happiness, and happiness stops tears—at least until the jam jar runs empty. Join a weeping earthworm and an endearing narrator on an inventive emotional rollercoaster.', 'Neobična i beskrajno duhovita slikovnica o bezbrojnim praktičnim primjenama suza. Pokušavajući da oraspoloži tužnu glistu, pripovjedač samo pogoršava situaciju i tjera je u još veći plač. Da bi popravio stvar, počinje da smišlja načine kako produktivno iskoristiti suze: na primjer, ako ste tužni u vrijeme ručka, možete napuniti šerpu i skuvati tjesteninu bez dodavanja soli! Suze pomažu kruškama da rastu, od krušaka se pravi džem, a džem vraća osmijeh na lice... bar dok ga ima u tegli!', 'Остроумное и теплое утешение для тех, кто ревет в три ручья — оказывается, в этих слезах можно даже сварить спагетти без соли!', 'A brilliantly quirky comfort for anyone who weeps buckets — turns out tears are perfect for boiling pasta without adding salt!', 'Duhovita i topla utjeha za sve koji ponekad rone krokodilske suze — ispostavlja se da u njima možete skuvati tjesteninu i bez soli!', '/covers/DP-1061.webp', '#3b82f6', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["funny","real"]', '["emotions","crying","humor","earthworm","philosophy"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('приду-в-4-1062', 'DP-1062', 'Приду в 4', 'I''ll Come at Four', 'Doći ću u četiri', 'Вольфдитрих Шнурре', 'Wolfdietrich Schnurre', 'Volfditrih Šnure', 'Ротраут Сюзанна Бернер', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'В клетке зоопарка снует туда-сюда страшная гиена. Вы подходите поближе, и вдруг она говорит: - На самом деле я принцесса. Попытаетесь ли вы ее расколдовать?', 'A scruffy hyena paces back and forth in her zoo cage. You step closer, and she whispers: "Actually, I''m an enchanted princess." Would you dare invite her to your home and try to break the spell?', 'U zoološkom vrtu, u svom kavezu, nervozno juri strašna hijena. Prilazite bliže, a ona vam iznenada šapne: „Zapravo, ja sam princeza.“ Hoćete li je pozvati u goste i pokušati da skinete čaroliju?', 'Трогательная и глубокая притча о том, как чашка чая и капелька чуткости могут расколдовать самое одинокое сердце.', 'A deeply touching, quirky fable proving that a warm cup of tea and genuine hospitality can work wonders for even the scruffiest soul.', 'Dirljiva i mudra priča o tome kako topla šolja čaja i malo iskrene pažnje mogu ugrijati i najusamljenije srce.', '/covers/DP-1062.webp', '#d4883b', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["friends","animals","magic"]', '["empathy","kindness","zoo","hyena","fable"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-комиксы-1063', 'DP-1063', 'Сказки-комиксы', 'Fairy Tale Comics', 'Bajke u stripu', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', '', 'Мелик-Пашаев', NULL, NULL, 6, 16, 'middle', 'Дети любят слушать сказки. И обожают рассматривать комиксы. Почему бы не дать им возможность делать это одновременно? Так рассудила немецкая художница Ротраут Сюзанне Бернер и нарисовала восхитительно остроумные детские комиксы по мотивам своих любимых сказок братьев Гримм. В книгу вошли 8 известных сказок: "Принцесса и лягушонок", "Госпожа Метелица", "Мальчик-с-пальчик", "Рапунцель", "Йоринда и Йорингель", "Счастливый Ганс", "Ганс-ёжик" и "Красная шапочка". На их страницах взрослых и маленьких читателей ждут и шутки художника, и задачки на внимательность, и другие сюрпризы.', 'Children love listening to fairy tales and adore reading comics, so why not enjoy both at once? Acclaimed German illustrator Rotraut Susanne Berner reimagines eight classic Brothers Grimm tales as delightfully witty comic strips. Featuring beloved favorites like Rapunzel, Little Red Riding Hood, and The Frog Prince, this charming collection is filled with visual gags, playful details, and unexpected surprises for readers of all ages.', 'Djeca vole da slušaju bajke, a obožavaju da čitaju stripove — zašto onda ne spojiti to dvoje? Poznata njemačka ilustratorka Rotraut Suzane Berner pretočila je osam klasičnih bajki braće Grim u neodoljivo duhovite stripove. Uz dobro poznate priče poput Crvenkape, Zlatokose i Žapca cara, stranice donose obilje vizuelnog humora, zadatke za pažljive posmatrače i vesela iznenađenja za sve uzraste.', 'Любимые сказки братьев Гримм в формате озорного комикса от создательницы «Городка» — оторваться невозможно ни детям, ни взрослым!', 'Classic Grimm fairy tales transformed into witty, delightful comics by the legendary creator of the Wimmelbooks!', 'Omiljene bajke braće Grim pretvorene u vesele i duhovite stripove — prava poslastica i za male i za velike čitaoce!', '/covers/DP-1063.webp', '#e9a12c', 'nonfiction', 'ru', 'available', 'поврежден корешок книги', '["magic","funny","adventure"]', '["fairy tales","comics","brothers grimm","humor","graphic novel"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пес-и-заяц-1064', 'DP-1064', 'Пес и заяц', 'Dog and Hare', 'Pas i zec', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', '', 'Росмэн', NULL, NULL, 6, 16, 'middle', 'Герои этой истории - пёс Хуго и заяц Ханнес - живут в Шмелином городке возле Шмелиной реки. Каждый день Хуго и Ханнес видятся в школе, что интересно одному, то интересно и другому, но у них и мысли нет перекинуться меж собой словечком, ведь их семейства на дух друг друга не переносят. Никто уже и не помнит, откуда пошла эта взаимная неприязнь, так уж повелось. Но в одно прекрасное воскресенье Шмелиный городок отправляется на соревнования по бегу, и заяц и пес спешат попасть на него во все восемь лап.', 'Hugo the dog and Hannes the hare live in Bumblebee Town. They see each other at school every day and share all the same passions, yet they never exchange a word because their families have harbored a mutual grudge for generations. Nobody even remembers how the feud began, but when the big town race takes place on a fine Sunday, both rush to the starting line on all eight paws.', 'Pas Hugo i zec Hanes žive u gradu Bumbarovu pored rijeke Bumbarice. Svakoga dana se viđaju u školi i vole iste stvari, ali ne progovaraju ni riječ jer se njihove porodice generacijama ne podnose. Niko se više i ne sjeća odakle potiče ta netrpeljivost, sve dok jedne sunčane nedjelje velika trkačka takmičenja ne pokrenu svih njihovih osam šapa.', 'Добрая и остроумная история о том, как вековая соседская вражда растворяется без следа, стоит лишь побежать навстречу дружбе!', 'A delightfully witty tale proving that silly family feuds don''t stand a chance when paws race together toward friendship!', 'Duhovita i topla priča koja pokazuje da besmislene porodične svađe nestaju čim potrčite u susret pravom prijateljstvu!', '/covers/DP-1064.webp', '#58983e', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["animals","friends","funny"]', '["friendship","rivalry","animals","sports","school"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('что-у-соседа-на-обед--1065', 'DP-1065', 'Что у соседа на обед?', 'What''s Cooking at 10 Garden Street?', 'Šta komšija kuva za ručak?', 'Феличита Сала', 'Felicita Sala', 'Feličita Sala', '', 'Речь', NULL, NULL, 6, 16, 'middle', 'По Садовнической улице доносится изумительный аромат! Сеньора Лейла пробует свой знаменитый соус к спагетти. В квартире на третьем этаже господин Сингх собирается приготовить вкусный кокосовый дал. А по соседству с ним миссис Гринпи радуется золотистой корочке только что приготовленных мини-кишей… Эта книга - сборник оригинальных рецептов национальных блюд. Она поможет юным читателям расширить свой кругозор и проявить творческую фантазию. Готовьте с удовольствием!', 'Delicious aromas are drifting through the apartment building on Garden Street! Señora Leila is tasting her famous spaghetti sauce, Mr. Singh is stirring a fragrant coconut dhal, and Mrs. Greenpea is pulling golden mini-quiches from the oven. This delightfully illustrated storybook cookbook introduces young chefs to authentic international recipes and the joy of sharing meals with neighbors.', 'Iz zgrade u Ulici baštovana širi se neodoljiv miris! Sinjora Leila proba svoj čuveni sos za špagete, gospodin Sing priprema mirisni kokos dal, a gospođa Grinpi se divi zlatnoj korici mini-kiševa. Ova predivno ilustrovana zbirka recepata iz cijelog svijeta probudiće kulinarsku maštu svakog malog kuvara i naučiti ga radosti zajedničke trpeze.', 'Загляните в кастрюли и сковородки целого дома — здесь пахнет дружбой, специями и праздником со всего света!', 'Peek into the bubbling pots of an entire apartment building—this cozy cookbook serves up friendship, flavors, and easy recipes from around the globe!', 'Zavirite u šerpe i tiganje jedne zgrade pune divnih komšija — ova knjiga donosi recepte, mirise i pravo prijateljstvo!', '/covers/DP-1065.webp', '#c85a32', 'nonfiction', 'ru', 'available', 'повреждена обложка', '["friends","real"]', '["cooking","recipes","food","neighbors","cultures"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('она-создала-чужовище-1066', 'DP-1066', 'Она создала чужовище', 'She Made a Monster: How Mary Shelley Created Frankenstein', 'Stvorila je čudovište', '', 'Lynn Fulton', 'Lin Fulton', 'Феличита Сала', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Двести лет тому назад лорд Байрон предложил своей подруге Мэри соревнование: кто лучше напишет страшную историю. Ненастной ночью Мэри вспоминает свои детские страхи и смерть матери. И вот, уже засыпая, она представляет чудовище настолько страшное, что люди в ужасе бегут от него. Проснувшись, Мэри понимает: история готова.', 'Two hundred years ago, Lord Byron challenged his friend Mary to a contest: who could write the best ghost story? On a stormy night, Mary reflects on her childhood fears and grief. Just as she drifts off to sleep, she envisions a creature so terrifying that people flee in horror. When she wakes, Mary knows: her masterpiece is born.', 'Prije dvije stotine godina, lord Bajron je predložio svojoj prijateljici Meri izazov: ko može da napiše najbolju strašnu priču? Tokom olujne noći, Meri se prisjeća djetinjih strahova i majke. U polusnu zamišlja stvorenje toliko strašno da ljudi u užasu bježe od njega. Kad se probudila, znala je: priča je rođena.', 'Загляните за кулисы грозовой швейцарской ночи и узнайте, как юная Мэри Шелли на спор подарила миру Франкенштейна!', 'Step into a stormy Swiss night and discover how a teenage Mary Shelley created Frankenstein on a spooky dare!', 'Zavirite u olujnu noć u Švajcarskoj i otkrijte kako je mlada Meri Šeli iz opklade stvorila čuvenog Frankenštajna!', '/covers/DP-1066.webp', '#2d3a40', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["spooky","real"]', '["frankenstein","mary shelley","biography","writing","gothic","history"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-домик-1067', 'DP-1067', 'Маленький домик', 'The Little House', 'Mala kućica', 'Вирджиния Ли Бертон', 'Virginia Lee Burton', 'Virdžinija Li Barton', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Эта книга о судьбе Маленького Домика, который и является главным героем книги. Однажды его построили, и был произнесен завет: этот домик будет стоять долго-долго и в нем будут жить правнуки наших правнуков. Домик встречает лето и зиму, утро и ночь, радуется распустившимся цветам яблони и первым снежинкам, он наблюдает жизнь людей, которые в нем живут. Но со временем на тихую деревенскую жизнь начинает наступать город. Он все ближе и ближе, и вот уже Маленький Домик оказывается в самом его центре, окруженный небоскребами, ревущими электричками, грохочущими трамваями и спешащими людьми. Хозяева его давно покинули. Трагедия заключается в том, что сумасшедший ритм города никак не может быть принят Домиком. Та ритмическая жизнь, согласная с природой уже не доступна ему. И хозяева его давно бросили. Домик обветшал. Дальше случается невероятное. И в конце истории Домик переезжает на столь милую ему поляну с ромашками и яблонями, и возвращается к своему естественному ритму жизни.', 'Once upon a time, a charming little house stood on a peaceful hill surrounded by wildflowers and apple trees, built never to be sold for gold or silver. As seasons turn and generations pass, the countryside gives way to sprawling roads, roaring elevated trains, and towering skyscrapers. Trapped in the hurried frenzy of a bustling metropolis, the weathered little house longs for starlight and quiet countryside—until a miraculous second chance brings it back to where daisies bloom.', 'Nekada davno, na mirnom brežuljku okruženom jabukama i tratinčicama, sagrađena je divna mala kuća koja je trebalo da traje vjekovima. Međutim, kako vrijeme odmiče, seoski mir guta neumoljivi grad sa neboderima, tramvajima i užurbanim ljudima. Oronula i zaboravljena u srcu bučnog velegrada, kućica čezne za prirodom i zvjezdanim nebom sve dok se ne dogodi čudesno spasenje koje je vraća tamo gdje joj je i srce.', 'Трогательная до слёз классика о том, как остаться верным себе и найти дорогу домой, даже когда вокруг выросли шумные небоскрёбы.', 'A timeless, heartwarming Caldecott masterpiece reminding both kids and adults that true home is where we can breathe and watch the stars.', 'Bezvremenska, dirljiva priča koja nas podsjeća da je pravi dom tamo đe možemo mirno disati i gledati zvijezde.', '/covers/DP-1067.webp', '#d97486', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["real","adventure"]', '["home","nature","city","classic","seasons"]', 1792836322700, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('комореби-собремеса-хэзеллих-1068', 'DP-1068', 'Комореби, собремеса, хэзеллих', 'Komorebi, Sobremesa, Gezellig', 'Komorebi, sobremesa, gezellig', 'Мария Ивашкина', 'Maria Ivashkina', 'Marija Ivaškina', '', 'Миля', NULL, NULL, 6, 16, 'middle', 'В разных языках найдены очень точные слова для определения сложных оттенков чувств. Если собрать несколько таких слов вместе, перед тобой возникает портрет. Каждая страна — как человек со своим характером. Наверняка, когда ты будешь узнавать эти слова, ты поймешь, что какие-то эмоции переживал сам, а какие-то тебя удивят и в следующий раз заставят остановиться и заметить, как солнечный свет ­проникает сквозь листья. И, может быть, это понятие станет твоим. Неважно, как ты его назовешь, главное, что оно не пройдет мимо тебя.', 'Different languages have discovered remarkably precise words to describe subtle nuances of feelings and everyday wonders. Gather several of these words together, and a vivid portrait appears: each country feels like a person with its own distinct character. As you discover them, you will realize that some of these feelings are ones you have experienced yourself, while others will surprise you and inspire you to pause and notice sunlight filtering through leaves. Perhaps these words will become your own companions across cultures.', 'U različitim jezicima postoje nevjerovatno precizne riječi za složene nijanse osjećanja i trenutaka. Kada sakupite nekoliko takvih riječi, pred vama oživljava portret: svaka zemlja je poput čovjeka sa sopstvenim karakterom. Otkrivajući ih, shvatićete da ste mnoga od ovih osjećanja i sami doživjeli, dok će vas neka iznenaditi i navesti da zastanete i primijetite kako se sunčeva svjetlost probija kroz krošnje drveća.', 'Эта книга научит называть по имени то самое неуловимое счастье, для которого в нашем языке почему-то не нашлось отдельного слова!', 'This lovely book gives names to those fleeting moments of wonder that never had a single word in your language!', 'Ova predivna knjiga daje imena onim posebnim trenucima sreće za koje u našem jeziku nismo imali jednu pravu riječ!', '/covers/DP-1068.webp', '#5b8a72', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["real","magic"]', '["linguistics","emotions","world cultures","languages","illustrated guide"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('полеш-открывает-музей-1069', 'DP-1069', 'Полеш открывает музей', 'Kubbe Makes a Museum', 'Poleš otvara muzej', 'Осхиль Кандад Юнсен', 'Åshild Kanstad Johnsen', 'Ošhild Kanstad Jonsen', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Как навести порядок в своей коллекции и стоит ли открывать собственный музей? Полеш, его бабушка и его подруга Йолка решили попробовать - и что же из этого вышло? Смешных лесных человечков, которых придумала и нарисовала норвежская писательница и художник Осхиль Канстад Юнсен, полюбили во всём мире. Если ваши дети всё время что-то находят и подбирают, а вы не знаете, куда всё это девать, - эта книга для вас!', 'How do you organize an ever-growing treasure hoard of pinecones, twigs, and curious pebbles? Little tree-troll Kubbe and his grandma decide to open their very own museum! But when visitors flock in and the collection grows out of control, Kubbe discovers a whole new, creative way to cherish his findings. A delightful, quirky Norwegian story for passionate little collectors everywhere.', 'Kako unijeti red u ogromnu kolekciju grančica, šišarki i neobičnih kamenčića? Mali drveni patuljak Poleš i njegova baka odlučuju da otvore sopstveni muzej! Ali kada posjetilaca postane previše, a eksponati preplave kuću, Poleš otkriva novi, čarobni način čuvanja uspomena. Duhovita norveška slikovnica za sve male sakupljače blaga.', 'Спасительная книга для родителей, чьи карманы вечно полны палочек, камешков и желудей: учимся превращать стихийный хаос в настоящий музей!', 'A lifesaver for parents whose pockets are stuffed with twigs and curious pebbles—showing how to turn clutter into curation!', 'Spas za roditelje čiji su džepovi puni grančica i kamenčića: saznajte kako da dječiji haos pretvorite u pravi muzej!', '/covers/DP-1069.webp', '#4e8563', 'nonfiction', 'ru', 'available', 'Для детей младшего школьного возраста.', '["funny","friends","real"]', '["collecting","museum","nature","forest","creativity"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рождественское-путешествие-мед-1070', 'DP-1070', 'Рождественское путешествие медведей вокруг света', 'The Bears'' Christmas Journey Around the World', 'Božićno putovanje medvjeda oko svijeta', 'Кястутис Каспарявичус', 'Kęstutis Kasparavičius', 'Kęstutis Kasparavičius', '', 'Мир детства', NULL, NULL, 6, 16, 'middle', 'Однажды накануне Рождества семейство бурых медведей отправляется в путешествие на воздушном шаре. Надо успеть поздравить своих друзей во всем мире и подарить им подарки!', 'One Christmas Eve, a family of brown bears sets off on a whimsical hot-air balloon expedition around the globe, determined to deliver presents and festive cheer to all their animal friends.', 'Uoči Božića, porodica smeđih medvjeda kreće na čarobno putovanje balonom na topli vazduh kako bi obišla prijatelje širom planete i svakome uručila praznični poklon.', 'Запрыгивайте в корзину воздушного шара вместе с медвежьим семейством — впереди самое доброе кругосветное рождественское приключение!', 'Hop into the hot-air balloon basket with this lovable bear family for the coziest round-the-world Christmas flight!', 'Uskočite u korpu balona sa ovom medvjeđom porodicom i poletite u najtopliju božićnu avanturu oko svijeta!', '/covers/DP-1070.webp', '#a83232', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["adventure","animals","friends"]', '["bears","christmas","travel","hot air balloon","geography"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дюймовочка-1071', 'DP-1071', 'Дюймовочка', 'Thumbelina', 'Palčica', '', 'Hans Christian Andersen', 'Hans Kristijan Andersen', 'Кястутис Каспарявичус', 'Рипол Кит', NULL, NULL, 6, 16, 'middle', '"Дюймовочка" - одна из самых романтичных сказок Ганса Христиана Андерсена. Историю крошечной девочки, появившейся из цветочного бутона, любят как дети, так и взрослые. Проиллюстрировал книгу известный литовский писатель и художник Кястутис Каспаравичюс. Его радостные, солнечные, нежные рисунки очень хорошо передают волшебное настроение сказки и помогают поверить в то, что чудеса случаются.', 'Hans Christian Andersen''s timeless tale of the tiny girl born from a flower bud comes alive with luminous, tender illustrations by renowned Lithuanian artist Kęstutis Kasparavičius, reminding readers of all ages that wonder and hope can blossom in the smallest places.', 'Jedna od najromantičnijih bajki Hansa Kristijana Andersena o sićušnoj djevojčici rođenoj iz cvjetnog pupoljka oživljava uz tople i nježne ilustracije litvanskog majstora Kęstutisa Kasparavičiusa, učeći nas da i najmanja bića mogu pronaći veliku sreću.', 'Даже крошечная девочка способна совершить огромное путешествие и найти своё истинное счастье среди цветов и птиц!', 'Even the tiniest girl can brave the grandest adventures and discover true happiness among the flowers and swallows!', 'Čak i najmanja djevojčica može hrabro proći kroz velike pustolovine i pronaći svoju pravu sreću!', '/covers/DP-1071.webp', '#e898ac', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["magic","adventure","animals"]', '["fairy tale","classic","thumbelina","flowers","illustrations"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('заяц-моркус-великий-1072', 'DP-1072', 'Заяц Моркус Великий', 'Morkus the Great Hare', 'Zec Morkus Veliki', '', 'Kęstutis Kasparavičius', 'Kęstutis Kasparavičius', 'Кястутис Каспарявичус', 'Мир и образование', NULL, NULL, 6, 16, 'middle', 'Это весёлая и поучительная сказка художника Кястутиса Каспаравичюса. В ней рассказывается о пирогах и пирожных, о зайчике Моркусике и его желании стать большим, толстым и сильным, о смышлёной крольчихе Фране и её Особенной Мягкой Овощной Диете. Словом, о приключениях, о танцах, любви и о том, как оставаться собой.', 'This cheerful and instructive tale by artist Kęstutis Kasparavičius is packed with delicious pies, a little hare named Morkus who dreams of becoming big and strong, and clever bunny Frana with her Special Soft Vegetable Diet. It is a delightful story about adventures, dancing, sweet romance, and the art of being yourself.', 'Ova vesela i poučna priča umjetnika Kęstutisa Kasparavičiusa govori o pitama i kolačima, malom zecu Morkusu i njegovoj želji da postane velik i snažan, te o pametnoj zečici Frani i njenoj Posebnoj mekoj dijeti od povrća. Ukratko, priča o avanturama, plesu, ljubavi i tome kako ostati svoj.', 'Уморительная и аппетитная сказка о том, почему лучше танцевать и любить себя, чем пытаться стать великаном с помощью горы пирожных!', 'A hilarious, pastry-scented tale proving that staying true to yourself is far sweeter than trying to grow huge on pies!', 'Urnebesna i slatka priča koja dokazuje da je uvijek bolje plesati i voljeti sebe nego pokušavati postati div jedući pite!', '/covers/DP-1072.webp', '#d96b27', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","animals"]', '["hares","humor","self-acceptance","pastries","friendship"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('животные-севера-1073', 'DP-1073', 'Животные Севера', 'Wild Animals of the North', 'Životinje Sjevera', 'Дитер Браун', 'Dieter Braun', 'Diter Braun', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Много лет иллюстратор и детский писатель Дитер Браун путешествовал по всему миру, изучая внешний вид животных, их повадки и привычки, а потом создал серию выдающихся плакатов. В эту книгу вошли его лучшие работы, посвященные животному миру Северного полушария. Книга проведет нас по самым необычным местам Северного полушария. Вслед за афалиной мы окунемся в воды океана, вместе с кабаном поищем вкусные корешки на опушке леса, пройдем по следам верблюда сквозь песчаную пустыню, с винторогим козлом поднимемся на вершину горы. А еще нанесем визит песцам, гуляющим по просторам Сибири за Полярным кругом, подглядим, как добывает себе пищу дятел желна, и, несмотря на испанскую жару, составим компанию пиренейской рыси. Уникальный графический стиль Дитера Брауна вдыхает жизнь в животных на картинках. Иллюстрации отличаются выразительными линиями, яркими цветами и в то же время удивительной натуралистичностью и любовью к деталям. А новаторской стиль повествования Брауна и его неподражаемый юмор превращают сухие факты о животных в интереснейшие рассказы.', 'Renowned illustrator Dieter Braun spent years observing creatures around the globe to create this breathtaking guide to Northern Hemisphere wildlife. From Arctic foxes traversing polar snowscapes to mountain goats scaling rocky peaks and dolphins leaping through ocean waves, each animal is rendered in Braun''s celebrated geometric, mid-century art style. Combining striking poster art with witty, fascinating naturalist facts, this volume brings the majesty of northern fauna vividly to life.', 'Poznati ilustrator Diter Braun godinama je putovao svijetom posmatrajući divlje životinje kako bi stvorio ovu veličanstvenu enciklopediju faune Sjeverne hemisfere. Od polarnih lisica na sniježnim prostranstvima Sibira do planinskih koza na strmim vrhovima i delfina u dubinama okeana, svaka životinja oživljava kroz prepoznatljiv retro-grafički stil. Uz impresivne ilustracije i pregršt zanimljivih činjenica, ova knjiga pretvara učenje o prirodi u pravi vizuelni užitak.', 'Потрясающая графическая энциклопедия, в которой северные звери нарисованы так стильно и выразительно, будто позируют для обложки арт-журнала!', 'A visually breathtaking expedition that turns northern wildlife into stunning modern art while sharing fascinating real-world facts!', 'Pravo vizuelno remek-djelo koje divlji svijet Sjevera prikazuje sa toliko stila da će očarati i djecu i odrasle!', '/covers/DP-1073.webp', '#2a5d6a', 'nonfiction', 'ru', 'available', 'Категория: Книжки-картинки', '["animals","adventure","real"]', '["дикая природа","животные","энциклопедия","север","иллюстрации"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('принцесса-и-счастье-1074', 'DP-1074', 'Принцесса и счастье', 'The Princess and Happiness', 'Princeza i sreća', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Сильке Леффлер', 'ИКЕА', NULL, NULL, 6, 16, 'middle', 'В сказочном лесу может случиться все что угодно. И когда принцесса Клара отправляется искать потерянное счастье своего отца, чудеса начинаются. -В пути принцесса встречает волка, огнедышащего дракона и ведьму, которая может кого угодного превратить в камень.', 'Anything can happen in an enchanted forest. When Princess Clara sets out to find her father''s lost happiness, the wonder truly begins. Along the way, the brave princess meets a wolf, a fire-breathing dragon, and a witch capable of turning anyone to stone.', 'U čarobnoj šumi se može desiti bilo šta. Kada princeza Klara krene u potragu za izgubljenom srećom svog oca, čuda počinju. Na tom putu princeza sreće vuka, zmaja koji riga vatru i vješticu koja svakoga može pretvoriti u kamen.', 'Мудрая и добрая сказка от Ульфа Старка, которая напомнит и детям, и взрослым, где же прячется настоящее счастье.', 'A tender and wise fairy tale by Ulf Stark that gently reminds children and grown-ups where real happiness is hidden.', 'Mudra i topla bajka Ulfa Starka koja i djecu i odrasle podsjeća na to gdje se zapravo krije prava sreća.', '/covers/DP-1074.webp', '#427856', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["magic","adventure"]', '["fairy tale","princess","dragon","magic forest","quest"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-асмодей-1075', 'DP-1075', 'Маленький Асмодей', 'Little Asmodeus', 'Mali Asmodej', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Анна Хеглунд', 'Мир детства', NULL, NULL, 6, 16, 'middle', 'Маленький Асмодей со своей семьёй живёт в Подземном царстве. Он слишком добрый и робкий, поэтому его отец - Повелитель Огня и Властелин Вздохов - ужасно им недоволен. Он отправляет сына на Землю, чтобы малыш нашёл того, кто продаст ему свою душу. Асмодей справляется с этой нелёгкой задачей, но может ли Повелитель Огня принять душу человека, который желает добра? О приключениях Асмодея рассказал классик современной детской литературы Ульф Старк, а трогательные иллюстрации нарисовала шведская художница Анна Хеглунд. Эта простая и тонкая философская притча интересна и взрослым, и детям.', 'Little Asmodeus lives in the Underworld, but he is far too gentle and shy to be a proper demon. Disappointed, his father—the Lord of Fire—sends him up to Earth with a difficult mission: find someone willing to sell their soul. Asmodeus succeeds, but what happens when that soul belongs to a kind girl whose only wish is goodness? A tender, philosophical fable about compassion and growing up by master storyteller Ulf Stark, with atmospheric art by Anna Höglund.', 'Mali Asmodej živi u Podzemnom svijetu, ali je previše blag i stidljiv za jednog malog demona. Razočaran, njegov otac — Gospodar vatre — šalje ga na Zemlju sa zadatkom da pronađe nekoga ko bi prodao svoju dušu. Asmodej uspijeva u toj neobičnoj misiji, ali može li Gospodar prihvatiti dušu koja želi samo dobro? Dirljiva i mudra bajkovita priča Ulfa Starka o dobroti, nježnosti i neočekivanom prijateljstvu.', 'Трогательная философская сказка о том, что даже в самом чертёнке может биться огромное доброе сердце.', 'A touching, witty fable proving that even the littlest demon can have the kindest heart.', 'Dirljiva i topla priča o tome kako čak i u jednom malom demonu može da kuca veliko, dobro srce.', '/covers/DP-1075.webp', '#b8432a', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["magic","friends"]', '["kindness","demons","friendship","underworld","parable"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дважды-чемпион-1076', 'DP-1076', 'Дважды чемпион', 'Two-Time Champion', 'Dvostruki šampion', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Маркус Маялуома', 'Малыш', NULL, NULL, 6, 16, 'middle', 'Все целуются - все, кроме Ульфа! Он ещё ни разу не целовался, а другие - бессчётное количество. Брат - как минимум сто раз. Но с кем бы попробовать, да и добиться в этом успеха? А ещё хорошо бы победить в смешном соревновании... Не сомневайтесь, у Ульфа всё получится! Ульф Старк написал около 40 книг и множество сценариев для телевидения, кино и театра. Он лауреат нескольких шведских и международных премий. Маркус Майалуома - один из самых популярных иллюстраторов. За свою работу над мультфильмами и иллюстрациями к детским книгам - как других авторов, так и своих собственных - награждён многочисленными призами.', 'Everyone is kissing—everyone except Ulf! He has never kissed anyone, while everyone else seems to have kissed countless times. His brother, at least a hundred! But who can he try it with, and how can he succeed? On top of that, wouldn''t it be great to win a hilarious competition? Have no fear, young Ulf will find his way!', 'Svi se ljube – svi osim Ulfa! On se još nijednom nije poljubio, dok su drugi to uradili bezbroj puta. Njegov brat – najmanje stotinu puta! Ali s kim da pokuša i kako da u tome uspije? A bilo bi sjajno i pobijediti u nekom smiješnom takmičenju... Ne sumnjajte, Ulf će uspjeti u svemu!', 'Остроумная, искренняя и невероятно смешная история Ульфа Старка о первых поцелуях, нелепых пари и великих детских триумфах.', 'A witty, heartwarming, and genuinely funny tale by Ulf Stark about first kisses, goofy bets, and grand childhood triumphs.', 'Duhovita, topla i nevjerovatno smiješna priča Ulfa Starka o prvim poljupcima, šašavim opkladama i velikim djetinjim pobjedama.', '/covers/DP-1076.webp', '#3b7ec4', 'nonfiction', 'ru', 'available', 'Для дошкольного и младшего школьного возраста.', '["funny","friends","real"]', '["growing up","first kiss","humor","childhood","brothers"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('умнее-старших-1077', 'DP-1077', 'Умнее старших', 'Smarter Than the Grown-ups', 'Pametniji od starijih', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Маркус Маялуома', 'Малыш', NULL, NULL, 6, 16, 'middle', 'Деревня Стюбери просто кишмя кишит детективами. Ульф тоже хочет стать сыщиком! Но это опасное занятие. И совсем не для малышей. Немного хитрости - и он берёт дело в свои руки! Ульф Старк написал около 40 книг и множество сценариев для телевидения, кино и театра. Он лауреат нескольких шведских и международных премий. Маркус Майалуома - один из самых популярных иллюстраторов. За свою работу над мультфильмами и иллюстрациями к детским книгам - как других авторов, так и своих собственных - награждён многочисленными призами. Отличный мальчишка Ульфик - герой целой серии книг. С ним все время приключаются смешные истории, про них мы и узнаем из книг, которые появятся позже.', 'The village of Stureby is practically crawling with detectives, and little Ulf desperately wants to be one too! Grown-ups say sleuthing is dangerous and definitely not for kids, but with a bit of quick thinking and sly mischief, Ulf takes the investigation into his own hands. A delightfully funny and heartwarming Swedish childhood adventure.', 'Selo Sturebi prosto vrvi od detektiva, a i mali Ulf želi da postane pravi istražitelj! Stariji tvrde da je to opasan posao i nikako za mališane, ali uz malo lukavstva i hrabrosti, Ulf preuzima stvar u svoje ruke. Topla i neizmjerno duhovita švedska priča o odrastanju i dječijoj domišljatosti.', 'Кто сказал, что расследования не для малышей? Маленький Ульф докажет, что детская смекалка легко перехитрит любого взрослого сыщика!', 'Who says detective work isn''t for kids? Little Ulf is here to prove that a clever child can outsmart any grown-up sleuth!', 'Ko kaže da detektivski posao nije za klince? Mali Ulf će dokazati da dječija domišljatost može nadmudriti svakog odraslog!', '/covers/DP-1077.webp', '#d97724', 'nonfiction', 'ru', 'available', 'Для дошкольного и младшего школьного возраста. | поврежден корешок книги', '["funny","adventure","real"]', '["detective","childhood","humor","sweden","growing up"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('долой-рабство-1078', 'DP-1078', 'Долой рабство', 'Down with Slavery!', 'Dolje ropstvo!', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Маркус Маялуома', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Сердитый дедушка рад объявить тебя лентяем только потому, что ты не копаешься в огороде. Больше того, он готов объявить тебя рабом! Ничего не поделаешь, теперь придется ему помогать, трудиться до седьмого пота. Но, к счастью, есть и другой дедушка. Возможно, он спасет тебя от рабства... Эта книга из автобиографической серии о мальчике Ульфе. Ульф — один из самых ярких персонажей Старка, он кочует из книги в книгу вместе со своим вредным старшим братом и ворчливым дедушкой.', 'A grumpy grandfather is quick to label you lazy just because you''re not weeding the garden. Worse yet, he proclaims you his unpaid laborer! There is no choice but to sweat it out under the summer sun—unless, of course, your other grandfather comes to the rescue... An autobiographical tale from master storyteller Ulf Stark, bursting with mischievous childhood charm, sibling bickering, and family eccentricities.', 'Mrzovoljni djed jedva čeka da te proglasi ljenjivcem samo zato što ne plijevi baštu, pa čak ide toliko daleko da te proglasi svojim slugom! Nema druge nego raditi do iznemoglosti, osim ako te drugi, mnogo blaži djed ne spasi ove muke. Ova dirljiva i duhovita autobiografska priča Ulfa Starka donosi vesele dogodovštine nestašnog dječaka, njegovog napornog starijeg brata i neobičnih djedova.', 'Прекрасный повод посмеяться над огородным «рабством» и вспомнить, что даже самые ворчливые дедушки любят нас больше всех на свете!', 'A hilarious and heartwarming reminder that enduring garden chores is much easier when you have a quirky sense of humor and a second grandpa on standby!', 'Urnebesna i topla priča koja dokazuje da se svako baštensko „ropstvo” lakše podnosi uz dobar humor i tajnog saveznika!', '/covers/DP-1078.webp', '#d97736', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["funny","real"]', '["grandparents","humor","childhood","family","scandinavian literature"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мина-и-коге-уезжают-на-запад-1079', 'DP-1079', 'Мина и Коге уезжают на Запад', 'Mina and Kåge Go West', 'Mina i Koge odlaze na Zapad', 'Анна Хеглунд', 'Anna Höglund', 'Ana Heglund', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Встречайте Мину и Коге - пару симпатичных шведских медведей. Книги об их непростых взаимоотношениях помогут детям понять этих странных взрослых. Мина и Коге переезжают в Америку. Коге в восторге от США, а вот Мине грустно и одиноко. К тому же надвигается страшная буря по имени Хуррикан! Сможет ли Мина привыкнуть к новой стране?', 'Meet Mina and Kåge, a charming pair of Swedish bears. Moving to America brings mixed feelings: while Kåge is thrilled by the new country, Mina feels lonely and homesick. To make matters worse, a fierce hurricane is headed their way! A gentle, deeply relatable story about big changes, adult relationships, and finding comfort in a foreign land.', 'Upoznajte Minu i Kogea, par simpatičnih švedskih medvjeda. Preseljenje u Ameriku donosi pomiješana osjećanja: dok je Koge oduševljen, Mina se osjeća usamljeno i tužno. Pored svega, približava se i strašna oluja – uragan! Nježna i iskrena priča o velikim promjenama, osjećanjima i navikavanju na novu sredinu.', 'Трогательная и честная история о переезде, тоске по дому и о том, как пережить любую бурю, когда рядом близкий медведь.', 'A touching and honest tale about moving across the world, homesickness, and weathering any storm together.', 'Dirljiva i iskrena priča o selidbi, nostalgiji i tome kako prebroditi svaku oluju uz podršku dragog prijatelja.', '/covers/DP-1079.webp', '#c46835', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["animals","friends","real"]', '["bears","moving","emotions","friendship","america"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мина-уходит-навсегда-1080', 'DP-1080', 'Мина уходит навсегда', 'Mina Leaves Forever', 'Mina odlazi zauvijek', 'Анна Хеглунд', 'Anna Höglund', 'Ana Heglund', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Встречайте Мину и Коге — пару симпатичных шведских медведей. Книги об их непростых взаимоотношениях помогут детям понять этих странных взрослых. Коге забыл про чай, умчался гулять и даже не сказал Мине «до свиданья». Как он мог! Мина решила наказать Коге — и уйти навсегда. Пусть он поймет, кого потерял!', 'Meet Mina and Kåge, a charming bear duo navigating the bumpy road of relationships. When Kåge forgets tea time and dashes off without even saying goodbye, Mina decides to pack up and leave forever to teach him a lesson! A wonderfully gentle, funny, and profound look at hurt feelings, drama, and why both kids and grown-ups sometimes act so oddly.', 'Upoznajte Minu i Kågea, šarmantan par medvjeda koji uče kako da prevaziđu nesuglasice. Kada Kåge zaboravi na čaj i odjuri bez pozdrava, Mina odlučuje da ode zauvijek kako bi shvatio koga je izgubio. Nježna, duhovita i mudra priča o durenju, velikim osjećanjima i tome kako razumjeti postupke onih koje volimo.', 'Идеальное руководство по драматическому надуванию губ и уходу навсегда, в котором каждый узнает себя или близкого!', 'The ultimate masterclass in dramatic pouting and storming off forever—guaranteed to make both kids and adults smile with self-recognition!', 'Vrhunski vodič za dramatično durenje i odlazak zauvijek u kom će se sigurno prepoznati i mali i veliki!', '/covers/DP-1080.webp', '#c46845', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["friends","animals","funny"]', '["bears","emotions","relationships","psychology","friendship"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('история-об-эле-и-космонавте-ла-1081', 'DP-1081', 'История об Эле и космонавте Лайке', 'The Story of Ella and Laika the Space Dog', 'Priča o Eli i psu kosmonautu Lajki', 'Хелен Рундгрен', 'Helena Rundgren', 'Helena Rundgren', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'С дворняжкой по кличке Крошка Эля происходит что-то странное. Люди поселили ее в большую клетку, кормят странной едой, учат выполнять разные команды. В целом неплохо, но иногда так хочется побегать по травке! Крошка Эля еще не знает, что станет одной из самых знаменитых собак в мире. Но обо всем по порядку…', 'Something very unusual is happening to a little stray pup named Ella. Humans placed her in a spacious enclosure, feed her peculiar treats, and train her to follow special commands. It''s not so bad, though she truly misses frolicking on the green grass. Little Ella has no idea yet that she is about to become one of the most famous dogs in history—Laika the astronaut dog.', 'Sa malom mješankom po imenu Eli dešava se nešto sasvim neobično. Ljudi su je smjestili u veliki kavez, hrane je čudnom hranom i uče da izvršava razne komande. Uopšte nije loše, iako joj ponekad jako nedostaje trčanje po travi! Mala Eli još uvijek ne sluti da će postati jedan od najslavnijih pasa na svijetu—kosmonaut Lajka.', 'Трогательный взгляд на историю покорения космоса глазами маленькой дворняжки, шагнувшей к звёздам.', 'A poignant, tender look at the dawn of space exploration seen through the eyes of a brave little stray who reached for the stars.', 'Dirljiva priča o osvajanju svemira viđena očima hrabrog malog psa koji se vinuo među zvijezde.', '/covers/DP-1081.webp', '#284b63', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["animals","real","adventure"]', '["space","dogs","history","science","laika"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('голем-1082', 'DP-1082', 'Голем', 'The Golem', 'Golem', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', '', 'дети ОГИ', NULL, NULL, 6, 16, 'middle', 'Исаак Башевис Зингер (1904 - 1991) - знаменитый еврейский писатель, лауреат Нобелевской премии по литературе. "Голем" - захватывающая и мудрая история, в основе которой лежит старинная еврейская легенда о глиняном человеке, созданном для защиты евреев в трудных ситуациях. И однажды он вышел из-под контроля своего создателя…', 'Isaac Bashevis Singer, Nobel Prize laureate in Literature, breathes life into the ancient Jewish legend of the Golem. Crafted from river clay to protect the community from injustice, this mighty giant faithfully serves his creator—until an uncontrollable power begins to stir within him.', 'Isak Baševis Singer, dobitnik Nobelove nagrade za književnost, oživljava drevnu jevrejsku legendu o Golemu. Stvoren od riječne gline kako bi zaštitio svoj narod od nepravde, ovaj moćni div vjerno služi svom tvorcu — sve dok se u njemu ne probudi sila koju niko ne može zauzdati.', 'Мудрая пражская легенда о глиняном защитнике, которая напоминает: даже самое доброе волшебство требует огромной ответственности.', 'A gripping Prague legend about a clay protector that reminds us even the noblest magic demands immense responsibility.', 'Mudra praška legenda o glinenom zaštitniku koja nas podsjeća da i najplemenitija magija zahtijeva ogromnu odgovornost.', '/covers/DP-1082.webp', '#845d42', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["magic","spooky","adventure"]', '["folklore","legends","prague","jewish culture","nobel laureate"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('макси-пес-фик-1083', 'DP-1083', 'Макси-пес Фик', 'Maxidog Fík', 'Maksi-pas Fik', 'Рудольф Чехура, Ирхи Шаломоун', 'Rudolf Čechura, Jiří Šalamoun', 'Rudolf Čehura, Jirži Šalamoun', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Как-то раз в одной самой обыкновенной семье появился маленький симпатичный пёсик, назвали его Фик. Он поселился в коробке от сапог, но на другой день она уже была ему мала. Фик был ужасным обжорой и рос так быстро, что вскоре даже собачья будка трещала по швам. Теперь это был уже не пёсик, а настоящий макси-пёс. Папа решил было продать его, но Фик оказался необыкновенным псом: он спас свою хозяйку, научился говорить, водить машину, а ещё он ходил в магазин и даже участвовал в скачках. Благодаря многосерийному мультфильму, снятому по мотивам этой книги, Фик известен в СССР и России ещё с 70-х годов прошлого века.', 'Once upon a time, an ordinary family adopted an adorable tiny pup named Fík. But Fík was a champion eater and grew so astonishingly fast that soon even a sturdy doghouse couldn''t hold him! Now a true giant of a dog, he proves his worth by rescuing his young owner, learning to speak, driving a car, and even winning a horse race. A beloved Czech classic packed with laughter, adventures, and heart.', 'Jednog dana u sasvim običnu porodicu stiglo je majušno, slatko štene po imenu Fik. Međutim, Fik je imao ogroman apetit i rastao je tolikom brzinom da mu je uskoro i velika kućica postala tijesna! Postao je pravi džinovski pas koji ne samo da je spasio svoju malu vlasnicu, već je naučio i da govori, vozi auto, ide u prodavnicu pa čak i da pobjeđuje na konjskim trkama.', 'Если ваш щенок за ночь перерос коробку из-под обуви, не пугайтесь: возможно, он просто гений и скоро научит вас водить машину!', 'If your puppy outgrows a shoe box overnight, don''t worry: he might just be a mastermind who''ll soon learn to drive your car!', 'Ako vaše štene preko noći preraste kutiju za cipele, bez brige: možda je prosto genijalac koji će vas uskoro naučiti da vozite auto!', '/covers/DP-1083.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","adventure","animals"]', '["giant dog","czech classic","humor","family","talking animals"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('макси-пес-фик-приключения-прод-1084', 'DP-1084', 'Макси-пес Фик приключения продолжаются', 'Maxidog Fík: The Adventures Continue', 'Maksi pas Fik: Avanture se nastavljaju', 'Рудольф Чехура, Ирхи Шаломоун', 'Rudolf Čechura, Jiří Šalamoun', 'Rudolf Čehura, Jirži Šalamoun', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Вы уже знакомы с собакой по имени Фик? Этот необыкновенный макси-пёс умеет говорить, читать, а иногда он даже ходит в магазин и участвует в скачках. Умеет ли Фик водить машину? Может ли он работать юнгой на корабле? Об этом вы узнаете из книги о новых приключениях макси-пса! Благодаря многосерийному мультфильму, снятому по мотивам этой книги, Фик известен в СССР и России ещё с 70-х годов прошлого века.', 'Have you already met the gentle giant named Fík? This extraordinary maxidog can talk, read, go shopping, and even compete in horse races! But can he drive a car or serve as a sailor on a ship? Find out in this hilarious collection of new adventures starring everyone''s favorite overgrown pup, made famous across generations by the classic animated series.', 'Da li ste već upoznali psa po imenu Fik? Ovaj neobični maksi pas zna da govori, čita, pa čak i da ide u prodavnicu ili učestvuje u konjičkim trkama. Ali da li Fik umije da vozi auto ili da bude mornar na brodu? Saznajte u novim dogodovštinama ovog džinovskog i pametnog psa, poznatog generacijama iz legendarnog crtanog filma.', 'Если вы думаете, что ваш пёс сообразительный, познакомьтесь с гигантом Фиком — он и машину водит, и корабли водит, и гарантированно рассмешит всю семью!', 'Think your dog is smart? Wait until you meet Maxidog Fík, an overgrown pup who can drive cars, sail ships, and bring non-stop giggles to the whole family!', 'Ako mislite da je vaš pas pametan, sačekajte da upoznate Fika — ovaj džinovski pas vozi auto, plovi morem i nasmijaće cijelu porodicu!', '/covers/DP-1084.webp', '#e05638', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["funny","animals","adventure"]', '["dogs","czech literature","humor","adventures","talking animals"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кирпичик-1085', 'DP-1085', 'Кирпичик', 'Brick: Who Found Herself in Architecture', 'Ciglica: Priča o arhitekturi', 'Джошуа Дэвид Стайн', 'Joshua David Stein', 'Džošua Dejvid Stajn', 'Джулия Ротман', 'Clever', NULL, NULL, 6, 16, 'middle', 'Какие бывают сказки? Волшебные и добрые, а еще бывают сказки архитектурные! Сказка «Кирпичик» — именно такая! Архитектура окружает нас — все здания однажды кто-то придумал. И некоторые из этих зданий состоят из кирпичиков! Мама говорила малышке Кирпичику: «Все большие вещи начинаются с маленьких кирпичиков. Оглянись — и увидишь». Кирпичик отправляется в большое путешествие, чтобы найти свое предназначение. В пути она встречает замки, церкви и минареты, синагоги и храмы, стены и дома. Где же ее место? Кем ей стать? Эта сказка наполнена не только архитектурой, но и глубоким смыслом. Как найти себя в огромном мире? Как маленький кирпичик может стать чем-то большим? Все архитектурные памятники: каждый храм, собор и даже каждый дом, нарисованный на страницах, — настоящие! Синагога Парк-Ист в США, минарет Малвия в Ираке, крепость Арк в Бухаре и даже собор Василия Блаженного — вы увидите целый мир вместе с малышкой Кирпичиком. Стильные иллюстрации помогут развивать чувство цвета и художественный вкус. Книгу «Кирпичик» автор посвящает «Всем большим, которые когда-то были маленькими, и всем маленьким, которые однажды станут большими».', 'Architecture surrounds us everywhere, and every majestic building was once just a dream built from tiny pieces. Little Brick sets off on a grand journey to find her true purpose in the world. Along the way, she discovers real architectural masterpieces—from ancient fortresses to soaring minarets and ornate cathedrals. A warm, beautifully illustrated tale about finding your place in a vast world, showing that every great thing starts with a small, steady beginning.', 'Arhitektura nas okružuje posvuda, a svaka velika građevina počinje od malih koraka. Mala Ciglica kreće na veliko putovanje svijetom kako bi pronašla svoju pravu svrhu. Na tom putu susreće prave arhitektonske spomenike — dvorce, minarete, sinagoge i hramove. Ova topla i stilski ilustrovana priča uči djecu prepoznavanju ljepote zgrada oko nas i podsjeća da svako od nas, ma koliko mali bio, može postati dio nečeg veličanstvenog.', 'Вдохновляющая архитектурная сказка о том, что даже самое грандиозное чудо света начинается с одного маленького кирпичика.', 'An inspiring architectural journey showing that even the grandest wonders of the world start with a single little brick.', 'Nadahnjujuća arhitektonska bajka koja podsjeća da i najveća svjetska čuda počinju od samo jedne male cigle.', '/covers/DP-1085.webp', '#c45436', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["adventure","real"]', '["architecture","world wonders","self-discovery","art","cities"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-господина-бальдера-1086', 'DP-1086', 'Тайна господина Бальдера', 'The Secret of Mr. Balder', 'Tajna gospodina Baldera', 'Якоб Вегелиус', 'Jakob Wegelius', 'Jakob Vegelijus', 'Якоб Вегелиус', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Господин Бальдер — отменный повар, виртуозный музыкант и любитель почитать в одиночестве. Он всегда ходит одной и той же дорогой, обходя крутые подъемы и наслаждаясь благоуханием цветов. В его тихой и уютной усадьбе не случается ничего примечательного. Но вот однажды утром в четверг, когда господин Бальдер, как обычно, подкреплялся овсянкой, ему на глаза попалось странное объявление…', 'Mr. Balder is an exquisite chef, a virtuoso musician, and an avid lover of quiet reading. He always walks the exact same route, avoids steep hills, and delights in the scent of blooming flowers. Nothing unusual ever happens at his serene estate. But one Thursday morning, as he enjoys his routine bowl of oatmeal, his eye catches an utterly bizarre classified ad...', 'Gospodin Balder je izvrstan kuvar, virtuozni muzičar i ljubitelj čitanja u osami. Uvijek šeta istom stazom, izbjegava strme uspone i uživa u mirisu cvijeća. Na njegovom tihom i udobnom imanju nikada se ne dešava ništa neobično. Ali jednog četvrtka ujutru, dok je po običaju doručkovao ovsenu kašu, pogled mu je privukao jedan sasvim čudan oglas...', 'Даже у самого предсказуемого и тихого джентльмена за чашкой овсянки может начаться невероятное детективное расследование!', 'Even the most quiet and predictable gentleman can find himself swept into a grand mystery over a simple bowl of morning oatmeal!', 'Čak i najmirniji i najpredvidljiviji gospodin može se naći usred nevjerovatne misterije samo zbog jednog doručka uz ovsenu kašu!', '/covers/DP-1086.webp', '#3b6978', 'nonfiction', 'ru', 'available', 'новое в библиотеке', '["adventure","funny"]', '["детектив","приключения","тайны","уют","скандинавская литература"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('легенда-о-салли-джонс-1087', 'DP-1087', 'Легенда о Салли Джонс', 'The Legend of Sally Jones', 'Legenda o Sali Džons', 'Якоб Вегелиус', 'Jakob Wegelius', 'Jakob Vegelijus', 'Якоб Вегелиус', 'Планета детства', NULL, NULL, 6, 16, 'middle', 'Эта история берет свое начало сто лет назад, когда в ненастную тропическую ночь в африканских джунглях родилась маленькая горилла. На долю Салли Джонс выпали суровые испытания, волею судьбы ей пришлось совершить путешествие по всему миру, она выступала в цирке шапито, долгие годы томилась в неволе в зоопарке, работала кочегаром на корабле и зазывалой в трактире. В ее истории было все: кража, погоня, настоящая дружба, предательство и надежда…', 'This story begins a hundred years ago, when a little gorilla was born in the African jungle on a stormy tropical night. Sally Jones faced harsh trials that carried her around the world: performing under a circus big top, languishing in a zoo, toiling as a steamship stoker, and greeting guests at a bustling tavern. Her epic journey has it all: daring heists, wild chases, true friendship, heartbreak, and unyielding hope.', 'Ova priča počinje prije sto godina, kada je u olujnoj tropskoj noći u afričkoj džungli rođena mala gorila. Sali Džons je doživjela teška iskušenja koja su je provela kroz čitav svijet: nastupala je u putujućem cirkusu, godinama čamila u zoološkom vrtu, radila kao ložačica na parobrodu i privlačila goste u krčmi. Njena nevjerovatna sudbina puna je krađa, potjera, pravog prijateljstva, izdaje i nepokolebljive nade.', 'Приготовьтесь к захватывающему кругосветному странствию в компании самой умной, смелой и благородной гориллы на свете!', 'Get ready for an epic globetrotting journey alongside the cleverest, bravest, and most noble gorilla in children''s literature!', 'Pripremite se za uzbudljivo putovanje oko svijeta u društvu najpametnije, najhrabrije i najplemenitije gorile na svijetu!', '/covers/DP-1087.webp', '#2b4c59', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["adventure","animals","friends"]', '["gorilla","sea voyage","circus","journey","friendship"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хвоинка-свинофуфик-и-носик-роз-1088', 'DP-1088', 'Хвоинка, свинофуфик и носик-розочкой', 'Kotten, Piggy-Puff, and Rosy Nose', 'Iglanka, Prase-Pufica i Roze Nosić', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Однажды вечером к ежихе Хвоинке пришла гостья... Эти стихи всемирно известной шведской писательницы Лены Андерсон перевёл на русский язык замечательный поэт Михаил Яснов. Для тех, кто учится считать и любит рассматривать картинки!', 'One evening, hedgehog Kotten receives an unexpected guest... These charming rhyming verses by the internationally acclaimed Swedish author Lena Anderson invite young readers to discover numbers, spot playful details, and fall in love with cozy woodland adventures.', 'Jedne večeri, ježica Iglanka dočekuje neočekivanu gošću... Ovi ljupki stihovi svjetski poznate švedske autorke Lene Anderson pozivaju mališane da kroz igru i tople ilustracije s lakoćom nauče da broje.', 'Уютная и добрая книжка в стихах, с которой учиться считать — сплошное лесное удовольствие!', 'A delightfully cozy rhyming tale that turns learning to count into a sweet woodland celebration!', 'Topla i nježna pričica u stihovima uz koju je učenje brojanja prava šumska zabava!', '/covers/DP-1088.webp', '#e8929e', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["animals","friends","funny"]', '["rhymes","counting","hedgehogs","swedish literature","early learning"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-хвоинки-1089', 'DP-1089', 'Тайна Хвоинки', 'Pinecone''s Secret', 'Tajna Iglice', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Ежиха Хвоинка весь день не выходит из дома - что случилось? Эти стихи всемирно известной шведской писательницы Лены Андерсон перевёл на русский язык замечательный поэт Михаил Яснов. Для тех, кто учится считать и любит рассматривать картинки!', 'Hedgehog Pinecone hasn''t left her cozy house all day—what could have happened? This charming rhyming tale by renowned Swedish author and illustrator Lena Anderson is perfect for little ones learning to count and exploring wonderful pictures.', 'Ježica Iglica cijeli dan ne izlazi iz svoje kućice – šta se to dogodilo? Ovi topli stihovi poznate švedske autorke Lene Anderson savršeni su za mališane koji uče da broje i vole da istražuju divne ilustracije.', 'Загляните в уютный домик ежихи Хвоинки: здесь можно не только раскрыть её секрет, но и весело научиться считать!', 'Peek inside little hedgehog Pinecone''s cozy home to uncover her sweet secret and practice counting along the way!', 'Zavirite u topli dom ježice Iglice: otkrijte njenu slatku tajnu i usput kroz stihove naučite da brojite!', '/covers/DP-1089.webp', '#527559', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["animals","friends"]', '["hedgehog","counting","poetry","picture book","animals"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('все-друзья-наперечет-1090', 'DP-1090', 'Все друзья наперечет', 'Counting All My Friends', 'Svi prijatelji na broju', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Знали бы вы, сколько зверей пришло в гости к Хвоинке! Эти стихи всемирно известной шведской писательницы Лены Андерсон перевёл на русский язык замечательный поэт Михаил Яснов. Для тех, кто учится считать, любит учить стихи наизусть и рассматривать картинки!', 'If only you knew how many animal guests came to visit Little Pinecone! Written in delightful verse by world-renowned Swedish author Lena Anderson, this book is perfect for little ones learning to count, reciting rhymes, and exploring whimsical illustrations.', 'Kad biste samo znali koliko je šumskih životinja došlo u posjetu Šišarkici! Ovi stihovi svjetski poznate švedske autorke Lene Anderson savršeni su za mališane koji uče da broje, vole da recituju i uživaju u detaljnim ilustracijama.', 'Считать лесных гостей в стихах куда веселее, чем обычные скучные цифры!', 'Counting woodland party guests in bouncy rhymes is way more fun than ordinary math!', 'Brojanje šumskih gostiju kroz rime mnogo je zabavnije od obične matematike!', '/covers/DP-1090.webp', '#527943', 'nonfiction', 'ru', 'available', 'Категория: Ульф Старк', '["animals","friends","funny"]', '["counting","poetry","animals","rhymes","nature"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('веста-линнея-и-ее-друзья-1091', 'DP-1091', 'Веста-Линнея и ее друзья', 'Vesta-Linnea and Her Friends', 'Vesta-Lineja i njeni prijatelji', 'Туве Аппельгрен', 'Tove Appelgren', 'Tuve Apelgren', 'Салла Саволайнен', 'Белая ворона', NULL, NULL, 6, 16, 'middle', '"Минди обещала позвонить, как только освободится. Скоро, скоро, совсем скоро. Прыг, прыг, прыг. Сегодня пятница! Светит солнце! Щебечут птицы! Все просто замечательно! Прыг!" Веста-Линнея ждет звонка от Минди и не выпускает телефон из рук. Она сгорает от нетерпения, ведь Минди такая веселая и смелая! Но телефон молчит. Неужели Минди не хочет дружить с Вестой-Линнеей?', 'Vesta-Linnea clutches the phone, bursting with excitement: Friday is here, the sun is shining, and her friend Mindy promised to call as soon as she was free! But as the minutes tick by in complete silence, doubt begins to creep in. Does Mindy truly want to be friends, or has Vesta-Linnea been forgotten? A warm and perceptive story about navigating the ups and downs of childhood friendship.', 'Vesta-Lineja ne ispušta telefon iz ruku i nestrpljivo čeka: petak je, sija sunce, a vesela Mindi je obećala da će se javiti čim bude slobodna! Ipak, telefon uporno ćuti. Da li Mindi zaista želi da se druži sa njom ili je zaboravila na dogovor? Nježna i iskrena priča o prijateljstvu, strpljenju i nesigurnostima koje svi ponekad osjećamo.', 'Каждый, кто хоть раз гипнотизировал молчащий телефон, сразу поймёт бурю чувств Весты-Линнеи — очень искренняя и узнаваемая история о дружбе!', 'Anyone who has ever stared down a silent phone waiting for a best friend to call will instantly relate to Vesta-Linnea’s emotional rollercoaster!', 'Svako ko je ikada hipnotisano gledao u telefon čekajući poziv druga, odmah će prepoznati sebe u ovoj dirljivoj priči!', '/covers/DP-1091.webp', '#e8a838', 'nonfiction', 'ru', 'available', 'Для дошкольного возраста.', '["friends","real"]', '["friendship","emotions","patience","growing up","scandinavian books"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('веста-линнея-и-собака-1092', 'DP-1092', 'Веста-Линнея и собака', 'Vesta-Linnea and the Dog', 'Vesta-Lineja i pas', 'Туве Аппельгрен', 'Tove Appelgren', 'Tove Appelgren', 'Салла Саволайнен', 'Белая ворона', NULL, NULL, 6, 16, 'middle', '- Мама, - говорит Веста-Линнея однажды за ужином. - Я считаю, нам надо завести собаку. Эта светлая мысль рано или поздно приходит в голову почти каждому ребенку. Весте-Линнее повезло - и в ее семье появляется прелестное создание по имени Чих. У него бархатный лобик, смешной носик и маленькое сердечко, чье биение наполняет Весту-Линнею неизведанным до этого счастьем. Но тут на всю семью обрушивается ужасная новость - у Виктора… аллергия на шерсть! Неужели придется расстаться с Чихом навсегда?', '“Mom,” Vesta-Linnea announces at dinner, “I think we need a dog.” It''s a dream shared by almost every child, and soon a charming pup named Sneezy joins the family, melting Vesta-Linnea’s heart. But then unexpected news hits: Viktor is allergic to fur! Could they really have to say goodbye to their beloved pet?', '„Mama“, kaže Vesta-Lineja jedne večeri za večerom, „mislim da nam treba pas.“ Taj divan san dijeli skoro svako dijete, a porodici se ubrzo pridružuje preslatko štene. Međutim, iznenada stiže teška vijest: Viktor je alergičan na dlaku! Da li će zaista morati zauvijek da se oproste od svog novog ljubimca?', 'Трогательная и очень жизненная история о мечте о щенке, огромной нежности и непростых решениях, которые порой приходится принимать всей семьёй.', 'A tender, relatable family tale about the dream of having a puppy, boundless affection, and the tough choices families sometimes have to face together.', 'Dirljiva i iskrena porodična priča o želji za psićem, velikoj ljubavi i teškim odlukama koje se moraju donijeti zajedno.', '/covers/DP-1092.webp', '#d0733f', 'nonfiction', 'ru', 'available', 'Для детей дошкольного возраста.', '["animals","real","friends"]', '["dogs","pets","family life","empathy","growing up"]', 1792836322701, 1792845706198);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('веста-линнея-и-лунный-свет-1093', 'DP-1093', 'Веста-Линнея и лунный свет', 'Vesta-Linnea and the Moonlight', 'Vesta-Lineja i mjesečina', 'Туве Аппельгрен', 'Tove Appelgren', 'Tuve Apelgren', 'Салла Саволайнен', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Иногда безо всякой причины на Весту-Линнею нападает черная тоска, но, к счастью, ненадолго. А что делать, если грусть не проходит? Если человек плачет весь день и его горе такое большое, что не помещается в комнате? А вдруг колодезной ведьме из страшного сна тоже бывает тоскливо? И как связаны грусть и радость?', 'Sometimes deep gloom washes over Vesta-Linnea for no reason at all, but luckily it usually passes quickly. But what should one do when sadness lingers? What if someone cries all day long and their sorrow is so vast it can''t even fit in the room? Could the creepy well-witch from a nightmare be feeling blue, too? A tender, comforting picture book exploring the mysteries of sadness, fear, and joy.', 'Ponekad bez ikakvog razloga Vesta-Lineju obuzme crna tuga, ali na sreću, ne traje dugo. Šta raditi ako tuga ipak ne prolazi? Ako neko plače po cijeli dan, a njegov bol je toliki da ne može da stane u sobu? Da li je možda i vještici iz strašnog sna ponekad teško oko srca? Nježna priča o tome kako su tuga i radost neraskidivo povezane.', 'Утешительная и честная книга о том, что грустить — это нормально, даже когда печаль кажется больше целой комнаты.', 'A deeply comforting and honest tale reassuring young readers that feeling blue is completely normal, even when sadness feels too big for the room.', 'Tješna i iskrena priča o tome da je sasvim u redu biti tužan, čak i kada tuga djeluje veća od cijele sobe.', '/covers/DP-1093.webp', '#2c3e66', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["real"]', '["emotions","sadness","family","bedtime","growing up"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дикие-соседи-1094', 'DP-1094', 'Дикие соседи', 'Wild Neighbors', 'Divlje komšije', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Ульрика Кестере', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Кролик купил себе летний домик и отправился в отпуск. Однако возле домика он обнаружил четырех диких кошек, которые лакали воду из фонтана! Кролик страшно перепугался. Что же делать? Шведская художница Ульрика Кестере сочинила и нарисовала историю о том, что даже страшные дикие кошки могут стать твоими друзьями, надо лишь попробовать найти к ним подход. Для дошкольного возраста', 'Rabbit buys a cozy summer house and heads off on vacation, only to discover four wild cats drinking from his fountain! Terrified at first, Rabbit soon learns that even the wildest neighbors can become good friends if you just know how to find the right approach. A heartwarming, beautifully illustrated picture book by Swedish author Ulrika Kestere.', 'Zec je kupio ljetnjikovac i krenuo na odmor, ali je pored kuće zatekao četiri divlje mačke kako piju vodu iz fontane! Isprva preplašen, zec ubrzo uči da čak i najstrašnije divlje komšije mogu postati najbolji prijatelji kada im priđemo otvorenog srca. Topla priča švedske autorke i ilustratorke Ulrike Kestere.', 'Обаятельная история о том, как перебороть первый страх и подружить робкого кролика с самыми зубастыми соседями!', 'A charming tale showing that even the fiercest-looking neighbors can turn into dear friends once you share a little kindness!', 'Šarmantna priča o tome kako prevazići strah i pronaći prave prijatelje među onima koji na prvi pogled djeluju opasno!', '/covers/DP-1094.webp', '#627c59', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["animals","friends","funny"]', '["cats","rabbits","friendship","vacation","picture book"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('теплый-свитер-для-лемура-1095', 'DP-1095', 'Теплый свитер для лемура', 'A Warm Sweater for a Lemur', 'Topli džemper za lemura', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Ульрика Кестере', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Далеко на севере есть чернично-синий дом, покрытый травяной крышей. В нем живут рысь Лиза и медвежонок Нильс. К ним в гости приезжает лемур Отто. Вот это событие! Отто - художник и хочет нарисовать северное сияние. Все бы ничего, вот только Отто прибыл из теплых краев и простудился. Но друзья придумали замечательный способ его подбодрить!', 'Far up north stands a blueberry-blue house with a grass-covered roof, home to Lisa the lynx and Nils the bear cub. One day, Otto the lemur arrives for a visit—what an adventure! Otto is an artist whose biggest dream is to paint the northern lights. But coming from the warm tropics, he instantly catches a cold. Luckily, his caring friends come up with the coziest way to cheer him up!', 'Daleko na sjeveru stoji borovnica-plava kućica sa travnatim krovom u kojoj žive ris Lisa i medvjedić Nils. U posjetu im stiže lemur Oto — kakav uzbudljiv događaj! Oto je umjetnik koji sanja da naslika polarnu svjetlost. Međutim, stigao je iz toplih krajeva i ubrzo se prehladio. Srećom, njegovi brižni prijatelji smislili su najtopliji način da ga obraduju!', 'Уютная северная история о дружбе, живописи и о том, как согреть даже самого теплолюбивого путешественника!', 'A delightfully cozy northern tale about friendship, art, and how to warm the heart and paws of a sun-loving traveler.', 'Nevjerovatno topla sjevernjačka priča o prijateljstvu, umjetnosti i tome kako ugrijati i najzimogrožljivijeg putnika!', '/covers/DP-1095.webp', '#2c4c6e', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["animals","friends"]', '["friendship","winter","animals","art","cozy"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленькая-ежинка-и-большая-еже-1096', 'DP-1096', 'Маленькая ежинка и большая ежевика', 'Little Hedgehog and the Big Blackberry', 'Mala ježica i velika kupina', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Ульрика Кестере', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Бывает, все наперебой поучают, говорят, что нужно делать. Робкая маленькая Ежинка попала как раз в такую историю. Она смущается, теряется, пугается, ко всем прислушивается. Но получится ли следовать таким разным советам? Да и всегда ли хорошо быть покладистой? Может быть, пора вспомнить, что собиралась сделать ты сама? Для чтения взрослыми детям.', 'Sometimes everyone tries to tell you what to do. Shy Little Hedgehog finds herself in just that pickle: feeling bewildered and intimidated, she tries to follow all the conflicting advice she hears. But can you really please everyone, and is it always best to be agreeable? Perhaps it''s time to remember what you wanted to do in the first place.', 'Ponekad se čini da svi oko nas znaju najbolje šta bi trebalo da radimo. Stidljiva mala Ježica našla se u vrtlogu oprečnih savjeta: zbunjena je i uplašena dok pokušava da posluša baš svakoga. No, da li je uvijek dobro povlađivati drugima i nije li vrijeme da se sjeti šta je zapravo sama željela?', 'Мудрая и невероятно трогательная сказка о том, как научиться слышать собственный голос посреди океана чужих советов.', 'A wise and wonderfully cozy tale about learning to trust your own inner voice amidst a flurry of well-meaning advice.', 'Mudra i nježna priča koja podsjeća male i velike koliko je važno vjerovati sebi pored tolikih tuđih savjeta.', '/covers/DP-1096.webp', '#633c57', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["animals","friends"]', '["hedgehogs","confidence","nature","growing up","forest tales"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('день-рождения-1097', 'DP-1097', 'День рождения', 'Birthday', 'Rođendan', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Ульрика Кестере', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Дети хотят скорей повзрослеть. А взрослые - снова помолодеть. Правда, странно? Даже немного глупо. Такая уж штука - День рождения. Ждешь его или нет - он все равно наступит. И так - каждый год. Пока что никому не удалось это изменить. День рождения - твой личный праздник, маленький или большой. Как ты его отметишь? Устроишь настоящий трам-тарарам? Или захочешь побыть в тишине и спокойствии? А может, ни то ни другое? Никто не знает, кроме тебя!', 'Children can''t wait to grow up, while grown-ups wish they could be young again. Strange, isn''t it? Even a little silly. That''s just how birthdays work: whether you wait for it or not, it will arrive anyway, year after year. A birthday is your very own celebration, big or small. How will you spend it? Throw a wildly noisy party, or enjoy peaceful quiet? Nobody knows except you!', 'Djeca jedva čekaju da odrastu, dok odrasli žele ponovo da se podmlade. Čudno, zar ne? Čak pomalo i blesavo. To je ta stvar sa rođendanom: čekao ga ti ili ne, on će svakako doći svake godine. Rođendan je tvoj lični praznik, bio on mali ili veliki. Kako ćeš ga proslaviti? Napraviti pravi urnebes ili uživati u miru i tišini? Niko ne zna osim tebe!', 'Мудрая и уютная книга о том, что взрослеть совсем не страшно, а свой личный праздник можно отмечать именно так, как хочется тебе!', 'A cozy, thoughtful book showing that growing older isn''t scary at all, and your special day is yours to celebrate however you please!', 'Topla i mudra knjiga koja te podsjeća da odrastanje uopšte nije strašno i da svoj poseban dan možeš proslaviti baš onako kako ti želiš!', '/covers/DP-1097.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["real","funny"]', '["birthdays","growing up","celebration","traditions","self-reflection"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-кончается-печенье-1098', 'DP-1098', 'Когда кончается печенье', 'When the Cookies Run Out', 'Kad ponestane keksića', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Дома у песика Пелле и кошечки Лолло настоящий кавардак: вещи валяются тут и там, нигде не пройти. Кажется, пора навести порядок. Но чтобы были силы для уборки, нужно съесть чего-нибудь сладенького! В буфете не осталось ни конфетки, ни печенья. Как быть? Друзья отправляются на поиски сладостей и по дороге попадают в разные переделки.', 'Pelle the pup and Lollo the kitty have an absolute mess at home: clutter everywhere and nowhere to step! It seems high time to tidy up. But tidying up requires proper fuel—something sweet, of course! When they discover the pantry is utterly bare of cookies and candies, the two friends set off on an epic quest for treats, stumbling into all kinds of funny misadventures along the way.', 'U kući psića Pelea i mačkice Lolo vlada pravi pravcati haos: stvari su razbacane na sve strane i nigdje se ne može proći. Izgleda da je vrijeme za veliko spremanje. Ali za takav posao treba snage, tačnije nešto slatko! Međutim, u ormariću nema ni mrvice keksa ni bombona. Šta sad? Drugari kreću u potragu za poslasticama i usput upadaju u gomilu smiješnih nevolja.', 'Знакомая история: чтобы начать генеральную уборку, срочно требуется подкрепиться печеньем, а его поиски могут обернуться грандиозным приключением!', 'A wonderfully relatable tale: you can''t possibly clean your room without a sweet snack first, even if finding one turns into a wild expedition!', 'Dobro poznata priča: niko ne može početi sa spremanjem sobe bez slatkiša, čak i ako potraga za keksom preraste u pravu ekspediciju!', '/covers/DP-1098.webp', '#d48c46', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["funny","animals","adventure"]', '["cats and dogs","sweets","cleaning","friendship","misadventures"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('комар-спасатель-1099', 'DP-1099', 'Комар-спасатель', 'Mosquito the Rescuer', 'Komar spasitelj', 'Софи Геррив', 'Sophie Guerrive', 'Sofi Geriv', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Игра-путешествие, в которой читателю предстоит составить компанию знаменитому динозавру-спасателю по имени Комар. На борту своего самолета-трансформера Комар отправляется в путь и находит пропавших людей, животных и потерянные предметы. Ни переполненный музей, ни девственный лес, ни подземный город с тысячей и одной пещерой не ускользнут от его орлиного глаза! Особенно, если ему поможет читатель! Полные мельчайших деталей иллюстрации Софи Геррив будут с интересом рассматривать и дети, и взрослые: художница спрятала среди персонажей и пейзажей множество остроумных отсылок к известным героям и символам из мира кино и литературы. Но вот, вы добрались до конца книги... И выясняется, что не все тайны раскрыты! Комар-Спасатель с жужжанием спешит на подвиги, а мы начинаем снова рассматривать книгу с еще большим интересом! Для младшего школьного возраста.', 'Hop aboard a magical shape-shifting plane with Komar, the bravest dinosaur rescuer around! Packed with intricate details and witty cultural Easter eggs, this seek-and-find adventure takes readers through bustling museums, lush primeval forests, and secret underground caverns to locate lost travelers, curious creatures, and misplaced treasures. Just when you think every secret is found, the story turns around and invites you to look even closer.', 'Ukrcajte se u čudesni avion-transformer sa Komarom, najhrabrijim dinosaurusom-spasiocem na svijetu! Ova interaktivna avantura traženja i pronalaženja vodi čitaoce kroz prepune muzeje, praistorijske šume i podzemne lavirinte u potrazi za izgubljenim ljudima, životinjama i zaboravljenim blagom. Prepuna duhovitih detalja i skrivenih referenci za male i velike detektive, ova knjiga se nikada ne zatvara poslije samo jednog čitanja.', 'Вооружитесь лупой и чувством юмора: этот динозавр на самолёте-трансформере затянет в поиски и детей, и взрослых на целые часы!', 'Grab your detective eyes and a sense of wonder—this dinosaur flying a transforming plane will have the whole family hooked for hours!', 'Naoružajte se lupom i radoznalošću: ovaj dinosaurus u avionu-transformeru prikovaće pažnju i djece i roditelja satima!', '/covers/DP-1099.webp', '#e68a35', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["adventure","funny","animals"]', '["seek-and-find","dinosaurs","wimmelbuch","adventure","puzzles"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пир-у-царя-зверей-1100', 'DP-1100', 'Пир у царя зверей', 'The Feast of the King of Beasts', 'Gozba kod cara životinja', 'Сибил фон Олферс', 'Sibylle von Olfers', 'Sibila fon Olfers', '', 'Рипол КИТ', NULL, NULL, 6, 16, 'middle', 'Книга "Пир у царя зверей" рассказывает о шутливом соревновании зверей, которые стремятся угодить своему повелителю Льву и угостить его лучше всех. Автор книги - Сибилл фон Олферс, известный иллюстратор и писатель начала ХХ века, отразила в своих произведениях трепетную душу ребенка. Ее имя стоит в одном ряду с Эльзой Бесков, Кейт Гринуэй, Иваном Билибиным и другими художниками и писателями начала века.', 'The Feast of the King of Beasts tells the playful story of woodland creatures competing to prepare the most magnificent treats for their royal ruler, the Lion. Illustrated by Sibylle von Olfers, a master of early 20th-century children''s literature alongside Elsa Beskow and Kate Greenaway, this enchanting vintage tale captures the gentle magic and wonder of childhood.', 'Knjiga „Gozba kod cara životinja“ donosi šaljivu priču o šumskim stvorenjima koja se nadmeću ko će pripremiti najljepšu gozbu za svog vladara Lava. Autorka Sibila fon Olfers, slavna ilustratorka s početka 20. vijeka čije ime stoji rame uz rame s Elzom Beskov i Kejt Grinvej, stvorila je bezvremensku slikovnicu punu topline, nježnosti i vintage šarma.', 'Изысканная классика стиля модерн о том, как лесные жители устроили самый забавный кулинарный поединок для грозного, но голодного льва!', 'A charming Art Nouveau classic where woodland creatures stage a delightful culinary showdown to win the Lion King''s royal favor!', 'Predivna klasična priča u stilu secesije o šumskim životinjama koje priređuju najsmješnije kulinarsko takmičenje za gladnog kralja Lava!', '/covers/DP-1100.webp', '#c68b39', 'nonfiction', 'ru', 'available', 'Для младшего школьного возраста.', '["animals","funny","magic"]', '["classic tales","animals","vintage illustration","nature","feast"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-дед-мороз-путешеству-1101', 'DP-1101', 'Маленький Дед Мороз путешествует вокруг света', 'Little Santa Travels Around the World', 'Mali Djed Mraz putuje oko svijeta', 'Ану Штонер', 'Anu Stohner', 'Anu Štoner', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'На Севере, в деревеньке Дедов Морозов, всё идёт как обычно: накануне Нового года Деды Морозы готовятся к большому путешествию... Но утром в день отъезда деревня оказывается опустевшей: на улочках ни души, светятся только окна больницы... "Новогодняя лихорадка!" - объясняет Доктор. "Кто же теперь развезёт подарки детям?!" - сокрушается Главный Дед Мороз. Кажется, у Маленького Деда Мороза есть идея...', 'Up North in the village of Santas, holiday preparations are in full swing until a sudden outbreak of ''New Year fever'' sends all the grown-up Santas straight to the hospital. Who will deliver presents to children around the world now? It looks like Little Santa and his trusty animal friends have a brilliant rescue plan!', 'Na dalekom Sjeveru, u selu Djedova Mrazova, sve je spremno za praznično putovanje — dok iznenadna „novogodišnja groznica“ ne pošalje sve odrasle pravo u bolničke krevete! Ko će sada podijeliti poklone djeci širom planete? Izgleda da Mali Djed Mraz ima sjajnu ideju...', 'Трогательное доказательство того, что даже самый крошечный Дед Мороз с верными лесными друзьями способен спасти праздник для всей планеты!', 'Heartwarming proof that even the tiniest Santa, backed by loyal animal friends, can save the holidays for the whole world!', 'Dirljiv dokaz da čak i najmanji Djed Mraz, uz vjerne šumske prijatelje, može spasiti praznike za čitavu planetu!', '/covers/DP-1101.webp', '#244b7a', 'nonfiction', 'ru', 'available', 'Для дошкольного возраста.', '["magic","adventure","animals"]', '["winter","new year","santa claus","animals","holidays"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-дед-мороз-едет-в-гор-1102', 'DP-1102', 'Маленький Дед Мороз едет в город', 'Little Santa Goes to the City', 'Mali Deda Mraz ide u grad', 'Ану Штонер', 'Anu Stohner', 'Anu Štoner', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Маленький Дед Мороз вместе со взрослыми Дедами Морозами живёт в деревеньке далеко на Севере. Он тоже украшает ёлку, печёт печенье и готовит подарки. Только дарит он их не детям, а лесным зверям. Но вот незадача: вдруг оказывается, в городе есть звери - и они тоже хотят получать подарки! Что же делать Маленькому Деду Морозу? Он спешит к Главному Деду Морозу - у того всегда совет наготове! "Ну а мы что можем поделать? - ворчит тот в свою длинную бороду. - Город далеко, ты маленький и сам не доберёшься. А в санях у больших Дедов Морозов подарки для детей едва умещаются". До города и правда очень далеко, а все олени нужна большим Дедам Морозам. Неужели городские звери снова останутся без подарков?', 'Little Santa Claus lives far away in the snowy North among all the grown-up Santas. He bakes cookies, decorates trees, and prepares gifts—not for human children, but for forest creatures. One day, he learns a surprising truth: animals live in cities too, and they never get any Christmas presents! The Chief Santa insists the city is too far and there are no spare reindeer or sled room for a little Santa. But when you have a big, determined heart, no distance is too far to deliver holiday magic to overlooked four-legged friends.', 'Mali Deda Mraz živi u selu daleko na sjeveru sa velikim Deda Mrazevima. On takođe ukrašava jelku, peče kolačiće i sprema poklone, samo što ih ne nosi djeci, već šumskim životinjama. Odjednom saznaje da životinje žive i u gradu — i da i one sanjaju o poklonima! Glavni Deda Mraz tvrdi da je grad predaleko, a da za Malog Deda Mraza nema mjesta u saonicama. Zar će gradske životinje zaista ostati bez novogodišnje čarolije?', 'Даже если ты самый крошечный Дед Мороз на свете, твоё доброе сердце непременно найдёт дорогу к тем, кто больше всего ждёт праздника!', 'Even the tiniest Santa has a heart big enough to brave a snowy journey for the city critters who need Christmas magic most!', 'Čak i najmanji Deda Mraz ima dovoljno veliko srce da pređe sav snijeg svijeta kako nijedna životinja u gradu ne bi ostala bez praznika!', '/covers/DP-1102.webp', '#2c5282', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["magic","animals","friends"]', '["christmas","winter","animals","kindness","presents"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ночной-цирк-1103', 'DP-1103', 'Ночной цирк', 'Circus Night', 'Noćni cirkus', 'Матиас де Леу', 'Mattias De Leeuw', 'Matijas De Lev', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Жила-была девочка. Она мечтала о цирке: училась жонглировать мячиками, крутить обручи и даже дрессировать игрушечных зверей. Однажды ночью она оказалась в цирке-шапито с самыми настоящими жонглерами, укротителями, фокусниками и силачами. И сама стала участницей настоящего циркового представления... История о заветной детской мечте, рассказанная без единого слова, будет понятна всем, и детям, и взрослым.', 'Once upon a time, a little girl dreamed of the circus: she practiced juggling balls, twirling hoops, and even training her stuffed animals. One night, she wanders into a magical big top filled with real acrobats, jugglers, animal tamers, and strongmen—and steps straight into the spotlight of a dazzling midnight show. Told entirely without words, this poetic visual story speaks directly to the dreamer in readers of all ages.', 'Bila jednom jedna djevojčica koja je sanjala o cirkusu: vježbala je žongliranje lopticama, vrtjela obruče i dresirala svoje plišane igračke. Jedne noći našla se pod pravom cirkuskom šatrom među krotiteljima, mađioničarima i akrobatama — i sama postala zvijezda čarobne predstave. Ova topla priča o ostvarenju snova ispričana je bez ijedne riječi i očaraće podjednako i djecu i odrasle.', 'Завораживающая книга без слов, где под куполом ночного цирка детская мечта взмывает прямо под самые звёзды!', 'A breathtaking wordless picture book where a child''s dream takes flight straight under the starry big-top tent!', 'Čarobna slikovnica bez ijedne riječi u kojoj se dječiji snovi vinuti pod sami zvjezdani cirkuski šator!', '/covers/DP-1103.webp', '#1c2438', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["magic","adventure"]', '["circus","wordless book","dreams","acrobatics","night"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лев-в-библиотеке-1104', 'DP-1104', 'Лев в библиотеке', 'Library Lion', 'Lav u biblioteci', 'Мишель Кнудсен', 'Michelle Knudsen', 'Mišel Knudsen', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Заведующая библиотекой мисс Мерривезер очень трепетно относится к правилам. Бегать нельзя. Кричать нельзя. А когда однажды в библиотеку приходит настоящий лев, она не знает, что делать, ведь в правилах ничего об этом не сказано! Но оказывается, что лев - находка для библиотеки: его лапы тихо ступают по полу, на него, как на большой мягкий диван, усаживаются дети, когда слушают сказки. И даже когда ему приходится нарушить сразу несколько правил, мисс Мерривезер не злится. Потому что это особый случай!', 'Miss Merriweather, the head librarian, is very strict about rules: no running, and absolutely no shouting! But when a real lion unexpectedly strolls into the library, nobody knows what to do, because there are no rules about lions. Soon enough, the gentle beast becomes the library''s greatest asset—he dusts books with his tail and lets children lean against his warm fur during story hour. And when he is forced to break the rules, Miss Merriweather learns that sometimes there are very good reasons to make an exception.', 'Gospođica Meriveder, stroga upravnica biblioteke, drži se pravila kao svetinje: nema trčanja i nema vike! Ali kada jednog dana u biblioteku ušeta pravi lav, niko ne zna šta da radi, jer u pravilniku ne piše ništa o lavovima. Ubrzo se ispostavlja da je lav divan pomoćnik: repom briše prašinu sa polica i služi kao najudobniji naslon za djecu tokom čitanja bajki. Čak i kada prekrši pravila, gospođica Meriveder shvata da za to ponekad postoji najplemenitiji razlog.', 'Добрая и пушистая история о том, что даже самые строгие правила иногда можно нарушить — особенно ради настоящей дружбы!', 'A heartwarming, cozy classic proving that sometimes even the strictest rules can be broken — especially for a friend!', 'Topla i čupava priča o tome da se čak i najstroža pravila ponekad mogu prekršiti — naročito zbog pravog prijateljstva!', '/covers/DP-1104.webp', '#d99b43', 'nonfiction', 'ru', 'available', 'Для детей младшего школьного возраста.', '["animals","friends"]', '["library","lion","friendship","rules","kindness"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-о-любви-1105', 'DP-1105', 'Книга о любви', 'The Love Book', 'Knjiga o ljubavi', 'Пернилла Стальфельт', 'Pernilla Stalfelt', 'Pernila Stalfelt', '', 'Мир детства', NULL, NULL, 6, 16, 'middle', '"Однажды, хочешь - верь, хочешь - не верь, Амур найдет тебя и постучится в дверь. Стрела его пронзит твою грудную клетку. Закружит голову и свалит в табуретки. Любовь слепа, как говорится. Но ничему живому от нее не скрыться".', 'One day, believe it or not, Cupid will find you and knock at your door. An arrow will pierce your chest, make your head spin, and knock you right off your chair. Love is blind, as they say, but no living creature can hide from it.', 'Jednog dana, vjerovali ili ne, Kupidon će vas pronaći i pokucati na vaša vrata. Njegova strijela će vam probosti grudi, zavrtjeće vam se u glavi i srušiti vas sa stolice. Ljubav je slijepa, kako kažu, ali se nijedno živo biće od nje ne može sakriti.', 'Остроумная, смелая и невероятно добрая шведская энциклопедия чувств для тех, кто хочет понять, откуда берутся бабочки в животе и почему любовь кружит голову.', 'A brilliantly quirky, honest, and warm Swedish guide to deciphering butterflies in your stomach and understanding why love makes the world spin.', 'Duhovit, iskren i nevjerovatno topao švedski vodič kroz leptiriće u stomaku koji objašnjava zašto nam ljubav zavrti pamet.', '/covers/DP-1105.webp', '#e63946', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["funny","real"]', '["любовь","чувства","шведская литература","психология","юмор"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-о-смерти-1106', 'DP-1106', 'Книга о смерти', 'The Death Book', 'Knjiga o smrti', 'Пернилла Стальфельт', 'Pernilla Stalfelt', 'Pernila Stalfelt', '', 'Мир детства', NULL, NULL, 6, 16, 'middle', 'От жизни люди умирают. Звери - тоже. Даже морская свинка вечно жить не может, Хотя, наверное, хотела бы. Увы. В виде букета загибаются цветы, Червяк обычно погибает на крючке, Комар - на лбу, а бабочка - в сачке. И, вспоминая про былое, Больной старик мечтает о покое И думает о тех, кого с ним больше нет, И о количестве прошедших зим и лет. Зима всегда сменяет лето, А после жизни наступает смерть, но это Совсем не страшно, потому что Без смерти жизнь была бы скучной', 'People die, animals die, and even flowers in a vase eventually wither away. Swedish author and illustrator Pernilla Stalfelt talks about one of life''s greatest mysteries with honest curiosity, gentle warmth, and a healthy dose of humor. This candid illustrated guide answers big questions about funerals, memories, and what might happen next, helping readers realize that dying is simply a natural part of living.', 'Ljudi umiru, životinje takođe, pa čak i cvijeće u vazi na kraju uvene. Švedska autorka Pernila Stalfelt pristupa jednoj od najvećih životnih tajni sa iskrenom radoznalošću, toplinom i dozom duhovitosti. Ova iskrena slikovnica odgovara na velika pitanja o sahranama, sjećanjima i onome što dolazi poslije, podsjećajući nas da je smrt jednostavno prirodan dio života.', 'Мудрая, бережная и поразительно честная книга с забавными картинками, которая помогает говорить о самом сложном без паники и слёз.', 'A wise, gentle, and refreshingly honest illustrated guide that helps kids and grown-ups talk about life''s biggest mystery without fear.', 'Mudra, nježna i nevjerovatno iskrena slikovnica koja pomaže djeci i roditeljima da o najtežoj temi razgovaraju bez straha i tabua.', '/covers/DP-1106.webp', '#c49a45', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["real","funny"]', '["death","philosophy","emotions","life cycle","growing up"]', 1792836322701, 1792845711160);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('одного-поля-ягоды-1107', 'DP-1107', 'Одного поля ягоды', 'Birds of a Feather', 'Svi smo mi jednaki', 'Пернилла Стальфельт', 'Pernilla Stalfelt', 'Pernila Stalfelt', '', 'Мир детства', NULL, NULL, 6, 16, 'middle', 'Все дети имеют равные права и одинаково достойны любви. Все дети имеют право выражать свое мнение. Дети имеют право рассчитывать на серьезное отношение и понимание со стороны взрослых... В этой книге авторы на примере различных жизненных ситуаций, проиллюстрированных цветными картинками, учат детей быть терпимыми к людям других национальностей, уважать чувства других людей, правильно вести себя со своими сверстниками.', 'All children have equal rights and deserve love, respect, and to have their voices heard. Through playful, candid illustrations and relatable everyday scenarios, Swedish author Pernilla Stalfelt explores diversity, tolerance, and human rights in a way that is easy, frank, and engaging for young minds.', 'Sva djeca imaju jednaka prava i podjednako zaslužuju ljubav, razumijevanje i priliku da kažu svoje mišljenje. Kroz duhovite i iskrene ilustracije i životne primjere, švedska autorka Pernila Stalfelt uči najmlađe toleranciji, uvažavanju različitosti i poštovanju drugih.', 'Серьёзный разговор о правах человека и равенстве, рассказанный с фирменным шведским юмором и абсолютным уважением к юному читателю.', 'A warm and delightfully frank guide to equality and empathy, tackling big questions about rights with signature Swedish humor.', 'Važan i topao razgovor o jednakosti i dječjim pravima, ispričan sa prepoznatljivim švedskim humorom i bez popovanja.', '/covers/DP-1107.webp', '#e0533c', 'nonfiction', 'ru', 'available', 'Для чтения взрослыми детям.', '["real","friends","funny"]', '["equality","tolerance","human rights","diversity","empathy"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('война-1108', 'DP-1108', 'Война', 'War', 'Rat', 'Леттриа', 'José Jorge Letria and André Letria', 'Žoze Žorž Letrija i Andre Letrija', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Книга о войне, рассказанная отцом и сыном. Поэзия иллюстраций и текста. Она приходит внезапно, как болезнь. Она не видит, не слышит, не чувствует. Она гнетёт, давит, заставляет молчать. За ней остаются лишь руины и мёртвая тишина. Война — самое страшное и самое живучее изобретение человечества. «Война» получила признание критиков всего мира и снискала множество литературных премий. На момент выхода книги на русском языке она издана на 12 языках и собрала уже больше 10 наград. Получила награду выставки в Болонье, а также Little Hakka, Portuguese Illustration Prize, NY Rights Fair Talking Pictures Award, и многие другие.', 'A profound book about war created by a father and son through poetic text and striking illustrations. War arrives abruptly like an illness—blind, deaf, and unfeeling. It crushes spirits, enforces silence, and leaves behind only ruins and chilling stillness. Acclaimed globally and honored with numerous awards, including accolades from the Bologna Children''s Book Fair and the Portuguese Illustration Prize, this masterpiece offers a solemn and necessary conversation about humanity''s darkest creation.', 'Duboka i snažna knjiga o ratu, stvorena zajedničkim radom oca i sina kroz poetski tekst i upečatljive ilustracije. Rat dolazi iznenada, poput bolesti — slijep, gluv i bezosjećajan. Guši, pritiska i prisiljava na ćutanje, ostavljajući za sobom samo ruševine i zlokobnu tišinu. Ova višestruko nagrađivana slikovnica otvara važan i hrabar razgovor o najstrašnijem izumu čovječanstva.', 'Мощная и поэтичная притча о разрушительной силе войны, говорящая с читателем любого возраста на языке невероятных иллюстраций.', 'A hauntingly poetic masterpiece that confronts the harsh realities of war through stark, unforgettable imagery.', 'Moćna i poetska priča koja se suočava sa surovošću rata kroz nezaboravne, dirljive ilustracije.', '/covers/DP-1108.webp', '#2c2f33', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["real"]', '["war","peace","allegory","picture book","award-winner"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('флон-флон-и-мюзетт-1109', 'DP-1109', 'Флон-Флон и Мюзетт', 'Flon-Flon and Musette', 'Flon-Flon i Muzet', '', 'Elzbieta', 'Elžbijeta', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Как разговаривать о войне с детьми? Ведь они с малых лет должны понимать, что война бессмысленна и люди сами выдумывают себе врагов. Благодаря этой простой, но глубокой истории о двух друзьях-зайчатах Флон-Флоне и Мюзетт, разлучённых войной, даже самые маленькие читатели поймут, как страшна и жестока любая война и как ценен мир. В выразительных иллюстрациях мягких пастельных тонов живой классик французской детской литературы, автор-иллюстратор польского происхождения Эльжбета сумела показать нежную дружбу героев, боль разлуки, силу надежды и любви, побеждающих страх и разрушение. «Война не умирает, сынок. Она лишь засыпает время от времени. И когда она спит, нужно быть очень осторожными, чтобы не разбудить её». «Самокат» перевел и подготовил на русском тексты и методики этих занятий и готов поделиться с ими с заинтересованными специалистами и родителями.', 'How do we talk to children about war? Through the gentle and profound story of two little rabbit friends, Flon-Flon and Musette, separated by sudden conflict, young readers discover the sorrow of division and the precious value of peace. Illustrated in soft, evocative pastels by classic author Elzbieta, this tender picture book speaks about friendship, enduring hope, and love that outlasts sorrow.', 'Kako razgovarati s djecom o ratu? Kroz nježnu i dirljivu priču o dva mala zeca prijatelja, Flon-Flonu i Muzet, koje je razdvojio rat, i najmlađi čitaoci mogu razumjeti besmisao sukoba i neprocjenjivu vrijednost mira. Uz tople pastelne ilustracije poznate autorke Elžbijete, ova slikovnica pruža utjehu, govoreći o prijateljstvu i nadi koje pobjeđuju strah.', 'Трогательная и бережная притча о двух зайчатах, которая находит самые правильные и нежные слова для разговора о мире и войне.', 'A tender and profound parable of two little rabbits that finds just the right, gentle words to talk about peace and war.', 'Dirljiva i nježna priča o dva zečića koja pronalazi prave, blage riječi za razgovor o miru i ratu.', '/covers/DP-1109.webp', '#8b9d83', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["friends","animals","real"]', '["war","peace","friendship","rabbits","picture book","empathy"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чемпион-1110', 'DP-1110', 'Чемпион', 'The Champion', 'Šampion', '', 'Farhad Hasanzadeh', 'Farhad Hasanzade', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'В чемпионской семье превыше всего ценятся сила и выносливость. Логично — без них будущему чемпиону не добыть ни спортивных званий, ни наград. Вот только Абтин не хочет их добывать. И не хочет становиться чемпионом. В руках у него тонкая кисточка, а в голове и в сердце — все краски мира. Но что может один против всех, один юный художник с тонкой кисточкой — против целого семейства чемпионов? Представьте, кое-что может – если найдёт в себе достаточно мужества и немножко смекалки.', 'In a family of champions, strength and endurance are valued above all else. Naturally, without them, a future champion cannot claim medals or athletic titles. But Abtin doesn''t care for trophies, nor does he wish to be a sports hero. Instead, his hands hold a delicate paintbrush, and his mind is full of vibrant colors. What chance does a young painter stand against an entire dynasty of athletes? As it turns out, quite a lot—with enough courage and a splash of wit.', 'U porodici šampiona snaga i izdržljivost se cijene više od svega. Jasno je — bez njih budući šampion ne može osvojiti medalje ni sportske titule. Međutim, Abtin uopšte ne želi da ih osvaja, niti želi da postane sportski as. U njegovoj ruci je tanka četkica, a u glavi i srcu sve boje svijeta. Šta može jedan mladi slikar protiv čitave loze šampiona? Pokazuje se da može mnogo — ako pronađe dovoljno hrabrosti i malo mudrosti.', 'Трогательная и вдохновляющая история о том, как остаться верным своей мечте, даже если вся твоя семья мечтает о золотых медалях!', 'A touching and inspiring tale about staying true to your art, even when your entire family is obsessed with gold medals!', 'Dirljiva i inspirativna priča o tome kako ostati vjeran svojoj umjetnosti, čak i kad čitava porodica sanja o zlatnim medaljama!', '/covers/DP-1110.webp', '#e05638', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["real"]', '["art","family","courage","individuality","sports"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('маленький-принц-ил-б-алеманья--1111', 'DP-1111', 'Маленький принц (ил. Б. Алеманья)', 'The Little Prince (illus. by Beatrice Alemagna)', 'Mali princ (il. Beatriče Alemanja)', '', 'Antoine de Saint-Exupéry', 'Antoan de Sent Egziperi', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Издание в твёрдом переплете. Плотная бумага, чёткий, удобный для чтения шрифт. Цветные иллюстрации. Знаменитая книга Антуана де Сент-Экзюпери «Маленький принц» переведена более чем на 300 языков мира. Миллионы её поклонников повторяют знаменитые слова: «Ты навсегда в ответе за тех, кого приручил», «Встал поутру, умылся, привёл себя в порядок — и сразу же приведи в порядок свою планету», «Но ведь нет таких магазинов, где торговали бы друзьями, и потому люди больше не имеют друзей». Трогательная философская сказка рассказала людям о жизни так просто и понятно, что сама стала частью жизни. Среди десятков именитых художников, создававших образы героев книги, нельзя не отметить французского иллюстратора итальянского происхождения Беатриче Алеманья. Лауреат более 10 международных премий и конкурсов, автор 15 иллюстрированных альбомов и 30 книг, Беатриче Алеманья уделяет особое внимание чувствам и эмоциям персонажей. Возможно, поэтому её работы находят самый горячий отклик в детских сердцах. И как тут не вспомнить ещё одну знаменитую цитату из книги: «Зорко одно лишь сердце. Самого главного глазами не увидишь».', 'Antoine de Saint-Exupéry''s beloved classic The Little Prince comes alive in this exquisite hardcover edition featuring illustrations by internationally acclaimed artist Beatrice Alemagna. A touching philosophical fairy tale translated into over 300 languages, it reminds readers young and old that one sees clearly only with the heart, and that what is essential is invisible to the eye.', 'Čuveni klasik Antoana de Sent Egziperija „Mali princ“ oživljava u ovom posebnom izdanju u tvrdom povezu sa očaravajućim ilustracijama nagrađivane umjetnice Beatriče Alemanje. Dirljiva filozofska bajka prevedena na više od 300 jezika podsjeća nas da samo srcem dobro vidimo i da je ono najvažnije očima nevidljivo.', 'Вечная история о дружбе, лисах и розах, в которой сквозь тёплые мазки Беатриче Алеманьи самое главное видно не только сердцем, но и глазами!', 'A timeless tale of friendship, foxes, and roses, where Beatrice Alemagna''s poetic artwork makes the invisible wondrously visible!', 'Vječna priča o prijateljstvu, lisicama i ružama, u kojoj kroz magične poteze kista Beatriče Alemanje suštinu vidimo ne samo srcem, već i očima!', '/covers/DP-1111.webp', '#d49b3d', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["magic","friends","adventure"]', '["classic","friendship","stars","illustrated","philosophy"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('билет-для-зайца-1112', 'DP-1112', 'Билет для зайца', 'A Ticket for a Hare', 'Karta za zeca', '', 'Denis Kryukov', 'Denis Krjukov', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Юная блогер Аня — коренная москвичка, ее семья живет в столице с незапамятных времен. Но это не простая семья, а целая династия… зайцев! Все Анины родственники были сплошь замечательными ребятами и взрослыми. Но была у них одна удивительная особенность: не ладили они с городским транспортом. Норовили все проехать бесплатно! И не по злому умыслу, а как раз от своей замечательности, а также мечтательности и изобретательности. Но не волнуйтесь, все они исправились и перестали быть безбилетниками. И только Аня всегда исправно оплачивала проезд, потому что у нее была своя мечта — найти счастливый билетик. Книга-картинка с остроумными и нежными рассказами Дениса Крюкова и такими же иллюстрациями Полины Калашниковой знакомит детей не только с ушастыми горожанами, но и с историей развития городского транспорта и билетной системы c конца XIX века до наших дней. Книга «Билет для зайца» нарисована спиртовыми маркерами — любимым материалом художницы. Спиртовые маркеры напоминают Полине о детстве, которое она провела за рисованием фломастерами (от них не отрывало даже поедание супа). В отличии от фломзиков, маркеры позволяют работать с толщиной линии и цветовыми наложениями. «Маркеры почти не пачкаются, их можно везде взять с собой и в любой момент вытащить из рюкзака. Плюс они очень быстро позволяют зафиксировать идею. Мне важно, чтобы рука поспевала за ходом мысли. Или я за ходом руки. Не знаю, что в моем случае первостепенно».', 'Young blogger Anya comes from a long dynasty of Muscovite ''hares''—not just fluffy animals, but notorious fare dodgers who always dreamed up clever excuses not to pay for transit! Unlike her reformed relatives, Anya always buys a ticket because she dreams of catching a truly lucky one. Blending playful family lore with genuine transport history, this vibrant picture book takes readers on a journey through trams, buses, and subway tokens from the late 19th century to the modern day, delightfully illustrated with dynamic alcohol markers.', 'Mlada blogerka Anja potiče iz stare moskovske loze „zečeva“ — i to ne samo onih s dugim ušima, već pravih švercera u gradskom prevozu koji su uvijek izmišljali maštovite načine da putuju besplatno! Ipak, Anja marljivo kupuje svaku kartu jer sanja o tome da pronađe onu srećnu. Spajajući duhovite porodične anegdote i stvarnu istoriju gradskog prevoza i karata od kraja 19. vijeka do danas, ova razigrana slikovnica oslikana alkoholnim markerima pravo je uživanje za radoznale putnike.', 'Остроумная и красочная экскурсия по истории городского транспорта в компании обаятельного семейства самых настоящих зайцев-безбилетников!', 'A brilliantly witty, marker-drawn ride through the history of city transit with the most charming family of fare dodgers you''ll ever meet!', 'Duhovita i živopisna vožnja kroz istoriju gradskog prevoza u društvu najsimpatičnije porodice švercera na svijetu!', '/covers/DP-1112.webp', '#e05638', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["funny","real","animals"]', '["public transport","city history","picture book","humor","curiosity"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зачем-троллейбус-сбросил-рога--1113', 'DP-1113', 'Зачем троллейбус сбросил рога?', 'Why Did the Trolleybus Shed Its Horns?', 'Zašto je trolejbus odbacio rogove?', '', 'Unknown', 'Nepoznati autor', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Куда пропали московские троллейбусы? Они просто сбросили рога и превратились в электробусы! А произошло это благодаря одному весёлому синему троллейбусу, который мечтал увидеть весь мир, а не ездить каждый день по одинаковым маршрутам. Как и его лучший друг олень Бобка, троллейбус сбросил красивые, но большие и неудобные рога — ведь мечты и дружба стоят того, чтобы меняться. Совместная книга Музея транспорта Москвы и издательства А+А рассказывает историю троллейбусов, которые появились много лет назад в Германии и объехали весь мир, и раскрывает тайну: где и сегодня можно увидеть столичные троллейбусы.', 'Where did the city trolleybuses go? They simply shed their horns and turned into electric buses! It all happened thanks to one cheerful blue trolleybus who dreamed of seeing the whole world instead of circling the same route every day. Just like his best friend Bobka the deer, the trolleybus parted with his big, clumsy horns—because dreams and friendship are worth changing for. This joint project by the Moscow Transport Museum and A+A publishing tells the fascinating history of trolleybuses from their origins in Germany to their worldwide journeys, while revealing where you can still spot them today.', 'Gdje su nestali gradski trolejbusi? Jednostavno su odbacili svoje rogove i pretvorili se u električne autobuse! Sve je počelo zahvaljujući jednom veselom plavom trolejbusu koji je sanjao da vidi čitav svijet, umjesto da svaki dan kruži istom rutom. Baš poput svog najboljeg prijatelja, jelena Bobke, trolejbus je odbacio svoje glomazne rogove — jer snovi i prijateljstvo vrijede svake promjene. Ova knjiga, nastala u saradnji Muzeja transporta i izdavačke kuće A+A, otkriva istoriju trolejbusa od njihovog nastanka u Njemačkoj pa širom svijeta, otkrivajući tajnu gdje ih i danas možete sresti.', 'Удивительная и трогательная городская история о том, как старый добрый транспорт находит смелость меняться ради настоящей мечты.', 'A charming urban tale of technology, history, and the courage to shed old habits to chase your biggest dreams.', 'Šarmantna i topla priča o istoriji saobraćaja i hrabrosti da odbacimo stare navike kako bismo slijedili svoje snove.', '/covers/DP-1113.webp', '#1e70ba', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["real","friends","adventure"]', '["transport","trolleybuses","history","city","technology"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('звезда-1114', 'DP-1114', 'Звезда', 'The Star', 'Zvijezda', 'Десницкая Анна', 'Anna Desnitskaya', 'Ana Desnickaja', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Всем оставленным домам, всем переездам, вольным и невольным, посвящается. Надолго ли обретено спокойствие на новом месте? Неизвестно. Но твоя звезда всегда с тобой, где бы ты ни оказался, — и светит в окне.', 'Dedicated to all the homes left behind, and to every journey, voluntary or involuntary. Has true peace been found in this new place? Nobody knows for sure. But your guiding star remains with you wherever you go, shining gently through your window.', 'Posvećeno svim napuštenim domovima, svim selidbama, svojevoljnim i nevoljnim. Da li je mir na novom mjestu pronađen zauvijek? Ne zna se. Ali tvoja zvijezda je uvijek s tobom, gdje god da se nađeš — i sija na tvom prozoru.', 'Нежная и терапевтическая книга для каждого, кто однажды собирал чемодан и искал свой знакомый свет в чужом окне.', 'A tender, comforting picture book for anyone who has ever packed up their life and searched for a familiar glimmer in a strange new window.', 'Nježna i topla knjiga za svakoga ko se ikada selio i tražio poznato svjetlo kroz tuđi prozor.', '/covers/DP-1114.webp', '#25334a', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["real"]', '["moving","home","empathy","hope","family"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('на-краю-света-1115', 'DP-1115', 'На краю света', 'At the Edge of the World', 'Na kraju svijeta', 'Десницкая Анна', 'Anna Desnitskaya', 'Ana Desnickaja', 'Десницкая Анна', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Вера и Лукас растут на двух краях света. На Камчатке и в Чили жизнь очень разная, но тоскуют от одиночества везде похоже. И если настойчиво и долго посылать сигналы – то однажды может случиться чудо. Вечером мы с мамой выходим на берег океана. Я стою у воды и представляю – вот бы там, за краем света, у меня был друг. Я достаю фонарик из кармана куртки и свечу им в темноту над морем. Короткая вспышка, две длинных, потом снова короткая: точка-тире-тире-точка. Две точки, точка-тире-тире, точка, тире. На азбуке Морзе это означает: «привет». Я мигаю в темноту: «Привет, меня зовут Вера. Привет, меня зовут Вера»', 'Vera lives on the rugged coast of Kamchatka in Russia, while Lucas lives in a windy seaside town in Chile. Their everyday lives on opposite sides of the Pacific Ocean look completely different, yet the longing for a true friend feels the exact same. Every evening, they flash Morse code signals into the vast ocean dark, hoping someone across the waves will blink back.', 'Vera odrasta na divljim obalama Kamčatke, a Lukas u vjetrovitom gradiću u Čileu — na dva sasvim suprotna kraja svijeta. Život uz Pacifik na tim dalekim mjestima izgleda potpuno drugačije, ali je osjećaj usamljenosti i želja za prijateljstvom svuda isti. Svake večeri oni u tamu okeana šalju poruke Morzeovom azbukom, vjerujući da će neko sa druge obale odgovoriti.', 'Включите фонарик и загляните за горизонт: эта потрясающая книга-перевёртыш доказывает, что даже на краю земли ты не один, если умеешь светить навстречу другу.', 'Grab a flashlight and look across the ocean: this breathtaking flip-book proves that even on the furthest edge of the earth, you are never truly alone if you know how to signal for a friend.', 'Upalite baterijsku lampu i pogledajte preko horizonta: ova predivna knjiga dokazuje da čak ni na kraju svijeta nijeste sami ako šaljete signale prijateljstva.', '/covers/DP-1115.webp', '#1e3d59', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["friends","real","adventure"]', '["friendship","morse code","kamchatka","chile","ocean","geography"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('слухи-в-империи-1116', 'DP-1116', 'Слухи в империи', 'Rumors in the Empire', 'Glasine u carstvu', 'Аксёнов Андрей', 'Andrey Aksyonov', 'Andrej Aksjonov', 'Катя Гущина', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Даже у самых смешных и абсурдных слухов есть бытовые корни. Зависть, способ объяснить неизвестное или хитрый инструмент управления — если тебе кто-то не нравится, самое время пустить про него неприятную сплетню! По крайней мере, так иногда поступали в Российской империи. До сих пор мы слышим удивительные истории, которые родились из сплетен. Только представьте, сколько всего обсуждали в то время, и как легко люди могли во всё это поверить! У иллюстратора Кати Гущиной и историка Андрея Аксёнова есть преимущество перед нашими предками — дистанция от той словесной суеты, которая позволяет спокойно восстановить историю, подтвердить или опровергнуть слухи о российских императорах от Петра I до Николая II. Но, несмотря на это, авторы напоминают нам о том, что все правители, ученые, писатели, полководцы и народ прошлых веков — это на самом деле всё ещё очень живое настоящее.', 'Even the most absurd and hilarious rumors have down-to-earth roots. Envy, attempts to explain the unknown, or a clever political weapon—if someone bothers you, it''s prime time to start a rumor! That was certainly how things worked in the Russian Empire. To this day, we hear wild legends that began as courtly gossip. Illustrator Katya Gushchina and historian Andrey Aksyonov take a witty, clear-eyed look across the centuries, confirming and debunking famous tales about tsars from Peter the Great to Nicholas II, and showing that historical figures were just as lively, flawed, and rumor-prone as we are today.', 'Čak i najapsurdnije i najsmješnije glasine imaju sasvim obične korijene. Zavist, potreba da se objasni nepoznato ili lukavo oruđe vlasti — ako ti se neko ne dopada, pravo je vrijeme da pustiš dobar trač! Tako se bar često radilo u Ruskom carstvu. Do danas slušamo nevjerovatne priče nastale iz običnih spletki. Ilustratorka Katja Guščina i istoričar Andrej Aksjonov duhovito i pronicljivo rekonstruišu istoriju, razotkrivajući glasine o carskim vladarima od Petra Velikog do Nikolaja II, podsjećajući nas da je prošlost bila itekako živa i puna uzbuđenja.', 'Оказывается, царские сплетни и фейк-ньюс прошлого увлекательнее любого детективного сериала!', 'Turns out royal gossip and historical fake news are far more gripping than any detective show!', 'Ispostavlja se da su carski tračevi i istorijske spletke uzbudljiviji od bilo koje detektivske serije!', '/covers/DP-1116.webp', '#b83b32', 'nonfiction', 'ru', 'available', 'Категория: Спокойной ночи, Веста-Линнея!', '["real","funny"]', '["history","gossip","tsars","humor","illustrated"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('франсуа-трюффо-мальчик-из-кино-1117', 'DP-1117', 'Франсуа Трюффо. Мальчик из кино', 'François Truffaut: The Boy of Cinema', 'Fransoa Trifo: Dječak iz bioskopa', 'Лука Тортолини', 'Luca Tortolini', 'Luka Tortolini', 'Виктория Семыкина', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Какое было детство у будущих знаменитостей? Что помогало им стать мастерами своего дела? Для кого-то этот путь был проще: его поддерживала семья. А Франсуа Трюффо, замечательный французский режиссер, самый молодой обладатель гран-при Каннского фестиваля, не был избалован любовью домашних. Его детство было полно разочарований и не очень радостных приключений. Но у него была настоящая страсть — кино, и она преображала действительность, создавала целый мир и дарила надежду. Эта книга о том, что, если делаешь то, что любишь, как бы ни было трудно, — ты будешь вознаграждён. В 2022 году Трюффо могло бы исполниться 90 лет. Многие знают его по дебютному фильму о детстве «400 ударов». Виктория Семыкина, мастер смешанных техник и киноман, нарисовала историю взросления Трюффо, заложив в книгу образы из его любимого кино. Искать их – отдельное удовольствие для взрослых. А для детей эта живописная книжка-картинка станет прекрасным примером того, что и тяжелое детство может преобразиться, если следовать за своей мечтой со всем упорством.', 'What was the childhood of future legends really like? For François Truffaut, the iconic French director and the youngest Cannes Grand Prix winner, growing up was far from easy or warm. Yet he found solace in an all-consuming passion: cinema, which transformed his reality and gave him hope. With gorgeous mixed-media illustrations by Victoria Semykina filled with subtle film tributes, this poetic picture book shows that pursuing your dreams with determination can outshine any hardship.', 'Kakvo je bilo djetinjstvo slavnih umjetnika? Fransoa Trifo, velikan francuskog filma i najmlađi dobitnik priznanja u Kanu, nije odrastao okružen porodičnom toplinom, ali je pronašao utočište u svojoj najvećoj strasti — bioskopu. Uz divne ilustracije Viktorije Semikine prepune skrivenih filmskih omaža, ova slikovnica pruža dirljiv dokaz da ljubav prema umjetnosti i istrajnost mogu pobijediti i najteže okolnosti odrastanja.', 'Вдохновляющая и невероятно живописная история о том, как мальчишеская любовь к экрану превратила одинокое детство в шедевры мирового кино.', 'An inspiring, deeply cinematic story showing how a lonely boy''s passion for the big screen turned a rough childhood into film history.', 'Inspirativna i čarobno vizuelna priča o tome kako je dječakova ljubav prema platnu pretvorila usamljeno djetinjstvo u remek-djela svjetskog filma.', '/covers/DP-1117.webp', '#2a4b63', 'nonfiction', 'ru', 'available', '6+', '["real","adventure"]', '["кино","биография","взросление","париж","мечта"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секреты-пластилина-1118', 'DP-1118', 'Секреты пластилина', 'The Secrets of Plasticine', 'Tajne plastelina', 'Рони Орен', 'Roni Oren', 'Roni Oren', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Во что может превратиться кусочек пластилина в руках ребенка? Это всегда талантливая и очень интересная импровизация. На занятиях Рони Орена малыши не просто играют, они думают, фантазируют, изобретают, реализуют свои творческие замыслы. Эта книга поможет вам правильно воспитать и лучше узнать своего ребенка. Дети с удовольствием будут делать фигурки разных животных; учиться смешивать цвета, экспериментировать, фантазировать и придумывать новые игрушки. Во время работы над котенком, петушком или черепахой ребенок сможет создать свой собственный мир - не виртуальный, как это принято в наши дни, а самый настоящий, сделанный своими собственными руками. Этот мир будет населен зверюшками, которые малыш без труда вылепит из пластилина с помощью одного очень важного секрета. Откройте этот секрет маленькому ученику!', 'What can a piece of clay turn into in the hands of a curious child? Renowned animator Roni Oren shares his simple, step-by-step method for bringing charming animals to life from plasticine balls and sausages. Perfect for sparking creative imagination and fine motor skills, this colorful guide helps kids build their very own tactile wonderland—one cheerful little creature at a time.', 'U šta se sve komadić plastelina može pretvoriti u dječjim rukama? Čuveni animator Roni Oren otkriva jednostavnu metodu kojom se korak po korak stvaraju preslatke životinje od običnih loptica i valjčića. Ovaj šareni priručnik podstiče maštu, razvija finu motoriku i uči djecu kako da stvore sopstveni opipljivi svijet prepun veselih stvorenja.', 'Вооружитесь пачкой пластилина — и всего за пару простых шагов ваш стол превратится в целый зоопарк обаятельных зверушек!', 'Grab a fresh box of modeling clay and watch your tabletop instantly turn into a lively zoo of charming critters!', 'Uzmite kutiju plastelina i u samo nekoliko jednostavnih koraka pretvorite radni sto u veseli zoološki vrt!', '/covers/DP-1118.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["animals","real"]', '["plasticine","crafts","creativity","animals","diy"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секреты-пластилина-динозавры-1119', 'DP-1119', 'Секреты пластилина Динозавры', 'Secrets of Clay: Dinosaurs', 'Tajne plastelina: Dinosaurusi', 'Рони Орен', 'Roni Oren', 'Roni Oren', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Автор книги Рони Орен известен в мире не только как талантливый мультипликатор, но и как блестящий педагог, имеющий многолетний опыт работы с детьми. Методика Рони Орена получила признание и широко используется в разных странах. Придуманные и созданные им яркие и неповторимые образы помогают детям осваивать искусство лепки, развивать мелкую моторику, речь и эстетический вкус. Пластилиновый мир и истории Рони Орена - это безграничные возможности развития детской фантазии и ее воплощения. Любознательные малыши с удовольствием отправятся в увлекательное путешествие и познакомятся с динозаврами. Они научатся экспериментировать, самостоятельно подбирать нужный цвет пластилина и легко работать с большим количеством деталей.', 'Renowned animator and educator Roni Oren reveals the wonders of clay modeling through the prehistoric world of dinosaurs. With his simple and proven step-by-step method, young makers learn to roll, shape, and blend colorful clay into vibrant jurassic creatures while developing fine motor skills, spatial imagination, and artistic confidence.', 'Poznati animator i pedagog Roni Oren otkriva čuda vajanja od plastelina kroz praistorijski svijet dinosaurusa. Koristeći njegovu jednostavnu metodu korak po korak, djeca uče kako da oblikuju i miješaju šareni plastelin stvarajući omiljena stvorenja, razvijajući finu motoriku, kreativnost i umjetnički osjećaj.', 'Кто сказал, что динозавры вымерли, если их можно запросто оживить из пары ярких пластилиновых шариков прямо за рабочим столом?', 'Who says dinosaurs are extinct when you can easily bring a whole prehistoric herd to life right on your kitchen table?', 'Ko kaže da su dinosaurusi izumrli, kada ih lako možete oživjeti od nekoliko šarenih loptica plastelina za radnim stolom?', '/covers/DP-1119.webp', '#4a934a', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["animals","real"]', '["dinosaurs","clay modeling","crafts","creativity","step-by-step"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('секреты-пластилина-новый-год-1120', 'DP-1120', 'Секреты пластилина Новый год', 'Secrets of Clay: New Year', 'Tajne plastelina: Nova godina', 'Рони Орен', 'Roni Oren', 'Roni Oren', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Автор книги Рони Орен известен в мире не только как талантливый мультипликатор, но и как блестящий педагог, имеющий многолетний опыт работы с детьми. Методика Рони Орена получила признание и широко используется в разных странах. Придуманные и созданные им яркие и неповторимые образы помогают детям легко осваивать искусство лепки, развивать мелкую моторику, речь и эстетический вкус. Пластилиновый мир и истории Рони Орена - это безграничные возможности развития детской фантазии и ее воплощения. На страницах этой книги маленькие читатели встретятся с Дедом Морозом, Снегурочкой и их друзьями, окунутся в веселую предпраздничную суету и сами сделают забавные новогодние подарки.', 'World-renowned animator and master educator Roni Oren reveals the joy of clay modeling in this festive holiday edition. Through his signature step-by-step method, young creators will learn to sculpt Father Frost, the Snow Maiden, cheerful winter animals, and homemade holiday gifts, developing fine motor skills and artistic imagination along the way.', 'Svjetski poznati animator i pedagog Roni Oren otkriva tajne modelovanja plastelinom u ovom prazničnom izdanju. Kroz njegovu jednostavnu tehniku korak po korak, djeca sa lakoćom mogu napraviti Deda Mraza, Snjeguročku, vesele zimske životinje i novogodišnje ukrase, razvijajući maštu i finu motoriku.', 'Разомните пальчики: с этой книгой даже обычный комочек пластилина превратится в волшебного Деда Мороза!', 'Warm up your hands—with Roni Oren’s joyful guide, a simple lump of clay turns into holiday magic in no time!', 'Zagrijte prstiće: uz ovu knjigu običan komad plastelina pretvara se u pravu novogodišnju čaroliju!', '/covers/DP-1120.webp', '#c82333', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["magic","animals"]', '["crafts","clay modeling","new year","winter","creativity"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пластилиновая-лаборатория-чево-1121', 'DP-1121', 'Пластилиновая лаборатория Чевостика', 'Chevostik''s Plasticine Laboratory', 'Čevostikova plastelinska laboratorija', 'Людмила Сеньшова', 'Lyudmila Senshova', 'Ljudmila Senjšova', 'Ольга Чтак', 'Миф', NULL, NULL, 6, 16, 'middle', 'Очень сложно объяснить ребёнку, как устроен атом или речная система, чем отличаются высококучевые облака от перисто-слоистых, или описать, как выглядят флаги Туниса или Ганы. Но еще труднее заинтересовать его этим. "Пластилиновая лаборатория Чевостика" - уникальная книга. Она не только расскажет ребёнку о сложных предметах и явлениях окружающего мира, но и доступным языком ответит на извечные детские "почемучки": почему горит лампочка? Почему звезды такие маленькие? Из чего мы сделаны? Как летает самолёт? Почему листья зелёные? Почему...? Почему...? Почему...? А ещё вовлечет его в процесс познания и изучения окружающего мира. Эта книга не учебник по лепке, это путеводитель по Вселенной: от атома до гигантских созвездий, от цветка до насекомых, от колеса до пожарной машины. И каждый элемент этой Вселенной ребёнок сможет создать собственными руками. Потребуется лишь пластилин и немного фантазии.', 'How does an atom work, why do planes fly, and what makes leaves green? Chevostik turns complex scientific concepts into hands-on discoveries using ordinary modeling clay! From river systems and cloud formations to cosmic constellations and fire engines, this interactive guide invites curious young minds to build models of the universe with their own hands—making science tactile, engaging, and unforgettable.', 'Kako funkcioniše atom, zašto avioni lete i zašto je lišće zeleno? Čevostik pretvara složene naučne koncepte u zabavna istraživanja pomoću običnog plastelina! Od riječnih tokova i vrsta oblaka do dalekih sazvježđa i vatrogasnih vozila, ovaj interaktivni vodič poziva male radoznalce da sopstvenim rukama izvajaju čitav univerzum i na opipljiv način shvate svijet oko sebe.', 'Слепленный своими руками атом запомнится куда лучше школьного учебника — разминайте пластилин и отправляйтесь в увлекательную научную лабораторию!', 'A clay atom sculpted with your own hands is far more memorable than any dry textbook diagram—warm up your plasticine and sculpt your way through science!', 'Atom koji sami izvajate pamti se mnogo bolje nego bilo koja slika u udžbeniku — ugrijte plastelin i krenite u zabavnu naučnu laboratoriju!', '/covers/DP-1121.webp', '#e65c00', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["real","adventure"]', '["science","clay modeling","experiments","crafts","curiosity"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пластилиновая-лаборатория-чево-1122', 'DP-1122', 'Пластилиновая лаборатория Чевостика 2', 'Chevostik''s Plasticine Laboratory 2', 'Čevostikova plastelinska laboratorija 2', 'Людмила Сеньшова', 'Lyudmila Senshova', 'Ljudmila Senjšova', 'Ольга Чтак', 'Миф', NULL, NULL, 6, 16, 'middle', 'Очень сложно объяснить ребёнку, как устроен атом или речная система, чем отличаются высококучевые облака от перисто-слоистых, или описать, как выглядят флаги Туниса или Ганы. Но еще труднее заинтересовать его этим. "Пластилиновая лаборатория Чевостика" - уникальная книга. Она не только расскажет ребёнку о сложных предметах и явлениях окружающего мира, но и доступным языком ответит на извечные детские "почемучки": почему горит лампочка? Почему звезды такие маленькие? Из чего мы сделаны? Как летает самолёт? Почему листья зелёные? Почему...? Почему...? Почему...? А ещё вовлечет его в процесс познания и изучения окружающего мира. Эта книга не учебник по лепке, это путеводитель по Вселенной: от атома до гигантских созвездий, от цветка до насекомых, от колеса до пожарной машины. И каждый элемент этой Вселенной ребёнок сможет создать собственными руками. Потребуется лишь пластилин и немного фантазии.', 'Explaining how an atom works, how river systems flow, or why leaves are green can be tricky—unless you sculpt them yourself! Chevostik''s Plasticine Laboratory turns complex scientific concepts into hands-on art projects. More than just a modeling guide, this book is an interactive expedition through the universe, allowing young explorers to discover biology, geography, and physics by shaping atoms, clouds, planets, and machines with their own hands.', 'Objasniti djetetu kako izgleda atom, zašto sija sijalica ili kako nastaju oblaci može biti pravi izazov — osim ako sve to ne napravite od plastelina! Čevostikova plastelinska laboratorija pretvara naučne zagonetke u kreativne poduhvate, vodeći mlade istraživače kroz tajne univerzuma, prirode i tehnike koje mogu doslovno oblikovati sopstvenim rukama uz malo mašte.', 'Зачем зубрить скучные правила, если можно слепить модель атома, самолёт или созвездие прямо за кухонным столом?', 'Why memorize dry science facts when you can roll up your sleeves and sculpt an atom, an airplane, or an entire constellation right at your kitchen table?', 'Zašto bubati suve činjenice kada možete zasukati rukave i sami izvajati atom, avion ili čitavo sazvježđe?', '/covers/DP-1122.webp', '#e2583e', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["real","adventure"]', '["пластилин","наука для детей","чевостик","творчество","энциклопедия"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чудный-поезд-мчится-в-сон-1123', 'DP-1123', 'Чудный поезд мчится в сон', 'Steam Train, Dream Train', 'Čudesni voz snova', 'Column 2', 'Sherri Duskey Rinker', 'Šeri Daski Rinker', 'Column 3', 'Карьера Пресс', 2014, '978-5-904946-69-2', 6, 16, 'middle', 'Чудесные стихи о паровозе сновидений. Полярные медведи, обезьяны и черепахи, слоны и жирафы помогают загрузить его вагоны необычными грузами, а потом отправляются на нем в сладкий сон. Авторы книги "Стройка баюшки-баю" - книги номер один по версии New York Times и так полюбившейся в России, выпустили вторую удивительную книгу - для чтения на ночь. Теперь мы укладываем спать поезд и его пассажиров! Для чтения взрослыми детям.', 'Night is falling, and a magical steam train pulls into the station! Polar bears, kangaroos, monkeys, and turtles load each car with playful cargo like giant balls, ice cream, and building blocks before tucking in for sweet dreams. Created by the bestselling team behind ''Goodnight, Goodnight, Construction Site'', this rhythmic and soothing bedtime tale is the ultimate sleepy journey for little dreamers.', 'Noć se polako spušta i čarobni parni voz stiže na peron! Polarni medvjedi, majmuni, kornjače i slonovi tovare vagone neobičnim teretom — od sladoleda do velikih lopti — a zatim se udobno smještaju za putovanje u carstvo snova. Od autora bestselera „Laku noć, gradilište”, stiže još jedna nježna i ritmična priča pred spavanje.', 'Загружайте в вагоны шарики и мороженое: этот уютный сонный экспресс мчит прямиком в самые сладкие сны!', 'Hop aboard the coziest night express as animal crews pack each train car before drifting off to dreamland!', 'Uskočite u najušuškaniji noćni ekspres dok životinje pakuju vagone i polako tonu u najslađe snove!', '/covers/DP-1123.webp', '#1f2a44', 'nonfiction', 'ru', 'available', 'Column 5', '["magic","animals"]', '["bedtime","trains","animals","poetry","sleep"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('14-лесных-мышей-зимний-день-1124', 'DP-1124', '14 лесных мышей Зимний день', '14 Forest Mice: Winter Day', '14 šumskih miševa: Zimski dan', 'Кадзуо Ивамура', 'Kazuo Iwamura', 'Kazuo Iwamura', '', 'Самокат', NULL, NULL, 6, 16, 'middle', '«14 лесных мышей» — очень популярная в Японии и многих европейских странах серия книг о красоте повседневности и о жизни трех поколений мышиного семейства: бабушки, дедушки, мамы, папы и еще десяток мышат. В книге «14 лесных мышей. Зимний день» уместился один уютный и радостный снежный день: пока за окном метель, мышата со старшими играют в настольные игры, мастерят и лакомятся. А когда буря стихает, можно отправиться кататься с горок на новеньких саночках и играть в снежки! Книги Кадзуо Ивамура напоминают миниатюрные кукольные домики, в которых хочется рассмотреть и потрогать каждую деталь, а каждое маленькое событие наполнено истинно японской философией и любованием жизнью в каждом ее моменте.', 'A widely cherished series across Japan and Europe, ''14 Forest Mice'' celebrates the beauty of everyday life through three generations of a mouse family. ''Winter Day'' captures a cozy, snowy day: while a blizzard sweeps outside, grandparents, parents, and ten little mice play board games, make crafts, and bake delicious treats together. Once the storm passes, they dash outside to test their brand-new sleds on sparkling slopes! Kazuo Iwamura''s delicate illustrations feel like stepping into an intricate dollhouse full of warmth, wonder, and mindful Japanese aesthetics.', 'Izuzetno popularan serijal u Japanu i širom Evrope, ''14 šumskih miševa'' slavi ljepotu svakodnevice kroz život tri generacije jedne mišje porodice. Slikovnica ''Zimski dan'' dočarava jedan topao i radostan dan pod snijegom: dok napolju vije mećava, miševi u toplom domu igraju društvene igre, majstorišu i uživaju u poslasticama. Čim se bura stiša, vrijeme je za grudvanje i spust novim sankama niz padinu! Raskošni crteži Kazua Ivamure podsjećaju na kućice za lutke u kojima poželite da istražite svaki detalj i osjetite mir svakog trenutka.', 'Заварите какао и приготовьтесь разглядывать крошечные мышиные варежки — эта невероятно уютная зимняя книга согреет всю семью!', 'Brew a cup of tea and marvel at the tiny mice mittens — this delightfully detailed winter story is pure family coziness.', 'Skuvajte topli čaj i zavirite u sićušni mišji dom — ova nevjerovatno topla zimska priča ugrijaće srce čitavoj porodici!', '/covers/DP-1124.webp', '#6a93b0', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["animals","friends"]', '["winter","mice","family","snow","cozy"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('что-делать-если-2-1125', 'DP-1125', 'Что делать если... 2', 'What to Do If... 2', 'Šta raditi ako... 2', 'Людмила Петрановская', 'Lyudmila Petranovskaya', 'Ljudmila Petranovska', '', '', NULL, NULL, 6, 16, 'middle', 'В новой книге известного психолога речь пойдёт о выборе, о принятии решений, об ответственности, о том, как важно уметь оценивать риски. Она станет умным собеседником для школьников и бесценным помощником для их родителей. Для детей младшего школьного возраста.', 'In this guide by a renowned child psychologist, young readers learn how to navigate tricky situations, make thoughtful choices, understand responsibility, and evaluate risks. It serves as an empowering companion for school-aged kids and an invaluable ally for parents.', 'U novoj knjizi poznate dječje psihološkinje govori se o donošenju odluka, odgovornosti i procjeni rizika u školi i svakodnevnom životu. Pametan saputnik za osnovce i dragocjen pomoćnik za njihove roditelje.', 'Ваш надёжный гид по выходу из школьных и жизненных передряг без паники и с включённой головой!', 'Your go-to emergency handbook for handling tough choices, school drama, and tricky situations with calm confidence!', 'Tvoj pouzdani vodič za rješavanje školskih i svakodnevnih dilema bez panike i sa samopouzdanjem!', '/covers/DP-1125.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["real","friends"]', '["life skills","safety","child psychology","growing up","emotions"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лето-в-деревне-1126', 'DP-1126', 'Лето в деревне', 'Summer in the Countryside', 'Ljeto na selu', 'Зина Сурова', 'Zina Surova', 'Zina Surova', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Лето - это свобода, яркие впечатления и наблюдения за природой. А где, как не в деревне, ты можешь по-настоящему почувствовать вкус лета? Здесь сладкая земляника, велосипеды, рыбалка, ночёвка под открытым небом, тарзанка, поход за грибами, яблоки из сада и много-много всего, что недоступно нам в городе. В этой книге вас ждет увлекательный и познавательный рассказ от лица одиннадцатилетнего мальчика - его впечатления от жизни в деревне и удивительная история о лете, полном игр, творчества и незабываемых приключений. Зина Сурова написала эту книгу на основе личных впечатлений: каждое лето она проводит с семьей в деревне.', 'Summer is all about freedom, vibrant discoveries, and reconnecting with nature—and where better to taste true summer than in the countryside? Filled with wild strawberries, bicycle rides, fishing, sleeping under starry skies, rope swings, and sweet orchard apples, this captivating book is narrated by an eleven-year-old boy. Based on author Zina Surova’s real family getaways, it is an inspiring guide to country life brimming with games, outdoor crafts, and unforgettable adventures.', 'Ljeto donosi slobodu, živopisne utiske i istraživanje prirode, a gdje se bolje osjeća pravi duh ljeta nego na selu? Ovdje vas čekaju slatke šumske jagode, vožnja biciklom, ribolov, noćenje pod vedrim nebom, branje pečuraka i mirisne jabuke iz voćnjaka. Ispričana iz ugla jedanaestogodišnjeg dječaka, ova topla i poučna knjiga prenosi doživljaje seoskog života pune igara, kreativnosti i avantura, inspirisana stvarnim ljetovanjima autorke Zine Surove i njene porodice.', 'Настоящая энциклопедия дачного детства, от которой так и веет ароматом спелой земляники, нагретой речки и безграничной свободы!', 'The ultimate recipe for an idyllic childhood summer, bursting with the scent of wild strawberries, river swims, and barefoot freedom!', 'Pravi priručnik za bezbrižno ljeto na selu, koji miriše na divlje jagode, kupanje u rijeci i dane pune slobode!', '/covers/DP-1126.webp', '#5b8c3b', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["adventure","real"]', '["summer","countryside","nature","childhood","outdoor activities"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('все-деньги-мира-1127', 'DP-1127', 'Все деньги мира', 'All the Money in the World', 'Sav novac svijeta', 'Виталий Константинов', 'Vitali Konstantinov', 'Vitali Konstantinov', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Для среднего и старшего школьного возраста Евро, доллар, йена, франк, рубль, фунт — деньги есть во всём мире. Но что такое «деньги» на самом деле? Монеты, купюры, счёт в банке? Кредитные карты и криптовалюта? Кто всё это придумал, когда и где? Действительно ли деньги правят миром и по каким законам? Как велась торговля до того, как появились деньги? Правда ли, что где деньги — там и обман, и несправедливость? Самое время найти ответ на все эти вопросы с помощью научно-популярного комикса и стать настоящим экспертом по истории денег. Виталий Константинов — иллюстратор, комиксист, писатель. Его работы изданы в 40 странах и удостоены многочисленных премий. Недавно его комикс «История письменности: от клинописи до эмодзи» вышла в нашем издательстве и сразу стала бестселлером. В новой книге вы познакомитесь с разными аспектами существования и использования денег. Это своего рода путеводитель по всемирной истории денежных отношений, который поможет разобраться в том, что действительно волнует всех: правда ли деньги правят миром. Вместе с Виталием Константиновым мы отправимся в занимательное и познавательное путешествие от каури к монетам, от первых банкнот к современным криптовалютам.', 'Euro, dollar, yen, pound, cowrie shells, and crypto: money takes countless shapes, but what is it truly? From ancient bartering and the first minted coins to modern banking and digital currencies, award-winning author and illustrator Vitali Konstantinov guides readers through the witty, fascinating, and sometimes shady history of world economics in this captivating graphic novel.', 'Euro, dolar, jen, školjke kauri i kriptovalute: novac poprima bezbroj oblika, ali šta je on zapravo? Od drevne trampe i prvih kovanica do savremenih banaka i digitalnog novca, nagrađivani autor i ilustrator Vitali Konstantinov vodi čitaoce kroz duhovitu i uzbudljivu istoriju svjetske ekonomije u ovom upečatljivom stripu.', 'Захватывающий графический гид, который остроумно и наглядно объяснит, откуда взялись монеты, почему бумажки имеют ценность и правит ли всем криптовалюта!', 'A brilliant and witty graphic guide that reveals where coins came from, why pieces of paper hold value, and whether crypto really rules the universe!', 'Sjajan i duhovit strip-vodič koji objašnjava kako su nastale prve kovanice, zašto papirići imaju vrijednost i da li kriptovalute zaista vladaju svijetom!', '/covers/DP-1127.webp', '#3a8459', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["real","adventure"]', '["comics","money","history","economics","graphic novel"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('богатые-и-бедные-1128', 'DP-1128', 'Богатые и бедные', 'Rich and Poor', 'Bogati i siromašni', 'Джерри Бейли', 'Gerry Bailey', 'Džeri Bejli', '', 'Мнемозина', NULL, NULL, 6, 16, 'middle', 'Книги серии "Деньги? Деньги… Деньги!" рассчитаны на детей среднего школьного возраста и в простой, увлекательной форме рассказывают о разных аспектах современной экономики. Книга "Богатые и бедные" посвящена главному социальному противоречию нашей эпохи - постоянно увеличивающемуся разрыву между богатством и нищетой. Рассматриваются такие вопросы, как возникновение и утрата огромных состояний, финансовый успех, деньги и личное счастье, перераспределение богатства, деятельность международных финансовых организаций, благотворительность, злоупотребление богатством.', 'Part of the insightful series on modern economics, this book tackles the stark divide between wealth and poverty in our world. Young readers will discover how fortunes are built and lost, whether money truly buys happiness, and how charities and global financial institutions work to redistribute wealth.', 'Kao dio poučne serije o savremenoj ekonomiji, ova knjiga istražuje sve veći jaz između bogatstva i siromaštva. Mladi čitaoci će saznati kako se stvaraju i gube velika bogatstva, da li novac zaista donosi sreću, te kako dobrotvorne i globalne finansijske organizacije pomažu u preraspodjeli novca.', 'Умный и честный разговор о деньгах, справедливости и о том, почему не всё на свете можно измерить купюрами.', 'A smart, honest look at wealth, fairness, and why the most valuable things in life can''t be bought with cash.', 'Pametan i iskren razgovor o novcu, pravdi i zašto se najvažnije stvari u životu ne mogu kupiti novcem.', '/covers/DP-1128.webp', '#2e7d32', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["real"]', '["economics","money","society","financial literacy","non-fiction"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('на-вес-золота-1129', 'DP-1129', 'На вес золота', 'Worth Its Weight in Gold', 'Suvo zlato', '', 'Unknown', 'Nepoznati autor', '', 'А+А', NULL, NULL, 6, 16, 'middle', 'Человечество с глубокой древности использовало для торговли и накопления богатства маленькие кусочки драгоценных металлов с надписями и рисунками. В последние годы, с появлением банковских карточек, приложений и прочих технологий, монетки всё реже звенят в наших карманах. Но всё то, что люди отчеканили за тысячелетия, никуда не исчезло: просто монеты из денег превратились в хранителей множества историй и ключи к прошлому. Эта книга предлагает посмотреть на всемирную историю через призму нумизматики — науки о монетах. Наш читатель не только научится понимать язык монет, перенесётся в далекие эпохи и государства, встретит великих правителей и мастеров, но, может быть, решится пополнить ряды нумизматов и начнёт собирать собственную коллекцию. Большие открытия начинаются с малого — иногда совсем крошечного металлического кружка.', 'Since ancient times, humankind has used small stamped pieces of precious metal for trade and wealth. In our digital age of cards and banking apps, coins jingle in our pockets far less often, but their legacy hasn''t vanished—they''ve transformed into time capsules and keys to the past. This book explores world history through numismatics, the science of coins. Young readers will learn to decipher the secrets minted onto ancient currency, travel through forgotten empires, meet historic rulers, and perhaps even start their very own coin collection.', 'Još od davnina čovječanstvo je za trgovinu i bogatstvo koristilo male komade plemenitih metala sa natpisima i slikama. Danas, uz kartice i aplikacije, kovanice sve rjeđe zveckaju u našim džepovima, ali one nijesu nestale — postale su čuvari fascinantnih priča i ključevi prošlosti. Ova knjiga nudi pogled na svjetsku istoriju kroz numizmatiku — nauku o novcu. Čitaoci će naučiti da razumiju jezik kovanica, proputovati drevne civilizacije i možda dobiti želju da pokrenu sopstvenu numizmatičku kolekciju.', 'Загляните в карманы истории: даже самый крошечный старинный кругляш может рассказать о царях, пиратах и великих империях больше любого учебника!', 'Peer into history''s treasure chest: even the tiniest ancient coin can tell more about emperors, trade, and pirate adventures than a giant textbook!', 'Zavirite u džepove istorije: čak i najmanji novčić može ispričati o carevima, gusarima i zaboravljenim carstvima više od bilo kog udžbenika!', '/covers/DP-1129.webp', '#c59b27', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["real","adventure"]', '["coins","history","money","numismatics","encyclopedia"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('спроси-у-папы-1130', 'DP-1130', 'Спроси у папы', 'Ask Dad', 'Pitaj tatu', 'Давид Кали', 'Davide Cali', 'Davide Kali', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Взрослые вечно говорят загадками: "Вырастешь - поймешь", "Не знаю, посмотрим", "Нельзя иметь все!"... А еще задают детям вопросы, хотя ответы их явно не интересуют. Почему так происходит и что на самом деле они хотят сказать? Эта книга поможет тебе разобраться.', 'Adults always speak in riddles: ''You''ll understand when you grow up,'' ''We''ll see,'' ''You can''t have everything!''... And they keep asking questions even when they clearly don''t care about the answers. Why does this happen, and what do they actually mean? This hilarious decoder will help you crack the secret language of grown-ups.', 'Odrasli vječito govore u zagonetkama: „Shvatićeš kad porasteš“, „Vidjećemo“, „Ne možeš imati sve!“... Uz to postavljaju djeci pitanja iako ih odgovori uopšte ne zanimaju. Zašto je to tako i šta zapravo žele da kažu? Ova duhovita knjiga pomoći će ti da konačno dešifruješ jezik odraslih.', 'Идеальный карманный разговорник для детей, мечтающих наконец расшифровать загадочный язык родителей и выведать правду!', 'The ultimate pocket phrasebook for kids ready to finally crack their parents'' secret code and discover what they really mean!', 'Savršen priručnik za djecu koja žele da konačno dešifruju zagonetni jezik svojih roditelja!', '/covers/DP-1130.webp', '#e86b43', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["funny","real"]', '["parents","family","humor","communication","growing up"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('малютка-лабан-привидение-из-ко-1131', 'DP-1131', 'Малютка Лабан, привидение из королевского замка', 'Little Ghost Laban, the Ghost from the Royal Castle', 'Mali duh Laban, sablast iz kraljevskog dvorca', '', 'Inger and Lasse Sandberg', 'Inger i Lase Sandberg', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Малютка Лабан - доброе привидение из замка Проснись-и-Пой. Его отец хочет, чтобы сын научился пугать людей и стал таким же жутким, как он. Но Лабан боится привидений, и ему не нравится темнота в королевском замке. И вот однажды ночью папа взял малютку с собой в ночной рейд. Семейство привидений из королевского замка уже более полувека пугает детей во всем мире. По книгам Ингер и Лассе Сандберг был снят популярный мультсериал, они переведены на 33 языка и являются вторыми по популярности в библиотеках Швеции.', 'Little Ghost Laban is a friendly ghost who lives in Castle Goodmorning Sun. His father is eager to teach him how to be genuinely terrifying, but there''s just one problem: Laban is terribly afraid of the dark! One night, Father Ghost takes little Laban on a midnight haunting tour. A beloved Swedish classic created by Inger and Lasse Sandberg, Laban’s heartwarming mishaps have enchanted generations of young readers worldwide.', 'Mali duh Laban je dobroćudna sablast iz dvorca Dobro Jutro. Njegov tata silno želi da ga nauči kako da pošteno plaši ljude, ali postoji mali problem: Laban se i sam boji mraka! Jedne noći, tata ga vodi na ponoćni pohod kroz kraljevski dvorac. Švedski klasici Inger i Lasea Sandberga o ovom neodoljivom duhiću već decenijama uveseljavaju djecu širom svijeta.', 'Идеальная сказка для тех, кто боится темноты: оказывается, маленькие привидения боятся её ничуть не меньше!', 'The sweetest cure for bedtime fears: proof that even little castle ghosts can be terrified of the dark!', 'Savršena priča za one koji se plaše mraka: ispostavilo se da se i mali dvorcijski duhovi plaše čudovišta!', '/covers/DP-1131.webp', '#3f546c', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["funny","spooky","magic"]', '["ghosts","castles","bedtime","fears","swedish literature"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('малютка-лабан-приключения-в-за-1132', 'DP-1132', 'Малютка Лабан, приключения в замке', 'Little Ghost Laban: Adventures in the Castle', 'Mali duh Laban: Avanture u dvorcu', '', 'Inger and Lasse Sandberg', 'Inger i Lase Sandberg', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Малютка Лабан, принц Скок и Лаболина знакомятся с Груффолиной, сражаются с уборочной машиной волшебника и помогают папе выполнять его нелегкую работу. Семейство привидений из королевского замка уже более полувека пугает детей во всем мире. По книгам Ингер и Лассе Сандберг был снят популярный мультсериал, они переведены на 33 языка и являются вторыми по популярности в библиотеках Швеции. Для дошкольного возраста.', 'Little Ghost Laban, Prince Mischief, and baby Labolina meet Gruffolina, tackle a wizard''s runaway cleaning machine, and help Ghost Dad with his spooky duties. For over half a century, this lovable ghost family from the royal castle has charmed readers worldwide. Created by Inger and Lasse Sandberg, these iconic Swedish bedtime tales have inspired a beloved animated series and been translated into 33 languages.', 'Mali duh Laban, princ Skok i Labolina upoznaju Grufolinu, bore se protiv čarobnjakove mašine za čišćenje i pomažu tati u njegovom poslu strašenja. Porodica duhova iz kraljevskog dvorca već više od pola vijeka oduševljava djecu širom svijeta. Ove švedske priče Inger i Lasea Sandberga pretočene su u čuveni crtani film i prevedene na 33 jezika.', 'Знакомьтесь с самым добрым в мире привидением, которое само побаивается темноты, но всегда готово к весёлым замковым проделкам!', 'Meet the world''s friendliest little ghost, who is secretly afraid of the dark but always ready for playful castle capers!', 'Upoznajte najnježnijeg duha na svijetu, koji se i sam boji mraka, ali nikada ne propušta veselu avanturu u dvorcu!', '/covers/DP-1132.webp', '#6b9ac4', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["funny","magic","spooky"]', '["ghosts","castle","scandinavian literature","friendship","bedtime stories"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('малютка-лабан-снова-рождество--1133', 'DP-1133', 'Малютка Лабан. Снова Рождество!', 'Little Ghost Laban: It''s Christmas Again!', 'Mali duh Laban: Opet Božić!', '', 'Inger and Lasse Sandberg', 'Inger i Lase Sandberg', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', 'Все уже решили, что подарят мамам и папам на Рождество, и только Лабан пока ничего не придумал. А он так хотел приготовить самый лучший подарок! Кто же ему поможет? Похоже, осталось надеяться лишь на чудо. И ночь перед Рождеством - как раз то время, когда чудеса случаются. Для дошкольного возраста.', 'Everyone in the castle already knows what they are giving their parents for Christmas, except for little Laban, who hasn''t thought of anything yet. He wanted to make the absolute best present in the world! Who can help him now? It seems only a miracle can save the holiday—and Christmas Eve is truly the best time for miracles to happen.', 'Svi u dvorcu već znaju šta će pokloniti roditeljima za Božić, samo Laban još uvijek nije ništa smislio. A toliko je želio da pripremi najljepši poklon na svijetu! Ko će mu pomoći? Čini se da preostaje samo nada u čudo — a badnje veče je pravo vrijeme za čuda.', 'Даже добрым привидениям хочется подарить близким идеальный подарок, особенно в волшебную рождественскую ночь!', 'Even the friendliest little ghost wants to find the perfect present when Christmas magic is in the air!', 'Čak i najslađi mali duh želi da pronađe savršen poklon kad zavlada božićna čarolija!', '/covers/DP-1133.webp', '#2b4c7e', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["magic","spooky","funny"]', '["christmas","ghosts","presents","holidays","winter"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('самая-большая-книга-что-зачем--1134', 'DP-1134', 'Самая большая книга что? зачем? почему?', 'The Biggest Book of What? Why? How?', 'Najveća knjiga šta? zašto? kako?', 'Ермакович Дарья', 'Darya Ermakovich', 'Darja Ermakovič', '', '', NULL, NULL, 6, 16, 'middle', 'Увлекательная иллюстрированная энциклопедия для любознательных детей, отвечающая на самые популярные и неожиданные вопросы обо всем на свете — от природы и космоса до науки и человека.', 'A captivating illustrated encyclopedia for curious minds, answering the most popular and surprising questions about everything in the world — from nature and space to science and the human body.', 'Uzbudljiva ilustrovana enciklopedija za radoznalu djecu koja pruža odgovore na najpopularnija i najneočekivanija pitanja o svemu na svijetu — od prirode i svemira do nauke i ljudskog tijela.', 'Идеальное спасение для родителей маленьких «почемучек» и грандиозный иллюстрированный гид по тайнам Вселенной!', 'The ultimate lifesaver for parents of curious question-askers and a magnificent illustrated guide to the mysteries of our world!', 'Savršen spas za roditelje malih „radoznalaca“ i raskošan vodič kroz najzanimljivije tajne našeg svijeta!', NULL, '#1e70a2', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["real","adventure"]', '["encyclopedia","science","space","nature","curiosity"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('самые-известные-динозавры-и-ре-1135', 'DP-1135', 'Самые известные динозавры и рептилии', 'The Most Famous Dinosaurs and Reptiles', 'Najpoznatiji dinosaurusi i gmizavci', 'Владис 2018', 'Vladis Editorial', 'Vladis', '', 'Владис', 2018, '978-5-9567-2387-6', 6, 16, 'middle', 'Познавательная энциклопедия приглашает юных читателей в доисторический мир динозавров и современных рептилий, знакомя с их повадками, средой обитания и удивительными особенностями.', 'An educational encyclopedia that takes young readers on a journey through the prehistoric world of dinosaurs and into the realm of modern reptiles, showcasing their habits, habitats, and fascinating traits.', 'Edukativna enciklopedija koja vodi mlade čitaoce na uzbudljivo putovanje kroz praistorijski svijet dinosaurusa i carstvo savremenih gmizavaca, otkrivajući njihove navike, staništa i nevjerovatne osobine.', 'Настоящий портал в мезозойскую эру: открывайте скорее, пока тираннозавр не сбежал со страниц!', 'A real portal back to the Mesozoic era—open it up before the T-Rex leaps off the page!', 'Pravi portal u doba mezozoika: otvorite je brzo prije nego što tiranosaurus pobjegne sa stranica!', '/covers/DP-1135.webp', '#3d7a44', 'nonfiction', 'ru', 'available', 'Категория: пластилин', '["animals","adventure","real"]', '["dinosaurs","reptiles","encyclopedia","paleontology","prehistoric animals"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('акулиска-враг-редиски-1136', 'DP-1136', 'Акулиска враг Редиски', 'Fox and Piglet: The Radish Shark', 'Lisac i Prase: Ajkula od rotkvica', '', 'Bjørn F. Rørvik', 'Bjern F. Rorvik', 'Пер Дюбвиг', '', NULL, NULL, 6, 16, 'middle', 'На русском языке наконец выходит самая популярная в Норвегии серия детских книг! Истории о Лисе и Поросенке издаются там уже больше 20 лет, получили приз министерства культуры Норвегии. В первой книжке из серии историй о Лисе и Поросёнке мы знакомимся с ними и с другими удивительными персонажами. А кажется, что мы знакомы уже давно: с места в карьер, с первой же страницы, мы отправляемся с героями на поиски кукушки, которая исполняет любые желания, скачем верхом на королевской плюгавой, спасаем урожай редиски от вредной акулиски — грозы огородов, ищем драгоценные лисумруды и поросяхонты и притворяемся французским зелёным жаворонком, чтобы раздобыть йогурт с дыней. Одновременно на русском языке выходит вторая книга серии — «Кафе „Птичий хвост“ из историй о Лисе и Поросенке».', 'Meet Fox and Piglet, the most inventive duo in Norwegian children''s literature! Together, they embark on wild, laugh-out-loud escapades: hunting for a wish-granting cuckoo, riding a royal scruffy hound, digging for precious ''fox-eralds'' and ''pig-sapphires'', posing as rare French green skylarks just to get melon yogurt, and valiantly defending their prized vegetable garden from the dreaded radish shark.', 'Upoznajte Lisca i Prasence, najotkačeniji i najduhovitiji dvojac norveške dječije književnosti! Zajedno kreću u nevjerovatne avanture: tragaju za kukavicom koja ispunjava sve želje, jašu kraljevskog psa, traže dragocjeno drago kamenje i brane baštu od opasne ajkule koja proždire rotkvice.', 'Осторожно: уморительные проделки Лиса и Поросёнка вызывают неудержимые приступы хохота у читателей любого возраста!', 'Warning: Fox and Piglet''s brilliantly absurd woodland antics will have the whole family giggling uncontrollably!', 'Upozorenje: urnebesne smicalice Lisca i Praseta garantovano izazivaju napade smijeha kod čitalaca svih uzrasta!', '/covers/DP-1136.webp', '#d9435e', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","adventure","animals"]', '["fox and piglet","scandinavian literature","humor","friendship","vegetable garden"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-поросенок-болел-леопардозо-1137', 'DP-1137', 'Как поросенок болел леопардозом', 'How Piglet Caught Leoparditis', 'Kako se prase razboljelo od leoparditisa', '', 'Bjørn F. Rørvik', 'Bjern F. Rorvik', '', '', NULL, NULL, 6, 16, 'middle', 'Долгожданное пополнение в серии уморительно смешных историй о Лисе и Поросёнке! Лис и Поросёнок затеяли новую игру. Поросёнка сразила неизвестная болезнь. Доктора! Скорее! И доктор незамедлительно приходит на помощь — в белом халате и с хворометром в руках. Оказывается, у Поросёнка воспалился сипундер, его придётся удалить. Немедленно! Щипцами! Но Поросёнок категорически и громко не согласен. Пусть лучше у него будет леопардоз, который лечат газировкой и булочками. Только и в этой истории всё пойдёт не так, как задумали Лис и Поросёнок!', 'A hilarious addition to the beloved series about Fox and Piglet! The two friends decide to play doctor, and Piglet is struck by an enigmatic ailment. Doctor Fox rushes in with his thermometer and terrifying pliers, diagnosing a severe case that Piglet vehemently rejects. Piglet insists he would much rather have ''leoparditis''—a rare condition cured exclusively by fizzy lemonade and warm sweet buns. But of course, things get completely out of hand!', 'Urnebesno duhovita priča iz omiljenog serijala o Liscu i Prasetu! Dva prijatelja započinju igru ljekara kada Prase pogađa misteriozna bolest. Doktor Lisac stiže sa toplomjerom i kleštima, spreman za hitnu operaciju, ali se Prase odlučno buni. Radije bira ''leoparditis'', bolest koja se liječi isključivo gaziranim sokom i slatkim kiflama! Naravno, sve kreće potpuno nepredviđenim tokom.', 'Уморительное лекарство от хандры: лучший способ вылечить любую выдуманную болезнь — запастись лимонадом, булочками и лучшим другом!', 'A laugh-out-loud cure for boredom proving that the best medicine for any pretend sickness is fizzy soda, sweet buns, and a loyal friend!', 'Urnebesan lijek za dosadu koji dokazuje da se svaka izmišljena bolest najbolje liječi gaziranim sokom, kiflama i najboljim prijateljem!', '/covers/DP-1137.webp', '#d97724', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","animals","friends"]', '["humor","pretend play","fox and piglet","friendship","picture book"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кафе-птичий-хвост--1138', 'DP-1138', 'Кафе "Птичий хвост"', 'Café Birdtail', 'Kafe „Ptičji rep”', '', 'Bjørn F. Rørvik', 'Bjørn F. Rørvik', '', '', NULL, NULL, 6, 16, 'middle', 'На русском языке наконец выходит самая популярная в Норвегии серия детских книг! С этими смешными и дикими историями растёт уже второе поколение норвежских детей. Авторы получили множество премий, а истории переведены на пять языков. Во второй книжке наши давние знакомые — Лис и Поросёнок снова нашли приключения себе на голову (и на хвост). На этот раз друзья надумали открыть кафе для перелётных птиц. Блюда там на любой вкус: мясные мухи под соусом и отборные червяки, суп из личинок и живой десерт прямиком из муравейника. Вот только расплачиваться за угощение птицам придётся очень необычным способом. И всё шло по плану, пока в кафе не наведалась прожорливая проглотка...', 'Fox and Piglet are back with another hilarious adventure! This time, the inseparable duo decides to open a gourmet café for migratory birds. The menu is packed with bird delicacies: juicy flies in sauce, prime earthworms, maggot soup, and a wriggling dessert straight from an anthill. There is just one catch: guests must pay for their treats in a very peculiar way! Everything goes smoothly until a voracious feathered glutton arrives...', 'Lisac i Prase se vraćaju sa još jednom urnebesnom avanturom! Ovog puta, nerazdvojni drugari odlučuju da otvore gurmanski kafe za ptice selice. Na meniju su prave poslastice: sočne muve u sosu, birane gliste, čorba od crva i živi desert pravo iz mravinjaka. Postoji samo jedna caka — gosti moraju da plate na vrlo neobičan način! Sve je teklo po planu dok se nije pojavila jedna nezasita proždrljivica...', 'Приготовьтесь хохотать: Лис и Поросёнок открыли ресторан для птиц с червяками и жуками, где расплачиваться придётся перьями!', 'Get ready to giggle: Fox and Piglet have opened a bird café serving worm delicacies where you pay with your own feathers!', 'Spremite se za smijeh: Lisac i Prase su otvorili kafe za ptice sa poslasticama od glista, gdje se račun plaća perjem!', '/covers/DP-1138.webp', '#d97838', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","animals","friends"]', '["fox and piglet","birds","humor","cooking","norwegian literature"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('свитер-на-рождество-1139', 'DP-1139', 'Свитер на Рождество', 'A Christmas Sweater', 'Džemper za Božić', '', 'Bjørn F. Rørvik', 'Bjern F. Rorvik', '', '', NULL, NULL, 6, 16, 'middle', 'Картон Лютый заделался почётным членом клуба ниссе. И даже получил приглашение на новогоднюю встречу. Международную, между прочим. На таких важных мероприятиях дундук и не бывал никогда, идти самому боязно. Может, Лис с Поросёнком составят ему компанию? Друзья охотно соглашаются: там ведь будет лотерея с подарками и хоровод вокруг ёлки. Вот только приходить на праздник отчего-то нужно раздетым, без свитера…', 'Carton the Grouch has somehow become an honorary member of the Nisse club and received an invitation to their international holiday gala! He''s far too nervous to go alone, so can Fox and Piglet tag along? Of course they can—there will be a prize raffle and round dances by the tree! There''s just one strange rule: guests are asked to show up completely undressed, without a cozy sweater...', 'Karton Ljuti postao je počasni član kluba patuljaka nisea i čak dobio pozivnicu za međunarodni novogodišnji skup! Kako ga je strah da ide sam, Lija i Prase rado pristaju da mu prave društvo — ipak se tamo dijele pokloni na lutriji i igra oko jelke. Jedini je problem što na žurku nekako moraju doći sasvim golišavi, bez ijednog džempera...', 'Хватайте верных друзей и готовьтесь к уморительному норвежскому Рождеству, где даже колючий свитер может стать поводом для переполоха!', 'Grab your best friends and brace yourselves for a hilarious holiday caper where even a knitted sweater turns everything upside down!', 'Povedite najbolje prijatelje i spremite se za urnebesnu prazničnu avanturu u kojoj čak i pleteni džemper pravi pravu zbrku!', '/covers/DP-1139.webp', '#c43d32', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","friends","animals"]', '["christmas","fox and piglet","humor","winter","party"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вс-проглот-1140', 'DP-1140', 'Всёпроглот', 'The All-Swallower', 'Svegutač', '', 'Bjørn F. Rørvik', 'Bjørn F. Rørvik', '', '', NULL, NULL, 6, 16, 'middle', 'Лис затеял уборку в норе и решил заодно вычистить грязнющий ковёр. Сначала они с Поросёнком попробовали его вытрясти, но лишь засыпали пылью Поросёнка, а ковёр, увы, сделался ещё грязнее. Зато прилетели цыцыроны. От них друзья узнали, что Картон Лютый обзавёлся всёпроглотом. Но справится ли этот агрегат с ковром? «Справится и не подавится!» — уверяет их дундук, однако же чудо-машину напрокат не даёт. Приходится Лису с Поросёнком идти на хитрость, чтобы проучить жадину...', 'Fox decides to clean his den and wash a filthy carpet. He and Piglet try shaking it out, but they only end up covering Piglet in dust while making the carpet even dirtier. Luckily, bird-messengers bring word that Fierce Carton has acquired a wondrous "all-swallower." But will this bizarre gadget clean the carpet without choking on it? The stingy owner refuses to lend it out, so Fox and Piglet must hatch a clever scheme to teach the greedy fellow a lesson...', 'Lisac je odlučio da sredi svoju jazbinu i usput očisti prljavi tepih. On i Prase su prvo probali da ga istresu, ali su samo zasuli Prase prašinom, dok je tepih postao još prljaviji. Tada saznaju da je Ljuti Karton nabavio moćnog „svegutača”. Može li ova čudna mašina izaći na kraj s tepihom? Škrta komšija ne želi da je pozajmi, pa Lisac i Prase moraju smisliti lukav plan kako bi očitali lekciju tvrdici...', 'Уморительные приключения Лиса и Поросёнка, которые доказывают: генеральная уборка в лесу всегда заканчивается грандиозным хохотом!', 'A laugh-out-loud forest comedy proving that deep-cleaning a rug with quirky friends always turns into sheer chaos!', 'Urnebesna šumska avantura Lisca i Praseta koja dokazuje da veliko proljećno čišćenje uvijek donosi gomilu smijeha!', '/covers/DP-1140.webp', '#d96b27', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","animals","friends"]', '["fox and piglet","humor","cleaning","friendship","tricky plan"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дед-надзор-1141', 'DP-1141', 'Дед-надзор', 'The Christmas Inspector', 'Deda Nadzor', '', 'Bjørn F. Rørvik', 'Bjern F. Rervik', '', '', NULL, NULL, 6, 16, 'middle', 'Гуляли себе Лис и Поросёнок по зимнему заснеженному лесу — и случайно угодили на стоянку охламонов. Но тем не до незваных гостей, свалившихся со снегом им на голову, — они ждут Деда-Надзора. Оказывается, есть у охламонов давняя традиция: весь декабрь, до самого Рождества, нужно угощать Деда-Надзора приготовленными по его заказу тортами. А иначе Рождество не наступит. Дед-Надзор является за очередным тортом, и Лис с Поросёнком озадачены: больно уж странно он выглядит. Друзья решают выяснить, кто же этот загадочный любитель тортов.', 'While strolling through the snowy woods, Fox and Piglet stumble into the encampment of the rough-and-tumble cave dwellers. But nobody has time for unexpected guests—everyone is terrified of the Christmas Inspector! Tradition dictates feeding him custom-made cakes all through December or Christmas will be canceled. When the suspicious inspector shows up for his next treat, Fox and Piglet suspect foul play and launch their own hilarious winter investigation.', 'Šetajući po snijegom zavijanoj šumi, Lisac i Prase slučajno zalutaju u tabor pećinara. Ali oni nemaju vremena za nezvane goste — svi sa strepnjom čekaju Deda Nadzora! Prema starom običaju, cijelog decembra moraju ga hraniti specijalnim tortama kako Božić ne bi propao. Kada se tajanstveni inspektor pojavi, dvojica radoznalih prijatelja shvataju da tu nešto ozbiljno smrdi i kreću u urnebesnu istragu.', 'Остроумный скандинавский детектив с Лисом и Поросёнком, где спасение Рождества зависит от порции тортиков и природного любопытства!', 'A hilarious Nordic winter mystery where Fox, Piglet, and a suspicious cake-craving inspector turn holiday traditions delightfully upside down!', 'Urnebesna zimska detektivska avantura u kojoj Lisac i Prase spasavaju praznike uz pomoć torte i zdrave doze radoznalosti!', '/covers/DP-1141.webp', '#2b5b84', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","adventure","animals"]', '["fox and piglet","winter","christmas","humor","detective"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('конни-и-кот-нок-1142', 'DP-1142', 'Конни и котёнок', 'Conni and the Kitten', 'Koni i mače', '', 'Liane Schneider', 'Liane Šnajder', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Конни Клавиттер живет с мамой и папой в небольшом немецком городке. Ей три года, она совсем недавно начала ходить в детский сад и мечтает о домашнем животном. И вот однажды ее мечта сбывается — к ней в дом попадает потерявшийся котенок. Сможет ли Конни оставить его у себя? Или надо обязательно найти хозяина? Чем кормить котенка, где устроить ему «домик» и как следить за его здоровьем? Прочитайте историю Конни и научитесь вместе с ней ухаживать за домашними животными.', 'Three-year-old Conni has always dreamed of a pet, and one day her wish comes true when a lost kitten wanders into her life. Can Conni keep it, or must she find its owner? How do you feed a tiny kitten, make it a cozy bed, and look after its health? Follow Conni''s heartwarming story and discover the basics of caring for a furry new friend.', 'Trogodišnja Koni mašta o kućnom ljubimcu, i jednoga dana njena želja se ostvaruje kada u njen dom zaluta izgubljeno mače. Može li ga zadržati ili mora pronaći vlasnika? Čime ga hraniti, gdje mu napraviti ležaj i kako brinuti o njegovom zdravlju? Pročitajte Koninu priču i naučite kako se s ljubavlju njeguje mali četvoronožni prijatelj.', 'Идеальная и очень добрая инструкция для каждого малыша, который всем сердцем мечтает о пушистом четырёхлапом друге!', 'The sweetest and most practical guide for any little dreamer wishing for a purring four-legged friend!', 'Najnježniji i najtopliji vodič za sve mališane koji sanjaju o svom prvom malom mjau-prijatelju!', '/covers/DP-1142.webp', '#e58e37', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["animals","friends","real"]', '["cats","pets","kitten","caring","family"]', 1792836322701, 1792845711161);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('конни-ид-т-в-детский-сад-1143', 'DP-1143', 'Конни идёт в детский сад', 'Conni Goes to Kindergarten', 'Koni ide u vrtić', '', 'Liane Schneider', 'Lijane Šnajder', '', 'Альпина.Дети', 2023, '978-5-9614-8923-1', 6, 16, 'middle', 'Добрая терапевтическая история о первом дне трёхлетней Конни в детском садике. Книга помогает малышу справиться с волнением перед незнакомой обстановкой, научиться заводить друзей и оставаться без мамы.', 'A gentle, therapeutic story about three-year-old Conni''s very first day at kindergarten. The book helps toddlers navigate unfamiliar environments, ease separation anxiety, and learn how to make their first friends.', 'Topla terapijska priča o prvom danu trogodišnje Koni u vrtiću. Knjiga pomaže mališanima da prebrode strah od nepoznatog okruženja, lakše podnesu odvajanje od roditelja i steknu prve drugare.', 'Нежная и ободряющая история, которая покажет малышу, что детский сад — это совсем не страшно, а весело и здорово!', 'A comforting and cheerful tale that shows little ones that kindergarten is nothing to fear, but rather a place full of games and friends!', 'Nježna i ohrabrujuća priča koja će pokazati mališanima da vrtić nije strašan, već pun radosti i novih prijateljstava!', '/covers/DP-1143.webp', '#e2574c', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["friends","real"]', '["kindergarten","growing up","first day","coping with emotions","friendship"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('конни-и-карманные-деньги-1144', 'DP-1144', 'Конни и карманные деньги', 'Conni and Pocket Money', 'Koni i džeparac', '', 'Unknown', 'Nepoznati autor', '', 'Альпина Паблишер', 2020, '978-5-9614-2940-4', 6, 16, 'middle', 'Поучительная история знакомит малышей с основами финансовой грамотности на примере Конни, которая учится обращаться с первыми карманными деньгами, копить на желанную покупку и планировать траты.', 'An instructive story introducing young readers to the basics of financial literacy as Conni learns to manage her first pocket money, save for a dream purchase, and plan her spending wisely.', 'Poučna priča koja mališane uvodi u osnove finansijske pismenosti na primjeru Koni, koja uči kako da raspolaže prvim džeparcem, štedi za željenu igračku i planira troškove.', 'Замечательный способ весело и легко обсудить с ребёнком, почему деньги любят счёт и как накопить на мечту!', 'A delightful and practical way to chat with your child about saving up, spending smartly, and waiting for big dreams!', 'Sjajan i pristupačan način da sa djetetom popričate o prvom novcu, strpljenju i pametnom štednju za snove!', '/covers/DP-1144.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real"]', '["pocket money","financial literacy","growing up","saving"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('везучая-уточка-1145', 'DP-1145', 'Везучая уточка', 'The Lucky Duck', 'Srećna patkica', 'Холли Вебб', 'Holly Webb', 'Holi Veb', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Чем может Молли помочь утке, приносящей удачу? Найти её яйцо. Только это яйцо совершенно не похоже на обычные утиные яйца, и пропало оно в парке. Где как раз устроили весёлое приключение для детей - поиск шоколадных яиц. Так что везение Молли и утке точно понадобится! Для среднего школьного возраста.', 'How can Molly help a duck that brings good luck? By tracking down its missing egg! But this is no ordinary egg, and it is lost in the middle of a bustling park where children are busy hunting for chocolate treats. Molly and her feathered friend will need every ounce of luck they can find.', 'Kako Moli može pomoći patkici koja donosi sreću? Tako što će pronaći njeno izgubljeno jaje! Međutim, to jaje uopšte ne liči na obično, a nestalo je usred parka gdje djeca veselo tragaju za čokoladnim jajima. Moli i patkici će definitivno biti potrebna prava magija i sreća.', 'Трогательная детективная сказка о поисках волшебного яйца среди сотен шоколадных — запаситесь чаем и верьте в чудеса!', 'A heartwarming magical mystery about finding a very special duck egg hidden amidst hundreds of chocolate ones!', 'Topla magična misterija o potrazi za jednim posebnim jajetom skrivenim među stotinama čokoladnih!', '/covers/DP-1145.webp', '#e5aa38', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","animals","adventure"]', '["animals","magic","ducks","egg hunt","friendship"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лес-дружбы-лисичка-тыковка-или-1146', 'DP-1146', 'Лес дружбы. Лисичка Тыковка или лунный камень', 'Forest of Friendship: Pumpkin the Fox or the Moonstone', 'Šuma prijateljstva: Lisica Tikvica ili Mjesečev kamen', 'Дейзи Медоус', 'Daisy Meadows', 'Dejzi Medous', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Можно ли научить дракона танцевать? Лили и Джесс, конечно же, попробуют, только вот дракон Клякса учиться не хочет. Но лисичка Тыковка придет им на помощь, и тут не только дракон, а все обитатели Леса Дружбы пустятся в пляс.', 'Can you teach a dragon to dance? Lily and Jess are certainly going to try, but Inkdrop the little dragon isn''t keen on practicing at all. Luckily, Pumpkin the little fox rushes to help, and soon not just the dragon, but all the woodland folk in the Forest of Friendship are ready to groove!', 'Može li se zmaj naučiti da pleše? Lili i Džes će svakako pokušati, ali zmajčić Mrlja uopšte ne želi da vježba. Srećom, lisica Tikvica stiže u pomoć, pa će uskoro ne samo zmaj, već i svi stanovnici Šume prijateljstva zaplesati!', 'Уютная и добрая сказка о том, как музыка, терпение и хвостатые друзья могут расшевелить даже самого упрямого дракончика!', 'A charming, cozy tale showing that a bit of rhythm, patience, and fluffy friends can make even the grumpiest dragon dance!', 'Topla i vesela bajka koja dokazuje da uz dobru muziku, strpljenje i vesele šumske prijatelje čak i tvrdoglavi zmaj može da zapleše!', '/covers/DP-1146.webp', '#d96b27', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","friends","animals"]', '["dragons","foxes","friendship","dancing","fairy tale"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ежонок-эмили-или-корона-для-ум-1147', 'DP-1147', 'Ежонок Эмили или корона для умницы', 'Emily Prickleback''s Clever Idea', 'Ježić Emili ili kruna za pametnicu', 'Дейзи Медоус', 'Daisy Meadows', 'Dejzi Medous', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Дейзи Медоус - автор более ста книг для детей, среди которых серия Rainbow Magic - всемирный бестселлер о приключениях фей. Представляем вашему вниманию ее новый проект! Лили и Джесс - лучшие подруги, они обожают животных и даже помогают в ветклинике. Однажды девочки знакомятся с необычной кошкой Голди, которая привела их в волшебное место - Лес Дружбы, где все животные умеют разговаривать. С этого дня приключения следуют одно за другим! Ежонок Эмили признана самой умной из маленьких жителей Леса Дружбы. Но с заклятием дракона Пылинки даже она не может справиться. Лили и Джесс приходят ей на помощь - и теперь им втроем предстоит придумать, как спасти реку!', 'Best friends Lily and Jess love animals and volunteer at a veterinary clinic. One day, a magical cat named Goldie whisks them away to Friendship Forest, a wonderful world where animals can talk! When bright little hedgehog Emily Prickleback faces a tricky dragon''s spell over the river, the girls must team up with her to solve the puzzle and save their beloved forest.', 'Najbolje drugarice Lili i Džes obožavaju životinje i pomažu u veterinarskoj ambulanti. Jednog dana upoznaju neobičnu mačku Goldi, koja ih odvodi u čarobnu Šumu prijateljstva gdje sve životinje govore! Malom ježiću Emili potrebna je pomoć da razbije zlu čaroliju i spasi rijeku — a uz prave prijateljice, nijedan izazov nije nerješiv.', 'Маленький колючий комочек с острым умом докажет, что дружба и смекалка спасут даже заколдованную реку!', 'A tiny prickly friend with quick wits proves that teamwork and kindness make any magical river flow again!', 'Mali bodljikavi pametnjaković dokazuje da uz dobro srce i prave drugarice nijedna čarolija ne može pobijediti!', '/covers/DP-1147.webp', '#4ca682', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","animals","friends"]', '["hedgehogs","talking animals","magic forest","friendship","rescue"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('щенок-поппи-или-сонные-чары-1148', 'DP-1148', 'Щенок Поппи или сонные чары', 'Poppy the Puppy and the Sleep Spell', 'Štene Popi i uspavana čarolija', '', 'Daisy Meadows', 'Dejzi Medouz', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Мерзкая ведьма Гризельда наслала на щенка Пэтча сонные чары. Его сестрёнка Поппи вместе с Лили и Джесс пытаются развеять колдовство, но у них очень мало времени. Ведь, если щенка не разбудить до заката, он уснёт навсегда!', 'The wicked witch Grizelda has cast a sleeping hex over Patch the puppy. His brave little sister Poppy, along with best friends Lily and Jess, must race against the clock to break the enchantment before sunset—or Patch will stay asleep forever!', 'Zla vještica Grizelda bacila je uspavanu čaroliju na štene Peča. Njegova sestrica Popi, zajedno sa Lili i Džes, pokušava da razbije čin, ali vremena je malo — ako se štene ne probudi prije zalaska sunca, zaspaće zauvijek!', 'Держите лапки наготове: девочкам предстоит спасти сонного щенка до заката в настоящей сказочной гонке со временем!', 'Keep your paws ready: the girls must break the wicked witch''s spell and save an adorable puppy before sunset!', 'Držite šapice spremne: djevojčice imaju vremena samo do zalaska sunca da razbiju vještičju magiju i spasu pospanog psića!', '/covers/DP-1148.webp', '#6a4c93', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","animals","adventure"]', '["puppies","magic","witchcraft","rescue","friendship"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бельчонок-софи-или-осторожно-д-1149', 'DP-1149', 'Бельчонок Софи или осторожно, драконы!', 'Sophie Flufftail: Beware of Dragons!', 'Vjeverica Sofi ili pazi, zmajevi!', '', 'Daisy Meadows', 'Dejzi Medous', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'В Лесу Дружбы появились драконы - и с не самыми дружелюбными намерениями! Один из них заморозил Дом Света и сразу стало темно и холодно. Лили и Джесс поспешили на помощь друзьям и теперь вместе с белочкой Софи им надо вернуть в Лес Дружбы лето! Для среднего школьного возраста.', 'Dragons have arrived in Friendship Forest, and not with the friendliest intentions! One of them has frozen the House of Light, plunging everything into cold and darkness. Lily and Jess rush to help their friends, and now, alongside little squirrel Sophie, they must find a way to bring warm summer back to Friendship Forest!', 'Zmajevi su se pojavili u Šumi prijateljstva, i to bez nimalo prijateljskih namjera! Jedan od njih je zaledio Kuću svjetlosti, pa je sve obavio mrak i hladnoća. Lili i Džes žure u pomoć prijateljima i sada, zajedno sa vjevericom Sofi, moraju da vrate ljeto u Šumu prijateljstva!', 'Хватайте тёплые варежки и спешите на выручку: белочка Софи и верные подруги растопят любой драконий лёд!', 'Grab your warmest mittens and join the rescue: Sophie the squirrel and her friends can melt even dragon-made ice!', 'Uzmite tople rukavice i krenite u spasavanje: vjeverica Sofi i njene drugarice mogu da otope čak i zmajev led!', '/covers/DP-1149.webp', '#3e7cb1', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","magic","animals"]', '["friendship forest","dragons","squirrels","winter rescue","magic animals"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('принцессы-пони-друг-из-облачно-1150', 'DP-1150', 'принцессы пони. Друг из облачного леса', 'Princess Ponies: A Friend in the Cloud Forest', 'Poniji princeze: Prijatelj iz oblačne šume', 'Хоре Райдер', 'Chloe Ryder', 'Kloi Rajder', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Привет! Меня зовут Пиппа, и я люблю лошадей. Я просила маму купить мне пони, но оказалось, что это невозможно. Зато теперь я познакомилась с самыми настоящими волшебными пони и меня ждут удивительные приключения! Мрачный Облачный лес, населен неведомыми существами, и отправиться туда могут только по-настоящему храбрые пони. Но у нас со Звездочкой нет выбора, ведь именно там могут быть спрятаны недостающие подковы... Для младшего школьного возраста.', 'Pippa adores horses, and although she couldn''t have an ordinary pony of her own, she discovered something far better—real magical ponies! Now Pippa and her loyal pony Stardust must summon all their courage and enter the shadowy Cloud Forest, where strange creatures dwell, to find the missing enchanted horseshoes.', 'Pipa obožava konje više od svega. Iako nije mogla dobiti pravog ponija, otkrila je nešto mnogo čarobnije — prave magične ponije koji govore! Sada Pipa i njena ponica Zvjezdica moraju skupiti svu hrabrost i zakoračiti u sjenovitu Oblačnu šumu punu neobičnih stvorenja kako bi pronašle nestale čarobne potkovice.', 'Если вам пока не разрешают завести пони дома, просто откройте эту книгу и отправляйтесь в заколдованный лес на поиски волшебных подков!', 'If you can''t have a pony in your backyard, open this book and sneak into an enchanted kingdom where magical steeds need your help!', 'Ako vam ne daju pravog ponija kod kuće, samo otvorite ovu knjigu i zakoračite u začaranu šumu u potragu za magičnim potkovicama!', '/covers/DP-1150.webp', '#7b5ea7', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","magic","animals"]', '["ponies","magic","horses","friendship","quest"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пони-феи-холли-и-лес-единорого-1151', 'DP-1151', 'Пони-феи. Холли и лес единорогов', 'Fairy Ponies: Holly and the Unicorn Forest', 'Vilinski poniji: Holi i šuma jednoroga', 'Занна Дэвидсон', 'Zanna Davidson', 'Zana Dejvidson', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Холли мечтала увидеть единорогов, и наконец, ей выпал такой шанс. Только девочке предстоит не просто познакомиться с удивительными созданиями, но и спасти их от коварного пони Шедоу. В надежде завладеть троном, Шедоу решил воспользоваться магией единорогов. Если это произойдет, он станет самым могущественным пони и сможет управлять Островом... Для младшего школьного возраста.', 'Holly has always dreamed of seeing unicorns, and now her wish has finally come true. But meeting these wondrous creatures turns into a daring rescue mission when the villainous pony Shadow hatches a plot to steal their magic and seize the throne. Can Holly protect the unicorns and save the island before it''s too late?', 'Holi je oduvijek maštala da vidi jednoroge, i konačno joj se ukazala prilika. Ipak, ne čeka je samo upoznavanje s ovim čarobnim bićima, već i opasna misija spasavanja od lukavog ponija Šedoua. U želji da prigrabi prijesto, Šedou planira da iskoristi magiju jednoroga — hoće li Holi uspjeti da spasi Ostrvo?', 'Хватайте щепотку волшебной пыльцы и седлайте пони: в этом зачарованном лесу единорогам срочно требуется ваша помощь!', 'Grab a pinch of fairy dust and gallop into the enchanted forest, where magical unicorns are counting on you to save the day!', 'Uzmite malo vilinskog praha i odjašite u začaranu šumu — predivnim jednorozima hitno je potrebna pomoć!', '/covers/DP-1151.webp', '#9b5de5', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","animals"]', '["unicorns","ponies","fairies","magic","rescue"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пони-феи-холли-и-принцесса-пон-1152', 'DP-1152', 'Пони-феи. Холли и принцесса пони', 'Fairy Ponies: Holly and the Pony Princess', 'Vile poniji: Holi i princeza poni', 'Занна Дэвидсон', 'Zanna Davidson', 'Zana Dejvidson', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Племянница Королевы, принцесса Розабель, похищена. Все пони Острова пустились на поиски. Холли и ее друг-пони не остались в стороне и чтобы спасти принцессу вступили в схватку с помощниками злодея Шедоу. Сможет ли магия и заклинания помочь друзьям? Для младшего школьного возраста.', 'The Queen''s niece, Princess Rosabelle, has been captured, and every pony on Pony Island sets out to search for her. Holly and her winged pony friend leap straight into action to rescue the princess from wicked Shadow''s scheming henchmen. Can a sprinkle of fairy magic and heartfelt bravery save the day?', 'Kraljičina nećaka, princeza Rozabel, je oteta, a svi poniji sa Ostrva ponija kreću u potragu. Holi i njen krilati prijatelj poni ne oklijevaju i hrabro se suprotstavljaju pomagačima zlog Šedoua kako bi je spasili. Hoće li čarolija i prijateljstvo biti dovoljni za pobjedu?', 'Если вы любите волшебных крылатых пони и спасательные миссии, седлайте воображение — эта сказка для вас!', 'If you adore winged ponies and daring rescue missions, saddle up your imagination for this magical treat!', 'Ako volite krilate čarobne ponije i hrabre spasilačke misije, pripremite se za pravu bajkovitu avanturu!', '/covers/DP-1152.webp', '#d65b92', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","animals"]', '["ponies","fairies","magic","rescue","friendship"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('щепотка-магии-1153', 'DP-1153', 'Щепотка магии', 'A Pinch of Magic', 'Prstohvat magije', 'Мишель Харрисон', 'Michelle Harrison', 'Mišel Harison', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Сестры Уиддершинс — Бетти, Флисс и Чарли — при помощи трех волшебных предметов пытаются снять зловещее семейное проклятие. Но помогут ли эти предметы найти ответы на загадки, или навлекут на сестер новую беду? Бетти Уиддершинс узнала о фамильном проклятии вечером своего тринадцатого дня рождения. Это число некоторые считали несчастливым, но Бетти была слишком здравомыслящей, чтобы верить в приметы. Ей нравилось думать, что она далека от суеверий и прочей подобной ерунды, — пускай даже они окружали ее с самого рождения. Это та самая история, которую хочется прочитать за ночь или прятать от учителя под партой. А после — поставить на видное место на полке, чтобы любоваться красивым изданием.', 'The Widdershins sisters—Betty, Fliss, and Charlie—are trapped on the gloomy island of Crowstone by a sinister family curse. Armed with three magical heirlooms, they set out to break the spell and win their freedom. But will these enchanted objects help them uncover the truth, or drag them into even deeper danger? A breathtaking fantasy adventure full of mystery, sisterhood, and dark secrets.', 'Sestre Videršins — Beti, Flis i Čarli — zarobljene su na maglovitom ostrvu Kroustoun zbog zlokobnog porodičnog prokletstva. Naoružane sa tri čarobna naslijeđena predmeta, sestre kreću u opasnu potragu kako bi prekinule kletvu i osvojile slobodu. Uzbudljiva fantazijska avantura puna misterija, sestrinske odanosti i opasnih tajni.', 'Запасайтесь фонариком и одеялом: от этой таинственной истории о трех смелых сестрах и фамильных чарах просто невозможно оторваться до рассвета!', 'Grab a flashlight and a cozy blanket: once you dive into the mysterious world of the Widdershins sisters, you won''t sleep until the last page is turned!', 'Pripremite baterijsku lampu i toplo ćebe: čim zaronite u tajne sestara Videršins, nećete sklopiti oči do posljednje stranice!', '/covers/DP-1153.webp', '#1b4556', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","spooky"]', '["sisters","curse","fantasy","mystery","magic items"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('горстка-волшебства-1154', 'DP-1154', 'горстка волшебства', 'A Sprinkle of Sorcery', 'Prstohvat magije', 'Мишель Харрисон', 'Michelle Harrison', 'Mišel Harison', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Когда в «Потайном кармане» объявляется незваная гостья, сестры Уиддершинс — Бетти, Флисс и Чарли — оказываются по уши втянуты в очередное приключение. В нем замешаны таинственная карта, проклятый корабль, потерпевший крушение, и старинная легенда, которая может оказаться вовсе не легендой… Приготовься покинуть Вороний Камень и отправиться вместе с сестрами в неизведанное, прихватив с собой лишь горстку волшебства. Только берегись пиратов!', 'When an unwelcome guest arrives at the Poacher''s Pocket, the Widdershins sisters—Betty, Fliss, and Charlie—find themselves swept into another perilous journey. Involving a mysterious map, a cursed shipwreck, and an ancient legend that might just be true, they must leave Crowstone behind and venture into the unknown with only a sprinkle of sorcery to guide them. Beware of pirates!', 'Kada se u krčmi pojavi nezvani gost, sestre Videršins — Beti, Flis i Čarli — bivaju uvučene u još jednu opasnu pustolovinu. Uz tajanstvenu mapu, ukleti brodolom i drevnu legendu koja bi mogla biti istinita, sestre napuštaju Vranin kamen i plove u nepoznato naoružane samo prstohvatom magije. I pripazite na pirate!', 'Захватывающее продолжение «Щепотки магии», где старинная карта и пиратские тайны не дадут оторваться от книги до глубокой ночи!', 'A spellbinding nautical sequel packed with ancient maps, pirate perils, and sisterly courage that will keep you up reading past bedtime!', 'Očaravajuća morska avantura u kojoj vas drevne mape, pirati i sestrinska hrabrost vode pravo u srce magije!', '/covers/DP-1154.webp', '#1f4a5c', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","spooky"]', '["sisters","pirates","magic objects","curses","mystery"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('клубок-заклинаний-1155', 'DP-1155', 'клубок заклинаний', 'A Tangle of Spells', 'Klupko čarolija', 'Мишель Харрисон', 'Michelle Harrison', 'Mišel Harison', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Сестры Уиддершинс покидают туманный остров и поселяются в живописной деревушке Пендлвик. Но все здесь не так, как казалось вначале. Над деревушкой нависло что-то недоброе. Когда еще и Флисс начинает вести себя странно, Бетти и Чарли понимают, что им придется распутать целый клубок заклинаний... если еще не слишком поздно. Зачем читать эту книгу? Невероятно интересное продолжение приключений сестер Уиддершинс. Книга, полная магии и неожиданных поворотов сюжета. Кроме того, эта история о смелости, дружбе, взаимопомощи, верности выбору, о намерении изменить свою жизнь к лучшему. Книга, от которой невозможно оторваться до последней страницы.', 'The Widdershins sisters leave the misty Crowstone behind to settle in the picturesque village of Pendlewick. But not everything is as idyllic as it appears, and an ominous presence hangs over the town. When Fliss starts acting strangely, Betty and Charlie realize they must unravel a dangerous tangle of spells before it is too late. A thrilling magical tale of bravery, family secrets, and sisterly devotion.', 'Sestre Videršins napuštaju maglovito ostrvo Kroustoun i sele se u slikovito selo Pendlvik. Ali ništa ovdje nije onako kako izgleda, a nad selom se nadvila mračna prijetnja. Kada se Flis počne čudno ponašati, Beti i Čarli shvataju da moraju raspetljati opasno klupko čarolija prije nego što bude prekasno. Uzbudljiva priča puna magije, neočekivanih obrta i sestrinske odanosti.', 'Осторожно: потяните за одну волшебную ниточку — и не сможете оторваться от тайн сестёр Уиддершинс до самого рассвета!', 'Pull just one magical thread, and you''ll find yourself tangled up in the Widdershins sisters'' thrilling mystery until dawn!', 'Povucite samo jednu magičnu nit i bićete zapleteni u uzbudljive tajne sestara Videršins sve do zore!', '/covers/DP-1155.webp', '#2c6467', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","spooky"]', '["sisters","magic","witchcraft","curses","mystery"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('п-с-по-имени-мани-1156', 'DP-1156', 'пёс по имени Мани', 'A Dog Called Money', 'Pas po imenu Mani', 'Бодо Шефер', 'Bodo Schäfer', 'Bodo Šefer', '', 'Попурри', NULL, NULL, 6, 16, 'middle', 'Почему дети так быстро учатся и настолько легко схватывают новую информацию? Все очень просто: они делают это с удовольствием и не скованы ложными стереотипами. Пользуясь теми же правилами, вы сможете легко и просто отыскать свой путь к богатству. Трогательная история говорящего лабрадора Мани, который оказался настоящим финансовым гением, в доступной форме открывает перед детьми и взрослыми секреты денег. 3 причины читать эту книгу: 1. Мировой хит: тираж книги – более трёх миллионах экземпляров. От автора бестселлера №1 «Путь к финансовой свободе». 2. Главная книга по финансовой грамотности для детей расскажет о том, как инвестировать, экономить и зарабатывать. 3. Благодаря забавным историям и советам пса Мани вы поймёте, как изменить жизнь, чтобы прийти к мечте.', 'Why do kids pick up new ideas so quickly? Because they learn with pure curiosity, free from preconceived notions. Following the same playful spirit, this touching story of a talking Labrador named Money—who turns out to be a genuine financial genius—unveils the secrets of earning, saving, and investing for readers of all ages. Through heartwarming adventures and clear, practical advice, Money teaches twelve-year-old Kira how to build wealth and make her biggest dreams come true.', 'Zašto djeca tako brzo uče i s lakoćom usvajaju nova znanja? Zato što to rade sa zadovoljstvom i bez opterećenja predrasudama. Dirljiva priča o labradoru Maniju koji govori i koji se ispostavlja kao pravi finansijski genije, na jednostavan i pristupačan način otkriva tajne novca djeci i odraslima. Kroz zabavne avanture i praktične savjete, pametni pas uči dvanaestogodišnju Kiru kako da štedi, pametno ulaže i ostvari svoje najveće snove.', 'Кто бы мог подумать, что лучший финансовый консультант в мире виляет хвостом и обожает лакомства!', 'Who knew the world''s most brilliant financial advisor would have four paws, floppy ears, and a wagging tail!', 'Ko bi rekao da najbolji finansijski savjetnik na svijetu maše repom i obožava poslastice!', '/covers/DP-1156.webp', '#e5a93b', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["animals","real","friends"]', '["financial literacy","money","dogs","personal growth","saving"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('банка-со-светлячками-1157', 'DP-1157', 'Банка со светлячками', 'The Light Jar', 'Tegla sa svicima', 'Лиза Томпсон', 'Lisa Thompson', 'Liza Tompson', '', 'Миф', NULL, NULL, 6, 16, 'middle', 'У Нейта очень много вопросов. Почему мама разбудила его ночью и увезла из дома? Для чего им нужно прятаться ото всех в заброшенном доме у леса? Что случилось с мамой, которая ушла за покупками и не вернулась даже утром? Неужели она бросила его одного и вернулась туда, откуда они сбежали? Кто эта странная девочка, которая вдруг появляется из леса и просит ей помочь? И как спрятаться от всего опасного в этом мире, когда у Нейта есть только банка со светлячками, чтобы рассеять окружающую темноту?', 'Nate has so many questions. Why did his mother wake him in the middle of the night and rush him away from home? Why are they hiding in a dilapidated cottage by the woods? What happened to his mom when she went for groceries and didn''t return? And who is the mysterious girl who emerges from the trees asking for help? With only a makeshift jar of light to keep the shadows at bay, Nate must find the courage to uncover the truth.', 'Nejt ima previše neodgovorenih pitanja. Zašto ga je majka probudila usred noći i odvela daleko od kuće? Zašto moraju da se skrivaju u napuštenoj kolibi na rubu šume? Gdje je nestala njegova mama kada je otišla u nabavku i nije se vratila? I ko je ta neobična djevojčica koja izranja iz šume tražeći pomoć? Sa samo jednom teglom svjetlosti u rukama, Nejt mora pronaći hrabrost i suočiti se sa tamom.', 'Трогательный и захватывающий детектив о страхах, тайнах и храбрости, доказывающий, что даже крошечный огонёк способен развеять самую густую тьму.', 'A poignant and gripping mystery about fears, secrets, and bravery, proving that even the tiniest spark can banish the deepest darkness.', 'Dirljiva i napeta misterija o strahovima, tajnama i hrabrosti koja dokazuje da i najmanja iskra može otjerati najgušći mrak.', '/covers/DP-1157.webp', '#1c3847', 'nonfiction', 'ru', 'available', 'детектив, от 10 лет', '["adventure","friends","real"]', '["mystery","courage","family","friendship","secrets"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('арифметика-эмилии-орден-ж-лтог-1158', 'DP-1158', 'Арифметика Эмилии. Орден жёлтого дятла', 'Emília''s Arithmetic: The Order of the Yellow Woodpecker', 'Emilijina aritmetika: Red žutog djetlića', 'Монтейру Лобату', 'Monteiro Lobato', 'Monteiro Lobato', '', 'Октопус', NULL, NULL, 6, 16, 'middle', 'Веселая компания из Домика Желтого дятла ни дня не может без приключений! Герои книг Монтейру Лобату – бразильская девочка Лусия по прозвищу Носишка, её кузен Педриньо и тряпичная кукла Эмилия – уже побывали в Стране Грамматики и не собирается на этом останавливаться. Новую затею предложил самый серьёзный из друзей – граф де Кукурузо, человек из кукурузного початка. Никто не ожидал, что он превратит занятия по арифметике в цирк в прямом смысле слова.', 'The lively gang from Yellow Woodpecker Farm can''t live a single day without an adventure! Monteiro Lobato''s beloved characters—Lucia, her cousin Pedrinho, and the spunky rag doll Emilia—have already conquered the Land of Grammar and aren''t about to stop. The group''s most serious member, the scholarly corncob Viscount, surprises everyone by turning routine arithmetic into a spectacular three-ring circus.', 'Vesela družina sa imanja Žutog djetlića ne može zamisliti dan bez avanture! Junaci Monteira Lobata – Lucija, njen rođak Pedrinjo i brbljiva krpena lutka Emilija – nakon Zemlje gramatike kreću u nove pohode. Najozbiljniji među njima, učeni grof od Kukuruza, predlaže nevjerovatnu ideju: pretvara časove matematike u pravi pravcati cirkus!', 'Кто сказал, что математика — это скучно, если учить её помогают дерзкая тряпичная кукла и учёный кукурузный початок под куполом цирка?', 'Who says math is dull when your tutors are a cheeky rag doll and a scholarly corncob running a full-blown circus?', 'Ko kaže da je matematika dosadna kad je učite u cirkuskoj šatri uz drsku krpenu lutku i učenog gospodina od kukuruznog klipa?', '/covers/DP-1158.webp', '#e59b22', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","adventure","magic"]', '["math","circus","classics","brazilian literature","humor"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('100-вопросов-и-ответов-наука-1159', 'DP-1159', '100 вопросов и ответов. Наука', '100 Questions and Answers: Science', '100 pitanja i odgovora: Nauka', 'Алекс Фрит, Мина Лейси', 'Alex Frith, Minna Lacey', 'Aleks Frit, Mina Lejsi', '', 'Аванта+', NULL, NULL, 6, 16, 'middle', 'Знаете ли вы, что Земля движется по орбите быстрее пули? Что тело взрослого человека составляют около 7 октиллионов атомов? Или что небоскребы проектируют так, чтобы они гнулись на ветру? Эти невероятные факты и множество других собраны на страницах книги «Наука». Каждый разворот красочно оформлен и полон захватывающих данных о нашей планете, ее обитателях, космосе, технике и еще десятках тематик. Здесь можно узнать буквально обо всем на свете! Факты оформлены в короткие ёмкие тексты с инфографикой, чтобы ребенку было интереснее и удобнее взаимодействовать с книгой. Он узнает то, что не печатают в учебниках, и сможет без труда поразить одноклассников и друзей своей эрудицией.', 'Did you know that Earth orbits faster than a speeding bullet, the human body consists of around seven octillion atoms, and skyscrapers are engineered to bend in the wind? Packed with vibrant infographics and bite-sized explanations, this colorful guide explores outer space, human biology, technology, and beyond. It reveals the coolest scientific quirks rarely mentioned in school textbooks, ready to amaze young readers and everyone around them.', 'Da li ste znali da se Zemlja kreće brže od metka, da se ljudsko tijelo sastoji od sedam oktiliona atoma, ili da su neboderi osmišljeni da se savijaju na vjetru? Ova šarena enciklopedija puna je kratkih, upečatljivih tekstova i infografika koje otkrivaju tajne svemira, tehnologije, prirode i ljudskog tijela. Donosi nevjerovatne činjenice koje se rijetko nalaze u udžbenicima i garantuje pravo uživanje malim radoznalcima.', 'Готовы узнать, почему небоскрёбы качаются, а Земля мчит быстрее пули? Идеальная шпаргалка для будущих нобелевских лауреатов и неутомимых «почемучек»!', 'Ever wondered why skyscrapers sway or how Earth flies faster than a speeding bullet? It’s the ultimate playbook for curious minds and future geniuses!', 'Jeste li znali da se neboderi njišu na vjetru, a Zemlja juri brže od metka? Savršena knjiga za male genijalce i neumorne radoznalce!', '/covers/DP-1159.webp', '#1f7a8c', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","adventure"]', '["science","facts","encyclopedia","curiosity","space","nonfiction"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-принцесса--1160', 'DP-1160', 'Я-принцесса!', 'I Am a Princess!', 'Ja sam princeza!', 'Евгения Гюнтер', 'Evgenia Gunter', 'Jevgenija Ginter', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Новая книга от «Пешком в историю» «Я принцесса!» расскажет, как жили принцессы сто, триста или даже три тысячи лет назад. О чем мечтали или чего боялись, как развлекались или скучали – чем занимались в свои обычные царские будни? С этой книгой можно запросто представить, каково это – быть принцессой, например, в Древней Индии, Египте, Персии, средневековой Франции, допетровской Руси, Австрийской империи и др. Двенадцать принцесс с разных концов света из разных эпох сами расскажут: легко ли вставать каждый день в шесть утра, выщипывать ресницы, ходить в чоппинах, носить по два парика сразу, выучить несколько языков и многое другое. Все имена принцесс вымышлены, а вот подробности их жизни показаны достоверно с учетом всех исторических фактов. Предпоследняя глава книги «Современные принцессы», повествует о нескольких настоящих принцессах, которые живут в современном мире. А в последней главе «Принцессы, не такие как все» показаны те (не вымышленные!) дочери правителей, которые смогли, несмотря на традиции и обычаи, пойти своим путем.', 'What was it really like to be a princess a hundred, three hundred, or even three thousand years ago? Meet twelve fictional princesses from Ancient Egypt, Persia, medieval France, pre-Petrine Russia, and beyond as they reveal their authentic daily lives—from waking at dawn and plucking eyelashes to teetering on chopines and wearing two wigs at once. Based on historical research, the book also explores modern-day royalty and courageous princesses who dared to break traditions and forge their own paths.', 'Kako je zaista izgledao život princeza prije sto, trista ili čak tri hiljade godina? Upoznajte dvanaest princeza iz drevnog Egipta, Persije, srednjovjekovne Francuske, carske Rusije i drugih epoha, koje otkrivaju svoju pravu svakodnevicu — od ustajanja u zoru i čupanja trepavica do hodanja na visokim čopinama i nošenja po dvije perike odjednom. Zasnovana na istorijskim činjenicama, ova knjiga predstavlja i savremene princeze, kao i one hrabre vladarke koje su se usudile da prkose tradiciji.', 'Думаете, быть принцессой — это сплошные балы и короны? Приготовьтесь узнать о подъёмах на рассвете, гигантских париках и настоящих бунтарках сквозь века!', 'Think being a princess is all tiaras and fairytale balls? Prepare to discover dawn alarms, double wigs, and real royal rebels across history!', 'Mislite da je biti princeza samo nositi krunu i plesati na balu? Pripremite se za istinu o ranom ustajanju, ogromnim perikama i pravim buntovnicama kroz istoriju!', '/covers/DP-1160.webp', '#c94b7a', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","funny","adventure"]', '["princesses","history","nonfiction","fashion","girl power"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('петронелла-и-темная-история-с--1161', 'DP-1161', 'Петронелла и темная история с цирком', 'Petronella and the Dark Circus Mystery', 'Petronela i mračna cirkuska tajna', 'Сабрина Штэндиг', 'Sabine Städing', 'Sabine Städing', '', 'Питер', 2018, '978-5-00116-112-7', 6, 16, 'middle', '', 'A traveling circus arrives near the quiet apple orchard, but unsettling secrets and strange happenings follow under the big top. Little apple witch Petronella and her twin friends, Lina and Luis, must investigate the curious artists and stop the mischief before opening night.', 'Putujući cirkus stiže blizu mirnog voćnjaka, ali pod njegovom šatrom kriju se neobične i mračne tajne. Mala vještica iz jabuke Petronela i njeni prijatelji blizanci, Lina i Luis, moraju da riješe zagonetku tajanstvenih cirkusanata prije premijere.', 'Загляните под купол загадочного цирка вместе с яблочной ведьмочкой Петронеллой — фокусы здесь точно не обошлись без настоящей магии!', 'Step under the mysterious big top with apple witch Petronella — where circus tricks might just turn into real magic!', 'Zavirite pod šatru tajanstvenog cirkusa sa malom vješticom Petronelom — ovdje trikovi kriju pravu magiju!', '/covers/DP-1161.webp', '#3b2354', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","spooky"]', '["circus","witch","mystery","friendship","magic"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('красный-камень-1162', 'DP-1162', 'Красный камень', 'The Red Stone', 'Crveni kamen', 'Лита Ли', 'Lita Lee', 'Lita Li', '', '', NULL, NULL, 6, 16, 'middle', '', 'An intriguing guide into the fascinating world of the red stone, revealing its secrets, hidden powers, and captivating wonders for curious young explorers.', 'Fascinantan vodič kroz tajanstveni svijet crvenog kamena, koji otkriva njegove tajne, skrivene moći i uzbudljiva čuda za radoznale mlade istraživače.', 'Готовы разгадать все секреты и скрытую мощь загадочного красного камня?', 'Ready to unlock the secrets and hidden power waiting inside the mysterious red stone?', 'Jeste li spremni da otkrijete sve tajne i skrivenu moć zagonetnog crvenog kamena?', NULL, '#b22222', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","real"]', '["science","minerals","guide","discovery","geology"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('продавец-туманов-1163', 'DP-1163', 'Продавец туманов', 'The Fog Seller', 'Prodavac magle', 'Резная свирель', 'Reznaya Svirel', 'Reznaja svirel', '', 'Миф', NULL, NULL, 6, 16, 'middle', 'Эта книга как чашка горячего чая в промозглый день, как шерстяной плед для продрогшего городского мечтателя. Волшебные стихи-заклинания, философские притчи с теплыми и уютными акварельными иллюстрациями. Все самое необходимое холодной осенью и снежной зимой: чай с печеньками, простые истины, душевные книги, теплый плед, запах груш и мандаринов, дождь по стеклу, сказки и чудеса, тиканье часов в вечерней тишине, шепот далеких морей и корабли, плывущие над крышей.', 'This book feels like a hot cup of tea on a chilly day, a woolen blanket tucked around a daydreaming wanderer. Inside are magical spell-poems and thoughtful parables adorned with warm watercolor illustrations. It holds all the best cures for gray autumns and snowy winters: tea with cookies, gentle truths, the scent of pears and tangerines, rain pattering on window glass, distant ocean whispers, and ships floating right over the rooftops.', 'Ova knjiga je poput šolje toplog čaja u prohladnom danu, poput vunenog ćebeta za prozeblog gradskog sanjara. Magične pjesme-čini i tople parabole upotpunjene su prijatnim akvarelima. Sve što vam treba za jesenje i zimske večeri: čaj s keksom, jednostavne istine, miris krušaka i mandarina, dobošavanje kiše o prozor, bajke i brodovi koji plove iznad krovova.', 'Закутайтесь в плед, налейте чашку какао и приготовьтесь вдыхать сказки, пахнущие осенним дождем и волшебством.', 'Wrap yourself in a cozy blanket, pour some cocoa, and get ready to breathe in fairy tales scented with autumn rain and wonder.', 'Ušuškajte se u toplo ćebe, skuvajte kakao i prepustite se bajkama koje mirišu na jesenju kišu i čaroliju.', '/covers/DP-1163.webp', '#547185', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic"]', '["cozy reads","parables","poetry","fairy tales","autumn"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чик-чак-1164', 'DP-1164', 'Чик-чак', 'Chik-Chak', 'Čik-Čak', 'Елена Репетур', 'Elena Repetur', 'Jelena Repetur', '', 'Белая ворона', NULL, NULL, 6, 16, 'middle', '«Началось лето, и я больше не могу играть в бэтмена. Очень жарко. Под костюмом все потеет, и я через минуту его снимаю. Пришлось придумать своего героя. Теперь я Чик Чак — это на иврите «быстро». У меня только шорты и майка. Я быстро летаю и знаю разные языки, и у меня куча таких же супергеройских друзей. Злодеи тоже есть, но мы их каждый день побеждаем». Как перестать бояться и найти друзей, когда переезжаешь в новую страну? Особенно если кругом все говорят на чужом языке. Выход один — придется стать супергероем! Но для этого потребуется загадать желание, набраться терпения и, конечно, иногда смотреть мультики. Это история о больших подвигах маленького супергероя, который живет с мамой и папой в доме на горе и мечтает выучить все языки.', '"Summer has started, and I can''t play Batman anymore. It''s way too hot. I sweat under the costume, so I have to take it off right away. I had to invent my own hero. Now I am Chik-Chak—which means ''quickly'' in Hebrew!" How do you stop feeling scared and make new friends when moving to a brand-new country where everyone speaks an unfamiliar language? There''s only one way out: you have to become a superhero! A tender and funny autobiographical story about moving abroad, courage, and dreaming of speaking every language in the world.', '„Počelo je ljeto i više ne mogu da se igram Betmena. Previše je vruće, pa odmah skinem kostim. Zato sam morao da izmislim sopstvenog heroja. Sada sam Čik-Čak — što na hebrejskom znači ''brzo''!" Kako pobijediti strah i pronaći drugare kad se preseliš u novu zemlju u kojoj svi govore nepoznat jezik? Rješenje je samo jedno — moraš postati superheroj! Dirljiva i duhovita priča o prilagođavanju novom domu, hrabrosti i dječaku koji sanja da nauči sve jezike svijeta.', 'Идеальное и очень смешное руководство по покорению новых стран, языков и жаркого лета в одних шортах и майке!', 'The ultimate witty guide for young superheroes on conquering new countries, languages, and scorching summers in just shorts and a t-shirt!', 'Savršen i duhovit vodič za male superheroje o tome kako osvojiti novu zemlju, nepoznat jezik i vrelo ljeto u šortsu i majici!', '/covers/DP-1164.webp', '#f2994a', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","friends","funny"]', '["relocation","superheroes","languages","friendship","summer"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('папа-мама-8-детей-в-дании-1165', 'DP-1165', 'Папа, мама, 8 детей в Дании', 'Father, Mother, and Eight Children in Denmark', 'Tata, mama i osmoro djece u Danskoj', 'Анне- Кат. Вестли', 'Anne-Cath. Vestly', 'Anne-Kat. Vestli', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Помните замечательную книжку "Папа, мама, бабушка, восемь детей и грузовик"? Ну так вот: теперь у вас в руках новый сборник увлекательных повестей о дружном и весёлом семействе, в котором ни минуты не бывает тихо. Норвежская писательница Анне-Катрине Вестли, придумавшая истории про дом, где растут сразу восемь мальчиков и девочек, популярна во всей Европе, наверное, не меньше, чем знаменитая Астрид Линдгрен. Герои её книг - люди простые, но очень симпатичные: добрые, честные, трудолюбивые. Взрослые здесь не теряют умения относиться с юмором к себе самим и друг к другу, какие бы уроки ни преподносила им жизнь. А главное, они удивительно хорошо понимают своих детей и сохраняют это понимание, что бы те ни натворили и что бы ещё ни напридумывали.', 'Pack your bags and hop on board with Father, Mother, Grandma, and all eight lively kids on an unforgettable holiday trip to Denmark! Full of warmth, gentle humor, and boundless family affection, this delightful classic by Norwegian author Anne-Cath. Vestly proves that even with eight children and never a quiet minute, any adventure is wonderful when shared together.', 'Spakujte kofere i pođite sa tatom, mamom, bakom i osmoro živahnih mališana na nezaboravno ljetnje putovanje u Dansku! Puna topline, nježnog humora i bezuslovne porodične ljubavi, ova omiljena priča norveške književnice Anne-Kat. Vestli dokazuje da je, čak i kad u kući nikad nema tišine, svaka avantura čarobna kad smo na okupu.', 'Пристегните ремни: дружное семейство из десяти человек и неутомимая бабушка отправляются в путь, где смех звучит громче шума любого мотора!', 'Fasten your seatbelts: a bustling family of ten plus one energetic grandma are hitting the road, and the giggles are guaranteed to drown out the engine!', 'Vežite pojaseve: vesela desetočlana porodica i neumorna baka kreću na putovanje đe je smijeh glasniji od svakog motora!', '/covers/DP-1165.webp', '#e26d5c', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","adventure","real"]', '["family","travel","scandinavia","humor","childhood"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('серебряное-копытце-1166', 'DP-1166', 'Серебряное копытце', 'Silver Hoof and Other Ural Tales', 'Srebrno kopito i druge bajke', 'П. П. Бажов', 'Pavel Bazhov', 'Pavel Bažov', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Волшебные сказы Павла Бажова — это удивительные истории, в которых простые люди встречаются с могучими властителями поземных богатств. Великий Полоз, Медной горы Хозяйка, голубая змейка могут испытать человека, чтобы увидеть его душу. Недобрые люди будут наказаны, а чистые сердцем — вознаграждены.', 'Pavel Bazhov''s magical Ural tales are wondrous stories where ordinary folk cross paths with the mythical guardians of hidden mountain riches. The Mistress of the Copper Mountain, the Great Snake, and the Blue Serpent test human nature to reveal true intentions: the greedy meet their ruin, while the honest and kind-hearted are generously rewarded with wonders.', 'Čarobne priče Pavla Bažova sa Urala divne su pripovijetke u kojima se obični ljudi susrijeću s moćnim čuvarima podzemnih bogatstava. Gospodarica Bakarne gore, Veliki Poloz i Plava zmija iskušavaju ljude kako bi otkrili njihovu suštinu: pohlepni bivaju kažnjeni, a oni čistog srca nagrađeni blagom.', 'Уютные сказы о самоцветах, душевной щедрости и волшебном козлике, от удара копытца которого в снегу загораются драгоценные камни!', 'Cozy up with these timeless Ural folk tales full of sparkling gemstones, kind hearts, and a legendary goat that taps out jewels with its hoof!', 'Ušuškajte se uz ove bezvremenske uralske bajke pune svjetlucavih dragulja, dobrote i čarobnog jelena koji kopitom rasipa drago kamenje!', '/covers/DP-1166.webp', '#1d6b52', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","animals","adventure"]', '["fairy tales","folklore","gemstones","nature","classics"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('смешные-рассказы-о-школьниках-1167', 'DP-1167', 'Смешные рассказы о школьниках', 'Funny Stories About Schoolchildren', 'Smiješne priče o školarcima', '', 'Various Authors', 'Grupa autora', '', 'Росмэн', NULL, NULL, 6, 16, 'middle', 'В этой книге собраны веселые рассказы В. Голявкина, А. Раскина, В. Драгунского, И. Пивоваровой и Ю. Сотника о школе и школьниках. Герои этих рассказов на собственном примере доказывают, что школа — это не только учеба и оценки, но и настоящая дружба, взаимовыручка и, конечно, всевозможные забавные происшествия.', 'This vibrant collection brings together hilarious classic tales by V. Golyavkin, A. Raskin, V. Dragunsky, I. Pivovarova, and Y. Sotnik. Through their mischievous antics, the young heroes prove that school is far more than just lessons and homework—it is about true friendship, quick wits, and endless comical misadventures.', 'Ova zbirka donosi vesele priče V. Goljavkina, A. Raskina, V. Dragunskog, I. Pivovarove i J. Sotnika o školi i đačkom životu. Junaci ovih priča dokazuju da škola nisu samo časovi i ocjene, već i pravo prijateljstvo, međusobno pomaganje i pregršt urnebesnih dogodovština.', 'Идеальное лекарство от школьной скуки — порция классических юмористических историй о проделках у доски и на переменках!', 'The ultimate cure for classroom boredom—a hilarious dose of classic school pranks, blackboard blunders, and recess chaos!', 'Savršen lijek protiv đačke dosade — vesela doza klasičnih nestašluka, odgovaranja pred tablom i smijeha na velikom odmoru!', '/covers/DP-1167.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","friends","real"]', '["school","humor","short stories","friendship","classics"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рассказы-люси-синицыной-учениц-1168', 'DP-1168', 'Рассказы Люси Синицыной, ученицы 3 класса', 'Stories of Lucy Sinitsyna, Third Grader', 'Priče Ljusje Sinicine, učenice trećeg razreda', 'Ирина Пивоварова', 'Irina Pivovarova', 'Irina Pivovarova', '', 'Росмэн', NULL, NULL, 6, 16, 'middle', 'В этой книге собраны смешные и трогательные истории из жизни третьеклассницы Люси Синицыной. Люся — жизнерадостная, озорная девчонка, которая любит петь, прыгать по лужам и делать «секретики». Ей ничего не стоит перевоспитать хулигана, устроить большую стирку или сочинить безумное послание для лучшей подруги прямо на уроке. В общем, с Люсей не соскучишься!', 'A collection of hilarious and heartwarming stories about third-grader Lucy Sinitsyna. Lucy is a cheerful, mischievous girl who loves singing, jumping into puddles, and burying secret treasures. Whether she is reforming a school bully, tackling a mountain of laundry, or writing silly notes to her best friend during class, life with Lucy is never boring!', 'Ova zbirka donosi duhovite i dirljive priče iz života učenice trećeg razreda Ljusje Sinicine. Ljusja je vedra i nestašna djevojčica koja voli da pjeva, skače po baricama i pravi tajna skrovišta. Bilo da prevaspitava školskog mangupa, organizuje veliko pranje veša ili piše šašave poruke najboljoj drugarici nasred časa, uz Ljusju nikada nije dosadno!', 'Приготовьтесь хохотать в голос — неугомонная Люся докажет, что обычные школьные будни куда увлекательнее любого шпионского детектива!', 'Get ready to laugh out loud—mischievous Lucy proves that everyday school life is far more entertaining than any spy thriller!', 'Spremite se za glasan smijeh — nestašna Ljusja dokazuje da obični školski dani mogu biti uzbudljiviji od bilo koje špijunske avanture!', '/covers/DP-1168.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","friends","real"]', '["школа","дружба","юмор","рассказы","детство"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('поки-1169', 'DP-1169', 'Поки', 'The Pokus', 'Poki', 'Эдгар Вальтер', 'Edgar Valter', 'Edgar Valter', '', '', NULL, NULL, 6, 16, 'middle', '"Поки" - это сказка о забавных лесных человечках, одетых в кафтанчики из травы, испокон веков живущих в тенистом влажном подлеске. Гармоничные отношения с природой и её обитателями - таков лейтмотив этой доброй сказки. За вклад в национальную культуру Э. Вальтер награждён эстонским Орденом Белой Звезды третьей степени.', '"The Pokus" is an enchanting tale about gentle, curious forest creatures dressed in tufts of grass who have lived in the mossy wetlands since time immemorial. Celebrating life in harmony with nature and all living things, this heartwarming Estonian classic brings the tranquil magic of the wild forest directly into your hands.', '„Poki“ je čarobna priča o neobičnim, dobrim šumskim stvorenjima odjevenim u travnate kaputiće, koja od pamtivijeka žive u sjenovitoj šumi. Sklad sa prirodom i njenim stanovnicima glavna je poruka ove tople estonske bajke pune mudrosti, nježnosti i ljubavi prema divljem svijetu.', 'Познакомьтесь с милейшими травяными человечками, которые научат вас слушать шёпот леса и замечать чудеса прямо под ногами!', 'Meet the coziest grass-cloaked creatures who will teach you how to listen to the forest whisper and discover tiny wonders under your boots!', 'Upoznajte najdraža travnata bića koja će vas naučiti kako da osluškujete šapat šume i primijetite čuda pod nogama!', '/covers/DP-1169.webp', '#4b7a47', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","friends","animals"]', '["nature","forest","estonia","folklore","kindness"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большой-тылль-1170', 'DP-1170', 'Большой тылль', 'Big Tõll', 'Veliki Tol', 'Андрус Кивиряхк', 'Andrus Kivirähk', 'Andrus Kivirehk', '', '', NULL, NULL, 6, 16, 'middle', 'Жил когда-то давно на Сааремаа Большой Тылль — островной богатырь и властелин. Он и ростом был намного выше других, и силы у него было побольше. Природа Сааремаа была сурова, и люди, которые там жили, были суровые и сильные. Они спокойно трудились — пахали землю и ловили в море рыбу. У Тылля был злой и опасный враг — Нечистый. Он никогда не упускал случая навредить Тыллю.', 'Once upon a time on the island of Saaremaa lived Big Tõll, a giant hero and ruler of the island. Taller and mightier than anyone else, he watched over his hardworking people as they ploughed the rugged land and fished the stormy seas. But Tõll had a cunning and dangerous foe—the Evil One, who never missed a chance to cause trouble.', 'Nekada davno na ostrvu Sarema živio je Veliki Tol — otočki div, zaštitnik i vladar. Bio je mnogo viši od drugih i neuporedivo snažniji. Priroda Sareme bila je surova, a ljudi koji su tamo živjeli bili su istrajni i hrabri, obrađujući zemlju i pecajući na moru. Ipak, Tol je imao lukavog i opasnog neprijatelja — Nečastivog, koji nikada nije propuštao priliku da mu naudi.', 'Величественная и атмосферная северная легенда о великане-защитнике с огромным сердцем и несокрушимой силой.', 'A stirring Nordic legend about an island-protecting giant with an enormous heart and unmatched strength.', 'Moćna nordijska legenda o divu-zaštitniku velikog srca koji čuva svoje ostrvo i prkosi zlim silama.', '/covers/DP-1170.webp', '#334e68', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","magic"]', '["folklore","giants","legends","estonia","mythology"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('голубая-бусинка-1171', 'DP-1171', 'Голубая бусинка', 'The Blue Bead', 'Plava perlica', 'Мария Людвика Крюгер', 'Maria Krüger', 'Marija Kriger', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Семья восьмилетней Каролинки переезжает в новую квартиру. Пока взрослые собирают и выносят вещи, девочка случайно находит на полу, в щели, маленькую голубую бусинку. Да не простую, а волшебную – бусинка исполняет любые желания! Так и начинаются невероятные приключения Каролинки и ее верного друга Пётрека: они летают по воздуху, превращаются в невидимок, оживляют деревянную Бабу Ягу и каменных львов, воюют со злой колдуньей Филоменой... Но число желаний, которые может исполнить голубая бусинка, ограничено, и друзья учатся отличать пустяковые забавы от вещей важных и стоящих. “Голубая бусинка”- первая часть знаменитой дилогии Марии Крюгер (1904 – 1999).', 'Eight-year-old Karolcia finds a small blue bead tucked in a floorboard crack during her family''s move. To her astonishment, it grants any wish! Together with her loyal friend Piotr, Karolcia dives into thrilling adventures—flying through the air, turning invisible, and outsmarting the wicked witch Filomena. But because the bead''s magical power is limited, the children must learn what truly matters most.', 'Tokom selidbe u novi stan, osmogodišnja Karolinka u pukotini poda pronalazi malu plavu perlicu koja ispunjava sve želje! Zajedno sa svojim vjernim drugom Pjotrom, ona se upušta u nevjerovatne avanture: lete kroz vazduh, postaju nevidljivi i nadmudruju zlu vješticu Filomenu. Ipak, čarolija perlice nije beskrajna, pa djeca uče kako da razlikuju prolazne hirove od onoga što je zaista važno.', 'Заветная мечта каждого ребёнка — найти бусинку, исполняющую желания, главное — вовремя понять, что действительно стоит загадать!', 'Every kid''s dream comes true with a wish-granting bead—if only Karolcia and Piotr can figure out what''s truly worth wishing for!', 'Ostvarenje sna svakog djeteta je čarobna perlica koja ispunjava želje, samo treba otkriti šta je zaista važno poželjeti!', '/covers/DP-1171.webp', '#3478c6', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","friends"]', '["wishes","magic","friendship","adventures","classic"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лу-чепуховый-дневник-1172', 'DP-1172', 'Лу! чепуховый дневник', 'Lou! Secret Diary', 'Lu! Otkačeni dnevnik', 'Жюльен Нель', 'Julien Neel', 'Žilijen Nel', '', 'Самокат', NULL, NULL, 6, 16, 'middle', '"Лу! Чепуховый дневник" - первый том суперпопулярной во Франции серии рисованных историй про 12-тилетнюю девчушку Лу и ее маму. Книги про Лу издаются в разных странах мира уже 15 лет, 8 томов комикса вышли общим тиражом больше трех миллионов экземпляров! Эти истории стали и мультсериалом, и фильмом (с Людивин Санье, звездой французского кино, в роли мамы). И всё благодаря тому, что в героях комикса и дети, и подростки, и взрослые могут узнать себя!', '''Lou! Secret Diary'' is the opening volume of the smash-hit French graphic novel series about 12-year-old Lou and her creative, quirky mom. For over fifteen years, Lou''s adventures have captivated millions of readers worldwide, inspiring both an animated series and a feature film. Packed with humor and heartfelt honesty, it''s a story where kids, teens, and grown-ups will effortlessly recognize themselves.', '„Lu! Otkačeni dnevnik“ je prvi tom izuzetno popularnog francuskog strip-serijala o dvanaestogodišnjoj djevojčici Lu i njenoj neobičnoj mami. Knjige o Lu osvajaju čitaoce širom svijeta već 15 godina, prodate su u više od tri miliona primjeraka i pretočene u animiranu seriju i film. U ovim toplim i duhovitim pričama i djeca, i tinejdžeri i roditelji lako mogu prepoznati sebe!', 'Остроумная, живая и невероятно уютная графическая история о взрослении, первой влюбленности и самой лучшей (хоть и слегка чудаковатой) маме на свете.', 'A witty, vibrant, and utterly charming graphic novel about growing up, secret crushes, and having the coolest (and quirkiest) mom around.', 'Duhovit, topao i neodoljivo šarmantan strip o odrastanju, prvim simpatijama i najkul (i pomalo blesavoj) mami na svijetu.', '/covers/DP-1172.webp', '#e8566d', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","friends","real"]', '["comics","graphic novel","growing up","family","friendship"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('кот-нок-по-имени-гав-и-другие--1173', 'DP-1173', 'Котёнок по имени Гав и другие сказки', 'A Kitten Named Woof and Other Stories', 'Mače po imenu Vau i druge bajke', 'Г. Остер', 'Grigory Oster', 'Grigorij Oster', '', 'Малыш', NULL, NULL, 6, 16, 'middle', 'В этой книге много маленьких зверушек. Самый удивительный среди них — котёнок по имени Гав. Наверное, тот, кто его так назвал, хотел посмеяться. А вместо этого наградил его уравновешенным, смелым характером. Пока взрослые кошки и собаки ссорятся и воруют еду друг у друга, щенок и котёнок вместе играют и обедают одной сосиской пополам. Именно это и называется дружбой. В книгу вошли другие сказки для малышей Григория Остера.', 'Meet the most charming characters in children''s literature, led by an extraordinary kitten named Woof. While grown-up cats and dogs bicker, kitten Woof and puppy Sharik share sausages, explore the attic, and figure out why troubles should be met head-on. This delightful collection by Grigory Oster celebrates pure kindness, clever humor, and unconditional friendship.', 'Upoznajte najdraža stvorenja dječije književnosti na čelu sa neobičnim mačetom po imenu Vau. Dok se odrasle mačke i psi svađaju, mače i štene dijele jednu viršlu napola, istražuju tavan i hrabro idu u susret nevoljama jer ih ''tamo već čekaju''. Ova topla zbirka priča Grigorija Ostera slavi iskrenu dobrotu, bezazlen humor i pravo prijateljstvo.', 'Учит делиться сосисками ровно пополам и не бояться неприятностей, если они уже ждут тебя на чердаке!', 'A tender, timeless reminder that sausages taste better shared and fears are much easier faced together on the attic stairs.', 'Predivna priča koja nas uči da je viršla najslađa kad se podijeli napola i da se nevolja ne treba bojati kad imaš pravog druga.', '/covers/DP-1173.webp', '#e67e34', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["friends","animals","funny"]', '["kitten","friendship","puppy","classic","kindness"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('привидение-из-монастыря-пирита-1174', 'DP-1174', 'привидение из монастыря пирита', 'The Ghost of Pirita Convent', 'Duh iz manastira Pirita', 'Хелен Кяйт', 'Helen Käit', 'Helen Kejt', '', '', NULL, NULL, 6, 16, 'middle', 'Книга известной эстонской детской писательницы понравится любителям страшных историй. Особенно она придётся по душе тем, кто хоть раз задумывался, здорово ли было бы встретить настоящее привидение. Ведь столкнуться с потусторонним явлением – это одновременно жутко и интересно! А ещё лучше, если привидение будет обитать в старом доме, в разрушенном замке или, как в этой книге, в подземелье монастыря.', 'This thrilling tale by the renowned Estonian children''s author is a treat for fans of spooky stories. It is especially captivating for anyone who has ever wondered what it would be like to encounter a real ghost. Meeting the supernatural is both spine-chilling and utterly fascinating—especially when that ghost haunts the deep, shadowy dungeons of an ancient ruined convent.', 'Ova uzbudljiva priča poznate estonske autorke za djecu oduševiće ljubitelje tajanstvenih priča. Posebno će se dopasti onima koji su se ikada zapitali kako bi bilo sresti pravog duha. Susret sa natprirodnim je istovremeno jeziv i neodoljivo zanimljiv — naročito kada taj duh obitava u mračnim podzemnim hodnicima drevnog manastira.', 'Загляните в древние монастырские руины, если не боитесь щекочущих нервы шорохов и загадок из прошлого!', 'Step into the ancient convent ruins if you''re daring enough for spine-tingling whispers and secrets from the past!', 'Zavirite u drevne manastirske ruševine ako se ne bojite tajanstvenih šapata i zagonetki iz prošlosti!', '/covers/DP-1174.webp', '#3f4756', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["spooky","adventure","magic"]', '["ghosts","mystery","ruins","spooky stories","estonia"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книжный-вор-1175', 'DP-1175', 'Книжный вор', 'The Book Thief', 'Kradljivica knjiga', 'Маркус Зусак', 'Markus Zusak', 'Markus Zusak', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Январь 1939 года. Германия. Страна, затаившая дыхание. Никогда еще у смерти не было столько работы. А будет еще больше. Мать везет девятилетнюю Лизель Мемингер и ее младшего брата к приемным родителям под Мюнхен, потому что их отца больше нет - его унесло дыханием чужого и странного слова "коммунист", и в глазах матери девочка видит страх перед такой же судьбой. В дороге смерть навещает мальчика и впервые замечает Лизель. Так девочка оказывается на Химмель-штрассе - Небесной улице. Кто бы ни придумал это название, у него имелось здоровое чувство юмора. Не то чтобы там была сущая преисподняя. Нет. Но и никак не рай. "Книжный вор" - недлинная история, в которой, среди прочего, говорится: об одной девочке; о разных словах; об аккордеонисте; о разных фанатичных немцах; о еврейском драчуне; и о множестве краж. Это книга о силе слов и способности книг вскармливать душу. Экранизирован в 2013 году.', 'January 1939, Nazi Germany. Amidst looming catastrophe, Death narrates the life of nine-year-old Liesel Meminger on Himmel Street near Munich. In an era of fear and loss, Liesel discovers the transformative power of words, secretly stealing books and sharing them with her foster father, neighbors, and the Jewish fist-fighter hiding in their basement. A monumental and deeply moving novel about survival, friendship, and the enduring beauty of stories.', 'Januar 1939. godine, nacistička Njemačka. Devetogodišnja Lizel Meminger stiže kod hranitelja u Ulicu Himel nadomak Minhena. Usred siromaštva, straha i nadolazećeg rata, djevojčica otkriva spasonosnu moć knjiga i počinje da ih krade, dijeleći riječi sa svojim novim ocem i jevrejskim boksereom koji se skriva u njihovom podrumu. Dirljiva priča koju pripovijeda sama Smrt — oda ljudskosti i nepobjedivom duhu.', 'Пронзительная история, рассказанная самой Смертью, которая доказывает: слова и книги способны спасти душу даже в самые темные времена.', 'A breathtaking story narrated by Death itself, proving that the love of books can keep humanity alive in the darkest of times.', 'Potresna priča koju pripovijeda sama Smrt, podsjećajući nas na iscjeljujuću moć knjiga u najmračnijim vremenima.', '/covers/DP-1175.webp', '#4a3e3d', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","friends"]', '["wwii","books","friendship","courage","historical"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мистика-моря-1176', 'DP-1176', 'Мистика моря', 'Mysteries of the Sea', 'Misterije mora', 'Эдгар Аллан По', 'Edgar Allan Poe', 'Edgar Alan Po', '', 'Аркадия', NULL, NULL, 6, 16, 'middle', 'Море, прекрасная, грозная, неукротимая стихия, и люди, которые все же рискуют бросить ей вызов - отчаянные, способные противостоять любой сверхъестественной силе, - очаровывали признанного мастера "мрачного" романтизма Эдгара Аллана По еще в детстве. Мальчиком писатель с упоением слушал байки и леденящие кровь предания моряков, которые заходили по делам к его приемному отцу, а позже, опираясь на собственные впечатления, создал пропитанные мистикой и мрачным юмором произведения, которые вошли в этот сборник.', 'The sea, a beautiful, menacing, and untamable element, alongside the daring souls who dare to challenge it, fascinated the master of dark romanticism Edgar Allan Poe since childhood. As a young boy, he hung on every word of sailors'' eerie yarns visiting his foster father''s office. Later in life, weaving personal maritime impressions with spine-chilling folklore, Poe penned these legendary tales drenched in supernatural mystery and dark humor.', 'More, divlja i opasna stihija, kao i odvažni mornari koji se usuđuju da joj se suprotstave, očaravali su majstora mračnog romantizma Edgara Alana Poa još od najranijeg djetinjstva. Kao dječak slušao je ledene mornarske priče u luci, a kasnije ih pretvorio u nezaboravne pripovijetke prožete misterijom, morskim dubinama i specifičnim crnim humorom sabrane u ovom izdanju.', 'Загляните в штормовые бездны вместе с королём мистики — мурашки и солёный привкус морских легенд гарантированы!', 'Dive into tempestuous abysses with the master of mystery himself—spine-chilling nautical adventures guaranteed!', 'Zavirite u olujne morske dubine s majstorom jeze — čekaju vas nezaboravne avanture i mornarske legende!', '/covers/DP-1176.webp', '#1b3644', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","spooky"]', '["sea","gothic","classic tales","shipwrecks","legends"]', 1792836322701, 1792845716175);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вес-лый-новый-год-1177', 'DP-1177', 'весёлый Новый год', 'A Merry New Year', 'Vesela Nova godina', 'Альф Прёйсен', 'Alf Prøysen', 'Alf Prejsen', 'Владимир Сутеев', 'Мелик-Пашаев', NULL, NULL, 6, 16, 'middle', 'Альф Прёйсен – норвежский писатель, поэт, композитор – написал великое множество песен, стихов и сказок для детей. Сказка в стихах «Весёлый Новый год» – это уютный сказочный мирок дружного семейства мышей, которые живут в норке на чердаке. Добрая и весёлая сказка легко читается и быстро запоминается. А еще она необыкновенно хорошо иллюстрирована гениальным художником Владимиром Сутеевым. Мышиное жилище и семейные отношения нарисованы с великой любовью к деталям: генеральная предпраздничная уборка, скакалки, бантики, мышки-игрушки на верёвочке, ссора из-за кусочка колбаски, развешанные после стирки штанишки, платьица и маечки многочисленной мышиной детворы, ночной горшочек из ореховой скорлупы, заботливые мыши-родители и мудрая мышь-бабушка, сидящая на качалке-картофелине, и много-много других милых подробностей мышиного быта. Рекомендуется для чтения взрослыми детям-дошкольникам, а также для совместного рассматривания картинок.', 'Alf Prøysen, the beloved Norwegian author and poet, invites readers into the coziest miniature world of a cheerful mouse family living in an attic burrow. Told in catchy verse and brought to life by Vladimir Suteev''s classic, expressive illustrations, this festive tale brims with delightful domestic details—from holiday housecleaning and walnut-shell pots to a grandmother rocking on a potato. A perfect holiday treasure for cozy family read-alouds and picture spotting.', 'Alf Prejsen, proslavljeni norveški pisac i pjesnik, stvorio je u stihovima ugodan bajkoviti svijet o složnoj mišjoj porodici koja živi u skrovištu na tavanu. Ova vesela priča, obogaćena bezvremenskim ilustracijama Vladimira Sutejeva, osvaja neodoljivim detaljima iz mišje svakodnevice: od prednovogodišnjeg spremanja i ljuljaške od krompira do noćne noše od orahove ljuske. Divna knjiga za zajedničko čitanje i posmatranje raskošnih crteža sa najmlađima.', 'Загляните в самую уютную мышиную норку на чердаке — здесь Новый год встречают с ореховыми скорлупками, танцами и морем тепла!', 'Peek into the coziest mouse hole in the attic, where New Year is celebrated with nutshells, joyful dances, and boundless warmth!', 'Zavirite u najtopliju mišju rupu na tavanu, gdje se Nova godina dočekuje uz orahove ljuske, veseli ples i pregršt topline!', '/covers/DP-1177.webp', '#b94336', 'nonfiction', 'ru', 'available', '0+', '["animals","funny","friends"]', '["mice","new year","poetry","winter","family"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('малыши-чистят-зубы-1178', 'DP-1178', 'Малыши чистят зубы', 'Toddlers Brush Their Teeth', 'Mališani peru zube', 'Елена Ульева', 'Elena Ulyeva', 'Elena Uljeva', '', 'Клевер', NULL, NULL, 6, 16, 'middle', 'Елена Ульева - знаменитый педагог, автор детских книг, изданных совокупным тиражом 3 миллиона экземпляров. Её эффективная методика легла в основу серии книг о развитии самостоятельности у малыша. Серия "Самостоятельный малыш" поможет вашему ребёнку сформировать необходимые навыки: поучительные сказки обеспечат необходимую мотивацию, а красочные иллюстрации создадут положительный настрой. Эта книга научит вашего малыша: - следить за своими зубками - не бояться осмотра у стоматолога - слушаться взрослых Взрослых книга научит договариваться с детьми играя.', 'Elena Ulyeva is a renowned educator and author whose books help children build essential independence skills. From the ''Independent Toddler'' series, this book turns everyday tooth brushing into an engaging game with uplifting fairy tales and vibrant illustrations. It teaches little ones to care for their pearly whites, visit the dentist without tears, and helps parents turn daily hygiene routines into stress-free bonding moments.', 'Elena Uljeva je poznata pedagoškinja i autorka čije knjige podstiču razvoj samostalnosti kod mališana. Iz serijala „Samostalni mališan“, ova slikovnica pretvara pranje zubića u zabavnu igru kroz poučne priče i šarene ilustracije. Pomaže djeci da zavole njegu zuba i oslobode se straha od zubara, a roditeljima pruža nježne smjernice za uspostavljanje zdravih navika kroz igru.', 'Прощайте, утренние слёзы в ванной: эта книга превратит чистку зубов и поход к стоматологу в весёлую игру!', 'Say goodbye to bathroom bedtime battles: this charming book turns tooth brushing and dentist visits into an easy, playful ritual!', 'Zaboravite na jutarnje muke u kupatilu — uz ovu priču pranje zubića i odlazak zubaru postaju omiljena dječja igra!', '/covers/DP-1178.webp', '#5bb5a2', 'nonfiction', 'ru', 'available', '0+', '["real","funny"]', '["гигиена","чистка зубов","полезные привычки","здоровье"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('такие-разные-бабушки-1179', 'DP-1179', 'Такие разные бабушки', 'Grandmas Are So Different', 'Tako različite bake', 'Маркелова Н.Е.', 'Natalia Markelova', 'Natalija Markelova', '', 'Мещерякова', NULL, NULL, 6, 16, 'middle', 'В детстве мы мечтаем стать врачами, моряками или космонавтами. А вот Леночка мечтает стать бабушкой, ведь её бабушка — настоящая добрая фея! Какие ещё бывают бабушки и что за волшебство они хранят у себя в карманах в книге Натальи Маркеловой «Такие разные бабушки». Тёплые и солнечные иллюстрации Марии Коротаевой.', 'As children, we often dream of becoming doctors, sailors, or astronauts. But little Lena dreams of becoming a grandma, because her own grandmother is a real kind fairy! Discover the many kinds of grandmas and the gentle magic hidden in their pockets in Natalia Markelova''s heartwarming book, brought to life with sunny illustrations by Maria Korotaeva.', 'Kao djeca maštamo da postanemo ljekari, mornari ili astronauti. Ali malena Lena mašta da postane baka, jer je njena baka prava dobra vila! Saznajte kakve sve bake postoje i kakvu čaroliju kriju u svojim džepovima u toploj knjizi Natalije Markelove, sa sunčanim ilustracijama Marije Korotajeve.', 'Уютная и добрая ода всем бабушкам на свете — после прочтения немедленно захочется обнять свою бабулю или позвонить ей!', 'A cozy and heartwarming tribute to grandmothers everywhere — after reading it, you''ll immediately want to call yours for a big hug!', 'Topla i nježna priča posvećena svim bakama svijeta — nakon čitanja poželjećeš odmah da zagrliš svoju baku!', '/covers/DP-1179.webp', '#e89d67', 'nonfiction', 'ru', 'available', '6+', '["real","magic"]', '["grandmothers","family","love","childhood","kindness"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('благородные-хулиганы-из-2-а--1180', 'DP-1180', 'Благородные хулиганы из 2 "А"', 'The Noble Pranksters of Class 2-A', 'Plemeniti vragolani iz 2. "A"', 'Маркелова Н.Е.', 'Natalya Markelova', 'Natalija Markelova', '', 'Мещерякова', NULL, NULL, 6, 16, 'middle', 'Все знают, что бывают благородные разбойники. А существуют ли благородные хулиганы? Ответ на этот вопрос — в книге Натальи Маркеловой. Нас ждёт новая встреча с любимыми героями — Мишкой Курочкиным, Светой Иванкиной и другими замечательными ребятами. Они стали на год взрослее и теперь учатся во 2 классе, но по-прежнему верят в чудеса, приключения и крепкую дружбу.', 'Everyone has heard of noble bandits, but can pranksters be noble too? Second-graders Mishka, Sveta, and their classmates prove that lively mischief and warmhearted loyalty go hand in hand as they navigate school life, everyday adventures, and true friendship.', 'Svi znaju za plemenite razbojnike, ali da li postoje plemeniti vragolani? Drugaci Miška, Sveta i njihovo društvo dokazuju da nemirni nestašluci i iskrena dobrota mogu da idu zajedno, dok proživljavaju nezaboravne školske dane pune prijateljstva i smijeha.', 'Приготовьтесь хохотать: эти второклашки наглядно докажут, что доброе сердце и озорные проделки — идеальное сочетание!', 'Get ready to laugh out loud: these second-graders prove that a knack for mischief and a heart of gold make the ultimate team!', 'Spremite se za smijeh: ovi drugaci dokazuju da nestašluci i veliko toplo srce idu savršeno ruku pod ruku!', '/covers/DP-1180.webp', '#e07a38', 'nonfiction', 'ru', 'available', '6+', '["funny","friends","real"]', '["school stories","friendship","humor","classmates","childhood"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('к-доске-пойд-т-василькин-школь-1181', 'DP-1181', 'К доске пойдёт… Василькин! Школьные истории Димы Василькина, ученика 3 «А» класса', 'To the Board Goes... Vasilkin! School Stories of Dima Vasilkin, Third Grader', 'Pred tablu će... Vasiljkin! Školske priče Dime Vasiljkina, učenika 3. „A” razreda', 'Виктория Ледерман', 'Victoria Lederman', 'Viktorija Lederman', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', '«Дети должны быть умнее своих родителей», – повторяла мама. А у меня не получается быть умнее! Вот и тройка в четверти затесалась, по русскому. Портит колонку четвёрок и пятёрок! Несправедливо: я же хорошо пишу, однажды вот сочинил целую книжку про шуструю обезьянку. А потом ещё рассказ про то, как я потерял ранец. И про ужасный, противный день рождения Лизы Комаровой. И ещё, ещё… Ладно, обо всём по порядку! Меня зовут Дима Василькин, я учусь в третьем «А» и постоянно попадаю в смешные истории. Не все они, правда, сразу кажутся смешными – как, например, когда мы с Костиком застряли у него дома до самой ночи. Но всё равно я такие случаи люблю – рассказывать их потом одно удовольствие! А не люблю я только это: «К доске пойдёт… Василькин!» – слова, которые наша учительница Светлана Алексеевна говорит каждый день. Вот за что? Неужели мне без этого «к доске» мало приключений! Посудите сами!', 'Dima Vasilkin is an ordinary third-grader who has a knack for finding extraordinary adventures—or rather, trouble. Between accidentally getting a ''C'' on his report card, surviving a classmate''s awful birthday party, and getting trapped at a friend''s house until late at night, Dima''s life is never dull. The only phrase that truly terrifies him every single day is: ''To the board goes... Vasilkin!'' A witty, touching, and relatable collection of school mishaps.', 'Dima Vasiljkin ide u treći razred i stalno upada u smiješne i neobične zgode. Bilo da pokušava da popravi neočekivanu trojku, preživi grozan rođendan drugarice iz klupe ili ostane zaključan kod druga do kasno u noć — Dimi nikada nije dosadno. Jedino čega se istinski plaši jeste ona čuvena rečenica koju učiteljica ponavlja svakog dana: „Pred tablu će... Vasiljkin!”', 'Искренние и уморительные школьные хроники, в которых каждый узнает свои эпичные провалы и победы у доски!', 'A hilarious and heartwarming peek into third grade where every day at school turns into an unforgettable adventure!', 'Urnebesne i tople školske priče u kojima će svaki đak prepoznati sopstvene nestašluke i strah od prozivanja pred tablu!', '/covers/DP-1181.webp', '#e58226', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","friends","real"]', '["school stories","elementary school","humor","friendship","childhood"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ума-палата-детский-фразеологич-1182', 'DP-1182', 'Ума палата. Детский фразеологический словарь', 'Sharp as a Tack: Children''s Idiom Dictionary', 'Bistra glava: Dječji frazeološki rječnik', 'Рогалева, Никитина', 'Elena Rogaleva, Tatiana Nikitina', 'Elena Rogaljeva, Tatjana Nikitina', '', 'Мещерякова', NULL, NULL, 6, 16, 'middle', 'Фразеологизмы (устойчивые сочетания слов) делают нашу речь богаче, а жизнь интереснее! Детский фразеологический словарь "Ума палата" поможет ребенку узнать смысловое значение каждого оборота, а также подскажет, в каком случае данный фразеологизм можно употреблять, а в каком совсем неуместно. После прочтения книги ребенок уже не будет смотреть на доску как баран на новые ворота и дрожать как осиновый лист на уроках русского языка и уж тем более никогда не станет нести околесицу. Фразеологический словарь "Ума палата" вышел в серии нон-фикшн для детей "Пифагоровы штаны". Это третье издание книги ИД Мещерякова, дизайн для которого полностью обновлен. В книге много увлекательных заданий на проверку усвоенного материала.', 'Idioms make speech richer and everyday conversations far more entertaining! This engaging children''s phraseological dictionary helps young readers uncover the true meanings behind popular sayings and shows exactly when and how to use them. Packed with witty explanations and interactive exercises, this book turns language study into an exciting game where no one ever has to feel at a loss for words.', 'Frazeologizmi čine govor bogatijim, a svakodnevnu komunikaciju mnogo zanimljivijom! Ovaj dječji frazeološki rječnik pomaže mladim čitaocima da otkriju pravo značenje slikovitih izraza i nauče kada ih je prikladno upotrijebiti. Uz duhovita objašnjenja i zabavne zadatke za provjeru znanja, savladavanje jezičkih tajni postaće prava igra.', 'Остроумный и яркий путеводитель по крылатым выражениям, после которого в карман за словом точно лезть не придётся!', 'A lively, clever guide to idioms that ensures young readers will never be at a loss for words!', 'Duhovit i živopisan vodič kroz frazeme uz koji mališani više nikada neće ostati bez pravih riječi!', '/covers/DP-1182.webp', '#d97724', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","real"]', '["idioms","language","nonfiction","vocabulary","education"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('асино-лето-1183', 'DP-1183', 'Асино лето', 'Asya''s Summer', 'Asino ljeto', 'Тамара Михеева', 'Tamara Mikheeva', 'Tamara Mihejeva', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Семейка ветров живёт на Летней эстраде. Королевский уж, исполняющий желания, обосновался под крыльцом первого корпуса. А сколько удивительных существ населяют соседний лес! Ася познакомилась с ними сразу: в тот день, когда команда Кольки Огурцова в пух и прах разнесла сборную Наташки Ястровой. Ася, она же Прасковья Шустова, футбол и прочие игры не любит: гномы Севка, Горыныч и Ёж - вот с кем ей по-настоящему интересно! В летнем лагере девочка впервые, и всё ей в новинку: кто тут негласный лидер и почему, как общаться с толпой незнакомых детей, какие тайны хранят старые чердаки. "Светлячок", где когда-то отдыхала ещё Асина бабушка, не скучает никогда: здесь ссорятся и мирятся, влюбляются и расстаются, ходят на дискотеки и рассказывают страшилки. Постепенно и сама героиня подпадает под обаяние места - не без помощи магических лесных существ. Их помощь понадобится ей ещё раз: Коле, с которым Ася так подружилась, срочно понадобится редчайшее лекарство… Повесть Тамары Михеевой за несколько переизданий превратилась в настоящую детскую классику.', 'A family of winds lives on the outdoor stage, a wish-granting royal snake slithers under the cabin porch, and magical gnomes hide in the surrounding forest. Shy Asya is at summer camp for the first time, learning how to make friends, tell ghost stories, and find her place among loud peers. When her new friend Kolya falls gravely ill and needs an impossible cure, Asya embarks on a wondrous quest guided by camp spirits. A warm, nostalgic classic full of sun, pine needles, and childhood wonder.', 'Porodica vjetrova živi na ljetnjoj pozornici, kraljevska bjelouška koja ispunjava želje krije se ispod trema, a čudesni patuljci vrebaju u gustoj šumi. Asja je prvi put u ljetnjem kampu, gdje uči kako da sklopi prijateljstva, priča strašne priče i snađe se među nepoznatom djecom. Kada se njen drugar Kolja iznenada razboli, Asja uz pomoć šumskih bića kreće u potragu za čudotvornim lijekom. Topla i nostalgična priča o odrastanju, borovim šumama i snazi pravog prijateljstva.', 'Тёплая, пахнущая соснами и земляникой сказка о настоящей лагерной смене, где искренняя дружба творит самое настоящее волшебство.', 'A warm, pine-scented camp adventure proving that true friendship and a sprinkle of forest magic can work real miracles.', 'Topla ljetnja priča koja miriše na borove iglice i dokazuje da pravo prijateljstvo uz malo šumske magije čini čuda.', '/covers/DP-1183.webp', '#3d8b57', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","friends","adventure"]', '["summer camp","friendship","magic","nature","adventures"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вилли-1184', 'DP-1184', 'Вилли', 'Willy', 'Vili', 'Нина Дашевская', 'Nina Dashevskaya', 'Nina Daševskaja', '', 'КомпасГид', NULL, NULL, 6, 16, 'middle', 'Детство — это такое время, когда в жизни каждого появляется что-нибудь волшебное. У кого-то — говорящий велосипед, у кого-то — заброшенная великанская деревня, у кого-то — подружка, очень-очень высокая девочка, которая печёт самое вкусное печенье. Вот и у Севки, главного героя повести Нины Дашевской «Вилли», всё это есть. Он, как и все дети, мечтает о настоящей дружбе, верит в чудеса, и они с ним обязательно случаются. То есть, конечно, случаются с ним не только чудеса, но Севка никогда не унывает. Он уверен: в итоге волшебство всегда берёт верх над любыми неурядицами! В повести «Вилли», на первый взгляд, много невероятного, но вообще-то всё как в жизни. Ведь это повесть о самом обычном мальчике, за которого переживаешь и радуешься, как за лучшего друга. Нина Дашевская — музыкант и писатель. Она играет на скрипке в оркестре Детского музыкального театра им. Н. И. Сац, а её книги успели стать любимыми во многих семьях. Нина Дашевская дважды становилась лауреатом Всероссийского конкурса на лучшее литературное произведение для детей и юношества «Книгуру» — за повесть «Скрипка неизвестного мастера» (2013) и сборник рассказов «Около музыки» (2014). В 2014 году повесть «Вилли» стала лауреатом премии В. Крапивина.', 'Childhood is a time when magic sneaks into everyone''s life. For some, it is a talking bicycle; for others, an abandoned village of giants; and for Sevka, it is all that plus a remarkably tall friend who bakes the most delicious cookies. Nina Dashevskaya’s award-winning novella ''Willy'' captures the heart of childhood—where ordinary days intertwine with quiet miracles, and optimism always triumphs over troubles. It is a tender, cozy story about an ordinary boy who quickly becomes your dearest friend.', 'Djetinjstvo je doba kada se u svačijem životu pojavi malo magije. Za nekoga je to bicikl koji govori, za nekoga napušteno džinovsko selo, a za dječaka Sevku sve to zajedno, uz prijateljicu koja peče najslađe kolačiće. Nagrađivana priča Nine Daševskaje „Vili“ slavi istinsko prijateljstvo i vjeru u čuda koja se uvek izbore s nevoljama. Iako puna nevjerovatnih obrta, ovo je topla i stvarna pripovijest o dječaku za koga navijate kao za najboljeg druga.', 'Если ваш велосипед пока не умеет разговаривать, эта светлая повесть научит слышать чудеса в самых обычных вещах вокруг!', 'If your bicycle hasn''t started talking to you yet, this heartwarming tale will teach you how to hear everyday miracles all around!', 'Ako vaš bicikl još uvijek ne priča, ova topla priča naučiće vas kako da oslušnete svakodnevna čuda oko sebe!', '/covers/DP-1184.webp', '#4a9ec5', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","friends","real"]', '["bicycle","friendship","growing up","childhood","magic realism"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('якоб-учится-общаться-10-истори-1185', 'DP-1185', 'Якоб учится общаться: 10 историй в 1 книге', 'Jakob Learns to Communicate: 10 Stories in 1 Book', 'Jakob uči da komunicira: 10 priča u jednoj knjizi', 'Сандра Гримм', 'Sandra Grimm', 'Sandra Grim', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Подходит для совместного чтения с родителями детям от трех лет. В сборник вошли следующие истории: Якоб играет в футбол Якоб ссорится с Конни Якоб говорит нет Якоб учит правила дорожного движения Якоб хочет стать пожарным Якоб злится Якоб на ферме Якоб на детской площадке Якоб и беговел Якоб всё делает сам', 'Perfect for shared family reading with young children. This heartwarming collection brings together ten relatable everyday stories about little Jakob: playing soccer, quarreling with his sister Conni, learning to say "no", discovering road safety, dreaming of becoming a firefighter, dealing with anger, visiting a farm, exploring the playground, riding a balance bike, and proudly doing things all on his own.', 'Savršena knjiga za zajedničko čitanje roditelja i djece. Ova topla zbirka objedinjuje deset poučnih svakodnevnih priča o malom Jakobu: o igranju fudbala, svađi sa sestrom Koni, učenju da kaže „ne“, saobraćajnim pravilima, snovima o vatrogascima, savladavanju ljutnje, posjeti farmi, igralištu, vožnji balans-bicikla i samostalnosti.', 'Добрый и очень жизненный путеводитель по первым детским эмоциям, спорам и победам — читайте и взрослейте дружно!', 'A warm, down-to-earth guide to early emotions, sibling squabbles, and little triumphs that makes growing up feel like teamwork!', 'Topao i životan vodič kroz prve dječije emocije, nesuglasice i pobjede — čitajte i rastite složno!', '/covers/DP-1185.webp', '#e57c23', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","friends"]', '["social skills","emotions","growing up","family reading","daily life"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лев-колдунья-и-платяной-шкаф-1186', 'DP-1186', 'Лев, колдунья и платяной шкаф', 'The Lion, the Witch and the Wardrobe', 'Lav, vještica i ormar', 'Клайв Стейплз Льюис', 'C. S. Lewis', 'K. S. Luis', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Никто не знал, какую тайну хранит старый платяной шкаф, пока одной маленькой девочке не пришло в голову спрятаться среди шуб и зимних пальто. И тогда произошли удивительные события, открывшие миру чудесную страну — Нарнию. Что подают к чаю в гостях у фавнов? Как выглядит мир, в который никогда не приходит весна? Часто ли улыбаются великаны? Кто займёт четыре трона в главном дворце Кэр-Паравале? И сколько времени пройдёт на Земле, когда в Нарнии пролетит пятнадцать лет? Ответы на эти вопросы вы сможете не только прочитать в книге Клайва С. Льюиса «Лев, колдунья и платяной шкаф», но и увидеть, благодаря великолепным иллюстрациям современного британского художника Кристиана Бирмингема. Его работы не раз были отмечены престижными английскими премиями.', 'No one knew the secret kept inside the old wardrobe until a little girl decided to hide among the fur coats. What followed opened up the wondrous land of Narnia to our world. What do fauns serve for tea? What does a world trapped in perpetual winter look like? And how much earthly time passes while fifteen years slip by in Narnia? Discover C. S. Lewis''s timeless classic, brought to life with magnificent illustrations by acclaimed British artist Christian Birmingham.', 'Niko nije znao kakvu tajnu skriva stari ormar sve dok jednoj djevojčici nije palo na pamet da se sakrije među bunde i zimske kapute. Tada su započeli čudesni događaji koji su svijetu otkrili čarobnu zemlju — Narniju. Šta se služi za čaj kod fauna? Kako izgleda svijet u koji proljeće nikada ne stiže? Otkrijte bezvremeni klasik K. S. Luisa oživljen veličanstvenim ilustracijama nagrađivanog britanskog umjetnika Kristijana Birmingema.', 'Шагните сквозь старые шубы прямо в заснеженную Нарнию — только вежливо откажитесь от рахат-лукума, если угощает Белая Колдунья!', 'Step right through the fur coats into snowy Narnia — just remember to politely decline Turkish delight from mysterious queens!', 'Zakoračite kroz stare bunde pravo u snježnu Narniju — samo nikada ne prihvatajte ratluk od sumnjivih kraljica!', '/covers/DP-1186.webp', '#2c5270', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","magic","friends"]', '["narnia","fantasy","winter","talking animals","classic"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пеццетино-1187', 'DP-1187', 'Пеццетино', 'Pezzettino', 'Pezzettino', 'Лео Лионни', 'Leo Lionni', 'Leo Lioni', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Все вокруг Пеццетино совершают смелые поступки. Но он - простой маленький кусочек (pezzetino ведь так и переводится с итальянского - "кусочек"). Пеццетино решает, что он должен стать частью чего-то, принадлежать чему-то большему. Но ему удается совершить великое открытие: он принадлежит самому себе! Для дошкольного и младшего школьного возраста.', 'Everyone around Pezzettino is big, daring, and capable of amazing feats, making him wonder whose missing piece he must be. But an adventurous journey across the sea brings him to a liberating discovery: he doesn''t belong to anyone else, he is completely himself!', 'Svi oko Pecetina su veliki, hrabri i rade čudesne stvari, pa on vjeruje da je samo nečiji izgubljeni djelić. Ipak, putovanje preko mora vodi ga do predivnog saznanja: on ne pripada nikome drugom, već je sasvim potpun i svoj!', 'Мудрая и трогательная притча о том, что каждый из нас — не чей-то потерянный кусочек, а совершенно самостоятельное чудо.', 'A tender, philosophical gem reminding every reader that you don''t need to fit into someone else to be wonderfully whole.', 'Mudra i topla priča koja nas podsjeća da nismo ničiji djelić, već cjelovito i samostalno čudo.', '/covers/DP-1187.webp', '#e0632b', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","real"]', '["самопознание","индивидуальность","философская сказка","поиски себя","классика"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('побеждаю-страхи-1188', 'DP-1188', 'Побеждаю страхи', 'Conquering Fears', 'Pobjeđujem strahove', 'Елена Ульева', 'Elena Ulyeva', 'Jelena Uljeva', '', 'clever', NULL, NULL, 6, 16, 'middle', 'Через сказку про милого хамелеона ваш малыш узнает, как бороться с самыми распространенными страхами.', 'Through a gentle fairy tale about an adorable chameleon, young readers will learn practical and reassuring ways to tackle common childhood fears.', 'Kroz bajku o simpatičnom kameleonu, mališani će naučiti kako da se hrabro i mirno suoče sa najčešćim dječijim strahovima.', 'Добрый хамелеон научит менять не только цвет, но и отношение к темноте, монстрам и другим детским страхам!', 'A sweet little chameleon shows kids that courage isn''t about having no fears, but learning how to paint over them with confidence!', 'Simpatični kameleon naučiće djecu da se strahovi tope čim ih bolje upoznamo i razumijemo!', '/covers/DP-1188.webp', '#52a36b', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["animals","real"]', '["emotions","fears","animals","fairy tale therapy","growing up"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('подарок-1189', 'DP-1189', 'Подарок', 'The Present', 'Poklon', 'Аня Доброчасова', 'Anya Dobrochasova', 'Anja Dobročasova', '', 'ИДМ', NULL, NULL, 6, 16, 'middle', 'Близится 8 Марта. Вовка готовится поздравить сестру и маму, а вся семья готовится поздравить… Вовку! Только Вовка не сразу обрадовался своему празднику. Ему потребуется волшебный ключик, чтобы понять кое-что важное. Для младшего школьного возраста.', 'March 8th is right around the corner! Little Vovka is busy preparing surprises for his mother and sister, unaware that the whole family is secretly planning to celebrate... Vovka himself! At first, he isn''t thrilled about this unexpected turn of events, but a little magic key will help him unlock something truly important about love and family.', 'Bliži se 8. mart. Vovka se sprema da obraduje sestru i mamu, dok se čitava porodica krišom sprema da iznenadi... samog Vovku! Vovka se u početku nimalo ne raduje svom prazniku, ali biće mu potreban čarobni ključić kako bi shvatio nešto zaista važno.', 'Уютная и добрая весенняя история о Вовке и Хвостике, которая напоминает: лучший подарок — это внимание тех, кого мы любим.', 'A cozy, heartwarming spring tale about Vovka and his family that reminds us the sweetest gift is the care of those we love.', 'Topla i nježna proljećna priča o Vovki i njegovoj porodici koja nas podsjeća da je najljepši dar pažnja onih koje volimo.', '/covers/DP-1189.webp', '#e07a5f', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","friends","funny"]', '["family","holidays","spring","kindness","brothers and sisters"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('апельсин-1190', 'DP-1190', 'Апельсин', 'The Orange', 'Narandža', 'Аня Доброчасова', 'Anya Dobrochasova', 'Anja Dobročasova', '', 'ИДМ', NULL, NULL, 6, 16, 'middle', 'К Новому году! У Вовки было целых три Новых года, которые он прекрасно помнил. А сейчас, накануне четвёртого, праздничное настроение, приятная суета, красивая ёлка, подарки - всё было для Вовки под большим вопросом. Но чудеса иногда можно найти даже в старом шкафу с одеждой…', 'Just in time for New Year! Vovka clearly remembered three past celebrations. But now, on the eve of his fourth, festive joy, pleasant bustle, a glittering tree, and gifts are all up in the air. Yet holiday miracles can sometimes hide even inside an old coat closet...', 'Uoči Nove godine! Vovka se savršeno sjećao svoja tri prethodna dočeka. Ali sada, pred četvrti, praznično raspoloženje, ugodna gužva, okićena jelka i pokloni — sve je dovedeno u pitanje. Ipak, čuda se ponekad mogu pronaći čak i u starom ormaru s kaputima...', 'Трогательная новогодняя история о том, как одна сочная оранжевая магия способна вернуть праздник в дом.', 'A heartwarming New Year''s tale showing how a single burst of citrus magic can bring holiday joy back home.', 'Dirljiva novogodišnja priča o tome kako malo citrusne čarolije može vratiti prazničnu radost u dom.', '/covers/DP-1190.webp', '#e87722', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","real"]', '["new year","family","winter","holidays","childhood"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лунный-жук-1191', 'DP-1191', 'Лунный жук', 'The Moon Beetle', 'Mjesečeva buba', 'Аня Доброчасова', 'Anya Dobrochasova', 'Anja Dobročasova', 'ИДМ', 'ИДМ', NULL, NULL, 6, 16, 'middle', 'Оказавшись поздним вечером на пруду в валенках и шапке старшего брата, Соня, а точнее сказать - Хвостик, так её называла вся семья, с горькой обидой поняла, как плохо убегать из дома! Чтобы исправиться и не повторять ошибок, Хвостик с братом Вовкой решаются на крайнюю меру - идут в армию! Для младшего школьного возраста.', 'Finding herself late in the evening at the pond wearing her older brother''s oversized felt boots and winter hat, little Sonya—better known to her family as ''Tail''—realizes with bitter regret just how terrible running away from home really is. Determined to redeem herself and build iron discipline, Tail and her brother Vovka take drastic action: they decide to join the army! A warm and humorous story about sibling camaraderie for early school age.', 'Našavši se kasno uveče pored ribnjaka u prevelikim valjenkama i kapi starijeg brata, mala Sonja — koju porodica od milja zove Repić — sa gorkim kajanjem shvata koliko je loša ideja pobjeći od kuće. Kako bi se popravili i ojačali karakter, Repić i njen brat Vovka odlučuju se na krajnji korak: stupaju u pravu pravcatu armiju! Dirljiva i duhovita priča o bratsko-sestrinskim avanturama.', 'Трогательная и очень смешная история о братско-сестринском союзе, в котором даже побег на пруд заканчивается маршем в строю!', 'A tender and hilarious tale of sibling teamwork, proving that running away in oversized boots is best solved by enlisting in the ''army'' together!', 'Dirljiva i beskrajno duhovita priča o bratu i sestri koji dokazuju da se svaka nevolja najlakše prevazilazi zajedničkim vojničkim maršem!', '/covers/DP-1191.webp', '#2c4365', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","friends","real"]', '["siblings","family","humor","growing up","childhood"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('book-1192', 'DP-1192', '', 'Shaggy Happiness', 'Čupava sreća', 'Лохматое счастье', 'Elena Stepanova', 'Elena Stepanova', 'Елена Степанова', 'Энас', NULL, NULL, 6, 16, 'middle', 'Многие дети мечтают о самом настоящем лохматом счастье, которое умеет гавкать или мяукать, вилять хвостом, будить поутру и, конечно, шалить. О котёнке или щеночке! Специально для таких детей Елена Степанова и сочинила целую книжку, полную мурлыканья, гавканья, проказ и смешных историй. А нарисовала четвероногих героев и их друзей замечательная художница Любовь Ерёмина-Ношин. Для чтения взрослыми детям.', 'Many children dream of true, shaggy happiness that can bark or meow, wag its tail, wake you up in the morning, and, of course, get into all sorts of mischief. Elena Stepanova wrote an entire collection full of purring, barking, funny antics, and playful tales, delightfully illustrated by Lyubov Eryomina-Noshin.', 'Mnoga djeca maštaju o pravoj čupavoj sreći koja zna da laje ili mauče, maše repom, budi rano ujutru i, naravno, pravi nestašluke. Elena Stepanova je napisala divnu zbirku punu predenja, lajanja, nestašluka i smiješnih priča, koju je toplo ilustrovala Ljubov Jerjomina-Nošin.', 'Трогательные и озорные истории о щенках и котятах, которые мгновенно растопят сердце любого начинающего собаковода или кошатника!', 'Heartwarming and mischievous stories about puppies and kittens that will instantly charm any young animal lover!', 'Dirljive i vesele priče o štencima i mačićima koje će osvojiti srce svakog malog ljubitelja životinja!', '/covers/DP-1192.webp', '#e07a38', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["animals","friends","funny"]', '["pets","dogs","cats","humor","family reading"]', 1792836322701, 1792845716176);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-я-завидую-1193', 'DP-1193', 'Когда я завидую', 'When I Feel Jealous', 'Kad osjećam zavist', 'Корнелия Спилман', 'Cornelia Maude Spelman', 'Kornelija Spelman', '', 'Питер', NULL, NULL, 6, 16, 'middle', 'Медвежонок рассказывает о ситуациях, которые заставляют его завидовать: когда кто-то получает то, чего он хотел, или когда другой привлекает к себе внимание окружающих. Но главный герой находит способы справиться со своими переживаниями. Ваш малыш может научиться этому, слушая книгу и рассматривая картинки.', 'A little bear talks about everyday moments that make him feel jealous—like when someone else gets what he wanted or steals the spotlight—and discovers gentle, healthy ways to navigate those tricky feelings.', 'Mali medvjedić priča o situacijama u kojima osjeća zavist: kada neko dobije ono što je on želio ili kada privuče pažnju drugih, ali otkriva nježne i razumne načine kako da se izbori s tim teškim osjećanjima.', 'Тёплая и бережная подсказка для тех дней, когда зелёный червячок зависти вдруг решает пошептаться на ушко!', 'A gentle, comforting guide for those moments when the little green monster of jealousy decides to whisper in your ear!', 'Nježan i mudar vodič za one dane kada se u srcu probudi mali crv zavisti i zatraži razumijevanje.', '/covers/DP-1193.webp', '#7da038', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["animals","real"]', '["эмоции","психология","зависть","медвежонок","взросление"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-я-тревожусь-1194', 'DP-1194', 'Когда я тревожусь', 'When I Feel Worried', 'Kad sam zabrinut', 'Корнелия Спилман', 'Cornelia Maude Spelman', 'Kornelija Mod Spilman', '', 'Питер', NULL, NULL, 6, 16, 'middle', 'Дети часто волнуются, когда оказываются в новых или сложных ситуациях. Обычно они не знают как себя вести, когда кто-то на них сердится. Научите вашего малыша справляться с тревогой и быть уверенным в себе. Читайте книгу вместе и рассматривайте картинки. Для родителей даны рекомендации, что делать в трудном случае. Для детей младше 6 лет.', 'Children often feel anxious when facing new or challenging situations, or when someone is upset with them. This gentle, reassuring picture book helps little ones understand anxiety, build confidence, and discover healthy ways to cope, complete with practical guidance for parents.', 'Djeca se često brinu kada se nađu u novim ili teškim situacijama, ili kada se neko ljuti na njih. Ova nježna slikovnica pomaže mališanima da razumiju osjećaj zabrinutosti, steknu samopouzdanje i nauče kako da se umire, uz korisne savjete za roditelje.', 'Тёплая и бережная книга-обнимашка, которая мягко объяснит малышу, что тревожиться — это нормально, и научит справляться со страхами.', 'A comforting paper hug that reassures little worriers that big feelings pass and they are never alone.', 'Topao i nježan zagrljaj u obliku knjige koji mališanima poručuje da je sasvim u redu osjećati brigu i uči ih kako da je prevaziđu.', '/covers/DP-1194.webp', '#4a89a4', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","animals"]', '["emotions","anxiety","feelings","mental health","coping skills"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-я-грущу-1195', 'DP-1195', 'Когда я грущу', 'When I Feel Sad', 'Kada sam tužan', 'Корнелия Спилман', 'Cornelia Spelman', 'Kornelija Spilman', '', 'Питер', NULL, NULL, 6, 16, 'middle', 'Эта книга поможет вашим детям научиться сохранять уверенность в себе даже в сложных для них ситуациях. Морская свинка и ее друзья покажут, как справляться с трудностями, не теряя присутствия духа и уверенности в себе. Ваш малыш получит большое удовольствие, слушая книгу и рассматривая картинки.', 'This tender book helps children understand and accept sadness as a natural feeling. Through the story of a sweet guinea pig and her friends, young readers learn gentle, practical ways to cope with tough emotions and stay confident when things go wrong.', 'Ova topla knjiga pomaže djeci da razumiju svoja osjećanja i sačuvaju samopouzdanje čak i u izazovnim trenucima. Kroz priču o morskom prasetu i njegovim prijateljima, mališani uče kako da se nose sa tugom, uz divne ilustracije koje donose utjehu.', 'Даже самым смелым иногда нужно погрустить, и эта уютная книжка с морской свинкой подскажет, как бережно обнять свои чувства!', 'Even the bravest among us feel down sometimes, and this comforting story with a sweet guinea pig shows how to treat our feelings with kindness!', 'Čak i najhrabriji ponekad osjete tugu, a ova nježna slikovnica sa morskim prasetom uči nas kako da s ljubavlju zagrlimo svoja osjećanja!', '/covers/DP-1195.webp', '#5b84b1', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["animals","friends","real"]', '["emotions","feelings","sadness","guinea pig","empathy"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-чудес-1196', 'DP-1196', 'Книга чудес', 'A Wonder-Book for Girls and Boys', 'Knjiga čuda', 'Натаниэль Готорн', 'Nathaniel Hawthorne', 'Natanijel Hotorn', '', 'ИДМ', NULL, NULL, 6, 16, 'middle', 'В поместье Тэнглвуд стоит детский смех - это студент Юстас Брайт рассказывает свои удивительные истории! Как раздобыть летающие сандалии и победить ужасную Горгону? Откроет ли таинственный ящик любопытная девчонка Пандора? Кто такой Атлант и почему небо не падает? В "Книге чудес для девочек и мальчиков" - шесть захватывающих историй от мастера американской литературы Натаниэля Готорна, который всегда полагал, что большинство античных мифов могут стать занимательным чтением для детей - нужно только правильно их пересказать. Для среднего школьного возраста. Книга издана вне серии. Лакированные элементы на обложке с эффектом песка; издание с ляссе (ленточкой-закладкой). Продолжением "Книги чудес" являются "Тэнглвудские истории" Н. Готорна.', 'At Tanglewood estate, laughter rings out as student Eustace Bright entertains children with astonishing retellings of classical Greek myths. How can one find flying sandals to slay Medusa? What happens when curious Pandora opens the mysterious box? And why doesn''t the sky fall on Atlas''s shoulders? Nathaniel Hawthorne brings six timeless legends to life with humor, warmth, and magical wonder, making ancient myths unforgettable for young readers.', 'Na imanju Tenglvud odjekuje dječiji smijeh dok student Justas Brajt pripovijeda čarobne priče iz grčke mitologije. Kako nabaviti krilate sandale i pobijediti Gorgonu? Šta će se desiti kada radoznala Pandora otvori misterioznu kutiju? Natanijel Hotorn je šest drevnih mitova pretvorio u uzbudljivo i toplo štivo koje oživljava antičke legende na najljepši mogući način.', 'Загляните в древнегреческие мифы глазами великого классика — здесь чудовища повержены, а чудеса оживают на каждой странице!', 'Discover timeless Greek myths reimagined as enchanting adventures full of flying sandals, monsters, and playful wonder!', 'Zavirite u antičke mitove ispričane na čaroban način, gdje krilate sandale i neobična bića vode u nezaboravne avanture!', '/covers/DP-1196.webp', '#c47a38', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure"]', '["greek myths","mythology","legends","classics","ancient greece"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебный-короб-финские-народн-1197', 'DP-1197', 'Волшебный короб. Финские народные сказки', 'The Magic Chest: Finnish Folk Tales', 'Čarobna kutija: Finske narodne bajke', '', 'Finnish Folk Tales', 'Finske narodne bajke', 'илл. Тамара Юфа, Маргарита Юфа', 'Речь', NULL, NULL, 6, 16, 'middle', 'Сюжеты многих финских сказок связаны с мореплаванием, что логично для страны, имеющей давние морские пути. Другие истории повествуют о земледельцах, охотниках и рыболовах, третьи - о принцах и принцессах, четвёртые - о животных. Некоторые сюжеты читателю покажутся знакомыми, например, по карельским или западноевропейским сказкам. На это Унелма Конкка отвечала: "Чем больше мы читаем сказок разных стран, тем чаще убеждаемся в том, что большая часть их принадлежит народам всего мира. Но эта схожесть касается лишь сюжета сказки, её скелета. Каждый народ придаёт обще­известному сюжету своеобразную, неповторимую форму. В сказке отражаются история, психология, условия жизни и другие особенности данного народа". На русский язык сказки перевёл живущий в Финляндии писатель Арви Пертту. Проиллюстрировали сборник известные карельские художницы Тамара и Маргарита Юфа. Текст печатается по изданию: Волшебный короб: финские народные сказки. - Петрозаводск: Карелия, 1993. В книге использованы изображения произведений из фондов БУ "Музей изобразительных искусств Республики Карелия" Для младшего школьного возраста.', 'A rich treasury of Finnish folklore featuring sea-faring voyagers, crafty hunters, woodland beasts, and magical charms. Translated with heart and illuminated by the celebrated Karelian artists Tamara and Margarita Yufa, this collection reveals how universally beloved folktale motifs acquire a unique, northern soul woven from lakes, forests, and maritime winds.', 'Bogata riznica finskog folklora donosi priče o neustrašivim pomorcima, snalažljivim lovcima, šumskim životinjama, prinčevima i čarolijama. Ilustrovana prepoznatljivim radovima čuvenih karelskih umjetnica Tamare i Margarite Jufe, ova zbirka otkriva kako univerzalni motivi bajki poprimaju jedinstven, sjevernjački duh protkan jezerima, beskrajnim šumama i morskim vjetrovima.', 'Откройте этот волшебный сундучок, чтобы почувствовать свежий северный бриз, услышать шепот древних лесов и разгадать мудрость финских сказок!', 'Open this magical chest to catch a crisp Nordic breeze, listen to the whisper of ancient pines, and discover timeless northern wisdom!', 'Otvorite ovu čarobnu kutiju da osjetite svježi sjeverni vjetar, čujete šapat drevnih šuma i otkrijete bezvremenu mudrost finskih bajki!', '/covers/DP-1197.webp', '#2b5b64', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["magic","adventure","animals"]', '["fairy tales","folklore","finland","magic","legends"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('про-жика-и-медвежонка-1198', 'DP-1198', 'Про ёжика и медвежонка', 'About Hedgehog and Bear Cub', 'O Ježiću i Medvjediću', 'Сергей Козлов', 'Sergei Kozlov', 'Sergej Kozlov', 'Евгений Антоненков', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Замечательный сказочник Сергей Козлов - автор смешных и трогательных историй о Ёжике и Медвежонке. Эти неразлучные друзья давно перебрались со страниц книжек в кадры мультфильмов, которые знает и любит любой ребёнок: "Ёжик в тумане", "Трям! Здравствуйте!", "Зимняя сказка", "Осенние корабли". В этом сборнике вы найдёте лучшие сказки про Ёжика, Медвежонка и их друзей. Иллюстрации к этой книге нарисовал замечательный художник Евгенией Антоненков. Его Ёжик и Медвежонок такие трогательные и славные, что с ними захочется подружиться любому малышу. Евгенией Антоненков - участник различных международных выставок, обладатель диплома "Книга года" (2008). В 2009 и 2010 годах художник был номинирован на международную премию Астрид Линдгрен. Для дошкольного и младшего школьного возраста.', 'Sergei Kozlov is the beloved author of touching and gentle tales about Hedgehog and Little Bear, famous from timeless animations like ''Hedgehog in the Fog''. This cozy collection brings together poetic forest adventures celebrating loyalty, wonder, and simple joys, paired with dreamy illustrations by award-winning artist Evgeny Antonenkov.', 'Sergej Kozlov je čuveni autor dirljivih i nježnih priča o Ježiću i Medvjediću, ovjekovječenih u kultnim crtanim filmovima poput ''Jež u magli''. Ova topla zbirka donosi najljepše šumske bajke o odanosti, radoznalosti i iskrenom prijateljstvu, obogaćene čarobnim ilustracijama Evgenija Antonenkova.', 'Заварите чай с можжевеловыми веточками и приготовьтесь считать звёзды вместе с самыми нежными друзьями на свете.', 'Brew a cup of herbal tea and get ready to count falling stars with the gentlest woodland best friends ever written.', 'Skuvajte topao čaj i pripremite se za brojanje zvijezda sa najnježnijim šumskim prijateljima na svijetu.', '/covers/DP-1198.webp', '#c88242', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["friends","animals","magic"]', '["friendship","forest tales","bedtime stories","classics","kindness"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-приручить-дракона-1199', 'DP-1199', 'Как приручить дракона', 'How to Train Your Dragon', 'Kako dresirati zmaja', 'Крессида Коуэлл', 'Cressida Cowell', 'Kresida Kauel', '', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Если вы вдруг не знаете, то в старину у каждого уважающего себя викинга был свой дракон. Другие народы использовали в качестве домашних животных собак, лошадей и прочую скотину. А викинги - драконов. Но для начала юный викинг должен был поймать своего дракона, что само по себе не просто. А потом - приручить его. Что еще сложнее. Все вместе называется - испытание драконьим воспитанием. Того, кто его не пройдет, изгоняют из племени. Когда Иккинг, сын вождя племени Лохматых Хулиганов и самый немускулистый юный викинг на острове Олух, отправился ловить своего дракона, он не надеялся, что пройти испытание будет легко. И не подозревал, что им с Беззубиком предстоит стать героями! Для детей среднего школьного возраста.', 'Long ago, every self-respecting Viking had to catch and train their own dragon—or face banishment from the tribe. Hiccup Horrendous Haddock III, the delightfully un-brawny son of the Hairy Hooligan chief, didn''t expect the dragon initiation test to be easy, especially when he ends up with Toothless: a tiny, stubborn dragon with no teeth at all. Together, this unlikely pair must find a way to become heroes.', 'Nekada davno, svaki vikinški ratnik koji drži do sebe morao je da uhvati i pripitomi sopstvenog zmaja — ili da se suoči sa progonstvom iz plemena. Štucko, bistar ali nimalo mišićav sin poglavice, nije očekivao da će ispit biti lak, naročito kada završi sa Bezubim: majušnim, tvrdoglavim zmajem bez ijednog zuba. Ipak, ovaj nesvakidašnji dvojac moraće da pokaže da pravo junaštvo leži u srcu i pameti.', 'Забудьте про мультик: в книге Беззубик крошечный, ужасно вредный и действительно без зубов, а приключения викингов полны уморительного хулиганства!', 'Forget the movie: in the book, Toothless is pint-sized, terribly cheeky, and truly toothless, making this hilarious Viking quest an absolute joy!', 'Zaboravite film: u knjizi je Bezubi sićušan, nevjerovatno svojeglav i stvarno krezav, a ova vikinška avantura je prepuna urnebesnih nestašluka!', '/covers/DP-1199.webp', '#2e6f40', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","funny","friends"]', '["vikings","dragons","friendship","humor","underdogs"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бабуля-бандюга-1200', 'DP-1200', 'Бабуля-бандюга', 'Gangsta Granny', 'Baka gangster', 'Дэвид Уольямс', 'David Walliams', 'Dejvid Valijams', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Проводить пятничный вечер у бабули – самое скучное занятие на свете! Так всегда думал Бен. Ему приходилось играть в старомодные настольные игры, есть капустный суп и слушать скучные бабушкины истории. Но однажды всё изменилось. А всё потому, что Бен узнал невероятный секрет! Оказывается, его бабуля вовсе не скучная старушка, а настоящая звезда криминального мира! За её плечами сотни ограблений! Она смелая, хитрая и клёвая! А ещё она мечтает ограбить саму королеву! Бен решает, что обязательно должен ей помочь. Получится ли у них осуществить этот дерзкий план? И какие ещё тайны скрывает бабуля? Дэвид Уолльямс – обладатель Британской национальной книжной премии, классик современной детской литературы, книги которого переведены более чем на 50 языков и продаются по всему миру многомиллионными тиражами. Истории Дэвида Уолльямса помогают преодолеть страхи и поверить в собственные силы. Тони Росс – всемирно известный иллюстратор, номинант на Премию им. Г.-Х. Андерсена. Для среднего школьного возраста.', 'Ben used to dread Friday nights at his granny''s house—it meant cabbage soup, boring Scrabble games, and endless boredom. But everything changes the day Ben discovers her secret biscuit tin filled with diamonds! It turns out his quiet granny is actually an international jewel thief known as the Black Cat, and she''s planning the most daring heist in British history: stealing the Crown Jewels. A hilarious and heartwarming adventure that proves grandmothers are full of surprises.', 'Ben je mislio da su petkovi kod bake najdosadnija stvar na svijetu: kupusna supa, starinske društvene igre i beskrajna tišina. Sve dok jednog dana u bakinoj kutiji za keks nije otkrio pravo blago! Ispostavlja se da njegova baka nije nimalo dosadna, već opasna međunarodna kradljivica dragulja koja planira najveću pljačku u istoriji — krađu krunskih dragulja. Urnebesna i dirljiva priča o tome kako bake nikada ne treba potcjenjivati.', 'Никогда не судите бабушку по её капустному супу: возможно, по ночам она планирует величайшее ограбление века!', 'Never judge a granny by her cabbage soup—she might just be plotting the greatest heist of the century!', 'Nikada ne sudite baki po njenoj kupusnoj supi: možda baš noću planira najveću pljačku vijeka!', '/covers/DP-1200.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["funny","adventure","real"]', '["grandma","heist","humor","family","cabbage"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('научные-открытия-2020-1201', 'DP-1201', 'Научные открытия 2020', 'Scientific Discoveries 2020', 'Naučna otkrića 2020', 'Илья Колмановский', 'Ilya Kolmanovsky', 'Ilja Kolmanovski', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Каждую неделю Илья звонит учёным из разных стран и расспрашивает их, как им удалось сделать открытие, что было труднее всего и что — самое интересное. В этой книге — самые яркие и неожиданные научные истории 2020 года.', 'Every week, Ilya calls scientists from around the world to find out how they made their breakthroughs, what challenged them the most, and what fascinated them. This book gathers the most vibrant and unexpected scientific stories of 2020.', 'Svake sedmice Ilja zove naučnike iz različitih zemalja i pita ih kako su došli do svojih otkrića, šta je bilo najteže, a šta najuzbudljivije. U ovoj knjizi sakupljene su najupečatljivije i najneočekivanije naučne priče iz 2020. godine.', 'Узнайте из первых уст, каково это — делать настоящие открытия на передовой мировой науки!', 'Get front-row seats to the world''s most thrilling breakthroughs straight from the scientists who made them!', 'Zavirite iza kulisa svjetskih laboratorija i saznajte kako se stvaraju stvarna naučna čuda!', '/covers/DP-1201.webp', '#2660a4', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["real","adventure"]', '["science","discoveries","scientists","curiosity","nonfiction"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-вомбат-1202', 'DP-1202', 'Я вомбат', 'I Am a Wombat', 'Ja sam vombat', 'Дмитрий Быков', 'Dmitry Bykov', 'Dmitrij Bikov', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'В далёкой Австралии обитает очень необычное животное по имени вомбат. Он немножко похож на медвежонка и совершенно не боится людей. Наша книжка поможет тебе познакомиться с этим удивительным зверем. Ты узнаешь, какие он строит себе норы, чем отличается сумка мамы-вомбата от сумки мамы-кенгуру, что общего у верблюда и вомбата… А ещё… Но, нет, не будем рассказывать. Лучше скорее открывай книжку!', 'In distant Australia lives a truly unusual creature named the wombat. Looking a bit like a chubby little bear cub, it is completely fearless around humans. This lively book introduces you to this amazing animal: discover the underground labyrinths they dig, how a wombat mother''s pouch differs from a kangaroo''s, and what wombats have in common with camels!', 'U dalekoj Australiji živi neobična i neodoljiva životinja po imenu vombat. Liči na malog medvjeda i nimalo se ne boji ljudi. Ova zanimljiva knjiga pomoći će ti da upoznaš ovog čudesnog stvora: saznaćeš kakve podzemne tunele kopa, po čemu se torba mame-vombata razlikuje od kengurove, i šta je to zajedničko kamili i vombatu!', 'Приготовьтесь влюбиться в самого милого австралийского крепыша, который копает гигантские туннели и оставляет за собой забавные кубики!', 'Get ready to fall in love with Australia''s most adorable chubby digger, who excavates vast underground palaces and leaves cubic surprises!', 'Spremite se da se zaljubite u najslađeg australijskog debeljuškastog kopača koji pravi prave podzemne dvorce!', '/covers/DP-1202.webp', '#b86b35', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["animals","funny","real"]', '["wombats","australia","wildlife","nature","zoology"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('путеводитель-по-зв-здному-небу-1203', 'DP-1203', 'Путеводитель по звёздному небу', 'A Cat''s Guide to the Night Sky', 'Vodič kroz zvjezdano nebo', 'Стюарт Аткинсон', 'Stuart Atkinson', 'Stjuart Atkinson', '', 'Аванта', NULL, NULL, 6, 16, 'middle', 'Если ты любишь смотреть на звёзды и мечтаешь узнать о планетах и космических объектах что-нибудь новенькое, эта книга как раз для тебя. Кот Счастливчик расскажет тебе всё, что знает сам: - что такое созвездие и астеризм, - чем осеннее небо отличается от летнего, весеннего или зимнего, - когда можно увидеть падающие звёзды, - почему Луна бывает молодой, прибывающей, убывающей и старой, - какие бывают затмения, - как отличить звезду от планеты, - что такое северное сияние, - какие существуют туманности, ...и ещё многое и многое другое! Готовься к приключениям и наблюдениям. Кот Счастливчик расскажет, в какую погоду и где можно делать наблюдения, чтобы увидеть многое, из того что он рассказывает, своими глазами.', 'If you love gazing at the stars and want to uncover the secrets of the cosmos, this book is for you! Lucky the cat will teach you all about constellations, seasonal night skies, meteor showers, moon phases, auroras, and nebulae, complete with practical tips on how and when to do your own stargazing.', 'Ako voliš da posmatraš zvijezde i maštaš o istraživanju svemira, ova knjiga je savršen izbor! Mačak Srećko otkriće ti sve tajne noćnog neba: šta su sazviježđa, kako razlikovati zvijezdu od planete, zašto Mjesec mijenja oblik i kada loviti zvijezde padalice, uz sjajne savjete za prave noćne posmatrače.', 'Берите тёплый плед, термос и эту книгу — очаровательный кот Счастливчик сделает вас настоящим знатоком ночного неба уже сегодня вечером!', 'Grab a cozy blanket, hot cocoa, and this book—clever cat Lucky will turn you into a certified backyard stargazer tonight!', 'Ponesite toplo ćebe, čaj i ovu knjigu — mudri mačak Srećko pretvoriće vas u prave astronome već večeras!', '/covers/DP-1203.webp', '#1d2d50', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","animals","real"]', '["astronomy","stargazing","space","cats","science"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чудеса-россии-1204', 'DP-1204', 'Чудеса России', 'Wonders of Russia', 'Čuda Rusije', 'Аванта', 'Avanta', 'Avanta', '', '', NULL, NULL, 6, 16, 'middle', 'В книге "Чудеса России" школьники познакомятся не только с удивительными местами нашей страны: горами, реками, равнинами, водопадами, озерами и пещерами, но и с прекрасными городами, доисторическими памятниками и культовыми зданиями, созданными людьми, живущими в разных уголках нашей большой родины.', 'In "Wonders of Russia," young explorers discover breathtaking natural landscapes—mountains, rivers, plains, waterfalls, lakes, and caves—alongside magnificent historic cities, prehistoric monuments, and cultural landmarks spread across this vast country.', 'U knjizi „Čuda Rusije“ mladi istraživači će otkriti nevjerovatne prirodne predjele — planine, rijeke, ravnice, vodopade, jezera i pećine — ali i predivne gradove, praistorijske spomenike i kultne građevine rasprostranjene širom ove ogromne zemlje.', 'Настоящее грандиозное путешествие по самым диким природным уголкам и древним городам прямо со страниц энциклопедии!', 'An epic armchair expedition across mighty mountains, mysterious caves, and ancient cities!', 'Prava velika ekspedicija kroz divlje prirodne ljepote i drevne gradove, stvorena za radoznale male putnike!', '/covers/DP-1204.webp', '#2b5c8f', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","real"]', '["geography","nature","travel","encyclopedia","history"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('корабли-твоя-первая-энциклопед-1205', 'DP-1205', 'Корабли. Твоя первая энциклопедия', 'Ships: Your First Encyclopedia', 'Brodovi: Tvoja prva enciklopedija', 'Симон Филипп', 'Philippe Simon', 'Filip Simon', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Кто не мечтал хоть раз отправиться в море на яхте с белоснежными парусами или пересечь океан на огромном лайнере? По воде человек путешествует с древнейших времен: сначала на плотах и лодках, затем на парусниках и пароходах, а в наши дни моря и океаны бороздят огромные контейнеровозы, танкеры, пассажирские паромы, гоночные катера, яхты и еще много разных судов, о которых рассказано в нашей книге. Серия "Твоя первая энциклопедия"- лучший подарок для любознательного ребенка. Выбираете, что подарить школьнику, выпускнику детского сада или просто ищете универсальный подарок для мальчиков и девочек? Энциклопедия станет не только интересным, но и полезным приобретением. Она откроет ребенку мир знаний, расширит кругозор и пробудит интерес к учебе.', 'Who hasn''t dreamed of setting sail across the open sea on a majestic yacht or crossing the ocean on a grand liner? Humans have navigated waters since ancient times—starting with simple rafts and dugout canoes, progressing to wooden sailing ships and steamers, all the way to modern mega-container vessels, luxury cruise liners, and high-speed catamarans. Filled with vibrant illustrations and clear explanations, this book is an inspiring maritime voyage for curious young minds.', 'Ko bar jednom nije maštao o plovidbi morem na prelijepoj jedrilici ili prelasku okeana na ogromnom prekookeanskom brodu? Ljudi plove od davnina: od prvih splavova i čamaca, preko jedrenjaka i parobroda, pa sve do današnjih divovskih teretnjaka, tankera i brzih jahti. Ova bogato ilustrovana enciklopedija pruža uzbudljiv uvid u istoriju pomorstva i brodogradnje, savršen za svakog radoznalog školarca.', 'Свистать всех наверх: этот красочный путеводитель проведёт юного капитана от древних плотов до гигантских современных лайнеров!', 'All hands on deck—this vibrant guide takes young captains on an exciting voyage from ancient log rafts to mighty modern ocean liners!', 'Svi na palubu — ovaj slikoviti vodič povešće malog kapetana na nezaboravno putovanje od drevnih splavova do modernih prekookeanskih divova!', '/covers/DP-1205.webp', '#1d5b8c', 'nonfiction', 'ru', 'available', 'Категория: Бьёрн Рервик', '["adventure","real"]', '["ships","sea","transport","encyclopedia","history"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дикий-робот-1206', 'DP-1206', 'Дикий робот', 'The Wild Robot', 'Divlji robot', 'Питер Браун', 'Peter Brown', 'Piter Braun', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'По книге-бестселлеру Крис Сандерс, режиссер мультфильмов «Лило и Стич» и «Как приручить дракона», снял красивый захватывающий анимационный фильм (2024). Удивительная сказка про одного робота по имени Роз, попавшего на необитаемый остров. История начинается с кораблекрушения. Попавшее в шторм судно идет на дно вместе со своим грузом — многочисленными коробками, в которых аккуратно упакованы сотни роботов. Постепенно обломки прибивает волнами к затерянному в бескрайних водах острову. Все коробки разбились о прибрежные скалы, но одна из них уцелела и оказалась на берегу. Ее нашли любопытные морские выдры. Изучая коробку и играя с ней, они распаковали содержимое и... Щелк! Робот ожил.', 'Adapted into a breathtaking animated film by Chris Sanders (director of ''Lilo & Stitch'' and ''How to Train Your Dragon''), this bestselling story follows Roz, a robot stranded on a remote island after a shipwreck. Accidentally activated by curious sea otters, Roz must learn to survive in the untamed wilderness, build an unlikely community with the forest animals, and discover what it truly means to be alive.', 'Prema ovom bestseleru Kris Sanders, režiser crtanih filmova „Lilo i Stič“ i „Kako da dresirate svog zmaja“, snimio je zadivljujući animirani film. Ovo je priča o robotu Roz, koja se nakon brodoloma budi na pustom ostrvu divljine. Nakon što je radoznale vidre slučajno uključe, Roz uči kako da preživi u netaknutoj prirodi, gradi neobična prijateljstva sa šumskim životinjama i otkriva šta zaista znači imati srce.', 'Трогательная история выживания в дикой природе, которая доказывает: даже существо из металла и микросхем способно полюбить всем сердцем.', 'A deeply touching wilderness tale that proves even a creature made of metal and gears can learn to love with all its heart.', 'Dirljiva i topla priča koja dokazuje da čak i stvorenje od metala i žica može otkriti pravo, nježno srce.', '/covers/DP-1206.webp', '#3d7353', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","animals","friends"]', '["robots","survival","nature","friendship","animals"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('спасение-дикого-робота-1207', 'DP-1207', 'Спасение дикого робота', 'The Wild Robot Escapes', 'Bjekstvo divljeg robota', 'Питер Браун', 'Peter Brown', 'Piter Braun', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Вторая книга про робота по имени Роз. По первой книге Крис Сандерс, режиссер мультфильмов «Лило и Стич» и «Как приручить дракона», снял потрясающий анимационный фильм (2024). Новые вызовы, новые приключения, новые цели. Но вся та же Роз — добрая, человечная, любящая своего гусенка-сына. Теперь перед ней лежит непростая задача: она научилась выживать на необитаемом острове среди диких животных, но что же ей делать в цивилизованном мире?', 'In this touching sequel to the bestseller that inspired the 2024 animated hit, Roz the robot faces her greatest challenge yet. Separated from her island home and beloved gosling son Brightbill, Roz is trapped on a high-tech farm in human civilization. To return to the wilderness and her family, she must navigate humans, city life, and the true meaning of freedom.', 'U ovom dirljivom nastavku bestselera po kojem je snimljen i čuveni animirani film, robot Roz se suočava sa svojim najvećim izazovom. Daleko od svog divljeg ostrva i voljenog sinčića guščića Sjajnog Kljunića, Roz se nalazi zatočena na jednoj visokotehnološkoj farmi. Da bi se vratila svojoj porodici i slobodi, moraće da pronađe put kroz nepoznati svijet ljudi.', 'Если вы думали, что у роботов нет сердца, приготовьте платочки — путешествие Роз домой тронет каждого до глубины души!', 'If you thought robots didn''t have hearts, keep some tissues handy — Roz’s daring quest to reunite with her wild family will melt you completely!', 'Ako ste mislili da roboti nemaju srce, pripremite maramice — Rozino putovanje kući dirnuće svakog čitaoca pravo u dušu!', '/covers/DP-1207.webp', '#2a7f62', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","animals","friends"]', '["robots","nature","friendship","family","journey"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('миссия-дикого-робота-1208', 'DP-1208', 'Миссия дикого робота', 'The Wild Robot Protects', 'Misija divljeg robota', 'Питер Браун', 'Peter Brown', 'Piter Braun', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Новые приключения робота Роз, попавшего на необитаемый остров. В места, где живет Роз и ее семья, приходит беда: в океане появляется ядовитое течение, которое губит все живое. Все больше жителей вынуждены покинуть дом и искать безопасное укрытие. Лишь робот Роз не страшится течения. Она отправляется в долгое путешествие, где ей предстоит выяснить, кто отравляет воду, и остановить ядовитое течение, чего бы это ни стоило. Трогательная, человечная и добрая история о важности взаимовыручки, защите близких и о том, как люди, животные и даже роботы сообща могут творить чудеса и менять мир вокруг. Серия продана в мире тиражом 3,5+ млн экз. и переведена на 20+ языков. Осенью 2024 года в студии Dreamworks вышел мультфильм «Дикий робот» по мотивам первой книги серии', 'Roz the robot returns in an urgent environmental quest: a toxic tide has reached the ocean shores of her beloved island home, threatening all living creatures. As animals flee, fearless Roz dives deep into uncharted waters on an epic mission to find the source of the poison and save everyone she holds dear. A heartfelt, action-packed story about courage, family, and how robots and nature can unite to heal the planet.', 'Roz se vraća u novoj uzbudljivoj avanturi: otrovna morska struja prijeti njenom voljenom ostrvu i uništava sav život pod vodom. Dok životinje bježe, hrabra robotica Roz kreće na opasno putovanje okeanskim dubinama kako bi otkrila ko truje vodu i spasila svoj dom. Dirljiva i humana priča o zajedništvu, ekologiji i snazi ljubavi koja povezuje prirodu i tehnologiju.', 'Когда океану грозит беда, только самая душевная и отважная робот-мама способна погрузиться на глубину и спасти всех обитателей острова!', 'When a mysterious poison threatens the entire ocean, only the bravest robot mom on Earth can dive into the deep to save the day!', 'Kada okeanu zaprijeti opasnost, samo najhrabrija robotska mama može zaroniti u dubine i spasiti čitav životinjski svijet!', '/covers/DP-1208.webp', '#1b6b7a', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","animals","friends"]', '["роботы","океан","экология","дикая природа","дружба"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дикий-робот-на-острове-иллюстр-1209', 'DP-1209', 'Дикий робот на острове Иллюстрированная адаптация первой части трилогии о диком роботе', 'The Wild Robot on the Island (Illustrated Edition)', 'Divlji robot na ostrvu (Ilustrovana adaptacija)', '', 'Peter Brown', 'Piter Braun', '', 'МИФ', NULL, NULL, 6, 16, 'middle', 'Адаптация повести «Дикий робот» для всей семьи — с крупными буквами и цветными авторскими иллюстрациями! Роботам не место в дикой природе. Но после жуткого шторма один ящик с новеньким роботом оказывается на берегу незаселенного острова. Теперь Роз — именно так зовут робота — должна изучать поведение животных и приспосабливаться к жизни среди природы. Станет ли остров ей домом или все-таки диких роботов не бывает? Трогательная, человечная и добрая история о важности взаимовыручки, о защите своих близких, о том, как люди, животные и даже роботы сообща могут творить чудеса и менять мир вокруг.', 'A vibrant family-friendly adaptation of ''The Wild Robot'' featuring large type and full-color illustrations! When robot Roz washes ashore on an uninhabited, stormy island, survival means learning to communicate with the local wildlife and embracing nature. Can a mechanical being truly belong in the wilderness? A touching, heartwarming tale celebrating empathy, family, and the unexpected friendships that change the world.', 'Topla porodična adaptacija priče o Divljem robotu, sa krupnim slovima i živopisnim ilustracijama! Nakon brodoloma, robot Roz se budi na pustom ostrvu i mora naučiti jezik divljih životinja kako bi preživjela. Može li vještačko biće pronaći dom u netaknutoj prirodi? Dirljiva priča o prijateljstvu, empatiji i snazi zajedništva.', 'Может ли металлическое сердце согреть целый остров? Приготовьтесь удивляться, сопереживать и навсегда полюбить робота Роз!', 'Can a metallic heart warm an entire island? Prepare to fall head over heels for Roz the robot and her wild new family!', 'Može li metalno srce ogrijati cijelo ostrvo? Spremite se da zavolite neobičnu Roz i njenu divlju družinu!', '/covers/DP-1209.webp', '#2c7a51', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","animals","friends"]', '["robots","animals","survival","friendship","island"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('металллы-1210', 'DP-1210', 'Металллы', 'Metals', 'Metali', 'Петр Волцит', 'Pyotr Voltsit', 'Pjotr Volcit', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Можно ли обойтись в повседневной жизни без металлов? Представьте себе, что они внезапно исчезли - нет ни машин, ни поездов, ни станков, ни самого обычного ножа и отвёртки! И если металлы пропали бы совсем, то не стало бы и самой нашей планеты: на месте её железного ядра образовалась бы пустота. Исчезло бы и магнитное поле, которое создаёт ядро, и некому было бы защитить нас от космической радиации. Да и человек без металлов не прожил бы и секунды. Без кальция рассыпались бы в порошок зубы и кости, без железа кровь перестала бы разносить по телу кислород, а без магния растения перестали бы этот кислород выделять. Конечно, в небольшой книжке не расскажешь всё про металлы и их особенности. Но совершенно ясно: современному человеку не обойтись без знаний о металлах! Для младшего и среднего школьного возраста.', 'Could we survive in everyday life without metals? Imagine if they suddenly vanished: no cars, trains, or machines, not even a simple kitchen knife or screwdriver! If metals were gone, Earth itself would cease to exist—its iron core would turn into a hollow void, wiping out the magnetic field that shields us from cosmic radiation. Humans wouldn''t last a second either: without calcium our bones and teeth would crumble to powder, and without iron our blood couldn''t carry oxygen. A fascinating, eye-opening guide to the elements that literally hold our world together.', 'Možemo li u svakodnevnom životu zamisliti svijet bez metala? Zamislite da su iznenada nestali – nema automobila, vozova, mašina, pa čak ni običnog noža ili šrafcigera! A kada bi metali potpuno nestali, nestala bi i naša planeta: umjesto njenog gvozdenog jezgra ostala bi praznina, a sa njom bi nestalo i magnetno polje koje nas štiti od zračenja iz svemira. Čovjek bez metala ne bi preživio ni sekunde – bez kalcijuma bi nam se kosti pretvorile u prah, a bez gvožđa krv ne bi prenosila kiseonik. Ova knjiga otkriva nevjerovatan svijet metala bez kojih je život nemoguć.', 'Загляните под капот нашей планеты и собственного тела, чтобы узнать, почему без металлов всё моментально рассыплется в пыль!', 'Take a peek under the hood of our planet and your own body to discover why the entire universe would crumble to dust without metals!', 'Zavirite pod haubu naše planete i sopstvenog tijela da biste saznali zašto bi se bez metala sve u trenu pretvorilo u prah!', '/covers/DP-1210.webp', '#596e79', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real"]', '["metals","science","chemistry","physics","planet earth"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вопросы-памяти-1211', 'DP-1211', 'Вопросы памяти', 'Questions of Memory', 'Pitanja o pamćenju', '', 'Michèle Mira Pons', 'Mišel Mira Pon', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Что такое память, какая она бывает и где находится? Можно ли безоговорочно доверять своим воспоминаниям? Забывать – так ли уж это плохо и что делать, если забывать не хочется? Этими вопросами задаются не только дети, но и взрослые. А сколько про память существует мифов и ложных представлений, рассеять которые в силах лишь специалисты в области функционирования мозга – нейрофизиологи и нейропсихологи! В своей книге французская писательница и журналистка Мишель Мира Пон, заручившись поддержкой опытных научных консультантов, рассказывает обо всём, что на сегодняшний день мы знаем о памяти. Нейронные тропинки в мозгу, польза сна, язык деревьев и удивительные способности каракатиц – о чём только не говорится в 16 главах, посвящённых разным аспектам памяти! Однако за простым и живым языком, за яркими иллюстрациями и забавными примерами стоят научные факты. Благодаря этому сложнейший феномен памяти становится понятен даже ребёнку, а познавательное чтение - весёлым и занимательным.', 'What is memory, where does it live in our heads, and can we always trust what we remember? French author Michèle Mira Pons teams up with leading neuroscientists to take young readers on an exciting expedition through neural pathways, the hidden perks of sleep, and even the surprising memory tricks of cuttlefish and trees. Packed with lively illustrations and accessible scientific insights, this book turns complex brain science into a genuinely fun and memorable adventure.', 'Šta je pamćenje, kako funkcioniše i možemo li uvijek vjerovati sopstvenim sjećanjima? Francuska autorka Mišel Mira Pon, uz podršku neurofiziologa, vodi mlade čitaoce na uzbudljivo putovanje kroz vijuge mozga, važnost sna i čudesne sposobnosti sipa i drveća. Uz duhovite primjere i vesele ilustracije, ova knjiga pretvara složenu nauku o mozgu u jasnu, zabavnu i nezaboravnu priču.', 'Загляните внутрь собственной черепной коробки и узнайте, почему забывать ключи иногда даже полезно!', 'Take a fun peek inside your own brain to discover how memories are made—and why forgetting can actually be a superpower!', 'Zavirite u sopstveni mozak i otkrijte kako nastaju sjećanja i zašto zaboravljanje ponekad uopšte nije loša stvar!', '/covers/DP-1211.webp', '#3a6ea5', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real"]', '["brain","memory","neuroscience","science for kids","human body"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('планета-земля-мир-вокург-нас-в-1212', 'DP-1212', 'Планета Земля: мир вокург нас в инфографике', 'Planet Earth: The World Around Us in Infographics', 'Planeta Zemlja: Svijet oko nas u infografikama', '', 'Unknown', 'Nepoznati autor', '', 'Пешком в историю', 2017, '978-5-905474-76-7', 6, 16, 'middle', '', 'An engaging visual encyclopedia packed with colorful infographics that reveal the wonders of planet Earth. From towering mountain peaks and tectonic plates to deep ocean trenches and climate patterns, this book transforms complex scientific facts into stunning, easy-to-digest visual charts and diagrams for curious explorers.', 'Fascinantna vizuelna enciklopedija prepuna živopisnih infografika koje otkrivaju čuda planete Zemlje. Od visokih planinskih vrhova i tektonskih ploča do dubokih okeanskih rovova i klimatskih fenomena, ova knjiga pretvara složene naučne činjenice u pregledne i zabavne dijagrame za radoznale istraživače.', 'Вся невероятная мощь и красота нашей планеты — в ярких, наглядных и безумно увлекательных инфографиках!', 'Discover the incredible power and wonders of our home planet through vibrant, eye-opening infographics!', 'Otkrijte nevjerovatnu snagu i ljepotu naše planete kroz živopisne, pregledne i uzbudljive infografike!', '/covers/DP-1212.webp', '#2a7f62', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real","adventure"]', '["infographics","geography","earth","science","nature","ecology"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-считаю-вс--1213', 'DP-1213', 'Я считаю всё', 'I Count Everything', 'Brojim sve', '', 'Unknown', 'Nepoznati autor', '', 'Пешком в историю', 2018, '978-5-906994-10-3', 6, 16, 'middle', '', 'A vibrant and thought-provoking journey into the fascinating world of numbers, measurements, and curiosity. Discover how everything around us—from tiny grains of sand to boundless galaxies—can be counted, compared, and understood.', 'Živopisno i radoznalo putovanje kroz fascinantan svijet brojeva, mjerenja i statistike. Otkrijte kako se sve oko nas — od sitnih zrnaca pijeska do beskrajnih galaksija — može prebrojati, uporediti i razumjeti.', 'Оказывается, пересчитать можно абсолютно всё на свете — и это в сотни раз увлекательнее любого скучного урока математики!', 'Turns out you can count literally anything in the universe, and it is a hundred times more exciting than any routine math class!', 'Ispostavlja se da se na svijetu može prebrojati baš sve — i to je sto puta uzbudljivije od običnog časa matematike!', '/covers/DP-1213.webp', '#2b6cb0', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real","funny"]', '["math","numbers","science","curiosity","infographics"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('встречаем-по-одежке-всемирная--1214', 'DP-1214', 'Встречаем по одежке: всемирная история косюма для детей', 'Judged by the Cloth: A World History of Fashion for Kids', 'Sudeći po odjeći: Svjetska istorija kostima za djecu', '', 'Ekaterina Buntman', 'Jekaterina Buntman', '', 'Пешком в историю', 2016, '978-5-905474-50-7', 6, 16, 'middle', '', 'From prehistoric furs and Roman togas to Elizabethan ruffs, Victorian crinolines, and modern sneakers, this vibrant illustrated encyclopedia takes young readers on a stylish journey through world history, showing how our clothes reflect who we are.', 'Od praistorijskog krzna i rimskih toga do elizabetanskih kragni, viktorijanskih krinolina i modernih patika, ova bogato ilustrovana enciklopedija vodi mlade čitaoce na uzbudljivo putovanje kroz istoriju mode i otkriva kako odjeća odražava naš svijet.', 'Приготовьтесь к захватывающему дефиле сквозь эпохи: от первобытных шкур до дерзких париков и кринолинов!', 'Get ready for a fascinating runway walk through the ages, from prehistoric hides to towering powdered wigs and crinolines!', 'Pripremite se za uzbudljivu modnu pistu kroz vjekove: od praistorijskog krzna do raskošnih perika i krinolina!', '/covers/DP-1214.webp', '#d35400', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real","adventure"]', '["fashion","history","costume","encyclopedia","culture"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('истороия-ароматов-1215', 'DP-1215', 'Истороия ароматов', 'The Story of Scents', 'Istorija mirisa', '', 'Dimitri Delmas', 'Dimitri Delmas', '', 'Пешком в историю', NULL, NULL, 6, 16, 'middle', 'Представь себе букет любимых цветов. Какие они? Яркие тюльпаны? Бархатные розы? А может быть, нежные гвоздики? Когда-то все эти цветы прибыли к нам из далёких стран, очаровав своим ароматом и яркими лепестками путешественников, исследователей и миссионеров. Знаешь ли ты, что, прибыв в Голландию, тюльпаны свели с ума всю страну, развязали кошельки и устроили настоящую "лихорадку"? Кто такой "нос" и как он придумывает новые духи? Как добыть корень мандрагоры, который, по легенде, пронзительно кричит, оглушая всех вокруг, когда его выкапывают? Путешествуя с цветами, бросаешь якорь в неведомых портах, чтобы встретиться с иными мирами - то враждебными, то дружественными, познакомится с неведомыми народами, другими культурами, избавиться от предрассудков. Отправляйся в путь от Константинополя до Гоа, из холодных земель Лапландии к тропическим бразильским лесам вслед за путешественниками и первооткрывателями, которые находили новые виды цветов и растений, исследовали их лекарственные свойства и, конечно же, ароматы! Эта книга, написанная автором "Вкусной истории" Димитри Делма - взгляд на историю мира сквозь лепестки цветка, такой нежной и эфемерной его частички, с виду крошечной и незначительной.', 'Imagine a bouquet of your favorite flowers—bright tulips, velvety roses, or delicate carnations. Long ago, each of these plants traveled across oceans, captivating explorers, botanists, and missionaries with their beauty and perfume. Did you know that tulips once caused a wild economic craze in Holland? Or what it takes to be a master "nose" composing new perfumes? From Constantinople to Goa, from frozen Lapland to tropical rainforests, discover world history, geography, and legends through the fragrant lens of blooming flowers.', 'Zamislite buket omiljenog cvijeća: raskošne lale, baršunaste ruže ili nježne karanfile. Nekada su sve ove biljke stigle iz dalekih zemalja, očaravši putnike i botaničare svojim mirisom i ljepotom. Jeste li znali da su lale u Holandiji svojevremeno izazvale pravu ekonomsku groznicu? Ili ko je zapravo „nos“ i kako komponuje parfeme? Od Konstantinopolja do Goe, od Laponije do prašuma Brazila, ova knjiga otkriva istoriju svijeta viđenu kroz mirisne latice i neobične legende.', 'Настоящее кругосветное путешествие по следам цветов, специй и великих парфюмеров — вдохните поглубже!', 'Take a deep breath and embark on a globe-trotting journey tracking botanical wonders, wild adventures, and secret perfumes!', 'Udahnite duboko i krenite na putovanje oko svijeta prateći tragove rijetkog cvijeća, začina i tajni parfimerije!', '/covers/DP-1215.webp', '#c85a53', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","real"]', '["perfume","flowers","botany","history","travel"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('волшебная-пряжа-1216', 'DP-1216', 'Волшебная пряжа', 'Extra Yarn', 'Čarobno predivo', '', 'Mac Barnett', 'Mek Barnet', '', 'Карьера пресс', NULL, NULL, 6, 16, 'middle', 'Маленькая девочка Анабель из города, в котором существует только два цвета: цвет снега и цвет почерневших от сажи дымоходов открывает маленькую волшебную коробочку с разноцветной пряжей. Она вяжет себе свитер, а из остатков пряжи вяжет свитер для своей собаки. А из остатков вяжет еще один для соседа, еще свитера для всех своих одноклассников, для учителя, для мамы, для скворечника, для машин, для домов... Но пряжа все не кончается и не кончается! Город становится таким красочным, теплым и уютным, что на него желает посмотреть сам герцог. Но когда он приезжает, оказывается, он хочет еще и купить волшебную коробочку с пряжей. Он предлагает Анабель много денег, еще больше, но девочка не соглашается на сделку. Тогда он крадет коробочку. Но, вернувшись к себе домой, и устроившись в любимом кресле, герцог вдруг обнаруживает, что коробочка совершенно пуста! Получив по заслугам, жадный герцог выбрасывает ее в море, и она приплывает... обратно к Анабель, которая продолжает работу над вязанием свитера для дерева. Джон Классен, который работал над мультфильмами Кунг-фу Панда (2011) и Coraline (2009), использует черные чернила, гуашь и сканированную текстуру свитера цвета радуги, чем самым создает стильные линейные иллюстрации с яркими геометрическими акцентами.', 'In a dreary, cold town where everything is either the color of white snow or black soot, little Annabelle finds a small magic box filled with endless colorful yarn. She knits a cozy sweater for herself, then one for her dog, and soon enough, sweaters for neighbors, classmates, houses, and even trees. As the gloomy town turns warm and vibrant, an arrogant archduke decides he must buy her magical box at any cost. But magic only works in the hands of those with a generous heart in this award-winning tale illustrated by Caldecott Medalist Jon Klassen.', 'U sivom, hladnom gradiću u kojem postoje samo bijeli snijeg i crna čađ, djevojčica Anabel pronalazi čarobnu kutiju sa šarenim predivom koje nikada ne prestaje. Isplete džemper sebi, pa svom psu, a zatim i cijelom gradu — komšijama, kućama, pa čak i drveću. Međutim, kada pohlepni vojvoda pokuša da otme njenu čarobnu kutiju, shvatiće da pravo čudo pripada samo onima velikodušnog srca. Predivna, nagrađivana priča koju je maestralno ilustrovao Džon Klasen.', 'Уютная сказка о том, как щедрость и один маленький клубок способны согреть целый мир и превратить серость в цветущую радугу.', 'A brilliantly cozy and heartwarming story proving that a little kindness (and endless yarn!) can knit color and joy into the bleakest world.', 'Tople i duhovita priča o tome kako malo dobrote i beskrajno šareno predivo mogu da oboje i ugriju cijeli svijet.', '/covers/DP-1216.webp', '#3f6e80', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["magic","friends"]', '["knitting","kindness","colors","winter","picture book"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('солнце-воздух-1217', 'DP-1217', 'Солнце. Воздух', 'Sun. Air', 'Sunce. Vazduh', '', 'Unknown', 'Nepoznati autor', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Смешная и остроумная книга-перевертыш для больших и маленьких читателей. С одной стороны — всё, что вы хотели знать о Солнце. А теперь переверните книгу — вас ждут удивительные тайны воздуха! Внутри издания — интересные факты об окружающем мире и увлекательные творческие задания: можно поиграть с тенями или воздушными потоками прямо на страницах. Вы узнаете, как ветер помогает мореплавателям и что означает шкала Бофорта, из чего состоит воздух и как человек ощущает себя в невесомости, каковы размеры Солнца и на каком расстоянии от Земли оно находится, какую роль играют атмосферные реки и что такое крылатые семена, как высоко могут летать самолеты, вертолеты, воздушные шары и искусственные спутники, что такое график Килинга, а также многое другое...', 'A clever and witty flip-book for curious readers of all ages! On one side, discover everything you’ve ever wanted to know about the Sun. Flip the book over, and uncover the incredible mysteries of the Air! Packed with fascinating science facts, hands-on shadow games, experiments with air currents, atmospheric rivers, and satellite secrets, this two-in-one volume brings our skies and star to life.', 'Domišljata i duhovita knjiga-okretaljka za male i velike radoznalce! Sa jedne strane saznajte sve što vas je ikada zanimalo o Suncu, a zatim preokrenite knjigu i otkrijte čudesne tajne vazduha! Uz mnoštvo fascinantnih naučnih činjenica, igara sjenkama i vazdušnim strujama, ovo dvostruko izdanje pretvara učenje o prirodi u pravu zabavu.', 'Две увлекательные книги под одной обложкой: читаем про ослепительное Солнце, переворачиваем — и ловим попутный ветер и тайны воздуха!', 'Two brilliant science guides in one: dive into dazzling solar secrets, then flip the book over to chase the wild mysteries of the air!', 'Dvije sjajne enciklopedije u jednoj: istražite blistavo Sunce, pa okrenite knjigu naglavačke i uhvatite vjetrove i tajne vazduha!', '/covers/DP-1217.webp', '#f5a623', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real","adventure"]', '["science","nature","sun","air","experiments","interactive"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чистый-холст-1218', 'DP-1218', 'Чистый холст', 'Blank Canvas', 'Čisto platno', 'Саша Балашова', 'Sasha Balashova', 'Saša Balašova', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', '«Чистый холст» — история о художнице, которая оказалась в творческом тупике. Она ищет выход, пробует разные способы, теряет надежду, но снова находит её совершенно неожиданным образом. Каждый из нас в какой-то мере художник и время от времени сбивается с пути. Эта книга для тех, кто когда-либо сталкивался с кризисом и терял интерес к любимому делу. «Чистый холст» обнимает всех, кто запутался и погряз в сомнениях, и даёт надежду справиться с трудностями.', '"Blank Canvas" is a touching story about an artist trapped in a creative block. She searches for a way out, tries different techniques, loses hope, and unexpectedly finds it again. We are all creators in our own way, and everyone loses their spark from time to time. This book is a warm embrace for anyone battling self-doubt, offering comforting reassurance that inspiration always finds its way back.', '„Čisto platno“ je dirljiva priča o umjetnici koja se našla u stvaralačkoj krizi. Ona traži izlaz, isprobava razne tehnike, gubi nadu, ali je na sasvim neočekivan način ponovo pronalazi. Svako od nas je pomalo umjetnik i svako ponekad zaluta s puta. Ova knjiga pruža topao zagrljaj svima koje muče sumnje i donosi nadu da se svaka kreativna prepreka može savladati.', 'Если муза спряталась, а чистый лист пугает — эта чуткая книга бережно возьмёт за руку и покажет, как снова полюбить творчество.', 'If your muse has gone into hiding and a blank page feels terrifying, this gentle book will take you by the hand and remind you how to fall in love with making art again.', 'Ako se inspiracija sakrila, a prazan list papira izgleda strašno, ova nježna knjiga će vas uhvatiti za ruku i podsjetiti kako da ponovo zavolite stvaranje.', '/covers/DP-1218.webp', '#e6ad85', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real"]', '["creativity","art","inspiration","emotions","self-doubt"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('два-крыла-1219', 'DP-1219', 'Два крыла', 'Two Wings', 'Dva krila', 'Кристина Беллемо', 'Cristina Bellemo', 'Kristina Belemo', '', '', NULL, NULL, 6, 16, 'middle', 'Два крыла. Два прозрачно-белых крыла. Откуда они взялись под персиковым деревом?.. Книга-метафора о человеческой жизни от рождения до последнего полёта над любимым городом.', 'Two wings. Two translucent white wings. Where did they come from, lying beneath the peach tree? A lyrical metaphorical picture book about the journey of a human life, from quiet beginnings to a final, peaceful flight over a beloved city.', 'Dva krila. Dva prozirno-bijela krila. Odakle su se stvorila pod drvetom breskve?.. Slikovnica-metafora o ljudskom životu od rođenja do posljednjeg, tihog leta iznad voljenog grada.', 'Невероятно трогательная и светлая философская притча о жизни, памяти и крыльях, которые обязательно найдутся у каждого.', 'An exquisitely gentle and poetic parable about life, cherished memories, and the wings waiting quietly for each of us.', 'Neizmjerno nježna i dirljiva priča o životu, sjećanjima i krilima koja tiho čekaju svakoga od nas.', '/covers/DP-1219.webp', '#6da5a8', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["magic","real"]', '["philosophy","life-journey","metaphor","memories","poetic"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мышка-чарли-наводит-порядок-1220', 'DP-1220', 'Мышка Чарли наводит порядок', 'Charlie the Mouse Tidies Up', 'Mišić Čarli zavodi red', 'Катерина Горелик', 'Katerina Gorelik', 'Katerina Gorelik', '', '', NULL, NULL, 6, 16, 'middle', 'Мышка Чарли обожает чистоту и порядок! Поэтому она помогает с уборкой домиков своим соседям — обитателям Дикого и Волшебного лесов. Мрачные лабиринты кротовьей норы, своенравная избушка мадам Ведьмы, сахарные конюшни единорогов, логово мистера Дракона, ароматный имбирный домик — везде придётся навести порядок. Впереди у Чарли насыщенная рабочая неделя!', 'Charlie the mouse adores cleanliness and order! That is why he helps tidy up the dwellings of his magical neighbors across the Enchanted and Wild Forests. From the dark labyrinth of a mole hole and Madam Witch''s unruly hut to sugary unicorn stables, Mr. Dragon''s fiery lair, and a sweet gingerbread house—everything needs a thorough dusting. A bustling and delightful work week awaits Charlie!', 'Mišić Čarli obožava čistoću i red! Zato pomaže u pospremanju domova svojim komšijama — neobičnim stanovnicima Divlje i Čarobne šume. Mračni lavirinti krtičnjaka, svojeglava koliba gospođe Vještice, šećerne štale jednoroga, jazbina gospodina Zmaja i mirisna kućica od medenjaka — svuda treba zavesti red. Čarlija čeka izuzetno radna i vesela nedjelja!', 'Загляните во все потайные уголки сказочных домиков вместе с самым дотошным и обаятельным мышонком-клинером!', 'Peek into every secret nook and cranny of fairy-tale homes alongside the most charming little cleaner mouse ever!', 'Zavirite u sve skrivene kutke bajkovitih kućica zajedno sa najslađim mišićem koji obožava pospremanje!', '/covers/DP-1220.webp', '#487e64', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["funny","magic","animals"]', '["cleaning","fairy tale creatures","wimmelbuch","mice","forest"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('триста-тысяч-узелков-1221', 'DP-1221', 'Триста тысяч узелков', 'Three Hundred Thousand Knots', 'Tri stotine hiljada čvorova', 'Елена Голованова', 'Elena Golovanova', 'Elena Golovanova', '', '', NULL, NULL, 6, 16, 'middle', 'Как я прочитал ковёр Представь себе мир, где на коврах сидят, едят, спят, читают их, как газеты, и даже передают с их помощью зашифрованные послания! Как любой современный ребёнок, Гриша никогда не думал о коврах... пока однажды не оказался в мире одного из них. Вместе с проводником, обаятельным псом по имени Джабир, Гриша отправится в невероятное путешествие. Ему предстоит познакомиться с искусством, придуманным тысячи лет назад, узнать, из чего и как ткут удивительные ковры, увидеть самый старый ковёр и даже разгадать один жизненно важный шифр.', 'Imagine a world where carpets are used for sitting, eating, sleeping, and even reading like newspapers to uncover secret messages! Like any modern kid, Grisha never gave rugs a second thought—until he stepped right inside one. Accompanied by a charming dog guide named Jabir, Grisha embarks on an incredible journey through thousands of years of textile art, discovering how carpets are woven, seeing the world''s oldest rug, and cracking a vital cipher hidden in the knots.', 'Zamislite svijet u kojem se na ćilimima sjedi, jede, spava, pa čak i čita kao iz novina, otkrivajući tajne poruke! Kao i svako moderno dijete, Griša nikada nije mario za tepihe... sve dok se jednog dana nije našao unutar jednoga od njih. Uz vodiča, šarmantnog psa po imenu Džabir, Griša kreće na nevjerovatno putovanje kroz hiljade godina istorije tkanja, saznaje kako nastaju čudesni ćilimi, posjećuje najstariji ćilim na svijetu i rješava važnu šifru.', 'Разверните эту книгу, как восточный ковёр, и узнайте, сколько секретов и приключений прячется в каждом узелке!', 'Unroll this book like an ancient rug and discover just how many secrets, stories, and ciphers are hidden in every single knot!', 'Odmotajte ovu knjigu poput čarobnog ćilima i otkrijte koliko se tajni i avantura krije u svakom čvoriću!', '/covers/DP-1221.webp', '#b23a22', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","real"]', '["ковры","история вещей","ремесла","орнаменты","путешествия"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('знаменитые-ограбления-1222', 'DP-1222', 'Знаменитые ограбления', 'Famous Heists', 'Čuvene pljačke', 'Соледад Роберо Мариньо', 'Soledad Romero Mariño', 'Soledad Romero Mariño', '', '', NULL, NULL, 6, 16, 'middle', 'Познакомьтесь с самыми изобретательными преступниками в мире! Захватывающая иллюстрированная хроника самых дерзких и изощрённых ограблений за последние 150 лет. Как злоумышленники планировали кражи? Какими способами они обходили системы безопасности? Как полиции удавалось выйти на их след? Каким образом грабители завладевали добычей и стоимостью в несколько миллионов и зачастую умудрялись с ней сбежать? Кем были эти криминальные умы, осмелившиеся присвоить себе известнейшие произведения искусства, драгоценности и огромные суммы денег? Откройте для себя неожиданные подробности знаменитых ограблений!', 'Meet the most inventive criminals in history! A thrilling illustrated chronicle of the most daring and sophisticated heists of the last 150 years. How did the culprits plan their moves? How did they outsmart high-tech security, and how did detectives track them down? Discover the unbelievable true stories behind history''s most famous jewel, art, and bank jobs!', 'Upoznajte najdomišljatije lopove na svijetu! Uzbudljiva ilustrovana hronika najsmjelijih i najsloženijih pljački u posljednjih 150 godina. Kako su osmislili planove? Na koje su načine zaobišli sigurnosne sisteme i kako im je policija ušla u trag? Otkrijte nevjerovatne detalje i tajne iza najčuvenijih krađa umjetnina, dragulja i miliona!', 'Загляните за кулисы самых хитроумных преступлений в истории — захватывает дух получше любого шпионского блокбастера!', 'Step behind the scenes of history''s cleverest capers — more gripping than any Hollywood spy thriller!', 'Zavirite iza kulisa najlukavijih zločina u istoriji — uzbudljivije od bilo kog špijunskog filma!', '/covers/DP-1222.webp', '#23395b', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","real"]', '["heists","history","detectives","true crime","mysteries"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('нефть-1223', 'DP-1223', 'Нефть', 'Oil', 'Nafta', 'Дмитрий Мажоров', 'Dmitry Mazhorov', 'Dmitrij Mažorov', '', '', NULL, NULL, 6, 16, 'middle', 'Эта книга расскажет тебе, как добывают нефть из-под земли и из-под воды, проведёт по необычным городам — добывающей платформе и нефтеперерабатывающему заводу. Покажет, как устроены бензоколонка и автомобильный двигатель. Ты узнаешь, почему летают самолёт и ракета, чем питаются котельная и корабль и для чего на заводе по производству моторных масел нужны свинки. Поймёшь, какие опасности несёт добыча нефти для здоровья нашей планеты и как можно их избежать. Нефть называют чёрным золотом, потому что сегодня всё вокруг сделано из неё — от бензина в двигателе до жвачки и аспирина. Как такое может быть? Все ответы тут!', 'This book reveals how oil is extracted from underground and underwater depths, taking you on an exciting tour through offshore drilling rigs and refineries. You''ll discover how gas stations and engines work, what fuels planes, rockets, and giant ships, and even why pigs are used in motor oil plants. Find out why oil is hailed as ''black gold''—found in everything from gasoline to chewing gum and aspirin—and how we can protect our planet from the hazards of extraction.', 'Ova knjiga otkriva kako se nafta vadi ispod zemlje i vode, vodeći te u nesvakidašnje gradove — naftne platforme i rafinerije. Saznaćeš kako rade benzinske pumpe i automobilski motori, zašto lete avioni i rakete, i kako nafta pokreće kotlarnice i brodove. Otkrij zašto naftu zovu crnim zlatom — jer se od nje pravi sve, od goriva do žvakaće gume i aspirina — kao i koje opasnosti njena eksploatacija nosi za našu planetu.', 'Увлекательное расследование о «чёрном золоте», без которого не было бы ни полётов на ракетах, ни любимой жевательной резинки!', 'An eye-opening exploration of ''black gold,'' revealing how a mysterious dark liquid powers our rockets and secretly hides in chewing gum!', 'Fascinantno istraživanje o „crnom zlatu“ bez kojeg ne bi bilo ni svemirskih raketa, pa čak ni tvoje omiljene žvake!', '/covers/DP-1223.webp', '#2d3748', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real","adventure"]', '["nonfiction","science","oil","technology","ecology"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тело-мой-друг-и-враг-1224', 'DP-1224', 'Тело: мой друг и враг', 'My Body: Friend and Foe', 'Tijelo: moj prijatelj i neprijatelj', '', 'Dominique Adèle-Cassuto', 'Dominik Adel-Kasuto', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'У всех есть представление, как должно выглядеть твоё тело. А лучший способ бороться с чужим мнением, страхами и стереотипами — это знать, как устроен организм и что нужно именно тебе. В этой книге ты узнаешь: для чего нужна норма и что такое нормальный вес? Что происходит в пубертате? Что такое расстройство пищевого поведения? Проблемы тела и как с ними справиться? Как работают социальные сети и как они влияют на наше поведение и настроение? 5 причин купить книгу «Тело: мой друг и враг»: Доминик Адель-Кассуто, практикующий эндокринолог и диетолог, её книга основана на многолетнем опыте, современных исследованиях и опыте настоящих подростков; Научный консультант Даша Саркисян, медицинский журналист, соосновательница телеграм-канала «Намочи манту», адаптировала и дополнила книгу под российский контекст; Как всегда – смешные и точные иллюстрации Влады Мяконькиной; Эта книга поможет прийти к принятию своего тела, каким бы оно ни было, через понимание, как устроен организм, пищеварение, и что вообще происходит в пубертатный период; Но эта книга не только про тело, но и про то, как устроена современная культура и социальные сети, которым чаще всего выгодно, чтобы мы всегда оставались недовольными собой.', 'Everyone seems to have an opinion on what your body should look like, but the best way to conquer stereotypes, fears, and peer pressure is to truly understand how your body works. Written by endocrinologist and nutritionist Dominique Adèle-Cassuto, this empowering guide breaks down puberty, healthy weight, eating habits, and the tricky influence of social media on our self-image. With witty illustrations and scientific clarity, it teaches teens how to make peace with their bodies and tune out unrealistic beauty standards.', 'Svi imaju mišljenje o tome kako tvoje tijelo treba da izgleda, ali najbolji način za borbu protiv stereotipa i strahova jeste razumijevanje načina na koji organizam zaista funkcioniše. Kroz jasne naučne činjenice i duhovite ilustracije, ova knjiga endokrinologa i nutricionistkinje Dominik Adel-Kasuto vodi tinejdžere kroz izazove puberteta, odnos prema ishrani i pritisak društvenih mreža, pomažući im da prihvate i zavole sebe.', 'Честный, деликатный и научно выверенный гид, который поможет подростку подружиться с собственным телом и не вестись на чужие стандарты.', 'An honest, warm, and science-backed teen guide to making peace with your growing body and brushing off unrealistic social media standards.', 'Iskren, topao i naučno utemeljen vodič koji pomaže tinejdžerima da se sprijatelje sa svojim tijelom i odbace nametnute ideale sa mreža.', '/covers/DP-1224.webp', '#3fa5a3', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real"]', '["body positivity","puberty","health","teen guide","psychology"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('конец-все-не-так-просто-1225', 'DP-1225', 'Конец?Все не так просто', 'The End? It''s Not That Simple', 'Kraj? Nije sve tako jednostavno', 'Ноэми Вола', 'Noemi Vola', 'Noemi Vola', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Когда я был маленьким, я хотел быть мастером по ремонту концовок, то есть тем, кто исправляет финалы историй. Потому что, если вы заметили, они очень часто заканчиваются не на мажорной ноте, а просто ужасно! Финалы нередко оказываются слишком затянутыми, чересчур грустными, разочаровывающими, несправедливыми, непонятными, просто дурацкими. Так почему бы (при помощи воображения) не починить их?! Эта книга, победитель второй премии SERPA/Planeta Tangerina, — дань уважения (или пренебрежения?) всем плохим финалам. И она, уж будьте уверены, закончится самым лучшим образом!', 'When I was little, I wanted to be an endings repairman—someone who fixes the way stories conclude. Endings are so often disappointing, unfair, dragged out, or just plain absurd. So why not use our imagination to patch them up? Winner of the prestigious SERPA/Planeta Tangerina International Award, this delightfully witty book explores bad endings from every angle—and promises this one will end on the highest note!', 'Kad sam bio mali, želio sam da budem majstor za popravku završetaka — neko ko ispravlja krajeve priča. Jer, ako ste primijetili, priče se prečesto završavaju tužno, nepravedno, nerazumljivo ili potpuno besmisleno! Pa zašto ih maštom ne bismo popravili? Ova duhovita knjiga, nagrađena prestižnom nagradom SERPA/Planeta Tangerina, zabavan je osvrt na sve nezadovoljavajuće završetke — uz garanciju da se ova priča završava na najbolji mogući način!', 'Остроумное и философское руководство для всех, кого хоть раз возмущали дурацкие, несправедливые или чересчур грустные книжные финалы!', 'A delightfully witty and philosophical guide for anyone who has ever been thoroughly annoyed by silly, sad, or unfair story endings!', 'Duhovit i filozofski vodič za sve one koje su ikada nervirali tužni, dosadni ili nepravedni krajevi omiljenih priča!', '/covers/DP-1225.webp', '#e05a36', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["funny","real"]', '["storytelling","humor","creativity","philosophy","imagination"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('живая-книга-1226', 'DP-1226', 'Живая книга', 'Press Here', 'Pritisni ovdje', 'Эрве Тюлле', 'Hervé Tullet', 'Erve Tule', '', 'Клевер', NULL, NULL, 6, 16, 'middle', '«Живая книга» давно приобрела толпы поклонников во всем мире, познакомьтесь с ней и вы. В ней нет персонажей и нет сюжета, зато на ее страницах своей собственной жизнью живут озорные разноцветные кружочки. Чтобы начали происходить чудеса, понадобится помощь вашего ребенка: наколдовать больше кружочков простым хлопком в ладоши или выключить свет на страницах, потрясти и высыпать шарики из книг, а может, сдуть темноту из книги? Выполняйте интерактивные задания, переворачивайте страницы, играйте и удивляйтесь! «Живая книга» невероятно воздействует на воображение детей и захватывает внимание сильнее любой электронной игрушки. Подуйте, потрясите, похлопайте в ладоши, открывайте на любой странице и начинайте снова — забавные кружочки развеселят любого! Многочасовое веселье и радостный детский смех обеспечены: проверено маленькими поклонниками творчества Эрве Тюлле по всему миру.', 'Hervé Tullet’s worldwide sensation needs no screens or batteries—just your child''s hands and imagination! Press the yellow dot, tilt the book to the left, gently blow on the pages, or clap your hands to watch mischievous colored circles dance, multiply, and magically transform. An endlessly inventive, interactive masterpiece that will spark laughter and wonder every single time you open it.', 'Svjetski bestseler Ervea Tulea dokazuje da za nevjerovatnu magiju nijesu potrebni ekrani ni baterije — dovoljni su dječji prstići i bujna mašta! Pritisnite žutu tačkicu, nagnite knjigu ulijevo, dunite u stranice ili pljesnite rukama i posmatrajte kako razigrani šareni kružići plešu, množe se i mijenjaju boje. Ova neodoljiva interaktivna slikovnica garantuje sate smijeha i čiste radosti.', 'Кто сказал, что в бумажной книге нет кнопок? Жмите на точки, трясите страницы и смотрите, как прямо в руках оживает настоящее чудо!', 'Who says paper books don''t have touchscreens? Tap the dots, shake the pages, and watch real magic unfold right in your hands!', 'Ko kaže da papirne knjige nemaju dugmiće? Pritisnite tačkice, protresite stranice i gledajte kako u vašim rukama oživljava prava magija!', '/covers/DP-1226.webp', '#f7cb15', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["magic","funny"]', '["interactive","colors","imagination","play"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-для-тех-кто-лучше-всех-1227', 'DP-1227', 'Сказки для тех, кто лучше всех', 'Tales for the Best of All', 'Bajke za najbolje od svih', 'Роберто Пьюмини', 'Roberto Piumini', 'Roberto Pjumini', '', 'ИД «Городец»', 2022, '978-5-907483-86-6', 6, 16, 'middle', '', 'A whimsical and deeply poetic collection of modern fairy tales by beloved Italian storyteller Roberto Piumini. Filled with clever wordplay, gentle irony, and unforgettable characters, these stories gently show that the secret to being truly wonderful lies in generosity, imagination, and kindness.', 'Zbirka maštovitih i duboko poetičnih modernih bajki omiljenog italijanskog pripovjedača Roberta Pjuminija. Prepune duhovite igre riječima, nježne ironije i neobičnih junaka, ove priče otkrivaju da tajna istinske posebnosti leži u velikodušnosti, mašti i dobroti.', 'Ироничные и мудрые сказки великого итальянского сказочника о том, что быть «лучше всех» — значит уметь искренне удивляться и любить.', 'Witty and wonderfully philosophical Italian fairy tales showing that being ''the best'' simply means keeping your heart wide open to wonder.', 'Pronicljive i tople moderne italijanske bajke koje podsjećaju da biti „najbolji“ zapravo znači umjeti iskreno voljeti i maštati.', '/covers/DP-1227.webp', '#e26a45', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["magic","funny"]', '["fairy tales","italian literature","short stories","imagination","humor"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('листы-1228', 'DP-1228', 'Листы', 'Leaves: Júlia Sardà', 'Listovi: Žulija Sarda', 'Джулия Сарда', 'Júlia Sardà', 'Júlia Sardà', '', 'Поляндрия', 2022, '978-5-6046069-7-1', 6, 16, 'middle', '', 'A breathtaking showcase of artwork and creative sketches by acclaimed illustrator Júlia Sardà, inviting readers into her darkly whimsical, intricate, and atmospheric visual universe.', 'Raskošna zbirka ilustracija i skica koja otvara vrata u zagonetni, bajkoviti i vizuelno neodoljivi svijet čuvene umjetnice Žulije Sarde.', 'Погрузитесь в чарующий и таинственный мир Джулии Сарда — чистое вдохновение для будущих художников и любителей книжной магии!', 'Step inside the exquisitely detailed and atmospheric universe of Júlia Sardà—pure eye candy for dreamers and budding artists!', 'Zavirite u raskošni i pomalo tajanstveni svijet Žulije Sarde koji pruža bezgraničnu inspiraciju mladim umjetnicima!', '/covers/DP-1228.webp', '#2f4b4e', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["magic","real"]', '["art","illustrations","sketchbook","creativity","inspiration"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шмакодявки-1229', 'DP-1229', 'Шмакодявки', 'Tiny Critters: The World of Microbes', 'Sićušna bića: Svijet mikroba', '', 'Unknown', 'Nepoznati autor', '', 'Клевер', 2020, '978-5-00154-331-2', 6, 16, 'middle', '', 'A fascinating and witty dive into the invisible universe of bacteria, viruses, and microorganisms living all around us—and even inside our bodies! Discover how these tiny beings run our world, keep us healthy, and occasionally cause a little trouble.', 'Fascinantno i duhovito putovanje u nevidljivi univerzum bakterija, virusa i mikroorganizama koji žive svuda oko nas — pa čak i u našim tijelima! Otkrijte kako ova sićušna bića pokreću naš svijet, čuvaju naše zdravlje i ponekad naprave malu pometnju.', 'Загляните в микроскоп и познакомьтесь с миллионами крошечных созданий, без которых наша жизнь была бы совершенно невозможна!', 'Peer through the microscope and meet the millions of minuscule creatures without whom our planet simply couldn''t survive!', 'Zavirite kroz mikroskop i upoznajte milione sićušnih bića bez kojih naš život na planeti jednostavno ne bi bio moguć!', '/covers/DP-1229.webp', '#5ea853', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["funny","real"]', '["microbes","bacteria","science","biology","human body"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('удивительное-путешествие-кроли-1230', 'DP-1230', 'Удивительное путешествие кролика Эдварда', 'The Miraculous Journey of Edward Tulane', 'Čudesno putovanje Edvarda Tulejna', 'Кейт ди Камилло', 'Kate DiCamillo', 'Kejt Dikamilo', '', 'Азбука', NULL, NULL, 6, 16, 'middle', 'Однажды бабушка Пелегрина подарила внучке Абилин игрушечного кролика по имени Эдвард Тюлейн, которого сделал знаменитый кукольных дел мастер. Абилин просто обожала своего кролика, целовала его красивые длинные уши, наряжала в специально сшитые для него костюмы и каждое утро заводила его золотые часы на цепочке. А кролик был самовлюбленным и бессердечным эгоистом и никого, кроме себя, не любил. Как-то Абилин вместе с родителями отправилась в морское путешествие, и кролик Эдвард, случайно упав за борт, оказался на самом дне океана. Старый рыбак выловил его своей сетью и принёс жене. Потом кролик попадал в разные руки - и хорошие, и плохие. И каждый раз с грустью и тоской вспоминал девочку Абилин, которая его так любила. Холодное сердце кролика постепенно оттаивало, училось отвечать любовью на любовь, и в один прекрасный день Эдвард Тюлейн вернулся к Абилин, которая уже успела стать взрослой. Эту печальную и в то же время светлую историю написала современная американская писательница Кейт Дикамилло, обладательница многочисленных наград, вручаемых в области литературы для детей.', 'Edward Tulane is a vain, cold-hearted porcelain rabbit adored by a little girl named Abilene, who dresses him in fine silk suits and winds his gold pocket watch. But during an ocean voyage, Edward is knocked overboard and sinks to the bottom of the sea. Thus begins an extraordinary odyssey through different hands—from an old fisherman and an itinerant tramp to a sick child and a puppet master. Through loss, heartache, and kindness, Edward''s porcelain heart slowly breaks open, learning what it truly means to love and be loved.', 'Edvard Tulejn je oholi porcelanski zec hladnog srca kojeg devojčica Abilin obožava, oblačeći ga u svilena odijela i navijajući njegov zlatni sat. Međutim, tokom plovidbe morem, Edvard pada preko palube i završava na dnu okeana. Tako počinje njegovo nevjerovatno putovanje kroz mnoge ruke — od starog ribara i skitnice do bolesne djevojčice i lutkara. Kroz tugu, gubitke i dobrotu neznanaca, Edvardovo porcelansko srce postepeno puca i uči šta zaista znači voljeti.', 'Трогательная притча о фарфоровом эгоисте, которому пришлось пройти через полмира и разбиться на кусочки, чтобы научиться любить по-настоящему.', 'A heartbreakingly beautiful journey of a vain china rabbit who had to travel the world and break into pieces just to discover how to love.', 'Dirljiva priča o uobraženom porcelanskom zecu koji je morao da obiđe pola svijeta i slomi se na komade da bi naučio šta je prava ljubav.', '/covers/DP-1230.webp', '#2a5270', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","friends","magic"]', '["porcelain rabbit","journey","love and loss","growing up","classic"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-роман-1231', 'DP-1231', 'Как роман', 'The Rights of the Reader', 'Kao roman', 'Пеннак Даниэль', 'Daniel Pennac', 'Danijel Penak', '', 'Самокат', NULL, NULL, 6, 16, 'middle', '«Если, как то и дело говорится, мой сын, моя дочь, молодежь не любит читать — не надо винить в этом ни телевизор, ни современность, ни школу». «Кого же? — спросите вы. — И главное, что же в этом случае делать?» В своей книге «Как роман» Данниэль Пеннак щедро делится методами столь же простыми, сколь и результативными. Педагог Пеннак блестяще воплотил эти методы в школе и научил любви к чтению своих учеников. Писатель, он заставил читать и любить свои книги весь мир. 5 причин купить книгу «Как роман»: Смешное и полезное эссе для родителей и учителей. Никаких «как заставить ребенка читать», и даже «полюбить»; Откровенный, задушевный, остроумный разговор о первопричинах нелюбви к чтению и возможных путях её преодоления; Книга Даниэля Пеннака не только о любви к книге, но и о душевной близости, контактом между ребёнком и взрослым; Педагогическое эссе читается … как роман, и может стать руководством к тому, как сделать своего ребёнка счастливым. Ведь книга о счастье, счастье читать; Даниэль Пеннак – один из наиболее часто переводимых на иностранные языки авторов Франции, лауреат премии Ренодо, в 2023 году получил Большую литературную премию Французской академии. Это одна из старейших и значительных наград, вручаемых писателю во Франции за весь его литературный труд.', 'When children fall out of love with reading, we often blame screens, modern life, or school. In this warm, witty, and deeply empathetic essay, French author and teacher Daniel Pennac reveals why reading should never be a chore or a duty. Blending classroom anecdotes with infectious enthusiasm, he formulates the famous ''Rights of the Reader''—including the right not to read, the right to skip pages, and the right to read anywhere. A timeless celebration of books and genuine closeness between adults and children.', 'Kada djeca izgube volju za čitanjem, skloni smo da krivimo ekrane, školu ili moderno doba. U ovom toplom, duhovitom i mudrom eseju, francuski pisac i profesor Danijel Penak pokazuje kako čitanje nikada ne smije postati obaveza pod prisilom. Kroz anegdote iz učionice i neodoljiv šarm, on formuliše čuvena ''prava čitaoca''—poput prava da preskačemo stranice ili da ne završimo knjigu. Ovo je himna ljubavi prema knjizi i vodič za istinsku bliskost između roditelja i djece.', 'Главный манифест читательской свободы: вдохновляющая книга, которая напомнит и взрослым, и детям, что чтение — это не скучная обязанность, а чистое счастье!', 'The ultimate manifesto of readerly freedom, proving to both kids and adults that reading is pure joy, not homework!', 'Najljepši manifest čitalačke slobode koji podsjeća i djecu i odrasle da je čitanje čista radost, a ne domaći zadatak!', '/covers/DP-1231.webp', '#e58a2c', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real","funny"]', '["reading","books","parenting","education","essay"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('верю-не-верю-книга-тест-по-рел-1232', 'DP-1232', 'Верю — не верю Книга-тест по религиям и философиям', 'Believe It or Not: A Quiz Book on Religions and Philosophies', 'Vjerujem — ne vjerujem: Knjiga-test o religijama i filozofijama', '', 'Unknown', 'Nepoznat autor', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Мы все — ты, твои друзья, родные и супергерои в кино — действуем согласно нашим внутренним правилам и принципам, и нам кажется, что эти правила не противоречат друг другу. На самом деле мы часто смешиваем разные взгляды: о любви и дружбе можем думать как христиане, о смерти как индуисты, а о свободе и государстве как светские гуманисты. Книга «Верю — не верю» построена вокруг 28 вопросов — о смысле жизни, справедливости, личных границах, самооценке, отношениях — обо всём, что нас всех волнует. На каждый вопрос отвечают 10 анонимных мудрецов — представители 6 религий и 4 философий, они спорят, соглашаются и дополняют друг друга, а тебе нужно выбрать ответ, с которым ты больше всего согласен. Собрав все свои ответы, ты поймёшь, какие мировоззрения тебе ближе всего.', 'We all act according to inner principles, often blending diverse traditions without even knowing it: viewing love like a Christian, death like a Hindu, and freedom like a secular humanist. Built around 28 essential questions about life''s meaning, justice, and relationships, this book gathers 10 anonymous sages from 6 world religions and 4 philosophical schools to debate each topic. Pick the answers that resonate with you most and discover which worldview truly shapes your mind!', 'Svi mi živimo po unutrašnjim pravilima i principima, često spajajući potpuno različite poglede na svijet a da toga nijesmo ni svjesni. Knjiga „Vjerujem — ne vjerujem“ postavlja 28 važnih životnih pitanja — o smislu života, pravdi, ličnim granicama i odnosima. Na svako pitanje odgovara deset anonimnih mudraca iz šest religija i četiri filozofije; odaberi odgovore koji ti najviše leže i otkrij koji svjetonazori ti najbolje odgovaraju!', 'Пройди этот мудрый и увлекательный тест, чтобы узнать, какой философ или мыслитель живёт внутри тебя!', 'Take this clever, thought-provoking quiz to uncover which ancient philosophy secretly guides your everyday life!', 'Riješi ovaj mudri i zabavni kviz i saznaj koji filozof ili mislilac čuči u tebi!', '/covers/DP-1232.webp', '#3d6b7b', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real"]', '["philosophy","world religions","quiz","self-discovery","critical thinking"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('book-1233', 'DP-1233', '', 'Wars', 'Ratovi', '', 'Charlotte Gingras', 'Šarlot Žangra', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'В далекой мирной Канаде живёт семья. Лоранс пятнадцать, Люке девять, а Матильде меньше года. Жизнь меняется в один день, когда папа, на котором дома всё держалось, принимает решение отправиться на войну в Афганистан в составе миротворческой миссии. Все привычные семейные роли рушатся, а вместо них воцаряются страх, ожесточённость и непонимание. Пока отец рискует погибнуть на чужой войне, к ним в дом приходит своя, внутренняя война. Чтобы пережить её, некоторым придётся преждевременно повзрослеть. Шарлотта Жангра — канадская писательница. Она ставит непривычные вопросы и помогает при этом сохранить надежду, не утонуть во мраке. Среди её наград — крупные канадские премии генерал-губернатора (1999, 2000) и Alvine-Belisle (2012).', 'In peaceful Canada, Laurence, Luc, and baby Mathilde live a calm family life until their father decides to join a peacekeeping mission in Afghanistan. With his departure, their stable world unravels, giving way to fear, anger, and estrangement. While their father faces real conflict abroad, an internal battle erupts at home, forcing Laurence and Luc to grow up faster than they ever imagined. A poignant story of resilience, hope, and holding a family together.', 'U mirnoj Kanadi živi porodica sa troje djece — petnaestogodišnjom Lorans, devetogodišnjim Likom i malom Matildom. Njihov život se mijenja iz korijena onog dana kada otac odluči da ode u mirovnu misiju u Avganistan. Dok otac rizikuje život na tuđem ratištu, u njihov dom se useljava sopstveni, tihi unutrašnji rat koji ih tjera da prebrzo odrastu. Dirljiva i iskrena priča o nadi, strahu i porodičnoj snazi.', 'Глубокая и честная книга о том, как научиться слышать друг друга и сберечь тепло, когда привычный мир вокруг трещит по швам.', 'A deeply moving and honest novel about keeping the lights on at home when distant storms threaten to pull a family apart.', 'Duboko dirljiva i iskrena priča o tome kako sačuvati porodičnu toplinu kada se cijeli svijet iznenada uzdrma.', '/covers/DP-1233.webp', '#4a6274', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["real"]', '["family","growing up","resilience","empathy","relationships"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чертов-угол-1234', 'DP-1234', 'Чертов угол', 'Devil''s Corner', 'Đavolji ugao', 'Алексей Олейников', 'Alexey Oleynikov', 'Aleksej Olejnikov', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Если смешать атмосферу сериала «Очень странные дела» и декорации обычной подмосковной деревни, то получится «Чёртов угол» Для всех любителей мистики и загадок от 12 и до 100 лет. В подмосковной деревне начинают происходить странные события: на поле появляется призрак сына сумасшедшего помещика, жившего пару сотен лет назад, местный мальчишка без вести пропадает в Сорном лесу, а обыкновенный дед оказывается колдуном, охраняющим мир живых от призрачной хозяйки... Новая захватывающая и мистическая история для подростков от автора «Детективного агентства "Утюг"» и «Девочка и химеры» Алексея Олейникова.', 'What if you blended the eerie vibes of ''Stranger Things'' with the atmospheric mystery of a secluded countryside? In a quiet village, dark secrets begin to stir: the phantom of a mad landlord''s son haunts the fields, a boy vanishes into the cursed woods, and an ordinary-looking grandfather turns out to be a sorcerer guarding the living from a ghostly mistress. A gripping mystical mystery for teens and daring adults alike.', 'Ako pomiješate atmosferu serije „Stranger Things“ i tajanstveno seosko okruženje, dobićete „Đavolji ugao“ — poslasticu za sve ljubitelje jeze i misterija od 12 do 100 godina. U mirnom selu počinju da se zbivaju neobjašnjive stvari: poljima luta duh plemićkog sina, lokalni dječak nestaje bez traga u mračnoj šumi, a običan đed krije da je zapravo čarobnjak koji štiti svijet živih od sablasnih sila.', '«Очень странные дела» в деревенских декорациях: запасайтесь фонариком и чаем, ведь закрыть книгу до разгадки всех тайн просто невозможно!', 'Think ''Stranger Things'' meets folk mystery: grab a flashlight and cozy up, because you won''t put this down until dawn!', '„Stranger Things“ sa dozom seoskog folklora: pripremite baterijsku lampu i toplo ćebe, jer nema spavanja dok ne riješite sve misterije!', '/covers/DP-1234.webp', '#264639', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["spooky","adventure","magic"]', '["mystery","ghosts","folklore","village","ya"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('жажда-приключений-1235', 'DP-1235', 'Жажда приключений', 'Thirst for Adventure', 'Žeđ za avanturom', '', 'Various Authors', 'Grupa autora', '', 'Альпина', NULL, NULL, 6, 16, 'middle', 'Приключения случаются в тот момент, когда их ждешь меньше всего! Они могут настигнуть возле прилавка с арбузами, в собственной квартире, пока мама на работе, или в настоящей пиратской крепости. Главное — не переставать мечтать, а жажда приключений обязательно подскажет, куда отправиться на этот раз. Шесть детских авторов рассказали захватывающие истории: фантастические и сказочные, смешные и пронзительные. Но все они про те невероятные приключения, в которые верят дети и по которым скучают взрослые.', 'Adventures happen just when you least expect them! They might catch up with you by a watermelon stand, right in your own flat while mum is at work, or inside a real pirate fortress. The main thing is to never stop dreaming, and your thirst for adventure will show you where to head next. Six children''s authors share gripping stories—fantastic, whimsical, funny, and touching—celebrating the incredible escapades that kids believe in and grown-ups miss dearly.', 'Avanture se dešavaju baš onda kada im se najmanje nadate! Mogu vas zateći pored tezge s lubenicama, u sopstvenom stanu dok je mama na poslu, ili u pravoj piratskoj tvrđavi. Najvažnije je da nikada ne prestanete da maštate, a žeđ za avanturom će vam sigurno pokazati put. Šest pisaca za djecu donosi uzbudljive priče — fantastične i bajkovite, smiješne i dirljive — o nevjerovatnim doživljajima u koje djeca vjeruju, a za kojima odrasli toliko čeznu.', 'Шесть ярких историй напомнят и детям, и родителям, что грандиозная экспедиция может начаться даже с похода за арбузом!', 'Six captivating stories to remind both kids and parents that a grand expedition can begin right beside a humble watermelon stand!', 'Šest uzbudljivih priča podsjetiće i djecu i roditelje da velika ekspedicija može započeti čak i kupovinom lubenice!', '/covers/DP-1235.webp', '#d9653b', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["adventure","funny","real"]', '["short stories","adventures","imagination","childhood","anthology"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вы-не-были-на-таити--1236', 'DP-1236', 'Вы не были на Таити?', 'Haven''t You Been to Tahiti?', 'Zar niste bili na Tahitiju?', 'Курляндский', 'Alexander Kurlyandsky', 'Aleksandar Kurljandski', '', 'Махаон', 2013, '978-5-389-02191-4', 6, 16, 'middle', '', 'Hilarious, dramatic, and unforgettable adventures of Kesha the parrot, who is forever throwing tantrums, fleeing his loyal friend Vovka, and boasting about exotic travels he never actually took.', 'Urnebesne i nezaboravne avanture svojeglavog i dramatičnog papagaja Keše, koji stalno bježi od svog vjernog dječaka Vovke i izmišlja basnoslovne priče o dalekim krajevima.', 'Легендарные приключения дерзкого попугая Кеши напомнят, что дома всё-таки кормят лучше всего!', 'The iconic misadventures of the dramatic parrot Kesha will remind you that home is where the best snacks are!', 'Kultne avanture dramatičnog papagaja Keše podsjetiće vas da se kod kuće ipak najbolje jede!', '/covers/DP-1236.webp', '#e67e22', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["funny","animals","adventure"]', '["parrot","humor","kesha","classic","friendship"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('басни-1237', 'DP-1237', 'Басни', 'Fables', 'Basne', 'Крылов', 'Ivan Krylov', 'Ivan Krilov', '', 'Махаон', 2020, '978-5-389-10692-5', 6, 16, 'middle', '', 'Ivan Krylov''s timeless poetic fables bring a colorful cast of clever foxes, vain crows, clumsy bears, and wolves to life. Through catchy verses and vivid animal allegories, these beloved tales gently satirize human follies, teaching sharp moral lessons with warmth, humor, and brilliant folk wisdom.', 'Bezvremenske basne Ivana Krilova u stihovima oživljavaju galeriju lukavih lisica, taštih vrana, nespretnih medvjeda i vukova. Kroz pamtljive rime i duhovite alegorije o životinjama, ove klasične priče sa toplinom i oštroumnošću podsjećaju na ljudske vrline i mane.', 'Мудрые и невероятно смешные басни в стихах, где лесные звери ведут себя подозрительно похоже на нас с вами!', 'Wise and delightfully witty poetic tales where forest animals behave remarkably like the people around us!', 'Mudre i nevjerovatno duhovite priče u stihovima gdje se šumske životinje ponašaju sumnjivo slično ljudima!', '/covers/DP-1237.webp', '#3d6647', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["animals","funny","real"]', '["fables","classics","poetry","animals","morals"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('саджо-и-ее-бобры-1238', 'DP-1238', 'Саджо и ее бобры', 'The Adventures of Sajo and Her Beaver People', 'Sadžo i njeni dabrovi', 'Серая Сова', 'Grey Owl', 'Siva Sova', '', '', NULL, NULL, 6, 16, 'middle', '', 'A touching classic set in the Canadian wilderness about an Indigenous girl named Sajo and her brother who adopt two orphaned beaver kits, embarking on a daring rescue journey when the creatures are separated.', 'Dirljivi klasik smješten u kanadsku divljinu o domorodačkoj djevojčici Sadžo i njenom bratu koji usvajaju dva siročeta dabra, krećući u veliku avanturu spasavanja kada ih zla sudbina razdvoji.', 'Пронзительная и невероятно добрая северная история о дружбе индейской девочки с маленькими бобрятами, которая растопит любое сердце.', 'A tender wilderness tale of kinship between an Indigenous girl and two orphaned beaver kits that will warm your heart and stay with you forever.', 'Dirljiva priča iz divljine o prijateljstvu indijanske djevojčice i dva mala dabra koja će vam sigurno ugrijati srce.', NULL, '#2e5a44', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["animals","adventure","friends"]', '["beavers","nature","indigenous","wildlife","canada"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дивовижнi-пригоди-в-листовiй-ш-1239', 'DP-1239', 'дивовижнi пригоди в листовiй школi', 'Amazing Adventures in the Forest School', 'Nevjerovatne avanture u šumskoj školi', 'Всеволод Нестайко', 'Vsevolod Nestaiko', 'Vsevolod Nestajko', 'на украинском', 'Видавничий дім «Школа»', 2008, '978-966-429-005-7', 6, 16, 'middle', '', 'A beloved Ukrainian classic about gentle hedgehog Kosia and timid bunny Kolka who venture into a specialized forest school with Bear Valerian Pavlovych. Together with their woodland classmates, they learn bravery, solve funny forest mysteries, and discover the power of true friendship.', 'Omiljeni ukrajinski klasik o nježnom ježiću Kosji i plahom zecu Koljki koji polaze u šumsku školu kod učitelja medvjeda. Sa svojim šumskim drugarima uče o hrabrosti, rješavaju simpatične misterije i otkrivaju snagu pravog prijateljstva.', 'Самая добрая лесная сказка о преодолении страхов, школьных шалостях и крепкой дружбе зайчонка и ежонка!', 'Pack your backpack for the sweetest forest lessons, where shy woodland critters discover their inner courage and become lifelong friends!', 'Spakujte ruksak za najljepše šumske časove, gdje stidljiva bića pronalaze hrabrost i postaju najbolji prijatelji!', '/covers/DP-1239.webp', '#3b7a57', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["animals","friends","adventure"]', '["forest school","friendship","hedgehog","bunny","classic tales"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('феерични-пригоди-феи-та-еликси-1240', 'DP-1240', 'феерични пригоди Феи та еликсир щастя', 'Fairy Adventures: Fairies and the Elixir of Happiness', 'Bajkovite avanture: Vile i eliksir sreće', 'Юлита Ран', 'Yulita Ran', 'Julita Ran', 'на украинском', 'Ранок', 2021, '9786170970503', 6, 16, 'middle', '', 'Step into a sparkling realm where winged heroines embark on a magical quest to discover the secret recipe for true happiness. Filled with whimsy, friendship, and gentle enchantment, this delightful story reveals that the sweetest magic is found in the joy we share with others.', 'Zavirite u čarobni svijet gdje krilate vile kreću u uzbudljivu potragu za tajnim receptom za istinsku sreću. Kroz toplu priču o prijateljstvu i čaroliji, mališani otkrivaju da se najljepša magija krije u trenucima koje dijelimo sa onima koje volimo.', 'Хватайте щепотку пыльцы и верных друзей: рецепт настоящего счастья окажется куда проще и удивительнее любых зелий!', 'Grab a pinch of fairy dust and your best friends: the real recipe for happiness turns out to be far more wonderful than any potion!', 'Uzmite prstohvat vilinskog praha i najbolje drugare: pravi recept za sreću mnogo je ljepši od bilo kog magičnog napitka!', '/covers/DP-1240.webp', '#c084fc', 'nonfiction', 'ru', 'available', 'Категория: Дикий робот', '["magic","adventure","friends"]', '["fairies","magic","friendship","quest","happiness"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('пока-бьют-часы-1241', 'DP-1241', 'Пока бьют часы', 'While the Clock Strikes', 'Dok sat kuca', 'Софья Прокофьева', 'Sofya Prokofyeva', 'Sofja Prokofjeva', '', 'Эксмо', 2021, '978-5-04-155934-2', 6, 16, 'middle', '', 'A spellbinding classic fairy tale about a schoolgirl named Masha who discovers a magical cap of invisibility and journeys into the fantastical City of Merry Craftsmen to free its people from a wicked king before time runs out.', 'Uzbudljiva klasična bajka o djevojčici Maši koja pronalazi čarobnu kapu nevidljivku i dospijeva u tajanstveni Grad Veselih Majstora kako bi pomogla osloboditi njegove stanovnike od zlog kralja prije nego što sat prestane kucati.', 'Наденьте шапку-невидимку и поспешите спасти сказочный город — главное, успеть, пока бьют старинные часы!', 'Slip on the magical cap of invisibility and hurry to save the fairy-tale city before the ancient clock runs out of chimes!', 'Stavite čarobnu kapu nevidljivku i požurite da spasite bajkoviti grad — glavno je stići dok sat još otkucava!', '/covers/DP-1241.webp', '#2c405a', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["magic","adventure","friends"]', '["fairy tale","magic","bravery","invisibility","classic"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мой-дедушка-был-вишней-1242', 'DP-1242', 'Мой дедушка был вишней', 'My Grandpa Was a Cherry Tree', 'Moj djed je bio trešnja', 'Анджела Нанетти', 'Angela Nanetti', 'Angela Naneti', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Вишневое дерево по имени Феличе было посажено в честь рождения дочери и росло вместе с ней. И оно стало героем детских воспоминаний ее сына: его другом в играх, местом познания и приключений, символом непрерывности жизни. Главный герой этой книги ― дедушка, который со своей энергией, чувством свободы и способностью слышать дыхание дерева, кажется немного «странным». И так же легко, как дышит дерево, автор книги касается таких тем, как страдание и смерть близких, и искренне верит, что «человек не умирает, пока вишневые деревья продолжают жить для него». «Мой дедушка был вишней» вошла в список выдающихся книг для детей «Белые вороны», составляемый Международной мюнхенской юношеской библиотекой, была отмечена премиями в Италии, Германии и Франции, а автор ее, Анджела Нанетти, была номинирована на главную премию в детской литературе ― премию Андерсена.', 'A cherry tree named Felice was planted to celebrate a daughter''s birth and grew up right alongside her. Years later, it became the heart of her son Tonino''s childhood memories: a leafy fortress for games, secrets, and discovery, and a living testament to family ties. Tonino''s quirky, free-spirited grandfather teaches him to listen to the breath of the tree and understand that no one truly dies as long as someone loves them. A luminous and deeply moving story about growing up, family bonds, and the comforting continuity of life.', 'Trešnja po imenu Feliče posađena je u čast rođenja jedne djevojčice i rasla je zajedno s njom. Godinama kasnije, postala je središte djetinjstva njenog sina Tonina — drug u igri, skrovište za avanture i simbol neraskidive porodične ljubavi. Njegov neobični, slobodoumni djed uči ga da osluškuje disanje drveta i shvati da naši voljeni ostaju s nama sve dok žive u našem sjećanju. Dirljiva, topla i nezaboravna priča o odrastanju i snazi sjećanja.', 'Запаситесь носовыми платками и теплом: эта пронзительно светлая книга научит слышать, как дышат деревья, и беречь тех, кого мы любим.', 'Keep a handkerchief ready for happy tears: this luminous classic teaches us how to hear trees breathe and keep our loved ones alive in our hearts.', 'Pripremite maramice za suze ganuća: ova topla priča naučiće vas kako drveće diše i zašto oni koje volimo nikada zaista ne odlaze.', '/covers/DP-1242.webp', '#b83a4b', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real","friends"]', '["grandparents","family","nature","memory","growing up"]', 1792836322701, 1792845721079);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('самые-лучшие-волшебные-сказки--1243', 'DP-1243', 'Самые лучшие волшебные сказки. 1000 и 1 ночь', 'The Best Magic Fairy Tales: 1001 Nights', 'Najljepše čarobne bajke: 1001 noć', '', 'Arabian Folk Tales', 'Arapske narodne bajke', '', 'Три Кита / Дракон К', 1992, '5-85198-001-X', 6, 16, 'middle', 'дракон и к, три кита', 'A captivating treasury of classic tales from One Thousand and One Nights, featuring timeless stories of daring voyages, magical genies, clever heroes, and the enchanting wonders of the East.', 'Raskošna zbirka bezvremenih priča iz „Hiljadu i jedne noći“, ispunjena neustrašivim moreplovcima, moćnim duhovima iz lampe i čarolijama drevnog Orijenta.', 'Потри волшебную лампу и приготовься к захватывающему полёту на ковре-самолёте прямо в сердце восточных тайн!', 'Rub the magic lamp and get ready for an unforgettable magic carpet ride straight into ancient Eastern wonders!', 'Protrljaj čarobnu lampu i pripremi se za let na letećem ćilimu pravo u srce orijentalnih tajni!', '/covers/DP-1243.webp', '#1b2a47', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["magic","adventure"]', '["1001 nights","fairy tales","folklore","genies","oriental tales"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('балетные-туфельки-1244', 'DP-1244', 'Балетные туфельки', 'Ballet Shoes', 'Baletske cipelice', 'Ноэль Стритфилд', 'Noel Streatfeild', 'Noel Stritfild', '', 'Качели', NULL, NULL, 6, 16, 'middle', 'Три девочки-сироты растут в доме ученого-палеонтолога в старом добром Лондоне. А сам профессор путешествует где-то много лет. У Паулины, Петровой и Пози разные характеры и таланты. Только возможностей у племянницы профессора, которая их воспитывает, немного, и три названых сестры, вне зависимости от желания, обучаются в Детской академии танца и сценического мастерства. Паулину влечет и манит сцена. Для маленькой Пози главное в жизни - танцевать. Единственное, что ей осталось от родной матери, - балетные туфельки. А Петрова (между прочим, это имя) мечтает только о... самолетах. Как сложатся их судьбы? - Какими разными вещами мы будем заниматься! - воскликнула Паулина. - В таких разных местах, - добавила Пози. - А я вот подумала, - Петрова закатила глаза к потолку, - если бы другие девочки оказались на нашем месте, которой из нас они предпочли бы быть? Для старшего школьного возраста.', 'Three adopted orphan sisters grow up in the home of an eccentric paleontologist in good old London while the professor travels the world. Pauline, Petrova, and Posy couldn''t be more different: Pauline is drawn to the glamour of acting, little Posy''s whole world revolves around dancing in ballet shoes left by her mother, and Petrova dreams of nothing but aeroplanes and engines. To help make ends meet, the girls enter the Children''s Academy of Dancing and Stage Training, determined to put their family name in the history books.', 'Tri siročadi odrastaju u kući ekscentričnog paleontologa u starom Londonu dok profesor godinama putuje svijetom. Polin, Petrova i Pozi imaju potpuno različite talente: Polin privlači glumačka scena, za malu Pozi najvažniji je ples u baletskim cipelicama koje su joj jedina uspomena na majku, a Petrova mašta samo o avionima i motorima. Kako bi prebrodile novčane teškoće, sestre upisuju Dječiju akademiju plesa i scenske umjetnosti, odlučne da svoje neobično prezime upišu u istoriju.', 'Уютная и вдохновляющая английская классика о трёх непохожих сёстрах, готовых покорить театр, балетную сцену и даже бескрайнее небо!', 'A cozy, heartwarming classic about three adopted sisters determined to conquer the stage, the ballet, and even the open skies!', 'Topao i nadahnjujući engleski klasik o tri posvojene sestre odlučne da osvoje pozorište, baletsku scenu, pa čak i nebo!', '/covers/DP-1244.webp', '#c87588', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real","friends"]', '["балет","театр","сестры","лондон","мечты","классика"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('фрида-кало-1245', 'DP-1245', 'Фрида Кало', 'Frida Kahlo', 'Frida Kalo', 'Анна Герасименко, Лилу Рами', 'Anna Gerasimenko, Lilu Rami', 'Ana Gerasimenko, Lilu Rami', 'Ирина Вовк', 'clever', NULL, NULL, 6, 16, 'middle', '«Когда девочке было всего 6 лет, она тяжело заболела и после болезни стала хромать. „Фрида — деревянная нога!“ — дразнили ее ребята. Но она не слушала их. Она плавала, играла с мальчишками в футбол и даже занималась боксом. Фрида всегда была сильной и смелой девочкой.» Малыши узнают, как преодолевая любые невзгоды, можно осуществить свою мечту, а родители получат невероятное эстетическое удовольствие, перелистывая страницы книги «Фрида Кало. История про художницу, которая нарисовала себя и свою жизнь». Над изданием трудились постоянный автор издательства Clever Анна Герасименко, арт-директор Лилу Рами, а также иллюстратор Ирина Вовк. Благодаря их работе вы сможете с головой окунуться в мир Мексики, сказочных красок, любви и безграничного творчества!', 'When Frida was just six years old, she fell gravely ill and was left with a limp, but she never let bullies dim her spirit. She played soccer, went swimming, boxed, and stayed undeniably brave. This vibrant illustrated biography tells the inspiring story of an artist who painted her own life, overcoming any hardship with color, passion, and boundless creativity.', 'Kada je Frida imala samo šest godina, teško se razboljela i počela da hramlje, ali nikada nije dozvolila da joj to oduzme hrabrost. Igrala je fudbal, plivala, boksovala i sanjala velike snove. Ova živopisno ilustrovana biografija donosi priču o umjetnici koja je naslikala sopstveni život, savladavajući sve nedaće snagom mašte i beskrajne ljubavi prema umjetnosti.', 'Яркая и вдохновляющая история о смелости быть собой и о том, как превратить любые невзгоды в чистое искусство!', 'A vibrant and empowering celebration of Frida Kahlo that will inspire every young reader to paint their own path with courage and joy.', 'Ova topla i živopisna knjiga naučiće male čitaoce da uz hrabrost i malo boja i najveće prepreke mogu postati pravo remek-djelo.', '/covers/DP-1245.webp', '#1f5f8b', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real"]', '["biography","art","mexico","courage","frida kahlo"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('макс-и-горшок-1246', 'DP-1246', 'Макс и горшок', 'Max''s Potty', 'Maks i noša', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', '', 'Самокат', NULL, NULL, 6, 16, 'middle', '"Макс и горшок" - двухлетний малыш Макс всегда знает, чего хочет. Он очень гордится своим новым горшком и непременно должен научить им пользоваться песика. "Серия про Макса" - популярнейшие в мире книги для первого чтения малышей, написанные языком и с чувством юмора, хорошо понятными детям. Для дошкольного возраста. 2-е издание.', 'Two-year-old Max always knows what he wants! He is very proud of his brand-new potty and is absolutely determined to teach his little dog how to use it too. The ''Max'' series consists of world-famous first-reading board books for toddlers, told with clear language and a delightful sense of humor that little children adore.', 'Dvogodišnji Maks uvijek tačno zna šta želi! Veoma je ponosan na svoju novu nošu i čvrsto je odlučio da nauči svog psa kako da je koristi. Serijal o Maksu čini jedne od najpopularnijih knjiga na svijetu za najranije čitanje, pisane jednostavnim jezikom i s toplim humorom bliskim svakom mališanu.', 'Необычайно забавная и правдивая история о том, как научить пользоваться горшком не только себя, но и любимого пёсика!', 'A charming and hilarious milestone story showing that learning to use the potty is much more fun when your pup joins the lesson!', 'Preslatka i beskrajno duhovita priča koja pokazuje da je navikavanje na nošu mnogo zabavnije uz najboljeg psećeg druga!', '/covers/DP-1246.webp', '#d94b38', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","real","animals"]', '["potty training","toddlers","humor","dogs","first books"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('макс-и-подгузник-1247', 'DP-1247', 'Макс и подгузник', 'Max''s Diaper', 'Maks i pelena', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Малышу Максу надоело носить подгузник. Он предлагает примерить его Песику. Оба довольны результатами, но мама почему-то совсем не довольна! Первую книгу про Макса писательница Барбру Линдгрен и художница Эва Эриксон из Швеции выпустили в 1981 году. Последнюю - в 1991-м. Всего в серии вышло 11 книг. И именно они принесли настоящий мировой успех своим авторам. В 2014 году в Швеции серия была переиздана в современном оформлении. Гениальными по простоте и чувству юмора книгами их назвали организаторы Мемориальной премии Астрид Линдгрен, которую получила Барбру Линдгрен в 2014 году. Сейчас их уже причисляют к классике книжек-картинок для первого чтения с ребенком, а в свое время именно лаконичность и "детскость" языка вызвала немало протестов со стороны педагогов. В книге "Макс и лампа" Линдгрен и Эриксон даже написали специальное предисловие и "перевели" текст на язык взрослых, позволив себе немного иронии в адрес взрослых педантов. Но в любой стране, где бы они не выходили, книги получали признание и любовь читателей - и больших, и маленьких.', 'Little Max is completely done with diapers—so he generously decides his dog should wear one instead! Both boy and puppy are thrilled with the makeover, but Mom doesn''t seem quite as impressed. Created by celebrated Swedish author Barbro Lindgren and illustrator Eva Eriksson, this classic, delightfully understated picture book captures the stubborn humor and pure logic of toddlerhood.', 'Malom Maksu je dojadilo da nosi pelenu, pa je odlučio da je isproba na svom psu. Obojica su prezadovoljni novim modnim detaljem, ali mama nekako nije oduševljena! Ovu genijalnu i duhovitu slikovnicu stvorile su Barbro Lindgren i Eva Erikson, pretvorivši svakodnevne dječje nestašluke u pravu svjetsku klasiku.', 'Искромётный скандинавский шедевр о том, что бывает, когда подгузник примеряет лучший четвероногий друг!', 'A timeless, laugh-out-loud Scandinavian classic about toddler rebellion and a very cooperative puppy!', 'Bezvremenski duhovita skandinavska priča o malom tvrdoglavcu i njegovom psu koji rado dijeli pelenu!', '/covers/DP-1247.webp', '#e89252', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","real","animals"]', '["toddlers","picture book","dogs","humor","growing up"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('выходи-кто-где-живет-1248', 'DP-1248', 'Выходи! кто где живет', 'Come Out! Who Lives Where?', 'Izađi! Ko gdje živi', 'Сюзанна Риха', 'Susanne Riha', 'Suzane Riha', '', 'Качели', NULL, NULL, 6, 16, 'middle', 'Стать бы ветерком и провести весь год на природе: в лесу и в поле, на речке. Ветерок всех видит и слышит, а его никто не пугается. Можно увидеть, где живут, что едят звери и птицы. Чем занимаются весь год деревья и цветы. Какой месяц для какого растения главный. Как дерево наращивает кольца. Когда и где появляются малыши... Всё любопытно, всё интересно. Мы, конечно, не можем превратиться в ветерок, но зато можем прочитать и рассмотреть чудесную книжку Сюзанны Рихи и многое узнать.', 'Imagine turning into a gentle breeze and spending the whole year outdoors—wandering through forests, meadows, and riversides where no creature fears your presence. You could discover where animals build their homes, observe trees adding new rings, and watch nature burst into bloom. Susanne Riha''s gorgeously illustrated guide opens a window into the secret, seasonal lives of wildlife and plants.', 'Zamislite da se pretvorite u blagi povjetarac i provedete čitavu godinu u prirodi: u šumi, polju i kraj rijeke, posmatrajući sve skrivene kutke a da vas se niko ne uplaši. Otkrijte gdje životinje prave domove, kako drveće stvara godove i kada se rađaju mladunci. Predivno ilustrovani prirodnjački vodič Suzane Rihe otvara prozor u čudesne sezonske cikluse biljnog i životinjskog svijeta.', 'Загляните в гости к барсукам, птицам и вековым дубам, не потревожив ни единого лесного жителя!', 'Peek into the cozy homes of badgers, birds, and ancient oaks without startling a single woodland creature!', 'Zavirite u tople domove jazavaca, ptica i drevnih hrastova, a da ne uplašite nijednog šumskog stanovnika!', '/covers/DP-1248.webp', '#4a7c59', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["animals","real","adventure"]', '["nature","wildlife","forest","seasons","ecology"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('котофеи-1249', 'DP-1249', 'Котофеи', 'The Cat Fairies', 'Kotofeji', 'Ольга Фадеева', 'Olga Fadeeva', 'Olga Fadejeva', '', 'Речь', NULL, NULL, 6, 16, 'middle', 'Чудесам не обязательно дожидаться наступления Нового года! Вот и в семье Хвоста и Кокосика произошло исключительное событие: хозяева котов выиграли в конкурсе главный приз - новогодние каникулы в загородном доме отдыха. И пускай домосед Хвост не очень-то обрадовался предстоящей поездке, зато Кокосику не терпелось отправиться навстречу новым впечатлениям. Но каково же было удивление обоих, когда друзья попали… в обычную городскую гостиницу для кошек! Как же теперь отыскать хозяев, да ещё успеть встретить Новый год? Будьте уверены, у Хвоста и Кокосика всё получится - впереди КотоФеев ждёт настоящая лесная сказка!', 'Miracles don’t have to wait for New Year''s Eve! Tail and Kokosik''s humans have won a dream holiday at a countryside retreat. While couch-potato Tail isn''t thrilled about leaving home, little Kokosik can''t wait for adventure. But shock awaits them: instead of a snowy vacation, the two friends are dropped off at an ordinary city cat hotel! How will they track down their humans in time to celebrate New Year''s Eve? Rest assured, these whiskered cat-fairies will find their way straight into a magical winter wonderland.', 'Čuda ne moraju čekati doček Nove godine! Vlasnici mačora Repa i Kokosića osvojili su zimski odmor u seoskom odmaralištu. Dok se lijeni Rep nije previše obradovao putovanju, Kokosić je jedva čekao avanturu. Međutim, umjesto na idiličnom odmoru, prijatelji završavaju u običnom gradskom hotelu za mačke! Kako sada pronaći svoje ljude i stići na novogodišnje slavlje? Ovi čarobni krzneni junaci kreću na put i čeka ih prava zimska šumska bajka.', 'Уютная и снежная новогодняя сказка о кошачьей дружбе, смекалке и настоящих крылатых чудесах, которая согреет любого в зимний вечер!', 'A cozy, snowy holiday adventure proving that with a loyal friend and a dash of cat magic, you can conquer any winter storm!', 'Ušuškana, sniježna novogodišnja bajka o mačijem prijateljstvu i domišljatosti koja će vas ugrijati i donijeti pravi praznični duh!', '/covers/DP-1249.webp', '#3b6e8c', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["animals","magic","adventure"]', '["cats","winter","new year","friendship","magic"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('томасина-1250', 'DP-1250', 'Томасина', 'Thomasina', 'Tomasina', 'Пол Гэллико', 'Paul Gallico', 'Pol Galiko', '', 'Лабиринт', NULL, NULL, 6, 16, 'middle', 'Одна из самых известных книг американского писателя Пола Гэллико о рыжеволосой девочке Мэри Руа, рыжей кошке Томасине и о чуде, жизненно необходимом и ребёнку, и взрослому. Трогательная и захватывающая история заставляет печалиться и радоваться вместе с героями, учит ценить любовь и милосердие. Иллюстрации Натальи Демидовой замечательно передают атмосферу книги - тишину шотландского городка, молчаливую суровость его взрослых обитателей, милую непосредственность героев-детей и неповторимое обаяние рыжей Томасины - лучшей на свете кошки, в которую просто невозможно не влюбиться. Для детей 10-12 лет.', 'Set in a quiet Scottish town, this beloved classic tells the touching story of red-haired Mary Ruadh, her fiercely loved ginger cat Thomasina, and the miracle of compassion that softens the heart of a grieving veterinarian father. Filled with atmospheric warmth, silent highland secrets, and tender wonder, it is an unforgettable tale about love, healing, and the mysterious power of kindness.', 'Smještena u mirnom škotskom gradiću, ova voljena priča govori o riđokosoj djevojčici Meri Ruah, njenoj voljenoj riđoj mački Tomasini i čudu saosjećanja koje omekšava srce strogog oca veterinara. Dirljiva i duboka, ova knjiga podsjeća i djecu i odrasle koliko su ljubav, oproštaj i nježnost važni za istinsko iscjeljenje.', 'Запасайтесь носовыми платками и теплым пледом: эта рыжая шотландская кошка растопит самое суровое сердце и напомнит о силе любви!', 'Keep a cozy blanket and some tissues handy: this ginger Scottish cat knows exactly how to heal wounded hearts and work quiet miracles.', 'Pripremite toplo ćebe i maramice: ova riđa škotska mačka zna kako da otopi i najtvrđe srce i podsjeti na pravo čudo ljubavi!', '/covers/DP-1250.webp', '#c46210', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["animals","friends","magic"]', '["cats","scotland","kindness","healing","classic"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чудесный-ларец-1251', 'DP-1251', 'Чудесный ларец', 'The Wondrous Casket', 'Čudesna škrinja', 'В.И. Даль, Пушкин', 'Vladimir Dal, Alexander Pushkin', 'Vladimir Dalj, Aleksandar Puškin', '', 'Молодая гвардия, 1994', NULL, NULL, 6, 16, 'middle', 'Книгу составили русские народные сказки, загадки и пословицы, собранные и обработанные известным русским писателем Владимиром Ивановичем Далем, и знаменитые поэтические сказки Александра Сергеевича Пушкина, Издание подготовлено для детей младшего возраста.', 'This treasury brings together Russian folk tales, riddles, and proverbs collected and adapted by the renowned lexicographer Vladimir Dal, alongside Alexander Pushkin''s timeless fairy tales in verse.', 'Ova riznica objedinjuje ruske narodne bajke, zagonetke i poslovice koje je sakupio i obradio Vladimir Dalj, uz bezvremene poetske bajke Aleksandra Puškina.', 'Загляните в этот ларец — там спрятаны самые певучие сказки Пушкина и сокровища народной мудрости от дедушки Даля!', 'Peek inside this wondrous treasure chest to uncover Pushkin’s melodious verses and folklore gems lovingly gathered by Vladimir Dal!', 'Zavirite u ovu čudesnu škrinju i otkrijte Puškinove melodične stihove i biserje narodnih mudrosti koje je sakupio Vladimir Dalj!', '/covers/DP-1251.webp', '#a85232', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["magic","adventure"]', '["folk tales","poetry","riddles","classics","folklore"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('шедевр-1252', 'DP-1252', 'Шедевр', 'Masterpiece', 'Remek-djelo', 'Элис Броуч', 'Elise Broach', 'Elis Brouč', '', 'Розовый жираф', NULL, NULL, 6, 16, 'middle', 'Марвин - самый обыкновенный жук, его семья поселилась под кухонной мойкой в квартире Помпадеев в Нью-Йорке. Джеймс Помпадей - самый обыкновенный одиннадцатилетний мальчик, которому подарили на день рождения набор для рисования: чернила и перо. И Марвин сделал Джеймсу подарок - нарисовал изящнейшую миниатюру. А вся слава достала Джеймсу. Так, соверешенно неожиданно для самих себя друзья (разве может кто-то запретить одиннадцатилетнему мальчику дружить с жуком?!) оказались участниками и главными героями увлекательнейшего арт-детектива, в котором перемешалось все: подделка шедевра великого мастера, хитроумные планы грабителей и полные настоящих опасностей приключения. Удастся ли Джеймсу спасти Метрополитен от ограбления и вернуть утраченные рисунки Альбрехта Дюрера? Ясно лишь одно - без помощи Марвина ему не обойтись. Для детей от 12 лет.', 'Marvin is an ordinary beetle living under the kitchen sink in a Manhattan apartment. James is an eleven-year-old boy who receives a pen-and-ink drawing set for his birthday. When Marvin dips his legs into the ink and creates an exquisite miniature masterpiece, James gets all the credit. Before they know it, this unusual duo gets swept into a high-stakes art heist mystery involving Albrecht Dürer drawings and dangerous thieves at the Metropolitan Museum of Art. One thing is certain: James cannot pull this off without his six-legged genius friend.', 'Marvin je sasvim obična buba koja sa porodicom živi ispod kuhinjskog sudopera u njujorškom stanu. Džejms je jedanaestogodišnji dječak koji za rođendan dobija mastilo i pero za crtanje. Kada Marvin nacrta prefinjenu minijaturu, sva slava nehotice pripada Džejmsu. Ubrzo se ova dva neobična prijatelja nalaze u središtu uzbudljivog umjetničkog detektivskog zapleta koji uključuje Albrehta Direra, falsifikate i opasnu pljačku u muzeju Metropoliten. Jedno je sigurno — Džejms ne može riješiti misteriju bez svog malenog pomoćnika.', 'Кто бы мог подумать, что гениальным художником и напарником в расследовании музейной кражи века станет крошечный жук из-под кухонной раковины!', 'Who would have thought that a brilliant master artist and the ultimate partner in cracking an art museum heist would be a tiny beetle from under the kitchen sink!', 'Ko bi rekao da će genijalni slikar i najbolji partner u rješavanju muzejske pljačke vijeka biti majušna buba ispod kuhinjskog sudopera!', '/covers/DP-1252.webp', '#1f3b58', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","friends","animals"]', '["детектив","искусство","дружба","музей","нью-йорк"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рико-оскар-и-разбитое-сердце-1253', 'DP-1253', 'Рико, Оскар и разбитое сердце', 'Rico, Oskar and the Broken Heart', 'Riko, Oskar i slomljeno srce', 'Андреас Штайнхефель', 'Andreas Steinhöfel', 'Andreas Štajnhofel', '', 'Самокат', NULL, NULL, 6, 16, 'middle', 'Рико и Оскар снова расследуют дело! И на этот раз в нем замешаны лотерея, сумка и...мама Рико! Расследование, конечно, открывает глаза мальчишкам и их помощникам не только на преступление, но и на картину отношений между людьми, дружбу, любовь, жестокость и самопожертвование. Как и первая книга о Рико и Оскаре, эта история написана от лица героя — и мы видим мир совершенно непривычно и остро, глазами мальчика с особым мышлением и восприятием мира. Ранее в «Самокате» вышла первая книга серии — «Рико, Оскар и тени темнее темного». Книги о Рико и Оскаре получили Немецкую детскую литературную премию, были экранизированы в Германии и уже стали современной классикой детского и подросткового чтения. Награды: Немецкая детская литературная премия, 2009 Список IBBY, 2010', 'Rico and Oskar are on the case again! This time, the mystery involves bingo games, a suspicious handbag, and... Rico''s own mother. As their unconventional investigation unfolds, the two inseparable friends uncover not only clues to petty crimes, but also poignant truths about friendship, sacrifice, and the complicated world of grown-up relationships. Narrated with Rico''s uniquely candid and heartwarming perspective, this award-winning German mystery is as tender as it is hilarious.', 'Riko i Oskar ponovo vode istragu! Ovog puta u slučaj su umiješani bingo, tajanstvena torba i... Rikova mama. Istraga dvojici nerazdvojnih prijatelja ne otkriva samo pozadinu neobične prevare, već i složeni svijet odraslih, povjerenja, prijateljstva i ljubavi. Ispričana iz iskrene i tople perspektive dječaka sa posebnim pogledom na svijet, ova nagrađivana detektivska priča pruža savršen balans smijeha i emocija.', 'Остроумный детектив с огромным сердцем о двух совершенно непохожих друзьях, которые видят мир ярче и глубже многих взрослых.', 'A witty, deeply touching detective tale proving that two inseparable best friends can crack any case—even the mystery of a broken heart.', 'Duhovita detektivska priča velikog srca o dva nerazdvojna prijatelja koji svijet vide ljepše, iskrenije i dublje od mnogih odraslih.', '/covers/DP-1253.webp', '#b82a38', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","friends","adventure"]', '["детектив","дружба","семья","взросление","юмор"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('москвест-1254', 'DP-1254', 'Москвест', 'Moskvest', 'Moskvest', 'Жвалевский-Пастернак', 'Andrey Zhvalevsky, Evgenia Pasternak', 'Andrej Žvalevski, Jevgenija Pasternak', '', 'Время', NULL, NULL, 6, 16, 'middle', 'История - дама капризная. Стоило одному неосторожному подростку ругнуть ее у стен Кремля, и его вместе с собеседницей откинуло так далеко, что выбираться придется целую книгу. "Куда мы попали? Как нам отсюда выбраться? Как выжить?" - спрашивают герои книги. Очень хочется им помочь, ведь у нас под рукой интернет, а они мало что помнят даже из школьного курса! Да и школьный курс не всегда совпадает с тем, что происходит перед изумленным взглядом невольных путешественников во времени. Особенно когда приходится столкнуться с дружинниками Долгорукого, давать советы Калите, защищать Москву от Тохтамыша или работать толмачом у английского посла. А еще - это роман о любви... 6-е издание, исправленное.', 'History is a whimsical lady. When a careless teen vents his frustration with history right by the Kremlin walls, he and his female companion are thrown centuries into the past, embarking on an epic journey to return home. Left without Google or cheat sheets, they can barely recall the basics from their school textbooks—which don''t always match the harsh reality of living past anyway. Facing medieval warriors, advising Grand Prince Ivan Kalita, defending against warlord Tokhtamysh, and serving as translators for an English ambassador, they navigate danger, wits, and an unexpected blossoming romance.', 'Istorija je hirovita dama. Bilo je dovoljno da jedan neoprezni tinejdžer opsuje istoriju pored zidina Kremlja, pa da zajedno sa svojom saputnicom bude odbačen vjekovima unazad. Bez interneta i telefona, heroji jedva uspijevaju da se sjete školskih lekcija—koje se, uz to, nimalo ne poklapaju sa onim što vide svojim očima! Od susreta sa ratnicima Jurija Dolgorukog i savjetovanja kneza Ivana Kalite, do odbrane od kana Tohtamiša i prevođenja engleskom poslaniku, ovo nevjerovatno putovanje kroz vrijeme jeste i iskrena priča o prvoj ljubavi.', 'Захватывающий исторический квест сквозь века без интернета, подсказок и права на ошибку — лучший способ полюбить историю!', 'A thrilling time-travel quest through the centuries without Wi-Fi, cheat sheets, or room for error—the ultimate way to fall in love with history!', 'Uzbudljiva potraga kroz vjekove bez interneta, puškica i prava na grešku — najbolji način da se zavoli istorija!', '/covers/DP-1254.webp', '#a33327', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","friends","funny"]', '["time travel","history","adventure","middle school","moscow"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('это-мои-эмоции-1255', 'DP-1255', 'Это - мои эмоции', 'These Are My Emotions', 'Ovo su moje emocije', 'Наталья Ремиш', 'Natalia Remish', 'Natalija Remiš', '', 'Поляндрия', NULL, NULL, 6, 16, 'middle', 'Может ли ваш ребёнок понять, что он чувствует, и назвать эту эмоцию? Способен ли справиться с ней и помочь себе, находясь под её влиянием? Кажется, что всё просто. Здесь нервничает, здесь капризничает, здесь устал... Но это не эмоции как таковые, это уже следствие — различные реакции ребёнка на внутреннее эмоциональное состояние. Именно понимание его поможет ребёнку контролировать не только своё поведение, но и, что более важно, — уровень своего благополучия. Детей можно научить различать эмоции, рассказывать о них, конструктивно себя вести. В этой книге вы найдёте наглядные иллюстрации ситуаций и практические задания для детей, чтобы разобраться в четырёх эмоциях, — вина, ревность, зависть, страх.', 'Can your child pinpoint what they are feeling and give that emotion a name? Being cranky, nervous, or tired are often just surface reactions to deeper internal states. Understanding what is happening inside helps children manage not only their behavior, but their overall sense of well-being. Through clear illustrations of everyday situations and practical exercises, this book guides young readers in untangling four tricky feelings: guilt, jealousy, envy, and fear.', 'Može li vaše dijete prepoznati šta osjeća i dati toj emociji pravo ime? Nervoza, hirovi ili umor često su samo reakcije na dublje unutrašnje stanje. Upravo razumijevanje tih osjećanja pomaže djetetu da kontroliše ponašanje i očuva unutrašnji mir. Uz jasne ilustracije životnih situacija i praktične zadatke, ova knjiga pomaže djeci da razumiju i prevaziđu četiri teške emocije: krivicu, ljubomoru, zavist i strah.', 'Незаменимый компас по внутреннему миру, который научит договариваться со страхом, завистью и виной без слёз и ссор.', 'An essential emotional compass that helps kids befriend big, tricky feelings like guilt, jealousy, and fear with kindness and clarity.', 'Neprocjenjiv vodič kroz unutrašnji svijet koji uči djecu kako da se nose sa strahom, zavišću i krivicom bez suza i svađa.', '/covers/DP-1255.webp', '#e07a5f', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real"]', '["emotions","psychology","feelings","growing up","self-regulation"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('санька-и-море-1256', 'DP-1256', 'Санька и море', 'Sanka and the Sea', 'Sanjka i more', 'Виктория Ледерман', 'Victoria Lederman', 'Viktorija Lederman', '', 'Пять четвертей', NULL, NULL, 6, 16, 'middle', 'Сенька Шмелёв окончил первый класс и впервые в жизни едет с родителями на море. Он и представить себе не мог, насколько оно невероятное: огромное, шумное, солёное… В бескрайних водных просторах живут дельфины и прозрачные медузы, а берег усыпан блестящими гладкими камушками. Сколько секретов оно хранит! И если внимательно наблюдать, может быть, море согласится раскрыть хотя бы некоторые из них? Виктория Ледерман - классик современной детской литературы и лауреат множества премий, среди которых - "Книгуру", Корнейчуковская, Крапивинская, "Алиса", посвящённая памяти Кира Булычёва. От Калининграда до Владивостока мальчишки и девчонки с удовольствием читают книги Виктории Ледерман и узнают в персонажах себя и своих сверстников. Герой её новой повести Сенька Шмелёв - мечтательный, немного застенчивый, но верящий в чудеса. Не сомневаемся, что и вы захотите с ним подружиться! Для младшего и среднего школьного возраста.', 'Senka has just completed first grade and is heading to the sea with his parents for the very first time in his life. He could never have imagined how magnificent it would be: immense, roaring, salty, with playful dolphins, translucent jellyfish, and smooth pebbles along the shore. How many secrets does the vast water keep, and will it share them with an observant, dreamy boy? A delightfully sun-drenched story about growing up and the wonder of first discoveries.', 'Senjka je upravo završio prvi razred i po prvi put u životu putuje na more sa roditeljima. Nije mogao ni da zamisli koliko je ono veličanstveno: ogromno, bučno i slano, puno delfina, meduza i glatkih oblutaka na obali. Koliko samo tajni more krije! Ako pažljivo posmatra, možda će mu more otkriti poneku od njih. Viktorija Lederman donosi divnu, suncem okupanu priču o radoznalosti i magiji prvih velikih otkrića.', 'Идеальное чтение перед походом на пляж для всех, кто помнит трепет своей самой первой встречи с морем!', 'The perfect seaside read for anyone who remembers the pure magic of seeing the ocean for the very first time!', 'Savršena knjiga za ponijeti na plažu, namijenjena svima koji pamte čaroliju svog prvog susreta s morem!', '/covers/DP-1256.webp', '#2a7f9d', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real","adventure"]', '["sea","summer","vacation","growing up","childhood"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большая-книга-музеев-1257', 'DP-1257', 'Большая книга музеев', 'The Big Book of Museums', 'Velika knjiga muzeja', 'Ева Бенсар', 'Eva Bensard', 'Eva Bensar', 'Бенджамен Шо', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Париж, Пекин, Санкт-Петербург, Рим, Амстердам, Мехико — отправьтесь в путешествие по 12 удивительным музеям. Экскурсию проведут лучшие из лучших: хранители музеев, архитекторы, реставраторы, художники... и другие, более неожиданные проводники! Шедевры мирового искусства, необычные профессии и советы к просмотру — музеи оживают на страницах этой книги.', 'Paris, Beijing, Saint Petersburg, Rome, Amsterdam, Mexico City — embark on a journey through 12 extraordinary museums! Guided by curators, architects, restorers, artists, and even some surprising companions, you''ll uncover world masterpieces, learn about unusual professions, and discover expert visiting tips as museums come alive across these vibrant pages.', 'Pariz, Peking, Sankt Peterburg, Rim, Amsterdam, Meksiko Siti — krenite na putovanje kroz 12 nevjerovatnih muzeja! Ture vode najbolji od najboljih: kustosi, arhitekte, restauratori, umjetnici... ali i sasvim neočekivani vodiči. Remek-djela svjetske umjetnosti, neobične profesije i korisni savjeti — muzeji oživljavaju na stranicama ove knjige.', 'Загляните за кулисы величайших мировых музеев без очередей и скучных экскурсий!', 'Skip the ticket lines and sneak behind the scenes of the world''s greatest museums with the coolest insiders!', 'Zavirite iza kulisa najslavnijih svjetskih muzeja bez čekanja u redovima i dosadnih vodiča!', '/covers/DP-1257.webp', '#b85d38', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","real"]', '["музеи","искусство","путешествия","профессии","шедевры"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('большое-книжное-приключение-за-1258', 'DP-1258', 'Большое книжное приключение: за кулисами книгоиздания', 'The Great Book Adventure: Behind the Scenes of Publishing', 'Velika avantura knjige: iza kulisa izdavaštva', 'Стефани Верне, Камий де Кюссак', 'Stéphanie Vernet, Camille de Cussac', 'Stefani Verne, Kamij de Kisak', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Кто выбирает тему, иллюстрации, формат и даже решает, какой будет цена книги? Прежде чем попасть к вам в руки, она проходит через все звенья длинной книжной цепочки — это настоящая командная работа! Познакомьтесь с автором, главным редактором, иллюстратором, полиграфистом, книготорговцем и библиотекарем и узнайте, чем они живут. От портретов к историям, от догадок к ответам. Готовы заглянуть за кулисы книгоиздания?', 'Who picks the topic, the illustrations, the format, and even sets the price of a book? Before it lands in your hands, a book journeys through a fascinating creative chain—a true team effort! Meet the author, chief editor, illustrator, printer, bookseller, and librarian to discover their daily craft. Are you ready to take a peek behind the scenes of bookmaking?', 'Ko bira temu, ilustracije, format i ko uopšte odlučuje o cijeni knjige? Prije nego što stigne u vaše ruke, knjiga prolazi kroz dugačak lanac stvaranja — pravi timski rad! Upoznajte pisca, urednika, ilustratora, štampara, knjižara i bibliotekara i saznajte kako izgleda njihov svijet. Jeste li spremni da zavirite iza kulisa nastanka knjige?', 'Загляните за кулисы типографий и издательств, чтобы узнать, сколько заботливых рук создают каждую любимую историю!', 'Peek behind the scenes of print shops and publishers to discover how many caring hands bring each beloved story to life!', 'Zaviri iza kulisa štamparija i izdavača da otkriješ koliko brižnih ruku stvara svaku omiljenu priču!', '/covers/DP-1258.webp', '#e75a3c', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real","adventure"]', '["books","publishing","how it works","professions","illustration"]', 1792836322701, 1792845725955);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рабочие-лодки-1259', 'DP-1259', 'Рабочие лодки', 'Working Boats: An Inside Look at Ten Amazing Vessels', 'Radni brodovi: Pogled iznutra na deset nevjerovatnih plovila', 'Том Крестодина', 'Tom Crestodina', 'Tom Krestodina', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Взойди на борт и погрузись в удивительный мир промышленных судов. Хочешь узнать, как проводят на воде спасательные операции? Как живут исследователи на научных судах? Что нужно для ловли крабов в ледяных водах северной части Тихого океана? Эта книга покажет суда в разрезе, со всеми мельчайшими деталями и расскажет, как это — жить и работать на десяти удивительных лодках', 'Step aboard and dive into the fascinating world of working ships. Discover how maritime rescue missions unfold, how marine scientists live aboard research ships, and what it takes to haul crab in the icy waters of the North Pacific. Featuring intricate cross-section drawings, this book reveals every tiny detail of life and work on ten extraordinary vessels.', 'Zakoračite na palubu i uronite u uzbudljiv svijet industrijskih i istraživačkih brodova. Otkrijte kako se izvode spasilačke akcije na vodi, kako naučnici žive na istraživačkim plovilima i šta je potrebno za lov na krabe u ledenim vodama sjevernog Pacifika. Kroz detaljne presjeke, ova knjiga otkriva kako izgleda život i rad na deset izuzetnih plovila.', 'Загляните под палубу настоящих морских трудяг — от краболовов до спасательных катеров — в невероятно детальных и живых разрезах!', 'Peek beneath the decks of real seafaring workhorses — from crab boats to rescue vessels — packed with breathtaking cutaway details!', 'Zavirite ispod palube pravih morskih radnika — od ribarica za krabe do spasilačkih čamaca — uz nevjerovatno detaljne presjeke!', '/covers/DP-1259.webp', '#235575', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","real"]', '["ships","ocean","engineering","cross-sections","technology"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('карта-приятных-воспоминаний-1260', 'DP-1260', 'Карта приятных воспоминаний', 'The Map of Good Memories', 'Mapa lijepih uspomena', 'Фран Нуньо, Зузанна Целей', 'Fran Nuño, Zuzanna Celej', 'Fran Nunjo, Zuzana Celej', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Некоторые места неразрывно связаны с воспомина­ниями о счастливых моментах нашей жизни. Девочка Зоя, которая вместе с семьёй вынуждена покинуть родной город из-за войны, перед отъездом решает сохранить эти моменты в памяти. Она рисует «карту приятных воспоминаний» и отмечает на ней важные для себя места родного города. Теперь Зоя спокойна: эти воспоминания останутся с ней навсегда', 'Certain places are forever linked to the happiest moments of our lives. Zoe, a young girl forced to leave her hometown because of war, decides to preserve these moments before departing. She draws a ''map of good memories'', marking all the places dear to her heart so that her home will always stay with her.', 'Neka mjesta su zauvijek povezana sa srećnim trenucima našeg života. Djevojčica Zoja, primorana da sa porodicom napusti rodni grad zbog rata, odlučuje da prije odlaska sačuva te trenutke. Ona crta „mapu lijepih uspomena“ i na njoj označava sva draga mjesta, znajući da će ta sjećanja zauvijek ostati s njom.', 'Трогательная и нежная история о том, как сохранить тепло любимого дома в сердце, даже когда приходится уезжать далеко-далеко.', 'A tender and touching story showing that no matter how far you must travel, the warmth of home stays safely folded in your heart.', 'Dirljiva i nježna priča o tome kako sačuvati toplinu rodnog doma u srcu, čak i kada moraš poći daleko.', '/covers/DP-1260.webp', '#c49a6c', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real"]', '["memories","home","hope","empathy","war"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('очень-может-быть-20-правдивых--1261', 'DP-1261', 'Очень может быть. 20 правдивых (и не очень) историй', 'Quite Possibly: 20 True (and Not-So-True) Stories', 'Vrlo moguće: 20 istinitih (i ne baš istinitih) priča', 'Камиль де Брейне, Ярне Дарен', 'Camille de Bruyne, Jarne Daeren', 'Camille de Bruyne, Jarne Daeren', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Очень может быть, когда-то давным-давно жила-была книга с двадцатью историями, которые произошли на самом деле, а может быть и не происходили вовсе. Эта книга — игра. Можно начать с самого начала или открыть книгу на любой странице, прочитать историю и, прежде чем переворачивать страницу, нужно угадать, правдивая это история или чистой воды выдумки.', 'Once upon a time, there was a book packed with twenty fascinating stories that either really happened or never occurred at all. This book is an exhilarating game: open it to any page, read the tale, and test your instincts by guessing whether it is absolute fact or pure fiction before flipping the page to reveal the truth.', 'Vrlo je moguće da je nekada davno postojala knjiga sa dvadeset priča koje su se zaista desile, a možda i nijesu uopšte. Ova knjiga je prava igra: možete je otvoriti na bilo kojoj stranici, pročitati priču i, prije nego što okrenete list, pogoditi da li je u pitanju gola istina ili čista izmišljotina.', 'Проверьте свою интуицию и детективное чутьё: сможете ли вы отличить невероятную правду от ловко замаскированной выдумки?', 'Test your intuition and detective skills: can you tell an unbelievable truth from a cleverly crafted lie?', 'Testirajte svoju intuiciju i detektivski njuh: možete li razlikovati nevjerovatnu istinu od vješte izmišljotine?', '/covers/DP-1261.webp', '#e9a738', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real","funny"]', '["trivia","true or false","facts","interactive","curiosity"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('билли-и-гены-1262', 'DP-1262', 'Билли и гены', 'Billy and the Genes', 'Bili i geni', 'Стефан Боонен, Мелвин', 'Stefan Boonen, Melvin', 'Stefan Bonen, Melvin', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Эта книга расскажет тебе о мальчике Билли и о его генах. Гены — это крошечные частички твоего организма. Каждый ребёнок получает их от папы и мамы. Гены есть повсюду: у тебя в слюне, в волосах, в поте, в пальцах на ногах, во рту, внутри и снаружи. Повсюду! Голубые или карие у тебя глаза? Какой формы твои ладошки? Быстро ли ты бегаешь? Любишь ли ты шоколад? Да что ни возьми — всё это решают твои гены!', 'This book tells the story of a boy named Billy and his tiny, fascinating genes. Genes are microscopic parts of your body that you inherit from your mom and dad. They are everywhere: in your hair, your toes, your saliva, and all over you, inside and out! Why are your eyes blue or brown? Why do you run fast or crave chocolate? Come find out how your genes secretly decide almost everything about you!', 'Ova knjiga priča o dječaku Biliju i njegovim genima — sićušnim djelićima tvog tijela koje dobijaš od mame i tate. Geni su svuda: u tvojoj kosi, prstićima, pljuvački, unutra i spolja! Jesu li ti oči plave ili smeđe? Da li brzo trčiš i obožavaš čokoladu? Zaroni u ovu zabavnu priču i otkrij šta sve o tebi odlučuju tvoji tajanstveni geni!', 'Весёлый и наглядный путеводитель по собственной ДНК, который объяснит, почему вы так заразительно смеётесь или обожаете шоколад!', 'A cheerful, brilliantly illustrated guide to your own DNA that explains why you laugh like your dad or love chocolate like your mom!', 'Veseo i slikovit vodič kroz sopstveni DNK koji objašnjava zašto se tako zarazno smiješ ili obožavaš čokoladu baš kao tvoji roditelji!', '/covers/DP-1262.webp', '#4388cc', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","real"]', '["genetics","human body","science for kids","dna","biology"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('год-вместе-1263', 'DP-1263', 'Год вместе', 'A Year Together', 'Godina zajedno', 'Клэр Лебур', 'Claire Lebourg', 'Kler Lebur', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Времена года сменяют друг друга, друзья, семьи и незнакомцы пересекаются, делятся мгновениями своей жизни. Мы несёмся из одного места в другое, уезжаем, встречаемся, разговариваем, работаем, едим и веселимся...все вместе! Книжка-картинка расскажет о жизни такой, какая она есть. Считается, что найти парочку, присутствующую на каждой странице, почти невозможно...почти.', 'Seasons shift, while friends, families, and strangers cross paths and share snippets of their lives. We rush from one place to another, travel, meet, chat, work, eat, and have fun... all together! This vibrant picture book portrays life just as it is. Word has it that spotting the special couple hidden on every single page is nearly impossible... well, almost.', 'Godišnja doba se smjenjuju, dok se prijatelji, porodice i neznanci susreću i dijele trenutke svojih života. Žurimo s jednog mjesta na drugo, putujemo, razgovaramo, radimo, jedemo i radujemo se... svi zajedno! Ova slikovnica prikazuje život onakvim kakav jeste. Kažu da je gotovo nemoguće pronaći par koji se pojavljuje na svakoj stranici... pa, skoro nemoguće.', 'Загляните в круговорот времён года и попробуйте отыскать на каждой странице влюблённую парочку — это настоящий гимн нашей суетливой, но такой тёплой жизни!', 'Dive into the whirlwind of passing seasons and spot the recurring couple on every page—a cozy, playful celebration of everyday life together!', 'Zavirite u krug godišnjih doba i pokušajte pronaći skriveni par na svakoj stranici — divna oda našoj užurbanoj, ali toploj svakodnevici!', '/covers/DP-1263.webp', '#e28743', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real","friends"]', '["wimmelbuch","seasons","daily life","community","observation"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('тайна-черной-скалы-1264', 'DP-1264', 'Тайна черной скалы', 'The Secret of Black Rock', 'Tajna Crne stijene', 'Джо Тодд-Стентон', 'Joe Todd-Stanton', 'Džo Tod-Stenton', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Эрин очарована океаном и легендой о Чёрной скале. О такой огромной, темной, загадочной и очень опасной. Говорят, она уничтожает все лодки, которые осмелятся приблизиться к ней. Так ли это на самом деле и сможет ли Эрин раскрыть тайну Чёрной скалы?', 'Erin is captivated by the ocean and the legend of the Black Rock—colossal, dark, mysterious, and dangerous, whispered to destroy every vessel that dares near it. But is the terrifying sea monster truly a monster, or something far more wondrous waiting to be understood?', 'Erin je očarana okeanom i legendom o zloglasnoj Crnoj stijeni — ogromnoj, mračnoj i opasnoj prijetnji koja navodno uništava svaki brod koji joj priđe. Da li je stijena zaista nemilosrdno čudovište ili magično biće koje čeka da otkrije svoju tajnu?', 'Завораживающая морская сказка с невероятными иллюстрациями о том, что за пугающей тайной часто скрывается живое чудо, нуждающееся в защите.', 'A breathtaking oceanic tale with mesmerizing art, proving that what looks terrifying at first might just be a gentle giant in need of a friend.', 'Čarobna morska priča sa predivnim ilustracijama koja nas uči da se iza najvećih strahova često kriju najnježnija čuda prirode.', '/covers/DP-1264.webp', '#1b4d68', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","magic","animals"]', '["ocean","sea creatures","bravery","nature","illustrated"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дикая-1265', 'DP-1265', 'Дикая', 'Wild', 'Divlja', 'Эмили Хьюз', 'Emily Hughes', 'Emili Hjuz', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'В своей блестящей дебютной книжке-картинке гавайский автор и иллюстратор Эмили Хьюз рассказывает о девочке, которая живёт в дикой природе. Медведи научили её есть, вороны — говорить, а лисы — играть. Она безусловно, откровенно, счастливо и неудержимо дикая. Но всё изменилось после встречи с незнакомцами, очень похожими на неё… Эта изобретательная, причудливая история с выразительными, новаторскими иллюстрациями увлечет новое поколение читателей, как ничто другое.', 'In this dazzling debut picture book, Hawaiian author and illustrator Emily Hughes tells the story of a girl living in the wilderness, taught to eat by bears, speak by birds, and play by foxes. She is irrevocably, happily wild—until one day she encounters strange creatures who look just like her. A lush, evocative tale about true nature and finding where you belong.', 'U svojoj briljantnoj slikovnici prvijencu, havajska autorka i ilustratorka Emili Hjuz priča o djevojčici koja odrasta u divljini. Medvjedi su je naučili da jede, ptice da govori, a lisice da se igra. Ona je bezuslovno i srećno divlja — sve dok ne sretne neobična stvorenja koja nevjerovatno liče na nju...', 'Прекрасное напоминание о том, как важно беречь внутреннюю свободу и не позволять никому приручить твою дикую душу!', 'A lush, heartwarming ode to wild freedom, nature, and staying delightfully, unapologetically true to yourself.', 'Prelijepa i dirljiva oda slobodi prirode i hrabrosti da ostanemo vjerni svom divljem, nesputanom srcu.', '/covers/DP-1265.webp', '#2e6038', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["animals","adventure","friends"]', '["nature","freedom","forest","animals","picture book"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('никудышный-гном-1266', 'DP-1266', 'Никудышный гном', 'The Good-for-Nothing Gnome', 'Beskorisni patuljak', 'Брюно Ноб', 'Bruno Nob', 'Bruno Nob', '', 'Гудвин', NULL, NULL, 6, 16, 'middle', 'Все гномы Деда Мороза трудолюбивые и послушные. Но даже среди таких молодцов всегда есть тот, кто будет выбиваться из толпы. Знакомьтесь — Никудышный гном, утомленный работой. Что же делать с таким негодяем?', 'All of Santa''s gnomes are hardworking and obedient. But even among such dutiful helpers, there is always one who breaks the mold. Meet the Good-for-Nothing Gnome, thoroughly exhausted by work. What in the world should be done with such a rascal?', 'Svi patuljci Deda Mraza su vrijedni i poslušni. Ali čak i među takvim radnicima uvijek postoji neko ko se izdvaja iz gomile. Upoznajte Beskorisnog patuljka, umornog od posla. Šta uopšte raditi s takvim vragolanom?', 'Очаровательно ленивая сказка для всех, кто хоть раз в жизни отчаянно уставал от работы и суеты!', 'A charmingly lazy festive tale for anyone who has ever felt completely exhausted by endless chores!', 'Šarmantno lijena praznična priča za svakoga ko se bar jednom umorio od posla i obaveza!', '/covers/DP-1266.webp', '#b23a34', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","magic"]', '["christmas","gnomes","humor","winter","laziness"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('изюмка-и-гном-1267', 'DP-1267', 'Изюмка и гном', 'Raisin and the Gnome', 'Izjumka i patuljak', 'Агнеш Балинт', 'Agnes Balint', 'Agneš Balint', '', 'Махаон', NULL, NULL, 6, 16, 'middle', 'Поучительные и добрые сказки о дружбе мудрого Гном Гномыча и маленького капризного поросёнка Изюмки. Вместе они живут в тыквенном домике, справляются с шалостями и учатся заботе и взаимовыручке.', 'Heartwarming and gentle tales about the friendship between wise Old Gnome and a whimsical little piglet named Raisin. Together in their cozy pumpkin house, they weather everyday mischief and learn the value of patience, care, and mutual help.', 'Poučne i tople priče o prijateljstvu mudrog patuljka i nestašnog, pomalo hirovitog prasenceta Izjumke. Živeći zajedno u kućici od bundeve, oni savladavaju sitne nestašluke i uče šta znače briga, strpljenje i međusobna podrška.', 'Идеальная сказка о том, как вырастить из капризного поросёнка самого преданного друга — особенно когда вы делите уютный тыквенный домик!', 'The coziest guide to turning a fussy little piglet into a loyal friend, especially when sharing a snug pumpkin house!', 'Najtoplija priča o tome kako se uz malo strpljenja tvrdoglavo prasence pretvara u najboljeg prijatelja — i to u pravoj kućici od bundeve!', '/covers/DP-1267.webp', '#e07a34', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["friends","animals","magic"]', '["friendship","piglet","gnome","bedtime stories","kindness"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хороший-динозавр-дорога-домой-1268', 'DP-1268', 'Хороший динозавр дорога домой', 'The Good Dinosaur: The Road Home', 'Dobri dinosaurus: Put kući', '', 'Disney', 'Dizni', '', 'Эксмо', NULL, NULL, 6, 16, 'middle', 'Яркая история по мотивам мультфильма Disney и Pixar о дружбе маленького динозавра Арло и храброго мальчика. Герои преодолевают опасности дикой природы и находят верный путь к родному дому.', 'A vibrant story based on the Disney and Pixar animated film about the heartwarming friendship between a timid young dinosaur named Arlo and a brave human boy. Together, they brave the perils of the untamed wilderness to find their way back home.', 'Živopisna priča zasnovana na crtanom filmu studija Disney i Pixar o prijateljstvu plašljivog dinosaurusa Arla i hrabrog dječaka. Zajedno savladavaju opasnosti divljine i traže put nazad do svog doma.', 'Трогательное путешествие о том, как даже самый пугливый динозавр может найти в себе смелость, если рядом верный друг!', 'A heartwarming wilderness quest proving that even the most timid dinosaur can find courage with a loyal friend by his side!', 'Dirljiva avantura koja dokazuje da i najplašljiviji dinosaurus može pronaći hrabrost kada uz sebe ima pravog prijatelja!', '/covers/DP-1268.webp', '#649b43', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","friends","animals"]', '["dinosaurs","friendship","journey","disney","courage"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-про-эмоции-почему-я-злю-1269', 'DP-1269', 'Сказки про эмоции. Почему я злюсь?', 'Tales About Emotions: Why Am I Angry?', 'Priče o osjećanjima: Zašto se ljutim?', 'Елена Ульева', 'Elena Ulyeva', 'Jelena Ulijeva', '', 'Clever', NULL, NULL, 6, 16, 'middle', 'Терапевтические сказки для малышей, помогающие распознавать чувство злости и справляться с раздражением. В книге есть полезные вопросы для обсуждения эмоций вместе с родителями.', 'Therapeutic tales for children that help them recognize anger and learn how to manage frustration calmly. The book includes thoughtful discussion prompts and questions for parents and kids to explore feelings together.', 'Terapijske priče za djecu koje pomažu u prepoznavanju bijesa i savladavanju ljutnje. Knjiga sadrži korisna pitanja i teme za zajednički razgovor roditelja i djece o osjećanjima.', 'Идеальная скорая помощь для маленьких вулканчиков и родителей, которые хотят превратить вспышки злости в тёплые объятия.', 'The perfect first-aid guide for little volcanoes and parents eager to transform fiery anger into warm hugs.', 'Savršena prva pomoć za male vulkane i roditelje koji žele da burne izlive bijesa pretvore u tople zagrljaje.', '/covers/DP-1269.webp', '#e2574c', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["real","friends"]', '["emotions","anger","emotional intelligence","psychology","self-regulation"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сказки-про-эмоции-почему-я-оби-1270', 'DP-1270', 'Сказки про эмоции. Почему я обиделся?', 'Tales About Emotions: Why Am I Hurt?', 'Bajke o osjećanjima: Zašto sam se uvrijedio?', 'Елена Ульева', 'Elena Ulyeva', 'Elena Ulijeva', '', 'Clever', NULL, NULL, 6, 16, 'middle', 'Короткие поучительные истории о том, почему возникает обида и как экологично ее выражать. Помогает ребенку развивать эмоциональный интеллект и учиться мириться с друзьями.', 'Short educational stories exploring why feelings of resentment arise and how to express them healthily. Helps children develop emotional intelligence and learn how to make up with friends.', 'Kratke poučne priče o tome zašto se javlja osjećaj uvrijeđenosti i kako ga izraziti na zdrav način. Pomaže djeci da razviju emocionalnu inteligenciju i nauče kako da se pomire s drugarima.', 'Уютная и полезная книга-помощница, которая подскажет, куда деть надутые щёчки и как снова весело играть вместе.', 'A gentle and helpful guide showing kids how to let go of hurt feelings and turn pouting back into playtime.', 'Nježan i koristan vodič koji uči djecu kako da otpuste uvrijeđenost i ponovo pronađu zajednički jezik s drugarima.', '/covers/DP-1270.webp', '#5b8eb9', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["friends","real"]', '["emotions","feelings","friendship","emotional intelligence","psychology"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('викинг-таппи-большая-книга-при-1271', 'DP-1271', 'Викинг Таппи Большая книга приключений', 'Viking Tappi: The Great Book of Adventures', 'Viking Tapi: Velika knjiga avantura', 'Марцин Мотка', 'Marcin Mortka', 'Marćin Mortka', 'Марта Курчевская', 'Вилли Винки', NULL, NULL, 6, 16, 'middle', 'Веселые сказочные истории о добродушном великане-викинге Таппи и его друзьях из волшебного Шепчущего Леса. Книга учит доброте, дружбе и находчивости.', 'Delightful fairy-tale stories about the gentle giant Viking Tappi and his woodland companions in the magical Whispering Forest. A heartwarming read celebrating kindness, friendship, and clever problem-solving.', 'Vesele bajkovite priče o dobroćudnom divu vikingu Tapiju i njegovim šumskim prijateljima iz čarobne Šaputave šume. Knjiga koja slavi dobrotu, pravo prijateljstvo i domišljatost.', 'Познакомьтесь с самым добрым викингом на свете, который предпочитает угощать лесных зверят блинчиками, а не размахивать мечом!', 'Meet the kindest Viking in the world, who much prefers baking sweet treats for woodland animals to swinging a sword!', 'Upoznajte najdobrodušnijeg vikinga na svijetu, koji više voli da časti šumske životinjice palačinkama nego da maše mačem!', '/covers/DP-1271.webp', '#3d7a5a', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","friends","magic"]', '["vikings","friendship","whispering forest","fairy tales","kindness"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('зимние-приключения-щенячий-пат-1272', 'DP-1272', 'Зимние приключения Щенячий патруль', 'Winter Adventures: PAW Patrol', 'Zimske avanture: Patrolne šape', '', 'Unknown', 'Nepoznat autor', '', 'Лев', NULL, NULL, 6, 16, 'middle', 'Увлекательные зимние истории о команде отважных щенков и мальчике Райдере. Друзья выручают попавших в снежную ловушку и разгадывают тайну снежного чудища.', 'Exciting winter tales about the brave team of rescue pups and their leader, Ryder. Join the friends as they rescue those trapped in deep snowdrifts and unravel the mystery of the snow monster.', 'Uzbudljive zimske priče o timu hrabrih štenaca i dječaku Rajderu. Prijatelji spasavaju one zarobljene u snježnim smetovima i rješavaju misteriju snježnog čudovišta.', 'Заводите снегоходы: отважные щенки спешат на помощь даже в самый трескучий мороз!', 'Fire up the snowmobiles: the brave pups are ready to roll to the rescue, even in the freezing cold!', 'Upalite motorne sanke: hrabri štenci jure u pomoć čak i po najvećoj mećavi!', '/covers/DP-1272.webp', '#3a86c8', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["adventure","animals","friends"]', '["paw patrol","winter","dogs","rescue","friendship"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('ледяное-королевство-1273', 'DP-1273', 'Ледяное королевство', 'The Frozen Kingdom', 'Zaleđeno kraljevstvo', 'мультяшные истории', 'Cartoon Stories', 'Crtane priče', '', 'Умка', NULL, NULL, 6, 16, 'middle', 'Волшебная сказочная история по мотивам любимого мультфильма о верности, храбрости и сестринской любви, способной растопить даже вечные льды.', 'A magical fairy-tale story based on the beloved animated movie about loyalty, courage, and sisterly love capable of melting even eternal ice.', 'Magična bajkovita priča zasnovana na omiljenom crtanom filmu o odanosti, hrabrosti i sestrinskoj ljubavi koja može otopiti i vječni led.', 'Идеальное чтение для тех, кто точно знает: самое верное средство от ледяных бурь — это искренняя любовь и тепло сестринских сердец!', 'The perfect read for anyone who knows that a warm heart and sisterly love can melt even the coldest winter storm!', 'Savršeno štivo za sve koji znaju da toplo srce i sestrinska ljubav mogu otopiti i najhladniju sniježnu oluju!', '/covers/DP-1273.webp', '#5dade2', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["magic","adventure","friends"]', '["magic","winter","sisterhood","fairy tale","adventure"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('давай-делиться-дракоша-1274', 'DP-1274', 'Давай делиться, дракоша', 'Let''s Share, Dragon', 'Hajde da dijelimo, zmajiću', 'Бьянка Шульц', 'Bianca Schulze', 'Bjanka Šulc', 'Самара Харди', 'Clever', NULL, NULL, 6, 16, 'middle', 'Забавная интерактивная сказка о маленькой Дракоше, которая очень не любит делиться своими вещами. Книга в игровой форме учит договариваться и дружить.', 'A funny, interactive tale about a little Dragon who really dislikes sharing her treasures. In a playful and engaging way, this book teaches young readers how to negotiate, take turns, and embrace true friendship.', 'Zabavna i interaktivna priča o maloj Zmajici koja uopšte ne voli da dijeli svoje stvari. Kroz igru, knjiga uči djecu kako da se dogovaraju i njeguju pravo prijateljstvo.', 'Поможет даже самым упрямым маленьким собственникам делиться своими сокровищами весело и без слёз!', 'A delightful interactive treat that gently teaches even the fiercest little hoarders that sharing is caring!', 'Predivna interaktivna priča koja će i najtvrdoglavije male zmajiće naučiti da je dijeljenje pravo blago!', '/covers/DP-1274.webp', '#f26a36', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","friends","magic"]', '["dragons","sharing","friendship","emotions","interactive"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('скажи-правду-дракоша-1275', 'DP-1275', 'Скажи правду, дракоша', 'Just Be Honest, Dragon!', 'Reci istinu, zmajiću', 'Бьянка Шульц', 'Bianca Schulze', 'Bjanka Šulc', 'Самара Харди', 'Clever', NULL, NULL, 6, 16, 'middle', 'Остроумная история-игра о том, как непросто признаться в своей ошибке. Книга помогает ребенку понять, почему важно говорить правду и не бояться этого.', 'A witty, interactive story about how tough it can be to own up to our mistakes. This charming book gently guides children to understand why telling the truth matters and helps them overcome the fear of honesty.', 'Duhovita i topla interaktivna priča o tome koliko je ponekad teško priznati grešku. Ova knjiga pomaže djeci da shvate zašto je važno govoriti istinu i kako prevazići strah od iskrenosti.', 'Очаровательный дракончик поможет превратить страшное признание в смелый и добрый поступок!', 'An adorable little dragon turns the scary task of admitting a mistake into a brave and cheerful adventure!', 'Preslatki zmajić pomoći će vašem mališanu da shvati da je priznanje greške zapravo čin prave hrabrosti!', '/covers/DP-1275.webp', '#e76f51', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","magic","animals"]', '["dragons","honesty","interactive","emotions","growing up"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('динозавры-у-бабушки-в-саду-1276', 'DP-1276', 'Динозавры у бабушки в саду', 'Dinosaurs in Grandma''s Garden', 'Dinosaurusi u bakinoj bašti', 'Йорг Иле и Доминик Хохвальд', 'Jörg Ihle and Dominik Hochwald', 'Jerg Ile i Dominik Hohvald', 'Петра Фритц', 'Clever', NULL, NULL, 6, 16, 'middle', 'Веселая иллюстрированная история о каникулах у бабушки и неуемной детской фантазии, превращающей дачный сад в настоящий мир динозавров.', 'A delightful illustrated story about summer holidays at grandma''s house and boundless childhood imagination that turns an ordinary backyard into a thrilling prehistoric world of dinosaurs.', 'Vesela ilustrovana priča o raspustu kod bake i bujnoj dječjoj mašti koja običnu baštu pretvara u uzbudljivi praistorijski svijet dinosaurusa.', 'Приготовьтесь к раскопкам между грядками: у бабушки каникулы никогда не бывают скучными, особенно если под смородиной притаился диплодок!', 'Get ready to dig between the berry bushes: vacation at grandma''s is never boring, especially when a diplodocus is hiding in the garden!', 'Pripremite se za arheološka iskopavanja među lejama: raspust kod bake nikad nije dosadan, naročito kada se u žbunju krije diplodokus!', '/covers/DP-1276.webp', '#3e8e41', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["funny","adventure","animals"]', '["dinosaurs","summer","grandparents","imagination","garden"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('лотти-и-отто-история-для-мальч-1277', 'DP-1277', 'Лотти и Отто. История для мальчишек и девчонок', 'Lotti and Otto: A Story for Boys and Girls', 'Loti i Oto: Priča za dječake i djevojčice', 'Колльен Ульмен-Фернандес', 'Collien Ulmen-Fernandes', 'Collien Ulmen-Fernandes', 'Карола Зивердинг', 'Clever', NULL, NULL, 6, 16, 'middle', 'Добрая история о дружбе девочки Лотти и выдренка Отто. Книга учит ребят не бояться быть собой, следовать мечте и разрушать стереотипы.', 'A heartwarming story about the friendship between a girl named Lotti and a little otter named Otto. The book encourages children to be unapologetically themselves, follow their dreams, and break free from outdated stereotypes.', 'Topla priča o prijateljstvu djevojčice Loti i male vidre Ota. Knjiga uči djecu da se ne plaše da budu svoja, da prate svoje snove i ruše nametnute rodne stereotipe.', 'Кто сказал, что девчонки не строят машины, а выдры не носят блестки? Смело будь собой!', 'Who says girls can''t build go-karts and otters can''t rock glittery outfits? Be boldly you!', 'Ko kaže da djevojčice ne prave automobile, a vidre ne vole šljokice? Budi hrabro ono što jesi!', '/covers/DP-1277.webp', '#3598a6', 'nonfiction', 'ru', 'available', 'Категория: Совенята', '["friends","animals","real"]', '["stereotypes","friendship","otters","individuality","equality"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('снеговик-1278', 'DP-1278', 'Снеговик', 'The Snowman', 'Snješko Bijelić', 'Майкл Морпурго', 'Michael Morpurgo', 'Majkl Morpurgo', '', 'Поляндрия', NULL, NULL, 4, 12, 'middle', 'Однажды в конце декабря Джеймс проснулся и увидел, что выпал долгожданный снег. Он поспешил на улицу, чтобы слепить снеговика. Глаза-угольки, старая шляпа, зелёный шарф и мандариновый нос - снеговик получился замечательный! Джеймс так не хотел с ним расставаться, что вышел его навестить прямо посреди ночи. Невероятно, но снеговик ожил... Вот уже сорок лет "Снеговик" Рэймонда Бриггса остаётся одной из самых известных рождественских книг. Удивительная история, мастерски переосмысленная и рассказанная Майклом Морпурго, поможет новому поколению читателей проникнуться волшебством этой сказки. Для дошкольного и младшего школьного возраста.', 'One late December morning, James wakes up to discover a world blanketed in fresh snow. Rushing outside, he builds the finest snowman with coal eyes, an old hat, a green scarf, and a tangerine nose. Unable to say goodbye, James sneaks out at midnight—only to find his snowman has miraculously come to life. Michael Morpurgo reimagines Raymond Briggs''s timeless classic for a new generation of dreamers.', 'Jednog jutra krajem decembra, Džejms se budi i zatiče svijet prekriven snijegom. Požurio je napolje da napravi najljepšeg Snješka sa očima od uglja, starim šeširom, zelenim šalom i nosom od mandarine. Te noći, kada se iskrao da ga posjeti, dogodilo se pravo čudo — Snješko je oživio. Majkl Morpurgo na čaroban način oživljava bezvremeni božićni klasik Rejmonda Brigsa za nove generacije.', 'Трогательная зимняя сказка о дружбе, ночном полёте и чудесах, которые случаются, если вложить в снеговика всю свою душу!', 'A breathtaking winter tale of friendship, midnight flight, and the quiet magic that happens when you build a snowman with all your heart!', 'Dirljiva zimska priča o prijateljstvu, letenju kroz noć i čaroliji koja oživi kad u Snješka uložite cijelo svoje srce!', '/covers/DP-1278.webp', '#3b6989', 'winter_and_new_year', 'ru', 'available', '', '["magic","friends","adventure"]', '["winter","christmas","snowman","friendship","classic"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('рождественская-каша-1279', 'DP-1279', 'Рождественская каша', 'The Christmas Porridge', 'Božićna kaša', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', '', 'Белая ворона', NULL, NULL, 4, 12, 'middle', 'На дворе сочельник. Пушистый белый снежок лежит на елях и крышах домов. А гномы ждут, когда хозяева дома преподнесут им тарелочку вкусной рождественской каши! Но тут случается непредвиденное… Книга всемирно известного шведского художника и писателя Свена Нурдквиста рассказывает о Рождестве в семействе гномов, где царят свои традиции. Перед праздником хозяева дома должны поднести им тарелку каши, а не то случатся несчастья. Но в этом году люди забыли древние обычаи, и гномам надо спасать положение. Забавные приключения семейки крошечных человечков и их несравненной мыши.', 'It is Christmas Eve, and fluffy white snow blankets the roofs and spruces. The tomte family is eagerly waiting for the humans to honor tradition and leave them a steaming bowl of buttery Christmas porridge. But the forgetful owners have overlooked the custom, threatening the house with bad luck! The tiny gnomes and their devoted pet mouse must hatch a clever, secretive plan to save Christmas dinner and restore harmony.', 'Badnje je veče i mekani snijeg prekriva krovove i jelke. Porodica patuljaka nestrpljivo čeka da ukućani ispoštuju drevni običaj i ostave im činiju tople božićne kaše. Ali ljudi su zaboravili na tradiciju, što kući donosi nesreću! Mudri patuljci i njihov vjerni miš moraju hitno smisliti lukav plan kako bi spasili praznik i obezbijedili zasluženi zalogaj.', 'Остроумная и уютная праздничная сказка, напоминающая, почему ни в коем случае нельзя забывать кормить домашних гномов рождественской кашей с маслицем!', 'A warm and wonderfully whimsical holiday classic proving why you should never, ever forget the butter in your house gnomes'' porridge!', 'Topla i duhovita praznična bajka koja nas podsjeća zašto nikada ne smijemo zaboraviti da počastimo kućne patuljke kašom s maslacem!', '/covers/DP-1279.webp', '#943828', 'winter_and_new_year', 'ru', 'available', '', '["magic","funny","adventure"]', '["christmas","gnomes","winter","folklore","family"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('гном-и-лис-1280', 'DP-1280', 'Гном и лис', 'The Tomten and the Fox', 'Patuljak i lisac', 'Астрид Линдгрен', 'Astrid Lindgren', 'Astrid Lindgren', 'Эва Эриксон', 'Белая ворона', NULL, NULL, 4, 12, 'middle', 'Зимняя ночь. Лис Микель подкрадывается к хутору, а в доме у рождественской елки играют дети. В сарае спят вкусные курочки. Но Лису до них не добраться — вот уже сто лет за хутором присматривает гном. Он объясняет Микелю: кур трогать нельзя. Но что тогда есть лису? Не беда: дети уже выставили для гнома рождественскую кашу, которой тот не прочь поделиться. Оказывается, это не хуже, чем курицы. Сытый лис спешит домой, а в небе восходит утренняя звезда.', 'It is a quiet, snowy winter night. Mickel the hungry fox sneaks toward the farmyard dreaming of tasty chickens. But the farm has a guardian: the wise old Tomten, who has watched over everyone for hundreds of years. The Tomten cannot let the fox harm the hens, but he understands hunger—and happily shares his own bowl of Christmas porridge. A timeless, gentle winter tale about peace, compassion, and the magic of giving.', 'Hladna je zimska noć, a gladni lisac se prikrada seoskom imanju sanjajući ukusne kokoške. Ali imanje čuva mudri patuljak Tomten, koji već stotinu godina pazi na sve stanovnike. Patuljak ne da da iko dira kokoške, ali razumije glad—pa sa liscem dijeli svoju božićnu kašu koju su mu djeca ostavila. Nježna i topla zimska priča o dobroti i miru.', 'Тихая сказка о том, как тарелка рождественской каши может спасти курочек и подружиться с голодным лисом.', 'A hushed, heartwarming bedtime tale proving that a shared bowl of sweet porridge can turn a hungry predator into a friend.', 'Čarobna i tiha zimska priča o tome kako čin dobrote i činija božićne kaše mogu nahraniti gladnog lisca i sačuvati kokoške.', '/covers/DP-1280.webp', '#1f3b5c', 'winter_and_new_year', 'ru', 'available', '', '["magic","animals","friends"]', '["зима","рождество","лиса","гном","доброта"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('-лка-пряники-подарки-1281', 'DP-1281', 'Ёлка, пряники, подарки', 'Christmas Tree, Gingerbread, and Gifts', 'Jelka, medenjaci i pokloni', 'Ульф Нильсон', 'Ulf Nilsson', 'Ulf Nilson', '', 'МИФ', NULL, NULL, 4, 12, 'middle', 'Уютные зимние истории о чудесах — больших и маленьких, которые в преддверии Нового года помогут создать волшебную атмосферу. Ульф Нильсон — современный шведский сказочник — собрал в этой книге четыре истории о пряничных человечках, проказниках-гномах, елках и волшебстве, а проиллюстрировали их лучшие художники. Это невероятно тёплые, уютные и чудесные сказки. Читайте их по одной в каждую неделю декабря.', 'Cozy winter tales about wonders big and small that will fill your home with holiday magic. Celebrated Swedish author Ulf Nilsson gathers four enchanting stories about gingerbread folk, mischievous gnomes, Christmas trees, and quiet miracles, illustrated by wonderful artists. An incredibly warm and heartwarming book to read week by week all December long.', 'Udobne zimske priče o malim i velikim čudima koja unose prazničnu čaroliju u svaki dom. Poznati švedski pisac Ulf Nilson sakupio je četiri tople priče o medenjacima, nestašnim patuljcima, jelkama i magiji, a predivne ilustracije upotpunjuju ovu prazničnu radost. Savršena knjiga za čitanje po jedne priče svake nedjelje decembra.', 'Заварите какао, завернитесь в плед и открывайте по одной сказке в неделю — идеальный рецепт ожидания праздника!', 'Brew some hot cocoa, curl up in a blanket, and savor one story a week—the ultimate recipe for holiday anticipation!', 'Skuvajte topli kakao, umotajte se u ćebe i čitajte po jednu priču svake nedjelje — pravi recept za praznično iščekivanje!', '/covers/DP-1281.webp', '#b83d30', 'winter_and_new_year', 'ru', 'available', '', '["magic","friends"]', '["christmas","winter","holidays","gnomes","scandinavian"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('две-зимы-1282', 'DP-1282', 'Две зимы', 'The Two Winters', 'Dvije zime', 'Йолан Бертран, Жион Тристан', 'Yolan Bertrand, Tristan Gion', 'Yolan Bertrand, Tristan Gion', '', 'МИФ', NULL, NULL, 4, 12, 'middle', 'Сказка-фэнтези о троллях, загадочной лисе, деревне викингов и смелом Альфреде, который бросит вызов самой Зиме! Приключения, волшебство, шутки, спасение и превращения. Жили в стародавние времена две сестры: старшая Зима — с лютыми холодами и метелями — и младшая Зимушка — с веселым катанием с гор и шумными ярмарками. Но после пропажи Зимушки в маленькой деревне викингов все пошло вверх дном. Злится старшая сестра, насылает морозы, а тролли крадут дрова и утварь. И только десятилетний сирота Альфред знает: надо найти Зимушку и тогда кончатся беды. Он отправляется в темный ледяной лес, где встретится с настоящим волшебством... Зимняя сказка с колоритом скандинавского фольклора. О смелости и чувстве юмора, которое помогает даже в самое холодное время года.', 'A Nordic fantasy fairy tale about trolls, a mysterious fox, a Viking village, and brave young Alfred who dares to challenge Winter herself! In ancient times lived two sisters: harsh, freezing Elder Winter and playful Little Winter, full of sledding and festive fairs. But when Little Winter mysteriously vanishes, bitter blizzards descend and mischievous trolls begin pilfering firewood. Ten-year-old orphan Alfred ventures into the frozen, enchanted forest to restore joy and balance to the North.', 'Nordijska bajkovita fantazija o trolovima, tajanstvenoj lisici, selu vikinga i hrabrom dječaku Alfredu koji se suprotstavlja samoj Zimi! Nekada su postojale dvije sestre: surova Velika Zima i vesela Mala Zima puna sanjkanja i vašara. Kada Mala Zima tajanstveno nestane, selo pogađaju ledeni mrazevi, a nestašni trolovi počinju da kradu drva. Desetogodišnji siročić Alfred kreće u zaleđenu šumu punu čarolije kako bi vratio radost i spasio svoje selo.', 'Закутайтесь в тёплый плед и отправляйтесь вместе с Альфредом на поиски пропавшего веселья в заснеженный скандинавский лес, где даже ворчливые тролли не помешают празднику!', 'Wrap yourself in a cozy blanket and join young Alfred on an epic Nordic trek where cheeky trolls, frosty magic, and pure bravery save the season!', 'Umotajte se u toplo ćebe i pođite sa Alfredom u sniježnu nordijsku avanturu đe ni vragolasti trolovi ne mogu ugasiti pravu zimsku radost!', '/covers/DP-1282.webp', '#325d79', 'winter_and_new_year', 'ru', 'available', '', '["adventure","magic","funny"]', '["winter","vikings","trolls","scandinavian folklore","fairy tale"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('йети-камера-мотор--1283', 'DP-1283', 'Йети, камера, мотор!', 'Yeti, Camera, Action!', 'Jeti, kamera, akcija!', 'Валентина Дёгтева, Алиса Юфа', 'Valentina Degteva, Alisa Yufa', 'Valentina Djohtjeva, Alisa Jufa', '', 'МИФ', NULL, NULL, 4, 12, 'middle', 'Под Новый год всем хочется сказки. Волшебной, неожиданной, увлекательной, с любимыми героями и красивыми иллюстрациями. Новая книга об очаровательном Йети именно такая — смешная, способная удивить и растрогать, а еще приправленная трюками и спецэффектами. Йети предстоит стать настоящей кинозвездой. Режиссёр картины — блистательный Петардо Конфетти, а в центре событий — похищение красавицы Снегурочки. Камера, мотор, начали: «свирепое чудище» вот-вот сцапает бедняжку... Но как быть, если под мохнатой шкурой снежного человека скрывается чуткое сердце? Йети больше всего на свете любит строить ледяные крепости для малышей, а ещё, конечно, поесть и поспать. Такой артист вот-вот провалит весь фильм. Что же будет? Занимайте места в зрительном зале, пока их не заняли пингвины.', 'Everyone longs for a fairy tale around New Year''s, and this delightful story starring a sweet Yeti has it all — humor, warmth, movie stunts, and whimsical magic. The Yeti is cast as a terrifying monster tasked with kidnapping the Snow Maiden under the direction of the flamboyant Petardo Confetti. But what if beneath the shaggy fur beats the gentlest heart, one that prefers building snow forts for toddlers, snacking, and napping over villainy? Take your seats in the cinema before the penguins take the best spots!', 'Pred Novu godinu svi želimo bajku, a ova priča o neodoljivom Jetiju donosi smijeh, nježnost i filmske avanture. Jeti iznenada postaje filmska zvijezda: u filmu režisera Petarda Konfetija treba da odglumi strašno čudovište koje otima Snjeguročku. Ali kako glumiti zlikovca kad ispod čupavog krzna kuca toplo srce koje najviše voli da gradi ledene tvrđave za djecu, jede i drijema? Zauzmite svoja mjesta u bioskopu prije nego što ih zauzmu pingvini!', 'Загляните за кулисы снежного блокбастера и узнайте, почему из добродушных лохматых великанов получаются самые трогательные кинозвёзды!', 'Peek behind the scenes of a snowy blockbuster and discover why gentle, fluffy giants make the most touching movie stars!', 'Zavirite iza kulisa sniježnog blokbastera i otkrijte zašto dobroćudni krzneni divovi postaju najdirljivije filmske zvijezde!', '/covers/DP-1283.webp', '#3a7f9e', 'winter_and_new_year', 'ru', 'available', '', '["funny","adventure","magic"]', '["yeti","cinema","new year","winter","humor"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('элвис-и-человек-в-красном-паль-1284', 'DP-1284', 'Элвис и человек в красном пальто', 'Elvis and the Man in the Red Coat', 'Elvis i čovjek u crvenom kaputu', 'Оле Кёнеке', 'Ole Könnecke', 'Ole Kenecke', 'Оле Кёнеке', 'В канун Нового года в доме автомеханика Элвиса неожиданно погас свет, и вскоре раздался стук в дверь. На пороге стоял печальный человек в красном пальто, который умолял о помощи: дело в том, что его сани, запряжённые оленями, налетели на столб с электрическими проводами и сломались, поэтому теперь он не успевал попасть на работу. Элвис никак не мог взять в толк, зачем этому странному человеку, разъезжающему на оленьей упряжке, вместо автомобиля, вдруг срочно понадобилось на работу под вечер 31 декабря, когда все сидят по домам и отдыхают. Вместе со своими друзьями Элвис помогает человеку в красном пальто, и тот в конце концов благополучно уезжает на свою загадочную ночную работу. Правда, никто так и не понял, кем же он был. Трогательная и остроумная новогодняя сказка для детей, а также для взрослых, которые тоже когда-то были детьми, но забыли об этом. Оле Кёнекке - известный немецкий иллюстратор и автор. Его альбомы и комиксы публикуются во всем мире и удостаиваются серьезных наград.', NULL, NULL, 4, 12, 'middle', 'В канун Нового года в доме автомеханика Элвиса неожиданно погас свет, и вскоре раздался стук в дверь. На пороге стоял печальный человек в красном пальто, который умолял о помощи: дело в том, что его сани, запряжённые оленями, налетели на столб с электрическими проводами и сломались, поэтому теперь он не успевал попасть на работу. Элвис никак не мог взять в толк, зачем этому странному человеку, разъезжающему на оленьей упряжке, вместо автомобиля, вдруг срочно понадобилось на работу под вечер 31 декабря, когда все сидят по домам и отдыхают. Вместе со своими друзьями Элвис помогает человеку в красном пальто, и тот в конце концов благополучно уезжает на свою загадочную ночную работу. Правда, никто так и не понял, кем же он был. Трогательная и остроумная новогодняя сказка для детей, а также для взрослых, которые тоже когда-то были детьми, но забыли об этом. Оле Кёнекке - известный немецкий иллюстратор и автор. Его альбомы и комиксы публикуются во всем мире и удостаиваются серьезных наград.', 'On New Year’s Eve, the power suddenly cuts out in the workshop of car mechanic Elvis, followed by an urgent knock at the door. Outside stands an unhappy man in a red coat: his reindeer-drawn sleigh crashed into a utility pole, and now he''s running late for work. Elvis can''t fathom why anyone would rush to work on December 31st, let alone in a flying sleigh, but together with his pals, he gets the vehicle back in running order. A witty, warm holiday tale by celebrated German illustrator Ole Könnecke for kids and grownups who need a pinch of festive wonder.', 'U novogodišnjoj noći u kući automehaničara Elvisa iznenada nestaje struje, a ubrzo se začuje kucanje na vratima. Na pragu stoji tužan čovjek u crvenom kaputu koji moli za pomoć: njegove sanke sa irvasima udarile su u električni stub i pokvarile se, pa sada kasni na posao. Elvisu nikako nije jasno zašto bi neko sa zapregom irvasa morao hitno na posao 31. decembra uveče, ali sa svojim prijateljima pomaže tajanstvenom gostu da popravi sanke. Dirljiva i duhovita zimska priča o neočekivanoj pomoći i prazničnoj magiji.', 'Даже волшебным саням Деда Мороза иногда нужен толковый автомеханик — остроумная и добрая новогодняя история!', 'Even Santa needs a skilled mechanic sometimes—a wonderfully dry, heartwarming holiday story about lending a hand.', 'Čak i Deda Mrazu ponekad treba dobar automehaničar — duhovita i topla praznična priča o uzajamnoj pomoći!', '/covers/DP-1284.webp', '#b82626', 'winter_and_new_year', 'ru', 'available', '', '["funny","magic","friends"]', '["new year","christmas","santa claus","winter","friendship"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('снег-1285', 'DP-1285', 'Снег', 'Snow', 'Snijeg', '', 'Walter de la Mare', 'Volter de la Mer', '', 'Классическое рождественское стихотворение Уолтера Дэ Ла Мэра впервые было опубликовано в 1924 году. А на этот раз оно очень гармонично сочетается со стильными, современными иллюстрациями Каролины Рабей. В книге прекрасно передана уютная атмосфера холодного, зимнего дня, добрые отношения между членами семьи и уютное ощущение предвкушения праздника. К тому же иллюстрированные стихи являются отличным способом, чтобы познакомить маленьких читателей с настоящей поэзией. Для детей младшего школьного возраста.', NULL, NULL, 4, 12, 'middle', 'Классическое рождественское стихотворение Уолтера Дэ Ла Мэра впервые было опубликовано в 1924 году. А на этот раз оно очень гармонично сочетается со стильными, современными иллюстрациями Каролины Рабей. В книге прекрасно передана уютная атмосфера холодного, зимнего дня, добрые отношения между членами семьи и уютное ощущение предвкушения праздника. К тому же иллюстрированные стихи являются отличным способом, чтобы познакомить маленьких читателей с настоящей поэзией. Для детей младшего школьного возраста.', 'Walter de la Mare''s classic Christmas poem, first published in 1924, is paired with Carolina Rabei''s stylish and tender illustrations. Capturing the cozy warmth of a frosty winter day, family togetherness, and the joyful anticipation of the holidays, this picture book is a wonderful introduction to poetry for young readers.', 'Klasična božićna pjesma Voltera de la Mera, prvi put objavljena 1924. godine, oživljava uz tople i prelijepe ilustracije Karoline Rabej. Knjiga dočarava ušuškanu atmosferu hladnog zimskog dana, porodičnu bliskost i radosno iščekivanje praznika, čineći je savršenim uvodom u pravu poeziju za najmlađe čitaoce.', 'Заварите какао, укутайтесь в плед и впустите в дом пушистую тишину настоящей зимней сказки!', 'Wrap yourself in a warm blanket with a cup of cocoa and listen to the soft, quiet magic of falling snow.', 'Ušuškajte se u toplo ćebe uz šolju kakaa i osjetite tihu, nježnu čaroliju sniježnog dana.', '/covers/DP-1285.webp', '#6b8ea8', 'winter_and_new_year', 'ru', 'available', '', '["magic","real"]', '["зима","стихи","снег","семья","рождество"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чик-и-брики-снеговик-1286', 'DP-1286', 'Чик и Брики. Снеговик', 'Pip and Posy: The Snowy Day', 'Pip i Pozi: Snješko', '', 'Axel Scheffler', 'Aksel Šefler', '', '', NULL, NULL, 4, 12, 'middle', '', 'When Pip and Posy head outside on a snowy day, they have a grand time sledging until it is time to build a snowman. Posy wants a snow mouse, but Pip wants a snow rabbit! After an epic snowy tiff, the two friends realize that warm hugs and sharing indoor crafts are the best part of winter.', 'Pip i Pozi jedva čekaju igru na snijegu, ali nastaje prava zbrka kada dođe red na pravljenje snješka. Posy želi sniježnog miša, a Pip sniježnog zeca! Poslije kratke zimske svađe, dvoje nerazdvojnih drugara shvataju da su tople palačinke i zagrljaj važniji od bilo koje ledene skulpture.', 'Даже самый громкий снежный спор легко растает перед теплом настоящей дружбы и уютом домашнего пластилина!', 'Even the fiercest snowy dispute melts away in no time with warm cuddles, true friendship, and a cup of cheer!', 'Čak i najveća sniježna prepirka brzo se otopi uz tople zagrljaje, iskreno prijateljstvo i igru u toploj sobi!', NULL, '#5c9ac7', 'winter_and_new_year', 'ru', 'available', '', '["friends","animals","funny"]', '["winter","snow","friendship","snowman","feelings"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('чик-и-брики-наряжают-лку-1287', 'DP-1287', 'Чик и Брики наряжают ёлку', 'Pip and Posy: The Christmas Tree', 'Pip i Pozi kite jelku', '', 'Axel Scheffler', 'Axel Scheffler', '', 'Clever (Клевер-Медиа-Групп)', 2018, '978-5-00115-527-0', 4, 12, 'middle', '', 'Pip and Posy are having wonderful festive fun decorating the Christmas tree with candy canes and delicious biscuits. But soon, the decorations mysteriously begin to disappear, and Pip starts to feel very unwell! A sweet, relatable holiday story about honesty, empathy, and cozy winter celebrations.', 'Pip i Pozi uživaju u kićenju novogodišnje jelke slatkim lizalicama i ukusnim medenjacima. Međutim, ukrasi misteriozno nestaju, a Pipa počinje da boli stomak! Topla praznična priča o iskrenosti, saosjećanju i pravom prijateljstvu.', 'Идеальная новогодняя история о том, почему не стоит вешать на ёлку слишком много пряников, если твой лучший друг обожает сладкое!', 'A hilarious holiday reminder of why hanging edible treats on the tree might tempt even your very best friend!', 'Zabavna praznična lekcija o tome zašto ukusni ukrasi na jelki ponekad prebrzo nestanu!', '/covers/DP-1287.webp', '#c0362c', 'winter_and_new_year', 'ru', 'available', '', '["funny","friends","animals"]', '["christmas","winter","friendship","toddlers","holidays"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('андрей-сахаров-человек-который-1288', 'DP-1288', 'Андрей Сахаров человек, который не боялся', 'Andrei Sakharov: The Man Who Was Not Afraid', 'Andrej Saharov: Čovjek koji se nije bojao', 'Ксения Новохатько', 'Ksenia Novokhatko', 'Ksenija Novahatko', '', 'самокат', NULL, NULL, 4, 12, 'middle', 'Кто наш герой сегодня? В чём его суперсила? В детстве Андрей был застенчивым - не мог заговорить даже с соседом по парте. Но спустя много лет именно его тихий голос зазвучал громче, чем взрывы самых разрушительных бомб, мнения самых важных политиков. Андрею Сахарову, как и всем нам, приходилось выбирать: думать самому или верить на слово, сказать или промолчать, вмешаться или остаться в стороне. Его жизнь была похожа на научный эксперимент, который часто приводил к неожиданным результатам. Совершая ошибки, сталкиваясь с неудачами и предательством, Сахаров всегда выбирал действие: ставил под сомнение то, что считалось неоспоримым, говорил на равных с главами государств, бросал вызов бесправию, несправедливости и авторитетам. Гениальный физик, "отец" советской водородной бомбы и правозащитник, лауреат Нобелевской премии мира, Сахаров был человеком, который не боялся - думать, высказываться, защищать.', 'Who is our hero today, and what is his superpower? As a boy, Andrei was painfully shy and struggled to talk even to his desk mate. Yet years later, his quiet voice resounded louder than the most destructive bomb blasts and the speeches of powerful politicians. Andrei Sakharov was a brilliant physicist, the father of the Soviet hydrogen bomb, and later a fearless human rights champion and Nobel Peace Prize laureate. This illustrated biography shows how a quiet boy became someone who was never afraid to think critically, speak truth to power, and stand up for justice.', 'Ko je naš heroj danas i u čemu leži njegova snaga? Kao dječak, Andrej je bio nevjerovatno stidljiv, ali je godinama kasnije upravo njegov tihi glas odjeknuo snažnije od najrazornijih bombi i govora moćnih političara. Andrej Saharov bio je genijalni fizičar, tvorac sovjetske hidrogenske bombe, a zatim nepokolebljivi borac za ljudska prava i dobitnik Nobelove nagrade za mir. Ova inspirativna ilustrovana biografija priča o čovjeku koji se nikada nije bojao da misli svojom glavom, govori istinu i brani slobodu.', 'Вдохновляющая история о том, как застенчивый мальчик вырос в бесстрашного ученого, чей тихий голос оказался громче любых атомных взрывов.', 'An inspiring tale of how a shy, quiet boy grew up to become a fearless scientist whose calm voice rang louder than any atomic blast.', 'Inspirativna priča o tome kako je jedan stidljivi dječak izrastao u neustrašivog naučnika čiji je tihi glas nadjačao i najglasnije atomske eksplozije.', '/covers/DP-1288.webp', '#e0a628', 'important_topics', 'ru', 'available', '', '["real"]', '["biography","science","human rights","courage","history"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('вы-жившие-большой-террор-1289', 'DP-1289', 'Вы-жившие. Большой террор', 'The Survivors: The Great Terror', 'Preživjeli: Veliki teror', '', 'Gulag History Museum', 'Muzej istorije Gulaga', '', 'самокат', NULL, NULL, 4, 12, 'middle', 'Более чем за двадцать лет существования ГУЛАГа через тюрьмы и лагеря прошли около 20 миллионов человек. Каждый десятый остался в ГУЛАГе навечно. Со временем слово "ГУЛАГ", первоначально обозначавшее "Главное управление лагерей", стало зловещим символом беззакония, жизни на грани смерти, каторжного труда и человеческого бесправия. Книга "Вы-жившие. Большой террор" - продолжение новой постоянной экспозиции Музея истории ГУЛАГа. Внутри - шесть графических историй, рассказывающих о судьбах людей, пострадавших от сталинских репрессий. Они занимали разное социальное положение, имели разные профессии, придерживались разных политических взглядов, жили в разных уголках страны. Но оказались в одинаково бесправном положении. Каждого из них несправедливо осудили, отправили в лагеря или расстреляли.', 'Over the more than twenty years of the GULAG system, nearly 20 million people passed through its prisons and camps, with every tenth prisoner remaining there forever. Created in collaboration with the Gulag History Museum, this volume presents six graphic novellas illustrating the real fates of ordinary people affected by Stalinist repressions. Spanning different professions, backgrounds, and beliefs, each endured injustice, forced labor, or execution, leaving an indelible testimony of resilience and human spirit.', 'Tokom više od dvadeset godina postojanja GULAG-a, kroz zatvore i logore prošlo je oko 20 miliona ljudi, a svaki deseti je tamo ostao zauvijek. Nastala kao nastavak postavke Muzeja istorije Gulaga, ova knjiga donosi šest grafičkih priča o sudbinama ljudi pogođenih staljinističkim represijama. Iako različitih profesija, društvenih statusa i uvjerenja, svi su se našli u jednako obespravljenom položaju, ostavljajući snažno svjedočanstvo o cijeni slobode i ljudskog dostojanstva.', 'Пронзительный графический роман, сохраняющий живую память и напоминающий о ценности человеческой жизни и свободы.', 'A poignant graphic novel preserving living memory and reminding young readers of the profound value of human life and freedom.', 'Potresan grafički roman koji čuva živo sjećanje i podsjeća nas na neprocjenjivu vrijednost ljudskog života i slobode.', '/covers/DP-1289.webp', '#3e3a37', 'important_topics', 'ru', 'available', '', '["real"]', '["graphic novel","history","gulag","memory","human rights"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('25-августа-1290', 'DP-1290', '25 августа', 'August 25th', '25. avgust', 'Александра Кувшинова', 'Aleksandra Kuvshinova', 'Aleksandra Kuvšinova', 'Софья Касьян', 'самокат', NULL, NULL, 4, 12, 'middle', 'В 1968 году во всем мире происходили важные события: повсюду люди боролись за свободу. Студенты выходили на демонстрации, правительства обсуждали права человека, музыканты писали песни о свободе и братстве. Что происходило тогда в Москве, на Красной площади? О чем думали люди, чего боялись и за что боролись? Как поступки отдельных людей могли повлиять на отношения между государствами? Что такое "мирная демонстрация" и почему за нее можно было попасть в тюрьму?', 'In 1968, pivotal events unfolded across the globe as people stood up for freedom. Students marched, debates on human rights raged, and musicians sang of liberty. But what happened on Moscow''s Red Square on August 25th? What were those few brave individuals thinking, what did they risk, and how did a quiet seven-minute protest challenge an entire empire? An accessible, striking look into modern history and civil courage.', 'Godine 1968. širom svijeta dešavali su se prelomni događaji: ljudi su ustajali u borbi za slobodu. Dok su studenti marširali, a muzičari pjevali o pravdi, šta se tačno odigralo na moskovskom Crvenom trgu 25. avgusta? O čemu su razmišljali ti hrabri ljudi i zašto su rizikovali sve? Upečatljiva istorijska priča o mirnom protestu i tome kako glas nekolicine može odjeknuti kroz vjekove.', 'Сильный и честный графический рассказ о том, как смелость горстки людей на Красной площади доказала, что свобода всегда сильнее страха.', 'A powerful, honest graphic journey into history showing how the quiet courage of just a few people proved that freedom shines brighter than fear.', 'Snažna i iskrena priča o istoriji koja pokazuje kako mirna hrabrost šačice ljudi dokazuje da je sloboda uvijek jača od straha.', '/covers/DP-1290.webp', '#b8352e', 'important_topics', 'ru', 'available', '', '["real"]', '["history","freedom","civil courage","protest","graphic non-fiction"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('бежать-нельзя-остаться-1291', 'DP-1291', 'Бежать нельзя остаться', 'Run or Stay', 'Pobjeći ili ostati', 'Алексей Олейников', 'Alexei Oleynikov', 'Aleksej Olejnikov', '', 'Самокат', NULL, NULL, 4, 12, 'middle', 'Семь историй об учениках обычной российской школы - выходцев из Йемена, Афганистана, Южного Судана, ЦАР, Палестины, Сирии и ДРК - основаны на реальных событиях и рассказывают, какие сложности вынуждены преодолевать дети-беженцы и их семьи. Языковой барьер и культурные различия, отсутствие правового статуса и поддержки со стороны государства, бедность, социальная изоляция и буллинг - лишь часть проблем, с которыми сталкиваются вынужденные мигранты. Графические истории, собранные писателем Алексеем Олейниковым и выполненные студентами Высшей школы экономики, дополнены мировой статистикой и краткими справками о странах исхода и причинах вынужденной миграции. В книге также есть памятка о том, как помочь оказавшимся в подобной ситуации людям.', 'Based on true stories, this graphic novel features seven students from Yemen, Afghanistan, South Sudan, the Central African Republic, Palestine, Syria, and the DRC attending an ordinary school. Through striking comic narratives illustrated by art students, the book explores the immense challenges refugee children and their families face—from language barriers and bureaucracy to bullying and loneliness—alongside real-world statistics, country profiles, and guidance on how to offer meaningful support.', 'Zasnovana na istinitim događajima, ova grafička novela donosi sedam priča o učenicima iz Jemena, Avganistana, Južnog Sudana, CAR-a, Palestine, Sirije i DR Konga koji pohađaju običnu školu. Kroz upečatljive stripove, knjiga progovara o preprekama s kojima se djeca izbjeglice suočavaju — od jezičkih barijera i birokratije do nerazumijevanja i izolacije — uz statističke podatke, kontekst zemalja iz kojih dolaze i praktične savjete kako im pružiti ruku podrške.', 'Пронзительный и честный графический путеводитель по чужому опыту, который учит сопереживать тем, чей дом остался за тысячи километров.', 'A poignant, deeply human graphic collection that builds bridges of empathy for classmates whose homes were left thousands of miles behind.', 'Dirljiva i iskrena grafička novela koja nas uči empatiji prema vršnjacima čiji su domovi ostali hiljadama kilometara daleko.', '/covers/DP-1291.webp', '#34495e', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["graphic novel","refugees","empathy","tolerance","human rights"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('скажи-мне-здравствуй--1292', 'DP-1292', 'Скажи мне "Здравствуй!"', 'Say Hello to Me!', 'Reci mi zdravo!', 'Алексей Олейников', 'Alexey Oleynikov', 'Aleksej Olejnikov', '', 'Самокат', NULL, NULL, 4, 12, 'middle', 'Россия — страна многонациональная. Здесь люди разных национальностей веками жили рядом друг с другом и находили общий язык. Сегодня те, кого мы еще недавно называли «жители братских республик», вдруг стали непонятными «мигрантами». Мы подумали, если объяснить, кто такие в действительности мигранты, почему они были вынуждены уехать из родных мест, если рассказать детям их истории и приокрыть дверь в их культуру, если честно признаться в том, что наши предки (за редким исключением) тоже когда-то были мигрантами, вокруг станет меньше страха и больше тепла.', 'People of diverse cultures have lived side by side for centuries, discovering common ground. Today, newcomers often face prejudice under the cold label of ''migrants''. By sharing personal stories, explaining why families leave their homelands, and welcoming children into different traditions, this book reminds us that almost all our ancestors were once migrants, too—replacing fear with genuine human warmth.', 'Ljudi različitih kultura vjekovima su živjeli jedni pored drugih i pronalazili zajednički jezik. Danas se pridošlice često suočavaju s hladnom etiketom „migranti”. Ova knjiga otkriva ko su ti ljudi u stvarnosti, zašto su napustili svoje domove, otvara vrata njihovoj tradiciji i podsjeća da su i naši preci nekada bili putnici u potrazi za novim početkom — kako bi u svijetu bilo manje straha, a više razumijevanja.', 'Искренняя и нужная книга, напоминающая, что за незнакомым словом «мигрант» прячется живой человек, которому просто нужно вовремя сказать «Привет!».', 'A tender and timely guide that proves an open heart and a simple ''hello'' can turn any stranger into a new neighbor.', 'Topla i mudra knjiga koja podsjeća da iza nepoznatih lica stoje ljudi kojima je ponekad potrebno samo jedno iskreno „Zdravo!” da se osjete kao kod kuće.', '/covers/DP-1292.webp', '#e07a5f', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["migration","empathy","diversity","friendship","multiculturalism"]', 1792836322701, 1792845725956);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('наш-мир-и-наши-права-1293', 'DP-1293', 'Наш мир и наши права', 'Our World and Our Rights', 'Naš svijet i naša prava', '', 'Unknown', 'Nepoznat autor', '', 'КомпасГид', NULL, NULL, 4, 12, 'middle', 'Учебно-методическое пособие "Наш мир и наши права. Что нужно знать о правах человека школьникам младших и средних классов" включает 30 пошаговых планов уроков, посвященных обсуждению Декларации прав человека, истории, литературных произведений, а также материалы для копирования, советы по проведению уроков и списки дополнительных источников. Оно поможет учителям рассказать детям 6-13 лет о правах человека и о том, как применять полученные знания в жизни. Учебник поможет: - рассказать о Всеобщей декларации прав человека и Конвенции о правах ребенка, их значении и ценностях; - выработать техники работы по правозащитной тематике; - включить правозащитный аспект в обсуждение тем об окружающем мире, о взрослении, нравственности, гражданской позиции, образовании, родной речи.', 'This educational guide, ''Our World and Our Rights: What Elementary and Middle Schoolers Need to Know About Human Rights,'' offers 30 step-by-step lesson plans exploring the Universal Declaration of Human Rights, history, and literature. Filled with ready-to-copy worksheets, practical teaching tips, and curated reading lists, it empowers educators and parents to discuss human dignity, empathy, growing up, and civic responsibility with children aged 6 to 13 in an engaging, relatable way.', 'Ovaj obrazovni priručnik, „Naš svijet i naša prava: Šta osnovci treba da znaju o ljudskim pravima“, nudi 30 detaljnih planova časova posvećenih Univerzalnoj deklaraciji o ljudskim pravima, istoriji i književnim djelima. Uz radne listove za kopiranje, praktične savjete i preporučene izvore, knjiga pomaže nastavnicima i roditeljima da djeci uzrasta od 6 do 13 godina na jasan i topao način približe teme ljudskog dostojanstva, ravnopravnosti, odrastanja i građanske svijesti.', 'Незаменимый путеводитель по справедливости и доброте, который простыми словами объяснит юным гражданам, как устроен мир прав и взаимного уважения.', 'An essential, warmhearted guide to fairness and respect that helps young minds grasp their rights and learn how to make the world a kinder place.', 'Nezamjenjiv i topao vodič kroz pravdu i poštovanje koji djeci na jednostavan način objašnjava njihova prava i uči ih kako da svijet učine boljim mjestom.', '/covers/DP-1293.webp', '#2c6e91', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["human rights","education","civic awareness","empathy","non-fiction"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('выборы-зверей-1294', 'DP-1294', 'Выборы зверей', 'The Animals'' Election', 'Izbori životinja', '', 'André Rodrigues, Larissa Ribeiro, Paula Desgualdo, Pedro Markun', 'Andre Rodrigez, Larisa Ribeiro, Paula Desgvaldo, Pedro Markun', '', 'Самокат', NULL, NULL, 4, 12, 'middle', 'Жители леса уже устали от царских капризов Льва. Вы только посмотрите: он отвел всю воду из реки, чтобы устроить у своего логова бассейн! Оставил всех без воды! И тогда возникает идея: лесу нужен новый правитель - значит, надо провести выборы! Сказано - сделано. Кандидатами на пост президента леса становятся Макака, Ленивец, Кобра и, конечно, Лев. А как проходят выборы? Каковы правила? Как определяется победитель? Ты узнаешь обо всём этом вместе с лесными зверями и сам сможешь выбрать полюбившегося кандидата. Только тс-с-с... голосование тайное!', 'Fed up with Lion''s selfish antics—like diverting the entire river just to build his own private pool—the woodland creatures decide it''s time for democracy! A monkey, a sloth, a cobra, and Lion himself launch their campaigns. How do debates, voting, and counting actually work? Follow along with the forest citizens, learn the basics of civic life, and cast your own vote—just remember, ballots are secret!', 'Šumskim životinjama je dosta samovolje kralja Lava – zamislite, preusmjerio je čitavu rijeku samo da napravi sebi bazen! Vrijeme je za promjene: šumi treba novi vođa, a to znači da se raspisuju pravi izbori. U trku ulaze majmun, ljenjivac, kobra i, naravno, stari kralj Lav. Kako teče kampanja, kakva su pravila i kako se bira pobjednik? Saznajte sve o demokratiji i glasajte – samo pssst, glasanje je tajno!', 'Остроумное и понятное руководство по демократии для юных граждан, где даже ленивец готов побороться за президентское кресло!', 'A delightfully witty crash course in democracy that proves choosing a leader is serious business—even when the candidates are monkeys and sloths!', 'Duhovit i jasan uvod u demokratiju za male građane, gdje se čak i ljenjivac bori za predsjedničku fotelju!', '/covers/DP-1294.webp', '#e5a823', 'important_topics', 'ru', 'available', '', '["funny","animals","real"]', '["democracy","elections","animals","citizenship","humor"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('книга-о-правах-человека-1295', 'DP-1295', 'Книга о правах человека', 'The Book of Human Rights', 'Knjiga o ljudskim pravima', '', 'Jacqueline Duhême, Robert Badinter', 'Žaklin Duem, Rober Badenter', '', 'КомпасГид', NULL, NULL, 4, 12, 'middle', 'Как рассказать детям - деятелям и гражданам будущего - о правах человека? Текст принятой в 1948 году "Декларации прав человека" слишком абстрактен, комментарии непонятны, учебники скучны. Чтобы выйти из этой ситуации, художница Жаклин Дюэм и правозащитник Робер Бадентер объединились и создали "Книгу о правах человека". Благодаря таланту Жаклин, оригинальный текст Декларации наполнился цветом и ожил. В ней абстракция наполнилась поэзией, в каждой статье поселились замечательные герои, необычные животные и фантастические цветы. Сухие слова превратились в сказку. Сказку, которая должна стать понятной и близкой реальностью для сегодняшних детей - завтрашних мужчин и женщин.', 'How can we introduce children to the concept of human rights without getting lost in dry legal terms? Renowned illustrator Jacqueline Duhême teamed up with human rights champion Robert Badinter to bring the 1948 Universal Declaration of Human Rights vividly to life. With vibrant colors, poetic imagery, friendly animals, and whimsical characters, abstract principles transform into an accessible, heartwarming story about equality, freedom, and human dignity.', 'Kako djeci, budućim stvaraocima sjutrašnjice, objasniti pojam ljudskih prava? Univerzalna deklaracija o ljudskim pravima iz 1948. godine često djeluje previše apstraktno, ali zahvaljujući ilustratorki Žaklin Duem i borcu za ljudska prava Roberu Badenteru, ona oživljava na najljepši način. Kroz tople boje, poetične motive i neobične likove, svako pravilo postaje razumljiva i bliska priča o jednakosti, poštovanju i slobodi.', 'Серьёзный разговор о свободе и справедливости превращается в тёплую, красочную сказку, понятную каждому ребёнку.', 'A serious conversation about freedom and justice turns into a bright, beautifully illustrated story every child can embrace.', 'Ozbiljan razgovor o slobodi i pravdi pretvara se u toplu, živopisnu priču koju svako dijete može lako da razumije.', '/covers/DP-1295.webp', '#2d7f9d', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["human rights","equality","freedom","society","picture book"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('мы-все-рождены-свободными-1296', 'DP-1296', 'Мы все рождены свободными', 'We Are All Born Free', 'Svi smo rođeni slobodni', '', 'Amnesty International', 'Amnesti internašonal', '', 'КомпасГид', NULL, NULL, 4, 12, 'middle', 'Все люди на планете должны быть защищены Всеобщей декларацией прав человека. Где бы мы ни жили, кем бы ни были - это наши права, и никто не может у нас их отнять. Веря в эти правила, действуя в соответствии с ними, обещая никогда не нарушать их, мы делаем мир лучше. Мы сами становимся лучше. Если подумать, это не так уж сложно, правда? "Мы все рождены свободными" - это уникальная книжка-картинка: специально для маленьких Граждан Мира текст Декларации сделан более доступным для понимания, все 30 статей проиллюстрированы известными детскими художниками, а обложка оформлена Петром Сисом.', 'Every person on Earth is protected by the Universal Declaration of Human Rights. No matter who we are or where we live, these rights belong to all of us. ''We Are All Born Free'' adapts all thirty articles of the Declaration for young global citizens, vividly illustrated by world-renowned artists to celebrate equality, freedom, and kindness.', 'Svi ljudi na planeti zaštićeni su Univerzalnom deklaracijom o ljudskim pravima. Gdje god živjeli i ko god bili, to su naša prava i niko nam ih ne može oduzeti. „Svi smo rođeni slobodni“ je prelijepa slikovnica koja djeci približava svih trideset članova Deklaracije kroz nadahnute radove slavnih svjetskih ilustratora.', 'Тёплая, вдохновляющая и невероятно красивая азбука человеческого достоинства, понятная и пятилетке, и взрослому.', 'A luminous, gorgeously illustrated guide to human dignity that proves big ideas can be simple, kind, and empowering.', 'Predivno ilustrovana i topla knjiga o ljudskom dostojanstvu koja dokazuje da velika prava mogu razumjeti i najmlađi.', '/covers/DP-1296.webp', '#3a7ebd', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["human rights","freedom","equality","picture book","kindness"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-имею-право-быть-ребенком-1297', 'DP-1297', 'Я имею право быть ребенком', 'I Have the Right to Be a Child', 'Imam pravo da budem dijete', 'Ален Серр', 'Alain Serres', 'Alain Serres', 'Орелия Фронти', 'Самокат', NULL, NULL, 4, 12, 'middle', 'Права ребенка - это не просто громкие слова на бумаге. Права ребенка важны везде: дома и в школе, во дворе и в больнице, на экране телевизора, компьютера и телефона, в книге и игре. Они должны соблюдаться всеми - ведь дети не всегда могут сами себя защитить, - чтобы из счастливых и защищенных детей выросли умные, добрые и сильные взрослые. Французский педагог, писатель и издатель Алан Серр рассказывает о правах ребёнка простым, но ярким, как иллюстрации к этой книге, языком, с ритмом и рифмами. А помогает ему на русском языке замечательный переводчик Михаил Яснов.', 'Children''s rights are not just solemn words on paper—they matter everywhere: at home, at school, in the playground, in books, and on screens. French educator and writer Alain Serres turns the principles of the UN Convention on the Rights of the Child into vivid, poetic verses, showing that every child deserves safety, care, and the freedom to grow into a compassionate and confident adult.', 'Prava djeteta nijesu samo krupne riječi na papiru — ona su važna svuda: kod kuće, u školi, u igri i u pričama. Francuski pedagog i pisac Alen Ser na jednostavan, poetičan i topao način približava Konvenciju o pravima djeteta, podsjećajući nas da svako dijete zaslužuje da raste bezbjedno, slobodno i okruženo ljubavlju.', 'Поэтичный, солнечный и очень важный манифест о том, что детство — это священное право на игру, заботу и собственный голос.', 'A radiant, poetic reminder that being a child means having the undeniable right to play, dream, and be protected.', 'Predivan i topao podsjetnik da svako dijete ima neprikosnoveno pravo na igru, snove, ljubav i bezbrižno odrastanje.', '/covers/DP-1297.webp', '#d95338', 'important_topics', 'ru', 'available', '', '["real"]', '["children''s rights","growing up","kindness","equality","poetry"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('стена-1298', 'DP-1298', 'Стена', 'The Wall: Growing Up Behind the Iron Curtain', 'Zid: Kako sam odrastao iza gvozdene zavjese', 'Петр Сис', 'Peter Sís', 'Peter Sis', '', 'Самокат', NULL, NULL, 4, 12, 'middle', 'Автобиографическая книга "Стена: как я рос за железным занавесом" - история детства и взросления художника, в судьбу которого постоянно вмешивалась политика. Это история мальчика, который рос совсем недавно, но совершенно в другую эпоху: во время Холодной войны. История мальчика, который родился и вырос за железным занавесом. Всю свою жизнь он хотел рисовать и мечтал о времени, когда рухнут стены недоверия и лжи, разделяющие людей. Иногда мечты сбываются. 9 ноября 1989 года рухнула Берлинская стена, и это событие ознаменовало окончание Холодной войны.', 'A deeply moving graphic memoir about growing up in Cold War Czechoslovakia behind the Iron Curtain. Peter Sís blends diary entries, historical context, and intricate drawings to recount a childhood filled with compulsory parades, secret Beatles records, and a stubborn dream that walls of fear and division would one day crumble.', 'Potresna i moćna autobiografska priča u slikama o djetinjstvu i odrastanju iza gvozdene zavjese u Čehoslovačkoj tokom Hladnog rata. Peter Sis kroz crteže i lične zapise priča o obaveznim paradama, tajnom slušanju rokenrola i dječaku čija je strast prema umjetnosti i slobodi bila jača od svakog zida.', 'Пронзительный графический дневник о свободе, рок-н-ролле и силе искусства, способного разрушить любые железные занавесы.', 'A breathtaking, deeply personal graphic memoir showing how art, rock ''n'' roll, and the longing for freedom can topple even the highest walls.', 'Dirljiva grafička priča o tome kako umjetnost, rokenrol i želja za slobodom mogu srušiti i najtvrđe zidove.', '/covers/DP-1298.webp', '#b83b3b', 'important_topics', 'ru', 'available', '', '["real","adventure"]', '["cold war","history","freedom","autobiography","graphic novel"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('диктатор-1299', 'DP-1299', 'Диктатор', 'The Dictator', 'Diktator', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Линда Бондестам', 'КомпасГид', NULL, NULL, 4, 12, 'middle', 'Диктатор ложится спать и приказывает звездам светить, диктатор просыпается и приказывает манной каше сию секунду остыть. Все это у него очень хорошо получается, он самый лучший в мире тиран. И, кажется, все вокруг уже и забыли, что он просто-напросто ребенок. Но если диктатор очень маленький, ему в конце концов может стать очень одиноко. Потому что нельзя приказать кому-то быть твоим другом. "Диктатор" классика шведской детской литературы Ульфа Старка и талантливого финского иллюстратора Линды Бондестам - пожалуй, первая антиутопия для самых маленьких. Это смешная и нежная история о том, как важно не забывать, что на свете есть любовь.', 'The Dictator goes to bed and commands the stars to shine; he wakes up and orders his porridge to cool down immediately. He is very good at commanding, perhaps the best little tyrant in the world. Everyone around seems to have forgotten he is just a tiny child. But even the fiercest dictator gets terribly lonely, because you can''t simply order someone to be your friend. Ulf Stark and Linda Bondestam have crafted a witty, tender anti-utopia for the youngest readers about big feelings and true warmth.', 'Diktator ide na spavanje i naređuje zvijezdama da sijaju; budi se i zapovijeda kaši da se smjesta ohladi. U tome je nevjerovatno uspješan — najbolji mali tiranin na svijetu! Čini se da su svi oko njega zaboravili da je on zapravo samo dijete. Ipak, i diktatoru postane usamljeno, jer se prijateljstvo ne može dobiti naređenjem. Švedski klasik Ulf Stark i ilustratorka Linda Bondestam stvorili su duhovitu i nježnu priču o moći, usamljenosti i zagrljajima.', 'Если в вашем доме завёлся грозный повелитель манной каши, эта остроумная и трогательная книга покажет, что даже самому суровому тирану на самом деле нужны друзья и объятия.', 'If there''s a tiny, stubborn commander ruling over your breakfast table, this delightfully witty book gently reminds us that even the fiercest little tyrants just need a friend.', 'Ako u vašem domu vlada mali tiranin koji naređuje kaši i zvijezdama, ova topla i duhovita slikovnica podsjetiće ga da se prijateljstvo ne može zapovijedati.', '/covers/DP-1299.webp', '#D93829', 'important_topics', 'ru', 'available', '', '["funny","friends","real"]', '["tantrums","friendship","humor","empathy","preschool"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('генерал-1300', 'DP-1300', 'Генерал', 'The General', 'General', 'Майкл Форман', 'Michael Foreman', 'Majkl Forman', '', 'Мир детства', NULL, NULL, 4, 12, 'middle', 'Один генерал хотел быть самым знаменитым генералом на свете. Но однажды он упал с лошади на прекрасной поляне и, увидев красоту цветов, разлюбил войну и научился ценить природу. Эта книга была написана и нарисована в 1961 году. Её авторы выросли в военном Лондоне под постоянными бомбёжками и никогда не знали мира без войны. Поэтому они придумали книгу, которая прославляла бы природу, а не разрушение. Сегодня в Англии "Генерал" отмечает юбилей. Нарисовавший её Майкл Форман стал одним из самых знаменитых английских художников. Он проиллюстрировал более 140 книг. Получил множество престижных наград. Но "Генерал" остаётся одной из главных его книг и через полстолетия не теряет актуальности. Он всё так же напоминает нам: чтобы сохранить наш удивительный мир, надо беречь каждую травинку и ценить каждую букашечку.', 'A proud general wants to become the most famous commander in the world, until he falls off his horse into a field of magnificent wildflowers and discovers the wonder of peace and nature. Created in 1961 by celebrated artist Michael Foreman, who grew up amidst the bombings of wartime London, this timeless anti-war picture book celebrates the beauty of every blade of grass over the cold machinery of war.', 'Ponosni general želi da postane najslavniji komandant na svijetu, sve dok jednoga dana ne padne s konja u polje čudesnog divljeg cvijeća i otkrije ljepotu mira i prirode. Nastala 1961. godine iz pera i kista čuvenog Majkla Formana, koji je odrastao pod ratnim bombardovanjem Londona, ova vanvremenska slikovnica slavi život, očuvanje prirode i mir umjesto razaranja.', 'Удивительно нежная антивоенная притча о том, как одна цветочная поляна может обезоружить целую армию и спасти целый мир!', 'A wonderfully tender anti-war fable proving that a field of wildflowers can easily disarm a mighty army and save the world!', 'Predivna i nježna antiratna priča o tome kako jedno polje cvijeća može razoružati čitavu vojsku i spasiti svijet!', '/covers/DP-1300.webp', '#4f7942', 'important_topics', 'ru', 'available', '', '["real"]', '["мир","природа","цветы","доброта","классика"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('коричневое-утро-1301', 'DP-1301', 'Коричневое утро', 'Brown Morning', 'Smeđe jutro', 'Франк Павлофф', 'Franck Pavloff', 'Frank Pavlof', '', 'КомпасГид', NULL, NULL, 4, 12, 'middle', '"Коричневое утро" - это новелла, написанная Франком Павлоффом в декабре 1998 года. Сюжет, как и сам стиль повествования "Коричневого утра", очень прост: два самых обычных приятеля, наблюдая, как формируется государство Коричневых, отказываются беспокоиться и что-то предпринимать. Незаметно для героев, в результате принятых мер и новых законов, всё изменяет цвет: кошки, собаки, газеты, радио... Нет причин для беспокойства - достаточно только соблюдать новые правила. Феномен антифашистской новеллы "Коричневое утро" Франка Павлоффа действительно впечатляет: книжечка в 12 страниц и стоимостью в 1 евро - вот уже больше 10 лет в списке бестселлеров во Франции, выдержала больше 40 переизданий, а общий тираж превышает 1 500 000 экземпляров.', 'Written by Franck Pavloff, ''Brown Morning'' is a concise yet strikingly powerful allegorical novella. Two ordinary friends watch as a totalitarian regime quietly takes over, deciding it''s easier not to worry and just follow the new rules. Step by step, everything turns brown—from cats and dogs to newspapers and radio. This deceptively simple anti-fascist fable has sold millions of copies worldwide, serving as an indispensable reminder of the danger of quiet compliance.', '„Smeđe jutro“ je kratka, ali izuzetno snažna alegorijska novela Franka Pavlofa. Dva obična prijatelja posmatraju rađanje totalitarne države, birajući da ne brinu i samo poštuju nova pravila. Korak po korak, sve poprima smeđu boju — od mačaka i pasa do štampe i radija. Ova antifašistička priča prodata je u milionima primjeraka širom svijeta kao nezaboravna opomena o opasnosti ravnodušnosti i ćutanja.', 'Короткая, но поразительно глубокая притча, которая учит вовремя замечать тревожные звоночки и никогда не закрывать глаза на несправедливость.', 'A brief yet deeply moving parable that gently reminds readers of all ages why staying silent is never a safe choice.', 'Kratka, ali nevjerovatno snažna priča koja podsjeća i djecu i odrasle zašto ćutanje pred nepravdom nikada nije rješenje.', '/covers/DP-1301.webp', '#7a5230', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["allegory","parable","freedom","important topics","friendship"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('дневник-блюмки-1302', 'DP-1302', 'Дневник Блюмки', 'Blumka''s Diary', 'Blumkin dnevnik', 'Ивонна Хмелевская', 'Iwona Chmielewska', 'Ivona Hmjelevska', '', 'Лес рук', NULL, NULL, 4, 12, 'middle', 'Варшава — Улица Крохмальная, 92 — Дом сирот. Когда-то тут жила Блюмка, доктор Корчак, пани Стефа и двести детей, в том числе: Зигмусь, который подарил жизнь серебряной рыбе, Регинка, чьи рассказы могли озарить самую тёмную ночь, Поля, которая вырастила у себя в ухе горошек, Хаимек, которого муравьи довели до суда, Чижик, который так усердно помогал, нося уголь в эмалированном горшке, и мышка, крошки для которой падали прямо с неба. Блюмка записывала все это у себя в дневнике, а когда ей не хватало слов — добавляла рисунки. До того дня, когда началась война… Ивона Хмелевская — всемирно известная польская художница и писательница. Живет и работает в Торуни, где также преподает на факультете изящных искусств Университета Николая Коперника.', 'Warsaw, 92 Krochmalna Street — The Orphan Home. Once upon a time, Blumka lived here with Doctor Korczak, Madame Stefa, and two hundred children: Zygmuś, who spared a silver fish; Reginka, whose tales could light up the darkest night; and many others. Blumka recorded their everyday moments in her diary, drawing pictures when words fell short, right up until the day the war broke out. A tender, exquisite masterpiece honoring Janusz Korczak and his children.', 'Varšava — Ulica Krohmalna 92 — Dom za siročad. Nekada su ovdje živjeli Blumka, doktor Korčak, gospođa Stefa i dvije stotine djece: Zigmuś koji je poštedio srebrnu ribu, Reginka čije su priče osvjetljavale najmračnije noći, i mnogi drugi. Blumka je sve to bilježila u svoj dnevnik, crtajući kad bi joj ponestalo riječi, sve do onog dana kada je počeo rat... Izuzetno nježna i dirljiva knjiga posvećena sjećanju na Januša Korčaka i njegovu djecu.', 'Невероятно трогательное и светлое свидетельство о доме доктора Корчака, где уважение и любовь к детям были важнее любых невзгод.', 'An exquisitely tender, luminous glimpse into Janusz Korczak’s orphanage, reminding us how precious, dignified, and brave a child''s everyday world can be.', 'Neizmjerno dirljiv i topao uvid u dom doktora Korčaka, koji nas podsjeća koliko je svijet svakog djeteta dragocjen i dostojanstven.', '/covers/DP-1302.webp', '#bfa588', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["history","janusz korczak","memory","diary","childhood"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('когда-я-вернусь-1303', 'DP-1303', 'Когда я вернусь', 'When I Return', 'Kad se vratim', 'Йессика Баб Бунде', 'Jessica Bab Bonde', 'Džesika Bab Bonde', 'Петер Бергтинг', 'Белая ворона', NULL, NULL, 4, 12, 'middle', 'Тобиас, Ливия, Сельма, Сусанна, Эмерих и Элисабет. Их жизнь началась так же, как твоя и моя. Они родились в мирных городах, у них была крепкая семья и верные друзья. Была крыша над головой, еда и одежда, такие же мысли и проблемы, как у самых обычных детей. Но однажды их жизнь изменилась… "Когда я вернусь" - это истории людей, в детстве прошедших через концлагеря. Йессика Баб Бунде собрала свидетельства очевидцев, а художник Петер Бергтинг нарисовал комиксы по мотивам этой старой истории.', 'Tobias, Livia, Selma, Susanna, Emerich, and Elisabeth lived ordinary, peaceful childhoods with loving families and friends—until the Second World War shattered their world. ''When I Return'' shares the real-life memories of six survivors who lived through concentration camps as children. Jessica Bab Bonde gently collected their poignant testimonies, vividly brought to life through Peter Bergting''s evocative illustrations.', 'Tobijas, Livija, Selma, Suzana, Emerih i Elizabet imali su bezbrižno djetinjstvo, dom i prijatelje — sve dok rat nije promijenio sve. „Kad se vratim“ donosi stvarne priče šestoro ljudi koji su kao djeca preživjeli koncentracione logore. Džesika Bab Bonde zabilježila je njihova svjedočanstva, a ilustrator Peter Bergting pretočio ih je u dirljivi strip o sjećanju i nadi.', 'Трогательный и деликатный графический роман, который бережно рассказывает детям о сложнейших страницах истории через голоса их ровесников.', 'A tender and accessible graphic novel that gently introduces young readers to history through the brave, unforgettable voices of children.', 'Dirljiv i pažljivo osmišljen strip koji djeci otvara važne istorijske teme kroz stvarne i hrabre priče njihovih vršnjaka.', '/covers/DP-1303.webp', '#6e737a', 'important_topics', 'ru', 'available', '', '["real"]', '["graphic novel","history","holocaust","memories","courage"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('не-справедливость-1304', 'DP-1304', 'Не/справедливость', 'In/Justice', 'Ne/pravda', 'Ника Дубровская', 'Nika Dubrovsky', 'Nika Dubrovski', '', 'Самокат', NULL, NULL, 4, 12, 'middle', 'В разные времена в разных культурах представления о том, что такое справедливость, менялись. Когда-то считалось несправедливым убивать людей, но торговля живыми людьми была вполне приемлемой и законной. В большинстве культур считается обязательным накормить и приютить странника, а где-то возможность напиться воды - предмет торговли и привилегия. От эпохи к эпохе, от культуры к культуре мы изменяем наше коллективное мнение о том, что такое хорошо, а что такое плохо. "НЕ/СПРАВЕДЛИВОСТЬ" - собрание историй и мнений из разных эпох.', 'Throughout history and across different cultures, humanity''s ideas about justice have continually shifted. While sheltering a weary traveler was once an unquestioned duty in some societies, elsewhere clean drinking water remains a commodity and a privilege. Epoch by epoch, our collective understanding of right and wrong transforms. ''In/Justice'' brings together captivating stories and perspectives from across eras, empowering young readers to think critically about fairness, ethics, and human dignity.', 'Kroz različite epohe i kulture, shvatanja o tome šta je pravedno stalno su se mijenjala. Nekada je trgovina ljudima bila zakonita, dok se u većini kultura pružanje skloništa putniku podrazumijeva, a negdje je i obična voda bila privilegija. Iz vijeka u vijek mijenjamo zajedničko mišljenje o tome šta je dobro, a šta loše. „Ne/pravda“ je zbirka priča i razmišljanja iz raznih doba koja poziva mlade čitaoce da promišljaju o pravednijem svijetu.', 'Книга-исследование, которая научит спорить с умом, замечать несправедливость и делать мир вокруг чуточку честнее!', 'A brilliant interactive guide that teaches young thinkers how to question the world and stand up for what''s fair!', 'Sjajan interaktivni vodič koji uči mlade mislioce kako da preispituju svijet i bore se za pravdu!', '/covers/DP-1304.webp', '#d95338', 'important_topics', 'ru', 'available', '', '["real"]', '["justice","history","society","human rights","philosophy"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('хиросима-1305', 'DP-1305', 'Хиросима', 'Hiroshima No Pika', 'Hirošima', 'Тоси Маруки', 'Toshi Maruki', 'Toši Maruki', '', 'КомпасГид', NULL, NULL, 4, 12, 'middle', '…6 августа 1945 года, в восемь часов пятнадцать минут ужасная вспышка осветила небо над Хиросимой. Это взорвалась первая в истории человечества атомная бомба. Вместе с мамой, которая несла на спине раненого отца, семилетняя Мии-тян бежала по городу, пытаясь спастись от огня. Падающие друг на друга люди, чёрный маслянистый дождь, радуга на тёмном небе и хрупкая надежда - вот что запомнила девочка. Чтобы позже рассказать об этом тем, кого там не было. Такое сложно представить или описать, но автору этой уникальной книжки-картинки, Тоси Маруки, это удаётся с потрясающей силой. "Если люди не сбросят бомбу, она сама не упадёт", - напоминает нам автор-номинант на Нобелевскую премию мира - и её слова звучат на 14 языках мира…', 'On August 6, 1945, at 8:15 a.m., a terrifying flash lit up the sky over Hiroshima as the first atomic bomb in human history detonated. Together with her mother carrying her wounded father, seven-year-old Mii-chan fled through the burning city. Amid black rain, falling debris, and unimaginable sorrow, she held on to a flicker of hope. Created by Nobel Peace Prize nominee Toshi Maruki, this unforgettable picture book speaks across generations and languages as a solemn plea for peace.', 'Šestog avgusta 1945. godine u osam sati i petnaest minuta, strahovit bljesak osvijetlio je nebo nad Hirošimom kada je eksplodirala prva atomska bomba u istoriji. Sedmogodišnja Mii-čan, zajedno s majkom koja nosi ranjenog oca, bježi kroz vatru i ruševine razorenog grada. Crna kiša, duga na tamnom nebu i krhka nada zauvijek su ostali u sjećanju ove djevojčice. Kroz snažne ilustracije i potresne riječi, Toši Maruki stvorila je knjigu-svjedočanstvo koja nas podsjeća koliko je mir dragocjen.', 'Пронзительная и важная книга-свидетельство о мире, сострадании и надежде, которую стоит бережно прочесть вместе.', 'A deeply moving and necessary testament to peace, memory, and enduring hope that children and adults should gently read together.', 'Duboko dirljivo i važno svjedočanstvo o miru, saosjećanju i nadi, koje vrijedi pažljivo pročitati zajedno.', '/covers/DP-1305.webp', '#8c3b2b', 'important_topics', 'ru', 'available', '', '["real"]', '["история","мир","память","япония","семья"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-ем-лапшу-а-в-это-время-1306', 'DP-1306', 'Я ем лапшу, а в это время', 'While I Eat Noodles', 'Ja jedem rezance, a u to vrijeme', '', 'Yoshifumi Hasegawa', 'Jošifumi Hasegava', '', 'КомпасГид', NULL, NULL, 4, 12, 'middle', 'Как объяснить ребёнку, что его жизнь - это лишь один мазок кисти на картине пуантилистов? Как рассказать, что где-то в мире всё совсем по-другому? На эти вопросы достаточно просто, поэтично и ёмко отвечает книга японского художника Ёсифуми Хасэгава "Я ем лапшу, а в это время…". С Востока дует ветер мудрости, и он нашёптывает историю о мальчике, который однажды за обедом задумался: что же происходит в эту секунду в мире? Кто-то зевает, кто-то играет на скрипке, кто-то готовит обед, кто-то зарабатывает на кусок хлеба… Мир и людские судьбы такие разные, об этом знает восточный ветер, малыш, который ест лапшу, а теперь и вы...', 'While one boy sits slurping his warm noodles, what is happening around the globe at this very second? Someone is yawning, someone is playing violin, and somewhere far away, a child is working to earn bread. A profoundly poetic and tender Japanese picture book that introduces children to empathy, global awareness, and the vastly different lives sharing our fragile planet.', 'Dok jedan dječak ruča i srče svoje tople rezance, šta druga djeca na svijetu rade u tom istom djeliću sekunde? Neko zijeva, neko svira violinu, a neko daleko mukotrpno radi za koru hljeba. Nježna i poetska slikovnica japanskog autora koja na jednostavan način uči djecu empatiji, širini svijeta i različitosti ljudskih sudbina.', 'Поэтичная и глубокая история, напоминающая, как огромен наш мир и как важно замечать тех, кто живёт совсем иначе.', 'A quiet, deeply touching reminder that while we slurp our lunch, the whole wide world is unfolding all at once.', 'Tiha i dirljiva priča koja nas podsjeća da, dok mi mirno ručamo, čitav svijet živi hiljadu sasvim različitih života.', '/covers/DP-1306.webp', '#c65f37', 'important_topics', 'ru', 'available', '', '["real"]', '["empathy","world","diversity","philosophy","japan"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('сибирские-хайку-1307', 'DP-1307', 'Сибирские хайку', 'Siberian Haiku', 'Sibirski haiku', 'Юрга Вилле', 'Jurga Vilė', 'Jurga Vile', 'Лина Итагаки', 'Самокат', NULL, NULL, 4, 12, 'middle', '"Сибирские хайку" - графический роман о депортированной литовской семье, в котором можно найти отражение тысяч других семейных историй XX века. "Я - Альгис, но чаще меня называют Альгюкас. Я всегда мечтал путешествовать. Вот только случилось это совсем не так, как я себе представлял. На рассвете 14 июня 1941 года к нам в дом ворвались солдаты и приказали собираться в дорогу. Покидая родную Литву мы не знали, что впереди нас ждут тяжелая работа, голод и злющие кусачие паразиты в холодном бараке - нашем новом доме, в Сибири. Как сложится здесь наша жизнь? Папа учил нас замечать чудеса мира, поддерживать друг друга. И мы стараемся: организуем хор "Яблоки", учимся играть на музыкальных инструментах и даже влюбляемся. И не перестаём надеяться на возвращение домой."', 'A poignant graphic novel based on real events, Siberian Haiku tells the moving story of Algis, a young Lithuanian boy deported with his family to Siberia in June 1941. Amidst bitter cold, relentless hunger, and hard labor in exile, Algis and his companions find ways to keep beauty and dignity alive: singing together in the ''Apples'' choir, writing haiku, learning music, and holding fast to the hope of returning home.', 'Dirljiv grafički roman zasnovan na istinitim događajima, ''Sibirski haiku'' priča priču o dječaku Algisu i njegovoj porodici koji su u junu 1941. godine deportovani iz Litvanije u Sibir. Uprkos oštroj zimi, gladi i teškom radu, Algis i njegovi saputnici pronalaze načine da sačuvaju ljepotu i nadu: osnivaju hor ''Jabuke'', pišu haiku stihove i neumorno sanjaju o povratku domu.', 'Трогательный и светлый графический роман о том, как человеческое тепло, музыка и поэзия помогают пережить самые суровые метели истории.', 'A deeply touching, poetic graphic novel showing that even in the coldest Siberian exile, warmth, song, and poetry can keep hope alive.', 'Nevjerovatno dirljiv i poetičan grafički roman koji pokazuje da pjesma, ljubav i nada mogu zagrijati i najhladnije sibirske zime.', '/covers/DP-1307.webp', '#5b7582', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["graphic novel","history","family","hope","survival"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('свобода-равенство-сестринство-1308', 'DP-1308', 'Свобода, равенство, сестринство', 'Women in Battle: 150 Years of Fighting for Freedom, Equality, and Sisterhood', 'Žene u borbi: Sloboda, jednakost, sestrinstvo', 'Марта Бреен, Йенни Юрдал', 'Marta Breen, Jenny Jordahl', 'Marta Breen, Jenny Jordahl', '', 'Самокат', NULL, NULL, 4, 12, 'middle', '150 лет назад мужчины и женщины жили очень по-разному. Женщины не могли голосовать на выборах и зарабатывать деньги. Они далеко не всегда могли распоряжаться собственным телом. И лишь когда женщины объединились и стали бороться за свои права, начали происходить изменения. Норвежская авторка Марта Бреен и иллюстраторка Йенни Юрдал придумали комикс, в котором легко и понятно рассказывают об истории женского движения, о драматических моментах и великих победах в борьбе женщин за свободу, равенство, сестринство. В Норвегии книга впервые вышла в марте 2018, и ее первый тираж был продан за месяц. Книга попала в список Лучших детских книг 2018 года по версии The Guardian. Права на издание книги проданы в 20 стран - от Албании до США и Японии.', 'One hundred and fifty years ago, women had no right to vote, earn their own money, or make decisions about their own bodies. Everything changed when women joined forces to fight for their rights. In this vivid graphic novel, Norwegian author Marta Breen and illustrator Jenny Jordahl recount the dramatic history, milestones, and breakthroughs of the global feminist movement.', 'Prije 150 godina žene nijesu imale pravo glasa, nijesu mogle samostalno zarađivati niti odlučivati o sopstvenom tijelu. Sve se promijenilo kada su se ujedinile u borbi za svoja prava. U ovom upečatljivom grafičkom romanu, norveška spisateljica Marta Bren i ilustratorka Dženi Jordal na pristupačan način dočaravaju istoriju, prelomne trenutke i pobjede ženskog pokreta za slobodu i jednakost.', 'Яркий и честный комикс о смелых бунтарках, благодаря которым мир стал справедливее для всех нас.', 'A vibrant and empowering graphic novel celebrating the fierce rebels who shaped history and fought for equality.', 'Upečatljiv i inspirativan strip o hrabrim buntovnicama zahvaljujući kojima je svijet postao pravedniji za sve nas.', '/covers/DP-1308.webp', '#e53935', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["feminism","history","graphic novel","equality","human rights"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('полынная-елка-1309', 'DP-1309', 'Полынная елка', 'The Wormwood Christmas Tree', 'Pelinova jelka', 'Ольга Колпакова', 'Olga Kolpakova', 'Olga Kolpakova', '', 'КомпасГид', NULL, NULL, 4, 12, 'middle', 'Что делать, если ваша семья - вдали от дома, от всего привычного и родного, и перед Рождеством у вас нет даже ёлки? Можно нарядить ветку полыни: нарезать бахрому из старой изорванной книжки, налепить из теста барашков, курочек, лошадок. Получится хоть и чёрно-бело, но очень красиво! Пятилетняя Марийхе знает: на тарелке под такой ёлкой утром обязательно найдётся подарок, ведь она весь год хорошо, почти хорошо себя вела. Рождество остаётся праздником всегда - даже на незнакомой сибирской земле, куда Марийхе с семьёй отправили с началом войны. Детская память сохраняет лишь обрывочные воспоминания, лишь фрагменты родительских объяснений о том, как и почему так произошло. Тяжёлая поступь истории приглушена, девочка едва слышит её - и запоминает тихие моменты радости, мгновения будничных огорчений, хрупкие образы, на первый взгляд ничего не говорящие об эпохе 1940-х. Марийхе, её сестры Мина и Лиля, их мама, тётя Юзефина с сыном Теодором, друзья и соседи по Ровнополью - русские немцы. И хотя они, как объяснял девочкам папа, "хорошие немцы", а не "фашисты", дальше жить в родных местах им запрещено: вдруг перейдут на сторону противника? Каким бы испытанием для семьи ни был переезд, справиться помогают добрые люди - такие есть в любой местности, в любом народе, в любое время.', 'What do you do if your family is far from home and you don''t even have a Christmas tree? You decorate a branch of wild wormwood with fringes snipped from an old book and little lambs shaped from dough! Five-year-old Marijche knows that even in harsh Siberian exile, where her Russian-German family was deported at the outbreak of World War II, Christmas remains sacred. Seen through innocent child eyes, the crushing weight of history steps back, revealing tender moments of resilience, family warmth, and the kindness of strangers who help them survive.', 'Šta uraditi ako je vaša porodica daleko od doma i pred Božić nemate čak ni jelku? Možete ukrasiti grančicu pelina resama isječenim iz stare knjige i figuricama od tijesta! Petogodišnja Marijhe zna da Božić ostaje praznik čak i u surovom sibirskom izgnanstvu, gdje je njena rusko-njemačka porodica prognana na početku Drugog svjetskog rata. Kroz nevine dječje oči, teška istorijska previranja ustupaju mjesto toplim trenucima nade, porodičnoj ljubavi i dobroti neznanaca koja pomaže da se preživi i najhladnija zima.', 'Пронзительная и удивительно светлая повесть о том, что даже веточка горькой полыни может стать рождественской ёлкой, если в сердце живет надежда, а рядом семья.', 'A poignant and luminous story showing that even a sprig of bitter wormwood can become a magical Christmas tree when surrounded by family love.', 'Dirljiva i nevjerovatno topla priča koja pokazuje da i obična grančica pelina može postati božićna jelka puna čuda kada je porodica na okupu.', '/covers/DP-1309.webp', '#708269', 'important_topics', 'ru', 'available', '', '["real","friends"]', '["historical fiction","wwii","family","christmas","hope"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('а-дедушка-в-костюме--1310', 'DP-1310', 'А дедушка в костюме?', 'Grandpa''s Suit', 'Je li đed u odijelu?', 'Амели фрид', 'Amelie Fried', 'Ameli Frid', 'Джеки Гляйх', 'КомпасГид', NULL, NULL, 4, 12, 'middle', 'Бруно очень любит своего дедушку. А теперь его нет... Брат Бруно, Ксавер, утверждает, что он на кладбище, а папа говорит - на небесах. Но что тут правда? Ксавер так много врёт, что Бруно не знает, можно ли ему поверить в этот раз. А родители постоянно повторяют: "Этого ты пока не поймёшь"... Поначалу, что бы Бруно ни делал, он чувствует глухую боль в груди. Как будто у него маленькая дырка в груди под свитером. Но постепенно она затягивается. Каждый вечер перед тем, как лечь спать, Бруно смотрит на дедушкину фотографию и разговаривает с ним. "Я тебя не забуду", - обещает он дедушке. И кажется, что тот улыбается ему издалека. Книга "А дедушка в костюме?" в 1998 году была отмечена Немецкой детской литературной премией и Немецким Фондом Искусств. Она переведена на французский, японский, корейский и китайский языки.', 'Bruno loves his grandfather dearly, but now he is gone. His brother Xaver says grandpa is at the cemetery, while Dad says he is in heaven. Who is telling the truth? Grown-ups keep repeating, ''You wouldn''t understand yet,'' leaving Bruno with a quiet, hollow ache in his chest. Slowly, through bedtime conversations with his grandfather''s photograph and warm memories, Bruno learns to heal, realizing that love and remembrance never fade.', 'Bruno neizmjerno voli svog đeda, ali njega više nema... Njegov brat Ksaver tvrdi da je na groblju, dok tata kaže da je na nebu. Kome vjerovati kad odrasli samo ponavljaju: „To još ne možeš da razumiješ“? U početku Bruno osjeća tupu prazninu u grudima, ali s vremenom, kroz tihe večernje razgovore sa đedovom slikom, shvata da ljubav i uspomene zauvijek ostaju sa nama.', 'Трогательная, честная и бережная история, которая помогает детям прожить грусть потери и сохранить светлую память.', 'A deeply touching and gentle book that provides a compassionate, honest way to talk with children about loss, grief, and love that never fades.', 'Dirljiva, iskrena i nježna priča koja pomaže djeci da razumiju gubitak i sačuvaju uspomenu na voljenog đeda.', '/covers/DP-1310.webp', '#3b5866', 'important_topics', 'ru', 'available', '', '["real"]', '["loss","family","grandfather","emotions","growing up"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('как-я-появился-на-свет-1311', 'DP-1311', 'Как я появился на свет', 'How I Came to Be', 'Kako sam došao na svijet', 'Катерина Януш', 'Katerina Janouch', 'Katerina Janouš', 'Мерви Линдман', 'Мир детства', NULL, NULL, 4, 12, 'middle', 'Откуда берутся дети? Что происходит в животе у мамы долгие девять месяцев? Как получаются мальчики и девочки? Откуда ребенок знает, когда ему родиться? Эта книжка - путешествие в таинства жизни. Все дети совершают его, но никто из них не помнит о нем. Настала пора прочесть эту книгу и пройти этот путь заново. Катерина Януш и Мерви Линдман в шутливой и одновременно просветительской форме расскажут о великом чуде - рождении ребенка - и ответят на вопросы детей.', 'Where do babies come from? What happens inside a mother''s belly for nine long months, and how does a baby know when it''s time to be born? This book takes young readers on a playful yet honest journey into the wonder of human life, answering big questions with warmth, humor, and clear, child-friendly explanations.', 'Odakle dolaze bebe? Šta se to dešava u maminom stomaku tokom dugih devet mjeseci i kako beba zna kada je vrijeme za rođenje? Ova knjiga vodi male čitaoce na iskreno i duhovito putovanje kroz čudo nastanka života, dajući tople i jasne odgovore na najvažnija dječja pitanja.', 'Деликатный, остроумный и абсолютно честный путеводитель по самому первому и главному путешествию в жизни каждого малыша!', 'A gentle, witty, and wonderfully honest guide to the very first and most magical journey of every child''s life!', 'Nježan, duhovit i potpuno iskren vodič kroz prvo i najvažnije putovanje u životu svakog djeteta!', '/covers/DP-1311.webp', '#f28c74', 'important_topics', 'ru', 'available', '', '["real","funny"]', '["рождение","анатомия","семья","беременность","взросление"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('откуда-я-взялся--1312', 'DP-1312', 'Откуда я взялся?', 'Where Did I Come From?', 'Odakle sam došao?', 'Вирджини Дюмон', 'Virginie Dumont', 'Virginie Dumont', '', 'АСТ', NULL, NULL, 4, 12, 'middle', 'В возрасте 5 лет ребенок впервые задает "трудные " вопросы: "Откуда я взялся ?","Где я был, пока меня не было?". Как ответить? Рассказать про аистов и капусту, отложив серьезный разговор до школы? Или попробовать найти нужные слова, чтобы объяснить чудо зарождения жизни и появления нового человека на свет? Доступно описать сложные физиологические и психологические процессы, происходящие в организме женщины и мужчины, готовящихся стать родителями, поможет эта книга.', 'A sensitive and honest guide for young inquisitive minds answering the timeless question: "Where did I come from?" With warmth, respect, and scientific clarity, it gently explains conception, pregnancy, and birth, turning a potentially awkward conversation into a natural and loving discovery.', 'Nježan i otvoren vodič za radoznale mališane koji odgovara na vječito pitanje: „Odakle sam došao?“. Kroz tople, razumljive i pažljivo birane riječi, ova knjiga objašnjava začeće, trudnoću i rođenje, pretvarajući osjetljivu temu u prirodno i lijepo saznanje.', 'Забудьте про аистов и капусту — эта тактичная и добрая книга подскажет самые верные слова для ответа на главный детский вопрос!', 'Forget the storks and cabbage patches—this thoughtful and reassuring book helps parents answer the biggest childhood question with gentle honesty!', 'Zaboravite na rode i kupus — ova nježna i iskrena knjiga pomaže roditeljima da sa lakoćom odgovore na najvažnije dječje pitanje!', '/covers/DP-1312.webp', '#e27d60', 'important_topics', 'ru', 'available', '', '["real"]', '["growing up","family","human body","curiosity","important topics"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('я-и-мой-страх-1313', 'DP-1313', 'Я и мой страх', 'Me and My Fear', 'Ja i moj strah', 'Франческа Санна', 'Francesca Sanna', 'Francesca Sanna', '', 'МИФ', NULL, NULL, 4, 12, 'middle', 'У нашей героини есть один секрет - маленький друг по имени Страх. Он помогает девочке исследовать мир и предупреждает все опасности. Но вскоре семья девочки переезжает жить в другую страну, и Страх начинает расти. Он становится все больше и сильнее, и постепенно заполоняет все вокруг. Из-за него девочка теперь чувствует себя одинокой, не хочет ходить в новую школу, боится заговорить с одноклассниками. Но однажды она встречает мальчика, у которого тоже есть свой Страх. Девочка понимает, что она такая не одна, что бояться - это нормально, и преодолевает Страх. Эта книга поможет детям не только адаптироваться в любой незнакомой для них среде, но и расскажет, что бояться - это нормально и это свойственно каждому из нас. Главное, уметь контролировать свои страхи.', 'When a young girl moves to a new country and attends a new school, her tiny companion—Fear—suddenly grows enormous, making her feel isolated and overwhelmed. But when a classmate reaches out to share a secret, she realizes she is not the only one living with a fear. A tender, beautifully illustrated exploration of childhood anxiety, empathy, and the courage it takes to open up.', 'Kada se djevojčica preseli u novu zemlju i krene u novu školu, njen mali saputnik — Strah — odjednom poraste toliko da je potpuno izoluje od svijeta. Ipak, susret sa dječakom koji takođe ima svog malog straha pomaže joj da shvati da nije sama. Nježna i dirljiva priča o prihvatanju emocija, hrabrosti i novim počecima.', 'Тёплая и бережная история, которая напоминает: бояться — это нормально, особенно когда рядом найдётся тот, кто готов поделиться своим секретом!', 'A gentle, comforting reminder that feeling scared is completely normal—and that sharing our worries is often the very best way to make a friend.', 'Nježna i ohrabrujuća priča koja nas podsjeća da je u redu osjećati strah, posebno kada otkrijemo da u tome nikada nismo sami!', '/covers/DP-1313.webp', '#3b8584', 'important_topics', 'ru', 'available', '', '["friends","real"]', '["emotions","fear","friendship","school","relocation"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('привет-месячные-1314', 'DP-1314', 'Привет, месячные', 'Welcome to Your Period', 'Dobrodošla, menstruacijo', 'Юми Сайнс', 'Yumi Stynes, Melissa Kang', 'Yumi Stynes, Melissa Kang', '', 'Белая ворона', NULL, NULL, 4, 12, 'middle', 'Во многих семьях откровенно разговаривать о месячных не принято, и месячные считаются чем-то странным, грязным, болезненным. Но так быть не должно! В этой книге собраны советы на все случаи жизни. Из нее ты узнаешь, когда наступают месячные и как они проходят у разных людей, что такое спазмы и как с ними бороться, что делать в случае протечки и многое другое. В книге собраны вопросы и рассказы реальных подростков и взрослых, а комментирует их опытный врач. Прочитав эту книгу, ты тоже станешь настоящим экспертом в этом вопросе и сможешь консультировать своих подруг! Журналистка Юми Стайнс и практикующий врач Мелисса Канг вместе написали этот гид - если тебе надо разобраться с месячными, никакая другая книга не понадобится. Эта книга поддержит, развеселит и даст всю необходимую информацию, которая будет полезна и девочкам, и родителям подростков, и просто всем, кто хочет восполнить пробелы в своих знаниях по этому деликатному вопросу.', 'In many families, talking openly about periods is still considered taboo, awkward, or even shameful. But it doesn''t have to be that way! Written by journalist Yumi Stynes and medical doctor Melissa Kang, this frank, reassuring, and funny guide covers everything from your first period, cramps, and leak emergencies to myths, mood swings, and period products. Packed with real-life stories and medical facts, this is the ultimate handbook that answers every question you might be too shy to ask out loud.', 'U mnogim porodicama otvoreni razgovori o menstruaciji još uvijek su tabu, a sama tema često djeluje zbunjujuće ili neprijatno. Ali ne mora biti tako! Ovaj iskreni, ohrabrujući i duhoviti vodič novinarke Yumi Stynes i ljekarke Melisse Kang nudi odgovore na sva pitanja: kada menstruacija počinje, kako se nositi s grčevima, šta uraditi ako se desi nezgoda i kako izabrati prave higijenske proizvode. Uz stvarne priče tinejdžerki i stručne medicinske savjete, ovo je knjiga koja ruši mitove i pruža potpunu sigurnost.', 'Дружелюбный, честный и невероятно заботливый гид без неловкости и занудства, который превратит страх перед взрослением в уверенность и спокойствие.', 'A warm, delightfully frank, and zero-awkwardness guide that turns every period worry into body-positive confidence.', 'Topao, iskren i oslobađajući vodič bez trunke nelagode, koji strah od odrastanja pretvara u samopouzdanje i mir.', '/covers/DP-1314.webp', '#e74c5e', 'important_topics', 'ru', 'available', '', '["real","friends","funny"]', '["puberty","growing up","health","girls","body positivity"]', 1792836322701, 1792845730920);
INSERT OR REPLACE INTO books (id, code, title_ru, title_en, title_me, author_ru, author_en, author_me, illustrator, publisher, year, isbn, age_min, age_max, age_group, annotation_ru, annotation_en, annotation_me, says_ru, says_en, says_me, cover_url, dominant_color, primary_section, language, status, condition_notes, moods_json, tags_json, created_at, updated_at) VALUES ('прощайте-господин-маффин--1315', 'DP-1315', 'Прощайте, господин Маффин!', 'Goodbye, Mr. Muffin', 'Zbogom, gospodine Mafine!', 'Ульф Нильсон', 'Ulf Nilsson', 'Ulf Nilson', 'Анна-Клара Тидхольм', 'Белая ворона', NULL, NULL, 4, 12, 'middle', 'Старая морская свинка по имени Господин Маффин готовится к последнему путешествию. Он с удовольствием вспоминает вкусные огурцы, приятные поглаживания, красавицу-жену и своих пушистых детей. А еще рядом с домом Господина Маффина стоит почтовый ящичек, где иногда появляются письма от его юной хозяйки. Она пишет о своей любви и грусти и рассуждает о смерти - по-детски просто и мудро. Деликатная и целительная история для размышлений на непростые темы. В 2002 году книга получила премию имени Августа Стриндберга в номинации "Литература для детей и юношества".', 'An elderly guinea pig named Mr. Muffin looks back fondly on a life well-lived—full of crisp cucumbers, gentle head pats, a loving family, and cozy memories—as he prepares for his final journey. Next to his home sits a little mailbox filled with tender notes from his young owner, pondering love, sorrow, and farewells with childlike honesty and wisdom. A gentle, deeply comforting, and award-winning story designed to open gentle conversations on life''s most tender moments.', 'Staro morsko prase po imenu gospodin Mafin priprema se za svoje posljednje putovanje, s ljubavlju se sjećajući sočnih krastavaca, nježnih maženja i svoje voljene porodice. Pored njegove kućice stoji malo poštansko sanduče u koje stižu dirljiva pisma njegove male vlasnice o ljubavi, tuzi i rastanku. Ova nježna, nagrađivana i iscjeljujuća priča pomaže djeci i roditeljima da na topao i mudar način razgovaraju o prolaznosti i opraštanju.', 'Невероятно светлая и бережная книга, которая помогает прожить грусть и понять, что настоящая любовь и тёплые воспоминания остаются навсегда.', 'A tender, comforting embrace of a book that makes talking about farewells feel gentle, loving, and reassuringly natural.', 'Predivna, topla i duboko dirljiva priča koja pruža utjehu i uči nas kako da sačuvamo najljepše uspomene u srcu.', '/covers/DP-1315.webp', '#a67c52', 'important_topics', 'ru', 'available', '', '["animals","real","friends"]', '["loss","grief","guinea pig","empathy","growing up"]', 1792836322701, 1792845730920);
