INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'анатомикум-698'), 'Анатомикум', 'Anatomicum', 'Anatomikum', 'Дженнифер Пакстон', 'Jennifer Paxton', 'Dženifer Pakston', 'Добро пожаловать в наш «Анатомикум». Этот постоянно открытый музей готов познакомить посетителей с экспонатами, рассказывающими об удивительном строении человеческого тела. Вы увидите, как самые разные части тела — от скелета и лицевых мышц до клеток мозга, отвечающих за наши мысли, — слаженно работают вместе. Заходите к нам и совершите потрясающее путешествие по человеческому организму.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'анималиум-699'), 'Анималиум', 'Animalium', 'Animalijum', 'Дженни Брум', 'Jenny Broom', 'Dženi Brum', 'Добро пожаловать в наш «Анималиум». Этот постоянно открытый музей готов познакомить посетителей любого пола и возраста с удивительной коллекцией, включающей более 160 видов животных. Вы узнаете, как они эволюционировали, заглянете в анатомическую лабораторию и познакомитесь с разнообразнейшими местообитаниями нашей планеты… Заходите к нам и изучайте животный мир во всем его великолепии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ботаникум-700'), 'Ботаникум', 'Botanicum', 'Botanikum', 'Кэти Уиллис', 'Kathy Willis', 'Keti Vilis', 'Добро пожаловать в наш «Ботаникум». Этот постоянно открытый музей представляет посетителям коллекцию, включающую грибы, лишайники и самые разнообразные растения – от крошечных одноклеточных водорослей до гигантских секвойядендронов, от нежного лютика до хищной росянки. Вы узнаете об эволюции многих растений и приспособлениях, позволивших им выжить. Заходите к нам и изучайте удивительный мир растений во всем его великолепии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'динозавриум-701'), 'Динозавриум', 'Dinosaurium', 'Dinosaurijum', 'Лили Маррей, Кейти Скотт, Джейми Брун', 'Lily Murray, Katie Scott', 'Lili Marej, Kejti Skot', 'Добро пожаловать в наш «Динозавриум». Этот круглосуточный музей работает без выходных и перерывов на обед. Он знакомит посетителей с впечатляющей коллекцией мезозойских ящеров: от миниатюрных троодонов до гигантских брахиозавров. Вы узнаете, как эволюционировали динозавры, почему одни были покрыты перьями, а другие – чешуей. Заходите к нам и полюбуйтесь динозаврами во всем их великолепии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'океанариум-702'), 'Океанариум', 'Oceanarium', 'Okeanarijum', 'Лавдэй Триник', 'Loveday Trinick', 'Lavdej Trinik', 'Добро пожаловать в наш «Океанариум»! Этот постоянно открытый музей приглашает посетителей в путешествие по Мировому океану – уникальной экосистеме, наполненной всевозможными формами жизни. Вы увидите множество морских обитателей – от микроскопического планктона и разноцветных медуз до удивительных глубоководных рыб и огромных китов. Океан – невероятная тайна, которую нам ещё только предстоит раскрыть. Заходите в наш музей и познакомьтесь с потрясающим подводным миром.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'планетариум-703'), 'Планетариум', 'Planetarium', 'Planetarijum', 'Раман Принджа', 'Raman Prinja', 'Raman Prindža', 'Добро пожаловать в наш «Планетариум». Этот постоянно открытый музей готов познакомить посетителей с коллекцией астрономических объектов — от крошечных ледяных спутников до гигантских галактик. Экспозиция включает выполненные по научным данным картины Солнечной системы, дальнего космоса, галактических скоплений и туманностей, показывающих разнообразие и бесконечность Вселенной. Заходите к нам и прикоснитесь к тайнам космоса.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'грибы-704'), 'Грибы', 'Mushrooms', 'Gljive', '', 'Unknown', 'Nepoznati autor', 'Грибы — одни из самых удивительных обитателей нашей планеты; царство грибов поражает впечатляющими масштабами, невероятным разнообразием видов и форм. В залах музея представлена обширная коллекция, посвящённая наиболее интересным представителям грибного царства. Она включает в себя микроскопические организмы, неразличимые невооружённым глазом, трутовики и лишайники, грибы тропических лесов, грибы-гиганты, съедобные грибы и многие другие. Вы узнаете, как размножаются грибы, какую роль они играют в жизни растений, животных и человека, с кем взаимодействуют и… на кого охотятся. Заходите к нам за новыми знаниями и впечатлениями и полюбуйтесь грибами во всём их великолепии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'языки-мира-705'), 'Языки мира', 'Languages of the World', 'Jezici svijeta', '', 'Unknown', 'Nepoznati autor', 'В мире существуют тысячи языков. На некоторых говорят миллионы людей, на других — единицы. Есть языки, которые совсем исчезли и оставили загадочные следы, другие возродились. Языки свистящие, придуманные, запрещенные, жестовые — если прислушаться к этому разнообразию, нам откроется настоящее сокровище. Эта книга — путешествие по всей планете, в котором языки доведут до самых удивительных мест. Они покажут, как можно думать о мире, как разговаривать и понимать друг друга.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'а-антарктида-706'), 'А - Антарктида', 'A is for Antarctica', 'A kao Antarktik', 'Давид Бём', 'David Böhm', 'David Böhm', 'Детская книжка-картинка, написанная и проиллюстрированная чешским автором Давидом Бёмом, посвящает юных читателей в тайны ледяного континента. Среди тем — история открытия и изучения Антарктиды, особенности ее климата, флоры и фауны, хроника знаменитых экспедиций к Южному полюсу, особенности жизни ученых на полярных станциях и даже веселый комикс.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'большой-атлас-мира-в-картинках-707'), 'Большой атлас мира в картинках |', 'Big Picture Atlas', 'Veliki atlas svijeta u slikama', 'Боне Эмили', 'Emily Bone', 'Emili Boun', 'Как совершить кругосветное путешествие, не выходя из дома? Очень просто: открыть эту книгу на любой странице! Этот атлас – не просто собрание географических карт, а живой, интересный рассказ о нашей планете. Вы узнаете о самых длинных реках и самых обширных пустынях мира, самых высоких горах и самом глубоководном желобе, познакомитесь с традициями и обычаями разных народов. На картах отмечены растения и животные шести континентов, изображены памятники истории и культуры. Познавайте окружающий мир – это очень интересно.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'карты-708'), 'Карты', 'Maps', 'Mape', 'Мизельиньские', 'Aleksandra Mizielińska, Daniel Mizieliński', 'Aleksandra Mizielinska, Danijel Mizielinski', 'Географическая карта может быть скучным школьным пособием, а может стать и игрой, развивающей воображение, тренирующей память и позволяющей овладевать новыми знаниями. Рисованный атлас «Карты» польских художников Александры и Даниэля Мизелиньских можно уподобить старинным картам мира, на которых картографы помещали много полезных сведений о странах и людях, в них живущих. И с его помощью художники приглашают нас в необычное путешествие вокруг света, которое можно совершить из дома. Четыре тысячи картинок рассказывают о 41 стране: кто в ней живет, какие самые распространенные имена, какие достопримечательности — природные, архитектурные, самые распространенные и самые редкие представители флоры и фауны, обычаи и традиции, исторические персонажи, прославившие свою родину, виды спорта, национальная кухня... И еще очень много всего, что заставит вас всей семьей часами бродить по африканским пустыням, осваивать приветствие новозеландских маори или изучать арктическую фауну. Вперед, к новым открытиям! 2013 — Премия Сорсьер (Ассоциация библиотекарей Франции) 2013 — Премия Андерсена (Книжный салон в Турине, Италия)');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'транссиб-709'), 'Транссиб', 'The Trans-Siberian Railway: A Trip Across Russia', 'Transsibirska željeznica', 'Литвина Александра', 'Alexandra Litvina', 'Aleksandra Litvina', 'Цифры, исторические факты и сведения о географии, которые можно найти в учебниках, дополнили реальные истории людей, связанных с Транссибом, рассказы о любимых местах, рецепты блюд и советы, что посмотреть, которыми щедро поделились дети и взрослые. Собирали эти истории, подбирали факты, создавали панорамы и зарисовки из мегаполисов и маленьких поселков — Александра Литвина и Аня Десницкая, создатели известной книги «История старой квартиры», настоящего события на российском и международном книжном рынке, лауреаты множества российских и международных наград.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'с-востока-на-запад-710'), 'С Востока на Запад', 'From East to West', 'Od istoka do zapada', 'Марина Бабанская', 'Marina Babanskaya', 'Marina Babanskaja', 'Отправить письмо бутылочной почтой решил смотритель маяка Пётр Круглов. Он попросил каждого, кому попадёт в руки его послание, дополнить его небольшим письмом о себе: где человек живёт, как проводит время, какие традиции есть в его семье и окружении. Бутылка странствует по огромной территории России, от Владивостока до Санкт-Петербурга, оказываясь в местах, где подавляющему большинству читателей наверняка не доводилось бывать. И люди, выловившие бутылку, дополняют послание в ней своим рассказом — как им живётся в вечной мерзлоте; какие традиции есть у горных народов; почему на Урале люди даже разговаривают чуть иначе, чем в Центральной России.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'горы-мира-история-восхождений--711'), 'Горы мира. История восхождений и открытий', 'Mountains of the World: A History of Ascents and Discoveries', 'Planine svijeta: Istorija uspona i otkrića', '', 'Unknown', 'Nepoznat autor', 'На счастье непосед, авантюристов и путешественников, на Земле есть горы — от совсем невысоких до непостижимо огромных. До поры до времени люди обходили их стороной, а потом решили взойти и посмотреть, что там наверху. Так начался и длится до сих пор роман человека и гор. Перед вами книга о том, как люди впервые поднялись в Альпы, на Кавказ и в Гималаи, о покорении Эвереста и всех восьмитысячников, об опасностях, отваге и приключениях. И конечно, о любви к горам, красоте и смысле жизни. Как устроены горы? Какие флаги водружали на вершины первопроходцы? Когда в горы впервые отправились женщины? Зачем альпинистам кошки, ледорубы и кислородные баллоны? Кого и почему называют «Великим»? Ответы на эти и многие другие вопросы ты найдёшь на страницах этой удивительной книги.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вс-теч-т-великие-реки-мира-712'), 'Всё течёт: великие реки мира', 'Everything Flows: Great Rivers of the World', 'Sve teče: Velike rijeke svijeta', '', 'Volker Mehnert', 'Volker Menert', 'Какая река самая длинная в мире — Нил или Амазонка? Через какие страны протекает Дунай? Как река Колорадо проложила себе путь через скалы Большого каньона? Как Волга и Лена определили облик России? Политическая или культурная граница, торговый путь или религиозный символ — реки всегда имели для нас особое значение. В этой книге представлены 18 легендарных рек со всех пяти континентов, и мы познакомимся с разнообразной жизнью и знаменитыми достопримечательностями, которые можно обнаружить на реках и вокруг них.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'атлас-города-713'), 'Атлас города', 'City Atlas', 'Atlas gradova', 'Мартин Хааке', 'Martin Haake', 'Martin Hake', 'Чем Москва отличается от Лондона, Рио-де-Жанейро - от Токио, а Берлин и Рим - от Нью-Йорка? Какой город самый большой, и что обязательно надо сделать, если ты оказался в одной из известнейших столиц мира? "Атлас города" - иллюстрированный путеводитель, который рассказывает все о культурных достопримечательностях, знаменитостях, культовых зданиях, национальных блюдах, праздниках и традициях 30 городов мира. Среди них: Лиссабон, Барселона, Лондон, Амстердам, Париж, Рим, Берлин, Хельсинки, Осло, Копенгаген, Стокгольм, Афины, Стамбул, Прага, Будапешт, Москва, Монреаль, Торонто, Чикаго, Нью-Йорк, Сан-Франциско, Мехико, Рио-де-Жанейро, Буэнос-Айрес, Гонконг, Токио, Сеул, Мумбай и Сидней. Отправляйтесь в захватывающее кругосветное путешествие с незаменимым помощником для детей и взрослых!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'это-лондон-714'), 'Это Лондон', 'This is London', 'Ovo je London', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', 'Это Лондон. Это его неповторимые улицы, парки и скверы, известные всему миру центральные площади, музеи, памятники, здания, двухэтажные автобусы, телефонные будки... Дожди и туманы. Это жители Лондона - конечно, они не похожи на жителей других городов, у них своя манера одеваться, свой образ жизни. И есть в Лондоне такое, что иногда ускользает от глаз взрослого, но зато очень интересно ребёнку! Замечательные виды одного из самых прекрасных городов мира создал в 1959 году Мирослав Шашек. Эта и 17 других его книг-путешествий по городам и странам стали классикой детской литературы. Мирослав Шашек родился 18 ноября 1916 года в Праге, умер в 1980 году в Швейцарии. По образованию архитектор. В 1948 году эмигрировал в ФРГ, жил в Мюнхене. Работал на радио "Свободная Европа". Известный художник, автор детских книг, книжный иллюстратор. "Это Лондон" - для любопытных маленьких читателей, которые читают сами и любят, когда им читают вслух.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'это-нью-йорк-715'), 'Это Нью-Йорк', 'This is New York', 'Ovo je Njujork', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', 'Это Нью-Йорк. Один из крупнейших городов мира... Здесь самые большие магазины, здания и пробки! Мы посетим Манхэттен, Бруклин и Гарлем, увидим статую Свободы. Замечательные виды одного из самых прекрасных городов мира создал в 1959 году Мирослав Шашек. Эта и 17 других его книг-путешествий по городам и странам стали классикой детской литературы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'это-париж-716'), 'Это Париж', 'This is Paris', 'Ovo je Pariz', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', 'Это Париж. Величественные дворцы и храмы, исторические памятники, прекрасные сады, музеи, улицы… И жители города - художники, продавщицы цветов, уличные артисты и даже тысячи кошек! Пройдемся по набережной Сены, заглянем в Лувр, поднимемся на Эйфелеву башню, узнаем историю города. Замечательные виды одного из самых прекрасных городов мира создал в 1959 году Мирослав Шашек. Эта и 17 других его книг-путешествий по городам и странам стали классикой детской литературы. "Это Париж" - для любопытных маленьких читателей, которые читают сами и любят, когда им читают вслух.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'это-рим-717'), 'Это Рим', 'This is Rome', 'Ovo je Rim', 'Мирослав Шашек', 'Miroslav Šašek', 'Miroslav Šašek', 'Мирослав Шашек ведет нас в незабываемое путешествие по Риму. Его иллюстрации - неожиданные, забавные и яркие покажут нам Рим древний и Рим современный - фонтаны, плещущие под ярким голубым небом, Римский Форум, Испанская лестница, древняя Аппиева дорога, самый знаменитый собор в мире - Базилика Святого Петра. Мы увидим апельсины и лимоны, созревающие в городских двориках, пальмы, растущие на крышах домов. Увидим статуи и мотоциклы. И жизнерадостных римлян, которые живут в "вечном городе". Эта книга как для тех, кто уже бросил монету в фонтан Треви, так и для тех, кто не бросал. Для юных и взрослых читателей, путешествующих по дорогам и страницам книг. Мирослав Шашек создал 18 книг-путешествий по миру, они получили множество наград и стали детской классикой. На русском языке в серии путешествий с Мирославом Шашеком выходили книги: Это Париж, Это Лондон, Это Нью-Йорк, Это Венеция.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'флаги-мира-718'), 'Флаги мира', 'Flags of the World', 'Zastave svijeta', 'Сильви Беднар', 'Sylvie Bednar', 'Silvi Bednar', 'У каждого флага своя история. Откуда взялся знаменитый канадский кленовый листок? Как называется единственная в мире страна, изобразившая на флаге свои географические очертания? Какая латиноамериканская страна является обладательницей уникального двустороннего флага? Давайте быстрее нырнём в этот мир разноцветных полос и причудливых символов. Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайны-глобуса-блау-719'), 'Тайны глобуса Блау', 'Secrets of the Blaeu Globe', 'Tajne Blaeuvog globusa', 'Мария Пономаренко', 'Maria Ponomarenko', 'Marija Ponomarenko', 'Эта книга посвящена непростой и полной тайн судьбе огромного 300-летнего глобуса. Прежде чем оказаться в одном из залов Государственного исторического музея, этот медный шар, на который нанесена карта мира с изображением диковинных животных и морских сражений, преодолел около 4 тысяч километров по морю и заснеженным российским полям, не раз переезжал из Москвы в Санкт-Петербург, подвергался варварскому обращению и бережной реставрации. Автор книги предлагает читателю вместе поломать голову над загадками, связанными с этим громадным молчаливым экспонатом. Кто был первым владельцем глобуса? Почему он оказался в России и как его к нам везли? Почему глобус был важным оружием в торговой борьбе разных стран? Наконец, что шуршит внутри глобуса? Книга, где все вертится вокруг одного медного шара, иллюстрирована множеством старинных карт, фотографиями удивительных деталей глобуса, которые обычным посетителям рассмотреть не удается.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'фермерские-рынки-мира-720'), 'Фермерские рынки мира', 'Farmers'' Markets of the World', 'Pijace svijeta', 'Мария Бахарева', 'Maria Bakhareva', 'Marija Bahareva', 'Доводилось ли вам побывать на настоящем фермерском рынке, куда идёшь с утра пораньше с сумкой-тележкой, чтобы успеть купить самые свежие продукты? А что насчёт рынков в других странах мира? Взять, например, Израиль: зимой там сезон клубники, и можно хоть каждый день лакомиться сладкими ягодами! На тайском рынке можно найти самые экзотические фрукты, в том числе дуриан, который запрещено вывозить из Таиланда. Загляни на рынок в Эфиопии и попробуй местную выпечку самбусу — пальчики оближешь! На рынке в Сан-Франциско продаётся мороженое с самыми невероятными вкусами — «Арахисовая паста с шоколадным печеньем» или «Клубника с засахаренным халапеньо». Открывай книгу и отправляйся в кругосветное гастрономическое путешествие по 24 фермерским рынкам в 12 странах мира — от Европы до Африки. Ты узнаешь, как выглядят рынки в разных уголках планеты и что на них можно купить. А ещё тебя ждут увлекательные квесты на каждом из рынков и рецепты национальных блюд.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хлеб-вкус-мира-721'), 'Хлеб. Вкус мира', 'Bread: The Taste of the World', 'Hljeb: Ukus svijeta', 'Бахарева Мария', 'Maria Bakhareva', 'Marija Bahareva', 'Скажи, какой хлеб любят у тебя дома, и я угадаю, откуда ты родом. А пробовал ли ты когда-нибудь итальянскую фокаччу, индийскую булочку пав, японский хлеб сёкупан и маорийский картофельный хлеб рэвену? Всего четыре ингредиента — мука, вода, соль и дрожжи. А хлеб получается разный. Хлеб ценят и любят везде. Давай отправимся в кругосветное хлебное путешествие. Побываем на разных континентах, в разных странах, городах и даже на полярной станции. А по дороге заглянем в местные булочные и пекарни и узнаем, как готовят хлеб по всему миру. Тебя ждут увлекательные квесты и национальные рецепты. Что может быть вкуснее свежего хлеба?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'смотри-байкал-книга-путешестви-722'), 'Смотри: Байкал! Книга-путешествие', 'Look: Baikal! A Journey Book', 'Pogledaj: Bajkal! Knjiga-putovanje', 'Ольга Патрушева', 'Olga Patrusheva', 'Olga Patruševa', 'Величественный и неповторимый Байкал, красивейшее и самое глубокое озеро в мире, — достояние всей планеты. Но для каждого из нас Байкал — свой, особенный. Хочешь и ты узнать свой Байкал?Величественный и неповторимый Байкал, красивейшее и самое глубокое озеро в мире, — достояние всей планеты. Но для каждого из нас Байкал — свой, особенный. Хочешь и ты узнать свой Байкал? Тогда тебе нужен хороший проводник. Уникальное книжное путешествие, в которое ты отправляешься, подготовит тебя к встрече с настоящим Байкалом: мы собрали самые разные факты — об истории озера, его характере и обитателях, о маршрутах разной степени сложности — и постарались рассказать о проблемах, которые стоят перед Байкалом прямо сейчас. Их столько, что огромному древнему озеру очень нужна сегодня и твоя помощь. И мы подскажем тебе, как помогать Байкалу и участвовать в его жизни из любой точки Земли. Аня и Варя Кендель — российские художницы, сёстры-близнецы, которые очень любят путешествовать и вместе делают иллюстрации для книг. В 2021 году Аня пять месяцев провела на берегу Байкала, а за два года до этого прошла на байдарке 400 километров вдоль западного берега. В том походе и родилась идея сделать книгу о Байкале.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'смотри-урал-книга-путешествие-723'), 'Смотри: Урал! Книга-путешествие', 'Look: The Urals! A Journey Book', 'Pogledaj: Ural! Knjiga-putovanje', 'Аня и Вапя Кендель, Олег Чегодаев', 'Anya Kendel, Varya Kendel, Oleg Chegodaev', 'Anja Kendel, Varja Kendel, Oleg Čegodajev', 'Уральские горы, каменный рубеж между Европой и Азией, — природная сокровищница России. Многоликий, протянувшийся на тысячи километров с юга на север, Урал каждому открывается по-своему. Хочешь и ты узнать свой Урал? Тогда тебе нужен проводник. Захватывающее книжное путешествие, в которое ты отправляешься, подготовит тебя к встрече с настоящим Уралом. Ты многое узнаешь об истории горного хребта, его природных памятниках и заповедных территориях, познакомишься с обитателями Урала, местными легендами и преданиями. Пройдёшь разнотравные степи, широколиственные леса, таёжные буреломы и бескрайние тундры по следам опытного путешественника, что оставил подсказки — маршруты по Уралу разной степени сложности, правила поведения в дикой природе и рекомендации для подготовки к твоему первому походу в горы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-растут-овощи-724'), 'Как растут овощи', 'How Does My Garden Grow?', 'Kako raste povrće', 'Герда Мюллер', 'Gerda Muller', 'Gerda Miler', 'Огород - это волшебное место, где дети, выросшие в городе, могут наблюдать за жизнью и ростом растений. Девочка Таня, героиня этой истории, поехала на каникулы в деревню к бабушке и дедушке, которые учат её сажать и выращивать овощи, обращаться с садовыми инструментами и собирать урожай. Таня узнаёт много интересного о тех растениях, плоды которых она прежде видела только на полках магазинов: как рождается и растет зеленый горошек, какую роль в жизни растений играют насекомые и птицы, как приготовить вкусный салат и как вырастить хрустящую редиску и сочную зелень в собственной квартире, устроив небольшой огород на балконе или подоконнике.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дары-природы-725'), 'Дары природы', 'Gifts of Nature: An Illustrated Guide', 'Darovi prirode', 'Аладжиди, Чукриэль', 'Virginie Aladjidi, Emmanuelle Tchoukriel', 'Virginie Aladjidi, Emmanuelle Tchoukriel', 'Эта увлекательная энциклопедия познакомит вас с фруктами, овощами, различными плодами и съедобными грибами. Рассматривайте удивительные реалистичные иллюстрации в классическом стиле, читайте об интересных фактах и познавайте чудесный мир, окружающий нас. Гид для родителей: Новая книга будет интересна каждому ребенку и родителям, а также бабушкам и дедушкам, сестрам и братьям, ведь путешествовать и познавать мир увлекательно для каждого! Иллюстрированная энциклопедия адресована детям от 6 лет и она станет прекрасным помощником в школе. Ее можно просто читать и рассматривать иллюстрации, а кроме этого готовить доклады и рефераты, и планировать летний отпуск по ней тоже приветствуется. Раскрывая "Дары природы. Иллюстрированный справочник" вы попадаете в интересный мир съедобных растений, фруктов, различными плодами и съедобных грибов и многого другого.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'насекомые-726'), 'Насекомые', 'Insects', 'Insekti', 'Аладжиди, Чукриэль', 'Virginie Aladjidi, Emmanuelle Tchoukriel', 'Virginie Aladjidi, Emmanuelle Tchoukriel', 'Почувствуйте себя великим естесствоиспытателем! Вы познакомитесь с насекомыми, составляющими 80% животного мира, - от хорошо знакомых бабочек и ос до экзотических жуков-голиафов и скарабеев. Рассматривайте удивительные реалистичные иллюстрации в классическом стиле, читайте об интересных фактах и познавайте чудесный мир, окружающий нас.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-лесу-727'), 'В лесу', 'In the Forest', 'U šumi', 'Петр Багин', 'Pyotr Bagin', 'Petar Bagin', 'Разворотные иллюстрации, посвящённые каждому месяцу в году, не просто выразительны и живописны, они еще и абсолютно точны с зоологической точки зрения. За зимой приходит весна, вслед за весной - лето и осень… Вокруг маленького читателя ходят медведи, олени, лоси, белки, лисы, зайчата, рыси. Птицы строят гнезда, звери роют норы. Птенцы выбираются из яиц, головастики - из икринок, зверята сосут материнское молоко. Для дошкольного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'моя-книга-бабочек-728'), 'Моя книга бабочек', 'My Butterfly Book', 'Moja knjiga leptira', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'В книге доступным и увлекательным языком описаны более тридцати видов бабочек, распространенных в России и других странах мира. Благодаря подробным и точным иллюстрациям книгу можно использовать как определитель бабочек. Издание адресовано широкому кругу читателей. Для младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мышиная-книга-729'), 'Мышиная книга', 'The Mouse Book', 'Mišja knjiga', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'В этой книге речь пойдет о самых важных животных на свете - полевках и мышах. Мы заглянем в их мир и увидим их в родной стихии. Встретим красивую красно-серую полевку, таинственного лесного лемминга, самую обычную рыжую полевку и многих, многих других! Надеемся, что эта книга поможет тебе по-другому взглянуть на жизнь мелких зверьков, которые незаметно живут рядом с нами. Шведский писатель Стефан Каста хорошо известен во всём мире, как автор подростковых романов, которые принесли ему множество международных наград. Однако его творчество не ограничивается только ими. Одна из наиболее известных серий Стефана о природе - книги-путеводители по полям и лесам с муравьишкой Софи. "Белая ворона" выпустила на русском языке все пять книг серии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-мире-жуков-730'), 'В мире жуков', 'The Beetle Book', 'U svijetu buba', 'Стив Дженкинс', 'Steve Jenkins', 'Stiv Dženkins', 'В своей необычной книге знаменитый иллюстратор Стив Дженкинс демонстрирует самых разных жуков во всей красе и знакомит маленьких читателей с удивительными фактами из их жизни. Как устроены насекомые, как они растут, чем питаются, где живут, как общаются между собой? Ваш ребенок найдет ответы на эти и многие другие вопросы во время увлекательного путешествия в фантастический мир жуков.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'софи-в-мире-деревьев-731'), 'Софи в мире деревьев', 'Sophie in the World of Trees', 'Sofi u svijetu drveća', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Знаешь ли ты, из какого дерева сделана бумага, на которой напечатана эта книжка? А из каких деревьев делают музыкальные инструменты и военные корабли, зубочистки и уголь для рисования, палочки для мороженого и лыжи? Сколько лет самому старому дубу России, и почему дубы растут поодиночке? Почему кленовые листья осенью становятся разноцветными? Муравьишка Софи приглашает тебя в удивительную экспедицию. Вместе с ней мы узнаем много интересного о жизни деревьев и цветов, которые мы встречаем каждый день. Для детей дошкольного и младшего школьного возраста');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'софи-в-мире-грибов-732'), 'Софи в мире грибов', 'Sophie in the Mushroom Forest', 'Sofi u svijetu gljiva', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Хочешь больше узнать про грибы? Тогда эта книга для тебя! В ней мы не только расскажем о грибах, но и постараемся раскрыть тебе душу леса. Мы, авторы этой книги, думаем, что лисички, рыжики, сыроежки и белые - не просто грибы. У них есть своя тайна! Во всяком случае, нам так кажется. Мы расскажем тебе о грибах, которые растут в соседнем лесу. Со временем ты тоже научишься их узнавать, полюбишь собирать и будешь с удовольствием заниматься этим в свободное время. Для младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'софи-в-мире-ягод-733'), 'Софи в мире ягод', 'Sophie in the World of Berries', 'Sofi u svijetu bobica', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Умеешь ли ты отличать дикую малину от костяники? Знаешь ли, что ягоды можно собирать круглый год, даже зимой? А из какой ягоды получается самое вкусное желе? В этой книге мы расскажем о том, что за ягоды встречаются в наших лесах, научим тебя различать даже такие малоизвестные ягоды, как куманика, княженика и водяника. Ты узнаешь, какие ягоды ядовиты, а какие съедобны, как их лучше собирать и что из них можно приготовить. И главное: ты снова встретишься с муравьишкой Софи и попадешь на большой Ягодный Пир! Для младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'цветочная-книга-шмеля-734'), 'Цветочная книга шмеля', 'The Bumblebee''s Flower Book', 'Bumbarova knjiga o cvijeću', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Многое в природе скрыто от наших глаз, и многое нам непонятно. Но случайностей в ней очень мало. Даже насекомые и те не кружат просто так. Подобно миру людей, их мир продуман и упорядочен. В этой книге мы расскажем вам правдивую сказку о жизни шмелей. Знаете ли вы, что на цветах для шмелей нанесены особые дорожные знаки? А что шмели обожают синие и жёлтые цветы, слышали? А что, летая, они оставляют в воздухе невидимый ароматный след? Раздел ботаники, изучающий цветение и опыление растений, называется «антэкология», и это очень увлекательная наука! Возможно, для кого-то эта книга станет первым определителем растений.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '-удивительные-летучие-мыши--735'), '«Удивительные летучие мыши»', 'Fantastic Bats', 'Čudesni slijepi miševi', 'Мартин Эмтенес', 'Martin Emtenäs', 'Martin Emtenes', 'Небольшая, но познавательная книга ученого-зоолога Мартина Эмтенеса с иллюстрациями Свена Нурдквиста. Летучих мышей принято опасаться, вокруг них сложилось много мифов и легенд. Из этой книги маленький читатель узнает интересные и достоверные факты о летучих мышах и перестанет их бояться (если когда-нибудь боялся). Книга поможет снять страх перед летучими мышами и узнать этих животных получше. Иллюстрации всемирно известного шведского художника Свена Нурдквиста. Автор — ученый и научный журналист.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'круглый-год-736'), 'Круглый год', 'All Year Round', 'Kroz cijelu godinu', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', 'Замечательный шведский путеводитель по лесам, полям и берегам. Проводником в мире животных и растений выступает девочка Майя - она наблюдает за природой Круглый год и отлично знает, чем отличается лесная мышь от мыши-полевки, почему спящие птицы не падают с веток, где зимуют пчелы, как поступают зайцы со своим пометом и как можно сделать подводный бинокль, поймать окуня и приготовить клевер с кефиром. Для младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'все-о-цветущих-растениях-737'), 'Все о цветущих растениях', 'All About Flowering Plants', 'Sve o cvjetnicama', '', 'Unknown', 'Nepoznat autor', 'Около 450 цветковых растений из всех уголков мира с научными латинскими названиями. Сотни великолепных иллюстраций, сделанных специально для этого издания. Подробные иллюстрированные справки об отдельных растениях с описанием их биологических особенностей. Роскошные и скромные, известные и редкие - цветковые растения покоряют наши сердца, украшают наши квартиры, сады и парки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'огород-на-подоконнике-738'), 'Огород на подоконнике', 'Garden on the Windowsill', 'Bašta na prozorskoj dasci', 'Клара Лидстрем', 'Klara Lidström', 'Klara Lidstrem', 'Во все времена людей восхищало все, что растет и зеленеет. Авторы этой книги не только рассказывают, как выращивать съедобные и декоративные растения, но и описывают всякие сумасшедшие эксперименты - например, как "прорастить" заячий помет или как сделать смешные прически из травы. Иллюстрации и пошаговые инструкции помогут детям проделать все эксперименты самостоятельно, почти без помощи взрослых. Для работы не потребуется ни дорогих материалов, ни сложных инструментов. И места надо совсем немного - для разведения этих растений достаточно подоконника, балкона или грядки на даче. Другими словами, это книжка для всех!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мой-первый-огород-739'), 'Мой первый огород', 'My First Garden', 'Moja prva bašta', 'Белла Линде', 'Bella Linde', 'Bela Linde', 'Любишь копаться в земле? Хочешь вырастить свой урожай? Отлично! Ты на верном пути и скоро поймешь, это проще простого! Тебя ждут удивительные открытия, ведь огород - самое интересное, почти волшебное место на даче. Ты только представь: закапываешь в землю крошечные семечки и клубни, а из них вырастает самая настоящая еда. Будет огород большим или маленьким - решать тебе. Можешь устроить его на грядках под открытым небом, в ящиках или цветочных горшках. Тебе понадобятся: земля, семена, рассада и несколько картофелин - и, разумеется, немного терпения. Все, что нужно, - это чуть-чуть поливать, удобрять, пропалывать, ждать и наблюдать.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'живая-природа-за-городом-740'), 'Живая природа за городом', 'Wildlife in the Countryside', 'Živi svijet u prirodi', 'Кэролин Пелиссье, Аладжиди, Чукриэль', 'Caroline Pellissier, Virginie Aladjidi, Emmanuelle Tchoukriel', 'Karolin Pelisje, Viržini Aladžidi, Emanuel Čukrijel', 'Что может быть лучше прогулки за город? Смотри, сколько цветов на лугу! Как они называются? А вот ползет улитка: зачем ей нужна раковинка? Слышишь, как громко квакают лягушки: почему они селятся рядом с водой? Видишь, ежик спешит в лес: какой домик он готовит себе к зиме? Книга познакомит ребенка с удивительным миром природы и задаст немало загадок. Ответы ребенок узнает, отогнув странички-клапаны. Прекрасные натуралистичные иллюстрации Эммануэль Чукриэль покажут красоту природы. Не удивляйтесь, если ребенок вдруг предложит вам отправиться за город.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'горячие-факты-про-лед-741'), 'Горячие факты про лед', 'Hot Facts About Ice', 'Vruće činjenice o ledu', 'Лена Шеберг', 'Lena Sjöberg', 'Lena Šeberg', 'Все знают, что лед - это замерзшая вода, он холодный, а в тепле тает. Но со льдом связана еще куча интересных вещей! Например, когда придумали холодильник? Почему лед мычит как корова? Как замерзает текучая вода? Какие животные зимуют во льду? И кто он такой - таинственный Ледяной Человек? Эта занимательная книга и ее автор, художник Лена Шёберг в 2009 году победили на шведском конкурсе научно-популярных изданий. В 2014 году в "Самокате" вышла другая познавательная книга Лены Шёберг "Крутые факты о яйцах".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'крутые-факты-о-яйцах-742'), 'Крутые факты о яйцах', 'Cool Facts About Eggs', 'Nevjerovatne činjenice o jajima', 'Лена Шеберг', 'Lena Sjöberg', 'Lena Šeberg', 'Познавательная книга не только для школьников, но и взрослых — об одной из двух частей известной дилеммы о курице и яйце. Хотя и курице, и другим птицам в книге тоже уделено немало внимания. Что такое яйцо, что происходит внутри него, у каких живых существ они встречаются, для чего нужны, что символизирует яйцо в разных культурах, какие есть традиции и приметы, и многие другие «крутые» сведения о яйцах.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'трогательные-факты-о-сердце-743'), 'Трогательные факты о сердце', 'Touching Facts About the Heart', 'Dirljive činjenice o srcu', 'Лена Шеберг', 'Lena Sjöberg', 'Lena Šeberg', 'Сердце — это самая важная мышца в нашего тела. День и ночь оно бьётся в груди, один удар в секунду, всю жизнь. Нет другой части тела, которая была бы так популярна, как сердце. Оно встречается повсюду: в песнях, стихах, искусстве и рекламе. И, конечно же, в нашей речи. Сердце может открываться и закрываться, может упасть, уйти в пятки, разбиться или пылать. У человека бывает разное сердце: ледяное, чёрствое, каменное, золотое и даже сердце льва. Слушать своё сердце — значит уметь сделать правильный выбор, даже если это порой очень трудно. В нашем сердце живут разные чувства: печаль, радость, тревога, любовь. Если любишь кого-то по-настоящему, сердце даёт тебе это понять. Знаешь ли ты, что сердце голубого кита размером с автомобиль? Или что твоё сердце такое же уникальное, как твои отпечатки пальцев? Почему кровеносные сосуды голубые, если кровь красная? Сколько сердец у дождевого червя? И что делает сердце на двери уличного туалета? В сердце столько всего сокрыто! Давайте вместе отправимся в самую глубину сердца.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'календарь-линнеи-744'), 'Календарь Линнеи', 'Linnea''s Almanac', 'Linejin kalendar', 'Лена Андерсон, Кристина Бьорк', 'Christina Björk, Lena Anderson', 'Kristina Bjork, Lena Anderson', '"Линнея - так меня назвали в честь маленького розового лесного цветочка. Но если я и цветок, то городской: я ведь живу в центре города. Впрочем, я люблю цветы, листья и вообще все живое". Некоторым кажется, будто в городе природы не существует, но это совсем не так. Линнея расскажет нам много интересного о том, что происходит с городской природой в разные времена года: каких птиц можно повстречать на улице, есть ли жизнь под снегом, как устроить маленький огородик прямо у себя во дворе. Впервые Линнея появилась на детской страничке популярной шведской газеты Dagens Nyheter в 1976 году. Кристина Бьорк и Лена Андерсон придумывали небольшие истории о девочке, которая любит растения и цветы. Рубрика стала очень популярной, и ее авторам даже предложили вести детскую телевизионную передачу о садоводстве. Книга была впервые издана в Швеции в 1982 году. Для младшего и среднего школьного возраста');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'электрические-рыбы-745'), 'Электрические рыбы', 'Electric Fish', 'Električne ribe', 'Эрик Харви-Жирар', 'Éric Harvey-Girard', 'Erik Harvi-Žirar', 'Осторожно! Под обложкой этой книги живут электрические скаты, угри, сомы и другие животные, использующие электрическую энергию для охоты, обороны или ориентации в пространстве. Вы узнаете, где можно встретить этих удивительных и порой опасных существ, как они устроены и какой след оставили в истории человечества. Книга завоевала Гран-при конкурсов Lux и Grafika канадского агентства Infopresse за иллюстрации и графический дизайн. Попала в шорт-лист премии Хьюберта-Ривза, вручающейся научно-популярным книгам для детей и подростков. Для среднего и старшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'анатомия-океана-746'), 'Анатомия океана', 'Ocean Anatomy', 'Anatomija okeana', 'Джулия Ротман', 'Julia Rothman', 'Džulija Rotman', 'Вас ждут настоящие приключения в этом красочном кругосветном туре по океанам планеты! Исследуйте коралловые рифы, странствуйте по полярным морям и погружайтесь в глубины, чтобы познакомиться с их необычными обитателями. Восхитительные рисунки Джулии Ротман, сочетающие искусство и науку, отражают множество увлекательных аспектов жизни на поверхности моря и под его волнами.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чарльз-дарвин-происхождение-ви-747'), 'Чарльз Дарвин происхождение видов', 'Charles Darwin''s On the Origin of Species', 'Čarls Darvin: O porijeklu vrsta', '', 'Sabina Radeva, Charles Darwin', 'Sabina Radeva, Čarls Darvin', 'В 1859 г. Чарлз Дарвин, английский натуралист и биолог, написал книгу «Происхождение видов», в которой объяснил процесс эволюции различных видов животных. Идеи Дарвина актуальны до сих пор, и благодаря иллюстратору Сабине Радевой теперь доступны и юным читателям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'секреты-кошек-как-понять-свою--748'), 'Секреты кошек Как понять свою кошку и подружиться с ней', 'Cat Secrets: How to Understand Your Cat and Become Friends', 'Tajne mačaka: Kako razumjeti svoju mačku i sprijateljiti se s njom', 'Саша Рауш', 'Sasha Rausch', 'Saša Rauš', 'Все любят кошек (ну, или почти все). А вот любят ли кошки нас? Как им живется с людьми? Эта книга — не просто детская энциклопедия, это уникальный путеводитель по миру наших любимых питомцев. Автор книги — зоопсихолог Саша Рауш — отвечает на самые распространенные детские вопросы о кошках, их анатомии и повадках. Но особое внимание автор уделяет психологии животного. Как понять, что кошке плохо? Как научиться читать сигналы ее тела? Почему нельзя играть с кошкой лазерной указкой? Почему кошки любят забираться в коробки и ящики? Правда ли, что они умеют мстить? Узнав ответы на эти и многие другие вопросы, вы точно сможете подружиться со своим питомцем.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'невероятно-опасная-слизь-ледян-749'), 'Невероятно! Опасная слизь, ледяные мышки, съедобные камни и еще 95 историй о мире вокруг нас', 'Incredible! Dangerous Slime, Glacier Mice, Edible Stones, and 95 More Stories About the World Around Us', 'Nevjerovatno! Opasna sluz, ledeni miševi, jestivo kamenje i još 95 priča o svijetu oko nas', 'Ася Ванякина Настя Троян', 'Asya Vanyakina, Nastya Troyan', 'Asja Vanjakina, Nastja Trojan', 'Каждый день ученые по всему миру совершают удивительные открытия. Они узнают новые факты о суперспособностях животных и растений, выясняют захватывающие подробности об истории Вселенной. Чаще всего все эти истории остаются на страницах научных журналов. А жаль — ведь детям и родителям это тоже интересно!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мой-гербарий-волшебные-цветы-750'), 'Мой гербарий. Волшебные цветы', 'My Herbarium: Magical Flowers', 'Moj herbarijum: Čarobno cvijeće', 'Стефани Циск', 'Stephanie Zisk', 'Stefani Zisk', 'Эта книга посвящена 16 садовым растениям - про каждое из них ребенок узнает много интересного. Точные рисунки, сделанные художником с натуры, помогут легко найти и распознать эти растения в саду и на даче. Книга - увлекательное подспорье в учебе. Если в школе задали на лето сделать гербарий, скучное задание учителя станет волшебным! Советы по сбору и высушиванию растений пригодятся для создания собственного гербария. Весело и доступно книга рассказывает, с чего начать, как работать и на что обращать внимание при сборе и засушивании растений.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мой-лесной-гербарий-751'), 'Мой лесной гербарий', 'My Forest Herbarium', 'Moj šumski herbarijum', 'Анна Томас-Белли', 'Anne Thomas-Belli', 'Ana Tomas-Beli', 'Берёза, липа, клён, ясень, пихта, сосна, лиственница - как не запутаться малышу в таком разнообразии деревьев? Как определить, какие растения, грибы и ягоды в лесу ядовиты, а какие безопасны? С помощью этого познавательного альбома-гербария ваш ребёнок сделает свои первые открытия в мире природы! Из этой книги он узнает массу полезной информации о лесе: кто там живёт и что растёт, чем деревья отличаются друг от друга, а также как связаны между собой все части удивительной системы под названием "лес". А прекрасная коллекция листьев и семян будет долгие годы напоминать вам и вашему ребёнку о совместных прогулках! Для детей младше 6 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'деревья-752'), 'Деревья', 'Trees', 'Drveće', 'Камилла де ла Бедуайер', 'Camilla de la Bédoyère', 'Camilla de la Bédoyère', 'Эта книга рассказывает о лиственных и хвойных Деревьях. Благодаря наглядным иллюстрациям и увлекательным текстам читатель научится распознавать разные виды деревьев, растущих в парках, лесах и садах. Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ветер-753'), 'Ветер', 'Wind', 'Vjetar', '', 'Anna Skowrońska', 'Anna Skovronska', 'Как объяснить ребенку то, что нельзя увидеть и потрогать? С помощью книги отправиться в необыкновенное путешествие! Автор доступным языком рассказала практически обо всем, что связано с ветром, а команда дизайнеров красочно и с юмором проиллюстрировала даже самые сложные темы. Где рождается ветер и как превратить его в электричество? Есть ли ветер в космосе?Чем он полезен животным и растениям? Что такое эффект Кориолиса? Стоит ли знакомиться с Дорианом и Катриной, если они — циклоны? Отличное дополнение к урокам окружающего мира. Книга номинирована на премию IBBY «Книга года 2020» в категории «иллюстрации» и премию имени Фердинанда Великолепного в категории «лучшая детская книга». Большой формат. Доступно и наглядно обо всем, что связано с ветром.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-работает-маяк--754'), 'Как работает маяк?', 'How Does a Lighthouse Work?', 'Kako radi svjetionik?', 'Роман Беляев', 'Roman Belyaev', 'Roman Beljajev', 'Маяки — одни из самых древних инженерных сооружений на земле. За многие тысячелетия, что маяки помогают кораблям преодолевать опасности и находить правильный путь в море, они из архитектурных сооружений превратились в настоящие символы надежды. О маяках пишут стихи, песни, их рисуют художники. И все, взрослые и дети, мечтают побывать хотя бы раз на настоящем маяке, чтобы узнать, как он работает. Художник и дизайнер Роман Беляев, с детства неравнодушный к разным особенным инженерным сооружениям, придумал и создал удивительную серию про самые интересные изобретения человека в области инженерного строительства. Книга «Как работает маяк» открывает серию, в которую войдут позже истории мостов, мельниц и других необыкновенных сооружений.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'история-велосипеда-быстрые-ног-755'), 'История велосипеда. Быстрые ноги', 'The History of the Bicycle: Swift Feet', 'Istorija bicikla: Brze noge', 'Фомин Владимир, Попова Виктория', 'Vladimir Fomin, Viktoriya Popova', 'Vladimir Fomin, Viktorija Popova', 'С велосипедом многие из нас знакомы с детства. На нем ездят на работу и возят грузы, ставят рекорды и совершают кругосветные путешествия. Велосипедиста можно встретить практически везде. В некоторых странах велосипедов больше, чем людей. Он настолько привычен, что мы редко задумываемся о том, как и когда он был изобретен. Между тем это сравнительно недавнее изобретение — хорошая иллюстрация технологического прогресса последних столетий и в какой-то степени один из двигателей этого прогресса. Внешне простой, велосипед собрал в себе самые передовые технические достижения — от вулканизированной резины и шарикового подшипника до углепластика и компьютерного моделирования аэродинамики. Каждый раз, глядя на велосипед, мы восхищаемся его изящной простотой, за которой, если присмотреться, видны плоды трудов огромного количества людей. В этой книге приводится краткий, но яркий рассказ об истории велосипеда, его эволюции, влиянии на общество и основных элементах его конструкции. История велосипеда — это рассказ о самых передовых достижениях техники, о революции в умах и изменении облика городов.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'book-756'), '', 'The History of the Telephone', 'Istorija telefona', '', 'Unknown', 'Nepoznati autor', '«Забыл дома телефон» сегодня звучит как приговор. В смартфонах сосредоточена вся наша жизнь. Вызвать такси, расплатиться в магазине, послушать любимую музыку, почитать новости и, конечно, договориться о встрече – все это можно сделать нажатием пары кнопок. Трудно поверить, но таким телефон был не всегда. Еще каких-нибудь двадцать лет назад по мобильному телефону можно было только разговаривать и обмениваться короткими сообщениями. Пятьдесят лет назад домашний (стационарный) телефон был единственным средством связи, но и он стоял не в каждой квартире, и приходилось бегать к таксофону в соседний квартал. А было время, когда люди жили вообще без телефона. Как же тогда они общались друг с другом? И кто придумал устройства, передающие звук? В этой книге история средств связи от Древнего Рима до наших дней. Она ставит перед читателями множество интересных вопросов, благодаря которым можно наблюдать, как в диалоге между учёными разных стран и эпох развивалась наука и техника. Какие изобретения прошлого лежат в основе современной техники? Как помогли телеграфу «точки» и «тире»? Зачем телефонной трубке угольный порошок? Что изменилось благодаря радио? И как удалось перейти от аналога к цифре? А ещё из «Истории телефона» вы узнаете про секретный семафор Наполеона, радио на борту «Титаника», кабель на дне океана и взлом телефонной сети с помощью свистульки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кибер-без-опасности-757'), 'Кибер без опасности', 'Cyber Without Danger', 'Sajber bez opasnosti', 'Юрий Тихоглаз', 'Yuri Tikhoglaz', 'Jurij Tihoglaz', '«Шпион, который всегда с тобой», — так называют смартфон. Действительно, в умелых руках злонамеренного человека твой телефон и компьютер могут превратиться в мощную угрозу твоей личной безопасности. К счастью, риск можно сократить, если знать, откуда может прийти угроза, и соблюдать определенные правила. Автор этой книги — специалист в области компьютерной криминалистики — рассказывает о том, кто такие хакеры и зачем им разноцветные шляпы, приводит примеры известных хакеров, описывает основные угрозы, с которыми может столкнуться любой обладатель мобильного телефона или аккаунта в социальной сети. Но главное — он говорит о том, какие конкретные шаги нужно предпринять и какие правила соблюдать, чтобы не оказаться объектом высмеивания в Сети, чтобы не лишиться доступа к собственной электронной почте или денег с банковской карточки. Прочитав эту книгу, начинающий компьютерный пользователь сможет обезопасить себя. А еще из книги можно узнать, что хакеры — не обязательно злодеи, а также чем занимаются компьютерные криминалисты.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тысяча-лиц-энергии-758'), 'Тысяча лиц энергии', 'A Thousand Faces of Energy', 'Hiljadu lica energije', 'Роман Фишман', 'Roman Fishman', 'Roman Fišman', 'Энергии трудно дать определение. Это не вещество, не субстанция, не жидкость и не газ. Но что бы мы ни делали, мы постоянно ее расходуем. Причем не только тогда, когда включаем компьютер или едем на автомобиле, но и когда думаем или просто лежим на диване. Поэтому вопрос, откуда энергию взять, — вечный. Но кроме этого вопроса, возникает и множество других. Откуда берется электричество и как попадает к нам в дом? Можно ли жить без проводов? Как использовать энергию молнии? Почему качели качаются, а рогатки еще двести лет назад просто не существовали? Если тебе интересно об этом узнать — эта книга для тебя. И помни, вопросы — тот самый шаг, с которого начинается путь науки. Книга «Тысяча лиц энергии» выпущена при поддержке нашего постоянного партнера — Политехнического музея.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-приготовить-пирог-из-цифр-759'), 'Как приготовить пирог из цифр', 'How to Bake a Pie of Numbers', 'Kako napraviti pitu od brojeva', 'Наталья Крупенина', 'Natalia Krupenina', 'Natalija Krupenjina', 'Что такое информация и чем она отличается от данных? Как благодаря данным учёные совершают открытия, а врачи ставят диагнозы? Как сайты решают, какой мультфильм нам посоветовать? И какое отношение ко всему этому имеют пироги, облака и водопады? Наконец-то появилась книга, в которой об информации и данных рассказывается интересно и просто — так, что будет понятно и детям и взрослым.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-несъедобное-становится-съе-760'), 'Как несъедобное становится съедобным', 'How the Inedible Becomes Edible', 'Kako nejestivo postaje jestivo', 'Тим Скоренко', 'Tim Skorenko', 'Tim Skorenko', 'Что происходит, когда популяризатор науки и кулинар встречаются на одной кухне? Она превращается в химическую лабораторию! Почему, если сварить картошку, она станет мягкой? А яйцо, наоборот, затвердеет? Почему мясо шипит на сковородке? И, кстати, почему нельзя всё есть сырым? Удивительные превращения, секретные ингредиенты и всевозможные методы обработки продуктов станут известны тем, кто прочтёт эту книгу, созданную в сотрудничестве с экспертами Политехнического музея.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'почему-бриллианты-дороже-воды--761'), 'Почему бриллианты дороже воды? и еще 47 вопросов про экономику', 'Why Are Diamonds More Expensive than Water? And 47 More Questions About Economics', 'Zašto su dijamanti skuplji od vode? I još 47 pitanja o ekonomiji', 'Мария Бойко', 'Maria Boyko', 'Marija Bojko', 'Как устроены экономические отношения в обществе? Что такое рынок и какие у него законы? Почему одни страны богатые, а другие бедные? В книге Марии Бойко эти и многие другие вопросы объясняются интересно и просто — так, что становится понятно и детям, и взрослым.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'политика-то-о-чем-взрослые-теб-762'), 'Политика. То, о чем взрослые тебе не говорят', 'Politics: What Grown-Ups Don''t Tell You', 'Politika: Ono o čemu ti odrasli ne govore', 'Автор книги Богусь Янишевский – известный польский популяризатор науки – умеет простыми словами рассказывать детям про такие важные и непростые вещи.', 'Boguś Janiszewski', 'Boguś Janiszewski', 'Сложно представить себе современного ребенка, который бы хоть раз не поинтересовался: кто такой президент? Что такое налоги? Почему в стране постоянно кого-то выбирают? И вообще зачем вся эта политика? Родителям порой трудно ответить на подобные вопросы кратко и емко. Политика – это одна из тех тем, про которые родители не разговаривают с детьми, потому что – как справедливо отмечает автор – часто и сами в ней не разбираются. Великолепный образец современного подхода к обучению, в котором нет места сухим формулировкам, зато полно живых примеров и классного визуального материала.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'экономика-то-о-чем-взрослые-те-763'), 'Экономика. То, о чем взрослые тебе не рассказывают', 'Economics: What Grown-Ups Don''t Tell You', 'Ekonomija: Ono o čemu ti odrasli ne govore', '', 'Boguś Janiszewski', 'Boguś Janiszewski', 'Все, что образованному человеку любого возраста нужно знать об экономике, вы найдете в этой книге. Кто платит бабушке и дедушке пенсию? Что такое банк и зачем он дает кредиты? Где прячутся налоги? Как формируется бюджет государства? И даже – как спасти экономику от кризиса? Экономика – это одна из тех тем, которые родители не обсуждают с детьми, потому что – как справедливо отмечает автор – часто и сами не разбираются. Автор книги Богусь Янишевский – известный польский популяризатор науки – умеет простыми словами рассказывать детям про такие, казалось бы, сложные вещи. Его дуэт с иллюстратором Максом Скорвидером – великолепный образец современного подхода к обучению, в котором нет места сухим формулировкам, зато полно живых примеров и классного визуального материала. Они доказали: с детьми можно и нужно говорить о финансах, ведь они однажды вырастут и получат возможность влиять на будущее нашей страны.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'луи-пастер-ученый-детектив-764'), 'Луи Пастер Ученый-детектив', 'Louis Pasteur: Scientist Detective', 'Luj Paster: Naučnik detektiv', 'Флоранс Пино', 'Florence Pinaud', 'Florens Pino', 'Наука XIX века — настоящее приключение. Физики и химики пытаются понять, из чего состоит материя, биологи уже знают, что существуют крошечные организмы, но еще не понимают, что это такое, а работа в лаборатории скорее напоминает домашние опыты. В это время Луи Пастер совершает свои удивительные открытия: обнаруживает микроорганизмы, от которых портится вино и гибнет шелкопряд, доказывает, что жизнь не может зародиться «из ничего», изобретает вакцину от бешенства... И каждая новая задача — как детективное расследование. Книга получила специальный приз Bologna Ragazzi Award в категории Non/fiction на престижной Болонской детской книжной ярмарке.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чарлз-дарвин-революция-765'), 'Чарлз Дарвин Революция', 'Charles Darwin: A Revolution', 'Čarls Darvin: Revolucija', 'Анабель Крамер', 'Annabelle Kremer', 'Anabel Kremer', 'Это не просто рассказ о подробностях жизни великого Чарлза Дарвина — эта книга помогает понять, как мыслит ученый. Каким образом из хаоса информации, обрушившейся на него во время кругосветного путешествия на корабле «Бигль», молодой натуралист смог извлечь закономерности и построить на них теорию, которая стала основополагающей для современной науки? Давайте взглянем на мир глазами Чарлза Дарвин и проследим за ходом его мысли.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'магистр-рассеянных-наук-766'), 'Магистр рассеянных наук', 'Master of Scatterbrained Sciences', 'Magistar rasijanih nauka', 'Владимир Лёвшин', 'Vladimir Lyovshin', 'Vladimir Ljovšin', 'Герои этой книги носятся по всему белому свету в поисках приключений: плывут по океану, катаются на льдине, гуляют по краю кратера вулкана. Они знают, как заставить Черепаху и Гепарда бежать, не обгоняя друг друга, почему пятиконечную звезду древние называли золотой, а также умеют подобрать математический ключ к любому фруктовому магазину. С помощью участников Клуба Рассеянного Магистра читатель мгновенно запоминает правила и парадоксы самой точной в мире науки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'занимательная-физика-767'), 'Занимательная физика', 'Physics for Entertainment', 'Zanimljiva fizika', 'Я. И. Перельман', 'Yakov Perelman', 'Jakov Perelman', 'Одно из лучших классических пособий по физике. Хитрые головоломки, замысловатые вопросы, забавные задачи и парадоксы заинтересуют и помогут успешно освоить физику.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'занимательная-механика-768'), 'Занимательная механика', 'Entertaining Mechanics', 'Zanimljiva mehanika', 'Я. И. Перельман', 'Yakov Perelman', 'Jakov Pereljman', 'Почему человеку, сидящему в поезде, кажется, что поезд стоит на месте, а движется перрон? Если ударить яйцом о яйцо, какое из них разобьется первым? О чем спорили Коперник и Птолемей? Каков принцип действия аэродинамической трубы?.. Теория относительности и инерция, действие и противодействие и многое, многое другое из области прикладной и теоретической механики — вот о чем в простой, увлекательной и доступной форме, с помощью наглядных примеров из жизни, рассказывается в книге Якова Перельмана "Занимательная механика".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '101-головоломка-769'), '101 головоломка', '101 Puzzles', '101 mozgalica', 'Я. И. Перельман', 'Yakov Perelman', 'Jakov Pereljman', 'Сотня увлекательных головоломок для юных математиков. Это непростые, но интересные задачи научат логически рассуждать и нестандартно мыслить.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'большое-путешествие-по-телу-че-770'), 'Большое путешествие по телу человека', 'The Great Journey Through the Human Body', 'Veliko putovanje kroz ljudsko tijelo', 'Джон Фарндон', 'John Farndon', 'Džon Farndon', 'В этой книге подробно, наглядно и невероятно увлекательно рассказано о том, как устроен и как работает человеческий организм. Из чего состоит наше тело, что такое клетки, ткани и органы? Как работают мышцы, нервы и гормоны? Для чего нужны вода и еда и что с ними происходит в организме человека? Почему мы болеем и как выздоравливаем, как распознаем запахи и вкусы? Как мы думаем? Почему мы похожи на своих родителей? Подробный ответ на каждый вопрос разбит на удобные блоки и проиллюстрирован так, что становится ясно не только как устроено человеческое тело, но и как именно происходят в нем все жизненные процессы. Современная и оригинальная по замыслу и исполнению научно-популярная книга написана известным британским писателем Джоном Фарндоном, лауреатом книжных премий в США и Великобритании. Для детей 8-12 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайны-анатомии-771'), 'Тайны анатомии', 'The Magic Anatomy Book', 'Tajne anatomije', 'Кэрол Доннер', 'Carol Donner', 'Kerol Doner', 'Как устроено мое собственное тело? Почему желудок не пожирает сам себя? Зачем нужна иммунная система? Макс и Молли, герои книги "Тайны анатомии", как и все дети, задаются этими вопросами. Только в отличие от обычных детей из реального мира, читающих энциклопедии, расспрашивающих родителей и учителей, с Максом и Молли случилась невероятная история. Как-то на бабушкином чердаке они нашли старую книгу об анатомии человека, и как только они открыли книгу, детей ослепила внезапная вспышка яркого света. И вот, Макс и Молли уже не на чердаке бабушкиного дома, а путешествуют внутри живого человеческого тела. Книга Кэрол Доннер "Тайны анатомии" издавалась по-русски и прежде, в конце восьмидесятых. Этот увлекательный триллер-путешествие внутри человеческого тела моментально стал бестселлером. Многие мамы и папы, выросшие на этой книге, долго пытались найти ее для собственных детей - по библиотекам, в букинистических лавках, у друзей и знакомых. Мы решили ее переиздать, ведь нам, как и родителям наших читателей, тоже приходится отвечать на бесконечные вопросы собственных детей о том, почему человек устроен так, а не этак. А более полного, достоверного, а главное - увлекательного! - ответа на вопрос об устройстве человеческого тела нам встречать не приходилось. Для детей старшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'почему-мы-спим-772'), 'Почему мы спим', 'Why We Sleep', 'Zašto spavamo', 'Кэти Эванс', 'Katie Evans', 'Kejti Evans', 'Всё, что вы хотели знать о сне, но проспали! Зачем мы спим? Какие бывают циклы сна? Чем отличается сон животных? Можно ли избавиться от ночных кошмаров? Мы проводим около трети своей жизни во сне. Но что же на самом деле происходит в эти часы? Эта книга приглашает в увлекательное путешествие по миру сна и расскажет, что происходит, когда мы спим. 5 причин купить книгу «Почему мы спим?» Гипнотическая книга перенесет в яркое путешествие по царству сновидений — и даже дальше; Словно плед, книга будто соткана из фактурных иллюстраций Поли Плавинской; Сон интересовал человека с древних времен и сейчас, в век бесконечной стимуляции, тема как никогда волнующая; Не только интересные факты о биологических и культурных процессах, связанных со сном, но и советы как наладить режим; Увлекательное дополнение к учебным программам по биологии и естественным наукам для детей от 6 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'женщины-в-науке-773'), 'Женщины в науке', 'Women in Science: 50 Fearless Pioneers Who Changed the World', 'Žene u nauci: 50 neustrašivih pionirki koje su promijenile svijet', 'Рэйчел Игнатовски', 'Rachel Ignotofsky', 'Rejčel Ignotofski', 'Великолепно иллюстрированная книга знаменитого дизайнера Рэйчел Игнатовски посвящена 50 выдающимся женщинам науки древнего и современного мира. Героини книги - физик и химик Мария Кюри, американский математик Кэтрин Джонсон, рассчитавшая траекторию полета Аполлона-11 на Луну, Валентина Терешкова, первая женщина-космонавт и многие другие бесстрашные женщины, проложившие путь для новых поколений женщин-инженеров, биологов, генетиков, математиков, врачей, астронавтов, физиков.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'женщины-в-искуссве-774'), 'Женщины в искуссве', 'Women in Art: 50 Fearless Creatives Who Inspired the World', 'Žene u umjetnosti: 50 neustrašivih stvarateljki koje su inspirisale svijet', 'Рэйчел Игнатовски', 'Rachel Ignotofsky', 'Rejčel Ignotofski', 'Искусство - это нечто большее, чем просто красота, - это сила! Всё, что нас окружает, независимо от того, осознаем мы это или нет, создано художниками. Здание, в котором мы живем, рекламный щит на улице, узор у тебя на рубашке - всё это начиналось с идеи в голове у творца. Многие считают, что наша способность к самовыражению через творчество - и есть то, что делает людей особенными. Богато иллюстрированная книга знаменитого дизайнера Рэйчел Игнатовски посвящена 50 выдающимся женщинам искусства древнего и современного мира. Героини книги - художницы Фрида Кало и Джорджия О&#39;Киф, писательница Беатрис Поттер и многие другие бесстрашные женщины, проложившие путь для новых поколений женщин-художниц, скульпторов и писательниц. Читай, вдохновляйся и присоединяйся к сообществу творческих женщин!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'большая-инвентаризация-искусст-775'), 'Большая инвентаризация искусства', 'The Great Art Inventory', 'Veliki inventar umjetnosti', 'Луиза Локхарт', 'Louise Lockhart', 'Luiz Lokhart', 'Вместе с авторами этого издания читатель поучаствует в настоящей инвентаризации произведений искусства со всего мира. Книга состоит из десяти глав. Первый разворот каждой главы — краткая характеристика периода в истории искусств с древних времен и до современности, второй — импровизированная коллекция художественных артефактов эпохи. Это художники, картины, строения, скульптуры, явления, инструменты — все, из чего состоит художественное пространство времени.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'по-следам-современного-искусст-776'), 'По следам современного искусства Иллюстрированная книга для детей о произведениях современного искусства из собрания Национального музея современного искусства — Центра Жоржа Помпиду в Париже.', 'In Search of Modern Art: An Illustrated Guide to the Centre Pompidou', 'Tragom savremene umjetnosti: Ilustrovani vodič kroz Centar Pompidu', '', 'Alice Harman, Serge Bloch', 'Elis Harman, Serž Blok', 'Увлекательная книга-квест, написанная британкой Элис Харман и искрометно проиллюстрированная известным французским художником Сержем Блоком, проведет юных читателей и всех, кому интересно современное искусство, по его истории и по залам парижского Центра Помпиду. Обозревая лучшие экспонаты этого музея, непринужденно беседуя с их авторами и порой подшучивая над ними, текст не оставит сомнений в том, что искусство — одна из самых веселых вещей на свете.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'архитектура-глазами-голубя-777'), 'Архитектура глазами голубя', 'Architecture According to Pigeons', 'Arhitektura očima goluba', 'Крап Ли Пернхвост', 'Speck Lee Tailfeather', 'Spek Li Telveder', 'Увлекательное путешествие по главным мировым достопримечательностям от лица голубя по имени Крап. Рассказ сопровождается красочными иллюстрациями и учит наслаждаться красотой зданий самых юных путешественников. Уникальная возможность узнать о шедеврах архитектуры буквально с высоты птичьего полета.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кто-это-построил-778'), 'Кто это построил', 'Who Built This', 'Ko je ovo izgradio', 'Полина Фадеева, Анна Алямова', 'Polina Fadeeva, Anna Alyamova', 'Polina Fadjejeva, Ana Aljamova', 'Задумывались ли вы, глядя на дома и улицы, отели и музеи, магазины и моллы, о том, кто всё это построил? А ведь кто-то придумал и возвёл целые города, порты, мосты, парки. И даже памятники кто-то спроектировал так, чтобы они не падали. Эта книга о людях, которые построили всё то, что не создала сама природа, — об архитекторах. Они не всегда строят сами, они разрабатывают проекты и планы, продумывают использование и развитие территорий. Это сложнейшая и очень ответственная работа, и результат ее у всех на виду. Однако самих архитекторов мы видим редко, иногда знаем по имени и почти никогда — в лицо. А ведь эти мастера и творцы — живые люди, шутники и мечтатели. Анна Алямова и Полина Фадеева, потомственные архитекторы и подруги с детства, решили рассказать детям и взрослым не только о зданиях, планах, конструкциях и концепциях, но и об их создателях, которые были маленькими, придумывали затейливые штуки, любили конструкторы, помогали родителям, а когда выросли, не стали скучными взрослыми, а продолжили играть с реальностью и создавать новое и удивительное. Даже если окружающим всё это порой казалось странным ребячеством, со временем герои книги изменили мир, в котором мы живем.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'алексей-щусев-архитектор-котор-779'), 'Алексей Щусев, архитектор который покорил время', 'Alexey Shchusev: The Architect Who Conquered Time', 'Aleksej Šćusev: Arhitekta koji je pobijedio vrijeme', 'Ксения Смирнова, Полина Покладок', 'Ksenia Smirnova, Polina Pokladok', 'Ksenija Smirnova, Polina Pokladok', 'Первая популярная книга об Алексее Щусеве — человеке, который спроектировал и воплотил в жизнь десятки знаковых зданий (среди них Марфо-Мариинская обитель, Казанский Вокзал и Мавзолей Ленина в Москве, Театр оперы и балета в Ташкенте и Русский павильон в Венеции). Щусев был великим архитектором — но чтобы достичь того, что сам он называл «неплохими результатами», недостаточно просто уметь строить дома. Нужны и другие знания, умения и способности, которые позволяют нам назвать Алексея Викторовича замечательным реставратором, градостроителем, преподавателем, художником. На жизнь Щусева выпало множество событий, кардинально изменивших вкусы людей, скорость жизни, политический строй и отношение к прошлому. Но он смог «покорить время», оставаясь одним из лидеров отечественной архитектуры, что бы ни происходило в жизни, искусстве и стране. Авторы книги, научные сотрудники Государственного музея архитектуры, который носит имя Алексея Щусева, увлекательно и с любовью говорят о великом человеке, на примере которого дети и их родители узнают, как талант, трудолюбие и любовь к своему делу позволяют, несмотря на революции, войны и смену власти, не только идти в ногу со временем, но и остаться в памяти потомков.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-фотограф-780'), 'Я - фотограф', 'I Am a Photographer', 'Ja sam fotograf', 'Ольга Аверьянова, Олеся Гонсеровская', 'Olga Averyanova, Olesya Gonserovskaya', 'Olga Averjanova, Olesja Gonserovska', 'Все мы фотографируем! Порой кажется, что так было всегда. Но это заблуждение. Фотография — магия, наука и искусство — так думали на заре её истории. Сегодня — это просто касание пальцем кнопки смартфона. Или все-таки нет? Для детей и их родителей в книге можно найти ответы на этот и другие вопросы. Почитаем и посмотрим.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мир-инженера-шухова-как-работа-781'), 'Мир инженера Шухова Как работает мозг изобретателя', 'The World of Engineer Shukhov: How an Inventor''s Mind Works', 'Svijet inženjera Šuhova: Kako radi um pronalazača', 'Айрат Багаутдинов', 'Airat Bagautdinov', 'Ajrat Bagautdinov', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'история-книги-своими-руками-782'), 'История книги своими руками', 'DIY History of Books', 'Istorija knjige sopstvenim rukama', 'Светлана Прудовская', 'Svetlana Prudovskaya', 'Svetlana Prudovskaja', 'Вы знаете, какой была книга 4 тысячи лет назад? Хотите, не выходя из дома, сделать глиняную табличку, папирусный свиток, берестяную грамоту или бумажную гармошку? А изготовить собственную бумагу с цветами или с укропом? Читателю этой книги предстоит не только узнать, какой долгий путь прошла книга, но и пережить этот сюжет мировой истории на собственном опыте - через эксперименты с разными материалами и создание собственных рукотворных книг. Попутно читатель откроет для себя множество секретов художественного ремесла, которыми владели древние мастера. Книга богато иллюстрирована; в ней вы найдёте сказки, пословицы, скороговорки и рецепты, которые пригодятся для изготовления необычных рукодельных книжек. Автор книги - художник, педагог и искусствовед Светлана Прудовская. Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-знаю-такого-художника-783'), 'Я знаю такого художника', 'I Know an Artist', 'Znam tog umjetnika', 'Сьюзи Ходж', 'Susie Hodge', 'Suzi Hodž', 'Я знаю такого художника - это восемьдесят четыре очерка о выдающихся художниках XIX-XXI веков, оказавших решающее влияние на ход истории искусства. А еще это история неожиданных встреч и удивительных пересечений судеб. Одних художников - например, Пауля Клее и Анни Альберс - связывали отношения преподавателя и студента, других, как Джексона Поллока и Ли Краснер, - любовь и супружество, третьих - общий источник вдохновения, как, например, цветы в творчестве Джорджии О&#39;Кифф и Такаси Мураками.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'старые-мастера-рулят--784'), 'Старые мастера рулят!', 'Old Masters Rock!', 'Stari majstori su zakon!', 'Сайн-Витгенштейн Ноттебом Мария-Кристина', 'Maria-Christina Sayn-Wittgenstein Nottebohm', 'Maria-Christina Sayn-Wittgenstein Nottebohm', 'Книга для детей и родителей, открывающая новые стороны знакомых произведений искусства. «Старые мастера рулят!» включает в себя 50 картин как известных художников: Леонардо да Винчи, Винсента ван Гога, Эдварда Мунка, Питера Пауля Рубенса, Эдгара Дега, Эдуарда Мане, так и менее знакомых. Все они сгруппированы по темам — «Животные», «Природа», «Герои», «Мифы», «Магия» и другие — и наиболее полно рассказывают о художественных произведениях с XII до XX века.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'школа-искусств-785'), 'Школа искусств', 'The School of Art', 'Škola umjetnosti', 'Тил Триггс', 'Teal Triggs', 'Til Trigs', '"Школа искусств" - не просто книга. Это полноценный курс, который познакомит вашего ребенка с основами изобразительного искусства и дизайна. Вы попадете в настоящую школу, профессора которой расскажут вам все самое важное о главных элементах дизайна: линиях, геометрических фигурах, пространстве и цвете. Вы узнаете: какой может быть линия, как превратить двухмерную фигуру в трёхмерную, передать движение, работать с тенями, текстурой, штриховкой, паттернами и, конечно, цветом. После этого вы изучите основные правила, которые помогают собрать все элементы дизайна вместе. Темами уроков станут: композиция и модульная сетка, пропорции, перспектива, негативное и позитивное пространство, визуальный вес, ритм и многое другое. Ну, и наконец, последние уроки будут посвящены тому, как применять новые знания в жизни: как мыслить образами и отражать их на бумаге, как с помощью рисунков объяснять сложные идеи, рисовать комиксы и инфографику.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'линнея-в-саду-художника-786'), 'Линнея в саду художника', 'Linnea in Monet''s Garden', 'Lineja u slikarevom vrtu', 'Лена андерсон, Кристина Бьорк', 'Christina Björk, Lena Anderson', 'Kristina Bjork, Lena Anderson', 'Линнея - маленькая девочка, которая очень любит цветы. Вместе со своим другом, садовником Блумквистом, она совершает путешествие в Париж, на родину великого художника Клода Моне. Им удается не только побывать в музее, где хранятся его картины, но и заглянуть в дом художника, посмотреть на цветы в его саду и пройтись по знаменитому японскому мостику, который Моне так часто изображал на своих полотнах. А самое интересное о жизни Моне они узнают от его правнука, который повстречался им рядом с домом Моне. "Линнея в саду художника" - это книга об искусстве, написанная специально для детей. Она была переведена на 30 языков, только в Америке продано более 700 000 экземпляров! В Германии книга получила престижную премию в области юношеской литературы (1988) в номинации "Познавательная книга".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'оркестр-787'), 'Оркестр', 'The Orchestra', 'Orkestar', 'Авалон Нуово', 'Avalon Nuovo', 'Avalon Nuovo', 'Как устроен оркестр и на какие группы делятся музыкальные инструменты? Что значит «читать ноты» и как сочиняют музыку? Из чего состоят скрипка, труба и кларнет? Чем орган отличается от пианино? Почему так важна акустика концертного зала? Эта книга адресована и начинающим музыкантам, и всем тем, кто неравнодушен к волшебному миру музыки. Вы узнаете, как появились первые оркестры, кто из композиторов совершил настоящую музыкальную революцию, в чём секрет знаменитого цикла концертов Антонио Вивальди «Времена года» и ещё много-много интересного.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'иллюстрированная-история-рока-788'), 'Иллюстрированная история рока', 'An Illustrated History of Rock', 'Ilustrovana istorija roka', 'Сусана Монтеагудо', 'Susana Monteagudo', 'Susana Monteagudo', 'Точная дата рождения рока не известна. Нет у него и какого-то одного отца-основателя. Рок возник в Америке из смеси блюза, джаза, кантри, ритм-энд-блюза и других музыкальных стилей. Музыканты 1950-х годов соединили эти формы и ритмы, еще не понимая, что получившаяся смесь положит начало большой революции. "Иллюстрированная история рока" - книга про эту революцию. Она расскажет о группах и исполнителях, о самых важных песнях и альбомах, о фестивалях и фанатах, о звукозаписывающих компаниях, музыкальных журналах и передачах - короче, обо всем!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'школа-музыки-789'), 'Школа музыки', 'The School of Music', 'Škola muzike', 'МАйриг и Рэйчел Боуэн', 'Meurig and Rachel Bowen', 'Meurig i Rejčel Bouen', 'Продолжение "Школы искусств". Теперь пришло время обратить внимание на музыку! Мы снова стоим на пороге невероятной школы, где вас ждут профессиональные учителя и репетиторы. Они расскажут вам об особенностях вокала, инструментальной музыки, оркестрового исполнения. Лучшие в своих областях: Классическая оперная певица, Дирижер в оркестре (руководит музыкальными коллективами разных жанров) Эксперт по струнным инструментам, Виртуоз ударных инструментов, Богиня духовых инструментов Если ваш ребенок уже занимается музыкой, хотел бы начать ее изучение или ему просто интересно понять, как все устроено, - эта книга идеальный проводник в волшебный мир музыки. В книге есть музыкальные отрывки, которые можно найти и прослушать в интернете.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'история-музыки-в-картинках-790'), 'История музыки в картинках', 'The History of Music in Pictures', 'Istorija muzike u slikama', 'Бернар Дейрие Дени Лемери Майкл Сэдлер', 'Bernard Deyriès, Denis Lemery, Michael Sadler', 'Bernard Dejrije, Deni Lemeri, Majkl Sadler', 'Приглашаем в захватывающее путешествие "по следам классической музыки"! В этой "Истории" есть все, что нужно ученику или меломану: сведения о великих музыкантах древности и современности, о музыкальных инструментах и музыкальных нравах. Здесь есть классика, рок, джаз и авангард. Здесь есть даже то, о чем и педагоги узнают с удовольствием. А именно: - какая музыка была модной в каменном и других веках - что танцевали на дискотеке пять или семь столетий назад - кто придумал сочинения для ужинов короля… для двери и вздоха… для пишущей машинки… для магнитофона с симфоническим оркестром… А самое главное, что… "История музыки в картинках": веселая форма - но не в ущерб исторической достоверности. Просто учить и учиться станет намного интереснее!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'цой-история-рок-звезды-в-буква-791'), 'Цой История рок-звезды в буквах и картинках', 'Tsoi: The Story of a Rock Star in Letters and Pictures', 'Coj: Priča o rok zvijezdi u slovima i slikama', 'Денис Бояринов', 'Denis Boyarinov', 'Denis Bojarinov', '«Цой. История рок-звезды в буквах и картинках» — иллюстративный нонфикшн, в котором из отдельных эпизодов истории группы «Кино» и жизни Виктора Цоя складывается картина больших перемен, и для каждого она получается своей. Эта книга — собирательный образ, метафора эпохи, рассказ о кумире поколений, который понравится и подросткам, и взрослым. Всем, кто хотя бы раз в жизни подпевал уличным музыкантам, пел на кухне «Пачку сигарет» (про «самолет с серебристым крылом»), а может, и сам учился играть песни группы «Кино».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мусорная-революция-792'), 'Мусорная революция', 'Trash Revolution: Breaking the Cycle of Waste', 'Revolucija otpada', 'Эрика Файви', 'Erica Fyvie', 'Erika Fajvi', 'Задумывался ли ты когда-нибудь, что происходит с мусором, который мы ежедневно выбрасываем? Куда едет мусоровоз и что случается с обёрткой от шоколадки после того, как ты выкинул её в урну? Чаще всего мы просто выбрасываем ненужные вещи, тем самым всё больше и больше загрязняя окружающую природу. Но иногда мир можно изменить к лучшему, просто изменив свои привычки. Мы выбрали эту книгу для издания на русском языке, чтобы дети и взрослые могли разобраться, как именно устроен мир вещей вокруг нас, откуда мы получаем воду, одежду, продукты, книги и мобильные телефоны. А ещё для того, чтобы помочь миру стать чище. Мы надеемся, что читатель осознает масштаб всей мусорной проблемы в нашей стране и захочет на неё повлиять. И тогда мир станет лучше! Далеко ли можно уехать на бумажном велосипеде? И как съесть на обед свою ложку? Эта книга расскажет и покажет, как работает водоочистная станция, куда уходят пищевые отходы, как построить дом из переработанной бумаги и, самое главное, как избежать напрасной траты природных ресурсов и сохранить нашу планету для будущих поколений.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'прощай-нефть--793'), 'Прощай, нефть!', 'Goodbye Oil!', 'Zbogom, nafto!', 'Харриет Рассел', 'Harriet Russell', 'Harriet Russell', 'Иллюстрированная книга о том, как добывают нефть, как мы можем уменьшить нашу зависимость от нее, почему нам стоит перейти на альтернативные способы добычи топлива и уделять больше внимания проблеме раздельного сбора и переработки мусора. Нефть, как известно, - невозобновляемый ресурс. Но откуда она берется? Как ее производят? И что будет, если она закончится? На страницах книги автор поднимает все эти вопросы и предлагает изменить наши привычки, чтобы в один день нам всем не пришлось действительно попрощаться с нефтью.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '-пальмы-на-северном-полюсе-бол-794'), '«Пальмы на Северном полюсе. Большой рассказ об изменении климата»', 'Palm Trees at the North Pole: The Big Story of Climate Change', 'Palme na Sjevernom polu: Velika priča o klimatskim promjenama', 'Марк тер Хорст', 'Marc ter Horst', 'Marc ter Horst', 'Тема изменения климата на Земле часто вызывает жаркие споры. Спорят политики, эксперты в публицистических передачах, спорят коллеги на работе или члены семей. Действительно, вопрос этот очень сложный, и сходу в нем не разобраться. Нидерландский детский писатель и популяризатор науки Марк тер Хорст несколько лет собирал сведения об истории климатических изменений и решил поделиться с читателями полученными знаниями, попутно рассказывая о физике современных п прошлых изменений климата, об ученых-климатологах, о том, какой климат нас ждет в будущем и придется ли нам менять из-за климатических зименений свой образ жизни. Книга написана легко и с юмором, при этом она заставит задуматься об этой проблеме не только детей, но и взрослых.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '-дети-против-пластика--795'), '«Дети против пластика»', 'Kids Fight Plastic', 'Djeca protiv plastike', 'Мартин Дори', 'Martin Dorey', 'Martin Dori', 'Могут ли дети взять на себя такую сложную миссию, как борьба с пластиком? Или такое дело им не по плечу? Океан задыхается от мусорных островов, огромные свалки подступают к нашим городам, и даже в озерах Антарктиды обнаружен микропластик. Ни один супергерой не сумеет мгновенно избавить мир от накопившихся отходов. Наверное, без волшебства тут не обойтись... Удивительно! Самая большая трудность в борьбе с мусором — бросить вызов собственным привычкам, а самая большая победа — это когда друзья и близкие люди поверят тебе и последуют твоим экосоветам. Книга «Дети против пластика» поможет вдохновить на новые экологические подвиги не только маленьких читателей, но и их родителей и друзей. Кое-что из того, что вы найдете на ее страницах, будущие экологи изучают в университетах. Загрязнение пластиком — это, пожалуй, самая заметная составляющая глобальной проблемы отходов, но, разумеется, не стоит забывать и о других видах мусора.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мусорный-остров-796'), 'Мусорный остров', 'Plastic Island', 'Ostrvo smeća', '', 'Lee Myung-ae', 'Li Mjong-e', 'Разноцветный остров посреди океана — зрелище на первый взгляд завораживающее. Яркий и красочный, он весь состоит из неведомых предметов разных форм и размеров. Для чего они? Съедобны ли? И можно ли на этом острове жить? 5 причин купить книгу «Мусорный остров»: Красочная, тонкая и нежная история о жизни тупика на мусорном острове; Ли Мёнэ — южнокорейская художница, лауреат международных премий, чьи книги издаются на 5 языках; Книга-помощник в первом разговоре об экологии с ребенком, а также об ответственности человека перед окружающим миром, перед населяющими его существами и будущими поколениями; История мусорного острова и его обитателей — пронзительное напоминание о том, как хрупок и уязвим наш мир; Книга рассказана от лица тупика и раскрывает множество опасностей, которые в себе таит мусорный остров.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'спасем-воду-вместе-учебник-юно-797'), 'Спасем воду вместе. Учебник юного эколога', 'Save Water Together: A Young Ecologist''s Guidebook', 'Spasimo vodu zajedno: Priručnik za mlade ekologe', '', 'Water Family', 'Water Family', 'Совсем недавно мы принимали воду как должное и не задумывались над опасностями, которые ей угрожают. Высыхание водоёмов, таяние ледников, мусор в мировом океане, загрязнение воды отходами промышленных предприятий – к сожалению, сейчас эти проблемы стали реальностью. Настал момент, когда необходимо действовать. Эта книга расскажет о том, как вода необходима человеку и природе, и что можно сделать для её защиты. Французские спортсмены из Water Family и российские эко-активисты объяснят, что каждый из нас может сделать для защиты воды. Ведь даже ребенок может внести свой вклад в сохранение чистой воды в масштабе целой планеты.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-дела-земля--798'), 'Как дела, Земля?', 'How Are You Doing, Earth?', 'Kako si, Zemljo?', 'Дюваль', 'Duval', 'Duval', 'Книга "Как дела, Земля?" рассказывает детям школьного возраста об экологических проблемах Земли. Но делает это не скучно, а при помощи любопытных картинок и тестов. Лучше всего книгу характеризует цитата из Сент-Экзюпери: "Мы не наследуем землю предков, мы берем ее в долг у наших детей". Эта полезная книжка для классного или внеклассного чтения открывает серию книг "Этот огромный мир", в которую также входят другие книги - о том, как устроены средства массовой информации и о том, с какими трудностями приходится сталкиваться жителям больших городов.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайна-ничто-и-бесконечно-много-799'), 'Тайна ничто и бесконечно много глупостей', 'The Mystery of Nothing and Endless Nonsense', 'Tajna ničega i beskrajno mnogo gluposti', 'Ян Паул Схюттен', 'Jan Paul Schutten', 'Jan Paul Schutten', 'Задумайся: Вселенная бесконечна и всеобъемлюща. Но когда-то ее не существовало. А что же было до нее? Неужели пустота? Но как из пустоты возникло все? И правда ли, что вселенных может быть бесконечно много? С помощью этой книги ты отправишься в путешествие во времени и увидишь, как выглядела Вселенная всего через миллионную долю триллионной доли триллион триллионной доли секунды после возникновения. Попутно ты узнаешь, что такое черные дыры, частицы и античастицы, бозон Хиггса и многое другое. Ты сможешь понять, что значит самая знаменитая формула в мире - E = mc2, каким может быть мир, где двадцать измерений, что случилось 14 сентября 2015 года, почему Вселенная похожа на черничный пирог и как этот пирог испечь. И хотя в этой книге объясняется далеко не все, она научит тебя задавать правильные вопросы. А правильно поставленный вопрос - это первый шаг на пути к ответу, который, возможно, найдешь именно ты.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вот-это-космос--800'), 'Вот это космос!', 'Out of This World: The Great Space Book', 'Kakav svemir!', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Все, что описано в этой книге, происходит в далеком будущем - в 3001 году. Космические путешествия стали обычным делом, земляне живут и работают на астероидах, Марсе, Луне и даже на далеких звездах. Жители других планет больше не инопланетяне, а друзья и знакомые. Космические корабли, НЛО и автобусы курсируют со скоростью света (ну почти) - и вся галактика обожает пиццу! Занимайте места в школьном автобусе! Маури Куннас проведет увлекательную экскурсию по Солнечной системе. Незабываемые впечатления гарантированы!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'космос-801'), 'Космос', 'Space', 'Kosmos', 'Зина Сурова, Дмитрий Костюков', 'Zina Surova, Dmitry Kostyukov', 'Zina Surova, Dmitrij Kostjukov', '"Космос" - необычная книга! Она познавательна, как настоящая энциклопедия, и увлекательна, как весёлый комикс. У книги два автора: фотограф Дмитрий Костюков и художник Зина Сурова. Они вместе писали тексты и придумывали иллюстрации. Дмитрий много раз летал на Байконур, фотографировал старт и посадку космического корабля "Союз", сборку ракет и тренировки космонавтов. Зина делала иллюстрации в технике коллажа, соединяя фотографии, рисунки и комиксы на огромных листах бумаги. В процессе двухлетней работы над книгой авторы неоднократно консультировались с космонавтами.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'космическое-приключение-802'), 'Космическое приключение', 'Tatu and Patu: Space Adventure', 'Tatu i Patu: Svemirska avantura', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', '"Вперед, вверх и в космос! - крикнул Тату, когда межзвездный космический корабль "Бананас", или МКК "Бананас", взмыл в небо. Звездные пилоты А. Т. Лантич, или Тату, и Термо Бокс, или Пату, отправились в космическую даль проверить, все ли кольца Сатурна на месте. Неизвестная сила вовлекает их в невероятное, захватывающее приключение, в котором планеты исчезают, а орбиты меняют свои траектории. Только отвага и смекалка звездных пилотов могут спасти Вселенную.Космическое приключение разворачивается со скоростью света и проникает в самые потаенные уголки читательских галактик"');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'энциклопедия-балбесов-803'), 'Энциклопедия балбесов', 'The Encyclopedia of Goof-Offs, Dropouts, and Other Geniuses', 'Enciklopedija neznalica i ostalih genija', '', 'Unknown', 'Nepoznati autor', '«Энциклопедия балбесов, неучей и прочих гениев» расскажет Вам о детстве знаменитых талантливых людей. Все мы прекрасно знаем, что Пикассо — великий художник, Наполеон покорил всю Европу, Эйнштейн сформулировал теорию относительности, а Агата Кристи — самая знаменитая писательница детективов всех времен и народов. Но мало кому известно, что Пикассо носил в школу голубя, чтобы не скучать на уроках, Агате Кристи запрещали читать до восьми лет (что не помешало ей научиться делать это еще в пять), а гений Эйнштейн не говорил до трех лет и в школе считался тугодумом. И что многие выдающиеся люди в детстве отличались ужасным поведением. Со временем история увенчала их лаврами. Но это живые люди, биографии которых более увлекательны, чем любой приключенческий роман. Приглашаем вас окунуться в их детство и юность, почувствовать дыхание истории и попытаться понять, почему они стали великими.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'монстры-и-чудовища-804'), 'Монстры и чудовища', 'The Atlas of Monsters: Mythical Creatures from Around the World', 'Atlas čudovišta: Mitska bića iz cijelog svijeta', 'Сандра Лоуренс', 'Sandra Lawrence', 'Sandra Lorens', 'Тайны этой книги спрятаны на пожелтевших страницах карт и дневников, найденных в старинной английской усадьбе. Быть библиотекарем не так спокойно, как может показаться: вас может затянуть в историю, из которой вы не сможете выбраться! В книге собраны 227 самых странных фантастических существ и монстров. Переходите на следующий уровень! Для старшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'герои-мифов-и-легенд-805'), 'Герои мифов и легенд', 'Heroes of Myths and Legends', 'Heroji mitova i legendi', 'Сандра Лоуренс', 'Sandra Lawrence', 'Sandra Lorens', 'Начните распутывать загадочный клубок из странных символов, спрятанных на картах. Понадобится не только знания, но весь запас эмоционального интеллекта, внимательность, усидчивость и … свободное время. Ведь вы не сможете оторваться от этой книги. Для старшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'метро-подземный-город-806'), 'Метро. Подземный город', 'Metro: The Underground City', 'Metro: Podzemni grad', 'Наталия и Василий Волковы', 'Natalia Volkova, Vasily Volkov', 'Natalija Volkova, Vasilij Volkov', 'Эта книга расскажет не только об истории строительства Московского метрополитена, который считается самым красивым, но и о том, как устроен этот подземный мир - огромный, сложный и очень интересный. Кто придумал первые "подземки", как проектировалось и строилось метро, что такое "плывун" и "проходческий щит", откуда под землю попадает свежий воздух, где ночуют поезда? Эта книга - уникальное путешествие по самым красивым станциям, по знаменитым метрополитенам больших городов, путешествие сквозь землю и сквозь время. Для младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пособие-по-бессмертию-для-начи-807'), 'Пособие по бессмертию для начинающих', 'A Beginner''s Guide to Immortality: From Alchemy to Avatars', 'Vodič kroz besmrtnost za početnike', 'Мария Бирмингем', 'Maria Birmingham', 'Marija Birmingem', 'Вы хотите перехитрить смерть? Если ответ "да", то именно сейчас в ваших руках нужная вещь - путеводитель по бессмертию! Эта книга расскажет, на какие свершения были способны люди в стремлении обрести вечную жизнь... или как безумные мечтатели находили смерть в бесплодных поисках. "За последние два столетия продолжительность жизни увеличилась более чем вдвое. Человек, родившийся в начале XIX в., едва мог надеяться пересечь 35-летний рубеж, а сегодня средняя продолжительность жизни в развитой стране составляет 78 лет. Однако продлить жизнь на несколько десятилетий - это еще куда ни шло. Но жить вечно?.. В общем, устраивайтесь поудобнее и слушайте, как человечество пыталось (и продолжает пытаться) раскрыть секрет бессмертия". Для среднего и старшего школьного возраста');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'умираю-как-хочу-спросить-38-жи-808'), 'Умираю как хочу спросить! 38 жизненно важных вопросов про смерть', 'Dying to Ask! 38 Vital Questions About Death', 'Umirem od želje da pitam! 38 životnih pitanja o smrti', 'Автор: Кантавелья Хуан Анна, Дьюти Эллен Иллюстратор: Антинори Андреа', 'Anna Juan Cantavella, Ellen Duthie, Andrea Antinori', 'Anna Juan Cantavella, Ellen Duthie, Andrea Antinori', 'Когда умираешь, у тебя пропадают мысли? Откуда мне знать, что, когда я сплю, я не умер? Если я умру, что будет с моей приставкой? Смерть — это страшно? Правда, что когда отрубают голову, твое тело бегает без головы? Если умирает кто-то, кого ты любишь, сколько времени ты горюешь? В будущем появятся машины для оживления людей? Почему говорят «покойся с миром», а не «веселись с миром»? Две писательницы и один иллюстратор погружаются в тему и встречаются с 38 вопросами о смерти от девочек и мальчиков от 5 до 15 лет. Что они ответят? Эта нежная, без предрассудков книга, строгая и странным образом веселая, приглашает к разговорам, размышлениям и новым вопросам о смерти.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'внимание-доктор--809'), 'Внимание, доктор!', 'Attention, Doctor!', 'Pažnja, doktore!', 'Петр Свободны', 'Petr Svobodný', 'Petr Svobodni', 'Книга "Внимание, доктор!" - это не сюжетное повествование и не энциклопедия. Ее автор стремится лишь указать читателю на поворотные моменты в истории медицины. В этом ему помогают герои книги - обычная чешская семья. На протяжении семи глав мы вместе с ними узнаем, какие проблемы со здоровьем испытывали люди с древнейших времен до наших дней, знакомимся с революционны ми способами их решения, найденными по большей части уже в XIX и XX веках. Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'поразительные-паразиты-растени-810'), 'Поразительные паразиты: растения, грибы, животные', 'Astounding Parasites: Plants, Fungi, Animals', 'Zapanjujući paraziti: biljke, gljive, životinje', '', 'Unknown', 'Nepoznati autor', '«Ну и паразит же ты!» – говорит хозяин своему коту, утащившему со стола сосиску. «Паразиты окаянные!» – кричит старушка птицам, клюющим ягоды на огороде. Да мы часто используем это слово, не думая о его научном смысле. Но для учёных «паразит» совсем не ругательство, не прозвище, а серьёзный научный термин. В биологии так именуются организмы, живущие за счёт других. Мы окружены паразитами со всех сторон, хотя порой и не подозреваем об этом. Они всюду: в воде и на суше, в диком лесу и в современном городе. Иногда и внутри нас самих! Кого только нет в этом огромном сообществе! Растения и грибы, черви и моллюски, насекомые и раки. Есть даже рыбы, птицы и звери. Все они очень разные, но всех объединяет одна общая черта – стремление пожить за чужой счёт. Мир паразитов фантастически необычен – словно мир инопланетян, чудом оказавшихся на нашей планете. Нам зачастую трудно понять их вкусы и привычки. Трудно вообще принять само их существование. Но это часть нашей природы. Это вполне земные твари и в какой-то степени наши эволюционные родичи. Просто они пошли другим путём. Многие спросят: «Зачем вообще надо задумываться об этой гадости?» Не будем обобщать, паразиты – это далеко не всегда гадость. Например, вряд ли кто-то назовёт гадостью омелу, с которой связаны традиции многих народов. И повернётся ли язык называть гадостью романтичную кукушечку, воспетую в стихах и песнях? А ведь она тоже паразит. Как, вы об этом не знали? Или вот грибы, вырастающие паразитическим образом, но приносящие нам, людям, пользу. Берёзовый трутовик, например, он же чага, служит сырьём для противоопухолевых препаратов. Кордицепс, паразитирующий на некоторых видах насекомых, также служит сырьём для изготовления лекарств. Про пенициллин и говорить нечего, этот грибок-паразит, совершивший переворот в медицине, известен всем. И примеров таких необыкновенных паразитов можно привести ещё много. О том, как живут паразиты, зачем они нужны в природе и что могут дать людям, вы узнаете из этой книги. Кстати, первой детской книги в России на подобную тему!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хворые-истории-811'), 'Хворые истории', 'Sick Stories: Plagues, Bugs, and Outbreaks Through History', 'Zarazne priče: Istorija kuge, virusa i epidemija', 'Гося Кулик, Томек Жарнецкий', 'Gosia Kulik, Tomek Żarnecki', 'Gosja Kulik, Tomek Žarnecki', 'Похожи ли вирусы на зомби? Можно ли полюбить вшей? Кто придумал использовать болезни в качестве оружия? Зачем "чумному доктору" клюв? Как полиомиелит помог поймать Усаму бен Ладена? Эта книга - не скучная энциклопедия и не сухой справочник, на ее страницах вы можете найти все: и практические советы, и исторические анекдоты, узнаете о вакцинации и опасных для жизни похоронных обрядах. Пятнадцать вирусов и бактерий. Пятнадцать смертельных напастей. Как с ними боролись наши предки - и что знаем о них мы? Вот же зараза! Научный редактор и автор главы о коронавирусе Алексей Паевский. Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'что-там-внутри-путеводитель-по-812'), 'Что там внутри? Путеводитель по нашему мозгу', 'What''s Inside? A Guide to Our Brain', 'Šta je unutra? Vodič kroz naš mozak', 'Мартинш Изабель Миньош, Педроза Мария Мануэль', 'Isabel Minhós Martins, Maria Manuel Pedrosa', 'Izabel Minjoš Martins, Marija Manuel Pedrosa', 'Сегодня мы знаем, что наши мысли, чувства, решения, озарения — результат работы мозга во взаимодействии с другими органами и частями тела. Но как рождается мысль? Как функционирует мозг? Как сохраняет способность к обучению вплоть до старости? Как мозг чувствует, изобретает, творит и делает каждого из нас уникальной и неповторимой личностью? Книга «Что там внутри?» написана при участии команды нейробиологов, философов и психологов. Её авторы исследуют эволюцию мозга человека от рождения до старости, открывают невероятную реальность, построенную с помощью чувств, объясняют, как мы учимся, принимаем решения и действуем и как мы связаны с другими людьми и другими мозгами. И если, как утверждается в этой книге, на развитие мозга влияет любой жизненный опыт, мы надеемся, что знакомство с ней сделает ваш мозг еще более любознательным и счастливым! Несколько лет назад в Португалии, а затем на русском в «Самокате» вышла книга об удивительном мире природы— «Шагни за порог. Путеводитель по природе». За ней авторы и издатели решили сделать ответную книгу — про то, как важно заглянуть куда-нибудь внутрь. Но о чем могла бы быть эта книга? О человеческом теле? О тайнах, скрытых в центре Земли? Но больше других авторов вдохновила идея написать книгу о мозге, чтобы помочь самим себе и читателям лучше понять этот удивительный феномен, благодаря которому мы имеем возможность чувствовать, помнить, изучать, сравнивать, принимать решения, действовать, творить... (список глаголов бесконечен). К работе над книгой авторы привлекли большую команду экспертов. Их специализации, регалии, тезисы также перечислены в книге. Также читатели найдут в конце книги и большой список вышедшей на русском литературы о работе мозга, видеолекций, статей и ресурсов на эту тему.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'убийственный-стиль-813'), 'Убийственный стиль', 'Killer Style: The Dark History of Fashion', 'Ubitačni stil', 'Элисон Мэтьюс-Дэвид', 'Alison Matthews David', 'Alison Metjuz-Dejvid', 'Тот, кто стремится быть стильным и модным, подчас подвергает себя смертельной опасности. Не веришь? Прочитай эту книгу, и узнаешь про зеленый цвет — убийцу, про травмы из-за неудобных юбок и обуви, про тех, кто лишился жизни, производя одежду, и о многих других случаях, когда мода калечила людей. В общем, эта книга — предупреждение для всех модников. Для среднего и старшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хильда-и-твиг-прогулка-под-дож-814'), 'Хильда и Твиг, прогулка под дождем', 'Hilda and Twig: Hide from the Rain', 'Hilda i Tvig: Šetnja po kiši', '', 'Luke Pearson', 'Luk Pirson', 'Новая серия о приключениях Хильды и Твига еще до переезда в Тролльберг. История, в которой безобидная прогулка под дождем приносит чешуйчатые неприятности. Кажется, маленькому лисоленю придется набраться храбрости и спасти подругу... Хильда и Твиг не сидят дома, даже если за окном дождь. Каждый день они отправляются исследовать окрестности: скалы, пещеры, водопады... Но однажды прогулку прерывает сильная гроза, и друзьям приходится укрыться внутри таинственного кургана. Твиг быстро понимает: здесь совсем не безопасно. Маленький лисолень никогда не считал себя смельчаком, но теперь ему придется набраться храбрости, чтобы спасти лучшую подругу от больших чешуйчатых неприятностей. Эта история о том, что настоящая смелость — это готовность преодолеть страх ради того, кто тебе дорог. Даже самый осторожный из нас способен на подвиг, если рядом оказался тот, кто нуждается в помощи.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '1-хильда-и-тролль-815'), '1. Хильда и тролль', 'Hilda and the Troll', 'Hilda i trol', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Познакомьтесь с Хильдой - она ни дня не может провести без приключений! Морские духи, великаны, крошечные эльфы, тролли и подозрительные древесные люди - ее окружение никак нельзя назвать обычным. Каждый день Хильда бесстрашно изучает мир, полный истинно скандинавской магии. Но после встречи с каменным троллем события принимают совсем уж неожиданный поворот. Впрочем, как верно говорит сама Хильда - "Такова жизнь искателя приключений". Скорее отправляйтесь в путь вместе с Хильдой и ее питомцем Твигом!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '2-хильда-и-полуночный-великан-816'), '2. Хильда и полуночный великан', 'Hilda and the Midnight Giant', 'Hilda i ponoćni div', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'В новой истории Хильда узнает, что ее дом стоит прямо посреди города невидимых крошечных эльфов. И те требуют, чтобы Хильда с мамой перестали им мешать и покинули долину... Почему люди не могут видеть маленьких эльфов? Что нужно таинственному великану, который каждую ночь приходит к дому Хильды? И на что она пойдет, чтобы добиться справедливости?.. Как всегда в историях про Хильду, вас ждет таинственный и загадочный скандинавский мир, полный невероятных существ, неожиданные повороты событий и непростые вопросы, на которые нужно найти ответы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '3-хильда-и-птичий-парад-817'), '3. Хильда и птичий парад', 'Hilda and the Bird Parade', 'Hilda i parada ptica', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Хильду ждут новые приключения - она погружается в жизнь шумного города Тролльберга. Вдали от волшебных фьордов Хильде предстоит выяснить, сможет ли она быть счастлива в этом непривычном бетонном лесу... Совсем скоро Хильда узнает, что и новый дом полон удивительных сюрпризов и магических созданий. Ведь ее ждет таинственный Птичий парад! Новая книга Люка Пирсона, номинанта премии Айснера, продолжает серию "Хильдафолк", уже снискавшую мировую славу и получившую множество наград.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '4-хильда-и-черный-пес-818'), '4. Хильда и черный пес', 'Hilda and the Black Hound', 'Hilda i crni pas', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'В новой истории Хильда узнает, что Тролльберг хранит еще множество секретов. Жители взволнованы исчезновениями горожан, в округе несколько раз видели огромного черного пса, а Хильда даже у себя дома обнаруживает волшебных существ - вредных, но обаятельных ниссе. Почему по всему городу озорников-ниссе выгоняют из квартир? Куда пропадают вещи? И что за создание бродит вокруг, нагоняя страх на жителей Тролльберга?.. На этот раз Хильде предстоит разгадать настоящую детективную загадку в полном волшебства скандинавском мире.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '5-хильда-и-каменный-лес-819'), '5. Хильда и каменный лес', 'Hilda and the Stone Forest', 'Hilda i kamena šuma', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'Хильда почти не появляется дома - целыми днями она вместе с Тонту и Твигом исследует окрестности Тролльберга, а ее мама всё сильнее за нее волнуется... Напряжение нарастает, когда однажды Хильду вместе с мамой в момент ссоры внезапно забрасывает в загадочный и мрачный каменный лес - на землю троллей! Смогут ли они вдвоем найти путь обратно и вырваться из лап свирепого народа? И можно ли безнаказанно пройти по чужим владениям?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '6-хильда-и-горный-король-820'), '6. Хильда и горный король', 'Hilda and the Mountain King', 'Hilda i Planinski kralj', 'Люк Пирсон', 'Luke Pearson', 'Luk Pirson', 'В пятом томе мы оставили Хильду в очень неожиданной ситуации, и в триумфальном завершении серии ей предстоит выпутаться из нее! Хотя события принимают совсем уж зловещий оборот, герои волшебного мира не изменяют себе - ищут способ мирно разрешить конфликты. Но вот страшный король горных троллей явно настроен крайне сурово... Смогут ли герои вернуть мир в Тролльберг и в компанию своих друзей?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'изобретатели-821'), 'Изобретатели', 'Tatu and Patu''s Marvelous Inventions', 'Tatu i Patu: Čudesni izumi', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Братья Тату и Пату - неутомимые изобретатели. Они приехали из далёкой страны Чудляндии, где всё устроено совсем по-другому. Тату и Пату изучают разные предметы и явления и хотят сделать мир чуточку лучше. Они придумали 14 устройств, которые, несомненно, пригодятся каждому ребёнку! К удобным изобретениям быстро привыкаешь - осторожнее, вдруг вы потом не сможете заходить в комнату без букопугателя или просыпаться без будильно-кормильно-одевального аппарата? Хотите узнать, как они устроены? Скорее открывайте книгу и изучайте!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'идут-на-работу-822'), 'Идут на работу', 'Tatu and Patu at Work', 'Tatu i Patu idu na posao', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Куда так спешат взрослые каждое утро? Может быть, они торопятся за бесплатным мороженым? Тату и Пату должны это выяснить! Оказывается, по утрам взрослые бегут... на работу. Наверное, это ужасно интересно - работать пекарем или парикмахером, журналистом или музыкантом, строителем или пожарным! Любопытства Тату и Пату не занимать, и они решают попробовать себя во всех профессиях, какие только попались им на доске объявлений. Что же из этого выйдет?..');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'супергерои-823'), 'Супергерои', 'Superheroes', 'Superheroji', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Тату и Пату уже давно следят за невероятными приключениями Наномегачеловека. "Вот бы превратиться в супергероев!" - мечтают они, как вдруг - щёлк! - и с помощью пульта управления киберсилой превращаются в Кибертату и Гиперпату! Отважные герои готовы вступить в схватку с суперопасными злодеями и спасти Ваусити от гигантских упаковок, превративших жизнь города в настоящий хаос.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'феноменальная-книга-сказок-824'), 'Феноменальная книга сказок', 'The Phenomenal Book of Fairy Tales', 'Fenomenalna knjiga bajki', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Эта невероятная книга перевернет ваше отношение к чтению сказок! Она предлагает вам не только шесть новейших сказок, но и инструкции по прочтению, разработанные специально к каждой сказке! Не стойте на месте, приступайте к чтению!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вера-у-врача-825'), 'Вера у врача', 'Veera at the Doctor', 'Vera kod ljekara', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Вера собирается в поликлинику на приём к врачу. Могут ли Тату и Пату усидеть дома? Конечно, они отправятся вместе с ней! Ведь им любопытно: что это за место - поликлиника? Зачем туда ходят дети? Врач - он какой: страшный или не очень? В кабинете у врача оказывается столько всего интересного! Здесь можно измерить температуру, рост и вес. Проверить зрение с помощью картинок, а рефлексы - с помощью молоточка. Теперь Тату и Пату знают, что такое стетоскоп, отоскоп и тонометр! Зачем мыть руки перед едой, почему питаться надо правильно, а одеваться по погоде. И самое главное - врачи им теперь не страшны!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вера-на-кухне-826'), 'Вера на кухне', 'Veera in the Kitchen', 'Vera u kuhinji', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Тату и Пату гостят у Веры. Они проголодались, но на кухню идти боятся: кажется, там много опасных предметов. Да и готовить они пока не умеют... Но научиться не так уж и сложно! Вера знает, как обращаться с электроплитой, умеет выбирать нужные продукты и готовить с помощью рецепта. До ужина друзья успеют замесить тесто, приготовить начинку, испечь пиццу и изучить правила поведения за столом. Они познакомятся со множеством кухонных предметов, узнают названия приправ, научатся делать уборку на кухне и даже сервировать стол! Не забывая при этом шалить и веселиться. Ведь вместе веселее и готовить, и учиться, и шутить. И, конечно же, ужинать!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'невероятный-новый-год-827'), 'Невероятный новый год', 'Tatu and Patu''s Incredible New Year', 'Tatu i Patu: Nevjerovatna Nova godina', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Кто бы мог подумать, что братья перепутают дом? Не найдя Веры, Тату и Пату решают, что пришли на день раньше, и начинают готовиться к празднику! Что же они успеют натворить и какие сюрпризы их ждут? Поймут ли они, что пришли не туда? Скорее открывайте книгу, вас ждёт невероятное новогоднее приключение!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'детективы-дело-о-половинщике-828'), 'Детективы: дело о половинщике', 'Tatu and Patu, Detectives: The Case of the Halfer', 'Detektivi Tatu i Patu: Slučaj prepolovljivača', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'В семье Нико, старого знакомого Тату и Пату, происходят странные вещи. Сначала исчезла половина папиного бифштекса, а затем оказалось, что ополовиниться может что угодно: новые ползунки, чехол для телефона и даже макияж! Как это могло произойти? И кто за этим стоит? Разумеется, Тату и Пату не бросают друзей в беде и берутся расследовать тёмное дело! Тем более что они - настоящие профессионалы, мастера частного сыска и гении маскировки! Для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-детском-саду-829'), 'В детском саду', 'Tatu and Patu at Kindergarten', 'Tatu i Patu u vrtiću', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Тату и Пату собираются в аквапарк. Но случайно спутав названия, попадают в детский сад по соседству. Вы думаете, братья расстроились? Ничего подобного! Грязевые ванны в песочнице, игры и танцы, дневной сон после сытного обеда и репетиция праздничного спектакля - оказывается, в детском саду ещё как интересно и весело! Книги о Тату и Пату - одна из самых популярных книжных серий в Финляндии, на родине её авторов. Захватывающие и смешные истории о приключениях братьев-чудиков отмечены множеством литературных наград и не оставят равнодушным ни одного читателя!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'жизнь-и-творчество-830'), 'Жизнь и творчество', 'Tatu and Patu: Life and Works', 'Tatu i Patu: Život i djelo', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Уважаемые читатели, вы держите в руках необычное издание. Эта книга рассказывает не только о невероятных приключениях братьев из Чудляндии, но и об их происхождении! Пришло время приоткрыть завесу тайны. Причудливо ли чудляндское детство? Как Тату и Пату стали исследователями и изобретателями? Что такое состояние чудофории? Где находится загадочная Чудляндия? И как из двух маленьких чудляндцев смогли вырасти такие популярные личности? Это издание знакомит читателей как с детски ми годами и бурной молодостью знаменитых братьев, так и с трудностями и достижениями последних лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'инструкция-по-засыпанию-831'), 'Инструкция по засыпанию', 'Instruction Manual for Falling Asleep', 'Uputstvo za uspavljivanje', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Обязательно для прочтения каждому, кто любит спать (или нет) В гости к Тату и Пату приходит племянница Соня, и братья придумывают тысячу разных способов, как уложить малышку спать. Они даже составили специальный справочник: в нём рассказано, как выбрать идеальную игрушку для засыпания, что произойдёт, если долго не ложиться спать, почему родителям можно не спать до поздней ночи, а детям - нет, и многое другое. Хотите погрузиться в мир сноучения и дремотологии? Перед вами самая полная инструкция по засыпанию!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пора-обедать-832'), 'Пора обедать', 'Tatu and Patu: Time to Eat!', 'Tatu i Patu: Vrijeme je za ručak!', 'Айно Хавукайнен, Сами Тойвонен', 'Aino Havukainen, Sami Toivonen', 'Aino Havukainen, Sami Toivonen', 'Какие продукты чаще всего разливаются и разбрызгиваются? Что за проблемы возникают во время приготовления бутерброда? Каковы отличительные признаки большого мешалочника? Что такое древние вкусовые искусства? Ответить на эти вопросы способны только Тату и Пату! Братья из Чудляндии подготовили для вас свыше ста страниц - одна смешнее другой! А также тесты - несколько промежуточных и один заключительный.Только для наружного применения. Подходит взрослым и детям. Легко читается и легко усваивается.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пункт-назначения-луна-833'), 'Пункт назначения-луна', 'Destination Moon', 'Odredište Mjesec', 'Эрже', 'Hergé', 'Hergé', 'Тинтин - один из самых любимых персонажей, о его приключениях написано более 20 историй, автором которых является знаменитый бельгийский художник комиксов Эрже. Истории переведены на десятки языков и расходятся многомиллионными тиражами по всему миру. Американский режиссёр Стивен Спилберг по их мотивам снял художественный фильм "Приключения Тинтина. Тайна "Единорога"". Наш приятель бельгийский репортёр Тинтин снова попадает в очередную авантюру. Да ещё какую! Всё началось с загадочной телеграммы от знакомого профессора, в которой он приглашает Тинтина и его постоянного спутника во всех путешествиях капитана Хэддока в Сильдавию. В этой стране Тинтин уже был однажды и помог раскрыть заговор против её короля. Но что же на этот раз? Оказалось, профессор занимается подготовкой полёта… на Луну. И Тинтину вместе с капитаном Хэддоком предстоит составить ему компанию в этой рискованной экспедиции…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сломанное-ухо-834'), 'Сломанное ухо', 'The Broken Ear', 'Slomljeno uvo', 'Эрже', 'Hergé', 'Erže', 'Тинтин - один из самых любимых персонажей, о его приключениях написано более 20 историй, автором которых является знаменитый бельгийский художник комиксов Эрже. Истории переведены на десятки языков и расходятся многомиллионными тиражами по всему миру. Американский режиссёр Стивен Спилберг по их мотивам снял художественный фильм "Приключения Тинтина. Тайна "Единорога"". Из Этнографического музея похищен ценный экспонат - идол южноафриканского племени арумбайя. Но на следующее утро экспонат был обнаружен на прежнем месте в музее. Казалось бы, всё в порядке, если бы не маленькая деталь: у настоящего идола одно ухо повреждено, а ухо возвращённого абсолютно целое. Значит, это подделка! Но тогда где подлинник? Кто его украл? И самое главное - какую тайну хранит этот загадочный идол? Тинтин решает найти ответы на все эти вопросы…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'таинственная-звезда-835'), 'Таинственная звезда', 'The Shooting Star', 'Tajanstvena zvijezda', 'Эрже', 'Hergé', 'Erže', 'Молодой репортёр Тинтин, любитель приключений, опять попадает в историю! Всё началось с… конца света, который предсказал некий пророк Филиппулус. Но конца света не случилось, зато случилось кое-что другое - где-то в Северном Ледовитом океане упал метеорит, содержащий неизвестный науке металл. Это же сенсация! Срочно организуется экспедиция, и Тинтин с группой учёных отправляется в плавание, которое превращается в настоящую гонку. Кто же пытается опередить их и добраться до метеорита первым?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-стране-черного-золота-836'), 'В стране черного золота', 'Land of Black Gold', 'U zemlji crnog zlata', 'Эрже', 'Hergé', 'Herže', 'Тинтину, молодому бельгийскому репортёру, скучать не приходится! Вот и на этот раз намечается кое-что любопытное. А дело вот в чём. С некоторых пор странная "эпидемия" распространилась среди автомобильных моторов: они взрываются без всякой видимой причины. Владельцы машин в панике, продажи горючего резко упали, нефтяные скважины закрываются… Неужели всё дело в качестве бензина? А может, это диверсия? Тинтину здесь есть над чем поломать голову…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рейс-714-на-сидней-837'), 'Рейс 714 на Сидней', 'Flight 714 to Sydney', 'Let 714 za Sidnej', 'Эрже', 'Hergé', 'Erže', 'В каких только передрягах не оказывался юный репортёр Тинтин, где он только не побывал! И в гробнице фараона, и на таинственном Чёрном острове, и в пекле пустыни Сахары, и в диком африканском племени, и даже на Луне! Но вот в жерле дремавшего сотни лет и вдруг пробудившегося вулкана - такого он не припомнит. А всё началось с конференции по астронавтике в Сиднее, на которую Тинтин направлялся вместе с капитаном Хэддоком и профессором. Вот так поворот!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'драгоценности-катастфьоре-838'), 'Драгоценности Катастфьоре', 'The Castafiore Emerald', 'Kastafjorini dragulji', 'Эрже', 'Hergé', 'Erže', 'Однажды в замок Муленсар, принадлежавший капитану Хэддоку, приехала погостить Бьянка Кастафьоре - известная оперная дива, давняя знакомая Тинтина и капитана. И надо же было такому случиться - прямо из её комнаты пропал ценнейший изумруд, подарок махараджи Гопала. Под подозрением оказались все обитатели замка. И кто взялся за расследование? Конечно, Тинтин! Но каково же было его изумление, когда наконец он понял, ктo скрывался под маской вора…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пикаросы-839'), 'Пикаросы', 'Tintin and the Picaros', 'Tintin i Pikarosi', 'Эрже', 'Hergé', 'Erže', 'Невероятно! Тинтина и его друзей обвиняют в заговоре против генерала Тапиоки! Кроме того, выясняется, что арестовали Бьянку Кастафьоре и двух Дюпонов, давних знакомых Тинтина. Юный репортёр намерен вернуть себе честное имя и выручить из беды друзей, но для этого ему надо понять, при чём здесь пикаросы - партизаны, которые хотят свергнуть ненавистного им Тапиоку и его режим. Похоже, Тинтину пора снова собираться в путь, на этот раз в Латинскую Америку.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дело-профессора-840'), 'Дело профессора', 'The Calculus Affair', 'Slučaj profesora Turnesola', 'Эрже', 'Hergé', 'Erže', 'В замке Муленсар, имении капитана Хэддока, начали происходить необъяснимые события - вдребезги разлетаются прямо в руках чашки и стаканы, трескаются зеркала, от окон остаются лишь мелкие осколки, а драгоценные старинные вазы превращаются в груду черепков... Обитатели замка в панике. Юный бельгийский репортёр Тинтин, который всегда готов к любым авантюрам, подозревает, что разгадка кроется в загадочных экспериментах профессора, его давнего знакомого...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'акулы-красного-моря-841'), 'Акулы красного моря', 'The Red Sea Sharks', 'Ajkule Crvenog mora', 'Эрже', 'Hergé', 'Erže', 'Куда же на этот раз приведёт неуёмная жажда приключений молодого бельгийского репортёра Тинтина? А привела она юношу в далёкую страну, на родину его давнего знакомого — эмира Бен Калиш Эзаба. Казалось, приключение обещает быть захватывающим, и Тинтин, как всегда, готов к любому повороту событий. В каких только авантюрах он не бывал! Но вот с чем ему ещё не доводилось сталкиваться, так это с… работорговлей. Неужели эта дикость ещё где-то существует?..');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '7-хрустальных-шаров-842'), '7 хрустальных шаров', 'The Seven Crystal Balls', 'Sedam kristalnih kugli', 'Эрже', 'Hergé', 'Erže', 'Сенсация! Европейские учёные, исследовавшие малоизученные территории Перу и Боливии, обнаружили и вскрыли гробницу Великого Инки! И сразу с ними стало происходить нечто необъяснимое - все они, один за другим, впадали в летаргический сон. Неужели это месть Великого Инки за осквернение гробницы? Тинтина очень заинтересовала эта история, а когда похитили его знакомого профессора, он понял, что два события связаны между собой, и отправился на поиски в Южную Америку…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'храм-солнца-843'), 'Храм солнца', 'Prisoners of the Sun', 'Hram sunca', 'Эрже', 'Hergé', 'Erže', '"Храм Солнца" - продолжение книги "7 хрустальных шаров", в которой рассказывается о загадочных происшествиях, случившихся с европейскими учёными в Южной Америке, и о странном исчезновении знаменитого профессора. Юный репортёр Тинтин в компании капитана Хэддока и верного пса Снежка отправляется на поиски профессора. Им предстоит преодолеть немало трудностей, порой опасных для жизни. Но самое невероятное путешественников ждёт в конце пути, когда они неожиданным образом попадают в храм Солнца…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-америке-844'), 'в Америке', 'Tintin in America', 'Tintin u Americi', 'Эрже', 'Hergé', 'Erže', 'Тинтин продолжает борьбу с мощнейшим преступным синдикатом - чикагской бандой, которая пыталась взять под контроль добычу алмазов в Африке. Юному бельгийскому репортёру всё-таки удалось нарушить планы гангстеров! Судьба привела его в Чикаго, именно тут Тинтин намерен поставить точку в этом запутанном и очень опасном деле. Не раз он, преследуя бандитов, оказывался на краю гибели. Так неужели ему повезёт и с мафией будет покончено?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-конго-845'), 'в Конго', 'Tintin in the Congo', 'Tintin u Kongu', 'Эрже', 'Hergé', 'Erže', 'Известный своими авантюрными приключениями молодой бельгийский репортёр Тинтин отправился в путешествие по Африке. Но он даже не предполагал, чем это для него обернётся! Разве Тинтин мог подумать, что окажется в центре хитроумной операции короля чикагских гангстеров, который намеревался взять под контроль добычу алмазов в Африке? Юноша встал у бандита на пути, и его решили убрать… Чем же закончатся африканские приключения репортёра?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'скипетр-оттокара-846'), 'скипетр Оттокара', 'King Ottokar''s Sceptre', 'Žezlo kralja Otokara', 'Эрже', 'Hergé', 'Erže', 'Молодой репортёр Тинтин случайно знакомится с профессором Мудрено, специалистом по сигиллографии – науке, занимающейся изучением печатей. Профессор намерен отправиться в далёкую страну Сильдавию для дальнейшей исследовательской работы, и Тинтин едет с ним. И вот тут начинают происходить странные события, которые наводят репортёра на мысль: против короля Сильдавии готовится заговор. К тому же оказывается, что похищен главный символ королевской власти государства – скипетр…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'путешественники-на-луне-847'), 'путешественники на Луне', 'Explorers on the Moon', 'Istraživači na Mjesecu', 'Эрже', 'Hergé', 'Erže', 'В этой книге - продолжение приключений Тинтина и его постоянных спутников - капитана Хэддока и забавного пса Снежка. Читатель уже знаком с тем, как начались эти, пожалуй, самые рискованные, самые грандиозные приключения троицы, они описаны в книге "Пункт назначения - Луна". Так вот, полёт на эту далёкую планету всё-таки состоялся! Что ждёт путешественников там? Какие опасности их подстерегают? И главное - вернутся ли они на Землю? А это, как выяснилось, проблема…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-тибете-848'), 'в Тибете', 'Tintin in Tibet', 'Tintin na Tibetu', 'Эрже', 'Hergé', 'Erže', 'Произошла катастрофа – самолёт, летевший в Катманду, потерпел крушение где-то в районе горного массива. Молодой бельгийский репортёр Тинтин с ужасом узнаёт, что в самолёте находился его китайский друг Чан. Неужели он погиб?! Юноша отказывается в это верить, тем более ему приснился сон, в котором Чан, находясь в снежной западне, просит о помощи. Пусть это всего лишь сон и Чана наверняка уже нет в живых, Тинтин всё-таки решает отправиться на его поиски…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'секрет-единогрога-849'), 'Секрет единогрога', 'The Secret of the Unicorn', 'Tajna Jednoroga', 'Эрже', 'Hergé', 'Erže', 'Однажды Тинтин на блошином рынке купил модель великолепного старинного корабля, носящего гордое имя "Единорог". "Неплохой подарок!" - подумал он, намереваясь преподнести корабль своему другу, капитану Хэддоку, бывалому морскому волку. Но… корабль похитили! Бросившись на его поиски, Тинтин с капитаном убеждаются, что это не простое ограбление: слишком много тайн с ним связано, слишком много вопросов. И самое главное - какую роль во всём этом играет пергаментный свиток, обнаруженный в мачте "Единорога"?..');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'краб-с-золотыми-клешнями-850'), 'Краб с золотыми клешнями', 'The Crab with the Golden Claws', 'Rak sa zlatnim kliještima', 'Эрже', 'Hergé', 'Erže', 'Очередные захватывающие приключения молодого репортёра Тинтина не заставили себя долго ждать. Иначе и быть не могло - у этого юноши поразительный нюх на всякого рода авантюры. Погони, перестрелки, опасные путешествия и даже долгий, изнурительный переход пустыни Сахары! Отважный Тинтин ни перед чем не остановится, чтобы обезвредить преступную группировку, которая занимается распространением опиума, спрятав его в консервных банках из-под краба. Но противник слишком хитёр и коварен. Что же предпримет Тинтин на этот раз?.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сокровище-красного-ракхама-851'), 'сокровище красного ракхама', 'Red Rackham''s Treasure', 'Blago Crvenog Rakama', 'Эрже', 'Hergé', 'Erže', 'Наконец-то Тинтин и его друг капитан Хэддок выяснили, какую тайну хранит старинный пергаментный свиток, обнаруженный в мачте корабля "Единорог"! Впоследствии оказалось, что свитков на самом деле было три! Собрав их вместе, друзья поняли, что в них зашифрованы координаты места, где находится сокровище Красного Ракхама - предводителя пиратов. Но до него не так-то просто добраться. Тинтин и капитан смело отправляются в опасное путешествие, которое обещает стать невероятно захватывающим приключением!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'голубой-лотос-852'), 'голубой лотос', 'The Blue Lotus', 'Plavi lotos', 'Эрже', 'Hergé', 'Erže', 'Приключения Тинтина продолжаются! В книге «Сигары фараона» молодому репортёру удалось разоблачить международное преступное сообщество, занимавшееся контрабандой наркотиков. Казалось бы, дело закрыто. Но не тут-то было – после прибытия Тинтина в Шанхай на него вновь начинают охоту члены преступной группировки. С этого момента репортёр попадает в водоворот невероятных событий и захватывающих приключений, пытаясь выяснить, кто же всё-таки стоит во главе сети торговцев наркотиками.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'астерикс-из-галлии-853'), 'Астерикс из Галлии', 'Asterix the Gaul', 'Asteriks Gal', 'Госини, Удерзо', 'René Goscinny, Albert Uderzo', 'Rene Gosini, Alber Uderzo', 'АСТЕРИКС и ОБЕЛИКС – пожалуй, самые знаменитые герои комиксов, об их приключениях написано более 30 историй, авторами которых являются известный французский писатель Рене Госинни и его соотечественник художник Альбер Удерзо.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'астерикс-и-транситалика-854'), 'Астерикс и транситалика', 'Asterix and the Chariot Race', 'Asteriks i Transitalika', 'Госини, Удерзо', 'René Goscinny, Albert Uderzo', 'Rene Gosini, Alber Uderzo', 'Состояние римских дорог вызывает у народов Италии всё больше нареканий... Однако сенатор Лакт Бактерий, отвечающий за дорожную сеть, не намерен признавать очевидное: он устраивает невиданную доселе гонку колесниц через весь полуостров! К участию приглашаются экипажи со всего известного мира... Само собой, галлы из деревни неукротимых не могли остаться в стороне от такого события! Но у Юлия Цезаря другие планы: в гонке во что бы то ни стало должен победить представитель Рима.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кот-в-шляпе-855'), 'Кот в шляпе', 'The Cat in the Hat', 'Mačak u šeširu', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Seuss', 'Вы слышали про Доктора Сьюза? Он пишет детские стихи и сказки, сам рисует к ним картинки и даже умеет делать мультики. Его книги переведены на множество языков и вот уже несколько десятков лет расходятся миллионными тиражами. Между прочим, Доктор Сьюз самый продаваемый в мире англоязычный автор книжек для малышей. По его стихам снимались мультфильмы, ставились мюзиклы и радиоспектакли, его именем названа престижная литературная премия, а в Америке есть целый парк со скульптурами его героев. Многие поколения детей выросли бок о бок с добродушным слоном Хортоном, котом в шляпе и Гринчем, зловредным похитителем Рождества. Предположим, сидите вы дома с младшей сестрёнкой. День — скучнее не придумаешь. За окном дождик, и заняться решительно нечем. И тут на вашем пороге объявляется… КОТ В ШЛЯПЕ! Говорящими котами нынче никого не удивишь, но этот-то к тому же ещё и редкостный озорник, затейник и фокусник. И чего он только не выделывает! Всё у него в лапах ходит ходуном, а дом переворачивается вверх дном. Вашей скуки как не бывало! Только вот что скажет на всё это мама, когда вернётся?..');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дриад-856'), 'Дриад', 'The Lorax', 'Loraks', 'Доктор Сьюз', 'Dr. Seuss', 'Dr Sus', 'Познакомьтесь же и вы с замечательными героями этих книг! Например, с чудесным Дриадом. Однажды, давным-давно в прекрасной роще пуховых пальм, населённой удивительными зверюшками, каких больше нигде не встретишь, жил-поживал добрый Дриад. Но однажды пропал, вместе с дивной рощей и сказочным зверьём. Что же случилось, где они теперь и как их вернуть? Всё расскажет нелюдимый Мак-Глот…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хортон-высиживает-яйцо-857'), 'Хортон высиживает яйцо', 'Horton Hatches the Egg', 'Horton leži na jajetu', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Seuss', 'Птичке Мэйзи надоело высиживать яйцо. Легкомысленная особа эта Мэйзи — подавай ей отпуск, и всё тут! Раз такое дело, необходимо найти того, кто согласится вместо неё посидеть на гнезде. И оглядевшись по сторонам, Мэйзи обнаруживает… слона Хортона! Почему бы и нет? Слон, конечно, не птичка, но он такой добрый и заботливый! Решено: Мэйзи уговаривает Хортона занять своё место на гнезде, а сама улетает прохлаждаться в Майами. Хортон же отнёсся к делу со всей ответственностью... Что из этого вышло, читайте в книжке Доктора Сьюза!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'это-только-начало-858'), 'Это только начало', 'Oh, the Places You''ll Go!', 'Mjesta na koja ćeš stići!', 'Доктор Сьюз', 'Dr. Seuss', 'Doktor Sus', 'Представьте, что сегодня самый замечательный в мире день. День, когда можно выбрать что угодно и пойти куда угодно — все пути открыты, нужно только немножко решимости! Ведь если есть голова на плечах и две ноги в башмаках, значит, никакие тупые тупики, глухие заборы и окна без света не страшны. Эта книжка Доктора Сьюза, которую вы держите в руках, — лучшее на свете напутствие. Берите его — и вперёд! Ведь это только начало!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хортон-слышит-ктошку-859'), 'Хортон слышит ктошку', 'Horton Hears a Who!', 'Horton čuje Koga!', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Seuss', 'Однажды в джунглях Чавка слон Хортон услышал странный звук. Как-будто кто-то очень маленький – такой маленький, что уже невидимый! – звал на помощь. Конечно, Хортон не мог остаться в стороне. И отзывчивость великодушного слона спасла целый Ктошкоград!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'с-днем-рождения--860'), 'С днем рождения!', 'Happy Birthday to You!', 'Srećan rođendan!', 'Доктор Сьюз', 'Dr. Seuss', 'Dr. Sus', 'А с Деньрожденной Птицей хотите познакомиться? С ней вы можете попасть в сказочную страну Трубению, где день рождения празднуют с неслыханным размахом! Или даже не дожидаясь этого дня, прямо сейчас пуститься в волшебное приключение!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вот-ужас--861'), 'Вот ужас!', 'The Book of Spooks', 'Kakva strava!', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Приведения и домовые, ужасный снежный человек и мумия фараона, граф Дракула и ведьма тётушка Кривонос… Вот Ужас! Кто ещё прячется в этой книге? Но не бойтесь, она вовсе не страшная - ведь каждая история Маури Куннаса сдобрена юмором и обязательно хорошо заканчивается.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'веселые-машинки-862'), 'Веселые машинки', 'Funny Cars', 'Veseli automobili', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Грузовики, фургоны, электромобили, гоночные машины, драгстеры, пожарные машины, автобусы, мусоровозы, мотоциклы, джипы... В этой книге есть все средства передвижения от бабушкиного кабриолета до самого суперсовременного автомобиля на солнечных батареях. А это кто там на заправочной станции? Уж не Красная ли Шапочка с Серым Волком? А кто плачет в темноте подземной парковки? Гензель и Гретель? Маури Куннас рассказывает об их приключениях в своей неподражаемой манере, на радость всем юным автомобилистам перенося в мир машин героев известных сказок: "Три желания", "Гензель и Гретель", "Красная Шапочка", "Три брата" и "Золушка".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рождественские-истории-863'), 'Рождественские истории', 'Christmas Stories', 'Božićne priče', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Красочные, весёлые и захватывающие рождественские истории Маури Куннаса теперь собраны под одной обложкой! Выбирай подарки с гномом Вилле, попробуй поймать хитрого шамана и, конечно, загляни в гости к самому Санта-Клаусу! Скорее открывай эту книгу - и вперёд в деревню Корватунтури!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'марта-на-колядках-864'), 'Марта на колядках', 'Martha Goes Caroling', 'Marta ide u koledare', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Накануне Рождества Марта и мама покидают Пёсью горку и отправляются в город навестить родных. Что за чудесная пора! На улицах разворачивается рождественское представление! Жители города собрались посмотреть, как школьники будут разыгрывать традиционные сценки из репертуара народного театра. Туомас нарядился мавританским царём, Матиас - царём Иродом, а Август несёт настоящую рождественскую звезду! Петух часовщика чуть было не сорвал представление, но горожане не дали артистов в обиду. Жители городка подпевали и аплодировали юным актёрам и разошлись по домам только тогда, когда на небе зажглись тысячи звёзд. А вам знакомы эти песни? Если нет, скорее открывайте эту книгу! В ней вы найдёте ноты, тексты песен, весёлую историю и неповторимую уютную атмосферу зимнего праздника!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'водяной-на-песьей-горке-865'), 'Водяной на песьей горке', 'The Water Spirit of Doghill', 'Vodenjak na Psećem brdu', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'На Пёсьей горке любят рассказывать страшные истории. Про леших, домовых, призраков и лесных разбойников. Правда, иногда на поверку оказывается, что злая ведьма - это всего лишь соседская старушка, а водяной - переодевшийся работник Юсси… Но зато все лешие и призраки - самые настоящие! Не верите? Прочтите книгу Маури Куннаса - и убедитесь сами !');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'зима-на-песьей-горке-866'), 'Зима на песьей горке', 'Winter at Doghill', 'Zima na Pasjem brdu', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'На Пёсьей горке наступила зима, а вместе с ней - новые заботы. Жизнь на ферме наполнена трудом. Целыми днями не прекращается работа в лесу и хлеве, вечера проходят за рукоделием и домашними хлопотами под рассказы долгожителей. Иногда будни уступают место праздникам, и тогда на Пёсьей горке пируют и веселятся от всего сердца. О старых временах редко пишут столь увлекательно и красочно, как в серии книг Маури Куннаса. Весёлые и правдивые истории будет интересно почитать детям и взрослым.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'господин-хакарайнен-считает-ов-867'), 'Господин Хакарайнен считает овец', 'Mr. Clutterbuck Counts Sheep', 'Gospodin Hakarajnen broji ovce', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'В этой книге ты познакомишься с множеством забавных персонажей. Сколько их на самом деле? Отважный господин Хаккарайнен снова гуляет во сне. Он встречает пять диких ковбоев, десять лающих собак и целых двенадцать милых привидений... Скорее отправляйся в путешествие вместе с господином Хаккарайненом и научись считать от одного до двадцати!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'господин-хакарайнен-заблудился-868'), 'Господин Хакарайнен заблудился', 'Mr. Hakkarainen Gets Lost', 'Gospodin Hakarainen se izgubio', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'Господин Хаккарайнен - большой любитель увлекательных прогулок. Он уже побывал в парке развлечений, в цирке Буффало Билла, и даже в Шервудском лесу. Одна беда - гулять господин Хаккарайнен предпочитает… во сне. Неудивительно, что однажды он заблудился! Теперь господину Хаккарайнену нужна твоя помощь. Скорее открывай эту книгу - внутри тебя ждёт множество интересных заданий! А справиться с ними помогут воображение и внимательность.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'спокойной-ночи-господин-хаккар-869'), 'Спокойной ночи, господин Хаккарайнен', 'Good Night, Mr. Hakkarainen', 'Laku noć, gospodine Hakarainen', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Господин Хаккарайнен сам не знает того, что каждую ночь он отправляется в лунатическом сне на прогулку. Он становится рок-звездой, примиряет враждебные группировки байкеров, танцует на рельсах, спасает мясокомбинат от разорения и даже задерживает преступницу. Всё это - не просыпаясь! Узнает ли он в конце концов о своей ночной жизни? Или только верная морская свинка Маса останется свидетелем его невероятных приключений? Об этом расскажут смешные истории в картинках от Маури Куннаса.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хобби-господина-хаккарайнена-870'), 'Хобби господина Хаккарайнена', 'Mr. Clutterbuck''s Hobbies', 'Hobiji gospodina Hakarainena', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Танцы, велопрогулки, скейтборд, кросс, дайвинг, шахматы, кулинария… Чтение, рукоделие, сочинение стихов, спортивное ориентирование… Фотография, музыка, прыжки с парашютом, коллекционирование самых невероятных предметов от башмаков до старых электробритв!.. Сколько увлечений существует на свете! Все вокруг чем-то заняты и увлечены! И только господин Хаккарайнен не знает, есть ли у него хобби. Знаменитый лунатик каждую ночь отправляется на поиски своего призвания, нарушая спокойствие маленького городка. И… конечно же, призвание будет найдено! Наконец-то господин Хаккарайнен обнаружит, какое дело для него - самое любимое. Теперь жители городка вздохнут с облегчением и смогут спокойно выспаться!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '7-чудес-господина-хаккарайнена-871'), '7 чудес господина Хаккарайнена', 'Mr. Clutterbuck''s Seven Wonders', '7 čuda gospodina Hakarajnena', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Господин Хаккарайнен в компании морской свинки Масы и группы туристов отправляется в путешествие. Египетские пирамиды, остров Пасхи, Ниагарский водопад - ему предстоит посетить самые удивительные уголки земного шара! Не менее удивительны и приключения, которые ждут господина Хаккарайнена и его спутников. Ведь когда Хаккарайнен засыпает, начинается всё самое интересное. Никто не знает, куда заведёт его лунатический сон и что он вытворит на этот раз: совершит хулиганство или доброе дело, потрясёт публику акробатическим номером или сделает важное научное открытие.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'викинги-идут--872'), 'Викинги идут!', 'The Vikings Are Coming!', 'Vikinzi dolaze!', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Викинги были отважными мореходами и свирепыми разбойниками. Они плавали на кораблях с драконьими головами и наводили страх на мирных жителей прибрежных районов. А ещё они верили в дерево Иггдрасиль, на которое нанизаны разные миры, мечтали после смерти попасть в Вальгаллу и слагали саги обо всём, что происходило в их жизни. Маури Куннас, живой классик финской детской литературы, сочиняет и иллюстрирует саги, благодаря которым даже малыши поймут, кто же такие были эти викинги. Средневековую Скандинавию Куннаса населяют доблестные собаки, находчивые коты, флегматичные кабаны, свирепые волки и незадачливые барсуки. Коренные жители Америки - еноты с непереносимостью лактозы, а Константинополем правит бегемот. Помимо уморительно смешных сказок-саг в книгу включены описания кораблей, жилищ и городов викингов, перечень скандинавских богов, карта известного викингам обитаемого мира и примерная схема мироустройства по-викингски.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'на-диком-западе-873'), 'На диком Западе', 'In the Wild West', 'Na Divljem zapadu', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunas', 'Маури Куннас переносит нас на Дикий Запад, который населяют смелые ковбои, отважные шерифы, настойчивые золотоискатели, мудрые индейцы, а также отчаянные грабители и бандиты! Здесь неожиданно богатеют, кутят в салунах и лихо скачут по прериям. А истории про местных героев печатают в газете "Правдивые вести Запада". Самые весёлые и захватывающие из них собраны в этой книге!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'остров-сокровищ-874'), 'Остров сокровищ', 'Treasure Island', 'Ostrvo s blagom', 'Маури Куннас', 'Mauri Kunnas', 'Mauri Kunnas', 'Неожиданно в руки Джима и его мамы попадает карта капитана Флинта, с помощью которой можно отыскать сокровища, зарытые на необитаемом острове. Прощай, спокойная мирная жизнь! Впереди героев и их друзей ждут морское путешествие и путь к сокровищам, полный приключений и опасностей! Ведь за картой сокровищ давно охотятся одноногий Джон Сильвер и целая команда пиратов! На чьей стороне окажется правда - расскажет Маури Куннас в своём весёлом иллюстрированном переложении известнейшего романа шотландского писателя Роберта Льюиса Стивенсона "Остров сокровищ".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'груффало-875'), 'Груффало', 'The Gruffalo', 'Grozon', '', 'Julia Donaldson', 'Džulija Donaldson', '"- Какое еще груффало? Мышонок, ты о ком? - О, это очень крупный зверь, я с ним давно знаком..." Чтобы спастись от лисы, совы и змеи маленький мышонок выдумывает страшного груффало - зверя, который очень любит есть лис, сов и змей. Но сможет ли находчивый мышонок перехитрить всех голодных хищников? Ведь он-то хорошо знает, что никаких груффало не бывает... Или бывает? Сегодня трудно представить, что раньше никаких груффало не было. Со дня первого издания в Англии, в 1999 году, уже 26 миллионов книг о страшном звере с лиловыми шипами на спине нашли своих хозяев по всему миру, а сам герой говорит на 86 иностранных языках. Русскому же Груффало исполняется 15 лет. С днём рождения, Груффало! Сказка в стихах для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тимоти-скотт-876'), 'Тимоти Скотт', 'Tabby McTat', 'Tabi MekTet', '', 'Julia Donaldson', 'Džulija Donaldson', 'Тимоти Скотт, музыкальный кот,С гитаристом по имени ФредПели на улицах круглый год.К ним отовсюду сбегался народИ не жалел монет....Но однажды, пока Тимоти не было рядом, на шляпу с деньгами нацелился вор, схватил её - и наутёк. Фред кинулся вслед и... так два друга потерялись.Встретятся ли они когда-нибудь?Это лиричная, трогательная и смешная история о верной и мур-раз-лучной дружбе, написанная авторами знаменитого "Груффало".Для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'верхом-на-помеле-877'), 'Верхом на помеле', 'Room on the Broom', 'Mjesto na metli', '', 'Julia Donaldson', 'Džulija Donaldson', '""У ведьмы был кот, / полосатый толстяк, / рыжая коса / и высокий колпак..."" Ведьма мчит по небу на помеле и роняет на землю колпак, волшебную палочку и бантик с рыжей косы. Все это по очереди находят пес, птичка и лягушонок и просят в награду за службу прокатить их на помеле, что ведьма охотно и делает. Но метла ломается: кот, пес и лягушонок падают в болото, а ведьма попадает в лапы дракона; тот уже собирается съесть колдунью на ужин, как вдруг появляется жуткий, грозный зверь - чудище болот - и требует отдать ведьму ему... Куда пропали пес, кот и лягушонок? Что случилось с птичкой и что теперь станет с ведьмой? - читайте еще одну полную сюрпризов, красочную и обаятельную книжку от авторов ""Груффало"".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'человеткин-878'), 'Человеткин', 'Stick Man', 'Prutko', '', 'Julia Donaldson', 'Džulija Donaldson', 'Одним весенним днём Человеткин отправился на пробежку, но был схвачен собакой, которая приняла его за обыкновенную палку. Дети играли и бросили его в реку, а лебедь увидел в нем прутик дня гнезда. Осень сменит лето, придёт снежная зима - горемычный Человеткин перебывает мачтой для флага, шпагой, клюшкой, бумерангом, рукой для снеговика. Неужели он никогда не вернется домой, к челодеткам? Стихи из книги: – Нет! Я не палка! Пусти меня! Стой! Я ЧЕЛОВЕТКИН, разумный, живой! Я Человеткин, мне нужно домой!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'новый-наряд-великана-879'), 'Новый наряд великана', 'The Smartest Giant in Town', 'Najotmjeniji div u gradu', '', 'Julia Donaldson', 'Džulija Donaldson', '"Великану Джорджу очень хотелось принарядиться. И как только в городе открылся магазин гигантской одежды, он поспешил туда. Белоснежная рубашка, фасонистые брюки, блестящие ботинки, пёстрый галстук и носки с ромбиками - как приятно чувствовать себя нарядным и красивым! Но по дороге домой Джорджу встречаются жираф - кроткий нрав, пес - чуткий нос, орава мышат-малышат и козлик в маленькой лодке с мачтой в середке. Все эти звери попали в беду и им очень нужна помощь Джорджа… и его новые вещи! Написанная пружинистой прозой и стихами, это история о добром малом, который был богат не щегольским нарядом, а щедрым сердцем.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хочу-к-маме--880'), 'Хочу к маме!', 'Monkey Puzzle', 'Gdje je moja mama?', '', 'Julia Donaldson', 'Džulija Donaldson', 'Сможет ли мотылёк помочь мартышке найти маму? Да, но только после многих проб и ошибок, ведь приметы всё время приводят их к "неправильным" зверям. Это познавательная, весёлая, добрая и красочная как сами джунгли книга, написанная авторами знаменитого Груффало. Сказка в стихах для чтения взрослыми детям. Информационная продукция для детей, не достигших возраста шести лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тюлька-881'), 'Тюлька', 'Tiddler', 'Ribica Tili', '', 'Julia Donaldson', 'Džulija Donaldson', '"Жила на свете Тюлька, малюсенькая рыбка/Простая рыбка в сером чешуйчатом пальто… Рыбка Тюлька каждое утро опаздывает в школу и всякий раз под новым предлогом: то она скакала на морском коньке, то каталась на скате, то нашла сундук сокровищ, то была в плену у гигантского кальмара. Никто не верит в Тюлькины истории, ведь всем известно, что маленькая Тюлька - большая выдумщица. Но однажды Тюлька, чудом спасшись из рыбацких сетей, заблудилась в океане. Помогут ли теперь Тюльке ее выдумки? И верите ли вы им? Сказка в стихах для чтения взрослыми детям."');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'улитка-и-кит-882'), 'Улитка и кит', 'The Snail and the Whale', 'Puž i kit', 'Джулия Дональдсон', 'Julia Donaldson', 'Džulija Donaldson', '... Вот скала / Где над морем улитка жила / И вздыхала она то и дело: / - Как мне все надоело! / Мир огромен, а я тут сижу на скале, / А могла бы уплыть на большом корабле... / ...Или... Или, может быть, на хвосте синего кита-великана?! Мир так широк, а улитка так мала - кто мог подумать, что именно крохотная улитка спасет своего большого друга, когда тот попадет в беду? Самая новая сказка в стихах от авторов мировых бестселлеров "Груффало" и "Дочурка Груффало" с большими - на всю страницу - яркими картинками. Победитель конкурса BBC "Blue Reter Award", как лучшая иллюстрированная книга 2005 года для чтения вслух. Для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'если-в-домике-тесно-883'), 'Если в домике тесно', 'A Squash and a Squeeze', 'Tijesna kućica', 'Джулия Дональдсон', 'Julia Donaldson', 'Džulija Donaldson', '"В домишке за лесом старушка жила, / Был дом невелик и старушка мала. / На полке посуда, у печки дорожка, - / Не дом, а мечта! Только тесно немножко." Как быть если в домике тесно? Верное средство знает старый философ: "Взять курицу в дом. Только чур без вопросов!" А вслед за курицей-несушкой - блохастую козу, обжору-свинью и корову… И только когда прогонишь их обратно на двор, то поймешь, что на самом деле дом не мал, а велик. Это самая первая книга писательницы Джулии Дональдсон и художника Акселя Шеффлера - авторов мировых бестселлеров "Груффало" и "Дочурка Груффало" и обладателей множества литературных наград. Для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лучшая-свадьба-на-свете-884'), 'Лучшая свадьба на свете', 'The Scarecrows'' Wedding', 'Najbolje vjenčanje na svijetu', '', 'Julia Donaldson', 'Džulija Donaldson', '"Пугало Бетти и пугало Билли нежно и крепко друг друга любили. Раз на исходе рабочего дня Билли сказал: - Выходи за меня! …""Согласна! Ура!"" - сказала Бетти, и молодые принялись за приготовления. Портной паучок сшил пышное платье из белых как снег гусиных перьев. Коровы одолжили свои колокольца - чтобы весело трезвонить на свадьбе. Краб нанизал бусы из пестрых раковин. Шустрые мышки обшарили двор - добыли кольца от стареньких штор. Осталось нарвать большущий букет, и Билли отправился за ним. Но вот прошел один день, за ним второй, а Билли все нет. Бетти в тревоге: вдруг он другую навек полюбил? А между тем, фермер выставил в поле новое пугало - Гарри. Он франт и любезник и хочет расстроить свадьбу. Джулию Дональдсон называют ""детским Шекспиром сегодня"", а Аксель Шеффлер - один из самых ярких и узнаваемых иллюстраторов наших дней. ""Самая лучшая свадьба"" - долгожданная новинка этих талантливых авторов. …И, кстати, сможете ли вы найти в книге Груффало?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'бумажные-куклы-885'), 'Бумажные куклы', 'The Paper Dolls', 'Papirne lutke', 'Джулия Дональдсон', 'Julia Donaldson', 'Džulija Donaldson', 'Мы сцепили крепко руки, / не страшны нам бяки-злюки! / Неразлучны Кэт и Клод, / Мэри-задом-наперёд, / бедный Джим с двумя носами / и красавица Шарлот… Написанная прозой и стихами, это лиричная и трогательная история о детстве, золотом и быстроногом, и о том, как оно никуда не уходит. Для детей до 6 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'именинный-пирог-886'), 'Именинный пирог', 'The Birthday Cake', 'Rođendanska torta', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Котёнок Финдус празднует день рождения три раза в год. А его хозяин Петсон, всегда в этот день печёт ему Именинный пирог. Вот как сегодня. Но чтобы его приготовить, Петсону нужно попасть на чердак, найти удочку, достать ключ из колодца, починить велосипед, а Финдусу - побывать в роли тореадора. Да-да, соседи считают их чудаками. Ещё скажите, что это не так!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-финдус-потерялся-когда-был-887'), 'Как Финдус потерялся когда был маленький', 'When Findus Was Little and Disappeared', 'Kad je Findus bio mali i izgubio se', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Петсон был самым обычным одиноким стариком, пока в один прекрасный день соседка не принесла ему большую коробку, в которой сидел крошечный котёнок. Жизнь Петсона изменилась, теперь ему скучать не приходится! Эта книга о том, почему Финдуса зовут Финдусом, откуда у него такие смешные полосатые штаны и как ему удалось спастись от страшного чудовища. Для детей младшего школьного возраста.Книга Свена Нурдквиста "История о том, как Финдус потерялся, когда был маленьким" отсылает читателей к началу цикла о Петсоне и Финдусе. Вы узнаете, какие обстоятельства привели к судьбоносной встрече старика и котенка.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чужак-в-огороде-888'), 'Чужак в огороде', 'The Rooster in the Garden', 'Uljez u bašti', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Однажды старик Петсон принёс домой огромного и наглого петуха. Котёнок Финдус совсем не в восторге от нового соседа, который тотчас завладел вниманием кур и начал кукарекать сутки напролёт. Что же делать? У Финдуса есть план!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'а-ну-ка-петсон--889'), 'А ну-ка, Петсон!', 'Come on, Pettson!', 'Hajde, Petsone!', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Петсон умеет печь пироги, чинить проколотую шину и ловить рыбу. А может ли он бегать, прыгать и лазить по деревьям, как Финдус? Пора проверить! Свен Нурдквист- шведский художник и писатель, получивший мировую известность благодаря своим книгам для детей. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всём мире. Книга адресована детям от о до 3 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'финдус-переезжает-890'), 'Финдус переезжает', 'Findus Moves Out', 'Findus se seli', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Прошло более 10 лет с тех пор, как Свен Нурдквист написал последнюю книгу в серии про Петсона и Финдуса. Наконец нас ждет продолжение! По утрам старик Петсон любит поспать - хотя бы до семи часов. А кот Финдус не может прожить без утренней разминки, которая начинается в четыре утра. Всё бы ничего, но друзья живут в одной комнате… Свен Нурдквист - шведский художник и писатель, лауреат премии Астрид Линдгрен (2003 год). Первая книга о старике Петсоне и его умном котёнке Финдусе вышла в 1984 году, после чего серия продолжилась, а автор набирал популярность сначала у себя на родине, в Швеции, а далее и во всей Европе. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всём мире. Книги переведены на 40 языков.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'петсон-грустит-891'), 'Петсон Грустит', 'Pettson Goes Fishing', 'Petson je tužan', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Что делать, если твой друг ни с того ни с сего загрустил? Надо немедленно вернуть ему хорошее настроение! Самый весёлый и изобретательный в мире кот Финдус способен развеселить кого угодно, даже угрюмого старика Петсона. Как ему эту удается? Одной левой лапой! Свен Нурдквист- шведский художник и писатель, получивший мировую известность благодаря своим книгам для детей. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всём мире.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'охота-на-лис-892'), 'Охота на лис', 'The Fox Hunt', 'Lov na lisicu', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nurdkvist', 'Однажды к Петсону и Финдусу зашел их сосед Густавсон, который сказал, что в округе появилась лиса, ворующая кур. Но Финдус против охоты на лис, лису надо перехитрить, считает он. Поэтому вместе с Петсоном они придумывают хитроумный способ напугать лису, чтобы ей больше было неповадно наведываться в курятники. Друзья приготовили для лисы настоящее светопредставление: взрывы петард и фейерверков, чучело курицы, наполенной перцем и даже настоящее привидение! И не только отвадили лису от своего курятника, но и навсегда отучили Густавсона от охоты на лис.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'петсон-идет-в-поход-893'), 'Петсон идет в поход', 'Findus Goes Camping', 'Petson ide na kampovanje', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Однажды котенок Финдус нашел на чердаке у Петсона старую палатку и ему безудержно захотелось пойти в поход, а Петсону как раз надо испытать его новое изобретение — лук для ловли рыбы. Так что друзья собирают рюкзак и отправляются на озеро. Но по пути к ним привязываются куры, которые никак не хотят отпускать их. Тогда Петсон и Финдус ставят палатку в саду и ночуют под яблоней. И получается почти как настоящий поход.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рождество-в-домике-петсона-894'), 'Рождество в домике Петсона', 'Pettson''s Christmas', 'Božić kod Petsona', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Близится Рождество, а у Петсона еще ничего не готово к празднику. Надо успеть сходить в магазин, пока он не закрылся, а еще нужно нарубить дров и принести из леса елку. Но в лесу Петсон подворачивает ногу — и ходить больше не может. Его котенок Финдус в ужасе и расстройстве: Рождество и Новый год без елки, без угощения без подарков? Как такое может быть? Но о беде, случившейся с Петсоном, узнали соседи. И вот кто-то ему нарубил целый сарай дров, кто-то принес ветчины, а кто-то помог Финдусу нарядить елку. Удивительное Рождество получилось у Петсона с Финдусом в этом году!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'песенник-петсона-и-финдуса-895'), 'Песенник Петсона и Финдуса', 'Pettson and Findus Songbook', 'Pjesmarica Petsona i Findusa', 'Свен Хедман', 'Sven Hedman', 'Sven Hedman', 'Ну что, споем вместе с Петсоном и Финдусом? А может, даже станцуем? Фокстрот, самба, вальс, танго и многое другое в исполнении любимых героев! В книгу вошли двадцать пять песен с нотами по мотивам книг из популярной серии о старичке Петсоне и его котенке Финдусе. Эти песни можно не только разучить на гитаре или фортепьяно, но также послушать или скачать на музыкальных сервисах');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'поделки-финдуса-896'), 'Поделки Финдуса', 'The Pettson and Findus Craft Book', 'Findusove majstorije', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Старик Петсон - мастер на все руки, а его котёнок Финдус обожает придумывать. Они научат тебя мастерить фигурки животных из шишек, пересаживать растения и проращивать семена, делать бусы из гороха с фасолью, печь вкусный пирог с красной смородиной, строить домик из палочек для мороженого и даже разводить головастиков! Самое замечательное в том, что всё, описанное в этой книге, можно сделать дома. Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'готовим-с-петсоном-и-финдусом-897'), 'Готовим с Петсоном и Финдусом', 'Cooking with Pettson and Findus', 'Kuvamo sa Petsom i Findusom', '', 'Sven Nordqvist, Christine Samuelson', 'Sven Nurdkvist, Kristin Samuelson', 'Ни для кого не секрет, что Петсон - старик немного рассеянный. Мука у него может оказаться под диваном, а перец в велосипедной корзине. Его прекрасные рецепты разбросаны по всему дому. Однажды котёнок Финдус решил, что пора собрать их в кулинарную книгу, и вот что из этого получилось! Петсон и Финдус научат вас печь пироги и плюшки, варить супы, кисели, каши и даже готовить морковный мармелад. Рецепты у Петсона очень простые и вкусные, к тому же каждому из них предшествует небольшая история из жизни старика и котёнка. Большинство блюд дети постарше могут приготовить сами, а для самых маленьких предусмотрены задания попроще, которые обычно выполняет Финдус: скатать из фарша тефтельки, смешать соус, отмерить молоко и муку или натолочь сухари. Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'механический-дед-мороз-898'), 'Механический Дед Мороз', 'The Mechanical Santa', 'Mehanički Deda Mraz', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nurdkvist', 'Старик Петсон и котёнок Финдус готовятся встретить Рождество. "Но какое же Рождество без Деда Мороза?" - думает Финдус. "Но ведь Деда Мороза не существует, где его взять?.." - вздыхает Петсон. И тут ему в голову приходит блестящая идея! Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мама-му-и-гонщик-кракс-899'), 'Мама Му и гонщик Кракс', 'Mama Moo and Racer Crow', 'Mama Mu i trkač Kraks', 'Юя Висландер', 'Jujja Wieslander', 'Juja Vislander', 'Ну и жара! Мама Му купается в озере и пускает кораблики, а Кракс тем временем проектирует лучшую в мире гоночную лодку. Посмотрим, что из этого выйдет… Книги о Маме Му и Краксе переведены на 30 языков и известны во всем мире. Их авторы - Юя Висландер, почетный член шведской Академии детской книги, и Свен Нурдквист, получивший мировую известность благодаря книгам о Петсоне и Финдусе.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мама-му-играет-в-лето-900'), 'Мама Му играет в лето', 'Mama Moo Plays Summer', 'Mama Mu se igra ljeta', 'Юя Висландер', 'Jujja Wieslander', 'Jujja Wieslander', 'Сосульки превращаются в мороженое, а на деревьях вырастает листва, когда у тебя есть друг с богатой фантазией. Мама Му может устроить маленькое лето даже в разгар зимы! Книги о Маме Му и Краксе переведены на 30 языков и известны во всем мире. Их авторы - Юя Висландер, почетный член шведской Академии детской книги, и Свен Нурдквист, получивший мировую известность благодаря книгам о Петсоне и Финдусе. Юя Висландер - шведская детская писательница. Наиболее известна как автор серии рассказов о любознательной корове Маме Му и философствующем вороне Краксе с иллюстрациями Свена Нурдквиста. Юя придумала персонажей вместе с мужем Томасом. Мама Му и Кракс появились как герои радиоспектакля и детских песен, и лишь в 1991 году вышла первая книга. В 2005 году Юя Висландер получила премию Астрид Линдгрен.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сотворение-мира-901'), 'Сотворение мира', 'The Creation of the World', 'Stvaranje svijeta', 'Салли Альтшулер', 'Sally Altschuler', 'Sali Altšuler', 'Создавать мир - та еще работенка. Неудивительно, что Бог загрустил и подумал: "Вот бы мне кто-нибудь помог". Тогда рядом с ним сразу появилась Мия. Вдвоем они придумали все на свете, от морей до морковок. А потом решили, что это хорошо, и оставили людям - чтобы мы радовались миру и приглядывали за ним.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'корабль-ноя-902'), 'Корабль Ноя', 'Noah''s Ark', 'Nojeva barka', 'Салли Альтшулер', 'Sally Altschuler', 'Sali Altšuler', 'Дождь лил как из ведра, и Ной торопился поскорее собрать зверей на своем корабле. Вот только Носорог постоянно ворчал и жаловался, что его никто не любит. Так оно поначалу и было, но тут случилось кое-что непредвиденное, и Носорогу удалось доказать, что он настоящий герой. Датский писатель Салли Альтшулер показывает библейскую историю с неожиданной точки зрения. А знаменитый Свен Нурдквист удивительно остроумно изображает события, произошедшие во время Всемирного потопа.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'башня-вавилона-903'), 'Башня Вавилона', 'The Tower of Babel', 'Vavilonska kula', 'Салли Альтшулер', 'Sally Altschuler', 'Sali Althuler', 'Король совсем сбился с ног, чтобы развеселить свою дочку, но принцесса все равно скучает целыми днями: музыканты играют занудную музыку, повар готовит надоевшую еду, а танцоры всегда танцуют один и тот же танец. И тогда король приказал господину Вавилону созвать со всего мира лучших ремесленников и построить самую высокую в мире башню. "Башня господина Вавилона" - свободная трактовка знаменитого древнего мифа с юмористическими иллюстрациями Свена Нурдквиста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'книга-настоящих-рыболовов-904'), 'Книга настоящих рыболовов', 'The Real Angler''s Book', 'Knjiga pravih ribolovaca', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Что может быть интереснее и веселее, чем рыбалка в отличной компании? Особенно если ты настоящий спец в этом деле и знаешь, чем скумбрия отличается от трески, как ловить рыбу на мушку и что с ней делать, когда поймал. Не знаешь? Ничего страшного! Знаменитый шведский художник Свен Нурдквист расскажет и покажет все, что нужно знать настоящему рыболову. Так что смело беги на ближайшую речку (пруд, озеро, море). И не забудь взять с собой книжку!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'минус-и-большой-мир-905'), 'Минус и большой мир', 'Minus and the Big World', 'Minus i veliki svijet', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'Пора мне в дорогу, на мир посмотреть, решил однажды маленький мальчик по имени Минус. Сказано - сделано. В пути Минуса ждут необыкновенные встречи: он познакомится с тремя глуповатыми мудрецами, неумолкающим таратетрисом, разозлит ведьму, утешит грустную девочку Магдалену, поможет потерпевшему крушение воздухоплавателю взлететь в небо, спасет портниху от королевского гнева и научится считать до ста!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'прогулка-906'), 'Прогулка', 'The Walk', 'Šetnja', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordqvist', 'Обычная Прогулка с собакой может обернуться приключением, полным приятных неожиданностей. Розовый мамонт грустит в клетке для канарейки, а буйвол играет на ударной установке. Гигантский чайник сам разливает чай, а шляпа притворяется островком в море. В фантастических мирах Свена Нурдквиста возможно все! Свен Нурдквист - шведский художник и писатель, получивший мировую известность благодаря своим книгам для детей. По мотивам серии о Петсоне и Финдусе сняты мультфильмы, сделаны компьютерные игры и созданы театральные постановки. На книгах Нурдквиста выросло не одно поколение детей во всем мире.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'понятная-математика-907'), 'Понятная математика', 'Math Made Simple', 'Jasna matematika', 'Кристина Даль', 'Kristin Dahl', 'Kristin Dal', 'Думаешь, математика безнадежна и трудна? Возможно, ты даже считаешь, что она явно не для тебя? Так думают только те, кто не знает, что она из себя представляет на самом деле. Прочитав эту книгу, полную интереснейших задач (с ответами) и смешных рисунков Свена Нурдквиста, ты поймешь: математика вовсе не скучная и не сложная! Решая приведенные здесь задачи, не торопись и постарайся придумать несколько вариантов ответа. А иногда потребуется вывернуть ответ наизнанку!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'волшебные-линзы-и-хитроумные-я-908'), 'Волшебные линзы и хитроумные ящички', 'Magic Lenses and Clever Boxes', 'Čarobna sočiva i dovitljive kutije', 'Пелле Экерман', 'Pelle Eckerman', 'Pele Ekerman', 'Книга посвящена истории развития оптики - с древнейших времен и до наших дней. Здесь не только рассказывается про знаменитых ученых и изобретателей - Пифагора, Леонардо да Винчи, Исаака Ньютона и многих других, но еще приводятся пошаговые инструкции по изготовлению простейших научных приборов - микроскопа, телескопа, ящичного фотоаппарата и не только. Книга иллюстрирована художником Свеном Нурдквистом.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сага-о-людях-из-бирки-909'), 'Сага о людях из Бирки', 'The Saga of the People of Birka', 'Saga o ljudima iz Birke', 'Матс Валь', 'Mats Wahl', 'Mats Val', 'Эпоха викингов необыкновенно притягательна. Драккары и военные походы, скандинавские боги и саги поневоле будят воображение. Однако мы довольно смутно представляем себе, как протекала жизнь тысячу лет назад, как человек ухитрялся выживать в суровом мире. Романтический ореол вокруг викингов не находит ни исторического, ни археологического подтверждения. Зато усилиями ученых что ни год обнаруживаются новые фрагменты рассыпанной головоломки. Их пока слишком мало, чтобы сложить картину целиком. И приходится прибегать к помощи фантазии. В своей повести о событиях в Бирке и на балтийских берегах Матс Валь опирается на факты, полученные благодаря археологическим раскопкам. А иллюстрации Свена Нурдквиста, точно уловившего дух времени, вновь оживляют для нас давно ушедших людей и мир, в котором они жили.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дальний-путь-910'), 'Дальний путь', 'The Long Journey', 'Daleki put', 'Матс Валь', 'Mats Wahl', 'Mats Val', 'Кто из нас в детстве не мечтал тайком убежать из дома и отправиться в кругосветное путешествие? В XVIII веке у детей было больше шансов сделать это! На дворе 1743 год. Двое мальчишек незаметно пробираются на борт корабля "Гетеборг", который должен отправиться в Китай. Когда их находят матросы, корабль отплыл уже слишком далеко. Путешествие оказалось не только романтическим, но и весьма опасным.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'непослушный-пират-911'), 'Непослушный пират', 'The Disobedient Pirate', 'Neposlušni pirat', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', '"Увидеть мир глазами подростка, оставаясь при этом взрослым, - уникальный дар, которым Гиваргизов обладает вполне. Прибавьте к этому парадоксальность мышления - и получите представление о прозе Артура Гиваргизова" (Ксения Молдавская, газета "Книжное обозрение"). "Когда после долгой зимы открывают и моют окна, мир внутри дома и снаружи становится ярким, просторным, праздничным - совсем таким, как на картинках Максима Покалева');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'контрольный-диктант-и-древнегр-912'), 'Контрольный диктант и древнегреческая трагедия', 'The Dictation Test and Ancient Greek Tragedy', 'Kontrolni diktat i starogrčka tragedija', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Иногда очень хочется пойти в театр. Вдруг! Ночью! Посмотреть какую-нибудь Древнегреческую трагедию. Но нет времени, или билетов. Или ночью в театр без родителей не пускают. Иногда очень не хочется писать контрольный диктант. Но от Веры Петровны не спрячешься даже в лесу. Иногда из-за очень хорошего зрения совсем ничего не видишь, фамилии меняются вместе с временами года, во дворе можно устроить Красное море, поставить олимпийский рекорд, убегая от собаки... Многое бывает иногда. Всё зависит от настроения. А настроение у автора и художника книжки "Контрольный диктант и древнегреческая трагедия" всегда для весёлых и необычных историй подходящее.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'записки-собаки-охотника-913'), 'Записки собаки охотника', 'Notes of a Hunter''s Dog', 'Bilješke lovačkog psa', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Что же такое эти "Записки"? Это стихи. Самые настоящие, добротно сделанные и великолепно выдуманные детские стихи, в духе лучших представителей этого жанра. Читая их, находишь отголоски поэзии Даниила Хармса, Саши Чёрного, Бориса Заходера. Помните "Дневник фокса Микки"? По его мотивам ещё мультфильм сняли, "Записки Пирата". Вот персонаж заглавного стихотворения этой книги - явно его родственник.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'морж-учитель-и-поэт-914'), 'Морж, учитель и поэт', 'The Walrus, the Teacher and the Poet', 'Morž, učitelj i pjesnik', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Артур Гиваргизов давно известен как автор детских стихов (сборники "Как-то я летел с рябины", "Генералы", "Когда некогда", "Космонавты" и другие), рассказов и пьес. По образованию Артур профессиональный музыкант, но, читая его стихи, сразу понимаешь, что он настоящий поэт, хулиган и волшебник, который как никто понимает детей, и всегда заодно со своими читателями. Его новая книжка - "Морж, учитель и поэт" - это две истории о шестидесятилетнем Михаиле Михайловиче из поселка Песочный на берегу Северного Ледовитого океана. Но не пугайтесь! Речь совсем не о скучном пенсионере. Миша - человек пожилой, но очень, по-детски, счастливый, и все его зовут просто по имени, "потому что маленький, несерьёзный и мудрый - это одно и то же".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'слово-мамонта-915'), 'Слово мамонта', 'Mammoth''s Word', 'Mamutova riječ', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Миша в новой книге Артура Гиваргизова опять отправляется в путешествие, на Алтай. Если вы не знаете, где это, то скорее посмотрите на карту. А еще лучше купите билет до Барнаула, а оттуда на маршрутку в Тюнгур и возьмите с собой рюкзак, спальник, шерстяные носки… Ой, нет, сперва просто прочитайте, что написано об этом в повести «Как пройти на Белуху». А как приятно после путешествия вернуться домой, туда где все по-старому, уютно и понятно, и рассказывать соседям обо всем, что увидел. Правда, когда Миша вернулся с Алтая, оказалось, что в его родном Песочном назревают удивительные изменения. Такие, что даже мамонт заговорил. Об этом расскажет вторая повесть сборника, «Слово мамонта».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ефремовские-сказки-916'), 'Ефремовские сказки', 'Tales from Yefremov', 'Jefremovske bajke', 'Артур Гиваргизов', 'Arthur Givargizov', 'Artur Givargizov', 'Ефремов - это город. Сказки - это не сказки. Вернее, для нас, может быть, и сказки, а для жителей Ефремова - каждодневные новости. Например, коробка с серебряными звёздами. Ну конечно, её фокусник оставил. Просто Николаю Михайловичу надо было ещё пять минут подождать-посидеть спокойно, терпения не хватило, жаль. Кстати, вечером того же дня в коробку забрался Трезор. Теперь он чайка. Летает над двором и кричит: "Я собака! Собака!". Превращение Трезора в книжку не вошло, потому что Трезор превратился вечером, а книжку уже днём отправили в типографию. Да тут за полдня ещё столько всего случилось! В Ефремове каждый час случается что-нибудь необычное');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'бесконечно-ваши-волк-и-красная-917'), 'Бесконечно ваши, Волк и Красная Шапочка', 'Yours Truly, Wolf and Little Red Riding Hood', 'Beskrajno vaši, Vuk i Crvenkapa', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Девятнадцать вариаций на известную тему. На очень известную тему. Кажется, что всё уже сыграно… А вот и не всё: "Однажды Красная Шапочка отправилась в дремучий лес в ритме танго. А навстречу ей - Волк в ритме сальсы. На нём был бабушкин чепец, украшенный бумажными розочками, и халат, расшитый хризантемами"');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вопрос-номер-25-918'), 'Вопрос номер 25', 'Question Number 25', 'Pitanje broj 25', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Однажды меня попросили написать о вежливости: "Это очень серьёзная тема. Объясни, пожалуйста, детям, что такое вежливость. Ты же работал учителем?" Да, работал. У меня сначала плохо получалось, дети на моих уроках спали с открытыми глазами. Я разуверился в своих способностях, стал над собой подшучивать… А дети вдруг проснулись и начали внимательно слушать. Тогда я схитрил, придумал для серьёзной темы весёлый пример, рассказ "Прекрасный урок". С "Прекрасным уроком" урок прошёл - прекрасно. Вот из таких примеров и состоит книжка "Вопрос номер двадцать пять".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'генералы-919'), 'Генералы', 'Generals', 'Generali', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', '"Генералы" - результат работы поэта Артура Гиваргизова и художника Максима Покалёва. Генералы - персонажи каждого вошедшего в сборник стихотворения. Самые настоящие генералы - на службе, на параде, на рыбалке, в больнице, на футбольном матче или на прогулке с внучкой. Все герои книги симпатичные, а порой и трогательные, но иногда терпят неудачу, иногда оказываются в смешной ситуации, иногда ведут себя как расшалившиеся мальчишки. "И вроде бы и генералы суровые, и строго командуют, в общем, ведут себя как настоящие военные... но ни одно стихотворение нельзя читать без улыбки", - рассказывают в "Самокате".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'главные-роли-для-оли-920'), 'Главные роли для Оли', 'Starring Roles for Olya', 'Glavne uloge za Olju', 'Артур Гиваргизов', 'Arthur Givargizov', 'Artur Givargizov', 'Пятьдесят тысяч поклонников, миллион красных кофт, батоны до Франции, "Битлз" на хамелеоне и трёхметровый пластилиновый памятник!.. Это всё про Олю, всё Оля - хозяйка пятнадцати умных собак и абсолютная чемпионка школы. В Олин день рождения всегда салют. А для вас - художественный альбом со стихами Артура Гиваргизова и рисунками Максима Покалёва, яркий взрывной творческий симбиоз, который украсит домашнюю библиотеку самого взыскательного читателя.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'такие-разные-оли-921'), 'Такие разные Оли', 'So Many Different Olyas', 'Tako različite Olje', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Да, Оли очень разные. Или это одна Оля очень разная? Лена говорит, что книжка получилась про Лен, Надя - про Надь... В общем, разбирайтесь сами. Для детей младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'космонавты-922'), 'Космонавты', 'Cosmonauts', 'Kosmonauti', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Жизнь на Земле в 3228 году…много в ней…странного. Написал, а потом подумал: "Когда книжку буду переиздавать в 3238 году, все равно странное станет привычным". За смородиной на Марс летают, физкультура в невесомости… Везет же! Вспоминаю, как я на своей старинной физкультуре из-за земного притяжения не смог прыгнуть на метр пятьдесят... Но вот по коридорам в 3238-м не побегаешь, как сейчас, в ракете коридора нет. Где же лучше, в 3238-м или 2019-м? Да везде хорошо! Правда, когда я разглядываю картинки Кати Головановой, меня это будущее не завораживает!.. Можно в него переместиться не навсегда, этим-то и хороши книжки. Садишься на ракету, нарисованную на обложке, и : "Поехали!"');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'энциклопедия-с-бабочкой-и-бара-923'), 'Энциклопедия с бабочкой и барабаном', 'Encyclopedia with a Butterfly and a Drum', 'Enciklopedija sa leptirom i bubnjem', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Может быть, благодаря нашей не очень серьёзной, но правдивой энциклопедии хотя бы 4999 читателей станут не очень серьёзными, но настоящими энциклопедистами? А что, всё может быть!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'история-государства-российског-924'), 'История государства российского в отрывках из школьных сочинений', 'The History of the Russian State in Excerpts from School Essays', 'Istorija ruske države u odlomcima iz školskih sastava', 'Леонид Каминский', 'Leonid Kaminsky', 'Leonid Kaminski', 'Книга петербургского художника и писателя, знаменитого Учителя смеха Леонида Каминского собрана из многочисленных "ляпов", "смешных ашыпок" и несуразностей, которые юные читатели более двух десятков лет присылали ему в редакцию всероссийского журнала "Костёр". Эти нелепые отрывки из сочинений и ответы у доски составили богатейшую, уникальную коллекцию - настоящую энциклопедию школьного юмора.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'здравствуй-лошадь--925'), 'Здравствуй, лошадь!', 'Hello, Horse!', 'Zdravo, konju!', 'Ася Кравченко', 'Asya Kravchenko', 'Asja Kravčenko', 'Обыкновенные истории про лошадь по имени Кабачок, ее друзей и знакомых, и немножко про людей. Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сказки-старого-дома-926'), 'Сказки старого дома', 'Tales of the Old House', 'Bajke stare kuće', 'Ася Кравченко', 'Asya Kravchenko', 'Asja Kravčenko', 'Взрослым всегда некогда, и Ташке приходится со всем справляться самой: пристраивать в хорошие руки крокодила, заканчивать папину статью, устраивать чужую свадьбу. Но с чем никак ей не справиться - дом вот-вот снесут и надо переезжать.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'укротитель-сиреневых-бегемотов-927'), 'Укротитель сиреневых бегемотов', 'The Tamer of Lilac Hippos', 'Krotitelj ljubičastih nilskih konja', 'Сергей Георгиев', 'Sergey Georgiev', 'Sergej Georgijev', 'Краткость, точность, афористичность – отличительные черты прозы Сергея Георгиева. Его добрый юмор и наблюдения за жизнью и взрослением маленьких людей в сочетании с неповторимой нежной манерой художника-иллюстратора Елены Блиновой увидели свет в сборнике рассказов «Укротитель сиреневых бегемотов». Здесь герои говорят на бегемотском языке, подают сигналы марсианским летающим тарелкам и осваивают маленькие домашние хитрости с волшебными словами, музыкой и заклинаниями.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'простодушный-ганс-928'), 'Простодушный Ганс', 'Simple-Hearted Hans', 'Prostodušni Hans', 'Сергей Георгиев', 'Sergey Georgiev', 'Sergej Georgijev', 'Испокон веков люди рассказывают детям сказки. Добрые и забавные, страшные и не очень… А ведь сказки не только в старину рождались. Знаменитый детский писатель Сергей Георгиев сочинил для детей сборник сказок о простодушном Гансе. Сказки не простые: на первый взгляд в них вроде бы о стародавних временах рассказывается, а если вдуматься - то очень даже про нас с вами. Про трудолюбивых крестьян и злых разбойников. Про чванливого маркграфа и обидчивого дракона. Про метлу-голубушку, которая сама собой метёт. Про снежную печку, в которой пекутся ледяные оладушки. И про то, как Ганс нашёл чудесный горшочек, который чем прикажешь, тем и наполнится… А иллюстрации к этим сказкам, созданные художницей Александрой Новосёловой, словно сошли со страниц средневековых манускриптов. И трудно поверить, что книга эта родилась не под сводами старинных мастерских, а в наше время, в издательстве "Эгмонт". Книга продолжает серию "Город мастеров", и сразу ясно - это воистину творение настоящих мастеров своего дела.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сказки-про-королей-929'), 'Сказки про королей', 'Tales of Kings', 'Bajke o kraljevima', 'Сергей Седов', 'Sergey Sedov', 'Sergej Sedov', 'Волнуешься с первых строк: за подданных, за лошадь (упадёт ведь), за короля… Не надо волноваться, в сказках всё хорошо заканчивается. Ещё есть про рассеянного, стеснительного, трусливого… Сказки про королей! Про очень разных. Разных-преразных. Ужасно разных. А вы думали, все короли одинаковые? Вот прочтёте эту книжку и поймёте, как вы были не правы!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сказки-про-мам-930'), 'Сказки про мам', 'Tales About Moms', 'Bajke o mamama', 'Сергей Седов', 'Sergey Sedov', 'Sergej Sedov', '"Сказки про мам" Сергея Седова поражают своей невероятной современностью, а их неподдельная вневременная искренность заставит сопереживать любого - будь он сам хоть трижды мамой... И особенно замечательно, что мамы в сказках Сергея Седова очень разные - точно как в жизни! И как в жизни, у них есть одна общая черта - они бесконечно любят своих детей. А так как нет человека в мире, который появился бы на свет без участия мамы, то сказки эти будут интересны всем: маленьким и взрослым, умным и глупым, бедным и богатым, добрым и злым...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сказки-931'), 'Сказки', 'Fairy Tales', 'Bajke', 'Сергей Седов', 'Sergey Sedov', 'Sergej Sedov', 'В жизни есть место чуду, и один из самых известных собирателей таких чудес - Сергей Седов. Сказки его полны доброго вымысла, за которым угадывается реальность. Читатель узнаёт себя и своих друзей в героях этих сказок - в королях и волшебниках, рыбаках и дураках. Привычный мир открывается новыми гранями, в нём проявляется тонкое волшебство и весёлое чудачество, и читатель начинает уже смотреть на происходящее с ним мудрыми глазами сказочника.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'переход-932'), 'Переход', 'The Crossing', 'Prelaz', 'Артур Гиваргизов', 'Artur Givargizov', 'Artur Givargizov', 'Полгода назад Артур Гиваргизов и Виктория Семыкина сидели в кафе, обсуждали будущую книжку. Артур: Ну, если вкратце... Дима любит бродить по городу. По Кибальчича, Касаткина... Через дорогу Переходит осторожно, только на зелёный. Однажды светофор сломался, и Дима день стоял, два, три, четыре, пять, шесть... Родители даже стали волноваться. Виктория: Да, я несколько раз видела этого мальчика на Кибальчича! (Рисует Димин портрет, показывает Артуру.) Он? Артур (радостно): Он! Он! Димины родители (Виктории): И нас нарисуйте, пожалуйста. Автоинспектор: И меня. Водитель автобуса: И меня. Пассажиры и прохожие: И нас. Так Виктория Семыкина нарисовала всю книжку');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '3-минуты-до-хорошего-настроени-933'), '3 минуты до хорошего настроения', '3 Minutes to a Good Mood', '3 minuta do dobrog raspoloženja', 'Наталья Евдокимова', 'Natalya Evdokimova', 'Natalija Jevdokimova', 'Три минуты - примерно столько нужно, чтобы съесть бутерброд или прочитать один рассказ из этой книги. И читать лучше вслух. А лучше в громкоговоритель. Тогда хорошее настроение настанет сразу у многих людей! Только, читая вслух, будьте готовы, что выстроится очередь: нажать вам на нос. Вдруг у него звон мелодичный - прямо как у Васьки из одного рассказа. К Ваське длинная очередь выстраивалась.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вкусный-юра-934'), 'Вкусный Юра', 'Delicious Yura', 'Ukusni Jura', 'Михаил Есеновский', 'Mikhail Yesenovsky', 'Mihail Jesenovski', 'Михаил Есеновский снова написал про Юру. Того, который сначала всего боялся. Точнее, ничего не боялся (в книге "Главный шпионский вопрос"). Который потом болел. Вернее, не болел, а дружил со своими заболеваниями (в книге "Ангина Марина"). Теперь Юра ест. То есть, нет, это его едят. Он же вкусный. Ест лиса, ест волк, ест медведь. И носорог, и бегемот с крокодилом. Даже морская свинка. Даже тушканчик. Как же так? Ведь Юра один, а зверушек много. Ерунда, ничего страшного, хорошего человека на всех хватит.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'не-поверишь--935'), 'Не поверишь!', 'You Won''t Believe It!', 'Nećeš vjerovati!', 'Ирина Зартайская', 'Irina Zartayskaya', 'Irina Zartajska', 'Не поверите! Но квадратура круга и задача о перемещении дивана - далеко не самые важные вопросы, издревле волнующие лучшие умы человечества! Чем накормить лужу, как лучше бегать - за дворником или перед кошкой, на каком боку лежать, когда тебе грустно, на какую ногу надо надевать красный носок, чем опасна профессия археолога, можно ли влюбиться зимой, что общего между супом и шоколадом и, наконец, где живёт мальчик Тим? Если хотя бы один из этих вопросов поставил вас в тупик, эта книга для вас, так как вы просто обязаны хотя бы раз в жизни оказаться в тупике! Вы, конечно, не поверите, но там бывает ужасно интересно - особенно если в этот тупик вас поставят Ирина Зартайская и Владислав Суровегин!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-будто-936'), 'Как будто', 'As If', 'Kao da', 'Дина Бурачевская', 'Dina Burachevskaya', 'Dina Buračevska', 'Дина Бурачевская очень любит сочинять детские стихи лёжа в кровати, обложившись подушками, а рядом чтоб стояла тарелочка с пряниками и конфетами, а в ногах чтоб урчал любимый кот Лунтик. И ещё она любит выступать перед детьми, а когда она выступает, то машет руками, краснеет и даже подпрыгивает, но детям всё равно это очень нравится. Любимый цветок Дины Бурачевской - это одуванчик, так что если придёте на её выступление, то обязательно принесите букет белых одуванчиков, главное, чтоб в этот день погода была не очень ветреной...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'прическа-номер-один-937'), 'Прическа номер один', 'Hairstyle Number One', 'Frizura broj jedan', 'Михаил Есеновский', 'Mikhail Yesenovsky', 'Mihail Jesenovski', 'В этой книге Михаила Есеновского - стихи про всё. И про причёску номер один, и про 303 тысячи 33 волосинки, и про 400 пятен на Солнце. Здесь курица пытается взлететь с палубы авианосца, а мыши - улететь на Луну в ракете. Черепаха копит деньги на ремонт панциря, а рыбка - на аквариум с джакузи. Лев работает парикмахером, а моль - гардеробщицей в Большом театре. И всё это весело, энергично, под музыку. Крот танцует фокстрот, козёл - рок-н-ролл, а муравьи - танец маленьких лебедей. Ну очень маленьких.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'бублик-для-гуманоида-938'), 'Бублик для гуманоида', 'A Bagel for a Humanoid', 'Đevrek za humanoida', 'Валентина Дегтева', 'Valentina Degteva', 'Valentina Degtjeva', 'Никогда не заглядывайте в водопроводные люки! Вот героиня рассказов Валентины Дегтевой - девочка по имени Нинка - заглянула, и что? Обнаружила там заколдованного принца. Возись с ним ещё, расколдовывай… А Нинке давно домой пора, к маме! Смешные и добрые, весёлые и поучительные - эти истории полны удивительных неожиданностей и забавных приключений. "Атмосфера смешений и превращений - возвышенного и смешного, запутанного и явного,понятного и перевернутого - и есть главная особенность книги Валентины Дегтевой…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'из-переписки-с-коровой-939'), 'Из переписки с коровой', 'From Correspondence with a Cow', 'Iz prepiske sa kravom', 'Тим Собакин', 'Tim Sobakin', 'Tim Sobakin', 'Чудесные стихи Тима Собакина знает и любит уже не одно поколение читателей. На этот раз автор рассказывает о том, как он подружился… с коровой. Да-да, с самой настоящей коровой! Они обмениваются письмами: корова рассказывает своему новому другу о жизни в деревне, автор – о том, как работает вагоновожатым. В этой непринуждённой беседе в полной мере раскрывается яркий талант писателя и искромётное чувство юмора.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дрессировщик-бутербродов-940'), 'Дрессировщик бутербродов', 'The Sandwich Tamer', 'Krotitelj sendviča', 'Сергей Георгиев', 'Sergey Georgiev', 'Sergej Georgijev', 'Сергей Георгиев - мастер прозаической миниатюры. В "три абзаца" его сказки или рассказа умещается все, что должно быть в хорошей - "большой" - книге: правдивость и наблюдательность, доброта и юмор, а еще - снисходительность, и много житейской мудрости');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'новенький-941'), 'Новенький', 'The New Kid', 'Novi đak', 'Сергей Махотин', 'Sergey Makhotin', 'Sergej Mahotin', 'В семь лет, как все, я пошёл в школу. Но учился в ней не очень долго. Не потому что меня выгнали. Просто семья переехала в другой дом, и школу пришлось поменять. А заканчивал я уже третью по счёту школу. И хорошо помню ощущение новенького, который вдруг очутился в чужом коллективе. Волнение, тревогу, желание поскорее найти хороших друзей. А ведь этот сборник стихов - тоже Новенький. И тоже, как робкий поначалу школьник, мечтает подружиться с вами, дорогие читатели. Я, Сергей Махотин, и художница этой книжки Ирина Иванова очень надеемся, что так оно и произойдёт.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайный-гонец-942'), 'Тайный гонец', 'The Secret Messenger', 'Tajni glasnik', 'Марина Бородицкая', 'Marina Boroditskaya', 'Marina Borodickaja', 'Марина Бородицкая - автор, который завораживает с первой фразы. Завораживает, облагораживает, завладевает мыслями и чувствами, проникает в сердце, обволакивая, вдохновляя и излечивая кристально-чистыми образами, выверенно-отточенными метафорами, нежностью и глубиной. Будто кто-то из пёстрой разноголосой толпы хватает вдруг за руку и тащит вдоль прилавков, ошеломляющих роскошью');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'послушный-папа-943'), 'Послушный папа', 'An Obedient Dad', 'Poslušni tata', 'Наталья Евдокимова', 'Natalia Evdokimova', 'Natalija Jevdokimova', 'Наталья Евдокимова - афористичная, тонкая, точная; она подаёт образы своих маленьких героев через призму абсолютного принятия и понимания психологии ребёнка. Она не из тех "писателей", что, подобно герою одного из её рассказов, встретившись с детьми, тушуется и задаёт нелепые вопросы. Евдокимова уверена: ведь маленькому человеку надо-то всего ничего: мира во всём мире, красок акварельных, петушиное перо, воздушный шарик, железную дорогу, горсть гвоздей, лампу накаливания, чашку с отбитой ручкой, рост до потолка и маленькую крысу. И ещё она знает, в чём разница между обычным днём и первым днём каникул; научит, как получше сообщить родителям, что получил двойку, и как заставить папу слушаться - без дисциплины-то никуда!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'все-будет-в-порядке-944'), 'Все будет в порядке', 'Everything Will Be All Right', 'Sve će biti u redu', 'Валерий Воскобойников', 'Valery Voskoboynikov', 'Valerij Voskobojnikov', 'Книга Валерия Воскобойникова светлая, смешная и чуть-чуть печальная. Этот доверительный рассказ о приключениях, которые происходят с человеком, когда ему еще не исполнилось одиннадцати лет, в полном грозных опасностей и неожиданных радостей мире, надолго останется в памяти у читателя.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'откуда-берутся-дети-945'), 'Откуда берутся дети', 'Where Do Babies Come From?', 'Odakle dolaze djeca', 'Максим Кронгауз, Мария Бурас', 'Maxim Krongauz, Maria Buras', 'Maksim Krongauz, Marija Buras', 'Мария Бурас и Максим Кронгауз - лингвисты и любят поговорить. Эту любовь они передали своим героям. Братья Петя и Ося постоянно разговаривают: с прохожими и козами, с поэтами и аистами, друг с другом. I Им очень нужно узнать, Откуда берутся дети, чтобы помочь маме, которая... Стоп, это ведь подсказка! В общем, рядом с их домом в деревне был магазин, который попал в Книгу рекордов Гиннесса... стоп... а еще капустное поле, где... стоп... и секретный аистодром, откуда... стоп... а соседская девчонка Женька им всё время то мешала, то помогала... Постепенно и героям, и даже читателям становится ясно: если со всеми разговаривать и ничего не бояться, то всё получится. Для дошкольного и младшего школьного возраста');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'брат-юннат-946'), 'Брат-юннат', 'Brother Naturalist', 'Brat prirodnjak', 'Станислав Востоков', 'Stanislav Vostokov', 'Stanislav Vostokov', 'Сергей повернул ко мне нос-крючок и спросил: - Что главное в работе с опасными животными? - Войти в клетку? - предположил я. Сергей покачал головой. - Вовремя из неё выйти! В этой юмористической повести Станислав Востоков рассказывает о том, как начиналась его карьера натуралиста в 90-е годы. Для детей младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'секретный-пес-947'), 'Секретный пес', 'The Secret Dog', 'Tajni pas', 'Станислав Востоков', 'Stanislav Vostokov', 'Stanislav Vostokov', 'Секреты есть у всех: у дошкольников (’секретики’ под стеклом), у бабушек (кулинарные секреты), у бизнесменов (секреты фирмы). Секреты есть у маленьких и больших компаний. Секреты есть у ФСБ и ЦРУ. Так почему их не может быть у собаки? Особенно если она работает в секретном институте.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ветер-делают-деревья-948'), 'Ветер делают деревья', 'The Wind Is Made by Trees', 'Vjetar pravi drveće', 'Станислав Востоков', 'Stanislav Vostokov', 'Stanislav Vostokov', 'Видели вы такие книжки, где взрослые воспитатели делятся опытом с коллегами и рассказывают, как надо обращаться с ребятами в детском саду? Да сколько угодно! А такие, где шестилетние дети размышляют по поводу воспитательской работы, а заодно о смысле бытия, о сложении стихов по методу китайских поэтов-монахов и о том, для чего в манную кашу добавляют комки? Что, не видели? Ну тогда не теряйте времени: открывайте эту книжку - и читайте. Вы узнаете много нового причем не только о детсадовских буднях, но и о жизни вообще!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'детский-садик-13-949'), 'Детский садик 13', 'Kindergarten No. 13', 'Dječji vrtić 13', 'Валерий Роньшин', 'Valery Ronshin', 'Valerij Ronjšin', 'В нашем городе живут мастера выдумки и фантазии, смеха, игр и приключений - в общем, самые настоящие мастера детской литературы! Загляни в город мастеров - там никто не скучает! У одной принцессы был золотой скелет - у всех обычный, а у неё золотой, и вот однажды этот скелет украли... А один мальчик мог проспать целых пять лет подряд! У одной девочки за спиной росли крылья, но никто в это не верил, зато все верили, что один учитель - не обычный человек, а самый настоящий вампир! А в одной семье вообще были одни только инопланетяне, причём с разных планет... Ой, да что мы тут будем всё тебе рассказывать?! Лучше открывай книжку и читай!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вещи-моего-детства-950'), 'Вещи моего детства', 'Things from My Childhood', 'Stvari mog djetinjstva', 'Александра Ершанская', 'Alexandra Ershanskaya', 'Aleksandra Jeršanskaja', 'Саша Ершанская живет шестьдесят лет назад, в другом веке и даже в другой стране. От Саши нас отделяет целая эпоха. Но, не смотря на это, в чем-то мы с Сашей очень похожи. Все мы хотели быть хорошими и уступали место в автобусе бабушкам, переодически путая возраст бабушек и уступая место тридцатилетним девушкам. Все мы любили кататься на велосипедах и иногда с них падали. У многих из нас есть своя удивительная история о том, как мы наконец-то полюбили читать книги. И, конечно, у всех у нас была в жизни первая любовь, первая драка и первое горе. А вот предметы нас окружали совершенно разные. Кто сейчас знает, что такое шайка и зачем нужна керосинка? Мы сегодня не выходим из дома без мобильника, а у наших бабушек и дедушек были монетки на веревочке, чтобы звонить в телефоне-автомате. Мы умеем печатать на компьютере сто знаков в минуту, а им нужно было красиво и без клякс писать перьевой ручкой. Книга Александры Ершанской «Вещи моего детства» - это возможность заглянуть в другое время, в другую эпоху и лучше понять людей, которые там жили, а благодаря этому, возможно, лучше понять и самих себя.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'невероятная-история-о-гиганстс-951'), 'Невероятная история о гиганстской груше', 'The Incredible Story of the Giant Pear', 'Nevjerovatna priča o džinovskoj krušci', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', '«Эта история берёт своё начало в Сульбю, прекрасном городе на берегу моря. Сульбю в переводе с датского означает „Солнечный город“» Все начинается с того, что куда-то пропадает бургомистр! А жители сажают семечко, из которого вырастает гигантская груша. А из груши получается отличный корабль, на котором бесстрашные герои плывут спасать своего бургомистра. Смогут ли они добраться до острова и спасти друга? Якоб Мартин Стрид — невероятный выдумщик из сказочной Дании. Обладая выдающимся талантом карикатуриста и тонким чувством юмора, художник создает удивительный мир героев, которых очень любят дети и их родители. Этот необыкновенный датчанин придумал и нарисовал «Невероятную историю о гигантской груше», а также сюжеты о неугомонном слоненке Мимбо-Джимбо и его друзьях (например, о милом бегемотике Мумбо-Джумбо).');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мимбо-джимбо-играет-952'), 'Мимбо-Джимбо играет', 'Mimbo Jimbo Plays', 'Mimbo Džimbo se igra', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'В новой книге о слоненке Мимбо-Джимбо под названием «Мимбо-Джимбо играет» мы узнаем о том, как он получил посылку с деталями. И вот, как настоящий изобретатель, слоненок сразу же принялся мастерить. Сначала он смастерил машину, а потом из этой самой машины он сделал самолет и распугал попугаев, фламинго и всех, всех, всех... Куда ещё заведёт слонёнка фантазия? Об этом и многом другом мы узнаем на страницах новой книжки. Мимбо-Джимбо — это весёлый дружелюбный слонёнок, которого придумал знаменитый датский художник и писатель Якоб Мартин Стрид. Больше всего на свете Мимбо-Джимбо любит своего лучшего друга бегемотика Мумбо-Джумбо. А ещё ему нравится изобретать и путешествовать. Из-за своей любознательности друзья постоянно попадают в забавные ситуации, о которых вы узнаете в новой серии книг «Мимбо-Джимбо».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мимбо-едет-в-гости-953'), 'Мимбо едет в гости', 'Mimbo Jimbo Visits a Friend', 'Mimbo Džimbo ide u goste', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Мимбо-Джимбо — весёлый дружелюбный слонёнок, которого придумал знаменитый датский художник и писатель Якоб Мартин Стрид. Больше всего на свете Мимбо-Джимбо любит своего лучшего друга бегемотика Мумбо-Джумбо. А еще ему нравится изобретать и путешествовать. Из-за своей любознательности друзья постоянно попадают в забавные ситуации. Однажды Мимбо-Джимбо и Мумбо-Джумбо получили письмо — их пригласила в гости подруга. Конечно, надо немедленно собирать вещи и отправляться в аэропорт! Что же увидят друзья в далёкой стране? Какие приключения ждут их там?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мимбо-и-большие-слоны-954'), 'Мимбо и большие слоны', 'Mimbo Jimbo and the Big Elephants', 'Mimbo Džimbo i veliki slonovi', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Забавная история про то, как слоненок Мимбо-Джимбо отправился в путешествие к своим реальным сородичам — диким слонам, живущими в саванне. Слоненку предстоит пройти долгий путь по пустыне и по джунглям. Но самое главное, как примут большие серые слоны маленького синего Мимбо-Джимбо? Сумеет ли он с ними подружиться?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мимбо-строит-маяк-955'), 'Мимбо строит маяк', 'Mimbo-Jimbo Builds a Lighthouse', 'Mimbo-Džimbo gradi svjetionik', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', '«Мимбо-Джимбо строит маяк» — книга с яркими и веселыми иллюстрациями, которые заинтересуют детей в возрасте от 1 до 5 лет. Красочная, веселая история о слоненке и бегемотике, которые помогают друзьям и зверятам, попавшим в беду, путешествуют и учатся дружить. Больше всего на свете Мимбо-Джимбо любит своего лучшего друга — бегемотика Мумбо-Джумбо. А еще ему нравится изобретать и путешествовать. Из-за своей любознательности друзья постоянно попадают в забавные ситуации. Как-то Мимбо-Джимбо подарили большую лампочку. «Что же с ней делать? — думал слоненок. — Построю-ка я маяк!» Друзья с радостью согласились помочь Мимбо-Джимбо — заготавливали бетонные блоки, возводили стены, строили лестницу, устанавливали окна и двери... Ура, наконец-то можно зажечь маяк! Но... кто это приближается к Мимбо-Джимбо и его друзьям сквозь туман? Детям младшего возраста очень понравятся яркие иллюстрации и добрые персонажи книжки, забавные истории и приключения. А для ребят постарше «Мимбо-Джимбо строит маяк» станет книгой для первого самостоятельного чтения.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мимбо-и-долгая-зима-956'), 'Мимбо и долгая зима', 'Mimbo Jimbo and the Long Winter', 'Mimbo Džimbo i duga zima', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'На весёлого слонёнка Мимбо-Джимбо и его друзей обрушилась беда. Вместо долгожданной весны неожиданно пришла зима — да какая! Такого снегопада в Африке отродясь не видали. Кто же в этом виноват и что теперь делать? Как заставить Дух пушистого снега отправиться обратно на Северный полюс и спасти зверей от холода? Вперёд, навстречу приключениям вместе с Мимбо-Джимбо и его друзьями!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мумбо-джумбо-баба-яга-и-волшеб-957'), 'Мумбо-Джумбо, Баба-Яга и волшебные грибы', 'Mumbo Jumbo, Baba Yaga and the Magic Mushrooms', 'Mumbo Džambo, Baba Jaga i čarobne pečurke', 'Якоб Мартин Стрид', 'Jakob Martin Strid', 'Jakob Martin Strid', 'Мумбо-Джумбо — милый бегемотик, друг слоненка Мимбо-Джимбо. Однажды жители Маленькой долины решили устроить праздник, поэтому все были заняты уборкой, а Мумбо-Джумбо отправили в лес за лисичками для соуса. Бегемот не знал, как выглядят лисички, и попробовал какие-то неизвестные ему грибы. Ой-ой-ой! Мумбо-Джумбо стал великаном! Что же делать? Как помочь нашему другу, знает только Баба-яга, но она живет в далекой-далекой Сибири… Друзья все вместе отправляются в опасное путешествие, чтобы спасти Мумбо-Джумбо. Они доберутся до Сибири, найдут Бабу-ягу, побывают в Москве и… А что будет дальше, вы узнаете, когда прочитаете историю! Если вы прочитали «Невероятную историю о гигантской груше» и ищете что-то похожее, то эта книга точно для вас. «Мумбо-Джумбо, Баба-яга и волшебные грибы» — это невероятные приключения, динамичный сюжет, любимые герои и уютные вечера в кругу семьи. А еще «Мумбо-Джумбо» может стать первой самостоятельно прочитанной вашим ребенком книгой. Крупный шрифт и картинки-комиксы — идеальное сочетание для тех, кто только-только учится читать.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тося-бося-и-сбежавшие-уши-958'), 'Тося-Бося и сбежавшие уши', 'Tosya-Bosya and the Runaway Ears', 'Tosja-Bosja i odbjegle uši', 'Лина Жутауте', 'Lina Žutautė', 'Lina Žutaute', 'Ах, эта Тося-Бося! Не слушала маму, не слушала папу, не слушала бабушку. И так каждый день, по сто раз! Ничего удивительного, что однажды случилось невероятное: уши Тоси-Боси, словно по волшебству, спрыгнули на пол, проскакали через всю кухню, наперегонки пронеслись по коридору, без оглядки вылетели за дверь – и во двор!Если вам любопытно, что случилось дальше – читайте новую книгу о приключениях милой упрямицы Тоси-Боси. И не забудьте поискать, где же спрятались ее уши.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'был-бы-я-взрослым-959'), 'Был бы я взрослым', 'If I Were a Grown-Up', 'Da sam ja odrastao', 'Ева Яниковски', 'Éva Janikovszky', 'Éva Janikovszky', 'Каждый ребенок в душе больше всего на свете мечтает об одном: наконец-то стать взрослым! Ведь тогда-то и начинается жизнь: можно смело ходить по лужам, не мыть руки перед едой и не убирать игрушки! Вот оно - настоящее счастье! Но вот что странно: взрослые почему-то всего этого не делают. Остается только развести руками. Глупые они, эти взрослые. Книга известной венгерской писательницы Евы Яниковски, проиллюстрированная Ласло Ребером, красочно рассказывает именно об этом - о фантазиях одного мальчишки, которого от счастья отделяет лишь пара десятков лет. И вслед за автором так и хочется повторять: "Каждый ребёнок, даже самый маленький, знает, что быть непослушным куда веселее, чем быть паинькой". Чтобы затем задаваться вопросом: "Но если моим детям достанется самый большой надувной шар, самая большая порция мороженого, самая широкая лужа и самый высоченный сугроб, тогда какой мне толк быть ВЗРОСЛЫМ?"');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-кого-пошел-этот-ребенок--960'), 'В кого пошел этот ребенок?', 'Who Does This Kid Take After?', 'Na koga je ovo dijete?', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', '"В кого пошел этот ребенок?" - еще одна трогательная и знакомая всем история о родителях и детях, которые всячески показывают, что не похожи друг на друга, хотя втайне считают совсем иначе...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вечно-со-мной-что-то-случается-961'), 'Вечно со мной что то случается', 'Something Always Happens to Me', 'Uvijek se meni nešto dešava', 'Ева Яниковски', 'Eva Janikovszky', 'Eva Janikovski', 'Искренний и забавный рассказ первоклассника о жизни своей семьи. Каждый день наполнен разными событиями, на которые взрослые не всегда реагируют так, как хотелось бы ребёнку. И в этой круговерти очень важно сохранить взаимопонимание.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ну-вот-опять--962'), 'Ну вот, опять...', 'Here We Go Again...', 'Evo ga opet...', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', 'Очень хочется сделать маме подарок, который потом не окажется в нижнем ящике комода. Очень хочется устроить с другом клуб в подвале. А ещё хочется выиграть приз по лотерейному билету и получить главную роль в фильме… Но больше всего хочется услышать от папы и мамы: "Мы тобой гордимся!"');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'теперь-и-ты-знаешь-963'), 'Теперь и ты знаешь', 'Now You Know Too', 'Sad i ti znaš', 'Ева Яниковски', 'Éva Janikovszky', 'Éva Janikovszky', '"Почему взрослые не хотят играть со мной?" – недоумевает маленький мальчик. И взрослые рассказывают ему, чем они заняты целый день. Вскоре мальчуган узнаёт, чем занимаются почтальон, полицейский, крановщик, врач и даже… пенсионер! А ты знаешь?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'отвечай-когда-тебя-спрашивают-964'), 'Отвечай, когда тебя спрашивают', 'Answer When You''re Spoken To', 'Odgovori kad te pitaju', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', '"Почему ты плачешь?" "Почему ты смеёшься?" "Что ты ещё натворил?"… Как же трудно отвечать на вопросы взрослых! Ведь взрослые давно выросли и забыли, как разговаривать с детьми. Но будьте уверены: вы обязательно узнаете, как это надо делать.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'радуйся-что-девочка-радуйся-чт-965'), 'Радуйся, что девочка/Радуйся, что мальчик', 'Be Glad It''s a Girl / Be Glad It''s a Boy', 'Raduj se što je djevojčica / Raduj se što je dječak', 'Ева Яниковски', 'Eva Janikovszky', 'Éva Janikovszky', 'Будущей маме часто кажется, будто она знает, кто у нее родится. Мальчик? Поздравляем! Девчонки все плаксы и воображалы, а у вас будет защитник, сильный и смелый! Как же вам повезло! Говорите, девочка родилась? Так это замечательно! Уж она-то не подастся в автогонщики и будет всегда рядом с вами, никуда от вас не уедет, а если и уедет, то будет писать письма каждый день! И только ленивый на улице не заметит, как она прекрасна и, несомненно, похожа на вас. Ну и самое главное, она наверняка подарит вам внуков. Что вы говорите? Ей всего сутки? Ну что ж, осталось лишь немного подрасти.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хорошо-мне--966'), 'Хорошо мне!', 'Lucky Me!', 'Baš mi je dobro!', 'Ева Яниковски', 'Éva Janikovszky', 'Eva Janikovski', 'Как же хочется порадовать маму, папу, бабушку, дедушку и младшую сестрёнку! И как же сложно найти то, что обрадует всех… Но мы обязательно разберёмся, кто чему рад!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'азбука-в-картинках-967'), 'Азбука в картинках', 'Alphabet in Pictures', 'Azbuka u slikama', 'Александр Бенуа', 'Alexandre Benois', 'Aleksandar Benoa', 'Азбука в картинах – одна из самых знаменитых книг для детей. Изысканная графика Бенуа - до сих пор непревзойденный образец книжной иллюстрации. Каждая страница Азбуки - это удивительный, завораживающий сказочный мир. Самые первые книги в жизни ребенка непременно должны содержать красочные, красивые иллюстрации. Именно они приоткрывают для малышей дверь в волшебный мир сказок и удивительных историй, пробуждая интерес, развивая фантазию и воображение, постепенно прививая любовь к чтению. Яркие образы, созданные Бенуа, хорошо запоминаются и позволяют ребенку с большим вниманием и интересом заниматься таким сложным делом, как изучение алфавита. Современное издание Азбуки в картинах - точная копия оригинала, вышедшего в 1904 году. Книга ценна не только благодаря удивительным картинам Бенуа, но и благодаря тому, что в ней сохранены все буквы дореволюционного алфавита. Изучение Азбуки в картинах Бенуа вместе с детьми – отличный повод поговорить с ними о российской истории, начать ее подробное изучение.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'игра-в-слова-968'), 'Игра в слова', 'Playing with Words', 'Igra riječima', 'Дарья Герасимова', 'Daria Gerasimova', 'Darja Gerasimova', 'Книги Дарьи Герасимовой смешные, необычные и вместе с тем добрые и искренние. Малыш знакомится с каждой буквой через авторские иллюстрации и ритмичный белый стих, где почти в каждом слове используется изучаемая буква.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'такие-разные-буквы-969'), 'Такие разные буквы', 'Such Different Letters', 'Tako različita slova', '', 'David Plaksin', 'David Plaksin', 'Художник Давид Плаксин придумал не совсем обычную азбуку. В обычной азбуке все, что нарисовано, представляют существительные. А в этой азбуке о каждой букве рассказывают имена прилагательные. Умные школьники уже в первом классе знают, что прилагательное - это часть речи, которая обозначает качество, свойство или принадлежность предметов. Вот и здесь все буквы не просто названы, они действительно обладают своими качествами и характерами, иногда неожиданными, поэтому их разглядывать и запоминать - одно удовольствие. Но главное - из слов, придуманных Давидом Плаксиным, можно составить настоящую сказочную историю про все буквы нашего алфавита.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'азбука-искусство-конца-xix-xx--970'), 'Азбука: искусство конца XIX-XX веков', 'ABC: Art of the Late 19th and 20th Centuries', 'Azbuka: Umjetnost s kraja XIX i XX vijeka', '', 'Pushkin State Museum of Fine Arts', 'Državni muzej likovnih umjetnosti Puškin', 'Тридцать три картины на каждую букву алфавита из собрания Государственного музея изобразительных искусств имени А.С.Пушкина в Москве');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кротик-большая-книга-971'), 'Кротик большая книга', 'The Big Book of Little Mole', 'Krtić: Velika knjiga', 'Зденек Миллер', 'Zdeněk Miler', 'Zdenjek Miler', 'В Большой книге Кротика собраны самые любимые истории про героев: "Кротик и штанишки", "Кротик и телевизор", "Кротик и автомобильчик" и "Кротик и ракета". Книга с большим количеством иллюстраций из мультфильмов про Кротика, дополненных текстом про приключения героев – то, что нужно, чтобы маленький читатель не устал. Эту книгу можно просто рассматривать, как книжку-картинку, рассказывая вместе с ребенком свою историю про героев по иллюстрациям или же приглашать ребенка читать самостоятельно.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кротик-лучшие-истории-972'), 'Кротик лучшие истории', 'The Little Mole: Best Stories', 'Krtić: Najbolje priče', 'Зденек Миллер', 'Zdeněk Miler', 'Zdenjek Miler', 'Приключения доброго, веселого Кротика, придуманного Зденеком Милером еще полвека назад, по-прежнему приводят детей в восторг. По многочисленным просьбам родителей выпускаем второй сборник, в который вошли самые лучшие истории про Кротика: "Кротик и зонтик", "Кротик и Орел" и "Как Кротик вылечил Мышку".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'приключения-бабара-973'), 'Приключения Бабара', 'The Adventures of Babar', 'Babarove avanture', 'Жан де Брюнофф', 'Jean de Brunhoff', 'Žan de Brenof', 'Знакомьтесь, этого слона в зелёном костюме зовут Бабар. Французский писатель и иллюстратор Жан де Брюнофф придумал его в 1931 году, и с тех пор Бабар стал одним из самых любимых и известных персонажей по всему миру. Книги про него были переведены на 17 языков, по ним были сняты мультсериалы и анимационные фильмы. В эту книгу вошли истории о невероятных событиях в жизни Бабара. Он попадает в большой город, путешествует на воздушном шаре, плавает на спине кита в открытом море, строит прекрасный город для слонов в джунглях и попадает в дом Деда Мороза! Читайте о всех увлекательных приключениях слонёнка Бабара в этой книге!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чудесное-путешествие-нильса-с--974'), 'Чудесное путешествие Нильса с дикими гусями', 'The Wonderful Adventures of Nils', 'Čudesno putovanje Nilsa sa divljim guskama', 'Сельма Лагерлеф', 'Selma Lagerlöf', 'Selma Lagerlef', 'Однажды мальчишка Нильс решил пошутить над гномом, и стал маленьким. Его путешествие со стаей гусей описаны Сельмой Лагерлёф и проиллюстрирована Е. Мешковым. Знаменитая сказка шведской писательницы, лауреата Нобелевской премии не только развивает воображение малышей, но и в увлекательной, волшебной, нескучной форме даёт им знания о зоологии и географии. Крупный текст, ударения в словах, полное соответствие требованиям САНПИН. Учиться читать так интересно!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дагфрид-девочка-без-завитушек--975'), 'Дагфрид. Девочка без завитушек над ушами', 'Dagfrid: A Viking Girl Without Pastry Buns', 'Dagfrid: Djevojčica bez uvojaka', 'Аньес Матьё-Доде', 'Agnès Mathieu-Daudé', 'Anjes Matje-Dode', 'Многое в собственной жизни удручает Дагфрид. Одно имя чего стоит! Да и в остальном участь девочки-викинга счастливой не назовёшь: приходится заплетать волосы в косы и укладывать их в завитушки над ушами, носить платья до пят и вялить рыбу, единственную пищу викингов. А ещё девочкам не разрешают выходить в море и открывать Америку! Но вечно так продолжаться не могло. Настал день, когда рыба вконец опротивела Дагфрид...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'саша-и-маша-1-976'), 'Саша и Маша 1', 'Jip and Janneke 1', 'Saša i Maša 1', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Ani M.G. Šmit', 'Вы - молодцы! Вы купили замечательную книжку! И очень знаменитую. В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешные и интересные истории про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке... Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г.Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ганса Христиана Андерсена. Мы надеемся, что книжка про Сашу и Машу вам понравится. И не расстраивайтесь, что она так быстро закончилась, - мы приготовили для вас еще много смешных приключений этих детей. Не успеете вы дочитать одну книжку, как в магазинах появится следующая!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'саша-и-маша-2-977'), 'Саша и Маша 2', 'Jip and Janneke: Book 2', 'Saša i Maša 2', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Annie M.G. Schmidt', 'В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешных и интересных историй про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке… Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г. Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ханса Кристиана Андерсена.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'саша-и-маша-3-978'), 'Саша и Маша 3', 'Sasha and Masha 3', 'Saša i Maša 3', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Annie M.G. Schmidt', 'В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешных и интересных историй про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке… Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г. Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ганса Христиана Андерсена.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'саша-и-маша-4-979'), 'Саша и Маша 4', 'Jip and Janneke 4', 'Saša i Maša 4', 'Анни Шмидт', 'Annie M.G. Schmidt', 'Ani M. G. Šmit', 'В стране Голландии нет ни одной мамы, ни одного папы, ни одного мальчика и ни одной девочки, которые бы не знали и не любили смешных и интересных историй про Сашу и Машу. Только в Голландии этих детей зовут Йип и Йанеке… Трудные имена, правда? Поэтому мы решили, что в России их будут звать Саша и Маша. Написала эту книжку Анни М. Г. Шмидт. Самая знаменитая голландская писательница. Она написала очень много разных историй и сказок, и даже получила самую главную премию всех детских писателей в мире - имени Ганса Христиана Андерсена.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'люди-и-разбойники-из-кардамона-980'), 'Люди и разбойники из Кардамона', 'When the Robbers Came to Cardamom Town', 'Ljudi i razbojnici iz Kardamoma', 'Турбьерн Эгнер', 'Thorbjørn Egner', 'Torbjern Egner', 'Не во всяком городке можно встретить ручного льва, говорящего верблюда и самого доброго в мире полицмейстера. Но в Кардамоне с ними может познакомиться каждый. Кроме того, жители городка без билета катаются на двухэтажном трамвае, где поют песни и едят ароматные пряники. Правда, иногда в Кардамон наведываются разбойники, но от этого жизнь там становится только интереснее! Книга впервые появилась в СССР в 1956 году и с тех пор пользуется огромной популярностью. Изначально книга была опубликована в Норвегии с иллюстрациями и нотами самого автора - они сохранены в новом издании.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вертихвост-981'), 'Вертихвост', 'Claus Climbermouse and the Other Animals in the Huckybucky Forest', 'Penjalica i ostale životinje iz Hakebake šume', 'Турбьерн Эгнер', 'Thorbjørn Egner', 'Turbjern Egner', 'Мышонок Мортен в своём лесу Пригорок-Сорок-норок был меньше всех. Серенький пшик с хвостом, да и только. Зато парень он был хороший, трудился честно, прилежно и в чужую жизнь не лез. Вот бы, думал мышонок, все брали пример с меня и никого не обижали. К сожалению, пока что это не так. Но Мортен знает, как исправить дело! Настоящее издание представляет собой новый полный перевод книги Турбьёрна Эгнера, ранее выходившей под названием "Приключения в лесу Ёлки-на-Горке".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кариус-и-бактериус-982'), 'Кариус и Бактериус', 'Karius and Baktus', 'Karijus i Baktus', 'Турбьерн Эгнер', 'Thorbjørn Egner', 'Turbjern Egner', 'Эта история приключилась с мальчиком Йенсом, который обожал сладости, но очень не любил чистить зубы. Маленькие человечки построили два уютных дома у него во рту. Как вы думаете, каково было Йенсу? Для детей дошкольного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'папа-мама-8-детей-и-грузовик-983'), 'Папа, мама, 8 детей и грузовик', 'Eight Children and a Truck', 'Tata, mama, osmoro djece i kamion', 'Анне Вестли', 'Anne-Cath. Vestly', 'Ane-Kat. Vestli', 'Увлекательные повести о дружном и веселом семействе, в котором ни минуты не бывает тихо, потому что Марен любит танцевать, Мартин - прыгать, Мадс - стучать, Мона - петь, Милли - бить в барабан, Мина - вопить, а Малышка Мортен - колотить чем попало по всему, до чего только дотянется. Жить такой большой семьей, конечно, не просто, но зато тут никто никогда и не скучает. Норвежская писательница Анне-Катарина Вестли, придумавшая истории про дом, где растут сразу восемь мальчиков и девочек, популярна во всей Европе, наверное, не меньше, чем знаменитая Астрид Линдгрен. Герои ее книг - люди простые, но очень симпатичные: добрые, честные, трудолюбивые. Взрослые здесь не теряют умения относиться с юмором к себе самим и друг к другу, какие бы уроки ни преподносила им жизнь. А главное, они удивительно хорошо понимают своих детей и сохраняют это понимание, что бы те ни натворили и что бы еще ни напридумывали.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленький-подарок-антона-984'), 'Маленький подарок Антона', 'Anton''s Little Gift', 'Antonov mali poklon', 'Анне Вестли', 'Anne-Cath. Vestly', 'Ane-Kat. Vestli', 'Помните замечательную книжку про "Папу, маму, бабушку, восемь детей и грузовик"? Ну так вот: теперь у вас в руках новый сборник увлекательных повестей о дружном и веселом семействе, в котором ни минуты не бывает тихо, потому что Марен любит танцевать, Мартин - прыгать, Мадс - стучать, Мона - петь, Милли - бить в барабан, Мина - вопить, а Малышка Мортен - колотить чем попало по всему, до чего только дотянется. Жить такой большой семьей, конечно, не просто, но зато тут никто никогда и не скучает. Норвежская писательница Анне-Катарина Вестли, придумавшая истории про дом, где растут сразу восемь мальчиков и девочек, популярна во всей Европе, наверное, не меньше, чем знаменитая Астрид Линдгрен. Герои ее книг - люди простые, но очень симпатичные: добрые, честные, трудолюбивые. Взрослые здесь не теряют умения относиться с юмором к себе самим и друг к другу, какие бы уроки ни преподносила им жизнь. А главное, они удивительно хорошо понимают своих детей и сохраняют это понимание, что бы те ни натворили и что бы еще ни напридумывали.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мах-и-шебестова-путешествуют-985'), 'Мах и Шебестова путешествуют', 'Mach and Šebestová on Their Travels', 'Mah i Šebestova putuju svijetom', 'Милош Мацуорек', 'Miloš Macourek', 'Miloš Macourek', 'Смешной мальчишка в круглых очках и девчонка с большим бантом, а также их верный друг пёс Йонатан родом из Чехии, где их имена известны чуть ли не каждому жителю страны. И в этом нет ничего удивительного, ведь мультфильмы и книги о приключениях этой троицы начали выходить в Чехии с 1982 года и принесли главным героям огромнейшую популярность и всенародную любовь. Мах и Шебестова - самые обычные ученики начальной школы. Они учатся в одном классе, живут в одном подъезде и любят в свободное от уроков время играть с соседским псом по имени Йонатан. Правда, в распоряжении Маха и Шебестовой есть один необычный предмет - волшебная телефонная трубка, исполняющая любые желания того, кто в неё говорит (о том, как трубка попала в руки детей можно узнать из книги "Мах и Шебестова - волшебники из 3 "Б"). На этот раз Маху и Шебестовой предстоит головокружительное путешествие по всему земному шару. Волшебная трубка помогает друзьям переместиться то в Париж, то на Северный полюс, то в Перу, то в Африканскую деревню, то в Австралию, то в Голливуд, то на Гавайские острова - и повсюду их ждут удивительные приключения. Что самое интересное, Маху и Шебестововой никогда не приходит в голову воспользоваться трубкой ради собственной выгоды. Они прибегают к ее помощи исключительно ради того, чтобы выручить из беды кого-то из своих друзей, а то и вовсе незнакомых им людей, то есть ведут себя как настоящие супергерои! Для детей младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'налле-лапсон-986'), 'Налле Лапсон', 'Nalle Lapson', 'Nale Lapson', 'Йоста Кнутсон', 'Gösta Knutsson', 'Jesta Knutson', 'Налле Лапсона придумал шведский писатель, переводчик и режиссер Йоста Ларс Август Кнутсон (1908-1973) в 1949 году. Налле Лапсон - маленький медвежонок с глазами-бусинками, проснувшись от зимней спячки, не нашел свою маму и отправился в путешествие. Медвежонка ждет множество приключений, он находит настоящих друзей - девочку Лотту и собаку Тяпку, учится читать и считать, путешествует на автомобиле. В Швеции Налле Лапсон так же знаменит, как Винни-Пух и Паддингтон. Это первая книга, в которой медвежонок знакомится со своей подружкой Лоттой.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'налле-лапсон-берется-за-дело-987'), 'Налле Лапсон берется за дело', 'Nalle Lapson Takes Charge', 'Nale Lapson se baca na posao', 'Йоста Кнутсон', 'Gösta Knutsson', 'Jesta Knutson', 'Налле Лапсона придумал шведский писатель, переводчик и режиссер Йоста Ларс Август Кнутсон (1908-1973) в 1949 году. Налле Лапсон - маленький медвежонок с глазами-бусинками, проснувшись от зимней спячки, не нашел свою маму и отправился в путешествие. Медвежонка ждет множество приключений, он находит настоящих друзей - девочку Лотту и собаку Тяпку, учится читать и считать, путешествует на автомобиле. В Швеции Налле Лапсон так же знаменит, как Винни-Пух и Паддингтон. Это вторая книга, в которой Налле Лапсон ловит вора.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'налле-лапсон-и-тяпка-988'), 'Налле Лапсон и Тяпка', 'Nalle Lufs and Skrutten', 'Nale Lapson i Tjapka', 'Йоста Кнутсон', 'Gösta Knutsson', 'Jesta Knutson', 'Налле Лапсона придумал шведский писатель, переводчик и режиссер Йоста Ларе Август Кнутсон (1908-1973) в 1949 году. Налле Лапсон - маленький медвежонок с глазами-бусинками, проснувшись от зимней спячки, не нашел свою маму и отправился в путешествие. Медвежонка ждет множество приключений, он находит настоящих друзей - девочку Лотту и собаку Тяпку, учится читать и считать, путешествует на автомобиле. В Швеции Налле Лапсон так же знаменит, как Винни-Пух и Паддингтон. Это третья книга, в которой Налле Лапсон отправляется в путешествие со своим другом Тяпкой.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'адольфус-типс-и-ее-невероятная-989'), 'Адольфус Типс и ее невероятная история', 'The Amazing Story of Adolphus Tips', 'Nevjerovatna priča o Adolfus Tips', 'Майкл Морпурго', 'Michael Morpurgo', 'Majkl Morpurgo', '«Адольфус Типс и ее невероятная история» погружает читателя в трудные будни прибрежной английской деревушки, которая в годы Второй мировой войны оказалась в зоне размещения союзных войск. Семья Лили вынуждена покинуть родную ферму, но девочка не может оставить на произвол судьбы свою любимицу – своенравную серую кошку. За эти месяцы изгнания Лили обретет дружбу, которая продлится долгие десятилетия, а кошка обзаведется звучным именем – Адольфус Типс.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'орел-на-снегу-990'), 'Орел на снегу', 'An Eagle in the Snow', 'Orao na snijegu', 'Майкл Морпурго', 'Michael Morpurgo', 'Majkl Morpurgo', 'Когда-то, сражаясь на полях Первой мировой войны, Билли Барни поступил по совести и проявил милосердие к врагу. Но его благородный поступок обернулся трагедией для всего мира. И пока еще не стало слишком поздно, он должен исправить свою ошибку, искоренить зло. У него просто нет выбора…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'трудно-быть-львом-991'), 'Трудно быть львом', 'It''s Hard to Be a Lion', 'Teško je biti lav', 'Ури Орлев', 'Uri Orlev', 'Uri Orlev', 'Признайтесь, вы когда-нибудь мечтали стать могучим диким зверем? Чтобы одним ударом лапы победить всех врагов? Нет? А вот герой этой книги с детства хотел побыть львом, чтобы хоть на миг ощутить себя сильным, дерзким - и совершенно свободным. И представьте, его мечта сбылась! Однажды он проснулся и убедился, что он уже не человек, а самый настоящий лев. Вам предстоит узнать, каково ему было жить львом с человеческим разумом, стал он вольным зверем или оказался запертым в клетке, остался в городе или пробрался в Африку... И удалось ли ему снова стать человеком? Прочитав эту книгу, вы наверняка согласитесь с автором, известным израильским писателем Ури Орлевым, что быть львом очень даже нелегко.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лоранга-мазарин-и-дартаньян-992'), 'Лоранга, Мазарин и Дартаньян', 'Loranga, Masarin and Dartanjang', 'Loranga, Mazarin i Dartanjan', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', 'Лоранга слушает только эстрадную музыку, от остальной у него болит живот! Его сын Мазарин ест булочки, читает комиксы и слоняется без дела. По соседству, чтобы на него не попадали микробы, живет дедушка Дартаньян. Они покупают тиграм по тысяче сосисок, болеют "лайрингитом", кормят прапрадедушку семечками, сталкиваются со щуками в собственном гараже, играют в хоккей за Россию и Канаду швабрами и незрелым помидором - и вообще ведут себя самым неподобающим образом. Но несмотря на это Лоранга и его семейство любимы и популярны в Швеции уже почти 40 лет. Став героями мультфильма, аудиокниг, театральных постановок, они к тому же спели в Королевской опере в Стокгольме! А теперь эта троица заговорила по-русски и не прочь с тобой познакомиться...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'меня-зовут-мина-993'), 'Меня зовут Мина', 'My Name Is Mina', 'Zovem se Mina', 'Дэвид Алмонд', 'David Almond', 'Dejvid Almond', 'Дэвид Алмонд пишет просто. Просто, но о самом сложном. О вопросах, которые бередят душу, когда человеку десять-двенадцать лет, а взрослые не знают ответа: правда ли, что наши лопатки были когда-то крыльями? Могут ли ожить глиняные фигурки, если постараться и слепить их очень хорошо? Помогает ли любовь от болезней? Алмонд пишет так, что его читают дети и взрослые по всему миру - его книги переведены более чем на два десятка языков. В 2010 году он стал лауреатом премии имени Андерсена - высшей награды в мире детской литературы. А всех его наград не счесть. Книга "Скеллиг", написанная в 1998 году, получила медаль Карнеги и Уитбредовскую премию. В 2008 году вышел одноимённый фильм с Тимом Ротом в главной роли. Повесть "Меня зовут Мина" предваряет события, которые развернутся в "Скеллиге". …У Мины не было друзей, её считали странной. Не было отца, он умер. Зато у неё была мама - самая лучшая, всё понимающая мама - и целый мир в голове. Потому что голова - это место для чудес. Но как найти того, с кем можно ими поделиться?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'медвежонок-паддингтон-994'), 'Медвежонок Паддингтон', 'A Bear Called Paddington', 'Medvjedić Padington', 'Майкл Бонд', 'Michael Bond', 'Majkl Bond', 'В канун Рождества 1956 года в большом лондонском магазине писатель Майкл Бонд наткнулся на симпатичного игрушечного медвежонка. Бонд купил мишку и назвал Паддингтоном — в честь близлежащего вокзала. А в 1958 году мир впервые познакомился с неунывающим медвежонком, прибывшим из Дремучего Перу прямиком на Паддингтонский вокзал. Так возник новый литературный символ Англии — книги о Паддингтоне переведены на сорок языков, ему стоит памятник на одноименном вокзале, а туристы бойко раскупают игрушечных медвежат в синих пальтишках. Приключения Паддингтона продолжаются уже более шестидесяти лет — такой уж это медведь! С ним никогда не бывает скучно.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'соседи-995'), 'Соседи', 'Neighbors', 'Komšije', 'Кася Денисевич', 'Kasya Denisevich', 'Kasja Denisevič', 'Город полон домов, в доме много квартир. Кто они, наши Соседи? * Лучшая книга 2020 года, вышедшая США и написанная иностранным автором * Атмосфера московских улочек * Глубокое понимание сомнений и волнений ребенка О тех, кто живет рядом с нами, но при этом загадочно неуловимы. Соседи - они снизу, наверху, сбоку. Но мы часто даже не знаем как они выглядят, и можем догадываться об их присутствии по звуку захлопнутой двери, шагам...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'привет-москва--996'), 'Привет, Москва!', 'Hello, Moscow!', 'Zdravo, Moskva!', 'Таня Борисова', 'Tanya Borisova', 'Tanja Borisova', 'Таня Борисова живет в Москве, любит ходить на пленэр и делать городские зарисовки. Из них и родилась эта книга - увлекательное обозрение российской столицы, какой она открывается любителю кататься на велосипеде. Люди, здания, музеи и достопримечательности складываются в живой и запоминающийся образ уютного мегаполиса. Это прекрасный повод впервые познакомиться с Москвой - как для ее юных гостей и читателей из других мест России и мира, так и для самих москвичей, у каждого из которых свой образ города, неизбежно оставляющий за кадром многое из того, что в нем есть. Автор показывает Москву с личной и непринужденной точки зрения, предлагает по-новому взглянуть на знакомые места, научиться обращать внимание на интересные здания, музейные экспонаты, устройство города и привычки его жителей. Во время остановок по ходу воображаемой велосипедной прогулки у читателей будет случай поразмышлять о том, есть ли у них свои любимые места и здания, какие музеи им особенно нравятся и почему, а заодно узнать немало примечательных фактов из истории и современной жизни Москвы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'буквальная-москва-997'), 'Буквальная Москва', 'Alphabetical Moscow', 'Bukvalna Moskva', 'Александр Голубев', 'Alexander Golubev', 'Aleksandar Golubev', 'Москва! Как много в этом звуке… Чтобы ничего не упустить, пройдись по достопримечательностям столицы от "А" до "Я". Маршрут тебе подскажет книга "БУКВАльная Москва", а компанию составят два весёлых приятеля - старый знакомый питерский кот Батон и его столичный добрый друг кот Бульон. Будь уверен, эти двое пробежались по всем закоулкам Златоглавой и Белокаменной… Кстати, хочешь узнать, почему Москву так называют? Тогда присоединяйся к ним скорее!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'путеводитель-по-московскому-ме-998'), 'Путеводитель по московскому метр с Тимкой и Тинкой', 'Moscow Metro Guide with Timka and Tinka', 'Vodič kroz moskovski metro sa Timkom i Tinkom', '', 'Unknown', 'Nepoznati autor', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пешком-по-петербургу-с-тимкой--999'), 'Пешком по Петербургу с Тимкой и Тинкой', 'Walking Through St. Petersburg with Timka and Tinka', 'Šetnja po Sankt Peterburgu sa Timkom i Tinkom', '', 'Unknown', 'Nepoznati autor', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чудо-1000'), 'Чудо', 'Leaf', 'Čudo', 'Сандра Дикманн', 'Sandra Dieckmann', 'Sandra Dikman', 'Книга, которая восхищает в первую очередь своей красотой и волшебными атмосферными иллюстрациями, не оставляя никого равнодушным. Несмотря на то что это первая книга художника Сандры Дикманн, она была высоко оценена международным литературным сообществом. Для автора важна проблема экологии - таяние льдов в Арктике и судьба полярных медведей. Через историю белого медведя автор обращается к этой теме и к проблеме чужаков вообще, толерантности, приятия, взаимопомощи и взаимовыручки. То, что на первый взгляд может показаться странным, при ближайшем рассмотрении оказывается настоящим чудом и таит в себе массу возможностей, чтобы стать добрее, мудрее и человечнее.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пес-проглотивший-мир-1001'), 'Пес, проглотивший мир', 'The Dog That Swallowed the World', 'Pas koji je progutao svijet', 'Сандра Дикманн', 'Sandra Dieckmann', 'Sandra Dikman', 'Однажды в цветущей долине появился огромный черный пёс. Он ломал деревья, сворачивал леса, опустошал реки и моря. Звери и птицы не могли остановить его. Пёс ел всё, что пожелает. Вскоре он проглотил и всех жителей долины! И тогда, окутанные тьмой, звери и птицы решили объединиться и построить новый мир... На иллюстрациях Сандры Дикманн мир дикой природы наполнен волшебством и чудесами. Художник рассказывает глубокую и удивительную историю о дружбе, взаимопомощи и поддержке в самые трудные времена.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дома-и-домики-в-бермудском-тре-1002'), 'Дома и домики в бермудском треугольнике', 'Houses and Tiny Houses in the Bermuda Triangle', 'Kuće i kućice u Bermudskom trouglu', 'Маша Краснова-Шабаева', 'Masha Krasnova-Shabaeva', 'Maša Krasnova-Šabajeva', 'Увлекательнейшее занятие - разглядывать устройство домов и домиков! Но заглянуть в домики, которые построены в Бермудском треугольнике, может только человек с невероятной фантазией! Такой, как у художницы Маши Красновой-Шабаевой! Она рисует для The New York Times, Esquire, GQ, устраивает выставки и выпускает иллюстраторские зины, и может показать в своих иллюстрациях даже мир, который никто не видел - удивительные дома Безумного Леса, республики Насекоми, города Ветров или острова Оранжерей. И даже научит их конструировать из того, что есть под рукой и воображения!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'умеешь-ли-ты-хранить-секреты--1003'), 'Умеешь ли ты хранить секреты?', 'Can You Keep a Secret?', 'Umiješ li čuvati tajne?', 'Мелисса Кастрильон', 'Melissa Castrillón', 'Melissa Castrillón', 'Сможешь ли ты сохранить в секрете встречу с настоящим драконом? Однажды Винни повстречала дракона, а также его удивительных друзей — грифона, крылатого льва и древочеловека — последних волшебных существ на всём белом свете. Если кто-то узнает об их существовании, может случиться беда. Сумеет ли Винни сохранить этот секрет?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'супер-обычный-день-1004'), 'Супер обычный день', 'On a Magical Do-Nothing Day', 'Jedan sasvim običan dan', 'Беатриче Алеманья', 'Beatrice Alemagna', 'Beatriče Alemanja', 'Что делать на даче, пока мама работает, а за окном льет дождь? Конечно, играть в приставку, стрелять марсиан! Жаль, мама не согласна и ворчит, что это пустая трата времени! Но, оказывается, на улице, без приставки, тоже есть жизнь, да еще и какая волшебная…Невероятная реальность самого обычного дня в иллюстрациях Беатриче Алеманьи (одной из самых известных художниц книги в мире) завораживает и героя книги, и читателей. Вместе мы заблудимся в лесу, увидим мельтешение неизвестных микроштук в земле, волшебные камушки в пруду и удивительный свет сквозь тучи, услышим грохот собственного сердца. Так удивляться миру могут только дети и самые талантливые авторы детских книг! В этом упоении звуками, видами, шумом природы Беатриче Алеманья высвечивает (в буквальном смысле — своей потрясающей работой с цветом и фактурой) — возможности и необходимость природы для человека. Причем, все это — с ощущением игры и восторга, а не назидательности. Издания книг Беатриче Алеманьи на русском давно ждали многие любители иллюстрации. В 2014 году она приезжала с мастер-классами в Россию.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вся-правда-о-пиратах-1005'), 'Вся правда о пиратах', 'The Whole Truth About Pirates', 'Prava istina o piratima', 'Екатерина Степаненко', 'Ekaterina Stepanenko', 'Jekaterina Stepanenko', 'Просоленные насквозь морским ветром, бесстрашные и свободные, одноногие и одноглазые, с саблей в одной руке и с бутылкой рома в другой. Сражаются они так же неистово, как и ищут сокровища, не боятся ни Бога, ни дьявола, и нет никого, кто бы не трепетал при виде их чёрного флага с черепом и костями! Конечно же, речь о пиратах. Такими рисуют их книги и фильмы и так мы привыкли себе их представлять. Но много ли общего у такого романтического героя с настоящим морским разбойником? Эта книга приглашает читателей в путешествие по морям и океанам, где в разные века плавали пиратские суда, на необитаемые острова, где пираты прятали сокровища, и в порты, где они набирали команду. Она развеет мифы и расскажет всю правду о пиратах! Вам откроется подлинная разбойничья жизнь, полная страхов и опасностей, жестокая, неприглядная, а главное, очень короткая. Вы узнаете, когда появились пираты, на каких кораблях они плавали, кто и почему выбирал себе эту «профессию», действительно ли пираты не признавали никакого закона и никого не боялись.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'удивительные-самолеты-1006'), 'Удивительные самолеты', 'Amazing Airplanes', 'Čudesni avioni', '', 'Tony Mitton', 'Toni Miton', 'Книжка для маленьких. Они узнают в веселой красочной книжке о том, как летают самолеты и из чего они состоят. Стихи помогут малышам легко запомнить историю. Тони Миттон родился в Триполи и провел детство в Северной Африке, Германии и Гонконге. Он закончил затем Кембриджский Университет. Окончив университет он какое-то время работал учителем в школе. Но потом оставил учительство, полностью сосредоточившись на написании детских книг.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'корабли-1007'), 'Корабли', 'Ships', 'Brodovi', 'Али Митгуш', 'Ali Mitgutsch', 'Ali Mitgutsch', 'Щедро иллюстрированная книга знаменитого немецкого художника Али Митгуша (основоположника жанра "виммельбух") посвящена истории освоения человеком водной стихии и эволюции плавательных средств. Читателей ждет увлекательное путешествие во времени: благодаря мастерству художника можно во всех подробностях рассмотреть древние лодки и первые корабли Тихого океана, берестяные каноэ индейцев, финикийские биремы, драккары викингов, ганзейские когги, парусники времен великих географических открытий, пароходы и баржи 19 века и разнообразные современные корабли специального назначения. Книга расскажет об истории водолазного дела, рыболовного промысла, об устройстве старинных и современных маяков, о самых важных навигационных приборах и о принципах работы различных движителей. Книга Али Митгуша насыщена интересными и редкими фактами, она познавательна и уникальна в своем роде - ведь это, с одной стороны, визуальная история навигации от первобытных времен до наших дней, а с другой - настоящий гимн человеческому разуму, изобретательности и смекалке. Несмотря на относительно небольшое количество текста этот виммельбух достаточно информативен, чтобы удовлетворить запросы даже вполне эрудированных читателей, поэтому его будет интересно изучать как дошкольникам, так и детям более старшего возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'жизнь-одного-корабля-1008'), 'Жизнь одного корабля', 'The Life of a Ship', 'Život jednog broda', 'Инноченти Роберто', 'Roberto Innocenti', 'Roberto Inoćenti', 'Это книга о капитане и его корабле по имени «Клементина». Моряк рассказывает историю своего судна с начала 1930-х годов, когда оно было построено на верфи, и до его гибели. Ступив на борт «Клементины» еще мальчишкой, он провёл на этом грузовом судне почти всю жизнь, пройдя путь от юнги до капитана. С «Клементиной» он смог увидеть весь мир: Гавану и Валенсию, Панаму и Нью-Йорк, Лиссабон и Ливерпуль. «Клементина» побывала с мирными грузами в самых экзотических странах, во время войны через воды Арктики возила боеприпасы и технику для Красной Армии, а в конце своей долгой трудовой жизни обрела покой на морском дне. Капитан стоял за штурвалом своей «Клементины» до самой её гибели. Вместе они совершают путешествие длиною в жизнь. Корабль и его история оживают в удивительных, подробных иллюстрациях Роберто Инноченти, которые показывают, как менялся мир с 1930-х до 1980-х годов. Вместе с моряками мы становимся свидетелями сменяющих друг друга исторических событий: гражданской войны в Испании, Второй мировой войны, забастовок 1980-х годов в Польше, а также любуемся разнообразием пейзажей самых разных уголков мира: Полинезии и Индии, Америки и Европы, извержением вулкана, арктическими льдами, картинами мирной жизни и морских сражений. Историю жизни корабля дополняет карта мирных и военных маршрутов «Клементины», а также схемы внутреннего устройства судна от носа до кормы и от мачт до трюма. Сама «Клементина» - выдуманное судно, но ее судьба повторяет истории многих грузовых кораблей того времени.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-я-поменял-одного-папу-на-д-1009'), 'Как я поменял одного папу на двух золотых рыбок', 'The Day I Swapped My Dad for Two Goldfish', 'Dan kad sam zamijenio tatu za dvije zlatne ribice', 'Нил Гейман', 'Neil Gaiman', 'Nil Gejman', 'Нил Гейман - английский писатель-фантаст, автор графических романов и комиксов, сценариев к фильмам. Среди самых известных его работ - "Звездная пыль", "Американские боги", "Коралина", "Никогде", серия комиксов "Песочный человек". Гейману присуждены многие награды, включая премию "Хьюго", премию "Небьюла", премию Брэма Стокера, медаль Ньюбери. Книгу "Как я поменял одного папу на двух золотых рыбок" проиллюстрировал британский графический художник, фотограф и автор комиксов Дэйв МакКин. Его смешанная техника - причудливое сочетание рисунков и фотографий - превратила сюрреалистичный мир сказки Геймана о том, как важна семья, в завораживающее произведение искусства. Книга завоевала награду журнала Newsweek как лучшая детская книга года, получила премию Британской ассоциации научной фантастики за короткую художественную прозу и стала основой спектакля Национального театра Шотландии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'книга-без-названия-1010'), 'Книга без названия', 'Help! We Need a Title!', 'Knjiga bez naslova', 'Эрве Тюлле', 'Hervé Tullet', 'Erve Tile', 'Эта книга – ещё¸ не вполне книга, а только черновик. Впрочем, в ней уже есть свои персонажи (набросанные на скорую руку) и автор (по уши в работе!).');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'барсук-в-доме-1011'), 'Барсук в доме', 'A Badger in the House', 'Jazavac u kući', 'Лиза Рагвальс', 'Lisa Ragvals', 'Lisa Ragvals', 'Как-то раз в самой обычной семье поселился барсук. Но можно ли держать барсуков в доме? Аббе считает, что можно. Вскоре барсук занимает всю комнату и прорывает ход в квартиру этажом ниже. Что же будет дальше?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'почтальон-мышка-1012'), 'Почтальон Мышка', 'Here Comes Mr. Postmouse', 'Poštar Miš', 'Марианна Дюбюк', 'Marianne Dubuc', 'Marijana Dibik', 'Вы бывали дома у крокодилов? А у пингвинов? Нет? Тогда отправляйтесь вслед за Почтальоном Мышкой. Он разносит почту жителям необычной деревни: гнёзда и норы пещеры и коттеджи, хижины и игру полны забавных деталей, которые расскажут много интересного о тех, кто здесь живёт. А напоследок Почтальон Мышка доставит один маленький подарок - угадайте, кому!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'невероятные-приключения-почтал-1013'), 'Невероятные приключения почтальона Мышки', 'The Incredible Adventures of Mr. Postmouse', 'Nevjerovatne pustolovine poštara Mišića', 'Марианна Дюбюк', 'Marianne Dubuc', 'Marijana Dibik', 'Вот кто самый отважный почтальон на свете! Почтальон Мышка, герой вот уже третьей книжки-картинки канадской художницы Марианны Дюбюк, отправляется развозить посылки и письма на ракете. Мы уже познакомились с его забавными соседями, объехали вокруг света, а сегодня вместе с ним можем заглянуть в новые миры.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'носорог-витгенштейна-1014'), 'Носорог Витгенштейна', 'Wittgenstein''s Rhinoceros', 'Vitgenštajnov nosorog', 'Франсуаза Арменьо', 'Françoise Armengaud', 'Fransoaz Armengo', 'Людвиг Витгенштейн (1889–1951) был тем, кто в начале XX века полностью изменил философию, начав анализировать язык. Будучи ещё молодым человеком, мыслитель удивлял кембриджских профессоров. Именно со спора с одним из них начинается «Носорог Витгенштейна», где в попытках найти несуществующего в аудитории носорога молодой философ открывает секреты языка и пишет свой знаменитый «Логико-философский трактат».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленький-театр-ханны-арендт-1015'), 'Маленький театр Ханны Арендт', 'The Little Theater of Hannah Arendt', 'Malo pozorište Hane Arent', 'Марион Мюллер-Колар', 'Marion Muller-Colard', 'Marion Miler-Kolar', 'Ханна Арендт (1906–1975) занималась политической философией, особенно её волновали проблемы холокоста и фашизма. «Как люди допустили эти ужасы?» — спрашивала она тех, кто видел, как Германия возвысила Гитлера, и кому удалось сбежать из концлагеря. В детской книге Ханна Арендт встречает девочку Ханну, которая так похожа на неё в детстве. Они путешествуют по разным местам: это и греческий полис, и хмурый лес, и квартира самой Арендт. Взрослая Ханна объясняет маленькой, почему спрятаться от проблем в своей уютной норе — это не выход.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'соседи-1016'), 'Соседи', 'Neighbors', 'Komšije', 'Катерина Горелик', 'Katerina Gorelik', 'Katerina Gorelik', 'Эта книга - веселый, шумный дом, населенный множеством замечательных соседей. Петушиное семейство и летучие мыши, лисы и кролики, пингвины и медведи, кроты и даже драконы. Хорошо ли им живется рядом? Давайте проверим. Страницы книги "разрезаны" так, что ребенок может самостоятельно решить, кто чьим соседом будет. Их можно менять местами, создавая свой сценарий, а затем смотреть, в какие забавные ситуации попадают герои, и придумывать новые невероятные истории из их жизни.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мишки-на-новый-год-1017'), 'Мишки на Новый год', 'Bears for the New Year', 'Medvjedi za Novu godinu', 'Катерина Горелик', 'Katerina Gorelik', 'Katerina Gorelik', 'Под Новый год в гости к Мишкам приехали родственники: панда из Китая, гималайский мишка с Тибета и суровый русский медведь. Ведь только здесь, на Севере, можно вкусить все радости зимних каникул: прокатиться на оленях, окунуться в ледяную прорубь, посостязаться в скорости со снежной лавиной, а потом и со снежным человеком... Да еще и Дед Мороз заезжает в гости! Незабываемые впечатления!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'в-детском-саду-поросенок-1018'), 'В детском саду - поросенок', 'A Pig in Kindergarten', 'Prase u vrtiću', 'Юханна Тидель, Шарлотта Рамель', 'Johanna Thydell, Charlotte Ramel', 'Johanna Thydell, Charlotte Ramel', 'Что за жизнь! Так продолжаться не может. Вон - детский сад. С горки съезжают дети, пахнет свежеиспеченными булочками. А ты чувствуешь себя самым одиноким поросенком на свете. Но вдруг жизнь поворачивается к тебе своей солнечной стороной!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'здравствуй-мама--1019'), 'Здравствуй, мама!', 'Hello, Mama!', 'Zdravo, mama!', 'Катя Герман', 'Katja Gehrmann', 'Katja Gehrmann', 'Книжка-картинка иллюстратора Кати Германн, обладательницы премии ЮНИСЕФ и "Золотого яблока" биеннале иллюстраторов в Братиславе. "Мама!" - пискнул маленький непонятный зверь, высунув из яйца голову. Медведь в ужасе посмотрел на существо, внезапно оказавшееся у него в лапах.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'школа-трактористов-1020'), 'Школа трактористов', 'Tractor School', 'Traktorska škola', '', 'Kenneth Andersson', 'Kenet Anderson', 'Все любят тракторы, в этом Туре Персон уверен. На своей ферме он открыл школу трактористов. Те, кто сюда пришел, смогут ездить взад и вперед, подниматься и спускаться с горки, объезжать препятствия, ездить в ряд... Но больше всего ученики хотят устроить тракторный слалом. - Ни в коем случае, - говорит Туре. - Вам еще рано. И вот в один прекрасный день… Для дошкольного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'гномы-1021'), 'Гномы', 'Gnomes', 'Patuljci', 'Мацей Шиманович', 'Maciej Szymanowicz', 'Maciej Szymanowicz', 'Полная деталей, веселья и невероятных фактов книга о гномах. Узнайте, что эти маленькие создания делают в наших домах, в лесу, сказках и цветочных горшках. Читайте книгу и рассматривайте смешных гномов, их средства передвижения, жилища, спортивные соревнования и игры. А еще узнайте, за что наказаны садовые гномики, какой рост самого маленького гнома, как осуществить восхождение на высоту 8456 к.н.у.к. (калорий над уровнем коржика), что помогает гномам улизнуть из поля зрения человека и что это за болезнь такая - гномический хохотунчик.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'летчик-и-маленький-принц-1022'), 'Летчик и Маленький принц', 'The Pilot and the Little Prince: The Life of Antoine de Saint-Exupéry', 'Pilot i Mali princ: Život Antoana de Sent Egziperija', 'Петр Сис', 'Peter Sís', 'Peter Sis', 'Антуан де Сент-Экзюпери родился во Франции в 1900 году. В то время как раз изобрели аэропланы, и Антуан с детства мечтал летать. Он вырос, стал летчиком, и в его жизни начались настоящие приключения. Он был одним из первых пилотов почтовой авиации и вместе с друзьями помогал прокладывать новые воздушные пути в удаленные уголки мира. Антуан летал над горами и пустынями, боролся с ветрами и грозами, и даже пытался поставить авиационные рекорды. Несколько раз он попадал в аварии. Во время полетов он думал о жизни на земле и в небе, эти размышления подтолкнули его написать историю о "Маленьком принце", которую полюбили читатели во всем мире. Книга, созданная Петром Сисом, посвящена автору этой удивительной сказки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'там-где-живут-чудовища-1023'), 'Там, где живут чудовища', 'Where the Wild Things Are', 'Tamo gdje su divlja stvorenja', 'Морис Сендак', 'Maurice Sendak', 'Moris Sendak', '"В тот вечер Макс нарядился волком и устроил шурум-бурум. А потом бурум-шурум. А мама сказала: "Ах ты чудовище!" А Макс сказал: "Я страхобраз, и я тебя съем!" А мама отправила его спать. Без ужина". Кажется, эта ситуация знакома миллионам родителей во всех уголках света. Ребенок, который так расшалился, что не может остановиться. И мама, которая не хочет терпеть непослушание и невежливость. Что будет дальше? Терапия для взрослых, как проявлять в стрессовых ситуациях выдержку и терпение? Поучительный рассказ для ребенка, как нельзя себя вести и что за это бывает?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кенни-и-его-окно-1024'), 'Кенни и его окно', 'Kenny''s Window', 'Keni i njegov prozor', 'Морис Сендак', 'Maurice Sendak', 'Moris Sendak', '«Кенни и его окно» - первая книга, написанная и проиллюстрированная Морисом Сендаком, автором бестселлера «Там, где живут чудовища». Кенни просыпается посреди ночи и вспоминает, что во сне он видел сад, наполовину лунный, наполовину солнечный, а в саду - четырехногого петуха. Чтобы вернутся в волшебный сад, нужно ответить на семь вопросов, заданных петухом. В этой книге Сендак вновь говорит с ребенком на его тайном языке. На этом же языке говорят игрушки, а взрослые не понимают его так же, как не умеют слушать ночь. Это книга о поисках себя, поисках ответов на сложные, иногда невозможно сложные вопросы. Например, как сдержать нарушенное обещание и как понять, чего ты хочешь на самом деле.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лафкадио-или-лев-который-отстр-1025'), 'Лафкадио, или Лев, который отстреливался', 'Lafcadio: The Lion Who Shot Back', 'Lafkadio, lav koji je uzvratio paljbu', 'Шел Сильверстайн', 'Shel Silverstein', 'Šel Silverstin', 'Как все на свете устроено? Кто-то – охотник, а кто-то – лев. Охотники палят из ружей по львам, а львы стараются съесть охотников. А что случится, если лев и охотник поменяются местами? Лев будет стрелять, ну а охотник, где теперь этот охотник... Герой книги Шела Силверстайна Лафкадио - как раз тот лев, который начал отстреливаться. А еще с элегантной небрежностью носить костюмы, курить сигары и наслаждаться мармеладками, простите, мурр-меладками. Короче, он совсем перестал быть львом, настолько, что отправился однажды на охоту. Изменил ли Лафкадио самому себе, утратив львиную сущность? Стал ли он счастливее? Что случается, когда ты теряешь свое место в жизни, и находишь ли новое? Этими вопросами уже более тридцати лет задаются читатели знаменитой книги Шела Силверстайна. Да и сам автор – поэт, писатель, художник-карикатурист, композитор, музыкант, драматург, иллюстратор – сразу ли он нашел свой путь? Он воевал в Корее, а по возвращению в США стал рисовать карикатуры для журналов, а еще продавать хотдоги и, поверьте, он был чертовски хорошим продавцом хотдогов. А потом почти 20 лет сотрудничал с журналом Playboy, писал пьесы и ставил спектакли, сочинял музыку и тексты песен для популярных музыкантов, пока один друг не уговорил Силверстайна попробовать написать книгу для детей. Шел подумал и согласился. Так появилась на свет эта книга – «Лафкадио. Лев, который отстреливался», затем – Giraffe and a Half, ну и, конечно, знаменитое «Щедрое дерево».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'это-книжка-1026'), 'Это книжка', 'It''s a Book', 'To je knjiga', '', 'Lane Smith', 'Lejn Smit', 'Мы все больше зависим от всевозможных приспособлений и гаджетов. Вот, например, этот текст вы читаете на экране своего компьютера или даже телефона. Вы можете прокрутить страницу вниз, чтобы рассмотреть иллюстрации, движением пальцев увеличить или уменьшить кусок страницы и даже поставить «лайк»! Нашим детям не нужно объяснять, как запустить видео в Youtube или сделать фотографию с айфона. Мы читаем в метро e-book, слушаем аудиокниги в машине, и уже привыкаем к спецэффектам в ай-падах. Может, вообще мы все скоро забудем, что такое бумажные книги? Детей будут специально водить в библиотеки, как в музеи, чтобы показать им чудо чудное — толстые и тонкие книжки в твердом переплете или мягкой обложке, со статичными иллюстрациями, не издающими никаких звуков. А, может, у вас есть знакомые взрослые, которые почти забыли, каково это листать страницы, улавливать еле слышный запах типографской краски, ощупывать фактурные элементы на обложке? Чтобы мы все помнили, что такое книга и для чего она нужна, мы и выпустили эту книжку-картинку, книжку-шутку с незамысловатым, но исчерпывающим названием «Это книжка». Ее страницы нельзя прокрутить, ее герои размахивают мечами из слов, она не посылает твиты, и мышки у нее тоже нет. Это просто книжка. Остроумная и симпатичная. Чтобы мы не забыли, какие они, книжки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'люди-в-картинках-1027'), 'Люди в картинках', 'People', 'Ljudi u slikama', 'Блексболекс', 'Blexbolex', 'Blexbolex', 'Чем биолог похож на астронома? А чем спящий отличается от больного? Что общего у художника и маляра? А у полицейского и вора? А у оратора и заклинателя змей? Ну что, много мыслей пришло в голову? Но правильного ответа нет! Ведь все ответы правильны. Блексболекс предлагает читателю или, даже лучше сказать, ЗРИТЕЛЮ бесконечно фантазировать, глядя на самых разных людей, среди которых появляются придуманные и реальные, добрые и злые, взрослые и дети. Как и в жизни, разнообразие людей в этой книге бесконечно, но все здесь они находят себе место, образуя забавные пары - в чем-то похожие, а в чем-то невероятно разные. «Люди в картинках» в 2009 году получила приз «Самая красивая книга в мире» на Лейпцигской книжной ярмарке.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'два-трамвая-1028'), 'Два трамвая', 'Two Trams', 'Dva tramvaja', 'Иосиф Бродский', 'Joseph Brodsky', 'Josif Brodski', 'Иллюстрации к книге родились не только из бумаги и красок, но и из картона, клея, трубочек для напитков, старых пуговиц, медной проволоки, крышек пластиковых бутылок. С их помощью появились сначала «герои» стихотворения — трамваи, а потом и вырос целый город — с улицами, домами, рельсами и жителями. Благодаря оформлению, напоминающему театральные декорации, действие «Двух трамваев» разыгрывается перед вами как будто на сцене, настолько объемными и живыми иллюстрации выглядят на бумаге. Благодаря им с детьми можно не только читать стихи, но и внимательно рассматривать картинки, пытаясь угадать, из чего все сделано.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'какого-цвета-мистер-лис--1029'), 'Какого цвета мистер Лис?', 'What Color Is Mr. Fox?', 'Koje je boje gospodin Lisac?', 'Стефан Каста', 'Stefan Casta', 'Stefan Kasta', 'Во время вечерней прогулки Мистер Лис увидел то, что никогда до этого не замечал. На его пути встречается чудесный голубой цветок, и по сравнению с ним Мистер Лис чувствует себя совершенно бесцветным. В попытке измениться он красит свою шерстку соком ягод, купается в грязи, укутывается в мох. Но каждый раз, когда он спрашивает у других животных, какого он цвета, они воротят нос и советуют ему поскорее помыться... Но однажды весенний дождик смывает с Лиса результаты его неудачных попыток стать другим, его настоящий цвет замечают дети, и Мистер Лис наконец может посмотреть на себя другими глазами! Шведский автор - лауреат премии А. Линдрен - Стефан Каста говорит: можно пытаться изменить внешность, но кто-то обязательно заметит и полюбит тебя таким, какой ты есть. А иллюстратор Стаффан Гносспелиус при помощи раскрашенных офортов виртуозно показывает прекрасный сказочный лес, где Мистер Лис постепенно учится быть собой.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'каштанка-1030'), 'Каштанка', 'Kashtanka', 'Kaštanka', 'Антон Чехов', 'Anton Chekhov', 'Anton Čehov', 'Уникальность настоящего издания "Каштанки" в иллюстрациях Татьяны Кормер, одной из ведущих современных художников книги, которые выполнены в технике хромолитографии. Популярность хромолитографии в книжной иллюстрации, особенно детской, пришлась на вторую половину XIX - первую половину XX вв. К этой технике часто обращались такие известные иллюстраторы как В.Лебедев, Н.Тырса, В. Конашевич и другие. Сейчас же книжные художники практически ее не используют.Стиль и техника Татьяны Кормер в "Каштанке" отсылают нас к книжной эстетике рубежа XIX-XX веков. В 2010 году эскизы иллюстраций Татьяны Кормер к "Каштанке" были удостоены диплома международной премии CJBook Picture. Подробнее: https://www.labirint.ru/books/276542/');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'записки-и-зарисовки-о-втором-п-1031'), 'Записки и зарисовки о втором путешествии по острову Синего солнца', 'Notes and Sketches from the Second Journey Across the Island of the Blue Sun', 'Bilješke i skice o drugom putovanju po Ostrvu Plavog Sunca', 'Илья Донец, Маргарита Щетинская', 'Ilya Donets, Margarita Shchetinskaya', 'Ilja Donec, Margarita Ščetinska', '"…Где - то в глубине синего океана, на одной синей-синей планете каждый день просыпается Синее Солнце. Отправив в бесконечность остатки своих солнечных снов, светило потягивается, делает несколько наклонов, поворачивается вокруг своей оси и протягивает свои лучи к острову Синего Солнца". Так начинаются "Записки и зарисовки о втором путешествии по острову Синего Солнца", оставленные служащим банка без денег Аркадием. Это фантастическая повесть, в которой мы узнаем силу репейного сока, посетим театр гигантских марионеток, отправимся в путешествие птицерыбами Рыбофлота, чтобы в конце пуститься в погоню за одноглазым Циклоном. Во время своего путешествия Аркадий настолько тщательно вел записи, что, несмотря на фонтан каламбуров и неожиданных поворотов событий, получилось почти научное и энциклопедическое описание острова.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'город-добрых-дел-1032'), 'Город добрых дел', 'What Do People Do All Day?', 'Šta ljudi rade cijeli dan?', 'Ричард Скарри', 'Richard Scarry', 'Ričard Skeri', 'Одна из самых знаменитых книг Ричарда Скарри. Из нее малыши во всем мире узнают о том, что делают их родители на работе. С помощью нее взрослые объясняют малышам, как устроен мир взрослых.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'самая-лучшая-книжка-1033'), 'Самая лучшая книжка', 'Best Storybook Ever', 'Najbolja knjiga ikada', 'Ричард Скарри', 'Richard Scarry', 'Ričard Skari', 'Самые лучшие истории, стихи и сказки - с самыми любимыми персонажами единственного и неповторимого Ричарда Скарри. Как всегда у Ричарда Скарри - ребенок узнает все-все-все про мир: как смешиваются цвета, как устроено человеческое тело, счет, дни недели, времена года, профессии, путешествия и много много другого. 300 миллионов проданных копий - совокупный тираж книг Ричарда Скарри. Скарри переведен на 20 языков Мировая классика детской литературы XX столетия. 60 лет - самый читаемый, самый рассматриваемый и самый любимый детский автор и художник.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-из-мира-книг-1034'), 'Я из мира книг', 'A Child of Books', 'Dijete iz svijeta knjiga', 'Оливер Джефферс', 'Oliver Jeffers, Sam Winston', 'Oliver Džefers, Sem Vinston', 'Маленькая девочка - дитя книг - плывёт на своём плоту по морю слов и попадает в дом мальчика. Девочка приглашает его вместе отправиться в путешествие по миру историй… где может случиться всё, что угодно, стоит только это вообразить. Авторы так говорят о своей работе "Я из мира книг": "С самого начала мы хотели создать историю, которая показала бы нашу любовь к классическим детским книгам, но по-новому. Мы хотели поймать ту магию, которая появляется, когда ты теряешься в истории, неподвластной времени. Но сделать это так, как никто раньше не делал". Удивительно симпатичные персонажи Оливера Джефферса на замечательных иллюстрация Сэма Уинстона - настоящая ода миру книг. Сплетённые вместе сюжетом книги, уникальные иллюстрации помогают получить незабываемый опыт чтения, который побудит всех читателей, от мала до велика, исследовать, задавать вопросы и придумывать собственные истории.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'что-мы-с-тобой-построим-1035'), 'Что мы с тобой построим', 'What We''ll Build', 'Šta ćemo graditi', 'Оливер Джефферс', 'Oliver Jeffers', 'Oliver Džefers', 'Отец и дочь начинают закладывать фундамент общей жизни. Они создают драгоценные воспоминания, строят дом, где будут чувствовать себя в безопасности, и выращивают в своих сердцах любовь, которая их согреет. История о безграничной родительской любви, о бесконечных возможностях, даруемых жизнью, и обо всём, что необходимо для общего будущего. Ещё один шедевр от всемирно известного автора и иллюстратора детских книг Оливера Джефферса.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'джек-и-джим-1036'), 'Джек и Джим', 'Jack and Jim', 'Džek i Džim', 'Китти Краутер', 'Kitty Crowther', 'Kiti Krauter', 'В "Джеке и Джиме" рассказывается о чёрном дрозде Джеке, который мечтает увидеть море, и о чайке по имени Джим. Из истории, рассказанной и нарисованной Китти Краутер, можно будет узнать о приключениях этих непохожих друг на друга, но очень дружных птиц. Китти Краутер - бельгийская писательница и иллюстратор, также лауреат премии Астрид Линдгрен 2010 года. Создала иллюстрации к более чем 35 детским книгам. Большинство из них написала она сама.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ночные-сказки-1037'), 'Ночные сказки', 'Stories of the Night', 'Noćne priče', 'Китти Краутер', 'Kitty Crowther', 'Kiti Krauter', '- Расскажи мне три сказки, - попросил Медвежонок. - Хорошо, - улыбнулась Мама Медведица. Вместе с Медвежонком мы услышим три чудесные сказки: о Ночке, которая укладывала всех спать, о заблудившейся в лесу Жоре и о человеке по имени Бу, который никогда не снимал пальто.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'перед-моим-домом-1038'), 'Перед моим домом', 'In Front of My House', 'Ispred moje kuće', 'Марианна Дюбюк', 'Marianne Dubuc', 'Marianne Dubuc', 'В необычное путешествие можно отправиться прямо от порога собственного дома - лишь бы воображения хватило. Книжка-картинка канадской художницы Марианны Дюбюк (автора уже вышедших на русском "Карнавала зверей", "Почтальона Мышки", "Льва и птички") как нитка волшебного клубка ведёт читателя в сказку или в космос, и на каждом развороте нас ждут сюрпризы и загадки. Не только малыши (от 1,5 лет), но и дети постарше наверняка полюбят эту необычную историю и наверняка начнут придумывать свои. Марианна Дюбюк - автор-иллюстратор, который придумывает книжки-картинки со сложными сюжетом и структурой. Ее называют восходящей звездой французской литературы - в своих книгах она создает целые миры, как настоящий писатель.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайна-волка-1039'), 'Тайна волка', 'The Wolf''s Secret', 'Vukova tajna', '', 'Myriam Dahman, Nicolas Digard', 'Mirijam Daman, Nikola Digar', 'Волк — ловкий охотник, которого боится весь лес. И у него есть тайна... В самом сердце леса живёт молодая женщина. Её пение заворожило волка. Но однажды нежный голос стих...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'настоящий-кораблик-1040'), 'Настоящий кораблик', 'The Real Boat', 'Pravi brodić', 'Марина Аромштам', 'Marina Aromshtam', 'Marina Aromštam', 'Сказочная история о том, как бумажный кораблик искренне и сильно захотел стать настоящим кораблем. Он отправился в открытое море, чтобы найти большие корабли и понять, как ему стать таким же. Во время его путешествия ему встретятся судна самых разных размеров и назначений. И каждое будет держать свой путь. Без трудностей не обойдется, но маленький кораблик не сдастся даже в шторм. Книга Марины Аромштам и Виктории Семыкиной впервые увидела свет в Великобритании, а позже была опубликована во Франции, США и Австралии. "Настоящий кораблик" уже попадал в списки некоторых престижных конкурсов и премий, например, в шорт-лист американского конкурса 3X3 и лонг-лист 2018 Klaus Flugge Prize. Книга выиграла гран-при жюри BIBF Ananas в Пекине 2019 г и почетный приз жюри Klaus Flugge Prize в Лондоне в 2018 и была в шорт-листе американского конкурса 3X3. Эта красивая книга может стать прекрасным подарком на все случаи жизни. Не только детям, но и взрослым, которые ценят глубокие смыслы и атмосферные иллюстрации.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'почему-у-собаки-мокрый-нос-1041'), 'Почему у собаки мокрый нос', 'Why Dogs Have Wet Noses', 'Zašto psi imaju mokar nos', 'Эйвинд Турсетер', 'Kenneth Steven, Øyvind Torseter', 'Kenet Stiven, Ejvind Torseter', 'Давным-давно - так давно, что мир был еще совсем новенький, - пошел дождь. Да такой сильный, что не осталось на земле ни одного сухого места. И вот один человек по имени Ной построил огромный корабль, чтобы спасти людей и животных. Ной собрал всяческих животных, какие только бывают на свете. Он взял с собой даже слизняков и пауков, жуков и всяких противных букашек. Они провели в море двадцать дней и двадцать ночей, и вот однажды ковчег дал течь. "Что же делать?" - ужаснулся Ной. Кто спасет ковчег? Новую версию хорошо известной истории предлагают шотландский писатель Кеннет Стивен и норвежский иллюстратор Эйвинд Турсетер, лауреат престижных премий в области детской книги, в частности Bologna Ragazzi Award.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'волшебная-лавка-1042'), 'Волшебная лавка', 'The Magic Shop', 'Čarobna prodavnica', 'Герберт Уэллс', 'H. G. Wells', 'H. Dž. Vels', '"Волшебная лавка" - один из самых парадоксальных и загадочных рассказов известного английского фантаста Герберта Уэллса, автора романов "Человек-невидимка", "Война миров" и др. Оригинальные иллюстрации Кирилла Челушкина, художника с мировым именем, делают книгу поистине художественным альбомом. Уникальная авторская техника и своеобразный подход к тексту превращают издание в объект культуры. Волшебная лавка, куда Уэллс приводит читателя, открывает свои двери не каждому. Это место превращений, метаморфоз, которые так легко происходят с человеком в детстве и остаются воспоминаниями на всю жизнь.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ничья-вещь-1043'), 'Ничья вещь', 'The Lost Thing', 'Izgubljena stvar', 'Шон Тан', 'Shaun Tan', 'Šon Tan', 'Герой этой книги, собирая на пляже коллекцию бутылочных крышечек, встретил странное создание - вещь без хозяина и применения. Он пытается найти ей место, открывая для себя мир удивительных вещей, которых никто не замечает, потому что они не вписываются, или потому, что люди слишком заняты другими важными вещами - например, лежанием на пляже или чтением газет. В этой, как и в других своих книгах, знаменитый австралийский иллюстратор Шон Тан создает целую страну - Окраину - с возносящимися в небо небоскребами и населяющими их странными существами и предметами. Его книги из тех, что можно рассматривать до бесконечности, с каждым разом открывая для себя что-то новое. В 2001 году "Ничья вещь" была выбрана в Австралии книжкой-картинкой года. Она получила почетное упоминание на Международной книжной ярмарке в Болонье, премии в области книжной иллюстрации Aurelius и Spectrum в США. Снятый по ней мультфильм в 2010 году был назван лучшим короткометражным фильмом года на крупнейшем в мире международном анимационном фестивале в Аннеси.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'прибытие-1044'), 'Прибытие', 'The Arrival', 'Dolazak', 'Шон Тан', 'Shaun Tan', 'Šon Tan', '"Что заставляет многих людей бросить все и отправиться в одинокое путешествие в неизведанную страну, где нет ни семьи, ни друзей, где все зыбко, где будущее неопределенно? Этот графический роман - история каждого переселенца, каждого беженца, каждого, кто был вынужден покинуть родные места. Это дань уважения всем тем, кто проделал подобный путь." Шон Тан - автор и художник-иллюстратор таких книг, как "Ничья вещь", "Красное дерево" и "The Arrival. Прибытие". Все они были удостоены многочисленных международных наград. Мультфильм по книге "Ничья вещь" в 2011 году получил "Оскар" как самый лучший анимационный короткометражный фильм. Графический роман "The Arrival. Прибытие" получил премию Болонья Рагацци, а также был признан лучшей книгой с картинками. Книги Шона активно переводятся и издаются по всему миру. В 2001 году Шон получил премию как лучший художник-фантаст, а в 2011 году он стал лауреатом премии Астрид Линдгрен - самой авторитетной награды в области детской литературы. Шона Тана называют "непревзойденным мастером визуального повествования"');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'истории-далекого-пригорода-1045'), 'Истории далекого пригорода', 'Tales from Outer Suburbia', 'Priče iz dalekog predgrađa', 'Шон Тан', 'Shaun Tan', 'Šon Tan', 'Прославленный австралийский художник Шон Тан, обладатель многочисленных премий, автор знамениого графического романа "Прибытие", раскрывает тайны повседневной жизни: питомцы, сделанные своими руками, опасные свадьбы, выброшенные на берег морские млекопитающие, крохотные студенты по обмену и тайные комнаты, наполненные тьмой и восторгом.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'линдберг-1046'), 'Линдберг', 'Lindbergh: The Tale of a Flying Mouse', 'Lindberg: Priča o letećem mišu', 'Торбен Кульманн', 'Torben Kuhlmann', 'Torben Kulman', 'Давным-давно в огромном городе жил мышонок, который был до того любознательным, что месяцами просиживал в библиотеках за чтением книг. Однажды он заметил, что мышей в городе почти не осталось. Опасности прогнали его сородичей: голодные кошки и хищные совы подстерегают на улицах, а в домах людей повсюду расставлены зловещие устройства — мышеловки! Вот только куда отправились его друзья? Может быть, в Америку? У мышонка родился отчаянный план — научиться летать и пересечь Атлантический океан!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мой-дом-1047'), 'Мой дом', 'My Home', 'Moj dom', 'Давид Кали', 'Davide Calì', 'Davide Kali', 'Мне всегда было трудно считать какое-то место, город или здание своим домом. Но ведь дом должен быть у каждого человека, правда?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-не-сделал-уроки-потому-что--1048'), 'Я не сделал уроки потому что...', 'I Didn''t Do My Homework Because...', 'Nisam uradio domaći zato što...', 'Давид Кали', 'Davide Cali', 'Davide Cali', 'Главное - не растеряться! И если учитель задает вопрос в лоб - почему не сделано домашнее задание - надо отвечать. Действительно, мало ли что могло случиться? Дом заполонили роботы... Обезьяны... Похитили инопланетяне... Супермашина по изготовлению уроков сломалась... Дедушка и его друзья слишком громко музицировали в соседней комнате... Налетел ветер...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'горошек-1049'), 'Горошек', 'Little Pea', 'Graščić', 'Давид Кали', 'Davide Calì', 'Davide Calì', 'Книжка всемирно известного детского писателя Давида Кали - это притча о необычном, очень маленьком герое. Но этого кроху не забудешь! Он из тех, кто неизменно вызывает восхищение: потому, что он умеет быть счастливым, свободным и наслаждаться тем, что у него есть. Кто-то расстраивается из-за маленького роста... Но только не Горошек! Ему не подходит ни одна парта, он скатывается по ступенькам, потому что не может по ним шагать, он не может играть с друзьями в баскетбол, но он не унывает и преодолевает трудности при помощи изобретательности, нестандартного мышления и хорошего настроения. Вокруг этого современного Мальчика-с-пальчик Давид Кали и художник Себастьян Мурен создают смешной, уютный, полный прелестных деталей мир, который понравится рассматривать и детям, и взрослым.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'зубное-приключение-1050'), 'Зубное приключение', 'The Tooth Adventure', 'Zubna avantura', 'Эва Эриксон', 'Eva Eriksson', 'Eva Erikson', 'Наконец-то у Беллы выпал зуб! Это значит, что она уже совсем большая и может одна ездить на автобусе. Вместе с младшим братом и другом Густавом Белла отправляется к бабушке. Вот только в квартире бабушки все какое-то странное — может быть, они не туда попали? А вдруг здесь живет настоящая ведьма? Эва Эриксон — шведская художница и писательница. Помимо собственных книг, проиллюстрировала книги самых известных шведских писателей. Лауреат множества премий, в том числе премии Астрид Линдгрен и медали Эльзы Бесков.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'парко-1051'), 'Парко', 'Parco', 'Parko', 'Гуриди', 'Guridi', 'Guridi', '"Покойся с миром!" - сказали они. Но почему же тогда мир продолжает вертеться? Парко поднялся из могилы и пошел в город. И там он узнал что-то очень важное. С древнейших времен мы, люди, относились к смерти со страхом и почтением, создав бесконечное количество похоронных обычаев, религий и философских течений. Когда художник Гуриди попросил Алекса Ногеса написать веселую сказку о смерти, события и персонажи, которых он стал представлять, сами собой перенеслись в Мексику. Если и существует культура, в которой люди весело и с любовью относятся к своим мертвым, то это, без сомнения культура Мексики. Вот так и появился на свет Парко - самый обычный оживший мексиканский мертвец.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'малюсенький-паровозик-1052'), 'Малюсенький паровозик', 'Little Train', 'Mali vozić', 'Крис Галл', 'Chris Gall', 'Kris Gal', 'Малюсенький паровозик, который привык бегать по кругу своей игрушечной железной дороги вдруг оказался за пределами дома и повстречался с настоящими поездами. Что узнает о мире наш паровозик?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'замечтательная-книжка--1053'), 'Замечтательная книжка!', 'An Awesome Book!', 'Sjajna knjiga!', 'Даллас Клейтон', 'Dallas Clayton', 'Dallas Clayton', 'Замечательная книжка для детей. Для чтения взрослыми детям');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'защитник-детей-1054'), 'Защитник детей', 'The Champion of Children: The Story of Janusz Korczak', 'Zaštitnik djece: Priča o Janušu Korčaku', 'Томек Богацкий', 'Tomek Bogacki', 'Tomek Bogacki', 'Януш Корчак вел специальную программу на варшавском радио, где давал детям советы, как справиться с разными сложностями в их жизни. Януш Корчак всю свою жизнь посвятил детям - лечил их, писал о них, защищал от несправедливости. Писал для них книги - его сказочная повесть "Король Матиуш первый" любима многими поколениями детей во всем мире. Януш Корчак создал в Варшаве удивительный приют для еврейских сирот, которым управляли сами дети. А когда нацисты отправили их в концлагерь, где детей ожидала неминуемая смерть, он не оставил своих маленьких воспитанников и погиб вместе с ними. Эту книгу о Януше Корчаке написал и нарисовал американский детский писатель и художник Томек Богацкий.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мечтатель-из-местечка-1055'), 'Мечтатель из местечка', 'The Dreamer from the Shtetl', 'Sanjar iz varošice', '', 'Unknown', 'Nepoznat autor', 'Марк Шагал был одним из первых художников, которые выразили в своем творчестве внутренний мир - мечты, фантазии, воспоминания. Его картины отличаются богатством красок, его образная система сюрреалистична. Мойше Сегал родился 7 июля 1887 года в местечке Лиозно близ Витебска (сейчас этот город находится в Беларуси). Позднее он изменил имя, и оно стало звучать на французский манер - Марк Шагал. Мальчик рос в религиозной еврейской среде, и позднее это нашло отражение в сюжетах его картин.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'простая-бандероль-1056'), 'Простая бандероль', 'A Simple Parcel', 'Obična pošiljka', 'Брюно Хейтц', 'Bruno Heitz', 'Bruno Hajc', 'Брюно Хейтц нарисовал и написал за всю свою жизнь более пятидесяти книг; и ни одна из них не похожа на другую. Используя различные техники, - черно-белую графику, линогравюру, коллажи, фотографии сделанных им самим скульптур, - Брюно Хейтц создает оригинальные и забавные истории, которые любят и взрослые и дети. "Простая бандероль" - прекрасный образец современного французского искусства книги.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'расмус-в-кругосветном-путешест-1057'), 'Расмус в кругосветном путешествии', 'Rasmus Klump Around the World', 'Rasmus na putu oko svijeta', 'Карла ХАнсен', 'Carla Hansen', 'Karla Hansen', 'Знакомьтесь с медвежонком Расмусом и его друзьями - Пинго, Пелле и Тюленем! Они большие выдумщики и искатели приключений и постоянно попадают в весёлые истории! Отправляйтесь в самое захватывающее кругосветное путешествие вместе с нашими друзьями. За 80 дней они преодолеют моря и страны, им предстоит проехать на поезде, на спине слона, пролететь на дирижабле, проплыть в пасти кита и даже облететь вокруг Луны! Эту весёлую историю в картинках сможет понять даже тот, кто ещё не умеет читать. Выразительные иллюстрации шаг за шагом передают ход сюжета - можно просто рассматривать странички. А для тех, кто уже умеет читать, книга станет отличной дополнительной тренировкой навыков - в ней крупные буквы и простые короткие фразы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сокровища-лесных-эльфов-1058'), 'Сокровища лесных эльфов', 'Treasures of the Forest Elves', 'Blaga šumskih vilenjaka', 'Реетта Ниемеля', 'Reetta Niemelä', 'Reetta Niemelä', '"Это самая любимая и самая важная для меня книжка. Ведь она объединяет дорогие мне вещи: игру, фантазию, радость, дружбу, понимание, поддержку, тепло и любовь в семье. Я думаю, что весь мир состоит из таких вот очень маленьких и удивительных историй. Надо только наклониться и заглянуть, или зажмуриться и нырнуть, а может даже залезть в какую-нибудь маленькую норку. И тогда ты обязательно их найдешь!" Реетта Ниемеля. Художник-иллюстратор: Матти Пиккуямся.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'бига-и-каса-1059'), 'Бига и Каса', 'Biga and Kasa', 'Biga i Kasa', 'Илья Донец, Маргарита Щетинская', 'Ilya Donets, Margarita Shchetinskaya', 'Ilja Donec, Margarita Ščetinskaja', 'Бига и Каса живут у подножия большого дерева. Их мир ограничивается небольшой полянкой у корней деревьев и необходимостью каждый вечер включать на всем дереве свет. Всё, что не входит в их обычный распорядок, друзья считают неприятным и пугающим. Но однажды случается авария - перегорает главная лампочка - и, чтобы её заменить, друзьям приходится отправиться в путешествие на самую вершину дерева. Во время своего путешествия Бига и Каса решают инженерные задачи, знакомятся с другими обитателями дерева, преодолевают свои страхи и узнают, что мир гораздо больше и интереснее, чем они думали. Герои книги вылеплены из пластилина, а иллюстрации совмещают фотографии, рисунки и компьютерную обработку. В 2011 году "Бига и Каса" были отмечены премией "Образ книги".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дзен-в-коротеньких-штанишках-1060'), 'Дзен в коротеньких штанишках', 'Zen Shorts', 'Zen u kratkim pantalonama', 'Джон Мут', 'Jon J. Muth', 'Džon Dž. Mut', '"Дзен в коротких штанишках" - это несколько коротких историй, которые помогают приблизиться к медитации. Медитация доводит до совершенства нашу способность прислушиваться к собственной интуиции. В медитации нет никакой цели, но она зачастую позволяет нам проанализировать наши привычки, желания, представления и страхи. Истории "Дядюшка Рю и луна" и "Тяжелая ноша" относятся к дзен-буддийской литературе далекого прошлого. Рассказ "Удача фермера" восходит корнями к даосизму, история которого насчитывает несколько тысяч лет. Вариантов каждой из этих историй существует очень много. Автор выбрал те, которые показались наиболее доступными для юных читателей.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'если-плакать-как-фонтан-1061'), 'Если плакать как фонтан', 'If You Cry Like a Fountain', 'Ako plačeš kao fontana', 'Ноэми Вола', 'Noemi Vola', 'Noemi Vola', 'Причудливая и удивительно забавная книжка с картинками о множестве практических применений слез. Стараясь развеселить грустного червяка, рассказчик усугубляет ситуацию, заставляя червяка плакать. Пытаясь исправить ситуацию, рассказчик начинает думать о различных способах продуктивного использования слез. К примеру, если вам грустно в обед, плачьте, пока не наполните кастрюлю слезами и не сварите макароны — можно даже не солить! Слезы служат множеству различных целей. Без слез реки бы пересохли. Тучи становились бы все больше и больше, и фермеры бы сердились. Слезы помогают грушам расти, а из груш можно сварить варенье. Варенье делает людей счастливыми и помогает остановить слезы... по крайней мере, пока не кончится! Присоединяйтесь к плачущему червяку и неуклюжему рассказчику, которые исследуют множество способов использования слез.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'приду-в-4-1062'), 'Приду в 4', 'I''ll Come at Four', 'Doći ću u četiri', 'Вольфдитрих Шнурре', 'Wolfdietrich Schnurre', 'Volfditrih Šnure', 'В клетке зоопарка снует туда-сюда страшная гиена. Вы подходите поближе, и вдруг она говорит: - На самом деле я принцесса. Попытаетесь ли вы ее расколдовать?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сказки-комиксы-1063'), 'Сказки-комиксы', 'Fairy Tale Comics', 'Bajke u stripu', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', 'Дети любят слушать сказки. И обожают рассматривать комиксы. Почему бы не дать им возможность делать это одновременно? Так рассудила немецкая художница Ротраут Сюзанне Бернер и нарисовала восхитительно остроумные детские комиксы по мотивам своих любимых сказок братьев Гримм. В книгу вошли 8 известных сказок: "Принцесса и лягушонок", "Госпожа Метелица", "Мальчик-с-пальчик", "Рапунцель", "Йоринда и Йорингель", "Счастливый Ганс", "Ганс-ёжик" и "Красная шапочка". На их страницах взрослых и маленьких читателей ждут и шутки художника, и задачки на внимательность, и другие сюрпризы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пес-и-заяц-1064'), 'Пес и заяц', 'Dog and Hare', 'Pas i zec', 'Ротраут Сюзанна Бернер', 'Rotraut Susanne Berner', 'Rotraut Suzane Berner', 'Герои этой истории - пёс Хуго и заяц Ханнес - живут в Шмелином городке возле Шмелиной реки. Каждый день Хуго и Ханнес видятся в школе, что интересно одному, то интересно и другому, но у них и мысли нет перекинуться меж собой словечком, ведь их семейства на дух друг друга не переносят. Никто уже и не помнит, откуда пошла эта взаимная неприязнь, так уж повелось. Но в одно прекрасное воскресенье Шмелиный городок отправляется на соревнования по бегу, и заяц и пес спешат попасть на него во все восемь лап.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'что-у-соседа-на-обед--1065'), 'Что у соседа на обед?', 'What''s Cooking at 10 Garden Street?', 'Šta komšija kuva za ručak?', 'Феличита Сала', 'Felicita Sala', 'Feličita Sala', 'По Садовнической улице доносится изумительный аромат! Сеньора Лейла пробует свой знаменитый соус к спагетти. В квартире на третьем этаже господин Сингх собирается приготовить вкусный кокосовый дал. А по соседству с ним миссис Гринпи радуется золотистой корочке только что приготовленных мини-кишей… Эта книга - сборник оригинальных рецептов национальных блюд. Она поможет юным читателям расширить свой кругозор и проявить творческую фантазию. Готовьте с удовольствием!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'она-создала-чужовище-1066'), 'Она создала чужовище', 'She Made a Monster: How Mary Shelley Created Frankenstein', 'Stvorila je čudovište', '', 'Lynn Fulton', 'Lin Fulton', 'Двести лет тому назад лорд Байрон предложил своей подруге Мэри соревнование: кто лучше напишет страшную историю. Ненастной ночью Мэри вспоминает свои детские страхи и смерть матери. И вот, уже засыпая, она представляет чудовище настолько страшное, что люди в ужасе бегут от него. Проснувшись, Мэри понимает: история готова.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленький-домик-1067'), 'Маленький домик', 'The Little House', 'Mala kućica', 'Вирджиния Ли Бертон', 'Virginia Lee Burton', 'Virdžinija Li Barton', 'Эта книга о судьбе Маленького Домика, который и является главным героем книги. Однажды его построили, и был произнесен завет: этот домик будет стоять долго-долго и в нем будут жить правнуки наших правнуков. Домик встречает лето и зиму, утро и ночь, радуется распустившимся цветам яблони и первым снежинкам, он наблюдает жизнь людей, которые в нем живут. Но со временем на тихую деревенскую жизнь начинает наступать город. Он все ближе и ближе, и вот уже Маленький Домик оказывается в самом его центре, окруженный небоскребами, ревущими электричками, грохочущими трамваями и спешащими людьми. Хозяева его давно покинули. Трагедия заключается в том, что сумасшедший ритм города никак не может быть принят Домиком. Та ритмическая жизнь, согласная с природой уже не доступна ему. И хозяева его давно бросили. Домик обветшал. Дальше случается невероятное. И в конце истории Домик переезжает на столь милую ему поляну с ромашками и яблонями, и возвращается к своему естественному ритму жизни.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'комореби-собремеса-хэзеллих-1068'), 'Комореби, собремеса, хэзеллих', 'Komorebi, Sobremesa, Gezellig', 'Komorebi, sobremesa, gezellig', 'Мария Ивашкина', 'Maria Ivashkina', 'Marija Ivaškina', 'В разных языках найдены очень точные слова для определения сложных оттенков чувств. Если собрать несколько таких слов вместе, перед тобой возникает портрет. Каждая страна — как человек со своим характером. Наверняка, когда ты будешь узнавать эти слова, ты поймешь, что какие-то эмоции переживал сам, а какие-то тебя удивят и в следующий раз заставят остановиться и заметить, как солнечный свет ­проникает сквозь листья. И, может быть, это понятие станет твоим. Неважно, как ты его назовешь, главное, что оно не пройдет мимо тебя.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'полеш-открывает-музей-1069'), 'Полеш открывает музей', 'Kubbe Makes a Museum', 'Poleš otvara muzej', 'Осхиль Кандад Юнсен', 'Åshild Kanstad Johnsen', 'Ošhild Kanstad Jonsen', 'Как навести порядок в своей коллекции и стоит ли открывать собственный музей? Полеш, его бабушка и его подруга Йолка решили попробовать - и что же из этого вышло? Смешных лесных человечков, которых придумала и нарисовала норвежская писательница и художник Осхиль Канстад Юнсен, полюбили во всём мире. Если ваши дети всё время что-то находят и подбирают, а вы не знаете, куда всё это девать, - эта книга для вас!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рождественское-путешествие-мед-1070'), 'Рождественское путешествие медведей вокруг света', 'The Bears'' Christmas Journey Around the World', 'Božićno putovanje medvjeda oko svijeta', 'Кястутис Каспарявичус', 'Kęstutis Kasparavičius', 'Kęstutis Kasparavičius', 'Однажды накануне Рождества семейство бурых медведей отправляется в путешествие на воздушном шаре. Надо успеть поздравить своих друзей во всем мире и подарить им подарки!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дюймовочка-1071'), 'Дюймовочка', 'Thumbelina', 'Palčica', '', 'Hans Christian Andersen', 'Hans Kristijan Andersen', '"Дюймовочка" - одна из самых романтичных сказок Ганса Христиана Андерсена. Историю крошечной девочки, появившейся из цветочного бутона, любят как дети, так и взрослые. Проиллюстрировал книгу известный литовский писатель и художник Кястутис Каспаравичюс. Его радостные, солнечные, нежные рисунки очень хорошо передают волшебное настроение сказки и помогают поверить в то, что чудеса случаются.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'заяц-моркус-великий-1072'), 'Заяц Моркус Великий', 'Morkus the Great Hare', 'Zec Morkus Veliki', '', 'Kęstutis Kasparavičius', 'Kęstutis Kasparavičius', 'Это весёлая и поучительная сказка художника Кястутиса Каспаравичюса. В ней рассказывается о пирогах и пирожных, о зайчике Моркусике и его желании стать большим, толстым и сильным, о смышлёной крольчихе Фране и её Особенной Мягкой Овощной Диете. Словом, о приключениях, о танцах, любви и о том, как оставаться собой.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'животные-севера-1073'), 'Животные Севера', 'Wild Animals of the North', 'Životinje Sjevera', 'Дитер Браун', 'Dieter Braun', 'Diter Braun', 'Много лет иллюстратор и детский писатель Дитер Браун путешествовал по всему миру, изучая внешний вид животных, их повадки и привычки, а потом создал серию выдающихся плакатов. В эту книгу вошли его лучшие работы, посвященные животному миру Северного полушария. Книга проведет нас по самым необычным местам Северного полушария. Вслед за афалиной мы окунемся в воды океана, вместе с кабаном поищем вкусные корешки на опушке леса, пройдем по следам верблюда сквозь песчаную пустыню, с винторогим козлом поднимемся на вершину горы. А еще нанесем визит песцам, гуляющим по просторам Сибири за Полярным кругом, подглядим, как добывает себе пищу дятел желна, и, несмотря на испанскую жару, составим компанию пиренейской рыси. Уникальный графический стиль Дитера Брауна вдыхает жизнь в животных на картинках. Иллюстрации отличаются выразительными линиями, яркими цветами и в то же время удивительной натуралистичностью и любовью к деталям. А новаторской стиль повествования Брауна и его неподражаемый юмор превращают сухие факты о животных в интереснейшие рассказы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'принцесса-и-счастье-1074'), 'Принцесса и счастье', 'The Princess and Happiness', 'Princeza i sreća', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'В сказочном лесу может случиться все что угодно. И когда принцесса Клара отправляется искать потерянное счастье своего отца, чудеса начинаются. -В пути принцесса встречает волка, огнедышащего дракона и ведьму, которая может кого угодного превратить в камень.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленький-асмодей-1075'), 'Маленький Асмодей', 'Little Asmodeus', 'Mali Asmodej', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Маленький Асмодей со своей семьёй живёт в Подземном царстве. Он слишком добрый и робкий, поэтому его отец - Повелитель Огня и Властелин Вздохов - ужасно им недоволен. Он отправляет сына на Землю, чтобы малыш нашёл того, кто продаст ему свою душу. Асмодей справляется с этой нелёгкой задачей, но может ли Повелитель Огня принять душу человека, который желает добра? О приключениях Асмодея рассказал классик современной детской литературы Ульф Старк, а трогательные иллюстрации нарисовала шведская художница Анна Хеглунд. Эта простая и тонкая философская притча интересна и взрослым, и детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дважды-чемпион-1076'), 'Дважды чемпион', 'Two-Time Champion', 'Dvostruki šampion', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Все целуются - все, кроме Ульфа! Он ещё ни разу не целовался, а другие - бессчётное количество. Брат - как минимум сто раз. Но с кем бы попробовать, да и добиться в этом успеха? А ещё хорошо бы победить в смешном соревновании... Не сомневайтесь, у Ульфа всё получится! Ульф Старк написал около 40 книг и множество сценариев для телевидения, кино и театра. Он лауреат нескольких шведских и международных премий. Маркус Майалуома - один из самых популярных иллюстраторов. За свою работу над мультфильмами и иллюстрациями к детским книгам - как других авторов, так и своих собственных - награждён многочисленными призами.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'умнее-старших-1077'), 'Умнее старших', 'Smarter Than the Grown-ups', 'Pametniji od starijih', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Деревня Стюбери просто кишмя кишит детективами. Ульф тоже хочет стать сыщиком! Но это опасное занятие. И совсем не для малышей. Немного хитрости - и он берёт дело в свои руки! Ульф Старк написал около 40 книг и множество сценариев для телевидения, кино и театра. Он лауреат нескольких шведских и международных премий. Маркус Майалуома - один из самых популярных иллюстраторов. За свою работу над мультфильмами и иллюстрациями к детским книгам - как других авторов, так и своих собственных - награждён многочисленными призами. Отличный мальчишка Ульфик - герой целой серии книг. С ним все время приключаются смешные истории, про них мы и узнаем из книг, которые появятся позже.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'долой-рабство-1078'), 'Долой рабство', 'Down with Slavery!', 'Dolje ropstvo!', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Сердитый дедушка рад объявить тебя лентяем только потому, что ты не копаешься в огороде. Больше того, он готов объявить тебя рабом! Ничего не поделаешь, теперь придется ему помогать, трудиться до седьмого пота. Но, к счастью, есть и другой дедушка. Возможно, он спасет тебя от рабства... Эта книга из автобиографической серии о мальчике Ульфе. Ульф — один из самых ярких персонажей Старка, он кочует из книги в книгу вместе со своим вредным старшим братом и ворчливым дедушкой.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мина-и-коге-уезжают-на-запад-1079'), 'Мина и Коге уезжают на Запад', 'Mina and Kåge Go West', 'Mina i Koge odlaze na Zapad', 'Анна Хеглунд', 'Anna Höglund', 'Ana Heglund', 'Встречайте Мину и Коге - пару симпатичных шведских медведей. Книги об их непростых взаимоотношениях помогут детям понять этих странных взрослых. Мина и Коге переезжают в Америку. Коге в восторге от США, а вот Мине грустно и одиноко. К тому же надвигается страшная буря по имени Хуррикан! Сможет ли Мина привыкнуть к новой стране?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мина-уходит-навсегда-1080'), 'Мина уходит навсегда', 'Mina Leaves Forever', 'Mina odlazi zauvijek', 'Анна Хеглунд', 'Anna Höglund', 'Ana Heglund', 'Встречайте Мину и Коге — пару симпатичных шведских медведей. Книги об их непростых взаимоотношениях помогут детям понять этих странных взрослых. Коге забыл про чай, умчался гулять и даже не сказал Мине «до свиданья». Как он мог! Мина решила наказать Коге — и уйти навсегда. Пусть он поймет, кого потерял!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'история-об-эле-и-космонавте-ла-1081'), 'История об Эле и космонавте Лайке', 'The Story of Ella and Laika the Space Dog', 'Priča o Eli i psu kosmonautu Lajki', 'Хелен Рундгрен', 'Helena Rundgren', 'Helena Rundgren', 'С дворняжкой по кличке Крошка Эля происходит что-то странное. Люди поселили ее в большую клетку, кормят странной едой, учат выполнять разные команды. В целом неплохо, но иногда так хочется побегать по травке! Крошка Эля еще не знает, что станет одной из самых знаменитых собак в мире. Но обо всем по порядку…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'голем-1082'), 'Голем', 'The Golem', 'Golem', 'Исаак Башевис Зингер', 'Isaac Bashevis Singer', 'Isak Baševis Singer', 'Исаак Башевис Зингер (1904 - 1991) - знаменитый еврейский писатель, лауреат Нобелевской премии по литературе. "Голем" - захватывающая и мудрая история, в основе которой лежит старинная еврейская легенда о глиняном человеке, созданном для защиты евреев в трудных ситуациях. И однажды он вышел из-под контроля своего создателя…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'макси-пес-фик-1083'), 'Макси-пес Фик', 'Maxidog Fík', 'Maksi-pas Fik', 'Рудольф Чехура, Ирхи Шаломоун', 'Rudolf Čechura, Jiří Šalamoun', 'Rudolf Čehura, Jirži Šalamoun', 'Как-то раз в одной самой обыкновенной семье появился маленький симпатичный пёсик, назвали его Фик. Он поселился в коробке от сапог, но на другой день она уже была ему мала. Фик был ужасным обжорой и рос так быстро, что вскоре даже собачья будка трещала по швам. Теперь это был уже не пёсик, а настоящий макси-пёс. Папа решил было продать его, но Фик оказался необыкновенным псом: он спас свою хозяйку, научился говорить, водить машину, а ещё он ходил в магазин и даже участвовал в скачках. Благодаря многосерийному мультфильму, снятому по мотивам этой книги, Фик известен в СССР и России ещё с 70-х годов прошлого века.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'макси-пес-фик-приключения-прод-1084'), 'Макси-пес Фик приключения продолжаются', 'Maxidog Fík: The Adventures Continue', 'Maksi pas Fik: Avanture se nastavljaju', 'Рудольф Чехура, Ирхи Шаломоун', 'Rudolf Čechura, Jiří Šalamoun', 'Rudolf Čehura, Jirži Šalamoun', 'Вы уже знакомы с собакой по имени Фик? Этот необыкновенный макси-пёс умеет говорить, читать, а иногда он даже ходит в магазин и участвует в скачках. Умеет ли Фик водить машину? Может ли он работать юнгой на корабле? Об этом вы узнаете из книги о новых приключениях макси-пса! Благодаря многосерийному мультфильму, снятому по мотивам этой книги, Фик известен в СССР и России ещё с 70-х годов прошлого века.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кирпичик-1085'), 'Кирпичик', 'Brick: Who Found Herself in Architecture', 'Ciglica: Priča o arhitekturi', 'Джошуа Дэвид Стайн', 'Joshua David Stein', 'Džošua Dejvid Stajn', 'Какие бывают сказки? Волшебные и добрые, а еще бывают сказки архитектурные! Сказка «Кирпичик» — именно такая! Архитектура окружает нас — все здания однажды кто-то придумал. И некоторые из этих зданий состоят из кирпичиков! Мама говорила малышке Кирпичику: «Все большие вещи начинаются с маленьких кирпичиков. Оглянись — и увидишь». Кирпичик отправляется в большое путешествие, чтобы найти свое предназначение. В пути она встречает замки, церкви и минареты, синагоги и храмы, стены и дома. Где же ее место? Кем ей стать? Эта сказка наполнена не только архитектурой, но и глубоким смыслом. Как найти себя в огромном мире? Как маленький кирпичик может стать чем-то большим? Все архитектурные памятники: каждый храм, собор и даже каждый дом, нарисованный на страницах, — настоящие! Синагога Парк-Ист в США, минарет Малвия в Ираке, крепость Арк в Бухаре и даже собор Василия Блаженного — вы увидите целый мир вместе с малышкой Кирпичиком. Стильные иллюстрации помогут развивать чувство цвета и художественный вкус. Книгу «Кирпичик» автор посвящает «Всем большим, которые когда-то были маленькими, и всем маленьким, которые однажды станут большими».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайна-господина-бальдера-1086'), 'Тайна господина Бальдера', 'The Secret of Mr. Balder', 'Tajna gospodina Baldera', 'Якоб Вегелиус', 'Jakob Wegelius', 'Jakob Vegelijus', 'Господин Бальдер — отменный повар, виртуозный музыкант и любитель почитать в одиночестве. Он всегда ходит одной и той же дорогой, обходя крутые подъемы и наслаждаясь благоуханием цветов. В его тихой и уютной усадьбе не случается ничего примечательного. Но вот однажды утром в четверг, когда господин Бальдер, как обычно, подкреплялся овсянкой, ему на глаза попалось странное объявление…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'легенда-о-салли-джонс-1087'), 'Легенда о Салли Джонс', 'The Legend of Sally Jones', 'Legenda o Sali Džons', 'Якоб Вегелиус', 'Jakob Wegelius', 'Jakob Vegelijus', 'Эта история берет свое начало сто лет назад, когда в ненастную тропическую ночь в африканских джунглях родилась маленькая горилла. На долю Салли Джонс выпали суровые испытания, волею судьбы ей пришлось совершить путешествие по всему миру, она выступала в цирке шапито, долгие годы томилась в неволе в зоопарке, работала кочегаром на корабле и зазывалой в трактире. В ее истории было все: кража, погоня, настоящая дружба, предательство и надежда…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хвоинка-свинофуфик-и-носик-роз-1088'), 'Хвоинка, свинофуфик и носик-розочкой', 'Kotten, Piggy-Puff, and Rosy Nose', 'Iglanka, Prase-Pufica i Roze Nosić', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', 'Однажды вечером к ежихе Хвоинке пришла гостья... Эти стихи всемирно известной шведской писательницы Лены Андерсон перевёл на русский язык замечательный поэт Михаил Яснов. Для тех, кто учится считать и любит рассматривать картинки!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайна-хвоинки-1089'), 'Тайна Хвоинки', 'Pinecone''s Secret', 'Tajna Iglice', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', 'Ежиха Хвоинка весь день не выходит из дома - что случилось? Эти стихи всемирно известной шведской писательницы Лены Андерсон перевёл на русский язык замечательный поэт Михаил Яснов. Для тех, кто учится считать и любит рассматривать картинки!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'все-друзья-наперечет-1090'), 'Все друзья наперечет', 'Counting All My Friends', 'Svi prijatelji na broju', 'Лена Андерсон', 'Lena Anderson', 'Lena Anderson', 'Знали бы вы, сколько зверей пришло в гости к Хвоинке! Эти стихи всемирно известной шведской писательницы Лены Андерсон перевёл на русский язык замечательный поэт Михаил Яснов. Для тех, кто учится считать, любит учить стихи наизусть и рассматривать картинки!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'веста-линнея-и-ее-друзья-1091'), 'Веста-Линнея и ее друзья', 'Vesta-Linnea and Her Friends', 'Vesta-Lineja i njeni prijatelji', 'Туве Аппельгрен', 'Tove Appelgren', 'Tuve Apelgren', '"Минди обещала позвонить, как только освободится. Скоро, скоро, совсем скоро. Прыг, прыг, прыг. Сегодня пятница! Светит солнце! Щебечут птицы! Все просто замечательно! Прыг!" Веста-Линнея ждет звонка от Минди и не выпускает телефон из рук. Она сгорает от нетерпения, ведь Минди такая веселая и смелая! Но телефон молчит. Неужели Минди не хочет дружить с Вестой-Линнеей?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'веста-линнея-и-собака-1092'), 'Веста-Линнея и собака', 'Vesta-Linnea and the Dog', 'Vesta-Lineja i pas', 'Туве Аппельгрен', 'Tove Appelgren', 'Tove Appelgren', '- Мама, - говорит Веста-Линнея однажды за ужином. - Я считаю, нам надо завести собаку. Эта светлая мысль рано или поздно приходит в голову почти каждому ребенку. Весте-Линнее повезло - и в ее семье появляется прелестное создание по имени Чих. У него бархатный лобик, смешной носик и маленькое сердечко, чье биение наполняет Весту-Линнею неизведанным до этого счастьем. Но тут на всю семью обрушивается ужасная новость - у Виктора… аллергия на шерсть! Неужели придется расстаться с Чихом навсегда?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'веста-линнея-и-лунный-свет-1093'), 'Веста-Линнея и лунный свет', 'Vesta-Linnea and the Moonlight', 'Vesta-Lineja i mjesečina', 'Туве Аппельгрен', 'Tove Appelgren', 'Tuve Apelgren', 'Иногда безо всякой причины на Весту-Линнею нападает черная тоска, но, к счастью, ненадолго. А что делать, если грусть не проходит? Если человек плачет весь день и его горе такое большое, что не помещается в комнате? А вдруг колодезной ведьме из страшного сна тоже бывает тоскливо? И как связаны грусть и радость?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дикие-соседи-1094'), 'Дикие соседи', 'Wild Neighbors', 'Divlje komšije', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Кролик купил себе летний домик и отправился в отпуск. Однако возле домика он обнаружил четырех диких кошек, которые лакали воду из фонтана! Кролик страшно перепугался. Что же делать? Шведская художница Ульрика Кестере сочинила и нарисовала историю о том, что даже страшные дикие кошки могут стать твоими друзьями, надо лишь попробовать найти к ним подход. Для дошкольного возраста');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'теплый-свитер-для-лемура-1095'), 'Теплый свитер для лемура', 'A Warm Sweater for a Lemur', 'Topli džemper za lemura', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Далеко на севере есть чернично-синий дом, покрытый травяной крышей. В нем живут рысь Лиза и медвежонок Нильс. К ним в гости приезжает лемур Отто. Вот это событие! Отто - художник и хочет нарисовать северное сияние. Все бы ничего, вот только Отто прибыл из теплых краев и простудился. Но друзья придумали замечательный способ его подбодрить!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленькая-ежинка-и-большая-еже-1096'), 'Маленькая ежинка и большая ежевика', 'Little Hedgehog and the Big Blackberry', 'Mala ježica i velika kupina', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Бывает, все наперебой поучают, говорят, что нужно делать. Робкая маленькая Ежинка попала как раз в такую историю. Она смущается, теряется, пугается, ко всем прислушивается. Но получится ли следовать таким разным советам? Да и всегда ли хорошо быть покладистой? Может быть, пора вспомнить, что собиралась сделать ты сама? Для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'день-рождения-1097'), 'День рождения', 'Birthday', 'Rođendan', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Дети хотят скорей повзрослеть. А взрослые - снова помолодеть. Правда, странно? Даже немного глупо. Такая уж штука - День рождения. Ждешь его или нет - он все равно наступит. И так - каждый год. Пока что никому не удалось это изменить. День рождения - твой личный праздник, маленький или большой. Как ты его отметишь? Устроишь настоящий трам-тарарам? Или захочешь побыть в тишине и спокойствии? А может, ни то ни другое? Никто не знает, кроме тебя!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'когда-кончается-печенье-1098'), 'Когда кончается печенье', 'When the Cookies Run Out', 'Kad ponestane keksića', 'Ульрика Кестере', 'Ulrika Kestere', 'Ulrika Kestere', 'Дома у песика Пелле и кошечки Лолло настоящий кавардак: вещи валяются тут и там, нигде не пройти. Кажется, пора навести порядок. Но чтобы были силы для уборки, нужно съесть чего-нибудь сладенького! В буфете не осталось ни конфетки, ни печенья. Как быть? Друзья отправляются на поиски сладостей и по дороге попадают в разные переделки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'комар-спасатель-1099'), 'Комар-спасатель', 'Mosquito the Rescuer', 'Komar spasitelj', 'Софи Геррив', 'Sophie Guerrive', 'Sofi Geriv', 'Игра-путешествие, в которой читателю предстоит составить компанию знаменитому динозавру-спасателю по имени Комар. На борту своего самолета-трансформера Комар отправляется в путь и находит пропавших людей, животных и потерянные предметы. Ни переполненный музей, ни девственный лес, ни подземный город с тысячей и одной пещерой не ускользнут от его орлиного глаза! Особенно, если ему поможет читатель! Полные мельчайших деталей иллюстрации Софи Геррив будут с интересом рассматривать и дети, и взрослые: художница спрятала среди персонажей и пейзажей множество остроумных отсылок к известным героям и символам из мира кино и литературы. Но вот, вы добрались до конца книги... И выясняется, что не все тайны раскрыты! Комар-Спасатель с жужжанием спешит на подвиги, а мы начинаем снова рассматривать книгу с еще большим интересом! Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пир-у-царя-зверей-1100'), 'Пир у царя зверей', 'The Feast of the King of Beasts', 'Gozba kod cara životinja', 'Сибил фон Олферс', 'Sibylle von Olfers', 'Sibila fon Olfers', 'Книга "Пир у царя зверей" рассказывает о шутливом соревновании зверей, которые стремятся угодить своему повелителю Льву и угостить его лучше всех. Автор книги - Сибилл фон Олферс, известный иллюстратор и писатель начала ХХ века, отразила в своих произведениях трепетную душу ребенка. Ее имя стоит в одном ряду с Эльзой Бесков, Кейт Гринуэй, Иваном Билибиным и другими художниками и писателями начала века.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленький-дед-мороз-путешеству-1101'), 'Маленький Дед Мороз путешествует вокруг света', 'Little Santa Travels Around the World', 'Mali Djed Mraz putuje oko svijeta', 'Ану Штонер', 'Anu Stohner', 'Anu Štoner', 'На Севере, в деревеньке Дедов Морозов, всё идёт как обычно: накануне Нового года Деды Морозы готовятся к большому путешествию... Но утром в день отъезда деревня оказывается опустевшей: на улочках ни души, светятся только окна больницы... "Новогодняя лихорадка!" - объясняет Доктор. "Кто же теперь развезёт подарки детям?!" - сокрушается Главный Дед Мороз. Кажется, у Маленького Деда Мороза есть идея...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленький-дед-мороз-едет-в-гор-1102'), 'Маленький Дед Мороз едет в город', 'Little Santa Goes to the City', 'Mali Deda Mraz ide u grad', 'Ану Штонер', 'Anu Stohner', 'Anu Štoner', 'Маленький Дед Мороз вместе со взрослыми Дедами Морозами живёт в деревеньке далеко на Севере. Он тоже украшает ёлку, печёт печенье и готовит подарки. Только дарит он их не детям, а лесным зверям. Но вот незадача: вдруг оказывается, в городе есть звери - и они тоже хотят получать подарки! Что же делать Маленькому Деду Морозу? Он спешит к Главному Деду Морозу - у того всегда совет наготове! "Ну а мы что можем поделать? - ворчит тот в свою длинную бороду. - Город далеко, ты маленький и сам не доберёшься. А в санях у больших Дедов Морозов подарки для детей едва умещаются". До города и правда очень далеко, а все олени нужна большим Дедам Морозам. Неужели городские звери снова останутся без подарков?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ночной-цирк-1103'), 'Ночной цирк', 'Circus Night', 'Noćni cirkus', 'Матиас де Леу', 'Mattias De Leeuw', 'Matijas De Lev', 'Жила-была девочка. Она мечтала о цирке: училась жонглировать мячиками, крутить обручи и даже дрессировать игрушечных зверей. Однажды ночью она оказалась в цирке-шапито с самыми настоящими жонглерами, укротителями, фокусниками и силачами. И сама стала участницей настоящего циркового представления... История о заветной детской мечте, рассказанная без единого слова, будет понятна всем, и детям, и взрослым.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лев-в-библиотеке-1104'), 'Лев в библиотеке', 'Library Lion', 'Lav u biblioteci', 'Мишель Кнудсен', 'Michelle Knudsen', 'Mišel Knudsen', 'Заведующая библиотекой мисс Мерривезер очень трепетно относится к правилам. Бегать нельзя. Кричать нельзя. А когда однажды в библиотеку приходит настоящий лев, она не знает, что делать, ведь в правилах ничего об этом не сказано! Но оказывается, что лев - находка для библиотеки: его лапы тихо ступают по полу, на него, как на большой мягкий диван, усаживаются дети, когда слушают сказки. И даже когда ему приходится нарушить сразу несколько правил, мисс Мерривезер не злится. Потому что это особый случай!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'книга-о-любви-1105'), 'Книга о любви', 'The Love Book', 'Knjiga o ljubavi', 'Пернилла Стальфельт', 'Pernilla Stalfelt', 'Pernila Stalfelt', '"Однажды, хочешь - верь, хочешь - не верь, Амур найдет тебя и постучится в дверь. Стрела его пронзит твою грудную клетку. Закружит голову и свалит в табуретки. Любовь слепа, как говорится. Но ничему живому от нее не скрыться".');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'книга-о-смерти-1106'), 'Книга о смерти', 'The Death Book', 'Knjiga o smrti', 'Пернилла Стальфельт', 'Pernilla Stalfelt', 'Pernila Stalfelt', 'От жизни люди умирают. Звери - тоже. Даже морская свинка вечно жить не может, Хотя, наверное, хотела бы. Увы. В виде букета загибаются цветы, Червяк обычно погибает на крючке, Комар - на лбу, а бабочка - в сачке. И, вспоминая про былое, Больной старик мечтает о покое И думает о тех, кого с ним больше нет, И о количестве прошедших зим и лет. Зима всегда сменяет лето, А после жизни наступает смерть, но это Совсем не страшно, потому что Без смерти жизнь была бы скучной');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'одного-поля-ягоды-1107'), 'Одного поля ягоды', 'Birds of a Feather', 'Svi smo mi jednaki', 'Пернилла Стальфельт', 'Pernilla Stalfelt', 'Pernila Stalfelt', 'Все дети имеют равные права и одинаково достойны любви. Все дети имеют право выражать свое мнение. Дети имеют право рассчитывать на серьезное отношение и понимание со стороны взрослых... В этой книге авторы на примере различных жизненных ситуаций, проиллюстрированных цветными картинками, учат детей быть терпимыми к людям других национальностей, уважать чувства других людей, правильно вести себя со своими сверстниками.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'война-1108'), 'Война', 'War', 'Rat', 'Леттриа', 'José Jorge Letria and André Letria', 'Žoze Žorž Letrija i Andre Letrija', 'Книга о войне, рассказанная отцом и сыном. Поэзия иллюстраций и текста. Она приходит внезапно, как болезнь. Она не видит, не слышит, не чувствует. Она гнетёт, давит, заставляет молчать. За ней остаются лишь руины и мёртвая тишина. Война — самое страшное и самое живучее изобретение человечества. «Война» получила признание критиков всего мира и снискала множество литературных премий. На момент выхода книги на русском языке она издана на 12 языках и собрала уже больше 10 наград. Получила награду выставки в Болонье, а также Little Hakka, Portuguese Illustration Prize, NY Rights Fair Talking Pictures Award, и многие другие.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'флон-флон-и-мюзетт-1109'), 'Флон-Флон и Мюзетт', 'Flon-Flon and Musette', 'Flon-Flon i Muzet', '', 'Elzbieta', 'Elžbijeta', 'Как разговаривать о войне с детьми? Ведь они с малых лет должны понимать, что война бессмысленна и люди сами выдумывают себе врагов. Благодаря этой простой, но глубокой истории о двух друзьях-зайчатах Флон-Флоне и Мюзетт, разлучённых войной, даже самые маленькие читатели поймут, как страшна и жестока любая война и как ценен мир. В выразительных иллюстрациях мягких пастельных тонов живой классик французской детской литературы, автор-иллюстратор польского происхождения Эльжбета сумела показать нежную дружбу героев, боль разлуки, силу надежды и любви, побеждающих страх и разрушение. «Война не умирает, сынок. Она лишь засыпает время от времени. И когда она спит, нужно быть очень осторожными, чтобы не разбудить её». «Самокат» перевел и подготовил на русском тексты и методики этих занятий и готов поделиться с ими с заинтересованными специалистами и родителями.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чемпион-1110'), 'Чемпион', 'The Champion', 'Šampion', '', 'Farhad Hasanzadeh', 'Farhad Hasanzade', 'В чемпионской семье превыше всего ценятся сила и выносливость. Логично — без них будущему чемпиону не добыть ни спортивных званий, ни наград. Вот только Абтин не хочет их добывать. И не хочет становиться чемпионом. В руках у него тонкая кисточка, а в голове и в сердце — все краски мира. Но что может один против всех, один юный художник с тонкой кисточкой — против целого семейства чемпионов? Представьте, кое-что может – если найдёт в себе достаточно мужества и немножко смекалки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'маленький-принц-ил-б-алеманья--1111'), 'Маленький принц (ил. Б. Алеманья)', 'The Little Prince (illus. by Beatrice Alemagna)', 'Mali princ (il. Beatriče Alemanja)', '', 'Antoine de Saint-Exupéry', 'Antoan de Sent Egziperi', 'Издание в твёрдом переплете. Плотная бумага, чёткий, удобный для чтения шрифт. Цветные иллюстрации. Знаменитая книга Антуана де Сент-Экзюпери «Маленький принц» переведена более чем на 300 языков мира. Миллионы её поклонников повторяют знаменитые слова: «Ты навсегда в ответе за тех, кого приручил», «Встал поутру, умылся, привёл себя в порядок — и сразу же приведи в порядок свою планету», «Но ведь нет таких магазинов, где торговали бы друзьями, и потому люди больше не имеют друзей». Трогательная философская сказка рассказала людям о жизни так просто и понятно, что сама стала частью жизни. Среди десятков именитых художников, создававших образы героев книги, нельзя не отметить французского иллюстратора итальянского происхождения Беатриче Алеманья. Лауреат более 10 международных премий и конкурсов, автор 15 иллюстрированных альбомов и 30 книг, Беатриче Алеманья уделяет особое внимание чувствам и эмоциям персонажей. Возможно, поэтому её работы находят самый горячий отклик в детских сердцах. И как тут не вспомнить ещё одну знаменитую цитату из книги: «Зорко одно лишь сердце. Самого главного глазами не увидишь».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'билет-для-зайца-1112'), 'Билет для зайца', 'A Ticket for a Hare', 'Karta za zeca', '', 'Denis Kryukov', 'Denis Krjukov', 'Юная блогер Аня — коренная москвичка, ее семья живет в столице с незапамятных времен. Но это не простая семья, а целая династия… зайцев! Все Анины родственники были сплошь замечательными ребятами и взрослыми. Но была у них одна удивительная особенность: не ладили они с городским транспортом. Норовили все проехать бесплатно! И не по злому умыслу, а как раз от своей замечательности, а также мечтательности и изобретательности. Но не волнуйтесь, все они исправились и перестали быть безбилетниками. И только Аня всегда исправно оплачивала проезд, потому что у нее была своя мечта — найти счастливый билетик. Книга-картинка с остроумными и нежными рассказами Дениса Крюкова и такими же иллюстрациями Полины Калашниковой знакомит детей не только с ушастыми горожанами, но и с историей развития городского транспорта и билетной системы c конца XIX века до наших дней. Книга «Билет для зайца» нарисована спиртовыми маркерами — любимым материалом художницы. Спиртовые маркеры напоминают Полине о детстве, которое она провела за рисованием фломастерами (от них не отрывало даже поедание супа). В отличии от фломзиков, маркеры позволяют работать с толщиной линии и цветовыми наложениями. «Маркеры почти не пачкаются, их можно везде взять с собой и в любой момент вытащить из рюкзака. Плюс они очень быстро позволяют зафиксировать идею. Мне важно, чтобы рука поспевала за ходом мысли. Или я за ходом руки. Не знаю, что в моем случае первостепенно».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'зачем-троллейбус-сбросил-рога--1113'), 'Зачем троллейбус сбросил рога?', 'Why Did the Trolleybus Shed Its Horns?', 'Zašto je trolejbus odbacio rogove?', '', 'Unknown', 'Nepoznati autor', 'Куда пропали московские троллейбусы? Они просто сбросили рога и превратились в электробусы! А произошло это благодаря одному весёлому синему троллейбусу, который мечтал увидеть весь мир, а не ездить каждый день по одинаковым маршрутам. Как и его лучший друг олень Бобка, троллейбус сбросил красивые, но большие и неудобные рога — ведь мечты и дружба стоят того, чтобы меняться. Совместная книга Музея транспорта Москвы и издательства А+А рассказывает историю троллейбусов, которые появились много лет назад в Германии и объехали весь мир, и раскрывает тайну: где и сегодня можно увидеть столичные троллейбусы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'звезда-1114'), 'Звезда', 'The Star', 'Zvijezda', 'Десницкая Анна', 'Anna Desnitskaya', 'Ana Desnickaja', 'Всем оставленным домам, всем переездам, вольным и невольным, посвящается. Надолго ли обретено спокойствие на новом месте? Неизвестно. Но твоя звезда всегда с тобой, где бы ты ни оказался, — и светит в окне.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'на-краю-света-1115'), 'На краю света', 'At the Edge of the World', 'Na kraju svijeta', 'Десницкая Анна', 'Anna Desnitskaya', 'Ana Desnickaja', 'Вера и Лукас растут на двух краях света. На Камчатке и в Чили жизнь очень разная, но тоскуют от одиночества везде похоже. И если настойчиво и долго посылать сигналы – то однажды может случиться чудо. Вечером мы с мамой выходим на берег океана. Я стою у воды и представляю – вот бы там, за краем света, у меня был друг. Я достаю фонарик из кармана куртки и свечу им в темноту над морем. Короткая вспышка, две длинных, потом снова короткая: точка-тире-тире-точка. Две точки, точка-тире-тире, точка, тире. На азбуке Морзе это означает: «привет». Я мигаю в темноту: «Привет, меня зовут Вера. Привет, меня зовут Вера»');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'слухи-в-империи-1116'), 'Слухи в империи', 'Rumors in the Empire', 'Glasine u carstvu', 'Аксёнов Андрей', 'Andrey Aksyonov', 'Andrej Aksjonov', 'Даже у самых смешных и абсурдных слухов есть бытовые корни. Зависть, способ объяснить неизвестное или хитрый инструмент управления — если тебе кто-то не нравится, самое время пустить про него неприятную сплетню! По крайней мере, так иногда поступали в Российской империи. До сих пор мы слышим удивительные истории, которые родились из сплетен. Только представьте, сколько всего обсуждали в то время, и как легко люди могли во всё это поверить! У иллюстратора Кати Гущиной и историка Андрея Аксёнова есть преимущество перед нашими предками — дистанция от той словесной суеты, которая позволяет спокойно восстановить историю, подтвердить или опровергнуть слухи о российских императорах от Петра I до Николая II. Но, несмотря на это, авторы напоминают нам о том, что все правители, ученые, писатели, полководцы и народ прошлых веков — это на самом деле всё ещё очень живое настоящее.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'франсуа-трюффо-мальчик-из-кино-1117'), 'Франсуа Трюффо. Мальчик из кино', 'François Truffaut: The Boy of Cinema', 'Fransoa Trifo: Dječak iz bioskopa', 'Лука Тортолини', 'Luca Tortolini', 'Luka Tortolini', 'Какое было детство у будущих знаменитостей? Что помогало им стать мастерами своего дела? Для кого-то этот путь был проще: его поддерживала семья. А Франсуа Трюффо, замечательный французский режиссер, самый молодой обладатель гран-при Каннского фестиваля, не был избалован любовью домашних. Его детство было полно разочарований и не очень радостных приключений. Но у него была настоящая страсть — кино, и она преображала действительность, создавала целый мир и дарила надежду. Эта книга о том, что, если делаешь то, что любишь, как бы ни было трудно, — ты будешь вознаграждён. В 2022 году Трюффо могло бы исполниться 90 лет. Многие знают его по дебютному фильму о детстве «400 ударов». Виктория Семыкина, мастер смешанных техник и киноман, нарисовала историю взросления Трюффо, заложив в книгу образы из его любимого кино. Искать их – отдельное удовольствие для взрослых. А для детей эта живописная книжка-картинка станет прекрасным примером того, что и тяжелое детство может преобразиться, если следовать за своей мечтой со всем упорством.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'секреты-пластилина-1118'), 'Секреты пластилина', 'The Secrets of Plasticine', 'Tajne plastelina', 'Рони Орен', 'Roni Oren', 'Roni Oren', 'Во что может превратиться кусочек пластилина в руках ребенка? Это всегда талантливая и очень интересная импровизация. На занятиях Рони Орена малыши не просто играют, они думают, фантазируют, изобретают, реализуют свои творческие замыслы. Эта книга поможет вам правильно воспитать и лучше узнать своего ребенка. Дети с удовольствием будут делать фигурки разных животных; учиться смешивать цвета, экспериментировать, фантазировать и придумывать новые игрушки. Во время работы над котенком, петушком или черепахой ребенок сможет создать свой собственный мир - не виртуальный, как это принято в наши дни, а самый настоящий, сделанный своими собственными руками. Этот мир будет населен зверюшками, которые малыш без труда вылепит из пластилина с помощью одного очень важного секрета. Откройте этот секрет маленькому ученику!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'секреты-пластилина-динозавры-1119'), 'Секреты пластилина Динозавры', 'Secrets of Clay: Dinosaurs', 'Tajne plastelina: Dinosaurusi', 'Рони Орен', 'Roni Oren', 'Roni Oren', 'Автор книги Рони Орен известен в мире не только как талантливый мультипликатор, но и как блестящий педагог, имеющий многолетний опыт работы с детьми. Методика Рони Орена получила признание и широко используется в разных странах. Придуманные и созданные им яркие и неповторимые образы помогают детям осваивать искусство лепки, развивать мелкую моторику, речь и эстетический вкус. Пластилиновый мир и истории Рони Орена - это безграничные возможности развития детской фантазии и ее воплощения. Любознательные малыши с удовольствием отправятся в увлекательное путешествие и познакомятся с динозаврами. Они научатся экспериментировать, самостоятельно подбирать нужный цвет пластилина и легко работать с большим количеством деталей.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'секреты-пластилина-новый-год-1120'), 'Секреты пластилина Новый год', 'Secrets of Clay: New Year', 'Tajne plastelina: Nova godina', 'Рони Орен', 'Roni Oren', 'Roni Oren', 'Автор книги Рони Орен известен в мире не только как талантливый мультипликатор, но и как блестящий педагог, имеющий многолетний опыт работы с детьми. Методика Рони Орена получила признание и широко используется в разных странах. Придуманные и созданные им яркие и неповторимые образы помогают детям легко осваивать искусство лепки, развивать мелкую моторику, речь и эстетический вкус. Пластилиновый мир и истории Рони Орена - это безграничные возможности развития детской фантазии и ее воплощения. На страницах этой книги маленькие читатели встретятся с Дедом Морозом, Снегурочкой и их друзьями, окунутся в веселую предпраздничную суету и сами сделают забавные новогодние подарки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пластилиновая-лаборатория-чево-1121'), 'Пластилиновая лаборатория Чевостика', 'Chevostik''s Plasticine Laboratory', 'Čevostikova plastelinska laboratorija', 'Людмила Сеньшова', 'Lyudmila Senshova', 'Ljudmila Senjšova', 'Очень сложно объяснить ребёнку, как устроен атом или речная система, чем отличаются высококучевые облака от перисто-слоистых, или описать, как выглядят флаги Туниса или Ганы. Но еще труднее заинтересовать его этим. "Пластилиновая лаборатория Чевостика" - уникальная книга. Она не только расскажет ребёнку о сложных предметах и явлениях окружающего мира, но и доступным языком ответит на извечные детские "почемучки": почему горит лампочка? Почему звезды такие маленькие? Из чего мы сделаны? Как летает самолёт? Почему листья зелёные? Почему...? Почему...? Почему...? А ещё вовлечет его в процесс познания и изучения окружающего мира. Эта книга не учебник по лепке, это путеводитель по Вселенной: от атома до гигантских созвездий, от цветка до насекомых, от колеса до пожарной машины. И каждый элемент этой Вселенной ребёнок сможет создать собственными руками. Потребуется лишь пластилин и немного фантазии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пластилиновая-лаборатория-чево-1122'), 'Пластилиновая лаборатория Чевостика 2', 'Chevostik''s Plasticine Laboratory 2', 'Čevostikova plastelinska laboratorija 2', 'Людмила Сеньшова', 'Lyudmila Senshova', 'Ljudmila Senjšova', 'Очень сложно объяснить ребёнку, как устроен атом или речная система, чем отличаются высококучевые облака от перисто-слоистых, или описать, как выглядят флаги Туниса или Ганы. Но еще труднее заинтересовать его этим. "Пластилиновая лаборатория Чевостика" - уникальная книга. Она не только расскажет ребёнку о сложных предметах и явлениях окружающего мира, но и доступным языком ответит на извечные детские "почемучки": почему горит лампочка? Почему звезды такие маленькие? Из чего мы сделаны? Как летает самолёт? Почему листья зелёные? Почему...? Почему...? Почему...? А ещё вовлечет его в процесс познания и изучения окружающего мира. Эта книга не учебник по лепке, это путеводитель по Вселенной: от атома до гигантских созвездий, от цветка до насекомых, от колеса до пожарной машины. И каждый элемент этой Вселенной ребёнок сможет создать собственными руками. Потребуется лишь пластилин и немного фантазии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чудный-поезд-мчится-в-сон-1123'), 'Чудный поезд мчится в сон', 'Steam Train, Dream Train', 'Čudesni voz snova', 'Column 2', 'Sherri Duskey Rinker', 'Šeri Daski Rinker', 'Чудесные стихи о паровозе сновидений. Полярные медведи, обезьяны и черепахи, слоны и жирафы помогают загрузить его вагоны необычными грузами, а потом отправляются на нем в сладкий сон. Авторы книги "Стройка баюшки-баю" - книги номер один по версии New York Times и так полюбившейся в России, выпустили вторую удивительную книгу - для чтения на ночь. Теперь мы укладываем спать поезд и его пассажиров! Для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '14-лесных-мышей-зимний-день-1124'), '14 лесных мышей Зимний день', '14 Forest Mice: Winter Day', '14 šumskih miševa: Zimski dan', 'Кадзуо Ивамура', 'Kazuo Iwamura', 'Kazuo Iwamura', '«14 лесных мышей» — очень популярная в Японии и многих европейских странах серия книг о красоте повседневности и о жизни трех поколений мышиного семейства: бабушки, дедушки, мамы, папы и еще десяток мышат. В книге «14 лесных мышей. Зимний день» уместился один уютный и радостный снежный день: пока за окном метель, мышата со старшими играют в настольные игры, мастерят и лакомятся. А когда буря стихает, можно отправиться кататься с горок на новеньких саночках и играть в снежки! Книги Кадзуо Ивамура напоминают миниатюрные кукольные домики, в которых хочется рассмотреть и потрогать каждую деталь, а каждое маленькое событие наполнено истинно японской философией и любованием жизнью в каждом ее моменте.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'что-делать-если-2-1125'), 'Что делать если... 2', 'What to Do If... 2', 'Šta raditi ako... 2', 'Людмила Петрановская', 'Lyudmila Petranovskaya', 'Ljudmila Petranovska', 'В новой книге известного психолога речь пойдёт о выборе, о принятии решений, об ответственности, о том, как важно уметь оценивать риски. Она станет умным собеседником для школьников и бесценным помощником для их родителей. Для детей младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лето-в-деревне-1126'), 'Лето в деревне', 'Summer in the Countryside', 'Ljeto na selu', 'Зина Сурова', 'Zina Surova', 'Zina Surova', 'Лето - это свобода, яркие впечатления и наблюдения за природой. А где, как не в деревне, ты можешь по-настоящему почувствовать вкус лета? Здесь сладкая земляника, велосипеды, рыбалка, ночёвка под открытым небом, тарзанка, поход за грибами, яблоки из сада и много-много всего, что недоступно нам в городе. В этой книге вас ждет увлекательный и познавательный рассказ от лица одиннадцатилетнего мальчика - его впечатления от жизни в деревне и удивительная история о лете, полном игр, творчества и незабываемых приключений. Зина Сурова написала эту книгу на основе личных впечатлений: каждое лето она проводит с семьей в деревне.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'все-деньги-мира-1127'), 'Все деньги мира', 'All the Money in the World', 'Sav novac svijeta', 'Виталий Константинов', 'Vitali Konstantinov', 'Vitali Konstantinov', 'Для среднего и старшего школьного возраста Евро, доллар, йена, франк, рубль, фунт — деньги есть во всём мире. Но что такое «деньги» на самом деле? Монеты, купюры, счёт в банке? Кредитные карты и криптовалюта? Кто всё это придумал, когда и где? Действительно ли деньги правят миром и по каким законам? Как велась торговля до того, как появились деньги? Правда ли, что где деньги — там и обман, и несправедливость? Самое время найти ответ на все эти вопросы с помощью научно-популярного комикса и стать настоящим экспертом по истории денег. Виталий Константинов — иллюстратор, комиксист, писатель. Его работы изданы в 40 странах и удостоены многочисленных премий. Недавно его комикс «История письменности: от клинописи до эмодзи» вышла в нашем издательстве и сразу стала бестселлером. В новой книге вы познакомитесь с разными аспектами существования и использования денег. Это своего рода путеводитель по всемирной истории денежных отношений, который поможет разобраться в том, что действительно волнует всех: правда ли деньги правят миром. Вместе с Виталием Константиновым мы отправимся в занимательное и познавательное путешествие от каури к монетам, от первых банкнот к современным криптовалютам.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'богатые-и-бедные-1128'), 'Богатые и бедные', 'Rich and Poor', 'Bogati i siromašni', 'Джерри Бейли', 'Gerry Bailey', 'Džeri Bejli', 'Книги серии "Деньги? Деньги… Деньги!" рассчитаны на детей среднего школьного возраста и в простой, увлекательной форме рассказывают о разных аспектах современной экономики. Книга "Богатые и бедные" посвящена главному социальному противоречию нашей эпохи - постоянно увеличивающемуся разрыву между богатством и нищетой. Рассматриваются такие вопросы, как возникновение и утрата огромных состояний, финансовый успех, деньги и личное счастье, перераспределение богатства, деятельность международных финансовых организаций, благотворительность, злоупотребление богатством.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'на-вес-золота-1129'), 'На вес золота', 'Worth Its Weight in Gold', 'Suvo zlato', '', 'Unknown', 'Nepoznati autor', 'Человечество с глубокой древности использовало для торговли и накопления богатства маленькие кусочки драгоценных металлов с надписями и рисунками. В последние годы, с появлением банковских карточек, приложений и прочих технологий, монетки всё реже звенят в наших карманах. Но всё то, что люди отчеканили за тысячелетия, никуда не исчезло: просто монеты из денег превратились в хранителей множества историй и ключи к прошлому. Эта книга предлагает посмотреть на всемирную историю через призму нумизматики — науки о монетах. Наш читатель не только научится понимать язык монет, перенесётся в далекие эпохи и государства, встретит великих правителей и мастеров, но, может быть, решится пополнить ряды нумизматов и начнёт собирать собственную коллекцию. Большие открытия начинаются с малого — иногда совсем крошечного металлического кружка.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'спроси-у-папы-1130'), 'Спроси у папы', 'Ask Dad', 'Pitaj tatu', 'Давид Кали', 'Davide Cali', 'Davide Kali', 'Взрослые вечно говорят загадками: "Вырастешь - поймешь", "Не знаю, посмотрим", "Нельзя иметь все!"... А еще задают детям вопросы, хотя ответы их явно не интересуют. Почему так происходит и что на самом деле они хотят сказать? Эта книга поможет тебе разобраться.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'малютка-лабан-привидение-из-ко-1131'), 'Малютка Лабан, привидение из королевского замка', 'Little Ghost Laban, the Ghost from the Royal Castle', 'Mali duh Laban, sablast iz kraljevskog dvorca', '', 'Inger and Lasse Sandberg', 'Inger i Lase Sandberg', 'Малютка Лабан - доброе привидение из замка Проснись-и-Пой. Его отец хочет, чтобы сын научился пугать людей и стал таким же жутким, как он. Но Лабан боится привидений, и ему не нравится темнота в королевском замке. И вот однажды ночью папа взял малютку с собой в ночной рейд. Семейство привидений из королевского замка уже более полувека пугает детей во всем мире. По книгам Ингер и Лассе Сандберг был снят популярный мультсериал, они переведены на 33 языка и являются вторыми по популярности в библиотеках Швеции.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'малютка-лабан-приключения-в-за-1132'), 'Малютка Лабан, приключения в замке', 'Little Ghost Laban: Adventures in the Castle', 'Mali duh Laban: Avanture u dvorcu', '', 'Inger and Lasse Sandberg', 'Inger i Lase Sandberg', 'Малютка Лабан, принц Скок и Лаболина знакомятся с Груффолиной, сражаются с уборочной машиной волшебника и помогают папе выполнять его нелегкую работу. Семейство привидений из королевского замка уже более полувека пугает детей во всем мире. По книгам Ингер и Лассе Сандберг был снят популярный мультсериал, они переведены на 33 языка и являются вторыми по популярности в библиотеках Швеции. Для дошкольного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'малютка-лабан-снова-рождество--1133'), 'Малютка Лабан. Снова Рождество!', 'Little Ghost Laban: It''s Christmas Again!', 'Mali duh Laban: Opet Božić!', '', 'Inger and Lasse Sandberg', 'Inger i Lase Sandberg', 'Все уже решили, что подарят мамам и папам на Рождество, и только Лабан пока ничего не придумал. А он так хотел приготовить самый лучший подарок! Кто же ему поможет? Похоже, осталось надеяться лишь на чудо. И ночь перед Рождеством - как раз то время, когда чудеса случаются. Для дошкольного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'самая-большая-книга-что-зачем--1134'), 'Самая большая книга что? зачем? почему?', 'The Biggest Book of What? Why? How?', 'Najveća knjiga šta? zašto? kako?', 'Ермакович Дарья', 'Darya Ermakovich', 'Darja Ermakovič', 'Увлекательная иллюстрированная энциклопедия для любознательных детей, отвечающая на самые популярные и неожиданные вопросы обо всем на свете — от природы и космоса до науки и человека.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'самые-известные-динозавры-и-ре-1135'), 'Самые известные динозавры и рептилии', 'The Most Famous Dinosaurs and Reptiles', 'Najpoznatiji dinosaurusi i gmizavci', 'Владис 2018', 'Vladis Editorial', 'Vladis', 'Познавательная энциклопедия приглашает юных читателей в доисторический мир динозавров и современных рептилий, знакомя с их повадками, средой обитания и удивительными особенностями.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'акулиска-враг-редиски-1136'), 'Акулиска враг Редиски', 'Fox and Piglet: The Radish Shark', 'Lisac i Prase: Ajkula od rotkvica', '', 'Bjørn F. Rørvik', 'Bjern F. Rorvik', 'На русском языке наконец выходит самая популярная в Норвегии серия детских книг! Истории о Лисе и Поросенке издаются там уже больше 20 лет, получили приз министерства культуры Норвегии. В первой книжке из серии историй о Лисе и Поросёнке мы знакомимся с ними и с другими удивительными персонажами. А кажется, что мы знакомы уже давно: с места в карьер, с первой же страницы, мы отправляемся с героями на поиски кукушки, которая исполняет любые желания, скачем верхом на королевской плюгавой, спасаем урожай редиски от вредной акулиски — грозы огородов, ищем драгоценные лисумруды и поросяхонты и притворяемся французским зелёным жаворонком, чтобы раздобыть йогурт с дыней. Одновременно на русском языке выходит вторая книга серии — «Кафе „Птичий хвост“ из историй о Лисе и Поросенке».');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-поросенок-болел-леопардозо-1137'), 'Как поросенок болел леопардозом', 'How Piglet Caught Leoparditis', 'Kako se prase razboljelo od leoparditisa', '', 'Bjørn F. Rørvik', 'Bjern F. Rorvik', 'Долгожданное пополнение в серии уморительно смешных историй о Лисе и Поросёнке! Лис и Поросёнок затеяли новую игру. Поросёнка сразила неизвестная болезнь. Доктора! Скорее! И доктор незамедлительно приходит на помощь — в белом халате и с хворометром в руках. Оказывается, у Поросёнка воспалился сипундер, его придётся удалить. Немедленно! Щипцами! Но Поросёнок категорически и громко не согласен. Пусть лучше у него будет леопардоз, который лечат газировкой и булочками. Только и в этой истории всё пойдёт не так, как задумали Лис и Поросёнок!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кафе-птичий-хвост--1138'), 'Кафе "Птичий хвост"', 'Café Birdtail', 'Kafe „Ptičji rep”', '', 'Bjørn F. Rørvik', 'Bjørn F. Rørvik', 'На русском языке наконец выходит самая популярная в Норвегии серия детских книг! С этими смешными и дикими историями растёт уже второе поколение норвежских детей. Авторы получили множество премий, а истории переведены на пять языков. Во второй книжке наши давние знакомые — Лис и Поросёнок снова нашли приключения себе на голову (и на хвост). На этот раз друзья надумали открыть кафе для перелётных птиц. Блюда там на любой вкус: мясные мухи под соусом и отборные червяки, суп из личинок и живой десерт прямиком из муравейника. Вот только расплачиваться за угощение птицам придётся очень необычным способом. И всё шло по плану, пока в кафе не наведалась прожорливая проглотка...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'свитер-на-рождество-1139'), 'Свитер на Рождество', 'A Christmas Sweater', 'Džemper za Božić', '', 'Bjørn F. Rørvik', 'Bjern F. Rorvik', 'Картон Лютый заделался почётным членом клуба ниссе. И даже получил приглашение на новогоднюю встречу. Международную, между прочим. На таких важных мероприятиях дундук и не бывал никогда, идти самому боязно. Может, Лис с Поросёнком составят ему компанию? Друзья охотно соглашаются: там ведь будет лотерея с подарками и хоровод вокруг ёлки. Вот только приходить на праздник отчего-то нужно раздетым, без свитера…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вс-проглот-1140'), 'Всёпроглот', 'The All-Swallower', 'Svegutač', '', 'Bjørn F. Rørvik', 'Bjørn F. Rørvik', 'Лис затеял уборку в норе и решил заодно вычистить грязнющий ковёр. Сначала они с Поросёнком попробовали его вытрясти, но лишь засыпали пылью Поросёнка, а ковёр, увы, сделался ещё грязнее. Зато прилетели цыцыроны. От них друзья узнали, что Картон Лютый обзавёлся всёпроглотом. Но справится ли этот агрегат с ковром? «Справится и не подавится!» — уверяет их дундук, однако же чудо-машину напрокат не даёт. Приходится Лису с Поросёнком идти на хитрость, чтобы проучить жадину...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дед-надзор-1141'), 'Дед-надзор', 'The Christmas Inspector', 'Deda Nadzor', '', 'Bjørn F. Rørvik', 'Bjern F. Rervik', 'Гуляли себе Лис и Поросёнок по зимнему заснеженному лесу — и случайно угодили на стоянку охламонов. Но тем не до незваных гостей, свалившихся со снегом им на голову, — они ждут Деда-Надзора. Оказывается, есть у охламонов давняя традиция: весь декабрь, до самого Рождества, нужно угощать Деда-Надзора приготовленными по его заказу тортами. А иначе Рождество не наступит. Дед-Надзор является за очередным тортом, и Лис с Поросёнком озадачены: больно уж странно он выглядит. Друзья решают выяснить, кто же этот загадочный любитель тортов.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'конни-и-кот-нок-1142'), 'Конни и котёнок', 'Conni and the Kitten', 'Koni i mače', '', 'Liane Schneider', 'Liane Šnajder', 'Конни Клавиттер живет с мамой и папой в небольшом немецком городке. Ей три года, она совсем недавно начала ходить в детский сад и мечтает о домашнем животном. И вот однажды ее мечта сбывается — к ней в дом попадает потерявшийся котенок. Сможет ли Конни оставить его у себя? Или надо обязательно найти хозяина? Чем кормить котенка, где устроить ему «домик» и как следить за его здоровьем? Прочитайте историю Конни и научитесь вместе с ней ухаживать за домашними животными.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'конни-ид-т-в-детский-сад-1143'), 'Конни идёт в детский сад', 'Conni Goes to Kindergarten', 'Koni ide u vrtić', '', 'Liane Schneider', 'Lijane Šnajder', 'Добрая терапевтическая история о первом дне трёхлетней Конни в детском садике. Книга помогает малышу справиться с волнением перед незнакомой обстановкой, научиться заводить друзей и оставаться без мамы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'конни-и-карманные-деньги-1144'), 'Конни и карманные деньги', 'Conni and Pocket Money', 'Koni i džeparac', '', 'Unknown', 'Nepoznati autor', 'Поучительная история знакомит малышей с основами финансовой грамотности на примере Конни, которая учится обращаться с первыми карманными деньгами, копить на желанную покупку и планировать траты.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'везучая-уточка-1145'), 'Везучая уточка', 'The Lucky Duck', 'Srećna patkica', 'Холли Вебб', 'Holly Webb', 'Holi Veb', 'Чем может Молли помочь утке, приносящей удачу? Найти её яйцо. Только это яйцо совершенно не похоже на обычные утиные яйца, и пропало оно в парке. Где как раз устроили весёлое приключение для детей - поиск шоколадных яиц. Так что везение Молли и утке точно понадобится! Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лес-дружбы-лисичка-тыковка-или-1146'), 'Лес дружбы. Лисичка Тыковка или лунный камень', 'Forest of Friendship: Pumpkin the Fox or the Moonstone', 'Šuma prijateljstva: Lisica Tikvica ili Mjesečev kamen', 'Дейзи Медоус', 'Daisy Meadows', 'Dejzi Medous', 'Можно ли научить дракона танцевать? Лили и Джесс, конечно же, попробуют, только вот дракон Клякса учиться не хочет. Но лисичка Тыковка придет им на помощь, и тут не только дракон, а все обитатели Леса Дружбы пустятся в пляс.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ежонок-эмили-или-корона-для-ум-1147'), 'Ежонок Эмили или корона для умницы', 'Emily Prickleback''s Clever Idea', 'Ježić Emili ili kruna za pametnicu', 'Дейзи Медоус', 'Daisy Meadows', 'Dejzi Medous', 'Дейзи Медоус - автор более ста книг для детей, среди которых серия Rainbow Magic - всемирный бестселлер о приключениях фей. Представляем вашему вниманию ее новый проект! Лили и Джесс - лучшие подруги, они обожают животных и даже помогают в ветклинике. Однажды девочки знакомятся с необычной кошкой Голди, которая привела их в волшебное место - Лес Дружбы, где все животные умеют разговаривать. С этого дня приключения следуют одно за другим! Ежонок Эмили признана самой умной из маленьких жителей Леса Дружбы. Но с заклятием дракона Пылинки даже она не может справиться. Лили и Джесс приходят ей на помощь - и теперь им втроем предстоит придумать, как спасти реку!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'щенок-поппи-или-сонные-чары-1148'), 'Щенок Поппи или сонные чары', 'Poppy the Puppy and the Sleep Spell', 'Štene Popi i uspavana čarolija', '', 'Daisy Meadows', 'Dejzi Medouz', 'Мерзкая ведьма Гризельда наслала на щенка Пэтча сонные чары. Его сестрёнка Поппи вместе с Лили и Джесс пытаются развеять колдовство, но у них очень мало времени. Ведь, если щенка не разбудить до заката, он уснёт навсегда!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'бельчонок-софи-или-осторожно-д-1149'), 'Бельчонок Софи или осторожно, драконы!', 'Sophie Flufftail: Beware of Dragons!', 'Vjeverica Sofi ili pazi, zmajevi!', '', 'Daisy Meadows', 'Dejzi Medous', 'В Лесу Дружбы появились драконы - и с не самыми дружелюбными намерениями! Один из них заморозил Дом Света и сразу стало темно и холодно. Лили и Джесс поспешили на помощь друзьям и теперь вместе с белочкой Софи им надо вернуть в Лес Дружбы лето! Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'принцессы-пони-друг-из-облачно-1150'), 'принцессы пони. Друг из облачного леса', 'Princess Ponies: A Friend in the Cloud Forest', 'Poniji princeze: Prijatelj iz oblačne šume', 'Хоре Райдер', 'Chloe Ryder', 'Kloi Rajder', 'Привет! Меня зовут Пиппа, и я люблю лошадей. Я просила маму купить мне пони, но оказалось, что это невозможно. Зато теперь я познакомилась с самыми настоящими волшебными пони и меня ждут удивительные приключения! Мрачный Облачный лес, населен неведомыми существами, и отправиться туда могут только по-настоящему храбрые пони. Но у нас со Звездочкой нет выбора, ведь именно там могут быть спрятаны недостающие подковы... Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пони-феи-холли-и-лес-единорого-1151'), 'Пони-феи. Холли и лес единорогов', 'Fairy Ponies: Holly and the Unicorn Forest', 'Vilinski poniji: Holi i šuma jednoroga', 'Занна Дэвидсон', 'Zanna Davidson', 'Zana Dejvidson', 'Холли мечтала увидеть единорогов, и наконец, ей выпал такой шанс. Только девочке предстоит не просто познакомиться с удивительными созданиями, но и спасти их от коварного пони Шедоу. В надежде завладеть троном, Шедоу решил воспользоваться магией единорогов. Если это произойдет, он станет самым могущественным пони и сможет управлять Островом... Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пони-феи-холли-и-принцесса-пон-1152'), 'Пони-феи. Холли и принцесса пони', 'Fairy Ponies: Holly and the Pony Princess', 'Vile poniji: Holi i princeza poni', 'Занна Дэвидсон', 'Zanna Davidson', 'Zana Dejvidson', 'Племянница Королевы, принцесса Розабель, похищена. Все пони Острова пустились на поиски. Холли и ее друг-пони не остались в стороне и чтобы спасти принцессу вступили в схватку с помощниками злодея Шедоу. Сможет ли магия и заклинания помочь друзьям? Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'щепотка-магии-1153'), 'Щепотка магии', 'A Pinch of Magic', 'Prstohvat magije', 'Мишель Харрисон', 'Michelle Harrison', 'Mišel Harison', 'Сестры Уиддершинс — Бетти, Флисс и Чарли — при помощи трех волшебных предметов пытаются снять зловещее семейное проклятие. Но помогут ли эти предметы найти ответы на загадки, или навлекут на сестер новую беду? Бетти Уиддершинс узнала о фамильном проклятии вечером своего тринадцатого дня рождения. Это число некоторые считали несчастливым, но Бетти была слишком здравомыслящей, чтобы верить в приметы. Ей нравилось думать, что она далека от суеверий и прочей подобной ерунды, — пускай даже они окружали ее с самого рождения. Это та самая история, которую хочется прочитать за ночь или прятать от учителя под партой. А после — поставить на видное место на полке, чтобы любоваться красивым изданием.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'горстка-волшебства-1154'), 'горстка волшебства', 'A Sprinkle of Sorcery', 'Prstohvat magije', 'Мишель Харрисон', 'Michelle Harrison', 'Mišel Harison', 'Когда в «Потайном кармане» объявляется незваная гостья, сестры Уиддершинс — Бетти, Флисс и Чарли — оказываются по уши втянуты в очередное приключение. В нем замешаны таинственная карта, проклятый корабль, потерпевший крушение, и старинная легенда, которая может оказаться вовсе не легендой… Приготовься покинуть Вороний Камень и отправиться вместе с сестрами в неизведанное, прихватив с собой лишь горстку волшебства. Только берегись пиратов!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'клубок-заклинаний-1155'), 'клубок заклинаний', 'A Tangle of Spells', 'Klupko čarolija', 'Мишель Харрисон', 'Michelle Harrison', 'Mišel Harison', 'Сестры Уиддершинс покидают туманный остров и поселяются в живописной деревушке Пендлвик. Но все здесь не так, как казалось вначале. Над деревушкой нависло что-то недоброе. Когда еще и Флисс начинает вести себя странно, Бетти и Чарли понимают, что им придется распутать целый клубок заклинаний... если еще не слишком поздно. Зачем читать эту книгу? Невероятно интересное продолжение приключений сестер Уиддершинс. Книга, полная магии и неожиданных поворотов сюжета. Кроме того, эта история о смелости, дружбе, взаимопомощи, верности выбору, о намерении изменить свою жизнь к лучшему. Книга, от которой невозможно оторваться до последней страницы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'п-с-по-имени-мани-1156'), 'пёс по имени Мани', 'A Dog Called Money', 'Pas po imenu Mani', 'Бодо Шефер', 'Bodo Schäfer', 'Bodo Šefer', 'Почему дети так быстро учатся и настолько легко схватывают новую информацию? Все очень просто: они делают это с удовольствием и не скованы ложными стереотипами. Пользуясь теми же правилами, вы сможете легко и просто отыскать свой путь к богатству. Трогательная история говорящего лабрадора Мани, который оказался настоящим финансовым гением, в доступной форме открывает перед детьми и взрослыми секреты денег. 3 причины читать эту книгу: 1. Мировой хит: тираж книги – более трёх миллионах экземпляров. От автора бестселлера №1 «Путь к финансовой свободе». 2. Главная книга по финансовой грамотности для детей расскажет о том, как инвестировать, экономить и зарабатывать. 3. Благодаря забавным историям и советам пса Мани вы поймёте, как изменить жизнь, чтобы прийти к мечте.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'банка-со-светлячками-1157'), 'Банка со светлячками', 'The Light Jar', 'Tegla sa svicima', 'Лиза Томпсон', 'Lisa Thompson', 'Liza Tompson', 'У Нейта очень много вопросов. Почему мама разбудила его ночью и увезла из дома? Для чего им нужно прятаться ото всех в заброшенном доме у леса? Что случилось с мамой, которая ушла за покупками и не вернулась даже утром? Неужели она бросила его одного и вернулась туда, откуда они сбежали? Кто эта странная девочка, которая вдруг появляется из леса и просит ей помочь? И как спрятаться от всего опасного в этом мире, когда у Нейта есть только банка со светлячками, чтобы рассеять окружающую темноту?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'арифметика-эмилии-орден-ж-лтог-1158'), 'Арифметика Эмилии. Орден жёлтого дятла', 'Emília''s Arithmetic: The Order of the Yellow Woodpecker', 'Emilijina aritmetika: Red žutog djetlića', 'Монтейру Лобату', 'Monteiro Lobato', 'Monteiro Lobato', 'Веселая компания из Домика Желтого дятла ни дня не может без приключений! Герои книг Монтейру Лобату – бразильская девочка Лусия по прозвищу Носишка, её кузен Педриньо и тряпичная кукла Эмилия – уже побывали в Стране Грамматики и не собирается на этом останавливаться. Новую затею предложил самый серьёзный из друзей – граф де Кукурузо, человек из кукурузного початка. Никто не ожидал, что он превратит занятия по арифметике в цирк в прямом смысле слова.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '100-вопросов-и-ответов-наука-1159'), '100 вопросов и ответов. Наука', '100 Questions and Answers: Science', '100 pitanja i odgovora: Nauka', 'Алекс Фрит, Мина Лейси', 'Alex Frith, Minna Lacey', 'Aleks Frit, Mina Lejsi', 'Знаете ли вы, что Земля движется по орбите быстрее пули? Что тело взрослого человека составляют около 7 октиллионов атомов? Или что небоскребы проектируют так, чтобы они гнулись на ветру? Эти невероятные факты и множество других собраны на страницах книги «Наука». Каждый разворот красочно оформлен и полон захватывающих данных о нашей планете, ее обитателях, космосе, технике и еще десятках тематик. Здесь можно узнать буквально обо всем на свете! Факты оформлены в короткие ёмкие тексты с инфографикой, чтобы ребенку было интереснее и удобнее взаимодействовать с книгой. Он узнает то, что не печатают в учебниках, и сможет без труда поразить одноклассников и друзей своей эрудицией.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-принцесса--1160'), 'Я-принцесса!', 'I Am a Princess!', 'Ja sam princeza!', 'Евгения Гюнтер', 'Evgenia Gunter', 'Jevgenija Ginter', 'Новая книга от «Пешком в историю» «Я принцесса!» расскажет, как жили принцессы сто, триста или даже три тысячи лет назад. О чем мечтали или чего боялись, как развлекались или скучали – чем занимались в свои обычные царские будни? С этой книгой можно запросто представить, каково это – быть принцессой, например, в Древней Индии, Египте, Персии, средневековой Франции, допетровской Руси, Австрийской империи и др. Двенадцать принцесс с разных концов света из разных эпох сами расскажут: легко ли вставать каждый день в шесть утра, выщипывать ресницы, ходить в чоппинах, носить по два парика сразу, выучить несколько языков и многое другое. Все имена принцесс вымышлены, а вот подробности их жизни показаны достоверно с учетом всех исторических фактов. Предпоследняя глава книги «Современные принцессы», повествует о нескольких настоящих принцессах, которые живут в современном мире. А в последней главе «Принцессы, не такие как все» показаны те (не вымышленные!) дочери правителей, которые смогли, несмотря на традиции и обычаи, пойти своим путем.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'петронелла-и-темная-история-с--1161'), 'Петронелла и темная история с цирком', 'Petronella and the Dark Circus Mystery', 'Petronela i mračna cirkuska tajna', 'Сабрина Штэндиг', 'Sabine Städing', 'Sabine Städing', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'красный-камень-1162'), 'Красный камень', 'The Red Stone', 'Crveni kamen', 'Лита Ли', 'Lita Lee', 'Lita Li', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'продавец-туманов-1163'), 'Продавец туманов', 'The Fog Seller', 'Prodavac magle', 'Резная свирель', 'Reznaya Svirel', 'Reznaja svirel', 'Эта книга как чашка горячего чая в промозглый день, как шерстяной плед для продрогшего городского мечтателя. Волшебные стихи-заклинания, философские притчи с теплыми и уютными акварельными иллюстрациями. Все самое необходимое холодной осенью и снежной зимой: чай с печеньками, простые истины, душевные книги, теплый плед, запах груш и мандаринов, дождь по стеклу, сказки и чудеса, тиканье часов в вечерней тишине, шепот далеких морей и корабли, плывущие над крышей.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чик-чак-1164'), 'Чик-чак', 'Chik-Chak', 'Čik-Čak', 'Елена Репетур', 'Elena Repetur', 'Jelena Repetur', '«Началось лето, и я больше не могу играть в бэтмена. Очень жарко. Под костюмом все потеет, и я через минуту его снимаю. Пришлось придумать своего героя. Теперь я Чик Чак — это на иврите «быстро». У меня только шорты и майка. Я быстро летаю и знаю разные языки, и у меня куча таких же супергеройских друзей. Злодеи тоже есть, но мы их каждый день побеждаем». Как перестать бояться и найти друзей, когда переезжаешь в новую страну? Особенно если кругом все говорят на чужом языке. Выход один — придется стать супергероем! Но для этого потребуется загадать желание, набраться терпения и, конечно, иногда смотреть мультики. Это история о больших подвигах маленького супергероя, который живет с мамой и папой в доме на горе и мечтает выучить все языки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'папа-мама-8-детей-в-дании-1165'), 'Папа, мама, 8 детей в Дании', 'Father, Mother, and Eight Children in Denmark', 'Tata, mama i osmoro djece u Danskoj', 'Анне- Кат. Вестли', 'Anne-Cath. Vestly', 'Anne-Kat. Vestli', 'Помните замечательную книжку "Папа, мама, бабушка, восемь детей и грузовик"? Ну так вот: теперь у вас в руках новый сборник увлекательных повестей о дружном и весёлом семействе, в котором ни минуты не бывает тихо. Норвежская писательница Анне-Катрине Вестли, придумавшая истории про дом, где растут сразу восемь мальчиков и девочек, популярна во всей Европе, наверное, не меньше, чем знаменитая Астрид Линдгрен. Герои её книг - люди простые, но очень симпатичные: добрые, честные, трудолюбивые. Взрослые здесь не теряют умения относиться с юмором к себе самим и друг к другу, какие бы уроки ни преподносила им жизнь. А главное, они удивительно хорошо понимают своих детей и сохраняют это понимание, что бы те ни натворили и что бы ещё ни напридумывали.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'серебряное-копытце-1166'), 'Серебряное копытце', 'Silver Hoof and Other Ural Tales', 'Srebrno kopito i druge bajke', 'П. П. Бажов', 'Pavel Bazhov', 'Pavel Bažov', 'Волшебные сказы Павла Бажова — это удивительные истории, в которых простые люди встречаются с могучими властителями поземных богатств. Великий Полоз, Медной горы Хозяйка, голубая змейка могут испытать человека, чтобы увидеть его душу. Недобрые люди будут наказаны, а чистые сердцем — вознаграждены.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'смешные-рассказы-о-школьниках-1167'), 'Смешные рассказы о школьниках', 'Funny Stories About Schoolchildren', 'Smiješne priče o školarcima', '', 'Various Authors', 'Grupa autora', 'В этой книге собраны веселые рассказы В. Голявкина, А. Раскина, В. Драгунского, И. Пивоваровой и Ю. Сотника о школе и школьниках. Герои этих рассказов на собственном примере доказывают, что школа — это не только учеба и оценки, но и настоящая дружба, взаимовыручка и, конечно, всевозможные забавные происшествия.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рассказы-люси-синицыной-учениц-1168'), 'Рассказы Люси Синицыной, ученицы 3 класса', 'Stories of Lucy Sinitsyna, Third Grader', 'Priče Ljusje Sinicine, učenice trećeg razreda', 'Ирина Пивоварова', 'Irina Pivovarova', 'Irina Pivovarova', 'В этой книге собраны смешные и трогательные истории из жизни третьеклассницы Люси Синицыной. Люся — жизнерадостная, озорная девчонка, которая любит петь, прыгать по лужам и делать «секретики». Ей ничего не стоит перевоспитать хулигана, устроить большую стирку или сочинить безумное послание для лучшей подруги прямо на уроке. В общем, с Люсей не соскучишься!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'поки-1169'), 'Поки', 'The Pokus', 'Poki', 'Эдгар Вальтер', 'Edgar Valter', 'Edgar Valter', '"Поки" - это сказка о забавных лесных человечках, одетых в кафтанчики из травы, испокон веков живущих в тенистом влажном подлеске. Гармоничные отношения с природой и её обитателями - таков лейтмотив этой доброй сказки. За вклад в национальную культуру Э. Вальтер награждён эстонским Орденом Белой Звезды третьей степени.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'большой-тылль-1170'), 'Большой тылль', 'Big Tõll', 'Veliki Tol', 'Андрус Кивиряхк', 'Andrus Kivirähk', 'Andrus Kivirehk', 'Жил когда-то давно на Сааремаа Большой Тылль — островной богатырь и властелин. Он и ростом был намного выше других, и силы у него было побольше. Природа Сааремаа была сурова, и люди, которые там жили, были суровые и сильные. Они спокойно трудились — пахали землю и ловили в море рыбу. У Тылля был злой и опасный враг — Нечистый. Он никогда не упускал случая навредить Тыллю.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'голубая-бусинка-1171'), 'Голубая бусинка', 'The Blue Bead', 'Plava perlica', 'Мария Людвика Крюгер', 'Maria Krüger', 'Marija Kriger', 'Семья восьмилетней Каролинки переезжает в новую квартиру. Пока взрослые собирают и выносят вещи, девочка случайно находит на полу, в щели, маленькую голубую бусинку. Да не простую, а волшебную – бусинка исполняет любые желания! Так и начинаются невероятные приключения Каролинки и ее верного друга Пётрека: они летают по воздуху, превращаются в невидимок, оживляют деревянную Бабу Ягу и каменных львов, воюют со злой колдуньей Филоменой... Но число желаний, которые может исполнить голубая бусинка, ограничено, и друзья учатся отличать пустяковые забавы от вещей важных и стоящих. “Голубая бусинка”- первая часть знаменитой дилогии Марии Крюгер (1904 – 1999).');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лу-чепуховый-дневник-1172'), 'Лу! чепуховый дневник', 'Lou! Secret Diary', 'Lu! Otkačeni dnevnik', 'Жюльен Нель', 'Julien Neel', 'Žilijen Nel', '"Лу! Чепуховый дневник" - первый том суперпопулярной во Франции серии рисованных историй про 12-тилетнюю девчушку Лу и ее маму. Книги про Лу издаются в разных странах мира уже 15 лет, 8 томов комикса вышли общим тиражом больше трех миллионов экземпляров! Эти истории стали и мультсериалом, и фильмом (с Людивин Санье, звездой французского кино, в роли мамы). И всё благодаря тому, что в героях комикса и дети, и подростки, и взрослые могут узнать себя!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'кот-нок-по-имени-гав-и-другие--1173'), 'Котёнок по имени Гав и другие сказки', 'A Kitten Named Woof and Other Stories', 'Mače po imenu Vau i druge bajke', 'Г. Остер', 'Grigory Oster', 'Grigorij Oster', 'В этой книге много маленьких зверушек. Самый удивительный среди них — котёнок по имени Гав. Наверное, тот, кто его так назвал, хотел посмеяться. А вместо этого наградил его уравновешенным, смелым характером. Пока взрослые кошки и собаки ссорятся и воруют еду друг у друга, щенок и котёнок вместе играют и обедают одной сосиской пополам. Именно это и называется дружбой. В книгу вошли другие сказки для малышей Григория Остера.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'привидение-из-монастыря-пирита-1174'), 'привидение из монастыря пирита', 'The Ghost of Pirita Convent', 'Duh iz manastira Pirita', 'Хелен Кяйт', 'Helen Käit', 'Helen Kejt', 'Книга известной эстонской детской писательницы понравится любителям страшных историй. Особенно она придётся по душе тем, кто хоть раз задумывался, здорово ли было бы встретить настоящее привидение. Ведь столкнуться с потусторонним явлением – это одновременно жутко и интересно! А ещё лучше, если привидение будет обитать в старом доме, в разрушенном замке или, как в этой книге, в подземелье монастыря.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'книжный-вор-1175'), 'Книжный вор', 'The Book Thief', 'Kradljivica knjiga', 'Маркус Зусак', 'Markus Zusak', 'Markus Zusak', 'Январь 1939 года. Германия. Страна, затаившая дыхание. Никогда еще у смерти не было столько работы. А будет еще больше. Мать везет девятилетнюю Лизель Мемингер и ее младшего брата к приемным родителям под Мюнхен, потому что их отца больше нет - его унесло дыханием чужого и странного слова "коммунист", и в глазах матери девочка видит страх перед такой же судьбой. В дороге смерть навещает мальчика и впервые замечает Лизель. Так девочка оказывается на Химмель-штрассе - Небесной улице. Кто бы ни придумал это название, у него имелось здоровое чувство юмора. Не то чтобы там была сущая преисподняя. Нет. Но и никак не рай. "Книжный вор" - недлинная история, в которой, среди прочего, говорится: об одной девочке; о разных словах; об аккордеонисте; о разных фанатичных немцах; о еврейском драчуне; и о множестве краж. Это книга о силе слов и способности книг вскармливать душу. Экранизирован в 2013 году.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мистика-моря-1176'), 'Мистика моря', 'Mysteries of the Sea', 'Misterije mora', 'Эдгар Аллан По', 'Edgar Allan Poe', 'Edgar Alan Po', 'Море, прекрасная, грозная, неукротимая стихия, и люди, которые все же рискуют бросить ей вызов - отчаянные, способные противостоять любой сверхъестественной силе, - очаровывали признанного мастера "мрачного" романтизма Эдгара Аллана По еще в детстве. Мальчиком писатель с упоением слушал байки и леденящие кровь предания моряков, которые заходили по делам к его приемному отцу, а позже, опираясь на собственные впечатления, создал пропитанные мистикой и мрачным юмором произведения, которые вошли в этот сборник.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вес-лый-новый-год-1177'), 'весёлый Новый год', 'A Merry New Year', 'Vesela Nova godina', 'Альф Прёйсен', 'Alf Prøysen', 'Alf Prejsen', 'Альф Прёйсен – норвежский писатель, поэт, композитор – написал великое множество песен, стихов и сказок для детей. Сказка в стихах «Весёлый Новый год» – это уютный сказочный мирок дружного семейства мышей, которые живут в норке на чердаке. Добрая и весёлая сказка легко читается и быстро запоминается. А еще она необыкновенно хорошо иллюстрирована гениальным художником Владимиром Сутеевым. Мышиное жилище и семейные отношения нарисованы с великой любовью к деталям: генеральная предпраздничная уборка, скакалки, бантики, мышки-игрушки на верёвочке, ссора из-за кусочка колбаски, развешанные после стирки штанишки, платьица и маечки многочисленной мышиной детворы, ночной горшочек из ореховой скорлупы, заботливые мыши-родители и мудрая мышь-бабушка, сидящая на качалке-картофелине, и много-много других милых подробностей мышиного быта. Рекомендуется для чтения взрослыми детям-дошкольникам, а также для совместного рассматривания картинок.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'малыши-чистят-зубы-1178'), 'Малыши чистят зубы', 'Toddlers Brush Their Teeth', 'Mališani peru zube', 'Елена Ульева', 'Elena Ulyeva', 'Elena Uljeva', 'Елена Ульева - знаменитый педагог, автор детских книг, изданных совокупным тиражом 3 миллиона экземпляров. Её эффективная методика легла в основу серии книг о развитии самостоятельности у малыша. Серия "Самостоятельный малыш" поможет вашему ребёнку сформировать необходимые навыки: поучительные сказки обеспечат необходимую мотивацию, а красочные иллюстрации создадут положительный настрой. Эта книга научит вашего малыша: - следить за своими зубками - не бояться осмотра у стоматолога - слушаться взрослых Взрослых книга научит договариваться с детьми играя.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'такие-разные-бабушки-1179'), 'Такие разные бабушки', 'Grandmas Are So Different', 'Tako različite bake', 'Маркелова Н.Е.', 'Natalia Markelova', 'Natalija Markelova', 'В детстве мы мечтаем стать врачами, моряками или космонавтами. А вот Леночка мечтает стать бабушкой, ведь её бабушка — настоящая добрая фея! Какие ещё бывают бабушки и что за волшебство они хранят у себя в карманах в книге Натальи Маркеловой «Такие разные бабушки». Тёплые и солнечные иллюстрации Марии Коротаевой.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'благородные-хулиганы-из-2-а--1180'), 'Благородные хулиганы из 2 "А"', 'The Noble Pranksters of Class 2-A', 'Plemeniti vragolani iz 2. "A"', 'Маркелова Н.Е.', 'Natalya Markelova', 'Natalija Markelova', 'Все знают, что бывают благородные разбойники. А существуют ли благородные хулиганы? Ответ на этот вопрос — в книге Натальи Маркеловой. Нас ждёт новая встреча с любимыми героями — Мишкой Курочкиным, Светой Иванкиной и другими замечательными ребятами. Они стали на год взрослее и теперь учатся во 2 классе, но по-прежнему верят в чудеса, приключения и крепкую дружбу.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'к-доске-пойд-т-василькин-школь-1181'), 'К доске пойдёт… Василькин! Школьные истории Димы Василькина, ученика 3 «А» класса', 'To the Board Goes... Vasilkin! School Stories of Dima Vasilkin, Third Grader', 'Pred tablu će... Vasiljkin! Školske priče Dime Vasiljkina, učenika 3. „A” razreda', 'Виктория Ледерман', 'Victoria Lederman', 'Viktorija Lederman', '«Дети должны быть умнее своих родителей», – повторяла мама. А у меня не получается быть умнее! Вот и тройка в четверти затесалась, по русскому. Портит колонку четвёрок и пятёрок! Несправедливо: я же хорошо пишу, однажды вот сочинил целую книжку про шуструю обезьянку. А потом ещё рассказ про то, как я потерял ранец. И про ужасный, противный день рождения Лизы Комаровой. И ещё, ещё… Ладно, обо всём по порядку! Меня зовут Дима Василькин, я учусь в третьем «А» и постоянно попадаю в смешные истории. Не все они, правда, сразу кажутся смешными – как, например, когда мы с Костиком застряли у него дома до самой ночи. Но всё равно я такие случаи люблю – рассказывать их потом одно удовольствие! А не люблю я только это: «К доске пойдёт… Василькин!» – слова, которые наша учительница Светлана Алексеевна говорит каждый день. Вот за что? Неужели мне без этого «к доске» мало приключений! Посудите сами!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ума-палата-детский-фразеологич-1182'), 'Ума палата. Детский фразеологический словарь', 'Sharp as a Tack: Children''s Idiom Dictionary', 'Bistra glava: Dječji frazeološki rječnik', 'Рогалева, Никитина', 'Elena Rogaleva, Tatiana Nikitina', 'Elena Rogaljeva, Tatjana Nikitina', 'Фразеологизмы (устойчивые сочетания слов) делают нашу речь богаче, а жизнь интереснее! Детский фразеологический словарь "Ума палата" поможет ребенку узнать смысловое значение каждого оборота, а также подскажет, в каком случае данный фразеологизм можно употреблять, а в каком совсем неуместно. После прочтения книги ребенок уже не будет смотреть на доску как баран на новые ворота и дрожать как осиновый лист на уроках русского языка и уж тем более никогда не станет нести околесицу. Фразеологический словарь "Ума палата" вышел в серии нон-фикшн для детей "Пифагоровы штаны". Это третье издание книги ИД Мещерякова, дизайн для которого полностью обновлен. В книге много увлекательных заданий на проверку усвоенного материала.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'асино-лето-1183'), 'Асино лето', 'Asya''s Summer', 'Asino ljeto', 'Тамара Михеева', 'Tamara Mikheeva', 'Tamara Mihejeva', 'Семейка ветров живёт на Летней эстраде. Королевский уж, исполняющий желания, обосновался под крыльцом первого корпуса. А сколько удивительных существ населяют соседний лес! Ася познакомилась с ними сразу: в тот день, когда команда Кольки Огурцова в пух и прах разнесла сборную Наташки Ястровой. Ася, она же Прасковья Шустова, футбол и прочие игры не любит: гномы Севка, Горыныч и Ёж - вот с кем ей по-настоящему интересно! В летнем лагере девочка впервые, и всё ей в новинку: кто тут негласный лидер и почему, как общаться с толпой незнакомых детей, какие тайны хранят старые чердаки. "Светлячок", где когда-то отдыхала ещё Асина бабушка, не скучает никогда: здесь ссорятся и мирятся, влюбляются и расстаются, ходят на дискотеки и рассказывают страшилки. Постепенно и сама героиня подпадает под обаяние места - не без помощи магических лесных существ. Их помощь понадобится ей ещё раз: Коле, с которым Ася так подружилась, срочно понадобится редчайшее лекарство… Повесть Тамары Михеевой за несколько переизданий превратилась в настоящую детскую классику.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вилли-1184'), 'Вилли', 'Willy', 'Vili', 'Нина Дашевская', 'Nina Dashevskaya', 'Nina Daševskaja', 'Детство — это такое время, когда в жизни каждого появляется что-нибудь волшебное. У кого-то — говорящий велосипед, у кого-то — заброшенная великанская деревня, у кого-то — подружка, очень-очень высокая девочка, которая печёт самое вкусное печенье. Вот и у Севки, главного героя повести Нины Дашевской «Вилли», всё это есть. Он, как и все дети, мечтает о настоящей дружбе, верит в чудеса, и они с ним обязательно случаются. То есть, конечно, случаются с ним не только чудеса, но Севка никогда не унывает. Он уверен: в итоге волшебство всегда берёт верх над любыми неурядицами! В повести «Вилли», на первый взгляд, много невероятного, но вообще-то всё как в жизни. Ведь это повесть о самом обычном мальчике, за которого переживаешь и радуешься, как за лучшего друга. Нина Дашевская — музыкант и писатель. Она играет на скрипке в оркестре Детского музыкального театра им. Н. И. Сац, а её книги успели стать любимыми во многих семьях. Нина Дашевская дважды становилась лауреатом Всероссийского конкурса на лучшее литературное произведение для детей и юношества «Книгуру» — за повесть «Скрипка неизвестного мастера» (2013) и сборник рассказов «Около музыки» (2014). В 2014 году повесть «Вилли» стала лауреатом премии В. Крапивина.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'якоб-учится-общаться-10-истори-1185'), 'Якоб учится общаться: 10 историй в 1 книге', 'Jakob Learns to Communicate: 10 Stories in 1 Book', 'Jakob uči da komunicira: 10 priča u jednoj knjizi', 'Сандра Гримм', 'Sandra Grimm', 'Sandra Grim', 'Подходит для совместного чтения с родителями детям от трех лет. В сборник вошли следующие истории: Якоб играет в футбол Якоб ссорится с Конни Якоб говорит нет Якоб учит правила дорожного движения Якоб хочет стать пожарным Якоб злится Якоб на ферме Якоб на детской площадке Якоб и беговел Якоб всё делает сам');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лев-колдунья-и-платяной-шкаф-1186'), 'Лев, колдунья и платяной шкаф', 'The Lion, the Witch and the Wardrobe', 'Lav, vještica i ormar', 'Клайв Стейплз Льюис', 'C. S. Lewis', 'K. S. Luis', 'Никто не знал, какую тайну хранит старый платяной шкаф, пока одной маленькой девочке не пришло в голову спрятаться среди шуб и зимних пальто. И тогда произошли удивительные события, открывшие миру чудесную страну — Нарнию. Что подают к чаю в гостях у фавнов? Как выглядит мир, в который никогда не приходит весна? Часто ли улыбаются великаны? Кто займёт четыре трона в главном дворце Кэр-Паравале? И сколько времени пройдёт на Земле, когда в Нарнии пролетит пятнадцать лет? Ответы на эти вопросы вы сможете не только прочитать в книге Клайва С. Льюиса «Лев, колдунья и платяной шкаф», но и увидеть, благодаря великолепным иллюстрациям современного британского художника Кристиана Бирмингема. Его работы не раз были отмечены престижными английскими премиями.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пеццетино-1187'), 'Пеццетино', 'Pezzettino', 'Pezzettino', 'Лео Лионни', 'Leo Lionni', 'Leo Lioni', 'Все вокруг Пеццетино совершают смелые поступки. Но он - простой маленький кусочек (pezzetino ведь так и переводится с итальянского - "кусочек"). Пеццетино решает, что он должен стать частью чего-то, принадлежать чему-то большему. Но ему удается совершить великое открытие: он принадлежит самому себе! Для дошкольного и младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'побеждаю-страхи-1188'), 'Побеждаю страхи', 'Conquering Fears', 'Pobjeđujem strahove', 'Елена Ульева', 'Elena Ulyeva', 'Jelena Uljeva', 'Через сказку про милого хамелеона ваш малыш узнает, как бороться с самыми распространенными страхами.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'подарок-1189'), 'Подарок', 'The Present', 'Poklon', 'Аня Доброчасова', 'Anya Dobrochasova', 'Anja Dobročasova', 'Близится 8 Марта. Вовка готовится поздравить сестру и маму, а вся семья готовится поздравить… Вовку! Только Вовка не сразу обрадовался своему празднику. Ему потребуется волшебный ключик, чтобы понять кое-что важное. Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'апельсин-1190'), 'Апельсин', 'The Orange', 'Narandža', 'Аня Доброчасова', 'Anya Dobrochasova', 'Anja Dobročasova', 'К Новому году! У Вовки было целых три Новых года, которые он прекрасно помнил. А сейчас, накануне четвёртого, праздничное настроение, приятная суета, красивая ёлка, подарки - всё было для Вовки под большим вопросом. Но чудеса иногда можно найти даже в старом шкафу с одеждой…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лунный-жук-1191'), 'Лунный жук', 'The Moon Beetle', 'Mjesečeva buba', 'Аня Доброчасова', 'Anya Dobrochasova', 'Anja Dobročasova', 'Оказавшись поздним вечером на пруду в валенках и шапке старшего брата, Соня, а точнее сказать - Хвостик, так её называла вся семья, с горькой обидой поняла, как плохо убегать из дома! Чтобы исправиться и не повторять ошибок, Хвостик с братом Вовкой решаются на крайнюю меру - идут в армию! Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'book-1192'), '', 'Shaggy Happiness', 'Čupava sreća', 'Лохматое счастье', 'Elena Stepanova', 'Elena Stepanova', 'Многие дети мечтают о самом настоящем лохматом счастье, которое умеет гавкать или мяукать, вилять хвостом, будить поутру и, конечно, шалить. О котёнке или щеночке! Специально для таких детей Елена Степанова и сочинила целую книжку, полную мурлыканья, гавканья, проказ и смешных историй. А нарисовала четвероногих героев и их друзей замечательная художница Любовь Ерёмина-Ношин. Для чтения взрослыми детям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'когда-я-завидую-1193'), 'Когда я завидую', 'When I Feel Jealous', 'Kad osjećam zavist', 'Корнелия Спилман', 'Cornelia Maude Spelman', 'Kornelija Spelman', 'Медвежонок рассказывает о ситуациях, которые заставляют его завидовать: когда кто-то получает то, чего он хотел, или когда другой привлекает к себе внимание окружающих. Но главный герой находит способы справиться со своими переживаниями. Ваш малыш может научиться этому, слушая книгу и рассматривая картинки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'когда-я-тревожусь-1194'), 'Когда я тревожусь', 'When I Feel Worried', 'Kad sam zabrinut', 'Корнелия Спилман', 'Cornelia Maude Spelman', 'Kornelija Mod Spilman', 'Дети часто волнуются, когда оказываются в новых или сложных ситуациях. Обычно они не знают как себя вести, когда кто-то на них сердится. Научите вашего малыша справляться с тревогой и быть уверенным в себе. Читайте книгу вместе и рассматривайте картинки. Для родителей даны рекомендации, что делать в трудном случае. Для детей младше 6 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'когда-я-грущу-1195'), 'Когда я грущу', 'When I Feel Sad', 'Kada sam tužan', 'Корнелия Спилман', 'Cornelia Spelman', 'Kornelija Spilman', 'Эта книга поможет вашим детям научиться сохранять уверенность в себе даже в сложных для них ситуациях. Морская свинка и ее друзья покажут, как справляться с трудностями, не теряя присутствия духа и уверенности в себе. Ваш малыш получит большое удовольствие, слушая книгу и рассматривая картинки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'книга-чудес-1196'), 'Книга чудес', 'A Wonder-Book for Girls and Boys', 'Knjiga čuda', 'Натаниэль Готорн', 'Nathaniel Hawthorne', 'Natanijel Hotorn', 'В поместье Тэнглвуд стоит детский смех - это студент Юстас Брайт рассказывает свои удивительные истории! Как раздобыть летающие сандалии и победить ужасную Горгону? Откроет ли таинственный ящик любопытная девчонка Пандора? Кто такой Атлант и почему небо не падает? В "Книге чудес для девочек и мальчиков" - шесть захватывающих историй от мастера американской литературы Натаниэля Готорна, который всегда полагал, что большинство античных мифов могут стать занимательным чтением для детей - нужно только правильно их пересказать. Для среднего школьного возраста. Книга издана вне серии. Лакированные элементы на обложке с эффектом песка; издание с ляссе (ленточкой-закладкой). Продолжением "Книги чудес" являются "Тэнглвудские истории" Н. Готорна.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'волшебный-короб-финские-народн-1197'), 'Волшебный короб. Финские народные сказки', 'The Magic Chest: Finnish Folk Tales', 'Čarobna kutija: Finske narodne bajke', '', 'Finnish Folk Tales', 'Finske narodne bajke', 'Сюжеты многих финских сказок связаны с мореплаванием, что логично для страны, имеющей давние морские пути. Другие истории повествуют о земледельцах, охотниках и рыболовах, третьи - о принцах и принцессах, четвёртые - о животных. Некоторые сюжеты читателю покажутся знакомыми, например, по карельским или западноевропейским сказкам. На это Унелма Конкка отвечала: "Чем больше мы читаем сказок разных стран, тем чаще убеждаемся в том, что большая часть их принадлежит народам всего мира. Но эта схожесть касается лишь сюжета сказки, её скелета. Каждый народ придаёт обще­известному сюжету своеобразную, неповторимую форму. В сказке отражаются история, психология, условия жизни и другие особенности данного народа". На русский язык сказки перевёл живущий в Финляндии писатель Арви Пертту. Проиллюстрировали сборник известные карельские художницы Тамара и Маргарита Юфа. Текст печатается по изданию: Волшебный короб: финские народные сказки. - Петрозаводск: Карелия, 1993. В книге использованы изображения произведений из фондов БУ "Музей изобразительных искусств Республики Карелия" Для младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'про-жика-и-медвежонка-1198'), 'Про ёжика и медвежонка', 'About Hedgehog and Bear Cub', 'O Ježiću i Medvjediću', 'Сергей Козлов', 'Sergei Kozlov', 'Sergej Kozlov', 'Замечательный сказочник Сергей Козлов - автор смешных и трогательных историй о Ёжике и Медвежонке. Эти неразлучные друзья давно перебрались со страниц книжек в кадры мультфильмов, которые знает и любит любой ребёнок: "Ёжик в тумане", "Трям! Здравствуйте!", "Зимняя сказка", "Осенние корабли". В этом сборнике вы найдёте лучшие сказки про Ёжика, Медвежонка и их друзей. Иллюстрации к этой книге нарисовал замечательный художник Евгенией Антоненков. Его Ёжик и Медвежонок такие трогательные и славные, что с ними захочется подружиться любому малышу. Евгенией Антоненков - участник различных международных выставок, обладатель диплома "Книга года" (2008). В 2009 и 2010 годах художник был номинирован на международную премию Астрид Линдгрен. Для дошкольного и младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-приручить-дракона-1199'), 'Как приручить дракона', 'How to Train Your Dragon', 'Kako dresirati zmaja', 'Крессида Коуэлл', 'Cressida Cowell', 'Kresida Kauel', 'Если вы вдруг не знаете, то в старину у каждого уважающего себя викинга был свой дракон. Другие народы использовали в качестве домашних животных собак, лошадей и прочую скотину. А викинги - драконов. Но для начала юный викинг должен был поймать своего дракона, что само по себе не просто. А потом - приручить его. Что еще сложнее. Все вместе называется - испытание драконьим воспитанием. Того, кто его не пройдет, изгоняют из племени. Когда Иккинг, сын вождя племени Лохматых Хулиганов и самый немускулистый юный викинг на острове Олух, отправился ловить своего дракона, он не надеялся, что пройти испытание будет легко. И не подозревал, что им с Беззубиком предстоит стать героями! Для детей среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'бабуля-бандюга-1200'), 'Бабуля-бандюга', 'Gangsta Granny', 'Baka gangster', 'Дэвид Уольямс', 'David Walliams', 'Dejvid Valijams', 'Проводить пятничный вечер у бабули – самое скучное занятие на свете! Так всегда думал Бен. Ему приходилось играть в старомодные настольные игры, есть капустный суп и слушать скучные бабушкины истории. Но однажды всё изменилось. А всё потому, что Бен узнал невероятный секрет! Оказывается, его бабуля вовсе не скучная старушка, а настоящая звезда криминального мира! За её плечами сотни ограблений! Она смелая, хитрая и клёвая! А ещё она мечтает ограбить саму королеву! Бен решает, что обязательно должен ей помочь. Получится ли у них осуществить этот дерзкий план? И какие ещё тайны скрывает бабуля? Дэвид Уолльямс – обладатель Британской национальной книжной премии, классик современной детской литературы, книги которого переведены более чем на 50 языков и продаются по всему миру многомиллионными тиражами. Истории Дэвида Уолльямса помогают преодолеть страхи и поверить в собственные силы. Тони Росс – всемирно известный иллюстратор, номинант на Премию им. Г.-Х. Андерсена. Для среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'научные-открытия-2020-1201'), 'Научные открытия 2020', 'Scientific Discoveries 2020', 'Naučna otkrića 2020', 'Илья Колмановский', 'Ilya Kolmanovsky', 'Ilja Kolmanovski', 'Каждую неделю Илья звонит учёным из разных стран и расспрашивает их, как им удалось сделать открытие, что было труднее всего и что — самое интересное. В этой книге — самые яркие и неожиданные научные истории 2020 года.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-вомбат-1202'), 'Я вомбат', 'I Am a Wombat', 'Ja sam vombat', 'Дмитрий Быков', 'Dmitry Bykov', 'Dmitrij Bikov', 'В далёкой Австралии обитает очень необычное животное по имени вомбат. Он немножко похож на медвежонка и совершенно не боится людей. Наша книжка поможет тебе познакомиться с этим удивительным зверем. Ты узнаешь, какие он строит себе норы, чем отличается сумка мамы-вомбата от сумки мамы-кенгуру, что общего у верблюда и вомбата… А ещё… Но, нет, не будем рассказывать. Лучше скорее открывай книжку!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'путеводитель-по-зв-здному-небу-1203'), 'Путеводитель по звёздному небу', 'A Cat''s Guide to the Night Sky', 'Vodič kroz zvjezdano nebo', 'Стюарт Аткинсон', 'Stuart Atkinson', 'Stjuart Atkinson', 'Если ты любишь смотреть на звёзды и мечтаешь узнать о планетах и космических объектах что-нибудь новенькое, эта книга как раз для тебя. Кот Счастливчик расскажет тебе всё, что знает сам: - что такое созвездие и астеризм, - чем осеннее небо отличается от летнего, весеннего или зимнего, - когда можно увидеть падающие звёзды, - почему Луна бывает молодой, прибывающей, убывающей и старой, - какие бывают затмения, - как отличить звезду от планеты, - что такое северное сияние, - какие существуют туманности, ...и ещё многое и многое другое! Готовься к приключениям и наблюдениям. Кот Счастливчик расскажет, в какую погоду и где можно делать наблюдения, чтобы увидеть многое, из того что он рассказывает, своими глазами.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чудеса-россии-1204'), 'Чудеса России', 'Wonders of Russia', 'Čuda Rusije', 'Аванта', 'Avanta', 'Avanta', 'В книге "Чудеса России" школьники познакомятся не только с удивительными местами нашей страны: горами, реками, равнинами, водопадами, озерами и пещерами, но и с прекрасными городами, доисторическими памятниками и культовыми зданиями, созданными людьми, живущими в разных уголках нашей большой родины.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'корабли-твоя-первая-энциклопед-1205'), 'Корабли. Твоя первая энциклопедия', 'Ships: Your First Encyclopedia', 'Brodovi: Tvoja prva enciklopedija', 'Симон Филипп', 'Philippe Simon', 'Filip Simon', 'Кто не мечтал хоть раз отправиться в море на яхте с белоснежными парусами или пересечь океан на огромном лайнере? По воде человек путешествует с древнейших времен: сначала на плотах и лодках, затем на парусниках и пароходах, а в наши дни моря и океаны бороздят огромные контейнеровозы, танкеры, пассажирские паромы, гоночные катера, яхты и еще много разных судов, о которых рассказано в нашей книге. Серия "Твоя первая энциклопедия"- лучший подарок для любознательного ребенка. Выбираете, что подарить школьнику, выпускнику детского сада или просто ищете универсальный подарок для мальчиков и девочек? Энциклопедия станет не только интересным, но и полезным приобретением. Она откроет ребенку мир знаний, расширит кругозор и пробудит интерес к учебе.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дикий-робот-1206'), 'Дикий робот', 'The Wild Robot', 'Divlji robot', 'Питер Браун', 'Peter Brown', 'Piter Braun', 'По книге-бестселлеру Крис Сандерс, режиссер мультфильмов «Лило и Стич» и «Как приручить дракона», снял красивый захватывающий анимационный фильм (2024). Удивительная сказка про одного робота по имени Роз, попавшего на необитаемый остров. История начинается с кораблекрушения. Попавшее в шторм судно идет на дно вместе со своим грузом — многочисленными коробками, в которых аккуратно упакованы сотни роботов. Постепенно обломки прибивает волнами к затерянному в бескрайних водах острову. Все коробки разбились о прибрежные скалы, но одна из них уцелела и оказалась на берегу. Ее нашли любопытные морские выдры. Изучая коробку и играя с ней, они распаковали содержимое и... Щелк! Робот ожил.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'спасение-дикого-робота-1207'), 'Спасение дикого робота', 'The Wild Robot Escapes', 'Bjekstvo divljeg robota', 'Питер Браун', 'Peter Brown', 'Piter Braun', 'Вторая книга про робота по имени Роз. По первой книге Крис Сандерс, режиссер мультфильмов «Лило и Стич» и «Как приручить дракона», снял потрясающий анимационный фильм (2024). Новые вызовы, новые приключения, новые цели. Но вся та же Роз — добрая, человечная, любящая своего гусенка-сына. Теперь перед ней лежит непростая задача: она научилась выживать на необитаемом острове среди диких животных, но что же ей делать в цивилизованном мире?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'миссия-дикого-робота-1208'), 'Миссия дикого робота', 'The Wild Robot Protects', 'Misija divljeg robota', 'Питер Браун', 'Peter Brown', 'Piter Braun', 'Новые приключения робота Роз, попавшего на необитаемый остров. В места, где живет Роз и ее семья, приходит беда: в океане появляется ядовитое течение, которое губит все живое. Все больше жителей вынуждены покинуть дом и искать безопасное укрытие. Лишь робот Роз не страшится течения. Она отправляется в долгое путешествие, где ей предстоит выяснить, кто отравляет воду, и остановить ядовитое течение, чего бы это ни стоило. Трогательная, человечная и добрая история о важности взаимовыручки, защите близких и о том, как люди, животные и даже роботы сообща могут творить чудеса и менять мир вокруг. Серия продана в мире тиражом 3,5+ млн экз. и переведена на 20+ языков. Осенью 2024 года в студии Dreamworks вышел мультфильм «Дикий робот» по мотивам первой книги серии');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дикий-робот-на-острове-иллюстр-1209'), 'Дикий робот на острове Иллюстрированная адаптация первой части трилогии о диком роботе', 'The Wild Robot on the Island (Illustrated Edition)', 'Divlji robot na ostrvu (Ilustrovana adaptacija)', '', 'Peter Brown', 'Piter Braun', 'Адаптация повести «Дикий робот» для всей семьи — с крупными буквами и цветными авторскими иллюстрациями! Роботам не место в дикой природе. Но после жуткого шторма один ящик с новеньким роботом оказывается на берегу незаселенного острова. Теперь Роз — именно так зовут робота — должна изучать поведение животных и приспосабливаться к жизни среди природы. Станет ли остров ей домом или все-таки диких роботов не бывает? Трогательная, человечная и добрая история о важности взаимовыручки, о защите своих близких, о том, как люди, животные и даже роботы сообща могут творить чудеса и менять мир вокруг.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'металллы-1210'), 'Металллы', 'Metals', 'Metali', 'Петр Волцит', 'Pyotr Voltsit', 'Pjotr Volcit', 'Можно ли обойтись в повседневной жизни без металлов? Представьте себе, что они внезапно исчезли - нет ни машин, ни поездов, ни станков, ни самого обычного ножа и отвёртки! И если металлы пропали бы совсем, то не стало бы и самой нашей планеты: на месте её железного ядра образовалась бы пустота. Исчезло бы и магнитное поле, которое создаёт ядро, и некому было бы защитить нас от космической радиации. Да и человек без металлов не прожил бы и секунды. Без кальция рассыпались бы в порошок зубы и кости, без железа кровь перестала бы разносить по телу кислород, а без магния растения перестали бы этот кислород выделять. Конечно, в небольшой книжке не расскажешь всё про металлы и их особенности. Но совершенно ясно: современному человеку не обойтись без знаний о металлах! Для младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вопросы-памяти-1211'), 'Вопросы памяти', 'Questions of Memory', 'Pitanja o pamćenju', '', 'Michèle Mira Pons', 'Mišel Mira Pon', 'Что такое память, какая она бывает и где находится? Можно ли безоговорочно доверять своим воспоминаниям? Забывать – так ли уж это плохо и что делать, если забывать не хочется? Этими вопросами задаются не только дети, но и взрослые. А сколько про память существует мифов и ложных представлений, рассеять которые в силах лишь специалисты в области функционирования мозга – нейрофизиологи и нейропсихологи! В своей книге французская писательница и журналистка Мишель Мира Пон, заручившись поддержкой опытных научных консультантов, рассказывает обо всём, что на сегодняшний день мы знаем о памяти. Нейронные тропинки в мозгу, польза сна, язык деревьев и удивительные способности каракатиц – о чём только не говорится в 16 главах, посвящённых разным аспектам памяти! Однако за простым и живым языком, за яркими иллюстрациями и забавными примерами стоят научные факты. Благодаря этому сложнейший феномен памяти становится понятен даже ребёнку, а познавательное чтение - весёлым и занимательным.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'планета-земля-мир-вокург-нас-в-1212'), 'Планета Земля: мир вокург нас в инфографике', 'Planet Earth: The World Around Us in Infographics', 'Planeta Zemlja: Svijet oko nas u infografikama', '', 'Unknown', 'Nepoznati autor', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-считаю-вс--1213'), 'Я считаю всё', 'I Count Everything', 'Brojim sve', '', 'Unknown', 'Nepoznati autor', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'встречаем-по-одежке-всемирная--1214'), 'Встречаем по одежке: всемирная история косюма для детей', 'Judged by the Cloth: A World History of Fashion for Kids', 'Sudeći po odjeći: Svjetska istorija kostima za djecu', '', 'Ekaterina Buntman', 'Jekaterina Buntman', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'истороия-ароматов-1215'), 'Истороия ароматов', 'The Story of Scents', 'Istorija mirisa', '', 'Dimitri Delmas', 'Dimitri Delmas', 'Представь себе букет любимых цветов. Какие они? Яркие тюльпаны? Бархатные розы? А может быть, нежные гвоздики? Когда-то все эти цветы прибыли к нам из далёких стран, очаровав своим ароматом и яркими лепестками путешественников, исследователей и миссионеров. Знаешь ли ты, что, прибыв в Голландию, тюльпаны свели с ума всю страну, развязали кошельки и устроили настоящую "лихорадку"? Кто такой "нос" и как он придумывает новые духи? Как добыть корень мандрагоры, который, по легенде, пронзительно кричит, оглушая всех вокруг, когда его выкапывают? Путешествуя с цветами, бросаешь якорь в неведомых портах, чтобы встретиться с иными мирами - то враждебными, то дружественными, познакомится с неведомыми народами, другими культурами, избавиться от предрассудков. Отправляйся в путь от Константинополя до Гоа, из холодных земель Лапландии к тропическим бразильским лесам вслед за путешественниками и первооткрывателями, которые находили новые виды цветов и растений, исследовали их лекарственные свойства и, конечно же, ароматы! Эта книга, написанная автором "Вкусной истории" Димитри Делма - взгляд на историю мира сквозь лепестки цветка, такой нежной и эфемерной его частички, с виду крошечной и незначительной.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'волшебная-пряжа-1216'), 'Волшебная пряжа', 'Extra Yarn', 'Čarobno predivo', '', 'Mac Barnett', 'Mek Barnet', 'Маленькая девочка Анабель из города, в котором существует только два цвета: цвет снега и цвет почерневших от сажи дымоходов открывает маленькую волшебную коробочку с разноцветной пряжей. Она вяжет себе свитер, а из остатков пряжи вяжет свитер для своей собаки. А из остатков вяжет еще один для соседа, еще свитера для всех своих одноклассников, для учителя, для мамы, для скворечника, для машин, для домов... Но пряжа все не кончается и не кончается! Город становится таким красочным, теплым и уютным, что на него желает посмотреть сам герцог. Но когда он приезжает, оказывается, он хочет еще и купить волшебную коробочку с пряжей. Он предлагает Анабель много денег, еще больше, но девочка не соглашается на сделку. Тогда он крадет коробочку. Но, вернувшись к себе домой, и устроившись в любимом кресле, герцог вдруг обнаруживает, что коробочка совершенно пуста! Получив по заслугам, жадный герцог выбрасывает ее в море, и она приплывает... обратно к Анабель, которая продолжает работу над вязанием свитера для дерева. Джон Классен, который работал над мультфильмами Кунг-фу Панда (2011) и Coraline (2009), использует черные чернила, гуашь и сканированную текстуру свитера цвета радуги, чем самым создает стильные линейные иллюстрации с яркими геометрическими акцентами.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'солнце-воздух-1217'), 'Солнце. Воздух', 'Sun. Air', 'Sunce. Vazduh', '', 'Unknown', 'Nepoznati autor', 'Смешная и остроумная книга-перевертыш для больших и маленьких читателей. С одной стороны — всё, что вы хотели знать о Солнце. А теперь переверните книгу — вас ждут удивительные тайны воздуха! Внутри издания — интересные факты об окружающем мире и увлекательные творческие задания: можно поиграть с тенями или воздушными потоками прямо на страницах. Вы узнаете, как ветер помогает мореплавателям и что означает шкала Бофорта, из чего состоит воздух и как человек ощущает себя в невесомости, каковы размеры Солнца и на каком расстоянии от Земли оно находится, какую роль играют атмосферные реки и что такое крылатые семена, как высоко могут летать самолеты, вертолеты, воздушные шары и искусственные спутники, что такое график Килинга, а также многое другое...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чистый-холст-1218'), 'Чистый холст', 'Blank Canvas', 'Čisto platno', 'Саша Балашова', 'Sasha Balashova', 'Saša Balašova', '«Чистый холст» — история о художнице, которая оказалась в творческом тупике. Она ищет выход, пробует разные способы, теряет надежду, но снова находит её совершенно неожиданным образом. Каждый из нас в какой-то мере художник и время от времени сбивается с пути. Эта книга для тех, кто когда-либо сталкивался с кризисом и терял интерес к любимому делу. «Чистый холст» обнимает всех, кто запутался и погряз в сомнениях, и даёт надежду справиться с трудностями.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'два-крыла-1219'), 'Два крыла', 'Two Wings', 'Dva krila', 'Кристина Беллемо', 'Cristina Bellemo', 'Kristina Belemo', 'Два крыла. Два прозрачно-белых крыла. Откуда они взялись под персиковым деревом?.. Книга-метафора о человеческой жизни от рождения до последнего полёта над любимым городом.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мышка-чарли-наводит-порядок-1220'), 'Мышка Чарли наводит порядок', 'Charlie the Mouse Tidies Up', 'Mišić Čarli zavodi red', 'Катерина Горелик', 'Katerina Gorelik', 'Katerina Gorelik', 'Мышка Чарли обожает чистоту и порядок! Поэтому она помогает с уборкой домиков своим соседям — обитателям Дикого и Волшебного лесов. Мрачные лабиринты кротовьей норы, своенравная избушка мадам Ведьмы, сахарные конюшни единорогов, логово мистера Дракона, ароматный имбирный домик — везде придётся навести порядок. Впереди у Чарли насыщенная рабочая неделя!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'триста-тысяч-узелков-1221'), 'Триста тысяч узелков', 'Three Hundred Thousand Knots', 'Tri stotine hiljada čvorova', 'Елена Голованова', 'Elena Golovanova', 'Elena Golovanova', 'Как я прочитал ковёр Представь себе мир, где на коврах сидят, едят, спят, читают их, как газеты, и даже передают с их помощью зашифрованные послания! Как любой современный ребёнок, Гриша никогда не думал о коврах... пока однажды не оказался в мире одного из них. Вместе с проводником, обаятельным псом по имени Джабир, Гриша отправится в невероятное путешествие. Ему предстоит познакомиться с искусством, придуманным тысячи лет назад, узнать, из чего и как ткут удивительные ковры, увидеть самый старый ковёр и даже разгадать один жизненно важный шифр.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'знаменитые-ограбления-1222'), 'Знаменитые ограбления', 'Famous Heists', 'Čuvene pljačke', 'Соледад Роберо Мариньо', 'Soledad Romero Mariño', 'Soledad Romero Mariño', 'Познакомьтесь с самыми изобретательными преступниками в мире! Захватывающая иллюстрированная хроника самых дерзких и изощрённых ограблений за последние 150 лет. Как злоумышленники планировали кражи? Какими способами они обходили системы безопасности? Как полиции удавалось выйти на их след? Каким образом грабители завладевали добычей и стоимостью в несколько миллионов и зачастую умудрялись с ней сбежать? Кем были эти криминальные умы, осмелившиеся присвоить себе известнейшие произведения искусства, драгоценности и огромные суммы денег? Откройте для себя неожиданные подробности знаменитых ограблений!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'нефть-1223'), 'Нефть', 'Oil', 'Nafta', 'Дмитрий Мажоров', 'Dmitry Mazhorov', 'Dmitrij Mažorov', 'Эта книга расскажет тебе, как добывают нефть из-под земли и из-под воды, проведёт по необычным городам — добывающей платформе и нефтеперерабатывающему заводу. Покажет, как устроены бензоколонка и автомобильный двигатель. Ты узнаешь, почему летают самолёт и ракета, чем питаются котельная и корабль и для чего на заводе по производству моторных масел нужны свинки. Поймёшь, какие опасности несёт добыча нефти для здоровья нашей планеты и как можно их избежать. Нефть называют чёрным золотом, потому что сегодня всё вокруг сделано из неё — от бензина в двигателе до жвачки и аспирина. Как такое может быть? Все ответы тут!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тело-мой-друг-и-враг-1224'), 'Тело: мой друг и враг', 'My Body: Friend and Foe', 'Tijelo: moj prijatelj i neprijatelj', '', 'Dominique Adèle-Cassuto', 'Dominik Adel-Kasuto', 'У всех есть представление, как должно выглядеть твоё тело. А лучший способ бороться с чужим мнением, страхами и стереотипами — это знать, как устроен организм и что нужно именно тебе. В этой книге ты узнаешь: для чего нужна норма и что такое нормальный вес? Что происходит в пубертате? Что такое расстройство пищевого поведения? Проблемы тела и как с ними справиться? Как работают социальные сети и как они влияют на наше поведение и настроение? 5 причин купить книгу «Тело: мой друг и враг»: Доминик Адель-Кассуто, практикующий эндокринолог и диетолог, её книга основана на многолетнем опыте, современных исследованиях и опыте настоящих подростков; Научный консультант Даша Саркисян, медицинский журналист, соосновательница телеграм-канала «Намочи манту», адаптировала и дополнила книгу под российский контекст; Как всегда – смешные и точные иллюстрации Влады Мяконькиной; Эта книга поможет прийти к принятию своего тела, каким бы оно ни было, через понимание, как устроен организм, пищеварение, и что вообще происходит в пубертатный период; Но эта книга не только про тело, но и про то, как устроена современная культура и социальные сети, которым чаще всего выгодно, чтобы мы всегда оставались недовольными собой.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'конец-все-не-так-просто-1225'), 'Конец?Все не так просто', 'The End? It''s Not That Simple', 'Kraj? Nije sve tako jednostavno', 'Ноэми Вола', 'Noemi Vola', 'Noemi Vola', 'Когда я был маленьким, я хотел быть мастером по ремонту концовок, то есть тем, кто исправляет финалы историй. Потому что, если вы заметили, они очень часто заканчиваются не на мажорной ноте, а просто ужасно! Финалы нередко оказываются слишком затянутыми, чересчур грустными, разочаровывающими, несправедливыми, непонятными, просто дурацкими. Так почему бы (при помощи воображения) не починить их?! Эта книга, победитель второй премии SERPA/Planeta Tangerina, — дань уважения (или пренебрежения?) всем плохим финалам. И она, уж будьте уверены, закончится самым лучшим образом!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'живая-книга-1226'), 'Живая книга', 'Press Here', 'Pritisni ovdje', 'Эрве Тюлле', 'Hervé Tullet', 'Erve Tule', '«Живая книга» давно приобрела толпы поклонников во всем мире, познакомьтесь с ней и вы. В ней нет персонажей и нет сюжета, зато на ее страницах своей собственной жизнью живут озорные разноцветные кружочки. Чтобы начали происходить чудеса, понадобится помощь вашего ребенка: наколдовать больше кружочков простым хлопком в ладоши или выключить свет на страницах, потрясти и высыпать шарики из книг, а может, сдуть темноту из книги? Выполняйте интерактивные задания, переворачивайте страницы, играйте и удивляйтесь! «Живая книга» невероятно воздействует на воображение детей и захватывает внимание сильнее любой электронной игрушки. Подуйте, потрясите, похлопайте в ладоши, открывайте на любой странице и начинайте снова — забавные кружочки развеселят любого! Многочасовое веселье и радостный детский смех обеспечены: проверено маленькими поклонниками творчества Эрве Тюлле по всему миру.');
