INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'пока-бьют-часы-1241'), 'Пока бьют часы', 'While the Clock Strikes', 'Dok sat kuca', 'Софья Прокофьева', 'Sofya Prokofyeva', 'Sofja Prokofjeva', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мой-дедушка-был-вишней-1242'), 'Мой дедушка был вишней', 'My Grandpa Was a Cherry Tree', 'Moj djed je bio trešnja', 'Анджела Нанетти', 'Angela Nanetti', 'Angela Naneti', 'Вишневое дерево по имени Феличе было посажено в честь рождения дочери и росло вместе с ней. И оно стало героем детских воспоминаний ее сына: его другом в играх, местом познания и приключений, символом непрерывности жизни. Главный герой этой книги ― дедушка, который со своей энергией, чувством свободы и способностью слышать дыхание дерева, кажется немного «странным». И так же легко, как дышит дерево, автор книги касается таких тем, как страдание и смерть близких, и искренне верит, что «человек не умирает, пока вишневые деревья продолжают жить для него». «Мой дедушка был вишней» вошла в список выдающихся книг для детей «Белые вороны», составляемый Международной мюнхенской юношеской библиотекой, была отмечена премиями в Италии, Германии и Франции, а автор ее, Анджела Нанетти, была номинирована на главную премию в детской литературе ― премию Андерсена.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'самые-лучшие-волшебные-сказки--1243'), 'Самые лучшие волшебные сказки. 1000 и 1 ночь', 'The Best Magic Fairy Tales: 1001 Nights', 'Najljepše čarobne bajke: 1001 noć', '', 'Arabian Folk Tales', 'Arapske narodne bajke', 'дракон и к, три кита');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'балетные-туфельки-1244'), 'Балетные туфельки', 'Ballet Shoes', 'Baletske cipelice', 'Ноэль Стритфилд', 'Noel Streatfeild', 'Noel Stritfild', 'Три девочки-сироты растут в доме ученого-палеонтолога в старом добром Лондоне. А сам профессор путешествует где-то много лет. У Паулины, Петровой и Пози разные характеры и таланты. Только возможностей у племянницы профессора, которая их воспитывает, немного, и три названых сестры, вне зависимости от желания, обучаются в Детской академии танца и сценического мастерства. Паулину влечет и манит сцена. Для маленькой Пози главное в жизни - танцевать. Единственное, что ей осталось от родной матери, - балетные туфельки. А Петрова (между прочим, это имя) мечтает только о... самолетах. Как сложатся их судьбы? - Какими разными вещами мы будем заниматься! - воскликнула Паулина. - В таких разных местах, - добавила Пози. - А я вот подумала, - Петрова закатила глаза к потолку, - если бы другие девочки оказались на нашем месте, которой из нас они предпочли бы быть? Для старшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'фрида-кало-1245'), 'Фрида Кало', 'Frida Kahlo', 'Frida Kalo', 'Анна Герасименко, Лилу Рами', 'Anna Gerasimenko, Lilu Rami', 'Ana Gerasimenko, Lilu Rami', '«Когда девочке было всего 6 лет, она тяжело заболела и после болезни стала хромать. „Фрида — деревянная нога!“ — дразнили ее ребята. Но она не слушала их. Она плавала, играла с мальчишками в футбол и даже занималась боксом. Фрида всегда была сильной и смелой девочкой.» Малыши узнают, как преодолевая любые невзгоды, можно осуществить свою мечту, а родители получат невероятное эстетическое удовольствие, перелистывая страницы книги «Фрида Кало. История про художницу, которая нарисовала себя и свою жизнь». Над изданием трудились постоянный автор издательства Clever Анна Герасименко, арт-директор Лилу Рами, а также иллюстратор Ирина Вовк. Благодаря их работе вы сможете с головой окунуться в мир Мексики, сказочных красок, любви и безграничного творчества!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'макс-и-горшок-1246'), 'Макс и горшок', 'Max''s Potty', 'Maks i noša', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', '"Макс и горшок" - двухлетний малыш Макс всегда знает, чего хочет. Он очень гордится своим новым горшком и непременно должен научить им пользоваться песика. "Серия про Макса" - популярнейшие в мире книги для первого чтения малышей, написанные языком и с чувством юмора, хорошо понятными детям. Для дошкольного возраста. 2-е издание.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'макс-и-подгузник-1247'), 'Макс и подгузник', 'Max''s Diaper', 'Maks i pelena', 'Барбру Линдгрен', 'Barbro Lindgren', 'Barbro Lindgren', 'Малышу Максу надоело носить подгузник. Он предлагает примерить его Песику. Оба довольны результатами, но мама почему-то совсем не довольна! Первую книгу про Макса писательница Барбру Линдгрен и художница Эва Эриксон из Швеции выпустили в 1981 году. Последнюю - в 1991-м. Всего в серии вышло 11 книг. И именно они принесли настоящий мировой успех своим авторам. В 2014 году в Швеции серия была переиздана в современном оформлении. Гениальными по простоте и чувству юмора книгами их назвали организаторы Мемориальной премии Астрид Линдгрен, которую получила Барбру Линдгрен в 2014 году. Сейчас их уже причисляют к классике книжек-картинок для первого чтения с ребенком, а в свое время именно лаконичность и "детскость" языка вызвала немало протестов со стороны педагогов. В книге "Макс и лампа" Линдгрен и Эриксон даже написали специальное предисловие и "перевели" текст на язык взрослых, позволив себе немного иронии в адрес взрослых педантов. Но в любой стране, где бы они не выходили, книги получали признание и любовь читателей - и больших, и маленьких.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'выходи-кто-где-живет-1248'), 'Выходи! кто где живет', 'Come Out! Who Lives Where?', 'Izađi! Ko gdje živi', 'Сюзанна Риха', 'Susanne Riha', 'Suzane Riha', 'Стать бы ветерком и провести весь год на природе: в лесу и в поле, на речке. Ветерок всех видит и слышит, а его никто не пугается. Можно увидеть, где живут, что едят звери и птицы. Чем занимаются весь год деревья и цветы. Какой месяц для какого растения главный. Как дерево наращивает кольца. Когда и где появляются малыши... Всё любопытно, всё интересно. Мы, конечно, не можем превратиться в ветерок, но зато можем прочитать и рассмотреть чудесную книжку Сюзанны Рихи и многое узнать.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'котофеи-1249'), 'Котофеи', 'The Cat Fairies', 'Kotofeji', 'Ольга Фадеева', 'Olga Fadeeva', 'Olga Fadejeva', 'Чудесам не обязательно дожидаться наступления Нового года! Вот и в семье Хвоста и Кокосика произошло исключительное событие: хозяева котов выиграли в конкурсе главный приз - новогодние каникулы в загородном доме отдыха. И пускай домосед Хвост не очень-то обрадовался предстоящей поездке, зато Кокосику не терпелось отправиться навстречу новым впечатлениям. Но каково же было удивление обоих, когда друзья попали… в обычную городскую гостиницу для кошек! Как же теперь отыскать хозяев, да ещё успеть встретить Новый год? Будьте уверены, у Хвоста и Кокосика всё получится - впереди КотоФеев ждёт настоящая лесная сказка!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'томасина-1250'), 'Томасина', 'Thomasina', 'Tomasina', 'Пол Гэллико', 'Paul Gallico', 'Pol Galiko', 'Одна из самых известных книг американского писателя Пола Гэллико о рыжеволосой девочке Мэри Руа, рыжей кошке Томасине и о чуде, жизненно необходимом и ребёнку, и взрослому. Трогательная и захватывающая история заставляет печалиться и радоваться вместе с героями, учит ценить любовь и милосердие. Иллюстрации Натальи Демидовой замечательно передают атмосферу книги - тишину шотландского городка, молчаливую суровость его взрослых обитателей, милую непосредственность героев-детей и неповторимое обаяние рыжей Томасины - лучшей на свете кошки, в которую просто невозможно не влюбиться. Для детей 10-12 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чудесный-ларец-1251'), 'Чудесный ларец', 'The Wondrous Casket', 'Čudesna škrinja', 'В.И. Даль, Пушкин', 'Vladimir Dal, Alexander Pushkin', 'Vladimir Dalj, Aleksandar Puškin', 'Книгу составили русские народные сказки, загадки и пословицы, собранные и обработанные известным русским писателем Владимиром Ивановичем Далем, и знаменитые поэтические сказки Александра Сергеевича Пушкина, Издание подготовлено для детей младшего возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'шедевр-1252'), 'Шедевр', 'Masterpiece', 'Remek-djelo', 'Элис Броуч', 'Elise Broach', 'Elis Brouč', 'Марвин - самый обыкновенный жук, его семья поселилась под кухонной мойкой в квартире Помпадеев в Нью-Йорке. Джеймс Помпадей - самый обыкновенный одиннадцатилетний мальчик, которому подарили на день рождения набор для рисования: чернила и перо. И Марвин сделал Джеймсу подарок - нарисовал изящнейшую миниатюру. А вся слава достала Джеймсу. Так, соверешенно неожиданно для самих себя друзья (разве может кто-то запретить одиннадцатилетнему мальчику дружить с жуком?!) оказались участниками и главными героями увлекательнейшего арт-детектива, в котором перемешалось все: подделка шедевра великого мастера, хитроумные планы грабителей и полные настоящих опасностей приключения. Удастся ли Джеймсу спасти Метрополитен от ограбления и вернуть утраченные рисунки Альбрехта Дюрера? Ясно лишь одно - без помощи Марвина ему не обойтись. Для детей от 12 лет.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рико-оскар-и-разбитое-сердце-1253'), 'Рико, Оскар и разбитое сердце', 'Rico, Oskar and the Broken Heart', 'Riko, Oskar i slomljeno srce', 'Андреас Штайнхефель', 'Andreas Steinhöfel', 'Andreas Štajnhofel', 'Рико и Оскар снова расследуют дело! И на этот раз в нем замешаны лотерея, сумка и...мама Рико! Расследование, конечно, открывает глаза мальчишкам и их помощникам не только на преступление, но и на картину отношений между людьми, дружбу, любовь, жестокость и самопожертвование. Как и первая книга о Рико и Оскаре, эта история написана от лица героя — и мы видим мир совершенно непривычно и остро, глазами мальчика с особым мышлением и восприятием мира. Ранее в «Самокате» вышла первая книга серии — «Рико, Оскар и тени темнее темного». Книги о Рико и Оскаре получили Немецкую детскую литературную премию, были экранизированы в Германии и уже стали современной классикой детского и подросткового чтения. Награды: Немецкая детская литературная премия, 2009 Список IBBY, 2010');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'москвест-1254'), 'Москвест', 'Moskvest', 'Moskvest', 'Жвалевский-Пастернак', 'Andrey Zhvalevsky, Evgenia Pasternak', 'Andrej Žvalevski, Jevgenija Pasternak', 'История - дама капризная. Стоило одному неосторожному подростку ругнуть ее у стен Кремля, и его вместе с собеседницей откинуло так далеко, что выбираться придется целую книгу. "Куда мы попали? Как нам отсюда выбраться? Как выжить?" - спрашивают герои книги. Очень хочется им помочь, ведь у нас под рукой интернет, а они мало что помнят даже из школьного курса! Да и школьный курс не всегда совпадает с тем, что происходит перед изумленным взглядом невольных путешественников во времени. Особенно когда приходится столкнуться с дружинниками Долгорукого, давать советы Калите, защищать Москву от Тохтамыша или работать толмачом у английского посла. А еще - это роман о любви... 6-е издание, исправленное.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'это-мои-эмоции-1255'), 'Это - мои эмоции', 'These Are My Emotions', 'Ovo su moje emocije', 'Наталья Ремиш', 'Natalia Remish', 'Natalija Remiš', 'Может ли ваш ребёнок понять, что он чувствует, и назвать эту эмоцию? Способен ли справиться с ней и помочь себе, находясь под её влиянием? Кажется, что всё просто. Здесь нервничает, здесь капризничает, здесь устал... Но это не эмоции как таковые, это уже следствие — различные реакции ребёнка на внутреннее эмоциональное состояние. Именно понимание его поможет ребёнку контролировать не только своё поведение, но и, что более важно, — уровень своего благополучия. Детей можно научить различать эмоции, рассказывать о них, конструктивно себя вести. В этой книге вы найдёте наглядные иллюстрации ситуаций и практические задания для детей, чтобы разобраться в четырёх эмоциях, — вина, ревность, зависть, страх.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'санька-и-море-1256'), 'Санька и море', 'Sanka and the Sea', 'Sanjka i more', 'Виктория Ледерман', 'Victoria Lederman', 'Viktorija Lederman', 'Сенька Шмелёв окончил первый класс и впервые в жизни едет с родителями на море. Он и представить себе не мог, насколько оно невероятное: огромное, шумное, солёное… В бескрайних водных просторах живут дельфины и прозрачные медузы, а берег усыпан блестящими гладкими камушками. Сколько секретов оно хранит! И если внимательно наблюдать, может быть, море согласится раскрыть хотя бы некоторые из них? Виктория Ледерман - классик современной детской литературы и лауреат множества премий, среди которых - "Книгуру", Корнейчуковская, Крапивинская, "Алиса", посвящённая памяти Кира Булычёва. От Калининграда до Владивостока мальчишки и девчонки с удовольствием читают книги Виктории Ледерман и узнают в персонажах себя и своих сверстников. Герой её новой повести Сенька Шмелёв - мечтательный, немного застенчивый, но верящий в чудеса. Не сомневаемся, что и вы захотите с ним подружиться! Для младшего и среднего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'большая-книга-музеев-1257'), 'Большая книга музеев', 'The Big Book of Museums', 'Velika knjiga muzeja', 'Ева Бенсар', 'Eva Bensard', 'Eva Bensar', 'Париж, Пекин, Санкт-Петербург, Рим, Амстердам, Мехико — отправьтесь в путешествие по 12 удивительным музеям. Экскурсию проведут лучшие из лучших: хранители музеев, архитекторы, реставраторы, художники... и другие, более неожиданные проводники! Шедевры мирового искусства, необычные профессии и советы к просмотру — музеи оживают на страницах этой книги.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'большое-книжное-приключение-за-1258'), 'Большое книжное приключение: за кулисами книгоиздания', 'The Great Book Adventure: Behind the Scenes of Publishing', 'Velika avantura knjige: iza kulisa izdavaštva', 'Стефани Верне, Камий де Кюссак', 'Stéphanie Vernet, Camille de Cussac', 'Stefani Verne, Kamij de Kisak', 'Кто выбирает тему, иллюстрации, формат и даже решает, какой будет цена книги? Прежде чем попасть к вам в руки, она проходит через все звенья длинной книжной цепочки — это настоящая командная работа! Познакомьтесь с автором, главным редактором, иллюстратором, полиграфистом, книготорговцем и библиотекарем и узнайте, чем они живут. От портретов к историям, от догадок к ответам. Готовы заглянуть за кулисы книгоиздания?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рабочие-лодки-1259'), 'Рабочие лодки', 'Working Boats: An Inside Look at Ten Amazing Vessels', 'Radni brodovi: Pogled iznutra na deset nevjerovatnih plovila', 'Том Крестодина', 'Tom Crestodina', 'Tom Krestodina', 'Взойди на борт и погрузись в удивительный мир промышленных судов. Хочешь узнать, как проводят на воде спасательные операции? Как живут исследователи на научных судах? Что нужно для ловли крабов в ледяных водах северной части Тихого океана? Эта книга покажет суда в разрезе, со всеми мельчайшими деталями и расскажет, как это — жить и работать на десяти удивительных лодках');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'карта-приятных-воспоминаний-1260'), 'Карта приятных воспоминаний', 'The Map of Good Memories', 'Mapa lijepih uspomena', 'Фран Нуньо, Зузанна Целей', 'Fran Nuño, Zuzanna Celej', 'Fran Nunjo, Zuzana Celej', 'Некоторые места неразрывно связаны с воспомина­ниями о счастливых моментах нашей жизни. Девочка Зоя, которая вместе с семьёй вынуждена покинуть родной город из-за войны, перед отъездом решает сохранить эти моменты в памяти. Она рисует «карту приятных воспоминаний» и отмечает на ней важные для себя места родного города. Теперь Зоя спокойна: эти воспоминания останутся с ней навсегда');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'очень-может-быть-20-правдивых--1261'), 'Очень может быть. 20 правдивых (и не очень) историй', 'Quite Possibly: 20 True (and Not-So-True) Stories', 'Vrlo moguće: 20 istinitih (i ne baš istinitih) priča', 'Камиль де Брейне, Ярне Дарен', 'Camille de Bruyne, Jarne Daeren', 'Camille de Bruyne, Jarne Daeren', 'Очень может быть, когда-то давным-давно жила-была книга с двадцатью историями, которые произошли на самом деле, а может быть и не происходили вовсе. Эта книга — игра. Можно начать с самого начала или открыть книгу на любой странице, прочитать историю и, прежде чем переворачивать страницу, нужно угадать, правдивая это история или чистой воды выдумки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'билли-и-гены-1262'), 'Билли и гены', 'Billy and the Genes', 'Bili i geni', 'Стефан Боонен, Мелвин', 'Stefan Boonen, Melvin', 'Stefan Bonen, Melvin', 'Эта книга расскажет тебе о мальчике Билли и о его генах. Гены — это крошечные частички твоего организма. Каждый ребёнок получает их от папы и мамы. Гены есть повсюду: у тебя в слюне, в волосах, в поте, в пальцах на ногах, во рту, внутри и снаружи. Повсюду! Голубые или карие у тебя глаза? Какой формы твои ладошки? Быстро ли ты бегаешь? Любишь ли ты шоколад? Да что ни возьми — всё это решают твои гены!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'год-вместе-1263'), 'Год вместе', 'A Year Together', 'Godina zajedno', 'Клэр Лебур', 'Claire Lebourg', 'Kler Lebur', 'Времена года сменяют друг друга, друзья, семьи и незнакомцы пересекаются, делятся мгновениями своей жизни. Мы несёмся из одного места в другое, уезжаем, встречаемся, разговариваем, работаем, едим и веселимся...все вместе! Книжка-картинка расскажет о жизни такой, какая она есть. Считается, что найти парочку, присутствующую на каждой странице, почти невозможно...почти.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'тайна-черной-скалы-1264'), 'Тайна черной скалы', 'The Secret of Black Rock', 'Tajna Crne stijene', 'Джо Тодд-Стентон', 'Joe Todd-Stanton', 'Džo Tod-Stenton', 'Эрин очарована океаном и легендой о Чёрной скале. О такой огромной, темной, загадочной и очень опасной. Говорят, она уничтожает все лодки, которые осмелятся приблизиться к ней. Так ли это на самом деле и сможет ли Эрин раскрыть тайну Чёрной скалы?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дикая-1265'), 'Дикая', 'Wild', 'Divlja', 'Эмили Хьюз', 'Emily Hughes', 'Emili Hjuz', 'В своей блестящей дебютной книжке-картинке гавайский автор и иллюстратор Эмили Хьюз рассказывает о девочке, которая живёт в дикой природе. Медведи научили её есть, вороны — говорить, а лисы — играть. Она безусловно, откровенно, счастливо и неудержимо дикая. Но всё изменилось после встречи с незнакомцами, очень похожими на неё… Эта изобретательная, причудливая история с выразительными, новаторскими иллюстрациями увлечет новое поколение читателей, как ничто другое.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'никудышный-гном-1266'), 'Никудышный гном', 'The Good-for-Nothing Gnome', 'Beskorisni patuljak', 'Брюно Ноб', 'Bruno Nob', 'Bruno Nob', 'Все гномы Деда Мороза трудолюбивые и послушные. Но даже среди таких молодцов всегда есть тот, кто будет выбиваться из толпы. Знакомьтесь — Никудышный гном, утомленный работой. Что же делать с таким негодяем?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'изюмка-и-гном-1267'), 'Изюмка и гном', 'Raisin and the Gnome', 'Izjumka i patuljak', 'Агнеш Балинт', 'Agnes Balint', 'Agneš Balint', 'Поучительные и добрые сказки о дружбе мудрого Гном Гномыча и маленького капризного поросёнка Изюмки. Вместе они живут в тыквенном домике, справляются с шалостями и учатся заботе и взаимовыручке.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хороший-динозавр-дорога-домой-1268'), 'Хороший динозавр дорога домой', 'The Good Dinosaur: The Road Home', 'Dobri dinosaurus: Put kući', '', 'Disney', 'Dizni', 'Яркая история по мотивам мультфильма Disney и Pixar о дружбе маленького динозавра Арло и храброго мальчика. Герои преодолевают опасности дикой природы и находят верный путь к родному дому.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сказки-про-эмоции-почему-я-злю-1269'), 'Сказки про эмоции. Почему я злюсь?', 'Tales About Emotions: Why Am I Angry?', 'Priče o osjećanjima: Zašto se ljutim?', 'Елена Ульева', 'Elena Ulyeva', 'Jelena Ulijeva', 'Терапевтические сказки для малышей, помогающие распознавать чувство злости и справляться с раздражением. В книге есть полезные вопросы для обсуждения эмоций вместе с родителями.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сказки-про-эмоции-почему-я-оби-1270'), 'Сказки про эмоции. Почему я обиделся?', 'Tales About Emotions: Why Am I Hurt?', 'Bajke o osjećanjima: Zašto sam se uvrijedio?', 'Елена Ульева', 'Elena Ulyeva', 'Elena Ulijeva', 'Короткие поучительные истории о том, почему возникает обида и как экологично ее выражать. Помогает ребенку развивать эмоциональный интеллект и учиться мириться с друзьями.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'викинг-таппи-большая-книга-при-1271'), 'Викинг Таппи Большая книга приключений', 'Viking Tappi: The Great Book of Adventures', 'Viking Tapi: Velika knjiga avantura', 'Марцин Мотка', 'Marcin Mortka', 'Marćin Mortka', 'Веселые сказочные истории о добродушном великане-викинге Таппи и его друзьях из волшебного Шепчущего Леса. Книга учит доброте, дружбе и находчивости.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'зимние-приключения-щенячий-пат-1272'), 'Зимние приключения Щенячий патруль', 'Winter Adventures: PAW Patrol', 'Zimske avanture: Patrolne šape', '', 'Unknown', 'Nepoznat autor', 'Увлекательные зимние истории о команде отважных щенков и мальчике Райдере. Друзья выручают попавших в снежную ловушку и разгадывают тайну снежного чудища.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'ледяное-королевство-1273'), 'Ледяное королевство', 'The Frozen Kingdom', 'Zaleđeno kraljevstvo', 'мультяшные истории', 'Cartoon Stories', 'Crtane priče', 'Волшебная сказочная история по мотивам любимого мультфильма о верности, храбрости и сестринской любви, способной растопить даже вечные льды.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'давай-делиться-дракоша-1274'), 'Давай делиться, дракоша', 'Let''s Share, Dragon', 'Hajde da dijelimo, zmajiću', 'Бьянка Шульц', 'Bianca Schulze', 'Bjanka Šulc', 'Забавная интерактивная сказка о маленькой Дракоше, которая очень не любит делиться своими вещами. Книга в игровой форме учит договариваться и дружить.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'скажи-правду-дракоша-1275'), 'Скажи правду, дракоша', 'Just Be Honest, Dragon!', 'Reci istinu, zmajiću', 'Бьянка Шульц', 'Bianca Schulze', 'Bjanka Šulc', 'Остроумная история-игра о том, как непросто признаться в своей ошибке. Книга помогает ребенку понять, почему важно говорить правду и не бояться этого.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'динозавры-у-бабушки-в-саду-1276'), 'Динозавры у бабушки в саду', 'Dinosaurs in Grandma''s Garden', 'Dinosaurusi u bakinoj bašti', 'Йорг Иле и Доминик Хохвальд', 'Jörg Ihle and Dominik Hochwald', 'Jerg Ile i Dominik Hohvald', 'Веселая иллюстрированная история о каникулах у бабушки и неуемной детской фантазии, превращающей дачный сад в настоящий мир динозавров.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'лотти-и-отто-история-для-мальч-1277'), 'Лотти и Отто. История для мальчишек и девчонок', 'Lotti and Otto: A Story for Boys and Girls', 'Loti i Oto: Priča za dječake i djevojčice', 'Колльен Ульмен-Фернандес', 'Collien Ulmen-Fernandes', 'Collien Ulmen-Fernandes', 'Добрая история о дружбе девочки Лотти и выдренка Отто. Книга учит ребят не бояться быть собой, следовать мечте и разрушать стереотипы.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'снеговик-1278'), 'Снеговик', 'The Snowman', 'Snješko Bijelić', 'Майкл Морпурго', 'Michael Morpurgo', 'Majkl Morpurgo', 'Однажды в конце декабря Джеймс проснулся и увидел, что выпал долгожданный снег. Он поспешил на улицу, чтобы слепить снеговика. Глаза-угольки, старая шляпа, зелёный шарф и мандариновый нос - снеговик получился замечательный! Джеймс так не хотел с ним расставаться, что вышел его навестить прямо посреди ночи. Невероятно, но снеговик ожил... Вот уже сорок лет "Снеговик" Рэймонда Бриггса остаётся одной из самых известных рождественских книг. Удивительная история, мастерски переосмысленная и рассказанная Майклом Морпурго, поможет новому поколению читателей проникнуться волшебством этой сказки. Для дошкольного и младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'рождественская-каша-1279'), 'Рождественская каша', 'The Christmas Porridge', 'Božićna kaša', 'Свен Нурдквист', 'Sven Nordqvist', 'Sven Nordkvist', 'На дворе сочельник. Пушистый белый снежок лежит на елях и крышах домов. А гномы ждут, когда хозяева дома преподнесут им тарелочку вкусной рождественской каши! Но тут случается непредвиденное… Книга всемирно известного шведского художника и писателя Свена Нурдквиста рассказывает о Рождестве в семействе гномов, где царят свои традиции. Перед праздником хозяева дома должны поднести им тарелку каши, а не то случатся несчастья. Но в этом году люди забыли древние обычаи, и гномам надо спасать положение. Забавные приключения семейки крошечных человечков и их несравненной мыши.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'гном-и-лис-1280'), 'Гном и лис', 'The Tomten and the Fox', 'Patuljak i lisac', 'Астрид Линдгрен', 'Astrid Lindgren', 'Astrid Lindgren', 'Зимняя ночь. Лис Микель подкрадывается к хутору, а в доме у рождественской елки играют дети. В сарае спят вкусные курочки. Но Лису до них не добраться — вот уже сто лет за хутором присматривает гном. Он объясняет Микелю: кур трогать нельзя. Но что тогда есть лису? Не беда: дети уже выставили для гнома рождественскую кашу, которой тот не прочь поделиться. Оказывается, это не хуже, чем курицы. Сытый лис спешит домой, а в небе восходит утренняя звезда.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '-лка-пряники-подарки-1281'), 'Ёлка, пряники, подарки', 'Christmas Tree, Gingerbread, and Gifts', 'Jelka, medenjaci i pokloni', 'Ульф Нильсон', 'Ulf Nilsson', 'Ulf Nilson', 'Уютные зимние истории о чудесах — больших и маленьких, которые в преддверии Нового года помогут создать волшебную атмосферу. Ульф Нильсон — современный шведский сказочник — собрал в этой книге четыре истории о пряничных человечках, проказниках-гномах, елках и волшебстве, а проиллюстрировали их лучшие художники. Это невероятно тёплые, уютные и чудесные сказки. Читайте их по одной в каждую неделю декабря.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'две-зимы-1282'), 'Две зимы', 'The Two Winters', 'Dvije zime', 'Йолан Бертран, Жион Тристан', 'Yolan Bertrand, Tristan Gion', 'Yolan Bertrand, Tristan Gion', 'Сказка-фэнтези о троллях, загадочной лисе, деревне викингов и смелом Альфреде, который бросит вызов самой Зиме! Приключения, волшебство, шутки, спасение и превращения. Жили в стародавние времена две сестры: старшая Зима — с лютыми холодами и метелями — и младшая Зимушка — с веселым катанием с гор и шумными ярмарками. Но после пропажи Зимушки в маленькой деревне викингов все пошло вверх дном. Злится старшая сестра, насылает морозы, а тролли крадут дрова и утварь. И только десятилетний сирота Альфред знает: надо найти Зимушку и тогда кончатся беды. Он отправляется в темный ледяной лес, где встретится с настоящим волшебством... Зимняя сказка с колоритом скандинавского фольклора. О смелости и чувстве юмора, которое помогает даже в самое холодное время года.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'йети-камера-мотор--1283'), 'Йети, камера, мотор!', 'Yeti, Camera, Action!', 'Jeti, kamera, akcija!', 'Валентина Дёгтева, Алиса Юфа', 'Valentina Degteva, Alisa Yufa', 'Valentina Djohtjeva, Alisa Jufa', 'Под Новый год всем хочется сказки. Волшебной, неожиданной, увлекательной, с любимыми героями и красивыми иллюстрациями. Новая книга об очаровательном Йети именно такая — смешная, способная удивить и растрогать, а еще приправленная трюками и спецэффектами. Йети предстоит стать настоящей кинозвездой. Режиссёр картины — блистательный Петардо Конфетти, а в центре событий — похищение красавицы Снегурочки. Камера, мотор, начали: «свирепое чудище» вот-вот сцапает бедняжку... Но как быть, если под мохнатой шкурой снежного человека скрывается чуткое сердце? Йети больше всего на свете любит строить ледяные крепости для малышей, а ещё, конечно, поесть и поспать. Такой артист вот-вот провалит весь фильм. Что же будет? Занимайте места в зрительном зале, пока их не заняли пингвины.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'элвис-и-человек-в-красном-паль-1284'), 'Элвис и человек в красном пальто', 'Elvis and the Man in the Red Coat', 'Elvis i čovjek u crvenom kaputu', 'Оле Кёнеке', 'Ole Könnecke', 'Ole Kenecke', 'В канун Нового года в доме автомеханика Элвиса неожиданно погас свет, и вскоре раздался стук в дверь. На пороге стоял печальный человек в красном пальто, который умолял о помощи: дело в том, что его сани, запряжённые оленями, налетели на столб с электрическими проводами и сломались, поэтому теперь он не успевал попасть на работу. Элвис никак не мог взять в толк, зачем этому странному человеку, разъезжающему на оленьей упряжке, вместо автомобиля, вдруг срочно понадобилось на работу под вечер 31 декабря, когда все сидят по домам и отдыхают. Вместе со своими друзьями Элвис помогает человеку в красном пальто, и тот в конце концов благополучно уезжает на свою загадочную ночную работу. Правда, никто так и не понял, кем же он был. Трогательная и остроумная новогодняя сказка для детей, а также для взрослых, которые тоже когда-то были детьми, но забыли об этом. Оле Кёнекке - известный немецкий иллюстратор и автор. Его альбомы и комиксы публикуются во всем мире и удостаиваются серьезных наград.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'снег-1285'), 'Снег', 'Snow', 'Snijeg', '', 'Walter de la Mare', 'Volter de la Mer', 'Классическое рождественское стихотворение Уолтера Дэ Ла Мэра впервые было опубликовано в 1924 году. А на этот раз оно очень гармонично сочетается со стильными, современными иллюстрациями Каролины Рабей. В книге прекрасно передана уютная атмосфера холодного, зимнего дня, добрые отношения между членами семьи и уютное ощущение предвкушения праздника. К тому же иллюстрированные стихи являются отличным способом, чтобы познакомить маленьких читателей с настоящей поэзией. Для детей младшего школьного возраста.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чик-и-брики-снеговик-1286'), 'Чик и Брики. Снеговик', 'Pip and Posy: The Snowy Day', 'Pip i Pozi: Snješko', '', 'Axel Scheffler', 'Aksel Šefler', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'чик-и-брики-наряжают-лку-1287'), 'Чик и Брики наряжают ёлку', 'Pip and Posy: The Christmas Tree', 'Pip i Pozi kite jelku', '', 'Axel Scheffler', 'Axel Scheffler', '');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'андрей-сахаров-человек-который-1288'), 'Андрей Сахаров человек, который не боялся', 'Andrei Sakharov: The Man Who Was Not Afraid', 'Andrej Saharov: Čovjek koji se nije bojao', 'Ксения Новохатько', 'Ksenia Novokhatko', 'Ksenija Novahatko', 'Кто наш герой сегодня? В чём его суперсила? В детстве Андрей был застенчивым - не мог заговорить даже с соседом по парте. Но спустя много лет именно его тихий голос зазвучал громче, чем взрывы самых разрушительных бомб, мнения самых важных политиков. Андрею Сахарову, как и всем нам, приходилось выбирать: думать самому или верить на слово, сказать или промолчать, вмешаться или остаться в стороне. Его жизнь была похожа на научный эксперимент, который часто приводил к неожиданным результатам. Совершая ошибки, сталкиваясь с неудачами и предательством, Сахаров всегда выбирал действие: ставил под сомнение то, что считалось неоспоримым, говорил на равных с главами государств, бросал вызов бесправию, несправедливости и авторитетам. Гениальный физик, "отец" советской водородной бомбы и правозащитник, лауреат Нобелевской премии мира, Сахаров был человеком, который не боялся - думать, высказываться, защищать.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'вы-жившие-большой-террор-1289'), 'Вы-жившие. Большой террор', 'The Survivors: The Great Terror', 'Preživjeli: Veliki teror', '', 'Gulag History Museum', 'Muzej istorije Gulaga', 'Более чем за двадцать лет существования ГУЛАГа через тюрьмы и лагеря прошли около 20 миллионов человек. Каждый десятый остался в ГУЛАГе навечно. Со временем слово "ГУЛАГ", первоначально обозначавшее "Главное управление лагерей", стало зловещим символом беззакония, жизни на грани смерти, каторжного труда и человеческого бесправия. Книга "Вы-жившие. Большой террор" - продолжение новой постоянной экспозиции Музея истории ГУЛАГа. Внутри - шесть графических историй, рассказывающих о судьбах людей, пострадавших от сталинских репрессий. Они занимали разное социальное положение, имели разные профессии, придерживались разных политических взглядов, жили в разных уголках страны. Но оказались в одинаково бесправном положении. Каждого из них несправедливо осудили, отправили в лагеря или расстреляли.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = '25-августа-1290'), '25 августа', 'August 25th', '25. avgust', 'Александра Кувшинова', 'Aleksandra Kuvshinova', 'Aleksandra Kuvšinova', 'В 1968 году во всем мире происходили важные события: повсюду люди боролись за свободу. Студенты выходили на демонстрации, правительства обсуждали права человека, музыканты писали песни о свободе и братстве. Что происходило тогда в Москве, на Красной площади? О чем думали люди, чего боялись и за что боролись? Как поступки отдельных людей могли повлиять на отношения между государствами? Что такое "мирная демонстрация" и почему за нее можно было попасть в тюрьму?');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'бежать-нельзя-остаться-1291'), 'Бежать нельзя остаться', 'Run or Stay', 'Pobjeći ili ostati', 'Алексей Олейников', 'Alexei Oleynikov', 'Aleksej Olejnikov', 'Семь историй об учениках обычной российской школы - выходцев из Йемена, Афганистана, Южного Судана, ЦАР, Палестины, Сирии и ДРК - основаны на реальных событиях и рассказывают, какие сложности вынуждены преодолевать дети-беженцы и их семьи. Языковой барьер и культурные различия, отсутствие правового статуса и поддержки со стороны государства, бедность, социальная изоляция и буллинг - лишь часть проблем, с которыми сталкиваются вынужденные мигранты. Графические истории, собранные писателем Алексеем Олейниковым и выполненные студентами Высшей школы экономики, дополнены мировой статистикой и краткими справками о странах исхода и причинах вынужденной миграции. В книге также есть памятка о том, как помочь оказавшимся в подобной ситуации людям.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'скажи-мне-здравствуй--1292'), 'Скажи мне "Здравствуй!"', 'Say Hello to Me!', 'Reci mi zdravo!', 'Алексей Олейников', 'Alexey Oleynikov', 'Aleksej Olejnikov', 'Россия — страна многонациональная. Здесь люди разных национальностей веками жили рядом друг с другом и находили общий язык. Сегодня те, кого мы еще недавно называли «жители братских республик», вдруг стали непонятными «мигрантами». Мы подумали, если объяснить, кто такие в действительности мигранты, почему они были вынуждены уехать из родных мест, если рассказать детям их истории и приокрыть дверь в их культуру, если честно признаться в том, что наши предки (за редким исключением) тоже когда-то были мигрантами, вокруг станет меньше страха и больше тепла.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'наш-мир-и-наши-права-1293'), 'Наш мир и наши права', 'Our World and Our Rights', 'Naš svijet i naša prava', '', 'Unknown', 'Nepoznat autor', 'Учебно-методическое пособие "Наш мир и наши права. Что нужно знать о правах человека школьникам младших и средних классов" включает 30 пошаговых планов уроков, посвященных обсуждению Декларации прав человека, истории, литературных произведений, а также материалы для копирования, советы по проведению уроков и списки дополнительных источников. Оно поможет учителям рассказать детям 6-13 лет о правах человека и о том, как применять полученные знания в жизни. Учебник поможет: - рассказать о Всеобщей декларации прав человека и Конвенции о правах ребенка, их значении и ценностях; - выработать техники работы по правозащитной тематике; - включить правозащитный аспект в обсуждение тем об окружающем мире, о взрослении, нравственности, гражданской позиции, образовании, родной речи.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'выборы-зверей-1294'), 'Выборы зверей', 'The Animals'' Election', 'Izbori životinja', '', 'André Rodrigues, Larissa Ribeiro, Paula Desgualdo, Pedro Markun', 'Andre Rodrigez, Larisa Ribeiro, Paula Desgvaldo, Pedro Markun', 'Жители леса уже устали от царских капризов Льва. Вы только посмотрите: он отвел всю воду из реки, чтобы устроить у своего логова бассейн! Оставил всех без воды! И тогда возникает идея: лесу нужен новый правитель - значит, надо провести выборы! Сказано - сделано. Кандидатами на пост президента леса становятся Макака, Ленивец, Кобра и, конечно, Лев. А как проходят выборы? Каковы правила? Как определяется победитель? Ты узнаешь обо всём этом вместе с лесными зверями и сам сможешь выбрать полюбившегося кандидата. Только тс-с-с... голосование тайное!');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'книга-о-правах-человека-1295'), 'Книга о правах человека', 'The Book of Human Rights', 'Knjiga o ljudskim pravima', '', 'Jacqueline Duhême, Robert Badinter', 'Žaklin Duem, Rober Badenter', 'Как рассказать детям - деятелям и гражданам будущего - о правах человека? Текст принятой в 1948 году "Декларации прав человека" слишком абстрактен, комментарии непонятны, учебники скучны. Чтобы выйти из этой ситуации, художница Жаклин Дюэм и правозащитник Робер Бадентер объединились и создали "Книгу о правах человека". Благодаря таланту Жаклин, оригинальный текст Декларации наполнился цветом и ожил. В ней абстракция наполнилась поэзией, в каждой статье поселились замечательные герои, необычные животные и фантастические цветы. Сухие слова превратились в сказку. Сказку, которая должна стать понятной и близкой реальностью для сегодняшних детей - завтрашних мужчин и женщин.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'мы-все-рождены-свободными-1296'), 'Мы все рождены свободными', 'We Are All Born Free', 'Svi smo rođeni slobodni', '', 'Amnesty International', 'Amnesti internašonal', 'Все люди на планете должны быть защищены Всеобщей декларацией прав человека. Где бы мы ни жили, кем бы ни были - это наши права, и никто не может у нас их отнять. Веря в эти правила, действуя в соответствии с ними, обещая никогда не нарушать их, мы делаем мир лучше. Мы сами становимся лучше. Если подумать, это не так уж сложно, правда? "Мы все рождены свободными" - это уникальная книжка-картинка: специально для маленьких Граждан Мира текст Декларации сделан более доступным для понимания, все 30 статей проиллюстрированы известными детскими художниками, а обложка оформлена Петром Сисом.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-имею-право-быть-ребенком-1297'), 'Я имею право быть ребенком', 'I Have the Right to Be a Child', 'Imam pravo da budem dijete', 'Ален Серр', 'Alain Serres', 'Alain Serres', 'Права ребенка - это не просто громкие слова на бумаге. Права ребенка важны везде: дома и в школе, во дворе и в больнице, на экране телевизора, компьютера и телефона, в книге и игре. Они должны соблюдаться всеми - ведь дети не всегда могут сами себя защитить, - чтобы из счастливых и защищенных детей выросли умные, добрые и сильные взрослые. Французский педагог, писатель и издатель Алан Серр рассказывает о правах ребёнка простым, но ярким, как иллюстрации к этой книге, языком, с ритмом и рифмами. А помогает ему на русском языке замечательный переводчик Михаил Яснов.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'стена-1298'), 'Стена', 'The Wall: Growing Up Behind the Iron Curtain', 'Zid: Kako sam odrastao iza gvozdene zavjese', 'Петр Сис', 'Peter Sís', 'Peter Sis', 'Автобиографическая книга "Стена: как я рос за железным занавесом" - история детства и взросления художника, в судьбу которого постоянно вмешивалась политика. Это история мальчика, который рос совсем недавно, но совершенно в другую эпоху: во время Холодной войны. История мальчика, который родился и вырос за железным занавесом. Всю свою жизнь он хотел рисовать и мечтал о времени, когда рухнут стены недоверия и лжи, разделяющие людей. Иногда мечты сбываются. 9 ноября 1989 года рухнула Берлинская стена, и это событие ознаменовало окончание Холодной войны.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'диктатор-1299'), 'Диктатор', 'The Dictator', 'Diktator', 'Ульф Старк', 'Ulf Stark', 'Ulf Stark', 'Диктатор ложится спать и приказывает звездам светить, диктатор просыпается и приказывает манной каше сию секунду остыть. Все это у него очень хорошо получается, он самый лучший в мире тиран. И, кажется, все вокруг уже и забыли, что он просто-напросто ребенок. Но если диктатор очень маленький, ему в конце концов может стать очень одиноко. Потому что нельзя приказать кому-то быть твоим другом. "Диктатор" классика шведской детской литературы Ульфа Старка и талантливого финского иллюстратора Линды Бондестам - пожалуй, первая антиутопия для самых маленьких. Это смешная и нежная история о том, как важно не забывать, что на свете есть любовь.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'генерал-1300'), 'Генерал', 'The General', 'General', 'Майкл Форман', 'Michael Foreman', 'Majkl Forman', 'Один генерал хотел быть самым знаменитым генералом на свете. Но однажды он упал с лошади на прекрасной поляне и, увидев красоту цветов, разлюбил войну и научился ценить природу. Эта книга была написана и нарисована в 1961 году. Её авторы выросли в военном Лондоне под постоянными бомбёжками и никогда не знали мира без войны. Поэтому они придумали книгу, которая прославляла бы природу, а не разрушение. Сегодня в Англии "Генерал" отмечает юбилей. Нарисовавший её Майкл Форман стал одним из самых знаменитых английских художников. Он проиллюстрировал более 140 книг. Получил множество престижных наград. Но "Генерал" остаётся одной из главных его книг и через полстолетия не теряет актуальности. Он всё так же напоминает нам: чтобы сохранить наш удивительный мир, надо беречь каждую травинку и ценить каждую букашечку.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'коричневое-утро-1301'), 'Коричневое утро', 'Brown Morning', 'Smeđe jutro', 'Франк Павлофф', 'Franck Pavloff', 'Frank Pavlof', '"Коричневое утро" - это новелла, написанная Франком Павлоффом в декабре 1998 года. Сюжет, как и сам стиль повествования "Коричневого утра", очень прост: два самых обычных приятеля, наблюдая, как формируется государство Коричневых, отказываются беспокоиться и что-то предпринимать. Незаметно для героев, в результате принятых мер и новых законов, всё изменяет цвет: кошки, собаки, газеты, радио... Нет причин для беспокойства - достаточно только соблюдать новые правила. Феномен антифашистской новеллы "Коричневое утро" Франка Павлоффа действительно впечатляет: книжечка в 12 страниц и стоимостью в 1 евро - вот уже больше 10 лет в списке бестселлеров во Франции, выдержала больше 40 переизданий, а общий тираж превышает 1 500 000 экземпляров.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'дневник-блюмки-1302'), 'Дневник Блюмки', 'Blumka''s Diary', 'Blumkin dnevnik', 'Ивонна Хмелевская', 'Iwona Chmielewska', 'Ivona Hmjelevska', 'Варшава — Улица Крохмальная, 92 — Дом сирот. Когда-то тут жила Блюмка, доктор Корчак, пани Стефа и двести детей, в том числе: Зигмусь, который подарил жизнь серебряной рыбе, Регинка, чьи рассказы могли озарить самую тёмную ночь, Поля, которая вырастила у себя в ухе горошек, Хаимек, которого муравьи довели до суда, Чижик, который так усердно помогал, нося уголь в эмалированном горшке, и мышка, крошки для которой падали прямо с неба. Блюмка записывала все это у себя в дневнике, а когда ей не хватало слов — добавляла рисунки. До того дня, когда началась война… Ивона Хмелевская — всемирно известная польская художница и писательница. Живет и работает в Торуни, где также преподает на факультете изящных искусств Университета Николая Коперника.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'когда-я-вернусь-1303'), 'Когда я вернусь', 'When I Return', 'Kad se vratim', 'Йессика Баб Бунде', 'Jessica Bab Bonde', 'Džesika Bab Bonde', 'Тобиас, Ливия, Сельма, Сусанна, Эмерих и Элисабет. Их жизнь началась так же, как твоя и моя. Они родились в мирных городах, у них была крепкая семья и верные друзья. Была крыша над головой, еда и одежда, такие же мысли и проблемы, как у самых обычных детей. Но однажды их жизнь изменилась… "Когда я вернусь" - это истории людей, в детстве прошедших через концлагеря. Йессика Баб Бунде собрала свидетельства очевидцев, а художник Петер Бергтинг нарисовал комиксы по мотивам этой старой истории.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'не-справедливость-1304'), 'Не/справедливость', 'In/Justice', 'Ne/pravda', 'Ника Дубровская', 'Nika Dubrovsky', 'Nika Dubrovski', 'В разные времена в разных культурах представления о том, что такое справедливость, менялись. Когда-то считалось несправедливым убивать людей, но торговля живыми людьми была вполне приемлемой и законной. В большинстве культур считается обязательным накормить и приютить странника, а где-то возможность напиться воды - предмет торговли и привилегия. От эпохи к эпохе, от культуры к культуре мы изменяем наше коллективное мнение о том, что такое хорошо, а что такое плохо. "НЕ/СПРАВЕДЛИВОСТЬ" - собрание историй и мнений из разных эпох.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'хиросима-1305'), 'Хиросима', 'Hiroshima No Pika', 'Hirošima', 'Тоси Маруки', 'Toshi Maruki', 'Toši Maruki', '…6 августа 1945 года, в восемь часов пятнадцать минут ужасная вспышка осветила небо над Хиросимой. Это взорвалась первая в истории человечества атомная бомба. Вместе с мамой, которая несла на спине раненого отца, семилетняя Мии-тян бежала по городу, пытаясь спастись от огня. Падающие друг на друга люди, чёрный маслянистый дождь, радуга на тёмном небе и хрупкая надежда - вот что запомнила девочка. Чтобы позже рассказать об этом тем, кого там не было. Такое сложно представить или описать, но автору этой уникальной книжки-картинки, Тоси Маруки, это удаётся с потрясающей силой. "Если люди не сбросят бомбу, она сама не упадёт", - напоминает нам автор-номинант на Нобелевскую премию мира - и её слова звучат на 14 языках мира…');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-ем-лапшу-а-в-это-время-1306'), 'Я ем лапшу, а в это время', 'While I Eat Noodles', 'Ja jedem rezance, a u to vrijeme', '', 'Yoshifumi Hasegawa', 'Jošifumi Hasegava', 'Как объяснить ребёнку, что его жизнь - это лишь один мазок кисти на картине пуантилистов? Как рассказать, что где-то в мире всё совсем по-другому? На эти вопросы достаточно просто, поэтично и ёмко отвечает книга японского художника Ёсифуми Хасэгава "Я ем лапшу, а в это время…". С Востока дует ветер мудрости, и он нашёптывает историю о мальчике, который однажды за обедом задумался: что же происходит в эту секунду в мире? Кто-то зевает, кто-то играет на скрипке, кто-то готовит обед, кто-то зарабатывает на кусок хлеба… Мир и людские судьбы такие разные, об этом знает восточный ветер, малыш, который ест лапшу, а теперь и вы...');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'сибирские-хайку-1307'), 'Сибирские хайку', 'Siberian Haiku', 'Sibirski haiku', 'Юрга Вилле', 'Jurga Vilė', 'Jurga Vile', '"Сибирские хайку" - графический роман о депортированной литовской семье, в котором можно найти отражение тысяч других семейных историй XX века. "Я - Альгис, но чаще меня называют Альгюкас. Я всегда мечтал путешествовать. Вот только случилось это совсем не так, как я себе представлял. На рассвете 14 июня 1941 года к нам в дом ворвались солдаты и приказали собираться в дорогу. Покидая родную Литву мы не знали, что впереди нас ждут тяжелая работа, голод и злющие кусачие паразиты в холодном бараке - нашем новом доме, в Сибири. Как сложится здесь наша жизнь? Папа учил нас замечать чудеса мира, поддерживать друг друга. И мы стараемся: организуем хор "Яблоки", учимся играть на музыкальных инструментах и даже влюбляемся. И не перестаём надеяться на возвращение домой."');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'свобода-равенство-сестринство-1308'), 'Свобода, равенство, сестринство', 'Women in Battle: 150 Years of Fighting for Freedom, Equality, and Sisterhood', 'Žene u borbi: Sloboda, jednakost, sestrinstvo', 'Марта Бреен, Йенни Юрдал', 'Marta Breen, Jenny Jordahl', 'Marta Breen, Jenny Jordahl', '150 лет назад мужчины и женщины жили очень по-разному. Женщины не могли голосовать на выборах и зарабатывать деньги. Они далеко не всегда могли распоряжаться собственным телом. И лишь когда женщины объединились и стали бороться за свои права, начали происходить изменения. Норвежская авторка Марта Бреен и иллюстраторка Йенни Юрдал придумали комикс, в котором легко и понятно рассказывают об истории женского движения, о драматических моментах и великих победах в борьбе женщин за свободу, равенство, сестринство. В Норвегии книга впервые вышла в марте 2018, и ее первый тираж был продан за месяц. Книга попала в список Лучших детских книг 2018 года по версии The Guardian. Права на издание книги проданы в 20 стран - от Албании до США и Японии.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'полынная-елка-1309'), 'Полынная елка', 'The Wormwood Christmas Tree', 'Pelinova jelka', 'Ольга Колпакова', 'Olga Kolpakova', 'Olga Kolpakova', 'Что делать, если ваша семья - вдали от дома, от всего привычного и родного, и перед Рождеством у вас нет даже ёлки? Можно нарядить ветку полыни: нарезать бахрому из старой изорванной книжки, налепить из теста барашков, курочек, лошадок. Получится хоть и чёрно-бело, но очень красиво! Пятилетняя Марийхе знает: на тарелке под такой ёлкой утром обязательно найдётся подарок, ведь она весь год хорошо, почти хорошо себя вела. Рождество остаётся праздником всегда - даже на незнакомой сибирской земле, куда Марийхе с семьёй отправили с началом войны. Детская память сохраняет лишь обрывочные воспоминания, лишь фрагменты родительских объяснений о том, как и почему так произошло. Тяжёлая поступь истории приглушена, девочка едва слышит её - и запоминает тихие моменты радости, мгновения будничных огорчений, хрупкие образы, на первый взгляд ничего не говорящие об эпохе 1940-х. Марийхе, её сестры Мина и Лиля, их мама, тётя Юзефина с сыном Теодором, друзья и соседи по Ровнополью - русские немцы. И хотя они, как объяснял девочкам папа, "хорошие немцы", а не "фашисты", дальше жить в родных местах им запрещено: вдруг перейдут на сторону противника? Каким бы испытанием для семьи ни был переезд, справиться помогают добрые люди - такие есть в любой местности, в любом народе, в любое время.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'а-дедушка-в-костюме--1310'), 'А дедушка в костюме?', 'Grandpa''s Suit', 'Je li đed u odijelu?', 'Амели фрид', 'Amelie Fried', 'Ameli Frid', 'Бруно очень любит своего дедушку. А теперь его нет... Брат Бруно, Ксавер, утверждает, что он на кладбище, а папа говорит - на небесах. Но что тут правда? Ксавер так много врёт, что Бруно не знает, можно ли ему поверить в этот раз. А родители постоянно повторяют: "Этого ты пока не поймёшь"... Поначалу, что бы Бруно ни делал, он чувствует глухую боль в груди. Как будто у него маленькая дырка в груди под свитером. Но постепенно она затягивается. Каждый вечер перед тем, как лечь спать, Бруно смотрит на дедушкину фотографию и разговаривает с ним. "Я тебя не забуду", - обещает он дедушке. И кажется, что тот улыбается ему издалека. Книга "А дедушка в костюме?" в 1998 году была отмечена Немецкой детской литературной премией и Немецким Фондом Искусств. Она переведена на французский, японский, корейский и китайский языки.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'как-я-появился-на-свет-1311'), 'Как я появился на свет', 'How I Came to Be', 'Kako sam došao na svijet', 'Катерина Януш', 'Katerina Janouch', 'Katerina Janouš', 'Откуда берутся дети? Что происходит в животе у мамы долгие девять месяцев? Как получаются мальчики и девочки? Откуда ребенок знает, когда ему родиться? Эта книжка - путешествие в таинства жизни. Все дети совершают его, но никто из них не помнит о нем. Настала пора прочесть эту книгу и пройти этот путь заново. Катерина Януш и Мерви Линдман в шутливой и одновременно просветительской форме расскажут о великом чуде - рождении ребенка - и ответят на вопросы детей.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'откуда-я-взялся--1312'), 'Откуда я взялся?', 'Where Did I Come From?', 'Odakle sam došao?', 'Вирджини Дюмон', 'Virginie Dumont', 'Virginie Dumont', 'В возрасте 5 лет ребенок впервые задает "трудные " вопросы: "Откуда я взялся ?","Где я был, пока меня не было?". Как ответить? Рассказать про аистов и капусту, отложив серьезный разговор до школы? Или попробовать найти нужные слова, чтобы объяснить чудо зарождения жизни и появления нового человека на свет? Доступно описать сложные физиологические и психологические процессы, происходящие в организме женщины и мужчины, готовящихся стать родителями, поможет эта книга.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'я-и-мой-страх-1313'), 'Я и мой страх', 'Me and My Fear', 'Ja i moj strah', 'Франческа Санна', 'Francesca Sanna', 'Francesca Sanna', 'У нашей героини есть один секрет - маленький друг по имени Страх. Он помогает девочке исследовать мир и предупреждает все опасности. Но вскоре семья девочки переезжает жить в другую страну, и Страх начинает расти. Он становится все больше и сильнее, и постепенно заполоняет все вокруг. Из-за него девочка теперь чувствует себя одинокой, не хочет ходить в новую школу, боится заговорить с одноклассниками. Но однажды она встречает мальчика, у которого тоже есть свой Страх. Девочка понимает, что она такая не одна, что бояться - это нормально, и преодолевает Страх. Эта книга поможет детям не только адаптироваться в любой незнакомой для них среде, но и расскажет, что бояться - это нормально и это свойственно каждому из нас. Главное, уметь контролировать свои страхи.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'привет-месячные-1314'), 'Привет, месячные', 'Welcome to Your Period', 'Dobrodošla, menstruacijo', 'Юми Сайнс', 'Yumi Stynes, Melissa Kang', 'Yumi Stynes, Melissa Kang', 'Во многих семьях откровенно разговаривать о месячных не принято, и месячные считаются чем-то странным, грязным, болезненным. Но так быть не должно! В этой книге собраны советы на все случаи жизни. Из нее ты узнаешь, когда наступают месячные и как они проходят у разных людей, что такое спазмы и как с ними бороться, что делать в случае протечки и многое другое. В книге собраны вопросы и рассказы реальных подростков и взрослых, а комментирует их опытный врач. Прочитав эту книгу, ты тоже станешь настоящим экспертом в этом вопросе и сможешь консультировать своих подруг! Журналистка Юми Стайнс и практикующий врач Мелисса Канг вместе написали этот гид - если тебе надо разобраться с месячными, никакая другая книга не понадобится. Эта книга поддержит, развеселит и даст всю необходимую информацию, которая будет полезна и девочкам, и родителям подростков, и просто всем, кто хочет восполнить пробелы в своих знаниях по этому деликатному вопросу.');
INSERT INTO books_fts (rowid, title_ru, title_en, title_me, author_ru, author_en, author_me, annotation_ru) VALUES ((SELECT rowid FROM books WHERE id = 'прощайте-господин-маффин--1315'), 'Прощайте, господин Маффин!', 'Goodbye, Mr. Muffin', 'Zbogom, gospodine Mafine!', 'Ульф Нильсон', 'Ulf Nilsson', 'Ulf Nilson', 'Старая морская свинка по имени Господин Маффин готовится к последнему путешествию. Он с удовольствием вспоминает вкусные огурцы, приятные поглаживания, красавицу-жену и своих пушистых детей. А еще рядом с домом Господина Маффина стоит почтовый ящичек, где иногда появляются письма от его юной хозяйки. Она пишет о своей любви и грусти и рассуждает о смерти - по-детски просто и мудро. Деликатная и целительная история для размышлений на непростые темы. В 2002 году книга получила премию имени Августа Стриндберга в номинации "Литература для детей и юношества".');